package colorizer

import (
	"fmt"

	"github.com/logrusorgru/aurora/v4"

	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
)

const (
	fgOrange aurora.ColorIndex = 208
)

func GetColor(colorizer *aurora.Aurora, templateSeverity fmt.Stringer) string {
	var method func(arg interface{}) aurora.Value
	switch templateSeverity {
	case severity.Info:
		method = colorizer.Blue
	case severity.Low:
		method = colorizer.Green
	case severity.Medium:
		method = colorizer.Yellow
	case severity.High:
		method = func(stringValue interface{}) aurora.Value { return colorizer.Index(fgOrange, stringValue) }
	case severity.Critical:
		method = colorizer.Red
	default:
		method = colorizer.White
	}

	return method(templateSeverity.String()).String()
}

func New(colorizer *aurora.Aurora) func(severity.Severity) string {
	return func(severity severity.Severity) string {
		return GetColor(colorizer, severity)
	}
}

package configuration

import (
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"runtime"
	"slices"

	"github.com/adrg/xdg"
	"github.com/projectdiscovery/goflags"
	catalogconfig "github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
)

// Selection contains the config and profile selected for one invocation.
type Selection struct {
	Config  string
	Profile string
}

// Load applies automatic config files, one selected config file, and one
// selected profile in priority order. Explicit CLI flags retain precedence.
func Load(
	cfg *catalogconfig.Config,
	flagSet *goflags.FlagSet,
	selected *Selection,
	resolveProfile func(string) (string, error),
	args ...string,
) ([]error, error) {
	userConfigFile := cfg.GetFlagsConfigFilePath()
	defaultUserConfigFile := filepath.Join(xdg.ConfigHome, catalogconfig.BinaryName, catalogconfig.CLIConfigFileName)
	automaticFiles := automaticConfigFiles(xdg.ConfigDirs, runtime.GOOS, userConfigFile)

	return loadConfigFiles(userConfigFile, defaultUserConfigFile, automaticFiles, flagSet, selected, resolveProfile, args...)
}

func loadConfigFiles(
	userConfigFile string,
	defaultUserConfigFile string,
	automaticFiles []string,
	flagSet *goflags.FlagSet,
	selected *Selection,
	resolveProfile func(string) (string, error),
	args ...string,
) ([]error, error) {

	var warnings []error
	if err := prepareUserConfigFile(userConfigFile, defaultUserConfigFile); err != nil {
		warnings = append(warnings, err)
	}

	flagSet.SetConfigFilePaths(automaticFiles...)
	if err := flagSet.Parse(args...); err != nil {
		warnings = append(warnings, fmt.Errorf("automatic configuration was ignored: %w", err))
	}

	if err := mergeSelectedFiles(flagSet, selected, resolveProfile); err != nil {
		return warnings, err
	}

	return warnings, nil
}

func mergeSelectedFiles(
	flagSet *goflags.FlagSet,
	selected *Selection,
	resolveProfile func(string) (string, error),
) error {
	configFile := selected.Config
	if configFile != "" {
		if err := flagSet.MergeConfigFile(configFile); err != nil {
			return fmt.Errorf("read config file %q: %w", configFile, err)
		}

		// A selected config may choose a profile, but it cannot redirect its
		// completed config stage.
		selected.Config = configFile
	}

	if selected.Profile == "" {
		return nil
	}

	profileFile, err := resolveProfile(selected.Profile)
	if err != nil {
		return err
	}
	if err := flagSet.MergeConfigFile(profileFile); err != nil {
		return fmt.Errorf("read template profile %q: %w", profileFile, err)
	}

	// A profile cannot redirect either completed file-selection stage.
	selected.Config = configFile
	selected.Profile = profileFile

	return nil
}

func automaticConfigFiles(configDirs []string, goos, userConfigFile string) []string {
	highestFirst := make([]string, 0, len(configDirs)+2)
	highestFirst = append(highestFirst, userConfigFile)

	if unixSystemFile := unixSystemConfigFilePath(goos); unixSystemFile != "" {
		highestFirst = append(highestFirst, unixSystemFile)
	}

	for _, configDir := range configDirs {
		if filepath.IsAbs(configDir) {
			highestFirst = append(highestFirst, filepath.Join(configDir, catalogconfig.BinaryName, catalogconfig.CLIConfigFileName))
		}
	}

	files := make([]string, 0, len(highestFirst))
	seen := make(map[string]struct{}, len(highestFirst))

	for _, file := range highestFirst {
		if file == "" {
			continue
		}

		cleanFile := filepath.Clean(file)
		if _, exists := seen[cleanFile]; exists {
			continue
		}

		seen[cleanFile] = struct{}{}
		files = append(files, file)
	}

	slices.Reverse(files)

	return files
}

func unixSystemConfigFilePath(goos string) string {
	switch goos {
	case "aix", "darwin", "dragonfly", "freebsd", "linux", "netbsd", "openbsd", "solaris":
		return path.Join("/etc", catalogconfig.BinaryName, catalogconfig.CLIConfigFileName)
	default:
		return ""
	}
}

func prepareUserConfigFile(configFile, defaultConfigFile string) error {
	if filepath.Clean(configFile) == filepath.Clean(defaultConfigFile) {
		return nil
	}

	if _, err := os.Stat(configFile); err == nil {
		return nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("inspect custom config file %q: %w", configFile, err)
	}

	data, err := os.ReadFile(defaultConfigFile)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read default config file %q: %w", defaultConfigFile, err)
	}

	if err := os.MkdirAll(filepath.Dir(configFile), 0o700); err != nil {
		return fmt.Errorf("create custom config directory %q: %w", filepath.Dir(configFile), err)
	}

	file, err := os.OpenFile(configFile, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if errors.Is(err, os.ErrExist) {
		return nil
	}

	if err != nil {
		return fmt.Errorf("create custom config file %q: %w", configFile, err)
	}

	written := false

	defer func() {
		_ = file.Close()
		if !written {
			_ = os.Remove(configFile)
		}
	}()

	if _, err := file.Write(data); err != nil {
		return fmt.Errorf("copy default config from %q to %q: %w", defaultConfigFile, configFile, err)
	}

	if err := file.Close(); err != nil {
		return fmt.Errorf("close custom config file %q: %w", configFile, err)
	}

	written = true

	return nil
}

package configuration

import (
	"os"
	"path/filepath"
	"testing"

	catalogconfig "github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
)

func TestUnixSystemConfigFilePath(t *testing.T) {
	for _, goos := range []string{"aix", "darwin", "dragonfly", "freebsd", "linux", "netbsd", "openbsd", "solaris"} {
		if got, want := unixSystemConfigFilePath(goos), "/etc/nuclei/config.yaml"; got != want {
			t.Fatalf("unix system config for %s = %q, want %q", goos, got, want)
		}
	}
	for _, goos := range []string{"windows", "plan9", "js"} {
		if got := unixSystemConfigFilePath(goos); got != "" {
			t.Fatalf("system config for %s = %q, want empty", goos, got)
		}
	}
}

func TestPrepareUserConfigFile(t *testing.T) {
	dir := t.TempDir()
	defaultConfigFile := filepath.Join(dir, "default", catalogconfig.CLIConfigFileName)
	customConfigFile := filepath.Join(dir, "custom", catalogconfig.CLIConfigFileName)
	if err := os.MkdirAll(filepath.Dir(defaultConfigFile), 0o700); err != nil {
		t.Fatalf("create default config directory: %v", err)
	}
	if err := os.WriteFile(defaultConfigFile, []byte("value: inherited\n"), 0o600); err != nil {
		t.Fatalf("write default config: %v", err)
	}

	if err := prepareUserConfigFile(customConfigFile, defaultConfigFile); err != nil {
		t.Fatalf("prepare user config file: %v", err)
	}
	data, err := os.ReadFile(customConfigFile)
	if err != nil {
		t.Fatalf("read inherited config: %v", err)
	}
	if got, want := string(data), "value: inherited\n"; got != want {
		t.Fatalf("inherited config = %q, want %q", got, want)
	}

	if err := os.WriteFile(defaultConfigFile, []byte("value: changed\n"), 0o600); err != nil {
		t.Fatalf("update default config: %v", err)
	}
	if err := prepareUserConfigFile(customConfigFile, defaultConfigFile); err != nil {
		t.Fatalf("prepare existing user config: %v", err)
	}
	data, err = os.ReadFile(customConfigFile)
	if err != nil {
		t.Fatalf("read existing user config: %v", err)
	}
	if got, want := string(data), "value: inherited\n"; got != want {
		t.Fatalf("existing user config = %q, want %q", got, want)
	}

	missingConfigFile := filepath.Join(dir, "missing-custom", catalogconfig.CLIConfigFileName)
	if err := prepareUserConfigFile(missingConfigFile, filepath.Join(dir, "missing-default.yaml")); err != nil {
		t.Fatalf("prepare config without default source: %v", err)
	}
	if _, err := os.Stat(missingConfigFile); !os.IsNotExist(err) {
		t.Fatalf("missing default source created user config: %v", err)
	}
}

package configuration

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	catalogconfig "github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates/extensions"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/yaml"
	fileutil "github.com/projectdiscovery/utils/file"
)

// TemplatesDirectory returns the final template directory used while loading
// configuration and resolving profiles.
func TemplatesDirectory(options *types.Options, config *catalogconfig.Config) string {
	if templatesDir, overridden := TemplatesDirectoryOverride(options); overridden {
		return templatesDir
	}

	return config.GetTemplateDir()
}

// TemplatesDirectoryOverride returns an explicit flag/config or environment
// template directory.
func TemplatesDirectoryOverride(options *types.Options) (string, bool) {
	templatesDir := options.NewTemplatesDirectory
	if templatesDir == "" {
		templatesDir = os.Getenv(catalogconfig.NucleiTemplatesDirEnv)
	}

	if templatesDir == "" {
		return "", false
	}

	if absPath, err := filepath.Abs(templatesDir); err == nil {
		return absPath, true
	}

	return templatesDir, true
}

// ResolveProfilePath resolves a profile path or profile ID against the active
// template root.
func ResolveProfilePath(profilePath, templatesDir string) (string, error) {
	defaultProfilesPath := filepath.Join(templatesDir, "profiles")
	if filepath.Ext(profilePath) == "" {
		path, err := findProfilePathByID(profilePath, defaultProfilesPath)
		if err != nil {
			return "", err
		}

		if path == "" {
			return "", fmt.Errorf("%q is not a profile ID or profile path", profilePath)
		}

		profilePath = path
	}

	if !filepath.IsAbs(profilePath) {
		if filepath.Dir(profilePath) == "profiles" {
			defaultProfilesPath = templatesDir
		}

		currentDir, err := os.Getwd()
		if err == nil && fileutil.FileExists(filepath.Join(currentDir, profilePath)) {
			profilePath = filepath.Join(currentDir, profilePath)
		} else {
			profilePath = filepath.Join(defaultProfilesPath, profilePath)
		}
	}

	if !fileutil.FileExists(profilePath) {
		return "", fmt.Errorf("given template profile file %q does not exist", profilePath)
	}

	return profilePath, nil
}

func findProfilePathByID(profileID, profilesDir string) (string, error) {
	var profilePath string
	err := filepath.WalkDir(profilesDir, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if entry.IsDir() {
			return nil
		}

		ext := filepath.Ext(path)
		if ext != extensions.YAML && ext != extensions.YML {
			return nil
		}

		if strings.TrimSuffix(filepath.Base(path), ext) == profileID {
			profilePath = path
			return fs.SkipAll
		}

		return nil
	})

	if err != nil {
		return "", fmt.Errorf("search profile ID %q in %q: %w", profileID, profilesDir, err)
	}

	return profilePath, nil
}

// ApplyProfile processes profile-only inline targets and secrets after its
// flag values have been merged. It returns the private directory that owns a
// generated inline-secrets file.
func ApplyProfile(profilePath string, options *types.Options) (string, error) {
	if profilePath == "" {
		return "", nil
	}

	options.Targets = appendInlineTargets(options.Targets, options.InlineTargetsList)
	if strings.Contains(options.TargetsFilePath, "\n") {
		options.Targets = appendInlineTargets(options.Targets, options.TargetsFilePath)
		options.TargetsFilePath = ""
	}

	return processInlineSecretsFromProfile(profilePath, options)
}

func appendInlineTargets(targets []string, input string) []string {
	for target := range strings.SplitSeq(strings.TrimSpace(input), "\n") {
		target = strings.TrimSpace(target)
		if target != "" && !strings.HasPrefix(target, "#") {
			targets = append(targets, target)
		}
	}

	return targets
}

type profileSecrets struct {
	Secrets any `yaml:"secrets"`
}

func processInlineSecretsFromProfile(profilePath string, options *types.Options) (string, error) {
	data, err := os.ReadFile(profilePath)
	if err != nil {
		return "", fmt.Errorf("read profile file %q: %w", profilePath, err)
	}

	var profile profileSecrets
	if err := yaml.Unmarshal(data, &profile); err != nil {
		return "", fmt.Errorf("parse profile YAML %q: %w", profilePath, err)
	}

	if profile.Secrets == nil {
		return "", nil
	}

	secretsData, err := yaml.Marshal(profile.Secrets)
	if err != nil {
		return "", fmt.Errorf("marshal inline profile secrets: %w", err)
	}

	tempDir, err := os.MkdirTemp("", "nuclei-secrets-*")
	if err != nil {
		return "", fmt.Errorf("create inline secrets directory: %w", err)
	}

	removeDir := true
	defer func() {
		if removeDir {
			_ = os.RemoveAll(tempDir)
		}
	}()

	tempPath := filepath.Join(tempDir, "inline-secrets.yaml")
	if err := os.WriteFile(tempPath, secretsData, 0o600); err != nil {
		return "", fmt.Errorf("write inline secrets file %q: %w", tempPath, err)
	}

	removeDir = false
	options.SecretsFile = append(options.SecretsFile, tempPath)

	return tempDir, nil
}

package configuration

import (
