	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/stretchr/testify/require"
)

// simulateOnResultCallback reproduces the OnResult callback from lazy.go.
// It silently skips events without operator results and only errors post-execution
// if no data was extracted at all.
func simulateOnResultCallback(templatePath string, events []*output.InternalWrappedEvent) (map[string]interface{}, error) {
	data := map[string]interface{}{}

	for _, e := range events {
		if e == nil {
			continue
		}
		if !e.HasOperatorResult() {
			continue
		}
		for k, v := range e.OperatorsResult.DynamicValues {
			for _, value := range v {
				oldVal, ok := data[k]
				if !ok || len(value) > len(oldVal.(string)) {
					data[k] = value
				}
			}
		}
		for k, v := range e.OperatorsResult.Extracts {
			if len(v) > 0 {
				data[k] = v[0]
			}
		}
	}

	var finalErr error
	if len(data) == 0 {
		finalErr = fmt.Errorf("no extracted values found for template: %s", templatePath)
	}
	return data, finalErr
}

// flowEvents returns a pair of events simulating a flow: http(1) && http(2)
// where http(1) has no matchers and http(2) has extractors.
func flowEvents() []*output.InternalWrappedEvent {
	return []*output.InternalWrappedEvent{
		{InternalEvent: map[string]interface{}{"status_code": 200}},
		{
			OperatorsResult: &operators.Result{
				Matched: true,
				Extracts: map[string][]string{
					"userid":     {"USER-042"},
					"customerid": {"CUST-001"},
				},
			},
			InternalEvent: map[string]interface{}{"status_code": 200},
		},
	}
}

// TestCallbackWorksWithFlowTemplate verifies that the OnResult callback
// correctly handles flow templates (e.g., flow: http(1) && http(2)) where
// the first request has no matchers/extractors and the second has extractors.
// Regression test for #7295.
func TestCallbackWorksWithFlowTemplate(t *testing.T) {
	data, err := simulateOnResultCallback("login.yaml", flowEvents())

	require.Equal(t, "USER-042", data["userid"])
	require.Equal(t, "CUST-001", data["customerid"])
	require.NoError(t, err, "should not error when data is extracted from a later event")
}

// TestCallbackSingleRequest verifies single-request templates still work.
func TestCallbackSingleRequest(t *testing.T) {
	events := []*output.InternalWrappedEvent{
		{
			OperatorsResult: &operators.Result{
				Matched: true,
				Extracts: map[string][]string{
					"token": {"abc123"},
				},
			},
			InternalEvent: map[string]interface{}{},
		},
	}

	data, err := simulateOnResultCallback("auth.yaml", events)

	require.NoError(t, err)
	require.Equal(t, "abc123", data["token"])
}

// TestCallbackNoExtraction verifies error is returned when nothing is extracted.
func TestCallbackNoExtraction(t *testing.T) {
	events := []*output.InternalWrappedEvent{
		{InternalEvent: map[string]interface{}{"status_code": 404}},
	}

	data, err := simulateOnResultCallback("auth.yaml", events)

	require.Error(t, err)
	require.Contains(t, err.Error(), "no extracted values")
	require.Empty(t, data)
}

// TestCallbackNilEvent verifies nil events are safely ignored.
func TestCallbackNilEvent(t *testing.T) {
	events := []*output.InternalWrappedEvent{nil}

	data, err := simulateOnResultCallback("auth.yaml", events)

	require.Error(t, err)
	require.Contains(t, err.Error(), "no extracted values")
	require.Empty(t, data)
}

// TestCallbackDynamicValues verifies dynamic values (internal extractors) are captured.
func TestCallbackDynamicValues(t *testing.T) {
	events := []*output.InternalWrappedEvent{
		{
			OperatorsResult: &operators.Result{
				Matched: true,
				DynamicValues: map[string][]string{
					"session": {"sess-xyz-123", "sess-a"},
				},
			},
			InternalEvent: map[string]interface{}{},
		},
	}

	data, err := simulateOnResultCallback("auth.yaml", events)

	require.NoError(t, err)
	require.Equal(t, "sess-xyz-123", data["session"], "should pick the longest value")
}

func TestSkipSecretFileOnAuthTemplate(t *testing.T) {
	t.Run("nil template is a no-op", func(t *testing.T) {
		restore := skipSecretFileOnAuthTemplate(nil)
		require.NotPanics(t, restore)
	})

	t.Run("sets skip during fetch and restores previous values", func(t *testing.T) {
		alreadySkipped := &httpprotocol.Request{SkipSecretFile: true}
		needsSkip := &httpprotocol.Request{}
		tmpl := &templates.Template{
			RequestsHTTP: []*httpprotocol.Request{alreadySkipped, needsSkip},
		}
		tmpl.RequestsQueue = []protocols.Request{alreadySkipped, needsSkip}

		restore := skipSecretFileOnAuthTemplate(tmpl)
		require.True(t, alreadySkipped.SkipSecretFile)
		require.True(t, needsSkip.SkipSecretFile)

		restore()
		require.True(t, alreadySkipped.SkipSecretFile, "templates that already skipped secret-file must stay skipped")
		require.False(t, needsSkip.SkipSecretFile, "scan-time ApplyAuth must remain enabled after login fetch")
	})
}

package runner

import (
	"context"
	"errors"
	"sync"
	"time"

	"github.com/projectdiscovery/gologger"

	llmclient "github.com/projectdiscovery/nuclei/v3/pkg/operators/common/llm"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	utilsllm "github.com/projectdiscovery/utils/llm"
)

// llmMatcherClient adapts the shared provider layer to the minimal interface
// the matchers package needs, keeping matchers free of any provider SDK import.
type llmMatcherClient struct {
	client *utilsllm.Client
	model  string
}

// Model names the model behind a verdict so it can be recorded in the finding.
func (a *llmMatcherClient) Model() string {
	return a.model
}

func (a *llmMatcherClient) Complete(ctx context.Context, prompt string, asJSON bool) (string, error) {
	return a.client.Complete(ctx, utilsllm.Request{
		Prompt: prompt,
		Format: utilsllm.Format{JSON: asJSON},
	})
}

// llmJudgeClient is an llmMatcherClient whose provider classifies natively, so
// llm matchers ask it through Judge instead of Complete.
type llmJudgeClient struct {
	*llmMatcherClient
	warnComplete sync.Once
}

func (a *llmJudgeClient) Judge(ctx context.Context, question string, labels, inputs []string) (llmclient.Verdict, error) {
	verdict, err := a.client.Judge(ctx, utilsllm.JudgeRequest{Question: question, Labels: labels, Inputs: inputs})
	if err != nil {
		return llmclient.Verdict{}, err
	}
	return llmclient.Verdict{Label: verdict.Label, Confidence: verdict.Confidence, Model: verdict.Model}, nil
}

// Complete is only reached by llm extractors, which need free text a
// classifier cannot produce. Returning here spends no call budget and
// makes no provider request. Extractors turn the error into an empty
// result, and the warning says why.
func (a *llmJudgeClient) Complete(context.Context, string, bool) (string, error) {
	a.warnComplete.Do(func() {
		gologger.Warning().Msgf("llm provider %q cannot run llm extractors, they return nothing", utilsllm.ProviderJev)
	})
	return "", errors.New("llm provider cannot run extractors")
}

// configureLLM builds the scan's llm client from options. It returns nil unless
// -llm is set, so nothing reaches a model until the user opts in. The API key is
// read from the environment by the provider layer, never from options.
//
// The client is returned rather than installed globally so two scans in one
// process cannot overwrite each other's provider, cache, budget, or timeout.
func configureLLM(options *types.Options) (llmclient.Client, error) {
	if !options.EnableLLM {
		return nil, nil
	}

	client, err := utilsllm.New(utilsllm.Config{
		Provider:       options.LLMProvider,
		BaseURL:        options.LLMBaseURL,
		Model:          options.LLMModel,
		Timeout:        time.Duration(options.LLMTimeout) * time.Second,
		Cache:          options.LLMCache,
		MaxCalls:       options.LLMMaxCalls,
		MaxConcurrency: options.LLMConcurrency,
	})
	if err != nil {
		return nil, err
	}

	matcherClient := &llmMatcherClient{client: client, model: options.LLMModel}
	if client.CanJudge() {
		return &llmJudgeClient{llmMatcherClient: matcherClient}, nil
	}
	return matcherClient, nil
}

