type nucleiExecutor struct {
	engine       *core.Engine
	store        *loader.Store
	options      *NucleiExecutorOptions
	executorOpts *protocols.ExecutorOptions
}

type NucleiExecutorOptions struct {
	Options            *types.Options
	Output             output.Writer
	Progress           progress.Progress
	Catalog            catalog.Catalog
	IssuesClient       reporting.Client
	RateLimiter        *ratelimit.Limiter
	Interactsh         interactsh.IClient
	ProjectFile        *projectfile.ProjectFile
	Browser            *browserEngine.Browser
	FuzzStatsDB        *stats.Tracker
	Colorizer          *aurora.Aurora
	Parser             parser.Parser
	TemporaryDirectory string
	Logger             *gologger.Logger
}

func newNucleiExecutor(opts *NucleiExecutorOptions) (*nucleiExecutor, error) {
	fuzzFreqCache := frequency.New(frequency.DefaultMaxTrackCount, opts.Options.FuzzParamFrequency)
	resumeCfg := types.NewResumeCfg()

	// Create the executor options which will be used throughout the execution
	// stage by the nuclei engine modules.
	executorOpts := &protocols.ExecutorOptions{
		Output:              opts.Output,
		Options:             opts.Options,
		Progress:            opts.Progress,
		Catalog:             opts.Catalog,
		IssuesClient:        opts.IssuesClient,
		RateLimiter:         opts.RateLimiter,
		Interactsh:          opts.Interactsh,
		ProjectFile:         opts.ProjectFile,
		Browser:             opts.Browser,
		Colorizer:           opts.Colorizer,
		ResumeCfg:           resumeCfg,
		ExcludeMatchers:     excludematchers.New(opts.Options.ExcludeMatchers),
		InputHelper:         input.NewHelper(),
		TemporaryDirectory:  opts.TemporaryDirectory,
		Parser:              opts.Parser,
		FuzzParamsFrequency: fuzzFreqCache,
		GlobalMatchers:      globalmatchers.New(),
		FuzzStatsDB:         opts.FuzzStatsDB,
		Logger:              opts.Logger,
	}

	if opts.Options.ShouldUseHostError() {
		maxHostError := opts.Options.MaxHostError
		if maxHostError == 30 {
			maxHostError = 100 // auto adjust for fuzzings
		}
		if opts.Options.TemplateThreads > maxHostError {
			opts.Logger.Info().Msgf("Adjusting max-host-error to the concurrency value: %d", opts.Options.TemplateThreads)

			maxHostError = opts.Options.TemplateThreads
		}

		cache := hosterrorscache.New(maxHostError, hosterrorscache.DefaultMaxHostsCount, opts.Options.TrackError)
		cache.SetVerbose(opts.Options.Verbose)

		executorOpts.HostErrorsCache = cache
	}

	if opts.Options.HostBackoff {
		executorOpts.HostBackoff = hostbackoff.New(hostbackoff.Config{Max: opts.Options.HostBackoffMax})
	}
	if opts.Options.AutoCalibrate {
		executorOpts.CatchAll = catchall.New(0)
	}

	executorEngine := core.New(opts.Options)
	executorEngine.SetExecuterOptions(executorOpts)

	workflowLoader, err := parsers.NewLoader(executorOpts)
	if err != nil {
		return nil, errors.Wrap(err, "Could not create loader options.")
	}
	executorOpts.WorkflowLoader = workflowLoader

	// If using input-file flags, only load http fuzzing based templates.
	loaderConfig := loader.NewConfig(opts.Options, opts.Catalog, executorOpts)
	if (!strings.EqualFold(opts.Options.InputFileMode, "list") || opts.Options.DAST || opts.Options.DASTServer || opts.Options.DASTProxy) && !opts.Options.OfflineHTTP {
		// if input type is not list (implicitly enable fuzzing), unless passive/offlinehttp
		opts.Options.DAST = true
	}
	store, err := loader.New(loaderConfig)
	if err != nil {
		return nil, errors.Wrap(err, "Could not create loader options.")
	}
	if err := store.Load(); err != nil {
		return nil, errors.Wrap(err, "Could not load templates.")
	}

	return &nucleiExecutor{
		engine:       executorEngine,
		store:        store,
		options:      opts,
		executorOpts: executorOpts,
	}, nil
}

// proxifyRequest is a request for proxify
type proxifyRequest struct {
	URL     string `json:"url"`
	Request struct {
		Header map[string]string `json:"header"`
		Body   string            `json:"body"`
		Raw    string            `json:"raw"`
	} `json:"request"`
}

func (n *nucleiExecutor) ExecuteScan(target PostRequestsHandlerRequest) error {
	finalTemplates := []*templates.Template{}
	finalTemplates = append(finalTemplates, n.store.Templates()...)
	finalTemplates = append(finalTemplates, n.store.Workflows()...)

	if len(finalTemplates) == 0 {
		return errors.New("no templates provided for scan")
	}

	payload := proxifyRequest{
		URL: target.URL,
		Request: struct {
			Header map[string]string `json:"header"`
			Body   string            `json:"body"`
			Raw    string            `json:"raw"`
		}{
			Raw: target.RawHTTP,
		},
	}

	marshalledYaml, err := yaml.Marshal(payload)
	if err != nil {
		return fmt.Errorf("error marshalling yaml: %s", err)
	}

	inputProvider, err := http.NewHttpInputProvider(&http.HttpMultiFormatOptions{
		InputContents: string(marshalledYaml),
		InputMode:     "yaml",
		Options: formats.InputFormatOptions{
			Variables: make(map[string]interface{}),
		},
	})
	if err != nil {
		return errors.Wrap(err, "could not create input provider")
	}

	// We don't care about the result as its a boolean
	// stating whether we got matches or not
	_ = n.engine.ExecuteScanWithOpts(context.Background(), finalTemplates, inputProvider, true)
	return nil
}

func (n *nucleiExecutor) Close() {
	if n == nil || n.executorOpts == nil {
		return
	}
	if n.executorOpts.FuzzStatsDB != nil {
		n.executorOpts.FuzzStatsDB.Close()
	}
	if n.options != nil && n.options.Interactsh != nil {
		_ = n.options.Interactsh.Close()
	}
	if n.executorOpts.InputHelper != nil {
		_ = n.executorOpts.InputHelper.Close()
	}

}

package proxy

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"runtime"
	"time"

	"github.com/pkg/errors"
	fileutil "github.com/projectdiscovery/utils/file"
)

const (
	caCertFileName = "dast-proxy-ca.pem"
	caKeyFileName  = "dast-proxy-ca.key"

	caValidity = 2 * 365 * 24 * time.Hour

	// The key can mint a certificate that the user's browser trusts for any
	// host, so it must never be readable by other accounts on the machine.
	caKeyFileMode  os.FileMode = 0o600
	caCertFileMode os.FileMode = 0o644
)

// CA is the certificate authority used to sign intercepted TLS connections.
type CA struct {
	Certificate *tls.Certificate
	CertPath    string
	CertPEM     []byte
}

// LoadOrCreateCA loads the interception CA from dir, generating and persisting
// a new one on first use.
//
// goproxy ships a built-in CA whose private key is published with the library;
// it is deliberately never used here. A per-installation key is the only thing
// stopping a third party from minting certificates the user already trusts.
func LoadOrCreateCA(dir string) (*CA, error) {
	certPath := filepath.Join(dir, caCertFileName)
	keyPath := filepath.Join(dir, caKeyFileName)

	certExists, keyExists := fileutil.FileExists(certPath), fileutil.FileExists(keyPath)
	if certExists && keyExists {
		return loadCA(certPath, keyPath)
	}
	// Half a keypair is unusable, and regenerating over it would invalidate a
	// certificate the user may already have installed and trusted. Say which
	// file is orphaned instead of guessing.
	if certExists != keyExists {
		orphan := certPath
		if keyExists {
			orphan = keyPath
		}
		return nil, errors.Errorf("dast proxy CA is incomplete, remove %s to generate a new keypair", orphan)
	}
	return createCA(dir, certPath, keyPath)
}

func loadCA(certPath, keyPath string) (*CA, error) {
	if err := verifyKeyPermissions(keyPath); err != nil {
		return nil, err
	}

	certPEM, err := os.ReadFile(certPath)
	if err != nil {
		return nil, errors.Wrap(err, "could not read dast proxy CA certificate")
	}
	keyPEM, err := os.ReadFile(keyPath)
	if err != nil {
		return nil, errors.Wrap(err, "could not read dast proxy CA key")
	}

	certificate, err := tls.X509KeyPair(certPEM, keyPEM)
	if err != nil {
		return nil, errors.Wrap(err, "could not parse dast proxy CA keypair")
	}
	leaf, err := x509.ParseCertificate(certificate.Certificate[0])
	if err != nil {
		return nil, errors.Wrap(err, "could not parse dast proxy CA certificate")
	}
	if !leaf.IsCA {
		return nil, errors.Errorf("%s is not a certificate authority", certPath)
	}
	// Regenerating silently would swap the CA out from under a certificate the
	// user has already installed and trusted, so this is left to the user.
	if time.Now().After(leaf.NotAfter) {
		return nil, errors.Errorf("dast proxy CA expired on %s, remove %s and %s to generate a new one",
			leaf.NotAfter.Format(time.RFC3339), certPath, keyPath)
	}
	certificate.Leaf = leaf

	return &CA{Certificate: &certificate, CertPath: certPath, CertPEM: certPEM}, nil
}

func createCA(dir, certPath, keyPath string) (*CA, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, errors.Wrap(err, "could not create dast proxy CA directory")
	}

	privateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, errors.Wrap(err, "could not generate dast proxy CA key")
	}
	serialNumber, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, errors.Wrap(err, "could not generate dast proxy CA serial number")
	}

	now := time.Now()
	template := &x509.Certificate{
		SerialNumber: serialNumber,
		Subject: pkix.Name{
			CommonName:   "Nuclei DAST Proxy CA",
			Organization: []string{"ProjectDiscovery"},
		},
		NotBefore:             now.Add(-1 * time.Hour), // tolerate clock skew on the client
		NotAfter:              now.Add(caValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign | x509.KeyUsageDigitalSignature,
		BasicConstraintsValid: true,
		IsCA:                  true,
		// Sign leaf certificates only: a CA reachable through this one must not
		// be able to issue further authorities.
		MaxPathLen:     0,
		MaxPathLenZero: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &privateKey.PublicKey, privateKey)
	if err != nil {
		return nil, errors.Wrap(err, "could not create dast proxy CA certificate")
	}

	keyDER, err := x509.MarshalPKCS8PrivateKey(privateKey)
	if err != nil {
		return nil, errors.Wrap(err, "could not marshal dast proxy CA key")
	}
	certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER})

	// O_EXCL so a pre-existing path, including a symlink planted by another
	// user, can never be written through.
	if err := writeNewFile(keyPath, keyPEM, caKeyFileMode); err != nil {
		return nil, errors.Wrap(err, "could not write dast proxy CA key")
	}
	if err := writeNewFile(certPath, certPEM, caCertFileMode); err != nil {
		// Leaving the key behind would wedge every later start on the
		// incomplete-keypair check above.
		_ = os.Remove(keyPath)
		return nil, errors.Wrap(err, "could not write dast proxy CA certificate")
	}

	leaf, err := x509.ParseCertificate(der)
	if err != nil {
		return nil, errors.Wrap(err, "could not parse generated dast proxy CA certificate")
	}
	return &CA{
		Certificate: &tls.Certificate{Certificate: [][]byte{der}, PrivateKey: privateKey, Leaf: leaf},
		CertPath:    certPath,
		CertPEM:     certPEM,
	}, nil
}

func writeNewFile(path string, contents []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode)
	if err != nil {
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

func verifyKeyPermissions(keyPath string) error {
	if runtime.GOOS == "windows" {
		return nil
	}
	info, err := os.Stat(keyPath)
	if err != nil {
		return errors.Wrap(err, "could not stat dast proxy CA key")
	}
	if mode := info.Mode().Perm(); mode&0o077 != 0 {
		return errors.Errorf("dast proxy CA key %s is readable by other users (%#o), run: chmod 600 %s",
			keyPath, mode, keyPath)
	}
	return nil
}

package proxy

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestLoadOrCreateCAGeneratesUsableAuthority(t *testing.T) {
	dir := t.TempDir()

	ca, err := LoadOrCreateCA(dir)
	require.NoError(t, err)
	require.NotNil(t, ca.Certificate.Leaf)
	require.True(t, ca.Certificate.Leaf.IsCA)
	require.True(t, ca.Certificate.Leaf.MaxPathLenZero, "CA must not be able to issue sub authorities")
	require.Contains(t, string(ca.CertPEM), "BEGIN CERTIFICATE")
	require.NotContains(t, string(ca.CertPEM), "PRIVATE KEY")
	require.Equal(t, filepath.Join(dir, caCertFileName), ca.CertPath)
}

func TestLoadOrCreateCAKeyIsOwnerReadableOnly(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("unix file modes only")
	}
	dir := t.TempDir()

	_, err := LoadOrCreateCA(dir)
	require.NoError(t, err)

	info, err := os.Stat(filepath.Join(dir, caKeyFileName))
	require.NoError(t, err)
	require.Equal(t, caKeyFileMode, info.Mode().Perm())
}

func TestLoadOrCreateCAReusesExistingAuthority(t *testing.T) {
	dir := t.TempDir()

	first, err := LoadOrCreateCA(dir)
	require.NoError(t, err)
	second, err := LoadOrCreateCA(dir)
	require.NoError(t, err)

	require.Equal(t, first.Certificate.Leaf.SerialNumber, second.Certificate.Leaf.SerialNumber)
}

func TestLoadOrCreateCARejectsGroupReadableKey(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("unix file modes only")
	}
	dir := t.TempDir()

	_, err := LoadOrCreateCA(dir)
	require.NoError(t, err)
	require.NoError(t, os.Chmod(filepath.Join(dir, caKeyFileName), 0o644))

	_, err = LoadOrCreateCA(dir)
	require.ErrorContains(t, err, "readable by other users")
}

func TestLoadOrCreateCARejectsIncompleteKeypair(t *testing.T) {
	for _, orphan := range []string{caCertFileName, caKeyFileName} {
		dir := t.TempDir()
		require.NoError(t, os.WriteFile(filepath.Join(dir, orphan), []byte("x"), 0o600))

		_, err := LoadOrCreateCA(dir)
		require.ErrorContains(t, err, "incomplete", orphan)
		require.ErrorContains(t, err, orphan)
	}
}

// A failed certificate write must not leave the key behind, or the
// incomplete-keypair check would wedge every later start.
func TestLoadOrCreateCACleansUpKeyWhenCertificateWriteFails(t *testing.T) {
	dir := t.TempDir()
	// A directory at the certificate path makes the write fail.
	require.NoError(t, os.Mkdir(filepath.Join(dir, caCertFileName), 0o755))

	_, err := LoadOrCreateCA(dir)
	require.Error(t, err)
	require.NoFileExists(t, filepath.Join(dir, caKeyFileName), "orphaned key must be removed")

	require.NoError(t, os.Remove(filepath.Join(dir, caCertFileName)))
	ca, err := LoadOrCreateCA(dir)
	require.NoError(t, err, "startup must recover once the blocker is gone")
	require.True(t, ca.Certificate.Leaf.IsCA)
}

// Package proxy implements an intercepting HTTP proxy that feeds live traffic
// into the nuclei DAST scanner. Requests are forwarded untouched; a copy of
// each intercepted request is handed to the scanner out of band.
package proxy

import (
	"bytes"
	"crypto/subtle"
	"crypto/tls"
	"encoding/base64"
	"io"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/elazarl/goproxy"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
)

const (
	// Requests with a larger body are not mirrored at all: see captureRequest.
	maxCapturedBodySize = 4 << 20

	readHeaderTimeout = 30 * time.Second
)

// hopByHopHeaders are stripped from mirrored requests: they belong to the
// client-to-proxy leg and must not be replayed at a target.
var hopByHopHeaders = []string{
	"Connection",
	"Keep-Alive",
	"Proxy-Authorization",
	"Proxy-Authenticate",
	"Proxy-Connection",
	"TE",
	"Trailer",
	"Transfer-Encoding",
	"Upgrade",
}

// Options configures the intercepting proxy.
type Options struct {
	// Address is the host:port to listen on.
	Address string
	// CADir is the directory holding the interception CA.
	CADir string
	// Username and Password gate the proxy with basic authentication. They are
	// mandatory when Address is not a loopback address.
	Username string
	Password string
	// Verbose enables goproxy's own request logging.
	Verbose bool
	// Intercept reports whether the TLS connection to host should be decrypted.
	// Hosts it rejects are tunnelled through without inspection. Optional;
	// every host is intercepted when nil.
	Intercept func(host string) bool
	// Submit hands a captured request to the scanner. It must not block, and
	// returns false when the request could not be queued.
	Submit func(rawHTTP, targetURL string) bool
	// ForwardProxy is an optional HTTP(S) proxy URL for the forwarding leg.
	// Ambient HTTP_PROXY / HTTPS_PROXY are ignored so a leftover environment
	// variable cannot silently chain this listener.
	ForwardProxy string
}

// Proxy is an intercepting proxy that mirrors traffic into the scanner.
type Proxy struct {
	options *Options
	ca      *CA
	server  *http.Server

	intercepted          atomic.Int64
	tunnelsPassedThrough atomic.Int64
	dropped              atomic.Int64
}

// requestState is what a proxied request carries between the goproxy hooks.
// A CONNECT tunnel reuses one instance for every request inside it.
type requestState struct {
	tunnelAuthorized bool
	rawHTTP          string
}

// Stats reports what the proxy has done with the traffic it has seen.
type Stats struct {
	Intercepted int64
	// TunnelsPassedThrough counts CONNECT tunnels left encrypted, not requests:
	// their contents are never seen.
	TunnelsPassedThrough int64
	Dropped              int64
}

// New returns a proxy ready to be started.
func New(options *Options) (*Proxy, error) {
	if options.Submit == nil {
		return nil, errors.New("proxy requires a submit callback")
	}
	if err := validateBinding(options); err != nil {
		return nil, err
	}
	if _, err := parseForwardProxy(options.ForwardProxy); err != nil {
		return nil, err
	}
	ca, err := LoadOrCreateCA(options.CADir)
	if err != nil {
		return nil, err
	}

	proxy := &Proxy{options: options, ca: ca}
	proxy.server = &http.Server{
		Handler: proxy.handler(),
		// Read and write timeouts would break long lived CONNECT tunnels, so
		// only the header read is bounded.
		ReadHeaderTimeout: readHeaderTimeout,
	}
	return proxy, nil
}

// CertPath is the on-disk path of the CA certificate users need to trust.
func (p *Proxy) CertPath() string { return p.ca.CertPath }

// CertPEM is the PEM encoded CA certificate. It never contains the key.
func (p *Proxy) CertPEM() []byte { return p.ca.CertPEM }

// Stats returns the current proxy counters.
func (p *Proxy) Stats() Stats {
	return Stats{
		Intercepted:          p.intercepted.Load(),
		TunnelsPassedThrough: p.tunnelsPassedThrough.Load(),
		Dropped:              p.dropped.Load(),
	}
}

// Start listens and serves until Close is called.
func (p *Proxy) Start() error {
	listener, err := net.Listen("tcp", p.options.Address)
	if err != nil {
		return errors.Wrap(err, "could not listen on dast proxy address")
	}
	if err := p.server.Serve(listener); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

// Close shuts the proxy listener down.
func (p *Proxy) Close() error {
	if p.server == nil {
		return nil
	}
	if err := p.server.Close(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

func (p *Proxy) handler() http.Handler {
	handler := goproxy.NewProxyHttpServer()
	handler.Verbose = p.options.Verbose
	handler.Logger = proxyLogger{}
	handler.CertStore = newCertCache()
	// Stated rather than inherited from goproxy's default, because it is a
	// deliberate choice: the forwarding leg does not verify target certificates,
	// matching the rest of nuclei (see httpclientpool), since DAST targets
	// routinely serve self-signed ones. Interception inherently replaces the
	// browser's own validation, so this is reported at startup.
	forward, _ := parseForwardProxy(p.options.ForwardProxy)
	handler.Tr = &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true}, // #nosec G402
		Proxy:           forward,
	}

	// Every action carries our own CA. goproxy's package level OkConnect and
	// MitmConnect close over its built-in CA, whose private key ships with the
	// library, so none of them are reused here.
	signWithOurCA := goproxy.TLSConfigFromCA(p.ca.Certificate)
	mitm := &goproxy.ConnectAction{Action: goproxy.ConnectMitm, TLSConfig: signWithOurCA}
	tunnel := &goproxy.ConnectAction{Action: goproxy.ConnectAccept, TLSConfig: signWithOurCA}
	// Answering CONNECT with a challenge rather than dropping the connection is
	// what lets a browser prompt for the proxy credentials.
	challenge := &goproxy.ConnectAction{
		Action: goproxy.ConnectHijack,
		Hijack: func(req *http.Request, client net.Conn, _ *goproxy.ProxyCtx) {
			defer func() { _ = client.Close() }()
			if err := authRequiredResponse(req).Write(client); err != nil {
				gologger.Debug().Msgf("Could not write proxy auth challenge: %s", err)
			}
		},
		TLSConfig: signWithOurCA,
	}

	handler.OnRequest().HandleConnectFunc(func(host string, ctx *goproxy.ProxyCtx) (*goproxy.ConnectAction, string) {
		if !p.authorized(ctx.Req) {
			return challenge, host
		}
		// A client only sends Proxy-Authorization on CONNECT, so the successful
		// check is recorded on the context that every request inside the tunnel
		// goes on to share, rather than being repeated per request.
		ctx.UserData = &requestState{tunnelAuthorized: true}

		if p.options.Intercept != nil && !p.options.Intercept(host) {
			p.tunnelsPassedThrough.Add(1)
			return tunnel, host
		}
		return mitm, host
	})

	handler.OnRequest().DoFunc(func(req *http.Request, ctx *goproxy.ProxyCtx) (*http.Request, *http.Response) {
		state, _ := ctx.UserData.(*requestState)
		if state == nil || !state.tunnelAuthorized {
			if !p.authorized(req) {
				return req, authRequiredResponse(req)
			}
			state = &requestState{}
			ctx.UserData = state
		}
		// The body has to be captured before the transport consumes it, but the
		// response is only available later, so the raw request rides along on
		// the context until then.
		if raw, ok := captureRequest(req); ok {
			state.rawHTTP = raw
		}
		return req, nil
	})

	handler.OnResponse().DoFunc(func(resp *http.Response, ctx *goproxy.ProxyCtx) *http.Response {
		p.submit(ctx)
		return resp
	})

	return handler
}

// submit mirrors an intercepted request into the scanner. It runs while the
// client is still waiting for its response, so it must stay non-blocking.
func (p *Proxy) submit(ctx *goproxy.ProxyCtx) {
	if ctx == nil || ctx.Req == nil {
		return
	}
	state, ok := ctx.UserData.(*requestState)
	if !ok || state.rawHTTP == "" {
		return
	}
	raw := state.rawHTTP
	// Cleared so a tunnel that reuses this state cannot mirror it twice.
	state.rawHTTP = ""

	p.intercepted.Add(1)
	if !p.options.Submit(raw, ctx.Req.URL.String()) {
		p.dropped.Add(1)
	}
}

func (p *Proxy) authorized(req *http.Request) bool {
	if p.options.Username == "" && p.options.Password == "" {
		return true
	}
	if req == nil {
		return false
	}
	username, password, ok := parseProxyAuth(req.Header.Get("Proxy-Authorization"))
	if !ok {
		return false
	}
	// Both comparisons always run so the result does not leak which half failed.
	userMatch := subtle.ConstantTimeCompare([]byte(username), []byte(p.options.Username))
	passMatch := subtle.ConstantTimeCompare([]byte(password), []byte(p.options.Password))
	return userMatch&passMatch == 1
}

func parseProxyAuth(header string) (username, password string, ok bool) {
	const prefix = "Basic "
	if len(header) < len(prefix) || !strings.EqualFold(header[:len(prefix)], prefix) {
		return "", "", false
	}
	decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(header[len(prefix):]))
	if err != nil {
		return "", "", false
	}
	username, password, found := strings.Cut(string(decoded), ":")
	if !found {
		return "", "", false
	}
	return username, password, true
}

func authRequiredResponse(req *http.Request) *http.Response {
	resp := goproxy.NewResponse(req, "text/plain", http.StatusProxyAuthRequired, "proxy authentication required\n")
	resp.Header.Set("Proxy-Authenticate", `Basic realm="nuclei dast proxy"`)
	// goproxy leaves the protocol version unset, which writes a "HTTP/0.0"
	// status line that strict clients reject when this is hijacked onto a raw
	// connection to answer CONNECT.
	resp.Proto, resp.ProtoMajor, resp.ProtoMinor = "HTTP/1.1", 1, 1
	resp.Close = true
	return resp
}

// captureRequest renders the request as raw HTTP for the scanner, leaving the
// request that gets forwarded untouched.
func captureRequest(req *http.Request) (string, bool) {
	if req == nil || req.URL == nil {
		return "", false
	}
	if req.URL.Scheme != "http" && req.URL.Scheme != "https" {
		return "", false
	}
	// A body with no declared length, or one above the cap, is not mirrored at
	// all: fuzzing a large upload is not useful, buffering it would let proxied
	// traffic drive the scanner's memory use, and capturing only the headers
	// would hand the scanner a request that contradicts its own Content-Length.
	if hasBody(req) && (req.ContentLength < 0 || req.ContentLength > maxCapturedBodySize) {
		return "", false
	}

	body, err := bufferBody(req)
	if err != nil {
		gologger.Debug().Msgf("Could not buffer proxied request body: %s", err)
		return "", false
	}

	capture := req.Clone(req.Context())
	capture.Body = io.NopCloser(bytes.NewReader(body))
	capture.ContentLength = int64(len(body))
	// The proxy's own absolute-form request URI is not what the target sees.
	capture.RequestURI = ""
	// goproxy only strips hop-by-hop headers after this hook has run, so the
	// copy is sanitised here. The proxy credential in particular must never be
	// replayed to a target or written into scan output.
	stripHopByHopHeaders(capture.Header)

	dumped, err := httputil.DumpRequest(capture, true)
	if err != nil {
		gologger.Debug().Msgf("Could not capture proxied request: %s", err)
		return "", false
	}
	return string(dumped), true
}

func stripHopByHopHeaders(header http.Header) {
	for _, extra := range header.Values("Connection") {
		for _, name := range strings.Split(extra, ",") {
			if name = strings.TrimSpace(name); name != "" {
				header.Del(name)
			}
		}
	}
	for _, name := range hopByHopHeaders {
		header.Del(name)
	}
}

func parseForwardProxy(raw string) (func(*http.Request) (*url.URL, error), error) {
	if raw == "" {
		return nil, nil
	}
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Host == "" {
		return nil, errors.Errorf("invalid dast proxy forward proxy %q", raw)
	}
	return http.ProxyURL(parsed), nil
}

func hasBody(req *http.Request) bool {
	return req.Body != nil && req.Body != http.NoBody
}

// bufferBody reads the body and restores it on req so the request can still be
// forwarded after being mirrored.
func bufferBody(req *http.Request) ([]byte, error) {
	if !hasBody(req) {
		return nil, nil
	}
	body, err := io.ReadAll(io.LimitReader(req.Body, maxCapturedBodySize))
	if err != nil {
		return nil, err
	}
	req.Body = io.NopCloser(bytes.NewReader(body))
	return body, nil
}

func validateBinding(options *Options) error {
	host, _, err := net.SplitHostPort(options.Address)
	if err != nil {
		return errors.Wrapf(err, "invalid dast proxy address %q", options.Address)
	}
	if (options.Username == "") != (options.Password == "") {
		return errors.New("dast proxy auth needs both a username and a password")
	}
	if options.Username != "" || isLoopback(host) {
		return nil
	}
	// An unauthenticated proxy on a routable address is an open relay for
	// anyone who can reach it.
	return errors.Errorf("refusing to bind dast proxy to %q without authentication, pass -dast-proxy-auth user:pass or bind to localhost", options.Address)
}

func isLoopback(host string) bool {
	if host == "" {
		// A bare port binds every interface.
		return false
	}
	if host == "localhost" {
		return true
	}
	if ip := net.ParseIP(host); ip != nil {
		return ip.IsLoopback()
	}
	return false
}

// certCache memoises the leaf certificate minted for each intercepted host.
type certCache struct {
	certs sync.Map
}

func newCertCache() *certCache { return &certCache{} }

func (c *certCache) Fetch(hostname string, gen func() (*tls.Certificate, error)) (*tls.Certificate, error) {
	if cached, ok := c.certs.Load(hostname); ok {
		return cached.(*tls.Certificate), nil
	}
	cert, err := gen()
	if err != nil {
		return nil, err
	}
	actual, _ := c.certs.LoadOrStore(hostname, cert)
	return actual.(*tls.Certificate), nil
}

type proxyLogger struct{}

func (proxyLogger) Printf(format string, v ...any) {
	gologger.Debug().Msgf(format, v...)
}

// ParseAuth splits a user:pass credential pair as accepted on the command line.
func ParseAuth(value string) (username, password string, err error) {
	if value == "" {
		return "", "", nil
	}
	username, password, found := strings.Cut(value, ":")
	if !found || username == "" || password == "" {
		return "", "", errors.New("dast proxy auth must be in user:pass format")
	}
	return username, password, nil
}

package proxy

import (
	"bufio"
	"crypto/tls"
	"crypto/x509"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/input/types"
	"github.com/stretchr/testify/require"
)

type captured struct {
	rawHTTP   string
	targetURL string
}

// newTestProxy returns a proxy served over a local listener along with the
// requests it mirrors into the scanner.
func newTestProxy(t *testing.T, options *Options) (*Proxy, *url.URL, <-chan captured) {
	t.Helper()

	mirrored := make(chan captured, 8)
	options.CADir = t.TempDir()
	options.Submit = func(rawHTTP, targetURL string) bool {
		mirrored <- captured{rawHTTP: rawHTTP, targetURL: targetURL}
		return true
	}
	if options.Address == "" {
		options.Address = "127.0.0.1:0"
	}

	instance, err := New(options)
	require.NoError(t, err)

	frontend := httptest.NewServer(instance.server.Handler)
	t.Cleanup(frontend.Close)

	proxyURL, err := url.Parse(frontend.URL)
	require.NoError(t, err)
	return instance, proxyURL, mirrored
}

// skipInstance drops the proxy handle for tests that only drive it over HTTP.
func skipInstance(_ *Proxy, proxyURL *url.URL, mirrored <-chan captured) (*url.URL, <-chan captured) {
	return proxyURL, mirrored
}

func clientThrough(proxyURL *url.URL) *http.Client {
	return &http.Client{Transport: &http.Transport{Proxy: http.ProxyURL(proxyURL)}}
}

func TestProxyForwardsAndMirrorsRequest(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.WriteString(w, "upstream-body")
	}))
	defer upstream.Close()

	proxyURL, mirrored := skipInstance(newTestProxy(t, &Options{}))

	resp, err := clientThrough(proxyURL).Post(upstream.URL+"/login?next=/admin", "application/json", strings.NewReader(`{"user":"admin"}`))
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	require.Equal(t, http.StatusOK, resp.StatusCode)
	require.Equal(t, "upstream-body", string(body), "proxy must forward the upstream response untouched")

	got := <-mirrored
	require.Equal(t, upstream.URL+"/login?next=/admin", got.targetURL)

	// The scanner consumes the mirrored traffic through this parser, so the
	// capture is only useful if it round-trips.
	parsed, err := types.ParseRawRequestWithURL(got.rawHTTP, got.targetURL)
	require.NoError(t, err)
	require.Equal(t, http.MethodPost, parsed.Request.Method)
	require.Equal(t, `{"user":"admin"}`, parsed.Request.Body)
	require.Equal(t, "/login", parsed.URL.Path)
}

func TestProxyRequiresAuthWhenConfigured(t *testing.T) {
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "upstream-body")
	}))
	defer upstream.Close()

	proxyURL, mirrored := skipInstance(newTestProxy(t, &Options{Username: "nuclei", Password: "s3cret"}))

	resp, err := clientThrough(proxyURL).Get(upstream.URL + "/")
	require.NoError(t, err)
	_ = resp.Body.Close()
	require.Equal(t, http.StatusProxyAuthRequired, resp.StatusCode)
	require.Contains(t, resp.Header.Get("Proxy-Authenticate"), "Basic")
	require.Empty(t, mirrored, "an unauthenticated request must not reach the scanner")

	authenticated := proxyURL
	authenticated.User = url.UserPassword("nuclei", "s3cret")
	resp, err = clientThrough(authenticated).Get(upstream.URL + "/")
	require.NoError(t, err)
	_ = resp.Body.Close()
	require.Equal(t, http.StatusOK, resp.StatusCode)
	require.Equal(t, upstream.URL+"/", (<-mirrored).targetURL)
}

func TestProxyRejectsWrongCredentials(t *testing.T) {
