		_, _ = conn.Write([]byte("NUCLEI"))
	})
	defer server.Close()

	results, err := runSignedNucleiTemplateAndGetResults(filePath, server.URL, debug)
	if err != nil {
		return err
	}
	if err := errState.Err(); err != nil {
