import (
	"context"
	"time"

	"github.com/logrusorgru/aurora/v4"
	"github.com/projectdiscovery/nuclei/v3/internal/tests/testutils"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/loader"
	"github.com/projectdiscovery/nuclei/v3/pkg/core"
	"github.com/projectdiscovery/nuclei/v3/pkg/input/provider"
	"github.com/projectdiscovery/nuclei/v3/pkg/loader/workflow"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
	"github.com/projectdiscovery/utils/errkit"
)

// unsafeOptions are those nuclei objects/instances/types
// that are required to run nuclei engine but are not thread safe
// hence they are ephemeral and are created on every ExecuteNucleiWithOpts invocation
// in ThreadSafeNucleiEngine
type unsafeOptions struct {
	executerOpts *protocols.ExecutorOptions
}

// createEphemeralObjects creates ephemeral nuclei objects/instances/types.
// outputWriter overrides the base engine writer when non-nil (used for per-call callbacks).
func createEphemeralObjects(ctx context.Context, base *NucleiEngine, opts *types.Options, outputWriter output.Writer) (*unsafeOptions, error) {
	if outputWriter == nil {
		outputWriter = base.customWriter
	}
	u := &unsafeOptions{}
	u.executerOpts = &protocols.ExecutorOptions{
		Output:       outputWriter,
		Options:      opts,
		Progress:     base.customProgress,
		Catalog:      base.catalog,
		IssuesClient: base.rc,
		RateLimiter:  base.rateLimiter,

		RequestBodyBudget: base.executerOpts.RequestBodyBudget,
		Interactsh:        base.interactshClient,
		Colorizer:         aurora.New(aurora.WithColors(true)),
		ResumeCfg:         types.NewResumeCfg(),
		Parser:            base.parser,
		Browser:           base.browserInstance,
		DoNotCache:        opts.DoNotCacheTemplates,
	}
	if base.interactshClient != nil {
		u.executerOpts.InteractshScope = base.interactshClient.NewRequestScope()
	}
	if opts.ShouldUseHostError() && base.hostErrCache != nil {
		u.executerOpts.HostErrorsCache = base.hostErrCache
	}
	if opts.RateLimitMinute > 0 {
		opts.RateLimit = opts.RateLimitMinute
		opts.RateLimitDuration = time.Minute
	}
	if opts.RateLimit > 0 && opts.RateLimitDuration == 0 {
		opts.RateLimitDuration = time.Second
	}
	u.executerOpts.RateLimiter = utils.GetRateLimiter(ctx, opts.RateLimit, opts.RateLimitDuration)
	return u, nil
}

// restoreBaseExcludeTags re-adds any of the engine's baseline excluded tags that
// a per-execution option dropped, appending only what is missing so the result
// is order-stable and repeated application is a no-op.
//
// The current ExcludeTags slice is cloned before merging so a caller-owned
// backing array (e.g. a reused WithTemplateFilters ExcludeTags value with spare
// capacity) is never mutated or shared across concurrent executions.
func restoreBaseExcludeTags(base []string, opts *types.Options) {
	if len(base) == 0 {
		return
	}
	merged := append([]string(nil), opts.ExcludeTags...)
	present := make(map[string]struct{}, len(merged)+len(base))
	for _, tag := range merged {
		present[tag] = struct{}{}
	}
	for _, tag := range base {
		if _, ok := present[tag]; ok {
			continue
		}
		merged = append(merged, tag)
		present[tag] = struct{}{}
	}
	opts.ExcludeTags = merged
}

// resolveEphemeralOutput combines the base/global writer with any per-call result callbacks.
// Global callbacks keep working; per-call callbacks are isolated to this execution.
func resolveEphemeralOutput(base, call *NucleiEngine) output.Writer {
	out := base.customWriter
	if call == nil || len(call.resultCallbacks) == 0 {
		return out
	}

	callbacks := append([]func(event *output.ResultEvent){}, call.resultCallbacks...)
	callWriter := testutils.NewMockOutputWriter(call.opts.OmitTemplate)
	callWriter.WriteCallback = func(event *output.ResultEvent) {
		for _, cb := range callbacks {
			if cb != nil {
				cb(event)
			}
		}
	}

	if out == nil {
		return callWriter
	}
	return output.NewMultiWriter(out, callWriter)
}

// closeEphemeralObjects closes all resources used by ephemeral nuclei objects/instances/types
func closeEphemeralObjects(u *unsafeOptions) {
	if u.executerOpts.InteractshScope != nil {
		u.executerOpts.InteractshScope.Close()
	}
	if u.executerOpts.RateLimiter != nil {
		u.executerOpts.RateLimiter.Stop()
	}
	// dereference all objects that were inherited from base nuclei engine
	// since these are meant to be closed globally by base nuclei engine
	u.executerOpts.Output = nil
	u.executerOpts.IssuesClient = nil
	u.executerOpts.Interactsh = nil
	u.executerOpts.InteractshScope = nil
	u.executerOpts.HostErrorsCache = nil
	u.executerOpts.Progress = nil
	u.executerOpts.Catalog = nil
	u.executerOpts.Parser = nil
}

// ThreadSafeNucleiEngine is a tweaked version of nuclei.Engine whose methods are thread-safe
// and can be used concurrently. Non-thread-safe methods start with Global prefix
type ThreadSafeNucleiEngine struct {
	eng *NucleiEngine
}

// NewThreadSafeNucleiEngine creates a new nuclei engine with given options
// whose methods are thread-safe and can be used concurrently
// Note: Non-thread-safe methods start with Global prefix
func NewThreadSafeNucleiEngineCtx(ctx context.Context, opts ...NucleiSDKOptions) (*ThreadSafeNucleiEngine, error) {
	defaultOptions := types.DefaultOptions()
	e := &NucleiEngine{
		opts:   defaultOptions,
		mode:   threadSafe,
		ctx:    ctx,
		Logger: defaultOptions.Logger,
	}
	for _, option := range opts {
		if err := option(e); err != nil {
			return nil, err
		}
	}
	if err := e.init(ctx); err != nil {
		return nil, err
	}
	return &ThreadSafeNucleiEngine{eng: e}, nil
}

// Deprecated: use NewThreadSafeNucleiEngineCtx instead
func NewThreadSafeNucleiEngine(opts ...NucleiSDKOptions) (*ThreadSafeNucleiEngine, error) {
	return NewThreadSafeNucleiEngineCtx(context.Background(), opts...)
}

// GlobalLoadAllTemplates loads all templates from nuclei-templates repo
// This method will load all templates based on filters given at the time of nuclei engine creation in opts
func (e *ThreadSafeNucleiEngine) GlobalLoadAllTemplates() error {
	return e.eng.LoadAllTemplates()
}

// GlobalResultCallback sets a callback function which will be called for each result
// across all ExecuteNucleiWithOpts invocations. For a callback scoped to a single
// execution, pass WithResultCallback in that call's opts instead.
func (e *ThreadSafeNucleiEngine) GlobalResultCallback(callback func(event *output.ResultEvent)) {
	e.eng.resultCallbacks = []func(*output.ResultEvent){callback}
}

// ExecuteNucleiWithOptsCtx executes templates on targets and can be called concurrently.
// Pass WithResultCallback in opts for a per-execution result callback (combined with any
// GlobalResultCallback). Not all options are thread-safe.
func (e *ThreadSafeNucleiEngine) ExecuteNucleiWithOptsCtx(ctx context.Context, targets []string, opts ...NucleiSDKOptions) error {
	baseOpts := e.eng.opts.Copy()
	tmpEngine := &NucleiEngine{opts: baseOpts, mode: threadSafe}
	for _, option := range opts {
		if err := option(tmpEngine); err != nil {
			return err
		}
	}
	// Per-execution options land on a COPY of the engine's options, so an option
	// that assigns a whole filter set clears every field it does not name —
	// WithTemplateFilters does exactly that. ExcludeTags is one of those fields,
	// and it carries the .nuclei-ignore deny-list that applyRequiredDefaults
	// installed at construction; nothing re-reads the ignore file afterwards, so
	// the exclusions would be lost for this execution and templates tagged dos,
	// bruteforce, fuzz, local or txt-service would run.
	//
	// Restore the engine's baseline exclusions so a per-execution filter can add
	// to them but never silently discard them. IncludeTags remains the explicit
	// per-tag override for callers who do want an ignored template to run.
	restoreBaseExcludeTags(e.eng.opts.ExcludeTags, tmpEngine.opts)

	// create ephemeral nuclei objects/instances/types using base nuclei engine
	unsafeOpts, err := createEphemeralObjects(ctx, e.eng, tmpEngine.opts, resolveEphemeralOutput(e.eng, tmpEngine))
	if err != nil {
		return err
	}
	// cleanup and stop all resources
	defer closeEphemeralObjects(unsafeOpts)

	// load templates
	workflowLoader, err := workflow.NewLoader(unsafeOpts.executerOpts)
	if err != nil {
		return errkit.Wrapf(err, "Could not create workflow loader: %s", err)
	}
	unsafeOpts.executerOpts.WorkflowLoader = workflowLoader

	loaderConfig := loader.NewConfig(tmpEngine.opts, e.eng.catalog, unsafeOpts.executerOpts)
	loaderConfig.MetadataIndex = e.eng.getMetadataIndex()
	store, err := loader.New(loaderConfig)
	if err != nil {
		return errkit.Wrapf(err, "Could not create loader client: %s", err)
	}
	if err := store.Load(); err != nil {
		return errkit.Wrapf(err, "Could not load templates: %s", err)
	}

	inputProvider := provider.NewSimpleInputProviderWithUrls(e.eng.opts.ExecutionId, targets...)

	if len(store.Templates()) == 0 && len(store.Workflows()) == 0 {
		return ErrNoTemplatesAvailable
	}
	if inputProvider.Count() == 0 {
		return ErrNoTargetsAvailable
	}

	engine := core.New(tmpEngine.opts)
	engine.SetExecuterOptions(unsafeOpts.executerOpts)

	_ = engine.ExecuteScanWithOpts(ctx, store.Templates(), inputProvider, false)

	engine.WorkPool().Wait()
	return nil
}

// ExecuteNucleiWithOpts is same as ExecuteNucleiWithOptsCtx but with default context
// This is a placeholder and will be deprecated in future major release
func (e *ThreadSafeNucleiEngine) ExecuteNucleiWithOpts(targets []string, opts ...NucleiSDKOptions) error {
	return e.ExecuteNucleiWithOptsCtx(context.Background(), targets, opts...)
}

// Close all resources used by nuclei engine
func (e *ThreadSafeNucleiEngine) Close() {
	e.eng.Close()
}

package nuclei

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/index"
)

func BenchmarkExecuteNucleiWithOptsCtx(b *testing.B) {
	templatePath := filepath.Join(b.TempDir(), "benchmark.yaml")
	err := os.WriteFile(templatePath, []byte(`id: benchmark-execute-nuclei-with-opts-ctx

info:
  name: Benchmark ExecuteNucleiWithOptsCtx
  author: pdteam
  severity: info

http:
  - method: GET
    path:
      - "{{BaseURL}}"
    matchers:
      - type: status
        status:
          - 418
`), 0o600)
	if err != nil {
		b.Fatalf("could not write benchmark template: %s", err)
	}

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusNoContent)
	}))
	b.Cleanup(server.Close)

	metadataIndex, err := index.NewIndex(b.TempDir())
	if err != nil {
		b.Fatalf("could not create benchmark metadata index: %s", err)
	}

	engine, err := NewThreadSafeNucleiEngineCtx(
		b.Context(),
		DisableUpdateCheck(),
		WithTemplatesOrWorkflows(TemplateSources{Templates: []string{templatePath}}),
	)
	if err != nil {
		b.Fatalf("could not create thread-safe nuclei engine: %s", err)
	}
	b.Cleanup(engine.Close)

	// Keep benchmark metadata isolated from the user's persistent cache.
	engine.eng.metadataIndexOnce.Do(func() {
		engine.eng.metadataIndex = metadataIndex
	})

	targets := []string{server.URL}
	if err := engine.ExecuteNucleiWithOptsCtx(b.Context(), targets); err != nil {
		b.Fatalf("could not warm up nuclei execution: %s", err)
	}

	b.ReportAllocs()
	b.ResetTimer()

	for b.Loop() {
		if err := engine.ExecuteNucleiWithOptsCtx(b.Context(), targets); err != nil {
			b.Fatalf("could not execute nuclei: %s", err)
		}
	}
}

package nuclei

import (
	"sync"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/assert"
)

func TestRestoreBaseExcludeTags(t *testing.T) {
	tests := []struct {
		name     string
		base     []string
		current  []string
		expected []string
	}{
		{
			name:     "per-execution filter cleared the deny-list",
			base:     []string{"dos", "fuzz"},
			current:  nil,
			expected: []string{"dos", "fuzz"},
		},
		{
			name:     "per-execution exclusions are kept alongside the baseline",
			base:     []string{"dos"},
			current:  []string{"custom"},
			expected: []string{"custom", "dos"},
		},
		{
			name:     "entries already present are not duplicated",
			base:     []string{"dos", "fuzz"},
			current:  []string{"fuzz"},
			expected: []string{"fuzz", "dos"},
		},
		{
			name:     "no baseline is a no-op",
			base:     nil,
			current:  []string{"custom"},
			expected: []string{"custom"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			opts := &types.Options{ExcludeTags: tt.current}
			restoreBaseExcludeTags(tt.base, opts)
			assert.Equal(t, tt.expected, []string(opts.ExcludeTags))
		})
	}
}

// TestRestoreBaseExcludeTagsIsIdempotent matters because the helper runs on
// every execution against a long-lived engine.
func TestRestoreBaseExcludeTagsIsIdempotent(t *testing.T) {
	opts := &types.Options{}
	restoreBaseExcludeTags([]string{"dos", "fuzz"}, opts)
	restoreBaseExcludeTags([]string{"dos", "fuzz"}, opts)

	assert.Equal(t, []string{"dos", "fuzz"}, []string(opts.ExcludeTags))
}

// TestRestoreBaseExcludeTagsDoesNotMutateCallerSlice guards the concurrent
// ThreadSafeNucleiEngine case where WithTemplateFilters assigns a caller-owned
// ExcludeTags slice with spare capacity: a naive append would race and mutate
// the caller's backing array.
func TestRestoreBaseExcludeTagsDoesNotMutateCallerSlice(t *testing.T) {
	shared := make([]string, 1, 8)
	shared[0] = "custom"
	base := []string{"dos", "fuzz"}

	var wg sync.WaitGroup
	for i := 0; i < 32; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			opts := &types.Options{ExcludeTags: shared}
			restoreBaseExcludeTags(base, opts)
			if got := []string(opts.ExcludeTags); len(got) != 3 || got[0] != "custom" || got[1] != "dos" || got[2] != "fuzz" {
				panic(got)
			}
		}()
	}
	wg.Wait()

	assert.Equal(t, []string{"custom"}, shared[:1])
	assert.Equal(t, make([]string, 7), shared[1:cap(shared)])
}

package nuclei_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync"
	"testing"

	nuclei "github.com/projectdiscovery/nuclei/v3/lib"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/stretchr/testify/require"
)

func TestThreadSafeWithResultCallbackIsolation(t *testing.T) {
	templatePath := writeSDKMatchTemplate(t)

	srvA := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("token-A-unique"))
	}))
	t.Cleanup(srvA.Close)

	srvB := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("token-B-unique"))
	}))
	t.Cleanup(srvB.Close)

	ne, err := nuclei.NewThreadSafeNucleiEngineCtx(context.Background())
	require.NoError(t, err)
	t.Cleanup(ne.Close)

	var (
		mu          sync.Mutex
		callbackA   []string
		callbackB   []string
		globalURLs  []string
		globalCount int
		errA, errB  error
	)

	ne.GlobalResultCallback(func(event *output.ResultEvent) {
		mu.Lock()
		defer mu.Unlock()
		globalCount++
		globalURLs = append(globalURLs, eventMatchedURL(event))
	})

	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		errA = ne.ExecuteNucleiWithOptsCtx(context.Background(), []string{srvA.URL},
			nuclei.WithTemplatesOrWorkflows(nuclei.TemplateSources{Templates: []string{templatePath}}),
			nuclei.WithTemplateFilters(nuclei.TemplateFilters{IDs: []string{"sdk-callback-match"}}),
			nuclei.WithResultCallback(func(event *output.ResultEvent) {
				mu.Lock()
				defer mu.Unlock()
				callbackA = append(callbackA, eventMatchedURL(event))
			}),
		)
	}()

	go func() {
		defer wg.Done()
		errB = ne.ExecuteNucleiWithOptsCtx(context.Background(), []string{srvB.URL},
			nuclei.WithTemplatesOrWorkflows(nuclei.TemplateSources{Templates: []string{templatePath}}),
			nuclei.WithTemplateFilters(nuclei.TemplateFilters{IDs: []string{"sdk-callback-match"}}),
			nuclei.WithResultCallback(func(event *output.ResultEvent) {
				mu.Lock()
				defer mu.Unlock()
				callbackB = append(callbackB, eventMatchedURL(event))
			}),
		)
	}()

	wg.Wait()

	require.NoError(t, errA)
	require.NoError(t, errB)

	mu.Lock()
	defer mu.Unlock()

	require.NotEmpty(t, callbackA, "per-call callback A should receive results")
	require.NotEmpty(t, callbackB, "per-call callback B should receive results")
	for _, matched := range callbackA {
		require.Contains(t, matched, srvA.URL, "callback A must only see server A")
		require.NotContains(t, matched, srvB.URL, "callback A must not see server B")
	}
	for _, matched := range callbackB {
		require.Contains(t, matched, srvB.URL, "callback B must only see server B")
		require.NotContains(t, matched, srvA.URL, "callback B must not see server A")
	}

	// Global callback still sees both executions (no regression).
	require.GreaterOrEqual(t, globalCount, 2)
	require.NotEmpty(t, globalURLs)
}

func TestThreadSafeGlobalCallbackWithoutPerCallStillWorks(t *testing.T) {
	templatePath := writeSDKMatchTemplate(t)

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("token-A-unique"))
	}))
	t.Cleanup(srv.Close)

	ne, err := nuclei.NewThreadSafeNucleiEngineCtx(context.Background())
	require.NoError(t, err)
	t.Cleanup(ne.Close)

	var got int
	ne.GlobalResultCallback(func(event *output.ResultEvent) {
		got++
	})

	err = ne.ExecuteNucleiWithOptsCtx(context.Background(), []string{srv.URL},
		nuclei.WithTemplatesOrWorkflows(nuclei.TemplateSources{Templates: []string{templatePath}}),
		nuclei.WithTemplateFilters(nuclei.TemplateFilters{IDs: []string{"sdk-callback-match"}}),
	)
	require.NoError(t, err)
	require.GreaterOrEqual(t, got, 1, "global callback should still receive results without WithResultCallback")
}

func TestWithResultCallbackNilIsNoop(t *testing.T) {
	ne, err := nuclei.NewThreadSafeNucleiEngineCtx(context.Background(), nuclei.WithResultCallback(nil))
	require.NoError(t, err)
	ne.Close()
}

func writeSDKMatchTemplate(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	path := filepath.Join(dir, "sdk-callback-match.yaml")
	content := `id: sdk-callback-match
info:
  name: SDK callback match
  author: nuclei-sdk-test
  severity: info
http:
  - method: GET
    path:
      - "{{BaseURL}}/"
    matchers:
      - type: word
        words:
          - "token-"
`
	require.NoError(t, os.WriteFile(path, []byte(content), 0o600))
	return path
}

// eventMatchedURL prefers Matched/URL over Host (Host omits the port).
func eventMatchedURL(event *output.ResultEvent) string {
	if event == nil {
		return ""
	}
	if event.Matched != "" {
		return event.Matched
	}
	if event.URL != "" {
		return event.URL
	}
	return event.Host
}

package nuclei

import (
	"encoding/json"
	"os"
	"path/filepath"

	"github.com/pkg/errors"                                       //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
	"github.com/projectdiscovery/nuclei/v3/pkg/types"             //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
	fileutil "github.com/projectdiscovery/utils/file"             //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
	permissionutil "github.com/projectdiscovery/utils/permission" //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
)

// loadResumeCfg returns the scan progression stored in the file set by
// WithResumeFile, or an empty one when the file does not exist yet. It mirrors
// what the CLI runner does for -resume. The thread-safe engine ignores the file,
// so a malformed one must not stop it from starting.
func (e *NucleiEngine) loadResumeCfg() (*types.ResumeCfg, error) {
	resumeCfg := types.NewResumeCfg()
	if e.mode == threadSafe || !e.opts.ShouldLoadResume() {
		return resumeCfg, nil
	}

	data, err := os.ReadFile(e.opts.Resume)
	if err != nil {
		return nil, errors.Wrap(err, "could not read resume file")
	}

	err = json.Unmarshal(data, resumeCfg)
	if err != nil {
		return nil, errors.Wrapf(err, "could not parse resume file %q", e.opts.Resume)
	}

	resumeCfg.Compile()

	return resumeCfg, nil
}

// resetResumeProgress drops the progress that earlier calls on this engine
// recorded. Each call then starts like a new CLI run with -resume: it skips what
// the loaded file marks as done and saves what it did itself over the loaded
// progress. Without it, a template that an earlier call finished stays completed
// in the next call's saved file, and resuming from that file skips work the call
// never finished.
func (e *NucleiEngine) resetResumeProgress() {
	resumeCfg := e.executerOpts.ResumeCfg

	resumeCfg.Lock()
	defer resumeCfg.Unlock()

	resumeCfg.Current = make(map[string]*types.ResumeInfo)
}

// saveResumeCfg writes the scan progression to the file set by WithResumeFile.
// It mirrors Runner.SaveResumeConfig, which the CLI calls on interrupt.
func (e *NucleiEngine) saveResumeCfg() error {
	path := e.opts.Resume

	dir := filepath.Dir(path)
	if !fileutil.FolderExists(dir) {
		err := os.MkdirAll(dir, permissionutil.ConfigFolderPermission)
		if err != nil {
			return errors.Wrapf(err, "could not create resume directory %q", dir)
		}
	}

	data, err := json.MarshalIndent(e.executerOpts.ResumeCfg.Snapshot(), "", "\t")
	if err != nil {
		return errors.Wrap(err, "could not encode resume configuration")
	}

	err = os.WriteFile(path, data, permissionutil.ConfigFilePermission)
	if err != nil {
		return errors.Wrapf(err, "could not write resume file %q", path)
	}

	return nil
}

