// applyRequiredDefaults to options
func (e *NucleiEngine) applyRequiredDefaults(ctx context.Context) {
	mockoutput := testutils.NewMockOutputWriter(e.opts.OmitTemplate)
	mockoutput.WriteCallback = func(event *output.ResultEvent) {
		if (event.Error != "" || !event.MatcherStatus) && !e.opts.MatcherStatus {
			return
		}
		if len(e.resultCallbacks) > 0 {
			for _, callback := range e.resultCallbacks {
				if callback != nil {
					callback(event)
				}
			}
			return
		}

		sb := strings.Builder{}
		fmt.Fprintf(&sb, "[%v] ", event.TemplateID)

		if event.Matched != "" {
			sb.WriteString(event.Matched)
		} else {
			sb.WriteString(event.Host)
		}

		fmt.Println(sb.String())
	}

	if e.onFailureCallback != nil {
		mockoutput.FailureCallback = e.onFailureCallback
	}

	if e.customWriter != nil {
		e.customWriter = output.NewMultiWriter(e.customWriter, mockoutput)
	} else {
		e.customWriter = mockoutput
	}

	// Inline PDCP upload wiring; mirrors the CLI's setupPDCPUpload without
	// pulling it into the exported runner surface.
	if e.opts.ScanID != "" {
		e.opts.EnableCloudUpload = true
	}
	if e.opts.EnableCloudUpload {
		creds, err := (&pdcpauth.PDCPCredHandler{}).GetCreds()
		if err != nil {
			if err != pdcpauth.ErrNoCreds {
				e.Logger.Verbose().Msgf("Could not get credentials for cloud upload: %s\n", err)
			}
			e.Logger.Warning().Msgf("To view results on Cloud Dashboard, configure API key from %v", pdcpauth.DashBoardURL)
		} else if uploadWriter, err := pdcp.NewUploadWriter(ctx, e.Logger, creds); err != nil {
			e.Logger.Warning().Msgf("PDCP (%v) Auto-Save Failed: %s", pdcpauth.DashBoardURL, err)
		} else {
			if e.opts.ScanID != "" {
				_ = uploadWriter.SetScanID(e.opts.ScanID)
			}
			if e.opts.ScanName != "" {
				uploadWriter.SetScanName(e.opts.ScanName)
			}
			if e.opts.TeamID != "" {
				uploadWriter.SetTeamID(e.opts.TeamID)
			}
			e.customWriter = output.NewMultiWriter(e.customWriter, uploadWriter)
		}
	}

	if e.customProgress == nil {
		e.customProgress = &testutils.MockProgressClient{}
	}

	if e.hostErrCache == nil && e.opts.ShouldUseHostError() {
		e.hostErrCache = hosterrorscache.New(30, hosterrorscache.DefaultMaxHostsCount, nil)
	}

	// setup interactsh
	if e.interactshOpts != nil {
		e.interactshOpts.Output = e.customWriter
		e.interactshOpts.Progress = e.customProgress
	} else {
		e.interactshOpts = interactsh.DefaultOptions(e.customWriter, e.rc, e.customProgress)
	}

	if e.rateLimiter == nil {
		if e.opts.RateLimitMinute > 0 {
			e.opts.RateLimit = e.opts.RateLimitMinute
			e.opts.RateLimitDuration = time.Minute
		}

		if e.opts.RateLimit > 0 && e.opts.RateLimitDuration == 0 {
			e.opts.RateLimitDuration = time.Second
		}
		e.rateLimiter = nucleiUtils.GetRateLimiter(ctx, e.opts.RateLimit, e.opts.RateLimitDuration)
	}

	if e.opts.ExcludeTags == nil {
		e.opts.ExcludeTags = []string{}
	}

	e.inputProvider = provider.NewSimpleInputProvider()
}

func (e *NucleiEngine) loadIgnoreFile() error {
	ignoreFile, err := config.ReadIgnoreFile()
	if errors.Is(err, os.ErrNotExist) {
		e.Logger.Warning().Msgf("Could not read active .nuclei-ignore file: %s; continuing without ignore exclusions", err)

		return nil
	}

	if err != nil {
		return err
	}

	// .nuclei-ignore blocks templates that should not run by default, by tag
	// (dos, fuzz, ...) and by path (templates known to have weak matchers, which
	// would otherwise generate false positives). Both sections are applied, as
	// the CLI runner does — applying only the tags leaves the `files` section
	// inert for every SDK consumer.
	e.opts.ExcludeTags = append(e.opts.ExcludeTags, ignoreFile.Tags...)
	e.opts.ExcludedTemplates = append(e.opts.ExcludedTemplates, ignoreFile.Files...)

	return nil
}

// init
func (e *NucleiEngine) init(ctx context.Context) error {
	if err := config.DefaultConfig.InitializationError(); err != nil {
		return errors.Wrap(err, "initialize nuclei configuration")
	}
	// Update logger ref (if it was changed by [WithLogger])
	// (Logger is already initialized)
	if e.opts.Logger != e.Logger {
		e.Logger = e.opts.Logger
	}

	if e.opts.Verbose {
		e.Logger.SetMaxLevel(levels.LevelVerbose)
	} else if e.opts.Debug {
		e.Logger.SetMaxLevel(levels.LevelDebug)
	} else if e.opts.Silent {
		e.Logger.SetMaxLevel(levels.LevelSilent)
	}

	if err := runner.ValidateOptions(e.opts); err != nil {
		return err
	}

	// Load the resume file before init creates the temp dir and the interactsh
	// client, so a bad file fails without resources to release.
	resumeCfg, resumeErr := e.loadResumeCfg()
	if resumeErr != nil {
		return resumeErr
	}

	if e.opts.Parser != nil {
		if op, ok := e.opts.Parser.(*templates.Parser); ok {
			e.parser = op
		}
	}

	if e.parser == nil {
		e.parser = templates.NewParser()
		e.ownsParser = true
	}
	e.compiledParser = e.parser
	if !e.ownsParser {
		// Compiled templates retain engine-local ExecutorOptions. Keep their
		// cache private while the caller-owned parser provides the parsed cache.
		e.compiledParser = templates.NewParserWithParsedCache(e.parser.Cache())
		e.compiledParser.ShouldValidate = e.parser.ShouldValidate
		e.compiledParser.NoStrictSyntax = e.parser.NoStrictSyntax
	}

	if protocolstate.ShouldInit(e.opts.ExecutionId) {
		_ = protocolinit.Init(e.opts)
	}

	if e.opts.ProxyInternal && (e.opts.AliveHttpProxy != "" || e.opts.AliveSocksProxy != "") {
		httpclient, err := httpclientpool.Get(e.opts, &httpclientpool.Configuration{}, "")
		if err != nil {
			return err
		}
		e.httpClient = httpclient
	}

	e.applyRequiredDefaults(ctx)
	var err error

	// setup progressbar
	if e.enableStats {
		progressInstance, progressErr := progress.NewStatsTicker(e.opts.StatsInterval, e.enableStats, e.opts.StatsJSON, false, e.opts.MetricsPort)
		if progressErr != nil {
			return err
		}
		e.customProgress = progressInstance
		e.interactshOpts.Progress = progressInstance
	}

	if err := reporting.CreateConfigIfNotExists(); err != nil {
		return err
	}
	ropts := e.reportingOpts
	if ropts == nil {
		ropts = &reporting.Options{}
	}
	if e.rc, err = reporting.New(ropts, "", false); err != nil {
		return err
	}
	e.interactshOpts.IssuesClient = e.rc
	if e.httpClient != nil {
		e.interactshOpts.HTTPClient = e.httpClient
	}
	if e.interactshClient, err = interactsh.New(e.interactshOpts); err != nil {
		return err
	}

	if e.opts.Headless {
		if engine.MustDisableSandbox() {
			e.Logger.Warning().Msgf("The current platform and privileged user will run the browser without sandbox")
		}
		browser, err := engine.New(e.opts)
		if err != nil {
			return err
		}
		e.browserInstance = browser
	}

	if e.catalog == nil {
		e.catalog = disk.NewCatalog(config.DefaultConfig.TemplatesDirectory)
	}

	if e.tmpDir == "" {
		tmpDir, err := os.MkdirTemp("", "nuclei-tmp-*")
		if err != nil {
			return err
		}
		e.tmpDir = tmpDir
	}

	e.executerOpts = &protocols.ExecutorOptions{
		Output:             e.customWriter,
		Options:            e.opts,
		Progress:           e.customProgress,
		Catalog:            e.catalog,
		IssuesClient:       e.rc,
		RateLimiter:        e.rateLimiter,
		RequestBodyBudget:  httpbody.NewBudget(int64(e.opts.MaxRequestBodyInFlight)),
		Interactsh:         e.interactshClient,
		Colorizer:          aurora.New(aurora.WithColors(true)),
		ResumeCfg:          resumeCfg,
		Browser:            e.browserInstance,
		Parser:             e.compiledParser,
		DoNotCache:         e.opts.DoNotCacheTemplates,
		InputHelper:        input.NewHelper(),
		TemporaryDirectory: e.tmpDir,
		Logger:             e.opts.Logger,
	}
	if e.opts.ShouldUseHostError() && e.hostErrCache != nil {
		e.executerOpts.HostErrorsCache = e.hostErrCache
	}
	if len(e.opts.SecretsFile) > 0 {
		authTmplStore, err := runner.GetAuthTmplStore(e.opts, e.catalog, e.executerOpts)
		if err != nil {
			return errors.Wrap(err, "failed to load dynamic auth templates")
		}
		authOpts := &authprovider.AuthProviderOptions{SecretsFiles: e.opts.SecretsFile}
		authOpts.LazyFetchSecret = runner.GetLazyAuthFetchCallback(&runner.AuthLazyFetchOptions{
			TemplateStore: authTmplStore,
			ExecOpts:      e.executerOpts,
		})
		// initialize auth provider
		provider, err := authprovider.NewAuthProvider(authOpts)
		if err != nil {
			return errors.Wrap(err, "could not create auth provider")
		}
		e.executerOpts.AuthProvider = provider
	}
	if e.authprovider != nil {
		e.executerOpts.AuthProvider = e.authprovider
	}

	// prefetch secrets to ensure authentication completes before scanning starts
	if e.executerOpts.AuthProvider != nil {
		if err := e.executerOpts.AuthProvider.PreFetchSecrets(); err != nil {
			return errors.Wrap(err, "could not prefetch secrets")
		}
	}

	if e.executerOpts.RateLimiter == nil {
		if e.opts.RateLimitMinute > 0 {
			e.opts.RateLimit = e.opts.RateLimitMinute
			e.opts.RateLimitDuration = time.Minute
		}
		if e.opts.RateLimit > 0 && e.opts.RateLimitDuration == 0 {
			e.opts.RateLimitDuration = time.Second
		}
		if e.opts.RateLimit == 0 && e.opts.RateLimitDuration == 0 {
			e.executerOpts.RateLimiter = ratelimit.NewUnlimited(ctx)
		} else {
			e.executerOpts.RateLimiter = ratelimit.New(ctx, uint(e.opts.RateLimit), e.opts.RateLimitDuration)
		}
	}

	// Handle the case where the user passed an existing parser that we can use as a cache
	if e.opts.Parser != nil {
		if cachedParser, ok := e.opts.Parser.(*templates.Parser); ok {
			e.parser = cachedParser
			e.opts.Parser = cachedParser
		}
	}

	// Create a new parser if necessary
	if e.parser == nil {
		op := templates.NewParser()
		e.parser = op
		e.ownsParser = true
		e.opts.Parser = op
		e.executerOpts.Parser = op
		e.executerOpts.Options.Parser = op
	}

	e.engine = core.New(e.opts)
	e.engine.SetExecuterOptions(e.executerOpts)

	httpxOptions := httpx.DefaultOptions
	httpxOptions.Timeout = 5 * time.Second
	if len(e.opts.InternalResolversList) > 0 {
		httpxOptions.Resolvers = e.opts.InternalResolversList
	}
	if client, err := httpx.New(&httpxOptions); err != nil {
		return err
	} else {
		e.httpxClient = nucleiUtils.GetInputLivenessChecker(client)
	}

	if DefaultConfig.CanCheckForUpdates() {
		// Only Happens once regardless how many times this function is called
		// This will update ignore file to filter out templates with weak matchers to avoid false positives
		// and also upgrade templates to latest version if available
		latestIgnoreHash, _ := installer.NucleiSDKVersionCheck()

		if err := e.processUpdateCheckResults(); err != nil {
			return err
		}

		if DefaultConfig.IgnoreFileNeedsUpdate(latestIgnoreHash) {
			if err := installer.UpdateIgnoreFile(); err != nil {
				e.opts.Logger.Warning().Msgf("failed to update nuclei ignore file: %s\n", err)
			}
		}
	}

	// Read .nuclei-ignore LAST, once init has finished managing that file and
	// the options it writes into.
	//
	// It must come after the update block above: init creates or replaces the
	// ignore file there (UpdateIgnoreFile), so reading earlier reads a file this
	// same call is about to write. On a host without a pre-existing ignore file
	// — a fresh install, or any container whose filesystem was reset — the read
	// found nothing, warned, and left the engine with an empty deny-list for its
	// whole lifetime, because ExcludeTags is never re-read after init. Reading
	// afterwards also makes the corrupt-file check recoverable rather than fatal:
	// a malformed local file that IgnoreFileNeedsUpdate replaces no longer fails
	// the scan.
	//
	// GetAuthTmplStore scopes a copy of the options, so it no longer clears
	// the engine filters. This read is still what installs the deny-list, and
	// it has to follow the update block above.
	if err := e.loadIgnoreFile(); err != nil {
		return err
	}

	return nil
}

type syncOnce struct {
	sync.Once
}

var (
	updateCheckInstance    = &syncOnce{}
	templateUpdateInstance = &syncOnce{}
)

// processUpdateCheckResults processes update check results
func (e *NucleiEngine) processUpdateCheckResults() error {
	var err error
	updateCheckInstance.Do(func() {
		if e.onUpdateAvailableCallback != nil {
			e.onUpdateAvailableCallback(config.DefaultConfig.LatestNucleiTemplatesVersion)
		}
	})
	if !e.disableTemplatesAutoUpgrade {
		templateUpdateInstance.Do(func() {
			tm := installer.TemplateManager{}
			err = tm.UpdateIfOutdated()
		})
	}
	return err
}

//go:build regression

// Package sdk_test contains an opt-in, large-scale regression harness for the
// HTTP engine. It is gated behind the "regression" build tag so it never runs
// as part of the normal unit/integration suites; run it explicitly with:
//
//	go test -tags regression ./lib/tests/ -run TestScaleRegression -v
//
// Tune the host count with NUCLEI_SCALE_HOSTS (default 50).
//
// The harness stands up many independent loopback HTTP hosts and runs a diverse
// template set (word/header/regex/status/dsl/extractor matchers, redirects, raw
// requests and a multi-step cookie-reuse flow) through the engine, asserting
// that every host yields the full expected finding set. It also includes a host
// that emits the "plain HTTP request was sent to HTTPS port" 400 body to
// exercise the HTTP->HTTPS port tracker: a wrongly detected/false-positive scheme
// rewrite must not silently drop findings of unrelated templates hitting the
// same host:port (regression guard for the tracker fallback).
package sdk_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strconv"
	"sync"
	"testing"

	nuclei "github.com/projectdiscovery/nuclei/v3/lib"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/stretchr/testify/require"
)

// scaleTemplates is the diverse template set exercised by the harness. Each one
// deterministically matches every host so per-template finding counts must
// equal the number of hosts.
var scaleTemplates = map[string]string{
	"01-basic-word.yaml": `id: scale-basic-word
info: {name: Scale Basic Word, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/"]
    matchers-condition: and
    matchers:
      - {type: word, part: body, words: ["REGRESSION-OK"]}
      - {type: status, status: [200]}
`,
	"02-header-match.yaml": `id: scale-header-match
info: {name: Scale Header Match, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/"]
    matchers:
      - {type: word, part: header, words: ["nuclei-regression"]}
`,
	"03-regex.yaml": `id: scale-regex
info: {name: Scale Regex, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/"]
    matchers:
      - {type: regex, part: body, regex: ["token=[A-Z0-9]{6}"]}
`,
	"04-multi-cookie.yaml": `id: scale-multi-cookie
info: {name: Scale Multi-step Cookie Reuse, author: regression, severity: info}
http:
  - cookie-reuse: true
    raw:
      - |
        GET /login HTTP/1.1
        Host: {{Hostname}}
        User-Agent: regression

      - |
        GET /profile HTTP/1.1
        Host: {{Hostname}}
        User-Agent: regression

    matchers:
      - {type: word, part: body, words: ["welcome-admin"]}
`,
	"05-redirect.yaml": `id: scale-redirect
info: {name: Scale Redirect, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/redirect"]
    host-redirects: true
    max-redirects: 3
    matchers:
      - {type: word, part: body, words: ["REGRESSION-OK"]}
`,
	"06-raw.yaml": `id: scale-raw
info: {name: Scale Raw Request, author: regression, severity: info}
http:
  - raw:
      - |
        GET / HTTP/1.1
        Host: {{Hostname}}
        User-Agent: regression-raw

    matchers-condition: and
    matchers:
      - {type: status, status: [200]}
      - {type: word, part: body, words: ["build=stable"]}
`,
	"07-dsl-json.yaml": `id: scale-dsl-json
info: {name: Scale DSL JSON, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/api"]
    matchers:
      - {type: dsl, dsl: ['contains(body, "\"admin\":true") && status_code == 200']}
`,
	"08-extractor.yaml": `id: scale-extractor
info: {name: Scale Extractor, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/api"]
    extractors:
      - {type: regex, part: body, regex: ['"version":"([0-9.]+)"'], group: 1}
    matchers:
      - {type: word, part: body, words: ["active"]}
`,
	// This template triggers the HTTP->HTTPS port tracker. With the fallback in
	// place, the tracker must not cause the other plain-HTTP templates above to
	// be dropped on the same host:port.
	"09-httpsport.yaml": `id: scale-httpsport
info: {name: Scale HTTP to HTTPS Port, author: regression, severity: info}
http:
  - method: GET
    path: ["{{BaseURL}}/httpsport"]
    matchers:
      - {type: word, part: body, words: ["plain HTTP request was sent to HTTPS port"]}
`,
}

// scaleHandler serves deterministic, template-matchable content. The /httpsport
// endpoint mimics a server that received plain HTTP on an HTTPS port.
func scaleHandler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-Reg", "nuclei-regression")
		w.Header().Set("Server", "regression-test/1.0")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("REGRESSION-OK token=ABC123 build=stable\n"))
	})
	mux.HandleFunc("/login", func(w http.ResponseWriter, r *http.Request) {
		http.SetCookie(w, &http.Cookie{Name: "sess", Value: "valid-token", Path: "/"})
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("logged-in\n"))
	})
	mux.HandleFunc("/profile", func(w http.ResponseWriter, r *http.Request) {
		if c, err := r.Cookie("sess"); err != nil || c.Value != "valid-token" {
			w.WriteHeader(http.StatusUnauthorized)
			_, _ = w.Write([]byte("unauthorized\n"))
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("welcome-admin profile-data\n"))
	})
	mux.HandleFunc("/redirect", func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "/", http.StatusFound)
	})
	mux.HandleFunc("/httpsport", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusBadRequest)
		_, _ = w.Write([]byte("Client sent an HTTP request to an HTTPS server.\nThe plain HTTP request was sent to HTTPS port\n"))
	})
	mux.HandleFunc("/api", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"active","version":"2.4.1","admin":true}`))
	})
	return mux
}

func TestScaleRegression(t *testing.T) {
	hosts := 50
	if v, err := strconv.Atoi(os.Getenv("NUCLEI_SCALE_HOSTS")); err == nil && v > 0 {
		hosts = v
	}

	// Stand up N independent loopback hosts (distinct host:port each, so the
	// per-host pool / connection-reuse / http->https machinery is exercised
	// across many keys).
	handler := scaleHandler()
	targets := make([]string, 0, hosts)
	servers := make([]*httptest.Server, 0, hosts)
	for i := 0; i < hosts; i++ {
		srv := httptest.NewServer(handler)
		servers = append(servers, srv)
		targets = append(targets, srv.URL)
	}
	defer func() {
		for _, srv := range servers {
			srv.Close()
		}
	}()

	// Write the template set to a temp directory.
	tplDir := t.TempDir()
	for name, content := range scaleTemplates {
		require.NoError(t, os.WriteFile(filepath.Join(tplDir, name), []byte(content), 0o644))
	}

	ne, err := nuclei.NewNucleiEngineCtx(
		context.Background(),
		nuclei.WithTemplatesOrWorkflows(nuclei.TemplateSources{Templates: []string{tplDir}}),
		nuclei.WithSandboxOptions(true, false),
		nuclei.DisableUpdateCheck(),
	)
	require.NoError(t, err)
	defer ne.Close()

	ne.LoadTargets(targets, false)
	require.NoError(t, ne.LoadAllTemplates())

	var mu sync.Mutex
	perTemplate := map[string]int{}
	perTemplateHost := map[string]map[string]struct{}{}
	require.NoError(t, ne.ExecuteWithCallback(func(event *output.ResultEvent) {
		if event == nil {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		perTemplate[event.TemplateID]++
		if perTemplateHost[event.TemplateID] == nil {
			perTemplateHost[event.TemplateID] = map[string]struct{}{}
		}
		// key on matched-at (includes host:port) since Host alone is 127.0.0.1
		// for every loopback server
		perTemplateHost[event.TemplateID][event.Matched] = struct{}{}
	}))

	// Every template must match on every host. In particular scale-multi-cookie
	// and the other plain-HTTP templates must reach the full host count even
	// though scale-httpsport marks each host:port as "requires HTTPS" — proving
	// the http->https tracker fallback prevents silent finding loss.
	wantIDs := []string{
		"scale-basic-word", "scale-header-match", "scale-regex", "scale-multi-cookie",
		"scale-redirect", "scale-raw", "scale-dsl-json", "scale-extractor", "scale-httpsport",
	}
	for _, id := range wantIDs {
		unique := len(perTemplateHost[id])
		require.Equalf(t, hosts, unique,
			"template %q matched on %d/%d hosts (per-template hits=%d)", id, unique, hosts, perTemplate[id])
	}

	t.Logf("scale regression OK: %d hosts x %d templates = %d findings",
		hosts, len(wantIDs), hosts*len(wantIDs))
}

package sdk_test

import (
	"context"
	"os"
	"os/exec"
	"testing"
	"time"

	nuclei "github.com/projectdiscovery/nuclei/v3/lib"
	"github.com/projectdiscovery/utils/env"
	"github.com/stretchr/testify/require"
	"github.com/tarunKoyalwar/goleak"
)

var knownLeaks = []goleak.Option{
	goleak.Pretty(),
	// net/http transport maintains idle keep-alive connections whose goroutines
	// exit on idle timeout or explicit close - not real leaks.
	goleak.IgnoreAnyFunction("net/http.(*http2ClientConn).readLoop"),
	// go 1.27 moved the bundled http2 transport out of net/http, which renamed
	// the same idle connection goroutine
	goleak.IgnoreAnyFunction("net/http/internal/http2.(*ClientConn).readLoop"),
	goleak.IgnoreAnyFunction("net/http.(*persistConn).readLoop"),
	goleak.IgnoreAnyFunction("net/http.(*persistConn).writeLoop"),
	// expirable LRU cache creates a background goroutine for TTL expiration that persists
	// see: https://github.com/hashicorp/golang-lru/blob/770151e9c8cdfae1797826b7b74c33d6f103fbd8/expirable/expirable_lru.go#L79
	goleak.IgnoreAnyContainingPkg("github.com/hashicorp/golang-lru/v2/expirable"),
	// leveldb + shared rate limiter + memguardian outlive a single SDK engine.
	// Sleep alone is not reliable under -race or when NewNucleiEngineCtx fails before Close.
	goleak.IgnoreAnyContainingPkg("github.com/syndtr/goleveldb"),
	goleak.IgnoreAnyContainingPkg("github.com/projectdiscovery/ratelimit"),
	goleak.IgnoreAnyFunction("github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate.StartActiveMemGuardian.func1"),
	// NOTE(dwisiswant0): This is an indirect call and not used anywhere, not
	// even within SOPS (#5841). See `go mod why go.opencensus.io/stats/view`.
	goleak.IgnoreAnyContainingPkg("go.opencensus.io/stats/view"),
}

func TestSimpleNuclei(t *testing.T) {
	fn := func() {
		defer func() {
			// resources like leveldb have a delay to commit in-memory resources
			// to disk, typically 1-2 seconds, so we wait for 2 seconds
			time.Sleep(2 * time.Second)
			goleak.VerifyNone(t, knownLeaks...)
		}()
		ne, err := nuclei.NewNucleiEngineCtx(
			context.TODO(),
			nuclei.WithTemplateFilters(nuclei.TemplateFilters{ProtocolTypes: "dns"}), // filter dns templates
			nuclei.EnableStatsWithOpts(nuclei.StatsOptions{JSON: true}),
		)
		require.NoError(t, err)
		defer ne.Close()
		ne.LoadTargets([]string{"scanme.sh"}, false) // probe non http/https target is set to false here
		// when callback is nil it nuclei will print JSON output to stdout
		err = ne.ExecuteWithCallback(nil)
		require.NoError(t, err)
	}

	// this is shared test so needs to be run as separate process
	if env.GetEnvOrDefault("TestSimpleNuclei", false) {
		// run as new process
		cmd := exec.Command(os.Args[0], "-test.run=TestSimpleNuclei")
		cmd.Env = append(os.Environ(), "TestSimpleNuclei=true")
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("process ran with error %s, output: %s", err, out)
		}
	} else {
		fn()
	}
}

