	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatalf("create test directory: %v", err)
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		t.Fatalf("write test file: %v", err)
	}
}

func TestReloadTemplateVersion(t *testing.T) {
	newConfig := func(t *testing.T, templatesDir string) *Config {
		t.Helper()
		cfg := &Config{stateDir: t.TempDir()}
		cfg.setTemplatesDir(templatesDir)
		return cfg
	}

	t.Run("adopts the version another process installed", func(t *testing.T) {
		templatesDir := t.TempDir()
		cfg := newConfig(t, templatesDir)
		other := &Config{stateDir: cfg.stateDir, TemplateVersion: "v2.0.0"}
		other.setTemplatesDir(templatesDir)
		if err := other.WriteTemplatesConfig(); err != nil {
			t.Fatalf("write templates state: %v", err)
		}

		if err := cfg.ReloadTemplateVersion(); err != nil {
			t.Fatalf("reload templates version: %v", err)
		}
		if cfg.TemplateVersion != "v2.0.0" {
			t.Fatalf("template version = %q, want v2.0.0", cfg.TemplateVersion)
		}
	})

	t.Run("ignores state of another templates directory", func(t *testing.T) {
		cfg := newConfig(t, t.TempDir())
		cfg.TemplateVersion = "v1.0.0"
		other := &Config{stateDir: cfg.stateDir, TemplateVersion: "v2.0.0"}
		other.setTemplatesDir(t.TempDir())
		if err := other.WriteTemplatesConfig(); err != nil {
			t.Fatalf("write templates state: %v", err)
		}

		if err := cfg.ReloadTemplateVersion(); err != nil {
			t.Fatalf("reload templates version: %v", err)
		}
		if cfg.TemplateVersion != "v1.0.0" {
			t.Fatalf("template version = %q, want v1.0.0", cfg.TemplateVersion)
		}
	})

	t.Run("keeps the loaded version without state", func(t *testing.T) {
		cfg := newConfig(t, t.TempDir())
		cfg.TemplateVersion = "v1.0.0"

		if err := cfg.ReloadTemplateVersion(); err != nil {
			t.Fatalf("reload templates version: %v", err)
		}
		if cfg.TemplateVersion != "v1.0.0" {
			t.Fatalf("template version = %q, want v1.0.0", cfg.TemplateVersion)
		}
	})

	t.Run("adopts the version written through the other name of a symlink", func(t *testing.T) {
		templatesDir := t.TempDir()
		link := filepath.Join(t.TempDir(), "templates-link")
		if err := os.Symlink(templatesDir, link); err != nil {
			t.Skipf("symlinks are unavailable: %v", err)
		}

		cfg := newConfig(t, link)
		other := &Config{stateDir: cfg.stateDir, TemplateVersion: "v2.0.0"}
		other.setTemplatesDir(templatesDir)
		if err := other.WriteTemplatesConfig(); err != nil {
			t.Fatalf("write templates state: %v", err)
		}

		if err := cfg.ReloadTemplateVersion(); err != nil {
			t.Fatalf("reload templates version: %v", err)
		}
		if cfg.TemplateVersion != "v2.0.0" {
			t.Fatalf("template version = %q, want v2.0.0", cfg.TemplateVersion)
		}

		cfg.TemplateVersion = "v1.0.0"
		cfg.setTemplatesDir(templatesDir)
		writer := &Config{stateDir: cfg.stateDir, TemplateVersion: "v3.0.0"}
		writer.setTemplatesDir(link)
		if err := writer.WriteTemplatesConfig(); err != nil {
			t.Fatalf("write templates state through the link: %v", err)
		}
		if err := cfg.ReloadTemplateVersion(); err != nil {
			t.Fatalf("reload templates version: %v", err)
		}
		if cfg.TemplateVersion != "v3.0.0" {
			t.Fatalf("template version = %q, want v3.0.0", cfg.TemplateVersion)
		}
	})
}

package config

import (
	"encoding/csv"
	"io"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/templates/extensions"
	filepathutil "github.com/projectdiscovery/nuclei/v3/pkg/utils/filepath"
	fileutil "github.com/projectdiscovery/utils/file"
	stringsutil "github.com/projectdiscovery/utils/strings"
)

var (
	knownConfigFiles     = []string{"cves.json", "contributors.json", "TEMPLATES-STATS.json"}
	knownMiscDirectories = []string{".git", ".github", "helpers"}
)

// TemplateFormat
type TemplateFormat uint8

const (
	YAML TemplateFormat = iota
	JSON
	Unknown
)

// GetKnownConfigFiles returns known config files.
func GetKnownConfigFiles() []string {
	return knownConfigFiles
}

// IsKnownConfigFile returns true if the base name of fpath is exactly one of
// the known config files. Names that only contain one of them, such as
// "cves.json.yaml", are not considered config files.
func IsKnownConfigFile(fpath string) bool {
	return slices.Contains(knownConfigFiles, filepath.Base(filepath.FromSlash(fpath)))
}

// GetKnownMiscDirectories returns known misc directories with trailing slashes.
//
// The trailing slash ensures that directory matching is explicit and avoids
// falsely match files with similar names (e.g. "helpers" matching
// "some-helpers.yaml"), since [IsTemplate] checks against normalized full paths.
func GetKnownMiscDirectories() []string {
	trailedSlashDirs := make([]string, 0, len(knownMiscDirectories))
	for _, dir := range knownMiscDirectories {
		trailedSlashDirs = append(trailedSlashDirs, dir+string(os.PathSeparator))
	}

	return trailedSlashDirs
}

// GetTemplateFormatFromExt returns template format
func GetTemplateFormatFromExt(filePath string) TemplateFormat {
	fileExt := strings.ToLower(filepath.Ext(filePath))
	switch fileExt {
	case extensions.JSON:
		return JSON
	case extensions.YAML:
		return YAML
	default:
		return Unknown
	}
}

// GetSupportTemplateFileExtensions returns all supported template file extensions
func GetSupportTemplateFileExtensions() []string {
	return []string{extensions.YAML, extensions.JSON}
}

// IsTemplate returns true if the file is a template based on its path.
// It used by goflags and other places to filter out non-template files.
func IsTemplate(fpath string) bool {
	return IsTemplateWithRoot(fpath, "")
}

// IsTemplateWithRoot returns true if the file is a template based on its path
// and root directory. If rootDir is provided, it checks for excluded
// directories relative to the root.
func IsTemplateWithRoot(fpath, rootDir string) bool {
	fpath = filepath.FromSlash(fpath)
	fname := filepath.Base(fpath)
	fext := strings.ToLower(filepath.Ext(fpath))

	if IsKnownConfigFile(fname) {
		return false
	}

	var pathToCheck string
	if rootDir != "" {
		if filepath.IsAbs(fpath) {
			rel, err := filepath.Rel(rootDir, fpath)
			if err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
				pathToCheck = rel
			} else {
				pathToCheck = fpath
			}
		} else {
			pathToCheck = fpath
		}
	} else {
		pathToCheck = fpath
	}

	// Only check components if pathToCheck is NOT absolute
	// This avoids false positives on parent directories for absolute paths
	if !filepath.IsAbs(pathToCheck) {
		for p := range strings.SplitSeq(pathToCheck, string(os.PathSeparator)) {
			for _, excluded := range knownMiscDirectories {
				if strings.EqualFold(p, excluded) {
					return false
				}
			}
		}
	}

	return stringsutil.EqualFoldAny(fext, GetSupportTemplateFileExtensions()...)
}

type template struct {
	ID string `json:"id" yaml:"id"`
}

// GetTemplateIDFromReader returns template id from reader
func GetTemplateIDFromReader(data io.Reader, filename string) (string, error) {
	var t template
	var err error
	switch GetTemplateFormatFromExt(filename) {
	case YAML:
		err = fileutil.UnmarshalFromReader(fileutil.YAML, data, &t)
	case JSON:
		err = fileutil.UnmarshalFromReader(fileutil.JSON, data, &t)
	}
	return t.ID, err
}

func getTemplateID(filePath string) (string, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return "", err
	}

	defer func() {
		_ = file.Close()
	}()
	return GetTemplateIDFromReader(file, filePath)
}

// GetTemplatesIndexFile returns map[template-id]: template-file-path
func GetNucleiTemplatesIndex() (map[string]string, error) {
	indexFile := DefaultConfig.GetTemplateIndexFilePath()
	index := map[string]string{}
	if fileutil.FileExists(indexFile) {
		f, err := os.Open(indexFile)
		if err == nil {
			csvReader := csv.NewReader(f)
			records, err := csvReader.ReadAll()
			if err == nil {
				for _, v := range records {
					if len(v) >= 2 {
						templateID := v[0]
						templatePath := v[1]
						// Normalize path for consistent comparison (handles Windows path issues)
						normalizedPath := filepath.Clean(templatePath)
						// Validate that the file actually exists (prevents stale entries from deleted files on Windows)
						if fileutil.FileExists(normalizedPath) {
							index[templateID] = normalizedPath
						}
					}
				}
				// Close file handle before returning
				_ = f.Close()
				return index, nil
			}
			_ = f.Close()
		}
		DefaultConfig.Logger.Error().Msgf("failed to read index file creating new one: %v", err)
	}

	ignoreDirs := DefaultConfig.GetAllCustomTemplateDirs()

	// empty index if templates are not installed
	if !fileutil.FolderExists(DefaultConfig.TemplatesDirectory) {
		return index, nil
	}
	err := filepath.WalkDir(DefaultConfig.TemplatesDirectory, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			DefaultConfig.Logger.Verbose().Msgf("failed to walk path=%v err=%v", path, err)
			return nil
		}
		if d.IsDir() || !IsTemplateWithRoot(path, DefaultConfig.TemplatesDirectory) || filepathutil.IsPathWithinAnyDirectory(path, ignoreDirs...) {
			return nil
		}
		// Normalize path for consistent comparison (handles Windows path issues)
		normalizedPath := filepath.Clean(path)
		// get template id from file
		id, err := getTemplateID(normalizedPath)
		if err != nil || id == "" {
			DefaultConfig.Logger.Verbose().Msgf("failed to get template id from file=%v got id=%v err=%v", normalizedPath, id, err)
			return nil
		}
		index[id] = normalizedPath
		return nil
	})
	return index, err
}

package config

import (
	"os"
	"path/filepath"
	"testing"

	osutils "github.com/projectdiscovery/utils/os"
	"github.com/stretchr/testify/require"
)

// toAbs converts a slash separated absolute path into an OS specific absolute
// path, prefixing it with the system volume on Windows.
func toAbs(p string) string {
	if osutils.IsWindows() {
		// Infer the drive letter from the Windows system path
		// SystemRoot or WINDIR typically points to something like "C:\Windows"
		systemRoot := os.Getenv("SystemRoot")
		if systemRoot == "" {
			systemRoot = os.Getenv("WINDIR")
		}
		// Extract volume name (e.g., "C:") from the system path
		volumeName := filepath.VolumeName(systemRoot)
		if volumeName == "" {
			// Fallback to C: if we can't determine the volume
			volumeName = "C:"
		}
		return filepath.FromSlash(volumeName + p)
	}
	return filepath.FromSlash(p)
}

// TestIsTemplate checks template detection for supported extensions, excluded
// directories and known config files.
func TestIsTemplate(t *testing.T) {
	tests := []struct {
		name    string
		fpath   string
		rootDir string
		want    bool
	}{
		{
			name:    "valid template",
			fpath:   "dns/cname.yaml",
			rootDir: "",
			want:    true,
		},
		{
			name:    "excluded directory relative",
			fpath:   "helpers/data.txt",
			rootDir: "",
			want:    false,
		},
		{
			name:    "excluded directory .git",
			fpath:   ".git/config",
			rootDir: "",
			want:    false,
		},
		{
			name:    "absolute path with excluded parent dir (bug fix)",
			fpath:   toAbs("/path/to/somewhere/that/has/helpers/dir/nuclei/nuclei-templates/dns/cname.yaml"),
			rootDir: toAbs("/path/to/somewhere/that/has/helpers/dir/nuclei/nuclei-templates"),
			want:    true,
		},
		{
			name:    "absolute path with excluded dir inside root",
			fpath:   toAbs("/path/to/somewhere/that/has/helpers/dir/nuclei/nuclei-templates/helpers/data.txt"),
			rootDir: toAbs("/path/to/somewhere/that/has/helpers/dir/nuclei/nuclei-templates"),
			want:    false,
		},
		{
			name:    "absolute path without root (skip check)",
			fpath:   toAbs("/opt/helpers/foo.yaml"),
			rootDir: "",
			want:    true,
		},
		{
			name:    "valid template with different extension",
			fpath:   "dns/cname.json",
			rootDir: "",
			want:    true,
		},
		{
			name:    "invalid extension",
			fpath:   "dns/cname.txt",
			rootDir: "",
			want:    false,
		},
		{
			name:    "excluded config file",
			fpath:   "cves.json",
			rootDir: "",
			want:    false,
		},
		{
			name:    "excluded config file in subdirectory",
			fpath:   "nuclei-templates/TEMPLATES-STATS.json",
			rootDir: "",
			want:    false,
		},
		{
			name:    "template name containing config file name",
			fpath:   "http/cves.json.yaml",
			rootDir: "",
			want:    true,
		},
		{
			name:    "json template name containing config file name",
			fpath:   "http/contributors.json.json",
			rootDir: "",
			want:    true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := IsTemplateWithRoot(tt.fpath, tt.rootDir)
			require.Equal(t, tt.want, got, "IsTemplateWithRoot(%q, %q)", tt.fpath, tt.rootDir)
		})
	}
}

// TestIsKnownConfigFile ensures only exact config file base names match, and
// names that merely contain one (e.g. cves.json.yaml) do not.
func TestIsKnownConfigFile(t *testing.T) {
	for _, fpath := range []string{
		"cves.json",
		"contributors.json",
		"TEMPLATES-STATS.json",
		toAbs("/home/user/nuclei-templates/cves.json"),
		"https://example.com/nuclei-templates/cves.json",
	} {
		require.True(t, IsKnownConfigFile(fpath), "IsKnownConfigFile(%q)", fpath)
	}

	for _, fpath := range []string{
		"cves.json.yaml",
		"http/cves.json.yaml",
		"my-contributors.json",
		toAbs("/home/user/cves.json/test.yaml"),
	} {
		require.False(t, IsKnownConfigFile(fpath), "IsKnownConfigFile(%q)", fpath)
	}
}

func TestGetNucleiTemplatesIndexIncludesCustomDirSiblingPrefix(t *testing.T) {
	tmpDir := t.TempDir()
	cfgDir := t.TempDir()

	oldConfigDir := DefaultConfig.GetConfigDir()
	oldTemplatesDir := DefaultConfig.TemplatesDirectory
	DefaultConfig.SetConfigDir(cfgDir)
