	customGitHubDir := filepath.Join(tmpDir, "github")
	require.NoError(t, os.MkdirAll(customGitHubDir, 0755))
	require.NoError(t, os.WriteFile(filepath.Join(customGitHubDir, "custom-template.yaml"), []byte(`id: custom-template
info:
  name: Custom Template
  author: test
  severity: info`), 0644))

	siblingDir := filepath.Join(tmpDir, "github-evil")
	require.NoError(t, os.MkdirAll(siblingDir, 0755))
	require.NoError(t, os.WriteFile(filepath.Join(siblingDir, "sibling-template.yaml"), []byte(`id: sibling-template
info:
  name: Sibling Template
  author: test
  severity: info`), 0644))

	index, err := GetNucleiTemplatesIndex()
	require.NoError(t, err)
	require.NotContains(t, index, "custom-template", "custom template directory should be excluded")
	require.Contains(t, index, "sibling-template", "custom directory sibling prefix should be indexed")
}

package config

import (
	"os"
	"path/filepath"
	"strings"
)

// CanonicalTemplatesPath is the identity of a templates directory. A symlink
// and its target are the same directory, including while the target does not
// exist yet, so a lock and a reloaded version follow either name.
func CanonicalTemplatesPath(path string) string {
	if strings.TrimSpace(path) == "" {
		return ""
	}
	return resolveTemplatesPath(path, map[string]struct{}{})
}

func resolveTemplatesPath(path string, seen map[string]struct{}) string {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = filepath.Clean(path)
	}
	if _, ok := seen[abs]; ok {
		return abs
	}
	seen[abs] = struct{}{}

	dir := abs
	var missing []string
	for {
		info, err := os.Lstat(dir)
		if err == nil {
			if info.Mode()&os.ModeSymlink != 0 {
				if resolved, err := filepath.EvalSymlinks(dir); err == nil {
					return filepath.Join(append([]string{resolved}, missing...)...)
				}
				target, readErr := os.Readlink(dir)
				if readErr != nil {
					return filepath.Join(append([]string{dir}, missing...)...)
				}
				if !filepath.IsAbs(target) {
					target = filepath.Join(filepath.Dir(dir), target)
				}
				resolvedTarget := resolveTemplatesPath(target, seen)
				return filepath.Join(append([]string{resolvedTarget}, missing...)...)
			}
			resolved := dir
			if r, err := filepath.EvalSymlinks(dir); err == nil {
				resolved = r
			}
			return filepath.Join(append([]string{resolved}, missing...)...)
		}

		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Join(append([]string{dir}, missing...)...)
		}
		missing = append([]string{filepath.Base(dir)}, missing...)
		dir = parent
	}
}

package disk

import (
	"io"
	"io/fs"
	"os"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
)

// DiskCatalog is a template catalog helper implementation based on disk
type DiskCatalog struct {
	templatesDirectory string
	templatesFS        fs.FS // Due to issues with how Go has implemented fs.FS, we'll have to also implement normal os operations, as well.  See: https://github.com/golang/go/issues/44279
}

// NewCatalog creates a new Catalog structure using provided input items
// using disk based items
func NewCatalog(directory string) *DiskCatalog {
	catalog := &DiskCatalog{templatesDirectory: directory}
	if directory == "" {
		catalog.templatesDirectory = config.DefaultConfig.GetTemplateDir()
	}
	return catalog
}

// NewFSCatalog creates a new Catalog structure using provided input items
// using the fs.FS as its filesystem.
func NewFSCatalog(fs fs.FS, directory string) *DiskCatalog {
	catalog := &DiskCatalog{
		templatesDirectory: directory,
		templatesFS:        fs,
	}
	return catalog
}

// OpenFile opens a file and returns an io.ReadCloser to the file.
// It is used to read template and payload files based on catalog responses.
func (d *DiskCatalog) OpenFile(filename string) (io.ReadCloser, error) {
	if d.templatesFS == nil {
		return os.Open(filename)
	}

	return d.templatesFS.Open(filename)
}

