package disk

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/logrusorgru/aurora/v4"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	filepathutil "github.com/projectdiscovery/nuclei/v3/pkg/utils/filepath"
	stringsutil "github.com/projectdiscovery/utils/strings"
	updateutils "github.com/projectdiscovery/utils/update"
	urlutil "github.com/projectdiscovery/utils/url"
)

var deprecatedPathsCounter int

// GetTemplatesPath returns a list of absolute paths for the provided template list.
func (c *DiskCatalog) GetTemplatesPath(definitions []string) ([]string, map[string]error) {
	// keeps track of processed dirs and files
	processed := make(map[string]bool)
	allTemplates := []string{}
	erred := make(map[string]error)

	for _, t := range definitions {
		if config.IsKnownConfigFile(t) {
			continue
		}
		if strings.Contains(t, urlutil.SchemeSeparator) && stringsutil.ContainsAny(t, config.GetSupportTemplateFileExtensions()...) {
			if _, ok := processed[t]; !ok {
				processed[t] = true
				allTemplates = append(allTemplates, t)
			}
		} else {
			paths, err := c.GetTemplatePath(t)
			if err != nil {
				erred[t] = err
			}
			for _, path := range paths {
				if _, ok := processed[path]; !ok {
					processed[path] = true
					allTemplates = append(allTemplates, path)
				}
			}
		}
	}
	// purge all false positives
	filteredTemplates := []string{}
	for _, v := range allTemplates {
		if !config.IsKnownConfigFile(v) {
			filteredTemplates = append(filteredTemplates, v)
		}
	}

	return filteredTemplates, erred
}

// GetTemplatePath parses the specified input template path and returns a compiled
// list of finished absolute paths to the templates evaluating any glob patterns
// or folders provided as in.
func (c *DiskCatalog) GetTemplatePath(target string) ([]string, error) {
	processed := make(map[string]struct{})

	if c.templatesFS == nil {
		var err error
		target, err = c.convertPathToAbsolute(target)
		if err != nil {
			return nil, errors.Wrapf(err, "could not find template file")
		}
	}

	if strings.Contains(target, "*") {
		globMatches, err := c.findGlobPathMatches(target, processed)
		if err != nil {
			return nil, errors.Wrap(err, "could not globbing path")
		}

		if len(globMatches) > 0 {
			return globMatches, nil
		} else {
			return globMatches, fmt.Errorf("%w in path %q", ErrNoTemplatesFound, target)
		}
	}

	// `target` is either a file or a directory
	match, file, err := c.findFileMatches(target, processed)
	if err != nil {
		return nil, errors.Wrap(err, "could not find file")
	}

	if file {
		if match != "" {
			return []string{match}, nil
		}
		return nil, nil
	}

	// Recursively walk down the Templates directory and run all
	// the template file checks
	matches, err := c.findDirectoryMatches(target, processed)
	if err != nil {
		return nil, errors.Wrap(err, "could not find directory matches")
	}

	if len(matches) == 0 {
		return nil, fmt.Errorf("%w in path %q", ErrNoTemplatesFound, target)
	}

	return matches, nil
}

// convertPathToAbsolute resolves the paths provided to absolute paths
// before doing any operations on them regardless of them being BLOB, folders, files, etc.
func (c *DiskCatalog) convertPathToAbsolute(t string) (string, error) {
	if strings.Contains(t, "*") {
		file := filepath.Base(t)
		absPath, err := c.ResolvePath(filepath.Dir(t), "")
		if err != nil {
			return "", err
		}
		return filepath.Join(absPath, file), nil
	}
	return c.ResolvePath(t, "")
}

// findGlobPathMatches returns the matched files from a glob path
func (c *DiskCatalog) findGlobPathMatches(absPath string, processed map[string]struct{}) ([]string, error) {
	var err error
	var matches []string

	if c.templatesFS != nil {
		// Compute the path relative to the templates directory using
		// canonical containment instead of a lexical TrimPrefix. The previous
		// strings.TrimPrefix(absPath, c.templatesDirectory) would, for a
		// templatesDirectory like "/foo" and an absPath like
		// "/foo-evil/x*.yaml", silently truncate to "-evil/x*.yaml" — a
		// sibling-prefix bug equivalent to the one fixed across the rest of
		// the codebase. With canonical containment the sibling-prefix case
		// no longer aliases into the embedded FS root.
		relPath := absPath
		if c.templatesDirectory != "" && filepathutil.IsPathWithinDirectory(absPath, c.templatesDirectory) {
			if rel, relErr := filepath.Rel(c.templatesDirectory, absPath); relErr == nil && rel != "." {
				relPath = rel
			}
		}
		// fs.FS always uses forward slashes.
		relPath = filepath.ToSlash(relPath)
		relPath = strings.TrimPrefix(relPath, "/")
		matches, err = fs.Glob(c.templatesFS, relPath)
	} else {
		matches, err = filepath.Glob(absPath)
	}

	if err != nil {
		return nil, err
	}

	results := make([]string, 0, len(matches))
	for _, match := range matches {
		if _, ok := processed[match]; !ok {
			processed[match] = struct{}{}
			results = append(results, match)
		}
	}

	return results, nil
}

// findFileMatches finds if a path is an absolute file. If the path
// is a file, it returns true otherwise false with no errors.
func (c *DiskCatalog) findFileMatches(absPath string, processed map[string]struct{}) (match string, matched bool, err error) {
	if c.templatesFS != nil {
		absPath = strings.Trim(absPath, "/")
	}
	var info fs.File
	if c.templatesFS == nil {
		info, err = os.Open(absPath)
	} else {
		// If we were given no path, then it's not a file, it's the root, and we can quietly return.
		if absPath == "" {
			return "", false, nil
		}

		info, err = c.templatesFS.Open(absPath)
	}
	if err != nil {
		return "", false, err
	}
	defer func() {
		_ = info.Close()
	}()
	stat, err := info.Stat()
	if err != nil {
		return "", false, err
	}
	if !stat.Mode().IsRegular() {
		return "", false, nil
	}
	if _, ok := processed[absPath]; !ok {
		processed[absPath] = struct{}{}
		return absPath, true, nil
	}
	return "", true, nil
}

// findDirectoryMatches finds matches for templates from a directory
func (c *DiskCatalog) findDirectoryMatches(absPath string, processed map[string]struct{}) ([]string, error) {
	var results []string
	var err error
	if c.templatesFS == nil {
		err = filepath.WalkDir(
			absPath,
			func(path string, d fs.DirEntry, err error) error {
				// continue on errors
				if err != nil {
					return nil
				}
				if !d.IsDir() && config.IsTemplateWithRoot(path, absPath) {
					if _, ok := processed[path]; !ok {
						results = append(results, path)
						processed[path] = struct{}{}
					}
				}
				return nil
			},
		)
	} else {
		// For the special case of the root directory, we need to pass "." to `fs.WalkDir`.
		if absPath == "" {
			absPath = "."
		}
		absPath = strings.TrimSuffix(absPath, "/")

		err = fs.WalkDir(
			c.templatesFS,
			absPath,
			func(path string, d fs.DirEntry, err error) error {
				// continue on errors
				if err != nil {
					return nil
				}
				if !d.IsDir() && config.IsTemplateWithRoot(path, absPath) {
					if _, ok := processed[path]; !ok {
						results = append(results, path)
						processed[path] = struct{}{}
					}
				}
				return nil
			},
		)
	}
	return results, err
}

// PrintDeprecatedPathsMsgIfApplicable prints a warning message if any
// deprecated paths are found. Unless mode is silent warning message is printed.
//
// Deprecated: No longer used since the official Nuclei Templates repository
// have restructured this a long time ago.
func PrintDeprecatedPathsMsgIfApplicable(isSilent bool) {
	if !updateutils.IsOutdated("v9.4.3", config.DefaultConfig.TemplateVersion) {
		return
	}
	if deprecatedPathsCounter > 0 && !isSilent {
		config.DefaultConfig.Logger.Print().Msgf("[%v] Found %v template[s] loaded with deprecated paths, update before v3 for continued support.\n", aurora.Yellow("WRN").String(), deprecatedPathsCounter)
	}
}

package disk

import (
	"os"
	"path/filepath"
	"testing"
	"testing/fstest"

	"github.com/stretchr/testify/require"
)

// TestFindGlobPathMatchesUsesCanonicalContainment ensures that when an
// absPath shares a lexical prefix with templatesDirectory but is not actually
// inside it (a sibling-prefix path), the embedded-FS lookup does NOT silently
// strip part of the prefix and resolve into the templates root.
func TestFindGlobPathMatchesUsesCanonicalContainment(t *testing.T) {
	// Build a small in-memory FS that simulates an embedded templates tree
	// and a sibling tree. fs.Glob is rooted at the FS root, so the test
	// asserts that with the buggy prefix-trim a sibling-prefix glob would
	// match the in-bounds entry; with the fix it does not.
	memFS := fstest.MapFS{
		"http/test.yaml":      {Data: []byte("legit")},
		"http-evil/test.yaml": {Data: []byte("sibling")},
	}

	templatesDir := filepath.Join(t.TempDir(), "templates")

	cat := NewFSCatalog(memFS, templatesDir)

	// Glob for siblings of templatesDir (the previous TrimPrefix would have
	// silently aliased "/.../templates-evil/*.yaml" into "-evil/*.yaml" and
	// then collapsed to a glob with no leading separator that ran against
	// memFS root — observable as confused matches in production code paths
	// that rely on this method).
	sibling := templatesDir + "-evil"
	matches, err := cat.findGlobPathMatches(filepath.Join(sibling, "*.yaml"), map[string]struct{}{})
	require.NoError(t, err)
	// Whatever the glob produces, it must NOT include the in-bounds
	// http/test.yaml from inside the templates directory.
	for _, m := range matches {
		require.NotContains(t, m, "http/test.yaml",
			"sibling-prefix glob must not alias into the templates root")
	}
}

// TestFindGlobPathMatchesResolvesContainedPath ensures a glob inside the
// templates directory resolves against the embedded FS.
func TestFindGlobPathMatchesResolvesContainedPath(t *testing.T) {
	memFS := fstest.MapFS{
		"http/test.yaml": {Data: []byte("legit")},
	}

	templatesDir := filepath.Join(t.TempDir(), "templates")
	cat := NewFSCatalog(memFS, templatesDir)

	// A glob that lives inside templatesDir resolves correctly via the
	// canonical relative path (no surprises from the rewrite).
	matches, err := cat.findGlobPathMatches(filepath.Join(templatesDir, "http", "*.yaml"), map[string]struct{}{})
	require.NoError(t, err)
	require.Equal(t, []string{"http/test.yaml"}, matches)
}

// TestGetTemplatesPathKnownConfigFiles ensures that only exact known config
// file names are skipped, and templates whose names merely contain one (e.g.
// cves.json.yaml) are still loaded.
func TestGetTemplatesPathKnownConfigFiles(t *testing.T) {
	templatesDir := t.TempDir()
	httpDir := filepath.Join(templatesDir, "http")
	require.NoError(t, os.MkdirAll(httpDir, 0755))

	template := filepath.Join(httpDir, "cves.json.yaml")
	for _, f := range []string{
		template,
		filepath.Join(templatesDir, "cves.json"),
		filepath.Join(templatesDir, "contributors.json"),
		filepath.Join(templatesDir, "TEMPLATES-STATS.json"),
	} {
		require.NoError(t, os.WriteFile(f, []byte("id: test"), 0644))
	}

	cat := NewCatalog(templatesDir)

	t.Run("direct path", func(t *testing.T) {
		paths, errs := cat.GetTemplatesPath([]string{template})
		require.Empty(t, errs)
		require.Equal(t, []string{template}, paths)
	})

	t.Run("directory traversal", func(t *testing.T) {
		paths, errs := cat.GetTemplatesPath([]string{templatesDir})
		require.Empty(t, errs)
		require.Equal(t, []string{template}, paths)
	})

	t.Run("config file is skipped", func(t *testing.T) {
		paths, errs := cat.GetTemplatesPath([]string{filepath.Join(templatesDir, "cves.json")})
		require.Empty(t, errs)
		require.Empty(t, paths)
	})
}

package disk

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	fileutil "github.com/projectdiscovery/utils/file"
)

// ResolvePath resolves the path to an absolute one in various ways.
//
// It checks if the filename is an absolute path, looks in the current directory
// or checking the nuclei templates directory. If a second path is given,
// it also tries to find paths relative to that second path.
func (c *DiskCatalog) ResolvePath(templateName, second string) (string, error) {
	if filepath.IsAbs(templateName) {
		return templateName, nil
	}
	if c.templatesFS != nil {
		if potentialPath, err := c.tryResolve(templateName); err != errNoValidCombination {
			return potentialPath, nil
		}
	}
	if second != "" {
		secondBasePath := filepath.Join(filepath.Dir(second), templateName)
		if potentialPath, err := c.tryResolve(secondBasePath); err != errNoValidCombination {
			return potentialPath, nil
		}
	}

	if c.templatesFS == nil {
		curDirectory, err := os.Getwd()
		if err != nil {
			return "", err
		}

		templatePath := filepath.Join(curDirectory, templateName)
		if potentialPath, err := c.tryResolve(templatePath); err != errNoValidCombination {
			return potentialPath, nil
		}
	}

	templatePath := filepath.Join(config.DefaultConfig.GetTemplateDir(), templateName)
	if potentialPath, err := c.tryResolve(templatePath); err != errNoValidCombination {
		return potentialPath, nil
	}

	return "", fmt.Errorf("no such path found: %s", templateName)
}

var errNoValidCombination = errors.New("no valid combination found")

// tryResolve attempts to load locate the target by iterating across all the folders tree
func (c *DiskCatalog) tryResolve(fullPath string) (string, error) {
	if c.templatesFS == nil {
		if fileutil.FileOrFolderExists(fullPath) {
			return fullPath, nil
		}
	} else {
		if _, err := fs.Stat(c.templatesFS, fullPath); err == nil {
			return fullPath, nil
		}
	}
	return "", errNoValidCombination
}

package index

import (
	"path/filepath"
	"slices"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
)

// Filter represents filtering criteria for template metadata.
//
// Inclusion fields (e.g., Authors, Tags, IDs, Severities, ProtocolTypes) use
// AND logic across different filter types and OR logic within each type.
// Exclusion fields (e.g., ExcludeTags, ExcludeIDs, ExcludeSeverities,
// ExcludeProtocolTypes) take precedence over normal inclusion fields.
// IncludeTags can force inclusion only for the same excluded tag; other
// exclusion criteria and unrelated excluded tags still apply. IncludeTemplates
// remains an explicit template override.
type Filter struct {
	// once ensures that IDs and ExcludedIDs are compiled the first time Matches is called.
	once sync.Once

	// Authors to include.
	Authors []string

	// Tags to include.
	Tags []string

	// ExcludeTags to exclude (takes precedence over Tags).
	ExcludeTags []string

	// IncludeTags to force include matching tag exclusions.
	IncludeTags []string

	// IDs to include (supports wildcards).
	IDs []string

	// includeIDs is a map of IDs for a quick lookup.
	includeIDs map[string]struct{}

	// includeIDPatterns are the patterns extracted from IDs.
	includeIDPatterns []string

	// ExcludeIDs to exclude (supports wildcards).
	ExcludeIDs []string

	// excludeIDs is a map of ExcludeIDs for a quick lookup.
	excludeIDs map[string]struct{}

	// excludeIDPatterns are the patterns extracted from ExcludeIDs.
	excludeIDPatterns []string

	// IncludeTemplates paths to force include even if excluded.
	IncludeTemplates []string

	// ExcludeTemplates paths to exclude.
	ExcludeTemplates []string

	// Severities to include.
	Severities []severity.Severity

	// ExcludeSeverities to exclude.
	ExcludeSeverities []severity.Severity

	// ProtocolTypes to include.
	ProtocolTypes []types.ProtocolType

	// ExcludeProtocolTypes to exclude.
	ExcludeProtocolTypes []types.ProtocolType
}

// Matches checks if metadata matches the filter criteria.
func (f *Filter) Matches(m *Metadata) bool {
	f.once.Do(f.Compile)

	if f.matchesIncludeTemplate(m) {
		return true
	}

	if f.isExcluded(m) {
		return false
	}

	if !f.matchesIncludes(m) {
		return false
	}

	return true
}

// matchesIncludeTemplate checks if template is explicitly included by path.
func (f *Filter) matchesIncludeTemplate(m *Metadata) bool {
	if len(f.IncludeTemplates) > 0 {
		for _, includePath := range f.IncludeTemplates {
			if matchesPath(m.FilePath, includePath) {
				return true
			}
		}
	}

	return false
}

// isExcluded checks if template should be excluded.
func (f *Filter) isExcluded(m *Metadata) bool {
	if len(f.ExcludeTemplates) > 0 {
		for _, excludePath := range f.ExcludeTemplates {
			if matchesPath(m.FilePath, excludePath) {
				return true
			}
		}
	}

	if len(f.ExcludeTags) > 0 {
		for _, excludeTag := range f.ExcludeTags {
			if m.HasTag(excludeTag) && !slices.Contains(f.IncludeTags, excludeTag) {
				return true
			}
		}
	}

	if len(f.ExcludeIDs) > 0 {
		if f.matchesExcludeID(m.ID) {
			return true
		}
	}

	if len(f.ExcludeSeverities) > 0 {
		if slices.ContainsFunc(f.ExcludeSeverities, m.MatchesSeverity) {
			return true
		}
	}

	if len(f.ExcludeProtocolTypes) > 0 {
		if slices.ContainsFunc(f.ExcludeProtocolTypes, m.MatchesProtocol) {
			return true
		}
	}

	return false
}

// matchesIncludes checks if metadata matches include filters.
//
// Returns true if no include filters are specified, or if all specified filter
// types match.
func (f *Filter) matchesIncludes(m *Metadata) bool {
	if len(f.Authors) > 0 {
		if !slices.ContainsFunc(f.Authors, m.HasAuthor) {
			return false
		}
	}

	if len(f.Tags) > 0 {
		if !slices.ContainsFunc(f.Tags, m.HasTag) {
			return false
		}
	}

	if len(f.IDs) > 0 {
		if !f.matchesIncludeID(m.ID) {
			return false
		}
	}

	if len(f.Severities) > 0 {
		if !slices.ContainsFunc(f.Severities, m.MatchesSeverity) {
			return false
		}
	}

	if len(f.ProtocolTypes) > 0 {
		if !slices.ContainsFunc(f.ProtocolTypes, m.MatchesProtocol) {
			return false
		}
	}

	return true
}

// Compile pre-processes IDs and ExcludeIDs into fast lookup structures.
// The first time Matches is called, this is called automatically.
// If IDs or ExcludeIDs are modified after calling Matches, this must be called manually.
// This method is not thread-safe, so make sure noone is using the filter when calling it.
func (f *Filter) Compile() {
	f.includeIDPatterns = nil
	f.includeIDs = make(map[string]struct{}, len(f.IDs))
	for _, p := range f.IDs {
		idOrPattern := strings.ToLower(p)
		if strings.ContainsAny(idOrPattern, "*?[") {
			f.includeIDPatterns = append(f.includeIDPatterns, idOrPattern)
		} else {
			f.includeIDs[idOrPattern] = struct{}{}
		}
	}

	f.excludeIDPatterns = nil
	f.excludeIDs = make(map[string]struct{}, len(f.ExcludeIDs))
	for _, p := range f.ExcludeIDs {
		idOrPattern := strings.ToLower(p)
		if strings.ContainsAny(idOrPattern, "*?[") {
			f.excludeIDPatterns = append(f.excludeIDPatterns, idOrPattern)
		} else {
			f.excludeIDs[idOrPattern] = struct{}{}
		}
	}
}

// matchesIncludeID reports whether templateID matches any entry in includeIDs or includeIDPatterns.
func (f *Filter) matchesIncludeID(templateID string) bool {
	templateID = strings.ToLower(templateID)
	if _, ok := f.includeIDs[templateID]; ok {
		return true
	}

	for _, pattern := range f.includeIDPatterns {
		if matched, _ := filepath.Match(pattern, templateID); matched {
			return true
		}
	}

	return false
}

// matchesExcludeID reports whether templateID matches any entry in excludeIDs or excludeIDPatterns.
func (f *Filter) matchesExcludeID(templateID string) bool {
	templateID = strings.ToLower(templateID)
	if _, ok := f.excludeIDs[templateID]; ok {
		return true
	}

	for _, pattern := range f.excludeIDPatterns {
		if matched, _ := filepath.Match(pattern, templateID); matched {
			return true
		}
	}

	return false
}

// matchesPath checks if template path matches pattern.
func matchesPath(templatePath, pattern string) bool {
	templatePath = filepath.Clean(templatePath)
	pattern = filepath.Clean(pattern)

	if templatePath == pattern {
		return true
	}

	if strings.HasPrefix(templatePath, pattern+string(filepath.Separator)) {
		return true
	}

	matched, _ := filepath.Match(pattern, templatePath)

	return matched
}

// FilterFunc is a function that filters metadata.
type FilterFunc func(*Metadata) bool

// UnmarshalFilter creates a Filter from nuclei options.
func UnmarshalFilter(
	authors, tags, excludeTags, includeTags []string,
	ids, excludeIDs []string,
	includeTemplates, excludeTemplates []string,
	severities, excludeSeverities []string,
	protocolTypes, excludeProtocolTypes []string,
) (*Filter, error) {
	filter := &Filter{
		Authors:          authors,
		Tags:             tags,
		ExcludeTags:      excludeTags,
		IncludeTags:      includeTags,
		IDs:              ids,
		ExcludeIDs:       excludeIDs,
		IncludeTemplates: includeTemplates,
		ExcludeTemplates: excludeTemplates,
	}

	for _, sev := range severities {
		holder := &severity.Holder{}
		if err := holder.UnmarshalYAML(func(v interface{}) error {
			*v.(*string) = sev
			return nil
		}); err == nil {
			filter.Severities = append(filter.Severities, holder.Severity)
		}
	}

	for _, sev := range excludeSeverities {
		holder := &severity.Holder{}
		if err := holder.UnmarshalYAML(func(v interface{}) error {
			*v.(*string) = sev
			return nil
		}); err == nil {
			filter.ExcludeSeverities = append(filter.ExcludeSeverities, holder.Severity)
		}
	}

	for _, pt := range protocolTypes {
		holder := &types.TypeHolder{}
		if err := holder.UnmarshalYAML(func(v interface{}) error {
			*v.(*string) = pt
			return nil
		}); err == nil && holder.ProtocolType != types.InvalidProtocol {
			filter.ProtocolTypes = append(filter.ProtocolTypes, holder.ProtocolType)
		}
	}

	for _, pt := range excludeProtocolTypes {
		holder := &types.TypeHolder{}
		if err := holder.UnmarshalYAML(func(v interface{}) error {
			*v.(*string) = pt
			return nil
		}); err == nil && holder.ProtocolType != types.InvalidProtocol {
			filter.ExcludeProtocolTypes = append(filter.ExcludeProtocolTypes, holder.ProtocolType)
		}
	}

	return filter, nil
}

// UnmarshalFilterFunc creates a FilterFunc from filter criteria.
func UnmarshalFilterFunc(filter *Filter) FilterFunc {
	if filter == nil {
		return func(*Metadata) bool { return true }
	}

	return filter.Matches
}

// IsEmpty returns true if filter has no criteria set.
func (f *Filter) IsEmpty() bool {
	return len(f.Authors) == 0 &&
		len(f.Tags) == 0 &&
		len(f.ExcludeTags) == 0 &&
		len(f.IncludeTags) == 0 &&
		len(f.IDs) == 0 &&
		len(f.ExcludeIDs) == 0 &&
		len(f.IncludeTemplates) == 0 &&
		len(f.ExcludeTemplates) == 0 &&
		len(f.Severities) == 0 &&
		len(f.ExcludeSeverities) == 0 &&
		len(f.ProtocolTypes) == 0 &&
		len(f.ExcludeProtocolTypes) == 0
}

// String returns a human-readable representation of the filter.
func (f *Filter) String() string {
	var parts []string

	if len(f.Authors) > 0 {
		parts = append(parts, "authors="+strings.Join(f.Authors, ","))
	}

	if len(f.Tags) > 0 {
		parts = append(parts, "tags="+strings.Join(f.Tags, ","))
	}

	if len(f.ExcludeTags) > 0 {
		parts = append(parts, "exclude-tags="+strings.Join(f.ExcludeTags, ","))
	}

	if len(f.IDs) > 0 {
		parts = append(parts, "ids="+strings.Join(f.IDs, ","))
	}

	if len(f.ExcludeIDs) > 0 {
		parts = append(parts, "exclude-ids="+strings.Join(f.ExcludeIDs, ","))
	}

	if len(f.Severities) > 0 {
		sevs := make([]string, len(f.Severities))
		for i, s := range f.Severities {
			sevs[i] = s.String()
		}

		parts = append(parts, "severities="+strings.Join(sevs, ","))
	}

	if len(f.ProtocolTypes) > 0 {
		pts := make([]string, len(f.ProtocolTypes))
		for i, p := range f.ProtocolTypes {
			pts[i] = p.String()
		}

		parts = append(parts, "types="+strings.Join(pts, ","))
	}

	if len(parts) == 0 {
		return "filter=<nil>"
	}

	return "filter(" + strings.Join(parts, ", ") + ")"
}

package index

import (
	"fmt"
	"testing"
)

const templateCount = 10_000

func makeMetadataCorpus(n int) []*Metadata {
	corpus := make([]*Metadata, n)
	for i := range n {
		corpus[i] = &Metadata{
			ID:           fmt.Sprintf("cve-2021-%04d", i),
			Tags:         []string{"cve", "http"},
			Authors:      []string{"tester"},
			Severity:     "critical",
			ProtocolType: "http",
		}
	}
	return corpus
}

// mixedFilter builds a realistic filter: exactIDs exact IDs (~1/3 match corpus) + wildcardPatterns glob patterns (no match)
func mixedFilter(exactIDs, wildcardPatterns int) *Filter {
	ids := make([]string, 0, exactIDs+wildcardPatterns)
	for i := range exactIDs {
		ids = append(ids, fmt.Sprintf("cve-202%d-%04d", i%3, i)) // ~1/3 hit corpus (year 2021)
	}
	for i := range wildcardPatterns {
		ids = append(ids, fmt.Sprintf("sqli-%04d-*", i)) // wildcard, no match
	}
	return &Filter{IDs: ids}
}

func BenchmarkFilterMatches(b *testing.B) {
	corpus := makeMetadataCorpus(templateCount)

	cases := []struct{ exact, wildcards int }{
		{10, 0},
		{100, 0},
		{1000, 0},
		{100, 1},
		{100, 3},
		{100, 5},
	}

	for _, tc := range cases {
		b.Run(fmt.Sprintf("ids=%d,patterns=%d", tc.exact, tc.wildcards), func(b *testing.B) {
			b.ReportAllocs()

			filter := mixedFilter(tc.exact, tc.wildcards)
			filter.Compile()
			for b.Loop() {
				for _, meta := range corpus {
					_ = filter.matchesIncludeID(meta.ID)
				}
			}
		})
	}
}

