func TestFilterFuncCanMutateIndex(t *testing.T) {
	cache, err := NewIndex(t.TempDir())
	require.NoError(t, err)
	cache.Set("/tmp/original.yaml", &Metadata{ID: "original", FilePath: "/tmp/original.yaml"})

	done := make(chan []string, 1)
	go func() {
		done <- cache.FilterFunc(func(*Metadata) bool {
			cache.Set("/tmp/from-callback.yaml", &Metadata{ID: "callback", FilePath: "/tmp/from-callback.yaml"})
			return true
		})
	}()

	select {
	case paths := <-done:
		require.Equal(t, []string{"/tmp/original.yaml"}, paths)
	case <-time.After(time.Second):
		t.Fatal("FilterFunc deadlocked when its callback mutated the index")
	}
}

func TestIndexVersionMismatch(t *testing.T) {
	tmpDir := t.TempDir()

	// Create cache with current version
	cache1, err := NewIndex(tmpDir)
	require.NoError(t, err)

	metadata := &Metadata{
		ID:       "version-test",
		FilePath: "/tmp/version.yaml",
	}
	cache1.Set(metadata.FilePath, metadata)

	// Save with current version
	err = cache1.Save()
	require.NoError(t, err)

	// Manually modify version and save again
	cache1.mu.Lock()
	cache1.version = 999
	cache1.dirty = true
	cache1.mu.Unlock()
	err = cache1.Save()
	require.NoError(t, err)

	// Try to load with different version
	cache2, err := NewIndex(tmpDir)
	require.NoError(t, err)

	// Load should succeed but cache should be empty (version mismatch)
	err = cache2.Load()
	require.NoError(t, err, "Load should not error on version mismatch")
	require.Equal(t, 0, cache2.Size(), "Cache should be empty after version mismatch")
}

