	"regexp"
	"strings"

	"github.com/alecthomas/chroma/v2/quick"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	pdcpauth "github.com/projectdiscovery/utils/auth/pdcp"
	"github.com/projectdiscovery/utils/errkit"
)

var (
	aiTemplateGeneratorAPIEndpoint = "https://api.projectdiscovery.io/v1/template/ai"
	// aiTemplateHTTPClient verifies TLS, since the request carries the PDCP API key.
	aiTemplateHTTPClient = &http.Client{}
	// aiTemplateIDRegex keeps the template file name inside the pdcp directory.
	aiTemplateIDRegex = regexp.MustCompile(`^[A-Za-z0-9_-]+$`)
)

type AITemplateResponse struct {
	CanRun     bool   `json:"canRun"`
	Comment    string `json:"comment"`
	Completion string `json:"completion"`
	Message    string `json:"message"`
	Name       string `json:"name"`
	TemplateID string `json:"template_id"`
}

func getAIGeneratedTemplates(prompt string, options *types.Options) ([]string, error) {
	prompt = strings.TrimSpace(prompt)
	if len(prompt) < 5 {
		return nil, errkit.Newf("Prompt is too short. Please provide a more descriptive prompt")
	}

	if len(prompt) > 3000 {
		return nil, errkit.Newf("Prompt is too long. Please limit to 3000 characters")
	}

	template, templateID, err := generateAITemplate(prompt)
	if err != nil {
		return nil, errkit.Newf("Failed to generate template: %v", err)
	}

	pdcpTemplateDir := filepath.Join(config.DefaultConfig.GetTemplateDir(), "pdcp")
	if err := os.MkdirAll(pdcpTemplateDir, 0755); err != nil {
		return nil, errkit.Newf("Failed to create pdcp template directory: %v", err)
	}

	templateFile := filepath.Join(pdcpTemplateDir, templateID+".yaml")
	err = os.WriteFile(templateFile, []byte(template), 0644)
	if err != nil {
		return nil, errkit.Newf("Failed to generate template: %v", err)
	}

	options.Logger.Info().Msgf("Generated template available at: https://cloud.projectdiscovery.io/templates/%s", templateID)
	options.Logger.Info().Msgf("Generated template path: %s", templateFile)

	// Check if we should display the template
	// This happens when:
	// 1. No targets are provided (-target/-list)
	// 2. No stdin input is being used
	hasNoTargets := len(options.Targets) == 0 && options.TargetsFilePath == ""
	hasNoStdin := !options.Stdin

	if hasNoTargets && hasNoStdin {
		// Display the template content with syntax highlighting
		if !options.NoColor {
			var buf bytes.Buffer
			err = quick.Highlight(&buf, template, "yaml", "terminal16m", "monokai")
			if err == nil {
				template = buf.String()
			}
		}
		options.Logger.Debug().Msgf("\n%s", template)
		// FIXME:
		// we should not be exiting the program here
		// but we need to find a better way to handle this
		os.Exit(0)
	}

	return []string{templateFile}, nil
}

func generateAITemplate(prompt string) (string, string, error) {
	reqBody := map[string]string{
		"prompt": prompt,
	}
	jsonBody, err := json.Marshal(reqBody)
	if err != nil {
		return "", "", errkit.Newf("Failed to marshal request body: %v", err)
	}

	req, err := http.NewRequest(http.MethodPost, aiTemplateGeneratorAPIEndpoint, bytes.NewBuffer(jsonBody))
	if err != nil {
		return "", "", errkit.Newf("Failed to create HTTP request: %v", err)
	}

	ph := pdcpauth.PDCPCredHandler{}
	creds, err := ph.GetCreds()
	if err != nil {
		return "", "", errkit.Newf("Failed to get PDCP credentials: %v", err)
	}

	if creds == nil {
		return "", "", errkit.Newf("PDCP API Key not configured, Create one for free at https://cloud.projectdiscovery.io/")
	}

	req.Header.Set("Content-Type", "application/json")
	req.Header.Set(pdcpauth.ApiKeyHeaderName, creds.APIKey)

	resp, err := aiTemplateHTTPClient.Do(req)
	if err != nil {
		return "", "", errkit.Newf("Failed to send HTTP request: %v", err)
	}
	defer func() {
		_ = resp.Body.Close()
	}()

	if resp.StatusCode == http.StatusUnauthorized {
		return "", "", errkit.Newf("Invalid API Key or API Key not configured, Create one for free at https://cloud.projectdiscovery.io/")
	}

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return "", "", errkit.Newf("API returned status code %d: %s", resp.StatusCode, string(body))
	}

	var result AITemplateResponse
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return "", "", errkit.Newf("Failed to decode API response: %v", err)
	}

	if result.TemplateID == "" || result.Completion == "" {
		return "", "", errkit.Newf("Failed to generate template")
	}

	if !aiTemplateIDRegex.MatchString(result.TemplateID) {
		return "", "", errkit.Newf("Invalid template ID in API response: %q", result.TemplateID)
	}

	return result.Completion, result.TemplateID, nil
}

package loader

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/require"
)

func newAITemplateServer(t *testing.T, templateID string, gotKey *atomic.Value) {
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotKey.Store(r.Header.Get("X-Api-Key"))
		_ = json.NewEncoder(w).Encode(map[string]string{
			"completion":  "id: test\n",
			"template_id": templateID,
		})
	}))
	t.Cleanup(srv.Close)

	oldEndpoint, oldClient := aiTemplateGeneratorAPIEndpoint, aiTemplateHTTPClient
	t.Cleanup(func() { aiTemplateGeneratorAPIEndpoint, aiTemplateHTTPClient = oldEndpoint, oldClient })
	aiTemplateGeneratorAPIEndpoint = srv.URL
	t.Setenv("PDCP_API_KEY", "test-key")
	if templateID != "" {
		// Trust the test certificate, to check the template_id only.
		aiTemplateHTTPClient = srv.Client()
	}
}

func TestAITemplateVerifiesTLS(t *testing.T) {
	var gotKey atomic.Value
	newAITemplateServer(t, "", &gotKey)

	_, _, err := generateAITemplate("check for exposed admin panels")
	require.ErrorContains(t, err, "certificate")
	require.Nil(t, gotKey.Load(), "the API key went to an untrusted server")
}

func TestAITemplateRejectsUnsafeID(t *testing.T) {
	for _, id := range []string{"../../.config/nuclei/config", "a/b", `a\b`, "a.b", "a b"} {
		var gotKey atomic.Value
		newAITemplateServer(t, id, &gotKey)
		_, _, err := generateAITemplate("check for exposed admin panels")
		require.Error(t, err, id)
	}

	var gotKey atomic.Value
	newAITemplateServer(t, "Abc-123_x", &gotKey)
	_, templateID, err := generateAITemplate("check for exposed admin panels")
	require.NoError(t, err)
	require.Equal(t, "Abc-123_x", templateID)
}

package filter

import (
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog"
)

// PathFilter is a path based template filter
type PathFilter struct {
	excludedTemplates          []string
	alwaysIncludedTemplatesMap map[string]struct{}
}

// PathFilterConfig contains configuration options for Path based templates Filter
type PathFilterConfig struct {
	IncludedTemplates []string
	ExcludedTemplates []string
}

// NewPathFilter creates a new path filter from provided config
func NewPathFilter(config *PathFilterConfig, catalogClient catalog.Catalog) *PathFilter {
	paths, _ := catalogClient.GetTemplatesPath(config.ExcludedTemplates)
	filter := &PathFilter{
		excludedTemplates:          paths,
		alwaysIncludedTemplatesMap: make(map[string]struct{}),
	}

	alwaysIncludeTemplates, _ := catalogClient.GetTemplatesPath(config.IncludedTemplates)
	for _, tpl := range alwaysIncludeTemplates {
		filter.alwaysIncludedTemplatesMap[tpl] = struct{}{}
	}
	return filter
}

// Match performs match for path filter on templates and returns final list
func (p *PathFilter) Match(templates []string) map[string]struct{} {
	templatesMap := make(map[string]struct{})
	for _, tpl := range templates {
		templatesMap[tpl] = struct{}{}
	}
	for _, template := range p.excludedTemplates {
		if _, ok := p.alwaysIncludedTemplatesMap[template]; ok {
			continue
		} else {
			delete(templatesMap, template)
		}
	}
	return templatesMap
}

// MatchIncluded returns true if the template was included explicitly
func (p *PathFilter) MatchIncluded(template string) bool {
	_, found := p.alwaysIncludedTemplatesMap[template]
	return found
}

