func TestWorkflowNestedSubtemplatesDoNotDeadlockAtConcurrencyLimit(t *testing.T) {
	// Repro for #8074: with TemplateThreads equal to the number of matching
	// nested parents, each parent used to hold a waitgroup slot while calling
	// AddWithContext for its children, so every slot was occupied by a parent
	// waiting for another slot and the workflow never finished.
	progressBar, _ := progress.NewStatsTicker(0, false, false, false, 0)
	matchOutputs := []*output.InternalWrappedEvent{{
		OperatorsResult: &operators.Result{},
		Results:         []*output.ResultEvent{{}},
	}}

	const parents = 3
	var entered atomic.Int32
	allHolding := make(chan struct{})
	releaseParents := make(chan struct{})
	leafRuns := &atomic.Int32{}

	leaf := &mockExecuter{result: true, executeScanHook: func(ctx *scan.ScanContext) {
		leafRuns.Add(1)
	}}
	parentExec := &mockExecuter{
		result:  true,
		outputs: matchOutputs,
		executeScanHook: func(ctx *scan.ScanContext) {
			if entered.Add(1) == parents {
				close(allHolding)
			}
			// Stay inside ExecuteWithResults so the parent still owns its
			// waitgroup slot while every peer also holds one.
			<-releaseParents
		},
	}
	mkParent := func() *workflows.WorkflowTemplate {
		return &workflows.WorkflowTemplate{
			Executers: []*workflows.ProtocolExecuterPair{{
				Executer: parentExec,
				Options:  &protocols.ExecutorOptions{Progress: progressBar},
			}},
			Subtemplates: []*workflows.WorkflowTemplate{{
				Executers: []*workflows.ProtocolExecuterPair{{
					Executer: leaf,
					Options:  &protocols.ExecutorOptions{Progress: progressBar},
				}},
			}},
		}
	}

	workflow := &workflows.Workflow{
		Options: &protocols.ExecutorOptions{Options: &types.Options{TemplateThreads: parents}},
		Workflows: []*workflows.WorkflowTemplate{{
			Executers: []*workflows.ProtocolExecuterPair{{
				Executer: &mockExecuter{result: true, outputs: matchOutputs},
				Options:  &protocols.ExecutorOptions{Progress: progressBar},
			}},
			Subtemplates: []*workflows.WorkflowTemplate{mkParent(), mkParent(), mkParent()},
		}},
	}

	engine := &Engine{}
	input := contextargs.NewWithInput(context.Background(), "https://test.com")
	ctx := scan.NewScanContext(context.Background(), input)

	done := make(chan bool, 1)
	go func() {
		done <- engine.executeWorkflow(ctx, workflow)
	}()

	select {
	case <-allHolding:
	case <-time.After(2 * time.Second):
		t.Fatal("nested parents did not all acquire TemplateThreads slots")
	}
	close(releaseParents)

	select {
	case matched := <-done:
		require.True(t, matched, "nested workflow should report a match")
		require.EqualValues(t, parents, leafRuns.Load(), "each nested parent should run its leaf")
	case <-time.After(3 * time.Second):
		t.Fatal("nested workflow deadlocked at TemplateThreads == matching nested parents")
	}
}

func TestWorkflowSubtemplatesUnblockCancelledAcquire(t *testing.T) {
	progressBar, _ := progress.NewStatsTicker(0, false, false, false, 0)
	var started atomic.Int32
	block := &mockExecuter{result: true, executeScanHook: func(ctx *scan.ScanContext) {
		started.Add(1)
		<-ctx.Context().Done()
	}}
	var waitingStarted atomic.Bool
	waiting := &mockExecuter{result: true, executeScanHook: func(ctx *scan.ScanContext) {
		waitingStarted.Store(true)
		<-ctx.Context().Done()
	}}

	// Two slots: the two blockers occupy them so the third AddWithContext waits.
	workflow := &workflows.Workflow{Options: &protocols.ExecutorOptions{Options: &types.Options{TemplateThreads: 2}}, Workflows: []*workflows.WorkflowTemplate{
		{Executers: []*workflows.ProtocolExecuterPair{{
			Executer: &mockExecuter{result: true, outputs: []*output.InternalWrappedEvent{
				{OperatorsResult: &operators.Result{}, Results: []*output.ResultEvent{{}}},
			}}, Options: &protocols.ExecutorOptions{Progress: progressBar}},
		}, Subtemplates: []*workflows.WorkflowTemplate{
			{Executers: []*workflows.ProtocolExecuterPair{{Executer: block, Options: &protocols.ExecutorOptions{Progress: progressBar}}}},
			{Executers: []*workflows.ProtocolExecuterPair{{Executer: block, Options: &protocols.ExecutorOptions{Progress: progressBar}}}},
			{Executers: []*workflows.ProtocolExecuterPair{{Executer: waiting, Options: &protocols.ExecutorOptions{Progress: progressBar}}}},
		}},
	}}

	engine := &Engine{}
	parent, cancel := context.WithCancel(context.Background())
	input := contextargs.NewWithInput(parent, "https://test.com")
	ctx := scan.NewScanContext(parent, input)

	done := make(chan struct{})
	go func() {
		defer close(done)
		engine.executeWorkflow(ctx, workflow)
	}()

	deadline := time.After(2 * time.Second)
	for started.Load() < 2 {
		select {
		case <-deadline:
			t.Fatal("blocking subtemplates did not occupy both slots")
		case <-time.After(10 * time.Millisecond):
		}
	}
	cancel()

	select {
	case <-done:
	case <-time.After(2 * time.Second):
		t.Fatal("workflow stayed blocked after cancel")
	}
	require.False(t, waitingStarted.Load(), "third subtemplate must not start while slots are held")
}

// errHeaderTimeout is the error of a request to a host that accepts
// connections and never answers.
var errHeaderTimeout = errors.New("net/http: timeout awaiting response headers")

// TestWorkflowStepsKeepHostErrors runs steps whose requests time out, as they
// do against a host that accepts connections and never answers. Each request
// records its failure, and the step itself returns nil, as a template step can
// when its requests fail. The step after the last allowed failure must find the
// host unresponsive (#8177).
//
//nolint:exhaustruct,exhaustruct_v5 // fixtures keep zero-value defaults
func TestWorkflowStepsKeepHostErrors(t *testing.T) {
	t.Parallel()

	const maxHostError = 3

	cache := hosterrorscache.New(maxHostError, hosterrorscache.DefaultMaxHostsCount, nil)
	t.Cleanup(cache.Close)

	progressBar, _ := progress.NewStatsTicker(0, false, false, false, 0)
	stepOptions := &protocols.ExecutorOptions{Progress: progressBar}

	steps := make([]*workflows.WorkflowTemplate, 0, maxHostError+1)
	for range maxHostError {
		steps = append(steps, &workflows.WorkflowTemplate{Executers: []*workflows.ProtocolExecuterPair{{
			Executer: &mockExecuter{executeScanHook: func(ctx *scan.ScanContext) {
				cache.MarkFailedOrRemove("http", ctx.Input, errHeaderTimeout)
			}},
			Options: stepOptions,
		}}})
	}

	var unresponsive bool

	steps = append(steps, &workflows.WorkflowTemplate{Executers: []*workflows.ProtocolExecuterPair{{
		Executer: &mockExecuter{executeScanHook: func(ctx *scan.ScanContext) {
			unresponsive = cache.Check("http", ctx.Input)
		}},
		Options: stepOptions,
	}}})

	workflow := &workflows.Workflow{
		Options:   &protocols.ExecutorOptions{Options: &types.Options{TemplateThreads: 1}, HostErrorsCache: cache},
		Workflows: steps,
	}
	input := contextargs.NewWithInput(t.Context(), "http://127.0.0.1:47321")
	(&Engine{}).executeWorkflow(scan.NewScanContext(t.Context(), input), workflow)

	require.True(t, unresponsive, "the host errors recorded by earlier steps must not be reset")
}

type mockExecuter struct {
	result          bool
	executeHook     func(input *contextargs.MetaInput)
	executeScanHook func(ctx *scan.ScanContext)
	outputs         []*output.InternalWrappedEvent
}

// Compile compiles the execution generators preparing any requests possible.
func (m *mockExecuter) Compile() error {
	return nil
}

// Requests returns the total number of requests the rule will perform
func (m *mockExecuter) Requests() int {
	return 1
}

// Execute executes the protocol group and  returns true or false if results were found.
func (m *mockExecuter) Execute(ctx *scan.ScanContext) (bool, error) {
	if m.executeHook != nil {
		m.executeHook(ctx.Input.MetaInput)
	}
	if m.executeScanHook != nil {
		m.executeScanHook(ctx)
	}
	return m.result, nil
}

// ExecuteWithResults executes the protocol requests and returns results instead of writing them.
func (m *mockExecuter) ExecuteWithResults(ctx *scan.ScanContext) ([]*output.ResultEvent, error) {
	if m.executeHook != nil {
		m.executeHook(ctx.Input.MetaInput)
	}
	if m.executeScanHook != nil {
		m.executeScanHook(ctx)
	}
	for _, output := range m.outputs {
		ctx.LogEvent(output)
	}
	return ctx.GenerateResult(), nil
}

package core

import (
	"context"
	"fmt"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	syncutil "github.com/projectdiscovery/utils/sync"
)

// WorkPool implements an execution pool for executing different
// types of task with different concurrency requirements.
//
// It also allows Configuration of such requirements. This is used
// for per-module like separate headless concurrency etc.
type WorkPool struct {
	Headless *syncutil.AdaptiveWaitGroup
	Default  *syncutil.AdaptiveWaitGroup
	config   WorkPoolConfig
}

// WorkPoolConfig is the configuration for work pool
type WorkPoolConfig struct {
	// InputConcurrency is the concurrency for inputs values.
	InputConcurrency int
	// TypeConcurrency is the concurrency for the request type templates.
	TypeConcurrency int
	// HeadlessInputConcurrency is the concurrency for headless inputs values.
	HeadlessInputConcurrency int
	// TypeConcurrency is the concurrency for the headless request type templates.
	HeadlessTypeConcurrency int
}

// NewWorkPool returns a new WorkPool instance
func NewWorkPool(config WorkPoolConfig) *WorkPool {
	return &WorkPool{
		config:   config,
		Headless: newPool(config.HeadlessTypeConcurrency),
		Default:  newPool(config.TypeConcurrency),
	}
}

// newPool returns a pool of size, or of one when size is below 1.
// syncutil.New returns a nil pool for a size below 1, which the scan would
// dereference.
func newPool(size int) *syncutil.AdaptiveWaitGroup {
	size = max(size, 1)

	pool, err := syncutil.New(syncutil.WithSize(size))
	if err != nil {
		// The size is at least 1, so this cannot happen. Stopping here beats
		// handing the scan a nil pool.
		panic(fmt.Sprintf("could not create work pool of size %d: %s", size, err))
	}

	return pool
}

// Wait waits for all the work pool wait groups to finish
func (w *WorkPool) Wait() {
	w.Default.Wait()
	w.Headless.Wait()
}

// InputPool returns a work pool for an input type
func (w *WorkPool) InputPool(templateType types.ProtocolType) *syncutil.AdaptiveWaitGroup {
	var count int
	if templateType == types.HeadlessProtocol {
		count = w.config.HeadlessInputConcurrency
	} else {
		count = w.config.InputConcurrency
	}

	return newPool(count)
}

func (w *WorkPool) RefreshWithConfig(config WorkPoolConfig) {
	w.RefreshWithConfigContext(context.Background(), config)
}

func (w *WorkPool) RefreshWithConfigContext(ctx context.Context, config WorkPoolConfig) {
	if w.config.TypeConcurrency != config.TypeConcurrency {
		w.config.TypeConcurrency = config.TypeConcurrency
	}
	if w.config.HeadlessTypeConcurrency != config.HeadlessTypeConcurrency {
		w.config.HeadlessTypeConcurrency = config.HeadlessTypeConcurrency
	}
	if w.config.InputConcurrency != config.InputConcurrency {
		w.config.InputConcurrency = config.InputConcurrency
	}
	if w.config.HeadlessInputConcurrency != config.HeadlessInputConcurrency {
		w.config.HeadlessInputConcurrency = config.HeadlessInputConcurrency
	}
	w.Refresh(ctx)
}

func (w *WorkPool) Refresh(ctx context.Context) {
	// newPool sized the pools to at least 1, so compare against the same bound.
	typeConcurrency := max(w.config.TypeConcurrency, 1)
	headlessTypeConcurrency := max(w.config.HeadlessTypeConcurrency, 1)

	if w.Default.Size != typeConcurrency {
		err := w.Default.Resize(ctx, typeConcurrency)
		if err != nil {
			gologger.Warning().Msgf("Could not resize workpool: %s\n", err)
		}
	}

	if w.Headless.Size != headlessTypeConcurrency {
		err := w.Headless.Resize(ctx, headlessTypeConcurrency)
		if err != nil {
			gologger.Warning().Msgf("Could not resize workpool: %s\n", err)
		}
	}
}

