	match, _, err := checkTimingDependency(
		4,   // requestsLimit
		15,  // highSleepTimeSeconds
		0.1, // correlationErrorRange
		0.2, // slopeErrorRange
		baseline,
		reqSender,
	)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if match {
		t.Fatal("Expected no match for slow non-injectable case")
	}
	if timesCalled > 3 {
		t.Fatalf("Expected early termination (≤3 calls), got %d calls", timesCalled)
	}
}

func TestRealWorldNonInjectableCase(t *testing.T) {
	baseline := 0.0
	var iteration int
	counts := []float64{11, 21, 11, 21, 11}
	reqSender := func(delay int) (float64, error) {
		iteration++
		return counts[iteration-1], nil
	}
	match, _, err := checkTimingDependency(
		4,   // requestsLimit
		15,  // highSleepTimeSeconds
		0.1, // correlationErrorRange
		0.2, // slopeErrorRange
		baseline,
		reqSender,
	)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if match {
		t.Fatal("Expected no match for real-world non-injectable case")
	}
	if iteration > 4 {
		t.Fatalf("Expected ≤4 iterations, got %d", iteration)
	}
}

func TestSmallErrorDependence(t *testing.T) {
	baseline := 0.0
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	reqSender := func(delay int) (float64, error) {
		return float64(delay) + rng.Float64()*0.5, nil
	}
	match, reason, err := checkTimingDependency(
		4,   // requestsLimit
		15,  // highSleepTimeSeconds
		0.1, // correlationErrorRange
		0.2, // slopeErrorRange
		baseline,
		reqSender,
	)
	if err != nil {
		t.Fatalf("Unexpected error: %v", err)
	}
	if !match {
		t.Fatalf("Expected match for small error case. Reason: %s", reason)
	}
}

// copyHeaders replicates the header-copy logic from Analyze's reqSender closure.
// It copies all headers from src to dst, skipping the fuzzed key when the
// component is a header component.
func copyHeaders(dst, src *retryablehttp.Request, componentName, fuzzedKey string) {
	for k, vs := range src.Header {
		if componentName == "header" && k == fuzzedKey {
			continue
		}
		dst.Header[k] = vs
	}
}

func TestRebuildFromClonedComponentLosesPostParseHeaders(t *testing.T) {
	rawReq, _ := retryablehttp.NewRequest("GET", "http://example.com/?id=1", nil)

	q := component.NewQuery()
	parsed, err := q.Parse(rawReq)
	require.True(t, parsed)
	require.NoError(t, err)

	// in the real flow the component is cloned before custom headers are
	// injected, so the clone's internal request has no custom headers
	cloned := q.Clone()

	rawReq.Header.Set("Cookie", "session=abc123")
	rawReq.Header.Set("Authorization", "Bearer tok")

	err = cloned.SetValue("id", "2")
	require.NoError(t, err)

	rebuilt, err := cloned.Rebuild()
	require.NoError(t, err)

	require.Empty(t, rebuilt.Header.Get("Cookie"), "cloned component rebuild should not have post-parse headers")
	require.Empty(t, rebuilt.Header.Get("Authorization"))
}

func TestHeaderCopyRestoresCustomHeaders(t *testing.T) {
	rawReq, _ := retryablehttp.NewRequest("GET", "http://example.com/?id=1", nil)

	q := component.NewQuery()
	parsed, err := q.Parse(rawReq)
	require.True(t, parsed)
	require.NoError(t, err)

	cloned := q.Clone()

	// simulate post-parse header injection on the live request
	rawReq.Header.Set("Cookie", "session=abc123")
	rawReq.Header.Set("Authorization", "Bearer tok")
	rawReq.Header.Set("X-Custom", "value")

	err = cloned.SetValue("id", "2")
	require.NoError(t, err)
	rebuilt, err := cloned.Rebuild()
	require.NoError(t, err)

	copyHeaders(rebuilt, rawReq, cloned.Name(), "")

	require.Equal(t, "session=abc123", rebuilt.Header.Get("Cookie"))
	require.Equal(t, "Bearer tok", rebuilt.Header.Get("Authorization"))
	require.Equal(t, "value", rebuilt.Header.Get("X-Custom"))
}

func TestHeaderCopySkipsFuzzedKey(t *testing.T) {
	rawReq, _ := retryablehttp.NewRequest("GET", "http://example.com/", nil)
	rawReq.Header.Set("X-Inject", "original-value")
	rawReq.Header.Set("Cookie", "session=abc123")

	h := component.NewHeader()
	parsed, err := h.Parse(rawReq)
	require.True(t, parsed)
	require.NoError(t, err)

	fuzzedKey := "X-Inject"
	err = h.SetValue(fuzzedKey, "sleep(5)")
	require.NoError(t, err)
	rebuilt, err := h.Rebuild()
	require.NoError(t, err)

	copyHeaders(rebuilt, rawReq, h.Name(), fuzzedKey)

	require.Equal(t, "sleep(5)", rebuilt.Header.Get("X-Inject"), "fuzzed header should keep the payload")
	require.Equal(t, "session=abc123", rebuilt.Header.Get("Cookie"), "non-fuzzed headers should be copied")
}

func TestHeaderCopyWithMultipleValues(t *testing.T) {
	rawReq, _ := retryablehttp.NewRequest("GET", "http://example.com/?q=1", nil)

	q := component.NewQuery()
	parsed, err := q.Parse(rawReq)
	require.True(t, parsed)
	require.NoError(t, err)

	cloned := q.Clone()

	rawReq.Header.Add("X-Multi", "val1")
	rawReq.Header.Add("X-Multi", "val2")

	rebuilt, err := cloned.Rebuild()
	require.NoError(t, err)

	copyHeaders(rebuilt, rawReq, cloned.Name(), "")

	require.Equal(t, []string{"val1", "val2"}, rebuilt.Header.Values("X-Multi"))
}

package xss

import (
	"io"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz/analyzers"
	"golang.org/x/net/html"
)

const (
	analyzerName         = "xss_context"
	maxResponseBodyBytes = 10 * 1024 * 1024 // 10 MiB
)

// XSSAnalyzer implements the analyzers.Analyzer interface for XSS context detection.
type XSSAnalyzer struct{}

var _ analyzers.Analyzer = &XSSAnalyzer{}

func init() {
	analyzers.RegisterAnalyzer(analyzerName, &XSSAnalyzer{})
}

func (a *XSSAnalyzer) Name() string {
	return analyzerName
}

func (a *XSSAnalyzer) ApplyInitialTransformation(data string, params map[string]interface{}) string {
	return analyzers.ApplyPayloadTransformations(data)
}

func (a *XSSAnalyzer) Analyze(options *analyzers.Options) (bool, string, error) {
	if options == nil || options.FuzzGenerated.Component == nil || options.HttpClient == nil {
		return false, "", nil
	}

	gr := options.FuzzGenerated
	payload := gr.Value
	if payload == "" {
		return false, "", nil
	}

	if err := gr.Component.SetValue(gr.Key, payload); err != nil {
		return false, "", err
	}
	defer func() {
		_ = gr.Component.SetValue(gr.Key, gr.OriginalValue)
	}()

	rebuilt, err := gr.Component.Rebuild()
	if err != nil {
		return false, "", err
	}

	resp, err := options.HttpClient.Do(rebuilt)
	if err != nil {
		return false, "", err
	}
	defer func() {
		_ = resp.Body.Close()
	}()

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBodyBytes))
	if err != nil {
		return false, "", err
	}

	ctx, err := AnalyzeReflectionContext(string(body), payload)
	if err != nil {
		return false, "", err
	}
	if ctx == ContextUnknown {
		return false, "", nil
	}
	return true, "xss-reflected in " + ctx.String(), nil
}

