package dataformat

import (
	"errors"
	"fmt"
)

// dataformats is a list of dataformats
var dataformats map[string]DataFormat

const (
	// DefaultKey is the key i.e used when given
	// data is not of k-v type
	DefaultKey = "value"
)

func init() {
	dataformats = make(map[string]DataFormat)

	// register the default data formats
	RegisterDataFormat(NewGraphql())
	RegisterDataFormat(NewJSON())
	RegisterDataFormat(NewXML())
	RegisterDataFormat(NewRaw())
	RegisterDataFormat(NewForm())
	RegisterDataFormat(NewMultiPartForm())
}

const (
	// GraphqlDataFormat is the name of the GraphQL-over-HTTP JSON data format
	GraphqlDataFormat = "graphql"
	// JSONDataFormat is the name of the JSON data format
	JSONDataFormat = "json"
	// XMLDataFormat is the name of the XML data format
	XMLDataFormat = "xml"
	// RawDataFormat is the name of the Raw data format
	RawDataFormat = "raw"
	// FormDataFormat is the name of the Form data format
	FormDataFormat = "form"
	// MultiPartFormDataFormat is the name of the MultiPartForm data format
	MultiPartFormDataFormat = "multipart/form-data"
)

// decodePriority prefers more specific formats before generic ones (GraphQL
// bodies are valid JSON, so GraphQL must win over JSON).
var decodePriority = []string{
	GraphqlDataFormat,
	JSONDataFormat,
	XMLDataFormat,
	MultiPartFormDataFormat,
	FormDataFormat,
	RawDataFormat,
}

// Get returns the dataformat by name
func Get(name string) DataFormat {
	return dataformats[name]
}

// RegisterEncoder registers an encoder
func RegisterDataFormat(dataformat DataFormat) {
	dataformats[dataformat.Name()] = dataformat
}

// DataFormat is an interface for encoding and decoding
type DataFormat interface {
	// IsType returns true if the data is of the type
	IsType(data string) bool
	// Name returns the name of the encoder
	Name() string
	// Encode encodes the data into a format
	Encode(data KV) (string, error)
	// Decode decodes the data from a format
	Decode(input string) (KV, error)
}

// Decoded is a decoded data format
type Decoded struct {
	// DataFormat is the data format
	DataFormat string
	// Data is the decoded data
	Data KV
}

// Decode decodes the data from a format
func Decode(data string) (*Decoded, error) {
	tryDecode := func(dataformat DataFormat) (*Decoded, error) {
		if dataformat == nil || !dataformat.IsType(data) {
			return nil, nil
		}
		decoded, err := dataformat.Decode(data)
		if err != nil {
			return nil, err
		}
		return &Decoded{
			DataFormat: dataformat.Name(),
			Data:       decoded,
		}, nil
	}

	for _, name := range decodePriority {
		decoded, err := tryDecode(dataformats[name])
		if err != nil {
			return nil, err
		}
		if decoded != nil {
			return decoded, nil
		}
	}
	for name, dataformat := range dataformats {
		if containsString(decodePriority, name) {
			continue
		}
		decoded, err := tryDecode(dataformat)
		if err != nil {
			return nil, err
		}
		if decoded != nil {
			return decoded, nil
		}
	}
	return nil, nil
}

func containsString(items []string, want string) bool {
	for _, item := range items {
		if item == want {
			return true
		}
	}
	return false
}

// Encode encodes the data into a format
func Encode(data KV, dataformat string) (string, error) {
	if dataformat == "" {
		return "", errors.New("dataformat is required")
	}
	if encoder, ok := dataformats[dataformat]; ok {
		return encoder.Encode(data)
	}
	return "", fmt.Errorf("dataformat %s is not supported", dataformat)
}

package dataformat

import (
	"testing"
)

func TestDataformatDecodeEncode_JSON(t *testing.T) {
	obj := `{"foo":"bar"}`

	decoded, err := Decode(obj)
	if err != nil {
		t.Fatal(err)
	}
	if decoded.DataFormat != "json" {
		t.Fatal("unexpected data format")
	}
	if decoded.Data.Get("foo") != "bar" {
		t.Fatal("unexpected data")
	}

	encoded, err := Encode(decoded.Data, decoded.DataFormat)
	if err != nil {
		t.Fatal(err)
	}
	if encoded != obj {
		t.Fatal("unexpected data")
	}
}

func TestDataformatDecodeEncode_XML(t *testing.T) {
	obj := `<foo attr="baz">bar</foo>`

	decoded, err := Decode(obj)
	if err != nil {
		t.Fatal(err)
	}
	if decoded.DataFormat != "xml" {
		t.Fatal("unexpected data format")
	}
	fooValue := decoded.Data.Get("foo")
	if fooValue == nil {
		t.Fatal("key 'foo' not found")
	}
	fooMap, ok := fooValue.(map[string]interface{})
	if !ok {
		t.Fatal("type assertion to map[string]interface{} failed")
	}
	if fooMap["#text"] != "bar" {
		t.Fatal("unexpected data for '#text'")
	}
	if fooMap["-attr"] != "baz" {
		t.Fatal("unexpected data for '-attr'")
	}

	encoded, err := Encode(decoded.Data, decoded.DataFormat)
	if err != nil {
		t.Fatal(err)
	}
	if encoded != obj {
		t.Fatal("unexpected data")
	}
}

package dataformat

import (
	"fmt"
	"regexp"
	"strconv"

	"github.com/projectdiscovery/gologger"
	mapsutil "github.com/projectdiscovery/utils/maps"
	urlutil "github.com/projectdiscovery/utils/url"
)

const (
	normalizedRegex = `_(\d+)$`
)

var (
	reNormalized = regexp.MustCompile(normalizedRegex)
)

// == Handling Duplicate Query Parameters / Form Data ==
// Nuclei supports fuzzing duplicate query parameters by internally normalizing
// them and denormalizing them back when creating request this normalization
// can be leveraged to specify custom fuzzing behaviour in template as well
// if a query like `?foo=bar&foo=baz&foo=fuzzz` is provided, it will be normalized to
// foo_1=bar , foo_2=baz , foo=fuzzz (i.e last value is given original key which is usual behaviour in HTTP and its implementations)
// this way this change does not break any existing rules in template given by keys-regex or keys
// At same time if user wants to specify 2nd or 1st duplicate value in template, they can use foo_1 or foo_2 in keys-regex or keys
// Note: By default all duplicate query parameters are fuzzed

type Form struct{}

var (
	_ DataFormat = &Form{}
)

// NewForm returns a new Form encoder
func NewForm() *Form {
	return &Form{}
}

// IsType returns true if the data is Form encoded
func (f *Form) IsType(data string) bool {
	return false
}

// Encode encodes the data into Form format
func (f *Form) Encode(data KV) (string, error) {
	params := urlutil.NewOrderedParams()

	data.Iterate(func(key string, value any) bool {
		params.Add(key, fmt.Sprint(value))
		return true
	})

	normalized := map[string]map[string]string{}
	// Normalize the data
	for _, origKey := range data.OrderedMap.GetKeys() {
		// here origKey is base key without _1, _2 etc.
		if origKey != "" && !reNormalized.MatchString(origKey) {
			params.Iterate(func(key string, value []string) bool {
				if baseKey, ok := normalizedKeyBase(key); ok && baseKey == origKey {
					m := map[string]string{}
					if normalized[origKey] != nil {
						m = normalized[origKey]
					}
					if len(value) == 1 {
						m[key] = value[0]
					} else {
						m[key] = ""
					}
					normalized[origKey] = m
					params.Del(key)
				}
				return true
			})
		}
	}

	if len(normalized) > 0 {
		for k, v := range normalized {
			maxIndex := -1
			for key := range v {
				matches := reNormalized.FindStringSubmatch(key)
				if len(matches) == 2 {
					dataIdx, err := strconv.Atoi(matches[1])
					if err != nil {
						gologger.Verbose().Msgf("error converting normalized index(%v) to integer: %v", matches[1], err)
						continue
					}
					if dataIdx > maxIndex {
						maxIndex = dataIdx
					}
				}
			}
			if maxIndex >= 0 { // Ensure the slice is only created if maxIndex is valid
				data := make([]string, maxIndex+1) // Ensure the slice is large enough
				for key, value := range v {
					matches := reNormalized.FindStringSubmatch(key)
					if len(matches) == 2 {
						dataIdx, err := strconv.Atoi(matches[1]) // Error already checked above
						if err != nil {
							gologger.Verbose().Msgf("error converting data index to integer: %v", err)
							continue
						}
						// Validate dataIdx to avoid index out of range errors
						if dataIdx > 0 && dataIdx <= len(data) {
							data[dataIdx-1] = value // Use dataIdx-1 since slice is 0-indexed
						} else {
							gologger.Verbose().Msgf("data index out of range: %d", dataIdx)
						}
					}
				}
				if len(params.Get(k)) > 0 {
					data[maxIndex] = fmt.Sprint(params.Get(k)) // Use maxIndex which is the last index
				}
				// remove existing
				params.Del(k)
				if len(data) > 0 {
					params.Add(k, data...)
				}
			}
		}
	}

	encoded := params.Encode()
	return encoded, nil
}

func normalizedKeyBase(key string) (string, bool) {
	match := reNormalized.FindStringIndex(key)
	if match == nil {
		return "", false
	}
	return key[:match[0]], true
}

// Decode decodes the data from Form format
func (f *Form) Decode(data string) (KV, error) {
	ordered_params := urlutil.NewOrderedParams()
	ordered_params.Merge(data)

	values := mapsutil.NewOrderedMap[string, any]()
	ordered_params.Iterate(func(key string, value []string) bool {
		if len(value) == 1 {
			values.Set(key, value[0])
		} else {
			// in case of multiple query params in form data
			// last value is considered and previous values are exposed with _1, _2, _3 etc.
			// note that last value will not be included in _1, _2, _3 etc.
			for i := 0; i < len(value)-1; i++ {
				values.Set(key+"_"+strconv.Itoa(i+1), value[i])
			}
			values.Set(key, value[len(value)-1])
		}
		return true
	})
	return KVOrderedMap(&values), nil
}

// Name returns the name of the encoder
func (f *Form) Name() string {
	return FormDataFormat
}

package dataformat

import "testing"

func TestFormDecodeEncode_DuplicateParameters(t *testing.T) {
	form := NewForm()
	decoded, err := form.Decode("foo=a&foo=b&foo=c")
	if err != nil {
		t.Fatal(err)
	}

	encoded, err := form.Encode(decoded)
	if err != nil {
		t.Fatal(err)
	}
	if encoded != "foo=a&foo=b&foo=c" {
		t.Fatalf("unexpected form encoding: %q", encoded)
	}
}

func TestFormDecodeEncode_DoesNotMergePrefixParameterNames(t *testing.T) {
	form := NewForm()
	decoded, err := form.Decode("foo=a&foobar=b&foobar=c")
	if err != nil {
		t.Fatal(err)
	}

	encoded, err := form.Encode(decoded)
	if err != nil {
		t.Fatal(err)
	}
	if encoded != "foo=a&foobar=b&foobar=c" {
		t.Fatalf("unexpected form encoding: %q", encoded)
	}
}

package dataformat

import (
	"fmt"
	"sort"
	"strings"

	"github.com/graphql-go/graphql/language/ast"
	"github.com/graphql-go/graphql/language/kinds"
	"github.com/graphql-go/graphql/language/lexer"
	"github.com/graphql-go/graphql/language/parser"
	"github.com/graphql-go/graphql/language/printer"
	"github.com/graphql-go/graphql/language/source"
	"github.com/graphql-go/graphql/language/visitor"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

const (
	graphqlMetaQuery         = "#_query"
	graphqlMetaOperationName = "#_operationName"
	graphqlMetaHasVariables  = "#_hasVariables"
	graphqlMetaExtensions    = "#_extensions"
)

// Graphql encodes and decodes GraphQL-over-HTTP JSON bodies
// ({"query","variables","operationName"}) so DAST fuzzing can target
// variables and inline field arguments instead of the raw query string.
type Graphql struct{}

var _ DataFormat = &Graphql{}

// NewGraphql returns a new GraphQL data format encoder/decoder.
func NewGraphql() *Graphql {
	return &Graphql{}
}

// Name returns the name of the data format.
func (g *Graphql) Name() string {
	return GraphqlDataFormat
}

// IsType reports whether data is a GraphQL HTTP request body.
func (g *Graphql) IsType(data string) bool {
	_, ok := parseGraphQLHTTPBody(data, true)
	return ok
}

type graphQLHTTPBody struct {
	Query         string          `json:"query,omitempty"`
	OperationName string          `json:"operationName,omitempty"`
	Variables     *map[string]any `json:"variables,omitempty"`
	Extensions    json.Message    `json:"extensions,omitempty"`
}

func parseGraphQLHTTPBody(data string, validateQuery bool) (graphQLHTTPBody, bool) {
	trimmed := strings.TrimSpace(data)
	if !strings.HasPrefix(trimmed, "{") || !strings.HasSuffix(trimmed, "}") {
		return graphQLHTTPBody{}, false
	}

	var body graphQLHTTPBody
	if err := json.Unmarshal([]byte(trimmed), &body); err != nil {
		return graphQLHTTPBody{}, false
	}
	if strings.TrimSpace(body.Query) == "" {
		return graphQLHTTPBody{}, false
	}
	if !validateQuery {
		return body, true
	}
	if _, err := parseQueryAST(body.Query); err != nil {
		return graphQLHTTPBody{}, false
	}
	return body, true
}

func parseQueryAST(query string) (*ast.Document, error) {
	doc, err := parser.Parse(parser.ParseParams{
		Source: &source.Source{Body: []byte(query)},
	})
	if err == nil {
		return doc, nil
	}

	// graphql-go v0.8.1 predates GraphQL null literal support. Replace null
	// name tokens with an enum sentinel for parsing, then restore the AST.
	rewritten, sentinel, replaced, rewriteErr := rewriteGraphQLNullTokens(query)
	if rewriteErr != nil || !replaced {
		return nil, err
	}
	doc, rewriteErr = parser.Parse(parser.ParseParams{
		Source: &source.Source{Body: []byte(rewritten)},
	})
	if rewriteErr != nil {
		return nil, err
	}
	visitor.Visit(doc, &visitor.VisitorOptions{
		Enter: func(params visitor.VisitFuncParams) (string, interface{}) {
			switch node := params.Node.(type) {
			case *ast.Name:
				if node.Value == sentinel {
					node.Value = "null"
				}
			case *ast.EnumValue:
				if node.Value == sentinel {
					node.Value = "null"
				}
			}
			return visitor.ActionNoChange, nil
		},
	}, nil)
	return doc, nil
}

func rewriteGraphQLNullTokens(query string) (string, string, bool, error) {
	sentinel := "__NUCLEI_GRAPHQL_NULL__"
	for strings.Contains(query, sentinel) {
		sentinel += "_"
	}

	src := &source.Source{Body: []byte(query)}
	next := lexer.Lex(src)
	var out strings.Builder
	last := 0
	replaced := false
	for {
		token, err := next(0)
		if err != nil {
			return "", "", false, err
		}
		if token.Kind == lexer.EOF {
			break
		}
		if token.Kind != lexer.NAME || token.Value != "null" {
			continue
		}
		out.WriteString(query[last:token.Start])
		out.WriteString(sentinel)
		last = token.End
		replaced = true
	}
	if !replaced {
		return query, sentinel, false, nil
	}
	out.WriteString(query[last:])
	return out.String(), sentinel, true, nil
}

// Decode extracts fuzzable GraphQL variables / inline arguments.
func (g *Graphql) Decode(data string) (KV, error) {
	body, ok := parseGraphQLHTTPBody(data, true)
	if !ok {
		return KV{}, fmt.Errorf("not a graphql http body")
	}
	doc, err := parseQueryAST(body.Query)
	if err != nil {
		return KV{}, fmt.Errorf("could not parse graphql query: %w", err)
	}

	kv := KVMap(map[string]any{})
	kv.Set(graphqlMetaQuery, body.Query)
	if body.OperationName != "" {
		kv.Set(graphqlMetaOperationName, body.OperationName)
	}
	if body.Extensions != nil {
		kv.Set(graphqlMetaExtensions, body.Extensions)
	}

	hasVariables := body.Variables != nil
	if hasVariables {
		kv.Set(graphqlMetaHasVariables, true)
		for key, value := range *body.Variables {
			kv.Set(key, value)
		}
	}

	// Inline arguments are only exposed when variables are absent; otherwise
	// variables are the stable fuzz surface (and rewrites stay in JSON).
	if !hasVariables {
		for key, value := range collectInlineArguments(doc) {
			if kv.Get(key) != nil {
				continue
			}
			kv.Set(key, value)
		}
	}
	return kv, nil
}

// Encode rebuilds a GraphQL HTTP JSON body from fuzzed KV values.
func (g *Graphql) Encode(data KV) (string, error) {
	queryVal := data.Get(graphqlMetaQuery)
	if queryVal == nil {
		return "", fmt.Errorf("graphql query metadata missing")
	}
	query := types.ToString(queryVal)

	body := graphQLHTTPBody{Query: query}
	if op := data.Get(graphqlMetaOperationName); op != nil {
		body.OperationName = types.ToString(op)
	}
	if extensions, ok := data.Get(graphqlMetaExtensions).(json.Message); ok {
		body.Extensions = extensions
	}

	hasVariables, _ := data.Get(graphqlMetaHasVariables).(bool)
	if hasVariables {
		variables := make(map[string]any)
		body.Variables = &variables
		data.Iterate(func(key string, value any) bool {
			if strings.HasPrefix(key, "#_") {
				return true
			}
			variables[key] = value
			return true
		})
	} else {
		doc, err := parseQueryAST(query)
		if err != nil {
			return "", fmt.Errorf("could not parse graphql query: %w", err)
		}
		data.Iterate(func(key string, value any) bool {
			if strings.HasPrefix(key, "#_") {
				return true
			}
			applyInlineArgument(doc, key, value)
			return true
		})
		body.Query = types.ToString(printer.Print(doc))
	}

	encoded, err := json.Marshal(body)
	if err != nil {
		return "", err
	}
	return string(encoded), nil
}

func collectInlineArguments(doc *ast.Document) map[string]any {
	args := make(map[string]any)
	for _, ref := range inlineArgumentRefs(doc) {
		if containsVariable(ref.argument.Value) {
			continue
		}
		args[ref.key] = astValueToGo(ref.argument.Value)
	}
	return args
}

func applyInlineArgument(doc *ast.Document, key string, value any) {
	for _, ref := range inlineArgumentRefs(doc) {
		if ref.key == key && !containsVariable(ref.argument.Value) {
			ref.argument.Value = goValueToAST(value, ref.argument.Value)
			return
		}
	}
}

func containsVariable(value ast.Value) bool {
	switch typed := value.(type) {
	case *ast.Variable:
		return true
	case *ast.ListValue:
		for _, item := range typed.Values {
			if containsVariable(item) {
				return true
			}
		}
	case *ast.ObjectValue:
		for _, field := range typed.Fields {
			if containsVariable(field.Value) {
				return true
			}
		}
	}
	return false
}

type inlineArgumentRef struct {
	key      string
	path     string
	argument *ast.Argument
}

func inlineArgumentRefs(doc *ast.Document) []inlineArgumentRef {
	var refs []inlineArgumentRef
	walkFields(doc, func(path string, field *ast.Field) {
		for _, argument := range field.Arguments {
			if argument.Name == nil {
				continue
			}
			refs = append(refs, inlineArgumentRef{
				path:     path,
				argument: argument,
			})
		}
	})

	counts := make(map[string]int)
	for _, ref := range refs {
		counts[ref.argument.Name.Value]++
	}
	for index := range refs {
		name := refs[index].argument.Name.Value
		refs[index].key = name
		if counts[name] > 1 {
			refs[index].key = refs[index].path + "." + name
		}
	}

	keyCounts := make(map[string]int)
	for _, ref := range refs {
		keyCounts[ref.key]++
	}
	keyIndexes := make(map[string]int)
	for index := range refs {
		key := refs[index].key
		keyIndexes[key]++
		if keyCounts[key] > 1 {
			refs[index].key = fmt.Sprintf("%s[%d]", key, keyIndexes[key])
		}
	}
	return refs
}

func walkFields(doc *ast.Document, fn func(string, *ast.Field)) {
	if doc == nil {
		return
	}
	for _, def := range doc.Definitions {
		switch typed := def.(type) {
		case *ast.OperationDefinition:
			prefix := ""
			if typed.Name != nil {
				prefix = typed.Name.Value
			}
			walkSelectionSet(typed.SelectionSet, prefix, fn)
		case *ast.FragmentDefinition:
			prefix := "fragment"
			if typed.Name != nil {
				prefix += "." + typed.Name.Value
			}
			walkSelectionSet(typed.SelectionSet, prefix, fn)
		}
	}
}

func walkSelectionSet(set *ast.SelectionSet, parentPath string, fn func(string, *ast.Field)) {
	if set == nil {
		return
	}

	fieldCounts := make(map[string]int)
	for _, selection := range set.Selections {
		if field, ok := selection.(*ast.Field); ok {
			fieldCounts[fieldResponseName(field)]++
		}
	}
	fieldIndexes := make(map[string]int)

	for _, selection := range set.Selections {
		switch typed := selection.(type) {
		case *ast.Field:
			name := fieldResponseName(typed)
			fieldIndexes[name]++
			if fieldCounts[name] > 1 {
				name = fmt.Sprintf("%s[%d]", name, fieldIndexes[name])
			}
			path := name
			if parentPath != "" {
				path = parentPath + "." + name
			}
			fn(path, typed)
			walkSelectionSet(typed.SelectionSet, path, fn)
		case *ast.InlineFragment:
			walkSelectionSet(typed.SelectionSet, parentPath, fn)
		}
	}
}

func fieldResponseName(field *ast.Field) string {
	if field.Alias != nil {
		return field.Alias.Value
	}
	if field.Name != nil {
		return field.Name.Value
	}
	return "field"
}

func goValueToAST(value any, original ast.Value) ast.Value {
	if enum, ok := original.(*ast.EnumValue); ok && enum.Value == "null" && value == nil {
		return &ast.EnumValue{Kind: kinds.EnumValue, Value: "null"}
	}

	switch original.(type) {
	case *ast.IntValue:
		return &ast.IntValue{Kind: kinds.IntValue, Value: types.ToString(value)}
	case *ast.FloatValue:
		return &ast.FloatValue{Kind: kinds.FloatValue, Value: types.ToString(value)}
	case *ast.EnumValue:
		return &ast.EnumValue{Kind: kinds.EnumValue, Value: types.ToString(value)}
	case *ast.StringValue:
		return &ast.StringValue{Kind: kinds.StringValue, Value: types.ToString(value)}
	}

	switch v := value.(type) {
	case string:
		return &ast.StringValue{Kind: kinds.StringValue, Value: v}
	case bool:
		return &ast.BooleanValue{Kind: kinds.BooleanValue, Value: v}
	case int:
		return &ast.IntValue{Kind: kinds.IntValue, Value: fmt.Sprintf("%d", v)}
	case int32:
		return &ast.IntValue{Kind: kinds.IntValue, Value: fmt.Sprintf("%d", v)}
	case int64:
		return &ast.IntValue{Kind: kinds.IntValue, Value: fmt.Sprintf("%d", v)}
	case float32:
		return &ast.FloatValue{Kind: kinds.FloatValue, Value: fmt.Sprintf("%v", v)}
	case float64:
		// JSON numbers decode as float64; keep integers looking like ints when possible.
		if v == float64(int64(v)) {
			return &ast.IntValue{Kind: kinds.IntValue, Value: fmt.Sprintf("%d", int64(v))}
		}
		return &ast.FloatValue{Kind: kinds.FloatValue, Value: fmt.Sprintf("%v", v)}
	case []any:
		originalList, _ := original.(*ast.ListValue)
		values := make([]ast.Value, 0, len(v))
		for index, item := range v {
			var originalItem ast.Value
			if originalList != nil && index < len(originalList.Values) {
				originalItem = originalList.Values[index]
			}
			values = append(values, goValueToAST(item, originalItem))
		}
		return &ast.ListValue{Kind: kinds.ListValue, Values: values}
	case map[string]any:
		originalObject, _ := original.(*ast.ObjectValue)
		fields := make([]*ast.ObjectField, 0, len(v))
		used := make(map[string]struct{}, len(v))
		if originalObject != nil {
			for _, field := range originalObject.Fields {
				if field.Name == nil {
					continue
				}
				name := field.Name.Value
				value, ok := v[name]
				if !ok {
					continue
				}
				fields = append(fields, &ast.ObjectField{
					Kind:  kinds.ObjectField,
					Name:  &ast.Name{Kind: kinds.Name, Value: name},
					Value: goValueToAST(value, field.Value),
				})
				used[name] = struct{}{}
			}
		}

		names := make([]string, 0, len(v)-len(used))
		for name := range v {
			if _, ok := used[name]; !ok {
				names = append(names, name)
			}
		}
		sort.Strings(names)

		for _, name := range names {
			fields = append(fields, &ast.ObjectField{
				Kind:  kinds.ObjectField,
				Name:  &ast.Name{Kind: kinds.Name, Value: name},
				Value: goValueToAST(v[name], nil),
			})
		}
		return &ast.ObjectValue{Kind: kinds.ObjectValue, Fields: fields}
	default:
		return &ast.StringValue{Kind: kinds.StringValue, Value: types.ToString(v)}
	}
}

func astValueToGo(value ast.Value) any {
	switch v := value.(type) {
	case *ast.StringValue:
		return v.Value
	case *ast.IntValue:
		return v.Value
	case *ast.FloatValue:
		return v.Value
	case *ast.BooleanValue:
		return v.Value
	case *ast.EnumValue:
		if v.Value == "null" {
			return nil
		}
		return v.Value
	case *ast.ListValue:
		out := make([]any, 0, len(v.Values))
		for _, item := range v.Values {
			out = append(out, astValueToGo(item))
		}
		return out
	case *ast.ObjectValue:
		out := make(map[string]any, len(v.Fields))
		for _, field := range v.Fields {
			if field.Name == nil {
				continue
			}
			out[field.Name.Value] = astValueToGo(field.Value)
		}
		return out
	default:
		return nil
	}
}

package dataformat

import (
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// JSON is a JSON encoder
//
// For now JSON only supports objects as the root data type
// and not arrays
//
// TODO: Support arrays + other JSON oddities by
// adding more attributes to the map[string]interface{}
type JSON struct{}

var (
	_ DataFormat = &JSON{}
)

// NewJSON returns a new JSON encoder
func NewJSON() *JSON {
	return &JSON{}
}

// IsType returns true if the data is JSON encoded
func (j *JSON) IsType(data string) bool {
	return strings.HasPrefix(data, "{") && strings.HasSuffix(data, "}")
}

// Encode encodes the data into JSON format
func (j *JSON) Encode(data KV) (string, error) {
	encoded, err := json.Marshal(data.Map)
	return string(encoded), err
}

// Decode decodes the data from JSON format
func (j *JSON) Decode(data string) (KV, error) {
	var decoded map[string]interface{}
	err := json.Unmarshal([]byte(data), &decoded)
	return KVMap(decoded), err
}

// Name returns the name of the encoder
func (j *JSON) Name() string {
	return JSONDataFormat
}

package dataformat

import (
	"maps"

	mapsutil "github.com/projectdiscovery/utils/maps"
)

// KV is a key-value struct
// that is implemented or used by fuzzing package
// to represent a key-value pair
// sometimes order or key-value pair is important (query params)
// so we use ordered map to represent the data
// if it's not important/significant (ex: json,xml) we use map
// this also allows us to iteratively implement ordered map
type KV struct {
	Map        mapsutil.Map[string, any]
	OrderedMap *mapsutil.OrderedMap[string, any]
}

// Clones the current state of the KV struct
func (kv *KV) Clone() KV {
	newKV := KV{}
	if kv.OrderedMap == nil {
		newKV.Map = maps.Clone(kv.Map)
		return newKV
	}
	clonedOrderedMap := kv.OrderedMap.Clone()
	newKV.OrderedMap = &clonedOrderedMap
	return newKV
}

// IsNIL returns true if the KV struct is nil
func (kv *KV) IsNIL() bool {
	return kv.Map == nil && kv.OrderedMap == nil
}

// IsOrderedMap returns true if the KV struct is an ordered map
func (kv *KV) IsOrderedMap() bool {
	return kv.OrderedMap != nil
}

// Set sets a value in the KV struct
func (kv *KV) Set(key string, value any) {
	if kv.OrderedMap != nil {
		kv.OrderedMap.Set(key, value)
		return
	}
	if kv.Map == nil {
		kv.Map = make(map[string]interface{})
	}
	kv.Map[key] = value
}

// Get gets a value from the KV struct
func (kv *KV) Get(key string) interface{} {
	if kv.OrderedMap != nil {
		value, ok := kv.OrderedMap.Get(key)
		if !ok {
			return nil
		}
		return value
	}
	return kv.Map[key]
}

// Iterate iterates over the KV struct in insertion order
func (kv *KV) Iterate(f func(key string, value any) bool) {
	if kv.OrderedMap != nil {
		kv.OrderedMap.Iterate(func(key string, value any) bool {
			return f(key, value)
		})
		return
	}
	for key, value := range kv.Map {
		if !f(key, value) {
			break
		}
	}
}

// Delete deletes a key from the KV struct
func (kv *KV) Delete(key string) bool {
	if kv.OrderedMap != nil {
		_, ok := kv.OrderedMap.Get(key)
		if !ok {
			return false
		}
		kv.OrderedMap.Delete(key)
		return true
	}
	_, ok := kv.Map[key]
	if !ok {
		return false
	}
	delete(kv.Map, key)
	return true
}

// KVMap returns a new KV struct with the given map
func KVMap(data map[string]interface{}) KV {
	return KV{Map: data}
}

// KVOrderedMap returns a new KV struct with the given ordered map
func KVOrderedMap(data *mapsutil.OrderedMap[string, any]) KV {
	return KV{OrderedMap: data}
}

// ToMap converts the ordered map to a map
func ToMap(m *mapsutil.OrderedMap[string, any]) map[string]interface{} {
	data := make(map[string]interface{})
	m.Iterate(func(key string, value any) bool {
		data[key] = value
		return true
	})
	return data
}

// ToOrderedMap converts the map to an ordered map
func ToOrderedMap(data map[string]interface{}) *mapsutil.OrderedMap[string, any] {
	m := mapsutil.NewOrderedMap[string, any]()
	for key, value := range data {
		m.Set(key, value)
	}
	return &m
}

package dataformat

import (
	"bytes"
	"fmt"
	"io"
	"mime"
	"mime/multipart"
	"net/textproto"

	mapsutil "github.com/projectdiscovery/utils/maps"
)

type MultiPartForm struct {
	boundary      string
	filesMetadata map[string]FileMetadata
}

type FileMetadata struct {
	ContentType string
	Filename    string
}

var (
	_ DataFormat = &MultiPartForm{}
)

// NewMultiPartForm returns a new MultiPartForm encoder
func NewMultiPartForm() *MultiPartForm {
	return &MultiPartForm{
		filesMetadata: make(map[string]FileMetadata),
	}
}

// SetFileMetadata sets the file metadata for a given field name
func (m *MultiPartForm) SetFileMetadata(fieldName string, metadata FileMetadata) {
	if m.filesMetadata == nil {
		m.filesMetadata = make(map[string]FileMetadata)
	}

	m.filesMetadata[fieldName] = metadata
}

// GetFileMetadata gets the file metadata for a given field name
func (m *MultiPartForm) GetFileMetadata(fieldName string) (FileMetadata, bool) {
	if m.filesMetadata == nil {
		return FileMetadata{}, false
	}

	metadata, exists := m.filesMetadata[fieldName]

	return metadata, exists
}

// IsType returns true if the data is MultiPartForm encoded
func (m *MultiPartForm) IsType(data string) bool {
	// This method should be implemented to detect if the data is multipart form encoded
	return false
}

// Encode encodes the data into MultiPartForm format
func (m *MultiPartForm) Encode(data KV) (string, error) {
	var b bytes.Buffer
	w := multipart.NewWriter(&b)
	if err := w.SetBoundary(m.boundary); err != nil {
		return "", err
	}

	var Itererr error
	data.Iterate(func(key string, value any) bool {
		var fw io.Writer
		var err error

		if fileMetadata, ok := m.filesMetadata[key]; ok {
			if filesArray, isArray := value.([]any); isArray {
				for _, file := range filesArray {
					h := make(textproto.MIMEHeader)
					h.Set("Content-Disposition",
						fmt.Sprintf(`form-data; name=%q; filename=%q`,
							key, fileMetadata.Filename))
					h.Set("Content-Type", fileMetadata.ContentType)

					if fw, err = w.CreatePart(h); err != nil {
						Itererr = err
						return false
					}

					if _, err = fw.Write([]byte(file.(string))); err != nil {
						Itererr = err
						return false
					}
				}

				return true
			}
		}

		// Add field
		var values []string
		switch v := value.(type) {
		case nil:
			values = []string{""}
		case string:
			values = []string{v}
		case []string:
			values = v
		case []any:
			values = make([]string, len(v))
			for i, item := range v {
				if item == nil {
					values[i] = ""
				} else {
					values[i] = fmt.Sprint(item)
				}
			}
		default:
			values = []string{fmt.Sprintf("%v", v)}
		}

		for _, val := range values {
			if fw, err = w.CreateFormField(key); err != nil {
				Itererr = err
				return false
			}
			if _, err = fw.Write([]byte(val)); err != nil {
				Itererr = err
				return false
			}
		}
		return true
	})
	if Itererr != nil {
		return "", Itererr
	}

	_ = w.Close()
	return b.String(), nil
}

// ParseBoundary parses the boundary from the content type
func (m *MultiPartForm) ParseBoundary(contentType string) error {
	_, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		return err
	}
	m.boundary = params["boundary"]
	if m.boundary == "" {
		return fmt.Errorf("no boundary found in the content type")
	}

	// NOTE(dwisiswant0): boundary cannot exceed 70 characters according to
	// RFC-2046.
	if len(m.boundary) > 70 {
		return fmt.Errorf("boundary exceeds maximum length of 70 characters")
	}

	return nil
}

// Decode decodes the data from MultiPartForm format
func (m *MultiPartForm) Decode(data string) (KV, error) {
	if m.boundary == "" {
		return KV{}, fmt.Errorf("boundary not set, call ParseBoundary first")
	}

	// Create a buffer from the string data
	b := bytes.NewBufferString(data)
	r := multipart.NewReader(b, m.boundary)

	form, err := r.ReadForm(32 << 20) // 32MB is the max memory used to parse the form
	if err != nil {
		return KV{}, err
	}
	defer func() {
		_ = form.RemoveAll()
	}()

	result := mapsutil.NewOrderedMap[string, any]()
	for key, values := range form.Value {
		if len(values) > 1 {
			result.Set(key, values)
		} else {
			result.Set(key, values[0])
		}
	}

	if m.filesMetadata == nil {
		m.filesMetadata = make(map[string]FileMetadata)
	}

	for key, files := range form.File {
		fileContents := []interface{}{}
		var fileMetadataList []FileMetadata

		for _, fileHeader := range files {
			file, err := fileHeader.Open()
			if err != nil {
				return KV{}, err
			}

			buffer := new(bytes.Buffer)
			if _, err := buffer.ReadFrom(file); err != nil {
				_ = file.Close()

				return KV{}, err
			}
			_ = file.Close()

			fileContents = append(fileContents, buffer.String())

			fileMetadataList = append(fileMetadataList, FileMetadata{
				ContentType: fileHeader.Header.Get("Content-Type"),
				Filename:    fileHeader.Filename,
			})
		}

		result.Set(key, fileContents)

		// NOTE(dwisiswant0): store the first file's metadata instead of the
		// last one
		if len(fileMetadataList) > 0 {
			m.filesMetadata[key] = fileMetadataList[0]
		}
	}
	return KVOrderedMap(&result), nil
}

// Name returns the name of the encoder
func (m *MultiPartForm) Name() string {
	return "multipart/form-data"
}

package dataformat

import (
	"testing"

	mapsutil "github.com/projectdiscovery/utils/maps"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestMultiPartFormEncode(t *testing.T) {
	tests := []struct {
		name     string
		fields   map[string]any
		wantErr  bool
		expected map[string]any
	}{
		{
			name: "duplicate fields ([]string) - checkbox scenario",
			fields: map[string]any{
				"interests": []string{"sports", "music", "reading"},
				"colors":    []string{"red", "blue"},
			},
			expected: map[string]any{
				"interests": []string{"sports", "music", "reading"},
				"colors":    []string{"red", "blue"},
			},
		},
		{
			name: "single string fields - backward compatibility",
			fields: map[string]any{
				"username": "john",
				"email":    "john@example.com",
			},
			expected: map[string]any{
				"username": "john",
				"email":    "john@example.com",
			},
		},
		{
			name: "mixed types",
			fields: map[string]any{
				"string":     "text",
				"array":      []string{"item1", "item2"},
				"number":     42,                            // tests fmt.Sprint fallback
				"float":      3.14,                          // tests float conversion
				"boolean":    true,                          // tests boolean conversion
				"zero":       0,                             // tests zero value
				"emptyStr":   "",                            // tests empty string
				"negative":   -123,                          // tests negative number
				"nil":        nil,                           // tests nil value
				"mixedArray": []any{"str", 123, false, nil}, // tests mixed type array
			},
			expected: map[string]any{
				"string":     "text",
				"array":      []string{"item1", "item2"},
				"number":     "42",                                // numbers are converted to strings in multipart
				"float":      "3.14",                              // floats are converted to strings
				"boolean":    "true",                              // booleans are converted to strings
				"zero":       "0",                                 // zero value converted to string
				"emptyStr":   "",                                  // empty string remains empty
				"negative":   "-123",                              // negative numbers converted to strings
				"nil":        "",                                  // nil values converted to "" string
				"mixedArray": []string{"str", "123", "false", ""}, // mixed array converted to string array
			},
		},
		{
			name: "empty array - should not appear in output",
			fields: map[string]any{
				"emptyArray":  []string{},
				"normalField": "value",
			},
			expected: map[string]any{
				"normalField": "value",
				// emptyArray should not appear in decoded output
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			defer func() {
				if r := recover(); r != nil {
					t.Errorf("Test panicked: %v", r)
				}
			}()

			form := NewMultiPartForm()
			form.boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW"

			kv := mapsutil.NewOrderedMap[string, any]()
			for k, v := range tt.fields {
				kv.Set(k, v)
			}

			encoded, err := form.Encode(KVOrderedMap(&kv))

			if tt.wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)

			// Decode the encoded multipart data
			decoded, err := form.Decode(encoded)
			require.NoError(t, err)

			// Compare decoded values with expected values
			for expectedKey, expectedValue := range tt.expected {
				actualValue := decoded.Get(expectedKey)
				switch expected := expectedValue.(type) {
				case []string:
					actual, ok := actualValue.([]string)
					require.True(t, ok, "Expected []string for key %s, got %T", expectedKey, actualValue)
					assert.ElementsMatch(t, expected, actual, "Values mismatch for key %s", expectedKey)
				case []any:
					actual, ok := actualValue.([]any)
					require.True(t, ok, "Expected []any for key %s, got %T", expectedKey, actualValue)
					assert.ElementsMatch(t, expected, actual, "Values mismatch for key %s", expectedKey)
				case string:
					actual, ok := actualValue.(string)
					require.True(t, ok, "Expected string for key %s, got %T", expectedKey, actualValue)
					assert.Equal(t, expected, actual, "Values mismatch for key %s", expectedKey)
				default:
					assert.Equal(t, expected, actualValue, "Values mismatch for key %s", expectedKey)
				}
			}

			// Ensure no unexpected keys are present in decoded output
			decoded.Iterate(func(key string, value any) bool {
				_, exists := tt.expected[key]
				assert.True(t, exists, "Unexpected key %s found in decoded output", key)
				return true
			})

			t.Logf("Encoded output:\n%s", encoded)
		})
	}
}

func TestMultiPartFormRoundTrip(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Errorf("Test panicked: %v", r)
		}
	}()

	form := NewMultiPartForm()
	form.boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW"

	original := mapsutil.NewOrderedMap[string, any]()
	original.Set("username", "john")
	original.Set("interests", []string{"sports", "music", "reading"})

	encoded, err := form.Encode(KVOrderedMap(&original))
	require.NoError(t, err)

	decoded, err := form.Decode(encoded)
	require.NoError(t, err)

	assert.Equal(t, "john", decoded.Get("username"))
	assert.ElementsMatch(t, []string{"sports", "music", "reading"}, decoded.Get("interests"))

	t.Logf("Encoded output:\n%s", encoded)
}

func TestMultiPartFormFileUpload(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Errorf("Test panicked: %v", r)
		}
	}()

	// Test decoding of a manually crafted multipart form with files
	form := NewMultiPartForm()
	form.boundary = "----WebKitFormBoundaryFileUploadTest"

	// Manually craft a multipart form with file uploads
	multipartData := `------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="name"

John Doe
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="email"

john@example.com
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="profile_picture"; filename="profile.jpg"
Content-Type: image/jpeg

fake_jpeg_binary_data_here
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="documents"; filename="resume.pdf"
Content-Type: application/pdf

fake_pdf_content_1
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="documents"; filename="cover_letter.pdf"
Content-Type: application/pdf

fake_pdf_content_2
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="skills"

Go
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="skills"

JavaScript
------WebKitFormBoundaryFileUploadTest
Content-Disposition: form-data; name="skills"

Python
------WebKitFormBoundaryFileUploadTest--
`

	// Test decoding
	decoded, err := form.Decode(multipartData)
	require.NoError(t, err)

	// Verify regular fields
	assert.Equal(t, "John Doe", decoded.Get("name"))
	assert.Equal(t, "john@example.com", decoded.Get("email"))
	assert.Equal(t, []string{"Go", "JavaScript", "Python"}, decoded.Get("skills"))

	// Verify file fields
	profilePicture := decoded.Get("profile_picture")
	require.NotNil(t, profilePicture)
	profileArray, ok := profilePicture.([]interface{})
	require.True(t, ok, "Expected []interface{} for profile_picture")
	require.Len(t, profileArray, 1)
	assert.Equal(t, "fake_jpeg_binary_data_here", profileArray[0])

	documents := decoded.Get("documents")
	require.NotNil(t, documents)
	documentsArray, ok := documents.([]interface{})
	require.True(t, ok, "Expected []interface{} for documents")
	require.Len(t, documentsArray, 2)
	assert.Contains(t, documentsArray, "fake_pdf_content_1")
	assert.Contains(t, documentsArray, "fake_pdf_content_2")
}

