)

var (
	ErrRuleNotApplicable = errkit.New("rule not applicable")
)

// IsErrRuleNotApplicable checks if an error is due to rule not applicable
func IsErrRuleNotApplicable(err error) bool {
	if err == nil {
		return false
	}
	if strings.Contains(err.Error(), "rule not applicable") {
		return true
	}
	return false
}

// ExecuteRuleInput is the input for rule Execute function
type ExecuteRuleInput struct {
	// Input is the context args input
	Input *contextargs.Context
	// Callback is the callback for generated rule requests
	Callback func(GeneratedRequest) bool
	// InteractURLs contains interact urls for execute call
	InteractURLs []string
	// Values contains dynamic values for the rule
	Values map[string]interface{}
	// BaseRequest is the base http request for fuzzing rule
	BaseRequest *retryablehttp.Request
	// DisplayFuzzPoints is a flag to display fuzz points
	DisplayFuzzPoints bool

	// ApplyPayloadInitialTransformation is an optional function
	// to transform the payload initially based on analyzer rules
	ApplyPayloadInitialTransformation func(string, map[string]interface{}) string
	AnalyzerParams                    map[string]interface{}
}

// GeneratedRequest is a single generated request for rule
type GeneratedRequest struct {
	// Request is the http request for rule
	Request *retryablehttp.Request
	// InteractURLs is the list of interactsh urls
	InteractURLs []string
	// DynamicValues contains dynamic values map
	DynamicValues map[string]interface{}
	// Component is the component for the request
	Component component.Component
	// Parameter being fuzzed
	Parameter string

	// Key is the key for the request
	Key string
	// FuzzedKeys contains the keys under test, including multiple mode.
	FuzzedKeys []string
	// Value is the value for the request
	Value string
	// OriginalValue is the original value for the request
	OriginalValue string
	// OriginalPayload is the original payload for the request
	OriginalPayload string
}

// Execute executes a fuzzing rule accepting a callback on which
// generated requests are returned.
//
// Input is not thread safe and should not be shared between concurrent
// goroutines.
func (rule *Rule) Execute(input *ExecuteRuleInput) (err error) {
	if !rule.isInputURLValid(input.Input) {
		return errkit.Newf("rule not applicable: invalid input url: %v", input.Input.MetaInput.Input)
	}
	if input.BaseRequest == nil && input.Input.MetaInput.ReqResp == nil {
		return errkit.Newf("rule not applicable: both base request and reqresp are nil for %v", input.Input.MetaInput.Input)
	}

	var finalComponentList []component.Component
	// match rule part with component name
	displayDebugFuzzPoints := make(map[string]map[string]string)
	for _, componentName := range component.Components {
		if rule.Part != componentName && !sliceutil.Contains(rule.Parts, componentName) && rule.partType != requestPartType {
			continue
		}
		component := component.New(componentName)
		discovered, err := component.Parse(input.BaseRequest)
		if err != nil {
			gologger.Verbose().Msgf("Could not parse component %s: %s\n", componentName, err)
			continue
		}
		if !discovered {
			continue
		}

		// check rule applicable on this component
		if !rule.checkRuleApplicableOnComponent(component) {
			continue
		}
		// Debugging display for fuzz points
		if input.DisplayFuzzPoints {
			displayDebugFuzzPoints[componentName] = make(map[string]string)
			_ = component.Iterate(func(key string, value interface{}) error {
				displayDebugFuzzPoints[componentName][key] = fmt.Sprintf("%v", value)
				return nil
			})
		}

		if rule.options.FuzzStatsDB != nil {
			_ = component.Iterate(func(key string, value interface{}) error {
				rule.options.FuzzStatsDB.RecordComponentEvent(fuzzStats.ComponentEvent{
					URL:           input.Input.MetaInput.Target(),
					ComponentType: componentName,
					ComponentName: fmt.Sprintf("%v", value),
				})
				return nil
			})
		}

		finalComponentList = append(finalComponentList, component)
	}
	if len(displayDebugFuzzPoints) > 0 {
		marshalled, _ := json.MarshalIndent(displayDebugFuzzPoints, "", "  ")
		gologger.Info().Msgf("[%s] Fuzz points for %s [%s]\n%s\n", rule.options.TemplateID, input.Input.MetaInput.Input, input.BaseRequest.Method, string(marshalled))
	}

	if len(finalComponentList) == 0 {
		return errkit.Newf("rule not applicable: no component matched on this rule")
	}

	baseValues := input.Values
	baseInteractURLs := append([]string(nil), input.InteractURLs...)
	if rule.generator == nil {
		for _, component := range finalComponentList {
			optionVars := rule.options.Options.Vars.AsMap()
			constants := rule.options.Constants
			dataValues := rule.options.NewVariablesScope(baseValues, optionVars, constants)
			// Render variables once, allocating their interactsh URLs. The
			// output may contain runtime data, so it is never rendered again.
			evaluation := rule.options.Variables.EvaluateWithInteractshScope(dataValues, rule.options.Interactsh)
			input.Values = generators.MergeMaps(evaluation.Values, baseValues, optionVars, constants)
			input.InteractURLs = mergeInteractURLs(baseInteractURLs, evaluation.InteractURLs)

			err := rule.executeRuleValues(input, component)
			if err != nil {
				return err
			}
		}
		return nil
	}
mainLoop:
	for _, component := range finalComponentList {
		iterator := rule.generator.NewIterator()
		for {
			values, next := iterator.Value()
			if !next {
				continue mainLoop
			}
			var interactURLs []string
			input.Values, interactURLs = rule.prepareGeneratorValues(values, baseValues)
			input.InteractURLs = mergeInteractURLs(baseInteractURLs, interactURLs)

			if err := rule.executeRuleValues(input, component); err != nil {
				if err == io.EOF {
					return nil
				}
				gologger.Warning().Msgf("[%s] Could not execute rule: %s\n", rule.options.TemplateID, err)
				return err
			}
		}
	}
	return nil
}

func mergeInteractURLs(base, urls []string) []string {
	if len(base)+len(urls) == 0 {
		return nil
	}

	merged := make([]string, 0, len(base)+len(urls))
	seen := make(map[string]struct{}, len(base)+len(urls))

	for _, url := range base {
		if _, ok := seen[url]; ok {
			continue
		}

		seen[url] = struct{}{}
		merged = append(merged, url)
	}

	for _, url := range urls {
		if _, ok := seen[url]; ok {
			continue
		}

		seen[url] = struct{}{}
		merged = append(merged, url)
	}

	return merged
}

func (rule *Rule) prepareGeneratorValues(values, baseValues map[string]interface{}) (map[string]interface{}, []string) {
	optionVars := rule.options.Options.Vars.AsMap()
	constants := rule.options.Constants
	evaluationValues := rule.options.NewVariablesScope(values, baseValues, optionVars, constants)
	evaluation := rule.options.Variables.EvaluateWithInteractshScope(evaluationValues, rule.options.Interactsh)
	evaluatedValues, interactURLs := evaluation.Values, evaluation.InteractURLs
	inputValues, dataKeys := mergeFuzzValueLayers(
		fuzzValueLayer{values: evaluatedValues, kind: fuzzValueData},
		fuzzValueLayer{values: values, kind: fuzzValueTemplate},
		fuzzValueLayer{values: baseValues, kind: fuzzValueData},
		fuzzValueLayer{values: optionVars, kind: fuzzValueData},
		fuzzValueLayer{values: constants, kind: fuzzValueData},
	)

	// Generator values are template-authored payload definitions until this
	// render. Rendered variables, runtime/base, CLI option, and constant
	// values remain data. Payloads layer over variables so a payload that
	// shares a variable's name is still rendered.
	return rule.evaluateVarsWithInteractsh(inputValues, interactURLs, dataKeys)
}

type fuzzValueKind uint8

const (
	fuzzValueTemplate fuzzValueKind = iota
	fuzzValueData
)

type fuzzValueLayer struct {
	values map[string]interface{}
	kind   fuzzValueKind
}

func mergeFuzzValueLayers(layers ...fuzzValueLayer) (map[string]interface{}, map[string]struct{}) {
	size := 0
	for _, layer := range layers {
		size += len(layer.values)
	}

	values := make(map[string]interface{}, size)
	dataKeys := make(map[string]struct{})

	for _, layer := range layers {
		for key, value := range layer.values {
			values[key] = value
			if layer.kind == fuzzValueData {
				dataKeys[key] = struct{}{}
				continue
			}
			delete(dataKeys, key)
		}
	}

	if len(dataKeys) == 0 {
		return values, nil
	}

	return values, dataKeys
}

// evaluateVars evaluates variables in a string using available executor options
func (rule *Rule) evaluateVars(input string) (string, error) {
	if rule.options == nil {
		return input, nil
	}

	data := generators.MergeMaps(
		rule.options.Variables.GetAll(),
		rule.options.Constants,
		rule.options.Options.Vars.AsMap(),
	)

	exprs := expressions.FindExpressions(input, marker.ParenthesisOpen, marker.ParenthesisClose, data)

	err := expressions.ContainsUnresolvedVariables(exprs...)
	if err != nil {
		return input, err
	}

	result, err := render.Render(render.Input{
		Options: rule.options.GetOptions(),
		Text:    input,
		Values:  data,
	})
	if err != nil {
		return input, err
	}

	return result.Text, nil
}

// evaluateVarsWithInteractsh renders template-text values and leaves runtime data untouched.
func (rule *Rule) evaluateVarsWithInteractsh(data map[string]interface{}, interactshUrls []string, dataKeys map[string]struct{}) (map[string]interface{}, []string) {
	// Check if Interactsh options are configured
	if rule.options.Interactsh != nil {
		rendered := maps.Clone(data)

		interactshUrlsMap := make(map[string]struct{})
		for _, url := range interactshUrls {
			interactshUrlsMap[url] = struct{}{}
		}

		interactshUrls = mapsutil.GetKeys(interactshUrlsMap)

		// Render each template-text value against the unrendered input, so
		// the result does not depend on map iteration order.
		for k, v := range data {
			if _, ok := dataKeys[k]; ok {
				continue
			}

			got, err := render.Render(render.Input{
				Options:      rule.options.GetOptions(),
				Text:         fmt.Sprint(v),
				Values:       data,
				Interactsh:   rule.options.Interactsh,
				InteractURLs: interactshUrls,
			})
			if err == nil {
				rendered[k] = got.Text
				for _, url := range got.InteractURLs {
					if _, ok := interactshUrlsMap[url]; ok {
						continue
					}

					interactshUrlsMap[url] = struct{}{}
					interactshUrls = append(interactshUrls, url)
				}
			}
		}

		data = rendered
	}

	return data, interactshUrls
}

// isInputURLValid returns true if url is valid after parsing it
func (rule *Rule) isInputURLValid(input *contextargs.Context) bool {
	if input == nil || input.MetaInput == nil || input.MetaInput.Input == "" {
		return false
	}
	_, err := urlutil.Parse(input.MetaInput.Input)
	return err == nil
}

// executeRuleValues executes a rule with a set of values
func (rule *Rule) executeRuleValues(input *ExecuteRuleInput, ruleComponent component.Component) error {
	// if we are only fuzzing values
	if len(rule.Fuzz.Value) > 0 {
		for _, value := range rule.Fuzz.Value {
			originalPayload := value

			if err := rule.executePartRule(input, ValueOrKeyValue{Value: value, OriginalPayload: originalPayload}, ruleComponent); err != nil {
				if component.IsErrSetValue(err) {
					// this are errors due to format restrictions
					// ex: fuzzing string value in a json int field
					continue
				}

				return err
			}
		}

		return nil
	}

	// if we are fuzzing both keys and values
	if rule.Fuzz.KV != nil {
		var gotErr error

		rule.Fuzz.KV.Iterate(func(key, value string) bool {
			if err := rule.executePartRule(input, ValueOrKeyValue{Key: key, Value: value}, ruleComponent); err != nil {
				if component.IsErrSetValue(err) {
					// this are errors due to format restrictions
					// ex: fuzzing string value in a json int field
					return true
				}
				gotErr = err

				return false
			}

			return true
		})

		// if mode is multiple now build and execute it
		if rule.modeType == multipleModeType {
			var fuzzedKeys []string
			rule.Fuzz.KV.Iterate(func(key, value string) bool {
				var evaluated string
				var err error

				evaluated, input.InteractURLs, err = rule.executeEvaluate(input, key, "", value, input.InteractURLs)
				if err != nil {
					gotErr = err

					return false
				}

				if err := ruleComponent.SetValue(key, evaluated); err != nil {
					return true
				}
				fuzzedKeys = append(fuzzedKeys, key)

				return true
			})

			if gotErr != nil {
				return gotErr
			}

			req, err := ruleComponent.Rebuild()
			if err != nil {
				return err
			}

			if gotErr := rule.execWithInput(input, req, input.InteractURLs, ruleComponent, "", "", "", "", "", "", fuzzedKeys...); gotErr != nil {
				return gotErr
			}
		}

		return gotErr
	}

	// something else is wrong
	return fmt.Errorf("no fuzz values specified")
}

// Compile compiles a fuzzing rule and initializes it for operation
func (rule *Rule) Compile(generator *generators.PayloadGenerator, options *protocols.ExecutorOptions) error {
	// If a payload generator is specified from base request, use it
	// for payload values.
	if generator != nil {
		rule.generator = generator
	}
	rule.options = options

	// Resolve the default enums
	if rule.Mode != "" {
		if valueType, ok := stringToModeType[rule.Mode]; !ok {
			return errors.Errorf("invalid mode value specified: %s", rule.Mode)
		} else {
			rule.modeType = valueType
		}
	} else {
		rule.modeType = multipleModeType
	}
	if rule.Part != "" {
		if valueType, ok := stringToPartType[rule.Part]; !ok {
			return errors.Errorf("invalid part value specified: %s", rule.Part)
		} else {
			rule.partType = valueType
		}
	}
	if rule.Part == "" && len(rule.Parts) == 0 {
		return errors.Errorf("no part specified for rule")
	}

	if rule.Type != "" {
		if valueType, ok := stringToRuleType[rule.Type]; !ok {
			return errors.Errorf("invalid type value specified: %s", rule.Type)
		} else {
			rule.ruleType = valueType
		}
	} else {
		rule.ruleType = replaceRuleType
	}

	// Initialize other required regexes and maps
	if len(rule.Keys) > 0 {
		rule.keysMap = make(map[string]struct{})
	}

	// eval vars in "keys"
	for _, key := range rule.Keys {
		evaluatedKey, err := rule.evaluateVars(key)
		if err != nil {
			return errors.Wrap(err, "could not evaluate key")
		}

		rule.keysMap[strings.ToLower(evaluatedKey)] = struct{}{}
	}

	// eval vars in "values"
	for _, value := range rule.ValuesRegex {
		evaluatedValue, err := rule.evaluateVars(value)
		if err != nil {
			return errors.Wrap(err, "could not evaluate value regex")
		}

		compiled, err := regexp.Compile(evaluatedValue)
		if err != nil {
			return errors.Wrap(err, "could not compile value regex")
		}

		rule.valuesRegex = append(rule.valuesRegex, compiled)
	}

	// eval vars in "keys-regex"
	for _, value := range rule.KeysRegex {
		evaluatedValue, err := rule.evaluateVars(value)
		if err != nil {
			return errors.Wrap(err, "could not evaluate key regex")
		}

		compiled, err := regexp.Compile(evaluatedValue)
		if err != nil {
			return errors.Wrap(err, "could not compile key regex")
		}

		rule.keysRegex = append(rule.keysRegex, compiled)
	}

	if rule.ruleType != replaceRegexRuleType {
		if rule.ReplaceRegex != "" {
			return errors.Errorf("replace-regex is only applicable for replace and replace-regex rule types")
		}
	} else {
		if rule.ReplaceRegex == "" {
			return errors.Errorf("replace-regex is required for replace-regex rule type")
		}

		evalReplaceRegex, err := rule.evaluateVars(rule.ReplaceRegex)
		if err != nil {
			return errors.Wrap(err, "could not evaluate replace regex")
		}

		compiled, err := regexp.Compile(evalReplaceRegex)
		if err != nil {
			return errors.Wrap(err, "could not compile replace regex")
		}

		rule.replaceRegex = compiled
	}

	return nil
}

package fuzz

import (
	"sync"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/interactsh"
	"github.com/stretchr/testify/require"
)

func TestEvaluateVarsWithInteractsh_RaceCondition(t *testing.T) {
	rule := &Rule{}
	rule.options = &protocols.ExecutorOptions{
		Interactsh: &interactsh.Client{},
	}

	sharedData := map[string]interface{}{
		"var1": "value1",
		"var2": "{{var1}}_suffix",
		"var3": "prefix_{{var1}}",
	}

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			rule.evaluateVarsWithInteractsh(sharedData, nil, nil)
		}()
	}
	wg.Wait()
}

func TestEvaluateVarsWithInteractshDoesNotEvaluateRuntimeData(t *testing.T) {
	rule := &Rule{}
	rule.options = &protocols.ExecutorOptions{
		Interactsh: &interactsh.Client{},
	}
	data := map[string]interface{}{
		"from_response": "{{secret}}",
		"secret":        "leaked-secret",
	}

	got, urls := rule.evaluateVarsWithInteractsh(data, nil, map[string]struct{}{
		"from_response": {},
		"secret":        {},
	})

	require.Empty(t, urls)
	require.Equal(t, "{{secret}}", got["from_response"])
}

package fuzz

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"strings"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/disk"
	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz/component"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/interactsh"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/variables"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/stretchr/testify/require"
)

const (
	// requestBodyWithDSL is request data that looks like a DSL expression.
	requestBodyWithDSL = `PLAIN-{{to_upper("abc")}}-END`
	queryRuleTarget    = "http://127.0.0.1/echo?p=SEED"
)

// fakeInteractshClient hands out numbered URLs without contacting a server.
// Fuzz rules only allocate URLs through NewURLWithData, so the embedded nil
// IClient is never called.
type fakeInteractshClient struct {
	interactsh.IClient

	issued int
}

func (c *fakeInteractshClient) NewURLWithData(string) (string, error) {
	c.issued++

	return fmt.Sprintf("oast%d.example", c.issued), nil
}

// newQueryRule compiles a single-mode rule that replaces the p query value
// with fuzzValue.
func newQueryRule(
	t *testing.T,
	fuzzValue string,
	generator *generators.PayloadGenerator,
	templateVars variables.Variable,
	client interactsh.IClient,
) *Rule {
	t.Helper()

	rule := &Rule{
		Part: component.RequestQueryComponent,
		Type: "replace",
		Mode: "single",
		Fuzz: SliceOrMapSlice{Value: []string{fuzzValue}},
	}
	err := rule.Compile(generator, &protocols.ExecutorOptions{
		Variables:  templateVars,
		Options:    &types.Options{},
		Interactsh: client,
	})
	require.NoError(t, err)

	return rule
}

// executeQueryRule runs rule against queryRuleTarget and returns the generated
// requests.
func executeQueryRule(
	t *testing.T,
	rule *Rule,
	method string,
	body io.Reader,
	values map[string]any,
) []GeneratedRequest {
	t.Helper()

	req, err := retryablehttp.NewRequest(method, queryRuleTarget, body)
	require.NoError(t, err)

	var got []GeneratedRequest
	err = rule.Execute(&ExecuteRuleInput{
		Input:       contextargs.NewWithInput(context.Background(), queryRuleTarget),
		BaseRequest: req,
		Values:      values,
		Callback: func(gr GeneratedRequest) bool {
			got = append(got, gr)

			return true
		},
	})
	require.NoError(t, err)

	return got
}

// newRequestDataVariableRule returns a query rule whose template declares
// b: "{{body}}", so b captures request data.
func newRequestDataVariableRule(t *testing.T, fuzzValue string, payloads map[string]any) *Rule {
	t.Helper()

	templateVars := newFuzzTestVariables()
	templateVars.Set("b", "{{body}}")

	var generator *generators.PayloadGenerator

	if payloads != nil {
		var err error

		generator, err = generators.New(
			payloads, generators.BatteringRamAttack, "", disk.NewCatalog(""), "", types.DefaultOptions(),
		)
		require.NoError(t, err)
	}

	// The CLI creates an Interactsh client even with -no-interactsh.
	return newQueryRule(t, fuzzValue, generator, templateVars, &interactsh.Client{})
}

// fuzzedQueryValues runs rule against a POST request whose body is
// requestBodyWithDSL and returns the fuzzed p query value of each generated
// request.
func fuzzedQueryValues(t *testing.T, rule *Rule) []string {
	t.Helper()

	generated := executeQueryRule(t, rule, http.MethodPost, strings.NewReader(requestBodyWithDSL), map[string]any{
		"body": requestBodyWithDSL,
	})

	got := make([]string, 0, len(generated))
	for _, gr := range generated {
		got = append(got, gr.Request.URL.Query().Get("p"))
	}

	return got
}

func TestExecuteKeepsRequestDataInTemplateVariableLiteral(t *testing.T) {
	t.Parallel()

	t.Run("fuzz value", func(t *testing.T) {
		t.Parallel()

		rule := newRequestDataVariableRule(t, "{{b}}", nil)

		require.Equal(t, []string{requestBodyWithDSL}, fuzzedQueryValues(t, rule))
	})

	t.Run("payload value", func(t *testing.T) {
		t.Parallel()

		rule := newRequestDataVariableRule(t, "{{inj}}", map[string]any{
			"inj": []any{"{{b}}"},
		})

		// Each run iterates a fresh value map. Repeat so the result
		// cannot depend on map iteration order.
		for range 256 {
			require.Equal(t, []string{requestBodyWithDSL}, fuzzedQueryValues(t, rule))
		}
	})
}

func TestExecuteRendersTemplateVariableInteractshMarker(t *testing.T) {
	t.Parallel()

	templateVars := newFuzzTestVariables()
	templateVars.Set("marker", "{{interactsh-url}}")
	rule := newQueryRule(t, "{{marker}}", nil, templateVars, &fakeInteractshClient{})

	got := executeQueryRule(t, rule, http.MethodGet, nil, nil)

	require.Len(t, got, 1)
	require.Equal(t, []string{"oast1.example"}, got[0].InteractURLs)
	require.Equal(t, "oast1.example", got[0].Request.URL.Query().Get("p"))
}

func TestPrepareGeneratorValuesRendersPayloadSharingVariableName(t *testing.T) {
	t.Parallel()

	templateVars := newFuzzTestVariables()
	templateVars.Set("inj", "variable")

	rule := &Rule{
		options: &protocols.ExecutorOptions{
			Variables:  templateVars,
			Options:    &types.Options{},
			Interactsh: &fakeInteractshClient{},
		},
	}

	values, _ := rule.prepareGeneratorValues(map[string]any{
		"inj": `{{to_upper("payload")}}`,
	}, nil)

	require.Equal(t, "PAYLOAD", values["inj"])
}

func TestPrepareGeneratorValuesRendersPayloadsAgainstUnrenderedInput(t *testing.T) {
	t.Parallel()

	rule := &Rule{
		options: &protocols.ExecutorOptions{
			Variables:  newFuzzTestVariables(),
			Options:    &types.Options{},
			Interactsh: &interactsh.Client{},
		},
	}

	for range 256 {
		values, _ := rule.prepareGeneratorValues(map[string]any{
			"upper": `{{to_upper("x")}}`,
			"ref":   "{{upper}}",
		}, nil)

		require.Equal(t, "X", values["upper"])
		// ref sees the unrendered definition of upper as data.
		require.Equal(t, `{{to_upper("x")}}`, values["ref"])
	}
}

package frequency

import (
	"net"
	"net/url"
	"os"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/projectdiscovery/gcache"
	"github.com/projectdiscovery/gologger"
)

// Tracker implements a frequency tracker for a given input
// which is used to determine uninteresting input parameters
// which are not that interesting from fuzzing perspective for a template
// and target combination.
//
// This is used to reduce the number of requests made during fuzzing
// for parameters that are less likely to give results for a rule.
type Tracker struct {
	frequencies              gcache.Cache[string, *cacheItem]
	paramOccurrenceThreshold int

	isDebug bool
}

const (
	DefaultMaxTrackCount            = 10000
	DefaultParamOccurrenceThreshold = 10
)

type cacheItem struct {
	errors atomic.Int32
	sync.Once
}

// New creates a new frequency tracker with a given maximum
// number of params to track in LRU fashion with a max error threshold
func New(maxTrackCount, paramOccurrenceThreshold int) *Tracker {
	gc := gcache.New[string, *cacheItem](maxTrackCount).ARC().Build()

	var isDebug bool
	if os.Getenv("FREQ_DEBUG") != "" {
		isDebug = true
	}
	return &Tracker{
		isDebug:                  isDebug,
		frequencies:              gc,
		paramOccurrenceThreshold: paramOccurrenceThreshold,
	}
}

func (t *Tracker) Close() {
	t.frequencies.Purge()
}

// MarkParameter marks a parameter as frequently occurring once.
//
// The logic requires a parameter to be marked as frequently occurring
// multiple times before it's considered as frequently occurring.
func (t *Tracker) MarkParameter(parameter, target, template string) {
	normalizedTarget := normalizeTarget(target)
	key := getFrequencyKey(parameter, normalizedTarget, template)

	if t.isDebug {
		gologger.Verbose().Msgf("[%s] Marking %s as found uninteresting", template, key)
	}

	existingCacheItem, err := t.frequencies.GetIFPresent(key)
	if err != nil || existingCacheItem == nil {
		newItem := &cacheItem{errors: atomic.Int32{}}
		newItem.errors.Store(1)
		_ = t.frequencies.Set(key, newItem)
		return
	}
	existingCacheItem.errors.Add(1)

	_ = t.frequencies.Set(key, existingCacheItem)
}

// IsParameterFrequent checks if a parameter is frequently occurring
// in the input with no much results.
func (t *Tracker) IsParameterFrequent(parameter, target, template string) bool {
	normalizedTarget := normalizeTarget(target)
	key := getFrequencyKey(parameter, normalizedTarget, template)

	if t.isDebug {
		gologger.Verbose().Msgf("[%s] Checking if %s is frequently found uninteresting", template, key)
	}

	existingCacheItem, err := t.frequencies.GetIFPresent(key)
	if err != nil || existingCacheItem == nil {
		return false
	}

	if existingCacheItem.errors.Load() >= int32(t.paramOccurrenceThreshold) {
		existingCacheItem.Do(func() {
			gologger.Verbose().Msgf("[%s] Skipped %s from parameter for %s as found uninteresting %d times", template, parameter, target, existingCacheItem.errors.Load())
		})
		return true
	}
	return false
}

// UnmarkParameter unmarks a parameter as frequently occurring. This carries
// more weight and resets the frequency counter for the parameter causing
// it to be checked again. This is done when results are found.
func (t *Tracker) UnmarkParameter(parameter, target, template string) {
	normalizedTarget := normalizeTarget(target)
	key := getFrequencyKey(parameter, normalizedTarget, template)

	if t.isDebug {
		gologger.Verbose().Msgf("[%s] Unmarking %s as frequently found uninteresting", template, key)
	}

	_ = t.frequencies.Remove(key)
}

func getFrequencyKey(parameter, target, template string) string {
	var sb strings.Builder
	sb.WriteString(target)
	sb.WriteString(":")
	sb.WriteString(template)
	sb.WriteString(":")
	sb.WriteString(parameter)
	str := sb.String()
	return str
}

func normalizeTarget(value string) string {
	finalValue := value
	if strings.HasPrefix(value, "http") {
		if parsed, err := url.Parse(value); err == nil {
			hostname := parsed.Host
			finalPort := parsed.Port()
			if finalPort == "" {
				if parsed.Scheme == "https" {
					finalPort = "443"
				} else {
					finalPort = "80"
				}
				hostname = net.JoinHostPort(parsed.Host, finalPort)
			}
			finalValue = hostname
		}
	}
	return finalValue
}

package fuzz

import (
	"regexp"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
)

// Rule is a single rule which describes how to fuzz the request
type Rule struct {
	// description: |
	//   Type is the type of fuzzing rule to perform.
	//
	//   replace replaces the values entirely. prefix prefixes the value. postfix postfixes the value
	//   and infix places between the values.
	// values:
	//   - "replace"
	//   - "prefix"
	//   - "postfix"
	//   - "infix"
	Type     string `yaml:"type,omitempty" json:"type,omitempty" jsonschema:"title=type of rule,description=Type of fuzzing rule to perform,enum=replace,enum=prefix,enum=postfix,enum=infix,enum=replace-regex"`
	ruleType ruleType
	// description: |
	//   Part is the part of request to fuzz.
	// values:
	//   - "query"
	//   - "header"
	//   - "path"
	//   - "body"
	//   - "cookie"
	//   - "request"
	Part     string `yaml:"part,omitempty" json:"part,omitempty" jsonschema:"title=part of rule,description=Part of request rule to fuzz,enum=query,enum=header,enum=path,enum=body,enum=cookie,enum=request"`
	partType partType
	// description: |
	//   Parts is the list of parts to fuzz. If multiple parts need to be
	//   defined while excluding some, this should be used instead of singular part.
	// values:
	//   - "query"
	//   - "header"
	//   - "path"
	//   - "body"
	//   - "cookie"
	//   - "request"
	Parts []string `yaml:"parts,omitempty" json:"parts,omitempty" jsonschema:"title=parts of rule,description=Part of request rule to fuzz,enum=query,enum=header,enum=path,enum=body,enum=cookie,enum=request"`

	// description: |
	//   Mode is the mode of fuzzing to perform.
	//
	//   single fuzzes one value at a time. multiple fuzzes all values at same time.
	// values:
	//   - "single"
	//   - "multiple"
	Mode     string `yaml:"mode,omitempty" json:"mode,omitempty" jsonschema:"title=mode of rule,description=Mode of request rule to fuzz,enum=single,enum=multiple"`
	modeType modeType

	// description: |
	//   Keys is the optional list of key named parameters to fuzz.
	// examples:
	//   - name: Examples of keys
	//     value: >
	//       []string{"url", "file", "host"}
	Keys    []string `yaml:"keys,omitempty" json:"keys,omitempty" jsonschema:"title=keys of parameters to fuzz,description=Keys of parameters to fuzz"`
	keysMap map[string]struct{}
	// description: |
	//   KeysRegex is the optional list of regex key parameters to fuzz.
	// examples:
	//   - name: Examples of key regex
	//     value: >
	//       []string{"url.*"}
	KeysRegex []string `yaml:"keys-regex,omitempty" json:"keys-regex,omitempty" jsonschema:"title=keys regex to fuzz,description=Regex of parameter keys to fuzz"`
	keysRegex []*regexp.Regexp
	// description: |
	//   Values is the optional list of regex value parameters to fuzz.
	// examples:
	//   - name: Examples of value regex
	//     value: >
	//       []string{"https?://.*"}
	ValuesRegex []string `yaml:"values,omitempty" json:"values,omitempty" jsonschema:"title=values regex to fuzz,description=Regex of parameter values to fuzz"`
	valuesRegex []*regexp.Regexp

	// description: |
	//   Fuzz is the list of payloads to perform substitutions with.
	// examples:
	//   - name: Examples of fuzz
	//     value: >
	//       []string{"{{ssrf}}", "{{interactsh-url}}", "example-value"}
	//      or
	//       x-header: 1
	//       x-header: 2
	Fuzz SliceOrMapSlice `yaml:"fuzz,omitempty" json:"fuzz,omitempty" jsonschema:"title=payloads of fuzz rule,description=Payloads to perform fuzzing substitutions with"`
	// description: |
	//  replace-regex is regex for regex-replace rule type
	//  it is only required for replace-regex rule type
	// examples:
	//   - type: replace-regex
	//     replace-regex: "https?://.*"
	ReplaceRegex string         `yaml:"replace-regex,omitempty" json:"replace-regex,omitempty" jsonschema:"title=replace regex of rule,description=Regex for regex-replace rule type"`
	replaceRegex *regexp.Regexp `yaml:"-" json:"-"`
	options      *protocols.ExecutorOptions
	generator    *generators.PayloadGenerator
}

// ruleType is the type of rule enum declaration
type ruleType int

const (
	replaceRuleType ruleType = iota + 1
	prefixRuleType
	postfixRuleType
	infixRuleType
	replaceRegexRuleType
)

var stringToRuleType = map[string]ruleType{
	"replace":       replaceRuleType,
	"prefix":        prefixRuleType,
	"postfix":       postfixRuleType,
	"infix":         infixRuleType,
	"replace-regex": replaceRegexRuleType,
}

// partType is the part of rule enum declaration
type partType int

const (
	queryPartType partType = iota + 1
	headersPartType
	pathPartType
	bodyPartType
	cookiePartType
	requestPartType
)

var stringToPartType = map[string]partType{
	"query":   queryPartType,
	"header":  headersPartType,
	"path":    pathPartType,
	"body":    bodyPartType,
	"cookie":  cookiePartType,
	"request": requestPartType, // request means all request parts
}

// modeType is the mode of rule enum declaration
type modeType int

const (
	singleModeType modeType = iota + 1
	multipleModeType
)

var stringToModeType = map[string]modeType{
	"single":   singleModeType,
	"multiple": multipleModeType,
}

// matchKeyOrValue matches key value parameters with rule parameters
func (rule *Rule) matchKeyOrValue(key, value string) bool {
	if len(rule.keysMap) == 0 && len(rule.valuesRegex) == 0 && len(rule.keysRegex) == 0 {
		return true
	}
	if value != "" {
		for _, regex := range rule.valuesRegex {
			if regex.MatchString(value) {
				return true
			}
		}
	}
	if (len(rule.keysMap) > 0 || len(rule.keysRegex) > 0) && key != "" {
		if _, ok := rule.keysMap[strings.ToLower(key)]; ok {
			return true
		}
		for _, regex := range rule.keysRegex {
			if regex.MatchString(key) {
				return true
			}
		}
	}
	return false
}

package fuzz

import (
	"testing"

	"github.com/projectdiscovery/goflags"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/variables"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
	"github.com/stretchr/testify/require"
)

func TestRuleMatchKeyOrValue(t *testing.T) {
	rule := &Rule{
		Part: "query",
	}
	err := rule.Compile(nil, nil)
	require.NoError(t, err, "could not compile rule")

	result := rule.matchKeyOrValue("url", "")
	require.True(t, result, "could not get correct result")

	t.Run("key", func(t *testing.T) {
		rule := &Rule{Keys: []string{"url"}, Part: "query"}
		err := rule.Compile(nil, nil)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("url", "")
		require.True(t, result, "could not get correct result")
		result = rule.matchKeyOrValue("test", "")
		require.False(t, result, "could not get correct result")
	})
	t.Run("value", func(t *testing.T) {
		rule := &Rule{ValuesRegex: []string{`https?:\/\/?([-a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,6}\b)*(\/[\/\d\w\.-]*)*(?:[\?])*(.+)*`}, Part: "query"}
		err := rule.Compile(nil, nil)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("", "http://localhost:80")
		require.True(t, result, "could not get correct result")
		result = rule.matchKeyOrValue("test", "random")
		require.False(t, result, "could not get correct result")
	})
}

func TestEvaluateVariables(t *testing.T) {
	t.Run("keys", func(t *testing.T) {
		rule := &Rule{
			Keys: []string{"{{foo_var}}"},
			Part: "query",
		}

		// mock
		templateVars := variables.Variable{
			InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(1),
		}
		templateVars.Set("foo_var", "foo_var_value")

		constants := map[string]interface{}{
			"const_key": "const_value",
		}

		options := &types.Options{}

		// runtime vars (to simulate CLI)
		runtimeVars := goflags.RuntimeMap{}
		_ = runtimeVars.Set("runtime_key=runtime_value")
		options.Vars = runtimeVars

		executorOpts := &protocols.ExecutorOptions{
			Variables: templateVars,
			Constants: constants,
			Options:   options,
		}

		err := rule.Compile(nil, executorOpts)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("foo_var_value", "test_value")
		require.True(t, result, "should match evaluated variable key")

		result = rule.matchKeyOrValue("{{foo_var}}", "test_value")
		require.False(t, result, "should not match unevaluated variable key")
	})

	t.Run("keys-regex", func(t *testing.T) {
		rule := &Rule{
			KeysRegex: []string{"^{{foo_var}}"},
			Part:      "query",
		}

		templateVars := variables.Variable{
			InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(1),
		}
		templateVars.Set("foo_var", "foo_var_value")

		executorOpts := &protocols.ExecutorOptions{
			Variables: templateVars,
			Constants: map[string]interface{}{},
			Options:   &types.Options{},
		}

		err := rule.Compile(nil, executorOpts)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("foo_var_value", "test_value")
		require.True(t, result, "should match evaluated variable in regex")

		result = rule.matchKeyOrValue("other_key", "test_value")
		require.False(t, result, "should not match non-matching key")
	})

	t.Run("values-regex", func(t *testing.T) {
		rule := &Rule{
			ValuesRegex: []string{"{{foo_var}}"},
			Part:        "query",
		}

		templateVars := variables.Variable{
			InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(1),
		}
		templateVars.Set("foo_var", "test_pattern")

		executorOpts := &protocols.ExecutorOptions{
			Variables: templateVars,
			Constants: map[string]interface{}{},
			Options:   &types.Options{},
		}

		err := rule.Compile(nil, executorOpts)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("test_key", "test_pattern")
		require.True(t, result, "should match evaluated variable in values regex")

		result = rule.matchKeyOrValue("test_key", "other_value")
		require.False(t, result, "should not match non-matching value")
	})

	// complex vars w/ consts and runtime vars
	t.Run("complex-variables", func(t *testing.T) {
		rule := &Rule{
			Keys: []string{"{{template_var}}", "{{const_key}}", "{{runtime_key}}"},
			Part: "query",
		}

		templateVars := variables.Variable{
			InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(1),
		}
		templateVars.Set("template_var", "template_value")

		constants := map[string]interface{}{
			"const_key": "const_value",
		}

		options := &types.Options{}
		runtimeVars := goflags.RuntimeMap{}
		_ = runtimeVars.Set("runtime_key=runtime_value")
		options.Vars = runtimeVars

		executorOpts := &protocols.ExecutorOptions{
			Variables: templateVars,
			Constants: constants,
			Options:   options,
		}

		err := rule.Compile(nil, executorOpts)
		require.NoError(t, err, "could not compile rule")

		result := rule.matchKeyOrValue("template_value", "test")
		require.True(t, result, "should match template variable")

		result = rule.matchKeyOrValue("const_value", "test")
		require.True(t, result, "should match constant")

		result = rule.matchKeyOrValue("runtime_value", "test")
		require.True(t, result, "should match runtime variable")

		result = rule.matchKeyOrValue("{{template_var}}", "test")
		require.False(t, result, "should not match unevaluated template variable")
	})

	t.Run("invalid-variables", func(t *testing.T) {
		rule := &Rule{
			Keys: []string{"{{nonexistent_var}}"},
			Part: "query",
		}

		executorOpts := &protocols.ExecutorOptions{
			Variables: variables.Variable{
				InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(0),
			},
			Constants: map[string]interface{}{},
			Options:   &types.Options{},
		}

		err := rule.Compile(nil, executorOpts)
		if err != nil {
			require.Contains(t, err.Error(), "unresolved", "error should mention unresolved variables")
		} else {
			result := rule.matchKeyOrValue("some_key", "some_value")
			require.False(t, result, "should not match when variables are unresolved")
		}
	})

	t.Run("evaluateVars-function", func(t *testing.T) {
		rule := &Rule{}

		templateVars := variables.Variable{
			InsertionOrderedStringMap: *utils.NewEmptyInsertionOrderedStringMap(1),
		}
		templateVars.Set("test_var", "test_value")

		constants := map[string]interface{}{
			"const_var": "const_value",
		}

		options := &types.Options{}
		runtimeVars := goflags.RuntimeMap{}
		_ = runtimeVars.Set("runtime_var=runtime_value")
		options.Vars = runtimeVars

		executorOpts := &protocols.ExecutorOptions{
			Variables: templateVars,
			Constants: constants,
			Options:   options,
		}

		rule.options = executorOpts

		// Test simple var substitution
		result, err := rule.evaluateVars("{{test_var}}")
		require.NoError(t, err, "should evaluate template variable")
		require.Equal(t, "test_value", result, "should return evaluated value")

		// Test constant substitution
		result, err = rule.evaluateVars("{{const_var}}")
		require.NoError(t, err, "should evaluate constant")
		require.Equal(t, "const_value", result, "should return constant value")

		// Test runtime var substitution
		result, err = rule.evaluateVars("{{runtime_var}}")
		require.NoError(t, err, "should evaluate runtime variable")
		require.Equal(t, "runtime_value", result, "should return runtime value")

		// Test mixed content
		result, err = rule.evaluateVars("prefix-{{test_var}}-suffix")
		require.NoError(t, err, "should evaluate mixed content")
		require.Equal(t, "prefix-test_value-suffix", result, "should return mixed evaluated content")

		// Test unresolved var - should either fail during evaluation or return original string
		result2, err := rule.evaluateVars("{{nonexistent}}")
		if err != nil {
			require.Contains(t, err.Error(), "unresolved", "should fail for unresolved variable")
		} else {
			// If no error, it should return the original unresolved variable
			require.Equal(t, "{{nonexistent}}", result2, "should return original string for unresolved variable")
		}
	})
}

package fuzz

import (
	"io"
	"strconv"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz/component"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/render"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryablehttp-go"
	sliceutil "github.com/projectdiscovery/utils/slice"
)

// executePartRule executes part rules based on type
func (rule *Rule) executePartRule(input *ExecuteRuleInput, payload ValueOrKeyValue, component component.Component) error {
	return rule.executePartComponent(input, payload, component)
}

// checkRuleApplicableOnComponent checks if a rule is applicable on given component
func (rule *Rule) checkRuleApplicableOnComponent(component component.Component) bool {
	if rule.Part != component.Name() && !sliceutil.Contains(rule.Parts, component.Name()) && rule.partType != requestPartType {
		return false
	}
	foundAny := false
	_ = component.Iterate(func(key string, value interface{}) error {
		if rule.matchKeyOrValue(key, types.ToString(value)) {
			foundAny = true
			return io.EOF
		}
		return nil
	})
	return foundAny
}

// executePartComponent executes this rule on a given component and payload
func (rule *Rule) executePartComponent(input *ExecuteRuleInput, payload ValueOrKeyValue, ruleComponent component.Component) error {
	// Note: component needs to be cloned because they contain values copied by reference
	if payload.IsKV() {
		// for kv fuzzing
		return rule.executePartComponentOnKV(input, payload, ruleComponent.Clone())
	} else {
		// for value only fuzzing
		return rule.executePartComponentOnValues(input, payload.Value, payload.OriginalPayload, ruleComponent.Clone())
	}
}

// executePartComponentOnValues executes this rule on a given component and payload
// this supports both single and multiple [ruleType] modes
// i.e if component has multiple values, they can be replaced once or all depending on mode
func (rule *Rule) executePartComponentOnValues(input *ExecuteRuleInput, payloadStr, originalPayload string, ruleComponent component.Component) error {
	var fuzzedKeys []string
	finalErr := ruleComponent.Iterate(func(key string, value interface{}) error {
		valueStr := types.ToString(value)
		if !rule.matchKeyOrValue(key, valueStr) {
			// ignore non-matching keys
			return nil
		}

		var evaluated, originalEvaluated string
		var err error

		evaluated, input.InteractURLs, err = rule.executeEvaluate(input, key, valueStr, payloadStr, input.InteractURLs)
		if err != nil {
			return err
		}

		if input.ApplyPayloadInitialTransformation != nil {
			evaluated = input.ApplyPayloadInitialTransformation(evaluated, input.AnalyzerParams)
			originalEvaluated, _, err = rule.executeEvaluate(input, key, valueStr, originalPayload, input.InteractURLs)
			if err != nil {
				return err
			}
		}

		if err := ruleComponent.SetValue(key, evaluated); err != nil {
			// gologger.Warning().Msgf("could not set value due to format restriction original(%s, %s[%T]) , new(%s,%s[%T])", key, valueStr, value, key, evaluated, evaluated)
			return nil
		}
		if rule.modeType == multipleModeType {
			fuzzedKeys = append(fuzzedKeys, key)
		}

		if rule.modeType == singleModeType {
			req, err := ruleComponent.Rebuild()
			if err != nil {
				return err
			}

			if qerr := rule.execWithInput(input, req, input.InteractURLs, ruleComponent, key, valueStr, originalEvaluated, valueStr, key, evaluated); qerr != nil {
				return qerr
			}

			err = ruleComponent.SetValue(key, valueStr) // change back to previous value for temp
			if err != nil {
				return err
			}
		}

		return nil
	})

	if finalErr != nil {
		return finalErr
	}

	// We do not support analyzers with
	// multiple payload mode.
	if rule.modeType == multipleModeType {
		req, err := ruleComponent.Rebuild()
		if err != nil {
			return err
		}

		if qerr := rule.execWithInput(input, req, input.InteractURLs, ruleComponent, "", "", "", "", "", "", fuzzedKeys...); qerr != nil {
			err = qerr
			return err
		}
	}

	return nil
}

// executePartComponentOnKV executes this rule on a given component and payload
// currently only supports single mode
func (rule *Rule) executePartComponentOnKV(input *ExecuteRuleInput, payload ValueOrKeyValue, ruleComponent component.Component) error {
	var origKey string
	var origValue interface{}
	// when we have a key-value pair, iterate over only 1 value of the component
	// multiple values (aka multiple mode) not supported for this yet
	_ = ruleComponent.Iterate(func(key string, value interface{}) error {
		if key == payload.Key {
			origKey = key
			origValue = value
		}
		return nil
	})
	// iterate over given kv instead of component ones
	return func(key, value string) error {
		var evaluated string
		var err error
		evaluated, input.InteractURLs, err = rule.executeEvaluate(input, key, "", value, input.InteractURLs)
		if err != nil {
			return err
		}
		if err := ruleComponent.SetValue(key, evaluated); err != nil {
			return err
		}
		if rule.modeType == singleModeType {
			req, err := ruleComponent.Rebuild()
			if err != nil {
				return err
			}

			if qerr := rule.execWithInput(input, req, input.InteractURLs, ruleComponent, key, value, "", "", "", "", key); qerr != nil {
				return qerr
			}

			// after building change back to original value to avoid repeating it in further requests
			if origKey != "" {
				err = ruleComponent.SetValue(origKey, types.ToString(origValue)) // change back to previous value for temp
				if err != nil {
					return err
				}
			} else {
				_ = ruleComponent.Delete(key) // change back to previous value for temp
			}
		}
		return nil
	}(payload.Key, payload.Value)
}

// execWithInput executes a rule with input via callback
func (rule *Rule) execWithInput(input *ExecuteRuleInput, httpReq *retryablehttp.Request, interactURLs []string, component component.Component, parameter, parameterValue, originalPayload, originalValue, key, value string, fuzzedKeys ...string) error {
	// If the parameter is a number, replace it with the parameter value
	// or if the parameter is empty and the parameter value is not empty
	// replace it with the parameter value
	actualParameter := parameter
	if _, err := strconv.Atoi(parameter); err == nil || (parameter == "" && parameterValue != "") {
		actualParameter = parameterValue
	}
	// If the parameter is frequent, skip it if the option is enabled.
	// Skip frequency check when parameter is empty (mode: multiple sends
	// all values at once without a specific parameter name).
	if rule.options.FuzzParamsFrequency != nil && actualParameter != "" {
		if rule.options.FuzzParamsFrequency.IsParameterFrequent(
			actualParameter,
			httpReq.String(),
			rule.options.TemplateID,
		) {
			return nil
		}
	}
	if len(fuzzedKeys) == 0 && key != "" {
		fuzzedKeys = []string{key}
	}
	request := GeneratedRequest{
		Request:         httpReq,
		InteractURLs:    interactURLs,
		DynamicValues:   input.Values,
		Component:       component,
		Parameter:       actualParameter,
		Key:             key,
		FuzzedKeys:      append([]string(nil), fuzzedKeys...),
		Value:           value,
		OriginalValue:   originalValue,
		OriginalPayload: originalPayload,
	}
	if !input.Callback(request) {
		return types.ErrNoMoreRequests
	}
	return nil
}

// executeEvaluate executes evaluation of payload on a key and value and
// returns completed values to be replaced and processed
// for fuzzing.
func (rule *Rule) executeEvaluate(input *ExecuteRuleInput, _, value, payload string, interactshURLs []string) (string, []string, error) {
	values := generators.MergeMaps(rule.options.Variables.GetAll(), map[string]interface{}{
		"value": value,
	}, rule.options.Options.Vars.AsMap(), input.Values)

	result, err := render.Render(render.Input{
		Options:      rule.options.GetOptions(),
		Text:         payload,
		Values:       values,
		Interactsh:   rule.options.Interactsh,
		InteractURLs: interactshURLs,
	})
	if err != nil {
		return payload, result.InteractURLs, err
	}

	replaced := rule.executeRuleTypes(input, value, result.Text)

	return replaced, result.InteractURLs, nil
}

// executeRuleTypes executes replacement for a key and value
// ex: prefix, postfix, infix, replace , replace-regex
func (rule *Rule) executeRuleTypes(_ *ExecuteRuleInput, value, replacement string) string {
	var builder strings.Builder
	if rule.ruleType == prefixRuleType || rule.ruleType == postfixRuleType {
		builder.Grow(len(value) + len(replacement))
	}
	var returnValue string

	switch rule.ruleType {
	case prefixRuleType:
		builder.WriteString(replacement)
		builder.WriteString(value)
		returnValue = builder.String()
	case postfixRuleType:
		builder.WriteString(value)
		builder.WriteString(replacement)
		returnValue = builder.String()
	case infixRuleType:
		if len(value) <= 1 {
			builder.WriteString(value)
			builder.WriteString(replacement)
			returnValue = builder.String()
		} else {
			middleIndex := len(value) / 2
			builder.WriteString(value[:middleIndex])
			builder.WriteString(replacement)
			builder.WriteString(value[middleIndex:])
			returnValue = builder.String()
		}
	case replaceRuleType:
		returnValue = replacement
	case replaceRegexRuleType:
		returnValue = rule.replaceRegex.ReplaceAllString(value, replacement)
	}
	return returnValue
}

