// Package raw parses input files holding raw HTTP requests, the shape produced
// by "copy as raw request" in Burp and browser devtools and stored in .http
// files. It is the shortest path from a single request to a DAST scan, for
// targets that have no OpenAPI spec or captured traffic to feed in.
package raw

import (
	"io"
	"strings"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/input/formats"
	"github.com/projectdiscovery/nuclei/v3/pkg/input/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
)

// requestSeparator delimits requests when a file carries more than one,
// following the .http file convention
const requestSeparator = "###"

// RawFormat is a parser for files containing one or more raw HTTP requests
type RawFormat struct {
	opts formats.InputFormatOptions
}

// New creates a new raw HTTP request parser
func New() *RawFormat {
	return &RawFormat{}
}

var _ formats.Format = &RawFormat{}

// Name returns the name of the format
func (r *RawFormat) Name() string {
	return "http"
}

func (r *RawFormat) SetOptions(options formats.InputFormatOptions) {
	r.opts = options
}

// Parse parses the input and calls the provided callback
// function for each RawRequest it discovers.
func (r *RawFormat) Parse(input io.Reader, resultsCb formats.ParseReqRespCallback, filePath string) error {
	data, err := io.ReadAll(input)
	if err != nil {
		return errors.Wrap(err, "could not read raw request file")
	}
	for _, request := range splitRequests(string(data)) {
		reqResp, err := types.ParseRawRequest(terminateHeaders(request))
		if err != nil {
			gologger.Warning().Msgf("http: could not parse raw request in %s: %s\n", filePath, err)
			continue
		}
		if reqResp.URL.Host == "" {
			gologger.Warning().Msgf("http: skipped raw request in %s: no target, add a Host header or an absolute request target\n", filePath)
			continue
		}
		if reqResp.URL.Scheme == "" {
			// nothing in the request states the scheme, so settle it the same
			// way nuclei settles it for scheme-less list inputs
			reqResp.URL.Scheme = utils.DetermineSchemeOrder(reqResp.URL.Host)[0]
		}
		resultsCb(reqResp)
	}
	return nil
}

// splitRequests splits the file contents into individual raw requests
func splitRequests(data string) []string {
	var requests []string
	var current []string
	flush := func() {
		if request := strings.Join(current, "\n"); strings.TrimSpace(request) != "" {
			requests = append(requests, strings.TrimLeft(request, "\r\n"))
		}
		current = nil
	}
	for _, line := range strings.Split(data, "\n") {
		if strings.HasPrefix(strings.TrimSpace(line), requestSeparator) {
			flush()
			continue
		}
		current = append(current, line)
	}
	flush()
	return requests
}

// terminateHeaders appends the blank line that separates headers from the body.
// Requests copied out of a browser or Burp routinely end at the last header,
// and the parser needs that terminator to know where the headers stop.
func terminateHeaders(request string) string {
	if strings.Contains(request, "\n\r\n") || strings.Contains(request, "\n\n") {
		return request
	}
	return request + "\r\n\r\n"
}

package raw

import (
	"strings"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/input/formats"
	"github.com/projectdiscovery/nuclei/v3/pkg/input/types"
	"github.com/stretchr/testify/require"
)

func parseAll(t *testing.T, data string) []*types.RequestResponse {
	t.Helper()
	var got []*types.RequestResponse
	err := New().Parse(strings.NewReader(data), func(rr *types.RequestResponse) bool {
		got = append(got, rr)
		return false
	}, "test.http")
	require.NoError(t, err)
	return got
}

func TestParseSingleRequest(t *testing.T) {
	got := parseAll(t, "POST /api/login HTTP/1.1\r\nHost: example.com\r\nContent-Type: application/json\r\n\r\n{\"user\":\"admin\"}")

	require.Len(t, got, 1)
	require.Equal(t, "POST", got[0].Request.Method)
	require.Equal(t, "https://example.com/api/login", got[0].URL.String())
	require.Equal(t, `{"user":"admin"}`, got[0].Request.Body)
	contentType, _ := got[0].Request.Headers.Get("Content-Type")
	require.Equal(t, "application/json", contentType)
}

func TestParseMultipleRequests(t *testing.T) {
	got := parseAll(t, strings.Join([]string{
		"GET /one HTTP/1.1",
		"Host: example.com",
		"",
		"### second request",
		"POST /two HTTP/1.1",
		"Host: example.com",
		"",
		"body=1",
	}, "\n"))

	require.Len(t, got, 2)
	require.Equal(t, "https://example.com/one", got[0].URL.String())
	require.Equal(t, "https://example.com/two", got[1].URL.String())
	require.Equal(t, "body=1", got[1].Request.Body)
}

// A request pasted out of a browser or Burp commonly ends at the last header.
func TestParseWithoutTrailingBlankLine(t *testing.T) {
	got := parseAll(t, "GET /api/users?id=1 HTTP/1.1\r\nHost: example.com")

	require.Len(t, got, 1)
	require.Equal(t, "https://example.com/api/users?id=1", got[0].URL.String())
	require.Empty(t, got[0].Request.Body)
}

// The scheme is not part of an origin-form request, so it is inferred from the
// authority unless the request target states it.
func TestParseResolvesScheme(t *testing.T) {
	tests := []struct {
		name string
		raw  string
		url  string
	}{
		{"no port", "GET / HTTP/1.1\r\nHost: example.com\r\n\r\n", "https://example.com/"},
		{"port 80", "GET / HTTP/1.1\r\nHost: example.com:80\r\n\r\n", "http://example.com:80/"},
		{"high port", "GET / HTTP/1.1\r\nHost: 127.0.0.1:18080\r\n\r\n", "http://127.0.0.1:18080/"},
		{"absolute target", "GET https://example.com/p HTTP/1.1\r\nHost: example.com\r\n\r\n", "https://example.com/p"},
		{"absolute plain target", "GET http://example.com/p HTTP/1.1\r\nHost: example.com\r\n\r\n", "http://example.com/p"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := parseAll(t, tt.raw)
			require.Len(t, got, 1)
			require.Equal(t, tt.url, got[0].URL.String())
		})
	}
}

// A request with no way to resolve a target is dropped rather than scanned
// against nothing, and it must not take the rest of the file down with it.
func TestParseSkipsRequestsWithoutTarget(t *testing.T) {
	got := parseAll(t, strings.Join([]string{
		"GET /no-host HTTP/1.1",
		"X-Test: 1",
		"",
		"###",
		"GET /valid HTTP/1.1",
		"Host: example.com",
		"",
	}, "\n"))

	require.Len(t, got, 1)
	require.Equal(t, "https://example.com/valid", got[0].URL.String())
}

// The callback's return value is unused across every input format, and its two
// call sites in the provider give it opposite meanings, so a request must be
// reported regardless of what the previous one returned.
func TestParseIgnoresCallbackReturn(t *testing.T) {
	var count int
	err := New().Parse(strings.NewReader("GET /one HTTP/1.1\nHost: example.com\n\n###\nGET /two HTTP/1.1\nHost: example.com\n\n"), func(rr *types.RequestResponse) bool {
		count++
		return true
	}, "test.http")

	require.NoError(t, err)
	require.Equal(t, 2, count)
}

func TestFormatInterface(t *testing.T) {
	var format formats.Format = New()
	require.Equal(t, "http", format.Name())
}

package swagger

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/input/formats"
	"github.com/projectdiscovery/retryablehttp-go"
	"gopkg.in/yaml.v3"
)

// SwaggerDownloader implements the SpecDownloader interface for Swagger 2.0 specs
type SwaggerDownloader struct{}

// NewDownloader creates a new Swagger downloader
func NewDownloader() formats.SpecDownloader {
	return &SwaggerDownloader{}
}

// This function downloads a Swagger 2.0 spec from the given URL and saves it to tmpDir
func (d *SwaggerDownloader) Download(urlStr, tmpDir string, httpClient *retryablehttp.Client) (string, error) {
	// Swagger can be JSON or YAML
	supportedExts := d.SupportedExtensions()
	isSupported := false
	for _, ext := range supportedExts {
		if strings.HasSuffix(urlStr, ext) {
			isSupported = true
			break
		}
	}
	if !isSupported {
		return "", fmt.Errorf("URL does not appear to be a Swagger spec (supported: %v)", supportedExts)
	}

	const maxSpecSizeBytes = 10 * 1024 * 1024 // 10MB

	// Use provided httpClient or create a fallback
	var client *http.Client
	if httpClient != nil {
		client = httpClient.HTTPClient
	} else {
		// Fallback to simple client if no httpClient provided
		client = &http.Client{Timeout: 30 * time.Second}
	}

	resp, err := client.Get(urlStr)
	if err != nil {
		return "", errors.Wrap(err, "failed to download Swagger spec")
	}

	defer func() {
		_ = resp.Body.Close()
	}()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("HTTP %d when downloading Swagger spec", resp.StatusCode)
	}

	bodyBytes, err := io.ReadAll(io.LimitReader(resp.Body, maxSpecSizeBytes))
	if err != nil {
		return "", errors.Wrap(err, "failed to read response body")
	}

	// Determine format and parse
	var spec map[string]interface{}
	var isYAML bool

	// Try JSON first
	if err := json.Unmarshal(bodyBytes, &spec); err != nil {
		// Then try YAML
		if err := yaml.Unmarshal(bodyBytes, &spec); err != nil {
			return "", fmt.Errorf("downloaded content is neither valid JSON nor YAML: %w", err)
		}
		isYAML = true
	}

	// Validate it's a Swagger 2.0 spec
	if swagger, exists := spec["swagger"]; exists {
		if swaggerStr, ok := swagger.(string); ok && strings.HasPrefix(swaggerStr, "2.") {
			// Valid Swagger 2.0 spec
		} else {
			return "", fmt.Errorf("not a valid Swagger 2.0 spec (found version: %v)", swagger)
		}
	} else {
		return "", fmt.Errorf("not a Swagger spec (missing 'swagger' field)")
	}

	// Extract host from URL for host configuration
	parsedURL, err := url.Parse(urlStr)
	if err != nil {
		return "", errors.Wrap(err, "failed to parse URL")
	}

	host := parsedURL.Host
	scheme := parsedURL.Scheme
	if scheme == "" {
		scheme = "https"
	}

	// Add host if missing
	if _, exists := spec["host"]; !exists {
		spec["host"] = host
	}

	// Add schemes if missing
	if _, exists := spec["schemes"]; !exists {
		spec["schemes"] = []string{scheme}
	}

	// Create output directory
	swaggerDir := filepath.Join(tmpDir, "swagger")
	if err := os.MkdirAll(swaggerDir, 0755); err != nil {
		return "", errors.Wrap(err, "failed to create swagger directory")
	}

	// Generate filename and content based on original format
	var filename string
	var content []byte

	if isYAML {
		filename = fmt.Sprintf("swagger-spec-%d.yaml", time.Now().Unix())
		content, err = yaml.Marshal(spec)
		if err != nil {
			return "", errors.Wrap(err, "failed to marshal modified YAML spec")
		}
	} else {
		filename = fmt.Sprintf("swagger-spec-%d.json", time.Now().Unix())
		content, err = json.Marshal(spec)
		if err != nil {
			return "", errors.Wrap(err, "failed to marshal modified JSON spec")
		}
	}

	filePath := filepath.Join(swaggerDir, filename)

	// Write file
	file, err := os.Create(filePath)
	if err != nil {
		return "", errors.Wrap(err, "failed to create file")
	}

	defer func() {
		_ = file.Close()
	}()

	if _, writeErr := file.Write(content); writeErr != nil {
		_ = os.Remove(filePath)
		return "", errors.Wrap(writeErr, "failed to write file")
	}

	return filePath, nil
}

// SupportedExtensions returns the list of supported file extensions for Swagger
func (d *SwaggerDownloader) SupportedExtensions() []string {
	return []string{".json", ".yaml", ".yml"}
}

