package yaml

import (
	"fmt"
	"strings"

	yttcmd "carvel.dev/ytt/pkg/cmd/template"
	yttui "carvel.dev/ytt/pkg/cmd/ui"
	yttfiles "carvel.dev/ytt/pkg/files"
	yamlutil "github.com/projectdiscovery/nuclei/v3/pkg/utils/yaml"
)

func ytt(tpl, dvs []string, varFiles []string) ([]byte, error) {
	// create and invoke ytt "template" command
	templatingOptions := yttcmd.NewOptions()

	input, err := templatesAsInput(tpl...)
	if err != nil {
		return nil, err
	}

	if len(varFiles) > 0 {
		// Load vaarFiles into the templating options.
		templatingOptions.DataValuesFlags.FromFiles = varFiles
	}

	// equivalent to `--data-value-yaml`
	templatingOptions.DataValuesFlags.KVsFromYAML = dvs

	// for in-memory use, pipe output to "/dev/null"
	noopUI := yttui.NewCustomWriterTTY(false, noopWriter{}, noopWriter{})

	// Evaluate the template given the configured data values...
	output := templatingOptions.RunWithFiles(input, noopUI)
	if output.Err != nil {
		return nil, output.Err
	}

	return output.DocSet.AsBytes()
}

// templatesAsInput conveniently wraps one or more strings, each in a files.File, into a template.Input.
func templatesAsInput(tpl ...string) (yttcmd.Input, error) {
	var files []*yttfiles.File
	for i, t := range tpl {
		// to make this less brittle, you'll probably want to use well-defined names for `path`, here, for each input.
		// this matters when you're processing errors which report based on these paths.
		file, err := yttfiles.NewFileFromSource(yttfiles.NewBytesSource(fmt.Sprintf("tpl%d.yml", i), []byte(t)))
		if err != nil {
			return yttcmd.Input{}, err
		}

		files = append(files, file)
	}

	return yttcmd.Input{Files: files}, nil
}

func mapToKeyValueSlice(m map[string]interface{}) []string {
	var result []string
	for k, v := range m {
		y, _ := yamlutil.Marshal(v)
		result = append(result, fmt.Sprintf("%s=%s", k, strings.TrimSpace(string(y))))
	}
	return result
}

type noopWriter struct{}

func (w noopWriter) Write(data []byte) (int, error) { return len(data), nil }

package normalize

import (
	"regexp"
	"sort"
	"strconv"
	"strings"
	"sync"

	urlutil "github.com/projectdiscovery/utils/url"
)

// Placeholders a structurally variable path segment collapses to. They are
// spelled out rather than hashed so a skipped-target log reads plainly.
const (
	placeholderNum  = "{num}"
	placeholderUUID = "{uuid}"
	placeholderHash = "{hash}"
	placeholderDate = "{date}"
	placeholderVar  = "{var}"
)

var (
	numericSegment = regexp.MustCompile(`^\d+$`)
	uuidSegment    = regexp.MustCompile(`(?i)^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$`)
	hashSegment    = regexp.MustCompile(`(?i)^[0-9a-f]{16,}$`)
	// a date split across path positions is already caught as numeric segments
	dateSegment = regexp.MustCompile(`^\d{4}-\d{2}(-\d{2})?$`)
)

// classifySegment replaces a path segment that identifies a particular record
// with a placeholder, leaving segments that name a route alone.
func classifySegment(segment string) string {
	switch {
	case segment == "":
		return segment
	case numericSegment.MatchString(segment):
		return placeholderNum
	case uuidSegment.MatchString(segment):
		return placeholderUUID
	case dateSegment.MatchString(segment):
		return placeholderDate
	case hashSegment.MatchString(segment):
		return placeholderHash
	}
	return segment
}

// DefaultCollapseAfter is how many distinct values a single path position may
// hold on one host before the position itself is treated as an identifier. It
// catches slugs and names, which no pattern can recognise by shape alone.
const DefaultCollapseAfter = 20

// Fingerprinter groups URLs by the shape of their path and query, so a crawl
// that produced ten thousand product pages is recognised as one pattern.
//
// It is stateful by design: whether a path position is an identifier depends on
// how many distinct values that position has taken on that host, which is only
// knowable across the whole input.
type Fingerprinter struct {
	// MaxPerPattern is how many targets to keep per pattern. Zero keeps every
	// target, which is the default: dropping one is a target never scanned.
	MaxPerPattern int
	// CollapseAfter is the distinct-value threshold for a path position.
	CollapseAfter int

	mu       sync.Mutex
	kept     map[string]int
	position map[string]map[string]struct{}
}

// NewFingerprinter returns a fingerprinter keeping at most maxPerPattern
// targets for each pattern. A maxPerPattern of zero disables grouping.
func NewFingerprinter(maxPerPattern int) *Fingerprinter {
	return &Fingerprinter{
		MaxPerPattern: maxPerPattern,
		CollapseAfter: DefaultCollapseAfter,
		kept:          make(map[string]int),
		position:      make(map[string]map[string]struct{}),
	}
}

// Enabled reports whether the fingerprinter drops anything.
func (f *Fingerprinter) Enabled() bool {
	return f != nil && f.MaxPerPattern > 0
}

// Accept reports whether a target should be scanned, recording it against its
// pattern. A value that is not a URL is always accepted: it has no path to
// group by, and guessing would lose targets.
func (f *Fingerprinter) Accept(rawURL string) bool {
	return f.AcceptOn(rawURL, "")
}

// AcceptOn is Accept for a target connected to through ip. Each ip of a host
// is a server of its own, so it keeps its own count for every pattern.
func (f *Fingerprinter) AcceptOn(rawURL, ip string) bool {
	if !f.Enabled() {
		return true
	}
	pattern, ok := f.pattern(rawURL)
	if !ok {
		return true
	}
	if ip != "" {
		pattern += "@" + ip
	}

	f.mu.Lock()
	defer f.mu.Unlock()
	if f.kept[pattern] >= f.MaxPerPattern {
		return false
	}
	f.kept[pattern]++
	return true
}

// Pattern returns the structural fingerprint of a URL, for tests and logging.
func (f *Fingerprinter) Pattern(rawURL string) string {
	pattern, _ := f.pattern(rawURL)
	return pattern
}

func (f *Fingerprinter) pattern(rawURL string) (string, bool) {
	trimmed := strings.TrimSpace(rawURL)
	if idx := strings.Index(trimmed, "://"); idx > 0 {
		trimmed = strings.ToLower(trimmed[:idx]) + trimmed[idx:]
	}
	parsed, err := urlParse(trimmed)
	if err != nil || parsed == nil || parsed.Host == "" {
		return "", false
	}

	host := strings.ToLower(parsed.Host)
	segments := strings.Split(strings.Trim(parsed.Path, "/"), "/")
	shaped := make([]string, 0, len(segments))
	for index, segment := range segments {
		parent := strings.Join(segments[:index], "/")
		shaped = append(shaped, f.shapeSegment(host, parent, index, segment))
	}

	var builder strings.Builder
	builder.WriteString(host)
	builder.WriteString("/")
	builder.WriteString(strings.Join(shaped, "/"))
	if keys := queryKeys(parsed); len(keys) > 0 {
		// names without values: two searches differ by what was searched for,
		// not by the shape of the request
		builder.WriteString("?")
		builder.WriteString(strings.Join(keys, "&"))
	}
	return builder.String(), true
}

// shapeSegment classifies a segment by shape, then by how many distinct values
// the same position has already taken under this parent path on this host.
// The parent is part of the key so a busy /blog/<slug> does not also collapse
// /admin/<name> just because both sit at the same index.
func (f *Fingerprinter) shapeSegment(host, parent string, index int, segment string) string {
	if shaped := classifySegment(segment); shaped != segment {
		return shaped
	}
	if f.CollapseAfter <= 0 || segment == "" {
		return segment
	}

	key := host + "\x00" + parent + "\x00" + itoa(index)
	f.mu.Lock()
	values, ok := f.position[key]
	if !ok {
		values = make(map[string]struct{})
		f.position[key] = values
	}
	if len(values) < f.CollapseAfter {
		values[segment] = struct{}{}
	}
	collapsed := len(values) >= f.CollapseAfter
	f.mu.Unlock()

	if collapsed {
		return placeholderVar
	}
	return segment
}

// urlParse and queryKeys keep the url library dependency in one place.
func urlParse(raw string) (*urlutil.URL, error) {
	return urlutil.Parse(raw)
}

// queryKeys returns the query parameter names, sorted, with values dropped.
func queryKeys(parsed *urlutil.URL) []string {
	if parsed.Params == nil || parsed.Params.IsEmpty() {
		return nil
	}
	var keys []string
	parsed.Params.Iterate(func(key string, _ []string) bool {
		if !IsTrackingParam(key) {
			keys = append(keys, key)
		}
		return true
	})
	sort.Strings(keys)
	return keys
}

func itoa(value int) string { return strconv.Itoa(value) }

package normalize

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestPatternGroupsIdentifiers(t *testing.T) {
	f := NewFingerprinter(1)
	base := f.Pattern("http://acme.test/user/1/profile")
	for _, raw := range []string{
		"http://acme.test/user/2/profile",
		"http://acme.test/user/99999/profile",
	} {
		require.Equal(t, base, f.Pattern(raw), "numeric ids are the same shape")
	}
	require.Contains(t, base, placeholderNum)
}

func TestPatternGroupsUUIDsHashesAndDates(t *testing.T) {
	f := NewFingerprinter(1)
	require.Contains(t, f.Pattern("http://acme.test/o/3f2504e0-4f89-11d3-9a0c-0305e82c3301"), placeholderUUID)
	require.Contains(t, f.Pattern("http://acme.test/a/d41d8cd98f00b204e9800998ecf8427e"), placeholderHash)
	require.Contains(t, f.Pattern("http://acme.test/posts/2024-05-01"), placeholderDate)
	// a date spread across positions is already grouped as numeric segments
	require.Equal(t, "acme.test/posts/{num}/{num}", f.Pattern("http://acme.test/posts/2024/05"))
}

func TestPatternKeepsRouteNames(t *testing.T) {
	f := NewFingerprinter(1)
	require.NotEqual(t, f.Pattern("http://acme.test/admin"), f.Pattern("http://acme.test/login"),
		"route names are the structure, not identifiers within it")
}

func TestPatternDropsQueryValuesButKeepsSortedNames(t *testing.T) {
	f := NewFingerprinter(1)
	a := f.Pattern("http://acme.test/search?q=admin&page=2")
	b := f.Pattern("http://acme.test/search?page=9&q=root")
	require.Equal(t, a, b, "same parameters in a different order with different values is one shape")
	require.Contains(t, a, "page&q")
	require.NotContains(t, a, "admin")

	require.NotEqual(t, a, f.Pattern("http://acme.test/search?q=admin"), "a different parameter set is a different shape")
}

func TestPatternCollapsesHighCardinalityPosition(t *testing.T) {
	f := NewFingerprinter(1)
	f.CollapseAfter = 5
	// slugs have no recognisable shape, so the position itself is what gives
	// them away once it has held enough distinct values
	for i := 0; i < 5; i++ {
		f.Pattern(fmt.Sprintf("http://acme.test/blog/%s-post", []string{"alpha", "beta", "gamma", "delta", "epsilon"}[i]))
	}
	require.Contains(t, f.Pattern("http://acme.test/blog/zeta-post"), placeholderVar)
	// a different host is tracked separately
	require.NotContains(t, f.Pattern("http://other.test/blog/zeta-post"), placeholderVar)
}

func TestCollapseStaysInsideTheParentPath(t *testing.T) {
	f := NewFingerprinter(1)
	f.CollapseAfter = 3
	require.Equal(t, "acme.test/blog/one", f.Pattern("http://acme.test/blog/one"))
	require.Equal(t, "acme.test/blog/two", f.Pattern("http://acme.test/blog/two"))
	require.Equal(t, "acme.test/blog/{var}", f.Pattern("http://acme.test/blog/three"))

	// same index, different parent: a busy /blog/<slug> must not collapse /admin/<name>
	require.Equal(t, "acme.test/admin/a", f.Pattern("http://acme.test/admin/a"))
	require.Equal(t, "acme.test/admin/b", f.Pattern("http://acme.test/admin/b"))
	require.True(t, f.Accept("http://acme.test/admin/a"))
	require.True(t, f.Accept("http://acme.test/admin/b"), "a different parent still has its own cap")
}

func TestAcceptKeepsUpToTheCap(t *testing.T) {
	f := NewFingerprinter(2)
	require.True(t, f.Accept("http://acme.test/user/1"))
	require.True(t, f.Accept("http://acme.test/user/2"))
	require.False(t, f.Accept("http://acme.test/user/3"), "past the cap the pattern is already covered")
	require.True(t, f.Accept("http://acme.test/admin"), "a different pattern has its own budget")
}

func TestAcceptOnCountsEachIPApart(t *testing.T) {
	f := NewFingerprinter(1)
	require.True(t, f.AcceptOn("http://acme.test/user/1", "192.0.2.10"))
	require.True(t, f.AcceptOn("http://acme.test/user/1", "192.0.2.11"), "another ip is another server")
	require.False(t, f.AcceptOn("http://acme.test/user/2", "192.0.2.10"), "past the cap of its ip")
	require.True(t, f.Accept("http://acme.test/user/2"), "the host without an ip has its own budget")
}

// Off by default: dropping a target means never scanning it, so it has to be
// asked for.
func TestDisabledFingerprinterKeepsEverything(t *testing.T) {
	f := NewFingerprinter(0)
	require.False(t, f.Enabled())
	for i := 0; i < 100; i++ {
		require.True(t, f.Accept(fmt.Sprintf("http://acme.test/user/%d", i)))
	}
	var nilF *Fingerprinter
	require.False(t, nilF.Enabled())
	require.True(t, nilF.Accept("http://acme.test/user/1"))
}

func TestAcceptKeepsNonURLTargets(t *testing.T) {
	f := NewFingerprinter(1)
	require.True(t, f.Accept("acme.test"))
	require.True(t, f.Accept("not a url"))
	require.True(t, f.Accept("not a url"), "a value with no pattern is never grouped away")
}

// Package normalize collapses URLs that address the same resource onto one
// form, so a target list built by a crawler does not run every template several
// times over for what is effectively the same target.
//
// Only differences that cannot change the response are removed: host case, the
// fragment (never sent to the server), a default port, a trailing slash, and
// well known tracking parameters. Path case is left alone, because paths are
// case sensitive on most servers.
package normalize

import (
	"strings"

	urlutil "github.com/projectdiscovery/utils/url"
)

// trackingParams are query keys added by ad and analytics platforms. They are
// echoed back at most and never select a different resource, so two URLs that
// differ only by these are the same target. The list is deliberately limited to
// vendor prefixed names: a generic key like "ref" or "id" can be functional.
var trackingParams = map[string]struct{}{
	"utm_source":   {},
	"utm_medium":   {},
	"utm_campaign": {},
	"utm_term":     {},
	"utm_content":  {},
	"utm_id":       {},
	"utm_reader":   {},
	"utm_name":     {},
	"gclid":        {},
	"gbraid":       {},
	"wbraid":       {},
	"dclid":        {},
	"fbclid":       {},
	"msclkid":      {},
	"mc_cid":       {},
	"mc_eid":       {},
	"igshid":       {},
	"twclid":       {},
	"ttclid":       {},
	"yclid":        {},
	"_ga":          {},
	"_gl":          {},
}

// IsTrackingParam reports whether a query key is a known tracking parameter.
func IsTrackingParam(key string) bool {
	_, ok := trackingParams[strings.ToLower(key)]
	return ok
}

// URL returns the canonical form of raw. A value that cannot be parsed, or that
// carries no host, is returned unchanged: the input provider accepts things
// that are not URLs at all, and guessing at those would lose targets.
func URL(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return raw
	}

	// The scheme is case insensitive per RFC 3986, but the parser rejects one
	// that is not lowercase, so fold it before handing the value over.
	if idx := strings.Index(trimmed, "://"); idx > 0 {
		trimmed = strings.ToLower(trimmed[:idx]) + trimmed[idx:]
	}

	parsed, err := urlutil.Parse(trimmed)
	if err != nil || parsed == nil || parsed.Host == "" {
		return raw
	}

	parsed.Scheme = strings.ToLower(parsed.Scheme)
	parsed.Host = strings.ToLower(parsed.Host)
	parsed.Fragment = ""

	if host, port, ok := splitHostPort(parsed.Host); ok && isDefaultPort(parsed.Scheme, port) {
		parsed.Host = host
	}

	stripTrackingParams(parsed)

	// A trailing slash addresses the same resource as its absence for every
	// path but the root, where "/" is the path.
	if path := parsed.Path; len(path) > 1 && strings.HasSuffix(path, "/") {
		parsed.Path = strings.TrimRight(path, "/")
	}

	return parsed.String()
}

// stripTrackingParams removes known tracking keys, leaving every other
// parameter and its value untouched.
func stripTrackingParams(parsed *urlutil.URL) {
	if parsed.Params == nil || parsed.Params.IsEmpty() {
		return
	}
	// collected first: deleting while iterating would mutate the order under us
	var drop []string
	parsed.Params.Iterate(func(key string, _ []string) bool {
		if IsTrackingParam(key) {
			drop = append(drop, key)
		}
		return true
	})
	for _, key := range drop {
		parsed.Params.Del(key)
	}
	parsed.Update()
}

// splitHostPort separates a host and port, tolerating bracketed IPv6 literals.
func splitHostPort(host string) (string, string, bool) {
	if strings.HasPrefix(host, "[") {
		end := strings.LastIndex(host, "]")
		if end < 0 {
			return host, "", false
		}
		rest := host[end+1:]
		if !strings.HasPrefix(rest, ":") {
			return host, "", false
		}
		return host[:end+1], rest[1:], true
	}
	idx := strings.LastIndex(host, ":")
	if idx < 0 {
		return host, "", false
	}
	return host[:idx], host[idx+1:], true
}

func isDefaultPort(scheme, port string) bool {
	return (scheme == "http" && port == "80") || (scheme == "https" && port == "443")
}

// Origin returns the scheme and host a URL addresses, which is what a template
// built only from {{RootURL}} resolves against. It returns "" when the value
// carries no host, so callers can fall back to treating the target as unique.
func Origin(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return ""
	}
	if idx := strings.Index(trimmed, "://"); idx > 0 {
		trimmed = strings.ToLower(trimmed[:idx]) + trimmed[idx:]
	}
	parsed, err := urlutil.Parse(trimmed)
	if err != nil || parsed == nil || parsed.Host == "" {
		return ""
	}
	scheme := strings.ToLower(parsed.Scheme)
	host := strings.ToLower(parsed.Host)
	if h, port, ok := splitHostPort(host); ok && isDefaultPort(scheme, port) {
		host = h
	}
	if scheme == "" {
		return host
	}
	return scheme + "://" + host
}

package normalize

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func TestURLCollapsesEquivalentForms(t *testing.T) {
	same := "http://acme.test/page"
	for _, raw := range []string{
		"http://acme.test/page",
		"http://ACME.test/page",
		"HTTP://acme.test/page",
		"http://acme.test:80/page",
		"http://acme.test/page/",
		"http://acme.test/page#section",
		"http://acme.test/page?utm_source=news&utm_campaign=q4",
	} {
		require.Equal(t, same, URL(raw), "%q addresses the same resource", raw)
	}
}

func TestURLKeepsDifferencesThatMatter(t *testing.T) {
	// path case is significant on most servers, so it is left alone
	require.NotEqual(t, URL("http://acme.test/page"), URL("http://acme.test/PAGE"))
	// a non-default port is part of the target
	require.NotEqual(t, URL("http://acme.test/page"), URL("http://acme.test:8080/page"))
	// so is the scheme
	require.NotEqual(t, URL("http://acme.test/page"), URL("https://acme.test/page"))
	// and a functional query parameter
	require.NotEqual(t, URL("http://acme.test/page"), URL("http://acme.test/page?id=1"))
}

func TestURLKeepsFunctionalParamsWhenStrippingTracking(t *testing.T) {
	got := URL("http://acme.test/search?q=admin&utm_source=news&page=2")
	require.Contains(t, got, "q=admin")
	require.Contains(t, got, "page=2")
	require.NotContains(t, got, "utm_source")
}

func TestURLKeepsDefaultPortForOtherSchemes(t *testing.T) {
	// 443 is only the default for https, so on http it is a real port
	require.Contains(t, URL("http://acme.test:443/page"), ":443")
	require.NotContains(t, URL("https://acme.test:443/page"), ":443")
}

func TestURLKeepsRootPath(t *testing.T) {
	// "/" is the path at the root, not a trailing slash to trim
	require.Equal(t, URL("http://acme.test/"), URL("http://acme.test/"))
	require.NotEmpty(t, URL("http://acme.test/"))
}

func TestURLHandlesIPv6(t *testing.T) {
	require.Equal(t, URL("http://[::1]:8080/page"), URL("http://[::1]:8080/page/"))
	require.Contains(t, URL("http://[::1]:8080/page"), "[::1]:8080")
	// the default port still goes
	require.NotContains(t, URL("http://[::1]:80/page"), ":80")
}

// The provider accepts bare hosts, ip:port and other non-URL values. Guessing
// at those would lose targets, so they come back untouched.
func TestURLLeavesUnparsableInputAlone(t *testing.T) {
	for _, raw := range []string{"", "   ", "not a url", "acme.test", "10.0.0.1:8080"} {
		require.Equal(t, raw, URL(raw))
	}
}

func TestOriginIgnoresPathQueryAndDefaultPort(t *testing.T) {
	same := "https://example.com"
	for _, raw := range []string{
		"https://example.com/a",
		"https://EXAMPLE.com/b?q=1#frag",
		"https://example.com:443/c",
	} {
		require.Equal(t, same, Origin(raw), "%q is the same origin", raw)
	}
	require.NotEqual(t, Origin("https://example.com/a"), Origin("http://example.com/a"))
	require.NotEqual(t, Origin("https://example.com/a"), Origin("https://other.test/a"))
	require.NotEqual(t, Origin("https://example.com/a"), Origin("https://example.com:8443/a"))
	require.Equal(t, "example.com", Origin("example.com"))
	require.Empty(t, Origin(""))
	require.Empty(t, Origin("not a url"))
}

func TestIsTrackingParam(t *testing.T) {
	require.True(t, IsTrackingParam("utm_source"))
	require.True(t, IsTrackingParam("UTM_SOURCE"))
	require.True(t, IsTrackingParam("fbclid"))
	require.False(t, IsTrackingParam("id"))
	require.False(t, IsTrackingParam("ref"), "a generic name can be functional")
}

