	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/stretchr/testify/require"
)

const templatesDir = "/templates"

func newTemplate(path, id string, sev severity.Severity, product string, tags ...string) *templates.Template {
	info := model.Info{
		Tags:           stringslice.StringSlice{Value: tags},
		SeverityHolder: severity.Holder{Severity: sev},
	}
	if product != "" {
		info.Metadata = map[string]any{"product": product}
	}
	return &templates.Template{ID: id, Path: filepath.Join(templatesDir, path), Info: info}
}

var (
	thinkphpRCE  = newTemplate("http/cves/thinkphp-rce.yaml", "thinkphp-rce", severity.Critical, "thinkphp", "cve", "thinkphp", "rce")
	tomcatPanel  = newTemplate("http/exposed-panels/tomcat-panel.yaml", "tomcat-panel", severity.Info, "tomcat", "panel", "tomcat")
	ghostcat     = newTemplate("network/cves/CVE-2020-1938.yaml", "CVE-2020-1938", severity.Critical, "geode", "cve", "apache", "tomcat")
	gitConfig    = newTemplate("http/exposures/git-config.yaml", "git-config", severity.Medium, "", "exposure", "git")
	allTemplates = []*templates.Template{thinkphpRCE, tomcatPanel, ghostcat, gitConfig}
)

func selected(t *testing.T, r *Registry, input string) []string {
	t.Helper()
	selection := r.For(&contextargs.MetaInput{Input: input})
	var ids []string
	for _, tpl := range allTemplates {
		if selection == nil || selection.Allows(tpl.Path) {
			ids = append(ids, tpl.ID)
		}
	}
	return ids
}

func bindLine(t *testing.T, r *Registry, line string) string {
	t.Helper()
	parsed, err := r.ParseLine(line)
	require.NoError(t, err)
	r.Bind(&contextargs.MetaInput{Input: parsed.Target, CustomIP: parsed.IP}, parsed.Selection)
	return parsed.Target
}

func input(target string) *contextargs.MetaInput {
	return &contextargs.MetaInput{Input: target}
}

func TestParseLineRejectsInvalidLines(t *testing.T) {
	r := NewRegistry(templatesDir)
	for name, line := range map[string]string{
		"malformed json":   `{"target": "a.com"`,
		"missing target":   `{"tags": ["cve"]}`,
		"unknown key":      `{"target": "a.com", "tag": ["cve"]}`,
		"invalid severity": `{"target": "a.com", "severity": ["urgent"]}`,
		"invalid type":     `{"target": "a.com", "type": ["smtp"]}`,
		"non string value": `{"target": "a.com", "tags": [1]}`,
		"missing profile":  `{"target": "a.com", "profile": "does-not-exist"}`,
		"non string ip":    `{"target": "a.com", "ip": 10}`,
		"invalid ip":       `{"target": "a.com", "ip": "10.0.0"}`,
		"ip with zone":     `{"target": "a.com", "ip": "fe80::1%eth0"}`,
		"unspecified ip":   `{"target": "a.com", "ip": "0.0.0.0"}`,
		"ip target":        `{"target": "https://192.0.2.1", "ip": "192.0.2.10"}`,
		"cidr target":      `{"target": "192.0.2.0/24", "ip": "192.0.2.10"}`,
		"asn target":       `{"target": "AS13335", "ip": "192.0.2.10"}`,
	} {
		t.Run(name, func(t *testing.T) {
			_, err := r.ParseLine(line)
			require.Error(t, err)
		})
	}
}

func TestParseLineIP(t *testing.T) {
	r := NewRegistry(templatesDir)
	for line, want := range map[string]Line{
		`{"target": "https://a.com", "ip": "192.0.2.10"}`:             {Target: "https://a.com", IP: "192.0.2.10"},
		`{"target": "a.com:8443", "ip": " 2001:DB8::1 "}`:             {Target: "a.com:8443", IP: "2001:db8::1"},
		`{"target": "a.com", "ip": "::ffff:192.0.2.10"}`:              {Target: "a.com", IP: "192.0.2.10"},
		`{"target": "a.com"}`:                                         {Target: "a.com"},
		`{"target": "https://a.com", "ip": "192.0.2.10", "tags": []}`: {Target: "https://a.com", IP: "192.0.2.10"},
	} {
		t.Run(line, func(t *testing.T) {
			parsed, err := r.ParseLine(line)
			require.NoError(t, err)
			require.Equal(t, want, parsed)
		})
	}
	require.False(t, r.Scoped(), "lines that only set an ip do not scope the scan")
	require.Nil(t, r.LoadFilter())
}

func TestPinnedTargetsKeepTheirSelection(t *testing.T) {
	r := NewRegistry(templatesDir)
	bindLine(t, r, `{"target": "https://a.com", "ip": "192.0.2.10", "tags": ["thinkphp"]}`)
	bindLine(t, r, `{"target": "https://a.com", "ip": "192.0.2.11", "tags": ["tomcat"]}`)
	bindLine(t, r, `{"target": "https://a.com", "ip": "192.0.2.12"}`)
	r.Prepare(allTemplates)

	selectedFor := func(ip string) []string {
		selection := r.For(&contextargs.MetaInput{Input: "https://a.com", CustomIP: ip})
		var ids []string
		for _, tpl := range allTemplates {
			if selection == nil || selection.Allows(tpl.Path) {
				ids = append(ids, tpl.ID)
			}
		}
		return ids
	}
	require.Equal(t, []string{"thinkphp-rce"}, selectedFor("192.0.2.10"))
	require.Equal(t, []string{"tomcat-panel", "CVE-2020-1938"}, selectedFor("192.0.2.11"))
	require.Equal(t, []string{"thinkphp-rce", "tomcat-panel", "CVE-2020-1938", "git-config"}, selectedFor("192.0.2.12"))
}

func TestProfileMustBeAnID(t *testing.T) {
	dir := t.TempDir()
	require.NoError(t, os.MkdirAll(filepath.Join(dir, "profiles"), 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(dir, "profiles", "php.yml"), []byte("tags: [thinkphp]\n"), 0o600))
	outside := filepath.Join(dir, "outside.yml")
	require.NoError(t, os.WriteFile(outside, []byte("tags: [tomcat]\n"), 0o600))

	r := NewRegistry(dir)
	for _, profile := range []string{outside, "../outside.yml", "../outside", "profiles/php.yml", "php.yml", `profiles\php`, ".."} {
		t.Run(profile, func(t *testing.T) {
			line, err := json.Marshal(map[string]string{"target": "a.com", "profile": profile})
			require.NoError(t, err)
			_, err = r.ParseLine(string(line))
			require.ErrorContains(t, err, "profile ID")
		})
	}

	parsed, err := r.ParseLine(`{"target": "a.com", "profile": "php"}`)
	require.NoError(t, err)
	require.Equal(t, []string{"thinkphp"}, parsed.Selection.rules[0].filter.Tags)
}

func TestSelectionFilters(t *testing.T) {
	r := NewRegistry(templatesDir)
	tags := bindLine(t, r, `{"target": "https://a.com", "tags": ["thinkphp"]}`)
	commaTags := bindLine(t, r, `{"target": "https://b.com", "tags": "tomcat, exposure"}`)
	sev := bindLine(t, r, `{"target": "https://c.com", "severity": ["critical"], "exclude-id": ["CVE-2020-1938"]}`)
	paths := bindLine(t, r, `{"target": "https://d.com", "templates": ["http/"]}`)
	r.Prepare(allTemplates)

	require.Equal(t, []string{"thinkphp-rce"}, selected(t, r, tags))
	require.Equal(t, []string{"tomcat-panel", "CVE-2020-1938", "git-config"}, selected(t, r, commaTags))
	require.Equal(t, []string{"thinkphp-rce"}, selected(t, r, sev))
	require.Equal(t, []string{"thinkphp-rce", "tomcat-panel", "git-config"}, selected(t, r, paths))
	require.Equal(t, []string{"thinkphp-rce", "tomcat-panel", "CVE-2020-1938", "git-config"}, selected(t, r, "https://unlisted.com"))
}

func TestSelectionTech(t *testing.T) {
	r := NewRegistry(templatesDir)
	tomcat := bindLine(t, r, `{"target": "https://a.com", "tech": ["Apache Tomcat"]}`)
	php := bindLine(t, r, `{"target": "https://b.com", "tech": ["ThinkPHP"], "severity": ["critical", "medium"]}`)
	r.Prepare(allTemplates)

	// product-bound templates follow the tech list, generic ones always run;
	// Ghostcat declares product "geode" but is kept by its tomcat tag
	require.Equal(t, []string{"tomcat-panel", "CVE-2020-1938", "git-config"}, selected(t, r, tomcat))
	require.Equal(t, []string{"thinkphp-rce", "git-config"}, selected(t, r, php))
}

func TestProfileWithInlineOverride(t *testing.T) {
	dir := t.TempDir()
	require.NoError(t, os.MkdirAll(filepath.Join(dir, "profiles"), 0o755))
	profile := "code: true\ntags:\n  - thinkphp\nseverity:\n  - info\n"
	require.NoError(t, os.WriteFile(filepath.Join(dir, "profiles", "php.yml"), []byte(profile), 0o600))

	r := NewRegistry(dir)
	parsed, err := r.ParseLine(`{"target": "https://a.com", "profile": "php", "severity": "critical"}`)
	require.NoError(t, err)
	require.Len(t, parsed.Selection.rules, 1)
	require.Equal(t, []string{"thinkphp"}, parsed.Selection.rules[0].filter.Tags)
	require.Equal(t, []severity.Severity{severity.Critical}, parsed.Selection.rules[0].filter.Severities)
	require.Equal(t, "https://a.com", parsed.Target)
}

func TestDuplicateTargetsMerge(t *testing.T) {
	r := NewRegistry(templatesDir)
	phpLine, err := r.ParseLine(`{"target": "https://a.com", "tags": ["thinkphp"]}`)
	require.NoError(t, err)
	tomcatLine, err := r.ParseLine(`{"target": "https://a.com", "tags": ["tomcat"]}`)
	require.NoError(t, err)
	php, tomcat := phpLine.Selection, tomcatLine.Selection

	r.Bind(input("https://a.com"), php)
	r.Merge(input("https://a.com"), tomcat)
	r.Merge(input("https://a.com"), php)
	r.Bind(input("https://b.com"), php)
	r.Merge(input("https://b.com"), nil)
	r.Bind(input("https://c.com"), nil)
	r.Merge(input("https://c.com"), php)
	r.Prepare(allTemplates)

	require.Equal(t, []string{"thinkphp-rce", "tomcat-panel", "CVE-2020-1938"}, selected(t, r, "https://a.com"))
	require.Nil(t, r.For(&contextargs.MetaInput{Input: "https://b.com"}), "a plain duplicate lifts the restriction")
	require.Nil(t, r.For(&contextargs.MetaInput{Input: "https://c.com"}), "a plain target stays unrestricted")

	again, err := r.ParseLine(`{"target": "https://z.com", "tags": ["thinkphp"]}`)
	require.NoError(t, err)
	require.Same(t, php, again.Selection, "identical selectors are interned")
}

func TestLoadFilter(t *testing.T) {
	t.Run("union of selections", func(t *testing.T) {
		r := NewRegistry(templatesDir)
		bindLine(t, r, `{"target": "https://a.com", "tags": ["thinkphp"]}`)
		bindLine(t, r, `{"target": "https://b.com", "tech": ["tomcat"], "severity": ["info"]}`)
		filter := r.LoadFilter()
		require.NotNil(t, filter)

		r.Prepare(allTemplates)
		var loaded []string
		for _, tpl := range allTemplates {
			if filter(r.metadata[tpl.Path]) {
				loaded = append(loaded, tpl.ID)
			}
		}
		require.Equal(t, []string{"thinkphp-rce", "tomcat-panel"}, loaded)
	})

	t.Run("unrestricted target loads everything", func(t *testing.T) {
		r := NewRegistry(templatesDir)
		bindLine(t, r, `{"target": "https://a.com", "tags": ["thinkphp"]}`)
		r.Bind(input("https://b.com"), nil)
		require.Nil(t, r.LoadFilter())
	})

	t.Run("plain duplicate of a target line loads everything", func(t *testing.T) {
		r := NewRegistry(templatesDir)
		target := bindLine(t, r, `{"target": "https://a.com", "tags": ["thinkphp"]}`)
		r.Merge(input(target), nil)
		require.Nil(t, r.LoadFilter())
	})
}

func TestTechTokens(t *testing.T) {
	for tech, want := range map[string][]string{
		"nginx":         {"nginx"},
		"ThinkPHP":      {"thinkphp"},
		"apache_tomcat": {"apache-tomcat"},
		"Apache Tomcat": {"apache-tomcat", "apache", "tomcat"},
		"apache:tomcat": {"apache-tomcat", "apache", "tomcat"},
		"Microsoft IIS": {"microsoft-iis", "microsoft", "iis"},
		"  ":            nil,
	} {
		require.Equal(t, want, techTokens(tech), tech)
	}
}

func TestBindTechNarrowsOnlyTargetsWithoutASelection(t *testing.T) {
	r := NewRegistry(templatesDir)
	profiled := bindLine(t, r, `{"target": "https://a.example", "tags": ["thinkphp"]}`)
	require.NoError(t, r.BindTech(input(profiled), []string{"tomcat"}))
	require.NoError(t, r.BindTech(input("https://b.example"), []string{"tomcat-detect", "Apache Tomcat"}))
	r.Prepare(allTemplates)

	require.Equal(t, []string{"thinkphp-rce"}, selected(t, r, profiled), "its own selection is kept")
	require.Equal(t, []string{"tomcat-panel", "CVE-2020-1938", "git-config"}, selected(t, r, "https://b.example"))
	require.Len(t, selected(t, r, "https://c.example"), len(allTemplates), "nothing detected, nothing skipped")
}

func TestBindTechKeepsALineWidenedByAPlainDuplicate(t *testing.T) {
	r := NewRegistry(templatesDir)
	target := bindLine(t, r, `{"target": "https://a.example", "tags": ["thinkphp"]}`)
	r.Merge(input(target), nil)
	require.NoError(t, r.BindTech(input(target), []string{"tomcat"}))
	r.Prepare(allTemplates)

	require.Len(t, selected(t, r, target), len(allTemplates), "the union runs everything, thinkphp-rce included")
}

package targetprofile

import (
	"fmt"
	"path/filepath"
	"slices"
	"strings"
	"unicode"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/index"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// rule is a compiled selector.
type rule struct {
	key    string
	filter *index.Filter
	paths  []string
	tech   map[string]struct{}
}

func compileRule(sel selector, templatesDir string) (*rule, error) {
	var severities, excludeSeverities severity.Severities
	if err := setAll(&severities, sel[keySeverity]); err != nil {
		return nil, fmt.Errorf("key %q: %w", keySeverity, err)
	}
	if err := setAll(&excludeSeverities, sel[keyExcludeSeverity]); err != nil {
		return nil, fmt.Errorf("key %q: %w", keyExcludeSeverity, err)
	}
	var protocols, excludeProtocols types.ProtocolTypes
	if err := setAll(&protocols, sel[keyType]); err != nil {
		return nil, fmt.Errorf("key %q: %w", keyType, err)
	}
	if err := setAll(&excludeProtocols, sel[keyExcludeType]); err != nil {
		return nil, fmt.Errorf("key %q: %w", keyExcludeType, err)
	}

	r := &rule{
		filter: &index.Filter{
			Authors:              lowered(sel[keyAuthor]),
			Tags:                 lowered(sel[keyTags]),
			ExcludeTags:          lowered(sel[keyExcludeTags]),
			IncludeTags:          lowered(sel[keyIncludeTags]),
			IDs:                  sel[keyTemplateID],
			ExcludeIDs:           sel[keyExcludeID],
			Severities:           severities,
			ExcludeSeverities:    excludeSeverities,
			ProtocolTypes:        protocols,
			ExcludeProtocolTypes: excludeProtocols,
		},
	}
	for _, path := range sel[keyTemplates] {
		if !filepath.IsAbs(path) {
			path = filepath.Join(templatesDir, path)
		}
		r.paths = append(r.paths, filepath.Clean(path))
	}
	if len(sel[keyTech]) > 0 {
		r.tech = make(map[string]struct{}, len(sel[keyTech]))
		for _, tech := range sel[keyTech] {
			for _, token := range techTokens(tech) {
				r.tech[token] = struct{}{}
			}
		}
	}

	key, err := canonicalKey(sel)
	if err != nil {
		return nil, err
	}
	r.key = key
	return r, nil
}

// matches reports whether the template described by m is selected.
func (r *rule) matches(m *index.Metadata) bool {
	if !r.filter.Matches(m) {
		return false
	}
	if len(r.paths) > 0 && !slices.ContainsFunc(r.paths, func(path string) bool { return underPath(m.FilePath, path) }) {
		return false
	}
	return r.matchesTech(m)
}

// matchesTech implements tech-aware selection: templates bound to a product run
// only when the target runs that product, every other template always runs.
// A template is bound when it declares metadata.product; its tags are matched
// too because product metadata is sometimes imprecise (CVE-2020-1938 targets
// Tomcat but declares product "geode"). Erring on running a template keeps
// coverage when metadata and the target's tech list disagree.
func (r *rule) matchesTech(m *index.Metadata) bool {
	if len(r.tech) == 0 || m.Product == "" {
		return true
	}
	if _, ok := r.tech[normalizeTech(m.Product)]; ok {
		return true
	}
	for _, tag := range m.Tags {
		if _, ok := r.tech[normalizeTech(tag)]; ok {
			return true
		}
	}
	return false
}

func anyMatches(rules []*rule, m *index.Metadata) bool {
	return slices.ContainsFunc(rules, func(r *rule) bool { return r.matches(m) })
}

// techTokens expands a tech name reported by a fingerprinting tool into the
// tokens template metadata uses: "Apache Tomcat" and "apache:tomcat" yield
// apache-tomcat, apache and tomcat. Extra tokens can only select more
// templates, never fewer.
func techTokens(tech string) []string {
	words := strings.FieldsFunc(strings.ToLower(tech), func(r rune) bool { return r == ':' || unicode.IsSpace(r) })
	if len(words) == 0 {
		return nil
	}
	tokens := []string{normalizeTech(strings.Join(words, " "))}
	if len(words) > 1 {
		for _, word := range words {
			tokens = append(tokens, normalizeTech(word))
		}
	}
	return tokens
}

// normalizeTech maps a product or tag to its token form ("Apache_Tomcat" and
// "apache tomcat" both become apache-tomcat).
func normalizeTech(tech string) string {
	tech = strings.ReplaceAll(strings.ToLower(tech), "_", "-")
	return strings.Join(strings.Fields(tech), "-")
}

func underPath(templatePath, path string) bool {
	templatePath = filepath.Clean(templatePath)
	if templatePath == path || strings.HasPrefix(templatePath, path+string(filepath.Separator)) {
		return true
	}
	matched, _ := filepath.Match(path, templatePath)
	return matched
}

// canonicalKey identifies equivalent selectors so they share one compiled rule.
func canonicalKey(sel selector) (string, error) {
	normalized := make(map[string][]string, len(sel))
	for key, values := range sel {
		values = slices.Clone(values)
		slices.Sort(values)
		normalized[key] = slices.Compact(values)
	}
	data, err := json.Marshal(normalized)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func setAll(value interface{ Set(string) error }, values []string) error {
	if len(values) == 0 {
		return nil
	}
	return value.Set(strings.Join(values, ","))
}

func lowered(values []string) []string {
	if len(values) == 0 {
		return nil
	}
	out := make([]string, len(values))
	for i, value := range values {
		out[i] = strings.ToLower(value)
	}
	return out
}

// Package targetprofile binds template selections to individual targets, so a
// single scan can run a different profile on each target.
//
// A target line is a JSON object whose keys mirror template profiles and CLI
// flags, and may pin the target to an ip:
//
//	{"target": "https://a.example", "tags": ["thinkphp"], "tech": ["php"]}
//	{"target": "https://b.example", "profile": "wordpress", "severity": ["high"]}
//	{"target": "https://c.example", "ip": "192.0.2.10"}
package targetprofile

import (
	"errors"
	"fmt"
	"net/netip"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/projectdiscovery/mapcidr/asn"
	"github.com/projectdiscovery/nuclei/v3/internal/configuration"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/yaml"
	iputil "github.com/projectdiscovery/utils/ip"
	urlutil "github.com/projectdiscovery/utils/url"
)

const (
	keyTarget  = "target"
	keyProfile = "profile"
	keyIP      = "ip"

	keyTemplates       = "templates"
	keyTags            = "tags"
	keyExcludeTags     = "exclude-tags"
	keyIncludeTags     = "include-tags"
	keyAuthor          = "author"
	keyTemplateID      = "template-id"
	keyExcludeID       = "exclude-id"
	keySeverity        = "severity"
	keyExcludeSeverity = "exclude-severity"
	keyType            = "type"
	keyExcludeType     = "exclude-type"
	keyTech            = "tech"
)

// selectorKeys are the template selection keys a target line or profile may set.
var selectorKeys = []string{
	keyTemplates, keyTags, keyExcludeTags, keyIncludeTags, keyAuthor, keyTemplateID,
	keyExcludeID, keySeverity, keyExcludeSeverity, keyType, keyExcludeType, keyTech,
}

// selector is a raw template selection keyed by selector key.
type selector map[string][]string

// IsLine reports whether an input line is a target line rather than a plain target.
func IsLine(line string) bool {
	return strings.HasPrefix(strings.TrimSpace(line), "{")
}

// parseLine decodes a target line. Unknown keys are rejected so that a typo
// cannot silently widen the scan to every template.
func parseLine(line string) (target, profile, ip string, sel selector, err error) {
	var raw map[string]any
	if err := json.Unmarshal([]byte(line), &raw); err != nil {
		return "", "", "", nil, fmt.Errorf("invalid target line %q: %w", line, err)
	}

	target, err = stringValue(raw, keyTarget)
	if err != nil {
		return "", "", "", nil, err
	}
	target = strings.TrimSpace(target)
	if target == "" {
		return "", "", "", nil, fmt.Errorf("target line %q has no %q", line, keyTarget)
	}

	profile, err = stringValue(raw, keyProfile)
	if err != nil {
		return "", "", "", nil, err
	}
	ip, err = stringValue(raw, keyIP)
	if err != nil {
		return "", "", "", nil, err
	}
	if ip != "" {
		if ip, err = pinnedIP(target, ip); err != nil {
			return "", "", "", nil, fmt.Errorf("target %q: %w", target, err)
		}
	}
	delete(raw, keyTarget)
	delete(raw, keyProfile)
	delete(raw, keyIP)

	sel, ignored, err := toSelector(raw)
	if err != nil {
		return "", "", "", nil, fmt.Errorf("target %q: %w", target, err)
	}
	if len(ignored) > 0 {
		return "", "", "", nil, fmt.Errorf("target %q: unknown keys %s (supported: target, ip, profile, %s)", target, strings.Join(ignored, ", "), strings.Join(selectorKeys, ", "))
	}
	return target, profile, ip, sel, nil
}

// pinnedIP validates the ip a target is pinned to and returns it in canonical
// form. Only a target with a hostname can be pinned: the hostname is kept for
// the Host header, SNI and template variables while connections go to the ip.
func pinnedIP(target, value string) (string, error) {
	addr, err := netip.ParseAddr(strings.TrimSpace(value))
	if err != nil || addr.Zone() != "" || addr.IsUnspecified() {
		return "", fmt.Errorf("invalid ip %q", value)
	}
	if iputil.IsCIDR(target) || asn.IsASN(target) {
		return "", errors.New("a CIDR or ASN target cannot have an ip")
	}
	parsed, err := urlutil.Parse(target)
	if err != nil || parsed.Hostname() == "" || iputil.IsIP(parsed.Hostname()) {
		return "", errors.New("a target with an ip must have a hostname")
	}
	return addr.Unmap().String(), nil
}

// loadProfile reads the selection keys of a template profile. Keys that
// configure the whole scan (code, var, rate limits...) cannot apply to a single
// target and are returned as ignored.
func loadProfile(profile, templatesDir string) (selector, []string, error) {
	// Target lines often come from other tools, so a profile is only looked up
	// by ID inside the profiles directory and never read from a given path.
	if profile == "" || strings.ContainsAny(profile, `/\`) || filepath.Ext(profile) != "" {
		return nil, nil, fmt.Errorf("profile %q must be a profile ID from %s", profile, filepath.Join(templatesDir, "profiles"))
	}
	path, err := configuration.ResolveProfilePath(profile, templatesDir)
	if err != nil {
		return nil, nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, nil, fmt.Errorf("read profile %q: %w", path, err)
	}
	var raw map[string]any
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return nil, nil, fmt.Errorf("parse profile %q: %w", path, err)
	}
	sel, ignored, err := toSelector(raw)
	if err != nil {
		return nil, nil, fmt.Errorf("profile %q: %w", path, err)
	}
	return sel, ignored, nil
}

// toSelector extracts selector keys from raw, returning the other keys as ignored.
func toSelector(raw map[string]any) (selector, []string, error) {
	sel := selector{}
	var ignored []string
	for key, value := range raw {
		if !slices.Contains(selectorKeys, key) {
			ignored = append(ignored, key)
			continue
		}
		values, err := stringList(value)
		if err != nil {
			return nil, nil, fmt.Errorf("key %q: %w", key, err)
		}
		if len(values) > 0 {
			sel[key] = values
		}
	}
	slices.Sort(ignored)
	return sel, ignored, nil
}

// merge returns base overridden by the keys set in override, the same way
// CLI flags override a profile.
func (base selector) merge(override selector) selector {
	merged := make(selector, len(base)+len(override))
	for key, values := range base {
		merged[key] = values
	}
	for key, values := range override {
		merged[key] = values
	}
	return merged
}

func stringValue(raw map[string]any, key string) (string, error) {
	value, ok := raw[key]
	if !ok || value == nil {
		return "", nil
	}
	str, ok := value.(string)
	if !ok {
		return "", fmt.Errorf("key %q must be a string", key)
	}
	return str, nil
}

// stringList accepts a comma-separated string or a list of strings, matching
// how the equivalent CLI flags and profile keys are written.
func stringList(value any) ([]string, error) {
	var items []string
	switch v := value.(type) {
	case nil:
	case string:
		items = strings.Split(v, ",")
	case []any:
		for _, item := range v {
			str, ok := item.(string)
			if !ok {
				return nil, fmt.Errorf("expected strings, got %T", item)
			}
			items = append(items, str)
		}
	default:
		return nil, fmt.Errorf("expected a string or a list of strings, got %T", value)
	}

	values := make([]string, 0, len(items))
	for _, item := range items {
		if item = strings.TrimSpace(item); item != "" {
			values = append(values, item)
		}
	}
	return values, nil
}

package input

import (
	"net"
	"path/filepath"
	"strings"

	"github.com/projectdiscovery/hmap/store/hybrid"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	fileutil "github.com/projectdiscovery/utils/file"
	"github.com/projectdiscovery/utils/ports"
	stringsutil "github.com/projectdiscovery/utils/strings"
	urlutil "github.com/projectdiscovery/utils/url"
)

// Helper is a structure for helping with input transformation
type Helper struct {
	InputsHTTP *hybrid.HybridMap
}

// NewHelper returns a new input helper instance
func NewHelper() *Helper {
	helper := &Helper{}
	return helper
}

// Close closes the resources associated with input helper
func (h *Helper) Close() error {
	var err error
	if h.InputsHTTP != nil {
		err = h.InputsHTTP.Close()
	}
	return err
}

// Transform transforms an input based on protocol type and returns
// appropriate input based on it.
func (h *Helper) Transform(input string, protocol templateTypes.ProtocolType) string {
	switch protocol {
	case templateTypes.DNSProtocol, templateTypes.WHOISProtocol:
		return h.convertInputToType(input, typeHostOnly, "")
	case templateTypes.FileProtocol, templateTypes.OfflineHTTPProtocol:
		return h.convertInputToType(input, typeFilepath, "")
	case templateTypes.HTTPProtocol, templateTypes.HeadlessProtocol:
		return h.convertInputToType(input, typeURL, "")
	case templateTypes.NetworkProtocol:
		return h.convertInputToType(input, typeHostWithOptionalPort, "")
	case templateTypes.WebsocketProtocol:
		return h.convertInputToType(input, typeWebsocket, "")
	case templateTypes.SSLProtocol:
		return h.convertInputToType(input, typeHostWithPort, "443")
	}
	return input
}

// TransformPinned is Transform for an input pinned to ip, which takes the
// HTTP probe result made through that ip and never the result of the input
// without an ip, as that one may come from another server.
func (h *Helper) TransformPinned(input, ip string, protocol templateTypes.ProtocolType) string {
	if ip == "" || (protocol != templateTypes.HTTPProtocol && protocol != templateTypes.HeadlessProtocol) {
		return h.Transform(input, protocol)
	}
	if h.InputsHTTP != nil {
		if probed, ok := h.InputsHTTP.Get(ProbeKey(input, ip)); ok {
			return string(probed)
		}
	}
	// no probe through this ip: convert it as an input that was not probed
	return (&Helper{}).Transform(input, protocol)
}

// ProbeKey returns the key of the HTTP probe result of input in InputsHTTP.
// A target pinned to an ip is probed through that ip, so each ip has its own.
// The separator cannot occur in an input, which may hold an "@" of its own.
func ProbeKey(input, ip string) string {
	if ip == "" {
		return input
	}
	return input + "\x00" + ip
}

type inputType int

const (
	typeHostOnly inputType = iota + 1
	typeHostWithPort
	typeHostWithOptionalPort
	typeURL
	typeFilepath
	typeWebsocket
)

// convertInputToType converts an input based on an inputType.
// Various formats are supported for inputs and their transformation
func (h *Helper) convertInputToType(input string, inputType inputType, defaultPort string) string {
	isURL := strings.Contains(input, "://")
	uri, _ := urlutil.Parse(input)
	// Parse treats a single-label host such as "intranet" as a relative path
	// and clears Host. The input is already absolute, so parse it as one.
	if isURL {
		if abs, err := urlutil.ParseAbsoluteURL(input, false); err == nil {
			uri = abs
		}
	}

	var host, port string
	if isURL && uri != nil {
		host, port, _ = net.SplitHostPort(uri.Host)
	} else {
		host, port, _ = net.SplitHostPort(input)
	}

	hasHost := host != ""
	hasPort := ports.IsValid(port)
	hasDefaultPort := ports.IsValid(defaultPort)

	switch inputType {
	case typeFilepath:
		// if it has ports most likely it's not a file
		if hasPort {
			return ""
		}
		if filepath.IsAbs(input) {
			return input
		}
		if absPath, _ := filepath.Abs(input); absPath != "" && fileutil.FileOrFolderExists(absPath) {
			return input
		}
		if _, err := filepath.Match(input, ""); err != filepath.ErrBadPattern && !isURL {
			return input
		}
		// if none of these satisfy the condition return empty
		return ""
	case typeHostOnly:
		if hasHost {
			return host
		}
		if isURL && uri != nil {
			return uri.Hostname()
		}
		return input
	case typeURL:
		if uri != nil && stringsutil.EqualFoldAny(uri.Scheme, "http", "https") {
			return input
		}
		if h.InputsHTTP != nil {
			if probed, ok := h.InputsHTTP.Get(input); ok {
				return string(probed)
			}
		}
		// try to parse it as absolute url and return
		if absUrl, err := urlutil.ParseAbsoluteURL(input, false); err == nil {
			return absUrl.String()
		}
	case typeHostWithPort, typeHostWithOptionalPort:
		if hasHost && hasPort {
			// The network request replaces a reserved port that the scheme
			// implied, and keeps one the operator typed after a bare host. It
			// can tell them apart only while the URL keeps its scheme.
			if isURL && inputType == typeHostWithOptionalPort {
				return input
			}
			return net.JoinHostPort(host, port)
		}
		// An optional port is left to the request, which knows the template
		// port and applies the scheme default only when the template has none.
		if uri != nil && !hasPort && uri.Scheme == "https" && inputType == typeHostWithPort {
			// uri.Host keeps the brackets of an IPv6 literal, while
			// JoinHostPort adds them again, yielding "[[::1]]:443".
			return net.JoinHostPort(uri.Hostname(), "443")
		}
		if hasDefaultPort {
			// For a URL input the host is the parsed hostname, not the raw
			// input: JoinHostPort(input, defaultPort) brackets the raw string
			// (a scheme carries a colon), producing e.g. "[http://example.com]:443",
			// which is not a usable host:port.
			if isURL && uri != nil && !hasPort && uri.Hostname() != "" {
				return net.JoinHostPort(uri.Hostname(), defaultPort)
			}
			return net.JoinHostPort(input, defaultPort)
		}
		if inputType == typeHostWithOptionalPort {
			return input
		}
	case typeWebsocket:
		if uri != nil && stringsutil.EqualFoldAny(uri.Scheme, "ws", "wss") {
			return input
		}
		// empty if prefix is not given
		return ""
	}
	// do not return empty
	return input
}

package input

import (
	"testing"

	"github.com/projectdiscovery/hmap/store/hybrid"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	"github.com/stretchr/testify/require"
)

func TestTransformPinned(t *testing.T) {
	hm, err := hybrid.New(hybrid.DefaultDiskOptions)
	require.NoError(t, err, "could not create hybrid map")
	defer func() {
		_ = hm.Close()
	}()
	helper := &Helper{InputsHTTP: hm}

	_ = hm.Set(ProbeKey("app.test", ""), []byte("http://app.test"))
	_ = hm.Set(ProbeKey("app.test", "127.0.0.2"), []byte("https://app.test"))

	require.Equal(t, "https://app.test", helper.TransformPinned("app.test", "127.0.0.2", templateTypes.HTTPProtocol), "the probe made through the pinned ip")
	require.Equal(t, "http://app.test", helper.TransformPinned("app.test", "", templateTypes.HTTPProtocol), "an unpinned input")
	require.Equal(t, "app.test", helper.TransformPinned("app.test", "127.0.0.3", templateTypes.HTTPProtocol), "an ip without a probe of its own does not take the unpinned result")
	require.Equal(t, "app.test", helper.TransformPinned("app.test", "127.0.0.2", templateTypes.DNSProtocol), "a protocol that is not probed")
	require.NotEqual(t, ProbeKey("u.example@192.0.2.10", ""), ProbeKey("u.example", "192.0.2.10"), "an input holding an @ does not collide with a pinned one")
}

func TestConvertInputToType(t *testing.T) {
	helper := &Helper{}

	hm, err := hybrid.New(hybrid.DefaultDiskOptions)
	require.NoError(t, err, "could not create hybrid map")
	helper.InputsHTTP = hm
	defer func() {
		_ = hm.Close()
	}()

	_ = hm.Set("google.com", []byte("https://google.com"))

	tests := []struct {
		input       string
		inputType   inputType
		result      string
		defaultPort string
	}{
		// host
		{"google.com", typeHostOnly, "google.com", ""},
		{"google.com:443", typeHostOnly, "google.com", ""},
		{"https://google.com", typeHostOnly, "google.com", ""},
		{"https://google.com:443", typeHostOnly, "google.com", ""},
		{"http://[::1]", typeHostOnly, "::1", ""},
		{"https://[::1]:8443", typeHostOnly, "::1", ""},
		{"http://192.0.2.10", typeHostOnly, "192.0.2.10", ""},
		{"http://intranet", typeHostOnly, "intranet", ""},

		// url
		{"test.com", typeURL, "test.com", ""},
		{"google.com", typeURL, "https://google.com", ""},
		{"https://google.com", typeURL, "https://google.com", ""},

		// file
		{"google.com:443", typeFilepath, "", ""},
		{"https://google.com:443", typeFilepath, "", ""},
		{"/example/path", typeFilepath, "/example/path", ""},
		{"input_test.go", typeFilepath, "input_test.go", ""},
		{"../input", typeFilepath, "../input", ""},
		{"input_test.*", typeFilepath, "input_test.*", ""},

		// host-port
		{"google.com", typeHostWithPort, "google.com", ""},
		{"google.com:443", typeHostWithPort, "google.com:443", ""},
		{"https://google.com", typeHostWithPort, "google.com:443", ""},
		{"https://google.com:443", typeHostWithPort, "google.com:443", ""},
		// host-port with default port
		{"google.com", typeHostWithPort, "google.com:443", "443"},
		// host-port with default port and a URL input: the host must come from
		// the parsed URL, never from the raw input string
		{"http://google.com", typeHostWithPort, "google.com:443", "443"},
		{"http://google.com/path", typeHostWithPort, "google.com:443", "443"},
		{"http://192.0.2.10", typeHostWithPort, "192.0.2.10:443", "443"},
		{"http://localhost", typeHostWithPort, "localhost:443", "443"},
		{"http://[::1]", typeHostWithPort, "[::1]:443", "443"},
		{"http://intranet", typeHostWithPort, "intranet:443", "443"},
		{"http://intranet/path", typeHostWithPort, "intranet:443", "443"},
		{"http://intranet:8080", typeHostWithPort, "intranet:8080", "443"},
		// an explicit port always wins over the default port
		{"http://google.com:8443", typeHostWithPort, "google.com:8443", "443"},
		{"http://google.com:443", typeHostWithPort, "google.com:443", "443"},
		// without a default port the URL input is left alone
		{"http://google.com", typeHostWithPort, "http://google.com", ""},
		{"http://intranet", typeHostWithPort, "http://intranet", ""},
		{"https://google.com/path", typeHostWithPort, "google.com:443", ""},
		// an IPv6 literal in a https URL must not be double bracketed
		{"https://[::1]", typeHostWithPort, "[::1]:443", ""},

		// host with optional port
		{"google.com", typeHostWithOptionalPort, "google.com", ""},
		{"google.com:443", typeHostWithOptionalPort, "google.com:443", ""},
		// no port of its own: the request has the template port to take
		{"https://google.com", typeHostWithOptionalPort, "https://google.com", ""},
		// a URL with a port keeps its scheme: the request replaces a reserved
		// port that the scheme implied, and keeps one typed after a bare host
		{"https://google.com:443", typeHostWithOptionalPort, "https://google.com:443", ""},
		{"http://google.com:8080", typeHostWithOptionalPort, "http://google.com:8080", ""},
		{"http://[::1]:8080", typeHostWithOptionalPort, "http://[::1]:8080", ""},
		// host with optional port and default port
		{"google.com", typeHostWithOptionalPort, "google.com:443", "443"},
		{"http://google.com", typeHostWithOptionalPort, "google.com:443", "443"},

		// websocket
		{"google.com", typeWebsocket, "", ""},
		{"google.com:443", typeWebsocket, "", ""},
		{"https://google.com:443", typeWebsocket, "", ""},
		{"wss://google.com", typeWebsocket, "wss://google.com", ""},
	}

	for _, test := range tests {
		result := helper.convertInputToType(test.input, test.inputType, test.defaultPort)
		require.Equal(t, test.result, result, "could not get correct result %+v", test)
	}
}

//go:build gofuzz
// +build gofuzz

package types

// Fuzz exercises raw HTTP request parsing used by input format ingestion.
func Fuzz(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	if len(data) > fuzzMaxInputSize {
		return -1
	}
	if !fuzzRawRequestParsing(data) {
		return 0
	}
	return 1
}

package types

import (
	"fmt"
	"strings"
)

const (
	fuzzMaxInputSize  = 16 << 10
	fuzzMaxHeaders    = 8
	fuzzMaxValueBytes = 256
)

var (
	fuzzMethods = []string{"GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS", "HEAD"}
	fuzzPaths   = []string{"/", "/api/v1/users", "/login", "/search?q=nuclei", "?debug=true"}
	fuzzHosts   = []string{"example.com", "scanme.sh", "127.0.0.1", "example.com:8080"}
)

type fuzzHeader struct {
	key   string
	value string
}

type fuzzRawRequestCandidate struct {
	method    string
	path      string
	host      string
	targetURL string
	headers   []fuzzHeader
	body      string
}

func fuzzRawRequestParsing(data []byte) bool {
	raw, targetURL, ok := rawRequestFromFuzzData(data)
	if !ok {
		return false
	}

	parsed := false
	if rr, err := ParseRawRequest(raw); err == nil {
		exerciseFuzzRequestResponse(rr)
		parsed = true
	}
	if rr, err := ParseRawRequestWithURL(raw, targetURL); err == nil {
		exerciseFuzzRequestResponse(rr)
		parsed = true
	}
	if rr, err := ParseRawRequest(string(data)); err == nil {
		exerciseFuzzRequestResponse(rr)
		parsed = true
	}
	if rr, err := ParseRawRequestWithURL(string(data), targetURL); err == nil {
		exerciseFuzzRequestResponse(rr)
		parsed = true
	}

	return parsed
}

func rawRequestFromFuzzData(data []byte) (string, string, bool) {
	if len(data) == 0 || len(data) > fuzzMaxInputSize {
		return "", "", false
	}

	candidate := newFuzzRawRequestCandidate(data)
	candidate.applyLines(splitFuzzLines(data))
	return candidate.build(), candidate.targetURL, true
}

func newFuzzRawRequestCandidate(data []byte) *fuzzRawRequestCandidate {
	method := fuzzMethods[int(fuzzByteAt(data, 0))%len(fuzzMethods)]
	path := fuzzPaths[int(fuzzByteAt(data, 1))%len(fuzzPaths)]
	host := fuzzHosts[int(fuzzByteAt(data, 2))%len(fuzzHosts)]

	return &fuzzRawRequestCandidate{
		method:    method,
		path:      path,
		host:      host,
		targetURL: "https://" + host + path,
		headers: []fuzzHeader{
			{key: "User-Agent", value: "nuclei-fuzz"},
		},
		body: fuzzBody(string(data)),
	}
}

func (candidate *fuzzRawRequestCandidate) applyLines(lines []string) {
	for _, line := range lines {
		key, value, ok := cutFuzzKV(line)
		if !ok {
			candidate.body = fuzzBody(line)
			continue
		}

		switch key {
		case "method":
			candidate.method = fuzzMethod(value, candidate.method)
		case "path":
			candidate.path = fuzzRelativePath(value, candidate.path)
		case "host":
			candidate.host = fuzzHost(value, candidate.host)
		case "url", "target-url":
			candidate.targetURL = fuzzAbsoluteURL(value, candidate.targetURL)
		case "header":
			candidate.addHeader(value)
		case "body":
			candidate.body = fuzzBody(value)
		}
	}
}

func (candidate *fuzzRawRequestCandidate) addHeader(value string) {
	key, headerValue, ok := strings.Cut(value, ":")
	if !ok {
		key, headerValue, ok = strings.Cut(value, "=")
	}
	if !ok {
		return
	}

	key = fuzzHeaderKey(key)
	if key == "" || strings.EqualFold(key, "Host") || len(candidate.headers) >= fuzzMaxHeaders {
		return
	}
	candidate.headers = append(candidate.headers, fuzzHeader{key: key, value: fuzzHeaderValue(headerValue)})
}

func (candidate *fuzzRawRequestCandidate) build() string {
	var builder strings.Builder
	fmt.Fprintf(&builder, "%s %s HTTP/1.1\r\n", candidate.method, candidate.path)
	fmt.Fprintf(&builder, "Host: %s\r\n", candidate.host)
	for _, header := range candidate.headers {
		fmt.Fprintf(&builder, "%s: %s\r\n", header.key, header.value)
	}
	builder.WriteString("\r\n")
	builder.WriteString(candidate.body)
	return builder.String()
}

func exerciseFuzzRequestResponse(rr *RequestResponse) {
	if rr == nil {
		panic("nil request response")
	}
	if rr.Request == nil {
		panic("nil parsed request")
	}
	_ = rr.Clone()
	_ = rr.ID()
	_, _ = rr.MarshalJSON()
}

func splitFuzzLines(data []byte) []string {
	fields := strings.FieldsFunc(string(data), func(r rune) bool {
		return r == '\n' || r == '\r' || r == ';'
	})
	if len(fields) > fuzzMaxHeaders*4 {
		fields = fields[:fuzzMaxHeaders*4]
	}

	lines := make([]string, 0, len(fields))
	for _, field := range fields {
		field = fuzzTrim(field)
		if field != "" {
			lines = append(lines, field)
		}
	}
	return lines
}

func cutFuzzKV(line string) (string, string, bool) {
	key, value, ok := strings.Cut(line, "=")
	if !ok {
		key, value, ok = strings.Cut(line, ":")
	}
	if !ok {
		return "", "", false
	}
	return strings.ToLower(fuzzTrim(key)), fuzzTrim(value), true
}

func fuzzByteAt(data []byte, index int) byte {
	if len(data) == 0 {
		return 0
	}
	return data[index%len(data)]
}

func fuzzMethod(value, fallback string) string {
	value = strings.ToUpper(fuzzToken(value, 16))
	if value == "" {
		return fallback
	}
	return value
}

func fuzzRelativePath(value, fallback string) string {
	value = fuzzTrim(value)
	if value == "" {
		return fallback
	}
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	if strings.HasPrefix(value, "?") || strings.HasPrefix(value, "/") {
		return value
	}
	return "/" + value
}

func fuzzAbsoluteURL(value, fallback string) string {
	value = fuzzTrim(value)
	if strings.HasPrefix(value, "http://") || strings.HasPrefix(value, "https://") {
		return value
	}
	host := fuzzHost(value, "")
	if host == "" {
		return fallback
	}
	return "https://" + host + "/"
}

func fuzzHost(value, fallback string) string {
	value = strings.ToLower(fuzzTrim(value))
	var builder strings.Builder
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r)
		case r >= '0' && r <= '9':
			builder.WriteRune(r)
		case r == '.' || r == '-' || r == ':':
			builder.WriteRune(r)
		}
		if builder.Len() >= 128 {
			break
		}
	}
	if builder.Len() == 0 {
		return fallback
	}
	return builder.String()
}

func fuzzHeaderKey(value string) string {
	return fuzzToken(value, 64)
}

func fuzzHeaderValue(value string) string {
	return fuzzTrim(value)
}

func fuzzBody(value string) string {
	value = strings.ReplaceAll(value, "\x00", "")
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

func fuzzToken(value string, limit int) string {
	value = fuzzTrim(value)
	var builder strings.Builder
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r - 'a' + 'A')
		case r >= 'A' && r <= 'Z':
			builder.WriteRune(r)
		case r >= '0' && r <= '9':
			builder.WriteRune(r)
		case r == '-':
			builder.WriteRune(r)
		}
		if builder.Len() >= limit {
			break
		}
	}
	return builder.String()
}

func fuzzTrim(value string) string {
	value = strings.TrimSpace(strings.NewReplacer("\x00", "", "\r", " ", "\n", " ").Replace(value))
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

package types

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"net/textproto"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/useragent"
	"github.com/projectdiscovery/utils/conversion"
	mapsutil "github.com/projectdiscovery/utils/maps"
	stringsutil "github.com/projectdiscovery/utils/strings"
	urlutil "github.com/projectdiscovery/utils/url"
)

var (
	_ json.JSONCodec = &RequestResponse{}
)

// RequestResponse is a struct containing request and response
// obtained from one of the input formats.
// this struct can be considered as pd standard for request and response
type RequestResponse struct {
	// Timestamp is the timestamp of the request
	// Timestamp string `json:"timestamp"`
	// URL is the URL of the request
	URL urlutil.URL `json:"url"`
	// Request is the request of the request
	Request *HttpRequest `json:"request"`
	// Response is the response of the request
	Response *HttpResponse `json:"response"`

	// unexported / internal fields
	// lazy build request
	req    *retryablehttp.Request `json:"-"`
	reqErr error                  `json:"-"`
	once   sync.Once              `json:"-"`
}

// Clone clones the request response
func (rr *RequestResponse) Clone() *RequestResponse {
	cloned := &RequestResponse{
		URL: *rr.URL.Clone(),
	}
	if rr.Request != nil {
		cloned.Request = rr.Request.Clone()
	}
	if rr.Response != nil {
		cloned.Response = rr.Response.Clone()
	}
	return cloned
}

// BuildRequest builds a retryablehttp request from the request response
func (rr *RequestResponse) BuildRequest() (*retryablehttp.Request, error) {
	rr.once.Do(func() {
		// Request is optional: UnmarshalJSON only populates it when a "request"
		// key is present, so an entry carrying just a "url" leaves it nil.
		// Dereferencing it below would panic with a nil pointer instead of
		// surfacing a usable error, taking the whole scan down.
		if rr.Request == nil {
			rr.reqErr = fmt.Errorf("could not create request: no request in request response")
			return
		}
		urlx := rr.URL.Clone()
		var body io.Reader = nil
		if rr.Request.Body != "" {
			body = strings.NewReader(rr.Request.Body)
		}
		req, err := retryablehttp.NewRequestFromURL(rr.Request.Method, urlx, body)
		if err != nil {
			rr.reqErr = fmt.Errorf("could not create request: %s", err)
			return
		}
		rr.Request.Headers.Iterate(func(k, v string) bool {
			req.Header.Add(k, v)
			return true
		})
		if req.Header.Get("User-Agent") == "" {
			userAgent := useragent.PickRandom()
			req.Header.Set("User-Agent", userAgent.Raw)
		}
		rr.req = req
	})
	return rr.req, rr.reqErr
}

// To be implemented in the future
// func (rr *RequestResponse) BuildUnsafeRequest()

// ID returns a unique id/hash for request response
func (rr *RequestResponse) ID() string {
	var buff bytes.Buffer
	buff.WriteString(rr.URL.String())
	if rr.Request != nil {
		buff.WriteString(rr.Request.ID())
	}
	if rr.Response != nil {
		buff.WriteString(rr.Response.ID())
	}
	val := sha256.Sum256(buff.Bytes())
	return string(val[:])
}

// MarshalJSON marshals the request response to json
func (rr *RequestResponse) MarshalJSON() ([]byte, error) {
	m := make(map[string]interface{})
	m["url"] = rr.URL.String()
	// Request and Response are optional (UnmarshalJSON only reads the keys when
	// present), so nil pointers omit their keys instead of emitting "null".
	//
	// The pre-marshaled bytes must be wrapped as json.Message: encoding/json
	// (and sonic) encode a bare []byte as a base64 *string*, which this type's
	// own UnmarshalJSON — expecting a JSON object — cannot decode, breaking the
	// json.JSONCodec round-trip contract asserted above.
	if rr.Request != nil {
		reqBin, err := json.Marshal(rr.Request)
		if err != nil {
			return nil, err
		}
		m["request"] = json.Message(reqBin)
	}
	if rr.Response != nil {
		respBin, err := json.Marshal(rr.Response)
		if err != nil {
			return nil, err
		}
		m["response"] = json.Message(respBin)
	}
	return json.Marshal(m)
}

// UnmarshalJSON unmarshals the request response from json
func (rr *RequestResponse) UnmarshalJSON(data []byte) error {
	var m map[string]json.Message
	if err := json.Unmarshal(data, &m); err != nil {
		return err
	}
	urlStrRaw, ok := m["url"]
	if !ok {
		return fmt.Errorf("missing url in request response")
	}
	var urlStr string
	if err := json.Unmarshal(urlStrRaw, &urlStr); err != nil {
		return err
	}
	parsed, err := urlutil.ParseAbsoluteURL(urlStr, false)
	if err != nil {
		return err
	}
	rr.URL = *parsed

	reqBin, ok := m["request"]
	if ok {
		var req HttpRequest
		if err := json.Unmarshal(reqBin, &req); err != nil {
			return err
		}
		rr.Request = &req
	}

	respBin, ok := m["response"]
	if ok {
		var resp HttpResponse
		if err := json.Unmarshal(respBin, &resp); err != nil {
			return err
		}
		rr.Response = &resp
	}
	return nil
}

// HttpRequest is a struct containing the http request
type HttpRequest struct {
	// method of the request
	Method string `json:"method"`
	// headers of the request
	Headers mapsutil.OrderedMap[string, string] `json:"headers"`
	// body of the request
	Body string `json:"body"`
	// raw request (includes everything including method, headers, body, etc)
	Raw string `json:"raw"`
}

// ID returns a unique id/hash for raw request
func (hr *HttpRequest) ID() string {
	val := sha256.Sum256([]byte(hr.Raw))
	return string(val[:])
}

// Clone clones the request
func (hr *HttpRequest) Clone() *HttpRequest {
	return &HttpRequest{
		Method:  hr.Method,
		Headers: hr.Headers.Clone(),
		Body:    hr.Body,
		Raw:     hr.Raw,
	}
}

type HttpResponse struct {
	// status code of the response
	StatusCode int `json:"status_code"`
	// headers of the response
	Headers mapsutil.OrderedMap[string, string] `json:"headers"`
	// body of the response
	Body string `json:"body"`
	// raw response (includes everything including status code, headers, body, etc)
	Raw string `json:"raw"`
}

// Id returns a unique id/hash for raw response
func (hr *HttpResponse) ID() string {
	val := sha256.Sum256([]byte(hr.Raw))
	return string(val[:])
}

// Clone clones the response
func (hr *HttpResponse) Clone() *HttpResponse {
	return &HttpResponse{
		StatusCode: hr.StatusCode,
		Headers:    hr.Headers.Clone(),
		Body:       hr.Body,
		Raw:        hr.Raw,
	}
}

// ParseRawRequest parses a raw request from a string
// and returns the request and response object
// Note: it currently does not parse response and is meant to be added manually since its a optional field
func ParseRawRequest(raw string) (rr *RequestResponse, err error) {
	protoReader := textproto.NewReader(bufio.NewReader(strings.NewReader(raw)))
	methodLine, err := protoReader.ReadLine()
	if err != nil {
		return nil, fmt.Errorf("failed to read method line: %s", err)
	}
	rr = &RequestResponse{
		Request: &HttpRequest{},
	}
	/// must contain at least 3 parts
	parts := strings.Split(methodLine, " ")
	if len(parts) < 3 {
		return nil, fmt.Errorf("invalid method line: %s", methodLine)
	}
	method := parts[0]
	rr.Request.Method = method

	// the request target is normally an origin-form path, but proxy captures and
	// .http files use the absolute form, which already carries the authority
	var urlx *urlutil.URL
	target := parts[1]
	if stringsutil.HasPrefixAnyI(target, urlutil.HTTP+urlutil.SchemeSeparator, urlutil.HTTPS+urlutil.SchemeSeparator) {
		// urlutil.ParseAbsoluteURL only accepts lowercase schemes; preserve the
		// remainder of the request target unchanged.
		if scheme, rest, ok := strings.Cut(target, urlutil.SchemeSeparator); ok {
			target = strings.ToLower(scheme) + urlutil.SchemeSeparator + rest
		}
		urlx, err = urlutil.ParseAbsoluteURL(target, true)
	} else {
		urlx, err = urlutil.ParseRawRelativePath(target, true)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to parse url: %s", err)
	}
	rr.URL = *urlx

	// parse headers
	rr.Request.Headers = mapsutil.NewOrderedMap[string, string]()
	for {
		line, err := protoReader.ReadLine()
		if err != nil {
			return nil, fmt.Errorf("failed to read header line: %s", err)
		}
		if line == "" {
			// end of headers next is body
			break
		}
		key, value, found := strings.Cut(line, ":")
		if !found || key == "" {
			return nil, fmt.Errorf("invalid header line: %s", line)
		}
		value = strings.TrimSpace(value)
		// Host carries the authority rather than request metadata, and callers
		// read it off the URL: retryablehttp derives the wire Host from there,
		// and keeping it in the header map would expose it to header fuzzing as
		// if it were an ordinary header.
		if strings.EqualFold(key, "Host") {
			// an absolute request target takes precedence over the Host header
			if rr.URL.Host == "" {
				rr.URL.Host = value
			}
			continue
		}
		rr.Request.Headers.Set(key, value)
	}

	// parse body
	rr.Request.Body = ""
	var buff bytes.Buffer
	_, err = buff.ReadFrom(protoReader.R)
	if err != nil && err != io.EOF {
		return nil, fmt.Errorf("failed to read body: %s", err)
	}
	if buff.Len() > 0 {
		// yaml may include trailing newlines
		// remove them if present
		bin := buff.Bytes()
		if len(bin) > 0 && bin[len(bin)-1] == '\n' {
			bin = bin[:len(bin)-1]
		}
		if len(bin) > 0 && (bin[len(bin)-1] == '\r' || bin[len(bin)-1] == '\n') {
			bin = bin[:len(bin)-1]
		}
		rr.Request.Body = conversion.String(bin)
	}

	// set raw request
	rr.Request.Raw = raw
	return rr, nil
}

// ParseRawRequestWithURL parses a raw request from a string with given url
func ParseRawRequestWithURL(raw, url string) (rr *RequestResponse, err error) {
	rr, err = ParseRawRequest(raw)
	if err != nil {
		return nil, err
	}
	urlx, err := urlutil.ParseAbsoluteURL(url, false)
	if err != nil {
		return nil, err
	}
	rr.URL = *urlx
	return rr, nil
}

