func benchmarkWriteTemplateOutputs(b *testing.B, syncEachOutput bool) {
	rootDir := b.TempDir()
	contents := []byte("id: benchmark\ninfo:\n  name: Benchmark\n  author: test\n  severity: info\n")
	touchedDirectories := make(map[string]struct{})
	writer, err := newTemplateOutputWriter(rootDir)
	if err != nil {
		b.Fatal(err)
	}
	defer func() { _ = writer.Close() }()
	b.ReportAllocs()
	b.ResetTimer()

	for index := 0; index < b.N; index++ {
		// releases nest templates a few directories deep, e.g. http/cves/2024
		writePath := filepath.Join(rootDir, fmt.Sprintf("protocol-%d", index%4), fmt.Sprintf("category-%d", index%16), fmt.Sprintf("group-%d", index%64), fmt.Sprintf("template-%d.yaml", index))
		outputResult, err := writer.write(writePath, contents, 0o644)
		if err != nil {
			b.Fatal(err)
		}
		for _, directory := range outputResult.touchedDirectories {
			touchedDirectories[directory] = struct{}{}
		}

		if syncEachOutput {
			output, err := os.OpenFile(writePath, os.O_RDWR, 0)
			if err != nil {
				b.Fatal(err)
			}
			syncErr := output.Sync()
			closeErr := output.Close()
			if err := errors.Join(syncErr, closeErr); err != nil {
				b.Fatal(err)
			}
		}
	}

	if err := syncTemplateOutputDirectories(touchedDirectories, syncTemplateOwnershipDirectory); err != nil {
		b.Fatal(err)
	}
}

