package installer

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/utils/errkit"
)

// Tunables for withTemplatesUpdateLock. Package vars (instead of constants) so
// tests can shrink the 10m/15m windows without waiting them out.
var (
	templatesUpdateLockTimeout      = 10 * time.Minute
	templatesUpdateLockStaleAfter   = 15 * time.Minute
	templatesUpdateLockPollInterval = 250 * time.Millisecond
	// removeTemplatesUpdateLock is os.Remove except in tests that simulate a
	// lock disappearing, or refusing to disappear, between Stat and Remove.
	removeTemplatesUpdateLock = os.Remove
)

// withTemplatesUpdateLock serializes template install/update of templatesDir
// across processes. Parallel `go test` packages each have their own sync.Once,
// so without a cross-process lock they race on a shared templates directory
// (ENOENT, partial trees, checksum mismatches).
func withTemplatesUpdateLock(templatesDir string, fn func() error) error {
	lockPath := templatesUpdateLockPath(templatesDir)
	deadline := time.Now().Add(templatesUpdateLockTimeout)

	for {
		f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
		if err == nil {
			_, _ = fmt.Fprintf(f, "%d\n", os.Getpid())
			defer func() {
				_ = f.Close()
				_ = os.Remove(lockPath)
			}()
			return fn()
		}

		// Anything other than "already exists" (e.g. /tmp not writable,
		// read-only filesystem) will never succeed by retrying: fail fast
		// instead of spinning until the deadline.
		if !errors.Is(err, os.ErrExist) {
			return errkit.Wrapf(err, "could not create nuclei templates update lock at %s", lockPath)
		}

		info, statErr := os.Stat(lockPath)
		if statErr != nil {
			if os.IsNotExist(statErr) {
				// Lost a race with the holder releasing the lock; retry
				// immediately instead of sleeping through the window.
				continue
			}
			if time.Now().After(deadline) {
				return errkit.Wrapf(statErr, "timed out waiting for nuclei templates update lock at %s (could not stat lock); remove it manually if it is stale, or rerun with -duc/-disable-update-check to skip the automatic template update", lockPath)
			}
			time.Sleep(templatesUpdateLockPollInterval)
			continue
		}

		if age := time.Since(info.ModTime()); age > templatesUpdateLockStaleAfter {
			if rmErr := removeTemplatesUpdateLock(lockPath); rmErr != nil && !os.IsNotExist(rmErr) {
				// The classic multi-user hang: the lock lives in the shared
				// os.TempDir(), which has the sticky bit, so a lock file
				// created by another user cannot be unlinked (EPERM) by this
				// process. Retrying is pointless; surface who owns it and
				// how to recover instead of looping until the deadline.
				return errkit.Wrapf(rmErr, "stale nuclei templates update lock at %s (%s) could not be removed; it may belong to another user and cannot be unlinked from the shared temp dir, remove it manually (e.g. sudo rm %s) or rerun with -duc/-disable-update-check to skip the automatic template update", lockPath, describeUpdateLock(info, lockPath), lockPath)
			}
			continue
		}
		if time.Now().After(deadline) {
			return errkit.Wrapf(err, "timed out waiting for nuclei templates update lock at %s (%s); another process may be updating templates, if no update is running remove the stale lock manually (e.g. sudo rm %s) or rerun with -duc/-disable-update-check to skip the automatic template update", lockPath, describeUpdateLock(info, lockPath), lockPath)
		}
		time.Sleep(templatesUpdateLockPollInterval)
	}
}

// describeUpdateLock renders age, ownership and recorded pid of an existing
// lock for error messages. Everything is best-effort: the file is usually
// 0600, so a lock owned by another user may be neither readable nor statable
// beyond what os.Stat already returned.
func describeUpdateLock(info os.FileInfo, lockPath string) string {
	var parts []string
	parts = append(parts, fmt.Sprintf("age %s", time.Since(info.ModTime()).Round(time.Second)))
	parts = append(parts, fmt.Sprintf("mode %s", info.Mode()))
	if uid, gid, ok := updateLockOwner(info); ok {
		extra := fmt.Sprintf("uid=%d gid=%d", uid, gid)
		if current := os.Getuid(); current >= 0 && uid != uint64(current) {
			extra += " (another user)"
		}
		parts = append(parts, extra)
	}
	if pid, err := os.ReadFile(lockPath); err == nil {
		if trimmed := strings.TrimSpace(string(pid)); trimmed != "" {
			parts = append(parts, fmt.Sprintf("pid %s", trimmed))
		}
	} else if os.IsPermission(err) {
		parts = append(parts, "pid unreadable (permission denied, likely another user)")
	}
	return strings.Join(parts, ", ")
}

// updateLockOwner extracts uid/gid from os.Stat without importing syscall
// directly (syscall.Stat_t does not exist on windows). It uses reflection on
// info.Sys(): on unix this is *syscall.Stat_t with Uid/Gid fields, elsewhere
// the assertion fails and ok=false is reported.
func updateLockOwner(info os.FileInfo) (uid, gid uint64, ok bool) {
	sys := info.Sys()
	if sys == nil {
		return 0, 0, false
	}
	v := reflect.ValueOf(sys)
	if v.Kind() == reflect.Pointer && !v.IsNil() {
		v = v.Elem()
	}
	if v.Kind() != reflect.Struct {
		return 0, 0, false
	}
	uidField := v.FieldByName("Uid")
	gidField := v.FieldByName("Gid")
	if !uidField.IsValid() || !gidField.IsValid() {
		return 0, 0, false
	}
	toUint := func(rv reflect.Value) (uint64, bool) {
		switch rv.Kind() {
		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
			return rv.Uint(), true
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			if n := rv.Int(); n >= 0 {
				return uint64(n), true
			}
		}
		return 0, false
	}
	u, okU := toUint(uidField)
	g, okG := toUint(gidField)
	if !okU || !okG {
		return 0, 0, false
	}
	return u, g, true
}

// templatesUpdateLockPath derives one lock per templates directory, so updates
// of different directories do not wait on each other. Every alias of a
// directory maps to the same lock, including a symlink whose target does not
// exist yet.
func templatesUpdateLockPath(templatesDir string) string {
	sum := sha256.Sum256([]byte(config.CanonicalTemplatesPath(templatesDir)))
	return filepath.Join(os.TempDir(), fmt.Sprintf("nuclei-templates-update-%x.lock", sum[:8]))
}

package installer

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

// errkit quotes the error chain, so a Windows path's backslashes are escaped
// in Error() even though the message itself contains the real path.
func requireErrorContainsPath(t *testing.T, err error, path string) {
	t.Helper()
	rendered := err.Error()
	if strings.Contains(rendered, path) || strings.Contains(rendered, strings.ReplaceAll(path, `\`, `\\`)) {
		return
	}
	require.Contains(t, rendered, path)
}

func TestTemplatesUpdateLockPath(t *testing.T) {
	t.Run("same directory, same lock", func(t *testing.T) {
		dir := t.TempDir()
		require.Equal(t, templatesUpdateLockPath(dir), templatesUpdateLockPath(dir+string(filepath.Separator)))
	})

	t.Run("different directories, different locks", func(t *testing.T) {
		require.NotEqual(t, templatesUpdateLockPath(t.TempDir()), templatesUpdateLockPath(t.TempDir()))
	})

	t.Run("stable across a fresh install creating the directory", func(t *testing.T) {
		dir := filepath.Join(t.TempDir(), "missing", "nuclei-templates")
		before := templatesUpdateLockPath(dir)
		require.NoError(t, os.MkdirAll(dir, 0o755))
		require.Equal(t, before, templatesUpdateLockPath(dir))
	})

	t.Run("symlink to a directory, same lock", func(t *testing.T) {
		dir := t.TempDir()
		link := filepath.Join(t.TempDir(), "templates-link")
		if err := os.Symlink(dir, link); err != nil {
			t.Skipf("symlinks are unavailable: %v", err)
		}
		require.Equal(t, templatesUpdateLockPath(dir), templatesUpdateLockPath(link))
	})

	t.Run("dangling symlink, same lock before and after creation", func(t *testing.T) {
		parent := t.TempDir()
		target := filepath.Join(parent, "nuclei-templates")
		link := filepath.Join(parent, "templates-link")
		if err := os.Symlink(target, link); err != nil {
			t.Skipf("symlinks are unavailable: %v", err)
		}
		require.Equal(t, templatesUpdateLockPath(target), templatesUpdateLockPath(link))
		require.Equal(t, templatesUpdateLockPath(filepath.Join(target, "nested")), templatesUpdateLockPath(filepath.Join(link, "nested")))

		require.NoError(t, os.MkdirAll(target, 0o755))
		require.Equal(t, templatesUpdateLockPath(target), templatesUpdateLockPath(link))
	})

	t.Run("relative dangling symlink, same lock", func(t *testing.T) {
		parent := t.TempDir()
		target := filepath.Join(parent, "nuclei-templates")
		link := filepath.Join(parent, "templates-link")
		if err := os.Symlink("nuclei-templates", link); err != nil {
			t.Skipf("symlinks are unavailable: %v", err)
		}
		require.Equal(t, templatesUpdateLockPath(target), templatesUpdateLockPath(link))
	})
}

func TestWithTemplatesUpdateLockStaleLockIsCleared(t *testing.T) {
	dir := t.TempDir()
	lockPath := templatesUpdateLockPath(dir)
	require.NoError(t, os.WriteFile(lockPath, []byte("1234\n"), 0o600))
	stale := time.Now().Add(-1 * time.Hour)
	require.NoError(t, os.Chtimes(lockPath, stale, stale))
	t.Cleanup(func() { _ = os.Remove(lockPath) })

	ran := false
	require.NoError(t, withTemplatesUpdateLock(dir, func() error {
		ran = true
		return nil
	}))
	require.True(t, ran, "fn should run after the stale lock is cleared")
}

func TestWithTemplatesUpdateLockFreshLockTimesOutWithHelpfulMessage(t *testing.T) {
	oldTimeout, oldStale, oldPoll := templatesUpdateLockTimeout, templatesUpdateLockStaleAfter, templatesUpdateLockPollInterval
	templatesUpdateLockTimeout = 200 * time.Millisecond
	templatesUpdateLockStaleAfter = time.Hour
	templatesUpdateLockPollInterval = 10 * time.Millisecond
	defer func() {
		templatesUpdateLockTimeout, templatesUpdateLockStaleAfter, templatesUpdateLockPollInterval = oldTimeout, oldStale, oldPoll
	}()

	dir := t.TempDir()
	lockPath := templatesUpdateLockPath(dir)
	require.NoError(t, os.WriteFile(lockPath, []byte("99999\n"), 0o600))
	t.Cleanup(func() { _ = os.Remove(lockPath) })

	start := time.Now()
	err := withTemplatesUpdateLock(dir, func() error { return nil })
	elapsed := time.Since(start)
	require.Error(t, err)
	require.Less(t, elapsed, 10*time.Second, "must fail fast instead of hanging")
	require.Contains(t, err.Error(), "timed out waiting for nuclei templates update lock")
	requireErrorContainsPath(t, err, lockPath)
	require.Contains(t, err.Error(), "-duc")
}

func TestWithTemplatesUpdateLockStaleLockAlreadyRemoved(t *testing.T) {
	previous := removeTemplatesUpdateLock
	t.Cleanup(func() { removeTemplatesUpdateLock = previous })
	removeTemplatesUpdateLock = func(path string) error {
		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
			return err
		}
		// Another process removed the stale lock after we stat-ed it.
		return os.ErrNotExist
	}

	dir := t.TempDir()
	lockPath := templatesUpdateLockPath(dir)
	require.NoError(t, os.WriteFile(lockPath, []byte("1234\n"), 0o600))
	stale := time.Now().Add(-1 * time.Hour)
	require.NoError(t, os.Chtimes(lockPath, stale, stale))
	t.Cleanup(func() { _ = os.Remove(lockPath) })

	ran := false
	require.NoError(t, withTemplatesUpdateLock(dir, func() error {
		ran = true
		return nil
	}))
	require.True(t, ran, "a lock another process already removed must be taken, not treated as a failure")
}

func TestWithTemplatesUpdateLockUnremovableStaleLockFailsFast(t *testing.T) {
	previous := removeTemplatesUpdateLock
	t.Cleanup(func() { removeTemplatesUpdateLock = previous })
	removeTemplatesUpdateLock = func(string) error { return os.ErrPermission }

	dir := t.TempDir()
	lockPath := templatesUpdateLockPath(dir)
	require.NoError(t, os.WriteFile(lockPath, []byte("1234\n"), 0o600))
	stale := time.Now().Add(-1 * time.Hour)
	require.NoError(t, os.Chtimes(lockPath, stale, stale))
	t.Cleanup(func() { _ = os.Remove(lockPath) })

	ran := false
	start := time.Now()
	err := withTemplatesUpdateLock(dir, func() error {
		ran = true
		return nil
	})
	require.Error(t, err)
	require.False(t, ran)
	require.Less(t, time.Since(start), 2*time.Second)
	require.ErrorIs(t, err, os.ErrPermission)
	require.Contains(t, err.Error(), "could not be removed")
	requireErrorContainsPath(t, err, lockPath)
}

package installer

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
	"sort"

	"github.com/Masterminds/semver/v3"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/utils/errkit"
)

// GetNewTemplatesInVersions returns templates path of all newly added templates
// in these versions
func GetNewTemplatesInVersions(versions ...string) []string {
	allTemplates := []string{}
	for _, v := range versions {
		if v == config.DefaultConfig.TemplateVersion {
			allTemplates = append(allTemplates, config.DefaultConfig.GetNewAdditions()...)
			continue
		}
		_, err := semver.NewVersion(v)
		if err != nil {
			gologger.Error().Msgf("%v is not a valid semver version. skipping", v)
			continue
		}
		if config.IsOutdatedVersion(v, "v8.8.4") {
			// .new-additions was added in v8.8.4 any version before that is not supported
			gologger.Error().Msgf(".new-additions support was added in v8.8.4 older versions are not supported")
			continue
		}

		arr, err := getNewAdditionsFileFromGitHub(v)
		if err != nil {
			gologger.Error().Msgf("failed to fetch new additions for %v got: %v", v, err)
			continue
		}
		allTemplates = append(allTemplates, arr...)
	}
	return allTemplates
}

func getNewAdditionsFileFromGitHub(version string) ([]string, error) {
	resp, err := retryableHttpClient.Get(fmt.Sprintf("https://raw.githubusercontent.com/projectdiscovery/nuclei-templates/%s/.new-additions", version))
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		return nil, errkit.New("version not found")
	}
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	templatesList := []string{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		text := scanner.Text()
		if text == "" {
			continue
		}
		if config.IsTemplate(text) {
			templatesList = append(templatesList, text)
		}
	}
	return templatesList, nil
}

func PurgeEmptyDirectories(dir string) {
	alldirs := []string{}
	_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if d.IsDir() {
			alldirs = append(alldirs, path)
		}
		return nil
	})
	// sort in ascending order
	sort.Strings(alldirs)
	// reverse the order
	sort.Sort(sort.Reverse(sort.StringSlice(alldirs)))

	for _, d := range alldirs {
		if isEmptyDir(d) {
			_ = os.RemoveAll(d)
		}
	}
}

func isEmptyDir(dir string) bool {
	hasFiles := false
	_ = filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
		if !d.IsDir() {
			hasFiles = true
			return io.EOF
		}
		return nil
	})
	return !hasFiles
}

