	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/goconsole"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

const (
	exportToken   = "Export"
	exportAsToken = "ExportAs"
)

// errRuntimeTerminationTimeout is returned by session when the
// goroutine running goja.Runtime.RunProgram fails to terminate within the
// grace period after an interrupt was raised. When this error is returned
// the runtime MUST NOT be touched (no cleanup, no reuse, no Put back to
// the pool) because the orphaned goroutine is still operating on it; any
// concurrent access would race with goja's per-runtime state and can
// trigger a fatal "concurrent map read and map write" runtime panic.
//
// See https://github.com/projectdiscovery/nuclei/issues/7376.
var errRuntimeTerminationTimeout = errors.New("nuclei js runtime: program failed to terminate after interrupt")

var (
	lazyRegistryInit = sync.OnceFunc(func() {
		// autoregister console node module with default printer it uses gologger backend
		require.RegisterNativeModule(console.ModuleName, console.RequireWithPrinter(goconsole.NewGoConsolePrinter()))
	})
	pooljsc    *syncutil.AdaptiveWaitGroup
	lazySgInit = sync.OnceFunc(func() {
		pooljsc, _ = syncutil.New(syncutil.WithSize(PoolingJsVmConcurrency))
	})
	sgResizeCheck = func(ctx context.Context) {
		// resize check point
		if pooljsc.Size != PoolingJsVmConcurrency {
			if err := pooljsc.Resize(ctx, PoolingJsVmConcurrency); err != nil {
				gologger.Warning().Msgf("Could not resize workpool: %s\n", err)
			}
		}
	}
)

var gojapool = &sync.Pool{
	New: func() interface{} {
		return createNewRuntime()
	},
}

// ExecuteProgram executes a compiled program with the default options.
// it deligates if a particular program should run in a pooled or non-pooled runtime
func ExecuteProgram(ctx context.Context, p *goja.Program, args *ExecuteArgs, opts *ExecuteOptions) (goja.Value, error) {
	if opts == nil {
		opts = &ExecuteOptions{}
	}
	if opts.Source == nil {
		// not-recommended anymore
		return executeWithoutPooling(ctx, p, args, opts)
	}
	if !stringsutil.ContainsAny(*opts.Source, exportAsToken, exportToken) {
		// not-recommended anymore
		return executeWithoutPooling(ctx, p, args, opts)
	}
	return executeWithPoolingProgram(ctx, p, args, opts)
}

// executes the actual js program
func executeWithPoolingProgram(ctx context.Context, p *goja.Program, args *ExecuteArgs, opts *ExecuteOptions) (goja.Value, error) {
	if opts == nil {
		opts = &ExecuteOptions{}
	}
	// its unknown (most likely cannot be done) to limit max js runtimes at a moment without making it static
	// unlike sync.Pool which reacts to GC and its purposes is to reuse objects rather than creating new ones
	lazySgInit()
	// Bound admission separately so queue time does not consume execution time.
	queueCtx, cancelQueue := executionTimeout(ctx, opts)
	defer cancelQueue()
	sgResizeCheck(queueCtx)
	if err := pooljsc.AddWithContext(queueCtx); err != nil {
		return nil, err
	}

	cancelQueue()
	ctx, cancel := executionTimeout(ctx, opts)
	defer cancel()

	runtime := gojapool.Get().(*goja.Runtime)

	var buff bytes.Buffer
	opts.exports = make(map[string]interface{})

	session := newSession(sessionConfig{
		ctx:     ctx,
		runtime: runtime,
		program: p,
		args:    args,
		opts:    opts,
		prepareRuntime: func(runtime *goja.Runtime) error {
			registerExportHelpers(runtime, opts, &buff)
			return nil
		},
		cleanupRuntime: func(runtime *goja.Runtime) {
			_ = runtime.GlobalObject().Delete(exportAsToken)
			_ = runtime.GlobalObject().Delete(exportToken)
		},
		finalizeResult: func(runtime *goja.Runtime, val goja.Value) (goja.Value, error) {
			if val.Export() != nil {
				// append last value to output
				buff.WriteString(stringify(val, runtime))
			}
			// and return it as result
			return runtime.ToValue(buff.String()), nil
		},
		returnRuntime: func(runtime *goja.Runtime) {
			gojapool.Put(runtime)
		},
		releaseSlot:          pooljsc.Done,
		releaseAbandonedSlot: pooljsc.Done,
		onAbandon: func(err error) {
			gologger.Warning().Msgf("js runtime did not terminate after interrupt; abandoning it to avoid concurrent use: %s", err)
		},
	})
	return session.run()
}

func registerExportHelpers(runtime *goja.Runtime, opts *ExecuteOptions, buff *bytes.Buffer) {
	// register export functions
	_ = gojs.RegisterFuncWithSignature(runtime, gojs.FuncOpts{
		Name:        "Export", // we use string instead of const for documentation generation
		Signatures:  []string{"Export(value any)"},
		Description: "Converts a given value to a string and is appended to output of script",
		FuncDecl: func(call goja.FunctionCall, runtime *goja.Runtime) goja.Value {
			if len(call.Arguments) == 0 {
				return goja.Null()
			}
			for _, arg := range call.Arguments {
				if out := stringify(arg, runtime); out != "" {
					buff.WriteString(out)
				}
			}
			return goja.Null()
		},
	})
	// register exportAs function
	_ = gojs.RegisterFuncWithSignature(runtime, gojs.FuncOpts{
		Name:        "ExportAs", // Export
		Signatures:  []string{"ExportAs(key string,value any)"},
		Description: "Exports given value with specified key and makes it available in DSL and response",
		FuncDecl: func(call goja.FunctionCall, runtime *goja.Runtime) goja.Value {
			if len(call.Arguments) != 2 {
				// this is how goja expects errors to be returned
				// and internally it is done same way for all errors
				panic(runtime.ToValue("ExportAs expects 2 arguments"))
			}
			key := call.Argument(0).String()
			value := call.Argument(1)
			opts.exports[key] = stringify(value, runtime)
			return goja.Null()
		},
	})
}

// Internal purposes i.e generating bindings
func InternalGetGeneratorRuntime() *goja.Runtime {
	runtime := gojapool.Get().(*goja.Runtime)
	return runtime
}

func enableRequire(runtime *goja.Runtime) {
	lazyRegistryInit()
	_ = require.NewRegistry(require.WithLoader(newSourceLoader(runtime))).Enable(runtime)
}

func newSourceLoader(runtime *goja.Runtime) require.SourceLoader {
	return func(path string) ([]byte, error) {
		executionID := ""
		if value, ok := runtime.GetContextValue("executionId"); ok {
			if id, ok := value.(string); ok {
				executionID = id
			}
		}

		normalizedPath, err := protocolstate.NormalizePathWithExecutionId(executionID, path)
		if err != nil {
			return nil, err
		}

		return require.DefaultSourceLoader(normalizedPath)
	}
}

func createNewRuntime() *goja.Runtime {
	runtime := protocolstate.NewJSRuntime()
	enableRequire(runtime)
	// by default import below modules every time
	_ = runtime.Set("console", require.Require(runtime, console.ModuleName))

	// Register embedded javascript helpers
	if err := global.RegisterNativeScripts(runtime); err != nil {
		gologger.Error().Msgf("Could not register scripts: %s\n", err)
	}
	return runtime
}

// stringify converts a given value to string
// if its a struct it will be marshalled to json
func stringify(gojaValue goja.Value, runtime *goja.Runtime) string {
	value := gojaValue.Export()
	if value == nil {
		return ""
	}
	kind := reflect.TypeOf(value).Kind()
	if kind == reflect.Struct || kind == reflect.Pointer && reflect.ValueOf(value).Elem().Kind() == reflect.Struct {
		// in this case we must use JSON.stringify to convert to string
		// because json.Marshal() utilizes json tags when marshalling
		// but goja has custom implementation of json.Marshal() which does not
		// since we have been using `to_json` in all our examples we must stick to it
		// marshal structs or struct pointers to json automatically
		jsonStringify, ok := goja.AssertFunction(runtime.Get("to_json"))
		if ok {
			result, err := jsonStringify(goja.Undefined(), gojaValue)
			if err == nil {
				return result.String()
			}
		}
		// unlikely but if to_json threw some error use native json.Marshal
		val := value
		if kind == reflect.Pointer {
			val = reflect.ValueOf(value).Elem().Interface()
		}
		bin, err := json.Marshal(val)
		if err == nil {
			return string(bin)
		}
	}
	// for everything else stringify
	return fmt.Sprintf("%+v", value)
}

package compiler

import (
	"context"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	syncutil "github.com/projectdiscovery/utils/sync"
)

// TestAddWithContextRespectsDeadline verifies that AddWithContext returns an
// error when the context deadline expires while waiting for a pool slot.
// Before the fix, Add() used t.Context() and would block indefinitely.
func TestAddWithContextRespectsDeadline(t *testing.T) {
	pool, err := syncutil.New(syncutil.WithSize(1))
	require.NoError(t, err)

	// Fill the only slot.
	pool.Add()
	defer pool.Done()

	// Try to acquire with a short deadline, should fail fast and not hang.
	ctx, cancel := context.WithTimeout(t.Context(), 50*time.Millisecond)
	defer cancel()

	start := time.Now()
	err = pool.AddWithContext(ctx)
	elapsed := time.Since(start)

	require.Error(t, err, "AddWithContext should fail when pool is full and deadline expires")
	require.Less(t, elapsed, 200*time.Millisecond, "AddWithContext should fail fast after deadline")
}

package compiler

import (
	"context"
	"testing"
	"time"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	syncutil "github.com/projectdiscovery/utils/sync"
	"github.com/stretchr/testify/require"
)

// These tests replace global admission pools and must not run in parallel.
// Go suspends parallel package tests until these sequential tests finish.
func TestExecutionTimeoutAfterAdmission(t *testing.T) {
	lazySgInit()
	lazyFixedSgInit()
	oldPool, oldEphemeral := pooljsc, ephemeraljsc
	oldConcurrency := PoolingJsVmConcurrency
	t.Cleanup(func() {
		pooljsc, ephemeraljsc = oldPool, oldEphemeral
		PoolingJsVmConcurrency = oldConcurrency
	})
	PoolingJsVmConcurrency = 1

	for _, pooled := range []bool{true, false} {
		name := "non-pooled"
		if pooled {
			name = "pooled"
		}
		t.Run(name, func(t *testing.T) {
			pool, err := syncutil.New(syncutil.WithSize(1))
			require.NoError(t, err)
			if pooled {
				pooljsc = pool
			} else {
				ephemeraljsc = pool
			}

			execute := func(ctx context.Context, source string, budget time.Duration, callback func(*goja.Runtime) error) (ExecuteResult, error) {
				program, err := SourceAutoMode(source, false)
				require.NoError(t, err)
				return New().ExecuteWithOptions(ctx, program, nil, &ExecuteOptions{
					Source: &source, Callback: callback,
					TimeoutVariants: &types.Timeouts{JsCompilerExecutionTimeout: budget},
				})
			}
			quick := `var until = Date.now() + 150; while (Date.now() < until) {} "matched-evidence";`
			loop := `while (true) {}`
			if pooled {
				quick = `var until = Date.now() + 150; while (Date.now() < until) {} ExportAs("proof", "matched-evidence"); Export(true);`
				loop = `Export(true); while (true) {}`
			}

			if pooled {
				t.Run("admission-budget-includes-resize", func(t *testing.T) {
					occupied, err := syncutil.New(syncutil.WithSize(2))
					require.NoError(t, err)
					occupied.Add()
					occupied.Add()
					pooljsc = occupied
					defer func() {
						occupied.Done()
						occupied.Done()
						pooljsc = pool
					}()
					ctx, cancel := context.WithTimeout(t.Context(), 500*time.Millisecond)
					defer cancel()
					started := false
					begin := time.Now()
					_, err = execute(ctx, quick, 50*time.Millisecond, func(*goja.Runtime) error {
						started = true
						return nil
					})
					require.ErrorIs(t, err, context.DeadlineExceeded)
					require.False(t, started)
					require.Less(t, time.Since(begin), 250*time.Millisecond)
				})
			}

			t.Run("quick-script-after-queue", func(t *testing.T) {
				// The same script succeeds without contention.
				result, err := execute(t.Context(), quick, 300*time.Millisecond, nil)
				require.NoError(t, err)
				require.True(t, result.GetSuccess())

				pool.Add()
				released := make(chan struct{})
				timer := time.AfterFunc(200*time.Millisecond, func() {
					pool.Done()
					close(released)
				})
				defer func() {
					if timer.Stop() {
						pool.Done()
					} else {
						<-released
					}
				}()
				started := false
				begin := time.Now()
				result, err = execute(t.Context(), quick, 300*time.Millisecond, func(*goja.Runtime) error {
					started = true
					return nil
				})
				t.Logf("queue release=200ms, JS budget=300ms, elapsed=%s, started=%v, result=%v, error=%v", time.Since(begin), started, result, err)
				require.NoError(t, err)
				require.True(t, started)
				require.True(t, result.GetSuccess())
				if pooled {
					require.Equal(t, "matched-evidence", result["proof"])
				} else {
					require.Equal(t, "matched-evidence", result["response"])
				}
			})

			t.Run("caller-deadline-in-queue", func(t *testing.T) {
				pool.Add()
				defer pool.Done()
				ctx, cancel := context.WithTimeout(t.Context(), 50*time.Millisecond)
				defer cancel()
				started := false
				_, err := execute(ctx, quick, time.Second, func(*goja.Runtime) error {
					started = true
					return nil
				})
				require.ErrorIs(t, err, context.DeadlineExceeded)
				require.False(t, started)
			})

			t.Run("caller-cancels-queued-execution", func(t *testing.T) {
				pool.Add()
				defer pool.Done()
				ctx, cancel := context.WithCancel(t.Context())
				defer cancel()
				timer := time.AfterFunc(50*time.Millisecond, cancel)
				defer timer.Stop()
				started := false
				_, err := execute(ctx, quick, time.Second, func(*goja.Runtime) error {
					started = true
					return nil
				})
				require.ErrorIs(t, err, context.Canceled)
				require.False(t, started)
			})

			t.Run("admission-budget", func(t *testing.T) {
				pool.Add()
				defer pool.Done()
				started := false
				_, err := execute(t.Context(), quick, 50*time.Millisecond, func(*goja.Runtime) error {
					started = true
					return nil
				})
				require.ErrorIs(t, err, context.DeadlineExceeded)
				require.False(t, started)
			})

			t.Run("caller-deadline-during-execution", func(t *testing.T) {
				ctx, cancel := context.WithTimeout(t.Context(), 50*time.Millisecond)
				defer cancel()
				started := false
				_, err := execute(ctx, loop, time.Second, func(*goja.Runtime) error {
					started = true
					return nil
				})
				require.True(t, started)
				require.ErrorIs(t, err, context.DeadlineExceeded)
			})

			t.Run("nonpositive-budget", func(t *testing.T) {
				for _, budget := range []time.Duration{0, -time.Millisecond} {
					_, err := execute(t.Context(), quick, budget, nil)
					require.ErrorIs(t, err, context.DeadlineExceeded)
				}
			})

			t.Run("execution-budget", func(t *testing.T) {
				_, err := execute(t.Context(), loop, 50*time.Millisecond, nil)
				require.ErrorIs(t, err, context.DeadlineExceeded)
			})
		})
	}
}

func TestExecuteProgramWithoutTimeoutVariants(t *testing.T) {
	for _, source := range []string{`true;`, `Export(true);`} {
		program, err := SourceAutoMode(source, false)
		require.NoError(t, err)
		value, err := ExecuteProgram(t.Context(), program, NewExecuteArgs(), &ExecuteOptions{Source: &source})
		require.NoError(t, err)
		require.True(t, value.ToBoolean())
	}
}

package compiler

import (
	"context"
	"fmt"
	"time"

	"github.com/projectdiscovery/goja"
)

// sessionState represents the various states a session can be in during its lifecycle.
type sessionState uint8

const (
	sessionRunning sessionState = iota
	sessionCompleted
	sessionFailed
	sessionAbandoned
)

type gojaRunResult struct {
	result goja.Value
	err    error
}

// sessionConfig defines the configuration for a session, including the runtime,
// program, arguments, and lifecycle hooks for preparation, cleanup, and result
// finalization. It also includes callbacks for handling resource release and
// abandonment scenarios.
type sessionConfig struct {
	ctx     context.Context
	runtime *goja.Runtime
	program *goja.Program
	args    *ExecuteArgs
	opts    *ExecuteOptions

	prepareRuntime func(*goja.Runtime) error
	cleanupRuntime func(*goja.Runtime)
	finalizeResult func(*goja.Runtime, goja.Value) (goja.Value, error)

	returnRuntime        func(*goja.Runtime)
	releaseSlot          func()
	releaseAbandonedSlot func()
	onAbandon            func(error)
}

// session encapsulates the execution of a single JavaScript program, managing
// its lifecycle, including preparation, execution, and cleanup.
type session struct {
	config sessionConfig

	resultChan chan gojaRunResult
	state      sessionState

	commonPrepared bool
	commonCleaned  bool
	pathPrepared   bool
	pathCleaned    bool
}

func newSession(config sessionConfig) *session {
	if config.args == nil {
		config.args = NewExecuteArgs()
	}
	if config.opts == nil {
		config.opts = &ExecuteOptions{}
	}
	return &session{
		config:     config,
		resultChan: make(chan gojaRunResult, 1),
	}
}

func executeWithRuntime(ctx context.Context, runtime *goja.Runtime, p *goja.Program, args *ExecuteArgs, opts *ExecuteOptions, onOrphanExit func()) (goja.Value, error) {
	session := newSession(sessionConfig{
		ctx:                  ctx,
		runtime:              runtime,
		program:              p,
		args:                 args,
		opts:                 opts,
		releaseAbandonedSlot: onOrphanExit,
	})
	return session.run()
}

func (s *session) run() (goja.Value, error) {
	defer s.releaseAfterExit()
	defer s.cleanupPath()
	defer s.cleanupCommon()

	s.prepareCommon()
	if s.config.prepareRuntime != nil {
		s.pathPrepared = true
		if err := s.config.prepareRuntime(s.config.runtime); err != nil {
			s.state = sessionFailed
			return nil, err
		}
	}
	if s.config.opts.Callback != nil {
		if err := s.config.opts.Callback(s.config.runtime); err != nil {
			s.state = sessionFailed
			return nil, err
		}
	}

	s.start()
	result, err := s.wait()
	if err != nil {
		return nil, err
	}
	if result.err != nil {
		s.state = sessionFailed
		return nil, result.err
	}

	s.cleanupCommon()
	if s.config.finalizeResult != nil {
		value, err := s.config.finalizeResult(s.config.runtime, result.result)
		if err != nil {
			s.state = sessionFailed
			return nil, err
		}
		s.state = sessionCompleted
		return value, nil
	}

	s.state = sessionCompleted
	return result.result, nil
}

func (s *session) prepareCommon() {
	s.commonPrepared = true

	s.config.runtime.ClearInterrupt()
	_ = s.config.runtime.Set("template", s.config.args.TemplateCtx)
	for k, v := range s.config.args.Args {
		_ = s.config.runtime.Set(k, v)
	}

	executionCtx := s.config.ctx
	if s.config.opts.TimeoutVariants != nil {
		s.config.runtime.SetContextValue("timeoutVariants", s.config.opts.TimeoutVariants)
		executionCtx = context.WithValue(executionCtx, "timeoutVariants", s.config.opts.TimeoutVariants) //nolint:staticcheck
	}
	if s.config.opts.ProxyURL != "" {
		s.config.runtime.SetContextValue("proxyURL", s.config.opts.ProxyURL)
		executionCtx = context.WithValue(executionCtx, "proxyURL", s.config.opts.ProxyURL) //nolint:staticcheck
	}
	if len(s.config.opts.CustomHeaders) > 0 {
		headers := append([]string(nil), s.config.opts.CustomHeaders...)
		s.config.runtime.SetContextValue("customHeaders", headers)
		executionCtx = context.WithValue(executionCtx, "customHeaders", headers) //nolint:staticcheck
	}
	s.config.runtime.SetContextValue("executionId", s.config.opts.ExecutionId)
	s.config.runtime.SetContextValue("ctx", executionCtx)
	// Go calls derive their context from this, so the execution timeout also
	// cancels a library call in flight instead of leaving it running
	s.config.runtime.SetContext(executionCtx)
	enableRequire(s.config.runtime)
}

func (s *session) start() {
	go func() {
		defer func() {
			if r := recover(); r != nil {
				s.resultChan <- gojaRunResult{err: fmt.Errorf("panic: %s", r)}
			}
		}()

		result, err := s.config.runtime.RunProgram(s.config.program)
		s.resultChan <- gojaRunResult{result: result, err: err}
	}()
}

func (s *session) wait() (gojaRunResult, error) {
	select {
	case <-s.config.ctx.Done():
		contextErr := s.config.ctx.Err()
		s.config.runtime.Interrupt(contextErr)

		timer := time.NewTimer(time.Second)
		defer timer.Stop()

		select {
		case result := <-s.resultChan:
			return result, nil
		case <-timer.C:
			return gojaRunResult{}, s.abandon(contextErr)
		}
	case result := <-s.resultChan:
		return result, nil
	}
}

func (s *session) abandon(contextErr error) error {
	s.state = sessionAbandoned
	err := fmt.Errorf("%w: %w", errRuntimeTerminationTimeout, contextErr)
	if s.config.releaseAbandonedSlot != nil {
		resultChan := s.resultChan
		releaseAbandonedSlot := s.config.releaseAbandonedSlot
		go func() {
			<-resultChan
			releaseAbandonedSlot()
		}()
	}
	if s.config.onAbandon != nil {
		s.config.onAbandon(err)
	}
	return err
}

func (s *session) cleanupCommon() {
	if s.state == sessionAbandoned || !s.commonPrepared || s.commonCleaned {
		return
	}
	s.commonCleaned = true

	_ = s.config.runtime.GlobalObject().Delete("template")
	for k := range s.config.args.Args {
		_ = s.config.runtime.GlobalObject().Delete(k)
	}
	if s.config.opts.Cleanup != nil {
		s.config.opts.Cleanup(s.config.runtime)
	}
	s.config.runtime.RemoveContextValue("executionId")
	s.config.runtime.RemoveContextValue("ctx")
	s.config.runtime.SetContext(context.TODO())
	s.config.runtime.RemoveContextValue("timeoutVariants")
	s.config.runtime.RemoveContextValue("proxyURL")
	s.config.runtime.RemoveContextValue("customHeaders")
}

func (s *session) cleanupPath() {
	if s.state == sessionAbandoned || !s.pathPrepared || s.pathCleaned {
		return
	}
	s.pathCleaned = true
	if s.config.cleanupRuntime != nil {
		s.config.cleanupRuntime(s.config.runtime)
	}
}

func (s *session) releaseAfterExit() {
	if s.state == sessionAbandoned {
		return
	}
	if s.config.returnRuntime != nil {
		s.config.returnRuntime(s.config.runtime)
	}
	if s.config.releaseSlot != nil {
		s.config.releaseSlot()
	}
}

