package bytes

import (
	"encoding/hex"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/structs"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
)

type (
	// Buffer is a bytes/Uint8Array type in javascript
	// @example
	// ```javascript
	// const bytes = require('nuclei/bytes');
	// const bytes = new bytes.Buffer();
	// ```
	// @example
	// ```javascript
	// const bytes = require('nuclei/bytes');
	// // optionally it can accept existing byte/Uint8Array as input
	// const bytes = new bytes.Buffer([1, 2, 3]);
	// ```
	Buffer struct {
		buf []byte
	}
)

// NewBuffer creates a new buffer from a byte slice.
func NewBuffer(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	if len(call.Arguments) > 0 {
		if arg, ok := call.Argument(0).Export().([]byte); ok {
			return utils.LinkConstructor(call, runtime, &Buffer{buf: arg})
		} else {
			utils.NewNucleiJS(runtime).Throw("Invalid argument type. Expected bytes/Uint8Array as input but got %T", call.Argument(0).Export())
		}
	}
	return utils.LinkConstructor(call, runtime, &Buffer{})
}

// Write appends the given data to the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.Write([1, 2, 3]);
// ```
func (b *Buffer) Write(data []byte) *Buffer {
	b.buf = append(b.buf, data...)
	return b
}

// WriteString appends the given string data to the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// ```
func (b *Buffer) WriteString(data string) *Buffer {
	b.buf = append(b.buf, []byte(data)...)
	return b
}

// Bytes returns the byte representation of the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// log(buffer.Bytes());
// ```
func (b *Buffer) Bytes() []byte {
	return b.buf
}

// String returns the string representation of the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// log(buffer.String());
// ```
func (b *Buffer) String() string {
	return string(b.buf)
}

// Len returns the length of the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// log(buffer.Len());
// ```
func (b *Buffer) Len() int {
	return len(b.buf)
}

// Hex returns the hex representation of the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// log(buffer.Hex());
// ```
func (b *Buffer) Hex() string {
	return hex.EncodeToString(b.buf)
}

// Hexdump returns the hexdump representation of the buffer.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.WriteString('hello');
// log(buffer.Hexdump());
// ```
func (b *Buffer) Hexdump() string {
	return hex.Dump(b.buf)
}

// Pack uses structs.Pack and packs given data and appends it to the buffer.
// it packs the data according to the given format.
// @example
// ```javascript
// const bytes = require('nuclei/bytes');
// const buffer = new bytes.Buffer();
// buffer.Pack('I', 123);
// ```
func (b *Buffer) Pack(formatStr string, msg any) error {
	bin, err := structs.Pack(formatStr, msg)
	if err != nil {
		return err
	}
	b.Write(bin)
	return nil
}

// Package compress exposes streaming decompression to nuclei JavaScript templates.
package compress

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"net/http/httputil"
	"slices"
	"strings"

	"github.com/dsnet/compress/brotli"
	"github.com/klauspost/compress/gzip"
	"github.com/klauspost/compress/zlib"
	"github.com/klauspost/compress/zstd"
)

// maxDecodedChunk caps the decoded bytes one call hands back.
const maxDecodedChunk = 1 << 20

type pauseReason int

const (
	needInput pauseReason = iota
	outputFull
	finished
)

type (
	// Decoder decodes a compressed stream written to it in chunks. Each call
	// returns up to about 1 MB; call Read until it returns nothing before the
	// next Write.
	// @example
	// ```javascript
	// const compress = require('nuclei/compress');
	// const hash = require('nuclei/hash');
	// const d = compress.NewDecoder('gzip');
	// const h = hash.New('sha256');
	// for (const chunk of chunks) {
	//   for (let out = d.Write(chunk); out.length > 0; out = d.Read()) h.Write(out);
	// }
	// for (let out = d.Close(); out.length > 0; out = d.Read()) h.Write(out);
	// log(h.Sum());
	// ```
	Decoder struct {
		ctx context.Context
		// The decode goroutine and the template's calls take turns over these
		// channels, so no field is accessed by both at once.
		resume chan []byte
		paused chan pauseReason
		done   chan struct{}
		out    []byte

		state      pauseReason
		inputEnded bool

		pending []byte
		eof     bool
		err     error
	}
)

// NewDecoder returns a decoder for gzip, deflate, br, zstd, chunked or
// identity. List several comma-separated, in the order they were applied.
// @example
// ```javascript
// const compress = require('nuclei/compress');
// const d = compress.NewDecoder('br');
// // Content-Encoding: gzip sent with Transfer-Encoding: chunked
// const c = compress.NewDecoder('gzip, chunked');
// ```
func NewDecoder(ctx context.Context, encoding string) (*Decoder, error) {
	var opens []func(io.Reader) (io.Reader, func(), error)
	for name := range strings.SplitSeq(encoding, ",") {
		switch name = strings.ToLower(strings.TrimSpace(name)); name {
		case "gzip":
			opens = append(opens, func(r io.Reader) (io.Reader, func(), error) {
				zr, err := gzip.NewReader(r)
				return zr, func() {}, err
			})
		case "deflate":
			opens = append(opens, func(r io.Reader) (io.Reader, func(), error) {
				zr, err := zlib.NewReader(r)
				return zr, func() {}, err
			})
		case "br":
			opens = append(opens, func(r io.Reader) (io.Reader, func(), error) {
				br, err := brotli.NewReader(r, nil)
				return br, func() {}, err
			})
		case "zstd":
			opens = append(opens, func(r io.Reader) (io.Reader, func(), error) {
				// One goroutine so no background workers outlive the stream.
				zr, err := zstd.NewReader(r, zstd.WithDecoderConcurrency(1))
				if err != nil {
					return nil, nil, err
				}
				return zr, zr.Close, nil
			})
		case "chunked":
			opens = append(opens, func(r io.Reader) (io.Reader, func(), error) {
				return httputil.NewChunkedReader(r), func() {}, nil
			})
		case "", "identity":
		default:
			return nil, fmt.Errorf("unsupported encoding %q, expected gzip, deflate, br, zstd, chunked or identity", name)
		}
	}
	slices.Reverse(opens)
	open := func(r io.Reader) (io.Reader, func(), error) {
		var closers []func()
		closeAll := func() {
			for _, c := range slices.Backward(closers) {
				c()
			}
		}
		for _, o := range opens {
			next, c, err := o(r)
			if err != nil {
				closeAll()
				return nil, nil, err
			}
			r = next
			closers = append(closers, c)
		}
		return r, closeAll, nil
	}
	d := &Decoder{
		ctx:    ctx,
		resume: make(chan []byte),
		paused: make(chan pauseReason),
		done:   make(chan struct{}),
	}
	go d.run(open)
	d.wait()
	return d, nil
}

// Write decodes the next chunk and returns up to about 1 MB of output.
// @example
// ```javascript
// const compress = require('nuclei/compress');
// const d = compress.NewDecoder('gzip');
// const out = d.Write(chunk);
// ```
func (d *Decoder) Write(chunk []byte) ([]byte, error) {
	if d.done == nil {
		return nil, errNotCreatedByNewDecoder
	}
	if d.inputEnded {
		return nil, errors.New("decoder is closed")
	}
	if d.state == outputFull {
		return nil, errors.New("decoded bytes are waiting: call Read until it returns no bytes before writing more")
	}
	if d.state == needInput && len(chunk) > 0 {
		// The decode goroutine may still hold the chunk after Write returns.
		d.resumeWith(bytes.Clone(chunk))
	}
	return d.result()
}

// Read returns more decoded bytes, or none once the decoder needs input.
// @example
// ```javascript
// const compress = require('nuclei/compress');
// const d = compress.NewDecoder('gzip');
// for (let out = d.Write(chunk); out.length > 0; out = d.Read()) log(out.length);
// ```
func (d *Decoder) Read() ([]byte, error) {
	if d.done == nil {
		return nil, errNotCreatedByNewDecoder
	}
	d.advance()
	return d.result()
}

// Close ends the input and returns the last decoded bytes. A truncated
// stream errors once the bytes before the cut have been returned.
// @example
// ```javascript
// const compress = require('nuclei/compress');
// const d = compress.NewDecoder('gzip');
// d.Write(chunk);
// for (let out = d.Close(); out.length > 0; out = d.Read()) log(out.length);
// ```
func (d *Decoder) Close() ([]byte, error) {
	if d.done == nil {
		return nil, errNotCreatedByNewDecoder
	}
	d.inputEnded = true
	d.advance()
	return d.result()
}

// Finished reports whether a stream that marks its own end, such as a
// chunked body, has ended and all its output was read.
// @example
// ```javascript
// const compress = require('nuclei/compress');
// const d = compress.NewDecoder('gzip, chunked');
// while (!d.Finished()) for (let out = d.Write(conn.Recv(65536)); out.length > 0; out = d.Read()) log(out.length);
// ```
func (d *Decoder) Finished() bool {
	return d.state == finished && len(d.out) == 0
}

var errNotCreatedByNewDecoder = errors.New("decoder was not created with compress.NewDecoder")

func (d *Decoder) advance() {
	for len(d.out) == 0 && (d.state == outputFull || d.state == needInput && d.inputEnded) {
		d.resumeWith(nil)
	}
}

func (d *Decoder) result() ([]byte, error) {
	out := d.out
	d.out = nil
	if len(out) == 0 && d.state == finished {
		return nil, d.err
	}
	return out, nil
}

func (d *Decoder) resumeWith(chunk []byte) {
	select {
	case d.resume <- chunk:
		d.wait()
	case <-d.done:
		d.state = finished
	}
}

func (d *Decoder) wait() {
	select {
	case d.state = <-d.paused:
	case <-d.done:
		d.state = finished
	}
}

func (d *Decoder) run(open func(io.Reader) (io.Reader, func(), error)) {
	defer close(d.done)
	r, closeReader, err := open(decoderInput{d})
	if err != nil {
		d.err = err
		return
	}
	defer closeReader()
	_, err = io.Copy(decoderOutput{d}, r)
	d.err = err
}

func (d *Decoder) pause(reason pauseReason) ([]byte, error) {
	select {
	case d.paused <- reason:
	case <-d.ctx.Done():
		return nil, context.Cause(d.ctx)
	}
	select {
	case chunk := <-d.resume:
		return chunk, nil
	case <-d.ctx.Done():
		return nil, context.Cause(d.ctx)
	}
}

type decoderInput struct{ d *Decoder }

func (in decoderInput) Read(p []byte) (int, error) {
	d := in.d
	for len(d.pending) == 0 {
		if d.eof {
			return 0, io.EOF
		}
		chunk, err := d.pause(needInput)
		if err != nil {
			return 0, err
		}
		if chunk == nil {
			d.eof = true
		}
		d.pending = chunk
	}
	n := copy(p, d.pending)
	d.pending = d.pending[n:]
	return n, nil
}

type decoderOutput struct{ d *Decoder }

func (out decoderOutput) Write(p []byte) (int, error) {
	d := out.d
	d.out = append(d.out, p...)
	if len(d.out) >= maxDecodedChunk {
		if _, err := d.pause(outputFull); err != nil {
			return 0, err
		}
	}
	return len(p), nil
}

package compress

import (
	"bytes"
	"context"
	"io"
	"math/rand"
	"net/http/httputil"
	"testing"
	"time"

	"github.com/andybalholm/brotli"
	"github.com/klauspost/compress/gzip"
	"github.com/klauspost/compress/zlib"
	"github.com/klauspost/compress/zstd"
	"github.com/stretchr/testify/require"
)

func compressed(t *testing.T, encoding string, data []byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	var w io.WriteCloser
	switch encoding {
	case "gzip":
		w = gzip.NewWriter(&buf)
	case "deflate":
		w = zlib.NewWriter(&buf)
	case "br":
		w = brotli.NewWriter(&buf)
	case "zstd":
		zw, err := zstd.NewWriter(&buf)
		require.NoError(t, err)
		w = zw
	case "identity":
		return data
	}
	_, err := w.Write(data)
	require.NoError(t, err)
	require.NoError(t, w.Close())
	return buf.Bytes()
}

func decodeInChunks(t *testing.T, d *Decoder, input []byte) ([]byte, error) {
	t.Helper()
	rng := rand.New(rand.NewSource(1))
	var decoded []byte
	collect := func(out []byte, err error) bool {
		require.LessOrEqual(t, len(out), maxDecodedChunk+64<<10)
		decoded = append(decoded, out...)
		return err == nil && len(out) > 0
	}
	drain := func(out []byte, err error) error {
		for collect(out, err) {
			out, err = d.Read()
		}
		return err
	}
	for len(input) > 0 {
		n := min(len(input), 1+rng.Intn(70000))
		out, err := d.Write(input[:n])
		if err := drain(out, err); err != nil {
			return decoded, err
		}
		input = input[n:]
	}
	out, err := d.Close()
	return decoded, drain(out, err)
}

func TestDecoderMatchesWholeBodyDecode(t *testing.T) {
	data := bytes.Repeat([]byte("nuclei streaming decoder "), 400000)
	for _, encoding := range []string{"gzip", "deflate", "br", "zstd", "identity"} {
		t.Run(encoding, func(t *testing.T) {
			d, err := NewDecoder(t.Context(), encoding)
			require.NoError(t, err)
			decoded, err := decodeInChunks(t, d, compressed(t, encoding, data))
			require.NoError(t, err)
			require.Equal(t, data, decoded)
		})
	}
}

func chunked(t *testing.T, data []byte) []byte {
	t.Helper()
	var buf bytes.Buffer
	w := httputil.NewChunkedWriter(&buf)
	for len(data) > 0 {
		n := min(len(data), 8000)
		_, err := w.Write(data[:n])
		require.NoError(t, err)
		data = data[n:]
	}
	require.NoError(t, w.Close())
	buf.WriteString("\r\n")
	return buf.Bytes()
}

func TestDecoderDecodesChunkedTransfer(t *testing.T) {
	data := bytes.Repeat([]byte("nuclei chunked decoder "), 400000)
	for _, encoding := range []string{"gzip", "deflate", "br", "zstd", "identity"} {
		t.Run(encoding, func(t *testing.T) {
			d, err := NewDecoder(t.Context(), encoding+", chunked")
			require.NoError(t, err)
			decoded, err := decodeInChunks(t, d, chunked(t, compressed(t, encoding, data)))
			require.NoError(t, err)
			require.Equal(t, data, decoded)
		})
	}
}

func TestDecoderFinishesAtLastChunk(t *testing.T) {
	data := bytes.Repeat([]byte("finished "), 1000)
	d, err := NewDecoder(t.Context(), "gzip, chunked")
	require.NoError(t, err)
	input := chunked(t, compressed(t, "gzip", data))

	half := len(input) / 2
	_, err = d.Write(input[:half])
	require.NoError(t, err)
	require.False(t, d.Finished())

	out, err := d.Write(input[half:])
	require.NoError(t, err)
	var decoded []byte
	for ; len(out) > 0; out, err = d.Read() {
		decoded = append(decoded, out...)
	}
	require.NoError(t, err)
	require.Equal(t, data, decoded)
	require.True(t, d.Finished(), "decoder must finish without Close once the last chunk arrives")
}

func TestDecoderAppliesCodingsInReverse(t *testing.T) {
	data := bytes.Repeat([]byte("two codings "), 100000)
	input := compressed(t, "br", compressed(t, "gzip", data))
	d, err := NewDecoder(t.Context(), "gzip, br")
	require.NoError(t, err)
	decoded, err := decodeInChunks(t, d, input)
	require.NoError(t, err)
	require.Equal(t, data, decoded)
}

func TestDecoderReportsTruncatedStream(t *testing.T) {
	data := bytes.Repeat([]byte("truncated "), 200000)
	for _, encoding := range []string{"gzip", "deflate", "br", "zstd", "identity, chunked"} {
		t.Run(encoding, func(t *testing.T) {
			var input []byte
			if encoding == "identity, chunked" {
				input = chunked(t, data)
			} else {
				input = compressed(t, encoding, data)
			}
			d, err := NewDecoder(t.Context(), encoding)
			require.NoError(t, err)
			decoded, err := decodeInChunks(t, d, input[:len(input)/2])
			require.Error(t, err)
			require.True(t, bytes.HasPrefix(data, decoded), "bytes before the cut must still be handed back")
		})
	}
}

func TestDecoderStopsWhenContextEnds(t *testing.T) {
	ctx, cancel := context.WithCancel(t.Context())
	d, err := NewDecoder(ctx, "gzip")
	require.NoError(t, err)
	_, err = d.Write(compressed(t, "gzip", []byte("abandoned"))[:5])
	require.NoError(t, err)

	cancel()
	select {
	case <-d.done:
	case <-time.After(time.Second):
		t.Fatal("decode goroutine outlived its context")
	}
}

func TestNewDecoderRejectsUnknownEncoding(t *testing.T) {
	_, err := NewDecoder(t.Context(), "compress")
	require.Error(t, err)
	_, err = NewDecoder(t.Context(), "gzip, compress")
	require.Error(t, err)
}

func TestDecoderNotCreatedByNewDecoderErrors(t *testing.T) {
	var d Decoder
	_, err := d.Write([]byte("x"))
	require.ErrorIs(t, err, errNotCreatedByNewDecoder)
	_, err = d.Read()
	require.ErrorIs(t, err, errNotCreatedByNewDecoder)
	_, err = d.Close()
	require.ErrorIs(t, err, errNotCreatedByNewDecoder)
}

// Package dcerpc exposes a small subset of the projectdiscovery/goimpacket DCE/RPC
// stack to nuclei javascript templates. It is the entry point for AD attack
// templates that need to talk EPMAPPER / SAMR / LSARPC / SVCCTL / TSCH / WINREG
// / SRVSVC to a domain controller or member server.
//
// Capability map overlapping nmap SMB scripts (issue #4707):
//
//	smb-enum-users     → Client.SamrEnumerateUsers
//	smb-enum-services  → Client.EnumServices
//	smb-enum-sessions  → Client.EnumSessions
//	smb-enum-processes → Client.EnumProcesses (WinStation LegacyAPI)
//	smb-psexec         → Client.SmbExec (also nuclei/goexec, nuclei/scmr)
//	smb-ls / cat       → Client.SmbLs / SmbCat (prefer nuclei/smb for new templates)
//	(logged-on users)  → Client.EnumLoggedOnUsers (WKSSVC; not in nmap list)
//
// Not implemented here (by design — do not add):
//
//	smb-flood          — DoS; harmful, no scanner value (nmap categories: dos)
//	smb-mbenum         — Master Browser / mailslots; obsolete NetBIOS surface
//	smb-print-text     — writes to printer spooler; intrusive niche
//	smb-protocols / unauth discovery — nuclei/smb
//
// All host arguments are validated against the per-execution network policy
// before any traffic is sent. The actual TCP dial is performed via goimpacket's
// transport package, which nuclei rewires to its fastdialer at startup, so
// proxy / DNS caching / network policy all apply transparently.
package dcerpc

import (
	"context"
	"fmt"
	"net"
	"strconv"
	"time"

	gpatexec "github.com/projectdiscovery/goimpacket/pkg/atexec"
	gprpc "github.com/projectdiscovery/goimpacket/pkg/dcerpc"
	gpepm "github.com/projectdiscovery/goimpacket/pkg/dcerpc/epmapper"
	gplsa "github.com/projectdiscovery/goimpacket/pkg/dcerpc/lsarpc"
	gpsamr "github.com/projectdiscovery/goimpacket/pkg/dcerpc/samr"
	gpsvcctl "github.com/projectdiscovery/goimpacket/pkg/dcerpc/svcctl"
	gptsch "github.com/projectdiscovery/goimpacket/pkg/dcerpc/tsch"
	gpsession "github.com/projectdiscovery/goimpacket/pkg/session"
	gpsmb "github.com/projectdiscovery/goimpacket/pkg/smb"
	gpsmbexec "github.com/projectdiscovery/goimpacket/pkg/smbexec"
	"github.com/projectdiscovery/goja"

	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/smbsession"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// Endpoint is a flat representation of an entry returned by the EPMAPPER.
type Endpoint = gpepm.Endpoint

// DomainUser is a SAMR domain user record.
type DomainUser = gpsamr.DomainUser

// LookupResult is the result of a SID->name resolution via LSARPC.
type LookupResult = gplsa.LookupResult

type (
	// Client is a stateful DCE/RPC + SMB client backed by projectdiscovery/goimpacket.
	// One Client wraps one authenticated SMB session against the target host;
	// individual RPC interfaces (SAMR, LSARPC, EPMAPPER, ...) are bound on
	// demand by the corresponding helper methods.
	//
	// @example
	// ```javascript
	// const dcerpc = require('nuclei/dcerpc');
	// const c = new dcerpc.Client('dc01.acme.local', 'acme.local', 'admin', 'P@ssw0rd');
	// const endpoints = c.RpcDump();
	// log(to_json(endpoints));
	// ```
	Client struct {
		Host    string
		Domain  string
		User    string
		Pass    string
		NTHash  string
		KrbCC   string
		Port    int
		nj      *utils.NucleiJS
		creds   *gpsession.Credentials
		target  gpsession.Target
		smb     *gpsmb.Client
		started bool
	}
)

// NewClient constructs a DCE/RPC client. Authentication is NTLM by default;
// pass an empty password and use SetHash to enable pass-the-hash.
//
// Constructor: constructor(public host: string, public domain: string, public user: string, public password: string)
func NewClient(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	c := &Client{nj: utils.NewNucleiJS(runtime)}
	c.nj.ObjectSig = "Client(host, domain, user, password)"

	c.Host, _ = c.nj.GetArg(call.Arguments, 0).(string)
	c.Domain, _ = c.nj.GetArg(call.Arguments, 1).(string)
	c.User, _ = c.nj.GetArg(call.Arguments, 2).(string)
	c.Pass, _ = c.nj.GetArg(call.Arguments, 3).(string)
	c.Port = 445

	c.nj.Require(c.Host != "", "host cannot be empty")
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		c.nj.Throw("host %s blacklisted by network policy", c.Host)
	}

	c.creds = &gpsession.Credentials{
		Domain:   c.Domain,
		Username: c.User,
		Password: c.Pass,
	}
	c.target = gpsession.Target{Host: c.Host, Port: c.Port}
	return utils.LinkConstructor(call, runtime, c)
}

// SetHash enables NTLM pass-the-hash authentication.
// hash may be the bare NT hash or "<lm>:<nt>".
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', '');
// c.SetHash('aad3b435b51404eeaad3b435b51404ee:31d6cfe0d16ae931b73c59d7e0c089c0');
// ```
func (c *Client) SetHash(hash string) {
	c.creds.Hash = hash
	c.creds.Password = ""
}

// SetKerberos switches the client to Kerberos authentication. dcIP optionally
// pins the KDC IP when DNS is uncooperative.
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01.acme.local', 'acme.local', 'admin', 'P@ss');
// c.SetKerberos('10.10.10.10');
// ```
func (c *Client) SetKerberos(dcIP string) {
	c.creds.UseKerberos = true
	c.creds.DCIP = dcIP
}

// SetPort overrides the default SMB port (445).
func (c *Client) SetPort(port int) {
	c.Port = port
	c.target.Port = port
}

// connect lazily establishes the underlying SMB session that all RPC
// transports are tunneled through. The SMB Client is bound to a Dialer that
// captures this client's executionId so every dial inside goimpacket is
// validated against the same network policy.
func (c *Client) connect() error {
	if c.started {
		return nil
	}
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	c.smb = gpsmb.NewClientWithDialer(c.target, c.creds, NewExecDialer(c.nj.ExecutionId()))
	if err := c.smb.Connect(); err != nil {
		return fmt.Errorf("smb connect: %w", err)
	}
	c.started = true
	return nil
}

// Close releases the underlying SMB session.
func (c *Client) Close() {
	if c.smb != nil {
		c.smb.Close()
	}
	c.started = false
}

// rpcOverNamedPipe binds the supplied interface UUID over a named pipe and
// returns an authenticated *dcerpc.Client.
func (c *Client) rpcOverNamedPipe(pipe string, uuid [16]byte, major, minor uint16) (*gprpc.Client, error) {
	if err := c.connect(); err != nil {
		return nil, err
	}
	pf, err := c.smb.OpenPipe(pipe)
	if err != nil {
		return nil, fmt.Errorf("open pipe %q: %w", pipe, err)
	}
	rpc := gprpc.NewClient(pf)
	if err := rpc.BindAuth(uuid, major, minor, c.creds); err != nil {
		_ = pf.Close()
		return nil, fmt.Errorf("dcerpc bind: %w", err)
	}
	return rpc, nil
}

// RpcDump enumerates every RPC endpoint registered with the EPMAPPER over
// ncacn_ip_tcp/135 (impacket: rpcdump.py).
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const eps = c.RpcDump();
// for (const e of eps) { log(e.UUID + ' ' + e.Annotation); }
// ```
func (c *Client) RpcDump(ctx context.Context) ([]Endpoint, error) {
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	dialer := protocolstate.GetDialersWithId(c.nj.ExecutionId())
	if dialer == nil {
		return nil, fmt.Errorf("dialers not initialized for execution %s", c.nj.ExecutionId())
	}
	conn, err := dialer.Fastdialer.Dial(ctx, "tcp", net.JoinHostPort(c.Host, strconv.Itoa(135)))
	if err != nil {
		return nil, fmt.Errorf("dial epmapper: %w", err)
	}
	defer func() { _ = conn.Close() }()

	rpc := gprpc.NewClientTCP(gprpc.NewTCPTransport(conn))
	if err := rpc.Bind(gpepm.UUID, gpepm.MajorVersion, gpepm.MinorVersion); err != nil {
		return nil, fmt.Errorf("epmapper bind: %w", err)
	}
	epm := gpepm.NewEpmClient(rpc)
	return epm.Lookup()
}

// SamrEnumerateUsers connects to SAMR and returns every domain user record
// (impacket: samrdump.py).
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const users = c.SamrEnumerateUsers();
// for (const u of users) { log(u.Name + ' ' + u.RID); }
// ```
func (c *Client) SamrEnumerateUsers() ([]DomainUser, error) {
	rpc, err := c.rpcOverNamedPipe("samr", gpsamr.UUID, gpsamr.MajorVersion, gpsamr.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	samr := gpsamr.NewSamrClient(rpc, rpc.GetSessionKey())
	if err := samr.Connect(); err != nil {
		return nil, fmt.Errorf("samr connect: %w", err)
	}
	if err := samr.OpenDomain(c.Domain); err != nil {
		return nil, fmt.Errorf("samr open domain: %w", err)
	}
	defer samr.Close()
	return samr.EnumerateDomainUsers()
}

// SamrAddComputer creates a new machine account using the supplied password.
// Useful as the first step in many AD escalations (RBCD / shadow credentials).
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// c.SamrAddComputer('NUCLEI$', 'C0mputerP@ss!');
// ```
func (c *Client) SamrAddComputer(name, password string) error {
	c.nj.Require(name != "", "computer name cannot be empty")
	c.nj.Require(password != "", "computer password cannot be empty")
	rpc, err := c.rpcOverNamedPipe("samr", gpsamr.UUID, gpsamr.MajorVersion, gpsamr.MinorVersion)
	if err != nil {
		return err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	samr := gpsamr.NewSamrClient(rpc, rpc.GetSessionKey())
	if err := samr.Connect(); err != nil {
		return fmt.Errorf("samr connect: %w", err)
	}
	if err := samr.OpenDomain(c.Domain); err != nil {
		return fmt.Errorf("samr open domain: %w", err)
	}
	defer samr.Close()
	return samr.CreateComputer(name, password)
}

// SmbExecResult is returned by SmbExec.
type SmbExecResult struct {
	ServiceName string `json:"service_name"`
	Output      string `json:"output"`
}

// SmbExec executes a Windows command on the target host using the
// SVCCTL "create + start service" technique (impacket: smbexec.py / psexec.py).
// The command's stdout/stderr is captured by writing to the chosen share
// (default C$) and read back over SMB. Local admin equivalent rights are
// required on the target.
//
// command  - the command line to run; for powershell prefix with
//
//	`powershell -EncodedCommand <b64utf16>` or use any cmd one-liner.
//
// share    - writable share to stage the output file in (default "C$").
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const r = c.SmbExec('whoami /all', 'C$');
// log(r.output);
// ```
func (c *Client) SmbExec(command, share string) (*SmbExecResult, error) {
	c.nj.Require(command != "", "command cannot be empty")
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	if err := c.connect(); err != nil {
		return nil, err
	}

	pf, err := c.smb.OpenPipe("svcctl")
	if err != nil {
		return nil, fmt.Errorf("open svcctl pipe: %w", err)
	}
	defer func() {
		_ = pf.Close()
	}()

	rpc := gprpc.NewClient(pf)
	if err := rpc.Bind(gpsvcctl.UUID, gpsvcctl.MajorVersion, gpsvcctl.MinorVersion); err != nil {
		return nil, fmt.Errorf("svcctl bind: %w", err)
	}
	sc, err := gpsvcctl.NewServiceController(rpc)
	if err != nil {
		return nil, fmt.Errorf("svcctl open scm: %w", err)
	}
	defer sc.Close()

	res, err := gpsmbexec.Exec(sc, c.smb, command, gpsmbexec.Options{
		Share:   share,
		Mode:    gpsmbexec.ModeShare,
		Timeout: 10 * time.Second,
	})
	if err != nil {
		return nil, err
	}
	return &SmbExecResult{ServiceName: res.ServiceName, Output: res.Output}, nil
}


// AtExecResult is returned by AtExec.
type AtExecResult struct {
	TaskName string `json:"task_name"`
	Output   string `json:"output"`
}

// AtExec executes a Windows command on the target host using the Task Scheduler
// service over the atsvc named pipe (impacket: atexec.py). A one-shot scheduled
// task is registered as LocalSystem, executed once, and then deleted. The
// command's stdout/stderr is captured into %windir%\Temp on the chosen share
// (default ADMIN$) and read back over SMB. Local admin equivalent rights are
// required on the target.
//
// All the heavy lifting (task XML, register / run / poll / cleanup) lives in
// goimpacket's pkg/atexec library; this wrapper only handles the JS-facing
// validation and the per-execution network policy enforcement.
//
// command - the command line to run (wrapped in cmd.exe /C ... by default).
// share   - writable share to retrieve the output file from (default "ADMIN$").
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const r = c.AtExec('whoami /all', 'ADMIN$');
// log(r.output);
// ```
func (c *Client) AtExec(command, share string) (*AtExecResult, error) {
	c.nj.Require(command != "", "command cannot be empty")
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	if err := c.connect(); err != nil {
		return nil, err
	}

	pf, err := c.smb.OpenPipe("atsvc")
	if err != nil {
		return nil, fmt.Errorf("open atsvc pipe: %w", err)
	}
	defer func() { _ = pf.Close() }()

	rpc := gprpc.NewClient(pf)
	if err := rpc.BindAuth(gptsch.UUID, gptsch.MajorVersion, gptsch.MinorVersion, c.creds); err != nil {
		return nil, fmt.Errorf("tsch bind: %w", err)
	}
	ts := gptsch.NewTaskScheduler(rpc)

	res, err := gpatexec.Exec(ts, c.smb, command, gpatexec.Options{
		Share:     share,
		Timeout:   15 * time.Second,
		SessionID: -1,
	})
	if err != nil {
		return nil, err
	}
	return &AtExecResult{TaskName: res.TaskName, Output: res.Output}, nil
}

// SmbListShares enumerates the SMB shares exposed by the target.
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// for (const s of c.SmbListShares()) { log(s); }
// ```
func (c *Client) SmbListShares() ([]string, error) {
	if err := c.connect(); err != nil {
		return nil, err
	}
	return smbsession.FromClient(c.smb).ListShares()
}

// SmbCat reads the contents of a single file from the given share. The path
// is interpreted relative to the share root (use forward slashes).
// Prefer nuclei/smb.ReadFile for new templates; this remains for dcerpc sessions.
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const txt = c.SmbCat('backup', 'backup_credentials.txt');
// log(txt);
// ```
func (c *Client) SmbCat(share, file string) (string, error) {
	c.nj.Require(share != "", "share cannot be empty")
	c.nj.Require(file != "", "file cannot be empty")
	if err := c.connect(); err != nil {
		return "", err
	}
	return smbsession.FromClient(c.smb).ReadFile(share, file, smbsession.DefaultMaxReadBytes)
}

// SmbLs lists files under dir on the given share. dir = "" lists the root.
// Prefer nuclei/smb.ListDir for new templates.
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const entries = c.SmbLs('backup', '');
// for (const e of entries) { log(e.Name + (e.IsDir ? '/' : '')); }
// ```
type FileEntry = smbsession.Entry

func (c *Client) SmbLs(share, dir string) ([]FileEntry, error) {
	c.nj.Require(share != "", "share cannot be empty")
	if err := c.connect(); err != nil {
		return nil, err
	}
	return smbsession.FromClient(c.smb).ListDir(share, dir)
}

// LsaLookupSids resolves an array of SIDs to (domain, name, type) triples
// against LSARPC (impacket: lookupsid.py).
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const r = c.LsaLookupSids(['S-1-5-21-...-500']);
// log(to_json(r));
// ```
func (c *Client) LsaLookupSids(sids []string) ([]LookupResult, error) {
	c.nj.Require(len(sids) > 0, "at least one SID must be provided")
	rpc, err := c.rpcOverNamedPipe("lsarpc", gplsa.UUID, gplsa.MajorVersion, gplsa.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	lsa, err := gplsa.NewLsaClient(rpc)
	if err != nil {
		return nil, fmt.Errorf("lsa init: %w", err)
	}
	if err := lsa.OpenPolicy2(); err != nil {
		return nil, fmt.Errorf("lsa OpenPolicy2: %w", err)
	}
	defer lsa.Close()
	return lsa.LookupSids(sids)
}

package dcerpc

import (
	"fmt"

	gpsrvsvc "github.com/projectdiscovery/goimpacket/pkg/dcerpc/srvsvc"
	gpsvcctl "github.com/projectdiscovery/goimpacket/pkg/dcerpc/svcctl"
	winstation "github.com/projectdiscovery/goimpacket/pkg/dcerpc/tsts"
	gpwkssvc "github.com/projectdiscovery/goimpacket/pkg/dcerpc/wkssvc"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// ServiceEntry is a flat SVCCTL service record suitable for JS templates
// (nmap smb-enum-services).
type ServiceEntry struct {
	Name        string `json:"name"`
	DisplayName string `json:"display_name"`
	State       string `json:"state"`
	StateCode   uint32 `json:"state_code"`
	Controls    uint32 `json:"controls,omitempty"`
}

// SessionEntry is a flat SRVSVC session record (nmap smb-enum-sessions).
type SessionEntry struct {
	Client   string `json:"client"`
	Username string `json:"username"`
	Active   uint32 `json:"active_seconds"`
	Idle     uint32 `json:"idle_seconds"`
}

// ProcessEntry is a running process from the Terminal Services Legacy API
// (nmap smb-enum-processes analogue; nmap uses winreg perf counters, we use WinStation).
type ProcessEntry struct {
	Name           string `json:"name"`
	PID            uint32 `json:"pid"`
	SessionID      uint32 `json:"session_id"`
	WorkingSetSize uint32 `json:"working_set_size,omitempty"`
	SID            string `json:"sid,omitempty"`
}

// LoggedOnUser is a WKSSVC workstation user record (interactive / network logons
// known to the target). Useful companion to SamrEnumerateUsers / EnumSessions.
type LoggedOnUser struct {
	Username    string `json:"username"`
	LogonDomain string `json:"logon_domain"`
	OthDomains  string `json:"other_domains,omitempty"`
	LogonServer string `json:"logon_server,omitempty"`
}

// EnumServices lists Win32 services on the target via SVCCTL
// (nmap: smb-enum-services). Requires an authenticated session with rights
// to open the Service Control Manager.
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('dc01.acme.local', 'acme.local', 'admin', 'P@ssw0rd');
// const services = c.EnumServices();
//
//	for (const s of services) {
//	  if (s.State === 'RUNNING') { log(s.Name + ' => ' + s.DisplayName); }
//	}
//
// ```
func (c *Client) EnumServices() ([]ServiceEntry, error) {
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	rpc, err := c.rpcOverNamedPipe("svcctl", gpsvcctl.UUID, gpsvcctl.MajorVersion, gpsvcctl.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	sc, err := gpsvcctl.NewServiceController(rpc)
	if err != nil {
		return nil, fmt.Errorf("svcctl open scm: %w", err)
	}
	defer sc.Close()

	const serviceWin32 = gpsvcctl.SERVICE_WIN32_OWN_PROCESS | gpsvcctl.SERVICE_WIN32_SHARE_PROCESS
	raw, err := sc.EnumServicesStatus(serviceWin32, gpsvcctl.SERVICE_STATE_ALL)
	if err != nil {
		return nil, err
	}
	return mapServiceEntries(raw), nil
}

// EnumSessions lists SMB sessions known to the server via SRVSVC
// (nmap: smb-enum-sessions). Often requires administrative rights.
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('fs01.acme.local', 'acme.local', 'admin', 'P@ssw0rd');
// const sessions = c.EnumSessions();
//
//	for (const s of sessions) {
//	  log(s.Username + '@' + s.Client + ' active=' + s.Active + 's');
//	}
//
// ```
func (c *Client) EnumSessions() ([]SessionEntry, error) {
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	rpc, err := c.rpcOverNamedPipe("srvsvc", gpsrvsvc.UUID, gpsrvsvc.MajorVersion, gpsrvsvc.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	raw, err := gpsrvsvc.NetrSessionEnum(rpc)
	if err != nil {
		return nil, err
	}
	return mapSessionEntries(raw), nil
}

// EnumProcesses lists running processes via the Terminal Services Legacy API
// (Ctx_WinStation_API_service). This is the goimpacket-backed analogue of
// nmap smb-enum-processes (which reads winreg performance counters). Requires
// rights to open the WinStation server handle; TermService should be running.
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('dc01.acme.local', 'acme.local', 'admin', 'P@ssw0rd');
// const procs = c.EnumProcesses();
//
//	for (const p of procs) {
//	  log(p.PID + ' ' + p.Name + ' session=' + p.SessionID);
//	}
//
// ```
func (c *Client) EnumProcesses() ([]ProcessEntry, error) {
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	rpc, err := c.rpcOverNamedPipe(winstation.PipeCtxWinStation, winstation.LegacyAPIUUID, winstation.MajorVersion, winstation.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	legacy := winstation.NewLegacyClient(rpc)
	handle, err := legacy.OpenServer()
	if err != nil {
		return nil, fmt.Errorf("winstation OpenServer: %w", err)
	}
	defer func() {
		_ = legacy.CloseServer(handle)
	}()

	raw, err := legacy.GetAllProcesses(handle)
	if err != nil {
		return nil, err
	}
	return mapProcessEntries(raw), nil
}

// EnumLoggedOnUsers lists users currently known to the workstation service
// via WKSSVC NetrWkstaUserEnum. Complements SamrEnumerateUsers (domain DB)
// and EnumSessions (SMB sessions).
//
// @example
// ```javascript
// const dcerpc = require('nuclei/dcerpc');
// const c = new dcerpc.Client('ws01.acme.local', 'acme.local', 'admin', 'P@ssw0rd');
// const users = c.EnumLoggedOnUsers();
// for (const u of users) { log(u.LogonDomain + '\\' + u.Username); }
// ```
func (c *Client) EnumLoggedOnUsers() ([]LoggedOnUser, error) {
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	rpc, err := c.rpcOverNamedPipe("wkssvc", gpwkssvc.UUID, gpwkssvc.MajorVersion, gpwkssvc.MinorVersion)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = rpc.Transport.Close()
	}()

	raw, err := gpwkssvc.NetrWkstaUserEnum(rpc)
	if err != nil {
		return nil, err
	}
	return mapLoggedOnUsers(raw), nil
}

func mapServiceEntries(raw []gpsvcctl.EnumServiceEntry) []ServiceEntry {
	out := make([]ServiceEntry, 0, len(raw))
	for _, e := range raw {
		out = append(out, ServiceEntry{
			Name:        e.ServiceName,
			DisplayName: e.DisplayName,
			State:       gpsvcctl.GetServiceState(e.Status.CurrentState),
			StateCode:   e.Status.CurrentState,
			Controls:    e.Status.ControlsAccepted,
		})
	}
	return out
}

func mapSessionEntries(raw []gpsrvsvc.SessionInfo10) []SessionEntry {
	out := make([]SessionEntry, 0, len(raw))
	for _, e := range raw {
		out = append(out, SessionEntry{
			Client:   e.Cname,
			Username: e.Username,
			Active:   e.ActiveTime,
			Idle:     e.IdleTime,
		})
	}
	return out
}

func mapProcessEntries(raw []winstation.ProcessInfo) []ProcessEntry {
	out := make([]ProcessEntry, 0, len(raw))
	for _, e := range raw {
		out = append(out, ProcessEntry{
			Name:           e.ImageName,
			PID:            e.UniqueProcessId,
			SessionID:      e.SessionId,
			WorkingSetSize: e.WorkingSetSize,
			SID:            e.SID,
		})
	}
	return out
}

func mapLoggedOnUsers(raw []gpwkssvc.WkstaUserInfo1) []LoggedOnUser {
	out := make([]LoggedOnUser, 0, len(raw))
	for _, e := range raw {
		out = append(out, LoggedOnUser{
			Username:    e.Username,
			LogonDomain: e.LogonDomain,
			OthDomains:  e.OthDomains,
			LogonServer: e.LogonServer,
		})
	}
	return out
}

