package dcerpc

import (
	"context"
	"net"
	"time"

	gpwmiexec "github.com/projectdiscovery/goimpacket/pkg/wmiexec"
	"github.com/oiweiwei/go-msrpc/dcerpc"

	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/gptransport"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// WmiExecResult is returned by WmiExec.
type WmiExecResult struct {
	ReturnValue uint32 `json:"return_value"`
	Output      string `json:"output"`
}

// WmiExec executes a Windows command on the target host using DCOM
// Win32_Process.Create over the WMI IWbemServices interface (impacket:
// wmiexec.py). The command is launched as a fresh process by the WMI host
// process and its stdout/stderr is redirected into a temp file on the chosen
// share (default ADMIN$) which is then read back over SMB. WmiExec is
// stealthier than SmbExec / AtExec because it does not create a service or a
// scheduled task, but Win32_Process.Create itself does not return any captured
// output - the file-tailing roundtrip is required to recover stdout.
//
// The DCOM bootstrap, NTLM/SPNEGO negotiation and Win32_Process.Create call
// live in goimpacket's pkg/wmiexec library; this wrapper only handles the
// JS-facing validation, the per-execution network policy enforcement, and
// wires nuclei's fastdialer into go-msrpc.
//
// command - the command line to run; wrapped in cmd.exe /Q /c by default.
// share   - writable share to retrieve the output file from (default "ADMIN$").
//
// Authentication: NTLM with password or pass-the-hash via SetHash. Kerberos is
// not yet supported on this code path.
//
// @example
// ```javascript
// const c = new dcerpc.Client('dc01', 'acme.local', 'admin', 'P@ss');
// const r = c.WmiExec('whoami /all', 'ADMIN$');
// log(r.output);
// ```
func (c *Client) WmiExec(command, share string) (*WmiExecResult, error) {
	c.nj.Require(command != "", "command cannot be empty")
	if !protocolstate.IsHostAllowed(c.nj.ExecutionId(), c.Host) {
		return nil, protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	if err := c.connect(); err != nil {
		return nil, err
	}

	target := c.target
	target.Host = c.Host
	target.IP = c.Host

	res, err := gpwmiexec.Exec(
		context.Background(),
		target,
		c.creds,
		command,
		gpwmiexec.Options{Share: share, Timeout: 15 * time.Second},
		gpwmiexec.DialOptions{
			Dialer: &execDialerAdapter{execID: c.nj.ExecutionId()},
			SMB:    c.smb,
		},
	)
	if err != nil {
		return nil, err
	}
	return &WmiExecResult{ReturnValue: res.ReturnValue, Output: res.Output}, nil
}

// execDialerAdapter routes go-msrpc's TCP dials through nuclei's per-execution
// fastdialer. Implements the dcerpc.Dialer interface (DialContext only).
type execDialerAdapter struct{ execID string }

func (e *execDialerAdapter) DialContext(ctx context.Context, network, address string) (net.Conn, error) {
	return gptransport.DialWithExec(ctx, e.execID, network, address)
}

// Compile-time guard that execDialerAdapter satisfies dcerpc.Dialer.
var _ dcerpc.Dialer = (*execDialerAdapter)(nil)

package dcom

import (
	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/goexec"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
)

// Auth exposes DCOM authentication constructors.
var Auth = goexec.AuthConstructors()

// Client is a GoExec-backed DCOM execution client.
type Client struct {
	target  string
	auth    *goexec.Auth
	options goexec.ExecutionOptions
	nj      *utils.NucleiJS
}

// NewClient constructs a DCOM client.
//
// Constructor: constructor(target: string, auth: any)
func NewClient(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	nj := utils.NewNucleiJS(runtime)
	nj.ObjectSig = "Client(target, auth)"
	client := &Client{options: goexec.DefaultExecutionOptions(), nj: nj}
	client.target, _ = nj.GetArg(call.Arguments, 0).(string)
	if auth, ok := nj.GetArg(call.Arguments, 1).(*goexec.Auth); ok {
		client.auth = auth
	} else {
		nj.Throw("auth must be created with dcom.Auth")
	}
	obj := runtime.NewObject()
	client.bindAliases(obj, runtime)
	return obj
}

// SetOptions updates default execution options for future client calls.
func (c *Client) SetOptions(opts interface{}) {
	c.options = goexec.MergeOptions(c.options, opts)
}

// MMC invokes the MMC20.Application DCOM execution method.
func (c *Client) MMC(executable string, args string, opts interface{}) map[string]interface{} {
	req := goexec.Request{
		Module:     "dcom",
		Method:     "mmc",
		Target:     c.target,
		Auth:       c.auth,
		Executable: executable,
		Args:       args,
		Options:    goexec.MergeOptions(c.options, opts),
	}
	return goexec.Run(goexec.WithExecutionID(c.nj.Context(), c.nj.ExecutionId()), req).Public()
}

func (c *Client) bindAliases(obj *goja.Object, runtime *goja.Runtime) {
	_ = obj.Set("setOptions", func(call goja.FunctionCall) goja.Value {
		c.SetOptions(exportArg(call, 0))
		return goja.Undefined()
	})
	_ = obj.Set("SetOptions", func(call goja.FunctionCall) goja.Value {
		c.SetOptions(exportArg(call, 0))
		return goja.Undefined()
	})
	_ = obj.Set("mmc", func(call goja.FunctionCall) goja.Value {
		executable, _ := exportArg(call, 0).(string)
		args, _ := exportArg(call, 1).(string)
		return runtime.ToValue(c.MMC(executable, args, exportArg(call, 2)))
	})
	_ = obj.Set("MMC", func(call goja.FunctionCall) goja.Value {
		executable, _ := exportArg(call, 0).(string)
		args, _ := exportArg(call, 1).(string)
		return runtime.ToValue(c.MMC(executable, args, exportArg(call, 2)))
	})
}

func exportArg(call goja.FunctionCall, index int) interface{} {
	if index >= len(call.Arguments) || goja.IsUndefined(call.Arguments[index]) || goja.IsNull(call.Arguments[index]) {
		return nil
	}
	return call.Arguments[index].Export()
}

package fs

import (
	"context"
	"os"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// ListDir lists itemType values within a directory
// depending on the itemType provided
// itemType can be any one of ['file','dir',”]
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // this will only return files in /tmp directory
// const files = fs.ListDir('/tmp', 'file');
// ```
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // this will only return directories in /tmp directory
// const dirs = fs.ListDir('/tmp', 'dir');
// ```
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // when no itemType is provided, it will return both files and directories
// const items = fs.ListDir('/tmp');
// ```
func ListDir(ctx context.Context, path string, itemType string) ([]string, error) {
	executionId := ctx.Value("executionId").(string)
	finalPath, err := protocolstate.NormalizePathWithExecutionId(executionId, path)
	if err != nil {
		return nil, err
	}
	values, err := os.ReadDir(finalPath)
	if err != nil {
		return nil, err
	}
	var results []string
	for _, value := range values {
		if itemType == "file" && value.IsDir() {
			continue
		}
		if itemType == "dir" && !value.IsDir() {
			continue
		}
		results = append(results, value.Name())
	}
	return results, nil
}

// ReadFile reads file contents within permitted paths
// and returns content as byte array
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // here permitted directories are $HOME/nuclei-templates/*
// const content = fs.ReadFile('helpers/usernames.txt');
// ```
func ReadFile(ctx context.Context, path string) ([]byte, error) {
	executionId := ctx.Value("executionId").(string)
	finalPath, err := protocolstate.NormalizePathWithExecutionId(executionId, path)
	if err != nil {
		return nil, err
	}
	bin, err := os.ReadFile(finalPath)
	return bin, err
}

// ReadFileAsString reads file contents within permitted paths
// and returns content as string
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // here permitted directories are $HOME/nuclei-templates/*
// const content = fs.ReadFileAsString('helpers/usernames.txt');
// ```
func ReadFileAsString(ctx context.Context, path string) (string, error) {
	bin, err := ReadFile(ctx, path)
	if err != nil {
		return "", err
	}
	return string(bin), nil
}

// ReadFilesFromDir reads all files from a directory
// and returns a string array with file contents of all files
// @example
// ```javascript
// const fs = require('nuclei/fs');
// // here permitted directories are $HOME/nuclei-templates/*
// const contents = fs.ReadFilesFromDir('helpers/ssh-keys');
// log(contents);
// ```
func ReadFilesFromDir(ctx context.Context, dir string) ([]string, error) {
	files, err := ListDir(ctx, dir, "file")
	if err != nil {
		return nil, err
	}
	var results []string
	for _, file := range files {
		content, err := ReadFileAsString(ctx, dir+"/"+file)
		if err != nil {
			return nil, err
		}
		results = append(results, content)
	}
	return results, nil
}

package goconsole

import (
	"github.com/projectdiscovery/goja_nodejs/console"
	"github.com/projectdiscovery/gologger"
)

