package goexec

import (
	"context"
	"sync"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// Runner executes a normalized Windows helper request.
type Runner interface {
	Run(ctx context.Context, req Request) (*Result, error)
}

// Request is the adapter boundary between JavaScript helpers and GoExec.
type Request struct {
	Module         string
	Method         string
	Target         string
	Auth           *Auth
	Executable     string
	Args           string
	Command        string
	TaskName       string
	ServiceName    string
	Namespace      string
	ClassName      string
	MethodName     string
	MethodArgsJSON string
	Options        ExecutionOptions
}

var (
	runnerMu      sync.RWMutex
	defaultRunner Runner = &GoExecRunner{}
)

type executionIDContextKey struct{}

var executionIDKey executionIDContextKey

// SetRunnerForTesting replaces the adapter runner and returns a restore func.
func SetRunnerForTesting(runner Runner) func() {
	runnerMu.Lock()
	previous := defaultRunner
	defaultRunner = runner
	runnerMu.Unlock()
	return func() {
		runnerMu.Lock()
		defaultRunner = previous
		runnerMu.Unlock()
	}
}

// WithExecutionID adds nuclei's execution ID to contexts passed through manual
// JavaScript closures that do not go through gojs' context injection path.
func WithExecutionID(ctx context.Context, executionID string) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	if executionID == "" {
		return ctx
	}
	if _, ok := ctx.Value(executionIDKey).(string); !ok {
		ctx = context.WithValue(ctx, executionIDKey, executionID)
	}
	if protocolstate.GetExecutionContext(ctx) == nil {
		ctx = protocolstate.WithExecutionID(ctx, &protocolstate.ExecutionContext{ExecutionID: executionID})
	}
	return ctx
}

// Run executes a helper request and always returns a structured Result.
func Run(ctx context.Context, req Request) *Result {
	start := time.Now()
	normalized, err := normalizeTarget(req.Target)
	if err != nil {
		result := newResult(req)
		result.DurationMS = time.Since(start).Milliseconds()
		result.Error = newRedactor(req.Auth).Error(err)
		return result
	}
	req.Target = normalized

	runnerMu.RLock()
	runner := defaultRunner
	runnerMu.RUnlock()

	result, err := runner.Run(ctx, req)
	if result == nil {
		result = newResult(req)
	}
	if err != nil {
		result.OK = false
		result.Error = newRedactor(req.Auth).Error(err)
	}
	result.DurationMS = time.Since(start).Milliseconds()
	result.Stdout = truncateOutput(newRedactor(req.Auth).String(result.Stdout), req.Options.MaxOutputSize)
	result.Stderr = truncateOutput(newRedactor(req.Auth).String(result.Stderr), req.Options.MaxOutputSize)
	result.Error = newRedactor(req.Auth).String(result.Error)
	return result
}

package goexec

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"strings"
	"time"

	upstream "github.com/FalconOpsLLC/goexec/pkg/goexec"
	godce "github.com/FalconOpsLLC/goexec/pkg/goexec/dce"
	godcom "github.com/FalconOpsLLC/goexec/pkg/goexec/dcom"
	goscmr "github.com/FalconOpsLLC/goexec/pkg/goexec/scmr"
	gosmb "github.com/FalconOpsLLC/goexec/pkg/goexec/smb"
	gotsch "github.com/FalconOpsLLC/goexec/pkg/goexec/tsch"
	gowmi "github.com/FalconOpsLLC/goexec/pkg/goexec/wmi"
	"github.com/RedTeamPentesting/adauth"
	"github.com/google/uuid"
	"github.com/oiweiwei/go-msrpc/dcerpc"
	"github.com/oiweiwei/go-msrpc/ssp/gssapi"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/rs/zerolog"
)

// GoExecRunner maps nuclei helper requests to FalconOps GoExec library calls.
type GoExecRunner struct{}

func (r *GoExecRunner) Run(ctx context.Context, req Request) (*Result, error) {
	result := newResult(req)
	redactor := newRedactor(req.Auth)

	if err := req.Auth.validate(); err != nil {
		return result, err
	}
	if !protocolstate.IsHostAllowed(executionID(ctx), targetHost(req.Target)) {
		return result, protocolstate.ErrHostDenied.Msgf(req.Target)
	}
	if req.Auth.domainController != "" && !protocolstate.IsHostAllowed(executionID(ctx), targetHost(req.Auth.domainController)) {
		return result, ErrDomainControllerDenied
	}
	if req.Options.Proxy != "" && !proxyAllowed(ctx, req.Options.Proxy) {
		return result, ErrProxyDenied
	}
	if req.Options.Endpoint != "" && !endpointAllowed(ctx, req.Options.Endpoint) {
		return result, ErrEndpointDenied
	}
	if req.Options.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(req.Options.Timeout)*time.Second)
		defer cancel()
	}
	ctx = gssapi.NewSecurityContext(ctx)
	ctx = zerolog.New(io.Discard).WithContext(ctx)

	var err error
	switch strings.ToLower(req.Module) {
	case "wmi":
		err = r.runWMI(ctx, req, result)
	case "tsch":
		err = r.runTSCH(ctx, req, result)
	case "scmr":
		err = r.runSCMR(ctx, req, result)
	case "dcom":
		err = r.runDCOM(ctx, req, result)
	default:
		err = ErrUnsupportedModule
	}
	if err != nil {
		result.Error = redactor.Error(err)
		result.OK = false
		return result, nil
	}
	result.OK = true
	result.ExitCode = 0
	return result, nil
}

func (r *GoExecRunner) runWMI(ctx context.Context, req Request, result *Result) error {
	switch strings.ToLower(req.Method) {
	case "command", "proc":
		execIO, err := r.executionIO(ctx, req, result)
		if err != nil {
			return err
		}
		client, err := r.dceClient(ctx, req, "cifs", "")
		if err != nil {
			return err
		}
		module := &gowmi.WmiProc{
			Wmi: gowmi.Wmi{
				Client:   client,
				Resource: "//./root/cimv2",
			},
			WorkingDirectory: req.Options.Directory,
		}
		if err := upstream.ExecuteCleanMethod(ctx, module, execIO); err != nil {
			return err
		}
		collectExecutionOutput(req, result, execIO)
		return nil
	case "call":
		client, err := r.dceClient(ctx, req, "cifs", "")
		if err != nil {
			return err
		}
		args := map[string]any{}
		if req.MethodArgsJSON != "" {
			if err := json.Unmarshal([]byte(req.MethodArgsJSON), &args); err != nil {
				return fmt.Errorf("%w: %w", ErrInvalidMethodArguments, err)
			}
		}
		var out bytes.Buffer
		module := &gowmi.WmiCall{
			Wmi: gowmi.Wmi{
				Client:   client,
				Resource: defaultString(req.Namespace, "//./root/cimv2"),
			},
			Class:  req.ClassName,
			Method: req.MethodName,
			Args:   args,
			Out:    &out,
		}
		if module.Class == "" || module.Method == "" {
			return ErrInvalidMethodArguments
		}
		if err := upstream.ExecuteCleanAuxiliaryMethod(ctx, module); err != nil {
			return err
		}
		result.Stdout = out.String()
		result.OutputCollected = true
		return nil
	default:
		return ErrUnsupportedMethod
	}
}

func (r *GoExecRunner) runTSCH(ctx context.Context, req Request, result *Result) error {
	execIO, err := r.executionIO(ctx, req, result)
	if err != nil {
		return err
	}
	client, err := r.dceClient(ctx, req, "cifs", "ncacn_np:[atsvc]")
	if err != nil {
		return err
	}
	switch strings.ToLower(req.Method) {
	case "demand":
		module := &gotsch.TschDemand{
			Tsch: gotsch.Tsch{
				Client:   client,
				TaskPath: taskPath(req.TaskName),
			},
		}
		result.Cleanup.Attempted = true
		if err := upstream.ExecuteCleanMethod(ctx, module, execIO); err != nil {
			return err
		}
		collectExecutionOutput(req, result, execIO)
		return nil
	case "create":
		module := &gotsch.TschCreate{
			Tsch: gotsch.Tsch{
				Client:   client,
				TaskPath: taskPath(req.TaskName),
			},
			CallDelete: true,
		}
		result.Cleanup.Attempted = true
		if err := upstream.ExecuteCleanMethod(ctx, module, execIO); err != nil {
			return err
		}
		collectExecutionOutput(req, result, execIO)
		return nil
	default:
		return ErrUnsupportedMethod
	}
}

func (r *GoExecRunner) runSCMR(ctx context.Context, req Request, result *Result) error {
	execIO, err := r.executionIO(ctx, req, result)
	if err != nil {
		return err
	}
	client, err := r.dceClient(ctx, req, "cifs", "ncacn_np:[svcctl]")
	if err != nil {
		return err
	}
	module := &goscmr.ScmrCreate{
		Scmr: goscmr.Scmr{
			Client: client,
		},
		ServiceName: req.ServiceName,
	}
	result.Cleanup.Attempted = true
	if err := upstream.ExecuteCleanMethod(ctx, module, execIO); err != nil {
		return err
	}
	collectExecutionOutput(req, result, execIO)
	return nil
}

func (r *GoExecRunner) runDCOM(ctx context.Context, req Request, result *Result) error {
	if strings.ToLower(req.Method) != "mmc" {
		return ErrUnsupportedMethod
	}
	execIO, err := r.executionIO(ctx, req, result)
	if err != nil {
		return err
	}
	client, err := r.dceClient(ctx, req, "cifs", "")
	if err != nil {
		return err
	}
	module := &godcom.DcomMmc{
		Dispatch: godcom.Dispatch{
			Dcom: godcom.Dcom{
				Client: client,
			},
		},
		WorkingDirectory: req.Options.Directory,
		WindowState:      "Minimized",
	}
	if err := upstream.ExecuteCleanMethod(ctx, module, execIO); err != nil {
		return err
	}
	collectExecutionOutput(req, result, execIO)
	return nil
}

func (r *GoExecRunner) dceClient(ctx context.Context, req Request, protocol, endpoint string) (*godce.Client, error) {
	credential, target, err := r.credentials(ctx, protocol, req)
	if err != nil {
		return nil, err
	}
	client := &godce.Client{}
	client.Credential = credential
	client.Target = target
	client.Proxy = req.Options.Proxy
	client.NoSign = req.Options.NoSign
	client.NoSeal = req.Options.NoSeal
	client.Endpoint = req.Options.Endpoint
	client.Filter = req.Options.EPMFilter
	if client.Endpoint == "" && endpoint != "" {
		client.Endpoint = endpoint
	}
	if client.Endpoint == "" {
		client.UseEpm = true
	}
	if req.Options.EPM {
		client.UseEpm = true
	}
	if err := client.Parse(ctx); err != nil {
		return nil, err
	}
	return client, nil
}

func (r *GoExecRunner) smbClient(ctx context.Context, req Request) (*gosmb.Client, error) {
	credential, target, err := r.credentials(ctx, "cifs", req)
	if err != nil {
		return nil, err
	}
	client := &gosmb.Client{}
	client.Credential = credential
	client.Target = target
	client.Proxy = req.Options.Proxy
	client.NoSign = req.Options.NoSign
	client.NoSeal = req.Options.NoSeal
	if err := client.Parse(ctx); err != nil {
		return nil, err
	}
	return client, nil
}

func (r *GoExecRunner) credentials(ctx context.Context, protocol string, req Request) (*adauth.Credential, *adauth.Target, error) {
	opts := &adauth.Options{
		User:             req.Auth.username,
		Password:         req.Auth.password,
		NTHash:           req.Auth.ntHash,
		AESKey:           req.Auth.aesKey,
		CCache:           req.Auth.ccache,
		DomainController: req.Auth.domainController,
		ForceKerberos:    req.Auth.kerberos,
		PFXFileName:      req.Auth.pfxPath,
		PFXPassword:      req.Auth.pfxPassword,
	}
	return opts.WithTarget(ctx, protocol, req.Target)
}

func (r *GoExecRunner) executionIO(ctx context.Context, req Request, result *Result) (*upstream.ExecutionIO, error) {
	input := &upstream.ExecutionInput{
		Executable: req.Executable,
		Arguments:  req.Args,
		Command:    req.Command,
	}
	if req.Method == "command" && req.Command == "" {
		return nil, ErrMissingCommand
	}
	if req.Method != "command" && req.Executable == "" && req.Command == "" {
		return nil, ErrMissingExecutable
	}
	execIO := &upstream.ExecutionIO{
		Input: input,
	}
	if !req.Options.Output {
		return execIO, nil
	}
	if req.Options.OutputMethod != "" && req.Options.OutputMethod != DefaultOutputMethod {
		return nil, ErrUnsupportedOutputMethod
	}

	var out bytes.Buffer
	output := &upstream.ExecutionOutput{
		NoDelete:   req.Options.NoDeleteOutput,
		RemotePath: `C:\Windows\Temp\` + uuid.NewString(),
		Timeout:    time.Duration(req.Options.OutputTimeout) * time.Second,
		Writer:     nopWriteCloser{Writer: &out},
	}
	smbClient, err := r.smbClient(ctx, req)
	if err != nil {
		return nil, err
	}
	output.Provider = &gosmb.OutputFileFetcher{
		Client:           smbClient,
		Share:            `ADMIN$`,
		SharePath:        `C:\Windows`,
		File:             output.RemotePath,
		DeleteOutputFile: !output.NoDelete,
	}
	execIO.Output = output
	result.OutputMethod = DefaultOutputMethod
	result.Cleanup.Attempted = true
	result.Cleanup.Artifacts = []string{output.RemotePath}
	return execIO, nil
}

func collectExecutionOutput(req Request, result *Result, execIO *upstream.ExecutionIO) {
	if !req.Options.Output {
		return
	}
	result.Stdout = execIOOutput(execIO)
	result.OutputCollected = true
}

func execIOOutput(execIO *upstream.ExecutionIO) string {
	if execIO == nil || execIO.Output == nil || execIO.Output.Writer == nil {
		return ""
	}
	if writer, ok := execIO.Output.Writer.(interface{ String() string }); ok {
		return writer.String()
	}
	return ""
}

type nopWriteCloser struct {
	io.Writer
}

func (n nopWriteCloser) Close() error { return nil }

func (n nopWriteCloser) String() string {
	if s, ok := n.Writer.(interface{ String() string }); ok {
		return s.String()
	}
	return ""
}

func executionID(ctx context.Context) string {
	if ctx == nil {
		return ""
	}
	if value, ok := ctx.Value(executionIDKey).(string); ok && value != "" {
		return value
	}
	if value, ok := ctx.Value("executionId").(string); ok && value != "" {
		return value
	}
	if execCtx := protocolstate.GetExecutionContext(ctx); execCtx != nil {
		return execCtx.ExecutionID
	}
	return ""
}

func proxyAllowed(ctx context.Context, proxyURI string) bool {
	parsed, err := url.Parse(proxyURI)
	if err != nil || parsed.Hostname() == "" {
		return true
	}
	return protocolstate.IsHostAllowed(executionID(ctx), parsed.Hostname())
}

func endpointAllowed(ctx context.Context, endpoint string) bool {
	binding, err := dcerpc.ParseStringBinding(endpoint)
	if err != nil || binding.NetworkAddress == "" || binding.NetworkAddress == "0.0.0.0" || strings.HasPrefix(binding.NetworkAddress, "\\") {
		return true
	}
	return protocolstate.IsHostAllowed(executionID(ctx), binding.NetworkAddress)
}

func taskPath(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return `\` + uuid.NewString()
	}
	if strings.HasPrefix(name, `\`) {
		return name
	}
	return `\` + name
}

func defaultString(value, fallback string) string {
	if value == "" {
		return fallback
	}
	return value
}

package goexec

import (
	"bytes"
	"context"
	"strings"
	"testing"

	upstream "github.com/FalconOpsLLC/goexec/pkg/goexec"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

func TestRunRedactsRunnerErrors(t *testing.T) {
	restore := SetRunnerForTesting(runnerFunc(func(context.Context, Request) (*Result, error) {
		return nil, assertErr("authentication failed with secret-pass")
	}))
	defer restore()

	result := Run(context.Background(), Request{
		Module:  "wmi",
		Method:  "command",
		Target:  "127.0.0.1",
		Auth:    Password("CORP\\auditor", "secret-pass"),
		Command: "whoami",
		Options: DefaultExecutionOptions(),
	})
	if result.OK {
		t.Fatal("expected failed result")
	}
	if strings.Contains(result.Error, "secret-pass") {
		t.Fatalf("secret leaked in result error: %q", result.Error)
	}
}

func TestGoExecRunnerDeniesNetworkPolicyBeforeDial(t *testing.T) {
	executionID := "goexec-deny-test"
	if err := protocolstate.Init(&types.Options{
		ExecutionId:    executionID,
		ExcludeTargets: []string{"denied.local"},
	}); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { protocolstate.Close(executionID) })
	ctx := WithExecutionID(context.Background(), executionID)

	result := Run(ctx, Request{
		Module:  "wmi",
		Method:  "command",
		Target:  "denied.local",
		Auth:    Password("CORP\\auditor", "secret"),
		Command: "whoami",
		Options: DefaultExecutionOptions(),
	})
	if result.OK || !strings.Contains(result.Error, "network policy") {
		t.Fatalf("expected network-policy denial result, got %#v", result)
	}
}

func TestGoExecRunnerDeniesProxyNetworkPolicyBeforeDial(t *testing.T) {
	executionID := "goexec-proxy-deny-test"
	if err := protocolstate.Init(&types.Options{
		ExecutionId:    executionID,
		ExcludeTargets: []string{"169.254.169.254"},
	}); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { protocolstate.Close(executionID) })
	ctx := WithExecutionID(context.Background(), executionID)

	options := DefaultExecutionOptions()
	options.Proxy = "socks5://169.254.169.254:1080"
	result := Run(ctx, Request{
		Module:  "wmi",
		Method:  "command",
		Target:  "127.0.0.1",
		Auth:    Password("CORP\\auditor", "secret"),
		Command: "whoami",
		Options: options,
	})
	if result.OK || !strings.Contains(result.Error, ErrProxyDenied.Error()) {
		t.Fatalf("expected proxy network-policy denial result, got %#v", result)
	}
}

func TestGoExecRunnerDeniesEndpointNetworkPolicyBeforeDial(t *testing.T) {
	executionID := "goexec-endpoint-deny-test"
	if err := protocolstate.Init(&types.Options{
		ExecutionId:    executionID,
		ExcludeTargets: []string{"169.254.169.254"},
	}); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { protocolstate.Close(executionID) })
	ctx := WithExecutionID(context.Background(), executionID)

	options := DefaultExecutionOptions()
	options.Endpoint = "ncacn_ip_tcp:169.254.169.254[135]"
	result := Run(ctx, Request{
		Module:  "wmi",
		Method:  "command",
		Target:  "127.0.0.1",
		Auth:    Password("CORP\\auditor", "secret"),
		Command: "whoami",
		Options: options,
	})
	if result.OK || !strings.Contains(result.Error, ErrEndpointDenied.Error()) {
		t.Fatalf("expected endpoint network-policy denial result, got %#v", result)
	}
}

func TestCollectExecutionOutputCopiesWriter(t *testing.T) {
	var out bytes.Buffer
	_, _ = out.WriteString("captured output")

	req := Request{Options: DefaultExecutionOptions()}
	req.Options.Output = true
	result := newResult(req)
	execIO := &upstream.ExecutionIO{
		Output: &upstream.ExecutionOutput{
			Writer: nopWriteCloser{Writer: &out},
		},
	}

	collectExecutionOutput(req, result, execIO)

	if result.Stdout != "captured output" || !result.OutputCollected {
		t.Fatalf("expected collected output in result, got %#v", result)
	}
}

type runnerFunc func(context.Context, Request) (*Result, error)

func (f runnerFunc) Run(ctx context.Context, req Request) (*Result, error) {
	return f(ctx, req)
}

type assertErr string

func (a assertErr) Error() string { return string(a) }

package goexec

import (
	"strings"
)

type credentialMode string

const (
	modePassword credentialMode = "password"
	modeNTHash   credentialMode = "nt_hash"
	modeKerberos credentialMode = "kerberos"
	modeAESKey   credentialMode = "aes_key"
	modeCCache   credentialMode = "ccache"
	modePFX      credentialMode = "pfx"
)

// Auth stores Windows authentication material for GoExec-backed helpers.
//
// The credential fields are intentionally unexported so JavaScript templates
// cannot serialize them back into findings, debug output, or stored responses.
type Auth struct {
	mode             credentialMode
	username         string
	password         string
	ntHash           string
	aesKey           string
	pfxPath          string
	pfxPassword      string
	ccache           string
	kerberos         bool
	domainController string
}

// AuthConstructors returns the JavaScript-facing Auth helper namespace.
func AuthConstructors() map[string]interface{} {
	return map[string]interface{}{
		"password": Password,
		"ntHash":   NTHash,
		"kerberos": Kerberos,
		"aesKey":   AESKey,
		"ccache":   CCache,
		"pfx":      PFX,
	}
}

// Password creates username/password authentication.
func Password(username, password string) *Auth {
	return &Auth{
		mode:     modePassword,
		username: username,
		password: password,
	}
}

// NTHash creates pass-the-hash authentication.
func NTHash(username, ntHash string, extra ...string) *Auth {
	if len(extra) > 0 && extra[0] != "" && !strings.Contains(ntHash, ":") {
		ntHash += ":" + extra[0]
	}
	return &Auth{
		mode:     modeNTHash,
		username: username,
		ntHash:   ntHash,
	}
}

// Kerberos creates Kerberos authentication with optional fields such as dc.
func Kerberos(username string, options ...interface{}) *Auth {
	auth := &Auth{
		mode:     modeKerberos,
		username: username,
		kerberos: true,
	}
	auth.applyAuthOptions(firstOption(options))
	return auth
}

// AESKey creates Kerberos AES-key authentication.
func AESKey(username, aesKey string, options ...interface{}) *Auth {
	auth := &Auth{
		mode:     modeAESKey,
		username: username,
		aesKey:   aesKey,
		kerberos: true,
	}
	auth.applyAuthOptions(firstOption(options))
	return auth
}

// CCache creates ccache authentication.
func CCache(path string) *Auth {
	return &Auth{
		mode:     modeCCache,
		ccache:   path,
		kerberos: true,
	}
}

// PFX creates PFX client certificate authentication.
func PFX(username, pfxPath, pfxPassword string) *Auth {
	return &Auth{
		mode:        modePFX,
		username:    username,
		pfxPath:     pfxPath,
		pfxPassword: pfxPassword,
		kerberos:    true,
	}
}

// MarshalJSON intentionally hides credential material from serialized output.
func (a *Auth) MarshalJSON() ([]byte, error) {
	return []byte("{}"), nil
}

func firstOption(options []interface{}) interface{} {
	if len(options) == 0 {
		return nil
	}
	return options[0]
}

func (a *Auth) applyAuthOptions(raw interface{}) {
	values := mapFromAny(raw)
	if values == nil {
		return
	}
	if dc := stringValue(values, "dc", "domainController", "domain_controller"); dc != "" {
		a.domainController = dc
	}
	if kerberos, ok := boolValue(values, "kerberos"); ok {
		a.kerberos = kerberos
	}
	if password := stringValue(values, "password"); password != "" {
		a.password = password
	}
	if ntHash := stringValue(values, "ntHash", "nt_hash", "hash"); ntHash != "" {
		a.ntHash = ntHash
	}
	if ccache := stringValue(values, "ccache", "cCache"); ccache != "" {
		a.ccache = ccache
	}
}

func (a *Auth) validate() error {
	if a == nil {
		return ErrMissingAuth
	}
	selected := 0
	for _, value := range []string{a.password, a.ntHash, a.aesKey, a.pfxPath, a.ccache} {
		if value != "" {
			selected++
		}
	}
	switch {
	case selected == 0 && !a.kerberos:
		return ErrMissingAuth
	case selected > 1:
		// goexec/adauth always picks a single credential source. Allowing
		// more than one (even when kerberos is true) is almost certainly a
		// template mistake that would otherwise be silently truncated.
		return ErrMultipleCredentialModes
	case a.username == "" && a.mode != modeCCache:
		return ErrMissingUsername
	}
	return nil
}

func (a *Auth) secrets() []string {
	if a == nil {
		return nil
	}
	values := []string{
		a.password,
		a.ntHash,
		a.aesKey,
		a.pfxPassword,
		a.ccache,
	}
	if strings.ContainsAny(a.username, `\/@`) {
		values = append(values, a.username)
	}
	if strings.Contains(a.ntHash, ":") {
		values = append(values, strings.Split(a.ntHash, ":")...)
	}
	return compactStrings(values)
}

func compactStrings(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

