package kerberos

// the following code is adapted from the original library
// https://github.com/jcmturner/gokrb5/blob/855dbc707a37a21467aef6c0245fcf3328dc39ed/v8/client/network.go
// it is copied here because the library does not export "SendToKDC()"

import (
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"io"
	"net"
	"strings"
	"time"

	"github.com/jcmturner/gokrb5/v8/messages"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// sendtokdc.go deals with actual sending and receiving responses from KDC
// SendToKDC sends a message to the KDC and returns the response.
// It first tries to send the message over TCP, and if that fails, it falls back to UDP.(and vice versa)
// @example
// ```javascript
// const kerberos = require('nuclei/kerberos');
// const client = new kerberos.Client('acme.com');
// const response = kerberos.SendToKDC(client, 'message');
// ```
func SendToKDC(kclient *Client, msg string) (string, error) {
	if kclient == nil || kclient.nj == nil || kclient.Krb5Config == nil || kclient.Realm == "" {
		return "", fmt.Errorf("kerberos client is not initialized")
	}
	if kclient.config.timeout == 0 {
		kclient.config.timeout = 5 // default timeout 5 seconds
	}
	var response []byte
	var err error

	response, err = sendToKDCTcp(kclient, msg)
	if err == nil {
		// if it related to tcp
		bin, err := CheckKrbError(response)
		if err == nil {
			return string(bin), nil
		}
		// if it is krb error no need to do udp
		if e, ok := err.(messages.KRBError); ok {
			return string(response), e
		}
	}

	// fallback to udp
	response, err = sendToKDCUdp(kclient, msg)
	if err == nil {
		// if it related to udp
		bin, err := CheckKrbError(response)
		if err == nil {
			return string(bin), nil
		}
	}
	return string(response), err
}

// sendToKDCTcp sends a message to the KDC via TCP.
func sendToKDCTcp(kclient *Client, msg string) ([]byte, error) {
	_, kdcs, err := kclient.Krb5Config.GetKDCs(kclient.Realm, true)
	kclient.nj.HandleError(err, "error getting KDCs")
	kclient.nj.Require(len(kdcs) > 0, "no KDCs found")

	executionId := kclient.nj.ExecutionId()
	dialers := protocolstate.GetDialersWithId(executionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	dialCtx := kclient.nj.Context()
	var errs []string
	for i := 1; i <= len(kdcs); i++ {
		host, port, err := net.SplitHostPort(kdcs[i])
		if err == nil && kclient.config.ip != "" {
			// use that ip address instead of realm/domain for resolving
			host = kclient.config.ip
		}
		tcpConn, err := dialers.Fastdialer.Dial(dialCtx, "tcp", net.JoinHostPort(host, port))
		if err != nil {
			errs = append(errs, fmt.Sprintf("error establishing connection to %s: %v", kdcs[i], err))
			continue
		}
		defer func() {
			_ = tcpConn.Close()
		}()
		_ = tcpConn.SetDeadline(time.Now().Add(time.Duration(kclient.config.timeout) * time.Second)) //read and write deadline
		rb, err := sendTCP(tcpConn.(*net.TCPConn), []byte(msg))
		if err != nil {
			errs = append(errs, fmt.Sprintf("error sending to %s: %v", kdcs[i], err))
			continue
		}
		return rb, nil
	}
	if len(errs) > 0 {
		return nil, fmt.Errorf("error sending to a KDC: %s", strings.Join(errs, "; "))
	}
	return nil, nil
}

// sendToKDCUdp sends a message to the KDC via UDP.
func sendToKDCUdp(kclient *Client, msg string) ([]byte, error) {
	_, kdcs, err := kclient.Krb5Config.GetKDCs(kclient.Realm, true)
	kclient.nj.HandleError(err, "error getting KDCs")
	kclient.nj.Require(len(kdcs) > 0, "no KDCs found")

	executionId := kclient.nj.ExecutionId()
	dialers := protocolstate.GetDialersWithId(executionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", executionId)
	}
	dialCtx := kclient.nj.Context()
	var errs []string
	for i := 1; i <= len(kdcs); i++ {
		host, port, err := net.SplitHostPort(kdcs[i])
		if err == nil && kclient.config.ip != "" {
			// use that ip address instead of realm/domain for resolving
			host = kclient.config.ip
		}
		udpConn, err := dialers.Fastdialer.Dial(dialCtx, "udp", net.JoinHostPort(host, port))
		if err != nil {
			errs = append(errs, fmt.Sprintf("error establishing connection to %s: %v", kdcs[i], err))
			continue
		}
		defer func() {
			_ = udpConn.Close()
		}()
		_ = udpConn.SetDeadline(time.Now().Add(time.Duration(kclient.config.timeout) * time.Second)) //read and write deadline
		rb, err := sendUDP(udpConn.(*net.UDPConn), []byte(msg))
		if err != nil {
			errs = append(errs, fmt.Sprintf("error sending to %s: %v", kdcs[i], err))
			continue
		}
		return rb, nil
	}
	if len(errs) > 0 {
		// fallback to tcp
		return nil, fmt.Errorf("error sending to a KDC: %s", strings.Join(errs, "; "))
	}
	return nil, nil
}

// sendUDP sends bytes to connection over UDP.
func sendUDP(conn *net.UDPConn, b []byte) ([]byte, error) {
	var r []byte
	defer func() {
		_ = conn.Close()
	}()
	_, err := conn.Write(b)
	if err != nil {
		return r, fmt.Errorf("error sending to (%s): %v", conn.RemoteAddr().String(), err)
	}
	udpbuf := make([]byte, 4096)
	n, _, err := conn.ReadFrom(udpbuf)
	r = udpbuf[:n]
	if err != nil {
		return r, fmt.Errorf("sending over UDP failed to %s: %v", conn.RemoteAddr().String(), err)
	}
	if len(r) < 1 {
		return r, fmt.Errorf("no response data from %s", conn.RemoteAddr().String())
	}
	return r, nil
}

// sendTCP sends bytes to connection over TCP.
func sendTCP(conn *net.TCPConn, b []byte) ([]byte, error) {
	defer func() {
		_ = conn.Close()
	}()
	var r []byte
	// RFC 4120 7.2.2 specifies the first 4 bytes indicate the length of the message in big endian order.
	hb := make([]byte, 4)
	binary.BigEndian.PutUint32(hb, uint32(len(b)))
	b = append(hb, b...)

	_, err := conn.Write(b)
	if err != nil {
		return r, fmt.Errorf("error sending to KDC (%s): %v", conn.RemoteAddr().String(), err)
	}

	sh := make([]byte, 4)
	// A single Read may return fewer than 4 bytes when the header arrives in
	// more than one segment, which would decode the wrong message length.
	_, err = io.ReadFull(conn, sh)
	if err != nil {
		return r, fmt.Errorf("error reading response size header: %v", err)
	}
	s := binary.BigEndian.Uint32(sh)

	rb := make([]byte, s)
	_, err = io.ReadFull(conn, rb)
	if err != nil {
		return r, fmt.Errorf("error reading response: %v", err)
	}
	if len(rb) < 1 {
		return r, fmt.Errorf("no response data from KDC %s", conn.RemoteAddr().String())
	}
	return rb, nil
}

// CheckKrbError checks if the response bytes from the KDC are a KRBError.
func CheckKrbError(b []byte) ([]byte, error) {
	var KRBErr messages.KRBError
	if err := KRBErr.Unmarshal(b); err == nil {
		return b, KRBErr
	}
	return b, nil
}

// TGStoHashcat converts a TGS to a hashcat format.
func TGStoHashcat(tgs messages.Ticket, username string) (string, error) {
	return fmt.Sprintf("$krb5tgs$%d$*%s$%s$%s*$%s$%s",
		tgs.EncPart.EType,
		username,
		tgs.Realm,
		strings.Join(tgs.SName.NameString[:], "/"),
		hex.EncodeToString(tgs.EncPart.Cipher[:16]),
		hex.EncodeToString(tgs.EncPart.Cipher[16:]),
	), nil
}

// ASRepToHashcat converts an AS-REP message to a hashcat format
func ASRepToHashcat(asrep messages.ASRep) (string, error) {
	return fmt.Sprintf("$krb5asrep$%d$%s@%s:%s$%s",
		asrep.EncPart.EType,
		asrep.CName.PrincipalNameString(),
		asrep.CRealm,
		hex.EncodeToString(asrep.EncPart.Cipher[:16]),
		hex.EncodeToString(asrep.EncPart.Cipher[16:])), nil
}

package kerberos

import (
	"encoding/binary"
	"io"
	"net"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

// TestSendTCPReadsSplitLengthHeader checks that sendTCP reads the whole
// 4-byte length prefix when the KDC sends it in more than one segment.
func TestSendTCPReadsSplitLengthHeader(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer func() {
		_ = listener.Close()
	}()

	reply := []byte("kerberos reply")
	done := make(chan error, 1)
	go func() {
		conn, err := listener.Accept()
		if err != nil {
			done <- err
			return
		}
		defer func() {
			_ = conn.Close()
		}()
		_ = conn.(*net.TCPConn).SetNoDelay(true)

		// Read the 4-byte request length and the request itself.
		header := make([]byte, 4)
		if _, err := io.ReadFull(conn, header); err != nil {
			done <- err
			return
		}
		request := make([]byte, binary.BigEndian.Uint32(header))
		if _, err := io.ReadFull(conn, request); err != nil {
			done <- err
			return
		}

		size := make([]byte, 4)
		binary.BigEndian.PutUint32(size, uint32(len(reply)))
		// Send the length prefix in two writes so the client sees a short read.
		if _, err := conn.Write(size[:2]); err != nil {
			done <- err
			return
		}
		time.Sleep(50 * time.Millisecond)
		if _, err := conn.Write(append(size[2:], reply...)); err != nil {
			done <- err
			return
		}
		done <- nil
	}()

	conn, err := net.DialTCP("tcp", nil, listener.Addr().(*net.TCPAddr))
	require.NoError(t, err)
	_ = conn.SetDeadline(time.Now().Add(5 * time.Second))

	got, err := sendTCP(conn, []byte("request"))
	require.NoError(t, err)
	require.Equal(t, reply, got)
	require.NoError(t, <-done)
}

// Package krbforge wraps mandiant/gopacket's Kerberos ticket forging primitives
// (golden / silver tickets) for use from nuclei javascript templates.
//
// Forging requires the krbtgt NT hash (golden) or a service-account hash
// (silver) - obtained from secretsdump / dcsync. Templates can chain this with
// the dcerpc lib to produce end-to-end attack chains entirely in nuclei.
package krbforge

import (
	"encoding/hex"
	"fmt"
	"path/filepath"
	"strings"

	gpkrb "github.com/projectdiscovery/goimpacket/pkg/kerberos"
	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

// TicketRequest mirrors gopacket's TicketConfig with json-friendly tags.
type TicketRequest struct {
	Username       string   `json:"username"`
	Domain         string   `json:"domain"`
	DomainSID      string   `json:"domain_sid"`
	NTHash         string   `json:"nthash,omitempty"`
	AESKey         string   `json:"aes_key,omitempty"`
	SPN            string   `json:"spn,omitempty"`
	UserID         uint32   `json:"user_id,omitempty"`
	PrimaryGroupID uint32   `json:"primary_group_id,omitempty"`
	Groups         []uint32 `json:"groups,omitempty"`
	ExtraSIDs      []string `json:"extra_sids,omitempty"`
	DurationHours  int      `json:"duration_hours,omitempty"`
	KVNO           int      `json:"kvno,omitempty"`

	// OutputFile is retained for compatibility and must be empty.
	// goimpacket always writes its default ccache file.
	OutputFile string `json:"output_file,omitempty"`
}

// Ticket is the forged ticket plus metadata.
type Ticket struct {
	HexTicket  string `json:"ticket_hex"`
	HexKey     string `json:"session_key_hex"`
	EncType    int32  `json:"enc_type"`
	OutputFile string `json:"output_file,omitempty"`
}

// CreateGoldenTicket forges a TGT for the supplied user against the given
// realm using the krbtgt NT hash (or AES key). It returns the ASN.1-encoded
// ticket and the session key. goimpacket writes <username>.ccache in the current
// directory, replacing slashes in the username with dots. The destination must
// be inside the template directory unless -allow-local-file-access is enabled.
// req.OutputFile must be empty; custom paths and in-memory generation are unsupported.
//
// @example
// ```javascript
// const krb = require('nuclei/krbforge');
//
//	const t = krb.CreateGoldenTicket({
//	  username: 'Administrator',
//	  domain:   'acme.local',
//	  domain_sid: 'S-1-5-21-1004336348-1177238915-682003330',
//	  nthash:   '31d6cfe0d16ae931b73c59d7e0c089c0',
//	});
//
// log(t.ticket_hex);
// ```
func CreateGoldenTicket(call goja.FunctionCall, vm *goja.Runtime) goja.Value {
	nj := utils.NewNucleiJS(vm)
	nj.ObjectSig = "CreateGoldenTicket(request)"

	req, err := exportTicketRequest(vm, call.Argument(0))
	if err != nil {
		nj.ThrowError(err)
		return goja.Undefined()
	}

	ticket, err := createGoldenTicket(nj.ExecutionId(), req)
	if err != nil {
		nj.ThrowError(err)
		return goja.Undefined()
	}

	return vm.ToValue(ticket)
}

func createGoldenTicket(executionID string, req TicketRequest) (*Ticket, error) {
	cfg, err := buildConfig(executionID, req, "")
	if err != nil {
		return nil, err
	}

	return createTicket(cfg)
}

// CreateSilverTicket forges a service ticket (TGS) for the supplied SPN. The
// hash supplied must belong to the service account that owns the SPN (e.g.
// the machine account NT hash for cifs/host SPNs).
// File output follows CreateGoldenTicket. req.OutputFile and outputFile must
// be empty; custom paths and in-memory generation are unsupported.
//
// @example
// ```javascript
// const krb = require('nuclei/krbforge');
//
//	const t = krb.CreateSilverTicket({
//	  username: 'Administrator',
//	  domain:   'acme.local',
//	  domain_sid: 'S-1-5-21-1004336348-1177238915-682003330',
//	  nthash:   '31d6cfe0d16ae931b73c59d7e0c089c0',
//	  spn:      'cifs/server01.acme.local',
//	});
//
// log(t.output_file);
// ```
func CreateSilverTicket(call goja.FunctionCall, vm *goja.Runtime) goja.Value {
	nj := utils.NewNucleiJS(vm)
	nj.ObjectSig = "CreateSilverTicket(request, outputFile)"

	req, err := exportTicketRequest(vm, call.Argument(0))
	if err != nil {
		nj.ThrowError(err)
		return goja.Undefined()
	}

	outputFile, err := exportOutputFile(call.Argument(1))
	if err != nil {
		nj.ThrowError(err)
		return goja.Undefined()
	}

	ticket, err := createSilverTicket(nj.ExecutionId(), req, outputFile)
	if err != nil {
		nj.ThrowError(err)
		return goja.Undefined()
	}

	return vm.ToValue(ticket)
}

func createSilverTicket(executionID string, req TicketRequest, outputFile string) (*Ticket, error) {
	if req.SPN == "" {
		return nil, fmt.Errorf("spn is required for silver ticket")
	}

	cfg, err := buildConfig(executionID, req, outputFile)
	if err != nil {
		return nil, err
	}

	return createTicket(cfg)
}

func createTicket(cfg *gpkrb.TicketConfig) (*Ticket, error) {
	res, err := gpkrb.CreateTicket(cfg)
	if err != nil {
		return nil, err
	}

	return &Ticket{
		HexTicket:  hex.EncodeToString(res.Ticket),
		HexKey:     hex.EncodeToString(res.SessionKey),
		EncType:    res.EncType,
		OutputFile: res.Filename,
	}, nil
}

func buildConfig(executionID string, req TicketRequest, outputFile string) (*gpkrb.TicketConfig, error) {
	if outputFile != "" || req.OutputFile != "" {
		return nil, fmt.Errorf("goimpacket writes <username>.ccache in the current directory: custom output paths and in-memory ticket generation are not supported; leave outputFile empty")
	}

	// Match goimpacket's destination before it performs the file write.
	filename := strings.ReplaceAll(req.Username, "/", ".") + ".ccache"
	destination, err := filepath.Abs(filename)
	if err != nil {
		return nil, fmt.Errorf("resolve ccache destination %q: %w", filename, err)
	}
	if _, err := protocolstate.NormalizePathWithExecutionId(executionID, destination); err != nil {
		return nil, fmt.Errorf("validate ccache destination: %w", err)
	}

	return &gpkrb.TicketConfig{
		Username:       req.Username,
		Domain:         req.Domain,
		DomainSID:      req.DomainSID,
		NTHash:         req.NTHash,
		AESKey:         req.AESKey,
		SPN:            req.SPN,
		UserID:         req.UserID,
		PrimaryGroupID: req.PrimaryGroupID,
		Groups:         req.Groups,
		ExtraSIDs:      req.ExtraSIDs,
		Duration:       req.DurationHours,
		KVNO:           req.KVNO,
	}, nil
}

func exportTicketRequest(vm *goja.Runtime, value goja.Value) (TicketRequest, error) {
	var req TicketRequest
	if err := vm.ExportTo(value, &req); err != nil {
		return req, fmt.Errorf("invalid TicketRequest: %w", err)
	}
	return req, nil
}

func exportOutputFile(value goja.Value) (string, error) {
	if goja.IsUndefined(value) || goja.IsNull(value) {
		return "", nil
	}
	outputFile, ok := value.Export().(string)
	if !ok {
		return "", fmt.Errorf("outputFile must be a string")
	}
	return outputFile, nil
}

package krbforge

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

func TestCreateTicketDefaultOutput(t *testing.T) {
	for _, golden := range []bool{true, false} {
		for _, location := range []string{"sandbox", "outside denied", "outside allowed"} {
			t.Run(fmt.Sprintf("golden=%v/%s", golden, location), func(t *testing.T) {
				templatesDir := setTemplateDir(t)
				cwd := templatesDir
				if location != "sandbox" {
					cwd = t.TempDir()
				}
				t.Chdir(cwd)
				executionID := t.Name()
				setLocalFileAccess(executionID, location == "outside allowed")

				req := validTicketRequest()
				// goimpacket replaces slashes in SPN-style usernames with dots.
				req.Username = "service/http"
				var ticket *Ticket
				var err error
				if golden {
					req.SPN = ""
					ticket, err = createGoldenTicket(executionID, req)
				} else {
					ticket, err = createSilverTicket(executionID, req, "")
				}
				filename := "service.http.ccache"
				if location == "outside denied" {
					require.ErrorContains(t, err, "outside nuclei-template directory")
					require.Nil(t, ticket)
					_, err = os.Stat(filepath.Join(cwd, filename))
					require.ErrorIs(t, err, os.ErrNotExist)
					return
				}

				require.NoError(t, err)
				require.Equal(t, filename, ticket.OutputFile)
				require.NotEmpty(t, ticket.HexTicket)
				require.NotEmpty(t, ticket.HexKey)
				body, err := os.ReadFile(filepath.Join(cwd, ticket.OutputFile))
				require.NoError(t, err)
				require.NotEmpty(t, body)
			})
		}
	}
}

func TestCreateTicketRejectsUnsupportedOutput(t *testing.T) {
	cwd := setTemplateDir(t)
	t.Chdir(cwd)
	executionID := t.Name()
	setLocalFileAccess(executionID, true)

	for _, output := range []string{"-", "custom.ccache", filepath.Join(cwd, "custom.ccache")} {
		for _, method := range []string{"golden request", "silver request", "silver argument"} {
			t.Run(method+"/"+output, func(t *testing.T) {
				req := validTicketRequest()
				var ticket *Ticket
				var err error
				switch method {
				case "golden request":
					req.OutputFile = output
					ticket, err = createGoldenTicket(executionID, req)
				case "silver request":
					req.OutputFile = output
					ticket, err = createSilverTicket(executionID, req, "")
				case "silver argument":
					ticket, err = createSilverTicket(executionID, req, output)
				}
				require.ErrorContains(t, err, "custom output paths and in-memory ticket generation are not supported")
				require.Nil(t, ticket)
				files, err := os.ReadDir(cwd)
				require.NoError(t, err)
				require.Empty(t, files)
			})
		}
	}
}

func TestCreateTicketReportsWriteFailure(t *testing.T) {
