type (
	// Client is a client for ldap protocol in nuclei
	// @example
	// ```javascript
	// const ldap = require('nuclei/ldap');
	// // here ldap.example.com is the ldap server and acme.com is the realm
	// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
	// ```
	// @example
	// ```javascript
	// const ldap = require('nuclei/ldap');
	// const cfg = new ldap.Config();
	// cfg.Timeout = 10;
	// cfg.ServerName = 'ldap.internal.acme.com';
	// // optional config can be passed as third argument
	// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com', cfg);
	// ```
	Client struct {
		Host   string // Hostname
		Port   int    // Port
		Realm  string // Realm
		BaseDN string // BaseDN (generated from Realm)

		// unexported
		nj   *utils.NucleiJS // nuclei js utils
		conn *ldap.Conn
		cfg  Config
	}
)

type (
	// Config is extra configuration for the ldap client
	// @example
	// ```javascript
	// const ldap = require('nuclei/ldap');
	// const cfg = new ldap.Config();
	// cfg.Timeout = 10;
	// cfg.ServerName = 'ldap.internal.acme.com';
	// cfg.Upgrade = true; // upgrade to tls
	// ```
	Config struct {
		// Timeout is the timeout for the ldap client in seconds
		Timeout    int
		ServerName string // default to host (when using tls)
		Upgrade    bool   // when true first connects to non-tls and then upgrades to tls
	}
)

// Constructor for creating a new ldap client
// The following schemas are supported for url: ldap://, ldaps://, ldapi://,
// and cldap:// (RFC1798, deprecated but used by Active Directory).
// ldaps uses TLS/SSL, ldapi uses a Unix domain socket, and cldap uses connectionless LDAP.
// Constructor: constructor(public ldapUrl: string, public realm: string, public config?: Config)
func NewClient(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	// setup nucleijs utils
	c := &Client{nj: utils.NewNucleiJS(runtime)}
	c.nj.ObjectSig = "Client(ldapUrl,Realm,{Config})" // will be included in error messages

	// get arguments (type assertion is efficient than reflection)
	ldapUrl, _ := c.nj.GetArg(call.Arguments, 0).(string)
	realm, _ := c.nj.GetArg(call.Arguments, 1).(string)
	c.cfg = utils.GetStructTypeSafe[Config](c.nj, call.Arguments, 2, Config{})
	c.Realm = realm
	c.BaseDN = fmt.Sprintf("dc=%s", strings.Join(strings.Split(realm, "."), ",dc="))

	// validate arguments
	c.nj.Require(ldapUrl != "", "ldap url cannot be empty")
	c.nj.Require(realm != "", "realm cannot be empty")

	u, err := url.Parse(ldapUrl)
	c.nj.HandleError(err, "invalid ldap url supported schemas are ldap://, ldaps://, ldapi://, and cldap://")
	if u.Scheme == "" {
		// default to ldap
		u.Scheme = "ldap"
	}

	executionId := c.nj.ExecutionId()
	dialers := protocolstate.GetDialersWithId(executionId)
	if dialers == nil {
		gologger.Error().Msgf("dialers with executionId %s not found", executionId)
		return nil
	}

	dialCtx := c.nj.Context()
	var conn net.Conn
	if u.Scheme == "ldapi" {
		// the ldapi unix domain socket is not covered by the IP-based network
		// policy directly, so gate it on whether loopback access is permitted
		// (blocked when local network access is restricted via -lna).
		const ldapiPolicyHost = "127.0.0.1"

		c.nj.Require(protocolstate.IsHostAllowed(executionId, ldapiPolicyHost), protocolstate.ErrHostDenied.Msgf(ldapiPolicyHost).Error())
		if u.Path == "" || u.Path == "/" {
			u.Path = "/var/run/slapd/ldapi"
		}
		conn, err = dialers.Fastdialer.Dial(dialCtx, "unix", u.Path)
		c.nj.HandleError(err, "failed to connect to ldap server")
	} else {
		switch u.Scheme {
		case "cldap", "ldap", "ldaps":
			host, port := u.Hostname(), u.Port()
			c.nj.Require(host != "", "ldap host cannot be empty")
			c.nj.Require(protocolstate.IsHostAllowed(executionId, host), protocolstate.ErrHostDenied.Msgf(host).Error())

			switch u.Scheme {
			case "cldap":
				if port == "" {
					port = ldap.DefaultLdapPort
				}
				conn, err = dialers.Fastdialer.Dial(dialCtx, "udp", net.JoinHostPort(host, port))
			case "ldap":
				if port == "" {
					port = ldap.DefaultLdapPort
				}
				conn, err = dialers.Fastdialer.Dial(dialCtx, "tcp", net.JoinHostPort(host, port))
			case "ldaps":
				if port == "" {
					port = ldap.DefaultLdapsPort
				}
				serverName := host
				if c.cfg.ServerName != "" {
					serverName = c.cfg.ServerName
				}
				conn, err = dialers.Fastdialer.DialTLSWithConfig(dialCtx, "tcp", net.JoinHostPort(host, port),
					&tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS10, ServerName: serverName})
			}
		default:
			err = fmt.Errorf("unsupported ldap url schema %v", u.Scheme)
		}
		c.nj.HandleError(err, "failed to connect to ldap server")
	}
	// go-ldap waits for a reply with no timeout, and an interrupt cannot stop the runtime
	// inside that read: a server that accepts and never answers would keep the goroutine,
	// and everything the abandoned runtime references, alive for the life of the process.
	context.AfterFunc(dialCtx, func() { _ = conn.Close() })
	c.conn = ldap.NewConn(conn, u.Scheme == "ldaps")
	if u.Scheme != "ldaps" && c.cfg.Upgrade {
		serverName := u.Hostname()
		if c.cfg.ServerName != "" {
			serverName = c.cfg.ServerName
		}
		if err := c.conn.StartTLS(&tls.Config{InsecureSkipVerify: true, ServerName: serverName}); err != nil {
			c.nj.HandleError(err, "failed to upgrade to tls")
		}
	} else {
		c.conn.Start()
	}

	return utils.LinkConstructor(call, runtime, c)
}

// Authenticate authenticates with the ldap server using the given username and password
// performs NTLMBind first and then Bind/UnauthenticatedBind if NTLMBind fails
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// client.Authenticate('user', 'password');
// ```
func (c *Client) Authenticate(username, password string) bool {
	c.nj.Require(c.conn != nil, "no existing connection")
	if c.BaseDN == "" {
		c.BaseDN = fmt.Sprintf("dc=%s", strings.Join(strings.Split(c.Realm, "."), ",dc="))
	}
	if err := c.conn.NTLMBind(c.Realm, username, password); err == nil {
		// if bind with NTLMBind(), there is nothing
		// else to do, you are authenticated
		return true
	}

	var err error
	switch password {
	case "":
		if err = c.conn.UnauthenticatedBind(username); err != nil {
			c.nj.ThrowError(err)
		}
	default:
		if err = c.conn.Bind(username, password); err != nil {
			c.nj.ThrowError(err)
		}
	}
	return err == nil
}

// AuthenticateWithNTLMHash authenticates with the ldap server using the given username and NTLM hash
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// client.AuthenticateWithNTLMHash('pdtm', 'hash');
// ```
func (c *Client) AuthenticateWithNTLMHash(username, hash string) bool {
	c.nj.Require(c.conn != nil, "no existing connection")
	if c.BaseDN == "" {
		c.BaseDN = fmt.Sprintf("dc=%s", strings.Join(strings.Split(c.Realm, "."), ",dc="))
	}
	var err error
	if err = c.conn.NTLMBindWithHash(c.Realm, username, hash); err != nil {
		c.nj.ThrowError(err)
	}
	return err == nil
}

// Search accepts whatever filter and returns a list of maps having provided attributes
// as keys and associated values mirroring the ones returned by ldap
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// const results = client.Search('(objectClass=*)', 'cn', 'mail');
// ```
func (c *Client) Search(filter string, attributes ...string) SearchResult {
	c.nj.Require(c.conn != nil, "no existing connection")
	c.nj.Require(c.BaseDN != "", "base dn cannot be empty")
	c.nj.Require(len(attributes) > 0, "attributes cannot be empty")

	res, err := c.conn.Search(
		ldap.NewSearchRequest(
			"",
			ldap.ScopeWholeSubtree,
			ldap.NeverDerefAliases,
			0, 0, false,
			filter,
			attributes,
			nil,
		),
	)
	c.nj.HandleError(err, "ldap search request failed")
	return *getSearchResult(res)
}

// AdvancedSearch accepts all values of search request type and return Ldap Entry
// its up to user to handle the response
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// const results = client.AdvancedSearch(ldap.ScopeWholeSubtree, ldap.NeverDerefAliases, 0, 0, false, '(objectClass=*)', ['cn', 'mail'], []);
// ```
func (c *Client) AdvancedSearch(
	Scope, DerefAliases, SizeLimit, TimeLimit int,
	TypesOnly bool,
	Filter string,
	Attributes []string,
	Controls []ldap.Control) SearchResult {
	c.nj.Require(c.conn != nil, "no existing connection")
	if c.BaseDN == "" {
		c.BaseDN = fmt.Sprintf("dc=%s", strings.Join(strings.Split(c.Realm, "."), ",dc="))
	}
	req := ldap.NewSearchRequest(c.BaseDN, Scope, DerefAliases, SizeLimit, TimeLimit, TypesOnly, Filter, Attributes, Controls)
	res, err := c.conn.Search(req)
	c.nj.HandleError(err, "ldap search request failed")
	c.nj.Require(res != nil, "ldap search request failed got nil response")
	return *getSearchResult(res)
}

type (
	// Metadata is the metadata for ldap server.
	// this is returned by CollectMetadata method
	Metadata struct {
		BaseDN                        string
		Domain                        string
		DefaultNamingContext          string
		DomainFunctionality           string
		ForestFunctionality           string
		DomainControllerFunctionality string
		DnsHostName                   string
	}
)

// CollectLdapMetadata collects metadata from ldap server.
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// const metadata = client.CollectMetadata();
// log(to_json(metadata));
// ```
func (c *Client) CollectMetadata() Metadata {
	c.nj.Require(c.conn != nil, "no existing connection")
	var metadata Metadata
	metadata.Domain = c.Realm
	if c.BaseDN == "" {
		c.BaseDN = fmt.Sprintf("dc=%s", strings.Join(strings.Split(c.Realm, "."), ",dc="))
	}
	metadata.BaseDN = c.BaseDN

	// Use scope as Base since Root DSE doesn't have subentries
	srMetadata := ldap.NewSearchRequest(
		"",
		ldap.ScopeBaseObject,
		ldap.NeverDerefAliases,
		0, 0, false,
		"(objectClass=*)",
		[]string{
			"defaultNamingContext",
			"domainFunctionality",
			"forestFunctionality",
			"domainControllerFunctionality",
			"dnsHostName",
		},
		nil)
	resMetadata, err := c.conn.Search(srMetadata)
	c.nj.HandleError(err, "ldap search request failed")

	for _, entry := range resMetadata.Entries {
		for _, attr := range entry.Attributes {
			value := entry.GetAttributeValue(attr.Name)
			switch attr.Name {
			case "defaultNamingContext":
				metadata.DefaultNamingContext = value
			case "domainFunctionality":
				metadata.DomainFunctionality = value
			case "forestFunctionality":
				metadata.ForestFunctionality = value
			case "domainControllerFunctionality":
				metadata.DomainControllerFunctionality = value
			case "dnsHostName":
				metadata.DnsHostName = value
			}
		}
	}
	return metadata
}

// GetVersion returns the LDAP versions being used by the server
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// const versions = client.GetVersion();
// log(versions);
// ```
func (c *Client) GetVersion() []string {
	c.nj.Require(c.conn != nil, "no existing connection")

	// Query root DSE for supported LDAP versions
	sr := ldap.NewSearchRequest(
		"",
		ldap.ScopeBaseObject,
		ldap.NeverDerefAliases,
		0, 0, false,
		"(objectClass=*)",
		[]string{"supportedLDAPVersion"},
		nil)

	res, err := c.conn.Search(sr)
	c.nj.HandleError(err, "failed to get LDAP version")

	if len(res.Entries) > 0 {
		return res.Entries[0].GetAttributeValues("supportedLDAPVersion")
	}

	return []string{"unknown"}
}

// close the ldap connection
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
// client.Close();
// ```
func (c *Client) Close() {
	_ = c.conn.Close()
}

package ldap

import (
	"context"
	"net"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

func TestNewClientDeniesRestrictedLocalTCPBeforeDial(t *testing.T) {
	_, err := newLDAPClientForTest(t, &types.Options{
		RestrictLocalNetworkAccess: true,
	}, "ldap://127.0.0.1")

	requireNetworkPolicyError(t, err, "127.0.0.1")
	requireRejectedBeforeDial(t, err)
}

func TestNewClientDeniesLDAPIAsLocalNetworkAccess(t *testing.T) {
	_, err := newLDAPClientForTest(t, &types.Options{
		RestrictLocalNetworkAccess: true,
	}, "ldapi:///var/run/slapd/ldapi")

	requireNetworkPolicyError(t, err, "127.0.0.1")
	requireRejectedBeforeDial(t, err)
}

func requireRejectedBeforeDial(t *testing.T, err error) {
	t.Helper()

	if strings.Contains(err.Error(), "failed to connect to ldap server") {
		t.Fatalf("ldap target should be rejected by policy before dialing, got %q", err)
	}
}

func TestNewClientAllowsTCPWhenNetworkPolicyAllows(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		_ = listener.Close()
	}()

	accepted := make(chan net.Conn, 1)
	go func() {
		conn, err := listener.Accept()
		if err == nil {
			accepted <- conn
			return
		}
		accepted <- nil
	}()

	client, err := newLDAPClientForTest(t, &types.Options{}, "ldap://"+listener.Addr().String())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = client.conn.Close()
	})

	select {
	case conn := <-accepted:
		if conn == nil {
			t.Fatal("listener closed before accepting ldap connection")
		}
		_ = conn.Close()
	case <-time.After(time.Second):
		t.Fatal("ldap constructor did not connect to allowed listener")
	}
}

// A server that accepts and never answers used to keep Authenticate, and the runtime
// abandoned around it, blocked for the life of the process.
func TestAuthenticateReturnsWhenTheContextIsDone(t *testing.T) {
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = listener.Close()
	})
	go func() {
		var held []net.Conn
		for {
			conn, err := listener.Accept()
			if err != nil {
				for _, c := range held {
					_ = c.Close()
				}
				return
			}
			held = append(held, conn)
		}
	}()

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	client, err := newLDAPClientWithContextForTest(t, ctx, &types.Options{}, "ldap://"+listener.Addr().String())
	if err != nil {
		t.Fatal(err)
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		defer func() {
			_ = recover() // the failed bind is thrown to the runtime
		}()
		client.Authenticate("user", "")
	}()

	select {
	case <-done:
		t.Fatal("Authenticate returned before the server answered or the context was done")
	case <-time.After(200 * time.Millisecond):
	}

	cancel()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Authenticate still blocked after the context was done")
	}
}

func newLDAPClientForTest(t *testing.T, options *types.Options, ldapURL string) (*Client, error) {
	t.Helper()
	return newLDAPClientWithContextForTest(t, context.Background(), options, ldapURL)
}

func newLDAPClientWithContextForTest(t *testing.T, ctx context.Context, options *types.Options, ldapURL string) (*Client, error) {
	t.Helper()

	executionID := "ldap-" + strings.NewReplacer("/", "-", " ", "-").Replace(t.Name())
	options.ExecutionId = executionID
	if err := protocolstate.Init(options); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		protocolstate.Close(executionID)
	})

	runtime := goja.New()
	runtime.SetContextValue("executionId", executionID)
	runtime.SetContextValue("ctx", ctx)

	obj, err := runtime.New(runtime.ToValue(NewClient), runtime.ToValue(ldapURL), runtime.ToValue("corp.internal"))
	if err != nil {
		return nil, err
	}

	client, ok := obj.Export().(*Client)
	if !ok {
		t.Fatalf("expected *Client export, got %T", obj.Export())
	}
	return client, nil
}

func requireNetworkPolicyError(t *testing.T, err error, target string) {
	t.Helper()

	if err == nil {
		t.Fatal("expected network-policy denial, got nil")
	}
	if !strings.Contains(err.Error(), "network policy") || !strings.Contains(err.Error(), target) {
		t.Fatalf("expected network-policy denial for %q, got %q", target, err)
	}
}

package ldap

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/go-ldap/ldap/v3"
)

type (
	// SearchResult contains search result of any / all ldap search request
	// @example
	// ```javascript
	// const ldap = require('nuclei/ldap');
	// const client = new ldap.Client('ldap://ldap.example.com', 'acme.com');
	// const results = client.Search('(objectClass=*)', 'cn', 'mail');
	// ```
	SearchResult struct {
		// Referrals contains list of referrals
		Referrals []string `json:"referrals"`
		// Controls contains list of controls
		Controls []string `json:"controls"`
		// Entries contains list of entries
		Entries []LdapEntry `json:"entries"`
	}

	// LdapEntry represents a single LDAP entry
	LdapEntry struct {
		// DN contains distinguished name
		DN string `json:"dn"`
		// Attributes contains list of attributes
		Attributes LdapAttributes `json:"attributes"`
	}

	// LdapAttributes represents all LDAP attributes of a particular
	// ldap entry
	LdapAttributes struct {
		// CurrentTime contains current time
		CurrentTime []string `json:"currentTime,omitempty"`
		// SubschemaSubentry contains subschema subentry
		SubschemaSubentry []string `json:"subschemaSubentry,omitempty"`
		// DsServiceName contains ds service name
		DsServiceName []string `json:"dsServiceName,omitempty"`
		// NamingContexts contains naming contexts
		NamingContexts []string `json:"namingContexts,omitempty"`
		// DefaultNamingContext contains default naming context
		DefaultNamingContext []string `json:"defaultNamingContext,omitempty"`
		// SchemaNamingContext contains schema naming context
		SchemaNamingContext []string `json:"schemaNamingContext,omitempty"`
		// ConfigurationNamingContext contains configuration naming context
		ConfigurationNamingContext []string `json:"configurationNamingContext,omitempty"`
		// RootDomainNamingContext contains root domain naming context
		RootDomainNamingContext []string `json:"rootDomainNamingContext,omitempty"`
		// SupportedLDAPVersion contains supported LDAP version
		SupportedLDAPVersion []string `json:"supportedLDAPVersion,omitempty"`
		// HighestCommittedUSN contains highest committed USN
		HighestCommittedUSN []string `json:"highestCommittedUSN,omitempty"`
		// SupportedSASLMechanisms contains supported SASL mechanisms
		SupportedSASLMechanisms []string `json:"supportedSASLMechanisms,omitempty"`
		// DnsHostName contains DNS host name
		DnsHostName []string `json:"dnsHostName,omitempty"`
		// LdapServiceName contains LDAP service name
		LdapServiceName []string `json:"ldapServiceName,omitempty"`
		// ServerName contains server name
		ServerName []string `json:"serverName,omitempty"`
		// IsSynchronized contains is synchronized
		IsSynchronized []string `json:"isSynchronized,omitempty"`
		// IsGlobalCatalogReady contains is global catalog ready
		IsGlobalCatalogReady []string `json:"isGlobalCatalogReady,omitempty"`
		// DomainFunctionality contains domain functionality
		DomainFunctionality []string `json:"domainFunctionality,omitempty"`
		// ForestFunctionality contains forest functionality
		ForestFunctionality []string `json:"forestFunctionality,omitempty"`
		// DomainControllerFunctionality contains domain controller functionality
		DomainControllerFunctionality []string `json:"domainControllerFunctionality,omitempty"`
		// DistinguishedName contains the distinguished name
		DistinguishedName []string `json:"distinguishedName,omitempty"`
		// SAMAccountName contains the SAM account name
		SAMAccountName []string `json:"sAMAccountName,omitempty"`
		// PWDLastSet contains the password last set time
		PWDLastSet []string `json:"pwdLastSet,omitempty"`
		// LastLogon contains the last logon time
		LastLogon []string `json:"lastLogon,omitempty"`
		// MemberOf contains the groups the entry is a member of
		MemberOf []string `json:"memberOf,omitempty"`
		// ServicePrincipalName contains the service principal names
		ServicePrincipalName []string `json:"servicePrincipalName,omitempty"`
		// Extra contains other extra fields which might be present
		Extra map[string]any `json:"extra,omitempty"`
	}
)

// getSearchResult converts a ldap.SearchResult to a SearchResult
func getSearchResult(sr *ldap.SearchResult) *SearchResult {
	t := &SearchResult{
		Referrals: []string{},
		Controls:  []string{},
		Entries:   []LdapEntry{},
	}
	// add referrals
	t.Referrals = append(t.Referrals, sr.Referrals...)
	// add controls
	for _, ctrl := range sr.Controls {
		t.Controls = append(t.Controls, ctrl.String())
	}
	// add entries
	for _, entry := range sr.Entries {
		t.Entries = append(t.Entries, parseLdapEntry(entry))
	}
	return t
}

func parseLdapEntry(entry *ldap.Entry) LdapEntry {
	e := LdapEntry{
		DN: entry.DN,
	}
	attrs := LdapAttributes{
		Extra: make(map[string]any),
	}
	for _, attr := range entry.Attributes {
		switch attr.Name {
		case "currentTime":
			attrs.CurrentTime = decodeTimestamps(attr.Values)
		case "subschemaSubentry":
			attrs.SubschemaSubentry = attr.Values
		case "dsServiceName":
			attrs.DsServiceName = attr.Values
		case "namingContexts":
			attrs.NamingContexts = attr.Values
		case "defaultNamingContext":
			attrs.DefaultNamingContext = attr.Values
		case "schemaNamingContext":
			attrs.SchemaNamingContext = attr.Values
		case "configurationNamingContext":
			attrs.ConfigurationNamingContext = attr.Values
		case "rootDomainNamingContext":
			attrs.RootDomainNamingContext = attr.Values
		case "supportedLDAPVersion":
			attrs.SupportedLDAPVersion = attr.Values
		case "highestCommittedUSN":
			attrs.HighestCommittedUSN = attr.Values
		case "supportedSASLMechanisms":
			attrs.SupportedSASLMechanisms = attr.Values
		case "dnsHostName":
			attrs.DnsHostName = attr.Values
		case "ldapServiceName":
			attrs.LdapServiceName = attr.Values
		case "serverName":
			attrs.ServerName = attr.Values
		case "isSynchronized":
			attrs.IsSynchronized = attr.Values
		case "isGlobalCatalogReady":
			attrs.IsGlobalCatalogReady = attr.Values
		case "domainFunctionality":
			attrs.DomainFunctionality = attr.Values
		case "forestFunctionality":
			attrs.ForestFunctionality = attr.Values
		case "domainControllerFunctionality":
			attrs.DomainControllerFunctionality = attr.Values
		case "distinguishedName":
			attrs.DistinguishedName = attr.Values
		case "sAMAccountName":
			attrs.SAMAccountName = attr.Values
		case "pwdLastSet":
			attrs.PWDLastSet = decodeTimestamps(attr.Values)
		case "lastLogon":
			attrs.LastLogon = decodeTimestamps(attr.Values)
		case "memberOf":
			attrs.MemberOf = attr.Values
		case "servicePrincipalName":
			attrs.ServicePrincipalName = attr.Values
		default:
			attrs.Extra[attr.Name] = attr.Values
		}
	}
	e.Attributes = attrs
	return e
}

// decodeTimestamps  decodes multiple timestamps
func decodeTimestamps(timestamps []string) []string {
	res := []string{}
	for _, timestamp := range timestamps {
		res = append(res, DecodeADTimestamp(timestamp))
	}
	return res
}

// DecodeSID decodes a SID string
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const sid = ldap.DecodeSID('S-1-5-21-3623811015-3361044348-30300820-1013');
// log(sid);
// ```
func DecodeSID(s string) string {
	b := []byte(s)
	revisionLvl := int(b[0])
	subAuthorityCount := int(b[1]) & 0xFF

	var authority int
	for i := 2; i <= 7; i++ {
		authority = authority | int(b[i])<<(8*(5-(i-2)))
	}

	var size = 4
	var offset = 8
	var subAuthorities []int
	for i := 0; i < subAuthorityCount; i++ {
		var subAuthority int
		for k := 0; k < size; k++ {
			subAuthority = subAuthority | (int(b[offset+k])&0xFF)<<(8*k)
		}
		subAuthorities = append(subAuthorities, subAuthority)
		offset += size
	}

	var builder strings.Builder
	builder.WriteString("S-")
	fmt.Fprintf(&builder, "%d-", revisionLvl)
	fmt.Fprintf(&builder, "%d", authority)
	for _, v := range subAuthorities {
		fmt.Fprintf(&builder, "-%d", v)
	}
	return builder.String()
}

// DecodeADTimestamp decodes an Active Directory timestamp
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const timestamp = ldap.DecodeADTimestamp('132036744000000000');
// log(timestamp);
// ```
func DecodeADTimestamp(timestamp string) string {
	adtime, _ := strconv.ParseInt(timestamp, 10, 64)
	if (adtime == 9223372036854775807) || (adtime == 0) {
		return "Not Set"
	}
	unixtime_int64 := adtime/(10*1000*1000) - 11644473600
	unixtime := time.Unix(unixtime_int64, 0)
	return unixtime.Format("2006-01-02 3:4:5 pm")
}

// DecodeZuluTimestamp decodes a Zulu timestamp
// @example
// ```javascript
// const ldap = require('nuclei/ldap');
// const timestamp = ldap.DecodeZuluTimestamp('2021-08-25T10:00:00Z');
// log(timestamp);
// ```
func DecodeZuluTimestamp(timestamp string) string {
	zulu, err := time.Parse(time.RFC3339, timestamp)
	if err != nil {
		return ""
	}
	return zulu.Format("2006-01-02 3:4:5 pm")
}

package mqtt

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"strconv"
	"sync"
	"time"

	libnet "github.com/projectdiscovery/nuclei/v3/pkg/js/libs/net"
)

var (
	defaultTimeout = 10 * time.Second
)

const (
	maxSubscribedMessages = 1000
	maxSubscribedBytes    = 10 * 1024 * 1024 // 10MB
)

type (
	// Message represents an MQTT published message.
	// @example
	// ```javascript
	// const mqtt = require('nuclei/mqtt');
	// const client = new mqtt.Client();
	// client.Connect('broker.hivemq.com', 1883);
	// const msgs = client.Subscribe('test/topic', 2);
	// log(msgs[0].Topic, msgs[0].Payload);
	// ```
	Message struct {
		Topic   string `json:"topic"`
		Payload string `json:"payload"`
		QoS     int    `json:"qos"`
		Retain  bool   `json:"retain"`
	}

	// ConnectOptions contains connection options for an MQTT broker.
	// @example
	// ```javascript
	// const mqtt = require('nuclei/mqtt');
	// const opts = new mqtt.ConnectOptions();
	// opts.Username = 'admin';
	// opts.Password = 'admin';
	// ```
	ConnectOptions struct {
		Username           string `json:"username,omitempty"`
		Password           string `json:"password,omitempty"`
		ClientID           string `json:"client_id,omitempty"`
		CleanSession       *bool  `json:"clean_session,omitempty"`
		KeepAlive          int    `json:"keep_alive,omitempty"`
		TLS                bool   `json:"tls,omitempty"`
		InsecureSkipVerify *bool  `json:"insecure_skip_verify,omitempty"`
		Timeout            int    `json:"timeout,omitempty"`
	}

	// ConnectResult is the response returned by an MQTT connection attempt.
	// @example
	// ```javascript
	// const mqtt = require('nuclei/mqtt');
	// const client = new mqtt.Client();
	// const res = client.Connect('acme.com', 1883);
	// log(res.Success, res.ReturnCode, res.Reason);
	// ```
	ConnectResult struct {
		Success        bool   `json:"success"`
		ReturnCode     int    `json:"return_code"`
		Reason         string `json:"reason"`
		SessionPresent bool   `json:"session_present"`
	}

	// Client is an MQTT client for testing MQTT broker misconfigurations and authentication.
	// @example
	// ```javascript
	// const mqtt = require('nuclei/mqtt');
	// const client = new mqtt.Client();
	// const res = client.Connect('acme.com', 1883);
	// if (res.Success) {
	//     const msgs = client.Subscribe('#', 2);
	//     client.Publish('nuclei/probe', 'test');
	// }
	// client.Close();
	// ```
	Client struct {
		conn     net.Conn
		packetID uint16
		mu       sync.Mutex
		timeout  time.Duration
	}
)

// dial opens a network connection to host:port respecting protocolstate policy and context.
func dial(ctx context.Context, host string, port int, useTLS bool, insecureSkipVerify bool, timeout time.Duration) (net.Conn, error) {
	if host == "" || port <= 0 {
		return nil, fmt.Errorf("invalid host or port")
	}

	addr := net.JoinHostPort(host, strconv.Itoa(port))
	conn, err := libnet.Dial(ctx, "tcp", addr)
	if err != nil {
		return nil, err
	}

	_ = conn.SetDeadline(time.Now().Add(timeout))

	if useTLS {
		tlsConn := tls.Client(conn, &tls.Config{
			InsecureSkipVerify: insecureSkipVerify,
			MinVersion:         tls.VersionTLS12,
			ServerName:         host,
		})
		if err := tlsConn.HandshakeContext(ctx); err != nil {
			_ = conn.Close()
			return nil, fmt.Errorf("TLS handshake failed: %w", err)
		}
		conn = tlsConn
	}

	_ = conn.SetDeadline(time.Now().Add(timeout))
	return conn, nil
}

// IsMQTT checks whether the target host:port is running an MQTT broker.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const isMqtt = mqtt.IsMQTT('acme.com', 1883);
// log(isMqtt);
// ```
func IsMQTT(ctx context.Context, host string, port int) (bool, error) {
	conn, err := dial(ctx, host, port, false, true, defaultTimeout)
	if err != nil {
		return false, err
	}
	defer func() { _ = conn.Close() }()

	pkt, err := buildConnectPacket("nuclei-probe", "", "", true, 60)
	if err != nil {
		return false, err
	}
	_ = conn.SetWriteDeadline(time.Now().Add(defaultTimeout))
	if _, err := conn.Write(pkt); err != nil {
		return false, err
	}

	header, payload, err := readPacket(conn)
	if err != nil {
		return false, nil
	}

	// Any valid CONNACK indicates an active MQTT broker
	if (header >> 4) == PacketConnack {
		_, _, err := parseConnack(payload)
		return err == nil, nil
	}
	return false, nil
}

// IsAnonymousAllowed checks whether an MQTT broker permits unauthenticated / anonymous login.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const allowed = mqtt.IsAnonymousAllowed('acme.com', 1883);
// log(allowed);
// ```
func IsAnonymousAllowed(ctx context.Context, host string, port int) (bool, error) {
	conn, err := dial(ctx, host, port, false, true, defaultTimeout)
	if err != nil {
		return false, err
	}
	defer func() { _ = conn.Close() }()

	pkt, err := buildConnectPacket("", "", "", true, 60)
	if err != nil {
		return false, err
	}
	_ = conn.SetWriteDeadline(time.Now().Add(defaultTimeout))
	if _, err := conn.Write(pkt); err != nil {
		return false, err
	}

	header, payload, err := readPacket(conn)
	if err != nil {
		return false, err
	}

	if (header >> 4) != PacketConnack {
		return false, fmt.Errorf("expected CONNACK, got packet type %d", header>>4)
	}

	_, returnCode, err := parseConnack(payload)
	if err != nil {
		return false, err
	}

	return returnCode == ConnAccepted, nil
}

// Connect connects to an MQTT broker using optional credentials and settings.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// const res = client.Connect('acme.com', 1883);
// log(res.Success);
// ```
func (c *Client) Connect(ctx context.Context, host string, port int, options *ConnectOptions) (*ConnectResult, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn != nil {
		_ = c.conn.Close()
		c.conn = nil
	}

	timeout := defaultTimeout
	cleanSession := true
	keepAlive := uint16(60)
	clientID := "nuclei"
	var username, password string
	useTLS := false
	insecureSkipVerify := true

	if options != nil {
		if options.Timeout > 0 {
			timeout = time.Duration(options.Timeout) * time.Second
		}
		if options.KeepAlive > 0 {
			if options.KeepAlive > 65535 {
				keepAlive = 65535
			} else {
				keepAlive = uint16(options.KeepAlive)
			}
		}
		if options.ClientID != "" {
			clientID = options.ClientID
		}
		if options.CleanSession != nil {
			cleanSession = *options.CleanSession
		}
		if options.InsecureSkipVerify != nil {
			insecureSkipVerify = *options.InsecureSkipVerify
		}
		username = options.Username
		password = options.Password
		useTLS = options.TLS
	}

	c.timeout = timeout
	conn, err := dial(ctx, host, port, useTLS, insecureSkipVerify, timeout)
	if err != nil {
		return &ConnectResult{
			Success:    false,
			ReturnCode: -1,
			Reason:     err.Error(),
		}, err
	}

	pkt, err := buildConnectPacket(clientID, username, password, cleanSession, keepAlive)
	if err != nil {
		_ = conn.Close()
		return &ConnectResult{
			Success:    false,
			ReturnCode: -1,
			Reason:     err.Error(),
		}, err
	}

	_ = conn.SetWriteDeadline(time.Now().Add(timeout))
	if _, err := conn.Write(pkt); err != nil {
		_ = conn.Close()
		return &ConnectResult{
			Success:    false,
			ReturnCode: -1,
			Reason:     fmt.Sprintf("failed to send CONNECT: %v", err),
		}, err
	}

	header, payload, err := readPacket(conn)
	if err != nil {
		_ = conn.Close()
		return &ConnectResult{
			Success:    false,
			ReturnCode: -1,
			Reason:     fmt.Sprintf("failed to read CONNACK: %v", err),
		}, err
	}

	if (header >> 4) != PacketConnack {
		_ = conn.Close()
		return &ConnectResult{
			Success:    false,
			ReturnCode: -1,
			Reason:     fmt.Sprintf("unexpected packet %d (expected CONNACK)", header>>4),
		}, fmt.Errorf("unexpected packet %d", header>>4)
	}

	sessPresent, returnCode, err := parseConnack(payload)
	if err != nil {
		_ = conn.Close()
		return &ConnectResult{
			Success:    false,
			ReturnCode: int(returnCode),
			Reason:     err.Error(),
		}, err
	}

	res := &ConnectResult{
		Success:        returnCode == ConnAccepted,
		ReturnCode:     int(returnCode),
		Reason:         ConnackReason(returnCode),
		SessionPresent: sessPresent,
	}

	if res.Success {
		c.conn = conn
	} else {
		_ = conn.Close()
	}

	return res, nil
}

// ConnectAuth connects to an MQTT broker with a username and password.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// const res = client.ConnectAuth('acme.com', 1883, 'admin', 'admin');
// log(res.Success);
// ```
func (c *Client) ConnectAuth(ctx context.Context, host string, port int, username, password string) (*ConnectResult, error) {
	clean := true
	return c.Connect(ctx, host, port, &ConnectOptions{
		Username:     username,
		Password:     password,
		CleanSession: &clean,
	})
}

// Subscribe subscribes to a topic filter and collects received messages up to timeoutSec.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// client.Connect('acme.com', 1883);
// const msgs = client.Subscribe('#', 3);
//
//	for (const m of msgs) {
//	    log(m.Topic, m.Payload);
//	}
//
// ```
func (c *Client) Subscribe(ctx context.Context, topic string, timeoutSec int) ([]*Message, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn == nil {
		return nil, fmt.Errorf("not connected to MQTT broker")
	}

	c.packetID++
	if c.packetID == 0 {
		c.packetID = 1
	}
	pktID := c.packetID

	subPkt, err := buildSubscribePacket(pktID, topic, 0)
	if err != nil {
		return nil, fmt.Errorf("failed to build SUBSCRIBE: %w", err)
	}

	_ = c.conn.SetWriteDeadline(time.Now().Add(c.timeout))
	if _, err := c.conn.Write(subPkt); err != nil {
		_ = c.conn.Close()
		c.conn = nil
		return nil, fmt.Errorf("failed to send SUBSCRIBE: %w", err)
	}

	waitDuration := 2 * time.Second
	if timeoutSec > 0 {
		if timeoutSec > 60 {
			timeoutSec = 60
		}
		waitDuration = time.Duration(timeoutSec) * time.Second
	}
	if deadline, ok := ctx.Deadline(); ok {
		if remaining := time.Until(deadline); remaining < waitDuration {
			waitDuration = remaining
		}
	}

	readDeadline := time.Now().Add(waitDuration)
	_ = c.conn.SetDeadline(readDeadline)
	defer func() {
		if c.conn != nil {
			_ = c.conn.SetDeadline(time.Time{})
		}
	}()

	var messages []*Message
	var totalBytes int
	subackReceived := false

	for {
		select {
		case <-ctx.Done():
			_ = c.conn.Close()
			c.conn = nil
			return messages, ctx.Err()
		default:
		}

		header, payload, err := readPacket(c.conn)
		if err != nil {
			if errors.Is(err, errBrokenStream) {
				// The window closed in the middle of a packet. The stream cannot be
				// read in sync again, so the connection is dropped.
				_ = c.conn.Close()
				c.conn = nil
				if !subackReceived {
					return nil, fmt.Errorf("failed waiting for SUBACK: %w", err)
				}
				break
			}
			var netErr net.Error
			if errors.As(err, &netErr) && netErr.Timeout() {
				// Window finished
				break
			}
			if !subackReceived {
				_ = c.conn.Close()
				c.conn = nil
				return nil, fmt.Errorf("failed waiting for SUBACK: %w", err)
			}
			break
		}

		packetType := header >> 4
		switch packetType {
		case PacketSuback:
			subackPID, grantedQoS, err := parseSuback(payload)
			if err != nil {
				_ = c.conn.Close()
				c.conn = nil
				return nil, err
			}
			if subackPID != pktID {
				continue // Ignore stale/mismatched SUBACK from an earlier subscription
			}
			for _, qos := range grantedQoS {
				if qos == 0x80 {
					return nil, fmt.Errorf("subscription rejected by broker for topic %q", topic)
				}
			}
			subackReceived = true

		case PacketPublish:
			msg, err := parsePublish(header, payload)
			if err == nil {
				messages = append(messages, msg)
				totalBytes += len(msg.Topic) + len(msg.Payload)
				if len(messages) >= maxSubscribedMessages || totalBytes >= maxSubscribedBytes {
					return messages, nil
				}
			}
		}

		if time.Now().After(readDeadline) {
			break
		}
	}

	if !subackReceived {
		_ = c.conn.Close()
		c.conn = nil
		return nil, fmt.Errorf("subscription timed out waiting for SUBACK")
	}

	return messages, nil
}

// Publish publishes a message payload to a topic.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// client.Connect('acme.com', 1883);
// const ok = client.Publish('nuclei/test', 'probe payload');
// log(ok);
// ```
func (c *Client) Publish(ctx context.Context, topic string, payload string) (bool, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn == nil {
		return false, fmt.Errorf("not connected to MQTT broker")
	}

	select {
	case <-ctx.Done():
		return false, ctx.Err()
	default:
	}

	pkt, err := buildPublishPacket(topic, []byte(payload), 0, false, 0)
	if err != nil {
		return false, fmt.Errorf("failed to build PUBLISH: %w", err)
	}

	_ = c.conn.SetWriteDeadline(time.Now().Add(5 * time.Second))
	if _, err := c.conn.Write(pkt); err != nil {
		_ = c.conn.Close()
		c.conn = nil
		return false, fmt.Errorf("failed to send PUBLISH: %w", err)
	}

	return true, nil
}

// Ping sends an MQTT PINGREQ and awaits PINGRESP.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// client.Connect('acme.com', 1883);
// const alive = client.Ping();
// log(alive);
// ```
func (c *Client) Ping(ctx context.Context) (bool, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn == nil {
		return false, fmt.Errorf("not connected to MQTT broker")
	}

	select {
	case <-ctx.Done():
		return false, ctx.Err()
	default:
	}

	_ = c.conn.SetDeadline(time.Now().Add(5 * time.Second))
	_ = c.conn.SetWriteDeadline(time.Now().Add(5 * time.Second))
	if _, err := c.conn.Write(buildPingreqPacket()); err != nil {
		_ = c.conn.Close()
		c.conn = nil
		return false, fmt.Errorf("failed to send PINGREQ: %w", err)
	}

	for {
		header, _, err := readPacket(c.conn)
		if err != nil {
			_ = c.conn.Close()
			c.conn = nil
			return false, fmt.Errorf("failed to read PINGRESP: %w", err)
		}

		packetType := header >> 4
		if packetType == PacketPingresp {
			return true, nil
		}
		if packetType == PacketPublish {
			// Broker delivered an incoming publish message while ping was in flight; continue waiting for PINGRESP
			continue
		}
		return false, fmt.Errorf("unexpected ping response packet: %d", packetType)
	}
}

// Close cleanly disconnects and closes the connection.
// @example
// ```javascript
// const mqtt = require('nuclei/mqtt');
// const client = new mqtt.Client();
// client.Connect('acme.com', 1883);
// client.Close();
// ```
func (c *Client) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()

	if c.conn != nil {
		_ = c.conn.SetWriteDeadline(time.Now().Add(3 * time.Second))
		_, _ = c.conn.Write(buildDisconnectPacket())
		err := c.conn.Close()
		c.conn = nil
		return err
	}
	return nil
}

package mqtt

import (
	"bytes"
	"context"
	"encoding/binary"
	"net"
	"strings"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

func TestVarLengthEncoding(t *testing.T) {
	testCases := []int{0, 1, 64, 127, 128, 16383, 16384, 2097151}
	for _, tc := range testCases {
		encoded, err := encodeVarLength(tc)
		require.NoError(t, err)
		decoded, err := decodeVarLength(bytes.NewReader(encoded))
		require.NoError(t, err)
		require.Equal(t, tc, decoded)
	}

	// Test negative or overflow
	_, err := encodeVarLength(-1)
	require.Error(t, err)
	_, err = encodeVarLength(MaxRemainingLength + 1)
	require.Error(t, err)
}

func TestOversizedStringsAndPackets(t *testing.T) {
	hugeString := strings.Repeat("A", MaxStringLength+1)
	_, err := encodeString(hugeString)
	require.Error(t, err)

	_, err = buildConnectPacket("id", hugeString, "pass", true, 60)
	require.Error(t, err)

	_, err = buildSubscribePacket(1, hugeString, 0)
	require.Error(t, err)

	_, err = buildPublishPacket(hugeString, []byte("ok"), 0, false, 0)
	require.Error(t, err)

	// Oversized packet reading
	oversizedLen, err := encodeVarLength(MaxPacketSize + 100)
	require.NoError(t, err)
	buf := append([]byte{PacketPublish << 4}, oversizedLen...)
	_, _, err = readPacket(bytes.NewReader(buf))
	require.ErrorContains(t, err, "exceeds maximum allowed")
}

func TestPacketConnect(t *testing.T) {
	pkt, err := buildConnectPacket("test-client", "user1", "pass1", true, 60)
	require.NoError(t, err)
	require.NotEmpty(t, pkt)
	require.Equal(t, byte(PacketConnect<<4), pkt[0])

	r := bytes.NewReader(pkt)
	header, payload, err := readPacket(r)
	require.NoError(t, err)
	require.Equal(t, byte(PacketConnect<<4), header)

	// Verify protocol name "MQTT"
	protoLen := binary.BigEndian.Uint16(payload[0:2])
	require.Equal(t, uint16(4), protoLen)
	require.Equal(t, "MQTT", string(payload[2:6]))
	require.Equal(t, byte(0x04), payload[6]) // Protocol level 4 (MQTT 3.1.1)

	// CleanSession (0x02) | User (0x80) | Pass (0x40) = 0xC2
	require.Equal(t, byte(0xC2), payload[7])
}

func TestPacketPublishAndParse(t *testing.T) {
	pkt, err := buildPublishPacket("sensors/temperature", []byte("23.5C"), 0, true, 0)
	require.NoError(t, err)
	require.NotEmpty(t, pkt)

	r := bytes.NewReader(pkt)
	header, payload, err := readPacket(r)
	require.NoError(t, err)

	msg, err := parsePublish(header, payload)
	require.NoError(t, err)
	require.Equal(t, "sensors/temperature", msg.Topic)
	require.Equal(t, "23.5C", msg.Payload)
	require.Equal(t, 0, msg.QoS)
	require.True(t, msg.Retain)
}

func TestPacketSubscribe(t *testing.T) {
	pkt, err := buildSubscribePacket(42, "devices/#", 0)
	require.NoError(t, err)
	require.NotEmpty(t, pkt)
	require.Equal(t, byte((PacketSubscribe<<4)|0x02), pkt[0])

	r := bytes.NewReader(pkt)
	header, payload, err := readPacket(r)
	require.NoError(t, err)
	require.Equal(t, byte((PacketSubscribe<<4)|0x02), header)

	pid := binary.BigEndian.Uint16(payload[0:2])
	require.Equal(t, uint16(42), pid)

	subackPayload := []byte{0x00, 0x2A, 0x00} // PID 42, Success QoS 0
	subackPid, granted, err := parseSuback(subackPayload)
	require.NoError(t, err)
	require.Equal(t, uint16(42), subackPid)
	require.Equal(t, []byte{0x00}, granted)
}

func TestConnackReasons(t *testing.T) {
	require.Equal(t, "connection accepted", ConnackReason(ConnAccepted))
	require.Equal(t, "connection refused: bad user name or password", ConnackReason(ConnRefusedBadAuth))
	require.Equal(t, "connection refused: not authorized", ConnackReason(ConnRefusedNotAuthorized))
	require.Contains(t, ConnackReason(99), "connection refused: return code 99")
}

func TestRequestsHonourNetworkPolicy(t *testing.T) {
	execID := "mqtt-deny"
	require.NoError(t, protocolstate.Init(&types.Options{ExecutionId: execID, ExcludeTargets: []string{"203.0.113.50"}}))
	t.Cleanup(func() { protocolstate.Close(execID) })
	ctx := context.WithValue(context.Background(), "executionId", execID) //nolint:staticcheck

	_, err := IsMQTT(ctx, "203.0.113.50", 1883)
	require.Error(t, err)

	client := &Client{}
	_, err = client.Connect(ctx, "203.0.113.50", 1883, nil)
	require.Error(t, err)
}

func startMockMQTTBroker(t *testing.T) (net.Listener, int) {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	port := l.Addr().(*net.TCPAddr).Port

	go func() {
		for {
			conn, err := l.Accept()
			if err != nil {
				return
			}
			go handleMockClient(conn)
		}
	}()

	return l, port
}

func handleMockClient(conn net.Conn) {
	defer func() { _ = conn.Close() }()

	for {
		header, payload, err := readPacket(conn)
		if err != nil {
			return
		}

		packetType := header >> 4
		switch packetType {
		case PacketConnect:
			// Check if username is present (flags byte at offset 7)
			if len(payload) >= 8 {
				flags := payload[7]
				if (flags & 0x80) != 0 {
					// Check username
					offset := 10 // after proto(6) + level(1) + flags(1) + keepalive(2)
					if len(payload) >= offset+2 {
						clientLen := int(binary.BigEndian.Uint16(payload[offset : offset+2]))
						offset += 2 + clientLen
						if len(payload) >= offset+2 {
							userLen := int(binary.BigEndian.Uint16(payload[offset : offset+2]))
							user := string(payload[offset+2 : offset+2+userLen])
							if user == "baduser" {
								// Send CONNACK Refused Bad Auth
								_, _ = conn.Write([]byte{0x20, 0x02, 0x00, ConnRefusedBadAuth})
								return
							}
						}
					}
				}
			}
			// Send CONNACK Accepted
			_, _ = conn.Write([]byte{0x20, 0x02, 0x00, ConnAccepted})

		case PacketSubscribe:
			// Send SUBACK
			pid := binary.BigEndian.Uint16(payload[0:2])
			suback := []byte{0x90, 0x03, byte(pid >> 8), byte(pid & 0xFF), 0x00}
			_, _ = conn.Write(suback)

			// Publish test message
			pubPkt, err := buildPublishPacket("nuclei/alert", []byte("vuln-detected"), 0, false, 0)
			if err == nil {
				_, _ = conn.Write(pubPkt)
			}

		case PacketPublish:
			// QoS 0, no ack needed

		case PacketPingreq:
			// Send PINGRESP
			_, _ = conn.Write([]byte{PacketPingresp << 4, 0x00})

		case PacketDisconnect:
			return
		}
	}
}

func TestMockBrokerInteractions(t *testing.T) {
	execID := "mqtt-mock-test"
	require.NoError(t, protocolstate.Init(&types.Options{ExecutionId: execID}))
	t.Cleanup(func() { protocolstate.Close(execID) })
	ctx := context.WithValue(context.Background(), "executionId", execID) //nolint:staticcheck

	l, port := startMockMQTTBroker(t)
	defer func() { _ = l.Close() }()

	// 1. Test IsMQTT
	isMQTT, err := IsMQTT(ctx, "127.0.0.1", port)
	require.NoError(t, err)
	require.True(t, isMQTT)

	// 2. Test IsAnonymousAllowed
	anonAllowed, err := IsAnonymousAllowed(ctx, "127.0.0.1", port)
	require.NoError(t, err)
	require.True(t, anonAllowed)

	// 3. Test Client Connect Auth Failure
	badClient := &Client{}
	badRes, _ := badClient.ConnectAuth(ctx, "127.0.0.1", port, "baduser", "wrongpass")
	require.False(t, badRes.Success)
	require.Equal(t, int(ConnRefusedBadAuth), badRes.ReturnCode)

	// 4. Test Client Connect Success with default CleanSession preservation
	client := &Client{}
	res, err := client.Connect(ctx, "127.0.0.1", port, &ConnectOptions{KeepAlive: 70000})
	require.NoError(t, err)
	require.True(t, res.Success)
	require.Equal(t, int(ConnAccepted), res.ReturnCode)

	// 5. Test Ping
	alive, err := client.Ping(ctx)
	require.NoError(t, err)
	require.True(t, alive)

	// 6. Test Subscribe and Receive Message
	msgs, err := client.Subscribe(ctx, "nuclei/alert", 1)
	require.NoError(t, err)
	require.NotEmpty(t, msgs)
	require.Equal(t, "nuclei/alert", msgs[0].Topic)
	require.Equal(t, "vuln-detected", msgs[0].Payload)

	// 7. Test Publish
	pubOk, err := client.Publish(ctx, "nuclei/probe", "test payload")
	require.NoError(t, err)
	require.True(t, pubOk)

	// 8. Test Close and Double Close
	require.NoError(t, client.Close())
	require.NoError(t, client.Close())
}

func TestPasswordWithoutUsername(t *testing.T) {
	// MQTT 3.1.1 (MQTT-3.1.2-22): If Password flag is set, User Name flag MUST be set.
	pkt, err := buildConnectPacket("token-client", "", "my-secret-token", true, 60)
	require.NoError(t, err)

	r := bytes.NewReader(pkt)
	_, payload, err := readPacket(r)
	require.NoError(t, err)

	// CleanSession (0x02) | User (0x80) | Pass (0x40) = 0xC2
	require.Equal(t, byte(0xC2), payload[7])

	// The client ID comes right after the keep alive at payload[8:10], and the
	// username length follows it.
	clientIDLen := int(binary.BigEndian.Uint16(payload[10:12]))
	off := 12 + clientIDLen

	// Username length should be 0 (empty string)
	userLen := binary.BigEndian.Uint16(payload[off : off+2])
	require.Equal(t, uint16(0), userLen)
	off += 2

	// Password follows the username
	passLen := binary.BigEndian.Uint16(payload[off : off+2])
	require.Equal(t, uint16(len("my-secret-token")), passLen)
	off += 2
	require.Equal(t, "my-secret-token", string(payload[off:off+int(passLen)]))
}

// A window that closes in the middle of a PUBLISH must drop the connection.
// Keeping it would let the next read start inside that packet.
func TestSubscribePartialPacketClosesConnection(t *testing.T) {
	execID := "mqtt-partial-subscribe"
	require.NoError(t, protocolstate.Init(&types.Options{ExecutionId: execID}))
	t.Cleanup(func() { protocolstate.Close(execID) })
	ctx := context.WithValue(context.Background(), "executionId", execID) //nolint:staticcheck

	l, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer func() { _ = l.Close() }()
	port := l.Addr().(*net.TCPAddr).Port

	go func() {
		conn, err := l.Accept()
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()
		for {
			header, payload, err := readPacket(conn)
			if err != nil {
				return
			}
			switch header >> 4 {
			case PacketConnect:
				_, _ = conn.Write([]byte{PacketConnack << 4, 0x02, 0x00, ConnAccepted})
			case PacketSubscribe:
				// SUBACK for the packet id, then a PUBLISH that promises 10 bytes
				// and sends 5. The client's window closes in the middle of it.
				_, _ = conn.Write([]byte{PacketSuback << 4, 0x03, payload[0], payload[1], 0x00})
				_, _ = conn.Write([]byte{PacketPublish << 4, 0x0a, 0x00, 0x03, 'a', '/', 'b'})
			}
		}
	}()

	client := &Client{}
	res, err := client.Connect(ctx, "127.0.0.1", port, nil)
	require.NoError(t, err)
	require.True(t, res.Success)

	msgs, err := client.Subscribe(ctx, "a/b", 1)
	require.NoError(t, err)
	require.Empty(t, msgs)
	require.Nil(t, client.conn, "a stream cut in the middle of a packet must not be reused")
}

func TestPingWithInFlightPublish(t *testing.T) {
	execID := "mqtt-ping-inflight"
	require.NoError(t, protocolstate.Init(&types.Options{ExecutionId: execID}))
	t.Cleanup(func() { protocolstate.Close(execID) })
	ctx := context.WithValue(context.Background(), "executionId", execID) //nolint:staticcheck

	l, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	defer func() { _ = l.Close() }()

	port := l.Addr().(*net.TCPAddr).Port

	go func() {
		conn, err := l.Accept()
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()

		for {
			header, _, err := readPacket(conn)
			if err != nil {
				return
			}
			packetType := header >> 4
			switch packetType {
			case PacketConnect:
				_, _ = conn.Write([]byte{0x20, 0x02, 0x00, ConnAccepted})
			case PacketPingreq:
				// Send a PUBLISH packet first before PINGRESP
				pubPkt, _ := buildPublishPacket("sensors/temp", []byte("25.0"), 0, false, 0)
				_, _ = conn.Write(pubPkt)
				// Then send PINGRESP
				_, _ = conn.Write([]byte{PacketPingresp << 4, 0x00})
			case PacketDisconnect:
				return
			}
		}
	}()

	client := &Client{}
	res, err := client.Connect(ctx, "127.0.0.1", port, nil)
	require.NoError(t, err)
	require.True(t, res.Success)

	// Ping should skip the in-flight PUBLISH and successfully receive PINGRESP
	alive, err := client.Ping(ctx)
	require.NoError(t, err)
	require.True(t, alive)

	_ = client.Close()
}

package mqtt

import (
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

// Limits to prevent DoS and buffer overflows
const (
	MaxStringLength    = 65535
	MaxRemainingLength = 268435455
	MaxPacketSize      = 10 * 1024 * 1024 // 10MB limit on incoming packets
)

// MQTT 3.1.1 Control Packet Types
const (
	PacketConnect    byte = 1
	PacketConnack    byte = 2
	PacketPublish    byte = 3
	PacketPuback     byte = 4
	PacketPubrec     byte = 5
	PacketPubrel     byte = 6
	PacketPubcomp    byte = 7
	PacketSubscribe  byte = 8
	PacketSuback     byte = 9
	PacketUnsub      byte = 10
	PacketUnsuback   byte = 11
	PacketPingreq    byte = 12
	PacketPingresp   byte = 13
	PacketDisconnect byte = 14
)

// CONNACK Return Codes (MQTT 3.1.1 table 3.1)
const (
	ConnAccepted                    byte = 0
	ConnRefusedUnacceptableProtocol byte = 1
	ConnRefusedIdentifierRejected   byte = 2
	ConnRefusedServerUnavailable    byte = 3
	ConnRefusedBadAuth              byte = 4
	ConnRefusedNotAuthorized        byte = 5
)

// ConnackReason returns a human-readable description for CONNACK return codes.
func ConnackReason(code byte) string {
	switch code {
	case ConnAccepted:
		return "connection accepted"
	case ConnRefusedUnacceptableProtocol:
		return "connection refused: unacceptable protocol version"
	case ConnRefusedIdentifierRejected:
		return "connection refused: identifier rejected"
	case ConnRefusedServerUnavailable:
		return "connection refused: server unavailable"
	case ConnRefusedBadAuth:
		return "connection refused: bad user name or password"
	case ConnRefusedNotAuthorized:
		return "connection refused: not authorized"
	default:
		return fmt.Sprintf("connection refused: return code %d", code)
	}
}

// encodeVarLength encodes a length integer as an MQTT variable byte integer.
func encodeVarLength(length int) ([]byte, error) {
	if length < 0 || length > MaxRemainingLength {
		return nil, fmt.Errorf("remaining length %d exceeds MQTT max %d", length, MaxRemainingLength)
	}
	var out []byte
	for {
		encodedByte := byte(length % 128)
		length /= 128
		if length > 0 {
			encodedByte |= 128
		}
		out = append(out, encodedByte)
		if length == 0 {
			break
		}
	}
	return out, nil
}

// decodeVarLength decodes an MQTT variable byte integer from reader.
func decodeVarLength(r io.Reader) (int, error) {
	multiplier := 1
	value := 0
	buf := make([]byte, 1)
	for i := 0; i < 4; i++ {
		if _, err := io.ReadFull(r, buf); err != nil {
			return 0, err
		}
		encodedByte := buf[0]
		value += int(encodedByte&127) * multiplier
		if multiplier > 128*128*128 {
			return 0, errors.New("malformed remaining length")
		}
		multiplier *= 128
		if encodedByte&128 == 0 {
			return value, nil
		}
	}
	return 0, errors.New("malformed remaining length")
}

// encodeString encodes a UTF-8 string with a 2-byte big-endian length prefix.
func encodeString(s string) ([]byte, error) {
	b := []byte(s)
	if len(b) > MaxStringLength {
		return nil, fmt.Errorf("string length %d exceeds MQTT max %d", len(b), MaxStringLength)
	}
	out := make([]byte, 2+len(b))
	binary.BigEndian.PutUint16(out[0:2], uint16(len(b)))
	copy(out[2:], b)
	return out, nil
}

// buildConnectPacket constructs an MQTT 3.1.1 CONNECT packet.
func buildConnectPacket(clientID, username, password string, cleanSession bool, keepAlive uint16) ([]byte, error) {
	var varHeader []byte
	protoName, err := encodeString("MQTT")
	if err != nil {
		return nil, err
	}
	varHeader = append(varHeader, protoName...)
	varHeader = append(varHeader, 0x04) // Protocol Level: 4 (MQTT 3.1.1)

	// Connect Flags
	var flags byte
	if cleanSession {
		flags |= 0x02
	}
	// Per MQTT 3.1.1 spec (MQTT-3.1.2-22): If the User Name Flag is 0, the Password Flag MUST be 0.
	// If a password is provided, the User Name Flag MUST be set (encoding an empty username if omitted).
	hasUsername := username != "" || password != ""
	if hasUsername {
		flags |= 0x80
	}
	if password != "" {
		flags |= 0x40
	}
	varHeader = append(varHeader, flags)

	// Keep Alive (2 bytes big endian)
	ka := make([]byte, 2)
	binary.BigEndian.PutUint16(ka, keepAlive)
	varHeader = append(varHeader, ka...)

	// Payload
	var payload []byte
	cidBytes, err := encodeString(clientID)
	if err != nil {
		return nil, fmt.Errorf("invalid clientID: %w", err)
	}
	payload = append(payload, cidBytes...)

	if hasUsername {
		userBytes, err := encodeString(username)
		if err != nil {
			return nil, fmt.Errorf("invalid username: %w", err)
		}
		payload = append(payload, userBytes...)
	}
	if password != "" {
		passBytes, err := encodeString(password)
		if err != nil {
			return nil, fmt.Errorf("invalid password: %w", err)
		}
		payload = append(payload, passBytes...)
	}

	remainingLength := len(varHeader) + len(payload)
	lenBytes, err := encodeVarLength(remainingLength)
	if err != nil {
		return nil, err
	}

	var pkt []byte
	pkt = append(pkt, PacketConnect<<4)
	pkt = append(pkt, lenBytes...)
	pkt = append(pkt, varHeader...)
	pkt = append(pkt, payload...)
	return pkt, nil
}

// buildSubscribePacket constructs an MQTT 3.1.1 SUBSCRIBE packet for a single topic.
func buildSubscribePacket(packetID uint16, topic string, qos byte) ([]byte, error) {
	var varHeader [2]byte
	binary.BigEndian.PutUint16(varHeader[:], packetID)

	topicBytes, err := encodeString(topic)
	if err != nil {
		return nil, fmt.Errorf("invalid topic: %w", err)
	}

	var payload []byte
	payload = append(payload, topicBytes...)
	payload = append(payload, qos&0x03)

	remainingLength := len(varHeader) + len(payload)
	lenBytes, err := encodeVarLength(remainingLength)
	if err != nil {
		return nil, err
	}

	var pkt []byte
	// SUBSCRIBE fixed header flags must be 0010 (0x02)
	pkt = append(pkt, (PacketSubscribe<<4)|0x02)
	pkt = append(pkt, lenBytes...)
	pkt = append(pkt, varHeader[:]...)
	pkt = append(pkt, payload...)
	return pkt, nil
}

// buildPublishPacket constructs an MQTT 3.1.1 PUBLISH packet.
func buildPublishPacket(topic string, payload []byte, qos byte, retain bool, packetID uint16) ([]byte, error) {
	headerByte := (PacketPublish << 4)
	if retain {
		headerByte |= 0x01
	}
	headerByte |= (qos & 0x03) << 1

	topicBytes, err := encodeString(topic)
	if err != nil {
		return nil, fmt.Errorf("invalid topic: %w", err)
	}

	var varHeader []byte
	varHeader = append(varHeader, topicBytes...)
	if qos > 0 {
		pid := make([]byte, 2)
		binary.BigEndian.PutUint16(pid, packetID)
		varHeader = append(varHeader, pid...)
	}

	remainingLength := len(varHeader) + len(payload)
	lenBytes, err := encodeVarLength(remainingLength)
	if err != nil {
		return nil, err
	}

	var pkt []byte
	pkt = append(pkt, headerByte)
	pkt = append(pkt, lenBytes...)
	pkt = append(pkt, varHeader...)
	pkt = append(pkt, payload...)
	return pkt, nil
}

// buildPingreqPacket constructs an MQTT PINGREQ packet.
func buildPingreqPacket() []byte {
	return []byte{PacketPingreq << 4, 0x00}
}

// buildDisconnectPacket constructs an MQTT DISCONNECT packet.
func buildDisconnectPacket() []byte {
	return []byte{PacketDisconnect << 4, 0x00}
}

// errBrokenStream means a read failed after part of a packet was consumed, or
// a packet was refused, so the next read would start in the middle of a packet.
// The connection must not be used again.
var errBrokenStream = errors.New("MQTT stream is out of sync")

// readPacket reads a full MQTT packet from reader, rejecting packets over MaxPacketSize.
// Failures before the first byte is read are returned as they are. Failures after
// it wrap errBrokenStream.
func readPacket(r io.Reader) (headerByte byte, payload []byte, err error) {
	var header [1]byte
	if _, err := io.ReadFull(r, header[:]); err != nil {
		return 0, nil, err
	}
	length, err := decodeVarLength(r)
	if err != nil {
		return 0, nil, fmt.Errorf("%w: %w", errBrokenStream, err)
	}
	if length > MaxPacketSize {
		return 0, nil, fmt.Errorf("%w: MQTT packet length %d exceeds maximum allowed %d", errBrokenStream, length, MaxPacketSize)
	}
	buf := make([]byte, length)
	if length > 0 {
		if _, err := io.ReadFull(r, buf); err != nil {
			return 0, nil, fmt.Errorf("%w: %w", errBrokenStream, err)
		}
	}
	return header[0], buf, nil
}

// parseConnack decodes a CONNACK variable header.
func parseConnack(payload []byte) (sessionPresent bool, returnCode byte, err error) {
	if len(payload) < 2 {
		return false, 0, errors.New("short CONNACK response")
	}
	sessionPresent = (payload[0] & 0x01) != 0
	returnCode = payload[1]
	return sessionPresent, returnCode, nil
}

// parseSuback decodes a SUBACK packet payload.
func parseSuback(payload []byte) (packetID uint16, grantedQoS []byte, err error) {
	if len(payload) < 3 {
		return 0, nil, errors.New("short SUBACK response")
	}
	packetID = binary.BigEndian.Uint16(payload[0:2])
	grantedQoS = payload[2:]
	return packetID, grantedQoS, nil
}

// parsePublish decodes a PUBLISH packet.
func parsePublish(headerByte byte, body []byte) (*Message, error) {
	qos := (headerByte >> 1) & 0x03
	retain := (headerByte & 0x01) != 0

	if len(body) < 2 {
		return nil, errors.New("short PUBLISH packet")
	}
	topicLen := int(binary.BigEndian.Uint16(body[0:2]))
	if len(body) < 2+topicLen {
		return nil, errors.New("short PUBLISH topic")
	}
	topic := string(body[2 : 2+topicLen])
	offset := 2 + topicLen

	if qos > 0 {
		if len(body) < offset+2 {
			return nil, errors.New("short PUBLISH packet ID")
		}
		offset += 2
	}

	payload := string(body[offset:])
	return &Message{
		Topic:   topic,
		Payload: payload,
		QoS:     int(qos),
		Retain:  retain,
	}, nil
}

