type (
	// MySQLClient is a client for MySQL database.
	// Internally client uses go-sql-driver/mysql driver.
	// @example
	// ```javascript
	// const mysql = require('nuclei/mysql');
	// const client = new mysql.MySQLClient;
	// ```
	MySQLClient struct{}
)

// IsMySQL checks if the given host is running MySQL database.
// If the host is running MySQL database, it returns true.
// If the host is not running MySQL database, it returns false.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const isMySQL = mysql.IsMySQL('acme.com', 3306);
// ```
func (c *MySQLClient) IsMySQL(ctx context.Context, host string, port int) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	// todo: why this is exposed? Service fingerprint should be automatic
	return memoizedisMySQL(ctx, executionId, host, port)
}

// @memo
func isMySQL(ctx context.Context, executionId string, host string, port int) (bool, error) {
	// Reuse the memoized fingerprint probe so IsMySQL + FingerprintMySQL share one dial.
	_, err := memoizedfingerprintMySQL(ctx, executionId, host, port)
	if err != nil {
		return false, err
	}
	return true, nil
}

// Connect connects to MySQL database using given credentials.
// If connection is successful, it returns true.
// If connection is unsuccessful, it returns false and error.
// The connection is closed after the function returns.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const client = new mysql.MySQLClient;
// const connected = client.Connect('acme.com', 3306, 'username', 'password');
// ```
func (c *MySQLClient) Connect(ctx context.Context, host string, port int, username, password string) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	if !protocolstate.IsHostAllowed(executionId, host) {
		// host is not valid according to network policy
		return false, protocolstate.ErrHostDenied.Msgf(host)
	}

	// executing queries implies the remote mysql service
	ok, err := c.IsMySQL(ctx, host, port)
	if err != nil {
		return false, err
	}
	if !ok {
		return false, fmt.Errorf("not a mysql service")
	}

	dsn, err := BuildDSN(MySQLOptions{
		Host:     host,
		Port:     port,
		DbName:   "INFORMATION_SCHEMA",
		Protocol: "tcp",
		Username: username,
		Password: password,
	})
	if err != nil {
		return false, err
	}
	return memoizedconnectWithDSN(ctx, executionId, dsn)
}

type (
	// MySQLInfo contains information about MySQL server.
	// this is returned when fingerprint is successful
	MySQLInfo struct {
		Host            string        `json:"host,omitempty"`
		IP              string        `json:"ip"`
		Port            int           `json:"port"`
		Protocol        string        `json:"protocol"`
		TLS             bool          `json:"tls"`
		Transport       string        `json:"transport"`
		Version         string        `json:"version,omitempty"`
		ProtocolVersion int           `json:"protocolVersion,omitempty"`
		ThreadID        uint32        `json:"threadId,omitempty"`
		CapabilityFlags uint32        `json:"capabilityFlags,omitempty"`
		Capabilities    []string      `json:"capabilities,omitempty"`
		CharacterSet    uint8         `json:"characterSet,omitempty"`
		StatusFlags     uint16        `json:"statusFlags,omitempty"`
		Status          []string      `json:"status,omitempty"`
		Salt            string        `json:"salt,omitempty"`
		AuthPluginName  string        `json:"authPluginName,omitempty"`
		Debug           HandshakeInfo `json:"debug,omitempty"`
		Raw             string        `json:"metadata"`
	}
)

// returns MySQLInfo when fingerprint is successful
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const info = mysql.FingerprintMySQL('acme.com', 3306);
// log(to_json(info));
// ```
func (c *MySQLClient) FingerprintMySQL(ctx context.Context, host string, port int) (MySQLInfo, error) {
	executionId := ctx.Value("executionId").(string)
	return memoizedfingerprintMySQL(ctx, executionId, host, port)
}

// @memo
func fingerprintMySQL(ctx context.Context, executionId string, host string, port int) (MySQLInfo, error) {
	info := MySQLInfo{}
	if !protocolstate.IsHostAllowed(executionId, host) {
		// host is not valid according to network policy
		return info, protocolstate.ErrHostDenied.Msgf(host)
	}
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return MySQLInfo{}, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	conn, err := dialer.Fastdialer.Dial(ctx, "tcp", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
	if err != nil {
		return info, err
	}
	defer func() {
		_ = conn.Close()
	}()

	handshake, err := fingerprintConn(conn, mysqlFingerprintTimeout)
	if err != nil {
		return info, err
	}

	info.Host = host
	info.Port = port
	info.Protocol = "mysql"
	info.Transport = "tcp"
	info.TLS = false
	if hostIP := net.ParseIP(host); hostIP != nil {
		info.IP = hostIP.String()
	} else if remote, ok := conn.RemoteAddr().(*net.TCPAddr); ok && remote.IP != nil {
		info.IP = remote.IP.String()
	}
	info.Version = handshake.Version
	info.ProtocolVersion = handshake.ProtocolVersion
	info.ThreadID = handshake.ThreadID
	info.CapabilityFlags = handshake.CapabilityFlags
	info.Capabilities = handshake.Capabilities
	info.CharacterSet = handshake.CharacterSet
	info.StatusFlags = handshake.StatusFlags
	info.Status = handshake.Status
	info.Salt = handshake.Salt
	info.AuthPluginName = handshake.AuthPluginName
	info.Debug = handshake
	info.Raw = handshakeToJSON(handshake)
	return info, nil
}

// ConnectWithDSN connects to MySQL database using given DSN.
// we override mysql dialer with fastdialer so it respects network policy
// If connection is successful, it returns true.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const client = new mysql.MySQLClient;
// const connected = client.ConnectWithDSN('username:password@tcp(acme.com:3306)/');
// ```
func (c *MySQLClient) ConnectWithDSN(ctx context.Context, dsn string) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	return memoizedconnectWithDSN(ctx, executionId, dsn)
}

// ExecuteQueryWithOpts connects to Mysql database using given credentials
// and executes a query on the db.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const options = new mysql.MySQLOptions();
// options.Host = 'acme.com';
// options.Port = 3306;
// const result = mysql.ExecuteQueryWithOpts(options, 'SELECT * FROM users');
// log(to_json(result));
// ```
func (c *MySQLClient) ExecuteQueryWithOpts(ctx context.Context, opts MySQLOptions, query string) (*utils.SQLResult, error) {
	executionId := ctx.Value("executionId").(string)
	if !protocolstate.IsHostAllowed(executionId, opts.Host) {
		// host is not valid according to network policy
		return nil, protocolstate.ErrHostDenied.Msgf(opts.Host)
	}

	// executing queries implies the remote mysql service
	ok, err := c.IsMySQL(ctx, opts.Host, opts.Port)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("not a mysql service")
	}

	dsn, err := BuildDSN(opts)
	if err != nil {
		return nil, err
	}

	db, err := openDB(executionId, dsn)
	if err != nil {
		return nil, err
	}
	defer func() {
		_ = db.Close()
	}()
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(0)

	rows, err := db.QueryContext(ctx, query)
	if err != nil {
		return nil, err
	}

	data, err := utils.UnmarshalSQLRows(rows)
	if err != nil {
		if len(data.Rows) > 0 {
			// allow partial results
			return data, nil
		}
		return nil, err
	}
	return data, nil
}

// ExecuteQuery connects to Mysql database using given credentials
// and executes a query on the db.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const result = mysql.ExecuteQuery('acme.com', 3306, 'username', 'password', 'SELECT * FROM users');
// log(to_json(result));
// ```
func (c *MySQLClient) ExecuteQuery(ctx context.Context, host string, port int, username, password, query string) (*utils.SQLResult, error) {
	// executing queries implies the remote mysql service
	ok, err := c.IsMySQL(ctx, host, port)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("not a mysql service")
	}

	return c.ExecuteQueryWithOpts(ctx, MySQLOptions{
		Host:     host,
		Port:     port,
		Protocol: "tcp",
		Username: username,
		Password: password,
	}, query)
}

// ExecuteQuery connects to Mysql database using given credentials
// and executes a query on the db.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const result = mysql.ExecuteQueryOnDB('acme.com', 3306, 'username', 'password', 'dbname', 'SELECT * FROM users');
// log(to_json(result));
// ```
func (c *MySQLClient) ExecuteQueryOnDB(ctx context.Context, host string, port int, username, password, dbname, query string) (*utils.SQLResult, error) {
	return c.ExecuteQueryWithOpts(ctx, MySQLOptions{
		Host:     host,
		Port:     port,
		Protocol: "tcp",
		Username: username,
		Password: password,
		DbName:   dbname,
	}, query)
}

func init() {
	_ = mysql.SetLogger(log.New(io.Discard, "", 0))
}

package mysql

import (
	"context"
	"database/sql"
	"fmt"
	"net"
	"net/url"
	"strings"

	"github.com/go-sql-driver/mysql"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

type (
	// MySQLOptions defines the data source name (DSN) options required to connect to a MySQL database.
	// along with other options like Timeout etc
	// @example
	// ```javascript
	// const mysql = require('nuclei/mysql');
	// const options = new mysql.MySQLOptions();
	// options.Host = 'acme.com';
	// options.Port = 3306;
	// ```
	MySQLOptions struct {
		Host     string // Host is the host name or IP address of the MySQL server.
		Port     int    // Port is the port number on which the MySQL server is listening.
		Protocol string // Protocol is the protocol used to connect to the MySQL server (ex: "tcp").
		Username string // Username is the user name used to authenticate with the MySQL server.
		Password string // Password is the password used to authenticate with the MySQL server.
		DbName   string // DbName is the name of the database to connect to on the MySQL server.
		RawQuery string // QueryStr is the query string to append to the DSN (ex: "?tls=skip-verify").
		Timeout  int    // Timeout is the timeout in seconds for the connection to the MySQL server.
	}
)

// BuildDSN builds a MySQL data source name (DSN) from the given options.
// @example
// ```javascript
// const mysql = require('nuclei/mysql');
// const options = new mysql.MySQLOptions();
// options.Host = 'acme.com';
// options.Port = 3306;
// const dsn = mysql.BuildDSN(options);
// ```
func BuildDSN(opts MySQLOptions) (string, error) {
	if opts.Host == "" || opts.Port <= 0 {
		return "", fmt.Errorf("invalid host or port")
	}
	if opts.Protocol == "" {
		opts.Protocol = "tcp"
	}
	// We're going to use a custom dialer when creating MySQL connections, so if we've been
	// given "tcp" as the protocol, then quietly switch it to "nucleitcp", which we have
	// already registered.
	if opts.Protocol == "tcp" {
		opts.Protocol = "nucleitcp"
	}
	if opts.DbName == "" {
		opts.DbName = "/"
	} else {
		opts.DbName = "/" + opts.DbName
	}
	target := net.JoinHostPort(opts.Host, fmt.Sprintf("%d", opts.Port))
	var dsn strings.Builder
	fmt.Fprintf(&dsn, "%v:%v", url.QueryEscape(opts.Username), opts.Password)
	dsn.WriteString("@")
	fmt.Fprintf(&dsn, "%v(%v)", opts.Protocol, target)
	if opts.DbName != "" {
		dsn.WriteString(opts.DbName)
	}
	if opts.RawQuery != "" {
		dsn.WriteString(opts.RawQuery)
	}
	return dsn.String(), nil
}

// sandboxDSN enforces local file and network policy on a MySQL DSN.
// allowAllFiles is only honored when -lfa is enabled. tcp, tcp4 and tcp6
// DSNs are rewritten to nucleitcp so the driver uses the fastdialer
// registered in protocolstate. Unix sockets are treated as loopback for -lna.
// Other networks are rejected.
func sandboxDSN(executionId, dsn string) (string, error) {
	cfg, err := mysql.ParseDSN(dsn)
	if err != nil {
		return "", err
	}
	opts := &types.Options{ExecutionId: executionId}
	if cfg.AllowAllFiles && !protocolstate.IsLfaAllowed(opts) {
		cfg.AllowAllFiles = false
	}

	netName := cfg.Net
	if netName == "" {
		netName = "tcp"
	}
	switch netName {
	case "unix":
		// IP-based policy never sees a socket path; gate on loopback like ldapi.
		const unixPolicyHost = "127.0.0.1"
		if !protocolstate.IsHostAllowed(executionId, unixPolicyHost) {
			return "", protocolstate.ErrHostDenied.Msgf(unixPolicyHost)
		}
	case "tcp", "tcp4", "tcp6", "nucleitcp":
		// Only nucleitcp has a registered dialer; the others would use the
		// driver's plain net.Dialer and skip the dial-time policy check.
		cfg.Net = "nucleitcp"
		host := dsnPolicyHost(cfg.Addr)
		if !protocolstate.IsHostAllowed(executionId, host) {
			return "", protocolstate.ErrHostDenied.Msgf(host)
		}
	default:
		return "", fmt.Errorf("unsupported mysql network %q", netName)
	}
	return cfg.FormatDSN(), nil
}

func dsnPolicyHost(addr string) string {
	host, _, err := net.SplitHostPort(addr)
	if err == nil && host != "" {
		return host
	}
	return addr
}

// openDB opens a sandboxed MySQL connection from dsn.
func openDB(executionId, dsn string) (*sql.DB, error) {
	dsn, err := sandboxDSN(executionId, dsn)
	if err != nil {
		return nil, err
	}
	return sql.Open("mysql", dsn)
}

// @memo
func connectWithDSN(ctx context.Context, executionId string, dsn string) (bool, error) {
	db, err := openDB(executionId, dsn)
	if err != nil {
		return false, err
	}
	defer func() {
		_ = db.Close()
	}()
	db.SetMaxOpenConns(1)
	db.SetMaxIdleConns(0)

	pingCtx := context.WithValue(ctx, "executionId", executionId) // nolint: staticcheck
	err = db.PingContext(pingCtx)
	if err != nil {
		return false, err
	}
	return true, nil
}

package mysql

import (
	"testing"

	"github.com/go-sql-driver/mysql"
	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

func TestSandboxDSN(t *testing.T) {
	t.Run("strips allowAllFiles when lfa disabled", func(t *testing.T) {
		got, err := sandboxDSN("", "root:x@nucleitcp(127.0.0.1:3306)/?allowAllFiles=true")
		require.NoError(t, err)

		cfg, err := mysql.ParseDSN(got)
		require.NoError(t, err)
		require.False(t, cfg.AllowAllFiles)
	})

	t.Run("keeps allowAllFiles when lfa enabled", func(t *testing.T) {
		executionID := "mysql-lfa-" + t.Name()
		require.NoError(t, protocolstate.Init(&types.Options{
			ExecutionId:          executionID,
			AllowLocalFileAccess: true,
		}))
		t.Cleanup(func() { protocolstate.Close(executionID) })

		got, err := sandboxDSN(executionID, "root:x@nucleitcp(127.0.0.1:3306)/?allowAllFiles=true")
		require.NoError(t, err)

		cfg, err := mysql.ParseDSN(got)
		require.NoError(t, err)
		require.True(t, cfg.AllowAllFiles)
	})

	t.Run("leaves dsn without allowAllFiles untouched", func(t *testing.T) {
		got, err := sandboxDSN("", "root:x@nucleitcp(127.0.0.1:3306)/")
		require.NoError(t, err)

		cfg, err := mysql.ParseDSN(got)
		require.NoError(t, err)
		require.False(t, cfg.AllowAllFiles)
	})

	t.Run("rewrites tcp to nucleitcp", func(t *testing.T) {
		got, err := sandboxDSN("", "root:x@tcp(acme.com:3306)/")
		require.NoError(t, err)

		cfg, err := mysql.ParseDSN(got)
		require.NoError(t, err)
		require.Equal(t, "nucleitcp", cfg.Net)
		require.Equal(t, "acme.com:3306", cfg.Addr)
	})

	t.Run("rewrites tcp4 and tcp6 to nucleitcp", func(t *testing.T) {
		for _, netName := range []string{"tcp4", "tcp6"} {
			got, err := sandboxDSN("", "root:x@"+netName+"(acme.com:3306)/")
			require.NoError(t, err)

			cfg, err := mysql.ParseDSN(got)
			require.NoError(t, err)
			require.Equal(t, "nucleitcp", cfg.Net)
			require.Equal(t, "acme.com:3306", cfg.Addr)
		}
	})

	t.Run("rejects unsupported network", func(t *testing.T) {
		_, err := sandboxDSN("", "root:x@udp(acme.com:3306)/")
		require.Error(t, err)
		require.Contains(t, err.Error(), "udp")
	})

	t.Run("errors on invalid dsn", func(t *testing.T) {
		_, err := sandboxDSN("", "::not-a-dsn::")
		require.Error(t, err)
	})

	t.Run("denies loopback tcp when lna enabled", func(t *testing.T) {
		executionID := "mysql-lna-tcp-" + t.Name()
		require.NoError(t, protocolstate.Init(&types.Options{
			ExecutionId:                executionID,
			RestrictLocalNetworkAccess: true,
		}))
		t.Cleanup(func() { protocolstate.Close(executionID) })

		_, err := sandboxDSN(executionID, "vuser:vpass@tcp(127.0.0.1:3306)/vdb")
		require.Error(t, err)
		require.Contains(t, err.Error(), "127.0.0.1")
	})

	t.Run("denies loopback variants when lna enabled", func(t *testing.T) {
		executionID := "mysql-lna-variants-" + t.Name()
		require.NoError(t, protocolstate.Init(&types.Options{
			ExecutionId:                executionID,
			RestrictLocalNetworkAccess: true,
		}))
		t.Cleanup(func() { protocolstate.Close(executionID) })

		for _, dsn := range []string{
			"vuser:vpass@tcp4(127.0.0.1:3306)/vdb",
			"vuser:vpass@tcp6([::1]:3306)/vdb",
			"vuser:vpass@tcp([::ffff:127.0.0.1]:3306)/vdb",
		} {
			_, err := sandboxDSN(executionID, dsn)
			require.Error(t, err, dsn)
		}
	})

	t.Run("denies unix socket when lna enabled", func(t *testing.T) {
		executionID := "mysql-lna-unix-" + t.Name()
		require.NoError(t, protocolstate.Init(&types.Options{
			ExecutionId:                executionID,
			RestrictLocalNetworkAccess: true,
		}))
		t.Cleanup(func() { protocolstate.Close(executionID) })

		_, err := sandboxDSN(executionID, "vuser:vpass@unix(/tmp/nuclei-mysql-lna.sock)/vdb")
		require.Error(t, err)
		require.Contains(t, err.Error(), "127.0.0.1")
	})
}

package net

import (
	"bufio"
	"context"
	"crypto/tls"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/utils/errkit"
	"github.com/projectdiscovery/utils/reader"
)

var (
	defaultTimeout = time.Duration(5) * time.Second

	errNoConnection = errors.New("no connection: open one with net.Open or net.OpenTLS")
)

// getTimeoutFromContext returns the configured TCP timeout or defaultTimeout.
func getTimeoutFromContext(ctx context.Context) time.Duration {
	if tv, ok := ctx.Value("timeoutVariants").(*types.Timeouts); ok && tv != nil {
		if tv.TcpReadTimeout > 0 {
			return tv.TcpReadTimeout
		}
	}
	return defaultTimeout
}

func proxyURLFromContext(ctx context.Context) string {
	if proxyURL, ok := ctx.Value("proxyURL").(string); ok {
		return proxyURL
	}
	return ""
}

func executionIDFromContext(ctx context.Context) (string, error) {
	executionId, _ := ctx.Value("executionId").(string)
	if executionId == "" {
		return "", fmt.Errorf("executionId missing from context")
	}
	return executionId, nil
}

type dialFunc func(ctx context.Context, network, address string) (net.Conn, error)

// dialHTTPProxy establishes a TCP connection through an HTTP CONNECT proxy.
func dialHTTPProxy(ctx context.Context, dial dialFunc, proxyURL string, address string, timeout time.Duration) (net.Conn, error) {
	parsed, err := url.Parse(proxyURL)
	if err != nil {
		return nil, fmt.Errorf("invalid proxy URL: %w", err)
	}
	proxyAddr := parsed.Host
	if _, _, splitErr := net.SplitHostPort(proxyAddr); splitErr != nil {
		defaultPort := "8080"
		if parsed.Scheme == "https" {
			defaultPort = "443"
		}
		proxyAddr = net.JoinHostPort(proxyAddr, defaultPort)
	}

	proxyConn, err := dial(ctx, "tcp", proxyAddr)
	if err != nil {
		return nil, fmt.Errorf("could not connect to proxy %s: %w", proxyAddr, err)
	}
	if parsed.Scheme == "https" {
		config := &tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS10}
		if hostname := parsed.Hostname(); hostname != "" {
			config.ServerName = hostname
		}
		tlsConn := tls.Client(proxyConn, config)
		if err := tlsConn.HandshakeContext(ctx); err != nil {
			_ = proxyConn.Close()
			return nil, fmt.Errorf("could not establish TLS connection to proxy %s: %w", proxyAddr, err)
		}
		proxyConn = tlsConn
	}

	connectReq := &http.Request{
		Method: http.MethodConnect,
		URL:    &url.URL{Opaque: address},
		Host:   address,
		Header: make(http.Header),
	}
	if parsed.User != nil {
		connectReq.Header.Set("Proxy-Authorization", "Basic "+basicAuth(parsed.User))
	}

	_ = proxyConn.SetDeadline(time.Now().Add(timeout))
	if err := connectReq.Write(proxyConn); err != nil {
		_ = proxyConn.Close()
		return nil, fmt.Errorf("could not send CONNECT request: %w", err)
	}

	br := bufio.NewReader(proxyConn)
	resp, err := http.ReadResponse(br, connectReq)
	if err != nil {
		_ = proxyConn.Close()
		return nil, fmt.Errorf("could not read CONNECT response: %w", err)
	}
	_ = resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		_ = proxyConn.Close()
		return nil, fmt.Errorf("proxy CONNECT returned status %d", resp.StatusCode)
	}

	// reset deadline after successful CONNECT
	_ = proxyConn.SetDeadline(time.Time{})

	// preserve any bytes the buffered reader consumed past the CONNECT response
	if br.Buffered() > 0 {
		return &bufferedConn{Conn: proxyConn, reader: br}, nil
	}
	return proxyConn, nil
}

// basicAuth encodes proxy user credentials.
func basicAuth(user *url.Userinfo) string {
	username := user.Username()
	password, _ := user.Password()
	return base64.StdEncoding.EncodeToString([]byte(username + ":" + password))
}

func redactProxyURL(proxyURL string) string {
	parsed, err := url.Parse(proxyURL)
	if err != nil {
		return "<invalid proxy URL>"
	}
	parsed.User = nil
	return parsed.String()
}

// bufferedConn preserves bytes buffered during the CONNECT handshake.
type bufferedConn struct {
	net.Conn
	reader *bufio.Reader
}

func (c *bufferedConn) Read(b []byte) (int, error) {
	return c.reader.Read(b)
}

// dialTargetHost returns the host portion of a dial address. Addresses that
// are already a bare host are returned unchanged.
func dialTargetHost(address string) string {
	host, _, err := net.SplitHostPort(address)
	if err != nil {
		return address
	}
	return host
}

// Dial opens a connection using the execution dialer.
// When an HTTP(S) proxy is present in context, TCP dials use HTTP CONNECT.
// Misconfigured proxies return an error instead of silently dialing direct.
func Dial(ctx context.Context, protocol, address string) (net.Conn, error) {
	executionId, err := executionIDFromContext(ctx)
	if err != nil {
		return nil, err
	}
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	if proxyURL := proxyURLFromContext(ctx); proxyURL != "" {
		if protocol != "tcp" {
			return nil, fmt.Errorf("http proxy does not support protocol %q", protocol)
		}
		parsed, err := url.Parse(proxyURL)
		if err != nil {
			return nil, fmt.Errorf("invalid proxy URL %s: %w", redactProxyURL(proxyURL), err)
		}
		switch parsed.Scheme {
		case "http", "https":
			// Enforce the network policy on the tunneled target. Direct dials go
			// through Fastdialer, which validates the destination itself, but the
			// proxy path only dials the proxy through Fastdialer and tunnels the
			// target inside an HTTP CONNECT, so the target would otherwise skip the
			// deny-list (-exclude-hosts / -restrict-local-network-access) checks.
			// Split the port off first. IsHostAllowed only does that for a single
			// colon, so an address like [::1]:80 would skip the IP deny list.
			// Do this only for schemes that actually tunnel. IsHostAllowed resolves
			// hostnames, and an earlier check would hide "unsupported proxy scheme"
			// behind a DNS failure.
			if !protocolstate.IsHostAllowed(executionId, dialTargetHost(address)) {
				return nil, fmt.Errorf("host %s is not allowed by network policy", address)
			}
			return dialHTTPProxy(ctx, dialer.Fastdialer.Dial, proxyURL, address, getTimeoutFromContext(ctx))
		default:
			return nil, fmt.Errorf("unsupported proxy scheme %q in %s (expected http or https)", parsed.Scheme, redactProxyURL(proxyURL))
		}
	}

	return dialer.Fastdialer.Dial(ctx, protocol, address)
}

// Open opens a new connection to the address with a timeout.
// supported protocols: tcp, udp
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// ```
func Open(ctx context.Context, protocol, address string) (*NetConn, error) {
	timeout := getTimeoutFromContext(ctx)
	conn, err := Dial(ctx, protocol, address)
	if err != nil {
		return nil, err
	}
	return &NetConn{conn: conn, timeout: timeout}, nil
}

// OpenTLS opens a new TLS connection to the address with a timeout.
// supported protocols: tcp, udp
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.OpenTLS('tcp', 'acme.com:443');
// ```
func OpenTLS(ctx context.Context, protocol, address string) (*NetConn, error) {
	timeout := getTimeoutFromContext(ctx)
	config := &tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS10}
	host, _, _ := net.SplitHostPort(address)
	if host != "" {
		c := config.Clone()
		c.ServerName = host
		config = c
	}

	if proxyURLFromContext(ctx) != "" {
		conn, err := Dial(ctx, protocol, address)
		if err != nil {
			return nil, err
		}
		tlsConn := tls.Client(conn, config)
		if err := tlsConn.HandshakeContext(ctx); err != nil {
			_ = conn.Close()
			return nil, fmt.Errorf("TLS handshake failed: %w", err)
		}
		return &NetConn{conn: tlsConn, timeout: timeout}, nil
	}

	executionId, err := executionIDFromContext(ctx)
	if err != nil {
		return nil, err
	}
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", executionId)
	}
	conn, err := dialer.Fastdialer.DialTLSWithConfig(ctx, protocol, address, config)
	if err != nil {
		return nil, err
	}
	return &NetConn{conn: conn, timeout: timeout}, nil
}

type (
	// NetConn is a connection to a remote host.
	// this is returned/create by Open and OpenTLS functions.
	// @example
	// ```javascript
	// const net = require('nuclei/net');
	// const conn = net.Open('tcp', 'acme.com:80');
	// ```
	NetConn struct {
		// conn is nil when no connection is open.
		conn    net.Conn
		timeout time.Duration
	}
)

// Close closes the connection.
// Close does nothing if no connection is open.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// conn.Close();
// ```
func (c *NetConn) Close() error {
	if c.conn == nil {
		return nil
	}

	err := c.conn.Close()
	c.conn = nil

	return err
}

// SetTimeout sets read/write timeout for the connection (in seconds).
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// conn.SetTimeout(10);
// ```
func (c *NetConn) SetTimeout(value int) {
	c.timeout = time.Duration(value) * time.Second
}

// setDeadLine sets read/write deadline for the connection (in seconds).
// this is intended to be called before every read/write operation.
func (c *NetConn) setDeadLine() {
	if c.timeout == 0 {
		c.timeout = 5 * time.Second
	}
	_ = c.conn.SetDeadline(time.Now().Add(c.timeout))
}

// unsetDeadLine unsets read/write deadline for the connection.
func (c *NetConn) unsetDeadLine() {
	_ = c.conn.SetDeadline(time.Time{})
}

// SendArray sends array data to connection
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// conn.SendArray(['hello', 'world']);
// ```
func (c *NetConn) SendArray(data []interface{}) error {
	if c.conn == nil {
		return errNoConnection
	}

	c.setDeadLine()
	defer c.unsetDeadLine()
	input := types.ToByteSlice(data)
	length, err := c.conn.Write(input)
	if err != nil {
		return err
	}
	if length < len(input) {
		return fmt.Errorf("failed to write all bytes (%d bytes written, %d bytes expected)", length, len(input))
	}
	return nil
}

// SendHex sends hex data to connection
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// conn.SendHex('68656c6c6f');
// ```
func (c *NetConn) SendHex(data string) error {
	if c.conn == nil {
		return errNoConnection
	}

	c.setDeadLine()
	defer c.unsetDeadLine()
	bin, err := hex.DecodeString(data)
	if err != nil {
		return err
	}
	length, err := c.conn.Write(bin)
	if err != nil {
		return err
	}
	if length < len(bin) {
		return fmt.Errorf("failed to write all bytes (%d bytes written, %d bytes expected)", length, len(bin))
	}
	return nil
}

// Send sends data to the connection with a timeout.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// conn.Send('hello');
// ```
func (c *NetConn) Send(data string) error {
	if c.conn == nil {
		return errNoConnection
	}

	c.setDeadLine()
	defer c.unsetDeadLine()
	bin := []byte(data)
	length, err := c.conn.Write(bin)
	if err != nil {
		return err
	}
	if length < len(bin) {
		return fmt.Errorf("failed to write all bytes (%d bytes written, %d bytes expected)", length, len(data))
	}
	return nil
}

// RecvFull receives data from the connection with a timeout.
// If N is 0, it will read all data sent by the server with 8MB limit.
// it tries to read until N bytes or timeout is reached.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.RecvFull(1024);
// ```
func (c *NetConn) RecvFull(N int) ([]byte, error) {
	if c.conn == nil {
		return []byte{}, errNoConnection
	}

	c.setDeadLine()
	defer c.unsetDeadLine()
	if N == 0 {
		// in utils we use -1 to indicate read all rather than 0
		N = -1
	}
	bin, err := reader.ConnReadNWithTimeout(c.conn, int64(N), c.timeout)
	if err != nil {
		return []byte{}, errkit.Wrapf(err, "failed to read %d bytes", N)
	}
	return bin, nil
}

// Recv is similar to RecvFull but does not guarantee full read instead
// it creates a buffer of N bytes and returns whatever is returned by the connection
// for reading headers or initial bytes from the server this is usually used.
// for reading a fixed number of already known bytes (ex: body based on content-length) use RecvFull.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.Recv(1024);
// log(`Received ${data.length} bytes from the server`)
// ```
func (c *NetConn) Recv(N int) ([]byte, error) {
	if c.conn == nil {
		return []byte{}, errNoConnection
	}

	c.setDeadLine()
	defer c.unsetDeadLine()
	if N == 0 {
		N = 4096
	}
	b := make([]byte, N)
	n, err := c.conn.Read(b)
	if err != nil {
		return []byte{}, errkit.Wrapf(err, "failed to read %d bytes", N)
	}
	return b[:n], nil
}

// RecvFullString receives data from the connection with a timeout
// output is returned as a string.
// If N is 0, it will read all data sent by the server with 8MB limit.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.RecvFullString(1024);
// ```
func (c *NetConn) RecvFullString(N int) (string, error) {
	bin, err := c.RecvFull(N)
	if err != nil {
		return "", err
	}
	return string(bin), nil
}

// RecvString is similar to RecvFullString but does not guarantee full read, instead
// it creates a buffer of N bytes and returns whatever is returned by the connection
// for reading headers or initial bytes from the server this is usually used.
// for reading a fixed number of already known bytes (ex: body based on content-length) use RecvFullString.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.RecvString(1024);
// ```
func (c *NetConn) RecvString(N int) (string, error) {
	bin, err := c.Recv(N)
	if err != nil {
		return "", err
	}
	return string(bin), nil
}

// RecvFullHex receives data from the connection with a timeout
// in hex format.
// If N is 0,it will read all data sent by the server with 8MB limit.
// until N bytes or timeout is reached.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.RecvFullHex(1024);
// ```
func (c *NetConn) RecvFullHex(N int) (string, error) {
	bin, err := c.RecvFull(N)
	if err != nil {
		return "", err
	}
	return hex.Dump(bin), nil
}

// RecvHex is similar to RecvFullHex but does not guarantee full read instead
// it creates a buffer of N bytes and returns whatever is returned by the connection
// for reading headers or initial bytes from the server this is usually used.
// for reading a fixed number of already known bytes (ex: body based on content-length) use RecvFull.
// @example
// ```javascript
// const net = require('nuclei/net');
// const conn = net.Open('tcp', 'acme.com:80');
// const data = conn.RecvHex(1024);
// ```
func (c *NetConn) RecvHex(N int) (string, error) {
	bin, err := c.Recv(N)
	if err != nil {
		return "", err
	}
	return hex.Dump(bin), nil
}

package net

import (
	"bufio"
	"bytes"
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

func TestGetTimeoutFromContext(t *testing.T) {
	t.Run("default when missing", func(t *testing.T) {
		require.Equal(t, defaultTimeout, getTimeoutFromContext(context.Background()))
	})

	t.Run("reads TcpReadTimeout", func(t *testing.T) {
		expected := 15 * time.Second
		tv := &types.Timeouts{TcpReadTimeout: expected}
		ctx := context.WithValue(context.Background(), "timeoutVariants", tv) // nolint: staticcheck
		require.Equal(t, expected, getTimeoutFromContext(ctx))
	})
}

func TestBufferedConn(t *testing.T) {
	t.Run("read drains buffered bytes first", func(t *testing.T) {
		underlying := &bytes.Buffer{}
		underlying.WriteString("hello world")

		br := bufio.NewReader(underlying)
		_, _ = br.Peek(5)

		conn := &bufferedConn{
			Conn:   &fakeConn{},
			reader: br,
		}

		buf := make([]byte, 64)
		n, err := conn.Read(buf)
		require.NoError(t, err)
		require.Equal(t, "hello world", string(buf[:n]))
	})

	t.Run("read returns EOF after buffer is drained", func(t *testing.T) {
		underlying := bytes.NewBufferString("data")
		br := bufio.NewReader(underlying)
		conn := &bufferedConn{Conn: &fakeConn{}, reader: br}

		buf := make([]byte, 64)
		n, err := conn.Read(buf)
		require.NoError(t, err)
		require.Equal(t, "data", string(buf[:n]))

		_, err = conn.Read(buf)
		require.ErrorIs(t, err, io.EOF)
	})
}

// directDial is a plain net.Dialer for tests (no fastdialer dependency).
var directDial = (&net.Dialer{Timeout: 5 * time.Second}).DialContext

func TestDialHTTPProxy(t *testing.T) {
	t.Run("successful CONNECT tunnel", func(t *testing.T) {
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		require.NoError(t, err)
		defer func() { _ = ln.Close() }()

		targetPayload := "hello from target"
		go func() {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			defer func() { _ = conn.Close() }()

			req, err := http.ReadRequest(bufio.NewReader(conn))
			if err != nil {
				return
			}
			_ = req.Body.Close()

			_, _ = conn.Write([]byte("HTTP/1.1 200 Connection Established\r\n\r\n"))
			_, _ = conn.Write([]byte(targetPayload))
		}()

		ctx := context.Background()
		proxyURL := fmt.Sprintf("http://%s", ln.Addr().String())
		conn, err := dialHTTPProxy(ctx, directDial, proxyURL, "example.com:443", 5*time.Second)
		require.NoError(t, err)
		defer func() { _ = conn.Close() }()

		buf := make([]byte, 64)
		n, err := conn.Read(buf)
		require.NoError(t, err)
		require.Equal(t, targetPayload, string(buf[:n]))
	})

	t.Run("proxy returns non-200 status", func(t *testing.T) {
		ln, err := net.Listen("tcp", "127.0.0.1:0")
		require.NoError(t, err)
