	pkt = "\x00\x00\x00\xc0\xfeSMB@\x00\x00\x00\x00\x00\x00\x00\x00\x00\x1f\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00$\x00\x08\x00\x01\x00\x00\x00\x7f\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00x\x00\x00\x00\x02\x00\x00\x00\x02\x02\x10\x02\"\x02$\x02\x00\x03\x02\x03\x10\x03\x11\x03\x00\x00\x00\x00\x01\x00&\x00\x00\x00\x00\x00\x01\x00 \x00\x01\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x03\x00\n\x00\x00\x00\x00\x00\x01\x00\x00\x00\x01\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x00"
)

// DetectSMBGhost tries to detect SMBGhost vulnerability
// by using SMBv3 compression feature.
// If the host is vulnerable, it returns true.
// @example
// ```javascript
// const smb = require('nuclei/smb');
// const isSMBGhost = smb.DetectSMBGhost('acme.com', 445);
// ```
func (c *SMBClient) DetectSMBGhost(ctx context.Context, host string, port int) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	return memoizeddetectSMBGhost(ctx, executionId, host, port)
}

// @memo
func detectSMBGhost(ctx context.Context, executionId string, host string, port int) (bool, error) {
	if !protocolstate.IsHostAllowed(executionId, host) {
		// host is not valid according to network policy
		return false, protocolstate.ErrHostDenied.Msgf(host)
	}
	addr := net.JoinHostPort(host, strconv.Itoa(port))
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return false, fmt.Errorf("dialers not initialized for %s", executionId)
	}
	conn, err := dialer.Fastdialer.Dial(ctx, "tcp", addr)
	if err != nil {
		return false, err

	}
	defer func() {
		_ = conn.Close()
	}()

	_, err = conn.Write([]byte(pkt))
	if err != nil {
		return false, err
	}
	buff, _ := reader.ConnReadNWithTimeout(conn, 4, time.Duration(5)*time.Second)
	args, err := structs.Unpack(">I", buff)
	if err != nil {
		return false, err
	}
	if len(args) != 1 {
		return false, errors.New("invalid response")
	}

	length := args[0].(int)
	_ = conn.SetReadDeadline(time.Now().Add(2 * time.Second))
	data, err := reader.ConnReadNWithTimeout(conn, int64(length), time.Duration(5)*time.Second)
	if err != nil {
		return false, err
	}
	if len(data) < 72 {
		return false, errors.New("invalid response expected at least 72 bytes")
	}

	if !bytes.Equal(data[68:70], []byte("\x11\x03")) || !bytes.Equal(data[70:72], []byte("\x02\x00")) {
		return false, nil
	}
	return true, nil
}

package smbsession

import (
	"fmt"
	"path"
	"strings"
)

// ParseIdentity splits DOMAIN\user, domain/user, or user@domain into domain and username.
func ParseIdentity(user string) (domain, username string) {
	user = strings.TrimSpace(user)
	if user == "" {
		return "", ""
	}
	if i := strings.IndexByte(user, '\\'); i >= 0 {
		return user[:i], user[i+1:]
	}
	if i := strings.IndexByte(user, '/'); i >= 0 {
		return user[:i], user[i+1:]
	}
	if i := strings.LastIndexByte(user, '@'); i > 0 {
		return user[i+1:], user[:i]
	}
	return "", user
}

// NormalizeSharePath converts an SMB share-relative path to a clean form
// (forward slashes, no leading slash, "." for share root). Rejects ".." escapes.
func NormalizeSharePath(p string) (string, error) {
	p = strings.TrimSpace(p)
	p = strings.ReplaceAll(p, `\`, `/`)
	p = strings.Trim(p, `/`)
	if p == "" || p == "." {
		return ".", nil
	}
	if strings.ContainsRune(p, 0) {
		return "", fmt.Errorf("share path contains NUL")
	}
	clean := path.Clean(p)
	clean = strings.TrimPrefix(clean, "/")
	if clean == ".." || strings.HasPrefix(clean, "../") {
		return "", fmt.Errorf("share path escapes share root: %q", p)
	}
	if clean == "." {
		return ".", nil
	}
	return clean, nil
}

// RequireShareName validates a share name (no path separators).
func RequireShareName(share string) error {
	share = strings.TrimSpace(share)
	if share == "" {
		return fmt.Errorf("share name cannot be empty")
	}
	if strings.ContainsAny(share, `/\`) {
		return fmt.Errorf("share name must not contain path separators: %q", share)
	}
	if strings.ContainsRune(share, 0) {
		return fmt.Errorf("share name contains NUL")
	}
	return nil
}

package smbsession

import (
	"context"
	"fmt"
	"io"
	"os"
	"path"
	"strings"
	"sync"
	"time"

	gpsession "github.com/projectdiscovery/goimpacket/pkg/session"
	gpsmb "github.com/projectdiscovery/goimpacket/pkg/smb"

	"github.com/projectdiscovery/nuclei/v3/pkg/js/libs/gptransport"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
)

const (
	// DefaultMaxReadBytes caps remote file reads into memory.
	DefaultMaxReadBytes = 10 << 20 // 10 MiB
	// DefaultMaxTreeDepth caps recursive tree walks.
	DefaultMaxTreeDepth = 8
	// DefaultMaxTreeEntries caps how many tree entries are collected.
	DefaultMaxTreeEntries = 1024
)

// Creds holds NTLM (password or hash) credentials for Dial.
type Creds struct {
	User     string
	Password string
	Domain   string
	Hash     string // optional NT hash; when set, preferred over password
}

// Entry is a share-relative file or directory record.
type Entry struct {
	Name    string `json:"name"`
	Size    int64  `json:"size"`
	IsDir   bool   `json:"is_dir"`
	ModTime string `json:"mod_time,omitempty"`
}

// shareBackend is the subset of goimpacket SMB client used for share I/O.
// Tests substitute a fake implementation.
type shareBackend interface {
	UseShare(name string) error
	Ls(dir string) ([]os.FileInfo, error)
	Cat(file string) (string, error)
	ListShares() ([]string, error)
}

// shareOpener is an optional extension for streaming reads with a byte cap.
type shareOpener interface {
	Open(file string) (io.ReadCloser, error)
}

// Session wraps an authenticated goimpacket SMB client.
type Session struct {
	client    *gpsmb.Client
	backend   shareBackend // when set (tests), used instead of client
	closed    chan struct{}
	closeOnce sync.Once
}

// Dial connects and authenticates to host:port using the execution's dialer.
func Dial(ctx context.Context, executionID, host string, port int, creds Creds) (*Session, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if !protocolstate.IsHostAllowed(executionID, host) {
		return nil, protocolstate.ErrHostDenied.Msgf(host)
	}
	if port <= 0 {
		port = 445
	}
	domain, user := ParseIdentity(creds.User)
	if creds.Domain != "" {
		domain = creds.Domain
	}
	if user == "" {
		user = strings.TrimSpace(creds.User)
	}

	gpCreds := &gpsession.Credentials{
		Domain:   domain,
		Username: user,
		Password: creds.Password,
		Hash:     creds.Hash,
	}
	target := gpsession.Target{Host: host, Port: port}
	client := gpsmb.NewClientWithDialer(target, gpCreds, gptransport.NewExecDialer(executionID))

	if err := client.ConnectContext(ctx); err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return nil, ctxErr
		}
		return nil, err
	}
	return &Session{client: client}, nil
}

// FromClient wraps an already-connected goimpacket SMB client (e.g. dcerpc's).
func FromClient(client *gpsmb.Client) *Session {
	return &Session{client: client, closed: make(chan struct{})}
}

// Close tears down the SMB session. Safe on nil and idempotent.
func (s *Session) Close() {
	if s == nil {
		return
	}
	s.closeOnce.Do(func() {
		if s.closed != nil {
			close(s.closed)
		}
		if s.client != nil {
			s.client.Close()
		}
	})
}

// Native returns the underlying goimpacket client for advanced callers.
func (s *Session) Native() *gpsmb.Client {
	if s == nil {
		return nil
	}
	return s.client
}

func (s *Session) ops() shareBackend {
	if s == nil {
		return nil
	}
	if s.backend != nil {
		return s.backend
	}
	if s.client == nil {
		return nil
	}
	return s.client
}

// ListShares enumerates share names.
func (s *Session) ListShares() ([]string, error) {
	ops := s.ops()
	if ops == nil {
		return nil, fmt.Errorf("smb session not connected")
	}
	return ops.ListShares()
}

// ListDir lists one directory on share (share-relative path).
func (s *Session) ListDir(share, dir string) ([]Entry, error) {
	return s.ListDirContext(context.Background(), share, dir)
}

// ListDirContext lists one directory and stops waiting when ctx is cancelled
// by closing the session, matching Dial.
func (s *Session) ListDirContext(ctx context.Context, share, dir string) ([]Entry, error) {
	ops := s.ops()
	if ops == nil {
		return nil, fmt.Errorf("smb session not connected")
	}
	return s.awaitEntries(ctx, func(ctx context.Context) ([]Entry, error) {
		return listDir(ctx, ops, share, dir)
	})
}

// ReadFile reads a file from share, capped at maxBytes (default DefaultMaxReadBytes).
func (s *Session) ReadFile(share, filePath string, maxBytes int64) (string, error) {
	ops := s.ops()
	if ops == nil {
		return "", fmt.Errorf("smb session not connected")
	}
	return readFile(ops, share, filePath, maxBytes)
}

// ListTree walks share directories up to maxDepth / maxEntries.
func (s *Session) ListTree(share, root string, maxDepth, maxEntries int) ([]Entry, error) {
	return s.ListTreeContext(context.Background(), share, root, maxDepth, maxEntries)
}

// ListTreeContext walks share directories and stops waiting when ctx is cancelled
// by closing the session, matching Dial.
func (s *Session) ListTreeContext(ctx context.Context, share, root string, maxDepth, maxEntries int) ([]Entry, error) {
	ops := s.ops()
	if ops == nil {
		return nil, fmt.Errorf("smb session not connected")
	}
	return s.awaitEntries(ctx, func(ctx context.Context) ([]Entry, error) {
		return listTree(ctx, ops, share, root, maxDepth, maxEntries)
	})
}

func (s *Session) awaitEntries(ctx context.Context, fn func(context.Context) ([]Entry, error)) ([]Entry, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	type rec struct {
		entries []Entry
		err     error
	}
	ch := make(chan rec, 1)
	go func() {
		entries, err := fn(ctx)
		ch <- rec{entries, err}
	}()
	select {
	case <-ctx.Done():
		s.Close()
		<-ch
		return nil, ctx.Err()
	case r := <-ch:
		return r.entries, r.err
	}
}

func listDir(ctx context.Context, ops shareBackend, share, dir string) ([]Entry, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := RequireShareName(share); err != nil {
		return nil, err
	}
	normalized, err := NormalizeSharePath(dir)
	if err != nil {
		return nil, err
	}
	if err := ops.UseShare(share); err != nil {
		return nil, fmt.Errorf("mount share %q: %w", share, err)
	}
	infos, err := ops.Ls(normalized)
	if err != nil {
		return nil, err
	}
	out := make([]Entry, 0, len(infos))
	for _, fi := range infos {
		name := fi.Name()
		if name == "." || name == ".." {
			continue
		}
		out = append(out, fileInfoToEntry(fi))
	}
	return out, nil
}

func readFile(ops shareBackend, share, filePath string, maxBytes int64) (string, error) {
	if err := RequireShareName(share); err != nil {
		return "", err
	}
	if maxBytes <= 0 {
		maxBytes = DefaultMaxReadBytes
	}
	normalized, err := NormalizeSharePath(filePath)
	if err != nil {
		return "", err
	}
	if normalized == "." {
		return "", fmt.Errorf("file path cannot be empty")
	}
	if err := ops.UseShare(share); err != nil {
		return "", fmt.Errorf("mount share %q: %w", share, err)
	}
	// Prefer streaming Open+LimitReader when the backend supports it (tests /
	// future goimpacket Open). Fall back to Cat for the stock client.
	if opener, ok := ops.(shareOpener); ok {
		f, err := opener.Open(normalized)
		if err != nil {
			return "", err
		}
		defer func() { _ = f.Close() }()
		limited := io.LimitReader(f, maxBytes+1)
		body, err := io.ReadAll(limited)
		if err != nil {
			return "", err
		}
		if int64(len(body)) > maxBytes {
			return "", fmt.Errorf("file %q exceeds max read size of %d bytes", normalized, maxBytes)
		}
		return string(body), nil
	}
	body, err := ops.Cat(normalized)
	if err != nil {
		return "", err
	}
	if int64(len(body)) > maxBytes {
		return "", fmt.Errorf("file %q exceeds max read size of %d bytes", normalized, maxBytes)
	}
	return body, nil
}

func listTree(ctx context.Context, ops shareBackend, share, root string, maxDepth, maxEntries int) ([]Entry, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if err := RequireShareName(share); err != nil {
		return nil, err
	}
	if maxDepth <= 0 {
		maxDepth = DefaultMaxTreeDepth
	}
	if maxEntries <= 0 {
		maxEntries = DefaultMaxTreeEntries
	}
	normalized, err := NormalizeSharePath(root)
	if err != nil {
		return nil, err
	}
	if err := ops.UseShare(share); err != nil {
		return nil, fmt.Errorf("mount share %q: %w", share, err)
	}

	var out []Entry
	var walk func(rel string, depth int) error
	walk = func(rel string, depth int) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if len(out) >= maxEntries {
			return fmt.Errorf("tree listing exceeded max entries (%d)", maxEntries)
		}
		infos, err := ops.Ls(rel)
		if err != nil {
			return err
		}
		for _, fi := range infos {
			name := fi.Name()
			if name == "." || name == ".." {
				continue
			}
			childRel := name
			if rel != "." && rel != "" {
				childRel = path.Join(rel, name)
			}
			entry := fileInfoToEntry(fi)
			entry.Name = childRel
			out = append(out, entry)
			if len(out) >= maxEntries {
				return fmt.Errorf("tree listing exceeded max entries (%d)", maxEntries)
			}
			if fi.IsDir() && depth < maxDepth {
				if err := walk(childRel, depth+1); err != nil {
					return err
				}
			}
		}
		return nil
	}
	if err := walk(normalized, 1); err != nil {
		return out, err
	}
	return out, nil
}

func fileInfoToEntry(fi os.FileInfo) Entry {
	entry := Entry{Name: fi.Name(), Size: fi.Size(), IsDir: fi.IsDir()}
	if mt := fi.ModTime(); !mt.IsZero() {
		entry.ModTime = mt.UTC().Format(time.RFC3339)
	}
	return entry
}

