type fakeNode struct {
	name    string
	size    int64
	isDir   bool
	content string
}

type fakeBackend struct {
	dirs    map[string][]fakeNode
	shares  []string
	mounted string
}

type hangBackend struct {
	fakeBackend
	started   chan struct{}
	startOnce sync.Once
	wait      <-chan struct{}
}

func (h *hangBackend) Ls(string) ([]os.FileInfo, error) {
	h.startOnce.Do(func() { close(h.started) })
	<-h.wait
	return nil, context.Canceled
}

func newFakeBackend(dirs map[string][]fakeNode) *fakeBackend {
	if dirs == nil {
		dirs = map[string][]fakeNode{}
	}
	return &fakeBackend{dirs: dirs}
}

func (f *fakeBackend) UseShare(name string) error {
	f.mounted = name
	return nil
}

func (f *fakeBackend) ListShares() ([]string, error) {
	return append([]string(nil), f.shares...), nil
}

func (f *fakeBackend) Ls(dirname string) ([]os.FileInfo, error) {
	dirname = path.Clean(strings.Trim(strings.ReplaceAll(dirname, `\`, `/`), "/"))
	if dirname == "" {
		dirname = "."
	}
	nodes, ok := f.dirs[dirname]
	if !ok {
		return nil, &os.PathError{Op: "readdir", Path: dirname, Err: fs.ErrNotExist}
	}
	out := make([]os.FileInfo, 0, len(nodes))
	for _, n := range nodes {
		out = append(out, n.info())
	}
	return out, nil
}

func (f *fakeBackend) Cat(name string) (string, error) {
	rc, err := f.Open(name)
	if err != nil {
		return "", err
	}
	defer func() { _ = rc.Close() }()
	body, err := io.ReadAll(rc)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

func (f *fakeBackend) Open(name string) (io.ReadCloser, error) {
	name = path.Clean(strings.Trim(strings.ReplaceAll(name, `\`, `/`), "/"))
	dir, base := path.Split(name)
	dir = strings.Trim(dir, "/")
	if dir == "" {
		dir = "."
	}
	nodes, ok := f.dirs[dir]
	if !ok {
		return nil, &os.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
	}
	for _, n := range nodes {
		if n.name == base {
			if n.isDir {
				return nil, &os.PathError{Op: "open", Path: name, Err: fs.ErrInvalid}
			}
			return io.NopCloser(strings.NewReader(n.content)), nil
		}
	}
	return nil, &os.PathError{Op: "open", Path: name, Err: fs.ErrNotExist}
}

func (n fakeNode) info() os.FileInfo {
	return fakeFileInfo{n: n, mod: time.Unix(1, 0).UTC()}
}

type fakeFileInfo struct {
	n   fakeNode
	mod time.Time
}

func (f fakeFileInfo) Name() string { return f.n.name }
func (f fakeFileInfo) Size() int64  { return f.n.size }
func (f fakeFileInfo) Mode() os.FileMode {
	if f.n.isDir {
		return fs.ModeDir | 0755
	}
	return 0644
}
func (f fakeFileInfo) ModTime() time.Time { return f.mod }
func (f fakeFileInfo) IsDir() bool        { return f.n.isDir }
func (f fakeFileInfo) Sys() any           { return nil }

package smtp

import (
	"bufio"
	"bytes"
	"net/textproto"
	"strings"
)

type (
	// SMTPMessage is a message to be sent over SMTP
	// @example
	// ```javascript
	// const smtp = require('nuclei/smtp');
	// const message = new smtp.SMTPMessage();
	// message.From('xyz@projectdiscovery.io');
	// ```
	SMTPMessage struct {
		from string
		to   []string
		sub  string
		msg  []byte
		user string
		pass string
	}
)

// From adds the from field to the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.From('xyz@projectdiscovery.io');
// ```
func (s *SMTPMessage) From(email string) *SMTPMessage {
	s.from = email
	return s
}

// To adds the to field to the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.To('xyz@projectdiscovery.io');
// ```
func (s *SMTPMessage) To(email string) *SMTPMessage {
	s.to = append(s.to, email)
	return s
}

// Subject adds the subject field to the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.Subject('hello');
// ```
func (s *SMTPMessage) Subject(sub string) *SMTPMessage {
	s.sub = sub
	return s
}

// Body adds the message body to the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.Body('hello');
// ```
func (s *SMTPMessage) Body(msg []byte) *SMTPMessage {
	s.msg = msg
	return s
}

// Auth when called authenticates using username and password before sending the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.Auth('username', 'password');
// ```
func (s *SMTPMessage) Auth(username, password string) *SMTPMessage {
	s.user = username
	s.pass = password
	return s
}

// String returns the string representation of the message
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.From('xyz@projectdiscovery.io');
// message.To('xyz2@projectdiscoveyr.io');
// message.Subject('hello');
// message.Body('hello');
// log(message.String());
// ```
func (s *SMTPMessage) String() string {
	var buff bytes.Buffer
	tw := textproto.NewWriter(bufio.NewWriter(&buff))
	_ = tw.PrintfLine("To: %s", strings.Join(s.to, ","))
	if s.sub != "" {
		_ = tw.PrintfLine("Subject: %s", s.sub)
	}
	_ = tw.PrintfLine("\r\n%s", s.msg)
	return buff.String()
}

package smtp

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"net"
	"net/smtp"
	"strconv"
	"time"

	"github.com/praetorian-inc/fingerprintx/pkg/plugins"
	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"

	pluginsmtp "github.com/praetorian-inc/fingerprintx/pkg/plugins/services/smtp"
)

type (
	// SMTPResponse is the response from the IsSMTP function.
	// @example
	// ```javascript
	// const smtp = require('nuclei/smtp');
	// const client = new smtp.Client('acme.com', 25);
	// const isSMTP = client.IsSMTP();
	// log(isSMTP)
	// ```
	SMTPResponse struct {
		IsSMTP bool
		Banner string
	}
)

type (
	// Client is a minimal SMTP client for nuclei scripts.
	// @example
	// ```javascript
	// const smtp = require('nuclei/smtp');
	// const client = new smtp.Client('acme.com', 25);
	// ```
	Client struct {
		nj   *utils.NucleiJS
		host string
		port string
	}
)

// Constructor for SMTP Client
// Constructor: constructor(public host: string, public port: string)
func NewSMTPClient(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	// setup nucleijs utils
	c := &Client{nj: utils.NewNucleiJS(runtime)}
	c.nj.ObjectSig = "Client(host, port)" // will be included in error messages

	host, _ := c.nj.GetArg(call.Arguments, 0).(string) // host
	port, _ := c.nj.GetArg(call.Arguments, 1).(string) // port

	// validate arguments
	c.nj.Require(host != "", "host cannot be empty")
	c.nj.Require(port != "", "port cannot be empty")

	// validate port
	portInt, err := strconv.Atoi(port)
	c.nj.Require(err == nil && portInt > 0 && portInt < 65536, "port must be a valid number")
	c.host = host
	c.port = port

	executionId := c.nj.ExecutionId()

	// check if this is allowed address
	c.nj.Require(protocolstate.IsHostAllowed(executionId, host+":"+port), protocolstate.ErrHostDenied.Msgf(host+":"+port).Error())

	// Link Constructor to Client and return
	return utils.LinkConstructor(call, runtime, c)
}

// IsSMTP checks if a host is running a SMTP server.
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const client = new smtp.Client('acme.com', 25);
// const isSMTP = client.IsSMTP();
// log(isSMTP)
// ```
func (c *Client) IsSMTP() (SMTPResponse, error) {
	resp := SMTPResponse{}
	c.nj.Require(c.host != "", "host cannot be empty")
	c.nj.Require(c.port != "", "port cannot be empty")

	timeout := 5 * time.Second

	executionId := c.nj.ExecutionId()
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return SMTPResponse{}, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	conn, err := dialer.Fastdialer.Dial(c.nj.Context(), "tcp", net.JoinHostPort(c.host, c.port))
	if err != nil {
		return resp, err
	}
	defer func() {
		_ = conn.Close()
	}()

	smtpPlugin := pluginsmtp.SMTPPlugin{}
	service, err := smtpPlugin.Run(conn, timeout, plugins.Target{Host: c.host})
	if err != nil {
		return resp, err
	}
	if service == nil {
		return resp, nil
	}
	resp.Banner = service.Version
	resp.IsSMTP = true
	return resp, nil
}

// IsOpenRelay checks if a host is an open relay.
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.From('xyz@projectdiscovery.io');
// message.To('xyz2@projectdiscoveyr.io');
// message.Subject('hello');
// message.Body('hello');
// const client = new smtp.Client('acme.com', 25);
// const isRelay = client.IsOpenRelay(message);
// ```
func (c *Client) IsOpenRelay(msg *SMTPMessage) (bool, error) {
	c.nj.Require(c.host != "", "host cannot be empty")
	c.nj.Require(c.port != "", "port cannot be empty")

	executionId := c.nj.ExecutionId()
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return false, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	addr := net.JoinHostPort(c.host, c.port)
	conn, err := dialer.Fastdialer.Dial(c.nj.Context(), "tcp", addr)
	if err != nil {
		return false, err
	}
	defer func() {
		_ = conn.Close()
	}()
	// net/smtp reads with no deadline, and an interrupt cannot stop the runtime inside that
	// read: closing on cancel is what keeps a server that never answers from pinning it.
	defer context.AfterFunc(c.nj.Context(), func() { _ = conn.Close() })()
	client, err := smtp.NewClient(&limitedConn{Conn: conn, remaining: maxReadBytes}, c.host)
	if err != nil {
		return false, err
	}
	if err := client.Mail(msg.from); err != nil {
		return false, err
	}
	if len(msg.to) == 0 || len(msg.to) > 1 {
		return false, fmt.Errorf("invalid number of recipients: required 1, got %d", len(msg.to))
	}
	if err := client.Rcpt(msg.to[0]); err != nil {
		return false, err
	}

	// Send the email body.
	wc, err := client.Data()
	if err != nil {
		return false, err
	}

	_, err = wc.Write([]byte(msg.String()))
	if err != nil {
		return false, err
	}
	err = wc.Close()
	if err != nil {
		return false, err
	}
	// Send the QUIT command and close the connection.
	err = client.Quit()
	if err != nil {
		return false, err
	}
	return true, nil
}

// SendMail sends an email using the SMTP protocol.
// @example
// ```javascript
// const smtp = require('nuclei/smtp');
// const message = new smtp.SMTPMessage();
// message.From('xyz@projectdiscovery.io');
// message.To('xyz2@projectdiscoveyr.io');
// message.Subject('hello');
// message.Body('hello');
// const client = new smtp.Client('acme.com', 25);
// const isSent = client.SendMail(message);
// log(isSent)
// ```
func (c *Client) SendMail(msg *SMTPMessage) (bool, error) {
	c.nj.Require(c.host != "", "host cannot be empty")
	c.nj.Require(c.port != "", "port cannot be empty")

	var auth smtp.Auth
	if msg.user != "" && msg.pass != "" {
		auth = smtp.PlainAuth("", msg.user, msg.pass, c.host)
	}

	if err := c.sendMail(auth, msg); err != nil {
		c.nj.Throw("failed to send mail with message(%s) got %v", msg.String(), err)
	}
	return true, nil
}

// sendMail is smtp.SendMail over the execution's dialer. smtp.SendMail dials on its own,
// past the network policy, so nothing could bound what it reads or close it on cancel.
func (c *Client) sendMail(auth smtp.Auth, msg *SMTPMessage) error {
	executionId := c.nj.ExecutionId()
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return fmt.Errorf("dialers not initialized for %s", executionId)
	}

	conn, err := dialer.Fastdialer.Dial(c.nj.Context(), "tcp", net.JoinHostPort(c.host, c.port))
	if err != nil {
		return err
	}
	defer func() {
		_ = conn.Close()
	}()
	defer context.AfterFunc(c.nj.Context(), func() { _ = conn.Close() })()

	client, err := smtp.NewClient(&limitedConn{Conn: conn, remaining: maxReadBytes}, c.host)
	if err != nil {
		return err
	}
	if ok, _ := client.Extension("STARTTLS"); ok {
		if err := client.StartTLS(&tls.Config{ServerName: c.host}); err != nil {
			return err
		}
	}
	if auth != nil {
		if ok, _ := client.Extension("AUTH"); !ok {
			return errors.New("smtp: server doesn't support AUTH")
		}
		if err := client.Auth(auth); err != nil {
			return err
		}
	}
	if err := client.Mail(msg.from); err != nil {
		return err
	}
	for _, to := range msg.to {
		if err := client.Rcpt(to); err != nil {
			return err
		}
	}
	wc, err := client.Data()
	if err != nil {
		return err
	}
	if _, err := wc.Write([]byte(msg.String())); err != nil {
		return err
	}
	if err := wc.Close(); err != nil {
		return err
	}
	return client.Quit()
}

// maxReadBytes bounds what one connection may read. net/smtp reads replies through
// net/textproto, which buffers a line until "\n" with no limit; a whole dialogue, TLS
// handshake included, fits in tens of kilobytes.
const maxReadBytes = 1 << 20

var errReadLimit = fmt.Errorf("smtp: server sent more than %d bytes", maxReadBytes)

// limitedConn fails reads once remaining is spent.
type limitedConn struct {
	net.Conn
	remaining int64
}

func (c *limitedConn) Read(b []byte) (int, error) {
	if c.remaining <= 0 {
		return 0, errReadLimit
	}
	if int64(len(b)) > c.remaining {
		b = b[:c.remaining]
	}
	n, err := c.Conn.Read(b)
	c.remaining -= int64(n)
	return n, err
}

package smtp

import (
	"bytes"
	"context"
	"net"
	"net/textproto"
	"runtime"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

// A port that streams bytes without a newline used to be buffered whole: net/smtp reads replies
// through net/textproto, which reads a line until "\n" with no length limit.
func TestCallsBoundAReplyWithoutNewline(t *testing.T) {
	tests := []struct {
		name string
		call func(*Client, *SMTPMessage)
	}{
		{"SendMail", func(c *Client, m *SMTPMessage) { _, _ = c.SendMail(m) }},
		{"IsOpenRelay", func(c *Client, m *SMTPMessage) { _, _ = c.IsOpenRelay(m) }},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			listener := listenForLimitTest(t)
			go streamWithoutNewline(listener)
			client := newSMTPClientForLimitTest(t, listener.Addr().String())
			msg := (&SMTPMessage{}).From("scanner@example.com").To("admin@example.org")

			allocated := allocatedBy(func() {
				defer func() {
					_ = recover() // SendMail throws its error to the runtime
				}()
				tt.call(client, msg)
			})

			require.Less(t, allocated, uint64(64<<20), "allocated %d MiB reading one reply", allocated>>20)
		})
	}
}

// The cap must leave room for a normal dialogue.
func TestSendMailStillDeliversUnderTheReadLimit(t *testing.T) {
	listener := listenForLimitTest(t)
	received := serveOneSMTPSessionForLimitTest(listener)
	client := newSMTPClientForLimitTest(t, listener.Addr().String())

	msg := (&SMTPMessage{}).From("scanner@example.com").To("admin@example.org").Subject("hello").Body([]byte("world"))
	sent, err := client.SendMail(msg)
	require.NoError(t, err)
	require.True(t, sent)

	select {
	case data := <-received:
		require.Contains(t, data, "Subject: hello")
		require.Contains(t, data, "world")
	case <-time.After(5 * time.Second):
		t.Fatal("the server never saw the message")
	}
}

func newSMTPClientForLimitTest(t *testing.T, addr string) *Client {
	t.Helper()

	executionID := "smtp-" + strings.NewReplacer("/", "-", " ", "-").Replace(t.Name())
	require.NoError(t, protocolstate.Init(&types.Options{ExecutionId: executionID}))
	t.Cleanup(func() {
		protocolstate.Close(executionID)
	})

	vm := goja.New()
	vm.SetContextValue("executionId", executionID)
	vm.SetContextValue("ctx", context.Background())

	host, port, err := net.SplitHostPort(addr)
	require.NoError(t, err)
	obj, err := vm.New(vm.ToValue(NewSMTPClient), vm.ToValue(host), vm.ToValue(port))
	require.NoError(t, err)
	client, ok := obj.Export().(*Client)
	require.True(t, ok, "expected *Client export, got %T", obj.Export())

	return client
}

func listenForLimitTest(t *testing.T) net.Listener {
	t.Helper()

	listener, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	t.Cleanup(func() {
		_ = listener.Close()
	})

	return listener
}

// streamWithoutNewline sends 256 MiB without a newline to each connection: bounded so the test
// cannot exhaust the machine when the limit is missing.
func streamWithoutNewline(listener net.Listener) {
	const streamBytes = 256 << 20
	chunk := bytes.Repeat([]byte("A"), 32<<10)
	for {
		conn, err := listener.Accept()
		if err != nil {
			return
		}
		go func() {
			defer func() {
				_ = conn.Close()
			}()
			for sent := 0; sent < streamBytes; sent += len(chunk) {
				if _, err := conn.Write(chunk); err != nil {
					return
				}
			}
		}()
	}
}

// allocatedBy reports how many bytes call allocated, freed or not.
func allocatedBy(call func()) uint64 {
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	call()
	runtime.ReadMemStats(&after)
	return after.TotalAlloc - before.TotalAlloc
}

// serveOneSMTPSessionForLimitTest answers a single session like a minimal MTA with no
// extensions, and reports the DATA it was sent once the client quits.
func serveOneSMTPSessionForLimitTest(listener net.Listener) <-chan string {
	received := make(chan string, 1)
	go func() {
		conn, err := listener.Accept()
		if err != nil {
			return
		}
		defer func() {
			_ = conn.Close()
		}()

		tp := textproto.NewConn(conn)
		var data string
		_ = tp.PrintfLine("220 test ESMTP")
		for {
			line, err := tp.ReadLine()
			if err != nil {
				return
			}
			switch verb, _, _ := strings.Cut(line, " "); strings.ToUpper(verb) {
			case "EHLO", "HELO":
				_ = tp.PrintfLine("250 test")
			case "MAIL", "RCPT":
				_ = tp.PrintfLine("250 ok")
			case "DATA":
				_ = tp.PrintfLine("354 go ahead")
				body, err := tp.ReadDotBytes()
				if err != nil {
					return
				}
				data = string(body)
				_ = tp.PrintfLine("250 queued")
			case "QUIT":
				_ = tp.PrintfLine("221 bye")
				received <- data
				return
			default:
				_ = tp.PrintfLine("502 not implemented")
			}
		}
	}()
	return received
}

package smtp

import (
	"context"
	"net"
	"net/textproto"
	"strings"
	"testing"
	"time"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

type receivedMail struct {
	from string
	to   []string
	data string
}

func TestSendMailDeliversTheMessage(t *testing.T) {
	listener := listenForTest(t)
	received := serveOneSMTPSession(listener)
	client := newSMTPClientForTest(t, context.Background(), listener.Addr().String())

	msg := (&SMTPMessage{}).From("scanner@example.com").To("admin@example.org").Subject("hello").Body([]byte("world"))
	sent, err := client.SendMail(msg)
	if err != nil || !sent {
		t.Fatalf("SendMail() = %v, %v; want true, nil", sent, err)
	}

	select {
	case mail := <-received:
		if !strings.Contains(mail.from, "<scanner@example.com>") {
			t.Errorf("MAIL command = %q, want the sender", mail.from)
		}
		if len(mail.to) != 1 || !strings.Contains(mail.to[0], "<admin@example.org>") {
			t.Errorf("RCPT commands = %q, want the one recipient", mail.to)
		}
		if !strings.Contains(mail.data, "Subject: hello") || !strings.Contains(mail.data, "world") {
			t.Errorf("DATA = %q, want the subject and body", mail.data)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the server never saw the session end")
	}
}

// A server that accepts and never answers used to keep these calls, and the runtime
// abandoned around them, blocked for the life of the process.
func TestCallsReturnWhenTheContextIsDone(t *testing.T) {
	tests := []struct {
		name string
		call func(*Client, *SMTPMessage)
	}{
		{"SendMail", func(c *Client, m *SMTPMessage) { _, _ = c.SendMail(m) }},
		{"IsOpenRelay", func(c *Client, m *SMTPMessage) { _, _ = c.IsOpenRelay(m) }},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			listener := listenForTest(t)
			go holdConnections(listener)

			ctx, cancel := context.WithCancel(context.Background())
			defer cancel()
			client := newSMTPClientForTest(t, ctx, listener.Addr().String())
			msg := (&SMTPMessage{}).From("scanner@example.com").To("admin@example.org")

			done := make(chan struct{})
			go func() {
				defer close(done)
				defer func() {
					_ = recover() // SendMail throws its error to the runtime
				}()
				tt.call(client, msg)
			}()

			select {
			case <-done:
				t.Fatal("returned before the server answered or the context was done")
			case <-time.After(200 * time.Millisecond):
			}

			cancel()
			select {
			case <-done:
			case <-time.After(5 * time.Second):
				t.Fatal("still blocked after the context was done")
			}
		})
	}
}

func newSMTPClientForTest(t *testing.T, ctx context.Context, addr string) *Client {
	t.Helper()

	executionID := "smtp-" + strings.NewReplacer("/", "-", " ", "-").Replace(t.Name())
	if err := protocolstate.Init(&types.Options{ExecutionId: executionID}); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		protocolstate.Close(executionID)
	})

	runtime := goja.New()
	runtime.SetContextValue("executionId", executionID)
	runtime.SetContextValue("ctx", ctx)

	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		t.Fatal(err)
	}
	obj, err := runtime.New(runtime.ToValue(NewSMTPClient), runtime.ToValue(host), runtime.ToValue(port))
	if err != nil {
		t.Fatal(err)
	}
	client, ok := obj.Export().(*Client)
	if !ok {
		t.Fatalf("expected *Client export, got %T", obj.Export())
	}
	return client
}

func listenForTest(t *testing.T) net.Listener {
	t.Helper()

	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		_ = listener.Close()
	})
	return listener
}

// holdConnections accepts and never answers, like a tarpit.
func holdConnections(listener net.Listener) {
	var held []net.Conn
	for {
		conn, err := listener.Accept()
		if err != nil {
			for _, c := range held {
				_ = c.Close()
			}
			return
		}
		held = append(held, conn)
	}
}

// serveOneSMTPSession answers a single session like a minimal MTA with no extensions,
// and reports what it was sent once the client quits.
func serveOneSMTPSession(listener net.Listener) <-chan receivedMail {
	received := make(chan receivedMail, 1)
	go func() {
		conn, err := listener.Accept()
		if err != nil {
			return
		}
		defer func() {
			_ = conn.Close()
		}()

		tp := textproto.NewConn(conn)
		var mail receivedMail
		_ = tp.PrintfLine("220 test ESMTP")
		for {
			line, err := tp.ReadLine()
			if err != nil {
				return
			}
			switch verb, _, _ := strings.Cut(line, " "); strings.ToUpper(verb) {
			case "EHLO", "HELO":
				_ = tp.PrintfLine("250 test")
			case "MAIL":
				mail.from = line
				_ = tp.PrintfLine("250 ok")
			case "RCPT":
				mail.to = append(mail.to, line)
				_ = tp.PrintfLine("250 ok")
			case "DATA":
				_ = tp.PrintfLine("354 go ahead")
				body, err := tp.ReadDotBytes()
				if err != nil {
					return
				}
				mail.data = string(body)
				_ = tp.PrintfLine("250 queued")
			case "QUIT":
				_ = tp.PrintfLine("221 bye")
				received <- mail
				return
			default:
				_ = tp.PrintfLine("502 not implemented")
			}
		}
	}()
	return received
}

package ssh

import (
	"context"
	"errors"
	"fmt"
	"net"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/utils/vardump"
	"github.com/projectdiscovery/utils/errkit"
	"github.com/zmap/zgrab2/lib/ssh"
)

type (
	// SSHClient is a client for SSH servers.
	// Internally client uses github.com/zmap/zgrab2/lib/ssh driver.
	// @example
	// ```javascript
	// const ssh = require('nuclei/ssh');
	// const client = new ssh.SSHClient();
	// ```
	SSHClient struct {
		// connection is nil when no connection is open.
		connection *ssh.Client
		timeout    time.Duration
	}
)

// precompiled regex patterns
var (
	passwordQuestionPattern = regexp.MustCompile(`(?i)(pass(word|phrase|code)?|pin)`)
	usernameQuestionPattern = regexp.MustCompile(`(?i)(user(name)?|login)`)
)

// SetTimeout sets the timeout for the SSH connection in seconds
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// client.SetTimeout(10);
// ```
func (c *SSHClient) SetTimeout(sec int) {
	c.timeout = time.Duration(sec) * time.Second
}

// Connect tries to connect to provided host and port
// with provided username and password with ssh.
// Returns state of connection and error. If error is not nil,
// state will be false
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// const connected = client.Connect('acme.com', 22, 'username', 'password');
// ```
func (c *SSHClient) Connect(ctx context.Context, host string, port int, username, password string) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	conn, err := connect(&connectOptions{
		Host:        host,
		Port:        port,
		User:        username,
		Password:    password,
		ExecutionId: executionId,
	})
	if err != nil {
		return false, err
	}
	c.connection = conn

	return true, nil
}

// ConnectWithKey tries to connect to provided host and port
// with provided username and private_key.
// Returns state of connection and error. If error is not nil,
// state will be false
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// const privateKey = `-----BEGIN RSA PRIVATE KEY----- ...`;
// const connected = client.ConnectWithKey('acme.com', 22, 'username', privateKey);
// ```
func (c *SSHClient) ConnectWithKey(ctx context.Context, host string, port int, username, key string) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	conn, err := connect(&connectOptions{
		Host:        host,
		Port:        port,
		User:        username,
		PrivateKey:  key,
		ExecutionId: executionId,
	})

	if err != nil {
		return false, err
	}
	c.connection = conn

	return true, nil
}

// ConnectSSHInfoMode tries to connect to provided host and port
// with provided host and port
// Returns HandshakeLog and error. If error is not nil,
// state will be false
// HandshakeLog is a struct that contains information about the
// ssh connection
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// const info = client.ConnectSSHInfoMode('acme.com', 22);
// log(to_json(info));
// ```
func (c *SSHClient) ConnectSSHInfoMode(ctx context.Context, host string, port int) (*ssh.HandshakeLog, error) {
	executionId := ctx.Value("executionId").(string)
	return memoizedconnectSSHInfoMode(ctx, &connectOptions{
		Host:        host,
		Port:        port,
		ExecutionId: executionId,
	})
}

// Run tries to open a new SSH session, then tries to execute
// the provided command in said session
// Returns string and error. If error is not nil,
// state will be false
// The string contains the command output
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// client.Connect('acme.com', 22, 'username', 'password');
// const output = client.Run('id');
// log(output);
// ```
func (c *SSHClient) Run(cmd string) (string, error) {
	if c.connection == nil {
		return "", errkit.New("no connection")
	}
	session, err := c.connection.NewSession()
	if err != nil {
		return "", err
	}
	defer func() {
		_ = session.Close()
	}()

	data, err := session.Output(cmd)
	if err != nil {
		return "", err
	}

	return string(data), nil
}

// Close closes the SSH connection and destroys the client
// Returns the success state and error. If error is not nil,
// state will be false. Close does nothing and returns true
// if no connection is open.
// @example
// ```javascript
// const ssh = require('nuclei/ssh');
// const client = new ssh.SSHClient();
// client.Connect('acme.com', 22, 'username', 'password');
// const closed = client.Close();
// ```
func (c *SSHClient) Close() (bool, error) {
	if c.connection == nil {
		return true, nil
	}

	err := c.connection.Close()
	c.connection = nil

	if err != nil {
		return false, err
	}

	return true, nil
}

// unexported functions
type connectOptions struct {
	Host        string
	Port        int
	User        string
	Password    string
	PrivateKey  string
	Timeout     time.Duration // default 10s
	ExecutionId string
}

func (c *connectOptions) validate() error {
	if c.Host == "" {
		return errkit.New("host is required")
	}
	if c.Port <= 0 {
		return errkit.New("port is required")
	}
	if !protocolstate.IsHostAllowed(c.ExecutionId, c.Host) {
		// host is not valid according to network policy
		return protocolstate.ErrHostDenied.Msgf(c.Host)
	}
	if c.Timeout == 0 {
		c.Timeout = 10 * time.Second
	}
	return nil
}

// errSSHInfoCacheMiss allows cache lookups without sharing an in-flight handshake.
var errSSHInfoCacheMiss = errors.New("SSH info cache miss")

// memoizedconnectSSHInfoMode reuses completed successes while keeping each
// uncached handshake independently cancellable. Cache publication is best effort.
func memoizedconnectSSHInfoMode(ctx context.Context, opts *connectOptions) (*ssh.HandshakeLog, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	hash := "connectSSHInfoMode:" + fmt.Sprint(opts)
	value, err, _ := protocolstate.Memoizer.Do(hash, func() (interface{}, error) {
		return nil, errSSHInfoCacheMiss
	})
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err == nil {
		return value.(*ssh.HandshakeLog), nil
	}
	// Each cache miss owns its connection, so canceling one caller cannot close
	// another caller's handshake. Only completed successes are shared.
	data, err := connectSSHInfoMode(ctx, opts)
	if err != nil {
		return nil, err
	}
	// A concurrent cache lookup may share this short call and return a cache
	// miss. Caching is best effort; the completed handshake still succeeded.
	_, _, _ = protocolstate.Memoizer.Do(hash, func() (interface{}, error) {
		return data, nil
	})
	return data, nil
}

// connectSSHInfoMode collects handshake information and closes its connection
// when the caller cancels or the configured network timeout expires.
func connectSSHInfoMode(ctx context.Context, opts *connectOptions) (*ssh.HandshakeLog, error) {
	if err := opts.validate(); err != nil {
		return nil, err
	}

	data := new(ssh.HandshakeLog)

	sshConfig := ssh.MakeSSHConfig()
	sshConfig.Timeout = opts.Timeout
	sshConfig.ConnLog = data
	sshConfig.DontAuthenticate = true
	sshConfig.BannerCallback = func(banner string) error {
		data.Banner = strings.TrimSpace(banner)
		return nil
	}
	host := strings.TrimSuffix(strings.TrimPrefix(opts.Host, "["), "]")
	rhost := net.JoinHostPort(host, strconv.Itoa(opts.Port))
	conn, err := (&net.Dialer{Timeout: sshConfig.Timeout}).DialContext(ctx, "tcp", rhost)
	if err != nil {
		return nil, err
	}
	defer func() { _ = conn.Close() }()
	stop := context.AfterFunc(ctx, func() { _ = conn.Close() })
	defer stop()
	if err := conn.SetDeadline(time.Now().Add(sshConfig.Timeout)); err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		return nil, err
	}
	sshConn, _, _, err := ssh.NewClientConn(conn, rhost, sshConfig)
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = sshConn.Close() }()

	return data, nil
}

func connect(opts *connectOptions) (*ssh.Client, error) {
	if err := opts.validate(); err != nil {
		return nil, err
	}

	conf := &ssh.ClientConfig{
		User:    opts.User,
		Auth:    []ssh.AuthMethod{},
		Timeout: opts.Timeout,
	}

	if len(opts.Password) > 0 {
		conf.Auth = append(conf.Auth, ssh.Password(opts.Password))

		cb := func(user, instruction string, questions []string, echos []bool) (answers []string, err error) {
			answers = make([]string, len(questions))
			filledCount := 0
			for i, question := range questions {
				challenge := map[string]any{"user": user, "instruction": instruction, "question": question, "echo": echos[i]}
				gologger.Debug().Msgf("SSH keyboard-interactive question %d/%d: %s", i+1, len(questions), vardump.DumpVariables(challenge))
				if !echos[i] && passwordQuestionPattern.MatchString(question) {
					answers[i] = opts.Password
					filledCount++
				} else if echos[i] && usernameQuestionPattern.MatchString(question) {
					answers[i] = opts.User
					filledCount++
				}
			}
			gologger.Debug().Msgf("SSH keyboard-interactive: %d/%d questions filled", filledCount, len(questions))
			return answers, nil
		}
		conf.Auth = append(conf.Auth, ssh.KeyboardInteractiveChallenge(cb))
	}

	if len(opts.PrivateKey) > 0 {
		signer, err := ssh.ParsePrivateKey([]byte(opts.PrivateKey))
		if err != nil {
			return nil, err
		}
		conf.Auth = append(conf.Auth, ssh.PublicKeys(signer))
	}

	host := strings.TrimSuffix(strings.TrimPrefix(opts.Host, "["), "]")
	client, err := ssh.Dial("tcp", net.JoinHostPort(host, strconv.Itoa(opts.Port)), conf)
	if err != nil {
		return nil, err
	}
	return client, nil
}

package ssh_test

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"sync"
	"testing"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/js/compiler"
	sshlib "github.com/projectdiscovery/nuclei/v3/pkg/js/libs/ssh"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

type silentSSHPeer struct {
	listener net.Listener
	accepted chan net.Conn
	closed   chan struct{}
	stop     chan struct{}
	done     chan struct{}
	once     sync.Once
}

func newSilentSSHPeer(t *testing.T) *silentSSHPeer {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}

	peer := &silentSSHPeer{
		listener: listener,
		accepted: make(chan net.Conn, 1),
		closed:   make(chan struct{}),
		stop:     make(chan struct{}),
		done:     make(chan struct{}),
	}
	go func() {
		defer close(peer.done)
		conn, err := listener.Accept()
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()
		peer.accepted <- conn

		// Read the client banner without replying; EOF proves the client closed TCP.
		readDone := make(chan struct{})
		go func() {
			_, _ = io.Copy(io.Discard, conn)
			close(readDone)
		}()
		select {
		case <-readDone:
			close(peer.closed)
		case <-peer.stop:
			_ = conn.Close()
			<-readDone
		}
	}()
	t.Cleanup(func() {
		peer.close()
		select {
		case <-peer.done:
		case <-time.After(3 * time.Second):
			t.Error("local peer cleanup timed out")
		}
	})

	return peer
}

func (p *silentSSHPeer) close() {
	p.once.Do(func() {
		close(p.stop)
		_ = p.listener.Close()
	})
}

func (p *silentSSHPeer) port() int { return p.listener.Addr().(*net.TCPAddr).Port }

func (p *silentSSHPeer) waitAccepted(t *testing.T) net.Conn {
	t.Helper()
	select {
	case conn := <-p.accepted:
		return conn
	case <-time.After(5 * time.Second):
		t.Fatal("SSH connection never reached the local peer")
	}
	return nil
}

func TestSSHInfoCancellation(t *testing.T) {
	for _, cancelCall := range []bool{false, true} {
		name := "peer-close-control"
		if cancelCall {
			name = "cancel-in-flight"
		}
		t.Run(name, func(t *testing.T) {
			peer := newSilentSSHPeer(t)
			ctx, cancel := context.WithCancel(executionContext(t))
			defer cancel()
			done := make(chan error, 1)
			go func() {
				client := &sshlib.SSHClient{}
				_, err := client.ConnectSSHInfoMode(ctx, "127.0.0.1", peer.port())
				done <- err
			}()
			peer.waitAccepted(t)
			begin := time.Now()
			if cancelCall {
				cancel()
			} else {
				peer.close()
			}

			returned := false
			select {
			case err := <-done:
				returned = true
				t.Logf("call returned after %s: %v", time.Since(begin), err)
				if err == nil {
					t.Error("silent peer unexpectedly completed SSH handshake")
				}
			case <-time.After(time.Second):
				t.Errorf("SSH call still running 1s after trigger (cancel=%v)", cancelCall)
			}

			if cancelCall {
				select {
				case <-peer.closed:
					t.Log("client closed TCP after cancellation")
				case <-time.After(500 * time.Millisecond):
					t.Error("TCP connection remains open after cancellation")
				}
			}

			// Always stop the peer and wait for the call, including on regression failures.
			peer.close()
			if !returned {
				select {
				case err := <-done:
					_ = err
				case <-time.After(3 * time.Second):
					t.Error("SSH call did not stop after peer cleanup")
				}
			}
		})
	}
}

func TestJSDeadlineClosesSSHConnection(t *testing.T) {
	oldPooling := compiler.PoolingJsVmConcurrency
	compiler.PoolingJsVmConcurrency = 1
	defer func() { compiler.PoolingJsVmConcurrency = oldPooling }()

	peer := newSilentSSHPeer(t)
	done := make(chan error, 1)
	source := fmt.Sprintf(`const ssh = require('nuclei/ssh'); const c = new ssh.SSHClient(); Export(c.ConnectSSHInfoMode('127.0.0.1', %d));`, peer.port())
	begin := time.Now()
	go func() {
		_, err := executeSSHScript(t.Context(), source, 250*time.Millisecond)
		done <- err
	}()
	peer.waitAccepted(t)

	select {
	case err := <-done:
		t.Logf("JS call returned after %s: %v", time.Since(begin), err)
		if err == nil {
			t.Error("silent peer unexpectedly completed JS SSH check")
		}
	case <-time.After(4 * time.Second):
		peer.close()
		select {
		case err := <-done:
			_ = err
		case <-time.After(3 * time.Second):
			t.Error("JS call did not stop after peer cleanup")
		}
		t.Fatal("JS call did not return after execution deadline")
	}

	select {
	case <-peer.closed:
		t.Log("JS deadline closed the underlying TCP connection")
	case <-time.After(500 * time.Millisecond):
		t.Error("JS returned on timeout, but underlying SSH TCP connection is still open")
	}
	peer.close()
	// Wait for the peer cleanup before checking that the VM pool recovers.
	select {
	case <-peer.done:
	case <-time.After(3 * time.Second):
		t.Fatal("peer cleanup did not finish")
	}

	// A subsequent execution must be able to acquire the single pool slot.
	if _, err := executeSSHScript(t.Context(), `Export(true);`, 3*time.Second); err != nil {
		t.Errorf("JS pool did not recover after peer cleanup: %v", err)
	}
}

func executeSSHScript(ctx context.Context, source string, budget time.Duration) (compiler.ExecuteResult, error) {
	program, err := compiler.SourceAutoMode(source, false)
	if err != nil {
		return nil, err
	}
	return compiler.New().ExecuteWithOptions(ctx, program, nil, &compiler.ExecuteOptions{Source: &source, TimeoutVariants: &types.Timeouts{JsCompilerExecutionTimeout: budget}})
}

func TestSSHInfoAlreadyCanceled(t *testing.T) {
	peer := newSilentSSHPeer(t)
	ctx, cancel := context.WithCancel(executionContext(t))
	cancel()
	_, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, "127.0.0.1", peer.port())
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("error = %v, want context.Canceled", err)
	}
	select {
	case <-peer.accepted:
		t.Fatal("canceled call opened TCP")
	default:
	}
}

func TestSSHInfoSuccessAndCache(t *testing.T) {
	host, port := startServer(t)
	ctx := executionContext(t)
	first, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, host, port)
	if err != nil {
		t.Fatal(err)
	}
	if first == nil || first.ServerID == nil || first.ServerID.Raw == "" {
		t.Fatalf("missing SSH server information: %+v", first)
	}
	second, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, host, port)
	if err != nil || first != second {
		t.Fatalf("cached result = %p, %v; want %p, nil", second, err, first)
	}
	canceled, cancel := context.WithCancel(ctx)
	cancel()
	if _, err := new(sshlib.SSHClient).ConnectSSHInfoMode(canceled, host, port); !errors.Is(err, context.Canceled) {
		t.Fatalf("cached canceled call = %v", err)
	}
}

func TestSSHInfoConcurrentCancellation(t *testing.T) {
	peer := newSilentSSHPeer(t)
	ctx, cancel := context.WithCancel(executionContext(t))
	defer cancel()
	first := make(chan error, 1)
	go func() {
		_, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, "127.0.0.1", peer.port())
		first <- err
	}()
	peer.waitAccepted(t)
	// The second connection is accepted directly, so both calls are certainly in flight.
	second := make(chan error, 1)
	go func() {
		_, err := new(sshlib.SSHClient).ConnectSSHInfoMode(executionContext(t), "127.0.0.1", peer.port())
		second <- err
	}()
	if err := peer.listener.(*net.TCPListener).SetDeadline(time.Now().Add(time.Second)); err != nil {
		t.Fatal(err)
	}
	conn, err := peer.listener.Accept()
	if err != nil {
		peer.close()
		t.Fatal("second caller did not get an independent connection:", err)
	}
	defer func() { _ = conn.Close() }()
	cancel()
	select {
	case err := <-first:
		if !errors.Is(err, context.Canceled) {
			t.Fatalf("first error = %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("canceled caller did not return")
	}
	select {
	case err := <-second:
		t.Fatalf("other caller returned on first cancellation: %v", err)
	case <-time.After(30 * time.Millisecond):
	}
	_ = conn.Close()
	select {
	case err := <-second:
		if err == nil || errors.Is(err, context.Canceled) {
			t.Fatalf("peer error = %v", err)
		}
	case <-time.After(time.Second):
		t.Fatal("second caller did not stop")
	}
}

func TestSSHInfoRetriesAfterError(t *testing.T) {
	for _, cancelFirst := range []bool{false, true} {
		t.Run(fmt.Sprint("cancel=", cancelFirst), func(t *testing.T) {
			peer := newSilentSSHPeer(t)
			ctx := executionContext(t)
			firstCtx, cancel := context.WithCancel(ctx)
			defer cancel()
			done := make(chan error, 1)
			go func() {
				_, err := new(sshlib.SSHClient).ConnectSSHInfoMode(firstCtx, "127.0.0.1", peer.port())
				done <- err
			}()
			conn := peer.waitAccepted(t)
			if cancelFirst {
				cancel()
			} else {
				_ = conn.Close()
			}
			select {
			case err := <-done:
				if err == nil {
					t.Fatal("first handshake unexpectedly succeeded")
				}
				if cancelFirst && !errors.Is(err, context.Canceled) {
					t.Fatalf("cancellation error = %v", err)
				}
				if !cancelFirst && errors.Is(err, context.Canceled) {
					t.Fatalf("ordinary peer error became cancellation: %v", err)
				}
			case <-time.After(time.Second):
				t.Fatal("first call did not return")
			}
			// Reuse the same address and execution ID, forwarding the next connection
			// to a real SSH server. Neither ordinary errors nor cancellation may poison the cache.
			host, port := startServer(t)
			proxyDone := make(chan struct{})
			go func() {
				defer close(proxyDone)
				inbound, err := peer.listener.Accept()
				if err != nil {
					return
				}
				defer func() { _ = inbound.Close() }()
				outbound, err := net.Dial("tcp", net.JoinHostPort(host, fmt.Sprint(port)))
				if err != nil {
					return
				}
				defer func() { _ = outbound.Close() }()
				copied := make(chan struct{})
				go func() { _, _ = io.Copy(outbound, inbound); _ = outbound.Close(); close(copied) }()
				_, _ = io.Copy(inbound, outbound)
				_ = inbound.Close()
				<-copied
			}()
			retryCtx, retryCancel := context.WithTimeout(ctx, time.Second)
			defer retryCancel()
			result, err := new(sshlib.SSHClient).ConnectSSHInfoMode(retryCtx, "127.0.0.1", peer.port())
			if err != nil || result == nil || result.ServerID == nil {
				t.Fatalf("retry = %+v, %v", result, err)
			}
			select {
			case <-proxyDone:
			case <-time.After(time.Second):
				t.Fatal("successful info call left TCP open")
			}
			cached, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, "127.0.0.1", peer.port())
			if err != nil || cached != result {
				t.Fatalf("cached retry = %p, %v; want %p, nil", cached, err, result)
			}
		})
	}
}

func TestSSHInfoDeadlineClosesConnection(t *testing.T) {
	peer := newSilentSSHPeer(t)
	ctx, cancel := context.WithTimeout(executionContext(t), 250*time.Millisecond)
	defer cancel()
	done := make(chan error, 1)
	go func() {
		_, err := new(sshlib.SSHClient).ConnectSSHInfoMode(ctx, "127.0.0.1", peer.port())
		done <- err
	}()
	peer.waitAccepted(t)
	select {
	case err := <-done:
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("error = %v, want context.DeadlineExceeded", err)
		}
	case <-time.After(time.Second):
		t.Fatal("deadline did not stop the SSH handshake")
	}
	select {
	case <-peer.closed:
	case <-time.After(time.Second):
		t.Fatal("deadline left TCP connection open")
	}
}

