	vncplugin "github.com/praetorian-inc/fingerprintx/pkg/plugins/services/vnc"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	stringsutil "github.com/projectdiscovery/utils/strings"
)

type (
	// IsVNCResponse is the response from the IsVNC function.
	// @example
	// ```javascript
	// const vnc = require('nuclei/vnc');
	// const isVNC = vnc.IsVNC('acme.com', 5900);
	// log(toJSON(isVNC));
	// ```
	IsVNCResponse struct {
		IsVNC  bool
		Banner string
	}

	// VNCClient is a client for VNC servers.
	// @example
	// ```javascript
	// const vnc = require('nuclei/vnc');
	// const client = new vnc.VNCClient();
	// const connected = client.Connect('acme.com', 5900, 'password');
	// log(toJSON(connected));
	// ```
	VNCClient struct{}
)

// Connect connects to VNC server using given password.
// If connection and authentication is successful, it returns true.
// If connection or authentication is unsuccessful, it returns false and error.
// The connection is closed after the function returns.
// @example
// ```javascript
// const vnc = require('nuclei/vnc');
// const client = new vnc.VNCClient();
// const connected = client.Connect('acme.com', 5900, 'password');
// ```
func (c *VNCClient) Connect(ctx context.Context, host string, port int, password string) (bool, error) {
	executionId := ctx.Value("executionId").(string)
	return connect(ctx, executionId, host, port, password)
}

// connect attempts to authenticate with a VNC server using the given password
func connect(ctx context.Context, executionId string, host string, port int, password string) (bool, error) {
	if host == "" || port <= 0 {
		return false, fmt.Errorf("invalid host or port")
	}
	if !protocolstate.IsHostAllowed(executionId, host) {
		// host is not valid according to network policy
		return false, protocolstate.ErrHostDenied.Msgf(host)
	}

	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return false, fmt.Errorf("dialers not initialized for %s", executionId)
	}

	conn, err := dialer.Fastdialer.Dial(ctx, "tcp", net.JoinHostPort(host, strconv.Itoa(port)))
	if err != nil {
		return false, err
	}
	defer func() {
		_ = conn.Close()
	}()

	// Set connection timeout
	_ = conn.SetDeadline(time.Now().Add(10 * time.Second))

	// Create VNC client config with password
	vncConfig := vnclib.NewClientConfig(password)

	// Attempt to connect and authenticate
	c, err := vnclib.Connect(ctx, conn, vncConfig)
	if err != nil {
		// Check for specific authentication errors
		if isAuthError(err) {
			return false, nil // Authentication failed, but connection succeeded
		}
		return false, err // Connection or other error
	}
	if c != nil {
		_ = c.Close()
	}

	return true, nil
}

// isAuthError checks if the error is an authentication failure
func isAuthError(err error) bool {
	if err == nil {
		return false
	}

	// Check for common VNC authentication error messages
	errStr := err.Error()
	return stringsutil.ContainsAnyI(errStr, "authentication", "auth", "password", "invalid", "failed")
}

// IsVNC checks if a host is running a VNC server.
// It returns a boolean indicating if the host is running a VNC server
// and the banner of the VNC server.
// @example
// ```javascript
// const vnc = require('nuclei/vnc');
// const isVNC = vnc.IsVNC('acme.com', 5900);
// log(toJSON(isVNC));
// ```
func IsVNC(ctx context.Context, host string, port int) (IsVNCResponse, error) {
	executionId := ctx.Value("executionId").(string)
	return memoizedisVNC(ctx, executionId, host, port)
}

// @memo
func isVNC(ctx context.Context, executionId string, host string, port int) (IsVNCResponse, error) {
	resp := IsVNCResponse{}

	timeout := 5 * time.Second
	dialer := protocolstate.GetDialersWithId(executionId)
	if dialer == nil {
		return IsVNCResponse{}, fmt.Errorf("dialers not initialized for %s", executionId)
	}
	conn, err := dialer.Fastdialer.Dial(ctx, "tcp", net.JoinHostPort(host, strconv.Itoa(port)))
	if err != nil {
		return resp, err
	}
	defer func() {
		_ = conn.Close()
	}()

	vncPlugin := vncplugin.VNCPlugin{}
	service, err := vncPlugin.Run(conn, timeout, plugins.Target{Host: host})
	if err != nil {
		return resp, err
	}
	if service == nil {
		return resp, nil
	}
	resp.Banner = service.Version
	resp.IsVNC = true
	return resp, nil
}

package websocket

import (
	"context"
	"crypto/tls"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"time"

	"github.com/gobwas/ws"
	"github.com/gobwas/ws/wsutil"
	"github.com/projectdiscovery/goja"

	jsnet "github.com/projectdiscovery/nuclei/v3/pkg/js/libs/net"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

const (
	defaultTimeout = 5 * time.Second
	// maxMessageSize caps a received message, matching the net module's read limit.
	maxMessageSize = 8 * 1024 * 1024
)

type (
	// Options configures a WebSocket Client. All fields are optional.
	// @example
	// ```javascript
	// const websocket = require('nuclei/websocket');
	// const opts = new websocket.Options();
	// opts.Headers = {'Origin': 'https://acme.com'};
	// opts.Protocols = ['chat'];
	// const client = new websocket.Client('wss://acme.com/socket', opts);
	// ```
	Options struct {
		// Headers are extra HTTP headers sent with the opening handshake.
		Headers map[string]string
		// Protocols are the subprotocols offered in the handshake, in preference order.
		Protocols []string
		// TimeoutSeconds bounds the handshake and each send or receive.
		// 0 uses the scan's TCP read timeout.
		TimeoutSeconds int
		// ServerName overrides the TLS server name for wss:// URLs.
		ServerName string
	}
)

type (
	// Client is a WebSocket client for nuclei JS templates.
	// @example
	// ```javascript
	// const websocket = require('nuclei/websocket');
	// const client = new websocket.Client('ws://acme.com/socket');
	// client.Send('hello');
	// const reply = client.Receive();
	// client.Close();
	// ```
	Client struct {
		// URL is the ws:// or wss:// endpoint.
		URL string
		// Protocol is the subprotocol the server accepted, set after connecting.
		Protocol string
		// ResponseHeaders are the handshake response headers, set after connecting.
		// Upgrade, Connection and Sec-WebSocket-* headers are validated by the
		// handshake and not included; Protocol holds the negotiated subprotocol.
		ResponseHeaders map[string]string

		nj          *utils.NucleiJS
		executionID string
		opts        Options
		timeout     time.Duration
		conn        net.Conn
		reader      io.Reader
	}
)

// NewClient creates a new WebSocket client for the given ws:// or wss:// URL.
//
// Constructor: constructor(public url: string, public options?: Options)
func NewClient(call goja.ConstructorCall, runtime *goja.Runtime) *goja.Object {
	c := &Client{nj: utils.NewNucleiJS(runtime)}
	c.nj.ObjectSig = "Client(url, {Options})"

	rawURL, _ := c.nj.GetArg(call.Arguments, 0).(string)
	c.nj.Require(rawURL != "", "websocket url cannot be empty")
	if len(call.Arguments) > 1 && !goja.IsUndefined(call.Arguments[1]) && !goja.IsNull(call.Arguments[1]) {
		if err := runtime.ExportTo(call.Arguments[1], &c.opts); err != nil {
			c.nj.HandleError(err, "invalid websocket options")
		}
	}

	parsed, err := url.Parse(rawURL)
	c.nj.HandleError(err, "invalid websocket url")
	c.nj.Require(parsed.Scheme == "ws" || parsed.Scheme == "wss", "websocket url must use ws:// or wss://")
	c.nj.Require(parsed.Hostname() != "", "websocket url host cannot be empty")

	c.URL = rawURL
	c.executionID = c.nj.ExecutionId()
	c.timeout = timeoutFor(c.nj.Context(), c.opts.TimeoutSeconds)

	// defense in depth: the dialer re-checks the network policy on every dial
	c.nj.Require(protocolstate.IsHostAllowed(c.executionID, parsed.Hostname()), protocolstate.ErrHostDenied.Msgf(parsed.Hostname()).Error())

	return utils.LinkConstructor(call, runtime, c)
}

// Connect performs the opening handshake. It is optional; Send and Receive
// connect on demand.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// client.Connect();
// log(client.Protocol);
// ```
func (c *Client) Connect() {
	c.nj.Require(c.executionID != "", "websocket: missing executionId in runtime")
	if c.conn != nil {
		return
	}

	header := http.Header{}
	for key, value := range c.opts.Headers {
		header.Set(key, value)
	}
	responseHeaders := map[string]string{}
	dialer := ws.Dialer{
		Header:    ws.HandshakeHeaderHTTP(header),
		Protocols: c.opts.Protocols,
		Timeout:   c.timeout,
		TLSConfig: &tls.Config{InsecureSkipVerify: true, MinVersion: tls.VersionTLS10, ServerName: c.opts.ServerName},
		// route through the net module so network policy and proxies apply
		NetDial: jsnet.Dial,
		OnHeader: func(key, value []byte) error {
			responseHeaders[string(key)] = string(value)
			return nil
		},
	}

	ctx := context.WithValue(c.nj.Context(), "executionId", c.executionID) //nolint:staticcheck
	conn, buffered, handshake, err := dialer.Dial(ctx, c.URL)
	c.nj.HandleError(err, "websocket handshake failed")

	c.conn = conn
	c.reader = conn
	if buffered != nil {
		// frames the server sent right after the handshake are already buffered
		c.reader = io.MultiReader(buffered, conn)
	}
	c.Protocol = handshake.Protocol
	c.ResponseHeaders = responseHeaders
}

// Send sends a text message.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// client.Send('hello');
// ```
func (c *Client) Send(data string) {
	c.write(ws.OpText, []byte(data))
}

// SendHex sends a binary message given as hex.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// client.SendHex('68656c6c6f');
// ```
func (c *Client) SendHex(data string) {
	payload, err := hex.DecodeString(data)
	c.nj.HandleError(err, "invalid hex data")
	c.write(ws.OpBinary, payload)
}

// Receive returns the next text or binary message as a string. Pings are
// answered automatically.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// const message = client.Receive();
// ```
func (c *Client) Receive() string {
	return string(c.read())
}

// ReceiveHex returns the next text or binary message as hex.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// const message = client.ReceiveHex();
// ```
func (c *Client) ReceiveHex() string {
	return hex.EncodeToString(c.read())
}

// Close sends a close frame and closes the connection.
// @example
// ```javascript
// const websocket = require('nuclei/websocket');
// const client = new websocket.Client('ws://acme.com/socket');
// client.Close();
// ```
func (c *Client) Close() {
	if c.conn == nil {
		return
	}
	_ = c.conn.SetWriteDeadline(time.Now().Add(c.timeout))
	_ = ws.WriteFrame(c.conn, ws.MaskFrame(ws.NewCloseFrame(ws.NewCloseFrameBody(ws.StatusNormalClosure, ""))))
	c.release()
}

func (c *Client) release() {
	_ = c.conn.Close()
	c.conn = nil
	c.reader = nil
}

func (c *Client) write(op ws.OpCode, payload []byte) {
	c.Connect()
	c.nj.HandleError(c.conn.SetWriteDeadline(time.Now().Add(c.timeout)), "could not set write deadline")
	c.nj.HandleError(wsutil.WriteClientMessage(c.conn, op, payload), "websocket send failed")
}

func (c *Client) read() []byte {
	c.Connect()
	c.nj.HandleError(c.conn.SetReadDeadline(time.Now().Add(c.timeout)), "could not set read deadline")

	control := wsutil.ControlFrameHandler(c.conn, ws.StateClientSide)
	reader := wsutil.Reader{
		Source:       c.reader,
		State:        ws.StateClientSide,
		MaxFrameSize: maxMessageSize,
		// control frames can also arrive between the fragments of a message
		OnIntermediate: control,
	}
	for {
		header, err := reader.NextFrame()
		c.nj.HandleError(err, "websocket receive failed")
		if header.OpCode.IsControl() {
			if err := control(header, &reader); err != nil {
				var closed wsutil.ClosedError
				if errors.As(err, &closed) {
					// the control handler already answered the close frame
					c.release()
					c.nj.Throw("websocket closed by server: %d %s", closed.Code, closed.Reason)
				}
				c.nj.HandleError(err, "websocket receive failed")
			}
			continue
		}

		payload, err := io.ReadAll(io.LimitReader(&reader, maxMessageSize+1))
		c.nj.HandleError(err, "websocket receive failed")
		c.nj.Require(len(payload) <= maxMessageSize, fmt.Sprintf("websocket message exceeds %d bytes", maxMessageSize))
		return payload
	}
}

// timeoutFor returns the configured timeout, falling back to the scan's TCP
// read timeout like the net module.
func timeoutFor(ctx context.Context, seconds int) time.Duration {
	if seconds > 0 {
		return time.Duration(seconds) * time.Second
	}
	if timeouts, ok := ctx.Value("timeoutVariants").(*types.Timeouts); ok && timeouts != nil && timeouts.TcpReadTimeout > 0 {
		return timeouts.TcpReadTimeout
	}
	return defaultTimeout
}

package websocket

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/gobwas/ws"
	"github.com/gobwas/ws/wsutil"
	"github.com/projectdiscovery/goja"
	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// echoHandler upgrades the connection, greets, then echoes every message
// back with its original opcode until the client closes.
func echoHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		upgrader := ws.HTTPUpgrader{
			Protocol: func(protocol string) bool { return protocol == "chat" },
			Header:   http.Header{"X-Server": []string{"echo"}},
		}
		conn, _, _, err := upgrader.Upgrade(r, w)
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()

		if err := wsutil.WriteServerText(conn, []byte("welcome")); err != nil {
			return
		}
		for {
			payload, op, err := wsutil.ReadClientData(conn)
			if err != nil {
				return
			}
			if string(payload) == "close-me" {
				_ = ws.WriteFrame(conn, ws.NewCloseFrame(ws.NewCloseFrameBody(ws.StatusGoingAway, "bye")))
				return
			}
			if err := wsutil.WriteServerMessage(conn, op, payload); err != nil {
				return
			}
		}
	}
}

func initExec(t *testing.T, options *types.Options) string {
	t.Helper()
	executionID := "websocket-" + strings.NewReplacer("/", "-", " ", "-").Replace(t.Name())
	options.ExecutionId = executionID
	require.NoError(t, protocolstate.Init(options))
	t.Cleanup(func() { protocolstate.Close(executionID) })
	return executionID
}

// newRuntimeClient constructs a *Client through the goja runtime exactly as a
// nuclei template would.
func newRuntimeClient(t *testing.T, executionID, rawURL string, opts Options) (*Client, error) {
	t.Helper()
	runtime := goja.New()
	runtime.SetContextValue("executionId", executionID)
	runtime.SetContextValue("ctx", context.Background())

	obj, err := runtime.New(runtime.ToValue(NewClient), runtime.ToValue(rawURL), runtime.ToValue(opts))
	if err != nil {
		return nil, err
	}
	client, ok := obj.Export().(*Client)
	require.True(t, ok, "expected *Client export, got %T", obj.Export())
	t.Cleanup(client.Close)
	return client, nil
}

// thrown returns the message a client method throws into the JS runtime.
func thrown(fn func()) (message string) {
	defer func() {
		if r := recover(); r != nil {
			message = fmt.Sprint(r)
		}
	}()
	fn()
	return ""
}

func wsURL(server *httptest.Server) string {
	return "ws" + strings.TrimPrefix(server.URL, "http")
}

func TestTextAndBinaryRoundTrip(t *testing.T) {
	server := httptest.NewServer(echoHandler())
	defer server.Close()
	executionID := initExec(t, &types.Options{})

	client, err := newRuntimeClient(t, executionID, wsURL(server)+"/socket", Options{
		Protocols: []string{"chat"},
		Headers:   map[string]string{"Origin": "https://acme.test"},
	})
	require.NoError(t, err)

	require.Equal(t, "welcome", client.Receive(), "a message sent right after the handshake is not lost")
	require.Equal(t, "chat", client.Protocol)
	require.Equal(t, "echo", client.ResponseHeaders["X-Server"])

	client.Send("hello")
	require.Equal(t, "hello", client.Receive())

	client.SendHex("00ff10")
	require.Equal(t, "00ff10", client.ReceiveHex())
}

func TestServerCloseIsReported(t *testing.T) {
	server := httptest.NewServer(echoHandler())
	defer server.Close()
	executionID := initExec(t, &types.Options{})

	client, err := newRuntimeClient(t, executionID, wsURL(server), Options{})
	require.NoError(t, err)
	require.Equal(t, "welcome", client.Receive())

	client.Send("close-me")
	require.Contains(t, thrown(func() { client.Receive() }), "closed by server: 1001 bye")
}

func TestRejectedHandshake(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
