func TestConstructorValidation(t *testing.T) {
	executionID := initExec(t, &types.Options{})
	for rawURL, want := range map[string]string{
		"":                   "cannot be empty",
		"http://acme.test/":  "ws:// or wss://",
		"ws:///path-only":    "host cannot be empty",
