	err := e.CompileExtractors()
	require.Nil(t, err)

	got := e.ExtractDSL(map[string]interface{}{"hello": "hi"})
	require.Equal(t, map[string]struct{}{"HI": {}}, got)

	got = e.ExtractDSL(map[string]interface{}{"hi": "hello"})
	require.Equal(t, map[string]struct{}{}, got)
}

// TestExtractor_ExtractXPath_XMLPrologHTMLFallback mirrors the matcher case for
// extractors: an XHTML document that declares itself as XML must still be
// extracted from instead of yielding no values.
func TestExtractor_ExtractXPath_XMLPrologHTMLFallback(t *testing.T) {
	body := `<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>a&nbsp;b</title></head>
<body><h1 id="h">Admin</h1><br></body>
</html>`

	e := &Extractor{Type: ExtractorTypeHolder{ExtractorType: XPathExtractor}, XPath: []string{"//h1"}}
	err := e.CompileExtractors()
	require.Nil(t, err)

	got := e.ExtractXPath(body)
	require.Equal(t, map[string]struct{}{"Admin": {}}, got)

	// The XML-only entry point is unchanged: a document that is not well-formed
	// XML yields no results.
	require.Equal(t, map[string]struct{}{}, e.ExtractXML(body))
}

// TestExtractor_ExtractXPath_XMLPrologNoFallbackOnMiss guards the extractor
// fallback the same way as the matcher one.
func TestExtractor_ExtractXPath_XMLPrologNoFallbackOnMiss(t *testing.T) {
	body := `<?xml version="1.0" encoding="utf-8"?><Root><Item>x</Item></Root>`

	e := &Extractor{Type: ExtractorTypeHolder{ExtractorType: XPathExtractor}, XPath: []string{"//item"}}
	err := e.CompileExtractors()
	require.Nil(t, err)

	require.Equal(t, map[string]struct{}{}, e.ExtractXPath(body), "Well-formed XML must be matched case-sensitively")

	e = &Extractor{Type: ExtractorTypeHolder{ExtractorType: XPathExtractor}, XPath: []string{"//Item"}}
	err = e.CompileExtractors()
	require.Nil(t, err)

	require.Equal(t, map[string]struct{}{"x": {}}, e.ExtractXPath(body))
}

package extractors

import (
	"errors"
	"strings"

	"github.com/invopop/jsonschema"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// ExtractorType is the type of the extractor specified
type ExtractorType int

// name:ExtractorType
const (
	// name:regex
	RegexExtractor ExtractorType = iota + 1
	// name:kval
	KValExtractor
	// name:xpath
	XPathExtractor
	// name:json
	JSONExtractor
	// name:dsl
	DSLExtractor
	// name:llm
	LLMExtractor
	limit
)

// extractorMappings is a table for conversion of extractor type from string.
var extractorMappings = map[ExtractorType]string{
	RegexExtractor: "regex",
	KValExtractor:  "kval",
	XPathExtractor: "xpath",
	JSONExtractor:  "json",
	DSLExtractor:   "dsl",
	LLMExtractor:   "llm",
}

// GetType returns the type of the matcher
func (e *Extractor) GetType() ExtractorType {
	return e.Type.ExtractorType
}

// GetSupportedExtractorTypes returns list of supported types
func GetSupportedExtractorTypes() []ExtractorType {
	var result []ExtractorType
	for index := ExtractorType(1); index < limit; index++ {
		result = append(result, index)
	}
	return result
}

func toExtractorTypes(valueToMap string) (ExtractorType, error) {
	normalizedValue := normalizeValue(valueToMap)
	for key, currentValue := range extractorMappings {
		if normalizedValue == currentValue {
			return key, nil
		}
	}
	return -1, errors.New("Invalid extractor type: " + valueToMap)
}

func normalizeValue(value string) string {
	return strings.TrimSpace(strings.ToLower(value))
}

func (t ExtractorType) String() string {
	return extractorMappings[t]
}

// ExtractorTypeHolder is used to hold internal type of the extractor
type ExtractorTypeHolder struct {
	ExtractorType ExtractorType `mapping:"true"`
}

func (holder ExtractorTypeHolder) String() string {
	return holder.ExtractorType.String()
}

func (holder ExtractorTypeHolder) JSONSchema() *jsonschema.Schema {
	gotType := &jsonschema.Schema{
		Type:        "string",
		Title:       "type of the extractor",
		Description: "Type of the extractor",
	}
	for _, types := range GetSupportedExtractorTypes() {
		gotType.Enum = append(gotType.Enum, types.String())
	}
	return gotType
}

func (holder *ExtractorTypeHolder) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var marshalledTypes string
	if err := unmarshal(&marshalledTypes); err != nil {
		return err
	}

	computedType, err := toExtractorTypes(marshalledTypes)
	if err != nil {
		return err
	}

	holder.ExtractorType = computedType
	return nil
}

func (holder *ExtractorTypeHolder) UnmarshalJSON(data []byte) error {
	s := strings.Trim(string(data), `"`)
	if s == "" {
		return nil
	}
	computedType, err := toExtractorTypes(s)
	if err != nil {
		return err
	}

	holder.ExtractorType = computedType
	return nil
}

func (holder *ExtractorTypeHolder) MarshalJSON() ([]byte, error) {
	return json.Marshal(holder.ExtractorType.String())
}

func (holder ExtractorTypeHolder) MarshalYAML() (interface{}, error) {
	return holder.ExtractorType.String(), nil
}

package extractors

import (
	"regexp"

	"github.com/itchyny/gojq"
	"github.com/projectdiscovery/govaluate"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
)

// Extractor is used to extract part of response using a regex.
type Extractor struct {
	// description: |
	//   Name of the extractor. Name should be lowercase and must not contain
	//   spaces or underscores (_).
	// examples:
	//   - value: "\"cookie-extractor\""
	Name string `yaml:"name,omitempty" json:"name,omitempty" jsonschema:"title=name of the extractor,description=Name of the extractor"`
	// description: |
	//   Type is the type of the extractor.
	Type ExtractorTypeHolder `json:"type" yaml:"type"`
	// extractorType is the internal type of the extractor
	extractorType ExtractorType

	// description: |
	//   Regex contains the regular expression patterns to extract from a part.
	//
	//   Go regex engine does not support lookaheads or lookbehinds, so as a result
	//   they are also not supported in nuclei.
	// examples:
	//   - name: Braintree Access Token Regex
	//     value: >
	//       []string{"access_token\\$production\\$[0-9a-z]{16}\\$[0-9a-f]{32}"}
	//   - name: Wordpress Author Extraction regex
	//     value: >
	//       []string{"Author:(?:[A-Za-z0-9 -\\_=\"]+)?<span(?:[A-Za-z0-9 -\\_=\"]+)?>([A-Za-z0-9]+)<\\/span>"}
	Regex []string `yaml:"regex,omitempty" json:"regex,omitempty" jsonschema:"title=regex to extract from part,description=Regex to extract from part"`
	// description: |
	//   Group specifies a numbered group to extract from the regex.
	// examples:
	//   - name: Example Regex Group
	//     value: "1"
	RegexGroup int `yaml:"group,omitempty" json:"group,omitempty" jsonschema:"title=group to extract from regex,description=Group to extract from regex"`
	// regexCompiled is the compiled variant
	regexCompiled []*regexp.Regexp

	// description: |
	//   kval contains the key-value pairs present in the HTTP response header.
	//   kval extractor can be used to extract HTTP response header and cookie key-value pairs.
	//   kval extractor inputs are case-insensitive, and does not support dash (-) in input which can replaced with underscores (_)
	// 	 For example, Content-Type should be replaced with content_type
	//
	//   A list of supported parts is available in docs for request types.
	// examples:
	//   - name: Extract Server Header From HTTP Response
	//     value: >
	//       []string{"server"}
	//   - name: Extracting value of PHPSESSID Cookie
	//     value: >
	//       []string{"phpsessid"}
	//   - name: Extracting value of Content-Type Cookie
	//     value: >
	//       []string{"content_type"}
	KVal []string `yaml:"kval,omitempty" json:"kval,omitempty" jsonschema:"title=kval pairs to extract from response,description=Kval pairs to extract from response"`

	// description: |
	//   JSON allows using jq-style syntax to extract items from json response
	//
	// examples:
	//   - value: >
	//       []string{".[] | .id"}
	//   - value: >
	//       []string{".batters | .batter | .[] | .id"}
	JSON []string `yaml:"json,omitempty" json:"json,omitempty" jsonschema:"title=json jq expressions to extract data,description=JSON JQ expressions to evaluate from response part"`
	// description: |
	//   XPath allows using xpath expressions to extract items from html response
	//
	// examples:
	//   - value: >
	//       []string{"/html/body/div/p[2]/a"}
	XPath []string `yaml:"xpath,omitempty" json:"xpath,omitempty" jsonschema:"title=html xpath expressions to extract data,description=XPath allows using xpath expressions to extract items from html response"`
	// description: |
	//   Attribute is an optional attribute to extract from response XPath.
	//
	// examples:
	//   - value: "\"href\""
	Attribute string `yaml:"attribute,omitempty" json:"attribute,omitempty" jsonschema:"title=optional attribute to extract from xpath,description=Optional attribute to extract from response XPath"`

	// jsonCompiled is the compiled variant
	jsonCompiled []*gojq.Code

	// description: |
	//   Extracts using DSL expressions.
	DSL         []string `yaml:"dsl,omitempty" json:"dsl,omitempty" jsonschema:"title=dsl expressions to extract,description=Optional attribute to extract from response dsl"`
	dslCompiled []*govaluate.EvaluableExpression

	// description: |
	//   Part is the part of the request response to extract data from.
	//
	//   Each protocol exposes a lot of different parts which are well
	//   documented in docs for each request type.
	// examples:
	//   - value: "\"body\""
	//   - value: "\"raw\""
	Part string `yaml:"part,omitempty" json:"part,omitempty" jsonschema:"title=part of response to extract data from,description=Part of the request response to extract data from"`
	// description: |
	//   Internal, when set to true will allow using the value extracted
	//   in the next request for some protocols (like HTTP).
	Internal bool `yaml:"internal,omitempty" json:"internal,omitempty" jsonschema:"title=mark extracted value for internal variable use,description=Internal when set to true will allow using the value extracted in the next request for some protocols"`

	// description: |
	//   CaseInsensitive enables case-insensitive extractions. Default is false.
	// values:
	//   - false
	//   - true
	CaseInsensitive bool `yaml:"case-insensitive,omitempty" json:"case-insensitive,omitempty" jsonschema:"title=use case insensitive extract,description=use case insensitive extract"`

	// description: |
	//   Prompt is the natural-language instruction for an llm extractor. The
	//   model reads the response part and returns the values named by Schema.
	//
	//   {{...}} placeholders are interpolated from the template variables,
	//   -var and target. Response derived values are not interpolated, since
	//   the response is attacker controlled.
	Prompt string `yaml:"prompt,omitempty" json:"prompt,omitempty" jsonschema:"title=llm extraction prompt,description=Natural language instruction describing what to extract; supports {{...}} interpolation of variables and target values"`
	// description: |
	//   Schema names the fields an llm extractor returns, mapping each field to
	//   its type (string, number, boolean). It shapes both the prompt and the
	//   parsed output.
	Schema map[string]string `yaml:"schema,omitempty" json:"schema,omitempty" jsonschema:"title=llm extraction schema,description=Fields to extract mapped to their type"`
	// description: |
	//   MaxInputTokens caps how much of the response part is sent to the model
	//   for an llm extractor, as an approximate token count.
	MaxInputTokens int `yaml:"max-input-tokens,omitempty" json:"max-input-tokens,omitempty" jsonschema:"title=max llm input tokens,description=Approximate cap on response tokens sent to the model"`

	llmClient LLMClient
}

// NeedsResponse returns true if the extractor reads the full response.
func (extractor *Extractor) NeedsResponse() bool {
	if extractor == nil {
		return false
	}
	if matchers.IsResponseVar(extractor.Part) {
		return true
	}
	for _, k := range extractor.KVal {
		if matchers.IsResponseVar(k) {
			return true
		}
	}
	for _, expr := range extractor.dslCompiled {
		for _, v := range expr.Vars() {
			if matchers.IsResponseVar(v) {
				return true
			}
		}
	}
	return matchers.MentionsResponse(extractor.DSL, extractor.Regex)
}

//go:build gofuzz
// +build gofuzz

package extractors

import "github.com/projectdiscovery/nuclei/v3/pkg/operators/cache"

func init() {
	cache.SetCapacities(128, 128)
}

// Fuzz exercises extractor compilation and extraction with a compact line-based grammar.
func Fuzz(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	if len(data) > fuzzMaxInputSize {
		return -1
	}

	extractor, ok := extractorFromFuzzData(data)
	if !ok {
		return 0
	}
	if err := extractor.CompileExtractors(); err != nil {
		return 0
	}
	exerciseFuzzExtractor(extractor)
	return 1
}

package extractors

import (
	"regexp"
	"strconv"
	"strings"
)

const (
	fuzzMaxInputSize  = 16 << 10
	fuzzMaxItems      = 8
	fuzzMaxValueBytes = 256
)

var (
	fuzzExtractorTypes = []ExtractorType{RegexExtractor, KValExtractor, XPathExtractor, JSONExtractor, DSLExtractor}
	fuzzParts          = []string{"", "body", "raw", "all_headers", "header", "response"}
	fuzzAttributes     = []string{"", "href", "content", "id", "name"}
	fuzzRegexDefaults  = []string{`([A-Za-z0-9_]+)`, `token=([a-z0-9]+)`, `https?://[^\s"']+`}
	fuzzKValDefaults   = []string{"content_type", "server", "set_cookie", "x_powered_by"}
	fuzzJSONDefaults   = []string{`.id`, `.items[] | .id`, `.headers.server`, `.links[] | .href`}
	fuzzXPathDefaults  = []string{`//title`, `/html/body/div/p[2]/a`, `//link`, `/root/item`, `//item`}
	fuzzDSLDefaults    = []string{`to_upper(hello)`, `contains(to_lower(all_headers), "server")`, `body`, `content_type`}
	fuzzRegexCorpus    = "token=abc123\nserver=nginx\nurl=https://example.com/path\nhello=world"
	fuzzJSONCorpus     = `{"id":1,"name":"nuclei","items":[{"id":"a1"},{"id":"b2"}],"headers":{"server":"nginx"},"links":[{"href":"https://example.com"}]}`
	fuzzHTMLCorpus     = `<!doctype html><html><head><title>Example Domain</title><meta content="text/html" name="description" /></head><body><div><p>hello</p><p><a href="https://www.iana.org/domains/example">More information...</a></p></div></body></html>`
	fuzzXMLCorpus      = `<?xml version="1.0"?><root><item id="alpha">A</item><item id="beta">B</item><link href="https://example.com">Example</link></root>`
)

type fuzzExtractorCandidate struct {
	extractorType           ExtractorType
	part                    string
	name                    string
	attribute               string
	internal                bool
	caseInsensitive         bool
	explicitCaseInsensitive bool
	regexGroup              int
	values                  []string
}

func extractorFromFuzzData(data []byte) (*Extractor, bool) {
	if len(data) == 0 || len(data) > fuzzMaxInputSize {
		return nil, false
	}

	candidate := newFuzzExtractorCandidate(data)
	candidate.applyLines(splitFuzzLines(data))
	candidate.addFallbackValues(data)

	return candidate.build()
}

func newFuzzExtractorCandidate(data []byte) *fuzzExtractorCandidate {
	flags := fuzzByteAt(data, 1)
	return &fuzzExtractorCandidate{
		extractorType:   fuzzExtractorTypes[int(fuzzByteAt(data, 0))%len(fuzzExtractorTypes)],
		part:            fuzzParts[int(fuzzByteAt(data, 2))%len(fuzzParts)],
		name:            fuzzName(data),
		attribute:       fuzzAttributes[int(fuzzByteAt(data, 3))%len(fuzzAttributes)],
		internal:        flags&0x01 != 0,
		caseInsensitive: flags&0x02 != 0,
		regexGroup:      int(fuzzByteAt(data, 4) % 3),
	}
}

func (candidate *fuzzExtractorCandidate) applyLines(lines []string) {
	for _, line := range lines {
		key, rawValue, ok := cutFuzzKV(line)
		if !ok {
			candidate.addValue(line)
			continue
		}

		switch key {
		case "type":
			extractorType, err := toExtractorTypes(rawValue)
			if err != nil {
				candidate.extractorType = ExtractorType(0)
			} else {
				candidate.extractorType = extractorType
			}
		case "part":
			candidate.part = trimFuzzValue(rawValue)
		case "name":
			candidate.name = fuzzNameFromText(rawValue)
		case "attribute":
			candidate.attribute = fuzzAttribute(rawValue)
		case "internal":
			candidate.internal = parseFuzzBool(rawValue, candidate.internal)
		case "case-insensitive":
			candidate.caseInsensitive = parseFuzzBool(rawValue, candidate.caseInsensitive)
			candidate.explicitCaseInsensitive = true
		case "group":
			candidate.regexGroup = parseFuzzGroup(rawValue, candidate.regexGroup)
		case "value":
			candidate.addValue(rawValue)
		case "regex":
			candidate.extractorType = RegexExtractor
			candidate.addValue(rawValue)
		case "kval":
			candidate.extractorType = KValExtractor
			candidate.addValue(rawValue)
		case "json":
			candidate.extractorType = JSONExtractor
			candidate.addValue(rawValue)
		case "xpath":
			candidate.extractorType = XPathExtractor
			candidate.addValue(rawValue)
		case "dsl":
			candidate.extractorType = DSLExtractor
			candidate.addValue(rawValue)
		}
	}
}

func (candidate *fuzzExtractorCandidate) addFallbackValues(payload []byte) {
	if len(candidate.values) > 0 || len(candidate.values) >= fuzzMaxItems {
		return
	}

	fields := splitFuzzFields(payload)
	switch candidate.extractorType {
	case RegexExtractor:
		for _, field := range fields {
			candidate.addValue(fuzzRegexValue(field))
		}
		candidate.addDefaults(fuzzRegexDefaults, fuzzByteAt(payload, 5))
	case KValExtractor:
		for _, field := range fields {
			candidate.addValue(fuzzIdentifier(field))
		}
		candidate.addDefaults(fuzzKValDefaults, fuzzByteAt(payload, 5))
	case JSONExtractor:
		for _, field := range fields {
			candidate.addValue(fuzzJSONQuery(field))
		}
		candidate.addDefaults(fuzzJSONDefaults, fuzzByteAt(payload, 5))
	case XPathExtractor:
		for _, field := range fields {
			candidate.addValue(fuzzXPathQuery(field))
		}
		candidate.addDefaults(fuzzXPathDefaults, fuzzByteAt(payload, 5))
	case DSLExtractor:
		for _, field := range fields {
			candidate.addValue(fuzzDSLExpression(field))
		}
		candidate.addDefaults(fuzzDSLDefaults, fuzzByteAt(payload, 5))
	default:
		candidate.addDefaults(fuzzRegexDefaults, fuzzByteAt(payload, 5))
	}
}

func (candidate *fuzzExtractorCandidate) addDefaults(defaults []string, seed byte) {
	if len(candidate.values) >= fuzzMaxItems || len(defaults) == 0 {
		return
	}

	start := int(seed) % len(defaults)
	for offset := 0; offset < len(defaults) && len(candidate.values) < 2; offset++ {
		candidate.addValue(defaults[(start+offset)%len(defaults)])
	}
}

func (candidate *fuzzExtractorCandidate) addValue(value string) {
	value = trimFuzzValue(value)
	if value == "" || len(candidate.values) >= fuzzMaxItems {
		return
	}
	for _, existing := range candidate.values {
		if existing == value {
			return
		}
	}
	candidate.values = append(candidate.values, value)
}

func (candidate *fuzzExtractorCandidate) build() (*Extractor, bool) {
	extractor := &Extractor{
		Type:       ExtractorTypeHolder{ExtractorType: candidate.extractorType},
		Name:       candidate.name,
		Part:       candidate.part,
		Internal:   candidate.internal,
		Attribute:  candidate.attribute,
		RegexGroup: candidate.regexGroup,
	}

	if candidate.extractorType == KValExtractor || candidate.explicitCaseInsensitive {
		extractor.CaseInsensitive = candidate.caseInsensitive
	}
	if candidate.extractorType != XPathExtractor {
		extractor.Attribute = ""
	}
	if candidate.extractorType != RegexExtractor {
		extractor.RegexGroup = 0
	}

	switch candidate.extractorType {
	case RegexExtractor:
		extractor.Regex = append([]string(nil), candidate.values...)
	case KValExtractor:
		extractor.KVal = append([]string(nil), candidate.values...)
	case XPathExtractor:
		extractor.XPath = append([]string(nil), candidate.values...)
	case JSONExtractor:
		extractor.JSON = append([]string(nil), candidate.values...)
	case DSLExtractor:
		extractor.DSL = append([]string(nil), candidate.values...)
	default:
		extractor.Regex = append([]string(nil), candidate.values...)
	}

	// The fuzzer picks a group index independently of the patterns it picks,
	// so it routinely asks for a group the pattern cannot produce (its own
	// defaults include the group-less `https?://[^\s"']+`). CompileExtractors
	// now rejects that, which is correct for real templates but would make the
	// harness fail on inputs it deliberately generates. Clamp to what the
	// narrowest pattern actually captures so the fuzzer keeps exercising
	// extraction rather than dying at compile time.
	if extractor.RegexGroup > 0 {
		extractor.RegexGroup = clampFuzzRegexGroup(extractor.Regex, extractor.RegexGroup)
	}

	return extractor, len(candidate.values) > 0
}

func clampFuzzRegexGroup(patterns []string, group int) int {
	minGroups := -1
	for _, pattern := range patterns {
		compiled, err := regexp.Compile(pattern)
		if err != nil {
			continue
		}
		if groups := compiled.NumSubexp(); minGroups < 0 || groups < minGroups {
			minGroups = groups
		}
	}
	if minGroups < 0 {
		return 0
	}
	if group > minGroups {
		return minGroups
	}
	return group
}

func exerciseFuzzExtractor(extractor *Extractor) {
	switch extractor.GetType() {
	case RegexExtractor:
		_ = extractor.ExtractRegex(fuzzRegexCorpus)
	case KValExtractor:
		_ = extractor.ExtractKval(fuzzKValData())
	case XPathExtractor:
		_ = extractor.ExtractXPath(fuzzHTMLCorpus)
		_ = extractor.ExtractXPath(fuzzXMLCorpus)
	case JSONExtractor:
		_ = extractor.ExtractJSON(fuzzJSONCorpus)
	case DSLExtractor:
		_ = extractor.ExtractDSL(fuzzDSLData())
	}
}

func fuzzKValData() map[string]interface{} {
	return map[string]interface{}{
		"content_type": "Text/HTML",
		"server":       "Nginx",
		"set_cookie":   "session=abc123",
		"x_powered_by": "Go",
	}
}

func fuzzDSLData() map[string]interface{} {
	return map[string]interface{}{
		"hello":        "hi",
		"body":         "PING PONG",
		"all_headers":  "Server: Example\nContent-Type: text/html",
		"content_type": "text/html",
		"status_code":  200,
	}
}

func splitFuzzLines(data []byte) []string {
	fields := strings.FieldsFunc(string(data), func(r rune) bool {
		return r == '\n' || r == '\r' || r == ';'
	})
	if len(fields) > fuzzMaxItems*4 {
		fields = fields[:fuzzMaxItems*4]
	}

	lines := make([]string, 0, len(fields))
	for _, field := range fields {
		field = trimFuzzValue(field)
		if field != "" {
			lines = append(lines, field)
		}
	}
	return lines
}

func splitFuzzFields(data []byte) []string {
	fields := strings.FieldsFunc(string(data), func(r rune) bool {
		return r == '\n' || r == '\r' || r == '|' || r == ','
	})
	if len(fields) > fuzzMaxItems {
		fields = fields[:fuzzMaxItems]
	}

	values := make([]string, 0, len(fields))
	for _, field := range fields {
		field = trimFuzzValue(field)
		if field != "" {
			values = append(values, field)
		}
	}
	return values
}

func cutFuzzKV(line string) (string, string, bool) {
	key, value, ok := strings.Cut(line, "=")
	if !ok {
		key, value, ok = strings.Cut(line, ":")
	}
	if !ok {
		return "", "", false
	}
	return strings.ToLower(strings.TrimSpace(key)), trimFuzzValue(value), true
}

func trimFuzzValue(value string) string {
	value = strings.TrimSpace(strings.ReplaceAll(value, "\x00", ""))
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

func fuzzName(data []byte) string {
	if len(data) == 0 {
		return ""
	}
	if len(data) > 8 {
		data = data[:8]
	}
	return "fuzz-" + strconv.FormatUint(uint64(data[0]), 16) + fuzzNameSuffix(data[1:])
}

func fuzzNameSuffix(data []byte) string {
	if len(data) == 0 {
		return ""
	}
	var builder strings.Builder
	for _, value := range data {
		if builder.Len() >= 15 {
			break
		}
		builder.WriteString(strconv.FormatUint(uint64(value), 16))
	}
	return builder.String()
}

func fuzzNameFromText(value string) string {
	value = strings.ToLower(trimFuzzValue(value))
	if value == "" {
		return ""
	}
	var builder strings.Builder
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r)
		case r >= '0' && r <= '9':
			builder.WriteRune(r)
		case r == '-':
			builder.WriteRune(r)
		}
		if builder.Len() >= 32 {
			break
		}
	}
	if builder.Len() == 0 {
		return ""
	}
	return builder.String()
}

func fuzzAttribute(value string) string {
	attribute := fuzzIdentifier(value)
	if attribute == "" {
		return trimFuzzValue(value)
	}
	return attribute
}

func parseFuzzBool(value string, fallback bool) bool {
	switch strings.ToLower(trimFuzzValue(value)) {
	case "1", "true", "yes", "on":
		return true
	case "0", "false", "no", "off":
		return false
	default:
		return fallback
	}
}

func parseFuzzGroup(value string, fallback int) int {
	number, err := strconv.Atoi(trimFuzzValue(value))
	if err != nil {
		return fallback
	}
	if number < -2 {
		return -2
	}
	if number > 8 {
		return 8
	}
	return number
}

func fuzzRegexValue(value string) string {
	value = trimFuzzValue(value)
	if value == "" {
		return ""
	}
	return regexp.QuoteMeta(value)
}

func fuzzJSONQuery(value string) string {
	identifier := fuzzIdentifier(value)
	if identifier == "" {
		return ""
	}
	return "." + identifier
}

func fuzzXPathQuery(value string) string {
	identifier := fuzzIdentifier(value)
	if identifier == "" {
		return ""
	}
	return "//" + identifier
}

func fuzzDSLExpression(value string) string {
	identifier := fuzzIdentifier(value)
	if identifier == "" {
		return ""
	}
	switch identifier {
	case "hello", "body", "all_headers", "content_type":
		return "to_upper(" + identifier + ")"
	case "status_code":
		return identifier
	default:
		return identifier
	}
}

func fuzzIdentifier(value string) string {
	value = strings.ToLower(trimFuzzValue(value))
	if value == "" {
		return ""
	}
	var builder strings.Builder
	lastUnderscore := false
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r)
			lastUnderscore = false
		case r >= '0' && r <= '9':
			if builder.Len() == 0 {
				builder.WriteString("field_")
			}
			builder.WriteRune(r)
			lastUnderscore = false
		case r == '_' || r == '-' || r == '.' || r == ' ':
			if builder.Len() > 0 && !lastUnderscore {
				builder.WriteByte('_')
				lastUnderscore = true
			}
		}
		if builder.Len() >= 32 {
			break
		}
	}
	return strings.Trim(builder.String(), "_")
}

func fuzzByteAt(data []byte, index int) byte {
	if index < 0 || index >= len(data) {
		return 0
	}
	return data[index]
}

