// SupportsMap determines if the extractor type requires a map
func SupportsMap(extractor *Extractor) bool {
	return extractor.Type.ExtractorType == KValExtractor || extractor.Type.ExtractorType == DSLExtractor
}

package operators

import (
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/operators/extractors"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/stretchr/testify/require"
)

// counting stubs stand in for the protocol's match/extract funcs so the tests
// can assert how often the expensive operator was reached, not just the result.
type opCounter struct {
	llmMatches   int
	cheapMatches int
	llmExtracts  int
}

func (c *opCounter) matchFunc(cheap, llm bool) MatchFunc {
	return func(_ map[string]interface{}, matcher *matchers.Matcher) (bool, []string) {
		if matcher.GetType() == matchers.LLMMatcher {
			c.llmMatches++
			return llm, []string{"llm"}
		}
		c.cheapMatches++
		return cheap, []string{"cheap"}
	}
}

func (c *opCounter) extractFunc() ExtractFunc {
	return func(_ map[string]interface{}, extractor *extractors.Extractor) map[string]struct{} {
		if extractor.GetType() == extractors.LLMExtractor {
			c.llmExtracts++
		}
		return map[string]struct{}{"value": {}}
	}
}

func cheapMatcher(name string) *matchers.Matcher {
	return &matchers.Matcher{Type: matchers.MatcherTypeHolder{MatcherType: matchers.StatusMatcher}, Name: name}
}

func llmMatcher(name string) *matchers.Matcher {
	return &matchers.Matcher{Type: matchers.MatcherTypeHolder{MatcherType: matchers.LLMMatcher}, Name: name}
}

func TestExecuteSkipsLLMWhenCheapANDMatcherFails(t *testing.T) {
	counter := &opCounter{}
	// llm written first, exactly the order an author should not have to avoid
	ops := &Operators{Matchers: []*matchers.Matcher{llmMatcher("llm"), cheapMatcher("status")}}
	ops.matchersCondition = matchers.ANDCondition

	_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(false, true), counter.extractFunc(), false)
	require.False(t, ok)
	require.Equal(t, 0, counter.llmMatches, "a failing cheap matcher decides an AND, so the model must not be called")
}

func TestExecuteSkipsLLMWhenCheapORMatcherAlreadyMatched(t *testing.T) {
	counter := &opCounter{}
	ops := &Operators{Matchers: []*matchers.Matcher{llmMatcher("llm"), cheapMatcher("status")}}
	ops.matchersCondition = matchers.ORCondition

	_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(true, true), counter.extractFunc(), false)
	require.True(t, ok)
	require.Equal(t, 0, counter.llmMatches, "the outcome is already decided under OR")
}

func TestExecuteRunsLLMWhenCheapMatchersLeaveItUndecided(t *testing.T) {
	counter := &opCounter{}
	ops := &Operators{Matchers: []*matchers.Matcher{cheapMatcher("status"), llmMatcher("llm")}}
	ops.matchersCondition = matchers.ORCondition

	_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(false, true), counter.extractFunc(), false)
	require.True(t, ok)
	require.Equal(t, 1, counter.llmMatches)
}

func TestExecuteRunsLLMWhenCheapANDMatchersPass(t *testing.T) {
	counter := &opCounter{}
	ops := &Operators{Matchers: []*matchers.Matcher{llmMatcher("llm"), cheapMatcher("status")}}
	ops.matchersCondition = matchers.ANDCondition

	_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(true, true), counter.extractFunc(), false)
	require.True(t, ok)
	require.Equal(t, 1, counter.llmMatches)
}

// Reordering must not renumber the matchers, or unnamed ones silently change
// the names they report in output.
func TestExecutePreservesUnnamedMatcherIndexes(t *testing.T) {
	counter := &opCounter{}
	first := llmMatcher("")
	second := cheapMatcher("")
	ops := &Operators{Matchers: []*matchers.Matcher{first, second}}
	ops.matchersCondition = matchers.ORCondition

	result, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(false, true), counter.extractFunc(), true)
	require.True(t, ok)
	require.Contains(t, result.Matches, "llm-1", "the llm matcher keeps index 1 despite running second")
}

func TestExecuteDefersLLMExtractorUntilMatched(t *testing.T) {
	llmExtractor := &extractors.Extractor{
		Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.LLMExtractor}, Name: "version",
	}

	t.Run("no match", func(t *testing.T) {
		counter := &opCounter{}
		ops := &Operators{Matchers: []*matchers.Matcher{cheapMatcher("status")}, Extractors: []*extractors.Extractor{llmExtractor}}

		_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(false, false), counter.extractFunc(), false)
		require.False(t, ok)
		require.Equal(t, 0, counter.llmExtracts, "a 404 must not cost a model round trip")
	})

	t.Run("matched", func(t *testing.T) {
		counter := &opCounter{}
		ops := &Operators{Matchers: []*matchers.Matcher{cheapMatcher("status")}, Extractors: []*extractors.Extractor{llmExtractor}}

		_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(true, true), counter.extractFunc(), false)
		require.True(t, ok)
		require.Equal(t, 1, counter.llmExtracts)
	})
}

func TestExecuteRunsLLMExtractorWhenTemplateHasNoMatchers(t *testing.T) {
	counter := &opCounter{}
	ops := &Operators{Extractors: []*extractors.Extractor{
		{Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.LLMExtractor}, Name: "version"},
	}}

	_, ok := ops.Execute(map[string]interface{}{}, counter.matchFunc(false, false), counter.extractFunc(), false)
	require.True(t, ok)
	require.Equal(t, 1, counter.llmExtracts, "extraction is the point when there are no matchers")
}

// An internal extractor forces MergeMaps to a new outer map. The audit map must
// already be seeded on the caller's event so MatchLLM and AttachLLMAudits share
// the same inner map through that shallow copy.
func TestExecuteKeepsLLMAuditOnCallerEventAcrossDynamicMerge(t *testing.T) {
	audit := &matchers.LLMAudit{Verdict: "yes", Confidence: 0.9}
	ops := &Operators{
		Matchers: []*matchers.Matcher{llmMatcher("stack-trace")},
		Extractors: []*extractors.Extractor{{
			Name:     "token",
			Internal: true,
			Type:     extractors.ExtractorTypeHolder{ExtractorType: extractors.RegexExtractor},
		}},
	}

	data := map[string]interface{}{"body": "stack trace"}
	matchFn := func(d map[string]interface{}, matcher *matchers.Matcher) (bool, []string) {
		audits, ok := d[matchers.AuditEventKey].(map[string]*matchers.LLMAudit)
		require.True(t, ok, "Execute must seed the audit map before matchers run")
		audits[matcher.Name] = audit
		return true, []string{"stack"}
	}
	extractFn := func(map[string]interface{}, *extractors.Extractor) map[string]struct{} {
		return map[string]struct{}{"stack": {}}
	}

	result, ok := ops.Execute(data, matchFn, extractFn, false)
	require.True(t, ok)
	require.NotNil(t, result)
	require.NotEmpty(t, result.DynamicValues, "the internal extractor must force MergeMaps")

	got, ok := data[matchers.AuditEventKey].(map[string]*matchers.LLMAudit)
	require.True(t, ok, "the caller's InternalEvent must still hold the audit map")
	require.Same(t, audit, got["stack-trace"])
}

func TestLLMAuditLostWithoutPreMergeSeed(t *testing.T) {
	event := map[string]interface{}{"response": "x"}
	merged := generators.MergeMaps(event, map[string]interface{}{"token": "x"})
	merged[matchers.AuditEventKey] = map[string]*matchers.LLMAudit{
		"stack-trace": {Verdict: "yes"},
	}
	_, ok := event[matchers.AuditEventKey]
	require.False(t, ok, "a map created after MergeMaps stays on the merged copy")
}

package matchers

import (
	"encoding/hex"
	"fmt"
	"regexp"
	"strings"

	"github.com/projectdiscovery/govaluate"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/cache"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/common/dsl"
)

// CompileMatchers performs the initial setup operation on a matcher
func (matcher *Matcher) CompileMatchers() error {
	var ok bool

	// Support hexadecimal encoding for matchers too.
	if matcher.Encoding == "hex" {
		for i, word := range matcher.Words {
			if decoded, err := hex.DecodeString(word); err == nil && len(decoded) > 0 {
				matcher.Words[i] = string(decoded)
			}
		}
	}

	// Set up the matcher type
	computedType, err := toMatcherTypes(matcher.GetType().String())
	if err != nil {
		return fmt.Errorf("unknown matcher type specified: %s", matcher.Type)
	}

	matcher.matcherType = computedType

	// Validate the matcher structure
	if err := matcher.Validate(); err != nil {
		return err
	}

	// By default, match on body if user hasn't provided any specific items
	if matcher.Part == "" && matcher.GetType() != DSLMatcher {
		matcher.Part = "body"
	}

	// Compile the regexes (with shared cache)
	for _, regex := range matcher.Regex {
		if cached, err := cache.Regex().GetIFPresent(regex); err == nil && cached != nil {
			matcher.regexCompiled = append(matcher.regexCompiled, cached)
			continue
		}
		compiled, err := regexp.Compile(regex)
		if err != nil {
			return fmt.Errorf("could not compile regex: %s", regex)
		}
		_ = cache.Regex().Set(regex, compiled)
		matcher.regexCompiled = append(matcher.regexCompiled, compiled)
	}

	// Compile and validate binary Values in matcher
	for _, value := range matcher.Binary {
		if decoded, err := hex.DecodeString(value); err != nil {
			return fmt.Errorf("could not hex decode binary: %s", value)
		} else {
			matcher.binaryDecoded = append(matcher.binaryDecoded, string(decoded))
		}
	}

	// Compile the dsl expressions (with shared cache)
	for _, dslExpression := range matcher.DSL {
		if cached, err := cache.DSL().GetIFPresent(dslExpression); err == nil && cached != nil {
			matcher.dslCompiled = append(matcher.dslCompiled, cached)
			continue
		}
		compiledExpression, err := govaluate.NewEvaluableExpressionWithFunctions(dslExpression, dsl.HelperFunctions)
		if err != nil {
			return &dsl.CompilationError{DslSignature: dslExpression, WrappedError: err}
		}
		_ = cache.DSL().Set(dslExpression, compiledExpression)
		matcher.dslCompiled = append(matcher.dslCompiled, compiledExpression)
	}

	// Set up the condition type, if any.
	if matcher.Condition != "" {
		matcher.condition, ok = ConditionTypes[matcher.Condition]
		if !ok {
			return fmt.Errorf("unknown condition specified: %s", matcher.Condition)
		}
	} else {
		matcher.condition = ORCondition
	}

	if matcher.CaseInsensitive {
		if matcher.GetType() != WordsMatcher {
			return fmt.Errorf("case-insensitive flag is supported only for 'word' matchers (not '%s')", matcher.Type)
		}
		for i := range matcher.Words {
			matcher.Words[i] = strings.ToLower(matcher.Words[i])
		}
	}
	return nil
}

// GetType returns the condition type of the matcher
// todo: the field should be exposed natively
func (matcher *Matcher) GetCondition() ConditionType {
	return matcher.condition
}

package matchers

import (
	"fmt"
	"testing"

	"github.com/stretchr/testify/require"
	"gopkg.in/yaml.v3"
)

func TestCompileMatchersRequiresValues(t *testing.T) {
	tests := []struct {
		typ    string
		field  string
		values string
	}{
		{"word", "words", `["hello"]`},
		{"regex", "regex", `["hello"]`},
		{"binary", "binary", `["00"]`},
		{"status", "status", `[200]`},
		{"size", "size", `[0]`},
		{"dsl", "dsl", `["true"]`},
		{"xpath", "xpath", `["//a"]`},
	}
	for _, tt := range tests {
		t.Run(tt.typ, func(t *testing.T) {
			for _, suffix := range []struct{ name, yaml string }{
				{"omitted", ""},
				{"null", tt.field + ": null\n"},
				{"empty", tt.field + ": []\n"},
			} {
				t.Run(suffix.name, func(t *testing.T) {
					var operator Matcher
					require.NoError(t, yaml.Unmarshal([]byte("type: "+tt.typ+"\n"+suffix.yaml), &operator))
					require.ErrorContains(t, operator.CompileMatchers(), fmt.Sprintf("%s matcher requires at least one %s value", tt.typ, tt.field))
				})
			}
			t.Run("valid", func(t *testing.T) {
				var operator Matcher
				require.NoError(t, yaml.Unmarshal([]byte("type: "+tt.typ+"\n"+tt.field+": "+tt.values), &operator))
				require.NoError(t, operator.CompileMatchers())
			})
		})
	}
}

func TestCompileMatchersAllowsEmptyStringValue(t *testing.T) {
	m := &Matcher{
		Type:  MatcherTypeHolder{MatcherType: WordsMatcher},
		Words: []string{""},
	}
	require.NoError(t, m.CompileMatchers())
	matched, _ := m.MatchWords("body", nil)
	require.True(t, matched)
}

func TestCompileMatchersDSLTrailingBackslash(t *testing.T) {
	// Regression test: a DSL expression whose string literal ends in a
	// backslash used to panic the govaluate lexer (index out of range)
	// while a template was loading. It must surface as a compile error.
	var operator Matcher
	require.NoError(t, yaml.Unmarshal([]byte("type: dsl\ndsl:\n  - \"body == 'x\\\\'\"\n"), &operator))
	require.ErrorContains(t, operator.CompileMatchers(), "Unclosed string literal")
}

// Package matchers implements matchers for http response
// matching with templates.
package matchers

package matchers

import (
	"fmt"
	"regexp"
	"sort"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/expressions"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/render"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

var dslStringMarkerRegex = regexp.MustCompile(`\{\{([^{}]+)\}\}`)

// dslStringMarker represents a span of an unresolved DSL expression within a
// string literal.
type dslStringMarker struct {
	start int
	end   int
	expr  string
	quote byte
}

type textSpan struct {
	start int
	end   int
}

type stringLiteralSpan struct {
	start int
	end   int
	quote byte
}

func resolveDSLStringMarkers(expression string, data map[string]interface{}, options *types.Options) (string, error) {
	// Resolve only marker spans already present in the compiled DSL source.
	// Values are escaped for the surrounding string literal before recompilation.
	stringSpans := findStringLiteralSpans(expression)
	markers, err := findDSLStringMarkers(expression, data, stringSpans)
	if err != nil {
		return "", err
	}

	if len(markers) == 0 {
		return "", fmt.Errorf("unresolved DSL placeholders must be inside string literals")
	}

	sort.Slice(markers, func(i, j int) bool {
		return markers[i].start > markers[j].start
	})

	resolved := expression
	for _, marker := range markers {
		result, err := render.Render(render.Input{
			Text:    "{{" + marker.expr + "}}",
			Values:  data,
			Options: options,
		})
		if err != nil {
			return "", err
		}

		replacement := expressions.EscapeStringValue(result.Text, marker.quote)
		resolved = resolved[:marker.start] + replacement + resolved[marker.end:]
	}

	return resolved, nil
}

func findDSLStringMarkers(expression string, data map[string]interface{}, stringSpans []stringLiteralSpan) ([]dslStringMarker, error) {
	var markers []dslStringMarker
	var occupiedSpans []textSpan

	seenComplex := make(map[string]struct{})

	for _, expr := range expressions.FindExpressions(expression, "{{", "}}", data) {
		if _, ok := seenComplex[expr]; ok {
			continue
		}
		seenComplex[expr] = struct{}{}

		marker := "{{" + expr + "}}"
		for start := 0; ; {
			index := strings.Index(expression[start:], marker)
			if index < 0 {
				break
			}

			index += start
			end := index + len(marker)

			stringSpan, ok := stringLiteralForSpan(stringSpans, index, end)
			if !ok {
				return nil, fmt.Errorf("unresolved DSL placeholder %q is not inside a string literal", expr)
			}

			got := dslStringMarker{start: index, end: end, expr: expr, quote: stringSpan.quote}
			markers = append(markers, got)
			occupiedSpans = append(occupiedSpans, textSpan{start: index, end: end})
			start = end
		}
	}

	for _, match := range dslStringMarkerRegex.FindAllStringSubmatchIndex(expression, -1) {
		if len(match) < 4 || markerWithinSpans(match[0], match[1], occupiedSpans) {
			continue
		}

		stringSpan, ok := stringLiteralForSpan(stringSpans, match[0], match[1])
		if !ok {
			return nil, fmt.Errorf("unresolved DSL placeholder %q is not inside a string literal", expression[match[2]:match[3]])
		}

		markers = append(markers, dslStringMarker{
			start: match[0],
			end:   match[1],
			expr:  expression[match[2]:match[3]],
			quote: stringSpan.quote,
		})
	}

	return markers, nil
}

func markerWithinSpans(start, end int, spans []textSpan) bool {
	for _, span := range spans {
		if start >= span.start && end <= span.end {
			return true
		}
	}

	return false
}

func findStringLiteralSpans(expression string) []stringLiteralSpan {
	var spans []stringLiteralSpan
	var quote byte
	start := 0
	escaped := false

	for i := 0; i < len(expression); i++ {
		char := expression[i]
		if escaped {
			escaped = false
			continue
		}

		if char == '\\' {
			escaped = true
			continue
		}

		if quote != 0 {
			if char == quote {
				spans = append(spans, stringLiteralSpan{start: start, end: i, quote: quote})
				quote = 0
			}
			continue
		}

		if char == '\'' || char == '"' {
			quote = char
			start = i + 1
		}
	}

	if quote != 0 {
		spans = append(spans, stringLiteralSpan{start: start, end: len(expression), quote: quote})
	}

	return spans
}

func stringLiteralForSpan(spans []stringLiteralSpan, start, end int) (stringLiteralSpan, bool) {
	for _, span := range spans {
		if start >= span.start && end <= span.end {
			return span, true
		}
	}

	return stringLiteralSpan{}, false
}

