// ErrHoneypotSuppressed is returned by the output writer when a match result is suppressed
// due to honeypot detection.
var ErrHoneypotSuppressed = stderrors.New("honeypot suppressed result")

// Writer is an interface which writes output to somewhere for nuclei events.
type Writer interface {
	// Close closes the output writer interface
	Close()
	// Colorizer returns the colorizer instance for writer
	Colorizer() *aurora.Aurora
	// Write writes the event to file and/or screen.
	Write(*ResultEvent) error
	// WriteFailure writes the optional failure event for template to file and/or screen.
	WriteFailure(*InternalWrappedEvent) error
	// Request logs a request in the trace log
	Request(templateID, url, requestType string, err error)
	// RequestStatsLog logs a request stats log
	RequestStatsLog(statusCode, response string)
	//  WriteStoreDebugData writes the request/response debug data to file
	WriteStoreDebugData(host, templateID, eventType string, data string)
	// ResultCount returns the total number of results written
	ResultCount() int
}

// StandardWriter is a writer writing output to file and screen for results.
type StandardWriter struct {
	json                  bool
	jsonReqResp           bool
	timestamp             bool
	noMetadata            bool
	matcherStatus         bool
	responseSaveSize      int
	honeypotDetector      *honeypotdetector.Detector
	suppressHoneypot      bool
	honeypotThreshold     int
	mutex                 *sync.Mutex
	aurora                *aurora.Aurora
	outputFile            io.WriteCloser
	traceFile             io.WriteCloser
	errorFile             io.WriteCloser
	severityColors        func(severity.Severity) string
	storeResponse         bool
	storeResponseDir      string
	omitTemplate          bool
	DisableStdout         bool
	AddNewLinesOutputFile bool // by default this is only done for stdout
	KeysToRedact          []string
	// NoRedact skips the default credential keys; KeysToRedact still apply.
	NoRedact bool

	// redactSet caches the compiled credential-redaction regexes so they
	// are not recompiled on every Write call.
	redactPatternsOnce sync.Once
	redactSet          compiledRedaction

	// JSONLogRequestHook is a hook that can be used to log request/response
	// when using custom server code with output
	JSONLogRequestHook func(*JSONLogRequest)

	resultCount atomic.Int32
}

var _ Writer = &StandardWriter{}

var decolorizerRegex = regexp.MustCompile(`\x1B\[[0-9;]*[a-zA-Z]`)

// InternalEvent is an internal output generation structure for nuclei.
type InternalEvent map[string]interface{}

func (ie InternalEvent) Set(k string, v interface{}) {
	ie[k] = v
}

// InternalWrappedEvent is a wrapped event with operators result added to it.
type InternalWrappedEvent struct {
	// Mutex is internal field which is implicitly used
	// to synchronize callback(event) and interactsh polling updates
	// Refer protocols/http.Request.ExecuteWithResults for more details
	sync.RWMutex

	InternalEvent   InternalEvent
	Results         []*ResultEvent
	OperatorsResult *operators.Result
	UsesInteractsh  bool
	// Only applicable if interactsh is used
	// This is used to avoid duplicate successful interactsh events
	InteractshMatched atomic.Bool
	// CatchAll reports whether the response is the page the host serves for
	// any missing path. It probes the host on first call, so it is only asked
	// once a template matched. Nil when calibration is off or does not apply.
	CatchAll func() bool
}

func (iwe *InternalWrappedEvent) CloneShallow() *InternalWrappedEvent {
	return &InternalWrappedEvent{
		InternalEvent:   maps.Clone(iwe.InternalEvent),
		Results:         nil,
		OperatorsResult: nil,
		UsesInteractsh:  iwe.UsesInteractsh,
		CatchAll:        iwe.CatchAll,
	}
}

func (iwe *InternalWrappedEvent) HasOperatorResult() bool {
	iwe.RLock()
	defer iwe.RUnlock()

	return iwe.OperatorsResult != nil
}

func (iwe *InternalWrappedEvent) HasResults() bool {
	iwe.RLock()
	defer iwe.RUnlock()

	return len(iwe.Results) > 0
}

func (iwe *InternalWrappedEvent) SetOperatorResult(operatorResult *operators.Result) {
	iwe.Lock()
	defer iwe.Unlock()

	iwe.OperatorsResult = operatorResult
}

// ResultEvent is a wrapped result event for a single nuclei output.
type ResultEvent struct {
	// Template is the relative filename for the template
	Template string `json:"template,omitempty"`
	// TemplateURL is the URL of the template for the result inside the nuclei
	// templates repository if it belongs to the repository.
	TemplateURL string `json:"template-url,omitempty"`
	// TemplateID is the ID of the template for the result.
	TemplateID string `json:"template-id"`
	// TemplatePath is the path of template
	TemplatePath string `json:"template-path,omitempty"`
	// TemplateEncoded is the base64 encoded template
	TemplateEncoded string `json:"template-encoded,omitempty"`
	// Info contains information block of the template for the result.
	Info model.Info `json:"info,inline"`
	// MatcherName is the name of the matcher matched if any.
	MatcherName string `json:"matcher-name,omitempty"`
	// ExtractorName is the name of the extractor matched if any.
	ExtractorName string `json:"extractor-name,omitempty"`
	// LLM records the model verdict behind this finding, present only when an
	// llm matcher produced it. An llm verdict is not reproducible the way a
	// pattern match is, so the finding carries what it takes to audit it.
	LLM *matchers.LLMAudit `json:"llm,omitempty"`
	// Type is the type of the result event.
	Type string `json:"type"`
	// Host is the host input on which match was found.
	Host string `json:"host,omitempty"`
	// Port is port of the host input on which match was found (if applicable).
	Port string `json:"port,omitempty"`
	// Scheme is the scheme of the host input on which match was found (if applicable).
	Scheme string `json:"scheme,omitempty"`
	// URL is the Base URL of the host input on which match was found (if applicable).
	URL string `json:"url,omitempty"`
	// Path is the path input on which match was found.
	Path string `json:"path,omitempty"`
	// Matched contains the matched input in its transformed form.
	Matched string `json:"matched-at,omitempty"`
	// ExtractedResults contains the extraction result from the inputs.
	ExtractedResults []string `json:"extracted-results,omitempty"`
	// Request is the optional, dumped request for the match.
	Request string `json:"request,omitempty"`
	// Response is the optional, dumped response for the match.
	Response string `json:"response,omitempty"`
	// Metadata contains any optional metadata for the event
	Metadata map[string]interface{} `json:"meta,omitempty"`
	// IP is the IP address for the found result event.
	IP string `json:"ip,omitempty"`
	// Timestamp is the time the result was found at.
	Timestamp time.Time `json:"timestamp"`
	// Interaction is the full details of interactsh interaction.
	Interaction *server.Interaction `json:"interaction,omitempty"`
	// CURLCommand is an optional curl command to reproduce the request
	// Only applicable if the report is for HTTP.
	CURLCommand string `json:"curl-command,omitempty"`
	// MatcherStatus is the status of the match
	MatcherStatus bool `json:"matcher-status"`
	// Lines is the line count for the specified match
	Lines []int `json:"matched-line,omitempty"`
	// GlobalMatchers identifies whether the matches was detected in the response
	// of another template's result event
	GlobalMatchers bool `json:"global-matchers,omitempty"`

	// IssueTrackers is the metadata for issue trackers
	IssueTrackers map[string]IssueTrackerMetadata `json:"issue_trackers,omitempty"`
	// ReqURLPattern when enabled contains base URL pattern that was used to generate the request
	// must be enabled by setting protocols.ExecuterOptions.ExportReqURLPattern to true
	ReqURLPattern string `json:"req_url_pattern,omitempty"`

	// Fields related to HTTP Fuzzing functionality of nuclei.
	// The output contains additional fields when the result is
	// for a fuzzing template.
	IsFuzzingResult  bool   `json:"is_fuzzing_result,omitempty"`
	FuzzingMethod    string `json:"fuzzing_method,omitempty"`
	FuzzingParameter string `json:"fuzzing_parameter,omitempty"`
	FuzzingPosition  string `json:"fuzzing_position,omitempty"`
	AnalyzerDetails  string `json:"analyzer_details,omitempty"`

	FileToIndexPosition map[string]int `json:"-"`
	TemplateVerifier    string         `json:"-"`
	Error               string         `json:"error,omitempty"`
	// TemplateInfo is the info as the template wrote it, kept only when
	// placeholders changed the text. The changed fields can carry response data,
	// so they are redacted like the raw request and response. It is bookkeeping,
	// so no exporter writes it; mongo serializes with bson tags, not json ones.
	TemplateInfo *model.Info `json:"-" bson:"-"`
}

// MarshalJSON encodes the event with every map nested in Metadata keyed by
// strings. Metadata can hold javascript args decoded from template YAML.
func (r ResultEvent) MarshalJSON() ([]byte, error) {
	// resultEvent has the fields of ResultEvent but not this method, so marshaling it does not recurse.
	type resultEvent ResultEvent
	encoded := resultEvent(r)
	metadata, err := types.ToJSONMap(r.Metadata)
	if err != nil {
		return nil, err
	}
	encoded.Metadata = metadata
	return json.Marshal(encoded)
}

type IssueTrackerMetadata struct {
	// IssueID is the ID of the issue created
	IssueID string `json:"id,omitempty"`
	// IssueURL is the URL of the issue created
	IssueURL string `json:"url,omitempty"`
}

// NewStandardWriter creates a new output writer based on user configurations
func NewStandardWriter(options *types.Options) (*StandardWriter, error) {
	resumeBool := options.Resume != ""

	auroraColorizer := aurora.New(aurora.WithColors(!options.NoColor))

	var outputFile io.WriteCloser
	if options.Output != "" {
		output, err := newFileOutputWriter(options.Output, resumeBool)
		if err != nil {
			return nil, errors.Wrap(err, "could not create output file")
		}
		outputFile = output
	}
	var traceOutput io.WriteCloser
	if options.TraceLogFile != "" {
		output, err := newFileOutputWriter(options.TraceLogFile, resumeBool)
		if err != nil {
			return nil, errors.Wrap(err, "could not create output file")
		}
		traceOutput = output
	}
	var errorOutput io.WriteCloser
	if options.ErrorLogFile != "" {
		output, err := newFileOutputWriter(options.ErrorLogFile, resumeBool)
		if err != nil {
			return nil, errors.Wrap(err, "could not create error file")
		}
		errorOutput = output
	}
	// Try to create output folder if it doesn't exist
	if options.StoreResponse && !fileutil.FolderExists(options.StoreResponseDir) {
		if err := fileutil.CreateFolder(options.StoreResponseDir); err != nil {
			gologger.Fatal().Msgf("Could not create output directory '%s': %s\n", options.StoreResponseDir, err)
		}
	}

	writer := &StandardWriter{
		json:              options.JSONL,
		jsonReqResp:       !options.OmitRawRequests,
		noMetadata:        options.NoMeta,
		matcherStatus:     options.MatcherStatus,
		responseSaveSize:  options.ResponseSaveSize,
		timestamp:         options.Timestamp,
		suppressHoneypot:  options.SuppressHoneypotResults,
		honeypotThreshold: options.HoneypotThreshold,
		aurora:            auroraColorizer,
		mutex:             &sync.Mutex{},
		outputFile:        outputFile,
		traceFile:         traceOutput,
		errorFile:         errorOutput,
		severityColors:    colorizer.New(auroraColorizer),
		storeResponse:     options.StoreResponse,
		storeResponseDir:  options.StoreResponseDir,
		omitTemplate:      options.OmitTemplate,
		KeysToRedact:      options.Redact,
		NoRedact:          options.NoRedact,
	}

	if v := os.Getenv("DISABLE_STDOUT"); v == "true" || v == "1" {
		writer.DisableStdout = true
	}

	return writer, nil
}

// SetHoneypotDetector attaches an initialized honeypot detector to the writer.
func (w *StandardWriter) SetHoneypotDetector(detector *honeypotdetector.Detector) {
	w.honeypotDetector = detector
	if detector != nil {
		w.honeypotThreshold = detector.Threshold()
	}
}

func (w *StandardWriter) ResultCount() int {
	return int(w.resultCount.Load())
}

// Write writes the event to file and/or screen.
func (w *StandardWriter) Write(event *ResultEvent) error {
	if event.Error != "" && !w.matcherStatus {
		return nil
	}

	// Honeypot detection is performed only for successful matches.
	if event.MatcherStatus && w.honeypotDetector != nil {
		hostKey := event.URL
		if hostKey == "" && event.Host != "" {
			hostKey = event.Host
			if event.Port != "" {
				hostKey = net.JoinHostPort(event.Host, event.Port)
			}
		}

		if hostKey != "" {
			justFlagged := w.honeypotDetector.RecordMatch(hostKey, event.TemplateID)
			if justFlagged {
				normalized := honeypotdetector.NormalizeHostKey(hostKey)
				gologger.Warning().Msgf("Potential honeypot detected: %s (matched %d distinct templates)", normalized, w.honeypotThreshold)
			}

			if w.suppressHoneypot && w.honeypotDetector.IsFlagged(hostKey) {
				return ErrHoneypotSuppressed
			}
		}
	}

	// Enrich the result event with extra metadata on the template-path and url.
	if event.TemplatePath != "" {
		event.Template, event.TemplateURL = utils.TemplatePathURL(types.ToString(event.TemplatePath), types.ToString(event.TemplateID), event.TemplateVerifier)
	}

	// redact the default credential-bearing keys in addition to any
	// user-supplied -redact keys. patterns are compiled once and cached to
	// avoid recompiling regexes on every event in the write hot path.
	patterns := w.redactionPatterns()
	event.Request = redactWithSet(event.Request, patterns)
	event.Response = redactWithSet(event.Response, patterns)
	event.CURLCommand = redactWithSet(event.CURLCommand, patterns)
	event.Matched = redactWithSet(event.Matched, patterns)
	for _, field := range event.Info.FilledFields(event.TemplateInfo) {
		*field.Value = redactWithSet(*field.Value, patterns)
	}
	if w.responseSaveSize > 0 && len(event.Response) > w.responseSaveSize && event.Type == "http" {
		event.Response = truncateResponse(event.Response, w.responseSaveSize)
	}

	event.Timestamp = time.Now()

	var data []byte
	var err error

	if w.json {
		data, err = w.formatJSON(event)
	} else {
		data = w.formatScreen(event)
	}
	if err != nil {
		return errors.Wrap(err, "could not format output")
	}
	if len(data) == 0 {
		return nil
	}
	w.mutex.Lock()
	defer w.mutex.Unlock()

	if !w.DisableStdout {
		_, _ = os.Stdout.Write(data)
		_, _ = os.Stdout.Write([]byte("\n"))
	}

	if w.outputFile != nil {
		if !w.json {
			data = decolorizerRegex.ReplaceAll(data, []byte(""))
		}
		if _, writeErr := w.outputFile.Write(data); writeErr != nil {
			return errors.Wrap(writeErr, "could not write to output")
		}
		if w.AddNewLinesOutputFile && w.json {
			_, _ = w.outputFile.Write([]byte("\n"))
		}
	}
	w.resultCount.Add(1)
	return nil
}

// defaultRedactKeys are header and parameter names that are redacted from
// output regardless of the -redact flag, unless -no-redact is set.
var defaultRedactKeys = []string{
	"Authorization",
	"Proxy-Authorization",
	"Cookie",
	"Set-Cookie",
	"X-Api-Key",
}

// cookieHeaderValue is the value of one Cookie or Set-Cookie header, stopping
// at a quote so a curl -H 'Cookie: ...' does not swallow the rest of the line.
var cookieHeaderValue = regexp.MustCompile(`(?i)((?:Cookie|Set-Cookie)\s*:\s*)([^"'\r\n]*)`)

// compiledRedaction holds the three shapes a key can take. A header value is
// masked to the end of the line. Inside a cookie header, key=value stops at
// the next cookie delimiter so neighbouring cookies stay. A query value keeps
// an embedded ';' and runs to '&', a quote, or whitespace.
type compiledRedaction struct {
	headers []*regexp.Regexp
	cookies []*regexp.Regexp
	queries []*regexp.Regexp
}

func (c compiledRedaction) empty() bool {
	return len(c.headers) == 0 && len(c.cookies) == 0 && len(c.queries) == 0
}

// compileRedactPatterns builds the credential-redaction regexes for the given keys.
func compileRedactPatterns(keys []string) compiledRedaction {
	var set compiledRedaction
	for _, key := range keys {
		quoted := regexp.QuoteMeta(key)
		set.headers = append(set.headers, regexp.MustCompile(fmt.Sprintf(`(?i)(%s\s*:\s*["']?)([^"'&\r\n]+)(["'\r\n]|$)`, quoted)))
		set.cookies = append(set.cookies, regexp.MustCompile(fmt.Sprintf(`(?i)(%s\s*=\s*["']?)([^"'&\r\n\s]*?)(;\s*[\w.-]+(?:=|;|\r|\n|$)|["'&\r\n\s]|$)`, quoted)))
		set.queries = append(set.queries, regexp.MustCompile(fmt.Sprintf(`(?i)(%s\s*=\s*["']?)([^"'&\r\n\s]*)(["'&\r\n\s]|$)`, quoted)))
	}
	return set
}

// redactionPatterns returns the cached redaction set for this writer (default
// keys unless -no-redact is set, plus any user-supplied -redact keys).
func (w *StandardWriter) redactionPatterns() compiledRedaction {
	w.redactPatternsOnce.Do(func() {
		keys := make([]string, 0, len(defaultRedactKeys)+len(w.KeysToRedact))
		if !w.NoRedact {
			keys = append(keys, defaultRedactKeys...)
		}
		keys = append(keys, w.KeysToRedact...)
		w.redactSet = compileRedactPatterns(keys)
	})
	return w.redactSet
}

func redactKeys(data string, keys []string) string {
	return redactWithSet(data, compileRedactPatterns(keys))
}

func redactWithSet(data string, set compiledRedaction) string {
	if data == "" || set.empty() {
		return data
	}
	data = applyRedact(data, set.headers)
	if len(set.cookies) > 0 {
		data = cookieHeaderValue.ReplaceAllStringFunc(data, func(match string) string {
			parts := cookieHeaderValue.FindStringSubmatch(match)
			if len(parts) != 3 {
				return match
			}
			return parts[1] + applyRedact(parts[2], set.cookies)
		})
	}
	return redactOutsideCookieValues(data, set.queries)
}

func redactOutsideCookieValues(data string, patterns []*regexp.Regexp) string {
	if len(patterns) == 0 {
		return data
	}
	locs := cookieHeaderValue.FindAllStringSubmatchIndex(data, -1)
	if len(locs) == 0 {
		return applyRedact(data, patterns)
	}
	var b strings.Builder
	prev := 0
	for _, loc := range locs {
		valueStart, valueEnd := loc[4], loc[5]
		b.WriteString(applyRedact(data[prev:valueStart], patterns))
		b.WriteString(data[valueStart:valueEnd])
		prev = valueEnd
	}
	b.WriteString(applyRedact(data[prev:], patterns))
	return b.String()
}

func applyRedact(data string, patterns []*regexp.Regexp) string {
	for _, pattern := range patterns {
		data = pattern.ReplaceAllString(data, `$1***$3`)
	}
	return data
}

// JSONLogRequest is a trace/error log request written to file
type JSONLogRequest struct {
	Template  string      `json:"template"`
	Type      string      `json:"type"`
	Input     string      `json:"input"`
	Timestamp *time.Time  `json:"timestamp,omitempty"`
	Address   string      `json:"address"`
	Error     string      `json:"error"`
	Kind      string      `json:"kind,omitempty"`
	Attrs     interface{} `json:"attrs,omitempty"`
}

// Request writes a log the requests trace log
func (w *StandardWriter) Request(templatePath, input, requestType string, requestErr error) {
	if w.traceFile == nil && w.errorFile == nil && w.JSONLogRequestHook == nil {
		return
	}

	request := getJSONLogRequestFromError(templatePath, input, requestType, requestErr)
	if w.timestamp {
		ts := time.Now()
		request.Timestamp = &ts
	}
	data, err := json.Marshal(request)
	if err != nil {
		return
	}

	if w.JSONLogRequestHook != nil {
		w.JSONLogRequestHook(request)
	}

	if w.traceFile != nil {
		_, _ = w.traceFile.Write(data)
	}

	if requestErr != nil && w.errorFile != nil {
		_, _ = w.errorFile.Write(data)
	}
}

func getJSONLogRequestFromError(templatePath, input, requestType string, requestErr error) *JSONLogRequest {
	request := &JSONLogRequest{
		Template: templatePath,
		Input:    input,
		Type:     requestType,
	}

	parsed, _ := urlutil.ParseAbsoluteURL(input, false)
	if parsed != nil {
		request.Address = parsed.Hostname()
		port := parsed.Port()
		if port == "" {
			switch parsed.Scheme {
			case urlutil.HTTP:
				port = "80"
			case urlutil.HTTPS:
				port = "443"
			}
		}
		request.Address += ":" + port
	}
	errX := errkit.FromError(requestErr)
	if errX == nil {
		request.Error = "none"
	} else {
		request.Kind = errkit.ErrKindUnknown.String()
		var cause error
		if len(errX.Errors()) > 1 {
			cause = errX.Errors()[0]
		}
		if cause == nil {
			cause = errX
		}
		cause = tryParseCause(cause)
		request.Error = cause.Error()
		request.Kind = errkit.GetErrorKind(requestErr, nucleierr.ErrTemplateLogic).String()
		if len(errX.Attrs()) > 0 {
			request.Attrs = slog.GroupValue(errX.Attrs()...)
		}
	}
	// check if address slog attr is available in error if set use it
	if val := errkit.GetAttrValue(requestErr, "address"); val.Any() != nil {
		request.Address = val.String()
	}
	return request
}

