	data, err := w.formatJSON(event)
	require.NoError(t, err, "formatJSON should not fail on nested map[interface{}]interface{} (#7971)")
	require.Contains(t, string(data), `"labels":{"en":"Hello","nested_list":[{"inner_key":"inner_val"}]}`)
}

package output

import (
	"io"
	"os"
	"sync"

	"github.com/logrusorgru/aurora/v4"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	fileutil "github.com/projectdiscovery/utils/file"
)

// WriterOptions contains configuration options for a writer
type WriterOptions func(s *StandardWriter) error

// WithJson writes output in json format
func WithJson(json bool, dumpReqResp bool) WriterOptions {
	return func(s *StandardWriter) error {
		s.json = json
		s.jsonReqResp = dumpReqResp
		return nil
	}
}

// WithTimestamp writes output with timestamp
func WithTimestamp(timestamp bool) WriterOptions {
	return func(s *StandardWriter) error {
		s.timestamp = timestamp
		return nil
	}
}

// WithNoMetadata disables metadata output
func WithNoMetadata(noMetadata bool) WriterOptions {
	return func(s *StandardWriter) error {
		s.noMetadata = noMetadata
		return nil
	}
}

// WithMatcherStatus writes output with matcher status
func WithMatcherStatus(matcherStatus bool) WriterOptions {
	return func(s *StandardWriter) error {
		s.matcherStatus = matcherStatus
		return nil
	}
}

// WithAurora sets the aurora instance for the writer
func WithAurora(aurora *aurora.Aurora) WriterOptions {
	return func(s *StandardWriter) error {
		s.aurora = aurora
		return nil
	}
}

// WithWriter sets the writer for the writer
func WithWriter(outputFile io.WriteCloser) WriterOptions {
	return func(s *StandardWriter) error {
		s.outputFile = outputFile
		return nil
	}
}

// WithTraceSink sets the writer where trace output is written
func WithTraceSink(traceFile io.WriteCloser) WriterOptions {
	return func(s *StandardWriter) error {
		s.traceFile = traceFile
		return nil
	}
}

// WithErrorSink sets the writer where error output is written
func WithErrorSink(errorFile io.WriteCloser) WriterOptions {
	return func(s *StandardWriter) error {
		s.errorFile = errorFile
		return nil
	}
}

// WithSeverityColors sets the color function for severity
func WithSeverityColors(severityColors func(severity.Severity) string) WriterOptions {
	return func(s *StandardWriter) error {
		s.severityColors = severityColors
		return nil
	}
}

// WithStoreResponse sets the store response option
func WithStoreResponse(storeResponse bool, respDir string) WriterOptions {
	return func(s *StandardWriter) error {
		s.storeResponse = storeResponse
		s.storeResponseDir = respDir
		return nil
	}
}

// NewWriter creates a new output writer
// if no writer is specified it writes to stdout
func NewWriter(opts ...WriterOptions) (*StandardWriter, error) {
	s := &StandardWriter{
		mutex:                 &sync.Mutex{},
		DisableStdout:         true,
		AddNewLinesOutputFile: true,
	}
	for _, opt := range opts {
		if err := opt(s); err != nil {
			return nil, err
		}
	}
	if s.aurora == nil {
		s.aurora = aurora.New(aurora.WithColors(false))
	}
	if s.outputFile == nil {
		s.outputFile = os.Stdout
	}
	// Try to create output folder if it doesn't exist
	if s.storeResponse && !fileutil.FolderExists(s.storeResponseDir) {
		if err := fileutil.CreateFolder(s.storeResponseDir); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// Package stats provides a stats tracker for tracking Status Codes,
// Errors & WAF detection events.
//
// It is wrapped and called by output.Writer interface.
package stats

import (
	_ "embed"
	"fmt"
	"sort"
	"strconv"
	"sync"
	"sync/atomic"
	"time"

	"github.com/logrusorgru/aurora/v4"
	"github.com/projectdiscovery/nuclei/v3/pkg/output/stats/waf"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

var sharedWafDetector = sync.OnceValue(waf.NewWafDetector)

// Tracker is a stats tracker instance for nuclei scans
type Tracker struct {
	// counters for various stats
	statusCodes *mapsutil.SyncLockMap[string, *atomic.Int32]
	errorCodes  *mapsutil.SyncLockMap[string, *atomic.Int32]
	wafDetected *mapsutil.SyncLockMap[string, *atomic.Int32]
	wafCalls    atomic.Uint64
	wafBytes    atomic.Uint64
	wafRegexes  atomic.Uint64
	wafSkips    atomic.Uint64
	wafDuration atomic.Uint64

	// counterMu serializes get-or-create of the counters above. Each map is
	// concurrency safe on its own, but the read-then-write pair across a map
	// is not: when two goroutines race on the first hit for the same key they
	// each install their own counter, the later Set discards the earlier one,
	// and every increment already made on the discarded counter is lost.
	counterMu sync.Mutex

	// internal stuff
	wafDetector *waf.WafDetector
}

// NewTracker creates a new Tracker instance.
func NewTracker() *Tracker {
	return &Tracker{
		statusCodes: mapsutil.NewSyncLockMap[string, *atomic.Int32](),
		errorCodes:  mapsutil.NewSyncLockMap[string, *atomic.Int32](),
		wafDetected: mapsutil.NewSyncLockMap[string, *atomic.Int32](),
		wafDetector: sharedWafDetector(),
	}
}

// TrackStatusCode tracks the status code of a request
func (t *Tracker) TrackStatusCode(statusCode string) {
	t.incrementCounter(t.statusCodes, statusCode)
}

// TrackErrorKind tracks the error kind of a request
func (t *Tracker) TrackErrorKind(errKind string) {
	t.incrementCounter(t.errorCodes, errKind)
}

// TrackWAFDetected tracks the waf detected of a request
//
// First it detects if a waf is running and if so, it increments
// the counter for the waf.
func (t *Tracker) TrackWAFDetected(httpResponse string) {
	started := time.Now()
	id, ok, detectionStats := t.wafDetector.DetectWAFWithStats(httpResponse)
	t.wafCalls.Add(1)
	t.wafBytes.Add(uint64(len(httpResponse)))
	t.wafRegexes.Add(uint64(detectionStats.RegexEvaluations))
	t.wafSkips.Add(uint64(detectionStats.PrefilterSkips))
	t.wafDuration.Add(uint64(time.Since(started)))
	if !ok {
		return
	}

	t.incrementCounter(t.wafDetected, id)
}

// WAFMetrics reports execution-local WAF analysis work. It is separate from
// StatsOutput because it is operational telemetry rather than customer-facing
// scan statistics.
type WAFMetrics struct {
	Calls            uint64
	Bytes            uint64
	RegexEvaluations uint64
	PrefilterSkips   uint64
	Duration         time.Duration
}

// GetWAFMetrics returns an atomic snapshot suitable for progress logging while
// requests are still executing.
func (t *Tracker) GetWAFMetrics() WAFMetrics {
	return WAFMetrics{
		Calls:            t.wafCalls.Load(),
		Bytes:            t.wafBytes.Load(),
		RegexEvaluations: t.wafRegexes.Load(),
		PrefilterSkips:   t.wafSkips.Load(),
		Duration:         time.Duration(t.wafDuration.Load()),
	}
}

func (t *Tracker) incrementCounter(m *mapsutil.SyncLockMap[string, *atomic.Int32], key string) {
	counter, ok := m.Get(key)
	if !ok {
		counter = t.getOrCreateCounter(m, key)
	}
	counter.Add(1)
}

// getOrCreateCounter returns the counter stored for key, creating and storing
// it when it is still absent. Only creation is serialized, so concurrent first
// hits for the same key all end up incrementing one counter; the Add itself
// stays outside the lock.
func (t *Tracker) getOrCreateCounter(m *mapsutil.SyncLockMap[string, *atomic.Int32], key string) *atomic.Int32 {
	t.counterMu.Lock()
	defer t.counterMu.Unlock()

	// Re-check under the lock: another goroutine may have created the counter
	// between the caller's first Get and this point.
	if counter, ok := m.Get(key); ok {
		return counter
	}
	counter := new(atomic.Int32)
	_ = m.Set(key, counter)
	return counter
}

type StatsOutput struct {
	StatusCodeStats map[string]int `json:"status_code_stats"`
	ErrorStats      map[string]int `json:"error_stats"`
	WAFStats        map[string]int `json:"waf_stats"`
}

func (t *Tracker) GetStats() *StatsOutput {
	stats := &StatsOutput{
		StatusCodeStats: make(map[string]int),
		ErrorStats:      make(map[string]int),
		WAFStats:        make(map[string]int),
	}
	_ = t.errorCodes.Iterate(func(k string, v *atomic.Int32) error {
		stats.ErrorStats[k] = int(v.Load())
		return nil
	})
	_ = t.statusCodes.Iterate(func(k string, v *atomic.Int32) error {
		stats.StatusCodeStats[k] = int(v.Load())
		return nil
	})
	_ = t.wafDetected.Iterate(func(k string, v *atomic.Int32) error {
		waf, ok := t.wafDetector.GetWAF(k)
		if !ok {
			return nil
		}
		stats.WAFStats[waf.Name] = int(v.Load())
		return nil
	})
	return stats
}

// DisplayTopStats prints the most relevant statistics for CLI
func (t *Tracker) DisplayTopStats(noColor bool) {
	stats := t.GetStats()

	if len(stats.StatusCodeStats) > 0 {
		fmt.Printf("\n%s\n", aurora.Bold(aurora.Blue("Top Status Codes:")))
		topStatusCodes := getTopN(stats.StatusCodeStats, 6)
		for _, item := range topStatusCodes {
			if noColor {
				fmt.Printf("  %s: %d\n", item.Key, item.Value)
			} else {
				color := getStatusCodeColor(item.Key)
				fmt.Printf("  %s: %d\n", aurora.Colorize(item.Key, color), item.Value)
			}
		}
	}

	if len(stats.ErrorStats) > 0 {
		fmt.Printf("\n%s\n", aurora.Bold(aurora.Red("Top Errors:")))
		topErrors := getTopN(stats.ErrorStats, 5)
		for _, item := range topErrors {
			if noColor {
				fmt.Printf("  %s: %d\n", item.Key, item.Value)
			} else {
				fmt.Printf("  %s: %d\n", aurora.Red(item.Key), item.Value)
			}
		}
	}

	if len(stats.WAFStats) > 0 {
		fmt.Printf("\n%s\n", aurora.Bold(aurora.Yellow("WAF Detections:")))
		for name, count := range stats.WAFStats {
			if noColor {
				fmt.Printf("  %s: %d\n", name, count)
			} else {
				fmt.Printf("  %s: %d\n", aurora.Yellow(name), count)
			}
		}
	}
}

// Helper struct for sorting
type kv struct {
	Key   string
	Value int
}

// getTopN returns top N items from a map, sorted by value
func getTopN(m map[string]int, n int) []kv {
	var items []kv
	for k, v := range m {
		items = append(items, kv{k, v})
	}

	sort.Slice(items, func(i, j int) bool {
		return items[i].Value > items[j].Value
	})

	if len(items) > n {
		items = items[:n]
	}
	return items
}

// getStatusCodeColor returns appropriate color for status code
func getStatusCodeColor(statusCode string) aurora.Color {
	code, _ := strconv.Atoi(statusCode)
	switch {
	case code >= 200 && code < 300:
		return aurora.GreenFg
	case code >= 300 && code < 400:
		return aurora.BlueFg
	case code >= 400 && code < 500:
		return aurora.YellowFg
	case code >= 500:
		return aurora.RedFg
	default:
		return aurora.WhiteFg
	}
}

package stats

import (
	"runtime"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"
)

// Bounded scheduler stress for counter creation: every iteration uses a fresh
// tracker, so the key is always seen for the first time while workers are
// released together. The assertion is exact, so a fixed build never retries or
// sleeps; an unfixed build drops increments on the racing first hits.
const (
	concurrentFirstHitWorkers    = 64
	concurrentFirstHitIterations = 200
)

// releaseTogether runs fn in n goroutines that all start on one signal.
func releaseTogether(n int, fn func()) {
	var wg sync.WaitGroup
	start := make(chan struct{})
	wg.Add(n)
	for range n {
		go func() {
			defer wg.Done()
			<-start
			fn()
		}()
	}
	close(start)
	wg.Wait()
}

// requireMultipleP raises P above one so the racing window is reachable on
// small runners. It records the machine's real shape and does not claim that a
// single-P run cannot interleave: the scheduler may still preempt mid-window.
func requireMultipleP(t *testing.T) {
	t.Helper()
	t.Logf("scheduler shape: runtime.NumCPU=%d GOMAXPROCS=%d", runtime.NumCPU(), runtime.GOMAXPROCS(0))
	if runtime.GOMAXPROCS(0) < 2 {
		previous := runtime.GOMAXPROCS(4)
		t.Cleanup(func() { runtime.GOMAXPROCS(previous) })
	}
}

func TestTrackStatusCodeConcurrentFirstHit(t *testing.T) {
	requireMultipleP(t)

	for iteration := 0; iteration < concurrentFirstHitIterations; iteration++ {
		tracker := NewTracker()
		releaseTogether(concurrentFirstHitWorkers, func() { tracker.TrackStatusCode("200") })

		require.Equalf(t, concurrentFirstHitWorkers, tracker.GetStats().StatusCodeStats["200"],
			"iteration %d: concurrent first hits on status code 200 lost increments", iteration)
	}
}

func TestTrackErrorKindConcurrentFirstHit(t *testing.T) {
	requireMultipleP(t)

	for iteration := 0; iteration < concurrentFirstHitIterations; iteration++ {
		tracker := NewTracker()
		releaseTogether(concurrentFirstHitWorkers, func() { tracker.TrackErrorKind("timeout") })

		require.Equalf(t, concurrentFirstHitWorkers, tracker.GetStats().ErrorStats["timeout"],
			"iteration %d: concurrent first hits on error kind timeout lost increments", iteration)
	}
}

func TestTrackWAFDetectedConcurrentFirstHit(t *testing.T) {
	requireMultipleP(t)

	const workers = 16
	for iteration := 0; iteration < 20; iteration++ {
		tracker := NewTracker()
		releaseTogether(workers, func() { tracker.TrackWAFDetected("Attention Required! | Cloudflare") })

		// Read through the user-visible accessor, not the internal map: WAFStats
		// is keyed by detector name ("CloudFlare"), while wafDetected is keyed by
		// the detector id ("cloudflare").
		require.Equalf(t, workers, tracker.GetStats().WAFStats["CloudFlare"],
			"iteration %d: concurrent first WAF hits lost increments", iteration)
	}
}

func TestTrackStatusCodeConcurrentThenSequential(t *testing.T) {
	requireMultipleP(t)

	tracker := NewTracker()
	releaseTogether(concurrentFirstHitWorkers, func() { tracker.TrackStatusCode("200") })
	for range 5 {
		tracker.TrackStatusCode("200")
	}

	// Sequential updates must land on the counter that stayed in the map.
	require.Equal(t, concurrentFirstHitWorkers+5, tracker.GetStats().StatusCodeStats["200"])
}

func TestTrackStatusCodeConcurrentExistingKey(t *testing.T) {
	requireMultipleP(t)

	tracker := NewTracker()
	tracker.TrackStatusCode("200")
	releaseTogether(concurrentFirstHitWorkers, func() { tracker.TrackStatusCode("200") })

	require.Equal(t, concurrentFirstHitWorkers+1, tracker.GetStats().StatusCodeStats["200"])
}

func TestTrackStatusCodeConcurrentDistinctKeys(t *testing.T) {
	requireMultipleP(t)

	keys := []string{"200", "201", "204", "301", "302", "400", "401", "403", "404", "500"}
	tracker := NewTracker()

	var wg sync.WaitGroup
	start := make(chan struct{})
	wg.Add(len(keys))
	for _, key := range keys {
		go func() {
			defer wg.Done()
			<-start
			tracker.TrackStatusCode(key)
		}()
	}
	close(start)
	wg.Wait()

	stats := tracker.GetStats()
	total := 0
	for _, key := range keys {
		require.Equalf(t, 1, stats.StatusCodeStats[key], "status code %s counted wrong", key)
		total += stats.StatusCodeStats[key]
	}
	require.Equal(t, len(keys), total)
}

func TestTrackErrorKind(t *testing.T) {
	tracker := NewTracker()

	// Test single increment
	tracker.TrackErrorKind("timeout")
	if count, _ := tracker.errorCodes.Get("timeout"); count == nil || count.Load() != 1 {
		t.Errorf("expected error kind timeout count to be 1, got %v", count)
	}

	// Test multiple increments
	tracker.TrackErrorKind("timeout")
	if count, _ := tracker.errorCodes.Get("timeout"); count == nil || count.Load() != 2 {
		t.Errorf("expected error kind timeout count to be 2, got %v", count)
	}

	// Test different error kind
	tracker.TrackErrorKind("connection-refused")
	if count, _ := tracker.errorCodes.Get("connection-refused"); count == nil || count.Load() != 1 {
		t.Errorf("expected error kind connection-refused count to be 1, got %v", count)
	}
}

func TestTrackWaf_Detect(t *testing.T) {
	tracker := NewTracker()

	tracker.TrackWAFDetected("Attention Required! | Cloudflare")
	if count, _ := tracker.wafDetected.Get("cloudflare"); count == nil || count.Load() != 1 {
		t.Errorf("expected waf detected count to be 1, got %v", count)
	}
}

func TestTrackersShareDetectorButNotCounters(t *testing.T) {
	first := NewTracker()
	second := NewTracker()

	require.Same(t, first.wafDetector, second.wafDetector)

	first.TrackStatusCode("200")
	first.TrackErrorKind("timeout")
	first.TrackWAFDetected("Attention Required! | Cloudflare")

	require.Equal(t, 1, first.GetStats().StatusCodeStats["200"])
	require.Equal(t, 1, first.GetStats().ErrorStats["timeout"])
	require.Equal(t, 1, first.GetStats().WAFStats["CloudFlare"])
	require.Empty(t, second.GetStats().StatusCodeStats)
	require.Empty(t, second.GetStats().ErrorStats)
	require.Empty(t, second.GetStats().WAFStats)
}

func TestWAFMetricsAreExecutionLocal(t *testing.T) {
	first := NewTracker()
	second := NewTracker()
	response := "ordinary response with no WAF signature"

	first.TrackWAFDetected(response)

	metrics := first.GetWAFMetrics()
	require.Equal(t, uint64(1), metrics.Calls)
	require.Equal(t, uint64(len(response)), metrics.Bytes)
	require.Greater(t, metrics.PrefilterSkips, uint64(0))
	require.Greater(t, metrics.RegexEvaluations+metrics.PrefilterSkips, uint64(0))
	require.Zero(t, second.GetWAFMetrics().Calls)
}

func TestWAFMetricsAreConcurrencySafe(t *testing.T) {
	tracker := NewTracker()
	response := "ordinary response with no WAF signature"

	const calls = 32
	var wg sync.WaitGroup
	for range calls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			tracker.TrackWAFDetected(response)
		}()
	}
	wg.Wait()

	metrics := tracker.GetWAFMetrics()
	require.Equal(t, uint64(calls), metrics.Calls)
	require.Equal(t, uint64(calls*len(response)), metrics.Bytes)
}

package waf

import "unicode/utf8"

type literalMatcherNode struct {
	next    [256]int32
	failure int32
	outputs []string
}

// literalMatcher finds every configured byte string in one pass over the
// response. WAF responses can be several megabytes, so scanning once is much
// cheaper than searching the response once for every WAF signature.
type literalMatcher struct {
	nodes []literalMatcherNode
}

func newLiteralMatcher(patterns []string) *literalMatcher {
	if len(patterns) == 0 {
		return nil
	}

	matcher := &literalMatcher{nodes: []literalMatcherNode{newLiteralMatcherNode()}}
	seen := make(map[string]struct{}, len(patterns))
	for _, pattern := range patterns {
		if pattern == "" {
			continue
		}
		if _, ok := seen[pattern]; ok {
			continue
		}
		seen[pattern] = struct{}{}

		state := int32(0)
		for index := 0; index < len(pattern); index++ {
			value := pattern[index]
			next := matcher.nodes[state].next[value]
			if next == -1 {
				next = int32(len(matcher.nodes))
				matcher.nodes = append(matcher.nodes, newLiteralMatcherNode())
				matcher.nodes[state].next[value] = next
			}
			state = next
		}
		matcher.nodes[state].outputs = append(matcher.nodes[state].outputs, pattern)
	}

	queue := make([]int32, 0, len(matcher.nodes))
	for value := 0; value < 256; value++ {
		child := matcher.nodes[0].next[byte(value)]
		if child == -1 {
			matcher.nodes[0].next[byte(value)] = 0
			continue
		}
		matcher.nodes[child].failure = 0
		queue = append(queue, child)
	}

	for len(queue) > 0 {
		state := queue[0]
		queue = queue[1:]
		for value := 0; value < 256; value++ {
			child := matcher.nodes[state].next[byte(value)]
			if child == -1 {
				matcher.nodes[state].next[byte(value)] = matcher.nodes[matcher.nodes[state].failure].next[byte(value)]
				continue
			}
			failure := matcher.nodes[matcher.nodes[state].failure].next[byte(value)]
			matcher.nodes[child].failure = failure
			matcher.nodes[child].outputs = append(matcher.nodes[child].outputs, matcher.nodes[failure].outputs...)
			queue = append(queue, child)
		}
	}
	return matcher
}

func newLiteralMatcherNode() literalMatcherNode {
	node := literalMatcherNode{}
	for index := range node.next {
		node.next[index] = -1
	}
	return node
}

func (m *literalMatcher) find(content string) map[string]struct{} {
	found := make(map[string]struct{})
	if m == nil || len(m.nodes) == 0 {
		return found
	}

	state := int32(0)
	for index := 0; index < len(content); index++ {
		state = m.nodes[state].next[content[index]]
		for _, pattern := range m.nodes[state].outputs {
			found[pattern] = struct{}{}
		}
	}
	return found
}

// findExactAndASCIIFolded advances the case-sensitive and ASCII-folded
// matchers together, avoiding a second copy and traversal of large responses.
func findExactAndASCIIFolded(content string, exactMatcher, foldedMatcher *literalMatcher) (map[string]struct{}, map[string]struct{}) {
	exactFound := make(map[string]struct{})
	foldedFound := make(map[string]struct{})
	if foldedMatcher != nil && !isASCII(content) {
		foldedFound = foldedMatcher.find(canonicalFoldString(content))
		foldedMatcher = nil
	}
	var exactState, foldedState int32
	for index := 0; index < len(content); index++ {
		value := content[index]
		if exactMatcher != nil {
			exactState = exactMatcher.nodes[exactState].next[value]
			for _, pattern := range exactMatcher.nodes[exactState].outputs {
				exactFound[pattern] = struct{}{}
			}
		}
		if foldedMatcher != nil {
			if value >= 'a' && value <= 'z' {
				value -= 'a' - 'A'
			}
			foldedState = foldedMatcher.nodes[foldedState].next[value]
			for _, pattern := range foldedMatcher.nodes[foldedState].outputs {
				foldedFound[pattern] = struct{}{}
			}
		}
	}
	return exactFound, foldedFound
}

func mergeLiteralMatches(destination, source map[string]struct{}) {
	for pattern := range source {
		destination[pattern] = struct{}{}
	}
}

func isASCII(value string) bool {
	for index := 0; index < len(value); index++ {
		if value[index] >= utf8.RuneSelf {
			return false
		}
	}
	return true
}

package waf

import (
	_ "embed"
	"encoding/json"
	"log"
	"regexp"
	"regexp/syntax"
	"strings"
	"unicode"
	"unicode/utf8"
)

const (
	maxLiteralPrefilterClauses          = 64
	maxLiteralPrefilterNeedlesPerClause = 32
)

type WafDetector struct {
	wafs                 map[string]waf
	regexCache           map[string]*regexp.Regexp
	prefilterCache       map[string]literalPrefilter
	exactMatcher         *literalMatcher
	asciiFoldedMatcher   *literalMatcher
	unicodeFoldedMatcher *literalMatcher
}

// DetectionStats reports how much of the WAF regex set was evaluated for one
// response. A prefilter skip means the regex could not possibly match because
// a literal required by every matching path was absent.
type DetectionStats struct {
	RegexEvaluations int
	PrefilterSkips   int
}

type literalNeedle struct {
	value    string
	foldCase bool
}

type literalClause []literalNeedle

type literalPrefilter struct {
	clauses       []literalClause
	needsFoldCase bool
}

func (p literalPrefilter) allows(content string) bool {
	var foldedContent string
	if p.needsFoldCase {
		foldedContent = canonicalFoldString(content)
	}
	return p.allowsWithFoldedContent(content, foldedContent)
}

func (p literalPrefilter) allowsWithFoldedContent(content, foldedContent string) bool {
	for _, clause := range p.clauses {
		matches := true
		for _, needle := range clause {
			haystack := content
			if needle.foldCase {
				haystack = foldedContent
			}
			if !strings.Contains(haystack, needle.value) {
				matches = false
				break
			}
		}
		if matches {
			return true
		}
	}
	return false
}

func (p literalPrefilter) allowsWithMatches(exactMatches, foldedMatches map[string]struct{}) bool {
	for _, clause := range p.clauses {
		needle := strongestLiteralNeedle(clause)
		matched := exactMatches
		if needle.foldCase {
			matched = foldedMatches
		}
		if _, ok := matched[needle.value]; ok {
			return true
		}
	}
	return false
}

func strongestLiteralNeedle(clause literalClause) literalNeedle {
	strongest := clause[0]
	for _, candidate := range clause[1:] {
		if len(candidate.value) > len(strongest.value) {
			strongest = candidate
		}
	}
	return strongest
}

// waf represents a web application firewall definition
type waf struct {
	Company string `json:"company"`
	Name    string `json:"name"`
	Regex   string `json:"regex"`
}

// wafData represents the root JSON structure
type wafData struct {
	WAFs map[string]waf `json:"wafs"`
}

//go:embed regexes.json
var wafContentRegexes string

func NewWafDetector() *WafDetector {
	var data wafData
	if err := json.Unmarshal([]byte(wafContentRegexes), &data); err != nil {
		log.Printf("could not unmarshal waf content regexes: %s", err)
	}

	store := &WafDetector{
		wafs:           data.WAFs,
		regexCache:     make(map[string]*regexp.Regexp),
		prefilterCache: make(map[string]literalPrefilter),
	}

	for id, waf := range store.wafs {
		if waf.Regex == "" {
			continue
		}
		compiled, err := regexp.Compile(waf.Regex)
		if err != nil {
			log.Printf("invalid WAF regex for %s: %v", id, err)
			continue
		}
		store.regexCache[id] = compiled
		if prefilter, ok := buildLiteralPrefilter(waf.Regex); ok {
			store.prefilterCache[id] = prefilter
		}
	}
	var exactPatterns []string
	var foldedPatterns []string
	var unicodePatterns []string
	for _, prefilter := range store.prefilterCache {
		for _, clause := range prefilter.clauses {
			needle := strongestLiteralNeedle(clause)
			if needle.foldCase {
				if isASCII(needle.value) {
					foldedPatterns = append(foldedPatterns, needle.value)
				} else {
					unicodePatterns = append(unicodePatterns, needle.value)
				}
			} else {
				exactPatterns = append(exactPatterns, needle.value)
			}
		}
	}
	store.exactMatcher = newLiteralMatcher(exactPatterns)
	store.asciiFoldedMatcher = newLiteralMatcher(foldedPatterns)
	store.unicodeFoldedMatcher = newLiteralMatcher(unicodePatterns)
	return store
}

func (d *WafDetector) DetectWAF(content string) (string, bool) {
	id, matched, _ := d.DetectWAFWithStats(content)
	return id, matched
}

// DetectWAFWithStats detects a WAF and reports the amount of regex work done.
// The original compiled regex remains the source of truth. A regex is skipped
// only when a conservatively derived, required literal is absent.
func (d *WafDetector) DetectWAFWithStats(content string) (string, bool, DetectionStats) {
	var stats DetectionStats
	if d == nil || d.regexCache == nil {
		return "", false, stats
	}

	exactMatches, foldedMatches := findExactAndASCIIFolded(content, d.exactMatcher, d.asciiFoldedMatcher)
	if d.unicodeFoldedMatcher != nil {
		mergeLiteralMatches(foldedMatches, d.unicodeFoldedMatcher.find(canonicalFoldString(content)))
	}
	for id, regex := range d.regexCache {
		if regex == nil {
			continue
		}
		if prefilter, ok := d.prefilterCache[id]; ok {
			if !prefilter.allowsWithMatches(exactMatches, foldedMatches) {
				stats.PrefilterSkips++
				continue
			}
		}
		stats.RegexEvaluations++
		if regex.MatchString(content) {
			return id, true, stats
		}
	}
	return "", false, stats
}

func buildLiteralPrefilter(expression string) (literalPrefilter, bool) {
	parsed, err := syntax.Parse(expression, syntax.Perl)
	if err != nil {
		return literalPrefilter{}, false
	}
	clauses, ok := requiredLiteralClauses(parsed.Simplify())
	if !ok {
		return literalPrefilter{}, false
	}

	deduplicated := make([]literalClause, 0, len(clauses))
	needsFoldCase := false
	for _, clause := range clauses {
		clause = deduplicateLiteralClause(clause)
		if len(clause) == 0 || len(clause) > maxLiteralPrefilterNeedlesPerClause {
			return literalPrefilter{}, false
		}
		for _, needle := range clause {
			if needle.value == "" {
				return literalPrefilter{}, false
			}
			needsFoldCase = needsFoldCase || needle.foldCase
		}
		if !containsLiteralClause(deduplicated, clause) {
			deduplicated = append(deduplicated, clause)
		}
	}
	if len(deduplicated) == 0 || len(deduplicated) > maxLiteralPrefilterClauses {
		return literalPrefilter{}, false
	}
	return literalPrefilter{clauses: deduplicated, needsFoldCase: needsFoldCase}, true
}

// requiredLiteralClauses returns an OR-set of AND-clauses with this invariant:
// whenever expression matches, every literal in at least one returned clause
// occurs in the input. Unsupported or ambiguous expressions fall back to the
// original regex by returning false.
func requiredLiteralClauses(expression *syntax.Regexp) ([]literalClause, bool) {
	if expression == nil {
		return nil, false
	}

	switch expression.Op {
	case syntax.OpLiteral:
		if len(expression.Rune) == 0 {
			return nil, false
		}
		for _, value := range expression.Rune {
			if value == utf8.RuneError {
				return nil, false
			}
		}
		foldCase := expression.Flags&syntax.FoldCase != 0
		value := string(expression.Rune)
		if foldCase {
			value = canonicalFoldString(value)
		}
		return []literalClause{{{value: value, foldCase: foldCase}}}, true

	case syntax.OpCapture:
		if len(expression.Sub) != 1 {
			return nil, false
		}
		return requiredLiteralClauses(expression.Sub[0])

	case syntax.OpPlus:
		if len(expression.Sub) != 1 {
			return nil, false
		}
		return requiredLiteralClauses(expression.Sub[0])

	case syntax.OpRepeat:
		if expression.Min < 1 || len(expression.Sub) != 1 {
			return nil, false
		}
		return requiredLiteralClauses(expression.Sub[0])

	case syntax.OpConcat:
		clauses := []literalClause{{}}
		found := false
		for _, child := range expression.Sub {
			candidate, ok := requiredLiteralClauses(child)
			if !ok {
				continue
			}
			found = true
			if len(clauses) > maxLiteralPrefilterClauses/len(candidate) {
				return nil, false
			}
			combined := make([]literalClause, 0, len(clauses)*len(candidate))
			for _, currentClause := range clauses {
				for _, candidateClause := range candidate {
					if len(currentClause)+len(candidateClause) > maxLiteralPrefilterNeedlesPerClause {
						return nil, false
					}
					merged := make(literalClause, 0, len(currentClause)+len(candidateClause))
					merged = append(merged, currentClause...)
					merged = append(merged, candidateClause...)
					combined = append(combined, merged)
				}
			}
			clauses = combined
		}
		if !found {
			return nil, false
		}
		return clauses, true

	case syntax.OpAlternate:
		var clauses []literalClause
		for _, child := range expression.Sub {
			candidate, ok := requiredLiteralClauses(child)
			if !ok {
				return nil, false
			}
			if len(clauses)+len(candidate) > maxLiteralPrefilterClauses {
				return nil, false
			}
			clauses = append(clauses, candidate...)
		}
		if len(clauses) == 0 {
			return nil, false
		}
		return clauses, true

	default:
		return nil, false
	}
}

func deduplicateLiteralClause(clause literalClause) literalClause {
	deduplicated := make(literalClause, 0, len(clause))
	for _, needle := range clause {
		found := false
		for _, existing := range deduplicated {
			if existing == needle {
				found = true
				break
			}
		}
		if !found {
			deduplicated = append(deduplicated, needle)
		}
	}
	return deduplicated
}

func containsLiteralClause(clauses []literalClause, candidate literalClause) bool {
	for _, clause := range clauses {
		if len(clause) != len(candidate) {
			continue
		}
		equal := true
		for index := range clause {
			if clause[index] != candidate[index] {
				equal = false
				break
			}
		}
		if equal {
			return true
		}
	}
	return false
}

func canonicalFoldString(value string) string {
	var builder strings.Builder
	builder.Grow(len(value))
	for index := 0; index < len(value); {
		current := value[index]
		if current < utf8.RuneSelf {
			if current >= 'a' && current <= 'z' {
				current -= 'a' - 'A'
			}
			builder.WriteByte(current)
			index++
			continue
		}
		decoded, size := utf8.DecodeRuneInString(value[index:])
		builder.WriteRune(canonicalFoldRune(decoded))
		index += size
	}
	return builder.String()
}

func canonicalFoldRune(value rune) rune {
	canonical := value
	for folded := unicode.SimpleFold(value); folded != value; folded = unicode.SimpleFold(folded) {
		if folded < canonical {
			canonical = folded
		}
	}
	return canonical
}

func (d *WafDetector) GetWAF(id string) (waf, bool) {
	waf, ok := d.wafs[id]
	return waf, ok
}

package waf

import (
	"regexp"
