func TestDetectWAFReportsPrefilterWork(t *testing.T) {
	detector := &WafDetector{
		wafs: map[string]waf{
			"literal":  {Name: "Literal", Regex: `definitely-present`},
			"fallback": {Name: "Fallback", Regex: `(?i)case-folded`},
		},
		regexCache: map[string]*regexp.Regexp{
			"literal":  regexp.MustCompile(`definitely-present`),
			"fallback": regexp.MustCompile(`(?i)case-folded`),
		},
		prefilterCache: make(map[string]literalPrefilter),
	}
	if prefilter, ok := buildLiteralPrefilter(`definitely-present`); ok {
		detector.prefilterCache["literal"] = prefilter
	}
	if prefilter, ok := buildLiteralPrefilter(`(?i)case-folded`); ok {
		detector.prefilterCache["fallback"] = prefilter
	}

	_, matched, stats := detector.DetectWAFWithStats(strings.Repeat("ordinary response ", 1024))
	if matched {
		t.Fatal("unexpected WAF match")
	}
	if stats.PrefilterSkips != 2 {
		t.Fatalf("prefilter skips = %d, want 2", stats.PrefilterSkips)
	}
	if stats.RegexEvaluations != 0 {
		t.Fatalf("regex evaluations = %d, want 0", stats.RegexEvaluations)
	}
}

func FuzzLiteralPrefilterSoundness(f *testing.F) {
	patterns := []string{
		`alpha`,
		`alpha|bravo`,
		`prefix.+suffix`,
		`(?:optional)?required`,
		`(?:one|two)+`,
		`(?s)begin.+end`,
		`(?i)case-folded`,
		"�",
	}
	inputs := [][]byte{
		[]byte("alpha"),
		[]byte("bravo"),
		[]byte("prefix\nvalue\nsuffix"),
		[]byte("required"),
		{0xff},
		{0xff, 'a', 0xfe},
	}
	for _, pattern := range patterns {
		for _, input := range inputs {
			f.Add(pattern, input)
		}
	}

	f.Fuzz(func(t *testing.T, pattern string, input []byte) {
		compiled, err := regexp.Compile(pattern)
		if err != nil {
			return
		}
		prefilter, filterable := buildLiteralPrefilter(pattern)
		if compiled.Match(input) && filterable && !prefilter.allows(string(input)) {
			t.Fatalf("prefilter rejected regex match: pattern=%q input=%q", pattern, input)
		}
	})
}

func FuzzLiteralMatcherSoundness(f *testing.F) {
	f.Add("alpha", []byte("prefix alpha suffix"))
	f.Add("aba", []byte("ababa"))
	f.Add(string([]byte{0xff, 0xfe}), []byte{0, 0xff, 0xfe, 0})

	f.Fuzz(func(t *testing.T, pattern string, input []byte) {
		if pattern == "" || !strings.Contains(string(input), pattern) {
			return
		}
		found := newLiteralMatcher([]string{pattern}).find(string(input))
		if _, ok := found[pattern]; !ok {
			t.Fatalf("literal matcher missed pattern %q in input %q", pattern, input)
		}
	})
}

// Package progress implements progress display mechanism with very
// simple command line statistics printing on runtime.
package progress

package progress

import (
	"context"
	"fmt"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"

	"github.com/projectdiscovery/clistats"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// Progress is an interface implemented by nuclei progress display
// driver.
type Progress interface {
	// Stop stops the progress recorder.
	Stop()
	// Init inits the progress bar with initial details for scan
	Init(hostCount int64, rulesCount int, requestCount int64)
	// AddToTotal adds a value to the total request count
	AddToTotal(delta int64)
	// IncrementRequests increments the requests counter by 1.
	IncrementRequests()
	// SetRequests sets the counter by incrementing it with a delta
	SetRequests(count uint64)
	// IncrementMatched increments the matched counter by 1.
	IncrementMatched()
	// IncrementErrorsBy increments the error counter by count.
	IncrementErrorsBy(count int64)
	// IncrementFailedRequestsBy increments the number of requests counter by count
	// along with errors.
	IncrementFailedRequestsBy(count int64)
}

// TaskTracker is implemented by a Progress that also counts template
// executions. The engine counts one task for each template it runs on a
// target, and one for each self-contained template. Unlike the request total,
// which is an estimate, the task total is known when the scan starts, so it
// gives an exact completion percentage.
type TaskTracker interface {
	// AddToTaskTotal adds delta to the number of tasks the scan will run.
	AddToTaskTotal(delta int64)
	// IncrementTasksBy marks count tasks as done.
	IncrementTasksBy(count int64)
}

// ProbeTracker is implemented by a Progress that can also report progress
// of the pre-scan HTTP input probing phase. Input probing can take a long
// time on large target lists, and previously no stats were printed until
// the scan execution started, because the stats ticker only begins ticking
// on Init.
type ProbeTracker interface {
	// InitProbe initializes the stats for the input probing phase. All
	// counters and fields are registered here, before the ticker starts,
	// so the later Init call only updates values and never registers new
	// fields while the ticker is running.
	InitProbe(hostCount, templateCount, probeTotal int64)
	// IncrementProbes increments the probed-hosts counter by 1.
	IncrementProbes()
}

var (
	_ Progress     = &StatsTicker{}
	_ TaskTracker  = &StatsTicker{}
	_ ProbeTracker = &StatsTicker{}
)

// StatsTicker is a progress instance for showing program stats
type StatsTicker struct {
	cloud        bool
	active       bool
	outputJSON   bool
	stats        clistats.StatisticsClient
	tickDuration time.Duration
	// started is set once the stats event loop has been started (by
	// InitProbe or Init), so Init after InitProbe does not register fields
	// or start the ticker a second time.
	started bool
	// hosts, templates and scanStartedAt are registered as statics once and
	// updated in place, because clistats reads its static map without a lock
	// while the ticker and the metrics server run.
	hosts         liveInt
	templates     liveInt
	scanStartedAt liveTime
}

// liveInt is an int64 static field that can be updated after the ticker starts.
type liveInt struct{ v atomic.Int64 }

func (l *liveInt) String() string { return strconv.FormatInt(l.v.Load(), 10) }

func (l *liveInt) MarshalJSON() ([]byte, error) { return []byte(l.String()), nil }

// liveTime is a time static field that can be updated after the ticker starts.
type liveTime struct{ v atomic.Int64 }

func (l *liveTime) set(t time.Time) { l.v.Store(t.UnixNano()) }

func (l *liveTime) get() time.Time { return time.Unix(0, l.v.Load()) }

func (l *liveTime) String() string { return l.get().Format(time.RFC3339) }

func (l *liveTime) MarshalJSON() ([]byte, error) { return json.Marshal(l.get()) }

// NewStatsTicker creates and returns a new progress tracking object.
func NewStatsTicker(duration int, active, outputJSON, cloud bool, port int) (Progress, error) {
	var tickDuration time.Duration
	if active && duration != -1 {
		tickDuration = time.Duration(duration) * time.Second
	} else {
		tickDuration = -1
	}

	progress := &StatsTicker{}

	statsOpts := &clistats.DefaultOptions
	statsOpts.ListenPort = port
	// metrics port is enabled by default and is not configurable with new version of clistats
	// by default 63636 is used and than can be modified with -mp flag

	stats, err := clistats.NewWithOptions(context.TODO(), statsOpts)
	if err != nil {
		return nil, err
	}
	// only print in verbose mode
	gologger.Verbose().Msgf("Started metrics server at localhost:%v", stats.Options.ListenPort)
	progress.cloud = cloud
	progress.active = active
	progress.stats = stats
	progress.tickDuration = tickDuration
	progress.outputJSON = outputJSON

	return progress, nil
}

// InitProbe initializes the progress display before the HTTP input probing
// phase, so -stats prints probe progress instead of staying silent until
// scan execution starts. probeTotal is the number of input hosts that will
// be probed. Every field Init would register is registered here too, before
// the ticker starts, so Init never mutates the field set while it is served.
func (p *StatsTicker) InitProbe(hostCount, templateCount, probeTotal int64) {
	if p.started {
		return
	}
	p.register(hostCount, int(templateCount), 0)
	p.stats.AddCounter("probed", uint64(0))
	p.stats.AddCounter("probeTotal", uint64(probeTotal))
	p.start()
}

// IncrementProbes increments the probed-hosts counter by 1.
func (p *StatsTicker) IncrementProbes() {
	p.stats.IncrementCounter("probed", 1)
}

// Init initializes the progress display mechanism by setting counters, etc.
func (p *StatsTicker) Init(hostCount int64, rulesCount int, requestCount int64) {
	if p.started {
		// The ticker was already started by InitProbe. Every field exists,
		// so only store the counts the scan will actually use, restart the
		// scan clock so RPS excludes probing, and add the request total.
		p.hosts.v.Store(hostCount)
		p.templates.v.Store(int64(rulesCount))
		p.scanStartedAt.set(time.Now())
		p.stats.IncrementCounter("total", int(requestCount))
		return
	}
	p.register(hostCount, rulesCount, requestCount)
	p.start()
}

// register adds all counters and fields used by the progress display.
func (p *StatsTicker) register(hostCount int64, rulesCount int, requestCount int64) {
	now := time.Now()
	p.templates.v.Store(int64(rulesCount))
	p.hosts.v.Store(hostCount)
	p.scanStartedAt.set(now)
	p.stats.AddStatic("templates", &p.templates)
	p.stats.AddStatic("hosts", &p.hosts)
	p.stats.AddStatic("startedAt", now)
	p.stats.AddStatic("scanStartedAt", &p.scanStartedAt)
	p.stats.AddCounter("requests", uint64(0))
	p.stats.AddCounter("errors", uint64(0))
	p.stats.AddCounter("matched", uint64(0))
	p.stats.AddCounter("total", uint64(requestCount))
	p.stats.AddCounter("tasks", uint64(0))
	p.stats.AddCounter("totalTasks", uint64(0))
	// the metrics endpoint serves it once clistats keeps the fields its
	// caller provides; until then it serves requests/total
	p.stats.AddDynamic("percent", func(stats clistats.StatisticsClient) interface{} {
		return clistats.String(scanPercent(stats))
	})
}

// start starts the stats event loop and the periodic stats printing.
func (p *StatsTicker) start() {
	if p.active {
		var printCallbackFunc clistats.DynamicCallback
		if p.outputJSON {
			printCallbackFunc = printCallbackJSON
		} else {
			printCallbackFunc = p.makePrintCallback()
		}
		p.stats.AddDynamic("summary", printCallbackFunc)
		if err := p.stats.Start(); err != nil {
			gologger.Warning().Msgf("Couldn't start statistics: %s", err)
		}

		if p.tickDuration > 0 {
			// Note: this is needed and is responsible for the tick event
			p.stats.GetStatResponse(p.tickDuration, func(s string, err error) error {
				if err != nil {
					gologger.Warning().Msgf("Could not read statistics: %s\n", err)
				}
				return nil
			})
		}
	}
	p.started = true
}

// AddToTotal adds a value to the total request count
func (p *StatsTicker) AddToTotal(delta int64) {
	p.stats.IncrementCounter("total", int(delta))
}

// AddToTaskTotal adds delta to the number of tasks the scan will run.
func (p *StatsTicker) AddToTaskTotal(delta int64) {
	p.stats.IncrementCounter("totalTasks", int(delta))
}

// IncrementTasksBy marks count tasks as done.
func (p *StatsTicker) IncrementTasksBy(count int64) {
	p.stats.IncrementCounter("tasks", int(count))
}

// IncrementRequests increments the requests counter by 1.
func (p *StatsTicker) IncrementRequests() {
	p.stats.IncrementCounter("requests", 1)
}

// SetRequests sets the counter by incrementing it with a delta
func (p *StatsTicker) SetRequests(count uint64) {
	p.stats.IncrementCounter("requests", int(count))
}

// IncrementMatched increments the matched counter by 1.
func (p *StatsTicker) IncrementMatched() {
	p.stats.IncrementCounter("matched", 1)
}

// IncrementErrorsBy increments the error counter by count.
func (p *StatsTicker) IncrementErrorsBy(count int64) {
	p.stats.IncrementCounter("errors", int(count))
}

// IncrementFailedRequestsBy increments the number of requests counter by count along with errors.
func (p *StatsTicker) IncrementFailedRequestsBy(count int64) {
	// mimic dropping by incrementing the completed requests
	p.stats.IncrementCounter("requests", int(count))
	p.stats.IncrementCounter("errors", int(count))
}

func (p *StatsTicker) makePrintCallback() func(stats clistats.StatisticsClient) interface{} {
	return func(stats clistats.StatisticsClient) interface{} {
		builder := &strings.Builder{}

		var duration time.Duration
		if startedAt, ok := stats.GetStatic("startedAt"); ok {
			if startedAtTime, ok := startedAt.(time.Time); ok {
				duration = time.Since(startedAtTime)
				_, _ = fmt.Fprintf(builder, "[%s]", fmtDuration(duration))
			}
		}

		if templates, ok := stats.GetStatic("templates"); ok {
			builder.WriteString(" | Templates: ")
			builder.WriteString(clistats.String(templates))
		}

		if hosts, ok := stats.GetStatic("hosts"); ok {
			builder.WriteString(" | Hosts: ")
			builder.WriteString(clistats.String(hosts))
		}

		probed, _ := stats.GetCounter("probed")
		probeTotal, _ := stats.GetCounter("probeTotal")
		if probeTotal > 0 && probed < probeTotal {
			// the scan is still probing non-HTTP input hosts; scan requests
			// have not started yet, so report probe progress instead
			builder.WriteString(" | Probing: ")
			builder.WriteString(clistats.String(probed))
			builder.WriteRune('/')
			builder.WriteString(clistats.String(probeTotal))
			builder.WriteString(" (")
			builder.WriteString(clistats.String(percentComplete(probed, probeTotal)))
			builder.WriteString("%)\n")
			_, _ = fmt.Fprintf(os.Stderr, "%s", builder.String())
			return builder.String()
		}

		requests, okRequests := stats.GetCounter("requests")
		total, okTotal := stats.GetCounter("total")

		// If input is not given, total is 0 which cause percentage overflow
		if total == 0 {
			total = requests
		}

		if scanDuration := scanElapsed(stats, duration); okRequests && okTotal && scanDuration > 0 && !p.cloud {
			builder.WriteString(" | RPS: ")
			builder.WriteString(clistats.String(uint64(float64(requests) / scanDuration.Seconds())))
		}

		if matched, ok := stats.GetCounter("matched"); ok {
			builder.WriteString(" | Matched: ")
			builder.WriteString(clistats.String(matched))
		}

		if errors, ok := stats.GetCounter("errors"); ok && !p.cloud {
			builder.WriteString(" | Errors: ")
			builder.WriteString(clistats.String(errors))
		}

		if okRequests && okTotal {
			if p.cloud {
				builder.WriteString(" | Task: ")
			} else {
				builder.WriteString(" | Requests: ")
			}
			builder.WriteString(clistats.String(requests))
			builder.WriteRune('/')
			builder.WriteString(clistats.String(total))
			percent := percentComplete(requests, total)
			if tasks, totalTasks, ok := taskCounts(stats); ok {
				builder.WriteString(" | Tasks: ")
				builder.WriteString(clistats.String(tasks))
				builder.WriteRune('/')
				builder.WriteString(clistats.String(totalTasks))
				percent = percentComplete(tasks, totalTasks)
			}
			builder.WriteRune(' ')
			builder.WriteRune('(')
			builder.WriteString(clistats.String(percent))
			builder.WriteRune('%')
			builder.WriteRune(')')
			builder.WriteRune('\n')
		}

		_, _ = fmt.Fprintf(os.Stderr, "%s", builder.String())
		return builder.String()
	}
}

func printCallbackJSON(stats clistats.StatisticsClient) interface{} {
	builder := &strings.Builder{}
	if err := json.NewEncoder(builder).Encode(metricsMap(stats)); err == nil {
		_, _ = fmt.Fprintf(os.Stderr, "%s", builder.String())
	}
	return builder.String()
}

func metricsMap(stats clistats.StatisticsClient) map[string]interface{} {
	results := make(map[string]interface{})

	var (
		startedAt time.Time
		duration  time.Duration
	)

	if stAt, ok := stats.GetStatic("startedAt"); ok {
		startedAt = stAt.(time.Time)
		duration = time.Since(startedAt)
	}

	results["startedAt"] = startedAt
	results["duration"] = fmtDuration(duration)
	templates, _ := stats.GetStatic("templates")
	results["templates"] = clistats.String(templates)
	hosts, _ := stats.GetStatic("hosts")
	results["hosts"] = clistats.String(hosts)
	matched, _ := stats.GetCounter("matched")
	results["matched"] = clistats.String(matched)
	requests, _ := stats.GetCounter("requests")
	results["requests"] = clistats.String(requests)
	total, _ := stats.GetCounter("total")
	results["total"] = clistats.String(total)
	results["rps"] = clistats.String(uint64(float64(requests) / scanElapsed(stats, duration).Seconds()))
	errors, _ := stats.GetCounter("errors")
	results["errors"] = clistats.String(errors)
	tasks, _ := stats.GetCounter("tasks")
	results["tasks"] = clistats.String(tasks)
	totalTasks, _ := stats.GetCounter("totalTasks")
	results["totalTasks"] = clistats.String(totalTasks)
	probed, _ := stats.GetCounter("probed")
	results["probed"] = clistats.String(probed)
	probeTotal, _ := stats.GetCounter("probeTotal")
	results["probeTotal"] = clistats.String(probeTotal)

	results["percent"] = clistats.String(scanPercent(stats))
	return results
}

// scanElapsed returns the time since scan execution started, which excludes
// input probing, falling back to the overall elapsed time.
func scanElapsed(stats clistats.StatisticsClient, elapsed time.Duration) time.Duration {
	if value, ok := stats.GetStatic("scanStartedAt"); ok {
		if scanStart, ok := value.(*liveTime); ok {
			return time.Since(scanStart.get())
		}
	}
	return elapsed
}

// taskCounts returns the done and total tasks when the scan counts tasks.
func taskCounts(stats clistats.StatisticsClient) (tasks, totalTasks uint64, ok bool) {
	totalTasks, _ = stats.GetCounter("totalTasks")
	if totalTasks == 0 {
		return 0, 0, false
	}
	tasks, _ = stats.GetCounter("tasks")
	return tasks, totalTasks, true
}

// scanPercent returns the completed share of the scan, from tasks when they
// are counted and from requests otherwise.
func scanPercent(stats clistats.StatisticsClient) uint64 {
	if tasks, totalTasks, ok := taskCounts(stats); ok {
		return percentComplete(tasks, totalTasks)
	}
	requests, _ := stats.GetCounter("requests")
	total, _ := stats.GetCounter("total")
	return percentComplete(requests, total)
}

func percentComplete(done, total uint64) uint64 {
	if total == 0 {
		return 0
	}
	// nolint:gomnd // this is not a magic number
	return uint64((float64(done) * float64(100)) / float64(total))
}

// fmtDuration formats the duration for the time elapsed
func fmtDuration(d time.Duration) string {
	d = d.Round(time.Second)
	h := d / time.Hour
	d -= h * time.Hour
	m := d / time.Minute
	d -= m * time.Minute
	s := d / time.Second
	return fmt.Sprintf("%d:%02d:%02d", h, m, s)
}

// Stop stops the progress bar execution
func (p *StatsTicker) Stop() {
	if p.active {
		// Print one final summary
		if p.outputJSON {
			printCallbackJSON(p.stats)
		} else {
			p.makePrintCallback()(p.stats)
		}
		if err := p.stats.Stop(); err != nil {
			gologger.Warning().Msgf("Couldn't stop statistics: %s", err)
		}
	}
}

