func TestNormalizeAppName(t *testing.T) {
	appName := normalizeAppName("JBoss")
	require.Equal(t, "jboss", appName, "could not get normalized name")

	appName = normalizeAppName("JBoss:2.3.5")
	require.Equal(t, "jboss", appName, "could not get normalized name")
}

// countingExecuter counts the runs of a detection template.
type countingExecuter struct {
	runs atomic.Int32
}

func (c *countingExecuter) Compile() error { return nil }
func (c *countingExecuter) Requests() int  { return 1 }
func (c *countingExecuter) Execute(*scan.ScanContext) (bool, error) {
	c.runs.Add(1)

	return false, nil
}
func (c *countingExecuter) ExecuteWithResults(*scan.ScanContext) ([]*output.ResultEvent, error) {
	c.runs.Add(1)

	return nil, nil
}

// A -c or -bs below 1 must not make the service fail or dereference a nil
// pool; it runs one task at a time.
//
//nolint:exhaustruct,exhaustruct_v5,paralleltest // fixtures keep zero-value defaults
func TestServiceRunsWithConcurrencyBelowOne(t *testing.T) {
	for _, value := range []int{0, -1} {
		t.Run("-c="+strconv.Itoa(value), func(t *testing.T) {
			executer := &countingExecuter{}
			service := &Service{
				opts:          &protocols.ExecutorOptions{Options: &types.Options{TemplateThreads: value}},
				techTemplates: []*templates.Template{{ID: "tech-detect", Executer: executer}},
			}

			input := contextargs.NewMetaInput()
			input.Input = "http://127.0.0.1"

			require.NotPanics(t, func() { service.getTagsUsingDetectionTemplates(t.Context(), input) })
			require.EqualValues(t, 1, executer.runs.Load(), "the detection template runs once")
		})

		t.Run("-bs="+strconv.Itoa(value), func(t *testing.T) {
			service := &Service{
				opts:   &protocols.ExecutorOptions{Options: &types.Options{BulkSize: value}},
				target: provider.NewSimpleInputProvider(),
			}

			require.NoError(t, service.Execute(t.Context()))
		})
	}
}

// Package automaticscan implements automatic technology based template
// execution for a nuclei instance.
//
// First wappalyzer based technology detection is performed and templates
// are executed based on the results found. The results of wappalyzer
// technology detection are lowercased and split on space characters in the name,
// which are then used as tags for the execution of the templates.
//
// Example -
//
//	"Amazon Web Services,Jenkins,Atlassian Jira" -> "amazon,web,services,jenkins,atlassian,jira".
//
// Wappalyzergo (https://github.com/projectdiscovery/wappalyzergo) is used for wappalyzer tech
// detection.
//
// The logic is very simple and can be further improved to increase the coverage of
// this mode of nuclei execution.
package automaticscan

package automaticscan

import (
	"fmt"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/disk"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	sliceutil "github.com/projectdiscovery/utils/slice"
)

// getTemplateDirs returns template directories for given input
// by default it returns default template directory
func getTemplateDirs(opts Options) ([]string, error) {
	defaultTemplatesDirectories := []string{config.DefaultConfig.GetTemplateDir()}
	// adding custom template path if available
	if len(opts.ExecuterOpts.Options.Templates) > 0 {
		defaultTemplatesDirectories = append(defaultTemplatesDirectories, opts.ExecuterOpts.Options.Templates...)
	}
	// Collect path for default directories we want to look for templates in
	var allTemplates []string
	for _, directory := range defaultTemplatesDirectories {
		templates, err := opts.ExecuterOpts.Catalog.GetTemplatePath(directory)
		if err != nil {
			return nil, errors.Wrap(err, "could not get templates in directory")
		}
		allTemplates = append(allTemplates, templates...)
	}
	allTemplates = sliceutil.Dedupe(allTemplates)
	if len(allTemplates) == 0 {
		return nil, fmt.Errorf("%w for given input", disk.ErrNoTemplatesFound)
	}
	return allTemplates, nil
}

// LoadTemplatesWithTags loads and returns templates with given tags
func LoadTemplatesWithTags(opts Options, templateDirs []string, tags []string, logInfo bool) ([]*templates.Template, error) {
	finalTemplates, err := opts.Store.LoadTemplatesWithTags(templateDirs, tags)
	if err != nil {
		return nil, errors.Wrap(err, "could not load templates")
	}
	if len(finalTemplates) == 0 {
		return nil, errors.New("could not find any templates with tech tag")
	}

	if !opts.ExecuterOpts.Options.DisableClustering {
		// cluster and reduce requests
		totalReqBeforeCluster := getRequestCount(finalTemplates) * int(opts.Target.Count())
		finalTemplates, clusterCount, _ := templates.ClusterTemplates(finalTemplates, opts.ExecuterOpts)
		totalReqAfterClustering := getRequestCount(finalTemplates) * int(opts.Target.Count())
		if totalReqAfterClustering < totalReqBeforeCluster && logInfo {
			opts.ExecuterOpts.Logger.Info().Msgf("Automatic scan tech-detect: Templates clustered: %d (Reduced %d Requests)", clusterCount, totalReqBeforeCluster-totalReqAfterClustering)
		}
	}

	// log template loaded if VerboseVerbose flag is set
	if opts.ExecuterOpts.Options.VerboseVerbose {
		for _, tpl := range finalTemplates {
			opts.ExecuterOpts.Logger.Print().Msgf("%s\n", templates.TemplateLogMessage(tpl.ID,
				types.ToString(tpl.Info.Name),
				tpl.Info.Authors.ToSlice(),
				tpl.Info.SeverityHolder.Severity))
		}

	}
	return finalTemplates, nil
}

// returns total requests count
func getRequestCount(templates []*templates.Template) int {
	count := 0
	for _, template := range templates {
		// ignore requests in workflows as total requests in workflow
		// depends on what templates will be called in workflow
		if len(template.Workflows) > 0 {
			continue
		}
		count += template.TotalRequests
	}
	return count
}

package contextargs

import (
	"context"
	"net/http/cookiejar"
	"strings"
	"sync/atomic"

	"github.com/projectdiscovery/fastdialer/fastdialer"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/portutil"
	mapsutil "github.com/projectdiscovery/utils/maps"
	sliceutil "github.com/projectdiscovery/utils/slice"
	stringsutil "github.com/projectdiscovery/utils/strings"
	urlutil "github.com/projectdiscovery/utils/url"
)

var (
	// reservedPorts contains list of reserved ports for non-network requests in nuclei
	reservedPorts = []string{"80", "443", "8080", "8443", "8081", "53"}
)

// Context implements a shared context struct to share information across multiple templates within a workflow
type Context struct {
	ctx context.Context

	// Meta is the target for the executor
	MetaInput *MetaInput

	// CookieJar shared within workflow's http templates
	CookieJar *cookiejar.Jar

	// Args is a workflow shared key-value store
	args              *mapsutil.SyncLockMap[string, interface{}]
	templateVariables *mapsutil.SyncLockMap[string, struct{}]
}

// Create a new contextargs instance
func New(ctx context.Context) *Context {
	return NewWithInput(ctx, "")
}

// NewWithMetaInput creates a new contextargs instance with meta input
func NewWithMetaInput(ctx context.Context, input *MetaInput) *Context {
	n := New(ctx)
	n.MetaInput = input
	return n
}

// Create a new contextargs instance with input string
func NewWithInput(ctx context.Context, input string) *Context {
	jar, err := cookiejar.New(nil)
	if err != nil {
		gologger.Error().Msgf("contextargs: could not create cookie jar: %s\n", err)
	}
	metaInput := NewMetaInput()
	metaInput.Input = input
	return &Context{
		ctx:       ctx,
		MetaInput: metaInput,
		CookieJar: jar,
		args: &mapsutil.SyncLockMap[string, interface{}]{
			Map:      make(map[string]interface{}),
			ReadOnly: atomic.Bool{},
		},
		templateVariables: &mapsutil.SyncLockMap[string, struct{}]{
			Map:      make(map[string]struct{}),
			ReadOnly: atomic.Bool{},
		},
	}
}

// Context returns the context of the current contextargs
func (ctx *Context) Context() context.Context {
	return ctx.ctx
}

// WithCustomIP returns ctx with dials to the hostname of input pinned to its
// CustomIP. Dials made with ctx to other hosts, such as redirect targets or a
// proxy, are resolved as usual.
func WithCustomIP(ctx context.Context, input *MetaInput) context.Context {
	if input == nil || input.CustomIP == "" {
		return ctx
	}
	hostname := input.Hostname()
	if hostname == "" {
		return ctx
	}
	return fastdialer.WithResolveOverride(ctx, hostname, input.CustomIP)
}

// Set the specific key-value pair
func (ctx *Context) Set(key string, value interface{}) {
	_ = ctx.args.Set(key, value)
	ctx.clearTemplateVariable(key)
}

func (ctx *Context) hasArgs() bool {
	return !ctx.args.IsEmpty()
}

// Merge the key-value pairs
func (ctx *Context) Merge(args map[string]interface{}) {
	_ = ctx.args.Merge(args)
	for key := range args {
		ctx.clearTemplateVariable(key)
	}
}

// MergeTemplateVariables merges values produced from template variables.
func (ctx *Context) MergeTemplateVariables(args map[string]interface{}) {
	_ = ctx.args.Merge(args)
	for key := range args {
		ctx.setTemplateVariable(key)
	}
}

// Add the specific key-value pair
func (ctx *Context) Add(key string, v interface{}) {
	values, ok := ctx.args.Get(key)
	if !ok {
		ctx.Set(key, v)
	}

	// If the key exists, append the value to the existing value
	switch v := v.(type) {
	case []string:
		if values, ok := values.([]string); ok {
			values = append(values, v...)
			ctx.Set(key, values)
		}
	case string:
		if values, ok := values.(string); ok {
			tmp := []string{values, v}
			ctx.Set(key, tmp)
		}
	default:
		values, _ := ctx.Get(key)
		ctx.Set(key, []interface{}{values, v})
	}
}

// UseNetworkPort updates input with required/default network port for that template.
// The template port is used when:
//   - the input has no port at all, OR
//   - the input port is a reserved HTTP/DNS port AND the port was not explicitly
//     specified by the user (i.e. the input contains a URL scheme, meaning the
//     port was implied by the scheme, not typed by the operator).
//
// When the operator explicitly writes "target:80" (no scheme), that port is
// intentional (e.g. an SSH service running on port 80) and must not be replaced.
func (ctx *Context) UseNetworkPort(port string, excludePorts string) error {
	ignorePorts := reservedPorts
	if excludePorts != "" {
		ignorePorts = resolvePortList(strings.Split(excludePorts, ","))
		ignorePorts = sliceutil.Dedupe(ignorePorts)
	}
	if port == "" {
		// if template does not contain port, do nothing
		return nil
	}
	target, err := urlutil.Parse(ctx.MetaInput.Input)
	if err != nil {
		return err
	}
	if target.Host == "" {
		// urlutil.Parse drops the host of a single-label name such as
		// "https://intranet", which would turn the template port into ":port".
		target.Host = rawInputHost(ctx.MetaInput.Input)
	}
	inputPort := target.Port()
	if inputPort == "" {
		// No port in input at all — use the template port.
		target.UpdatePort(port)
		ctx.MetaInput.Input = target.Host
		return nil
	}
	// The input has an explicit port. Only override a reserved port when the
	// input included a URL scheme (http:// / https://), which means the port was
	// implied by the scheme rather than deliberately typed by the operator.
	// A bare "host:port" form (no scheme) means the operator chose that port
	// on purpose and we must not overwrite it.
	hasScheme := strings.Contains(ctx.MetaInput.Input, "://")
	if hasScheme && stringsutil.EqualFoldAny(inputPort, ignorePorts...) {
		target.UpdatePort(port)
		ctx.MetaInput.Input = target.Host
	}
	return nil
}

// rawInputHost returns the host part of an input without relying on
// urlutil.Parse: scheme, userinfo, path, query and fragment are stripped.
func rawInputHost(input string) string {
	if _, rest, ok := strings.Cut(input, "://"); ok {
		input = rest
	}
	if i := strings.IndexAny(input, "/?#"); i >= 0 {
		input = input[:i]
	}
	if i := strings.LastIndex(input, "@"); i >= 0 {
		input = input[i+1:]
	}
	return input
}

// Port returns the port of the target
func (ctx *Context) Port() string {
	target, err := urlutil.Parse(ctx.MetaInput.Input)
	if err != nil {
		return ""
	}
	return target.Port()
}

// Get the value with specific key if exists
func (ctx *Context) Get(key string) (interface{}, bool) {
	if !ctx.hasArgs() {
		return nil, false
	}

	return ctx.args.Get(key)
}

func (ctx *Context) GetAll() map[string]interface{} {
	if !ctx.hasArgs() {
		return nil
	}

	return ctx.args.Clone().Map
}

// GetTemplateVariables returns values currently owned by template variable
// evaluation.
func (ctx *Context) GetTemplateVariables() map[string]interface{} {
	if ctx.templateVariables == nil || ctx.templateVariables.IsEmpty() {
		return nil
	}

	values := make(map[string]interface{})
	for key := range ctx.templateVariables.Clone().Map {
		value, ok := ctx.Get(key)
		if ok {
			values[key] = value
		}
	}

	return values
}

func (ctx *Context) setTemplateVariable(key string) {
	if ctx.templateVariables == nil {
		ctx.templateVariables = &mapsutil.SyncLockMap[string, struct{}]{
			Map:      make(map[string]struct{}),
			ReadOnly: atomic.Bool{},
		}
	}
	_ = ctx.templateVariables.Set(key, struct{}{})
}

func (ctx *Context) clearTemplateVariable(key string) {
	if ctx.templateVariables == nil {
		return
	}
	ctx.templateVariables.Delete(key)
}

func (ctx *Context) ForEach(f func(string, interface{})) {
	_ = ctx.args.Iterate(func(k string, v interface{}) error {
		f(k, v)
		return nil
	})
}

// Has check if the key exists
func (ctx *Context) Has(key string) bool {
	return ctx.hasArgs() && ctx.args.Has(key)
}

func (ctx *Context) HasArgs() bool {
	return !ctx.args.IsEmpty()
}

func (ctx *Context) Clone() *Context {
	newCtx := &Context{
		ctx:               ctx.ctx,
		MetaInput:         ctx.MetaInput.Clone(),
		args:              ctx.args.Clone(),
		templateVariables: ctx.templateVariables.Clone(),
		CookieJar:         ctx.CookieJar,
	}
	return newCtx
}

// resolvePortList converts a list of port strings (numeric or service names) to numeric port strings.
func resolvePortList(ports []string) []string {
	resolved := make([]string, 0, len(ports))
	for _, p := range ports {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		if r, err := portutil.ResolvePort(p); err == nil {
			resolved = append(resolved, r)
		}
	}
	return resolved
}

// GetCopyIfHostOutdated returns a new contextargs if the host is outdated
func GetCopyIfHostOutdated(ctx *Context, url string) *Context {
	return copyIfOutdated(ctx, url, false)
}

// GetCopyIfAddressOutdated is GetCopyIfHostOutdated for the host errors cache.
// It also copies an input without a scheme when url has one, so that Address
// gives the port url goes to: a scheme-less input resolves to port 80, while an
// https url without a port goes to 443, where the transport records failures.
func GetCopyIfAddressOutdated(ctx *Context, url string) *Context {
	return copyIfOutdated(ctx, url, true)
}

// copyIfOutdated returns a copy of ctx for url when ctx has no input, or when
// url changes the host or the scheme. An input without a scheme matches any
// scheme unless fillScheme is set.
func copyIfOutdated(ctx *Context, url string, fillScheme bool) *Context {
	if ctx.MetaInput.Input == "" {
		newctx := ctx.Clone()
		newctx.MetaInput.Input = url
		return newctx
	}
	orig, _ := urlutil.Parse(ctx.MetaInput.Input)
	newURL, _ := urlutil.Parse(url)

	if orig == nil || newURL == nil {
		return ctx
	}

	schemeChanged := newURL.Scheme != "" && !strings.EqualFold(orig.Scheme, newURL.Scheme) &&
		(orig.Scheme != "" || fillScheme)
	if orig.Host != newURL.Host || schemeChanged {
		newCtx := ctx.Clone()
		if newURL.Scheme != "" {
			newCtx.MetaInput.Input = newURL.Scheme + "://" + newURL.Host
		} else {
			newCtx.MetaInput.Input = newURL.Host
		}
		return newCtx
	}
	return ctx
}

package contextargs

//nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
import (
	"context"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/input"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
)

// newNetworkContext returns the context a network request receives for target.
// The executers transform a target for the protocol first, and UseNetworkPort
// can only tell a scheme-implied port from a typed one if that keeps the scheme.
func newNetworkContext(target string) *Context {
	return NewWithInput(context.Background(), input.NewHelper().Transform(target, templateTypes.NetworkProtocol))
}

// TestUseNetworkPort is the behavior matrix for UseNetworkPort.
//
// The contract (see issue #7323):
//   - empty template port            -> no-op, input untouched
//   - input with no port             -> input gets the template port
//   - bare "host:port" (no scheme)   -> operator-chosen port, always preserved
//   - "scheme://host:port"           -> port is scheme-implied; a reserved
//     (or excluded) port is replaced by the template port, otherwise preserved
func TestUseNetworkPort(t *testing.T) {
	tests := []struct {
		name         string
		input        string
		templatePort string
		excludePorts string
		wantInput    string
	}{
		// --- empty template port: always a no-op ---
		{
			name:         "empty template port leaves bare host:port untouched",
			input:        "example.com:9999",
			templatePort: "",
			wantInput:    "example.com:9999",
		},
		{
			name:         "empty template port leaves no-port input untouched",
			input:        "example.com",
			templatePort: "",
			wantInput:    "example.com",
		},

		// --- no port in input: template port is applied ---
		{
			name:         "bare host without port uses template port",
			input:        "example.com",
			templatePort: "22",
			wantInput:    "example.com:22",
		},
		{
			name:         "http scheme without port uses template port",
			input:        "http://example.com",
			templatePort: "8888",
			wantInput:    "example.com:8888",
		},
		{
			name:         "https scheme without port uses template port",
			input:        "https://example.com",
			templatePort: "9090",
			wantInput:    "example.com:9090",
		},
		{
			name:         "https single-label host keeps its name",
			input:        "https://intranet",
			templatePort: "22",
			wantInput:    "intranet:22",
		},
		{
			name:         "http single-label host keeps its name",
			input:        "http://intranet",
			templatePort: "22",
			wantInput:    "intranet:22",
		},
		{
			name:         "bare single-label host keeps its name",
			input:        "intranet",
			templatePort: "22",
			wantInput:    "intranet:22",
		},
		{
			name:         "single-label host with path and userinfo keeps its name",
			input:        "https://user@intranet/login?x=1",
			templatePort: "22",
			wantInput:    "intranet:22",
		},
		{
			name:         "http scheme with path and no port uses template port",
			input:        "http://example.com/some/path",
			templatePort: "8888",
			wantInput:    "example.com:8888",
		},

		// --- bare host:port (no scheme): operator intent, never replaced ---
		{
			// core of issue #7323: SSH (or anything) on port 80.
			name:         "bare host with reserved port 80 is preserved",
			input:        "example.com:80",
			templatePort: "22",
			wantInput:    "example.com:80",
		},
		{
			name:         "bare host with reserved port 443 is preserved",
			input:        "example.com:443",
			templatePort: "22",
			wantInput:    "example.com:443",
		},
		{
			name:         "bare host with reserved port 8080 is preserved",
			input:        "example.com:8080",
			templatePort: "22",
			wantInput:    "example.com:8080",
		},
		{
			name:         "bare host with reserved port 53 is preserved",
			input:        "example.com:53",
			templatePort: "22",
			wantInput:    "example.com:53",
		},
		{
			name:         "bare host with non-reserved port is preserved",
			input:        "example.com:2222",
			templatePort: "22",
			wantInput:    "example.com:2222",
		},
		{
			name:         "bare host with port equal to template port is preserved",
			input:        "example.com:22",
			templatePort: "22",
			wantInput:    "example.com:22",
		},

		// --- scheme + reserved port: scheme-implied, replaced ---
		{
			name:         "http scheme with reserved port 80 is replaced",
			input:        "http://example.com:80",
			templatePort: "22",
			wantInput:    "example.com:22",
		},
		{
			name:         "https scheme with reserved port 443 is replaced",
			input:        "https://example.com:443",
			templatePort: "22",
			wantInput:    "example.com:22",
		},
		{
			name:         "http scheme with reserved port 8080 is replaced",
			input:        "http://example.com:8080",
			templatePort: "22",
			wantInput:    "example.com:22",
		},

		// --- scheme + non-reserved port: preserved ---
		// Note: when the port is preserved the input is left exactly as-is (the
		// scheme is kept). Only the replace path rewrites to bare "host:port".
		// getAddress() strips the scheme before dialing, so both forms dial the
		// same address.
		{
			name:         "http scheme with non-reserved port is preserved verbatim",
			input:        "http://example.com:9999",
			templatePort: "22",
			wantInput:    "http://example.com:9999",
		},

		// --- excludePorts: replaces the default reserved set ---
		{
			name:         "single-label host with a scheme port is replaced",
			input:        "https://intranet:443",
			templatePort: "22",
			wantInput:    "intranet:22",
		},
		{
			name:         "single-label host with a non-reserved port is preserved verbatim",
			input:        "https://intranet:9999",
			templatePort: "22",
			wantInput:    "https://intranet:9999",
		},
		{
			name:         "scheme port in excludePorts is replaced",
			input:        "http://example.com:9090",
			templatePort: "22",
			excludePorts: "9090",
			wantInput:    "example.com:22",
		},
		{
			name:         "scheme port not in excludePorts is preserved verbatim",
			input:        "http://example.com:9091",
			templatePort: "22",
			excludePorts: "9090",
			wantInput:    "http://example.com:9091",
		},
		{
			// excludePorts replaces the reserved list, so 80 is no longer ignored
			// and the scheme-prefixed input is preserved verbatim.
			name:         "scheme reserved port not in custom excludePorts is preserved verbatim",
			input:        "http://example.com:80",
			templatePort: "22",
			excludePorts: "9090",
			wantInput:    "http://example.com:80",
		},
		{
			name:         "scheme multiple excludePorts replaces matching",
			input:        "http://example.com:8443",
			templatePort: "22",
			excludePorts: "9090,8443",
			wantInput:    "example.com:22",
		},
		{
			// bare host:port is preserved even when the port is in excludePorts.
			name:         "bare host port in excludePorts is still preserved",
			input:        "example.com:9090",
			templatePort: "22",
			excludePorts: "9090",
			wantInput:    "example.com:9090",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx := newNetworkContext(tt.input)
			err := ctx.UseNetworkPort(tt.templatePort, tt.excludePorts)
			require.NoError(t, err)
			require.Equal(t, tt.wantInput, ctx.MetaInput.Input)
		})
	}
}

// TestUseNetworkPortIPv6 keeps IPv6 handling honest: bracketed literals must be
// preserved and the reserved/scheme rules apply the same way as for hostnames.
func TestUseNetworkPortIPv6(t *testing.T) {
	tests := []struct {
		name         string
		input        string
		templatePort string
		wantInput    string
	}{
		{
			name:         "bare IPv6 with reserved port is preserved",
			input:        "[::1]:80",
			templatePort: "22",
			wantInput:    "[::1]:80",
		},
		{
			name:         "bare IPv6 with non-reserved port is preserved",
			input:        "[2001:db8::1]:2222",
			templatePort: "22",
			wantInput:    "[2001:db8::1]:2222",
		},
		{
			name:         "scheme IPv6 with reserved port is replaced",
			input:        "http://[::1]:80",
			templatePort: "22",
			wantInput:    "[::1]:22",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ctx := newNetworkContext(tt.input)
			err := ctx.UseNetworkPort(tt.templatePort, "")
			require.NoError(t, err)
			require.Equal(t, tt.wantInput, ctx.MetaInput.Input)
		})
	}
}

func TestTemplateVariableOwnershipClearsOnDataWrites(t *testing.T) {
	ctx := New(context.Background())

	ctx.MergeTemplateVariables(map[string]interface{}{
		"token": "{{extracted_token}}",
	})
	require.Equal(t, map[string]interface{}{"token": "{{extracted_token}}"}, ctx.GetTemplateVariables())

	ctx.Set("token", "{{runtime_token}}")
	require.Empty(t, ctx.GetTemplateVariables())

	ctx.MergeTemplateVariables(map[string]interface{}{
		"token": "{{extracted_token}}",
	})
	ctx.Merge(map[string]interface{}{
		"token": "{{runtime_token}}",
	})
	require.Empty(t, ctx.GetTemplateVariables())
	require.Equal(t, map[string]interface{}{"token": "{{runtime_token}}"}, ctx.GetAll())
}

func TestTemplateVariableOwnershipIsCloned(t *testing.T) {
	ctx := New(context.Background())
	ctx.MergeTemplateVariables(map[string]interface{}{
		"token": "{{extracted_token}}",
	})

	cloned := ctx.Clone()
	require.Equal(t, map[string]interface{}{"token": "{{extracted_token}}"}, cloned.GetTemplateVariables())

	cloned.Set("token", "{{runtime_token}}")
	require.Empty(t, cloned.GetTemplateVariables())
	require.Equal(t, map[string]interface{}{"token": "{{extracted_token}}"}, ctx.GetTemplateVariables())
}

// TestUseNetworkPortServiceNameExclude verifies excludePorts accepts service
// names (resolved via portutil), e.g. "http" -> "80".
func TestUseNetworkPortServiceNameExclude(t *testing.T) {
	ctx := newNetworkContext("http://example.com:80")
	err := ctx.UseNetworkPort("22", "http")
	require.NoError(t, err)
	require.Equal(t, "example.com:22", ctx.MetaInput.Input)
}

// TestUseNetworkPortIdempotent ensures repeated application is stable and does
// not keep mutating the input.
func TestUseNetworkPortIdempotent(t *testing.T) {
	ctx := NewWithInput(context.Background(), "example.com")
	for i := 0; i < 3; i++ {
		require.NoError(t, ctx.UseNetworkPort("22", ""))
		require.Equal(t, "example.com:22", ctx.MetaInput.Input)
	}

	// A preserved bare explicit port must stay stable too.
	ctx = NewWithInput(context.Background(), "example.com:80")
	for i := 0; i < 3; i++ {
		require.NoError(t, ctx.UseNetworkPort("22", ""))
		require.Equal(t, "example.com:80", ctx.MetaInput.Input)
	}
}

// Package contextargs implements a generic entity for shared context within workflows
//
// All templates within a workflow shares the same cookiejar and a key-value store with shared items
package contextargs

package contextargs

import (
	"bytes"
	"crypto/md5"
	"fmt"
	"net"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/input/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	urlutil "github.com/projectdiscovery/utils/url"
	"github.com/segmentio/ksuid"
)

// MetaInput represents a target with metadata (TODO: replace with https://github.com/projectdiscovery/metainput)
type MetaInput struct {
	// Input represent the target
	Input string `json:"input,omitempty"`
	// CustomIP to use for connection
	CustomIP string `json:"customIP,omitempty"`
	// hash of the input
	hash string `json:"-"`

	// ReqResp is the raw request for the input
	ReqResp *types.RequestResponse `json:"raw-request,omitempty"`

	mu *sync.Mutex
}

func NewMetaInput() *MetaInput {
	return &MetaInput{mu: &sync.Mutex{}}
}

func (metaInput *MetaInput) marshalToBuffer() (bytes.Buffer, error) {
	var b bytes.Buffer
	err := json.NewEncoder(&b).Encode(metaInput)
	return b, err
}

// Target returns the target of the metainput
func (metaInput *MetaInput) Target() string {
	if metaInput.ReqResp != nil && metaInput.ReqResp.URL.URL != nil {
		return metaInput.ReqResp.URL.String()
	}
	return metaInput.Input
}

// URL returns request url
func (metaInput *MetaInput) URL() (*urlutil.URL, error) {
	instance, err := urlutil.ParseAbsoluteURL(metaInput.Target(), false)
	if err != nil {
		return nil, err
	}
	return instance, nil
}

// Hostname returns the hostname of the target without the port, or an empty
// string when the target cannot be parsed.
func (metaInput *MetaInput) Hostname() string {
	target, err := urlutil.Parse(metaInput.Target())
	if err != nil {
		return ""
	}
	return target.Hostname()
}

// Port returns the port of the target
// if port is not present then empty string is returned
func (metaInput *MetaInput) Port() string {
	target, err := urlutil.ParseAbsoluteURL(metaInput.Input, false)
	if err != nil {
		return ""
	}
	return target.Port()
}

// Address return the remote address of target
// Note: it does not resolve the domain to ip
// it is meant to be used by hosterrorsCache if invalid metainput
// is provided then it uses a random ksuid as hostname to avoid skipping valid targets
func (metaInput *MetaInput) Address() string {
	var hostname, port string
	target, err := urlutil.ParseAbsoluteURL(metaInput.Target(), false)
	if err != nil {
		if metaInput.CustomIP == "" {
			// since this is used in hosterrorscache we add a random id
			// which will never be used to avoid skipping valid targets
			hostname = fmt.Sprintf("invalid-%s", ksuid.New().String())
		}
	} else {
		hostname = target.Hostname()
		port = target.Port()
		if port == "" {
			switch target.Scheme {
			case urlutil.HTTP:
				port = "80"
			case urlutil.HTTPS:
				port = "443"
			default:
				port = "80"
			}
		}
	}
	if metaInput.CustomIP != "" {
		hostname = metaInput.CustomIP
	}
	if port == "" {
		if strings.HasPrefix(hostname, "http://") {
			port = "80"
		} else if strings.HasPrefix(hostname, "https://") {
			port = "443"
		}
	}
	return net.JoinHostPort(hostname, port)
}

// ID returns a unique id/hash for metainput
func (metaInput *MetaInput) ID() string {
	if metaInput.CustomIP != "" {
		return fmt.Sprintf("%s-%s", metaInput.Input, metaInput.CustomIP)
	}
	if metaInput.ReqResp != nil {
		return metaInput.ReqResp.ID()
	}
	return metaInput.Input
}

func (metaInput *MetaInput) MarshalString() (string, error) {
	b, err := metaInput.marshalToBuffer()
	return b.String(), err
}

func (metaInput *MetaInput) MustMarshalString() string {
	marshaled, _ := metaInput.MarshalString()
	return marshaled
}

func (metaInput *MetaInput) MarshalBytes() ([]byte, error) {
	b, err := metaInput.marshalToBuffer()
	return b.Bytes(), err
}

func (metaInput *MetaInput) MustMarshalBytes() []byte {
	marshaled, _ := metaInput.MarshalBytes()
	return marshaled
}

func (metaInput *MetaInput) Unmarshal(data string) error {
	return json.NewDecoder(strings.NewReader(data)).Decode(metaInput)
}

func (metaInput *MetaInput) Clone() *MetaInput {
	metaInput.mu.Lock()
	defer metaInput.mu.Unlock()

	input := NewMetaInput()
	input.Input = metaInput.Input
	input.CustomIP = metaInput.CustomIP
	input.hash = metaInput.hash
	if metaInput.ReqResp != nil {
		input.ReqResp = metaInput.ReqResp.Clone()
	}
	return input
}

func (metaInput *MetaInput) PrettyPrint() string {
	if metaInput.CustomIP != "" {
		return fmt.Sprintf("%s [%s]", metaInput.Input, metaInput.CustomIP)
	}
	if metaInput.ReqResp != nil {
		return fmt.Sprintf("%s [%s]", metaInput.ReqResp.URL.String(), metaInput.ReqResp.Request.Method)
	}
	return metaInput.Input
}

// GetScanHash returns a unique hash that represents a scan by hashing (metainput + templateId)
func (metaInput *MetaInput) GetScanHash(templateId string) string {
	// there may be some cases where metainput is changed ex: while executing self-contained template etc
	// but that totally changes the scanID/hash so to avoid that we compute hash only once
	// and reuse it for all subsequent calls
	metaInput.mu.Lock()
	defer metaInput.mu.Unlock()

	if metaInput.hash == "" {
		var rawRequest string
		if metaInput.ReqResp != nil {
			rawRequest = metaInput.ReqResp.ID()
		}
		metaInput.hash = getMd5Hash(templateId + ":" + metaInput.Input + ":" + metaInput.CustomIP + rawRequest)
	}
	return metaInput.hash
}

func getMd5Hash(data string) string {
	bin := md5.Sum([]byte(data))
	return string(bin[:])
}

