func TestHexDumpHighlightDoesNotExplode(t *testing.T) {
	// Two binary matchers of different lengths,
	// both consisting entirely of non-printable bytes
	op := &operators.Result{
		Matches: map[string][]string{
			"long":  {"\x05\x00\x00\x01"},
			"short": {"\x05\x00"},
		},
	}
	response := []byte{0x05, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00}
	dump := hex.Dump(response)

	done := make(chan int, 1)
	go func() { done <- len(Highlight(op, dump, false, true)) }()
	select {
	case n := <-done:
		// Sanity: output should stay within a few KB for a single-row
		// hex dump; before the fix it grew past 1 GB in <100 ms.
		if n > 10_000 {
			t.Fatalf("Highlight output suspiciously large: %d bytes", n)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("Highlight hung — exponential ReplaceAll regression")
	}
}

package writer

import (
	stderrors "errors"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/progress"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting"
)

// WriteResult is a helper for writing results to the output
func WriteResult(data *output.InternalWrappedEvent, out output.Writer, progress progress.Progress, issuesClient reporting.Client) bool {
	// Handle the case where no result found for the template.
	// In this case, we just show misc information about the failed
	// match for the template.
	if !data.HasOperatorResult() {
		return false
	}
	var matched bool
	for _, result := range data.Results {
		var suppressed bool
		if err := out.Write(result); err != nil {
			if stderrors.Is(err, output.ErrHoneypotSuppressed) {
				suppressed = true
			} else {
				gologger.Warning().Msgf("Could not write output event: %s\n", err)
			}
		}

		// Only create issues when the result was not suppressed.
		if issuesClient != nil && !suppressed {
			if err := issuesClient.CreateIssue(result); err != nil {
				gologger.Warning().Msgf("Could not create issue on tracker: %s", err)
			}
		}
		if !matched {
			matched = true
		}
		if !suppressed {
			progress.IncrementMatched()
		}
	}
	return matched
}

package honeypotdetector

import (
	"fmt"
	"net"
	"net/url"
	"strings"
	"sync"
)

// Detector tracks honeypot likelihood by counting distinct template matches per normalized host.
// Once a host reaches the configured threshold, it becomes flagged.
type Detector struct {
	threshold int
	hosts     sync.Map // map[normalizedHost]*hostState
}

type hostState struct {
	mu          sync.Mutex
	templateIDs map[string]struct{}
	flagged     bool
}

// New creates a new honeypot detector.
func New(threshold int) *Detector {
	if threshold <= 0 {
		threshold = 1
	}
	return &Detector{
		threshold: threshold,
	}
}

// Threshold returns the distinct template count required to flag a host.
func (d *Detector) Threshold() int {
	if d == nil {
		return 0
	}
	return d.threshold
}

// RecordMatch records a match for the given host and templateID.
//
// It returns true only when the host has just become flagged (i.e. crossed the threshold).
func (d *Detector) RecordMatch(host, templateID string) bool {
	if d == nil {
		return false
	}

	normalizedHost := normalizeHostKey(host)
	if normalizedHost == "" || templateID == "" {
		return false
	}

	stateAny, _ := d.hosts.LoadOrStore(normalizedHost, &hostState{
		templateIDs: make(map[string]struct{}),
	})
	state := stateAny.(*hostState)

	state.mu.Lock()
	defer state.mu.Unlock()

	if state.flagged {
		return false
	}
	if _, ok := state.templateIDs[templateID]; ok {
		return false
	}

	state.templateIDs[templateID] = struct{}{}
	if len(state.templateIDs) >= d.threshold {
		state.flagged = true
		state.templateIDs = nil
		return true
	}
	return false
}

// IsFlagged returns whether the given host is flagged.
func (d *Detector) IsFlagged(host string) bool {
	if d == nil {
		return false
	}

	normalizedHost := normalizeHostKey(host)
	if normalizedHost == "" {
		return false
	}

	stateAny, ok := d.hosts.Load(normalizedHost)
	if !ok {
		return false
	}
	state := stateAny.(*hostState)

	state.mu.Lock()
	defer state.mu.Unlock()
	return state.flagged
}

// Summary returns a short string with the total number of flagged hosts.
func (d *Detector) Summary() string {
	if d == nil {
		return "honeypot-detected hosts: 0"
	}

	var flagged int
	d.hosts.Range(func(_, v any) bool {
		state := v.(*hostState)
		state.mu.Lock()
		if state.flagged {
			flagged++
		}
		state.mu.Unlock()
		return true
	})

	return fmt.Sprintf("honeypot-detected hosts: %d", flagged)
}

// NormalizeHostKey normalizes host strings so different input formats map to the same key.
func NormalizeHostKey(input string) string {
	return normalizeHostKey(input)
}

func normalizeHostKey(input string) string {
	s := strings.TrimSpace(input)
	if s == "" {
		return ""
	}

	// Strip trailing slashes early.
	s = strings.TrimRight(s, "/")

	// If an absolute URL is present, parse it to reliably extract host and optional port.
	if strings.Contains(s, "://") {
		u, err := url.Parse(s)
		if err == nil && u != nil {
			host := u.Hostname()
			port := u.Port()
			if host == "" {
				return ""
			}
			host = normalizeHostWithoutPort(host)
			if port != "" {
				return net.JoinHostPort(host, port)
			}
			return host
		}
		// fall through if parsing fails
	}

	// Remove any path suffix (we only care about the authority).
	if idx := strings.IndexByte(s, '/'); idx >= 0 {
		s = s[:idx]
	}

	// If it looks like host:port (including bracketed IPv6), try SplitHostPort first.
	if host, port, err := net.SplitHostPort(s); err == nil {
		host = normalizeHostWithoutPort(host)
		if port == "" {
			return host
		}
		return net.JoinHostPort(host, port)
	}

	// Handle bracketed IPv6 without port: [2001:db8::1]
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		host := strings.TrimSuffix(strings.TrimPrefix(s, "["), "]")
		return normalizeHostWithoutPort(host)
	}

	// Handle bare IPv6 or host without port.
	return normalizeHostWithoutPort(s)
}

func normalizeHostWithoutPort(host string) string {
	h := strings.TrimSpace(host)
	if h == "" {
		return ""
	}
	h = strings.TrimPrefix(h, "[")
	h = strings.TrimSuffix(h, "]")
	h = strings.ToLower(h)

	if ip := net.ParseIP(h); ip != nil {
		return ip.String()
	}
	return h
}

// Package hostbackoff paces requests to a host that signals it is being
// overloaded, so a scan slows down instead of being blocked outright.
//
// nuclei already skips a host after repeated transport errors
// (pkg/protocols/common/hosterrorscache), which is all or nothing. A target
// that answers 429, or starts answering 403 to everything, is asking for less
// traffic rather than none, and the useful response is to keep scanning it more
// slowly.
//
// The control rule follows shipped practice rather than anything novel: a
// per-host delay that grows multiplicatively while the host complains and
// decays while it is healthy, with the host's own Retry-After honoured when it
// asks for longer. Scrapy's AutoThrottle, Heritrix and Googlebot's crawl
// capacity limit all work this way, and the asymmetry (a bad response may only
// slow the scan, never speed it up) is what keeps one lucky success from
// undoing a backoff.
package hostbackoff

import (
	"context"
	"math"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/gcache"
)

const (
	// DefaultStep is the delay applied the first time a host signals overload.
	DefaultStep = 250 * time.Millisecond
	// DefaultMax caps the per-host delay. Past this the host is better handled
	// by the host error cache, which skips it entirely.
	DefaultMax = 30 * time.Second
	// DefaultFactor grows the delay on each further complaint.
	DefaultFactor = 2.0
	// DefaultDecay shrinks the delay after a healthy response. It is far gentler
	// than the growth so that a scan recovers gradually rather than immediately
	// re-flooding a host that just recovered.
	DefaultDecay = 0.8
	// DefaultForbiddenStreak is how many consecutive 403s count as blocking. A
	// single 403 is ordinary (an endpoint the scan is not authorised for), but a
	// run of them usually means the host started refusing the scanner.
	DefaultForbiddenStreak = 5
	// DefaultMaxHosts bounds how many hosts are tracked at once, matching the
	// host error cache. A scan can carry millions of targets, so the state has
	// to be evictable; losing a host's entry only resets its delay, and the next
	// complaint earns it again.
	DefaultMaxHosts = 10000
)

// Config tunes the governor. The zero value is replaced by the defaults above.
type Config struct {
	Step            time.Duration
	Max             time.Duration
	Factor          float64
	Decay           float64
	ForbiddenStreak int
	MaxHosts        int
}

func (c *Config) applyDefaults() {
	if c.Step <= 0 {
		c.Step = DefaultStep
	}
	if c.Max <= 0 {
		c.Max = DefaultMax
	}
	if c.Factor <= 1 {
		c.Factor = DefaultFactor
	}
	if c.Decay <= 0 || c.Decay >= 1 {
		c.Decay = DefaultDecay
	}
	if c.ForbiddenStreak <= 0 {
		c.ForbiddenStreak = DefaultForbiddenStreak
	}
	if c.MaxHosts <= 0 {
		c.MaxHosts = DefaultMaxHosts
	}
}

type hostState struct {
	delay     time.Duration
	forbidden int
	// reachable is set once the host has answered. A dial that fails before
	// then is a closed or filtered port, which is no reason to slow down.
	reachable bool
	// slots holds the end of each slot handed out to a wait and not given
	// back, oldest first. The next slot starts where the last one ends, or one
	// delay from now once that end has passed. Concurrent waits reserve
	// successive slots so a delay paces the host instead of holding a burst
	// and releasing it together.
	slots []time.Time
}

// Governor holds the per-host delay for a scan.
type Governor struct {
	cfg   Config
	mu    sync.Mutex
	hosts gcache.Cache[string, *hostState]
}

// New returns a governor using cfg, with unset fields defaulted.
func New(cfg Config) *Governor {
	cfg.applyDefaults()
	return &Governor{cfg: cfg, hosts: gcache.New[string, *hostState](cfg.MaxHosts).ARC().Build()}
}

// Delay reports the current pause for a host, zero when it looks healthy.
func (g *Governor) Delay(host string) time.Duration {
	if g == nil || host == "" {
		return 0
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if state, err := g.hosts.GetIFPresent(host); err == nil && state != nil {
		return state.delay
	}
	return 0
}

// Wait pauses until this caller’s slot on the host. Callers that arrive
// together take successive slots of the current delay, so they do not all
// wake at once. It returns the context error if the scan is cancelled while
// waiting, so a stop is not held up by a long backoff. A cancelled wait gives
// its slot back; callers already holding later slots keep them.
func (g *Governor) Wait(ctx context.Context, host string) error {
	if g == nil || host == "" {
		return nil
	}
	if ctx.Err() != nil {
		return ctx.Err()
	}
	g.mu.Lock()
	state, err := g.hosts.GetIFPresent(host)
	if err != nil || state == nil || state.delay <= 0 {
		g.mu.Unlock()
		return nil
	}
	now := time.Now()
	// A slot that already ended constrains no one.
	ended, _ := slices.BinarySearchFunc(state.slots, now, time.Time.Compare)
	state.slots = slices.Delete(state.slots, 0, ended)

	start := now.Add(state.delay)
	if n := len(state.slots); n > 0 {
		start = state.slots[n-1]
	}

	end := start.Add(state.delay)
	state.slots = append(state.slots, end)
	_ = g.hosts.Set(host, state)
	wait := start.Sub(now)
	g.mu.Unlock()
	if wait <= 0 {
		return nil
	}
	timer := time.NewTimer(wait)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		g.release(state, end)
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

// Observe feeds one response back to the governor. retryAfter is the parsed
// Retry-After header, zero when absent. err is the transport error, if any.
func (g *Governor) Observe(host string, statusCode int, retryAfter time.Duration, err error) {
	if g == nil || host == "" {
		return
	}
	g.mu.Lock()
	defer g.mu.Unlock()

	state := g.state(host)
	defer func() { _ = g.hosts.Set(host, state) }()
	if statusCode > 0 {
		state.reachable = true
	}

	if statusCode == http.StatusForbidden {
		state.forbidden++
	} else if healthyStatus(statusCode) {
		state.forbidden = 0
	}
	// A 403 that names Retry-After is the host asking for a wait. The streak
	// is only for bare 403s, which are often just an unauthorised endpoint.
	if statusCode == http.StatusForbidden && retryAfter > 0 && state.forbidden < g.cfg.ForbiddenStreak {
		state.forbidden = g.cfg.ForbiddenStreak
	}

	if !g.isBlocking(statusCode, err, state) {
		// Only a response that actually served (2xx/3xx) is evidence the host
		// recovered. A 404 or 500 is what most templates get back, and treating
		// it as healthy would wipe the delay on the next probe.
		if healthyStatus(statusCode) {
			g.decay(state)
		}
		return
	}
	g.grow(state, retryAfter)
}

// ObserveDial feeds one connection attempt back to the governor, for
// protocols that have no response status to judge. A failed dial slows a host
// that accepted connections before, and a successful one counts as recovery.
// Errors on an established connection are the template's business, not the
// host asking for less.
func (g *Governor) ObserveDial(host string, err error) {
	if g == nil || host == "" {
		return
	}
	g.mu.Lock()
	defer g.mu.Unlock()

	state := g.state(host)
	switch {
	case err == nil:
		state.reachable = true
		g.decay(state)
	case state.reachable:
		g.grow(state, 0)
	default:
		// A port that never accepted is closed or filtered. Storing it would
		// fill the cache and evict hosts that actually have a delay.
		return
	}
	_ = g.hosts.Set(host, state)
}

// release gives back the slot ending at end. Slots after it belong to callers
// still waiting and keep their place. It does nothing when the slot is already
// gone because decay cleared the list or a later Wait pruned it.
func (g *Governor) release(state *hostState, end time.Time) {
	g.mu.Lock()
	defer g.mu.Unlock()

	if i := slices.IndexFunc(state.slots, end.Equal); i >= 0 {
		state.slots = slices.Delete(state.slots, i, i+1)
	}
}

func (g *Governor) state(host string) *hostState {
	if state, err := g.hosts.GetIFPresent(host); err == nil && state != nil {
		return state
	}
	return &hostState{}
}

func (g *Governor) grow(state *hostState, retryAfter time.Duration) {
	next := state.delay
	if next <= 0 {
		next = g.cfg.Step
	} else {
		next = time.Duration(math.Min(float64(next)*g.cfg.Factor, float64(g.cfg.Max)))
	}
	// The host named a wait of its own; respect it when it is the longer of the
	// two, since it is the only figure that is not a guess.
	if retryAfter > next {
		next = retryAfter
	}
	if next > g.cfg.Max {
		next = g.cfg.Max
	}
	state.delay = next
}

func (g *Governor) decay(state *hostState) {
	state.delay = time.Duration(float64(state.delay) * g.cfg.Decay)
	if state.delay < g.cfg.Step {
		state.delay = 0
		state.slots = nil
	}
}

// isBlocking reports whether a response means the host wants less traffic.
func (g *Governor) isBlocking(statusCode int, err error, state *hostState) bool {
	if err != nil {
		return true
	}
	switch statusCode {
	case http.StatusTooManyRequests, http.StatusServiceUnavailable:
		return true
	case http.StatusForbidden:
		return state.forbidden >= g.cfg.ForbiddenStreak
	}
	return false
}

// healthyStatus reports whether the host served a normal response. Template
// misses and server errors are not recovery.
func healthyStatus(statusCode int) bool {
	return statusCode >= http.StatusOK && statusCode < http.StatusBadRequest
}

// RetryAfter parses a Retry-After header, in either its delay-seconds or
// HTTP-date form. Delay-seconds is a non-negative decimal integer (RFC 9110);
// fractional and compound duration strings are rejected. A digit string that
// does not fit in a Duration saturates instead of being ignored. The result
// is zero when the header is absent or unparsable, and never a negative wait
// for a date already in the past.
func RetryAfter(header string) time.Duration {
	header = strings.TrimSpace(header)
	if header == "" {
		return 0
	}
	if seconds, ok := delaySeconds(header); ok {
		return seconds
	}
	if when, err := http.ParseTime(header); err == nil {
		if wait := time.Until(when); wait > 0 {
			return wait
		}
	}
	return 0
}

// delaySeconds parses a Retry-After delay-seconds value. The boolean is false
// when header is not a decimal integer.
func delaySeconds(header string) (time.Duration, bool) {
	if header == "" {
		return 0, false
	}
	for i := 0; i < len(header); i++ {
		if header[i] < '0' || header[i] > '9' {
			return 0, false
		}
	}
	const maxDuration = time.Duration(1<<63 - 1)
	const maxSeconds = uint64(maxDuration / time.Second)
	seconds, err := strconv.ParseUint(header, 10, 64)
	if err != nil || seconds > maxSeconds {
		return maxDuration, true
	}
	return time.Duration(seconds) * time.Second, true
}

package hostbackoff

import (
	"context"
	"errors"
	"net/http"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestHealthyHostIsNotDelayed(t *testing.T) {
	g := New(Config{})
	for i := 0; i < 10; i++ {
		g.Observe("acme.test", http.StatusOK, 0, nil)
	}
	require.Zero(t, g.Delay("acme.test"), "a host that answers normally must not be slowed")
}

func TestTooManyRequestsBacksOff(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, Factor: 2, Max: time.Second})

	g.Observe("acme.test", http.StatusTooManyRequests, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))

	g.Observe("acme.test", http.StatusTooManyRequests, 0, nil)
	require.Equal(t, 200*time.Millisecond, g.Delay("acme.test"), "a repeat complaint grows the delay")
}

func TestServiceUnavailableBacksOff(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond})
	g.Observe("acme.test", http.StatusServiceUnavailable, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))
}

func TestTransportErrorBacksOff(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond})
	g.Observe("acme.test", 0, 0, errors.New("connection reset"))
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))
}

// A single 403 is ordinary: plenty of templates probe endpoints the scan is not
// authorised for. A run of them is the host refusing the scanner.
func TestForbiddenOnlyBacksOffAsAStreak(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, ForbiddenStreak: 3})

	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	require.Zero(t, g.Delay("acme.test"), "an occasional 403 is not a block")

	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"), "a streak is")
}

func TestOkResetsTheForbiddenStreak(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, ForbiddenStreak: 3})
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	g.Observe("acme.test", http.StatusOK, 0, nil)
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	require.Zero(t, g.Delay("acme.test"), "the streak must start again after a healthy response")
}

// The host's own figure is the only one that is not a guess, so it wins when it
// is longer than what the governor would have chosen.
func TestRetryAfterIsHonouredWhenLonger(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, Max: time.Minute})

	g.Observe("acme.test", http.StatusTooManyRequests, 5*time.Second, nil)
	require.Equal(t, 5*time.Second, g.Delay("acme.test"))

	// a shorter Retry-After does not undo a longer backoff already earned
	g.Observe("acme.test", http.StatusTooManyRequests, time.Millisecond, nil)
	require.Equal(t, 10*time.Second, g.Delay("acme.test"))
}

func TestDelayIsCapped(t *testing.T) {
	g := New(Config{Step: time.Second, Factor: 10, Max: 2 * time.Second})
	for i := 0; i < 5; i++ {
		g.Observe("acme.test", http.StatusTooManyRequests, time.Hour, nil)
	}
	require.Equal(t, 2*time.Second, g.Delay("acme.test"), "neither growth nor Retry-After may exceed the cap")
}

func TestHealthyResponsesDecayTheDelay(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, Factor: 2, Decay: 0.5})
	g.Observe("acme.test", http.StatusTooManyRequests, 0, nil)
	g.Observe("acme.test", http.StatusTooManyRequests, 0, nil)
	require.Equal(t, 200*time.Millisecond, g.Delay("acme.test"))

	g.Observe("acme.test", http.StatusOK, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))

	// below the first step there is nothing useful left to wait for
	g.Observe("acme.test", http.StatusOK, 0, nil)
	require.Zero(t, g.Delay("acme.test"))
}

func TestHostsAreIndependent(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond})
	g.Observe("blocked.test", http.StatusTooManyRequests, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("blocked.test"))
	require.Zero(t, g.Delay("healthy.test"), "one host complaining must not slow another")
}

func TestWaitSleepsAndRespectsCancellation(t *testing.T) {
	g := New(Config{Step: 50 * time.Millisecond})

	start := time.Now()
	require.NoError(t, g.Wait(context.Background(), "quiet.test"))
	require.Less(t, time.Since(start), 10*time.Millisecond, "a healthy host is not waited on")

	g.Observe("slow.test", http.StatusTooManyRequests, 0, nil)
	start = time.Now()
	require.NoError(t, g.Wait(context.Background(), "slow.test"))
	require.GreaterOrEqual(t, time.Since(start), 50*time.Millisecond)

	// a cancelled scan must not be held up by a long backoff
	g.Observe("stuck.test", http.StatusTooManyRequests, time.Hour, nil)
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	require.ErrorIs(t, g.Wait(ctx, "stuck.test"), context.Canceled)
}

func TestWaitSpacesConcurrentCallers(t *testing.T) {
	const step = 60 * time.Millisecond
	g := New(Config{Step: step, Max: time.Second})
	g.Observe("burst.test", http.StatusTooManyRequests, 0, nil)

	start := time.Now()
	var wg sync.WaitGroup
	wg.Add(2)
	for i := 0; i < 2; i++ {
		go func() {
			defer wg.Done()
			require.NoError(t, g.Wait(context.Background(), "burst.test"))
		}()
	}
	wg.Wait()
	require.GreaterOrEqual(t, time.Since(start), 2*step-10*time.Millisecond)
}

// waitHost is the host the cancellation tests wait on.
const waitHost = "acme.test"

// pacedGovernor returns a governor that has slowed waitHost to one start per
// step.
func pacedGovernor(step time.Duration) *Governor {
	var cfg Config

	cfg.Step, cfg.Max = step, step
	governor := New(cfg)
	governor.Observe(waitHost, http.StatusTooManyRequests, 0, nil)

	return governor
}

// waitingCtx tells a test when Wait has started waiting on it. Wait calls
// Done only after it has reserved its slot, so the slot is held from then on.
type waitingCtx struct {
	context.Context //nolint:containedctx // waitingCtx is itself a context wrapping another

	once    sync.Once
	waiting chan struct{}
}

func (c *waitingCtx) Done() <-chan struct{} {
	c.once.Do(func() { close(c.waiting) })

	return c.Context.Done()
}

// waitResult is what a background Wait returned, and when.
type waitResult struct {
	err error
	at  time.Time
}

// startWait runs Wait on waitHost in the background and returns once it holds
// its slot, with the func that cancels the wait and the channel that gets its
// result.
func startWait(t *testing.T, governor *Governor) (context.CancelFunc, <-chan waitResult) {
	t.Helper()

	ctx, cancel := context.WithCancel(t.Context())
	waitCtx := &waitingCtx{Context: ctx, once: sync.Once{}, waiting: make(chan struct{})}
	result := make(chan waitResult, 1)

	go func() {
		err := governor.Wait(waitCtx, waitHost)
		result <- waitResult{err: err, at: time.Now()}
	}()

	select {
	case <-waitCtx.waiting:
	case got := <-result:
		t.Fatalf("Wait returned %v before holding a slot", got.err)
	}

	return cancel, result
}

// A wait that is cancelled never sends its request, so its slot must not push
// back the callers that come after it (#8163).
func TestWaitCancelledSlotsDoNotDelayLaterCallers(t *testing.T) {
	t.Parallel()

	const step = 200 * time.Millisecond

	governor := pacedGovernor(step)

	for range 3 {
		cancel, result := startWait(t, governor)
		cancel()
		require.ErrorIs(t, (<-result).err, context.Canceled)
	}

	// Three slots held on would put this caller 4 steps out.
	ctx, cancel := context.WithTimeout(t.Context(), 5*step/2)
	defer cancel()

	start := time.Now()

	require.NoError(t, governor.Wait(ctx, waitHost))
	require.GreaterOrEqual(t, time.Since(start), step, "the host is still paced")
}

// Cancelled waits give back their slots in whatever order they stop, while
// live callers keep theirs, including one queued behind a cancelled wait.
func TestWaitCancelledSlotsKeepLiveCallersInPlace(t *testing.T) {
	t.Parallel()

	const step = 200 * time.Millisecond

	governor := pacedGovernor(step)

	// The slots start 1 to 5 steps from now.
	start := time.Now()
	_, first := startWait(t, governor)
	cancelSecond, second := startWait(t, governor)
	_, third := startWait(t, governor)
	cancelFourth, fourth := startWait(t, governor)
	cancelFifth, fifth := startWait(t, governor)

	cancelSecond()
	cancelFifth()
	cancelFourth()

	for _, result := range []<-chan waitResult{second, fourth, fifth} {
		require.ErrorIs(t, (<-result).err, context.Canceled)
	}

	// The next free slot follows the third caller's, 4 steps in.
	ctx, cancel := context.WithDeadline(t.Context(), start.Add(5*step))
	defer cancel()

	require.NoError(t, governor.Wait(ctx, waitHost))
	require.GreaterOrEqual(t, time.Since(start), 4*step, "the next caller follows the last live one")

	got := <-first
	require.NoError(t, got.err)
	require.Less(t, got.at.Sub(start), 2*step, "the first caller kept its slot")

	got = <-third
	require.NoError(t, got.err)
	require.Less(t, got.at.Sub(start), 4*step, "the caller behind a cancelled wait kept its slot")
}

// Decay drops the slots handed out under the old delay, so a wait held from
// before the host recovered does not push back callers once it backs off again.
func TestDecayDropsHeldSlots(t *testing.T) {
	t.Parallel()

	const step = 300 * time.Millisecond

	governor := pacedGovernor(step)

	// This wait keeps its slot, which ends 2 steps from now.
	_, _ = startWait(t, governor)

	governor.Observe(waitHost, http.StatusOK, 0, nil)
	require.Zero(t, governor.Delay(waitHost), "a healthy response clears a one-step delay")
	governor.Observe(waitHost, http.StatusTooManyRequests, 0, nil)

	start := time.Now()

	require.NoError(t, governor.Wait(t.Context(), waitHost))
	require.Less(t, time.Since(start), 3*step/2, "the next caller waits one step, not behind the earlier slot")
}

func TestForbiddenRetryAfterBacksOffImmediately(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, ForbiddenStreak: 5, Max: time.Minute})
	g.Observe("acme.test", http.StatusForbidden, 2*time.Second, nil)
	require.Equal(t, 2*time.Second, g.Delay("acme.test"))
}

func TestNilGovernorIsInert(t *testing.T) {
	var g *Governor
	require.Zero(t, g.Delay("acme.test"))
	require.NoError(t, g.Wait(context.Background(), "acme.test"))
	require.NotPanics(t, func() { g.Observe("acme.test", http.StatusTooManyRequests, 0, nil) })
}

func TestRetryAfterParsing(t *testing.T) {
	require.Equal(t, 5*time.Second, RetryAfter("5"))
	require.Equal(t, 5*time.Second, RetryAfter(" 5 "))
	require.Zero(t, RetryAfter(""))
	require.Zero(t, RetryAfter("not-a-number"))
	require.Zero(t, RetryAfter("-3"), "a negative wait is meaningless")
	require.Zero(t, RetryAfter(time.Now().Add(-time.Hour).UTC().Format(http.TimeFormat)), "a date in the past is not a wait")

	future := RetryAfter(time.Now().Add(30 * time.Second).UTC().Format(http.TimeFormat))
	require.Greater(t, future, 25*time.Second)
	require.LessOrEqual(t, future, 30*time.Second)
}

// The previous parser appended "s" and called time.ParseDuration, which accepts
// fractional seconds and Go duration strings, and returns an error (then zero)
// when the integer does not fit.
func TestRetryAfterRejectsDurationSyntax(t *testing.T) {
	fractional, err := time.ParseDuration("1.5s")
	require.NoError(t, err)
	require.Equal(t, 1500*time.Millisecond, fractional)
	require.Zero(t, RetryAfter("1.5"))

	compound, err := time.ParseDuration("1m3s")
	require.NoError(t, err)
	require.Equal(t, 63*time.Second, compound)
	require.Zero(t, RetryAfter("1m3"))

	_, err = time.ParseDuration("999999999999999999999s")
	require.Error(t, err)
	require.Equal(t, time.Duration(1<<63-1), RetryAfter("999999999999999999999"))
}

func TestNotFoundDoesNotClearBackoff(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, Decay: 0.5})
	g.Observe("acme.test", http.StatusTooManyRequests, 0, nil)
	g.Observe("acme.test", http.StatusNotFound, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))

	g.Observe("acme.test", http.StatusInternalServerError, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))

	g.Observe("acme.test", http.StatusOK, 0, nil)
	require.Zero(t, g.Delay("acme.test"))
}

func TestForbiddenStreakSurvivesAMiss(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, ForbiddenStreak: 3})
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	g.Observe("acme.test", http.StatusNotFound, 0, nil)
	require.Zero(t, g.Delay("acme.test"))

	g.Observe("acme.test", http.StatusForbidden, 0, nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test"))
}

func TestFailedDialBacksOffAndSuccessfulDialDecays(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond, Factor: 2, Decay: 0.5})
	g.ObserveDial("acme.test:22", nil)
	g.ObserveDial("acme.test:22", errors.New("connection refused"))
	g.ObserveDial("acme.test:22", errors.New("connection refused"))
	require.Equal(t, 200*time.Millisecond, g.Delay("acme.test:22"))

	g.ObserveDial("acme.test:22", nil)
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test:22"))
	g.ObserveDial("acme.test:22", nil)
	require.Zero(t, g.Delay("acme.test:22"))
}

// A port that never accepted is closed or filtered, not pushing back. Slowing
// it would cost every template aimed at it a growing wait for nothing.
func TestDialFailureOnNeverReachedHostIsIgnored(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond})
	for i := 0; i < 3; i++ {
		g.ObserveDial("acme.test:22", errors.New("connection refused"))
	}
	require.Zero(t, g.Delay("acme.test:22"))
	_, err := g.hosts.GetIFPresent("acme.test:22")
	require.Error(t, err, "a port that never accepted must not take a cache slot")

	g.ObserveDial("ok.test:22", nil)
	_, err = g.hosts.GetIFPresent("ok.test:22")
	require.NoError(t, err, "a port that accepted is tracked so a later refusal can slow it")
}

func TestResponseMarksHostReachableForDials(t *testing.T) {
	g := New(Config{Step: 100 * time.Millisecond})
	g.Observe("acme.test:443", http.StatusNotFound, 0, nil)
	g.ObserveDial("acme.test:443", errors.New("connection refused"))
	require.Equal(t, 100*time.Millisecond, g.Delay("acme.test:443"))
}

package hosterrorscache

import (
	"errors"
	"net"
	"net/url"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"

	"github.com/projectdiscovery/gcache"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/types/nucleierr"
	"github.com/projectdiscovery/utils/errkit"
	stringsutil "github.com/projectdiscovery/utils/strings"
	"golang.org/x/net/idna"
)

// CacheInterface defines the signature of the hosterrorscache so that
// users of Nuclei as embedded lib may implement their own cache
type CacheInterface interface {
	SetVerbose(verbose bool)                                                  // log verbosely
	Close()                                                                   // close the cache
	Check(protoType string, ctx *contextargs.Context) bool                    // return true if the host should be skipped
	Remove(ctx *contextargs.Context)                                          // remove a host from the cache
	MarkFailed(protoType string, ctx *contextargs.Context, err error)         // record a failure (and cause) for the host
	MarkFailedOrRemove(protoType string, ctx *contextargs.Context, err error) // record a failure (and cause) for the host or remove it
	IsPermanentErr(ctx *contextargs.Context, err error) bool                  // return true if the error is permanent for the host
}

var (
	_ CacheInterface = (*Cache)(nil)
)

// Cache is a cache for host based errors. It allows skipping
// certain hosts based on an error threshold.
//
// It uses an LRU cache internally for skipping unresponsive hosts
// that remain so for a duration.
type Cache struct {
	MaxHostError    int
	verbose         bool
	maxHostsCount   int
	failedTargets   gcache.Cache[string, *cacheItem]
	failedTargetsMu sync.RWMutex
	TrackError      []string
	closed          atomic.Bool
}

type cacheItem struct {
	sync.Once
	errors         atomic.Int32
	isPermanentErr bool
	cause          error // optional cause
	mu             sync.Mutex
}

const DefaultMaxHostsCount = 10000

// New returns a new host max errors cache
func New(maxHostError, maxHostsCount int, trackError []string) *Cache {
	return &Cache{
		MaxHostError:  maxHostError,
		maxHostsCount: maxHostsCount,
		TrackError:    trackError,
	}
}

func (c *Cache) getFailedTargets(create bool) gcache.Cache[string, *cacheItem] {
	c.failedTargetsMu.RLock()
	cache := c.failedTargets
	c.failedTargetsMu.RUnlock()
	if cache != nil || !create || c.closed.Load() {
		return cache
	}

	c.failedTargetsMu.Lock()
	defer c.failedTargetsMu.Unlock()
	if c.failedTargets == nil && !c.closed.Load() {
		c.failedTargets = gcache.New[string, *cacheItem](c.maxHostsCount).ARC().Build()
	}
	return c.failedTargets
}

// SetVerbose sets the cache to log at verbose level
func (c *Cache) SetVerbose(verbose bool) {
	c.verbose = verbose
}

// Close closes the host errors cache
func (c *Cache) Close() {
	if !c.closed.CompareAndSwap(false, true) {
		return
	}
	c.failedTargetsMu.Lock()
	cache := c.failedTargets
	c.failedTargets = nil
	c.failedTargetsMu.Unlock()
	if cache != nil && config.DefaultConfig.IsDebugArgEnabled(config.DebugArgHostErrorStats) {
		items := cache.GetALL(false)
		for k, val := range items {
			gologger.Info().Label("MaxHostErrorStats").Msgf("Host: %s, Errors: %d", k, val.errors.Load())
		}
	}
	// The cache owns no background resource. Purge rebuilds an empty ARC with
	// the original capacity, which allocates several megabytes immediately
	// before callers discard a closed cache. Releasing the reference lets the
	// garbage collector reclaim both entries and storage without replacement.
}

// NormalizeCacheValue processes the input value and returns a normalized cache
// value.
func (c *Cache) NormalizeCacheValue(value string) string {
	var normalizedValue = value

	u, err := url.ParseRequestURI(value)
	if err != nil || u.Host == "" {
		if strings.Contains(value, ":") {
			return normalizedValue
		}
		u, err2 := url.ParseRequestURI("https://" + value)
		if err2 != nil {
			return normalizedValue
		}

		normalizedValue = u.Host
	} else {
		port := u.Port()
		if port == "" {
			switch u.Scheme {
			case "https":
				normalizedValue = net.JoinHostPort(u.Host, "443")
			case "http":
				normalizedValue = net.JoinHostPort(u.Host, "80")
			}
		} else {
			normalizedValue = u.Host
		}
	}

	return normalizedValue
}

// ErrUnresponsiveHost reports that a request was not sent because the
// address it goes to was found unresponsive. Its message is the error the
// engine writes for a target it skips for the same reason.
var ErrUnresponsiveHost = errors.New("host was skipped as it was found unresponsive")

// Check returns true if a host should be skipped as it has been
// unresponsive for a certain number of times.
//
// The value can be many formats -
//   - URL: https?:// type
//   - Host:port type
//   - host type
func (c *Cache) Check(protoType string, ctx *contextargs.Context) bool {
	failedTargets := c.getFailedTargets(false)
	if failedTargets == nil {
		return false
	}
	finalValue := c.GetKeyFromContext(ctx, nil)

	cache, err := failedTargets.GetIFPresent(finalValue)
	if err != nil {
		return false
	}

	cache.mu.Lock()
	defer cache.mu.Unlock()

	if cache.isPermanentErr {
		cache.Do(func() {
			gologger.Info().Msgf("Skipped %s from target list as found unresponsive permanently: %s", finalValue, cache.cause)
		})
		return true
	}

	if cache.errors.Load() >= int32(c.MaxHostError) {
		cache.Do(func() {
			gologger.Info().Msgf("Skipped %s from target list as found unresponsive %d times", finalValue, cache.errors.Load())
		})
		return true
	}

	return false
}

// Remove removes a host from the cache
func (c *Cache) Remove(ctx *contextargs.Context) {
	failedTargets := c.getFailedTargets(false)
	if failedTargets == nil {
		return
	}
	key := c.GetKeyFromContext(ctx, nil)
	_ = failedTargets.Remove(key) // remove even the cache is not present
}

// MarkFailed marks a host as failed previously
//
// Deprecated: Use MarkFailedOrRemove instead.
func (c *Cache) MarkFailed(protoType string, ctx *contextargs.Context, err error) {
	if err == nil {
		return
	}

	c.MarkFailedOrRemove(protoType, ctx, err)
}

// MarkFailedOrRemove marks a host as failed previously or removes it
func (c *Cache) MarkFailedOrRemove(protoType string, ctx *contextargs.Context, err error) {
	// A failure that occurs because the caller's context was cancelled or hit its
	// deadline is not the host's fault (e.g. the parent scan was cancelled). Such
	// errors classify as temporary/deadline and would otherwise be counted, so
	// ignore them. A nil error (success) still resets the host below.
	if err != nil && ctx != nil && ctx.Context() != nil && ctx.Context().Err() != nil {
		return
	}

	if err != nil && !c.checkError(protoType, err) {
		return
	}

	if err == nil {
		// Remove the host from cache
		//
		// NOTE(dwisiswant0): The decision was made to completely remove the
		// cached entry for the host instead of simply decrementing the error
		// count (using `(atomic.Int32).Swap` to update the value to `N-1`).
		// This approach was chosen because the error handling logic operates
		// concurrently, and decrementing the count could lead to UB (unexpected
		// behavior) even when the error is `nil`.
		//
		// To clarify, consider the following scenario where the error
		// encountered does NOT belong to the permanent network error category
		// (`errkit.ErrKindNetworkPermanent`):
		//
		// 1. Iteration 1: A timeout error occurs, and the error count for the
		//    host is incremented.
		// 2. Iteration 2: Another timeout error is encountered, leading to
		//    another increment in the host's error count.
		// 3. Iteration 3: A third timeout error happens, which increments the
		//    error count further. At this point, the host is flagged as
		//    unresponsive.
		// 4. Iteration 4: The host becomes reachable (no error or a transient
		//    issue resolved). Instead of performing a no-op and leaving the
		//    host in the cache, the host entry is removed entirely to reset its
		//    state.
		// 5. Iteration 5: A subsequent timeout error occurs after the host was
		//    removed and re-added to the cache. The error count is reset and
		//    starts from 1 again.
		//
		// This removal strategy ensures the cache is updated dynamically to
		// reflect the current state of the host without persisting stale or
		// irrelevant error counts that could interfere with future error
		// handling and tracking logic.
		c.Remove(ctx)

		return
	}

	cacheKey := c.GetKeyFromContext(ctx, err)
	failedTargets := c.getFailedTargets(true)
	if failedTargets == nil {
		return
	}
	cache, cacheErr := failedTargets.GetIFPresent(cacheKey)
	if errors.Is(cacheErr, gcache.KeyNotFoundError) {
		cache = &cacheItem{errors: atomic.Int32{}}
	}

	cache.mu.Lock()
	defer cache.mu.Unlock()

	if errkit.IsKind(err, errkit.ErrKindNetworkPermanent) {
		cache.isPermanentErr = true
	}

	cache.cause = err
	cache.errors.Add(1)

	_ = failedTargets.Set(cacheKey, cache)
}

// IsPermanentErr returns true if the error is permanent for the host.
func (c *Cache) IsPermanentErr(ctx *contextargs.Context, err error) bool {
	if err == nil {
		return false
	}

	if errkit.IsKind(err, errkit.ErrKindNetworkPermanent) {
		return true
	}

	failedTargets := c.getFailedTargets(false)
	if failedTargets == nil {
		return false
	}
	cacheKey := c.GetKeyFromContext(ctx, err)
	cache, cacheErr := failedTargets.GetIFPresent(cacheKey)
	if cacheErr != nil {
		return false
	}

	cache.mu.Lock()
	defer cache.mu.Unlock()

	return cache.isPermanentErr
}

// GetKeyFromContext returns the key for the cache from the context
func (c *Cache) GetKeyFromContext(ctx *contextargs.Context, err error) string {
	// Note:
	// ideally any changes made to remote addr in template like {{Hostname}}:81 etc
	// should be reflected in contextargs but it is not yet reflected in some cases
	// and needs refactor of ScanContext + ContextArgs to achieve that
	// i.e why we use real address from error if present
	var address string

	// 1. the address carried inside the error (if the transport sets it)
	if err != nil {
		if v := errkit.GetAttrValue(err, "address"); v.Any() != nil {
			address = v.String()
		}
	}

	if address == "" {
		address = ctx.MetaInput.Address()
	} else if ctx.MetaInput.CustomIP != "" {
		address = pinnedAddress(ctx.MetaInput, address)
	}

	finalValue := c.NormalizeCacheValue(address)
	return finalValue
}

// pinnedAddress maps the address of a failed dial to a pinned target, which
// fastdialer reports with the hostname in ASCII form, to the pinned ip that
// Check keys the target by. Addresses of other hosts are returned as is.
func pinnedAddress(input *contextargs.MetaInput, address string) string {
	host, port, err := net.SplitHostPort(address)
	if err != nil || !strings.EqualFold(asciiHost(host), asciiHost(input.Hostname())) {
		return address
	}
	return net.JoinHostPort(input.CustomIP, port)
}

// asciiHost returns the ASCII form of an internationalized hostname.
func asciiHost(host string) string {
	if ascii, err := idna.ToASCII(host); err == nil {
		return ascii
	}
	return host
}

var reCheckError = regexp.MustCompile(`(no address found for host|could not resolve host|connection refused|connection reset by peer|could not connect to any address found for host|timeout awaiting response headers|i/o timeout)`)

// checkError checks if an error represents a type that should be
// added to the host skipping table.
// it first parses error and extracts the cause and checks for blacklisted
// or common errors that should be skipped
func (c *Cache) checkError(protoType string, err error) bool {
	if err == nil {
		return false
	}
	if protoType != "http" {
		return false
	}
	kind := errkit.GetErrorKind(err, nucleierr.ErrTemplateLogic)
	switch kind {
	case nucleierr.ErrTemplateLogic:
		// these are errors that are not related to the target
		// and are due to template logic
		return false
	case errkit.ErrKindNetworkTemporary:
		// a single temporary error (timeout, i/o reset) is transient, but a host
		// that produces them on every request with no success in between is
		// unresponsive. Count it; MarkFailedOrRemove resets the host on the next
		// successful response, so only consecutive failures reach MaxHostError.
		return true
	case errkit.ErrKindNetworkPermanent:
		// these should be counted as host errors
		return true
	case errkit.ErrKindDeadline:
		// these should not be counted as host errors
		return false
	default:
		// parse error for further processing
		errX := errkit.FromError(err)
		tmp := errX.Cause()
		cause := tmp.Error()
		if stringsutil.ContainsAll(cause, "ReadStatusLine:", "read: connection reset by peer") {
			// this is a FP and should not be counted as a host error
			// because server closes connection when it reads corrupted bytes which we send via rawhttp
			return false
		}
		if strings.HasPrefix(cause, "ReadStatusLine:") {
			// error is present in last part when using rawhttp
			// this will be fixed once errkit is used everywhere
			lastIndex := strings.LastIndex(cause, ":")
			if lastIndex == -1 {
				lastIndex = 0
			}
			if lastIndex >= len(cause)-1 {
				lastIndex = 0
			}
			cause = cause[lastIndex+1:]
		}
		for _, msg := range c.TrackError {
			if strings.Contains(cause, msg) {
				return true
			}
		}
		return reCheckError.MatchString(cause)
	}
}

package hosterrorscache

import (
	"context"
	"errors"
	"log/slog"
	"sync"
	"sync/atomic"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/utils/errkit"
	"github.com/stretchr/testify/require"
)

const (
	protoType = "http"
)

func TestCacheCheck(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	err := errors.New("net/http: timeout awaiting response headers")

	t.Run("increment host error", func(t *testing.T) {
		ctx := newCtxArgs(t.Name())
		for i := 1; i < 3; i++ {
			cache.MarkFailed(protoType, ctx, err)
			got := cache.Check(protoType, ctx)
			require.Falsef(t, got, "got %v in iteration %d", got, i)
		}
	})

	t.Run("flagged", func(t *testing.T) {
		ctx := newCtxArgs(t.Name())
		for i := 1; i <= 3; i++ {
			cache.MarkFailed(protoType, ctx, err)
		}

		got := cache.Check(protoType, ctx)
		require.True(t, got)
	})

	t.Run("mark failed or remove", func(t *testing.T) {
		ctx := newCtxArgs(t.Name())
		cache.MarkFailedOrRemove(protoType, ctx, nil) // nil error should remove the host from cache
		got := cache.Check(protoType, ctx)
		require.False(t, got)
	})
}

func TestCacheCloseReleasesStorageAndIsIdempotent(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	cache.MarkFailed(protoType, newCtxArgs(t.Name()), errors.New("timeout"))

	cache.Close()
	require.Nil(t, cache.failedTargets)

	require.NotPanics(t, cache.Close)
}

func TestCacheAllocatesStorageOnlyForTrackedFailure(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	t.Cleanup(cache.Close)
	ctx := newCtxArgs(t.Name())

	require.Nil(t, cache.failedTargets)
	require.False(t, cache.Check(protoType, ctx))
	cache.Remove(ctx)
	cache.MarkFailedOrRemove(protoType, ctx, nil)
	cache.MarkFailedOrRemove(protoType, ctx, errors.New("template condition failed"))
	require.Nil(t, cache.failedTargets, "read, success, and template errors must not allocate host storage")

	cache.MarkFailedOrRemove(protoType, ctx, errors.New("net/http: timeout awaiting response headers"))
	require.NotNil(t, cache.failedTargets)
}

func TestCacheCloseBeforeFirstFailureKeepsStorageUnallocated(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	cache.Close()

	ctx := newCtxArgs(t.Name())
	require.NotPanics(t, func() {
		cache.MarkFailedOrRemove(protoType, ctx, errors.New("net/http: timeout awaiting response headers"))
		cache.MarkFailedOrRemove(protoType, ctx, nil)
		cache.Remove(ctx)
		require.False(t, cache.Check(protoType, ctx))
	})
	require.Nil(t, cache.failedTargets)
}

func TestCacheCheckTimeout(t *testing.T) {
	// A host that consistently times out (request deadline exceeded) is
	// unresponsive and must be skipped once MaxHostError consecutive timeouts
	// are recorded. Production surfaces these as ErrKindNetworkTemporary.
	cache := New(3, DefaultMaxHostsCount, nil)
	err := errkit.New("context deadline exceeded (Client.Timeout exceeded while awaiting headers)").
		SetKind(errkit.ErrKindNetworkTemporary)

	t.Run("flagged after threshold", func(t *testing.T) {
		ctx := newCtxArgs(t.Name())
		for i := 1; i <= 3; i++ {
			cache.MarkFailed(protoType, ctx, err)
		}
		require.True(t, cache.Check(protoType, ctx), "host with repeated timeouts must be skipped")
	})

	t.Run("reset on success keeps a live host", func(t *testing.T) {
		ctx := newCtxArgs(t.Name())
		cache.MarkFailed(protoType, ctx, err)
		cache.MarkFailed(protoType, ctx, err)
		cache.MarkFailedOrRemove(protoType, ctx, nil) // a successful response resets the host
		require.False(t, cache.Check(protoType, ctx), "a host that responded must not be skipped")
	})
}

func TestCacheCheckRawHTTPTimeout(t *testing.T) {
	// rawhttp/unsafe templates surface read timeouts as a plain-string error
	// ("ReadStatusLine: ... i/o timeout") that errkit cannot classify, so it
	// reaches the regex fallback. A host that produces these on every request
	// must still be skipped.
	cache := New(3, DefaultMaxHostsCount, nil)
	err := errors.New("ReadStatusLine: read tcp 127.0.0.1:60087->127.0.0.1:18080: i/o timeout")

	ctx := newCtxArgs(t.Name())
	for i := 1; i <= 3; i++ {
		cache.MarkFailed(protoType, ctx, err)
	}
	require.True(t, cache.Check(protoType, ctx), "host with repeated rawhttp i/o timeouts must be skipped")
}

func TestMarkSkipsParentContextCancellation(t *testing.T) {
	// A failure that happens because the caller's (parent scan) context was
	// cancelled or hit its deadline is not the host's fault and must not be
	// counted. context.DeadlineExceeded otherwise classifies as a temporary
	// network error and would wrongly accumulate.
	cache := New(3, DefaultMaxHostsCount, nil)
	parent, cancel := context.WithCancel(context.Background())
	cancel()
	ctx := contextargs.NewWithInput(parent, "cancelled-host")
	timeout := errkit.New("context deadline exceeded").SetKind(errkit.ErrKindNetworkTemporary)

	for i := 0; i < 5; i++ {
		cache.MarkFailedOrRemove(protoType, ctx, timeout)
	}
	require.False(t, cache.Check(protoType, ctx), "failures under a cancelled parent context must not mark the host")
}

func TestNonConsecutiveTimeoutsDoNotSkip(t *testing.T) {
	// A live host that times out intermittently but succeeds in between must not
	// be skipped: a success resets the count so only consecutive failures reach
	// the threshold. Guards the property the HTTP path relies on.
	cache := New(3, DefaultMaxHostsCount, nil)
	ctx := newCtxArgs(t.Name())
	timeout := errkit.New("i/o timeout").SetKind(errkit.ErrKindNetworkTemporary)

	cache.MarkFailedOrRemove(protoType, ctx, timeout)
	cache.MarkFailedOrRemove(protoType, ctx, timeout)
	cache.MarkFailedOrRemove(protoType, ctx, nil) // successful response resets the host
	cache.MarkFailedOrRemove(protoType, ctx, timeout)
	require.False(t, cache.Check(protoType, ctx), "a success between timeouts must reset the count")
}

func TestTrackErrors(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, []string{"custom error"})

	for i := 0; i < 100; i++ {
		cache.MarkFailed(protoType, newCtxArgs("custom"), errors.New("got: nested: custom error"))
		got := cache.Check(protoType, newCtxArgs("custom"))
		if i < 2 {
			// till 3 the host is not flagged to skip
			require.False(t, got)
		} else {
			// above 3 it must remain flagged to skip
			require.True(t, got)
		}
	}
	value := cache.Check(protoType, newCtxArgs("custom"))
	require.Equal(t, true, value, "could not get checked value")
}

func TestCacheItemDo(t *testing.T) {
	var (
		count int
		item  cacheItem
	)

	wg := sync.WaitGroup{}
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			item.Do(func() {
				count++
			})
		}()
	}
	wg.Wait()

	// ensures the increment happened only once regardless of the multiple call
	require.Equal(t, count, 1)
}

func TestRemove(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	ctx := newCtxArgs(t.Name())
	err := errors.New("net/http: timeout awaiting response headers")

	for i := 0; i < 100; i++ {
		cache.MarkFailed(protoType, ctx, err)
	}

	require.True(t, cache.Check(protoType, ctx))
	cache.Remove(ctx)
	require.False(t, cache.Check(protoType, ctx))
}

func TestCacheMarkFailed(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)

	tests := []struct {
		host     string
		expected int32
	}{
		{"http://example.com:80", 1},
		{"example.com:80", 2},
		// earlier if port is not provided then port was omitted
		// but from now it will default to appropriate http scheme based port with 80 as default
		{"example.com:443", 1},
	}

	for _, test := range tests {
		normalizedCacheValue := cache.GetKeyFromContext(newCtxArgs(test.host), nil)
		cache.MarkFailed(protoType, newCtxArgs(test.host), errors.New("no address found for host"))
		failedTarget, err := cache.failedTargets.Get(normalizedCacheValue)
		require.Nil(t, err)
		require.NotNil(t, failedTarget)

		require.EqualValues(t, test.expected, failedTarget.errors.Load())
	}
}

func TestCacheMarkFailedConcurrent(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)

	tests := []struct {
		host     string
		expected int32
	}{
		{"http://example.com:80", 200},
		{"example.com:80", 200},
		{"example.com:443", 100},
	}

	// the cache is not atomic during items creation, so we pre-create them with counter to zero
	failedTargets := cache.getFailedTargets(true)
	for _, test := range tests {
		normalizedValue := cache.NormalizeCacheValue(test.host)
		newItem := &cacheItem{errors: atomic.Int32{}}
		newItem.errors.Store(0)
		_ = failedTargets.Set(normalizedValue, newItem)
	}

	wg := sync.WaitGroup{}
	for _, test := range tests {
		currentTest := test
		for i := 0; i < 100; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				cache.MarkFailed(protoType, newCtxArgs(currentTest.host), errors.New("net/http: timeout awaiting response headers"))
			}()
		}
	}
	wg.Wait()

	for _, test := range tests {
		require.True(t, cache.Check(protoType, newCtxArgs(test.host)))

		normalizedCacheValue := cache.NormalizeCacheValue(test.host)
		failedTarget, err := cache.failedTargets.Get(normalizedCacheValue)
		require.Nil(t, err)
		require.NotNil(t, failedTarget)

		require.EqualValues(t, test.expected, failedTarget.errors.Load())
	}
}

func TestCacheCheckConcurrent(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	ctx := newCtxArgs(t.Name())

	wg := sync.WaitGroup{}
	for i := 1; i <= 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			cache.MarkFailed(protoType, ctx, errors.New("no address found for host"))
			if i >= 3 {
				got := cache.Check(protoType, ctx)
				require.True(t, got)
			}
		}()
	}
	wg.Wait()
}

func newCtxArgs(value string) *contextargs.Context {
	ctx := contextargs.NewWithInput(context.TODO(), value)
	return ctx
}

func TestGetKeyFromContextPinnedTarget(t *testing.T) {
	cache := New(3, DefaultMaxHostsCount, nil)
	pinned := contextargs.NewWithMetaInput(context.Background(), &contextargs.MetaInput{
		Input:    "https://a.example",
		CustomIP: "192.0.2.10",
	})
	// fastdialer reports the dialed hostname as the error address
	dialErr := errkit.WithAttr(errkit.New("connection refused"), slog.String("address", "a.example:443"))
	require.Equal(t, cache.GetKeyFromContext(pinned, nil), cache.GetKeyFromContext(pinned, dialErr))

	// an error from another host keeps its own address
	otherErr := errkit.WithAttr(errkit.New("connection refused"), slog.String("address", "b.example:443"))
	require.Equal(t, "b.example:443", cache.GetKeyFromContext(pinned, otherErr))

	// an internationalized hostname is reported in its ASCII form
	idn := contextargs.NewWithMetaInput(context.Background(), &contextargs.MetaInput{
		Input:    "https://bücher.example",
		CustomIP: "192.0.2.10",
	})
	idnErr := errkit.WithAttr(errkit.New("connection refused"), slog.String("address", "xn--bcher-kva.example:443"))
	require.Equal(t, "192.0.2.10:443", cache.GetKeyFromContext(idn, idnErr))
}

// A target without a scheme is sent to https, so the transport reports its
// failures at port 443. The http request paths check, mark and reset the host
// through GetCopyIfAddressOutdated for each request URL (#8175).
func TestSchemelessTargetIsKeyedByRequestPort(t *testing.T) {
	t.Parallel()

	target := contextargs.NewWithInput(context.Background(), "127.0.0.1")
	requestInput := func(path string) *contextargs.Context {
		return contextargs.GetCopyIfAddressOutdated(target, "https://127.0.0.1"+path)
	}
	refused := errkit.WithAttr(
		errkit.New("connection refused").SetKind(errkit.ErrKindNetworkPermanent),
		slog.String("address", "127.0.0.1:443"),
	)
	timeout := errkit.WithAttr(
		errkit.New("i/o timeout").SetKind(errkit.ErrKindNetworkTemporary),
		slog.String("address", "127.0.0.1:443"),
	)

	t.Run("permanent error skips the next request", func(t *testing.T) {
		t.Parallel()

		cache := New(30, DefaultMaxHostsCount, nil)
		cache.MarkFailedOrRemove(protoType, requestInput("/n1"), refused)
		require.True(t, cache.Check(protoType, requestInput("/n2")))
	})

	t.Run("temporary errors skip after max host errors", func(t *testing.T) {
		t.Parallel()

		cache := New(3, DefaultMaxHostsCount, nil)

		for i := range 3 {
			require.Falsef(t, cache.Check(protoType, requestInput("/n")), "skipped before error %d", i+1)
			cache.MarkFailedOrRemove(protoType, requestInput("/n"), timeout)
		}

		require.True(t, cache.Check(protoType, requestInput("/n")))
	})

	t.Run("success resets the host", func(t *testing.T) {
		t.Parallel()

		cache := New(3, DefaultMaxHostsCount, nil)
		cache.MarkFailedOrRemove(protoType, requestInput("/n1"), timeout)
		cache.MarkFailedOrRemove(protoType, requestInput("/n2"), timeout)
		cache.MarkFailedOrRemove(protoType, requestInput("/n3"), nil)
		cache.MarkFailedOrRemove(protoType, requestInput("/n4"), timeout)
		// The https form of the target reads the same 443 entry.
		require.False(t, cache.Check(protoType, newCtxArgs("https://127.0.0.1")))
	})
}

package hostratelimit

import (
	"fmt"
	"net"
	"strings"

	urlutil "github.com/projectdiscovery/utils/url"
)

// NormalizeHostPort extracts and normalizes "hostname:port" from a URL or
// host[:port] string. Default ports (80/443) are derived from the scheme when
// missing. It is shared by the per-host rate limit pool and the HTTP-to-HTTPS
// port tracker so that both group entries by the same key.
func NormalizeHostPort(rawURL string) string {
	if rawURL == "" {
		return ""
	}

	parsed, err := urlutil.Parse(rawURL)
	if err != nil {
		// If parsing fails, try to extract host:port manually
		return extractHostPort(rawURL)
	}

	scheme := parsed.Scheme
	if scheme == "" {
		scheme = "http"
	}

	// Extract just the hostname (without port) and port separately
	hostname := parsed.Hostname()
	if hostname == "" {
		// Fallback: try to extract from Host field
		host := parsed.Host
		if host != "" {
			// Split host:port if port is present
			if h, _, err := net.SplitHostPort(host); err == nil {
				hostname = h
			} else {
				hostname = host
			}
		}
	}

	if hostname == "" {
		return extractHostPort(rawURL)
	}

	port := parsed.Port()
	if port == "" {
		port = defaultPort(scheme)
	}

	// Return just hostname:port (no scheme prefix)
	return fmt.Sprintf("%s:%s", hostname, port)
}

// extractHostPort attempts to extract host:port from a string when URL parsing fails
func extractHostPort(s string) string {
	original := s
	scheme := "http"

	// Remove scheme prefix if present
	switch {
	case strings.HasPrefix(s, "wss://"):
		s = strings.TrimPrefix(s, "wss://")
		scheme = "wss"
	case strings.HasPrefix(s, "ws://"):
		s = strings.TrimPrefix(s, "ws://")
		scheme = "ws"
	case strings.HasPrefix(s, "https://"):
		s = strings.TrimPrefix(s, "https://")
		scheme = "https"
	case strings.HasPrefix(s, "http://"):
		s = strings.TrimPrefix(s, "http://")
		scheme = "http"
	}

	// Extract up to first /, ?, #, space, or newline (path/query/fragment separator)
	if idx := strings.IndexAny(s, "/?# \n\r\t"); idx != -1 {
		s = s[:idx]
	}

	if s == "" {
		return original // Return original if we can't extract anything
	}

	// Validate and split host:port
	host, port, err := net.SplitHostPort(s)
	if err == nil {
		// Valid host:port format
		if port == "" {
			port = defaultPort(scheme)
		}
		// Return just host:port (no scheme prefix)
		return fmt.Sprintf("%s:%s", host, port)
	}

	return fmt.Sprintf("%s:%s", s, defaultPort(scheme))
}

func defaultPort(scheme string) string {
	if scheme == "https" || scheme == "wss" {
		return "443"
	}
	return "80"
}

package hostratelimit

import "testing"

func TestNormalizeHostPortWebSocketDefaults(t *testing.T) {
	if got, want := NormalizeHostPort("wss://example.com"), "example.com:443"; got != want {
		t.Fatalf("wss default port: got %q, want %q", got, want)
	}
	if got, want := NormalizeHostPort("https://example.com"), "example.com:443"; got != want {
		t.Fatalf("https default port: got %q, want %q", got, want)
	}
	if got, want := NormalizeHostPort("ws://example.com"), "example.com:80"; got != want {
		t.Fatalf("ws default port: got %q, want %q", got, want)
	}
	if got, want := NormalizeHostPort("wss://example.com:8443/socket"), "example.com:8443"; got != want {
		t.Fatalf("explicit wss port: got %q, want %q", got, want)
	}
}

package hostratelimit

import (
	"fmt"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// GetPerHostRateLimiter gets or creates a rate limiter for a specific host
// Returns nil if per-host rate limiting is not enabled
func GetPerHostRateLimiter(options *types.Options, hostname string) (*PerHostRateLimiter, error) {
	if !options.PerHostRateLimit {
		return nil, nil
	}

	dialers := protocolstate.GetDialersWithId(options.ExecutionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", options.ExecutionId)
	}

	dialers.Lock()
	if dialers.PerHostRateLimitPool == nil {
		poolSize := options.PerHostRateLimitPoolSize
		if poolSize == 0 {
			poolSize = 1024
		} else if poolSize < 0 {
			// expirable.LRU uses zero as its unbounded mode. This is useful for
			// scan-persistent embedders that must never refresh a host budget
			// merely because many other hosts were visited.
			poolSize = 0
		}
		// Keep entries for the entire scan duration - no TTL-based eviction during scan
		// so all hosts are tracked throughout the entire scan, even for very long scans
		dialers.PerHostRateLimitPool = NewPerHostRateLimitPool(poolSize, 24*time.Hour, 24*time.Hour, options)
	}
	poolAny := dialers.PerHostRateLimitPool
	dialers.Unlock()

	pool, ok := poolAny.(*PerHostRateLimitPool)
	if !ok || pool == nil {
		return nil, nil
	}

	return pool.GetOrCreate(hostname)
}

// RecordPerHostRateLimitRequest records a request for pps stats calculation
func RecordPerHostRateLimitRequest(options *types.Options, hostname string) {
	if !options.PerHostRateLimit || hostname == "" {
		return
	}

	dialers := protocolstate.GetDialersWithId(options.ExecutionId)
	if dialers == nil {
		return
	}

	dialers.Lock()
	poolAny := dialers.PerHostRateLimitPool
	dialers.Unlock()

	pool, ok := poolAny.(*PerHostRateLimitPool)
	if !ok || pool == nil {
		return
	}

	pool.RecordRequest(hostname)
}

package hostratelimit

import (
	"context"
	"fmt"
	"math"
	"sync"
	"sync/atomic"
	"time"

	"github.com/hashicorp/golang-lru/v2/expirable"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"golang.org/x/time/rate"
)

type PerHostRateLimitPool struct {
	cache       *expirable.LRU[string, *rateLimitEntry]
	capacity    int
	mu          sync.Mutex
	options     *types.Options
	maxLifetime time.Duration // Maximum lifetime for entries regardless of access

	hits      atomic.Uint64
	misses    atomic.Uint64
	evictions atomic.Uint64
}

// ppsWindowSize is the number of recent request timestamps tracked per host
// for pps calculation (heuristic balance between precision and memory)
const ppsWindowSize = 100

type rateLimitEntry struct {
	limiter        *PerHostRateLimiter
	createdAt      time.Time
	accessCount    atomic.Uint64
	requestCount   atomic.Uint64
	firstRequestAt atomic.Int64 // UnixNano timestamp
	lastRequestAt  atomic.Int64 // UnixNano timestamp

	// Fixed-size circular buffer of recent request timestamps for pps
	// calculation: avoids the re-allocations of a sliding slice window
	requestTimestamps [ppsWindowSize]int64
	tsHead            int // next write position
	tsCount           int // number of valid entries (up to ppsWindowSize)
	requestMu         sync.Mutex
}

// PerHostRateLimiter serializes admission for one normalized host.
type PerHostRateLimiter struct {
	limiter   *rate.Limiter
	ctx       context.Context
	cancel    context.CancelFunc
	admission chan struct{}
	unlimited bool
	mu        sync.RWMutex
	limit     uint
	duration  time.Duration
}

// Wait blocks until the host budget admits one request or ctx is canceled.
func (l *PerHostRateLimiter) Wait(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return context.Cause(ctx)
	}
	if l == nil || l.ctx == nil || l.ctx.Err() != nil {
		return nil
	}
	l.mu.RLock()
	unlimited := l.unlimited
	l.mu.RUnlock()
	if unlimited {
		return nil
	}

	select {
	case l.admission <- struct{}{}:
		defer func() { <-l.admission }()
	case <-ctx.Done():
		return context.Cause(ctx)
	case <-l.ctx.Done():
		return nil
	}

	l.mu.RLock()
	if l.unlimited {
		l.mu.RUnlock()
		return nil
	}
	reservation := l.limiter.Reserve()
	l.mu.RUnlock()
	if !reservation.OK() {
		return fmt.Errorf("host rate limiter cannot reserve one request")
	}
	delay := reservation.Delay()
	if delay <= 0 {
		return nil
	}

	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-timer.C:
		return nil
	case <-ctx.Done():
		reservation.Cancel()
		return context.Cause(ctx)
	case <-l.ctx.Done():
		reservation.Cancel()
		return nil
	}
}

// Take waits for one request using a non-cancelable context.
func (l *PerHostRateLimiter) Take() {
	if err := l.Wait(context.Background()); err != nil {
		gologger.Warning().Msgf("Could not take per-host rate limit: %s", err)
	}
}

// CanTake reports whether the limiter can admit a request immediately.
func (l *PerHostRateLimiter) CanTake() bool {
	if l == nil || l.ctx == nil {
		return true
	}
	if l.ctx.Err() != nil {
		return false
	}
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.unlimited || (len(l.admission) == 0 && l.limiter.Tokens() > 0)
}

// GetLimit returns the current request budget for the configured duration.
func (l *PerHostRateLimiter) GetLimit() uint {
	if l == nil {
		return 0
	}
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.limit
}

// SetLimit changes the request budget while preserving the configured duration.
func (l *PerHostRateLimiter) SetLimit(limit uint) {
	if l == nil {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.limit = limit
	l.configureLocked()
}

// SetDuration changes the duration over which the request budget is refilled.
func (l *PerHostRateLimiter) SetDuration(duration time.Duration) {
	if duration <= 0 {
		panic("rate limit duration must be positive")
	}
	if l == nil {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.duration = duration
	l.configureLocked()
}

func (l *PerHostRateLimiter) configureLocked() {
	if l.duration == 0 {
		l.unlimited = true
		return
	}
	requestsPerSecond := rate.Limit(float64(l.limit) / l.duration.Seconds())
	if l.limiter == nil {
		l.limiter = rate.NewLimiter(requestsPerSecond, int(l.limit))
	} else {
		l.limiter.SetLimit(requestsPerSecond)
		l.limiter.SetBurst(int(l.limit))
	}
	if l.admission == nil {
		l.admission = make(chan struct{}, 1)
	}
	l.unlimited = false
}

// Stop releases current and future waiters without reporting a scan error.
func (l *PerHostRateLimiter) Stop() {
	if l != nil && l.cancel != nil {
		l.cancel()
	}
}

func NewPerHostRateLimitPool(size int, maxIdleTime, maxLifetime time.Duration, options *types.Options) *PerHostRateLimitPool {
	if size < 0 {
		size = 0
	}
	// For global scan tracking, use very long TTL to keep entries for entire scan duration
	// Default to 24 hours if not specified, which should cover even very long scans
	if maxIdleTime == 0 {
		maxIdleTime = 24 * time.Hour
	}
	if maxLifetime == 0 {
		maxLifetime = 24 * time.Hour
	}

	ttl := maxIdleTime
	if maxLifetime < maxIdleTime {
		ttl = maxLifetime
	}

	pool := &PerHostRateLimitPool{
		cache: expirable.NewLRU[string, *rateLimitEntry](
			size,
			func(key string, value *rateLimitEntry) {
				gologger.Debug().Msgf("[perhost-ratelimit-pool] Evicted rate limiter for %s (age: %v, accesses: %d)",
					key, time.Since(value.createdAt), value.accessCount.Load())
			},
			ttl,
		),
		capacity:    size,
		options:     options,
		maxLifetime: maxLifetime,
	}

	pool.cache.Purge()

	return pool
}

func (p *PerHostRateLimitPool) GetOrCreate(
	host string,
) (*PerHostRateLimiter, error) {
	normalizedHost := NormalizeHostPort(host)

	// Try to get entry (this refreshes TTL in expirable LRU)
	if entry, ok := p.cache.Get(normalizedHost); ok {
		// Check if entry has exceeded maxLifetime
		if p.maxLifetime > 0 && time.Since(entry.createdAt) > p.maxLifetime {
			// Entry is too old, need to evict and recreate
			// Acquire lock to safely evict
			p.mu.Lock()
			// Double-check after acquiring lock (another goroutine might have evicted it)
			if entry, ok := p.cache.Peek(normalizedHost); ok {
				// Check maxLifetime again (entry might have been replaced)
				if time.Since(entry.createdAt) > p.maxLifetime {
					p.cache.Remove(normalizedHost)
					p.evictions.Add(1)
					// Fall through to create new entry
				} else {
					// Entry was replaced or is now valid
					entry.accessCount.Add(1)
					p.hits.Add(1)
					p.mu.Unlock()
					return entry.limiter, nil
				}
			}
			// Entry was evicted or doesn't exist, continue to create new one
		} else {
			// Entry is valid (not expired by maxLifetime)
			entry.accessCount.Add(1)
			p.hits.Add(1)
			return entry.limiter, nil
		}
	} else {
		// Entry doesn't exist, acquire lock to create
		p.mu.Lock()
	}

	// At this point we have the lock and need to create a new entry
	defer p.mu.Unlock()

	// Double-check after acquiring lock (another goroutine might have created it)
	if entry, ok := p.cache.Peek(normalizedHost); ok {
		// Check maxLifetime
		if p.maxLifetime > 0 && time.Since(entry.createdAt) > p.maxLifetime {
			// Entry is too old, evict it
			p.cache.Remove(normalizedHost)
			p.evictions.Add(1)
		} else {
			// Entry exists and is valid
			entry.accessCount.Add(1)
			p.hits.Add(1)
			return entry.limiter, nil
		}
	}

	p.misses.Add(1)

	// Create new rate limiter for this host
	limiter, err := newPerHostRateLimiter(p.options)
	if err != nil {
		return nil, err
	}

	entry := &rateLimitEntry{
		limiter:   limiter,
		createdAt: time.Now(),
	}
	entry.accessCount.Store(1)

	evicted := p.cache.Add(normalizedHost, entry)
	if evicted {
		p.evictions.Add(1)
	}

	return limiter, nil
}

// newPerHostRateLimiter continuously refills every finite host budget instead
// of starting one fixed-window timer goroutine per host. Apart from producing
// steadier target pressure, this keeps a large host pool cheap and prevents
// several concurrent engines from consuming the whole window at once.
func newPerHostRateLimiter(options *types.Options) (*PerHostRateLimiter, error) {
	ctx, cancel := context.WithCancel(context.Background())
	if options == nil {
		return &PerHostRateLimiter{ctx: ctx, cancel: cancel, unlimited: true, limit: math.MaxUint32, duration: time.Millisecond}, nil
	}
	if options.RateLimit < 0 {
		cancel()
		return nil, fmt.Errorf("rate limit must not be negative: %d", options.RateLimit)
	}
	if options.RateLimitDuration < 0 {
		cancel()
		return nil, fmt.Errorf("rate limit duration must not be negative: %s", options.RateLimitDuration)
	}
	if options.RateLimit == 0 || options.RateLimitDuration == 0 {
		return &PerHostRateLimiter{ctx: ctx, cancel: cancel, unlimited: true, limit: math.MaxUint32, duration: time.Millisecond}, nil
	}
	requestsPerSecond := rate.Limit(float64(options.RateLimit) / options.RateLimitDuration.Seconds())
	return &PerHostRateLimiter{
		limiter:   rate.NewLimiter(requestsPerSecond, options.RateLimit),
		ctx:       ctx,
		cancel:    cancel,
		admission: make(chan struct{}, 1),
		limit:     uint(options.RateLimit),
		duration:  options.RateLimitDuration,
	}, nil
}

func (p *PerHostRateLimitPool) EvictHost(host string) bool {
	normalizedHost := NormalizeHostPort(host)

	existed := p.cache.Remove(normalizedHost)
	if existed {
		p.evictions.Add(1)
	}
	return existed
}

func (p *PerHostRateLimitPool) EvictAll() {
	keys := p.cache.Keys()
	for _, key := range keys {
		if entry, ok := p.cache.Peek(key); ok && entry != nil && entry.limiter != nil {
			entry.limiter.Stop()
		}
	}
	count := p.cache.Len()
	p.cache.Purge()
	p.evictions.Add(uint64(count))
}

func (p *PerHostRateLimitPool) Size() int {
	return p.cache.Len()
}

func (p *PerHostRateLimitPool) Stats() RateLimitPoolStats {
	return RateLimitPoolStats{
		Hits:      p.hits.Load(),
		Misses:    p.misses.Load(),
		Evictions: p.evictions.Load(),
		Size:      p.Size(),
	}
}

func (p *PerHostRateLimitPool) Close() {
	p.EvictAll()
}

type RateLimitPoolStats struct {
	Hits      uint64
	Misses    uint64
	Evictions uint64
	Size      int
}

func (p *PerHostRateLimitPool) GetLimiterForHost(host string) (*PerHostRateLimiter, bool) {
	normalizedHost := NormalizeHostPort(host)

	if entry, ok := p.cache.Peek(normalizedHost); ok {
		return entry.limiter, true
	}
	return nil, false
}

func (p *PerHostRateLimitPool) ListAllLimiters() []string {
	return p.cache.Keys()
}

type RateLimitInfo struct {
	Host        string
	CreatedAt   time.Time
	AccessCount uint64
	Age         time.Duration
}

func (p *PerHostRateLimitPool) GetRateLimitInfo(host string) *RateLimitInfo {
	normalizedHost := NormalizeHostPort(host)

	entry, ok := p.cache.Peek(normalizedHost)
	if !ok {
		return nil
	}

	now := time.Now()

	return &RateLimitInfo{
		Host:        normalizedHost,
		CreatedAt:   entry.createdAt,
		AccessCount: entry.accessCount.Load(),
		Age:         now.Sub(entry.createdAt),
	}
}

func (p *PerHostRateLimitPool) GetAllRateLimitInfo() []*RateLimitInfo {
	infos := []*RateLimitInfo{}
	for _, key := range p.cache.Keys() {
		if info := p.GetRateLimitInfo(key); info != nil {
			infos = append(infos, info)
		}
	}
	return infos
}

func (p *PerHostRateLimitPool) Resize(size int) int {
	evicted := p.cache.Resize(size)
	p.capacity = size
	return evicted
}

func (p *PerHostRateLimitPool) Cap() int {
	return p.capacity
}

// RecordRequest records a request timestamp for a host to calculate pps
func (p *PerHostRateLimitPool) RecordRequest(host string) {
	normalizedHost := NormalizeHostPort(host)
	entry, ok := p.cache.Peek(normalizedHost)
	if !ok || entry == nil {
		return
	}

	now := time.Now().UnixNano()
	entry.requestCount.Add(1)

	// Set first request time if not set
	if entry.firstRequestAt.Load() == 0 {
		entry.firstRequestAt.Store(now)
	}
	entry.lastRequestAt.Store(now)

	// Track recent timestamps for pps calculation (circular buffer, no re-allocs)
	entry.requestMu.Lock()
	entry.requestTimestamps[entry.tsHead] = now
	entry.tsHead = (entry.tsHead + 1) % ppsWindowSize
	if entry.tsCount < ppsWindowSize {
		entry.tsCount++
	}
	entry.requestMu.Unlock()
}

// calculatePPS calculates requests per second for a host based on recent requests
func (p *PerHostRateLimitPool) calculatePPS(entry *rateLimitEntry) float64 {
	if entry == nil {
		return 0
	}

	entry.requestMu.Lock()
	defer entry.requestMu.Unlock()

	if entry.tsCount < 2 {
		// Need at least 2 requests to calculate pps
		return 0
	}

	now := time.Now().UnixNano()
	// Calculate pps based on requests in the last second, walking the circular
	// buffer backwards from the most recent timestamp
	oneSecondAgo := now - int64(time.Second)
	recentRequests := 0
	for i := 0; i < entry.tsCount; i++ {
		idx := (entry.tsHead - 1 - i + 2*ppsWindowSize) % ppsWindowSize
		if entry.requestTimestamps[idx] >= oneSecondAgo {
			recentRequests++
		} else {
			break
		}
	}

	// If we have recent requests, use them; otherwise calculate from total time span
	if recentRequests > 0 {
		return float64(recentRequests)
	}

	// Fallback: calculate average pps from first to last request
	first := entry.firstRequestAt.Load()
	last := entry.lastRequestAt.Load()
	if first == 0 || last == 0 || last <= first {
		return 0
	}

	duration := time.Duration(last - first)
	if duration <= 0 {
		return 0
	}

	totalRequests := entry.requestCount.Load()
	if totalRequests < 2 {
		return 0
	}

	return float64(totalRequests) / duration.Seconds()
}

func (p *PerHostRateLimitPool) PrintStats() {
	stats := p.Stats()
	if stats.Size == 0 {
		return
	}
	var hitRate float64
	if total := stats.Hits + stats.Misses; total > 0 {
		hitRate = float64(stats.Hits) * 100 / float64(total)
	}
	gologger.Info().Msgf("[perhost-ratelimit-pool] Rate limit stats: Hits=%d Misses=%d HitRate=%.1f%% Hosts=%d",
		stats.Hits, stats.Misses, hitRate, stats.Size)
}

// PrintPerHostPPSStats prints requests per second for each host
func (p *PerHostRateLimitPool) PrintPerHostPPSStats() {
	if p.Size() == 0 {
		return
	}

	type hostStat struct {
		host     string
		pps      float64
		requests uint64
		age      time.Duration
	}

	// Collect stats under lock, log after releasing it to avoid blocking
	// concurrent GetOrCreate/RecordRequest callers during slow I/O
	p.mu.Lock()
	hostStats := []hostStat{}
	for _, key := range p.cache.Keys() {
		entry, ok := p.cache.Peek(key)
		if !ok || entry == nil {
			continue
		}

		hostStats = append(hostStats, hostStat{
			host:     key,
			pps:      p.calculatePPS(entry),
			requests: entry.requestCount.Load(),
			age:      time.Since(entry.createdAt),
		})
	}
	p.mu.Unlock()

	if len(hostStats) == 0 {
		return
	}

	gologger.Info().Msgf("[perhost-ratelimit-pool] Per-host requests per second (pps):")
	for _, stat := range hostStats {
		gologger.Info().Msgf("  %s: %.2f pps (total: %d requests, age: %v)",
			stat.host, stat.pps, stat.requests, stat.age.Round(time.Second))
	}
}

package interactsh

import (
	"errors"
	"time"
)

var (
	defaultInteractionDuration = 60 * time.Second

	ErrInteractshClientNotInitialized = errors.New("interactsh client not initialized")
)

const (
	stopAtFirstMatchAttribute   = "stop-at-first-match"
	templateIdAttribute         = "template-id"
	defaultMaxInteractionsCount = 5000
)

package interactsh

import (
	"bytes"
	"fmt"
	"os"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"errors"

	"github.com/projectdiscovery/gcache"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/interactsh/pkg/client"
	"github.com/projectdiscovery/interactsh/pkg/server"
	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz/frequency"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/progress"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/responsehighlighter"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/writer"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/marker"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/utils/errkit"
	stringsutil "github.com/projectdiscovery/utils/strings"
)

// Client is a wrapped client for interactsh server.
type Client struct {
	sync.Once
	sync.RWMutex
	cacheOnce          sync.Once
	requestLifecycleMu sync.RWMutex

	options *Options

	// interactsh is a client for interactsh server.
	interactsh *client.Client
	// requests is a stored cache for interactsh-url->request-event data.
	requests gcache.Cache[string, *RequestData]
	// interactions is a stored cache for interactsh-interaction->interactsh-url data
	interactions gcache.Cache[string, []*server.Interaction]
	// matchedTemplates is a stored cache to track matched templates
	matchedTemplates gcache.Cache[string, bool]
	// interactshURLs is a stored cache to track multiple interactsh markers
	interactshURLs gcache.Cache[string, string]

	eviction         time.Duration
	pollDuration     time.Duration
	cooldownDuration time.Duration

	hostname string

	// determines if wait the cooldown period in case of generated URL
	generated atomic.Bool
	matched   atomic.Bool
	// lastExpirySweep is when dropExpiredRequests last ran, in Unix nanoseconds.
	lastExpirySweep atomic.Int64

	onInteractionMu sync.RWMutex
	onInteraction   func(i *server.Interaction, foundRequest *RequestData)
}

var _ IClient = &Client{}

var interactshSNIAnnotationRegex = regexp.MustCompile(`(?m)^[\t ]*@tls-sni:[\t ]*(?:https?://)?interactsh-url[\t ]*$`)

// RequestScope owns the delayed interaction registrations created by one
// engine execution. A shared Client can serve many concurrent executions, but
// each execution still needs its own callback window and deterministic cleanup.
type RequestScope struct {
	client    *Client
	once      sync.Once
	mu        sync.Mutex
	ids       map[string]struct{}
	closing   bool
	callbacks sync.WaitGroup
}

// NewRequestScope creates an execution-scoped interaction lifecycle. Call
// Close after the execution work pool has drained.
func (c *Client) NewRequestScope() *RequestScope {
	return &RequestScope{client: c, ids: make(map[string]struct{})}
}

func (s *RequestScope) track(id string) bool {
	if s == nil || id == "" {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closing {
		return false
	}
	s.ids[id] = struct{}{}
	return true
}

func (s *RequestScope) beginCallback() bool {
	if s == nil {
		return true
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closing {
		return false
	}
	s.callbacks.Add(1)
	return true
}

func (s *RequestScope) endCallback() {
	if s != nil {
		s.callbacks.Done()
	}
}

// Close waits the same callback cooldown used by a standalone Client, then
// removes only this execution's unmatched registrations. The shared poller and
// registrations belonging to other executions remain active.
func (s *RequestScope) Close() {
	if s == nil || s.client == nil {
		return
	}
	s.once.Do(func() {
		s.mu.Lock()
		hasRegistrations := len(s.ids) > 0
		s.mu.Unlock()
		if hasRegistrations && s.client.cooldownDuration > 0 {
			time.Sleep(s.client.cooldownDuration)
		}

		// Serialize registration removal with the poller's request lookup and
		// callback admission. A callback that already found this execution's
		// request is counted before closing begins; a later callback cannot start.
		s.client.requestLifecycleMu.Lock()
		s.mu.Lock()
		s.closing = true
		ids := make([]string, 0, len(s.ids))
		for id := range s.ids {
			ids = append(ids, id)
		}
		s.mu.Unlock()
		if s.client.requests != nil {
			for _, id := range ids {
				s.client.requests.Remove(id)
			}
		}
		s.client.requestLifecycleMu.Unlock()

		// Result writers, progress reporters, and issue clients remain owned by
		// the execution until every callback admitted above has completed.
		s.callbacks.Wait()
	})
}

// New returns a new interactsh server client
func New(options *Options) (*Client, error) {
	interactClient := &Client{
		eviction:         options.Eviction,
		options:          options,
		pollDuration:     options.PollDuration,
		cooldownDuration: options.CooldownPeriod,
	}
	return interactClient, nil
}

func (c *Client) SetInteractionCallback(cb func(interaction *server.Interaction, foundRequest *RequestData)) {
	c.onInteractionMu.Lock()
	defer c.onInteractionMu.Unlock()
	c.onInteraction = cb
}

func (c *Client) notifyInteraction(interaction *server.Interaction, request *RequestData, err error) {
	c.onInteractionMu.RLock()
	cb := c.onInteraction
	c.onInteractionMu.RUnlock()
	if cb == nil || err != nil || request == nil {
		return
	}
	cb(interaction, request)
}

func (c *Client) initializeCaches() {
	c.cacheOnce.Do(func() {
		requests := gcache.New[string, *RequestData](c.options.CacheSize).LRU().Build()
		interactions := gcache.New[string, []*server.Interaction](defaultMaxInteractionsCount).LRU().Build()
		matchedTemplates := gcache.New[string, bool](defaultMaxInteractionsCount).LRU().Build()
		interactshURLs := gcache.New[string, string](defaultMaxInteractionsCount).LRU().Build()

		c.interactions = interactions
		c.matchedTemplates = matchedTemplates
		c.interactshURLs = interactshURLs
		c.requests = requests
	})
}

func (c *Client) poll() error {
	if c.options.NoInteractsh {
		// do not init if disabled
		return ErrInteractshClientNotInitialized
	}
	c.initializeCaches()
	interactsh, err := client.New(&client.Options{
		ServerURL:           c.options.ServerURL,
		Token:               c.options.Authorization,
		DisableHTTPFallback: c.options.DisableHttpFallback,
		HTTPClient:          c.options.HTTPClient,
		KeepAliveInterval:   time.Minute,
	})
	if err != nil {
		return errkit.Wrap(err, "could not create client")
	}

	c.interactsh = interactsh

	interactURL := interactsh.URL()
	interactDomain := interactURL[strings.Index(interactURL, ".")+1:]
	gologger.Info().Msgf("Using Interactsh Server: %s", interactDomain)

	c.setHostname(interactDomain)

	err = interactsh.StartPolling(c.pollDuration, func(interaction *server.Interaction) {
		c.requestLifecycleMu.RLock()
		request, err := c.requests.Get(interaction.UniqueID)
		callbackAdmitted := request != nil && request.Scope.beginCallback()
		c.requestLifecycleMu.RUnlock()
		c.notifyInteraction(interaction, request, err)
		// for more context in github actions
		if strings.EqualFold(os.Getenv("GITHUB_ACTIONS"), "true") && c.options.Debug {
			gologger.DefaultLogger.Print().Msgf("[Interactsh]: got interaction of %v for request %v and error %v", interaction, request, err)
		}
		if errors.Is(err, gcache.KeyNotFoundError) || request == nil {
			// If we don't have any request for this ID, add it to temporary
			// lru cache, so we can correlate when we get an add request.
			items, err := c.interactions.Get(interaction.UniqueID)
			if errkit.Is(err, gcache.KeyNotFoundError) || items == nil {
				_ = c.interactions.SetWithExpire(interaction.UniqueID, []*server.Interaction{interaction}, defaultInteractionDuration)
			} else {
				items = append(items, interaction)
				_ = c.interactions.SetWithExpire(interaction.UniqueID, items, defaultInteractionDuration)
			}
			return
		}
		if !callbackAdmitted {
			return
		}
		defer request.Scope.endCallback()

		if requestShouldStopAtFirstMatch(request) || c.options.StopAtFirstMatch {
			if gotItem, err := c.matchedTemplates.Get(eventHash(request.Event)); gotItem && err == nil {
				return
			}
		}

		_ = c.processInteractionForRequest(interaction, request)
	})

	if err != nil {
		return errkit.Wrap(err, "could not perform interactsh polling")
	}
	return nil
}

// requestShouldStopAtFirstMatch checks if further interactions should be stopped
// note: extra care should be taken while using this function since internalEvent is
// synchronized all the time and if caller functions has already acquired lock its best to explicitly specify that
// we could use `TryLock()` but that may over complicate things and need to differentiate
// situations whether to block or skip
func requestShouldStopAtFirstMatch(request *RequestData) bool {
	request.Event.RLock()
	defer request.Event.RUnlock()

	if stop, ok := request.Event.InternalEvent[stopAtFirstMatchAttribute]; ok {
		if v, ok := stop.(bool); ok {
			return v
		}
	}
	return false
}

// processInteractionForRequest processes an interaction for a request
func (c *Client) processInteractionForRequest(interaction *server.Interaction, data *RequestData) bool {
	var result *operators.Result
	var matched bool
	var templateID string
	data.Event.Lock()
	data.Event.InternalEvent["interactsh_protocol"] = interaction.Protocol
	if strings.EqualFold(interaction.Protocol, "dns") {
		data.Event.InternalEvent["interactsh_request"] = strings.ToLower(interaction.RawRequest)
	} else {
		data.Event.InternalEvent["interactsh_request"] = interaction.RawRequest
	}
	data.Event.InternalEvent["interactsh_response"] = interaction.RawResponse
	data.Event.InternalEvent["interactsh_ip"] = interaction.RemoteAddress
	if data.Operators != nil {
		result, matched = data.Operators.Execute(data.Event.InternalEvent, data.MatchFunc, data.ExtractFunc, c.options.Debug || c.options.DebugRequest || c.options.DebugResponse)
	} else {
		// this is most likely a bug so error instead of warning
		if data.Event.InternalEvent != nil {
			templateID = fmt.Sprint(data.Event.InternalEvent[templateIdAttribute])
		}
	}
	data.Event.Unlock()
	if data.Operators == nil {
		gologger.Error().Msgf("missing compiled operators for '%v' template", templateID)
	}

	// for more context in github actions
	if strings.EqualFold(os.Getenv("GITHUB_ACTIONS"), "true") && c.options.Debug {
		gologger.DefaultLogger.Print().Msgf("[Interactsh]: got result %v and status %v after processing interaction", result, matched)
	}

	fuzzParamsFrequency := data.FuzzParamsFrequency
	if fuzzParamsFrequency == nil {
		fuzzParamsFrequency = c.options.FuzzParamsFrequency
	}
	// Parameter frequency applies only to fuzz-generated requests. Regular OOB
	// requests do not carry the concrete HTTP request/parameter needed to build
	// a frequency key, even though the execution itself owns a tracker.
	if fuzzParamsFrequency != nil && data.Request != nil && data.Operators != nil {
		if !matched {
			fuzzParamsFrequency.MarkParameter(data.Parameter, data.Request.String(), data.Operators.TemplateID)
		} else {
			fuzzParamsFrequency.UnmarkParameter(data.Parameter, data.Request.String(), data.Operators.TemplateID)
		}
	}

	// if we don't match, return
	if !matched || result == nil {
		return false
	}
	c.requests.Remove(interaction.UniqueID)

	if data.Event.OperatorsResult != nil {
		data.Event.OperatorsResult.Merge(result)
	} else {
		data.Event.SetOperatorResult(result)
	}
	// ensure payload values are preserved for interactsh-only matches
	data.Event.Lock()
	if data.Event.OperatorsResult != nil && len(data.Event.OperatorsResult.PayloadValues) == 0 {
		if payloads, ok := data.Event.InternalEvent["payloads"].(map[string]interface{}); ok {
			data.Event.OperatorsResult.PayloadValues = payloads
		}
	}
	data.Event.Unlock()

	data.Event.Lock()
	data.Event.Results = data.MakeResultFunc(data.Event)
	for _, event := range data.Event.Results {
		event.Interaction = interaction
	}
	data.Event.Unlock()

	if c.options.Debug || c.options.DebugRequest || c.options.DebugResponse {
		c.debugPrintInteraction(interaction, data.Event.OperatorsResult)
	}

	// if event is not already matched, write it to output
	outputWriter := data.Output
	if outputWriter == nil {
		outputWriter = c.options.Output
	}
	progressClient := data.Progress
	if progressClient == nil {
		progressClient = c.options.Progress
	}
	issuesClient := data.IssuesClient
	if issuesClient == nil {
		issuesClient = c.options.IssuesClient
	}
	if !data.Event.InteractshMatched.Load() && writer.WriteResult(data.Event, outputWriter, progressClient, issuesClient) {
		data.Event.InteractshMatched.Store(true)
		c.matched.Store(true)
		if requestShouldStopAtFirstMatch(data) || c.options.StopAtFirstMatch {
			_ = c.matchedTemplates.SetWithExpire(eventHash(data.Event), true, defaultInteractionDuration)
		}
	}

	return true
}

func (c *Client) AlreadyMatched(data *RequestData) bool {
	c.initializeCaches()
	return c.matchedTemplates.Has(eventHash(data.Event))
}

// URL returns a new URL that can be interacted with
func (c *Client) URL() (string, error) {
	if c == nil {
		return "", ErrInteractshClientNotInitialized
	}
	// first time initialization
	var err error
	c.Do(func() {
		err = c.poll()
	})
	if err != nil {
		return "", errkit.Wrap(ErrInteractshClientNotInitialized, err.Error())
	}

	if c.interactsh == nil {
		return "", ErrInteractshClientNotInitialized
	}

	c.generated.Store(true)
	return c.interactsh.URL(), nil
}

// Close the interactsh clients after waiting for cooldown period.
func (c *Client) Close() bool {
	if c == nil {
		return false
	}
	if c.cooldownDuration > 0 && c.generated.Load() {
		time.Sleep(c.cooldownDuration)
	}

	if c.interactsh != nil {
		_ = c.interactsh.StopPolling()
		_ = c.interactsh.Close()
	}

	if c.requests != nil {
		c.requests.Purge()
		c.interactions.Purge()
		c.matchedTemplates.Purge()
		c.interactshURLs.Purge()
	}

	return c.matched.Load()
}

// Replace replaces the default Interactsh URL placeholders with interactsh URLs.
func (c *Client) Replace(data string, interactshURLs []string) (string, []string) {
	for _, interactshURLMarker := range marker.FindInteractshURLMarkers(data) {
		if url, err := c.NewURLWithData(interactshURLMarker); err == nil {
			interactshURLs = append(interactshURLs, url)
			data = strings.Replace(data, interactshURLMarker, url, 1)
		}
	}
	return data, interactshURLs
}

// ReplaceWithMarker replaces custom regex matches with Interactsh URLs and appends them to interactshURLs.
func (c *Client) ReplaceWithMarker(data string, regex *regexp.Regexp, interactshURLs []string) (string, []string) {
	for _, interactshURLMarker := range regex.FindAllString(data, -1) {
		if url, err := c.NewURLWithData(interactshURLMarker); err == nil {
			interactshURLs = append(interactshURLs, url)
			data = strings.Replace(data, interactshURLMarker, url, 1)
		}
	}
	return data, interactshURLs
}

func (c *Client) NewURL() (string, error) {
	return c.NewURLWithData("")
}

func (c *Client) NewURLWithData(data string) (string, error) {
	url, err := c.URL()
	if err != nil {
		return "", err
	}
	if url == "" {
		return "", errors.New("empty interactsh url")
	}
	_ = c.interactshURLs.SetWithExpire(url, data, defaultInteractionDuration)
	return url, nil
}

// MakePlaceholders does placeholders for interact URLs and other data to a map
func (c *Client) MakePlaceholders(urls []string, data map[string]interface{}) {
	data["interactsh-server"] = c.getHostname()
	if len(urls) == 0 {
		return
	}
	c.initializeCaches()
	for _, url := range urls {
		if interactshURLMarker, err := c.interactshURLs.Get(url); interactshURLMarker != "" && err == nil {
			interactshMarker := strings.TrimSuffix(strings.TrimPrefix(interactshURLMarker, "{{"), "}}")

			c.interactshURLs.Remove(url)

			data[interactshMarker] = url
			urlIndex := strings.Index(url, ".")
			if urlIndex == -1 {
				continue
			}
			data[strings.Replace(interactshMarker, "url", "id", 1)] = url[:urlIndex]
		}
	}
}

// MakeResultEventFunc is a result making function for nuclei
type MakeResultEventFunc func(wrapped *output.InternalWrappedEvent) []*output.ResultEvent

// RequestData contains data for a request event
type RequestData struct {
	MakeResultFunc MakeResultEventFunc
	Event          *output.InternalWrappedEvent
	Operators      *operators.Operators
	MatchFunc      operators.MatchFunc
	ExtractFunc    operators.ExtractFunc

	Parameter string
	Request   *retryablehttp.Request

	// These fields route delayed results back to the execution that registered
	// the request when the Interactsh client is shared concurrently.
	Output              output.Writer
	Progress            progress.Progress
	IssuesClient        reporting.Client
	FuzzParamsFrequency *frequency.Tracker
	Scope               *RequestScope
}

// RequestEvent is the event for a network request sent by nuclei.
func (c *Client) RequestEvent(interactshURLs []string, data *RequestData) {
	if len(interactshURLs) == 0 {
		return
	}
	c.initializeCaches()
	c.dropExpiredRequests()
	for _, interactshURL := range interactshURLs {
		id := strings.TrimRight(strings.TrimSuffix(interactshURL, c.getHostname()), ".")

		if requestShouldStopAtFirstMatch(data) || c.options.StopAtFirstMatch {
			gotItem, err := c.matchedTemplates.Get(eventHash(data.Event))
			if gotItem && err == nil {
				break
			}
		}

		interactions, err := c.interactions.Get(id)
		if interactions != nil && err == nil {
			for _, interaction := range interactions {
				if !data.Scope.beginCallback() {
					break
				}
				matched := c.processInteractionForRequest(interaction, data)
				data.Scope.endCallback()
				if matched {
					c.interactions.Remove(id)
					break
				}
			}
		} else {
			c.requestLifecycleMu.RLock()
			if data.Scope.track(id) {
				_ = c.requests.SetWithExpire(id, data, c.eviction)
			}
			c.requestLifecycleMu.RUnlock()
		}
	}
}

// dropExpiredRequests removes the registrations past their eviction deadline,
// at most once per poll interval.
//
// The cache drops an expired entry only when its key is read again or the LRU
// needs room, and the key of a target that never calls back is never read. So
// without this, a scan keeps the event of every OOB request, response body and
// full response included, until the cache is full: CacheSize times the response
// read size. An expired entry can no longer match anyway, since the poller's
// lookup drops it unprocessed.
func (c *Client) dropExpiredRequests() {
	now := time.Now().UnixNano()
	last := c.lastExpirySweep.Load()
	if now-last < int64(c.pollDuration) || !c.lastExpirySweep.CompareAndSwap(last, now) {
		return
	}

	// The write lock keeps a registration from being replaced between its
	// expiry check and its removal.
	c.requestLifecycleMu.Lock()
	defer c.requestLifecycleMu.Unlock()

	for _, id := range c.requests.Keys(false) {
		if !c.requests.Has(id) {
			c.requests.Remove(id)
		}
	}
}

// HasMatchers returns true if an operator has interactsh part
// matchers or extractors.
//
// Used by requests to show result or not depending on presence of interact.sh
// data part matchers.
func HasMatchers(op *operators.Operators) bool {
	if op == nil {
		return false
	}

	for _, matcher := range op.Matchers {
		for _, dsl := range matcher.DSL {
			if stringsutil.ContainsAnyI(dsl, "interactsh") {
				return true
			}
		}
		if stringsutil.HasPrefixI(matcher.Part, "interactsh") {
			return true
		}
	}
	for _, matcher := range op.Extractors {
		if stringsutil.HasPrefixI(matcher.Part, "interactsh") {
			return true
		}
	}
	return false
}

// HasMarkers checks if the text contains any syntax that asks Nuclei to
// generate an Interactsh URL. In addition to template markers, raw HTTP
// requests support the special @tls-sni annotation without braces.
func HasMarkers(data string) bool {
	return marker.HasInteractshURLMarker(data) || interactshSNIAnnotationRegex.MatchString(data)
}

func (c *Client) debugPrintInteraction(interaction *server.Interaction, event *operators.Result) {
	builder := &bytes.Buffer{}

	switch interaction.Protocol {
	case "dns":
		builder.WriteString(formatInteractionHeader("DNS", interaction.FullId, interaction.RemoteAddress, interaction.Timestamp))
		if c.options.DebugRequest || c.options.Debug {
			builder.WriteString(formatInteractionMessage("DNS Request", interaction.RawRequest, event, c.options.NoColor))
		}
		if c.options.DebugResponse || c.options.Debug {
			builder.WriteString(formatInteractionMessage("DNS Response", interaction.RawResponse, event, c.options.NoColor))
		}
	case "http":
		builder.WriteString(formatInteractionHeader("HTTP", interaction.FullId, interaction.RemoteAddress, interaction.Timestamp))
		if c.options.DebugRequest || c.options.Debug {
			builder.WriteString(formatInteractionMessage("HTTP Request", interaction.RawRequest, event, c.options.NoColor))
		}
		if c.options.DebugResponse || c.options.Debug {
			builder.WriteString(formatInteractionMessage("HTTP Response", interaction.RawResponse, event, c.options.NoColor))
		}
	case "smtp":
		builder.WriteString(formatInteractionHeader("SMTP", interaction.FullId, interaction.RemoteAddress, interaction.Timestamp))
		if c.options.DebugRequest || c.options.Debug || c.options.DebugResponse {
			builder.WriteString(formatInteractionMessage("SMTP Interaction", interaction.RawRequest, event, c.options.NoColor))
		}
	case "ldap":
		builder.WriteString(formatInteractionHeader("LDAP", interaction.FullId, interaction.RemoteAddress, interaction.Timestamp))
		if c.options.DebugRequest || c.options.Debug || c.options.DebugResponse {
			builder.WriteString(formatInteractionMessage("LDAP Interaction", interaction.RawRequest, event, c.options.NoColor))
		}
	}
	_, _ = fmt.Fprint(os.Stderr, builder.String())
}

func formatInteractionHeader(protocol, ID, address string, at time.Time) string {
	return fmt.Sprintf("[%s] Received %s interaction from %s at %s", ID, protocol, address, at.Format("2006-01-02 15:04:05"))
}

func formatInteractionMessage(key, value string, event *operators.Result, noColor bool) string {
	value = responsehighlighter.Highlight(event, value, noColor, false)
	return fmt.Sprintf("\n------------\n%s\n------------\n\n%s\n\n", key, value)
}

func hash(internalEvent output.InternalEvent) string {
	templateId := internalEvent[templateIdAttribute].(string)
	host := internalEvent["host"].(string)
	return fmt.Sprintf("%s:%s", templateId, host)
}

func eventHash(event *output.InternalWrappedEvent) string {
	event.RLock()
	defer event.RUnlock()

	return hash(event.InternalEvent)
}

func (c *Client) getHostname() string {
	c.RLock()
	defer c.RUnlock()

	return c.hostname
}

func (c *Client) setHostname(hostname string) {
	c.Lock()
	defer c.Unlock()

	c.hostname = hostname
}

// GetHostname returns the configured interactsh server hostname.
func (c *Client) GetHostname() string {
	return c.getHostname()
}

