func TestExcludeTargetsMatchExactHost(t *testing.T) {
	opts := types.DefaultOptions()
	opts.ExecutionId = "test-exclude-targets"
	opts.ExcludeTargets = []string{"test.com", "192.0.2.0/24", `^regex\.example$`, "bücher.example"}
	require.NoError(t, Init(opts))
	defer Close(opts.ExecutionId)

	np := GetDialersWithId(opts.ExecutionId).NetworkPolicy
	require.False(t, np.Validate("test.com"))
	require.False(t, np.Validate("TEST.com"))
	require.False(t, np.Validate("test.com."))
	require.False(t, np.Validate("sub.test.com"))
	require.False(t, np.Validate("192.0.2.10"))
	require.False(t, np.Validate("regex.example"))
	require.False(t, np.Validate("xn--bcher-kva.example"))
	require.True(t, np.Validate("latest.com"))
	require.True(t, np.Validate("test.com.example.org"))
	require.True(t, np.Validate("testXcom"))
	require.True(t, np.Validate("sub.regex.example"))
}

func TestMappedFormsDeniedByDialer(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	defer server.Close()
	_, port, err := net.SplitHostPort(server.Listener.Addr().String())
	require.NoError(t, err)

	for name, set := range map[string]func(*types.Options){
		"lna":           func(o *types.Options) { o.RestrictLocalNetworkAccess = true },
		"exclude-hosts": func(o *types.Options) { o.ExcludeTargets = []string{"127.0.0.1"} },
		"exclude-cidr":  func(o *types.Options) { o.ExcludeTargets = []string{"127.0.0.0/8"} },
	} {
		t.Run(name, func(t *testing.T) {
			opts := types.DefaultOptions()
			opts.ExecutionId = "test-mapped-" + name
			set(opts)
			require.NoError(t, Init(opts))
			defer Close(opts.ExecutionId)

			d := GetDialersWithId(opts.ExecutionId)
			hosts := []string{"127.0.0.1", "::ffff:127.0.0.1", "::ffff:7f00:1", "0:0:0:0:0:ffff:127.0.0.1"}
			if opts.RestrictLocalNetworkAccess {
				hosts = append(hosts, "::")
			}
			for _, host := range hosts {
				require.False(t, d.NetworkPolicy.Validate(host), host)
				ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
				conn, err := d.Fastdialer.Dial(ctx, "tcp", net.JoinHostPort(host, port))
				cancel()
				if conn != nil {
					_ = conn.Close()
				}
				require.Error(t, err, host)
			}
			require.True(t, d.NetworkPolicy.Validate("::ffff:8.8.8.8"))
			require.True(t, d.NetworkPolicy.Validate("8.8.8.8"))
		})
	}
}

func TestMappedDenyRanges(t *testing.T) {
	require.Equal(t, []string{"::ffff:127.0.0.0/104", "::ffff:192.0.2.10/128", "::ffff:0.0.0.0/104"},
		mappedDenyRanges([]string{"127.0.0.0/8", "192.0.2.10", "::1/128", "fc00::/7", `(?i)(^|\.)test\.com\.?$`, "0.0.0.0/8"}))
}

package randomip

import (
	"crypto/rand"
	"net"

	"github.com/pkg/errors"
	iputil "github.com/projectdiscovery/utils/ip"
	randutil "github.com/projectdiscovery/utils/rand"
)

const (
	maxIterations = 255
)

func GetRandomIPWithCidr(cidrs ...string) (net.IP, error) {
	if len(cidrs) == 0 {
		return nil, errors.Errorf("must specify at least one cidr")
	}

	randIdx, err := randutil.IntN(len(cidrs))
	if err != nil {
		return nil, err
	}

	cidr := cidrs[randIdx]

	if !iputil.IsCIDR(cidr) {
		return nil, errors.Errorf("%s is not a valid cidr", cidr)
	}

	baseIp, ipnet, err := net.ParseCIDR(cidr)
	if err != nil {
		return nil, err
	}

	switch {
	case ipnet.Mask[len(ipnet.Mask)-1] == 255:
		return baseIp, nil
	case iputil.IsIPv4(baseIp.String()):
		return getRandomIP(ipnet, 4), nil
	case iputil.IsIPv6(baseIp.String()):
		return getRandomIP(ipnet, 16), nil
	default:
		return nil, errors.New("invalid base ip")
	}
}

func getRandomIP(ipnet *net.IPNet, size int) net.IP {
	ip := ipnet.IP
	var iteration int

	for iteration < maxIterations {
		iteration++
		ones, _ := ipnet.Mask.Size()
		quotient := ones / 8
		remainder := ones % 8
		var r []byte
		switch size {
		case 4, 16:
			r = make([]byte, size)
		default:
			return ip
		}

		_, err := rand.Read(r)
		if err != nil {
			break
		}

		for i := 0; i <= quotient; i++ {
			if i == quotient {
				shifted := byte(r[i]) >> remainder
				r[i] = ipnet.IP[i] + (^ipnet.IP[i] & shifted)
			} else {
				r[i] = ipnet.IP[i]
			}
		}

		ip = r

		if !ip.Equal(ipnet.IP) {
			break
		}
	}

	return ip
}

package randomip

import (
	"net"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestGetRandomIp(t *testing.T) {
	tests := []struct {
		name     string
		cidr     []string
		errorMsg string
		valid    bool
	}{
		{
			name:  "Valid C class",
			cidr:  []string{"193.6.32.110/24"},
			valid: true,
		},
		{
			name:  "Valid B class",
			cidr:  []string{"128.34.33.29/16"},
			valid: true,
		},
		{
			name:  "Valid A class",
			cidr:  []string{"10.1.2.3/8"},
			valid: true,
		},
		{
			name:  "Valid classless zero based network",
			cidr:  []string{"205.102.139.2/30"},
			valid: true,
		},
		{
			name:  "Valid classless non-zero based network",
			cidr:  []string{"205.102.139.49/29"},
			valid: true,
		},
		{
			name:  "Multiple CIDRs",
			cidr:  []string{"1.2.3.4/15", "230.149.150.22/28"},
			valid: true,
		},
		{
			name:     "Negative CIDR length",
			cidr:     []string{"10.11.12.13/-1"},
			valid:    false,
			errorMsg: "10.11.12.13/-1 is not a valid CIDR",
		},
		{
			name:     "Large CIDR length",
			cidr:     []string{"10.11.12.13/33"},
			valid:    false,
			errorMsg: "10.11.12.13/33 is not a valid CIDR",
		},
		{
			name:     "No CIDR provided",
			cidr:     []string{},
			valid:    false,
			errorMsg: "must specify at least one cidr",
		},
		{
			name:  "Valid but crazy",
			cidr:  []string{"0.0.0.0/0"},
			valid: true,
		},
		{
			name:  "Valid but unlikely",
			cidr:  []string{"193.6.32.109/32"},
			valid: true,
		},
		{
			name:  "Valid IPv6",
			cidr:  []string{"2607:fb91:1294:85fa:3cbf:491:cd46:2625/120"},
			valid: true,
		},
		{
			name:  "Classless IPv4 starting with a non-zero base",
			cidr:  []string{"129.47.78.253/30"},
			valid: true,
		},
		{
			name:  "IPv6 and IPv4",
			cidr:  []string{"2603:8080:4400:d070:913:dee4:6c0c:9ae8/96", "212.78.146.240/25"},
			valid: true,
		},
		{
			name:     "Negative CIDR length IPv6",
			cidr:     []string{"2600:1700:27c:70:44eb:2d78:86b3:e905/-1"},
			valid:    false,
			errorMsg: "2600:1700:27c:70:44eb:2d78:86b3:e905/-1 is not a valid CIDR",
		},
		{
			name:     "Large CIDR length IPv6",
			cidr:     []string{"2607:fb91:bd02:127c:d736:abcf:5c77:e7fd/129"},
			valid:    false,
			errorMsg: "2607:fb91:bd02:127c:d736:abcf:5c77:e7fd/129 is not a valid CIDR",
		},
		{
			name:  "Valid but unlikely IPv6",
			cidr:  []string{"2607:fb91:bd02:127c:d736:abcf:5c77:e7fd/128"},
			valid: true,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			ip, err := GetRandomIPWithCidr(test.cidr...)
			if test.valid {
				require.NoError(t, err)
				anyInRange := false
				for _, cidr := range test.cidr {
					_, network, _ := net.ParseCIDR(cidr)
					anyInRange = anyInRange || network.Contains(ip)
				}
				require.Truef(t, anyInRange, "the IP address returned %v is not in range of the provided CIDRs", ip)
			} else {
				require.Error(t, err, test.errorMsg)
			}
		})
	}
}

// Package render centralizes rendering of template text with runtime values.
package render

import (
	"fmt"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/expressions"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/marker"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// Values contains render values. Values are inserted as data; they are not
// scanned as new template text after insertion.
type Values = map[string]interface{}

// URLSource allocates URLs for Interactsh markers found in template text.
type URLSource interface {
	NewURLWithData(data string) (string, error)
}

// Input describes a render operation. Text is template text, Values are data,
// and Interactsh is optional source-level marker handling.
type Input struct {
	// Options supplies scan authority separately from template-controlled values.
	Options      *types.Options
	Text         string
	Values       Values
	Interactsh   URLSource
	InteractURLs []string
}

// Result is the terminal rendered data and any Interactsh URLs allocated while
// rendering template text.
type Result struct {
	Text         string
	InteractURLs []string
}

// MapInput describes a map render operation. Source values are template text.
// Data values are terminal data that override Source and are not rendered.
type MapInput struct {
	Options *types.Options
	Source  Values
	Data    Values
	// Values is the evaluation context used while rendering Source.
	Values Values
	// Interactsh and InteractURLs carry source-level Interactsh allocations.
	Interactsh   URLSource
	InteractURLs []string
}

// MapResult contains the complete value map after Source rendering and Data
// overlay, plus any Interactsh URLs allocated while rendering Source values.
type MapResult struct {
	Values       Values
	InteractURLs []string
}

// Render evaluates template text with values and returns rendered data.
//
// Interactsh markers in Text are source-level render effects and are allocated
// before DSL helper evaluation, so helper transforms apply to generated URLs.
// Values are data and rendered output is terminal data; neither is rescanned for
// DSL expressions or Interactsh markers.
func Render(input Input) (Result, error) {
	prepared, err := ReplaceInteractshMarkers(input.Text, input.Interactsh, input.InteractURLs)
	if err != nil {
		return prepared, err
	}

	result, err := expressions.EvaluateWithOptions(prepared.Text, input.Values, input.Options)
	if err != nil {
		return prepared, err
	}

	return Result{Text: result, InteractURLs: prepared.InteractURLs}, nil
}

// RenderMap renders Source values as template text, overlays Data values, and
// returns a complete value map. Data keys are skipped while rendering so they
// cannot produce DSL or Interactsh side effects.
//
// It is intended for already-expanded payload iteration maps, not raw payload
// definitions containing lists.
func RenderMap(input MapInput) (MapResult, error) {
	values := make(Values, len(input.Source)+len(input.Data))
	urls := append([]string(nil), input.InteractURLs...)

	for key, value := range input.Source {
		if _, ok := input.Data[key]; ok {
			continue
		}

		result, err := Render(Input{
			Options:      input.Options,
			Text:         fmt.Sprint(value),
			Values:       input.Values,
			Interactsh:   input.Interactsh,
			InteractURLs: urls,
		})
		if err != nil {
			return MapResult{Values: values, InteractURLs: result.InteractURLs}, err
		}

		values[key] = result.Text
		urls = result.InteractURLs
	}

	for key, value := range input.Data {
		values[key] = value
	}

	return MapResult{Values: values, InteractURLs: urls}, nil
}

// ReplaceInteractshMarkers allocates Interactsh URLs for markers that appear in
// template text. It does not evaluate DSL expressions or inspect values.
func ReplaceInteractshMarkers(text string, source URLSource, interactURLs []string) (Result, error) {
	urls := append([]string(nil), interactURLs...)
	if source == nil {
		return Result{Text: text, InteractURLs: urls}, nil
	}

	for _, interactshURLMarker := range marker.FindInteractshURLMarkers(text) {
		url, err := source.NewURLWithData(interactshURLMarker)
		if err != nil {
			return Result{Text: text, InteractURLs: urls}, fmt.Errorf("replace interactsh marker %q: %w", interactshURLMarker, err)
		}

		urls = append(urls, url)
		text = strings.Replace(text, interactshURLMarker, url, 1)
	}

	return Result{Text: text, InteractURLs: urls}, nil
}

