package variables

// There are total 5 sources of variables
// 1. VariablesMap - Variables defined in the template  (available at Request.options.Variables in protocols)
// 2. PayloadsMap  - Payloads defined in the template   (available at Request.generator in protocols)
// 3. OptionsMap   - Variables passed using CLI Options (+ Env) (available at generators.BuildPayloadFromOptions)
// 4. DynamicMap   - Variables Obtained by extracting data from templates  (available at Request.ExecuteWithResults + merged with previous internalEvent)
// 5. ProtocolMap  - Variables generated by Evaluation Request / Responses of xyz protocol (available in Request.Make)
// 6. ConstantsMap  - Constants defined in the template (available at Request.options.Constants in protocols)

// As we can tell , all variables sources are not linear i.e why they need to re-evaluated
// consider example
// variables:
//  - name: "username@{{Host}}"

// Linear Sources (once obtained no need to re-evaluate)
// simply put they don't contain references to other variables
// 1. OptionsMap
// 2. DynamicMap
// 3. ProtocolMap

// Non-Linear Sources (need to re-evaluate)
// 1. VariablesMap
// 2. PayloadsMap
// Every time Linear Sources are updated , Non-Linear Sources need to be re-evaluated

// Constants (no need to re-evaluate, should contain only scalars)

package variables

import "github.com/projectdiscovery/nuclei/v3/pkg/types"

// Scope contains values used while evaluating template variables.
//
// Data values are terminal values from runtime, options, constants, payloads,
// or protocol context. Template values are produced from the template variables
// section and may be re-rendered when later data becomes available.
type Scope struct {
	values  map[string]scopeValue
	options *types.Options
}

type scopeValueKind uint8

const (
	scopeValueData scopeValueKind = iota
	scopeValueTemplate
)

type scopeValue struct {
	value interface{}
	kind  scopeValueKind
}

// NewScope creates an empty variable evaluation scope.
func NewScope() *Scope {
	return &Scope{values: make(map[string]scopeValue)}
}

// WithOptions binds this scope to the current scan without adding template variables.
func (s *Scope) WithOptions(options *types.Options) *Scope {
	s.options = options
	return s
}

// AddData adds terminal data values to the scope.
func (s *Scope) AddData(values ...map[string]interface{}) *Scope {
	if s == nil {
		return s
	}

	for _, valueMap := range values {
		for key, value := range valueMap {
			s.AddDataValue(key, value)
		}
	}

	return s
}

// AddDataValue adds one terminal data value to the scope.
func (s *Scope) AddDataValue(key string, value interface{}) *Scope {
	if s == nil {
		return s
	}

	s.values[key] = scopeValue{value: value, kind: scopeValueData}

	return s
}

// AddTemplate adds values produced from template variables.
func (s *Scope) AddTemplate(values map[string]interface{}) *Scope {
	if s == nil {
		return s
	}

	for key, value := range values {
		s.AddTemplateValue(key, value)
	}

	return s
}

// AddTemplateValue adds one value produced from template variables.
func (s *Scope) AddTemplateValue(key string, value interface{}) *Scope {
	if s == nil {
		return s
	}

	s.values[key] = scopeValue{value: value, kind: scopeValueTemplate}

	return s
}

// Values returns a plain value map for render evaluation.
func (s *Scope) Values() map[string]interface{} {
	if s == nil || len(s.values) == 0 {
		return nil
	}

	values := make(map[string]interface{}, len(s.values))
	for key, value := range s.values {
		values[key] = value.value
	}

	return values
}

func (s *Scope) clone() *Scope {
	if s == nil {
		return NewScope()
	}

	clone := NewScope().WithOptions(s.options)
	for key, value := range s.values {
		clone.values[key] = value
	}

	return clone
}

func (s *Scope) get(key string) (scopeValue, bool) {
	if s == nil {
		return scopeValue{}, false
	}

	value, ok := s.values[key]

	return value, ok
}

