package dnsclientpool

import (
	"strconv"
	"strings"
	"sync"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryabledns"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

var (
	clientPool *mapsutil.SyncLockMap[string, *Client]

	normalClient *Client
	m            sync.Mutex
)

// defaultResolvers contains the list of resolvers known to be trusted.
var defaultResolvers = []string{
	"1.1.1.1:53", // Cloudflare
	"1.0.0.1:53", // Cloudflare
	"8.8.8.8:53", // Google
	"8.8.4.4:53", // Google
}

// Init initializes the client pool implementation.
// Each resolver list gets its own client, so a later scan is not stuck with the first scan's resolvers.
func Init(options *types.Options) error {
	client, err := cachedClient(resolversFor(options))
	if err != nil {
		return errors.Wrap(err, "could not create dns client")
	}
	m.Lock()
	normalClient = client
	m.Unlock()
	return nil
}

func resolversFor(options *types.Options) []string {
	if options != nil && len(options.InternalResolversList) > 0 {
		return options.InternalResolversList
	}
	return defaultResolvers
}

func cachedClient(resolvers []string) (*Client, error) {
	m.Lock()
	defer m.Unlock()
	if clientPool == nil {
		clientPool = mapsutil.NewSyncLockMap[string, *Client]()
	}
	key := strings.Join(resolvers, ",")
	if client, ok := clientPool.Get(key); ok {
		return client, nil
	}
	dnsClient, err := retryabledns.New(resolvers, 1)
	if err != nil {
		return nil, err
	}
	client := &Client{Client: dnsClient}
	_ = clientPool.Set(key, client)
	return client, nil
}

// Configuration contains the custom configuration options for a client
type Configuration struct {
	// Retries contains the retries for the dns client
	Retries int
	// Resolvers contains the specific per request resolvers
	Resolvers []string
	// Proxy contains the proxy to use for the dns client
	Proxy string
}

// Hash returns the hash of the configuration to allow client pooling
func (c *Configuration) Hash() string {
	builder := &strings.Builder{}
	builder.WriteString("r")
	builder.WriteString(strconv.Itoa(c.Retries))
	builder.WriteString("l")
	builder.WriteString(strings.Join(c.Resolvers, ""))
	builder.WriteString("p")
	builder.WriteString(c.Proxy)
	hash := builder.String()
	return hash
}

// Get creates or gets a client for the protocol based on custom configuration
func Get(options *types.Options, configuration *Configuration) (*Client, error) {
	if (configuration.Retries <= 1) && len(configuration.Resolvers) == 0 {
		return cachedClient(resolversFor(options))
	}
	if len(options.InternalResolversList) == 0 && hasPolicyResolver(configuration.Resolvers) {
		return getPolicyClient(options, configuration)
	}
	hash := configuration.Hash()
	if client, ok := clientPool.Get(hash); ok {
		return client, nil
	}

	resolvers := defaultResolvers
	if len(options.InternalResolversList) > 0 {
		resolvers = options.InternalResolversList
	} else if len(configuration.Resolvers) > 0 {
		resolvers = configuration.Resolvers
	}
	dnsClient, err := retryabledns.NewWithOptions(retryabledns.Options{
		BaseResolvers: resolvers,
		MaxRetries:    configuration.Retries,
		Proxy:         options.AliveSocksProxy,
	})
	if err != nil {
		return nil, errors.Wrap(err, "could not create dns client")
	}
	client := &Client{Client: dnsClient}
	_ = clientPool.Set(hash, client)

	return client, nil
}

package dnsclientpool

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"fmt"
	"net"
	"net/http"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/miekg/dns"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryabledns"
	"github.com/projectdiscovery/retryabledns/doh"
)

// Client sends the DNS queries of a template. It sends queries for template
// DoH and DoT resolvers itself, because the retryabledns clients dial and
// follow redirects without the network policy of the scan.
type Client struct {
	*retryabledns.Client

	resolvers []resolver
	retries   int
	index     uint32
	doh       *doh.Client
	transport *http.Transport
	dial      func(ctx context.Context, network, address string) (net.Conn, error)
	timeout   time.Duration
}

// resolver is one template resolver. url is set for a DoH resolver and dot
// for a DoT resolver, and both are empty for a resolver that retryabledns
// queries over UDP or TCP.
type resolver struct {
	url    string
	method doh.Method
	dot    string
}

var (
	// policyClients holds the clients with DoH or DoT resolvers of each execution,
	// because each one dials with the dialer of its execution.
	policyClients = map[string]map[string]*Client{}
	policyMu      sync.Mutex

	// dotRootCAs verifies DoT certificates, and nil uses the system roots.
	dotRootCAs *x509.CertPool
)

func hasPolicyResolver(resolvers []string) bool {
	for _, r := range resolvers {
		if strings.HasPrefix(r, "doh:") || strings.HasPrefix(r, "dot:") {
			return true
		}
	}
	return false
}

// parseDotResolver returns the host and port of a resolver such as
// dot:dns.example or dot:dns.example:853, in the same way as retryabledns.
func parseDotResolver(r string) (resolver, bool) {
	if !strings.HasPrefix(r, "dot:") {
		return resolver{}, false
	}
	address := strings.TrimPrefix(r, "dot:")
	if _, _, err := net.SplitHostPort(address); err != nil {
		address = net.JoinHostPort(address, "853")
	}
	return resolver{dot: address}, true
}

// parseDohResolver returns the URL and method of a resolver such as
// doh:https://dns.example/dns-query:get, in the same way as retryabledns.
func parseDohResolver(r string) (resolver, bool) {
	if !strings.HasPrefix(r, "doh:") {
		return resolver{}, false
	}
	u := strings.TrimPrefix(r, "doh:")
	method := doh.MethodPost
	for _, suffix := range []string{":get", ":post", ":jsonapi"} {
		if strings.HasSuffix(u, suffix) {
			u = strings.TrimSuffix(u, suffix)
			if suffix == ":get" {
				method = doh.MethodGet
			}
			break
		}
	}
	return resolver{url: u, method: method}, true
}

func getPolicyClient(options *types.Options, configuration *Configuration) (*Client, error) {
	executionID := options.ExecutionId
	hash := configuration.Hash()

	policyMu.Lock()
	defer policyMu.Unlock()
	if client, ok := policyClients[executionID][hash]; ok {
		return client, nil
	}

	client := &Client{retries: configuration.Retries}
	var networkResolvers []string
	for _, r := range configuration.Resolvers {
		if parsed, ok := parseDohResolver(r); ok {
			client.resolvers = append(client.resolvers, parsed)
			continue
		}
		if parsed, ok := parseDotResolver(r); ok {
			client.resolvers = append(client.resolvers, parsed)
			continue
		}
		client.resolvers = append(client.resolvers, resolver{})
		networkResolvers = append(networkResolvers, r)
	}
	// Trace and the UDP and TCP resolvers still go through retryabledns.
	if len(networkResolvers) == 0 {
		networkResolvers = defaultResolvers
	}
	dnsClient, err := retryabledns.NewWithOptions(retryabledns.Options{
		BaseResolvers: networkResolvers,
		MaxRetries:    1,
		Proxy:         options.AliveSocksProxy,
	})
	if err != nil {
		return nil, errors.Wrap(err, "could not create dns client")
	}
	client.Client = dnsClient

	// The scan dialer checks every address it connects to, so redirects
	// and names that resolve to a denied address are refused too. It also
	// goes through the scan proxy when one is set.
	client.dial = func(ctx context.Context, network, address string) (net.Conn, error) {
		dialers := protocolstate.GetDialersWithId(executionID)
		if dialers == nil || dialers.Fastdialer == nil {
			return nil, fmt.Errorf("dialers not initialized for %s", executionID)
		}
		return dialers.Fastdialer.Dial(ctx, network, address)
	}
	client.timeout = options.GetTimeouts().DialTimeout
	client.transport = &http.Transport{
		DialContext: client.dial,
		// same as the retryabledns DoH client
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true}, // #nosec G402
	}
	client.doh = doh.NewWithOptions(doh.Options{
		HttpClient: &http.Client{
			Transport: client.transport,
			Timeout:   options.GetTimeouts().HttpTimeout,
		},
	})

	if policyClients[executionID] == nil {
		policyClients[executionID] = map[string]*Client{}
	}
	policyClients[executionID][hash] = client
	return client, nil
}

// Do sends a DNS message to the resolvers in turn until one answers with
// NOERROR, like retryabledns.Client.Do.
func (c *Client) Do(msg *dns.Msg) (*dns.Msg, error) {
	if len(c.resolvers) == 0 {
		return c.Client.Do(msg)
	}
	var resp *dns.Msg
	var err error
	for i := 0; i < c.retries; i++ {
		index := atomic.AddUint32(&c.index, 1)
		r := c.resolvers[index%uint32(len(c.resolvers))]
		if r.url != "" {
			resp, err = c.doh.QueryWithDOHMsg(r.method, doh.Resolver{URL: r.url}, msg)
		} else if r.dot != "" {
			resp, err = c.queryDoT(r.dot, msg)
		} else {
			resp, err = c.Client.Do(msg)
		}
		if err == nil && resp != nil && resp.Rcode == dns.RcodeSuccess {
			return resp, nil
		}
	}
	return resp, retryabledns.ErrRetriesExceeded
}

// queryDoT sends a DNS message over TLS to address. It dials through the scan
// dialer and verifies the certificate against the resolver host, as the
// retryabledns DoT client does.
func (c *Client) queryDoT(address string, msg *dns.Msg) (*dns.Msg, error) {
	host, _, err := net.SplitHostPort(address)
	if err != nil {
		return nil, err
	}
	timeout := c.timeout
	if timeout <= 0 {
		timeout = retryabledns.DefaultOptions.Timeout
	}
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	conn, err := c.dial(ctx, "tcp", address)
	if err != nil {
		return nil, err
	}
	tlsConn := tls.Client(conn, &tls.Config{ServerName: host, RootCAs: dotRootCAs, MinVersion: tls.VersionTLS12})
	defer func() { _ = tlsConn.Close() }()
	if err := tlsConn.HandshakeContext(ctx); err != nil {
		return nil, err
	}
	dnsClient := &dns.Client{Net: "tcp-tls", Timeout: timeout}
	resp, _, err := dnsClient.ExchangeWithConn(msg, &dns.Conn{Conn: tlsConn})
	return resp, err
}

// Close drops the clients with DoH or DoT resolvers of an execution.
func Close(executionID string) {
	policyMu.Lock()
	clients := policyClients[executionID]
	delete(policyClients, executionID)
	policyMu.Unlock()
	for _, client := range clients {
		client.transport.CloseIdleConnections()
	}
}

package dnsclientpool

import (
	"net"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/miekg/dns"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

// newDohServer answers every DoH query with a TXT record and counts the hits.
func newDohServer(t *testing.T, hits *atomic.Int32) *httptest.Server {
	t.Helper()
	return newDohServerOn(t, hits, "127.0.0.1:0")
}

// newDohServerOn is newDohServer bound to address, so a test can separate an
// allowed redirector from a denied target.
func newDohServerOn(t *testing.T, hits *atomic.Int32, address string) *httptest.Server {
	t.Helper()
	listener, err := net.Listen("tcp", address)
	require.NoError(t, err)
	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		m := new(dns.Msg)
		m.SetQuestion("example.com.", dns.TypeTXT)
		m.Response = true
		rr, err := dns.NewRR(`example.com. 60 IN TXT "doh-answer"`)
		require.NoError(t, err)
		m.Answer = append(m.Answer, rr)
		packed, err := m.Pack()
		require.NoError(t, err)
		w.Header().Set("Content-Type", "application/dns-message")
		_, _ = w.Write(packed)
	}))
	server.Listener = listener
	server.Start()
	t.Cleanup(server.Close)
	return server
}

func dohOptions(t *testing.T, excludeTargets []string) *types.Options {
	t.Helper()
	options := types.DefaultOptions()
	options.ExecutionId = t.Name()
	options.ExcludeTargets = excludeTargets
	require.NoError(t, protocolstate.Init(options))
	t.Cleanup(func() { protocolstate.Close(options.ExecutionId) })
	require.NoError(t, Init(options))
	return options
}

func txtQuery() *dns.Msg {
	msg := new(dns.Msg)
	msg.SetQuestion("example.com.", dns.TypeTXT)
	return msg
}

func TestDohResolverObeysNetworkPolicy(t *testing.T) {
	t.Run("denied address", func(t *testing.T) {
		var hits atomic.Int32
		internal := newDohServer(t, &hits)
		options := dohOptions(t, []string{"127.0.0.1"})

		client, err := Get(options, &Configuration{Retries: 1, Resolvers: []string{"doh:" + internal.URL + "/dns-query:get"}})
		require.NoError(t, err)
		_, _ = client.Do(txtQuery())
		require.Zero(t, hits.Load(), "DoH query reached a denied address")
	})

	t.Run("redirect to denied address", func(t *testing.T) {
		var hits atomic.Int32
		// The target listens on ::1, which is denied. The redirector stays on
		// 127.0.0.1. localhost cannot be the allowed hop: denying 127.0.0.1
		// denies localhost too, because that name resolves to 127.0.0.1.
		internal := newDohServerOn(t, &hits, "[::1]:0")
		redirector := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			http.Redirect(w, r, internal.URL+"/internal", http.StatusFound)
		}))
		t.Cleanup(redirector.Close)
		options := dohOptions(t, []string{"::1"})
		require.True(t, protocolstate.IsHostAllowed(options.ExecutionId, "127.0.0.1"))
		require.False(t, protocolstate.IsHostAllowed(options.ExecutionId, "::1"))

		client, err := Get(options, &Configuration{Retries: 1, Resolvers: []string{"doh:" + redirector.URL + "/dns-query:get"}})
		require.NoError(t, err)
		_, _ = client.Do(txtQuery())
		require.Zero(t, hits.Load(), "DoH redirect reached a denied address")
	})

	t.Run("allowed address", func(t *testing.T) {
		var hits atomic.Int32
		server := newDohServer(t, &hits)
		options := dohOptions(t, nil)

		client, err := Get(options, &Configuration{Retries: 2, Resolvers: []string{"doh:" + server.URL + "/dns-query:get"}})
		require.NoError(t, err)
		resp, err := client.Do(txtQuery())
		require.NoError(t, err)
		require.Len(t, resp.Answer, 1)
		require.Equal(t, int32(1), hits.Load())
	})
}

package dnsclientpool

import (
	"crypto/tls"
	"net"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/miekg/dns"
	"github.com/stretchr/testify/require"
)

// newDotListener accepts TCP connections on 127.0.0.1, counts them and closes
// them, so a test sees each DoT dial that reaches the address.
func newDotListener(t *testing.T, hits *atomic.Int32) string {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	require.NoError(t, err)
	t.Cleanup(func() { _ = l.Close() })
	go func() {
		for {
			conn, err := l.Accept()
			if err != nil {
				return
			}
			hits.Add(1)
			_ = conn.Close()
		}
	}()
	_, port, err := net.SplitHostPort(l.Addr().String())
	require.NoError(t, err)
	return port
}

func TestDotResolverObeysNetworkPolicy(t *testing.T) {
	for _, host := range []string{"127.0.0.1", "localhost"} {
		t.Run("denied address "+host, func(t *testing.T) {
			var hits atomic.Int32
			port := newDotListener(t, &hits)
			// localhost passes the resolver check through ::1, while 127.0.0.1 is denied
			options := dohOptions(t, []string{"127.0.0.1"})

			client, err := Get(options, &Configuration{Retries: 2, Resolvers: []string{"dot:" + net.JoinHostPort(host, port)}})
			require.NoError(t, err)
			_, _ = client.Do(txtQuery())
			require.Zero(t, hits.Load(), "DoT query reached a denied address")
		})
	}

	t.Run("allowed address", func(t *testing.T) {
		var hits atomic.Int32
		port := newDotListener(t, &hits)
		options := dohOptions(t, nil)

		client, err := Get(options, &Configuration{Retries: 1, Resolvers: []string{"dot:127.0.0.1:" + port}})
		require.NoError(t, err)
		_, _ = client.Do(txtQuery())
		require.Equal(t, int32(1), hits.Load())
	})
}

func TestDotResolverAnswers(t *testing.T) {
	// httptest gives a certificate for 127.0.0.1 and a pool that trusts it.
	certs := httptest.NewTLSServer(http.NotFoundHandler())
	t.Cleanup(certs.Close)
	previous := dotRootCAs
	dotRootCAs = certs.Client().Transport.(*http.Transport).TLSClientConfig.RootCAs
	t.Cleanup(func() { dotRootCAs = previous })

	l, err := tls.Listen("tcp", "127.0.0.1:0", &tls.Config{Certificates: certs.TLS.Certificates, MinVersion: tls.VersionTLS12})
	require.NoError(t, err)
	server := &dns.Server{Listener: l, Net: "tcp-tls", Handler: dns.HandlerFunc(func(w dns.ResponseWriter, q *dns.Msg) {
		m := new(dns.Msg)
		m.SetReply(q)
		rr, _ := dns.NewRR(`example.com. 60 IN TXT "dot-answer"`)
		m.Answer = append(m.Answer, rr)
		_ = w.WriteMsg(m)
	})}
	go func() { _ = server.ActivateAndServe() }()
	t.Cleanup(func() { _ = server.Shutdown() })

	options := dohOptions(t, nil)
	client, err := Get(options, &Configuration{Retries: 2, Resolvers: []string{"dot:" + l.Addr().String()}})
	require.NoError(t, err)
	resp, err := client.Do(txtQuery())
	require.NoError(t, err)
	require.Len(t, resp.Answer, 1)
	require.Contains(t, resp.Answer[0].String(), "dot-answer")
}

package dns

import (
	"bytes"
	"fmt"
	"strings"
	"time"

	"github.com/miekg/dns"

	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/extractors"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryabledns"
)

// Match matches a generic data response against a given matcher
func (request *Request) Match(data map[string]interface{}, matcher *matchers.Matcher) (bool, []string) {
	item, ok := request.getMatchPart(matcher.Part, data)
	// an llm matcher with inputs compares whole responses instead of one part
	if !ok && matcher.Type.MatcherType != matchers.DSLMatcher && len(matcher.Inputs) == 0 {
		return false, []string{}
	}

	switch matcher.GetType() {
	case matchers.StatusMatcher:
		statusCode, ok := item.(int)
		if !ok {
			return false, []string{}
		}
		return matcher.Result(matcher.MatchStatusCode(statusCode)), []string{}
	case matchers.SizeMatcher:
		return matcher.Result(matcher.MatchSize(len(types.ToString(item)))), []string{}
	case matchers.WordsMatcher:
		return matcher.ResultWithMatchedSnippet(matcher.MatchWordsWithOptions(types.ToString(item), data, request.options.GetOptions()))
	case matchers.RegexMatcher:
		return matcher.ResultWithMatchedSnippet(matcher.MatchRegex(types.ToString(item)))
	case matchers.BinaryMatcher:
		return matcher.ResultWithMatchedSnippet(matcher.MatchBinary(types.ToString(item)))
	case matchers.DSLMatcher:
		return matcher.Result(matcher.MatchDSLWithOptions(data, request.options.GetOptions())), []string{}
	case matchers.XPathMatcher:
		return matcher.Result(matcher.MatchXPath(types.ToString(item))), []string{}
	case matchers.LLMMatcher:
		return protocols.MatchLLM(data, matcher, types.ToString(item), request.options)
	}
	return false, []string{}
}

// Extract performs extracting operation for an extractor on model and returns true or false.
func (request *Request) Extract(data map[string]interface{}, extractor *extractors.Extractor) map[string]struct{} {
	item, ok := request.getMatchPart(extractor.Part, data)
	if !ok && !extractors.SupportsMap(extractor) {
		return nil
	}

	switch extractor.GetType() {
	case extractors.RegexExtractor:
		return extractor.ExtractRegex(types.ToString(item))
	case extractors.KValExtractor:
		return extractor.ExtractKval(data)
	case extractors.DSLExtractor:
		return extractor.ExtractDSLWithOptions(data, request.options.GetOptions())
	case extractors.LLMExtractor:
		return protocols.ExtractLLM(data, extractor, types.ToString(item), request.options)
	}
	return nil
}

func (request *Request) getMatchPart(part string, data output.InternalEvent) (interface{}, bool) {
	switch part {
	case "body", "all", "":
		part = "raw"
	}

	item, ok := data[part]
	if !ok {
		return "", false
	}

	return item, true
}

// responseToDSLMap converts a DNS response to a map for use in DSL matching
func (request *Request) responseToDSLMap(req, resp *dns.Msg, host, matched string, traceData *retryabledns.TraceData, duration time.Duration) output.InternalEvent {
	ret := output.InternalEvent{
		"host":          host,
		"matched":       matched,
		"request":       req.String(),
		"duration":      duration.Seconds(),
		"rcode":         resp.Rcode,
		"question":      questionToString(resp.Question),
		"extra":         rrToString(resp.Extra),
		"answer":        rrToString(resp.Answer),
		"ns":            rrToString(resp.Ns),
		"raw":           resp.String(),
		"template-id":   request.options.TemplateID,
		"template-info": request.options.TemplateInfo,
		"template-path": request.options.TemplatePath,
		"type":          request.Type().String(),
		"trace":         traceToString(traceData, false),
	}
	if len(resp.Answer) > 0 {
		ret = generators.MergeMaps(ret, recordsKeyValue(resp.Answer))
	}
	return ret
}

// MakeResultEvent creates a result event from internal wrapped event
func (request *Request) MakeResultEvent(wrapped *output.InternalWrappedEvent) []*output.ResultEvent {
	return protocols.MakeDefaultResultEvent(request, wrapped)
}

func (request *Request) MakeResultEventItem(wrapped *output.InternalWrappedEvent) *output.ResultEvent {
	data := &output.ResultEvent{
		TemplateID:       types.ToString(wrapped.InternalEvent["template-id"]),
		TemplatePath:     types.ToString(wrapped.InternalEvent["template-path"]),
		Info:             wrapped.InternalEvent["template-info"].(model.Info),
		TemplateVerifier: request.options.TemplateVerifier,
		Type:             types.ToString(wrapped.InternalEvent["type"]),
		Host:             types.ToString(wrapped.InternalEvent["host"]),
		Matched:          types.ToString(wrapped.InternalEvent["matched"]),
		ExtractedResults: wrapped.OperatorsResult.OutputExtracts,
		MatcherStatus:    true,
		Timestamp:        time.Now(),
		Request:          types.ToString(wrapped.InternalEvent["request"]),
		Response:         types.ToString(wrapped.InternalEvent["raw"]),
		TemplateEncoded:  request.options.EncodeTemplate(),
		Error:            types.ToString(wrapped.InternalEvent["error"]),
	}
	return data
}

func rrToString(resourceRecords []dns.RR) string { // TODO rewrite with generics when available
	buffer := &bytes.Buffer{}
	for _, resourceRecord := range resourceRecords {
		buffer.WriteString(resourceRecord.String())
	}
	return buffer.String()
}

func questionToString(resourceRecords []dns.Question) string {
	buffer := &bytes.Buffer{}
	for _, resourceRecord := range resourceRecords {
		buffer.WriteString(resourceRecord.String())
	}
	return buffer.String()
}

func traceToString(traceData *retryabledns.TraceData, withSteps bool) string {
	buffer := &bytes.Buffer{}
	if traceData != nil {
		for i, dnsRecord := range traceData.DNSData {
			if withSteps {
				fmt.Fprintf(buffer, "request %d to resolver %s:\n", i, strings.Join(dnsRecord.Resolver, ","))
			}
			_, _ = fmt.Fprintf(buffer, "%s\n", dnsRecord.Raw)
		}
	}
	return buffer.String()
}

func recordsKeyValue(resourceRecords []dns.RR) output.InternalEvent {
	var oe = make(output.InternalEvent)
	for _, resourceRecord := range resourceRecords {
		key := strings.ToLower(dns.TypeToString[resourceRecord.Header().Rrtype])
		value := strings.TrimSuffix(strings.ReplaceAll(resourceRecord.String(), resourceRecord.Header().String(), ""), ".")

		// if the key is already present, we need to convert the value to a slice
		// if the key has slice, then append the value to the slice
		if previous, ok := oe[key]; ok {
			switch v := previous.(type) {
			case string:
				oe[key] = []string{v, value}
			case []string:
				oe[key] = append(v, value)
			}
			continue
		}
		oe[key] = value
	}
	return oe
}

package dns

import (
