	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/internal/tests/testutils"
)

func TestDNSExecuteWithResults(t *testing.T) {
	options := testutils.DefaultOptions

	recursion := true
	testutils.Init(options)
	templateID := "testing-dns"
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   templateID,
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Low}, Name: "test"},
	})
	request := &Request{
		RequestType: DNSRequestTypeHolder{DNSRequestType: A},
		Class:       "INET",
		Retries:     5,
		ID:          templateID,
		Recursion:   &recursion,
		Name:        "{{FQDN}}",
		Operators: operators.Operators{
			Matchers: []*matchers.Matcher{{
				Name:  "test",
				Part:  "raw",
				Type:  matchers.MatcherTypeHolder{MatcherType: matchers.WordsMatcher},
				Words: []string{"8.8.8.8"},
			}},
			Extractors: []*extractors.Extractor{{
				Part:  "raw",
				Type:  extractors.ExtractorTypeHolder{ExtractorType: extractors.RegexExtractor},
				Regex: []string{"[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+"},
			}},
		},
		options: executerOpts,
	}
	err := request.Compile(executerOpts)
	require.Nil(t, err, "could not compile dns request")

	var finalEvent *output.InternalWrappedEvent
	t.Run("domain-valid", func(t *testing.T) {
		metadata := make(output.InternalEvent)
		previous := make(output.InternalEvent)
		ctxArgs := contextargs.NewWithInput(context.Background(), "dns.google")
		err := request.ExecuteWithResults(ctxArgs, metadata, previous, func(event *output.InternalWrappedEvent) {
			finalEvent = event
		})
		require.Nil(t, err, "could not execute dns request")
	})
	require.NotNil(t, finalEvent, "could not get event output from request")
	require.Equal(t, 1, len(finalEvent.Results), "could not get correct number of results")
	require.Equal(t, "test", finalEvent.Results[0].MatcherName, "could not get correct matcher name of results")
	require.GreaterOrEqual(t, 2, len(finalEvent.Results[0].ExtractedResults), "could not get correct number of extracted results")
	require.Contains(t, finalEvent.Results[0].ExtractedResults, "8.8.8.8", "could not get correct extracted results")
	require.Contains(t, finalEvent.Results[0].ExtractedResults, "8.8.4.4", "could not get correct extracted results")
	finalEvent = nil
	// Note: changing url to domain is responsible at tmplexec package and is implemented there
}

// With -pc below 1 the worker pool must still be built, and one payload is
// sent at a time, so the server sees them in iterator order.
//
//nolint:exhaustruct,exhaustruct_v5,paralleltest // fixtures keep zero-value defaults; the test options are global
func TestDNSPayloadsRunWithPayloadConcurrencyBelowOne(t *testing.T) {
	for _, payloadConcurrency := range []int{0, -1} {
		t.Run(fmt.Sprintf("pc=%d", payloadConcurrency), func(t *testing.T) {
			listener, err := (&net.ListenConfig{}).ListenPacket(t.Context(), "udp", "127.0.0.1:0")
			require.NoError(t, err)

			// ExecuteWithResults returns after the last reply, so every name is queued by then.
			names := make(chan string, 8)
			started := make(chan struct{})
			server := &dns.Server{
				PacketConn: listener,
				Handler: dns.HandlerFunc(func(w dns.ResponseWriter, r *dns.Msg) {
					names <- r.Question[0].Name

					_ = w.WriteMsg(new(dns.Msg).SetReply(r))
				}),
				NotifyStartedFunc: func() { close(started) },
			}

			t.Cleanup(func() { _ = server.Shutdown() })

			go func() { _ = server.ActivateAndServe() }()

			select {
			case <-started:
			case <-time.After(2 * time.Second):
				t.Fatal("dns server did not start")
			}

			options := testutils.DefaultOptions.Copy()
			options.PayloadConcurrency = payloadConcurrency
			testutils.Init(options)
			t.Cleanup(func() { testutils.Cleanup(options) })

			recursion := false
			request := &Request{
				ID:          "dns-payloads",
				RequestType: DNSRequestTypeHolder{DNSRequestType: A},
				Class:       "INET",
				Retries:     1,
				Recursion:   &recursion,
				Name:        "{{word}}.{{FQDN}}",
				Resolvers:   []string{listener.LocalAddr().String()},
				Payloads:    map[string]any{"word": []string{"one", "two", "three"}},
			}
			executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{ID: "dns-payloads"})
			require.NoError(t, request.Compile(executerOpts))
			require.Equal(t, 1, request.Threads, "a -pc below 1 sends one payload at a time")

			input := contextargs.NewWithInput(t.Context(), "example.com")
			err = request.ExecuteWithResults(input, nil, nil, func(*output.InternalWrappedEvent) {})
			require.NoError(t, err)

			got := make([]string, 0, len(names))
			for len(names) > 0 {
				got = append(got, <-names)
			}

			require.Equal(t, []string{"one.example.com.", "two.example.com.", "three.example.com."}, got)
		})
	}
}

package dns

import (
	"context"
	"net"
	"sync/atomic"
	"testing"
	"time"

	"github.com/miekg/dns"
	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/internal/tests/testutils"
	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
)

// startDNSServer answers every query with a TXT record, or with the A records
// in addrs when the question is for name, and counts the queries.
func startDNSServer(t *testing.T, name string, addrs []string, hits *atomic.Int32) string {
	t.Helper()
	pc, err := net.ListenPacket("udp", "127.0.0.1:0")
	require.NoError(t, err)
	server := &dns.Server{PacketConn: pc, Handler: dns.HandlerFunc(func(w dns.ResponseWriter, q *dns.Msg) {
		hits.Add(1)
		m := new(dns.Msg)
		m.SetReply(q)
		question := q.Question[0]
		switch {
		case question.Name == name && question.Qtype == dns.TypeA:
			for _, addr := range addrs {
				rr, _ := dns.NewRR(name + " 0 IN A " + addr)
				m.Answer = append(m.Answer, rr)
			}
		case question.Name == name:
		default:
			rr, _ := dns.NewRR(question.Name + ` 0 IN TXT "answer"`)
			m.Answer = append(m.Answer, rr)
		}
		_ = w.WriteMsg(m)
	})}
	go func() { _ = server.ActivateAndServe() }()
	t.Cleanup(func() { _ = server.Shutdown() })
	l, err := net.Listen("tcp", pc.LocalAddr().String())
	require.NoError(t, err)
	tcpServer := &dns.Server{Listener: l, Handler: server.Handler}
	go func() { _ = tcpServer.ActivateAndServe() }()
	t.Cleanup(func() { _ = tcpServer.Shutdown() })
	return pc.LocalAddr().String()
}

// useSystemResolver sends the lookups of the process to the DNS server at address.
func useSystemResolver(t *testing.T, address string) {
	t.Helper()
	previous := net.DefaultResolver
	net.DefaultResolver = &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
			var d net.Dialer
			return d.DialContext(ctx, "udp", address)
		},
	}
	t.Cleanup(func() { net.DefaultResolver = previous })
}

func TestDNSResolverNameObeysNetworkPolicy(t *testing.T) {
	// The resolver name has an allowed address and a denied address. The
	// policy check passes because one address is allowed, so the query must
	// not go to the denied one.
	var deniedHits, systemHits atomic.Int32
	denied := startDNSServer(t, "", nil, &deniedHits)
	_, port, err := net.SplitHostPort(denied)
	require.NoError(t, err)
	system := startDNSServer(t, "resolver.nuclei-test.", []string{"127.0.0.1", "127.0.0.2"}, &systemHits)
	useSystemResolver(t, system)

	options := testutils.DefaultOptions.Copy()
	options.SetExecutionID(t.Name())
	options.ExcludeTargets = []string{"127.0.0.1"}
	testutils.Init(options)
	t.Cleanup(func() { testutils.Cleanup(options) })
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "dns-resolver-policy",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Info}, Name: "test"},
	})

	for _, resolver := range []string{"resolver.nuclei-test:" + port, "tcp:resolver.nuclei-test:" + port} {
		t.Run(resolver, func(t *testing.T) {
			deniedHits.Store(0)
			request := &Request{
				RequestType: DNSRequestTypeHolder{DNSRequestType: TXT},
				Class:       "INET",
				Retries:     2,
				Name:        "{{FQDN}}",
				Resolvers:   []string{resolver},
			}
			require.NoError(t, request.Compile(executerOpts))

			msg := new(dns.Msg)
			msg.SetQuestion("example.com.", dns.TypeTXT)
			_, _ = request.dnsClient.Do(msg)
			require.Zero(t, deniedHits.Load(), "dns query reached a denied address")
		})
	}
}

func TestDNSResolverNameLookupStopsAtTimeout(t *testing.T) {
	// The system resolver never answers, so the lookup that pins the resolver
	// name must stop at the timeout.
	silent, err := net.ListenPacket("udp", "127.0.0.1:0")
	require.NoError(t, err)
	t.Cleanup(func() { _ = silent.Close() })
	useSystemResolver(t, silent.LocalAddr().String())

	start := time.Now()
	_, err = pinResolverHost(t.Name(), "silent.nuclei-test:53", "silent.nuclei-test", time.Second)
	require.Error(t, err)
	require.Less(t, time.Since(start), 4*time.Second, "the resolver lookup did not stop at the timeout")
}

package dns

import (
	"context"
	"math/rand"
	"net"

	"github.com/miekg/dns"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/dns/dnsclientpool"
	"github.com/projectdiscovery/retryabledns"
	sliceutil "github.com/projectdiscovery/utils/slice"
)

// traceNameServerPort is the port of the name servers that a trace queries.
var traceNameServerPort = "53"

// trace follows the delegation of host from the root servers in the same way
// as retryabledns.Client.Trace, but it skips name server addresses that the
// network policy denies. The name servers come from the answers, so the owner
// of a zone could otherwise send the queries of a trace to internal addresses.
func trace(executionID string, client *dnsclientpool.Client, host string, requestType uint16, maxRecursion int) (*retryabledns.TraceData, error) {
	var traceData retryabledns.TraceData
	host = dns.CanonicalName(host)
	servers := retryabledns.RootDNSServersIPv4
	seenNS := make(map[string]struct{})
	seenCName := make(map[string]int)
	for i := 1; i < maxRecursion; i++ {
		responses, err := client.QueryParallel(host, requestType, servers)
		if err != nil {
			return nil, err
		}
		for _, server := range servers {
			seenNS[server] = struct{}{}
		}
		if len(responses) == 0 {
			return &traceData, nil
		}
		for _, dnsData := range responses {
			if dnsData != nil && len(dnsData.Resolver) > 0 {
				traceData.DNSData = append(traceData.DNSData, dnsData)
			}
		}

		var nameServers []string
		var nextCname string
		for _, dnsData := range responses {
			if dnsData == nil {
				continue
			}
			for _, ns := range dnsData.NS {
				ips, err := net.DefaultResolver.LookupIP(context.Background(), "ip4", ns)
				if err != nil {
					continue
				}
				for _, ip := range ips {
					if !protocolstate.IsHostAllowed(executionID, ip.String()) {
						continue
					}
					nameServers = append(nameServers, net.JoinHostPort(ip.String(), traceNameServerPort))
				}
			}
			if nextCname == "" && len(dnsData.CNAME) > 0 {
				nextCname = dnsData.CNAME[0]
			}
		}
		nameServers = sliceutil.Dedupe(nameServers)
		if len(nameServers) == 0 {
			break
		}

		server := nameServers[rand.Intn(len(nameServers))] // #nosec G404
		if _, ok := seenNS[server]; ok && nextCname == "" {
			break
		}
		servers = []string{server}

		if nextCname != "" {
			seenCName[nextCname]++
			if seenCName[nextCname] > retryabledns.DefaultMaxPerCNAMEFollows {
				break
			}
			host = nextCname
		}
	}
	return &traceData, nil
}

