	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/retryabledns"
)

func serveTraceDNS(t *testing.T, address string, handler dns.HandlerFunc) string {
	t.Helper()
	pc, err := net.ListenPacket("udp", address)
	require.NoError(t, err)
	server := &dns.Server{PacketConn: pc, Handler: handler}
	go func() { _ = server.ActivateAndServe() }()
	t.Cleanup(func() { _ = server.Shutdown() })
	return pc.LocalAddr().String()
}

func TestDNSTraceObeysNetworkPolicy(t *testing.T) {
	// The zone of the traced name delegates to a name server on 127.0.0.1.
	// The trace must query it when the policy allows the address, so that the
	// test can see a trace that ignores the policy, and must skip it when the
	// policy denies the address.
	t.Run("allowed", func(t *testing.T) {
		require.NotZero(t, runTraceAgainstLoopbackNameServer(t, nil), "trace did not query the allowed name server")
	})
	t.Run("denied", func(t *testing.T) {
		require.Zero(t, runTraceAgainstLoopbackNameServer(t, []string{"127.0.0.1"}), "trace queried a denied name server")
	})
}

func runTraceAgainstLoopbackNameServer(t *testing.T, excludeTargets []string) int32 {
	t.Helper()
	var internalHits atomic.Int32
	internal := serveTraceDNS(t, "127.0.0.1:0", func(w dns.ResponseWriter, q *dns.Msg) {
		internalHits.Add(1)
		m := new(dns.Msg)
		m.SetReply(q)
		rr, _ := dns.NewRR(q.Question[0].Name + ` 0 IN TXT "internal"`)
		m.Answer = append(m.Answer, rr)
		_ = w.WriteMsg(m)
	})
	_, port, err := net.SplitHostPort(internal)
	require.NoError(t, err)
	previousPort := traceNameServerPort
	traceNameServerPort = port
	t.Cleanup(func() { traceNameServerPort = previousPort })

	// public stands in for the root servers, the scan resolvers and the system resolver
	public := serveTraceDNS(t, "127.0.0.1:0", func(w dns.ResponseWriter, q *dns.Msg) {
		m := new(dns.Msg)
		m.SetReply(q)
		question := q.Question[0]
		var rr dns.RR
		switch {
		case question.Name == "ns.nuclei-test." && question.Qtype == dns.TypeA:
			rr, _ = dns.NewRR("ns.nuclei-test. 0 IN A 127.0.0.1")
		case question.Name == "ns.nuclei-test.":
		case question.Name == "trace.nuclei-test.":
			rr, _ = dns.NewRR("trace.nuclei-test. 0 IN NS ns.nuclei-test.")
		default:
			rr, _ = dns.NewRR(question.Name + ` 0 IN TXT "public"`)
		}
		if rr != nil {
			m.Answer = append(m.Answer, rr)
		}
		_ = w.WriteMsg(m)
	})
	previousRoots := retryabledns.RootDNSServersIPv4
	retryabledns.RootDNSServersIPv4 = []string{public}
	t.Cleanup(func() { retryabledns.RootDNSServersIPv4 = previousRoots })
	previousResolver := net.DefaultResolver
	net.DefaultResolver = &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, _ string) (net.Conn, error) {
			var d net.Dialer
			return d.DialContext(ctx, "udp", public)
		},
	}
	t.Cleanup(func() { net.DefaultResolver = previousResolver })

	options := testutils.DefaultOptions.Copy()
	options.SetExecutionID(t.Name())
	options.ExcludeTargets = excludeTargets
	options.InternalResolversList = []string{public}
	testutils.Init(options)
	t.Cleanup(func() { testutils.Cleanup(options) })
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "dns-trace-policy",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Info}, Name: "test"},
	})

	request := &Request{
		RequestType: DNSRequestTypeHolder{DNSRequestType: TXT},
		Class:       "INET",
		Name:        "{{FQDN}}",
		// One retry keeps the client keyed by this test's resolvers, so a
		// client cached by an earlier run cannot point at a closed server.
		Retries:           1,
		Trace:             true,
		TraceMaxRecursion: 5,
	}
	require.NoError(t, request.Compile(executerOpts))

	var event output.InternalEvent
	input := contextargs.NewWithInput(context.Background(), "trace.nuclei-test")
	err = request.ExecuteWithResults(input, nil, nil, func(e *output.InternalWrappedEvent) {
		event = e.InternalEvent
	})
	require.NoError(t, err)
	require.Contains(t, event["trace"], "ns.nuclei-test", "trace did not query the root servers")
	return internalHits.Load()
}

// Package file implements the nuclei file protocol for local and remote SMB paths.
//
// Local paths use os.Open / directory walks as before. Remote targets use the
// shared smbsession stack (issue #6142 / #4707):
//
//	nuclei -t file-template.yaml -target '\\fs01\share\secret.txt'
//	nuclei -t file-template.yaml -target 'smb://user:pass@fs01/share/'
//
// Template auth (when not embedded in the URL):
//
//	file:
//	  - extensions: [all]
//	    smb-user: auditor
//	    smb-password: secret
//	    # smb-domain: CORP
//	    # smb-hash: <nthash>
//	    # smb-port: 445
package file

import (
	"path/filepath"
	"strings"

	"github.com/docker/go-units"
	"github.com/h2non/filetype"
	"github.com/pkg/errors"

	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
)

var (
	defaultMaxReadSize, _ = units.FromHumanSize("1Gb")
	chunkSize, _          = units.FromHumanSize("100Mb")
)

// Request contains a File matching mechanism for local disk operations.
type Request struct {
	// Operators for the current request go here.
	operators.Operators `yaml:",inline"`
	// description: |
	//   Extensions is the list of extensions or mime types to perform matching on.
	// examples:
	//   - value: '[]string{".txt", ".go", ".json"}'
	Extensions []string `yaml:"extensions,omitempty" json:"extensions,omitempty" jsonschema:"title=extensions to match,description=List of extensions to perform matching on"`
	// description: |
	//   DenyList is the list of file, directories, mime types or extensions to deny during matching.
	//
	//   By default, it contains some non-interesting extensions that are hardcoded
	//   in nuclei.
	// examples:
	//   - value: '[]string{".avi", ".mov", ".mp3"}'
	DenyList []string `yaml:"denylist,omitempty" json:"denylist,omitempty" jsonschema:"title=denylist, directories and extensions to deny match,description=List of files, directories and extensions to deny during matching"`

	// ID is the optional id of the request
	ID string `yaml:"id,omitempty" json:"id,omitempty" jsonschema:"title=id of the request,description=ID is the optional ID for the request"`

	// description: |
	//   MaxSize is the maximum size of the file to run request on.
	//
	//   By default, nuclei will process 1 GB of content and not go more than that.
	//   It can be set to much lower or higher depending on use.
	//   If set to "no" then all content will be processed
	// examples:
	//   - value: "\"5Mb\""
	MaxSize string `yaml:"max-size,omitempty" json:"max-size,omitempty" jsonschema:"title=max size data to run request on,description=Maximum size of the file to run request on"`
	maxSize int64

	// description: |
	//   elaborates archives
	Archive bool `yaml:"archive,omitempty" json:"archive,omitempty" jsonschema:"title=enable archives,description=Process compressed archives without unpacking"`

	// description: |
	//   enables mime types check
	MimeType bool `yaml:"mime-type,omitempty" json:"mime-type,omitempty" jsonschema:"title=enable filtering by mime-type,description=Filter files by mime-type"`

	CompiledOperators *operators.Operators `yaml:"-" json:"-"`

	// cache any variables that may be needed for operation.
	options             *protocols.ExecutorOptions
	mimeTypesChecks     []string
	extensions          map[string]struct{}
	denyList            map[string]struct{}
	denyMimeTypesChecks []string

	// description: |
	//   NoRecursive specifies whether to not do recursive checks if folders are provided.
	NoRecursive bool `yaml:"no-recursive,omitempty" json:"no-recursive,omitempty" jsonschema:"title=do not perform recursion,description=Specifies whether to not do recursive checks if folders are provided"`

	// description: |
	//   SMBUser authenticates to remote SMB shares when the file input is a UNC
	//   or smb:// path (issue #6142). Guest/anon: empty password.
	// examples:
	//   - value: "\"auditor\""
	SMBUser string `yaml:"smb-user,omitempty" json:"smb-user,omitempty" jsonschema:"title=SMB username,description=Username for SMB file targets"`
	// description: |
	//   SMBPassword is the password for SMB file targets.
	SMBPassword string `yaml:"smb-password,omitempty" json:"smb-password,omitempty" jsonschema:"title=SMB password,description=Password for SMB file targets"`
	// description: |
	//   SMBDomain is the optional NTLM domain / workgroup.
	SMBDomain string `yaml:"smb-domain,omitempty" json:"smb-domain,omitempty" jsonschema:"title=SMB domain,description=Domain for SMB authentication"`
	// description: |
	//   SMBHash enables pass-the-hash (overrides smb-password when set).
	SMBHash string `yaml:"smb-hash,omitempty" json:"smb-hash,omitempty" jsonschema:"title=SMB NT hash,description=NT hash for SMB pass-the-hash"`
	// description: |
	//   SMBPort overrides the default SMB port (445) for UNC targets.
	SMBPort int `yaml:"smb-port,omitempty" json:"smb-port,omitempty" jsonschema:"title=SMB port,description=TCP port for SMB (default 445)"`

	allExtensions bool
}

// RequestPartDefinitions contains a mapping of request part definitions and their
// description. Multiple definitions are separated by commas.
// Definitions not having a name (generated on runtime) are prefixed & suffixed by <>.
var RequestPartDefinitions = map[string]string{
	"template-id":       "ID of the template executed",
	"template-info":     "Info Block of the template executed",
	"template-path":     "Path of the template executed",
	"matched":           "Matched is the input which was matched upon",
	"path":              "Path is the path of file on local filesystem",
	"type":              "Type is the type of request made",
	"raw,body,all,data": "Raw contains the raw file contents",
}

// defaultDenylist contains common extensions to exclude
var defaultDenylist = []string{".3g2", ".3gp", ".arj", ".avi", ".axd", ".bmp", ".css", ".csv", ".deb", ".dll", ".doc", ".drv", ".eot", ".exe", ".flv", ".gif", ".gifv", ".h264", ".ico", ".iso", ".jar", ".jpeg", ".jpg", ".lock", ".m4a", ".m4v", ".map", ".mkv", ".mov", ".mp3", ".mp4", ".mpeg", ".mpg", ".msi", ".ogg", ".ogm", ".ogv", ".otf", ".pdf", ".pkg", ".png", ".ppt", ".psd", ".rm", ".rpm", ".svg", ".swf", ".sys", ".tif", ".tiff", ".ttf", ".vob", ".wav", ".webm", ".wmv", ".woff", ".woff2", ".xcf", ".xls", ".xlsx"}

// defaultArchiveDenyList contains common archive extensions to exclude
var defaultArchiveDenyList = []string{".7z", ".apk", ".gz", ".rar", ".tar.gz", ".tar", ".zip"}

// GetID returns the unique ID of the request if any.
func (request *Request) GetID() string {
	return request.ID
}

// Compile compiles the protocol request for further execution.
func (request *Request) Compile(options *protocols.ExecutorOptions) error {
	// if there are no matchers/extractors, we trigger an error as no operation would be performed on the template
	if request.IsEmpty() {
		return errors.New("empty operators")
	}
	compiled := &request.Operators
	compiled.ExcludeMatchers = options.ExcludeMatchers
	compiled.TemplateID = options.TemplateID
	if err := compiled.Compile(); err != nil {
		return errors.Wrap(err, "could not compile operators")
	}
	// llm operators only evaluate once they hold the scan's client; without
	// it every llm path returns a negative result instead of an error.
	protocols.BindLLMOperators(compiled, options)
	request.CompiledOperators = compiled

	// By default, use default max size if not defined
	switch {
	case strings.EqualFold(request.MaxSize, "no"):
		request.maxSize = -1
	case request.MaxSize != "":
		maxSize, err := units.FromHumanSize(request.MaxSize)
		if err != nil {
			return errors.Wrap(err, "could not parse max-size")
		}
		request.maxSize = maxSize
	default:
		request.maxSize = defaultMaxReadSize
	}

	request.options = options

	request.extensions = make(map[string]struct{})
	request.denyList = make(map[string]struct{})

	for _, extension := range request.Extensions {
		switch {
		case extension == "all":
			request.allExtensions = true
		case request.MimeType && filetype.IsMIMESupported(extension):
			continue
		default:
			if !strings.HasPrefix(extension, ".") {
				extension = "." + extension
			}
			request.extensions[extension] = struct{}{}
		}
	}
	request.mimeTypesChecks = extractMimeTypes(request.Extensions)

	// process default denylist (extensions)
	var denyList []string
	if !request.Archive {
		denyList = append(defaultDenylist, defaultArchiveDenyList...)
	} else {
		denyList = defaultDenylist
	}
	for _, excludeItem := range denyList {
		if !strings.HasPrefix(excludeItem, ".") {
			excludeItem = "." + excludeItem
		}
		request.denyList[excludeItem] = struct{}{}
	}
	for _, excludeItem := range request.DenyList {
		request.denyList[excludeItem] = struct{}{}
		// also add a cleaned version as the exclusion path can be dirty (eg. /a/b/c, /a/b/c/, a///b///c/../d)
		request.denyList[filepath.Clean(excludeItem)] = struct{}{}
	}
	request.denyMimeTypesChecks = extractMimeTypes(request.DenyList)
	return nil
}

func matchAnyMimeTypes(data []byte, mimeTypes []string) bool {
	// filetype.Is expects a file extension, not a mime type, so detect the type
	// once and compare its mime value against the configured entries
	kind, err := filetype.Match(data)
	if err != nil || kind == filetype.Unknown {
		return false
	}
	for _, mimeType := range mimeTypes {
		if kind.MIME.Value == mimeType {
			return true
		}
	}
	return false
}

func extractMimeTypes(m []string) []string {
	var mimeTypes []string
	for _, mm := range m {
		if !filetype.IsMIMESupported(mm) {
			continue
		}
		mimeTypes = append(mimeTypes, mm)
	}
	return mimeTypes
}

// Requests returns the total number of requests the YAML rule will perform
func (request *Request) Requests() int {
	return 0
}

// UpdateOptions replaces this request's options with a new copy
func (r *Request) UpdateOptions(opts *protocols.ExecutorOptions) {
	r.Operators = protocols.CloneOperators(r.Operators)
	r.CompiledOperators = nil
	if r.options == nil {
		if opts != nil {
			r.options = opts.Copy()
		}
		return
	}
	r.options = r.options.Copy()
	r.options.ApplyNewEngineOptions(opts)
}

package file

import (
	"context"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
	fileutil "github.com/projectdiscovery/utils/file"
	folderutil "github.com/projectdiscovery/utils/folder"
)

// getInputPaths parses the specified input paths and returns a compiled
// list of finished absolute paths to the files evaluating any allowlist, denylist,
// glob, file or folders, etc.
func (request *Request) getInputPaths(ctx context.Context, target string, callback func(string) error) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	processed := make(map[string]struct{})

	// Remote SMB targets (UNC / smb://) — issue #6142 bridge.
	if IsSMBPath(target) {
		return request.enumerateSMBInputs(ctx, target, func(path string) error {
			if _, ok := processed[path]; ok {
				return nil
			}
			processed[path] = struct{}{}
			return callInputPath(ctx, callback, path)
		})
	}

	// Template input includes a wildcard
	if strings.Contains(target, "*") && !request.NoRecursive {
		if err := request.findGlobPathMatches(ctx, target, processed, callback); err != nil {
			return errors.Wrap(err, "could not find glob matches")
		}
		return nil
	}

	// Template input is either a file or a directory
	file, err := request.findFileMatches(ctx, target, processed, callback)
	if err != nil {
		return errors.Wrap(err, "could not find file")
	}
	if file {
		return nil
	}
	if request.NoRecursive {
		return nil // we don't process dirs in no-recursive mode
	}
	// Recursively walk down the Templates directory and run all
	// the template file checks
	if err := request.findDirectoryMatches(ctx, target, processed, callback); err != nil {
		return errors.Wrap(err, "could not find directory matches")
	}
	return nil
}

// findGlobPathMatches returns the matched files from a glob path
func (request *Request) findGlobPathMatches(ctx context.Context, absPath string, processed map[string]struct{}, callback func(string) error) error {
	matches, err := filepath.Glob(absPath)
	if err != nil {
		return errors.Errorf("wildcard found, but unable to glob: %s\n", err)
	}
	for _, match := range matches {
		if !request.validatePath(absPath, match, false) {
			continue
		}
		if _, ok := processed[match]; !ok {
			processed[match] = struct{}{}
			if err := callInputPath(ctx, callback, match); err != nil {
				return err
			}
		}
	}
	return nil
}

// findFileMatches finds if a path is an absolute file. If the path
// is a file, it returns true otherwise false with no errors.
func (request *Request) findFileMatches(ctx context.Context, absPath string, processed map[string]struct{}, callback func(string) error) (bool, error) {
	info, err := os.Stat(absPath)
	if err != nil {
		return false, err
	}
	if !info.Mode().IsRegular() {
		return false, nil
	}
	if _, ok := processed[absPath]; !ok {
		if !request.validatePath(absPath, absPath, false) {
			return false, nil
		}
		processed[absPath] = struct{}{}
		if err := callInputPath(ctx, callback, absPath); err != nil {
			return true, err
		}
	}
	return true, nil
}

// findDirectoryMatches finds matches for templates from a directory
func (request *Request) findDirectoryMatches(ctx context.Context, absPath string, processed map[string]struct{}, callback func(string) error) error {
	err := filepath.WalkDir(
		absPath,
		func(path string, d fs.DirEntry, walkErr error) error {
			if err := ctx.Err(); err != nil {
				return err
			}
			// continue on errors
			if walkErr != nil {
				return nil
			}
			if d.IsDir() {
				return nil
			}
			if !request.validatePath(absPath, path, false) {
				return nil
			}
			if _, ok := processed[path]; !ok {
				processed[path] = struct{}{}
				return callInputPath(ctx, callback, path)
			}
			return nil
		},
	)
	return err
}

func callInputPath(ctx context.Context, callback func(string) error, path string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if callback == nil {
		return nil
	}
	return callback(path)
}

// validatePath validates a file path for blacklist and whitelist options
func (request *Request) validatePath(absPath, item string, inArchive bool) bool {
	extension := filepath.Ext(item)
	// extension check
	if len(request.extensions) > 0 {
		if _, ok := request.extensions[extension]; ok {
			return true
		} else if !request.allExtensions {
			return false
		}
	}

	var (
		fileExists bool
		dataChunk  []byte
	)
	if !inArchive && request.MimeType {
		// mime type check
		// read first bytes to infer runtime type
		fileExists = fileutil.FileExists(item)
		if fileExists {
			dataChunk, _ = readChunk(item)
			if len(request.mimeTypesChecks) > 0 && matchAnyMimeTypes(dataChunk, request.mimeTypesChecks) {
				return true
			}
		}
	}

	if matchingRule, ok := request.isInDenyList(absPath, item); ok {
		gologger.Verbose().Msgf("Ignoring path %s due to denylist item %s\n", item, matchingRule)
		return false
	}

	// denied mime type checks
	if !inArchive && request.MimeType && fileExists {
		if len(request.denyMimeTypesChecks) > 0 && matchAnyMimeTypes(dataChunk, request.denyMimeTypesChecks) {
			return false
		}
	}

	return true
}

func (request *Request) isInDenyList(absPath, item string) (string, bool) {
	extension := filepath.Ext(item)
	// check for possible deny rules
	// - extension is in deny list
	if _, ok := request.denyList[extension]; ok {
		return extension, true
	}

	// - full path is in deny list
	if _, ok := request.denyList[item]; ok {
		return item, true
	}

	// file is in a forbidden subdirectory
	filename := filepath.Base(item)
	fullPathWithoutFilename := strings.TrimSuffix(item, filename)
	relativePathWithFilename := strings.TrimPrefix(item, absPath)
	relativePath := strings.TrimSuffix(relativePathWithFilename, filename)

	// - filename is in deny list
	if _, ok := request.denyList[filename]; ok {
		return filename, true
	}

	// - relative path is in deny list
	if _, ok := request.denyList[relativePath]; ok {
		return relativePath, true
	}

	// relative path + filename are in the forbidden list
	if _, ok := request.denyList[relativePathWithFilename]; ok {
		return relativePathWithFilename, true
	}

	// root path + relative path are in the forbidden list
	if _, ok := request.denyList[fullPathWithoutFilename]; ok {
		return fullPathWithoutFilename, true
	}

	// check any progressive combined part of the relative and absolute path with filename for matches within rules prefixes
	if pathTreeItem, ok := request.isAnyChunkInDenyList(relativePath, false); ok {
		return pathTreeItem, true
	}
	if pathTreeItem, ok := request.isAnyChunkInDenyList(item, true); ok {
		return pathTreeItem, true
	}

	return "", false
}

func readChunk(fileName string) ([]byte, error) {
	r, err := os.Open(fileName)
	if err != nil {
		return nil, err
	}

	defer func() {
		_ = r.Close()
	}()

	var buff [1024]byte
	// a file shorter than the buffer is not an error here: ReadFull has already
	// copied its bytes, and magic-number detection only needs the first few
	n, err := io.ReadFull(r, buff[:])
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		return nil, err
	}
	return buff[:n], nil
}

func (request *Request) isAnyChunkInDenyList(path string, splitWithUtils bool) (string, bool) {
	var paths []string

	if splitWithUtils {
		pathInfo, _ := folderutil.NewPathInfo(path)
		paths, _ = pathInfo.Paths()
	} else {
		pathTree := strings.Split(path, string(os.PathSeparator))
		for i := range pathTree {
			paths = append(paths, filepath.Join(pathTree[:i]...))
		}
	}
	for _, pathTreeItem := range paths {
		if _, ok := request.denyList[pathTreeItem]; ok {
			return pathTreeItem, true
		}
	}

	return "", false
}

package file

import (
	"context"
	"fmt"
	"os"
