)

func TestIsSMBPath(t *testing.T) {
	require.True(t, IsSMBPath(`\\fs01\backup\a.txt`))
	require.True(t, IsSMBPath(`//fs01/backup/a.txt`))
	require.True(t, IsSMBPath(`smb://fs01/backup/a.txt`))
	require.True(t, IsSMBPath(`SMB://user:pass@fs01/share/`))
	require.False(t, IsSMBPath(`/tmp/a.txt`))
	require.False(t, IsSMBPath(`C:\Windows\a.txt`))
	require.False(t, IsSMBPath(``))
}

func TestParseSMBTargetUNC(t *testing.T) {
	got, err := ParseSMBTarget(`\\fs01\backup\docs\creds.txt`)
	require.NoError(t, err)
	require.Equal(t, "fs01", got.Host)
	require.Equal(t, "backup", got.Share)
	require.Equal(t, "docs/creds.txt", got.Path)
	require.Equal(t, 445, got.Port)
	require.Equal(t, `\\fs01\backup\docs\creds.txt`, got.Display())
}

func TestParseSMBTargetUNCShareRoot(t *testing.T) {
	got, err := ParseSMBTarget(`\\fs01\backup`)
	require.NoError(t, err)
	require.Equal(t, "backup", got.Share)
	require.Equal(t, ".", got.Path)
	require.Equal(t, `\\fs01\backup`, got.Display())
}

func TestParseSMBTargetURL(t *testing.T) {
	got, err := ParseSMBTarget(`smb://auditor:secret@fs01:1445/backup/a.txt`)
	require.NoError(t, err)
	require.Equal(t, "fs01", got.Host)
	require.Equal(t, 1445, got.Port)
	require.Equal(t, "backup", got.Share)
	require.Equal(t, "a.txt", got.Path)
	require.Equal(t, "auditor", got.User)
	require.Equal(t, "secret", got.Password)
}

func TestParseSMBTargetURLWithDomain(t *testing.T) {
	got, err := ParseSMBTarget(`smb://CORP;alice:p@fs01/share/x`)
	require.NoError(t, err)
	require.Equal(t, "CORP", got.Domain)
	require.Equal(t, "alice", got.User)
	require.Equal(t, "p", got.Password)
	require.Equal(t, "share", got.Share)
	require.Equal(t, "x", got.Path)
}

func TestParseSMBTargetRejectsEscape(t *testing.T) {
	_, err := ParseSMBTarget(`\\fs01\backup\..\..\Windows\win.ini`)
	require.Error(t, err)
}

func TestParseSMBTargetRejectsBadShare(t *testing.T) {
	_, err := ParseSMBTarget(`smb://fs01/bad/share/x`)
	// share is "bad", path is "share/x" — valid
	require.NoError(t, err)
	_, err = ParseSMBTarget(`\\fs01\`)
	require.Error(t, err)
}

func TestResolveSMBCredsPreferURL(t *testing.T) {
	req := &Request{SMBUser: "tmpl", SMBPassword: "tmpl-pass", SMBDomain: "TMPL"}
	target := &SMBTarget{User: "urluser", Password: "urlpass", Domain: "URLDOM"}
	creds := req.resolveSMBCreds(target)
	require.Equal(t, "urluser", creds.User)
	require.Equal(t, "urlpass", creds.Password)
	require.Equal(t, "URLDOM", creds.Domain)
}

func TestResolveSMBCredsParseIdentity(t *testing.T) {
	req := &Request{SMBUser: `CORP\bob`, SMBPassword: "x"}
	creds := req.resolveSMBCreds(&SMBTarget{})
	require.Equal(t, "CORP", creds.Domain)
	require.Equal(t, "bob", creds.User)
}

func TestIsDirectorySMBTarget(t *testing.T) {
	require.True(t, isDirectorySMBTarget(`\\fs01\backup`))
	require.True(t, isDirectorySMBTarget(`smb://fs01/backup/`))
	require.True(t, isDirectorySMBTarget(`\\fs01\backup\docs\`))
	require.False(t, isDirectorySMBTarget(`\\fs01\backup\a.txt`))
}

package engine

import (
	"strings"

	"github.com/invopop/jsonschema"
)

// Action is an action taken by the browser to reach a navigation
//
// Each step that the browser executes is an action. Most navigations
// usually start from the ActionLoadURL event, and further navigations
// are discovered on the found page. We also keep track and only
// scrape new navigation from pages we haven't crawled yet.
type Action struct {
	// description:
	//   Args contain arguments for the headless action.
	//
	//   Per action arguments are described in detail [here](https://nuclei.projectdiscovery.io/templating-guide/protocols/headless/).
	Data map[string]string `yaml:"args,omitempty" json:"args,omitempty" jsonschema:"title=arguments for headless action,description=Args contain arguments for the headless action"`
	// description: |
	//   Name is the name assigned to the headless action.
	//
	//   This can be used to execute code, for instance in browser
	//   DOM using script action, and get the result in a variable
	//   which can be matched upon by nuclei. An Example template [here](https://github.com/projectdiscovery/nuclei-templates/blob/main/headless/prototype-pollution-check.yaml).
	Name string `yaml:"name,omitempty" json:"name,omitempty" jsonschema:"title=name for headless action,description=Name is the name assigned to the headless action"`
	// description: |
	//   Description is the optional description of the headless action
	Description string `yaml:"description,omitempty" json:"description,omitempty" jsonschema:"title=description for headless action,description=Description of the headless action"`
	// description: |
	//   Action is the type of the action to perform.
	ActionType ActionTypeHolder `yaml:"action" json:"action" jsonschema:"title=action to perform,description=Type of actions to perform,enum=navigate,enum=script,enum=click,enum=rightclick,enum=text,enum=screenshot,enum=time,enum=select,enum=files,enum=waitload,enum=getresource,enum=extract,enum=setmethod,enum=addheader,enum=setheader,enum=deleteheader,enum=setbody,enum=waitevent,enum=keyboard,enum=debug,enum=sleep"`
}

func (a Action) JSONSchemaExtend(schema *jsonschema.Schema) {
	argsSchema, ok := schema.Properties.Get("args")
	if !ok {
		return
	}
	argsSchema.PatternProperties = map[string]*jsonschema.Schema{
		".*": {
			OneOf: []*jsonschema.Schema{
				{
					Type: "string",
				},
				{
					Type: "integer",
				},
				{
					Type: "boolean",
				},
			},
		},
	}
	argsSchema.Ref = ""
}

// String returns the string representation of an action
func (a *Action) String() string {
	builder := &strings.Builder{}
	builder.WriteString(a.ActionType.String())
	if a.Name != "" {
		builder.WriteString(" Name:")
		builder.WriteString(a.Name)
	}
	builder.WriteString(" ")
	for k, v := range a.Data {
		builder.WriteString(k)
		builder.WriteString(":")
		builder.WriteString(v)
		builder.WriteString(",")
	}
	return strings.TrimSuffix(builder.String(), ",")
}

// GetArg returns an arg for a name
func (a *Action) GetArg(name string) string {
	v, ok := a.Data[name]
	if !ok {
		return ""
	}
	return v
}

package engine

import (
	"errors"
	"strings"

	"github.com/invopop/jsonschema"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

// ActionType defines the action type for a browser action
type ActionType int8

// ActionData stores the action output data
type ActionData = mapsutil.Map[string, any]

// Types to be executed by the user.
// name:ActionType
const (
	// ActionNavigate performs a navigation to the specified URL
	// name:navigate
	ActionNavigate ActionType = iota + 1
	// ActionScript executes a JS snippet on the page.
	// name:script
	ActionScript
	// ActionClick performs the left-click action on an Element.
	// name:click
	ActionClick
	// ActionRightClick performs the right-click action on an Element.
	// name:rightclick
	ActionRightClick
	// ActionTextInput performs an action for a text input
	// name:text
	ActionTextInput
	// ActionScreenshot performs the screenshot action writing to a file.
	// name:screenshot
	ActionScreenshot
	// ActionTimeInput performs an action on a time input.
	// name:time
	ActionTimeInput
	// ActionSelectInput performs an action on a select input.
	// name:select
	ActionSelectInput
	// ActionFilesInput performs an action on a file input.
	// name:files
	ActionFilesInput
	// ActionWaitDOM waits for the HTML document has been completely loaded & parsed.
	// name:waitdom
	ActionWaitDOM
	// ActionWaitFCP waits for the first piece of content (text, image, etc.) is painted on the screen.
	// name:waitfcp
	ActionWaitFCP
	// ActionWaitFMP waits for page has rendered enough meaningful content to be useful to the user.
	// name:waitfmp
	ActionWaitFMP
	// ActionWaitIdle waits for the network is completely idle (no ongoing network requests).
	// name:waitidle
	ActionWaitIdle
	// ActionWaitLoad waits for the page and all its resources (like stylesheets and images) have finished loading.
	// name:waitload
	ActionWaitLoad
	// ActionWaitStable waits until the page is stable.
	// name:waitstable
	ActionWaitStable
	// ActionGetResource performs a get resource action on an element
	// name:getresource
	ActionGetResource
	// ActionExtract performs an extraction on an element
	// name:extract
	ActionExtract
	// ActionSetMethod sets the request method
	// name:setmethod
	ActionSetMethod
	// ActionAddHeader adds a header to the request
	// name:addheader
	ActionAddHeader
	// ActionSetHeader sets a header in the request
	// name:setheader
	ActionSetHeader
	// ActionDeleteHeader deletes a header from the request
	// name:deleteheader
	ActionDeleteHeader
	// ActionSetBody sets the value of the request body
	// name:setbody
	ActionSetBody
	// ActionWaitEvent waits for a specific event.
	// name:waitevent
	ActionWaitEvent
	// ActionWaitDialog waits for JavaScript dialog (alert, confirm, prompt, or onbeforeunload).
	// name:dialog
	ActionWaitDialog
	// ActionKeyboard performs a keyboard action event on a page.
	// name:keyboard
	ActionKeyboard
	// ActionDebug debug slows down headless and adds a sleep to each page.
	// name:debug
	ActionDebug
	// ActionSleep executes a sleep for a specified duration
	// name:sleep
	ActionSleep
	// ActionWaitVisible waits until an element appears.
	// name:waitvisible
	ActionWaitVisible
	// limit
	limit
)

// ActionStringToAction converts an action from string to internal representation
var ActionStringToAction = map[string]ActionType{
	"navigate":     ActionNavigate,
	"script":       ActionScript,
	"click":        ActionClick,
	"rightclick":   ActionRightClick,
	"text":         ActionTextInput,
	"screenshot":   ActionScreenshot,
	"time":         ActionTimeInput,
	"select":       ActionSelectInput,
	"files":        ActionFilesInput,
	"waitdom":      ActionWaitDOM,
	"waitfcp":      ActionWaitFCP,
	"waitfmp":      ActionWaitFMP,
	"waitidle":     ActionWaitIdle,
	"waitload":     ActionWaitLoad,
	"waitstable":   ActionWaitStable,
	"getresource":  ActionGetResource,
	"extract":      ActionExtract,
	"setmethod":    ActionSetMethod,
	"addheader":    ActionAddHeader,
	"setheader":    ActionSetHeader,
	"deleteheader": ActionDeleteHeader,
	"setbody":      ActionSetBody,
	"waitevent":    ActionWaitEvent,
	"waitdialog":   ActionWaitDialog,
	"keyboard":     ActionKeyboard,
	"debug":        ActionDebug,
	"sleep":        ActionSleep,
	"waitvisible":  ActionWaitVisible,
}

// ActionToActionString converts an action from  internal representation to string
var ActionToActionString = map[ActionType]string{
	ActionNavigate:     "navigate",
	ActionScript:       "script",
	ActionClick:        "click",
	ActionRightClick:   "rightclick",
	ActionTextInput:    "text",
	ActionScreenshot:   "screenshot",
	ActionTimeInput:    "time",
	ActionSelectInput:  "select",
	ActionFilesInput:   "files",
	ActionWaitDOM:      "waitdom",
	ActionWaitFCP:      "waitfcp",
	ActionWaitFMP:      "waitfmp",
	ActionWaitIdle:     "waitidle",
	ActionWaitLoad:     "waitload",
	ActionWaitStable:   "waitstable",
	ActionGetResource:  "getresource",
	ActionExtract:      "extract",
	ActionSetMethod:    "setmethod",
	ActionAddHeader:    "addheader",
	ActionSetHeader:    "setheader",
	ActionDeleteHeader: "deleteheader",
	ActionSetBody:      "setbody",
