import (
	"encoding/base64"

	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/proto"
)

// NewHijack create hijack from page.
func NewHijack(page *rod.Page) *Hijack {
	return &Hijack{
		page:    page,
		disable: &proto.FetchDisable{},
	}
}

// HijackHandler type
type HijackHandler = func(e *proto.FetchRequestPaused) error

// Hijack is a hijack handler
type Hijack struct {
	page    *rod.Page
	enable  *proto.FetchEnable
	disable *proto.FetchDisable
	cancel  func()
}

// SetPattern set pattern directly
func (h *Hijack) SetPattern(pattern *proto.FetchRequestPattern) {
	h.enable = &proto.FetchEnable{
		Patterns: []*proto.FetchRequestPattern{pattern},
	}
}

// Start hijack.
func (h *Hijack) Start(handler HijackHandler) func() error {
	if h.enable == nil {
		panic("hijack pattern not set")
	}

	p, cancel := h.page.WithCancel()
	h.cancel = cancel

	err := h.enable.Call(p)
	if err != nil {
		return func() error { return err }
	}

	wait := p.EachEvent(func(e *proto.FetchRequestPaused) {
		if handler != nil {
			err = handler(e)
		}
	})

	return func() error {
		wait()
		return err
	}
}

// Stop
func (h *Hijack) Stop() error {
	if h.cancel != nil {
		h.cancel()
	}
	return h.disable.Call(h.page)
}

// FetchGetResponseBody get request body.
func FetchGetResponseBody(page *rod.Page, e *proto.FetchRequestPaused) ([]byte, error) {
	m := proto.FetchGetResponseBody{
		RequestID: e.RequestID,
	}
	r, err := m.Call(page)
	if err != nil {
		return nil, err
	}

	if !r.Base64Encoded {
		return []byte(r.Body), nil
	}

	bs, err := base64.StdEncoding.DecodeString(r.Body)
	if err != nil {
		return nil, err
	}
	return bs, nil
}

// FetchContinueRequest continue request
func FetchContinueRequest(page *rod.Page, e *proto.FetchRequestPaused) error {
	m := proto.FetchContinueRequest{
		RequestID: e.RequestID,
	}
	return m.Call(page)
}

package engine

import (
	"context"
	"crypto/tls"
	"fmt"
	"net"
	"net/http"
	"net/http/cookiejar"
	"net/url"
	"time"

	"golang.org/x/net/http2"
	"golang.org/x/net/proxy"

	"github.com/projectdiscovery/fastdialer/fastdialer/ja3/impersonate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// newHttpClient creates a new http client for headless communication with a timeout
func newHttpClient(options *types.Options) (*http.Client, error) {
	dialers := protocolstate.GetDialersWithId(options.ExecutionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", options.ExecutionId)
	}
	// Set the base TLS configuration definition
	tlsConfig := &tls.Config{
		Renegotiation:      tls.RenegotiateOnceAsClient,
		InsecureSkipVerify: true,
		MinVersion:         tls.VersionTLS10,
		ClientSessionCache: tls.NewLRUClientSessionCache(1024),
	}

	if options.SNI != "" {
		tlsConfig.ServerName = options.SNI
	}

	// Add the client certificate authentication to the request if it's configured
	var err error
	tlsConfig, err = utils.AddConfiguredClientCertToRequest(tlsConfig, options)
	if err != nil {
		return nil, err
	}

	transport := &http.Transport{
		ForceAttemptHTTP2: options.ForceAttemptHTTP2,
		DialContext:       dialers.Fastdialer.Dial,
		DialTLSContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			if options.TlsImpersonate {
				return dialers.Fastdialer.DialTLSWithConfigImpersonate(ctx, network, addr, tlsConfig, impersonate.Random, nil)
			}
			if options.HasClientCertificates() || options.ForceAttemptHTTP2 {
				return dialers.Fastdialer.DialTLSWithConfig(ctx, network, addr, tlsConfig)
			}
			return dialers.Fastdialer.DialTLS(ctx, network, addr)
		},
		MaxIdleConns:        500,
		MaxIdleConnsPerHost: 500,
		MaxConnsPerHost:     500,
		TLSClientConfig:     tlsConfig,
	}
	if options.AliveHttpProxy != "" {
		if proxyURL, err := url.Parse(options.AliveHttpProxy); err == nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	} else if options.AliveSocksProxy != "" {
		socksURL, proxyErr := url.Parse(options.AliveSocksProxy)
		if proxyErr != nil {
			return nil, proxyErr
		}
		dialer, err := proxy.FromURL(socksURL, proxy.Direct)
		if err != nil {
			return nil, err
		}

		dc := dialer.(interface {
			DialContext(ctx context.Context, network, addr string) (net.Conn, error)
		})
		transport.DialContext = dc.DialContext
	}

	var roundTripper http.RoundTripper = transport

	// TLS impersonation via utls advertises h2 in ALPN to mimic a real browser.
	// Since utls returns *utls.UConn (not *tls.Conn), Go's http.Transport can't
	// detect the negotiated protocol and tries HTTP/1.x on an h2 connection,
	// causing "malformed HTTP response" errors. We use http2.Transport directly
	// with utls dialing to properly handle h2 connections (see #6360).
	if options.TlsImpersonate {
		// utls conns are not *tls.Conn, so http.Transport speaks HTTP/1 on an h2 session.
		// http2.Transport is deprecated in x/net 0.59, and it is still the dial that keeps h2. See #6360.
		roundTripper = &http2.Transport{ //nolint:staticcheck // SA1019
			DialTLSContext: func(ctx context.Context, network, addr string, _ *tls.Config) (net.Conn, error) { //nolint:staticcheck // SA1019
				return dialers.Fastdialer.DialTLSWithConfigImpersonate(ctx, network, addr, tlsConfig, impersonate.Random, nil)
			},
			TLSClientConfig:    tlsConfig, //nolint:staticcheck // SA1019
			AllowHTTP:          false,     //nolint:staticcheck // SA1019
			DisableCompression: false,     //nolint:staticcheck // SA1019
		}
	}

	jar, _ := cookiejar.New(nil)

	httpclient := &http.Client{
		Transport: roundTripper,
		Timeout:   time.Duration(options.Timeout*3) * time.Second,
		Jar:       jar,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// the browser should follow redirects not us
			return http.ErrUseLastResponse
		},
	}

	return httpclient, nil
}

package engine

import (
	"context"
	"errors"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/interactsh"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/render"
	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/utils"
)

// Instance is an isolated browser instance opened for doing operations with it.
type Instance struct {
	browser *Browser
	engine  *rod.Browser

	// redundant due to dependency cycle
	interactsh render.URLSource
	requestLog map[string]string // contains actual request that was sent
}

const browserCleanupTimeout = 5 * time.Second

// NewInstance creates a new instance for the current browser.
//
// The login process is repeated only once for a browser, and the created
// isolated browser instance is used for entire navigation one by one.
//
// Users can also choose to run the login->actions process again
// which uses a new incognito browser instance to run actions.
func (b *Browser) NewInstance() (*Instance, error) {
	return b.newInstanceBrowser(b.engine)
}

// NewInstanceWithContext bounds browser-context creation and all subsequent instance calls.
func (b *Browser) NewInstanceWithContext(ctx context.Context, timeout time.Duration) (*Instance, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := ctx.Err(); err != nil {
		return nil, context.Cause(ctx)
	}

	if timeout <= 0 {
		timeout = browserCleanupTimeout
	}
	creationCtx, cancelCreation := context.WithTimeout(b.engine.GetContext(), timeout)
	type result struct {
		instance *Instance
		err      error
	}
	resultCh := make(chan result, 1)
	go func() {
		instance, err := b.newInstanceBrowser(b.engine.Context(creationCtx))
		resultCh <- result{instance: instance, err: err}
	}()

	cleanup := func(instance *Instance) {
		if instance == nil {
			return
		}
		if err := instance.Close(); err != nil {
			gologger.Warning().Msgf("Could not close canceled browser instance: %s", err)
		}
	}

	select {
	case created := <-resultCh:
		cancelCreation()
		if created.err != nil {
			return nil, created.err
		}
		if err := ctx.Err(); err != nil {
			go cleanup(created.instance)
			return nil, context.Cause(ctx)
		}
		created.instance.engine = created.instance.engine.Context(ctx)
		return created.instance, nil
	case <-ctx.Done():
		go func() {
			created := <-resultCh
			cancelCreation()
			if created.err == nil {
				cleanup(created.instance)
			}
		}()
		return nil, context.Cause(ctx)
	}
}

func (b *Browser) newInstanceBrowser(engine *rod.Browser) (*Instance, error) {
	browser, err := engine.Incognito()
	if err != nil {
		return nil, err
	}

	// We use a custom sleeper that sleeps from 100ms to 500 ms waiting
	// for an interaction. Used throughout rod for clicking, etc.
	browser = browser.Sleeper(func() utils.Sleeper { return maxBackoffSleeper(10) })
	return &Instance{browser: b, engine: browser, requestLog: map[string]string{}}, nil
}

// returns a map of [template-defined-urls] -> [actual-request-sent]
// Note: this does not include CORS or other requests while rendering that were not explicitly
// specified in template
func (i *Instance) GetRequestLog() map[string]string {
	return i.requestLog
}

// Close closes all the tabs and pages for a browser instance
func (i *Instance) Close() error {
	ctx, cancel := context.WithTimeout(context.Background(), browserCleanupTimeout)
	defer cancel()
	return i.close(ctx)
}

// CloseWithPage closes a page and its isolated browser context within one cleanup deadline.
func (i *Instance) CloseWithPage(page *Page) error {
	ctx, cancel := context.WithTimeout(context.Background(), browserCleanupTimeout)
	defer cancel()
	if page != nil {
		page.close(ctx)
	}
	return i.close(ctx)
}

func (i *Instance) close(ctx context.Context) error {
	return i.engine.Context(ctx).Close()
}

// SetInteractsh client
func (i *Instance) SetInteractsh(interactsh interactsh.IClient) {
	i.interactsh = interactsh
}

// maxBackoffSleeper is a backoff sleeper respecting max backoff values
func maxBackoffSleeper(max int) utils.Sleeper {
	count := 0
	backoffSleeper := utils.BackoffSleeper(100*time.Millisecond, 500*time.Millisecond, nil)

	return func(ctx context.Context) error {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if count == max {
			return errors.New("max sleep count")
		}
		count++
		return backoffSleeper(ctx)
	}
}

package engine

import (
	"context"
	"testing"
	"time"

	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/cdp"
	"github.com/projectdiscovery/rod/lib/proto"
	"github.com/stretchr/testify/require"
)

type cleanupCDPClient struct {
	events      chan *cdp.Event
	contextErrs chan error
}

type lateCreateCDPClient struct {
	events   chan *cdp.Event
	disposed chan struct{}
	delay    time.Duration
}

func (c *lateCreateCDPClient) Event() <-chan *cdp.Event {
	return c.events
}

func (c *lateCreateCDPClient) Call(_ context.Context, _ string, method string, _ interface{}) ([]byte, error) {
	switch method {
	case "Target.createBrowserContext":
		time.Sleep(c.delay)
		return []byte(`{"browserContextId":"context-id"}`), nil
	case "Target.disposeBrowserContext":
		select {
		case c.disposed <- struct{}{}:
		default:
		}
	}
	return []byte("{}"), nil
}

func (c *cleanupCDPClient) Event() <-chan *cdp.Event {
	return c.events
}

func (c *cleanupCDPClient) Call(ctx context.Context, _ string, method string, _ interface{}) ([]byte, error) {
	if method == "Target.disposeBrowserContext" {
		c.contextErrs <- ctx.Err()
	}
	return []byte("{}"), nil
}

func TestNewInstanceWithContextCancelsBlockedBrowserContextCreation(t *testing.T) {
	client := newBlockingCDPClient("Target.createBrowserContext", 500*time.Millisecond)
	browser := &Browser{engine: rod.New().Client(client)}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()

	started := time.Now()
	_, err := browser.NewInstanceWithContext(ctx, time.Second)

	require.ErrorIs(t, err, context.DeadlineExceeded)
	require.Less(t, time.Since(started), 200*time.Millisecond)
}

func TestNewInstanceWithContextDisposesContextCreatedAfterCancellation(t *testing.T) {
	client := &lateCreateCDPClient{
		events:   make(chan *cdp.Event),
		disposed: make(chan struct{}, 1),
		delay:    50 * time.Millisecond,
	}
	browser := &Browser{engine: rod.New().Client(client)}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
	defer cancel()

	started := time.Now()
	_, err := browser.NewInstanceWithContext(ctx, time.Second)
	require.ErrorIs(t, err, context.DeadlineExceeded)
	require.Less(t, time.Since(started), 100*time.Millisecond)

	select {
	case <-client.disposed:
	case <-time.After(time.Second):
		t.Fatal("browser context created after cancellation was not disposed")
	}
}

func TestInstanceCloseUsesLiveCleanupContext(t *testing.T) {
	client := &cleanupCDPClient{
		events:      make(chan *cdp.Event),
		contextErrs: make(chan error, 1),
	}
	canceledCtx, cancel := context.WithCancel(context.Background())
	cancel()
	browser := rod.New().Client(client).Context(canceledCtx)
	browser.BrowserContextID = proto.BrowserBrowserContextID("context-id")
	instance := &Instance{engine: browser}

	require.NoError(t, instance.Close())
	require.NoError(t, <-client.contextErrs)
}

package engine

import (
	"bufio"
	"context"
	"fmt"
	"net/http"
	"net/url"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/utils/vardump"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/utils"
	httputil "github.com/projectdiscovery/nuclei/v3/pkg/protocols/utils/http"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/rod"
	"github.com/projectdiscovery/rod/lib/proto"
	"github.com/projectdiscovery/utils/errkit"
	urlutil "github.com/projectdiscovery/utils/url"
)

// Page is a single page in an isolated browser instance
type Page struct {
	ctx                *contextargs.Context
	inputURL           *urlutil.URL
	options            *Options
	page               *rod.Page
	rules              []rule
	instance           *Instance
	hijackRouter       *rod.HijackRouter
	hijackNative       *Hijack
	mutex              *sync.RWMutex
	History            []HistoryData
	InteractshURLs     []string
	ActionDurations    []time.Duration
	payloads           map[string]interface{}
	variables          map[string]interface{}
	lastActionNavigate *Action
	cancel             context.CancelFunc
	screenshots        int
}

// HistoryData contains the page request/response pairs
type HistoryData struct {
	RawRequest  string
	RawResponse string
}

// Options contains additional configuration options for the browser instance
type Options struct {
	Timeout       time.Duration
	DisableCookie bool
	Options       *types.Options
	// OnNavigationResponse receives the response to the initial URL once the
	// actions ran, even when they failed: the browser fails a navigation on
	// an error status with an empty body, and that status still matters.
	OnNavigationResponse func(*http.Response)
}

// Run runs a list of actions by creating a new page in the browser.
func (i *Instance) Run(ctx *contextargs.Context, actions []*Action, payloads map[string]interface{}, options *Options) (ActionData, *Page, error) {
	if err := ctx.Context().Err(); err != nil {
		return nil, nil, err
	}

	pageContext := ctx.Context()
	cancelPage := func() {}
	if options.Timeout > 0 {
		pageContext, cancelPage = context.WithTimeout(pageContext, options.Timeout)
	}
	page, err := i.engine.Context(pageContext).Page(proto.TargetCreateTarget{})
	if err != nil {
		cancelPage()
		return nil, nil, err
	}
	page = page.Context(pageContext)
	createdPage := &Page{
		options:  options,
		page:     page,
		ctx:      ctx,
		instance: i,
		mutex:    &sync.RWMutex{},
		cancel:   cancelPage,
	}
	successfulPageCreation := false
	defer func() {
		if !successfulPageCreation {
			createdPage.Close()
		}
	}()

	if err = i.browser.applyDefaultHeaders(page); err != nil {
		return nil, nil, err
	}

	if i.browser.customAgent != "" {
		if userAgentErr := page.SetUserAgent(&proto.NetworkSetUserAgentOverride{UserAgent: i.browser.customAgent}); userAgentErr != nil {
			return nil, nil, userAgentErr
		}
	}

	payloads = generators.MergeMaps(payloads,
		generators.BuildPayloadFromOptions(i.browser.options),
	)

	target := ctx.MetaInput.Input
	input, err := urlutil.Parse(target)
	if err != nil {
		return nil, nil, errkit.Wrapf(err, "could not parse URL %s", target)
	}

	hasTrailingSlash := httputil.HasTrailingSlash(target)
	variables := utils.GenerateVariables(input, hasTrailingSlash, contextargs.GenerateVariables(ctx))
	variables = generators.MergeMaps(variables, payloads)

	if vardump.EnableVarDump {
		gologger.Debug().Msgf("Headless Protocol request variables: %s\n", vardump.DumpVariables(variables))
	}

	createdPage.payloads = payloads
	createdPage.variables = variables
	createdPage.inputURL = input

	if options != nil && options.Options != nil {
		if netErr := protocolstate.SetupHeadlessNetworkPolicy(options.Options, page); netErr != nil {
			return nil, nil, netErr
		}
	}

	httpclient, err := i.browser.getHTTPClient()
	if err != nil {
		return nil, nil, err
	}

	// in case the page has request/response modification rules - enable global hijacking
	if createdPage.hasModificationRules() || containsModificationActions(actions...) {
		hijackRouter := page.HijackRequests()
		if err := hijackRouter.Add("*", "", createdPage.routingRuleHandler(httpclient)); err != nil {
			return nil, nil, err
		}
		createdPage.hijackRouter = hijackRouter
		go hijackRouter.Run()
	} else {
		hijackRouter := NewHijack(page)
		hijackRouter.SetPattern(&proto.FetchRequestPattern{
			URLPattern:   "*",
			RequestStage: proto.FetchRequestStageResponse,
		})
		createdPage.hijackNative = hijackRouter
		hijackRouterHandler := hijackRouter.Start(createdPage.routingRuleHandlerNative)
		go func() {
			_ = hijackRouterHandler()
		}()
	}

	if err := page.SetViewport(&proto.EmulationSetDeviceMetricsOverride{Viewport: &proto.PageViewport{
		Scale:  1,
		Width:  float64(1920),
		Height: float64(1080),
	}}); err != nil {
		return nil, nil, err
	}

	// inject cookies
	// each http request is performed via the native go http client
	// we first inject the shared cookies
	URL, err := url.Parse(ctx.MetaInput.Input)
	if err != nil {
		return nil, nil, err
	}

	if !options.DisableCookie {
		if cookies := ctx.CookieJar.Cookies(URL); len(cookies) > 0 {
			var NetworkCookies []*proto.NetworkCookie
			for _, cookie := range cookies {
				networkCookie := &proto.NetworkCookie{
					Name:     cookie.Name,
					Value:    cookie.Value,
					Domain:   cookie.Domain,
					Path:     cookie.Path,
					HTTPOnly: cookie.HttpOnly,
					Secure:   cookie.Secure,
					Expires:  proto.TimeSinceEpoch(cookie.Expires.Unix()),
					SameSite: proto.NetworkCookieSameSite(GetSameSite(cookie)),
					Priority: proto.NetworkCookiePriorityLow,
				}
				NetworkCookies = append(NetworkCookies, networkCookie)
			}
			params := proto.CookiesToParams(NetworkCookies)
			for _, param := range params {
				param.URL = ctx.MetaInput.Input
			}
			err := page.SetCookies(params)
			if err != nil {
				return nil, nil, err
			}
		}
	}

	data, err := createdPage.ExecuteActions(ctx, actions)
	if options.OnNavigationResponse != nil {
		if resp := createdPage.NavigationResponse(); resp != nil {
			options.OnNavigationResponse(resp)
		}
	}
	if err != nil {
		return nil, nil, err
	}

	// at the end of actions pull out the cookies from the browser. They are
	// exposed as DSL variables, since the browser does not report Set-Cookie
	// in the intercepted response headers, and they are injected into the
	// shared cookie jar unless cookie reuse is disabled. The cookies are read
	// for the whole host, because a cookie scoped to another path than the
	// input URL is still set by the response.
	var httpCookies []*http.Cookie
	if cookies, err := page.Browser().GetCookies(); err == nil {
		for _, cookie := range cookies {
			if !cookieMatchesHost(cookie.Domain, URL.Hostname()) {
				continue
			}
			httpCookie := &http.Cookie{
				Name:     cookie.Name,
				Value:    cookie.Value,
				Domain:   cookie.Domain,
				Path:     cookie.Path,
				HttpOnly: cookie.HTTPOnly,
				Secure:   cookie.Secure,
			}
			httpCookies = append(httpCookies, httpCookie)
		}
	}
	if !options.DisableCookie && len(httpCookies) > 0 {
		ctx.CookieJar.SetCookies(URL, httpCookies)
	}

	if resp := createdPage.FirstResponse(); resp != nil {
		headers := utils.HeadersToString(resp.Header)
		data["header"] = headers
		data["all_headers"] = headers
		data["status_code"] = fmt.Sprint(resp.StatusCode)
		addResponseVariables(data, resp, httpCookies)
	}

	successfulPageCreation = true // avoid closing the page in case of success in deferred function
	return data, createdPage, nil
}

// Close closes a browser page
func (p *Page) Close() {
	cleanupCtx, cancelCleanup := context.WithTimeout(context.Background(), browserCleanupTimeout)
	defer cancelCleanup()
	p.close(cleanupCtx)
}

func (p *Page) close(cleanupCtx context.Context) {
	if p.hijackRouter != nil {
		_ = p.hijackRouter.Stop()
	}
	if p.hijackNative != nil {
		_ = p.hijackNative.Stop()
	}
	if p.page.GetContext().Err() != nil {
		_, _ = proto.TargetCloseTarget{TargetID: p.page.TargetID}.Call(p.page.Browser().Context(cleanupCtx))
	} else {
		_ = p.page.Context(cleanupCtx).Close()
	}
	if p.cancel != nil {
		p.cancel()
	}
}

// Page returns the current page for the actions
func (p *Page) Page() *rod.Page {
	return p.page
}

// Browser returns the browser that created the current page
func (p *Page) Browser() *rod.Browser {
	return p.instance.engine
}

// URL returns the URL for the current page.
func (p *Page) URL() string {
	info, err := p.page.Info()
	if err != nil {
		return ""
	}
	return info.URL
}

// FirstResponse returns the response to the very first request from the
// browser, which is assumed to be the one for the initial URL. It is nil when
// none was recorded.
func (p *Page) FirstResponse() *http.Response {
	p.mutex.RLock()
	if len(p.History) == 0 {
		p.mutex.RUnlock()
		return nil
	}
	raw := p.History[0].RawResponse
	p.mutex.RUnlock()
	return parseHistoryResponse(raw)
}

// NavigationResponse returns the response that ended the initial navigation,
// nil when none was recorded. Redirect hops are separate history items, so it
// follows Location from the first item to the response that was not a redirect.
func (p *Page) NavigationResponse() *http.Response {
	p.mutex.RLock()
	history := slices.Clone(p.History)
	p.mutex.RUnlock()
	return navigationResponse(history)
}

// maxNavigationRedirects matches the redirect limit of Chromium.
const maxNavigationRedirects = 20

func navigationResponse(history []HistoryData) *http.Response {
	if len(history) == 0 {
		return nil
	}
	resp := parseHistoryResponse(history[0].RawResponse)
	current := historyRequestURL(history[0].RawRequest)
	next := 1
	for hop := 0; resp != nil && current != nil && hop < maxNavigationRedirects; hop++ {
		if resp.StatusCode < 300 || resp.StatusCode > 399 {
			break
		}
		location := resp.Header.Get("Location")
		if location == "" {
			break
		}
		target, err := current.Parse(location)
		if err != nil {
			break
		}
		found := false
		for i := next; i < len(history); i++ {
			candidate := historyRequestURL(history[i].RawRequest)
			if candidate == nil || !sameResource(candidate, target) {
				continue
			}
			hopResp := parseHistoryResponse(history[i].RawResponse)
			if hopResp == nil {
				break
			}
			resp, current, next, found = hopResp, candidate, i+1, true
			break
		}
		if !found {
			break
		}
	}
	return resp
}

func parseHistoryResponse(raw string) *http.Response {
	resp, err := http.ReadResponse(bufio.NewReader(strings.NewReader(raw)), nil)
	if err != nil {
		return nil
	}
	_ = resp.Body.Close()
	return resp
}

// historyRequestURL reads the target of a recorded request. The native hijack
// records an absolute URL on the request line. The rod router records a path
// and a Host header.
func historyRequestURL(raw string) *url.URL {
	lines := strings.Split(strings.ReplaceAll(raw, "\r\n", "\n"), "\n")
	fields := strings.Fields(lines[0])
	if len(fields) < 2 {
		return nil
	}
	target, err := url.Parse(fields[1])
	if err != nil {
		return nil
	}
	if target.Host != "" {
		return target
	}
	for _, line := range lines[1:] {
		if line == "" {
			break
		}
		name, value, ok := strings.Cut(line, ":")
		if ok && strings.EqualFold(strings.TrimSpace(name), "Host") {
			target.Host = strings.TrimSpace(value)
			return target
		}
	}
	return nil
}

// sameResource ignores the scheme, so an http to https redirect still matches
// when the recorded request has no scheme.
func sameResource(a, b *url.URL) bool {
	pathOf := func(u *url.URL) string {
		if u.EscapedPath() == "" {
			return "/"
		}
		return u.EscapedPath()
	}
	return strings.EqualFold(a.Host, b.Host) && pathOf(a) == pathOf(b) && a.RawQuery == b.RawQuery
}

// DumpHistory returns the full page navigation history
func (p *Page) DumpHistory() string {
	p.mutex.RLock()
	defer p.mutex.RUnlock()

	var historyDump strings.Builder
	for _, historyData := range p.History {
		historyDump.WriteString(historyData.RawRequest)
		historyDump.WriteString(historyData.RawResponse)
	}
	return historyDump.String()
}

// addToHistory adds a request/response pair to the page history
func (p *Page) addToHistory(historyData ...HistoryData) {
	p.mutex.Lock()
	defer p.mutex.Unlock()

	p.History = append(p.History, historyData...)
}

func (p *Page) addInteractshURL(URLs ...string) {
	p.mutex.Lock()
	defer p.mutex.Unlock()

	p.InteractshURLs = append(p.InteractshURLs, URLs...)
}

// appendRule records a request/response modification rule. The hijack handler
// reads p.rules from a separate goroutine, so writes must be synchronized.
func (p *Page) appendRule(r rule) {
	p.mutex.Lock()
	defer p.mutex.Unlock()

	p.rules = append(p.rules, r)
}

// rulesSnapshot returns a copy of the current rules for lock-free iteration by
// the hijack handler (which performs network I/O and must not hold the lock).
func (p *Page) rulesSnapshot() []rule {
	p.mutex.RLock()
	defer p.mutex.RUnlock()

	return slices.Clone(p.rules)
}

func (p *Page) hasModificationRules() bool {
	for _, rule := range p.rulesSnapshot() {
		if containsAnyModificationActionType(rule.Action) {
			return true
		}
	}
	return false
}

// updateLastNavigatedURL updates the last navigated URL in the instance's
// request log.
func (p *Page) updateLastNavigatedURL() {
	if p.lastActionNavigate == nil {
		return
	}

	templateURL := p.lastActionNavigate.GetArg("url")
	p.instance.requestLog[templateURL] = p.URL()
}

func containsModificationActions(actions ...*Action) bool {
	for _, action := range actions {
		if containsAnyModificationActionType(action.ActionType.ActionType) {
			return true
		}
	}
	return false
}

func containsAnyModificationActionType(actionTypes ...ActionType) bool {
	for _, actionType := range actionTypes {
		switch actionType {
		case ActionSetMethod:
			return true
		case ActionAddHeader:
			return true
		case ActionSetHeader:
			return true
		case ActionDeleteHeader:
			return true
		case ActionSetBody:
			return true
		}
	}
	return false
}

func GetSameSite(cookie *http.Cookie) string {
	switch cookie.SameSite {
	case http.SameSiteNoneMode:
		return "none"
	case http.SameSiteLaxMode:
		return "lax"
	case http.SameSiteStrictMode:
		return "strict"
	case http.SameSiteDefaultMode:
		fallthrough
	default:
		return ""
	}
}

