		Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.JSONExtractor},
		JSON: []string{".users[].email"},
	}
	err = extractor.CompileExtractors()
	require.Nil(t, err)

	result = request.Extract(data, extractor)
	expected = map[string]struct{}{
		"john@example.com": {},
		"jane@example.com": {},
		"bob@example.com":  {},
	}
	require.Equal(t, expected, result)

	// Test with invalid JSON
	invalidJSON := `{"invalid": json}`
	data = map[string]interface{}{
		"data": invalidJSON,
	}

	extractor = &extractors.Extractor{
		Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.JSONExtractor},
		JSON: []string{".invalid"},
	}
	err = extractor.CompileExtractors()
	require.Nil(t, err)

	result = request.Extract(data, extractor)
	require.Equal(t, map[string]struct{}{}, result)

	// Test with non-existent path
	extractor = &extractors.Extractor{
		Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.JSONExtractor},
		JSON: []string{".nonexistent"},
	}
	err = extractor.CompileExtractors()
	require.Nil(t, err)

	result = request.Extract(data, extractor)
	require.Equal(t, map[string]struct{}{}, result)
}

func TestRequest_MatchXPath(t *testing.T) {
	request := &Request{}

	htmlContent := `<!doctype html>
<html>
<head>
    <title>Test Page</title>
</head>
<body>
    <div class="container">
        <h1>Welcome</h1>
        <p>This is a test page</p>
        <a href="https://example.com" id="test-link">Click here</a>
    </div>
</body>
</html>`

	data := map[string]interface{}{
		"data": htmlContent,
	}

	// Test XPath matcher with existing element
	matcher := &matchers.Matcher{
		Type:      matchers.MatcherTypeHolder{MatcherType: matchers.XPathMatcher},
		XPath:     []string{"/html/body/div/h1"},
		Condition: "and",
	}
	err := matcher.CompileMatchers()
	require.Nil(t, err)

	matched, snippets := request.Match(data, matcher)
	require.True(t, matched)
	require.Empty(t, snippets)

	// Test XPath matcher with non-existent element
	matcher = &matchers.Matcher{
		Type:      matchers.MatcherTypeHolder{MatcherType: matchers.XPathMatcher},
		XPath:     []string{"/html/body/div/nonexistent"},
		Condition: "and",
	}
	err = matcher.CompileMatchers()
	require.Nil(t, err)

	matched, snippets = request.Match(data, matcher)
	require.False(t, matched)
	require.Empty(t, snippets)
}

func TestRequest_getMatchPart(t *testing.T) {
	request := &Request{}

	data := map[string]interface{}{
		"data":    "body content",
		"header":  "header content",
		"history": "history content",
	}

	// Test default part (should map to "data")
	part, ok := request.getMatchPart("", data)
	require.True(t, ok)
	require.Equal(t, "body content", part)

	// Test "body" part (should map to "data")
	part, ok = request.getMatchPart("body", data)
	require.True(t, ok)
	require.Equal(t, "body content", part)

	// Test "resp" part (should map to "data")
	part, ok = request.getMatchPart("resp", data)
	require.True(t, ok)
	require.Equal(t, "body content", part)

	// Test "header" part
	part, ok = request.getMatchPart("header", data)
	require.True(t, ok)
	require.Equal(t, "header content", part)

	// Test "all_headers" part (alias of header)
	part, ok = request.getMatchPart("all_headers", data)
	require.True(t, ok)
	require.Equal(t, "header content", part)

	// Test "history" part
	part, ok = request.getMatchPart("history", data)
	require.True(t, ok)
	require.Equal(t, "history content", part)

	// Test non-existent part
	part, ok = request.getMatchPart("nonexistent", data)
	require.False(t, ok)
	require.Equal(t, "", part)
}

func TestHeadlessDurationFields(t *testing.T) {
	event := output.InternalEvent{}
	addHeadlessDurationFields(event, []time.Duration{time.Second, 2 * time.Second}, 0)
	require.Equal(t, float64(1), event["duration_1"])
	require.Equal(t, float64(2), event["duration_2"])
	require.Equal(t, float64(2), event["duration"])

	event = output.InternalEvent{}
	addHeadlessDurationFields(event, nil, 500*time.Millisecond)
	require.Equal(t, 0.5, event["duration"])
	require.NotContains(t, event, "duration_1")

	request := &Request{}
	extractor := &extractors.Extractor{
		Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
		DSL:  []string{"duration"},
	}
	require.NoError(t, extractor.CompileExtractors())
	require.Equal(t, map[string]struct{}{"0.5": {}}, request.Extract(event, extractor))

	require.Contains(t, RequestPartDefinitions, "duration")
	require.NotContains(t, RequestPartDefinitions, "duration_<N>")
	require.NotContains(t, RequestPartDefinitions, "duration_ms")
	require.NotContains(t, RequestPartDefinitions, "duration_total")
}

func TestRequest_ExtractWithDifferentParts(t *testing.T) {
	request := &Request{}

	// Test extracting from different parts
	htmlContent := `<!doctype html><html><body><div><h1>Title</h1></div></body></html>`
	jsonContent := `{"id": 123}`

	data := map[string]interface{}{
