const (
	ReqURLPatternKey = "req_url_pattern"
)

// ErrEvalExpression
type errorTemplate struct {
	format string
}

func (e errorTemplate) Wrap(err error) wrapperError {
	return wrapperError{template: e, err: err}
}

func (e errorTemplate) Msgf(args ...interface{}) error {
	return errkit.Newf(e.format, args...)
}

type wrapperError struct {
	template errorTemplate
	err      error
}

func (w wrapperError) WithTag(tag string) error {
	return errkit.Wrap(w.err, w.template.format)
}

func (w wrapperError) Msgf(format string, args ...interface{}) error {
	return errkit.Wrapf(w.err, format, args...)
}

func (w wrapperError) Error() string {
	return errkit.Wrap(w.err, w.template.format).Error()
}

// ErrEvalExpression
var (
	ErrEvalExpression = errorTemplate{"could not evaluate helper expressions"}
	ErrUnresolvedVars = errorTemplate{"unresolved variables `%v` found in request"}
)

// generatedRequest is a single generated request wrapped for a template request
type generatedRequest struct {
	original        *Request
	rawRequest      *raw.Request
	meta            map[string]any
	pipelinedClient *rawhttp.PipelineClient
	request         *retryablehttp.Request
	dynamicValues   map[string]any
	interactshURLs  []string
	// sendTimeout bounds the exchange with the host, and sendTimeoutCause is
	// the error it ends with. executeRequest starts it after the rate-limit
	// and backoff waits and the body budget, so no wait uses it up.
	sendTimeout      time.Duration
	sendTimeoutCause error
	bodyReserved     bool
	// requestURLPattern tracks unmodified request url pattern without values ( it is used for constant vuln_hash)
	// ex: {{BaseURL}}/api/exp?param={{randstr}}
	requestURLPattern string

	fuzzGeneratedRequest fuzz.GeneratedRequest
}

// setReqURLPattern sets the url request pattern for the generated request
func (gr *generatedRequest) setReqURLPattern(reqURLPattern string) {
	if idx := strings.IndexByte(reqURLPattern, '\n'); idx >= 0 {
		reqURLPattern = strings.TrimSpace(reqURLPattern[:idx])
		// this is raw request (if it has 3 parts after strings.Fields then its valid only use 2nd part)
		parts := strings.Fields(reqURLPattern)
		if len(parts) >= 3 {
			// remove first and last and use all in between
			parts = parts[1 : len(parts)-1]
			reqURLPattern = strings.Join(parts, " ")
		}
	} else {
		reqURLPattern = strings.TrimSpace(reqURLPattern)
	}

	// now urlRequestPattern is generated replace preprocessor values with actual placeholders
	// that were used (these are called generated 'constants' and contains {{}} in var name)
	for k, v := range gr.original.options.Constants {
		if strings.HasPrefix(k, "{{") && strings.HasSuffix(k, "}}") {
			// this takes care of all preprocessors ( currently we have randstr and its variations)
			reqURLPattern = strings.ReplaceAll(reqURLPattern, fmt.Sprint(v), k)
		}
	}
	gr.requestURLPattern = reqURLPattern
}

// ApplyAuth applies the auth provider to the generated request
func (g *generatedRequest) ApplyAuth(provider authprovider.AuthProvider) {
	if provider == nil {
		return
	}
	if g.request != nil {
		authStrategies := provider.LookupURLX(g.request.URL)
		for _, strategy := range authStrategies {
			strategy.ApplyOnRR(g.request)
		}
	}
	if g.rawRequest != nil {
		parsed, err := urlutil.ParseAbsoluteURL(g.rawRequest.FullURL, true)
		if err != nil {
			gologger.Warning().Msgf("[authprovider] Could not parse URL %s: %s\n", g.rawRequest.FullURL, err)
			return
		}
		authStrategies := provider.LookupURLX(parsed)
		// here we need to apply it custom because we don't have a standard/official
		// rawhttp request format ( which we probably should have )
		for _, strategy := range authStrategies {
			g.rawRequest.ApplyAuthStrategy(strategy)
		}
	}
}

func (g *generatedRequest) URL() string {
	if g.request != nil {
		return g.request.String()
	}
	if g.rawRequest != nil {
		return g.rawRequest.FullURL
	}
	return ""
}

// Make creates a http request for the provided input.
func (r *requestGenerator) Make(ctx context.Context, input *contextargs.Context, reqData string, payloads, dynamicValues map[string]interface{}) (gr *generatedRequest, err error) {
	origReqData := reqData
	r.interactshURLs = nil
	defer func() {
		if gr != nil {
			gr.setReqURLPattern(origReqData)
		}
	}()
	// value of `reqData` depends on the type of request specified in template
	// 1. If request is raw request =  reqData contains raw request (i.e http request dump)
	// 2. If request is Normal ( simply put not a raw request) (Ex: with placeholders `path`) = reqData contains relative path

	isRawRequest := len(r.request.Raw) > 0
	for payloadName, payloadValue := range payloads {
		payloads[payloadName] = types.ToStringNSlice(payloadValue)
	}

	if r.request.SelfContained {
		return r.makeSelfContainedRequest(ctx, input, reqData, payloads, dynamicValues)
	}

	// Parse target url
	parsed, err := urlutil.ParseAbsoluteURL(input.MetaInput.Input, false)
	if err != nil {
		return nil, err
	}

	// Non-Raw Requests ex `{{BaseURL}}/somepath` may or maynot have slash after variable and the same is the case for
	// target url to avoid inconsistencies extra slash if exists has to removed from default variables
	hasTrailingSlash := false
	if !isRawRequest {
		// if path contains port ex: {{BaseURL}}:8080 use port specified in reqData
		parsed, reqData = httputil.UpdateURLPortFromPayload(parsed, reqData)
		hasTrailingSlash = httputil.HasTrailingSlash(reqData)
	}

	// defaultreqvars are vars generated from request/input ex: {{baseURL}}, {{Host}} etc
	// contextargs generate extra vars that may/may not be available always (ex: "ip")
	defaultReqVars := protocolutils.GenerateVariables(parsed, hasTrailingSlash, contextargs.GenerateVariables(input))
	// optionvars are vars passed from CLI or env variables
	optionVars := generators.BuildPayloadFromOptions(r.request.options.Options)

	scope := r.options.NewVariablesScope()
	r.options.AddTemplateCtxToVariablesScope(input.MetaInput, scope)
	scope.AddData(dynamicValues, defaultReqVars, optionVars, r.options.Constants)
	evaluation := r.options.Variables.EvaluateWithInteractshScope(scope, r.options.Interactsh)

	variablesMap, interactURLs := evaluation.Values, evaluation.InteractURLs
	if len(interactURLs) > 0 {
		r.interactshURLs = append(r.interactshURLs, interactURLs...)
	}

	// allVars contains all variables from all sources
	allVars := make(map[string]interface{})
	if r.request.options.HasTemplateCtx(input.MetaInput) {
		allVars = generators.MergeMaps(r.request.options.GetTemplateCtx(input.MetaInput).GetAll())
	}

	allVars = generators.MergeMaps(allVars, dynamicValues, defaultReqVars, optionVars, variablesMap, r.options.Constants)

	// Evaluate payload variables
	// eg: payload variables can be username: jon.doe@{{Hostname}}
	for payloadName, payloadValue := range payloads {
		payloads[payloadName], err = r.renderText(types.ToString(payloadValue), allVars)
		if err != nil {
			return nil, errkit.Wrap(err, "could not evaluate helper expressions")
		}
	}
	// finalVars contains allVars and any generator/fuzzing specific payloads
	// payloads used in generator should be given the most preference
	finalVars := generators.MergeMaps(allVars, payloads)

	if vardump.EnableVarDump {
		gologger.Debug().Msgf("HTTP Protocol request variables: %s\n", vardump.DumpVariables(finalVars))
	}

	// Note: If possible any changes to current logic (i.e evaluate -> then parse URL)
	// should be avoided since it is dependent on `urlutil` core logic

	// Evaluate (replace) variable with final values
	reqData, err = r.renderText(reqData, finalVars)
	if err != nil {
		return nil, errkit.Wrap(err, "could not evaluate helper expressions")
	}

	if isRawRequest {
		return r.generateRawRequest(ctx, reqData, parsed, finalVars, payloads)
	}

	reqURL, err := urlutil.ParseAbsoluteURL(reqData, true)
	if err != nil {
		return nil, errkit.Newf("failed to parse url %v while creating http request", reqData)
	}

	// while merging parameters first preference is given to target params
	finalparams := parsed.Params
	finalparams.Merge(reqURL.Params.Encode())
	reqURL.Params = finalparams

	return r.generateHttpRequest(ctx, reqURL, finalVars, payloads)
}

// validateSelfContainedHost validates a self-contained request's destination
// host against the execution network policy.
func (r *requestGenerator) validateSelfContainedHost(host string) error {
	if host == "" {
		return nil
	}
	executionId := r.request.options.Options.ExecutionId
	if !protocolstate.IsHostAllowed(executionId, host) {
		return errkit.Newf("self-contained request host %s is blocked by network policy", host)
	}
	return nil
}

// selfContained templates do not need/use target data and all values i.e {{Hostname}} , {{BaseURL}} etc are already available
// in template . makeSelfContainedRequest parses and creates variables map and then creates corresponding http request or raw request
func (r *requestGenerator) makeSelfContainedRequest(ctx context.Context, input *contextargs.Context, data string, payloads, dynamicValues map[string]interface{}) (*generatedRequest, error) {
	if r.request.isRaw() {
		return r.makeSelfContainedRawRequest(ctx, input, data, payloads, dynamicValues)
	}

	values, _, err := r.selfContainedValues(input, payloads, dynamicValues, nil)
	if err != nil {
		return nil, err
	}

	data, err = r.renderText(data, values)
	if err != nil {
		return nil, errkit.Wrap(err, "could not evaluate helper expressions")
	}
	if err := expressions.ContainsUnresolvedVariables(data); err != nil && !r.request.SkipVariablesCheck {
		// early exit: if there are any unresolved variables in `path` after evaluation
		// then return early since this will definitely fail
		return nil, errkit.Newf("unresolved variables `%v` found in request", data)
	}

	urlx, err := urlutil.ParseURL(data, true)
	if err != nil {
		return nil, errkit.Wrapf(err, "failed to parse %v in self contained request", data)
	}
	// validate the self-chosen destination host against the network policy.
	if err := r.validateSelfContainedHost(urlx.Hostname()); err != nil {
		return nil, err
	}
	return r.generateHttpRequest(ctx, urlx, values, payloads)
}

// makeSelfContainedRawRequest makes a self-contained raw request. Its request
// line names the URL, and that URL provides variables such as {{Hostname}} to
// the rest of the request. Each part of the template text is rendered once,
// so inserted values such as response data are sent unchanged:
//
//  1. Render the request line and check its host against the network policy.
//  2. Evaluate again the template variables and payloads whose template text
//     names URL variables. The others keep their values, so a random value
//     is the same in the request line and in the rest of the request.
//  3. Render the annotations and the rest of the request.
func (r *requestGenerator) makeSelfContainedRawRequest(ctx context.Context, input *contextargs.Context, data string, payloads, dynamicValues map[string]interface{}) (*generatedRequest, error) {
	annotations, requestLine, rest, err := splitRequestLine(data)
	if err != nil {
		return nil, err
	}

	// Payloads are rendered in place, so keep their template text for step 2.
	payloadText := generators.CopyMap(payloads)

	values, authored, err := r.selfContainedValues(input, payloads, dynamicValues, nil)
	if err != nil {
		return nil, err
	}

	requestLine, err = r.renderText(requestLine, values)
	if err != nil {
		return nil, errkit.Wrap(err, "could not evaluate helper expressions")
	}

	// Parse the line that raw.ParseRawRequest will read, even if a value
	// added a line break.
	firstLine, _, _ := strings.Cut(requestLine, "\n")

	parsed, err := r.requestLineURL(firstLine)
	if err != nil {
		return nil, err
	}

	// URL variables only fill in names that have no other value.
	fixed := make(map[string]interface{})

	for name, value := range protocolutils.GenerateVariables(parsed, false, nil) {
		if _, ok := values[name]; !ok {
			fixed[name] = value
		}
	}

	stale := r.staleValues(authored, payloadText, fixed)
	if len(stale) == 0 {
		values = generators.MergeMaps(fixed, values)
	} else {
		// Keep every other value, and evaluate the stale template variables
		// and payloads again from their template text.
		for name, value := range values {
			if _, ok := stale[name]; !ok {
				fixed[name] = value
			}
		}

		for name := range stale {
			if text, ok := payloadText[name]; ok {
				payloads[name] = text
			}
		}

		values, _, err = r.selfContainedValues(input, payloads, dynamicValues, fixed)
		if err != nil {
			return nil, err
		}
	}

	annotations, err = r.renderText(annotations, values)
	if err != nil {
		return nil, errkit.Wrap(err, "could not evaluate helper expressions")
	}

	rest, err = r.renderText(rest, values)
	if err != nil {
		return nil, errkit.Wrap(err, "could not evaluate helper expressions")
	}

	data = annotations + requestLine + rest

	// A value with a line break must not change which line is the request
	// line, or the request would go to a host that was not checked.
	if _, line, _, err := splitRequestLine(data); err != nil || line != firstLine {
		return nil, errkit.New("malformed request supplied: a value changed the request line")
	}

	return r.generateRawRequest(ctx, data, parsed, values, payloads)
}

// staleValues returns the names of the authored values whose template text
// names one of urlValues, directly or through another stale value. It reads
// template text only, so data inserted into a value cannot mark it stale.
// Variables are checked in evaluation order, then payloads, which are
// rendered after the variables.
func (r *requestGenerator) staleValues(authored, payloadText, urlValues map[string]interface{}) map[string]struct{} {
	stale := make(map[string]struct{})
	names := generators.CopyMap(urlValues)

	mark := func(name string, text interface{}) {
		if _, ok := authored[name]; !ok {
			return
		}

		if expressions.ReferencesVariables(types.ToString(text), names) {
			stale[name] = struct{}{}
			names[name] = nil
		}
	}

	r.request.options.Variables.ForEach(mark)

	for name, text := range payloadText {
		mark(name, text)
	}

	return stale
}

// requestLineURL returns the URL named by a rendered raw request line after
// checking its host against the network policy.
func (r *requestGenerator) requestLineURL(line string) (*urlutil.URL, error) {
	parts := strings.Split(line, " ")
	if len(parts) < 3 {
		return nil, fmt.Errorf("malformed request supplied")
	}

	if err := expressions.ContainsUnresolvedVariables(parts[1]); err != nil && !r.request.SkipVariablesCheck {
		return nil, errkit.Newf("unresolved variables `%v` found in request", parts[1])
	}

	parsed, err := urlutil.ParseURL(parts[1], true)
	if err != nil {
		return nil, fmt.Errorf("could not parse request URL: %w", err)
	}
	// self-contained requests choose their own destination URL, so validate
	// that host against the network policy.
	if err := r.validateSelfContainedHost(parsed.Hostname()); err != nil {
		return nil, err
	}

	return parsed, nil
}

// selfContainedValues evaluates the template variables and renders the
// payloads of a self-contained request, and returns the values to render the
// request with. Payloads are rendered in place. Values in fixed are data:
// they fill in names that have no other value, and a template variable or
// payload with the same name keeps that value instead of being evaluated.
// It also returns the values it produced from template text, that is the
// evaluated template variables and the rendered payloads.
func (r *requestGenerator) selfContainedValues(input *contextargs.Context, payloads, dynamicValues, fixed map[string]interface{}) (map[string]interface{}, map[string]interface{}, error) {
	optionValues := generators.BuildPayloadFromOptions(r.request.options.Options)
	values := generators.MergeMaps(fixed, optionValues)

	if r.request.options.HasTemplateCtx(input.MetaInput) {
		values = generators.MergeMaps(values, r.request.options.GetTemplateCtx(input.MetaInput).GetAll())
	}
	values = generators.MergeMaps(values, dynamicValues, payloads)
	// adds all variables from `variables` section in template
	scope := r.request.options.NewVariablesScope(optionValues)
	r.request.options.AddTemplateCtxToVariablesScope(input.MetaInput, scope)
	scope.AddData(dynamicValues, payloads, r.options.Constants, fixed)
	evaluation := r.request.options.Variables.EvaluateWithInteractshScope(scope, r.request.options.Interactsh)

	variablesMap, interactURLs := evaluation.Values, evaluation.InteractURLs
	if len(interactURLs) > 0 {
		r.interactshURLs = append(r.interactshURLs, interactURLs...)
	}

	values = generators.MergeMaps(variablesMap, values)
	signerVars := GetDefaultSignerVars(r.request.Signature.Value)

	// this will ensure that default signer variables are overwritten by other variables
	values = generators.MergeMaps(signerVars, values, r.options.Constants)

	// The evaluation owns TemplateValues, so add the rendered payloads to it.
	authored := evaluation.TemplateValues

	for payloadName, payloadValue := range payloads {
		if _, ok := fixed[payloadName]; ok {
			continue
		}

		renderedPayload, err := r.renderText(types.ToString(payloadValue), values)
		if err != nil {
			return nil, nil, errkit.Wrap(err, "could not evaluate payload helper expressions")
		}

		payloads[payloadName] = renderedPayload
		authored[payloadName] = renderedPayload
	}

	// priority of variables is as follows (from low to high) for self contained templates
	// default signer vars < variables < cli vars < dynamic values < payload < constants
	return generators.MergeMaps(values, payloads, r.options.Constants), authored, nil
}

// splitRequestLine splits raw request template text at its request line, the
// first line that is not an annotation. It returns the annotation lines, the
// request line without its line break, and the remaining text starting with
// that line break. The three parts concatenate back to raw.
func splitRequestLine(raw string) (annotations, requestLine, rest string, err error) {
	start := 0

	for {
		line, _, found := strings.Cut(raw[start:], "\n")
		if !found {
			return "", "", "", errkit.New("could not read request: no request line found")
		}

		if !strings.HasPrefix(line, "@") {
			return raw[:start], line, raw[start+len(line):], nil
		}

		start += len(line) + 1
	}
}

// generateHttpRequest generates http request from request data from template and variables
// finalVars = contains all variables including generator and protocol specific variables
// generatorValues = contains variables used in fuzzing or other generator specific values
func (r *requestGenerator) generateHttpRequest(ctx context.Context, urlx *urlutil.URL, finalVars, generatorValues map[string]interface{}) (*generatedRequest, error) {
	method, err := r.renderText(r.request.Method.String(), finalVars)
	if err != nil {
		return nil, errkit.Wrap(err, "failed to evaluate while generating http request")
	}

	// Build a request on the specified URL
	req, err := retryablehttp.NewRequestFromURLWithContext(ctx, method, urlx, nil)
	if err != nil {
		return nil, err
	}

	request, err := r.fillRequest(req, finalVars)
	if err != nil {
		return nil, err
	}

	return &generatedRequest{request: request, meta: generatorValues, original: r.request, dynamicValues: finalVars, interactshURLs: r.interactshURLs}, nil
}

// generateRawRequest generates Raw Request from request data from template and variables
// finalVars = contains all variables including generator and protocol specific variables
// generatorValues = contains variables used in fuzzing or other generator specific values
func (r *requestGenerator) generateRawRequest(ctx context.Context, rawRequest string, baseURL *urlutil.URL, finalVars, generatorValues map[string]interface{}) (*generatedRequest, error) {
	var rawRequestData *raw.Request
	var err error

	if r.request.SelfContained {
		// in self contained requests baseURL is extracted from raw request itself
		rawRequestData, err = raw.ParseRawRequest(rawRequest, r.request.Unsafe)
	} else {
		rawRequestData, err = raw.Parse(rawRequest, baseURL, r.request.Unsafe, r.request.DisablePathAutomerge)
	}
	if err != nil {
		return nil, errkit.Wrap(err, "failed to parse raw request")
	}

	// Unsafe option uses rawhttp library
	if r.request.Unsafe {
		annotationURL := rawRequestData.FullURL
		if annotationURL == "" && baseURL != nil {
			cloned := baseURL.Clone()
			cloned.Params.IncludeEquals = true
			cloned.Path = ""
			_ = cloned.MergePath(rawRequestData.Path, true)
			annotationURL = cloned.String()
			rawRequestData.FullURL = annotationURL
		}

		var annotationOverrides annotationOverrides
		if annotationURL != "" {
			annotationRequest, reqErr := retryablehttp.NewRequestWithContext(ctx, rawRequestData.Method, annotationURL, nil)
			if reqErr == nil {
				if hostHeader, ok := rawRequestData.Headers["Host"]; ok {
					annotationRequest.Host = hostHeader
				}

				annotationOverrides, _ = r.request.parseAnnotations(rawRequest, annotationRequest)
				if annotationOverrides.err != nil {
					return nil, errkit.Wrap(annotationOverrides.err, "failed to apply raw request annotations")
				}
				if annotationOverrides.request != nil && annotationOverrides.request.URL != nil {
					rawRequestData.FullURL = annotationOverrides.request.String()
				}
			}
		}

		if len(r.options.Options.CustomHeaders) > 0 {
			customHeaders := make([]string, 0, len(r.options.Options.CustomHeaders))
			for _, header := range r.options.Options.CustomHeaders {
				customHeaders = append(customHeaders, evaluateCustomHeaderExpressions(r.options.TemplateID, header, finalVars))
			}
			_ = rawRequestData.TryFillCustomHeaders(customHeaders)
		}

		if rawRequestData.Data != "" && !stringsutil.EqualFoldAny(rawRequestData.Method, http.MethodHead, http.MethodGet) && rawRequestData.Headers["Transfer-Encoding"] != "chunked" {
			rawRequestData.Headers["Content-Length"] = strconv.Itoa(len(rawRequestData.Data))
		}

		unsafeReq := &generatedRequest{rawRequest: rawRequestData, meta: generatorValues, original: r.request, interactshURLs: r.interactshURLs}

		if len(annotationOverrides.interactshURLs) > 0 {
			unsafeReq.interactshURLs = append(unsafeReq.interactshURLs, annotationOverrides.interactshURLs...)
		}

		return unsafeReq, nil
	}
	urlx, err := urlutil.ParseAbsoluteURL(rawRequestData.FullURL, true)
	if err != nil {
		return nil, errkit.Wrapf(err, "failed to create request with url %v got %v", rawRequestData.FullURL, err)
	}
	req, err := retryablehttp.NewRequestFromURLWithContext(ctx, rawRequestData.Method, urlx, nil)
	if err != nil {
		return nil, err
	}
	// Set the body here rather than through retryablehttp, which copies it
	// several times over.
	httpbody.SetString(req, rawRequestData.Data)

	// force transfer encoding if conditions are met
	if len(rawRequestData.Data) > 0 && req.Header.Get("Transfer-Encoding") != "chunked" && !stringsutil.EqualFoldAny(rawRequestData.Method, http.MethodGet, http.MethodHead) {
		req.ContentLength = int64(len(rawRequestData.Data))
	}

	// override the body with a new one that will be used to read the request body in parallel threads
	// for race condition testing
	if r.request.Threads > 0 && r.request.Race {
		req.Body = race.NewOpenGateWithTimeout(req.Body, time.Duration(2)*time.Second)
	}

	for key, value := range rawRequestData.Headers {
		if key == "" {
			continue
		}
		req.Header[key] = []string{value}
		if key == "Host" {
			req.Host = value
		}
	}

	request, err := r.fillRequest(req, finalVars)
	if err != nil {
		return nil, err
	}

	generatedRequest := &generatedRequest{
		request:        request,
		meta:           generatorValues,
		original:       r.request,
		dynamicValues:  finalVars,
		interactshURLs: r.interactshURLs,
	}

	if reqWithOverrides, hasAnnotations := r.request.parseAnnotations(rawRequest, req); hasAnnotations {
		if reqWithOverrides.err != nil {
			return nil, errkit.Wrap(reqWithOverrides.err, "failed to apply raw request annotations")
		}
		generatedRequest.request = reqWithOverrides.request
		generatedRequest.sendTimeout = reqWithOverrides.timeout
		generatedRequest.sendTimeoutCause = reqWithOverrides.timeoutCause
		generatedRequest.interactshURLs = append(generatedRequest.interactshURLs, reqWithOverrides.interactshURLs...)
	}

	return generatedRequest, nil
}

// fillRequest fills various headers in the request with values
func (r *requestGenerator) fillRequest(req *retryablehttp.Request, values map[string]interface{}) (*retryablehttp.Request, error) {
	// Set the header values requested
	for header, value := range r.request.Headers {
		value, err := r.renderText(value, values)
		if err != nil {
			return nil, errkit.Wrap(err, "failed to evaluate while adding headers to request")
		}

		req.Header[header] = []string{value}
		if header == "Host" {
			req.Host = value
		}
	}

	// Respect the connection reuse policy from the smart analyzer.
	switch r.request.connectionReusePolicy {
	case ReuseUnsafe:
		// Force connection close for requests that must not reuse connections
		if req.Header.Get("Connection") == "" {
			req.Header.Set("Connection", "close")
		}
		req.Close = true
	case ReuseSafe:
		// Allow connection pooling: drop any explicit close header
		if strings.EqualFold(req.Header.Get("Connection"), "close") {
			req.Header.Del("Connection")
		}
	default:
		// Defer to the connection-level keep-alive decision: per-host clients
		// keep connections alive unless a template explicitly disabled it.
		if r.request.connConfiguration != nil && r.request.connConfiguration.Connection != nil &&
			r.request.connConfiguration.Connection.DisableKeepAlive && req.Header.Get("Connection") == "" {
			req.Close = true
		}
	}

	// Check if the user requested a request body
	if r.request.Body != "" {
		body, err := r.renderText(r.request.Body, values)
		if err != nil {
			return nil, errkit.Wrap(err, "could not evaluate helper expressions")
		}

		httpbody.SetString(req, body)
	}

	if !r.request.Unsafe {
		userAgent := useragent.PickRandom()
		httputil.SetHeader(req, "User-Agent", userAgent.Raw)
	}

	// Only set these headers on non-raw requests
	if len(r.request.Raw) == 0 && !r.request.Unsafe {
		httputil.SetHeader(req, "Accept", "*/*")
		httputil.SetHeader(req, "Accept-Language", "en")
	}

	if !LeaveDefaultPorts {
		switch {
		case req.Scheme == "http" && strings.HasSuffix(req.Host, ":80"):
			req.Host = strings.TrimSuffix(req.Host, ":80")
		case req.Scheme == "https" && strings.HasSuffix(req.Host, ":443"):
			req.Host = strings.TrimSuffix(req.Host, ":443")
		}
	}

	if r.request.DigestAuthUsername != "" {
		req.Auth = &retryablehttp.Auth{
			Type:     retryablehttp.DigestAuth,
			Username: r.request.DigestAuthUsername,
			Password: r.request.DigestAuthPassword,
		}
	}

	return req, nil
}

func (r *requestGenerator) renderText(text string, values map[string]interface{}) (string, error) {
	result, err := render.Render(render.Input{
		Options:      r.options.GetOptions(),
		Text:         text,
		Values:       values,
		Interactsh:   r.options.Interactsh,
		InteractURLs: r.interactshURLs,
	})
	if err != nil {
		return "", err
	}

	r.interactshURLs = result.InteractURLs

	return result.Text, nil
}

package http

import (
	"context"
	"net/http"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/http/catchall"
	"github.com/projectdiscovery/retryablehttp-go"
	httpUtils "github.com/projectdiscovery/utils/http"
)

// catchAllCheck returns the lazy check for whether resp is the page the host
// serves for any missing path, or nil when calibration cannot judge this
// request. Fuzzed and raced requests target real endpoints on purpose, and
// only GET and HEAD are probed so that calibration never sends a body.
func (request *Request) catchAllCheck(client *retryablehttp.Client, generated *generatedRequest, resp catchall.Response, rateLimitKey string) func() bool {
	detector := request.options.CatchAll
	sent := generated.request
	if detector == nil || client == nil || sent == nil || sent.URL == nil || generated.fuzzGeneratedRequest.Request != nil || request.Race {
		return nil
	}
	if sent.Method != http.MethodGet && sent.Method != http.MethodHead {
		return nil
	}
	// The response buffers are reused for the next response in the chain,
	// and the check may run after that.
	resp.Body = strings.Clone(resp.Body)
	requestURL := *sent.URL.URL
	header := sent.Header.Clone()
	hostHeader := sent.Host
	limit := int64(request.getEffectiveReadLimit())

	probe := func(ctx context.Context, path string) (catchall.Response, error) {
		if err := request.rateLimitTake(ctx, rateLimitKey); err != nil {
			return catchall.Response{}, err
		}
		target := requestURL
		target.Path, target.RawPath, target.RawQuery = path, "", ""
		probeReq, err := retryablehttp.NewRequestWithContext(ctx, sent.Method, target.String(), nil)
		if err != nil {
			return catchall.Response{}, err
		}
		probeReq.Header = header.Clone()
		probeReq.Host = hostHeader
		probeResp, err := client.Do(probeReq)
		if err != nil {
			return catchall.Response{}, err
		}
		chain := httpUtils.NewResponseChain(probeResp, limit)
		defer chain.Close()
		if err := chain.Fill(); err != nil {
			return catchall.Response{}, err
		}
		final := chain.Response()
		return catchall.Response{StatusCode: final.StatusCode, Location: final.Header.Get("Location"), Body: chain.BodyString()}, nil
	}
	ctx := sent.Context()
	return sync.OnceValue(func() bool { return detector.Matches(ctx, &requestURL, resp, probe) })
}

package catchall

import (
	"slices"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
)

// hostWideTags mark templates whose claim is about the host rather than the
// requested path. A single page app serves its shell, title and scripts on
// every path, so "this is Grafana" stays true on its catch-all page.
var hostWideTags = []string{"tech", "panel"}

// evidenceOutsideBody lists the response parts a catch-all page does not
// disprove: headers are usually set for the whole host, and an out-of-band
// interaction proves the request reached something regardless of the page.
var evidenceOutsideBody = []string{"header", "interactsh"}

// Applies reports whether a match by a template with info and ops can be
// discounted when the response is the host's catch-all page.
func Applies(info model.Info, ops *operators.Operators) bool {
	if ops == nil {
		return false
	}
	if slices.ContainsFunc(info.Tags.ToSlice(), func(tag string) bool { return slices.Contains(hostWideTags, tag) }) {
		return false
	}
	for _, matcher := range ops.Matchers {
		if readsOutsideBody(matcher.Part) || slices.ContainsFunc(matcher.DSL, readsOutsideBody) {
			return false
		}
	}
	return true
}

func readsOutsideBody(s string) bool {
	s = strings.ToLower(s)
	return slices.ContainsFunc(evidenceOutsideBody, func(part string) bool { return strings.Contains(s, part) })
}

package catchall

import (
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/stringslice"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
)

// info mirrors a parsed template, whose tags are split and lowercased.
func info(tags ...string) model.Info {
	return model.Info{Tags: stringslice.StringSlice{Value: tags}}
}

func TestAppliesToPathClaims(t *testing.T) {
	ops := &operators.Operators{Matchers: []*matchers.Matcher{{Words: []string{"DB_PASSWORD"}}, {Status: []int{200}}}}
	require.True(t, Applies(info("exposure", "config"), ops))
}

func TestHostWideClaimsAreKept(t *testing.T) {
	ops := &operators.Operators{Matchers: []*matchers.Matcher{{Words: []string{"<title>Grafana</title>"}}}}
	require.False(t, Applies(info("tech", "discovery"), ops), "a single page app is still that app on its catch-all page")
	require.False(t, Applies(info("panel", "grafana"), ops))
}

func TestEvidenceOutsideTheBodyIsKept(t *testing.T) {
	cases := map[string]*matchers.Matcher{
		"header part":     {Part: "header", Words: []string{"Access-Control-Allow-Origin: https://evil.test"}},
		"interactsh part": {Part: "interactsh_protocol", Words: []string{"dns"}},
		"dsl on headers":  {DSL: []string{`contains(header, "X-Debug")`}},
		"dsl interactsh":  {DSL: []string{`contains(interactsh_protocol, "http")`}},
	}
	for name, matcher := range cases {
		ops := &operators.Operators{Matchers: []*matchers.Matcher{{Status: []int{200}}, matcher}}
		require.False(t, Applies(info("misconfig"), ops), name)
	}
}

func TestNoOperatorsNeverApplies(t *testing.T) {
	require.False(t, Applies(info("exposure"), nil))
}

// Package catchall recognises a match that only happened because the host
// answers every path with the same page.
//
// Many hosts return 200 for paths that do not exist: single page apps, catch-all
// routes, login redirects. A template that requests /.env and matches on a
// status code and a loose word then reports a file that is not there. Directory
// brute forcers solved this long ago (ffuf -ac, skipfish, dirsearch, sqlmap's
// page comparison): ask the host for paths that cannot exist, remember what it
// answers, and discount anything that looks the same.
//
// The baseline is per host, parent directory and path shape, because a .php
// path, a nested path and a trailing slash are often routed to different
// handlers. It is only built once a template matches, so hosts without findings
// never see a probe.
package catchall

import (
	"context"
	"crypto/rand"
	"html"
	"net/url"
	"path"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"sync"
	"unicode"

	"github.com/projectdiscovery/gcache"
)

const (
	// Threshold is the token similarity at which two pages count as the same.
	// Pages generated from one template differ only in reflected values and
	// tokens, which normalisation removes; real content differs far more.
	Threshold = 0.95
	// DefaultMaxBaselines bounds the cached baselines. Losing one only costs
	// the probes to rebuild it.
	DefaultMaxBaselines = 4096
	// samples is how many random paths are fetched per baseline. Two is the
	// fewest that shows whether the host answers consistently at all.
	samples = 2
	// minReflection is the shortest echoed path worth removing.
	minReflection = 3
)

// dynamic matches values that change on every load, such as CSRF tokens,
// session ids, timestamps and cache busters.
var dynamic = regexp.MustCompile(`[A-Za-z0-9_\-+=]{24,}|\d{6,}`)

// Response is the part of an HTTP response that identifies a catch-all page.
type Response struct {
	StatusCode int
	Location   string
	Body       string
}

// Prober fetches path from the scanned host the same way the matched request
// was sent, so the baseline sees the same redirects, headers and session.
type Prober func(ctx context.Context, path string) (Response, error)

// Detector caches catch-all baselines across templates.
type Detector struct {
	mu        sync.Mutex
	baselines gcache.Cache[string, *baseline]
}

type baseline struct {
	once    sync.Once
	samples []fingerprint
}

type fingerprint struct {
	statusCode int
	location   string
	tokens     map[string]int
	total      int
}

// New returns a detector that keeps up to maxBaselines baselines, or
// DefaultMaxBaselines when maxBaselines is not positive.
func New(maxBaselines int) *Detector {
	if maxBaselines <= 0 {
		maxBaselines = DefaultMaxBaselines
	}
	return &Detector{baselines: gcache.New[string, *baseline](maxBaselines).LRU().Build()}
}

// Matches reports whether resp, received for requestURL, is the page the host
// serves for paths that do not exist.
//
// It only answers yes for 2xx and 3xx responses. A real 404 or 500 page is
// what the host says about every missing path, so a template that matches it
// found something true of the whole host, such as a version in an error page.
func (d *Detector) Matches(ctx context.Context, requestURL *url.URL, resp Response, probe Prober) bool {
	if d == nil || requestURL == nil || !redirectOrSuccess(resp.StatusCode) {
		return false
	}
	requestPath := requestURL.EscapedPath()
	if requestPath == "" || requestPath == "/" {
		return false
	}
	key, shape := shapeOf(requestURL)
	b := d.baseline(key)
	b.once.Do(func() { b.samples = collect(ctx, shape, probe) })
	if len(b.samples) == 0 {
		return false
	}
	got := fingerprintOf(resp, requestPath)
	for _, sample := range b.samples {
		if got.like(sample) {
			return true
		}
	}
	return false
}

func (d *Detector) baseline(key string) *baseline {
	d.mu.Lock()
	defer d.mu.Unlock()
	if b, err := d.baselines.GetIFPresent(key); err == nil {
		return b
	}
	b := &baseline{}
	_ = d.baselines.Set(key, b)
	return b
}

// collect fetches random paths of one shape. It returns nothing when the host
// answers honestly (4xx or 5xx) or so inconsistently that no single page
// stands for "not found"; both mean nothing can be discounted.
func collect(ctx context.Context, shape func(string) string, probe Prober) []fingerprint {
	fingerprints := make([]fingerprint, 0, samples)
	for range samples {
		probePath := shape(strings.ToLower(rand.Text()))
		resp, err := probe(ctx, probePath)
		if err != nil || !redirectOrSuccess(resp.StatusCode) {
			return nil
		}
		fingerprints = append(fingerprints, fingerprintOf(resp, probePath))
	}
	if !fingerprints[0].like(fingerprints[1]) {
		return nil
	}
	return fingerprints
}

// shapeOf returns the cache key for requestURL and a function that builds a
// path of the same shape around a random name: same origin, same extension or
// leading dot, same trailing slash, and nested when the request was.
//
// Probes start at the root rather than in the requested directory. An app
// mounted under a directory, such as Swagger UI under /api-docs/, answers
// every path below it with itself; probing there would mistake the app for
// the host's catch-all page.
func shapeOf(requestURL *url.URL) (string, func(string) string) {
	p := requestURL.EscapedPath()
	trailing := strings.HasSuffix(p, "/")
	p = strings.TrimSuffix(p, "/")
	dir, name := path.Split(p)
	if dir != "/" {
		dir = "/" + strings.ToLower(rand.Text()) + "/"
	}

	var kind string
	switch {
	case trailing:
		kind = "/"
	case strings.HasPrefix(name, "."):
		kind = "."
	default:
		kind = strings.ToLower(path.Ext(name))
	}
	key := requestURL.Scheme + "://" + requestURL.Host + "\x00" + kind + "\x00" + strconv.FormatBool(dir != "/")
	return key, func(random string) string {
		switch kind {
		case "/":
			return dir + random + "/"
		case ".":
			return dir + "." + random
		default:
			return dir + random + kind
		}
	}
}

func fingerprintOf(resp Response, requestPath string) fingerprint {
	body := normalise(resp.Body, requestPath)
	tokens := map[string]int{}
	total := 0
	for _, token := range strings.FieldsFunc(body, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) }) {
		tokens[token]++
		total++
	}
	return fingerprint{
		statusCode: resp.StatusCode,
		location:   normalise(resp.Location, requestPath),
		tokens:     tokens,
		total:      total,
	}
}

// normalise removes what differs between two answers for missing paths: the
// requested path echoed back in any of its usual encodings, and values that
// change on every load.
func normalise(s, requestPath string) string {
	if s == "" {
		return s
	}
	decoded, err := url.PathUnescape(requestPath)
	if err != nil {
		decoded = requestPath
	}
	variants := []string{
		requestPath,
		decoded,
		url.QueryEscape(decoded),
		url.PathEscape(decoded),
		html.EscapeString(decoded),
		strings.TrimPrefix(decoded, "/"),
	}
	// Longest first, so a full path is removed before a fragment of it.
	slices.SortFunc(variants, func(a, b string) int { return len(b) - len(a) })
	for _, v := range variants {
		// Removing a one or two letter path would erase unrelated text.
		if len(v) >= minReflection {
			s = strings.ReplaceAll(s, v, "")
		}
	}
	return dynamic.ReplaceAllString(s, "")
}

// like reports whether two fingerprints are the same page: same status, same
// redirect target and nearly the same words, compared as a Dice coefficient
// over word counts.
func (f fingerprint) like(other fingerprint) bool {
	if f.statusCode != other.statusCode || f.location != other.location {
		return false
	}
	if f.total == 0 || other.total == 0 {
		return f.total == other.total
	}
	shared := 0
	for token, count := range f.tokens {
		shared += min(count, other.tokens[token])
	}
	return 2*float64(shared)/float64(f.total+other.total) >= Threshold
}

func redirectOrSuccess(statusCode int) bool {
	return statusCode >= 200 && statusCode < 400
}

package catchall

import (
	"context"
	"crypto/rand"
	"errors"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/require"
)

const spaShell = `<!doctype html><html><head><title>Acme Dashboard</title><script src="/static/js/main.4f2a9c.js"></script></head><body><noscript>You need to enable JavaScript to run this app.</noscript><div id="root"></div></body></html>`

func mustURL(t *testing.T, raw string) *url.URL {
	t.Helper()
	u, err := url.Parse(raw)
	require.NoError(t, err)
	return u
}

// prober answers every probe with page and counts the probes.
func prober(page func(path string) Response) (Prober, *atomic.Int32) {
	var probes atomic.Int32
	return func(_ context.Context, path string) (Response, error) {
		probes.Add(1)
		return page(path), nil
	}, &probes
}

func TestSinglePageAppShellIsCatchAll(t *testing.T) {
	probe, _ := prober(func(string) Response { return Response{StatusCode: http.StatusOK, Body: spaShell} })
	d := New(0)

	got := d.Matches(context.Background(), mustURL(t, "http://acme.test/.env"), Response{StatusCode: http.StatusOK, Body: spaShell}, probe)
	require.True(t, got, "the shell served for a missing .env is not a finding")
}

func TestRealContentIsNotCatchAll(t *testing.T) {
	probe, _ := prober(func(string) Response { return Response{StatusCode: http.StatusOK, Body: spaShell} })
	d := New(0)

	env := Response{StatusCode: http.StatusOK, Body: "DB_HOST=db\nDB_PASSWORD=hunter2\nAPP_KEY=base64:abc"}
	require.False(t, d.Matches(context.Background(), mustURL(t, "http://acme.test/.env"), env, probe))
}

func TestHonestNotFoundIsNeverCatchAll(t *testing.T) {
	notFound := Response{StatusCode: http.StatusNotFound, Body: "<h1>404 Not Found</h1>"}
	probe, probes := prober(func(string) Response { return notFound })
	d := New(0)

	require.False(t, d.Matches(context.Background(), mustURL(t, "http://acme.test/.env"), notFound, probe),
		"a 404 page says the same about every path, so matching it is a host-wide finding")
	require.Zero(t, probes.Load(), "an error response is never compared, so it needs no baseline")

	ok := Response{StatusCode: http.StatusOK, Body: "DB_PASSWORD=hunter2"}
	require.False(t, d.Matches(context.Background(), mustURL(t, "http://acme.test/.env"), ok, probe))
	require.EqualValues(t, 1, probes.Load(), "a host that answers 404 stops the baseline at the first probe")
}

func TestRootIsNeverProbed(t *testing.T) {
	probe, probes := prober(func(string) Response { return Response{StatusCode: http.StatusOK, Body: spaShell} })
	d := New(0)

	for _, raw := range []string{"http://acme.test", "http://acme.test/", "http://acme.test/?q=1"} {
		require.False(t, d.Matches(context.Background(), mustURL(t, raw), Response{StatusCode: http.StatusOK, Body: spaShell}, probe), raw)
	}
	require.Zero(t, probes.Load(), "the home page is the page itself, not an answer for a missing path")
}

func TestReflectedPathIsIgnored(t *testing.T) {
	page := func(path string) Response {
		return Response{
			StatusCode: http.StatusFound,
			Location:   "/login?redirectTo=" + url.QueryEscape(path),
			Body:       `<a href="/login?redirectTo=` + url.QueryEscape(path) + `">Found</a>. Page ` + path + ` needs a login.`,
		}
	}
	probe, _ := prober(page)
	d := New(0)

	got := d.Matches(context.Background(), mustURL(t, "http://acme.test/.git/config"), page("/.git/config"), probe)
	require.True(t, got, "a login redirect that echoes the path is the same answer for every path")
}

func TestUnstableHostIsNotCalibrated(t *testing.T) {
	probe, _ := prober(func(string) Response {
		return Response{StatusCode: http.StatusOK, Body: strings.Repeat(rand.Text()+" ", 20)}
	})
	d := New(0)

	got := d.Matches(context.Background(), mustURL(t, "http://acme.test/admin"), Response{StatusCode: http.StatusOK, Body: "Admin console"}, probe)
	require.False(t, got, "a host with no stable answer for missing paths gives nothing to discount")
}

func TestDynamicTokensAreIgnored(t *testing.T) {
	page := func() Response {
		return Response{StatusCode: http.StatusOK, Body: spaShell + `<meta name="csrf" content="` + rand.Text() + `"> rendered at ` + "1730000000123"}
	}
	probe, _ := prober(func(string) Response { return page() })
	d := New(0)

	require.True(t, d.Matches(context.Background(), mustURL(t, "http://acme.test/backup.zip"), page(), probe))
}

func TestBaselineIsSharedPerShape(t *testing.T) {
	probe, probes := prober(func(string) Response { return Response{StatusCode: http.StatusOK, Body: spaShell} })
	d := New(0)
	shell := Response{StatusCode: http.StatusOK, Body: spaShell}
	ctx := context.Background()

	d.Matches(ctx, mustURL(t, "http://acme.test/a.php"), shell, probe)
	d.Matches(ctx, mustURL(t, "http://acme.test/b.php"), shell, probe)
	require.EqualValues(t, samples, probes.Load(), "templates hitting the same shape reuse one baseline")

	d.Matches(ctx, mustURL(t, "http://acme.test/a.json"), shell, probe)
	d.Matches(ctx, mustURL(t, "http://acme.test/admin/a.php"), shell, probe)
	d.Matches(ctx, mustURL(t, "http://acme.test/api/v1/b.php"), shell, probe)
	d.Matches(ctx, mustURL(t, "https://acme.test/a.php"), shell, probe)
	require.EqualValues(t, 4*samples, probes.Load(), "another extension, nesting or origin may be routed elsewhere")
}

func TestProbeShapes(t *testing.T) {
	cases := map[string]*regexp.Regexp{
		"http://acme.test/.env":               regexp.MustCompile(`^/\.RANDOM$`),
		"http://acme.test/admin/":             regexp.MustCompile(`^/RANDOM/$`),
		"http://acme.test/Backup.ZIP":         regexp.MustCompile(`^/RANDOM\.zip$`),
		"http://acme.test/wp-admin/x.php?a=1": regexp.MustCompile(`^/[a-z2-7]{26}/RANDOM\.php$`),
		"http://acme.test/actuator/env":       regexp.MustCompile(`^/[a-z2-7]{26}/RANDOM$`),
	}
	for raw, want := range cases {
		_, shape := shapeOf(mustURL(t, raw))
		require.Regexp(t, want, shape("RANDOM"), raw)
	}
}

// Swagger UI mounted at /api-docs/ answers every path below it with itself.
// Probing inside that directory would call a real exposure a catch-all page.
func TestAppMountedInDirectoryIsNotCatchAll(t *testing.T) {
	const swaggerUI = `<html><head><title>Swagger UI</title></head><body><div id="swagger-ui"></div><script src="swagger-ui-bundle.js"></script></body></html>`
	probe, _ := prober(func(path string) Response {
		if strings.HasPrefix(path, "/api-docs/") {
			return Response{StatusCode: http.StatusOK, Body: swaggerUI}
		}
		return Response{StatusCode: http.StatusOK, Body: spaShell}
	})
	d := New(0)

	got := d.Matches(context.Background(), mustURL(t, "http://acme.test/api-docs/swagger.json"), Response{StatusCode: http.StatusOK, Body: swaggerUI}, probe)
	require.False(t, got)
}

func TestFailedProbeDisablesCalibration(t *testing.T) {
	d := New(0)
	probe := func(context.Context, string) (Response, error) { return Response{}, errors.New("connection reset") }

	require.False(t, d.Matches(context.Background(), mustURL(t, "http://acme.test/.env"), Response{StatusCode: http.StatusOK, Body: spaShell}, probe))
}

package http

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/internal/tests/testutils"
	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/stringslice"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/http/catchall"
)

const appShell = `<!doctype html><html><head><title>Acme</title></head><body><div id="root"></div></body></html>`

// singlePageApp serves its shell for every path except the files it really
// has, and counts the requests it receives.
func singlePageApp(t *testing.T, files map[string]string) (*httptest.Server, *atomic.Int32) {
	t.Helper()
	var requests atomic.Int32
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests.Add(1)
		if body, ok := files[r.URL.Path]; ok {
			_, _ = w.Write([]byte(body))
			return
		}
		_, _ = w.Write([]byte(appShell))
	}))
	t.Cleanup(ts.Close)
	return ts, &requests
}

// matchesEnv runs a loose .env template, the kind that fires on any HTML page,
// and reports whether it produced a result.
func matchesEnv(t *testing.T, target string, detector *catchall.Detector, tags string, word string) bool {
	t.Helper()
	options := testutils.DefaultOptions.Copy()
	options.SetExecutionID(t.Name())
	testutils.Init(options)
	t.Cleanup(func() { testutils.Cleanup(options) })

	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "loose-env",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.High}, Name: "loose-env", Tags: stringslice.StringSlice{Value: []string{tags}}},
	})
	executerOpts.CatchAll = detector
	request := &Request{
		Path:   []string{"{{BaseURL}}/.env"},
		Method: HTTPMethodTypeHolder{MethodType: HTTPGet},
		Operators: operators.Operators{Matchers: []*matchers.Matcher{
			{Type: matchers.MatcherTypeHolder{MatcherType: matchers.StatusMatcher}, Status: []int{http.StatusOK}},
			{Type: matchers.MatcherTypeHolder{MatcherType: matchers.WordsMatcher}, Words: []string{word}},
		}, MatchersCondition: "and"},
	}
	require.NoError(t, request.Compile(executerOpts))

	var matched bool
	err := request.ExecuteWithResults(contextargs.NewWithInput(context.Background(), target), output.InternalEvent{}, output.InternalEvent{}, func(event *output.InternalWrappedEvent) {
		matched = matched || event.HasResults()
	})
	require.NoError(t, err)
	return matched
}

func TestCatchAllPageMatchIsDropped(t *testing.T) {
	ts, _ := singlePageApp(t, nil)

	require.True(t, matchesEnv(t, ts.URL, nil, "exposure", "<html"), "without calibration the app shell passes for .env")
	require.False(t, matchesEnv(t, ts.URL, catchall.New(0), "exposure", "<html"))
}

func TestRealFileOnCatchAllHostIsKept(t *testing.T) {
	ts, _ := singlePageApp(t, map[string]string{"/.env": "DB_HOST=db\nDB_PASSWORD=hunter2\n"})

	require.True(t, matchesEnv(t, ts.URL, catchall.New(0), "exposure", "DB_PASSWORD"))
}

func TestHostWideTemplateKeepsCatchAllMatch(t *testing.T) {
	ts, _ := singlePageApp(t, nil)

	require.True(t, matchesEnv(t, ts.URL, catchall.New(0), "tech", `<title>Acme</title>`), "the app is still Acme on its catch-all page")
}

func TestNoMatchSendsNoProbes(t *testing.T) {
	ts, requests := singlePageApp(t, nil)

	require.False(t, matchesEnv(t, ts.URL, catchall.New(0), "exposure", "DB_PASSWORD"))
	require.EqualValues(t, 1, requests.Load(), "calibration only probes a host once a template matched")
}

package http

import (
	"fmt"
	"strings"

	"github.com/cespare/xxhash"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
)

// TmplClusterKey generates a unique key for the request
// to be used in the clustering process.
func (request *Request) TmplClusterKey() uint64 {
	inp := fmt.Sprintf("%s-%d-%t-%t-%t-%t-%s-%d", request.Method.String(), request.MaxRedirects, request.DisableCookie, request.Redirects, request.HostRedirects, request.ProtocolRedirects, strings.Join(request.Path, "-"), utils.MapHash(request.Headers))
	return xxhash.Sum64String(inp)
}

// IsClusterable returns true if the request is eligible to be clustered.
// A cluster sends its first member's request for every member, so a block that
// sends race_count copies would force its count on the others, or lose it to a
// plain first member (#8280). Without race_count, race sends what a plain block
// sends. A pipelined block is never clustered: the pipeline client writes its
// request differently from a plain block's, so a cluster would send one kind
// for the other.
func (request *Request) IsClusterable() bool {
	//nolint
	return !(len(request.Payloads) > 0 || len(request.Fuzzing) > 0 || len(request.Raw) > 0 || len(request.Body) > 0 || request.Unsafe || request.Pipeline || request.NeedsRequestCondition() || request.Name != "" || request.readsRawResponse || request.sendsRaceCopies())
}

package http

import (
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/stretchr/testify/require"
)

func TestCanCluster(t *testing.T) {
	req := &Request{Unsafe: true}
	require.False(t, req.IsClusterable(), "could cluster unsafe request")

	req = &Request{Path: []string{"{{BaseURL}}"}, Method: HTTPMethodTypeHolder{MethodType: HTTPGet}}
	newReq := &Request{Path: []string{"{{BaseURL}}"}, Method: HTTPMethodTypeHolder{MethodType: HTTPGet}}
	require.True(t, req.IsClusterable(), "could not cluster GET request")
	require.True(t, req.IsClusterable(), "could not cluster GET request")
	require.Equal(t, req.TmplClusterKey(), newReq.TmplClusterKey(), "cluster keys should be equal")
}

func TestIsClusterable(t *testing.T) {
	t.Run("simple GET is clusterable", func(t *testing.T) {
		req := &Request{Path: []string{"{{BaseURL}}"}, Method: HTTPMethodTypeHolder{MethodType: HTTPGet}}
		require.True(t, req.IsClusterable())
	})

	t.Run("payloads prevent clustering", func(t *testing.T) {
		req := &Request{
			Path:     []string{"{{BaseURL}}"},
			Method:   HTTPMethodTypeHolder{MethodType: HTTPGet},
			Payloads: map[string]interface{}{"user": "admin"},
		}
		require.False(t, req.IsClusterable())
	})

	t.Run("fuzzing prevents clustering", func(t *testing.T) {
		req := &Request{
			Path:    []string{"{{BaseURL}}"},
			Method:  HTTPMethodTypeHolder{MethodType: HTTPGet},
			Fuzzing: []*fuzz.Rule{{}},
		}
		require.False(t, req.IsClusterable())
	})

	t.Run("raw requests prevent clustering", func(t *testing.T) {
		req := &Request{
			Raw: []string{"GET / HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"},
		}
		require.False(t, req.IsClusterable())
	})

	t.Run("body prevents clustering", func(t *testing.T) {
		req := &Request{
			Path:   []string{"{{BaseURL}}"},
			Method: HTTPMethodTypeHolder{MethodType: HTTPPost},
			Body:   "key=value",
		}
		require.False(t, req.IsClusterable())
	})

	t.Run("unsafe prevents clustering", func(t *testing.T) {
		req := &Request{Unsafe: true, Raw: []string{"GET / HTTP/1.1\r\n\r\n"}}
		require.False(t, req.IsClusterable())
	})

	t.Run("named request prevents clustering", func(t *testing.T) {
		req := &Request{
			Path:   []string{"{{BaseURL}}"},
			Method: HTTPMethodTypeHolder{MethodType: HTTPGet},
			Name:   "login-check",
		}
		require.False(t, req.IsClusterable())
	})

	t.Run("redirects do not prevent clustering", func(t *testing.T) {
		req := &Request{
			Path:      []string{"{{BaseURL}}"},
			Method:    HTTPMethodTypeHolder{MethodType: HTTPGet},
			Redirects: true,
		}
		require.True(t, req.IsClusterable())
	})

	t.Run("protocol-redirects do not prevent clustering", func(t *testing.T) {
		req := &Request{
			Path:              []string{"{{BaseURL}}"},
			Method:            HTTPMethodTypeHolder{MethodType: HTTPGet},
			Redirects:         true,
			ProtocolRedirects: true,
		}
		require.True(t, req.IsClusterable())
	})
}

// A cluster sends its first member's request for every member, so a race block
// would force its race_count on the others, or lose it to a plain one (#8280).
//
//nolint:exhaustruct,exhaustruct_v5 // fixtures keep zero-value defaults
func TestIsClusterableRace(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		race        bool
		count       int
		pipeline    bool
		clusterable bool
	}{
		{name: "race with race_count is not clusterable", race: true, count: 5},
		// without race_count, race runs as any other block
		{name: "race without race_count is clusterable", race: true, clusterable: true},
		// a pipelined block sends its request differently from a plain one
		{name: "race with race_count in a pipeline is not clusterable", race: true, count: 5, pipeline: true},
		{name: "pipeline is not clusterable", pipeline: true},
		{name: "race_count without race is clusterable", count: 5, clusterable: true},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			req := &Request{
