func (e Request) JSONSchemaExtend(schema *jsonschema.Schema) {
	headersSchema, ok := schema.Properties.Get("headers")
	if !ok {
		return
	}
	headersSchema.PatternProperties = map[string]*jsonschema.Schema{
		".*": {
			OneOf: []*jsonschema.Schema{
				{
					Type: "string",
				},
				{
					Type: "integer",
				},
				{
					Type: "boolean",
				},
			},
		},
	}
	headersSchema.Ref = ""
}

