// GetID returns the unique ID of the request if any.
func (request *Request) GetID() string {
	return request.ID
}

func (request *Request) isRaw() bool {
	return len(request.Raw) > 0
}

// Compile compiles the protocol request for further execution.
func (request *Request) Compile(options *protocols.ExecutorOptions) error {
	if err := request.validate(); err != nil {
		return errors.Wrap(err, "validation error")
	}

	// Analyze connection reuse policy to determine if we can safely reuse connections
	forceHTTP2 := options.Options != nil && options.Options.ForceAttemptHTTP2
	reusePolicy := request.AnalyzeConnectionReuse(forceHTTP2)
	request.connectionReusePolicy = reusePolicy

	// Determine if keep-alive should be disabled
	// If policy is ReuseUnsafe, we must disable keep-alive to preserve existing behavior
	// Otherwise, use the standard logic (which may enable keep-alive)
	var disableKeepAlive bool
	switch reusePolicy {
	case ReuseUnsafe:
		// Preserve existing behavior: disable keep-alive for unsafe requests
		disableKeepAlive = true
	case ReuseSafe:
		// Enable keep-alive for safe requests to allow connection pooling
		disableKeepAlive = false
	default:
		// ReuseUnknown: keep-alive stays enabled so the per-host client pool can
		// reuse connections (matches the default pooling behavior)
		disableKeepAlive = false
	}

	connectionConfiguration := &httpclientpool.Configuration{
		Threads:          request.Threads,
		MaxRedirects:     request.MaxRedirects,
		NoTimeout:        false,
		DisableCookie:    request.DisableCookie,
		DisableHTTPCache: request.DisableHTTPCache,
		Connection: &httpclientpool.ConnectionConfiguration{
			DisableKeepAlive: disableKeepAlive,
		},
		RedirectFlow: httpclientpool.DontFollowRedirect,
	}
	var customTimeout int
	if request.Analyzer != nil && request.Analyzer.Name == "time_delay" {
		var timeoutVal int
		if timeout, ok := request.Analyzer.Parameters["sleep_duration"]; ok {
			timeoutVal, _ = timeout.(int)
		} else {
			timeoutVal = 5
		}

		// Add 5x buffer to the timeout
		customTimeout = int(math.Ceil(float64(timeoutVal) * 5))
	}
	if customTimeout > 0 {
		connectionConfiguration.Connection.CustomMaxTimeout = time.Duration(customTimeout) * time.Second
	}

	if request.Redirects || options.Options.FollowRedirects {
		connectionConfiguration.RedirectFlow = httpclientpool.FollowAllRedirect
	}
	if request.HostRedirects || options.Options.FollowHostRedirects {
		connectionConfiguration.RedirectFlow = httpclientpool.FollowSameHostRedirect
	}
	if request.ProtocolRedirects {
		connectionConfiguration.RedirectFlow = httpclientpool.FollowSameSchemeRedirect
	}

	// If we have request level timeout, ignore http client timeouts
	for _, req := range request.Raw {
		if hasTimeoutAnnotation(req) {
			connectionConfiguration.NoTimeout = true
		}
	}
	request.connConfiguration = connectionConfiguration
	request.customHeaders = make(map[string]string)

	dialer, err := networkclientpool.Get(options.Options, &networkclientpool.Configuration{
		CustomDialer: options.CustomFastdialer,
	})
	if err != nil {
		return errors.Wrap(err, "could not get dialer")
	}
	request.dialer = dialer
	request.bodySize = &bodySizeEstimate{}

	request.options = options
	for _, option := range request.options.Options.CustomHeaders {
		parts := strings.SplitN(option, ":", 2)
		if len(parts) != 2 {
			continue
		}
		request.customHeaders[parts[0]] = strings.TrimSpace(parts[1])
	}

	if request.Body != "" && !strings.Contains(request.Body, "\r\n") {
		request.Body = strings.ReplaceAll(request.Body, "\n", "\r\n")
	}
	if len(request.Raw) > 0 {
		for i, raw := range request.Raw {
			if !strings.Contains(raw, "\r\n") {
				request.Raw[i] = strings.ReplaceAll(raw, "\n", "\r\n")
			}
		}
		request.rawhttpClient = httpclientpool.GetRawHTTP(options)
	}
	if options.Options != nil && options.Options.ReplayProxy != "" {
		client, err := newReplayClient(options.Options)
		if err != nil {
			return err
		}
		request.replayClient = client
	}
	if len(request.Matchers) > 0 || len(request.Extractors) > 0 {
		compiled := &request.Operators
		compiled.ExcludeMatchers = options.ExcludeMatchers
		compiled.TemplateID = options.TemplateID
		if compileErr := compiled.Compile(); compileErr != nil {
			return errors.Wrap(compileErr, "could not compile operators")
		}
		// llm operators only evaluate once they hold the scan's client; without
		// it every llm path returns a negative result instead of an error.
		protocols.BindLLMOperators(compiled, options)
		request.CompiledOperators = compiled
	}

	// === fuzzing filters ===== //

	if request.FuzzPreConditionOperator != "" {
		request.fuzzPreConditionOperator = matchers.ConditionTypes[request.FuzzPreConditionOperator]
	} else {
		request.fuzzPreConditionOperator = matchers.ORCondition
	}

	for _, filter := range request.FuzzPreCondition {
		if err := filter.CompileMatchers(); err != nil {
			return errors.Wrap(err, "could not compile matcher")
		}
	}

	if request.Analyzer != nil {
		if analyzer := analyzers.GetAnalyzer(request.Analyzer.Name); analyzer == nil {
			return errors.Errorf("analyzer %s not found", request.Analyzer.Name)
		}
	}

	// Resolve payload paths from vars if they exists
	for name, payload := range request.options.Options.Vars.AsMap() {
		payloadStr, ok := payload.(string)
		// check if inputs contains the payload
		var hasPayloadName bool
		// search for markers in all request parts
		var inputs []string
		inputs = append(inputs, request.Method.String(), request.Body)
		inputs = append(inputs, request.Raw...)
		for k, v := range request.customHeaders {
			inputs = append(inputs, fmt.Sprintf("%s: %s", k, v))
		}
		for k, v := range request.Headers {
			inputs = append(inputs, fmt.Sprintf("%s: %s", k, v))
		}

		for _, input := range inputs {
			if expressions.ContainsVariablesWithNames(map[string]interface{}{name: payload}, input) == nil {
				hasPayloadName = true
				break
			}
		}
		if ok && hasPayloadName && fileutil.FileExists(payloadStr) {
			if request.Payloads == nil {
				request.Payloads = make(map[string]interface{})
			}
			request.Payloads[name] = payloadStr
		}
	}

	// tries to drop unused payloads - by marshaling sections that might contain the payload
	unusedPayloads := make(map[string]struct{})
	requestSectionsToCheck := []interface{}{
		request.customHeaders, request.Headers, request.Matchers,
		request.Extractors, request.Body, request.Path, request.Raw, request.Fuzzing,
	}
	if requestSectionsToCheckData, err := json.Marshal(requestSectionsToCheck); err == nil {
		for payload := range request.Payloads {
			if bytes.Contains(requestSectionsToCheckData, []byte(payload)) {
				continue
			}
			unusedPayloads[payload] = struct{}{}
		}
	}
	for payload := range unusedPayloads {
		delete(request.Payloads, payload)
	}

	if len(request.Payloads) > 0 {
		request.generator, err = generators.New(request.Payloads, request.AttackType.Value, request.options.TemplatePath, request.options.Catalog, request.options.Options.AttackType, request.options.Options)
		if err != nil {
			return errors.Wrap(err, "could not parse payloads")
		}
	}
	request.options = options
	request.totalRequests = request.Requests()

	if len(request.Fuzzing) > 0 {
		if request.Unsafe {
			return errors.New("cannot use unsafe with http fuzzing templates")
		}
		for _, rule := range request.Fuzzing {
			if fuzzingMode := options.Options.FuzzingMode; fuzzingMode != "" {
				rule.Mode = fuzzingMode
			}
			if fuzzingType := options.Options.FuzzingType; fuzzingType != "" {
				rule.Type = fuzzingType
			}
			if err := rule.Compile(request.generator, request.options); err != nil {
				return errors.Wrap(err, "could not compile fuzzing rule")
			}
		}
	}
	if len(request.Payloads) > 0 {
		// Due to a known issue (https://github.com/projectdiscovery/nuclei/issues/5015),
		// dynamic extractors cannot be used with payloads. To address this,
		// execution is handled by the standard engine without concurrency,
		// achieved by setting the thread count to 0.

		// this limitation will be removed once we have a better way to handle dynamic extractors with payloads
		hasMultipleRequests := false
		if len(request.Raw)+len(request.Path) > 1 {
			hasMultipleRequests = true
		}
		// look for dynamic extractor ( internal: true with named extractor)
		hasNamedInternalExtractor := false
		for _, extractor := range request.Extractors {
			if extractor.Internal && extractor.Name != "" {
				hasNamedInternalExtractor = true
				break
			}
		}
		if hasNamedInternalExtractor && hasMultipleRequests {
			stats.Increment(SetThreadToCountZero)
			request.Threads = 0
		} else {
			// specifically for http requests high concurrency and threads will lead to memory exhaustion, hence reduce the maximum parallelism
			if protocolstate.IsLowOnMemory() {
				request.Threads = protocolstate.GuardThreadsOrDefault(request.Threads)
			}
			request.Threads = options.GetThreadsForNPayloadRequests(request.Requests(), request.Threads)
		}
	}

	// Avoid reusing client-side HTTP proxy connections for the legacy non-threaded spray path.
	if shouldDisableKeepAliveForHTTPProxy(request, options) {
		request.connConfiguration.Connection.DisableKeepAlive = true
	}
	request.sharesResponse = canShareResponse(request, options.Flow)
	request.readsRawResponse = request.readsRawResponse || reads(request, options.Flow, rawParts...)
	request.maySendElsewhere = sendsElsewhere(request)
	return nil
}

// MaySendElsewhere reports whether a request of the block may go to an address
// other than its target's, such as another port. It is false for a block that
// sends only to the target, and it is false before Compile.
func (e *Request) MaySendElsewhere() bool {
	return e.maySendElsewhere
}

// sendsElsewhere reports whether any request of the block may go to an address
// other than its target's. A false positive only moves the skip of a request to
// a down target from the engine to the request path, which then skips each
// request to that address instead of ending the block, so every form that is
// not known to stay at the target counts. That is a
// self-contained request, which names its own destination, a path that does
// not start with {{BaseURL}} or {{RootURL}}, or that continues them with
// anything but a path, query or fragment, such as a port, and a raw request
// with a @Host annotation. A raw request line names only a path to send to the
// target: raw.Parse drops the host and port of an absolute URL there.
func sendsElsewhere(request *Request) bool {
	return request.SelfContained ||
		slices.ContainsFunc(request.Path, pathMayLeaveTarget) ||
		slices.ContainsFunc(request.Raw, hasHostAnnotation)
}

// pathMayLeaveTarget reports whether path may go to an address other than the
// target's.
func pathMayLeaveTarget(path string) bool {
	for _, variable := range []string{"{{BaseURL}}", "{{RootURL}}"} {
		if rest, found := strings.CutPrefix(path, variable); found {
			return rest != "" && strings.IndexByte("/?#", rest[0]) < 0
		}
	}

	return true
}

// hasHostAnnotation reports whether rawRequest has a @Host annotation.
func hasHostAnnotation(rawRequest string) bool {
	annotations, _ := raw.SplitAnnotations(rawRequest)

	return reHostAnnotation.MatchString(annotations)
}

// rawParts hold a response as received, before content decoding.
var rawParts = []string{"raw_body", "raw_response"}

// KeepRawResponses makes every request of a template keep raw responses when
// any of them or the flow reads raw parts, as a request can read those of an
// earlier one. It is called before the requests are compiled.
func KeepRawResponses(requests []*Request, flow string) {
	if !slices.ContainsFunc(requests, func(request *Request) bool { return reads(request, flow, rawParts...) }) {
		return
	}
	for _, request := range requests {
		request.readsRawResponse = true
	}
}

// keepsRawResponse reports whether responses keep their bytes as received,
// for this request's raw parts or for global matchers reading its events.
func (request *Request) keepsRawResponse() bool {
	return request.readsRawResponse || request.options.GlobalMatchers.Reads(rawParts...)
}

// canShareResponse reports whether a response another template got for the
// same request is as good as sending it again. A shared response arrives at
// once, so nothing that measures time may take one: race requests, timing
// analyzers, and a request whose operators or flow read the duration.
func canShareResponse(request *Request, flow string) bool {
	return !request.Race && request.Analyzer == nil && !reads(request, flow, "duration")
}

// reads reports whether the operators or flow of request may read any of
// parts. The operators are searched whole, so a new field that can read a
// part, as LLM matcher inputs do, is covered without being listed.
func reads(request *Request, flow string, parts ...string) bool {
	operators, err := json.Marshal(request.Operators)
	if err != nil {
		return true
	}
	// A later request can read an earlier raw part from its own body, path,
	// headers, or raw request, not only from its operators.
	fields, err := json.Marshal(struct {
		Path    []string          `json:"path,omitempty"`
		Raw     []string          `json:"raw,omitempty"`
		Body    string            `json:"body,omitempty"`
		Headers map[string]string `json:"headers,omitempty"`
	}{request.Path, request.Raw, request.Body, request.Headers})
	if err != nil {
		return true
	}
	return slices.ContainsFunc(parts, func(part string) bool {
		needle := []byte(part)
		return strings.Contains(flow, part) || bytes.Contains(operators, needle) || bytes.Contains(fields, needle)
	})
}

// RebuildGenerator rebuilds the generator for the request
func (request *Request) RebuildGenerator() error {
	generator, err := generators.New(request.Payloads, request.AttackType.Value, request.options.TemplatePath, request.options.Catalog, request.options.Options.AttackType, request.options.Options)
	if err != nil {
		return errors.Wrap(err, "could not parse payloads")
	}
	request.generator = generator
	return nil
}

// Requests returns the total number of requests the YAML rule will perform
func (request *Request) Requests() int {
	// a race block sends race_count copies of its first request, however many
	// entries it has, and it does so before it looks at fuzzing rules
	if request.sendsRaceCopies() {
		return request.RaceNumberRequests
	}
	// fuzzing requests depend on each input's parameters and add themselves to
	// the total as they are sent; any path or raw is not sent as such
	if len(request.Fuzzing) > 0 {
		return 0
	}
	generator := request.newGenerator(false)
	return generator.Total()
}

const (
	SetThreadToCountZero = "set-thread-count-to-zero"
)

// ConnectionReusePolicy determines whether a request can safely reuse connections
type ConnectionReusePolicy int

const (
	// ReuseUnknown indicates the policy hasn't been analyzed yet
	ReuseUnknown ConnectionReusePolicy = iota
	// ReuseSafe indicates the request can safely reuse connections (enable connection pooling)
	ReuseSafe
	// ReuseUnsafe indicates the request must close connections (preserve existing behavior)
	ReuseUnsafe
)

func init() {
	stats.NewEntry(SetThreadToCountZero, "Setting thread count to 0 for %d templates, dynamic extractors are not supported with payloads yet")
}

// UpdateOptions replaces this request's options with a new copy
func (r *Request) UpdateOptions(opts *protocols.ExecutorOptions) {
	r.Operators = protocols.CloneOperators(r.Operators)
	r.FuzzPreCondition = protocols.CloneMatchers(r.FuzzPreCondition)
	if r.options == nil {
		if opts != nil {
			r.options = opts.Copy()
		}
		return
	}
	r.options = r.options.Copy()
	r.options.ApplyNewEngineOptions(opts)
}

// HasFuzzing indicates whether the request has fuzzing rules defined.
func (request *Request) HasFuzzing() bool {
	return len(request.Fuzzing) > 0
}

// shouldDisableKeepAliveForHTTPProxy preserves the pre-pooling behavior only for
// standard HTTP proxies in non-threaded template/auto spray scans.
func shouldDisableKeepAliveForHTTPProxy(request *Request, options *protocols.ExecutorOptions) bool {
	if request == nil || options == nil || options.Options == nil || options.Options.AliveHttpProxy == "" {
		return false
	}
	return request.Threads <= 0 && options.Options.ScanStrategy != scanstrategy.HostSpray.String()
}

// AnalyzeConnectionReuse determines if a request can safely reuse connections.
// Returns ReuseUnsafe if connection closure is required, ReuseSafe otherwise.
// This analysis ensures backward compatibility by preserving connection-close behavior
// when necessary while enabling connection pooling for other requests.
//
// forceHTTP2 reports whether HTTP/2 may be negotiated (only possible when the
// user enables it, since the pooled transport sets custom dial hooks). It only
// affects the time_delay analyzer decision below.
func (r *Request) AnalyzeConnectionReuse(forceHTTP2 bool) ConnectionReusePolicy {
	// Priority 0: race requests need dedicated connections. Race uses a
	// one-shot synced body gate that breaks if a connection is reused and the
	// body is re-read, and reusing a single keep-alive connection would also
	// serialize the requests and defeat the race.
	//
	// Pipelined requests are not listed: the pipeline client dials its own
	// connections, so the pool never serves them. ReuseUnsafe would only add
	// "Connection: close" to each request, and the server would then close the
	// connection that the block's other requests are waiting on.
	if r.Race {
		return ReuseUnsafe
	}

	// Priority 1: Check for explicit "Connection: close" header in raw requests
	for _, raw := range r.Raw {
		if hasConnectionCloseHeader(raw) {
			return ReuseUnsafe
		}
	}

	// Priority 2: Check for "Connection: close" in regular headers
	for key, value := range r.Headers {
		if strings.EqualFold(key, "Connection") && strings.Contains(strings.ToLower(value), "close") {
			return ReuseUnsafe
		}
	}

	// Priority 3: time-based analyzers. The time_delay analyzer measures only the
	// server-side window (httptrace WroteHeaders -> GotFirstResponseByte), so
	// connection setup is excluded from the timing. Under HTTP/1.1 net/http never
	// shares an in-flight connection, so keep-alive reuse saves handshakes without
	// affecting the measurement -> safe to reuse. Under HTTP/2 concurrent sleeping
	// probes can multiplex onto one connection and add timing jitter, so force
	// fresh connections only in that case to keep detection error-free.
	if r.Analyzer != nil && r.Analyzer.Name == "time_delay" {
		if forceHTTP2 {
			return ReuseUnsafe
		}
		return ReuseSafe
	}

	// Default: Safe to reuse - enable connection pooling
	return ReuseSafe
}

// hasConnectionCloseHeader checks if a raw HTTP request contains "Connection: close"
// Case-insensitive check for both "Connection:" and "close"
func hasConnectionCloseHeader(raw string) bool {
	rawLower := strings.ToLower(raw)
	// Check for "connection:" header
	if !strings.Contains(rawLower, "connection:") {
		return false
	}
	// Check for "close" value after "connection:"
	// Handle various formats: "Connection: close", "Connection:Close", "Connection: close\r\n", etc.
	connIdx := strings.Index(rawLower, "connection:")
	if connIdx == -1 {
		return false
	}
	// Extract the value after "connection:"
	valueStart := connIdx + len("connection:")
	// Skip whitespace
	for valueStart < len(rawLower) && (rawLower[valueStart] == ' ' || rawLower[valueStart] == '\t') {
		valueStart++
	}
	// Check if the value contains "close"
	value := rawLower[valueStart:]
	// Find end of line or end of string
	if newlineIdx := strings.IndexAny(value, "\r\n"); newlineIdx != -1 {
		value = value[:newlineIdx]
	}
	return strings.Contains(value, "close")
}

// IsOriginScoped reports whether every request this block makes is fixed by the
// target's origin, so two targets differing only by path or query produce byte
// identical requests. Paths built from {{BaseURL}} or {{Path}} carry the
// target's own path and are therefore not origin scoped, and raw requests,
// payloads and fuzzing all vary the request independently of the origin.
func (request *Request) IsOriginScoped() bool {
	if len(request.Raw) > 0 || len(request.Path) == 0 {
		return false
	}
	if len(request.Payloads) > 0 || request.Fuzzing != nil {
		return false
	}
	for _, path := range request.Path {
		if !strings.Contains(path, "{{RootURL}}") || carriesTargetPath(path) {
			return false
		}
	}
	if carriesTargetPath(request.Body) {
		return false
	}
	for _, value := range request.Headers {
		if carriesTargetPath(value) {
			return false
		}
	}
	return true
}

// sendsRaceCopies reports whether the block sends race_count copies of its
// first request at once. Without race_count, or in a pipeline, a block with
// race set runs as any other.
func (e *Request) sendsRaceCopies() bool {
	return e.Race && !e.Pipeline && e.RaceNumberRequests > 0
}

// carriesTargetPath reports whether a value interpolates the target's own path.
func carriesTargetPath(value string) bool {
	return strings.Contains(value, "{{BaseURL}}") || strings.Contains(value, "{{Path}}")
}

package http

import (
	"errors"
	"strings"

	"github.com/invopop/jsonschema"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// HTTPMethodType is the type of the method specified
type HTTPMethodType int

// name:HTTPMethodType
const (
	// name:GET
	HTTPGet HTTPMethodType = iota + 1
	// name:HEAD
	HTTPHead
	// name:POST
	HTTPPost
	// name:PUT
	HTTPPut
	// name:DELETE
	HTTPDelete
	// name:CONNECT
	HTTPConnect
	// name:OPTIONS
	HTTPOptions
	// name:TRACE
	HTTPTrace
	// name:PATCH
	HTTPPatch
	// name:PURGE
	HTTPPurge
	// name:Debug
	HTTPDebug
	limit
)

// HTTPMethodMapping is a table for conversion of method from string.
var HTTPMethodMapping = map[HTTPMethodType]string{
	HTTPGet:     "GET",
	HTTPHead:    "HEAD",
	HTTPPost:    "POST",
	HTTPPut:     "PUT",
	HTTPDelete:  "DELETE",
	HTTPConnect: "CONNECT",
	HTTPOptions: "OPTIONS",
	HTTPTrace:   "TRACE",
	HTTPPatch:   "PATCH",
	HTTPPurge:   "PURGE",
	HTTPDebug:   "DEBUG",
}

// GetSupportedHTTPMethodTypes returns list of supported types
func GetSupportedHTTPMethodTypes() []HTTPMethodType {
	var result []HTTPMethodType
	for index := HTTPMethodType(1); index < limit; index++ {
		result = append(result, index)
	}
	return result
}

func toHTTPMethodTypes(valueToMap string) (HTTPMethodType, error) {
	normalizedValue := normalizeValue(valueToMap)
	for key, currentValue := range HTTPMethodMapping {
		if normalizedValue == currentValue {
			return key, nil
		}
	}
	return -1, errors.New("Invalid HTTP method verb: " + valueToMap)
}

func normalizeValue(value string) string {
	return strings.TrimSpace(strings.ToUpper(value))
}

func (t HTTPMethodType) String() string {
	return HTTPMethodMapping[t]
}

// HTTPMethodTypeHolder is used to hold internal type of the HTTP Method
type HTTPMethodTypeHolder struct {
	MethodType HTTPMethodType `mapping:"true"`
}

func (holder HTTPMethodTypeHolder) String() string {
	return holder.MethodType.String()
}

func (holder HTTPMethodTypeHolder) JSONSchema() *jsonschema.Schema {
	gotType := &jsonschema.Schema{
		Type:        "string",
		Title:       "method is the HTTP request method",
		Description: "Method is the HTTP Request Method",
	}
	for _, types := range GetSupportedHTTPMethodTypes() {
		gotType.Enum = append(gotType.Enum, types.String())
	}
	return gotType
}

func (holder *HTTPMethodTypeHolder) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var marshalledTypes string
	if err := unmarshal(&marshalledTypes); err != nil {
		return err
	}

	computedType, err := toHTTPMethodTypes(marshalledTypes)
	if err != nil {
		return err
	}

	holder.MethodType = computedType
	return nil
}

func (holder *HTTPMethodTypeHolder) UnmarshalJSON(data []byte) error {
	s := strings.Trim(string(data), `"`)
	if s == "" {
		return nil
	}
	computedType, err := toHTTPMethodTypes(s)
	if err != nil {
		return err
	}

	holder.MethodType = computedType
	return nil
}

func (holder *HTTPMethodTypeHolder) MarshalJSON() ([]byte, error) {
	return json.Marshal(holder.MethodType.String())
}

func (holder HTTPMethodTypeHolder) MarshalYAML() (interface{}, error) {
	return holder.MethodType.String(), nil
}

package http

import (
	"net"
	"net/url"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/internal/tests/testutils"
	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz/analyzers"
	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs" //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
)

func TestHTTPCompile(t *testing.T) {
	options := testutils.DefaultOptions
	options.CustomHeaders = []string{"User-Agent: test", "Hello: World"}

	testutils.Init(options)
	templateID := "testing-http"
	request := &Request{
		Name: "testing",
		Payloads: map[string]interface{}{
			"username": []string{"admin"},
			"password": []string{"admin", "guest", "password", "test", "12345", "123456"},
		},
		AttackType: generators.AttackTypeHolder{Value: generators.ClusterBombAttack},
		Raw: []string{`GET /manager/html HTTP/1.1
Host: {{Hostname}}
User-Agent: Nuclei - Open-source project (github.com/projectdiscovery/nuclei)
Connection: close
Authorization: Basic {{username + ':' + password}}
Accept-Encoding: gzip`},
	}
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   templateID,
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Low}, Name: "test"},
	})
	err := request.Compile(executerOpts)
	require.Nil(t, err, "could not compile http request")
	require.Equal(t, 6, request.Requests(), "could not get correct number of requests")
	require.Equal(t, map[string]string{"User-Agent": "test", "Hello": "World"}, request.customHeaders, "could not get correct custom headers")
}

// TestAnalyzeConnectionReuse guards the connection-reuse policy: requests that
// must not reuse pooled keep-alive connections (race, explicit
// "Connection: close", time-based analyzers) must be flagged ReuseUnsafe, while
// everything else stays ReuseSafe so dev's per-host pooling keeps connections alive.
func TestAnalyzeConnectionReuse(t *testing.T) {
	tests := []struct {
		name       string
		request    *Request
		forceHTTP2 bool
		want       ConnectionReusePolicy
	}{
		{
			name:    "plain request is safe",
			request: &Request{Path: []string{"{{BaseURL}}"}},
			want:    ReuseSafe,
		},
		{
			name:    "raw request without close is safe",
			request: &Request{Raw: []string{"GET / HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"}},
			want:    ReuseSafe,
		},
		{
			name:    "race is unsafe",
			request: &Request{Race: true, RaceNumberRequests: 5},
			want:    ReuseUnsafe,
		},
		{
			// the pipeline client keeps its own connections, and a close would
			// cut off the other requests pipelined on it
			name:    "pipeline is safe",
			request: &Request{Pipeline: true},
			want:    ReuseSafe,
		},
		{
			name:    "raw connection close is unsafe",
			request: &Request{Raw: []string{"GET / HTTP/1.1\r\nHost: {{Hostname}}\r\nConnection: close\r\n\r\n"}},
			want:    ReuseUnsafe,
		},
		{
			name:    "header connection close is unsafe",
			request: &Request{Headers: map[string]string{"Connection": "close"}},
			want:    ReuseUnsafe,
		},
		{
			// time_delay measures the server-side window only, so HTTP/1.1 reuse is
			// measurement-safe and lets time-based fuzzing reuse connections.
			name:    "time_delay is safe under http1",
			request: &Request{Analyzer: &analyzers.AnalyzerTemplate{Name: "time_delay"}},
			want:    ReuseSafe,
		},
		{
			// Under HTTP/2 concurrent sleeping probes can multiplex and add jitter,
			// so fresh connections are required to keep detection error-free.
			name:       "time_delay is unsafe under http2",
			request:    &Request{Analyzer: &analyzers.AnalyzerTemplate{Name: "time_delay"}},
			forceHTTP2: true,
			want:       ReuseUnsafe,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			require.Equal(t, tt.want, tt.request.AnalyzeConnectionReuse(tt.forceHTTP2))
		})
	}
}

const (
	rawGet    = "GET /x HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"
	rawTarget = "127.0.0.1:443"

	rawBaseURL       = "GET {{BaseURL}}/x HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"
	rawSelfContained = "GET http://other.test:8080/x HTTP/1.1\r\nHost: other.test\r\n\r\n"
)

// maySendElsewhereTests lists requests with whether they may leave the address
// of their target, https://127.0.0.1.
//
//nolint:exhaustruct,exhaustruct_v5,gochecknoglobals // a table in a function exceeds funlen
var maySendElsewhereTests = []struct {
	name    string
	request *Request
	want    bool
}{
	{name: "no requests", request: &Request{}},
	{name: "base url", request: &Request{Path: []string{"{{BaseURL}}"}}},
	{name: "base url path", request: &Request{Path: []string{"{{BaseURL}}/a1"}}},
	{name: "root url path", request: &Request{Path: []string{"{{RootURL}}/a1"}}},
	{name: "base url query", request: &Request{Path: []string{"{{BaseURL}}?a=1"}}},
	{name: "base url fragment", request: &Request{Path: []string{"{{BaseURL}}#a"}}},
	{name: "base url with a port", request: &Request{Path: []string{"{{BaseURL}}:8080/a"}}, want: true},
	{name: "root url with a port", request: &Request{Path: []string{"{{RootURL}}:8080/a"}}, want: true},
	{
		name:    "base url with a port variable",
		request: &Request{Path: []string{"{{BaseURL}}:{{port}}/a"}, Payloads: map[string]any{"port": []string{"8080"}}},
		want:    true,
	},
	{name: "base url with user info", request: &Request{Path: []string{"{{BaseURL}}@other.test/a"}}, want: true},
	{name: "base url that extends the host", request: &Request{Path: []string{"{{BaseURL}}.other.test/a"}}, want: true},
	{name: "host with a port", request: &Request{Path: []string{"http://{{Host}}:18081/"}}, want: true},
	{name: "absolute url", request: &Request{Path: []string{"http://other.test/"}}, want: true},
	{name: "hostname", request: &Request{Path: []string{"{{Hostname}}/a"}}, want: true},
	{
		name:    "one path of two sends elsewhere",
		request: &Request{Path: []string{"{{BaseURL}}/a2", "http://{{Host}}:18081/"}},
		want:    true,
	},
	{name: "raw request", request: &Request{Raw: []string{rawGet}}},
	{name: "raw with a host header", request: &Request{Raw: []string{"GET /x HTTP/1.1\r\nHost: other.test\r\n\r\n"}}},
	{name: "raw with a base url", request: &Request{Raw: []string{rawBaseURL}}},
	{
		// the host and port of an absolute request target are dropped
		name:    "raw with an absolute url",
		request: &Request{Raw: []string{"GET http://other.test:8080/x HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"}},
	},
	{
		name:    "unsafe raw with an absolute url",
		request: &Request{Unsafe: true, Raw: []string{"GET http://other.test:8080/x HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n"}},
	},
	{
		name:    "raw with a host annotation",
		request: &Request{Raw: []string{"@Host: other.test:8080\r\n" + rawGet}},
		want:    true,
	},
	{
		name:    "raw with a host annotation among others",
		request: &Request{Raw: []string{"@timeout: 5s\r\n@Host: {{Hostname}}:18081\r\n" + rawGet}},
		want:    true,
	},
	{
		name:    "unsafe raw with a host annotation",
		request: &Request{Unsafe: true, Raw: []string{"@Host: other.test:8080\r\n" + rawGet}},
		want:    true,
	},
	{name: "raw with a sni annotation", request: &Request{Raw: []string{"@tls-sni: other.test\r\n" + rawGet}}},
	{
		// only the lines before the request line are annotations
		name:    "host annotation after the request line",
		request: &Request{Raw: []string{rawGet + "@Host: other.test:8080\r\n"}},
	},
	{
		name:    "one raw of two sends elsewhere",
		request: &Request{Raw: []string{rawGet, "@Host: other.test:8080\r\n" + rawGet}},
		want:    true,
	},
	{
		// the request line names the destination
		name:    "self-contained raw",
		request: &Request{SelfContained: true, Raw: []string{rawSelfContained}},
		want:    true,
	},
}

// TestMaySendElsewhere checks which requests may leave the address of their
// target, and that a request that does leave it is never reported as staying:
// each case also builds its requests for https://127.0.0.1 and compares where
// they go.
func TestMaySendElsewhere(t *testing.T) {
	t.Parallel()

	// compiling a request sets up global protocol state, so compile one at a time
	var compileMu sync.Mutex

	options := testutils.DefaultOptions

	for _, test := range maySendElsewhereTests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			// Compile fills in the request, so each run compiles a copy
			request := *test.request

			compileMu.Lock()
			testutils.Init(options)

			info := &testutils.TemplateInfo{ID: "testing-elsewhere"} //nolint:exhaustruct,exhaustruct_v5 // only the id matters
			err := request.Compile(testutils.NewMockExecuterOptions(options, info))

			compileMu.Unlock()
			require.NoError(t, err)

			require.Equal(t, test.want, request.MaySendElsewhere())

			if request.SelfContained {
				return
			}

			for _, dest := range sentAddresses(t, &request) {
				if dest != rawTarget {
					require.True(t, request.MaySendElsewhere(), "a request goes to %s but is reported as staying", dest)
				}
			}
		})
	}
}

// sentAddresses returns the host and port each request of a compiled request
// block goes to for https://127.0.0.1.
func sentAddresses(t *testing.T, request *Request) []string {
	t.Helper()

	var addresses []string

	input := contextargs.NewWithInput(t.Context(), "https://127.0.0.1")
	generator := request.newGenerator(false)

	for {
		value, payloads, ok := generator.nextValue()
		if !ok {
			return addresses
		}

		generated, err := generator.Make(t.Context(), input, value, payloads, map[string]any{})
		require.NoError(t, err)

		sent, err := url.Parse(generated.URL())
		require.NoError(t, err)

		addresses = append(addresses, net.JoinHostPort(sent.Hostname(), portOf(sent)))
	}
}

// portOf returns the port u names, or the default port of its scheme.
func portOf(u *url.URL) string {
	if port := u.Port(); port != "" {
		return port
	}

	if u.Scheme == "http" {
		return "80"
	}

	return "443"
}

// Package httpcache provides RFC 9111 compliant HTTP response caching for nuclei.
// It wraps http.RoundTripper to cache responses based on standard HTTP caching headers.
package httpcache

import (
	"context"
	"errors"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/httpbody"
	"go.dw1.io/x/net/http/cache"
)

var (
	cacheMu sync.Mutex
	shared  *cache.Transport
)

// getCache returns the shared cache. The first call, and the first after
// Close, loads it from the snapshot that Close saved.
func getCache() *cache.Transport {
	cacheMu.Lock()

	defer cacheMu.Unlock()
	if shared == nil {
		shared = openCache(snapshotPath())
	}

	return shared
}

// Close saves the shared cache to its snapshot and releases it. Safe if the
// cache was never opened.
func Close() {
	cacheMu.Lock()
	defer cacheMu.Unlock()

	if shared == nil {
		return
	}

	if err := saveSnapshot(shared, snapshotPath()); err != nil {
		gologger.Warning().Msgf("HTTP cache: could not save snapshot: %s", err)
	}

	stats := shared.Stats()
	gologger.Verbose().Msgf(
		"HTTP cache: %d hits, %d revalidated, %d misses, %d bypassed, %d stored or loaded, %d evicted, %d dropped",
		stats.Hits, stats.Revalidations, stats.Misses, stats.Bypasses, stats.Stores, stats.Evictions, stats.Drops)

	shared = nil
}

// NewTransportWrapper returns a function that wraps an [http.RoundTripper] with
// caching.
//
// This is designed to be used with retryablehttp's WrapTransport option.
func NewTransportWrapper() func(http.RoundTripper) http.RoundTripper {
	c := getCache()

	// Within one engine, the per-host clients' transports have the same TLS,
	// proxy, and compression settings. Nuclei accepts that the clients
	// sharing the cache still break some of WithNext's requirements:
	//   - Clients pinned to different IPs for one hostname reach different
	//     servers, yet one IP's response answers the same URL for the others.
	//   - SDK engines with different proxy or TLS options share the cache,
	//     which is process-wide.
	// Requests that carry Authorization, Cookie, or Origin skip the cache.
	// Those fields are not part of the cache key, so storing one of them
	// would let a later request without those credentials reuse the response.
	return func(rt http.RoundTripper) http.RoundTripper {
		return newCachingTransport(c, rt)
	}
}

// transport sends requests through a cache.Transport that shares the shared
// cache's stored responses.
type transport struct {
	cache *cache.Transport
	next  http.RoundTripper
}

// originContact records whether RoundTrip reached the next RoundTripper.
// A pure cache hit leaves origin false. The cache clones the request and
// keeps this pointer in the context, including on revalidation.
type originContact struct {
	origin    bool
	setCookie []string
}

type originContactKey struct{}

// originMarker sets origin before the request reaches the live transport.
type originMarker struct {
	next http.RoundTripper
}

func (m originMarker) RoundTrip(req *http.Request) (*http.Response, error) {
	contact, _ := req.Context().Value(originContactKey{}).(*originContact)
	if contact != nil {
		contact.origin = true
	}
	resp, err := m.next.RoundTrip(req)
	if err != nil || resp == nil || contact == nil {
		return resp, err
	}
	// The cache stores the header map it is given. Drop Set-Cookie before that
	// copy so one client's jar is not installed into another's. The caller gets
	// the values back on a header map the cache does not retain.
	contact.setCookie = takeSetCookies(resp.Header)
	return resp, nil
}

func newCachingTransport(base *cache.Transport, next http.RoundTripper) *transport {
	return &transport{cache: base.WithNext(originMarker{next: next}), next: next}
}

// Unwrap returns the transport the cache wraps, so code that must not use the
// cache, such as reporting clients that need TLS verification, can reach it.
func (t *transport) Unwrap() http.RoundTripper {
	return t.next
}

// carriesIdentity reports whether req has a credential or browser-origin
// field the cache key does not include. Header keys are compared
// case-insensitively because a builder can store a non-canonical key.
func carriesIdentity(req *http.Request) bool {
	return headerHas(req.Header, "Authorization") || headerHas(req.Header, "Cookie") || headerHas(req.Header, "Origin")
}

func headerHas(h http.Header, name string) bool {
	for key, values := range h {
		if len(values) > 0 && strings.EqualFold(key, name) {
			return true
		}
	}
	return false
}

func nonCanonicalHeader(h http.Header) bool {
	for key := range h {
		if key != http.CanonicalHeaderKey(key) {
			return true
		}
	}
	return false
}

func takeSetCookies(h http.Header) []string {
	var cookies []string
	for key, values := range h {
		if strings.EqualFold(key, "Set-Cookie") {
			cookies = append(cookies, values...)
			delete(h, key)
		}
	}
	return cookies
}

// ServedFromCache reports whether resp was answered from stored data without
// a request to the origin. Revalidated responses contacted the origin and
// report false.
func ServedFromCache(resp *http.Response) bool {
	if resp == nil || resp.Request == nil {
		return false
	}
	contact, ok := resp.Request.Context().Value(originContactKey{}).(*originContact)
	return ok && contact != nil && !contact.origin
}

// ContactedOrigin reports whether a completed attempt should move the
// per-host backoff governor. Project-file hits leave sent false. A pure
// HTTP cache hit leaves ServedFromCache true.
func ContactedOrigin(sent bool, resp *http.Response) bool {
	return sent && !ServedFromCache(resp)
}

func (t *transport) RoundTrip(req *http.Request) (*http.Response, error) {
	getOrHead := req.Method == "" || req.Method == http.MethodGet || req.Method == http.MethodHead
	// Credentialed and non-canonical GET/HEAD requests skip the cache. Unsafe
	// methods still go through it so a successful write invalidates the URI.
	if getOrHead && (carriesIdentity(req) || nonCanonicalHeader(req.Header)) {
		return t.next.RoundTrip(req)
	}

	switch req.Method {
	case "", http.MethodGet, http.MethodHead:
		// Request building installs an empty httpbody.Body on requests without
		// a body. The cache bypasses a GET or HEAD whose Body is neither nil nor
		// NoBody, since its length is unknown. Only for these methods does Go
		// send both bodies the same way: a POST with the empty httpbody.Body
		// goes chunked, and with NoBody it gets Content-Length: 0.
		if body, ok := req.Body.(*httpbody.Body); ok && body.Len() == 0 {
			cloned := req.Clone(req.Context())
			cloned.Body = http.NoBody
			req = cloned
		}
	}

	contact := &originContact{}
	req = req.Clone(context.WithValue(req.Context(), originContactKey{}, contact))
	resp, err := t.cache.RoundTrip(req)
	if err != nil || resp == nil || len(contact.setCookie) == 0 {
		return resp, err
	}
	restored := resp.Header.Clone()
	restored["Set-Cookie"] = contact.setCookie
	resp.Header = restored
	return resp, nil
}

func snapshotPath() string {
	return filepath.Join(config.DefaultConfig.GetCacheDir(), "httpcache", "snapshot")
}

// openCache returns a new cache holding the responses in the snapshot at path.
// The cache validates each loaded response with the origin before its first
// use. Requests go through the Transports that WithNext returns, never through
// the one openCache returns, so its next RoundTripper doesn't matter.
func openCache(path string) *cache.Transport {
	c, err := cache.New(nil)
	if err != nil {
		// New fails only for invalid options, and none are passed.
		panic(err)
	}

	if err := loadSnapshot(c, path); err != nil {
		gologger.Warning().Msgf("HTTP cache: could not load snapshot %q: %s", path, err)
	}

	gologger.Verbose().Msgf("HTTP cache initialized (snapshot %q)", path)

	return c
}

func loadSnapshot(c *cache.Transport, path string) error {
	f, err := os.Open(path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}

	if err != nil {
		return err
	}

	defer func() { _ = f.Close() }()

	return c.Load(f)
}

// saveSnapshot writes c to path through a temporary file, so that a nuclei
// process starting meanwhile never loads a partial snapshot.
func saveSnapshot(c *cache.Transport, path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}

	// CreateTemp creates the file with mode 0600. The snapshot holds whole
	// responses, including those to requests with Authorization or Cookie.
	tmp, err := os.CreateTemp(dir, ".snapshot-*")
	if err != nil {
		return err
	}

	err = errors.Join(c.Save(tmp), tmp.Close())
	if err == nil {
		err = os.Rename(tmp.Name(), path)
	}

	if err != nil {
		_ = os.Remove(tmp.Name())
	}

	return err
}

package httpcache

import (
	"crypto/tls"
