}

func TestCredentialedPostInvalidatesCache(t *testing.T) {
	var hits atomic.Int32
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := hits.Add(1)
		if r.Method == http.MethodGet {
			w.Header().Set("Cache-Control", "max-age=60")
		}
		_, _ = fmt.Fprintf(w, "%s %d", r.Method, n)
	}))
	t.Cleanup(ts.Close)

	rt := newCachingTransport(openCache(filepath.Join(t.TempDir(), "snapshot")), ts.Client().Transport)
	if body := bodyOf(t, roundTrip(t, rt, ts.URL, nil)); body != "GET 1" {
		t.Fatalf("first body = %q", body)
	}

	req, err := http.NewRequestWithContext(t.Context(), http.MethodPost, ts.URL, http.NoBody)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Authorization", "secret")
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = resp.Body.Close() })
	_ = bodyOf(t, resp)

	if body := bodyOf(t, roundTrip(t, rt, ts.URL, nil)); body != "GET 3" {
		t.Fatalf("body after credentialed POST = %q, want a fresh GET", body)
	}
}

func roundTrip(t *testing.T, rt http.RoundTripper, url string, header http.Header) *http.Response {
	t.Helper()
	req, err := http.NewRequestWithContext(t.Context(), http.MethodGet, url, nil)
	if err != nil {
		t.Fatal(err)
	}
	for name, values := range header {
		for _, value := range values {
			req.Header.Add(name, value)
		}
	}
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = resp.Body.Close() })
	return resp
}

func bodyOf(t *testing.T, resp *http.Response) string {
	t.Helper()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatal(err)
	}
	return string(body)
}

// Reporting clients send tokens, so tlsverify must reach the scan transport
// under the cache wrapper and turn certificate verification on.
func TestTransportWrapperUnwrapsForTLSVerification(t *testing.T) {
	c, err := cache.New(nil)
	if err != nil {
		t.Fatal(err)
	}

	base := &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}}
	var wrapped http.RoundTripper = newCachingTransport(c, base)
	u, ok := wrapped.(interface{ Unwrap() http.RoundTripper })
	if !ok || u.Unwrap() != base {
		t.Fatal("the cache wrapper does not unwrap to the scan transport")
	}

	got, ok := tlsverify.Client(&http.Client{Transport: wrapped}).Transport.(*http.Transport)
	if !ok || got.TLSClientConfig.InsecureSkipVerify {
		t.Fatal("tlsverify did not turn verification on under the cache wrapper")
	}
}

