package httpclientpool

import (
	"net/http/cookiejar"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"
	"golang.org/x/net/publicsuffix"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/retryablehttp-go"
)

// newTestOptions returns a fresh *types.Options with a unique ExecutionId so
// tests do not share the package-global dialers/HTTPClientPool state.
func newTestOptions(t *testing.T, executionId string) *types.Options {
	t.Helper()
	opts := types.DefaultOptions()
	opts.SetExecutionID(executionId)
	require.NoError(t, protocolstate.Init(opts))
	t.Cleanup(func() { protocolstate.Close(opts.ExecutionId) })
	return opts
}

// TestGet_HostScopedCache verifies that two Get() calls for the same host with
// the same configuration return the same cached *retryablehttp.Client, while
// different hosts produce different clients (per-host pool isolation).
func TestGet_HostScopedCache(t *testing.T) {
	opts := newTestOptions(t, "test-host-scoped-cache")
	cfg := &Configuration{}

	c1, err := Get(opts, cfg, "example.com")
	require.NoError(t, err)
	require.NotNil(t, c1)

	c2, err := Get(opts, cfg, "example.com")
	require.NoError(t, err)
	require.Same(t, c1, c2, "second Get() for the same host must hit the cache")

	c3, err := Get(opts, cfg, "other.example.com")
	require.NoError(t, err)
	require.NotSame(t, c1, c3, "different hosts must produce different clients")
}

// TestGet_ExplicitCookieJarBypassesCache verifies that callers passing an
// explicit per-request cookie jar always receive a fresh client (so per-request
// session state is never leaked into the shared pool).
func TestGet_ExplicitCookieJarBypassesCache(t *testing.T) {
	opts := newTestOptions(t, "test-explicit-jar-bypass")

	jar1, err := cookiejar.New(&cookiejar.Options{PublicSuffixList: publicsuffix.List})
	require.NoError(t, err)
	cfg1 := &Configuration{Connection: &ConnectionConfiguration{}}
	cfg1.Connection.SetCookieJar(jar1)

	c1, err := Get(opts, cfg1, "example.com")
	require.NoError(t, err)
	require.NotNil(t, c1)

	jar2, err := cookiejar.New(&cookiejar.Options{PublicSuffixList: publicsuffix.List})
	require.NoError(t, err)
	cfg2 := &Configuration{Connection: &ConnectionConfiguration{}}
	cfg2.Connection.SetCookieJar(jar2)

	c2, err := Get(opts, cfg2, "example.com")
	require.NoError(t, err)
	require.NotSame(t, c1, c2, "explicit cookie jars must always bypass the cache")
}

// TestGet_DisableKeepAliveAffectsCacheKey verifies that Configuration.Hash
// distinguishes clients that differ only in DisableKeepAlive, so the pool
// cannot return a client with the wrong keep-alive semantics.
func TestGet_DisableKeepAliveAffectsCacheKey(t *testing.T) {
	opts := newTestOptions(t, "test-disable-keepalive-hash")

	cfgKeepAliveOn := &Configuration{
		Connection: &ConnectionConfiguration{DisableKeepAlive: false},
	}
	cfgKeepAliveOff := &Configuration{
		Connection: &ConnectionConfiguration{DisableKeepAlive: true},
	}

	require.NotEqual(t, cfgKeepAliveOn.Hash(), cfgKeepAliveOff.Hash(),
		"Configuration.Hash() must encode DisableKeepAlive to avoid pool-key collisions")

	cOn, err := Get(opts, cfgKeepAliveOn, "example.com")
	require.NoError(t, err)
	cOff, err := Get(opts, cfgKeepAliveOff, "example.com")
	require.NoError(t, err)
	require.NotSame(t, cOn, cOff,
		"clients with different DisableKeepAlive must not share a cache entry")

	// Sanity check the underlying transport actually reflects the flag.
	require.NotNil(t, cOn.HTTPClient.Transport)
	require.NotNil(t, cOff.HTTPClient.Transport)
}

// TestGet_TransportSharedAcrossConfigurations verifies that clients whose
// configurations differ only in client-level settings (redirect policy,
// cookie handling) still share one underlying transport per host, so the
// host's connection pool is reused across templates.
func TestGet_TransportSharedAcrossConfigurations(t *testing.T) {
	opts := newTestOptions(t, "test-transport-shared")

	cfgNoRedirects := &Configuration{}
	cfgRedirects := &Configuration{MaxRedirects: 5, RedirectFlow: FollowAllRedirect}

	c1, err := Get(opts, cfgNoRedirects, "example.com")
	require.NoError(t, err)
	c2, err := Get(opts, cfgRedirects, "example.com")
	require.NoError(t, err)

	require.NotSame(t, c1, c2, "different configurations must produce different clients")
	require.Same(t, c1.HTTPClient.Transport, c2.HTTPClient.Transport,
		"clients differing only in client-level settings must share the per-host transport")

	c3, err := Get(opts, cfgNoRedirects, "other.example.com")
	require.NoError(t, err)
	require.NotSame(t, c1.HTTPClient.Transport, c3.HTTPClient.Transport,
		"different hosts must not share a transport")
}

// TestGet_ExplicitCookieJarSharesTransport verifies that uncached clients
// created for explicit per-request cookie jars still reuse the pooled
// per-host transport instead of opening their own connections.
func TestGet_ExplicitCookieJarSharesTransport(t *testing.T) {
	opts := newTestOptions(t, "test-explicit-jar-transport")

	cached, err := Get(opts, &Configuration{Connection: &ConnectionConfiguration{}}, "example.com")
	require.NoError(t, err)

	jar, err := cookiejar.New(&cookiejar.Options{PublicSuffixList: publicsuffix.List})
	require.NoError(t, err)
	cfg := &Configuration{Connection: &ConnectionConfiguration{}}
	cfg.Connection.SetCookieJar(jar)

	withJar, err := Get(opts, cfg, "example.com")
	require.NoError(t, err)

	require.NotSame(t, cached, withJar, "explicit jar must bypass the client cache")
	require.Same(t, cached.HTTPClient.Transport, withJar.HTTPClient.Transport,
		"explicit-jar clients must still share the pooled per-host transport")
}

// TestGet_ConcurrentSameHost verifies that concurrent first requests for the
// same (configuration, host) pair produce exactly one shared client.
func TestGet_ConcurrentSameHost(t *testing.T) {
	opts := newTestOptions(t, "test-concurrent-same-host")
	cfg := &Configuration{}

	const workers = 32
	clients := make([]*retryablehttp.Client, workers)
	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			c, err := Get(opts, cfg, "example.com")
			require.NoError(t, err)
			clients[idx] = c
		}(i)
	}
	wg.Wait()

	for i := 1; i < workers; i++ {
		require.Same(t, clients[0], clients[i], "concurrent Get() calls must return one shared client")
	}
}

// TestResetConnectionStats verifies the global counter reset used between
// in-process scans to keep per-run summaries accurate.
func TestResetConnectionStats(t *testing.T) {
	connStats.New.Store(7)
	connStats.Reused.Store(11)
	recordHostConn("example.com", false)

	ResetConnectionStats()

	newC, reused := GetConnectionStats()
	require.Equal(t, int64(0), newC, "new conn counter must be reset to 0")
	require.Equal(t, int64(0), reused, "reused conn counter must be reset to 0")
	require.Empty(t, GetPerHostConnectionStats(), "per-host stats must be cleared on reset")
}

// TestPerHostConnectionStats verifies that the per-host breakdown is recorded
// alongside the global counters from the shared GotConn hook.
func TestPerHostConnectionStats(t *testing.T) {
	ResetConnectionStats()
	t.Cleanup(ResetConnectionStats)

	recordHostConn("a.example.com", false)
	recordHostConn("a.example.com", true)
	recordHostConn("a.example.com", true)
	recordHostConn("b.example.com", false)
	recordHostConn("", true) // empty host must be ignored

	stats := GetPerHostConnectionStats()
	byHost := make(map[string]PerHostConnStat, len(stats))
	for _, s := range stats {
		byHost[s.Host] = s
	}

	require.Len(t, stats, 2, "only non-empty hosts should be tracked")
	require.Equal(t, int64(1), byHost["a.example.com"].New)
	require.Equal(t, int64(2), byHost["a.example.com"].Reused)
	require.Equal(t, int64(1), byHost["b.example.com"].New)
	require.Equal(t, int64(0), byHost["b.example.com"].Reused)
}

package httpclientpool

import (
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/retryablehttp-go"
)

// TestIdleConnPoolAllowsKeepAliveReuse is a regression test for the per-host
// idle connection pool being smaller than the concurrency that runs against a
// host.
//
// http.Transport closes a connection returned to a host whose idle pool is
// already full. When MaxIdleConnsPerHost was 4, a scan running templates
// concurrently against one host reused almost nothing: connections past the
// fourth were closed on return and the next request dialled again, so the
// target saw close to one TCP connection per HTTP request.
//
// The server counts accepted connections, which is what actually matters:
// connection churn is invisible in request counts but is what pays a TCP (and
// TLS) handshake per request and exhausts NAT port mappings.
func TestIdleConnPoolAllowsKeepAliveReuse(t *testing.T) {
	const (
		requests    = 400
		concurrency = 50
	)

	var accepted, arrived atomic.Int64

	// Hold the first `concurrency` requests inside the handler until all of
	// them have arrived, so the transport is genuinely forced to keep that
	// many connections open at once. Without this the requests could
	// serialise and the connection count would prove nothing.
	barrier := make(chan struct{})
	var releaseOnce sync.Once
	release := func() { releaseOnce.Do(func() { close(barrier) }) }
	// Safety valve: never hang the suite if fewer than `concurrency` requests
	// ever reach the handler.
	timer := time.AfterFunc(30*time.Second, release)
	defer timer.Stop()

	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if arrived.Add(1) >= concurrency {
			release()
		}
		<-barrier
		_, _ = w.Write([]byte("ok"))
	}))
	server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
		if state == http.StateNew {
			accepted.Add(1)
		}
	}
	server.Start()
	defer server.Close()

	opts := newTestOptions(t, "test-idle-conn-pool-reuse")
	opts.TemplateThreads = concurrency

	client, err := Get(opts, &Configuration{}, server.Listener.Addr().String())
	require.NoError(t, err)

	var succeeded atomic.Int64
	var errMu sync.Mutex
	var firstErr error

	sem := make(chan struct{}, concurrency)
	var wg sync.WaitGroup
	for i := 0; i < requests; i++ {
		wg.Add(1)
		sem <- struct{}{}
		go func(i int) {
			defer wg.Done()
			defer func() { <-sem }()

			recordErr := func(err error) {
				errMu.Lock()
				defer errMu.Unlock()
				if firstErr == nil {
					firstErr = err
				}
			}

			req, err := retryablehttp.NewRequest(http.MethodGet, fmt.Sprintf("%s/path-%d", server.URL, i), nil)
			if err != nil {
				recordErr(err)
				return
			}
			resp, err := client.Do(req)
			if err != nil {
				recordErr(err)
				return
			}
			// Drain and close so the connection is eligible for reuse.
			if _, err := io.Copy(io.Discard, resp.Body); err != nil {
				_ = resp.Body.Close()
				recordErr(err)
				return
			}
			if err := resp.Body.Close(); err != nil {
				recordErr(err)
				return
			}
			succeeded.Add(1)
		}(i)
	}
	wg.Wait()

	// Without these the connection assertion is vacuous: zero successful
	// requests also means zero connections.
	require.NoError(t, firstErr, "requests must succeed for the connection count to mean anything")
	require.Equal(t, int64(requests), succeeded.Load(), "all requests must succeed")
	require.GreaterOrEqual(t, arrived.Load(), int64(concurrency),
		"handler must have seen at least `concurrency` requests for the overlap barrier to have engaged")

	conns := accepted.Load()
	t.Logf("%d requests over %d connections (%.1f requests/connection)",
		requests, conns, float64(requests)/float64(conns))

	// `concurrency` connections are genuinely required by the barrier above.
	// Anything much beyond that is the pool discarding connections instead of
	// reusing them; the regression lands near one connection per request.
	require.LessOrEqual(t, conns, int64(concurrency*2),
		"connections should be bounded by concurrency, not by request count")
}

// TestIdleConnPoolSize covers the sizing rule itself: a floor that -c raises
// when it is larger, payload threads raising it too, and nothing either of them
// declares shrinking it.
func TestIdleConnPoolSize(t *testing.T) {
	for _, testCase := range []struct {
		name            string
		templateThreads int
		requestThreads  int
		want            int
	}{
		{name: "unset", templateThreads: 0, requestThreads: 0, want: defaultIdleConnPoolSize},
		{name: "default -c", templateThreads: 25, requestThreads: 0, want: defaultIdleConnPoolSize},
		{name: "-c 50", templateThreads: 50, requestThreads: 0, want: defaultIdleConnPoolSize},
		{name: "-c 800", templateThreads: 800, requestThreads: 0, want: 800},
		{name: "payload threads raise the pool", templateThreads: 25, requestThreads: 900, want: 900},
		{name: "payload threads never shrink the pool", templateThreads: 25, requestThreads: 2, want: defaultIdleConnPoolSize},
		{name: "payload threads never shrink -c 800", templateThreads: 800, requestThreads: 2, want: 800},
		{name: "negative payload threads never shrink the pool", templateThreads: 50, requestThreads: -1, want: defaultIdleConnPoolSize},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			got := idleConnPoolSize(testCase.templateThreads, testCase.requestThreads)
			require.Equal(t, testCase.want, got)
			require.GreaterOrEqual(t, got, defaultIdleConnPoolSize,
				"the floor exists because -c does not bound how many connections the transport opens")
			require.GreaterOrEqual(t, got, testCase.templateThreads,
				"the pool must never be smaller than the template concurrency it serves")
		})
	}
}

// TestIdleConnPoolSizeIsWiredToTransport checks that the size actually reaches
// the transport, not just the helper: a sizing rule that never lands on
// http.Transport would leave the reuse bug in place while the unit test above
// still passed.
func TestIdleConnPoolSizeIsWiredToTransport(t *testing.T) {
	opts := newTestOptions(t, "test-idle-conn-pool-wiring")
	opts.TemplateThreads = 800

	client, err := Get(opts, &Configuration{}, "example.com")
	require.NoError(t, err)

	sharing, ok := client.HTTPClient.Transport.(*sharingTransport)
	require.True(t, ok, "expected the shared-response transport wrapper")
	tracking, ok := sharing.base.(*connTrackingTransport)
	require.True(t, ok, "expected the connection-tracking transport wrapper")
	transport, ok := tracking.base.(*http.Transport)
	require.True(t, ok, "expected an *http.Transport underneath")

	require.Equal(t, 800, transport.MaxIdleConnsPerHost)
	require.Equal(t, 800, transport.MaxIdleConns)
}

// cyclicBarrier releases waiters in groups of n. A single-shot barrier only
// forces the FIRST group of requests to overlap, and a pool that is too small
// still looks fine afterwards, because once the requests stop overlapping a
// shallow pool is enough. Holding every group keeps the concurrency up for the
// whole run, which is what a scan does to a host.
type cyclicBarrier struct {
	mu        sync.Mutex
	n         int
	count     int
	gate      chan struct{}
	abandoned bool
}

func newCyclicBarrier(n int) *cyclicBarrier {
	return &cyclicBarrier{n: n, gate: make(chan struct{})}
}

func (b *cyclicBarrier) wait() {
	b.mu.Lock()
	if b.abandoned {
		b.mu.Unlock()
		return
	}
	b.count++
	gate := b.gate
	if b.count == b.n {
		b.count = 0
		b.gate = make(chan struct{})
		close(gate)
		b.mu.Unlock()
		return
	}
	b.mu.Unlock()
	<-gate
}

// abandon is the safety valve: it stops blocking so a shortfall fails on the
// assertions instead of hanging the suite.
func (b *cyclicBarrier) abandon() {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.abandoned {
		return
	}
	b.abandoned = true
	close(b.gate)
}

func (b *cyclicBarrier) wasAbandoned() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.abandoned
}

// TestIdleConnPoolAllowsKeepAliveReuseWithPayloadThreads covers the client that
// payload templates share. Configuration.Threads is part of the client cache
// key, so every template declaring the same payload thread count hashes to one
// entry and its workers pile onto a single pool -- templateThreads templates
// times payloadThreads workers each. That client has to reuse connections just
// like the default one, and a rule that sized the pool from a single template's
// threads would leave it far below the concurrency it actually serves.
func TestIdleConnPoolAllowsKeepAliveReuseWithPayloadThreads(t *testing.T) {
	const (
		templateThreads   = 10
		payloadThreads    = 5
		concurrency       = templateThreads * payloadThreads
		requestsPerWorker = 8
		requests          = concurrency * requestsPerWorker
	)

	var accepted atomic.Int64
	barrier := newCyclicBarrier(concurrency)
	timer := time.AfterFunc(30*time.Second, barrier.abandon)
	defer timer.Stop()

	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		barrier.wait()
		_, _ = w.Write([]byte("ok"))
	}))
	server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
		if state == http.StateNew {
			accepted.Add(1)
		}
	}
	server.Start()
	defer server.Close()

	opts := newTestOptions(t, "test-idle-conn-pool-payload-threads")
	opts.TemplateThreads = templateThreads

	// One client, as the engine would hand out: every payload template with
	// this thread count hashes to the same cache entry.
	client, err := Get(opts, &Configuration{Threads: payloadThreads}, server.Listener.Addr().String())
	require.NoError(t, err)

	var succeeded atomic.Int64
	var errMu sync.Mutex
	var firstErr error
	recordErr := func(err error) {
		errMu.Lock()
		defer errMu.Unlock()
		if firstErr == nil {
			firstErr = err
		}
	}

	// templateThreads templates in flight, each running payloadThreads workers.
	var wg sync.WaitGroup
	for template := 0; template < templateThreads; template++ {
		for worker := 0; worker < payloadThreads; worker++ {
			wg.Add(1)
			go func(template, worker int) {
				defer wg.Done()

				for i := 0; i < requestsPerWorker; i++ {
					req, err := retryablehttp.NewRequest(http.MethodGet,
						fmt.Sprintf("%s/t-%d/w-%d/%d", server.URL, template, worker, i), nil)
					if err != nil {
						recordErr(err)
						barrier.abandon()
						return
					}
					resp, err := client.Do(req)
					if err != nil {
						recordErr(err)
						barrier.abandon()
						return
					}
					if _, err := io.Copy(io.Discard, resp.Body); err != nil {
						_ = resp.Body.Close()
						recordErr(err)
						return
					}
					if err := resp.Body.Close(); err != nil {
						recordErr(err)
						return
					}
					succeeded.Add(1)
				}
			}(template, worker)
		}
	}
	wg.Wait()

	// Without these the connection assertion is vacuous: zero successful
	// requests also means zero connections.
	require.NoError(t, firstErr, "requests must succeed for the connection count to mean anything")
	require.Equal(t, int64(requests), succeeded.Load(), "all requests must succeed")
	require.False(t, barrier.wasAbandoned(),
		"the barrier must have held every group; the safety valve firing means the overlap was not sustained")

	conns := accepted.Load()
	t.Logf("%d requests over %d connections (%.1f requests/connection), pool=%d",
		requests, conns, float64(requests)/float64(conns),
		idleConnPoolSize(templateThreads, payloadThreads))

	require.LessOrEqual(t, conns, int64(concurrency*2),
		"connections should be bounded by the concurrency, not by the request count")
}

package httpclientpool

import (
	"crypto/tls"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"sync"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// Benchmarks measuring the end-to-end effect of per-host pooling delivered by
// this PR. Two scenarios are compared on the same workload of N hosts × M
// requests per host:
//
//   * "before": a single shared client with keep-alive disabled, mirroring
//     pre-PR behavior on a host-spray strategy where every request opened a
//     fresh connection.
//
//   * "after":  one client per host obtained from httpclientpool.Get(...,
//     hostname). Keep-alive is always enabled and idle connections are
//     reused by the per-host transport pool.
//
// Numbers are most striking for HTTPS, where avoiding the TLS handshake on
// every request dominates the runtime.

const (
	prBenchHosts        = 10
	prBenchRequestsHost = 20
)

func setupPRBenchOptions(b *testing.B, executionId string) *types.Options {
	b.Helper()
	opts := types.DefaultOptions()
	opts.SetExecutionID(executionId)
	require.NoError(b, protocolstate.Init(opts))
	b.Cleanup(func() { protocolstate.Close(opts.ExecutionId) })
	return opts
}

func startPRTLSServers(b *testing.B, n int) []*httptest.Server {
	b.Helper()
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = fmt.Fprint(w, "ok")
	})
	servers := make([]*httptest.Server, n)
	for i := range servers {
		servers[i] = httptest.NewTLSServer(handler)
	}
	b.Cleanup(func() {
		for _, s := range servers {
			s.Close()
		}
	})
	return servers
}

func startPRHTTPServers(b *testing.B, n int) []*httptest.Server {
	b.Helper()
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = fmt.Fprint(w, "ok")
	})
	servers := make([]*httptest.Server, n)
	for i := range servers {
		servers[i] = httptest.NewServer(handler)
	}
	b.Cleanup(func() {
		for _, s := range servers {
			s.Close()
		}
	})
	return servers
}

// hostFromURL extracts host:port from an httptest.Server.URL.
func hostFromURL(b *testing.B, raw string) string {
	b.Helper()
	u, err := url.Parse(raw)
	require.NoError(b, err)
	return u.Host
}

// sharedClientNoKeepAlive mirrors the pre-PR shared-client + keep-alive-OFF
// path, which forced a brand new connection (and a TLS handshake when
// applicable) on every request.
func sharedClientNoKeepAlive() *http.Client {
	tr := &http.Transport{
		DisableKeepAlives: true,
		TLSClientConfig:   &tls.Config{InsecureSkipVerify: true},
	}
	return &http.Client{Transport: tr, Timeout: 30 * time.Second}
}

// runBeforePR drives the workload with a single shared client and keep-alive
// disabled.
func runBeforePR(b *testing.B, servers []*httptest.Server) {
	b.Helper()
	client := sharedClientNoKeepAlive()
	for _, srv := range servers {
		for i := 0; i < prBenchRequestsHost; i++ {
			resp, err := client.Get(srv.URL + fmt.Sprintf("/r%d", i))
			require.NoError(b, err)
			_, _ = io.Copy(io.Discard, resp.Body)
			_ = resp.Body.Close()
		}
	}
}

// runAfterPR drives the same workload using httpclientpool.Get(... host) so
// each host gets its own keep-alive enabled client, matching the path taken
// by request.go after this PR.
func runAfterPR(b *testing.B, opts *types.Options, servers []*httptest.Server) {
	b.Helper()
	cfg := &Configuration{}
	for _, srv := range servers {
		host := hostFromURL(b, srv.URL)
		client, err := Get(opts, cfg, host)
		require.NoError(b, err)
		for i := 0; i < prBenchRequestsHost; i++ {
			req, err := http.NewRequest(http.MethodGet, srv.URL+fmt.Sprintf("/r%d", i), nil)
			require.NoError(b, err)
			resp, err := client.HTTPClient.Do(req)
			require.NoError(b, err)
			_, _ = io.Copy(io.Discard, resp.Body)
			_ = resp.Body.Close()
		}
	}
}

// runAfterPRConcurrent drives the workload with one goroutine per host so
// the per-host pool benefit is measured under realistic scan concurrency.
func runAfterPRConcurrent(b *testing.B, opts *types.Options, servers []*httptest.Server) {
	b.Helper()
	cfg := &Configuration{}
	var wg sync.WaitGroup
	for _, srv := range servers {
		wg.Add(1)
		go func(s *httptest.Server) {
			defer wg.Done()
			host := hostFromURL(b, s.URL)
			client, err := Get(opts, cfg, host)
			if err != nil {
				b.Errorf("Get(%s): %v", host, err)
				return
			}
			for i := 0; i < prBenchRequestsHost; i++ {
				req, err := http.NewRequest(http.MethodGet, s.URL+fmt.Sprintf("/r%d", i), nil)
				if err != nil {
					b.Errorf("new request: %v", err)
					return
				}
				resp, err := client.HTTPClient.Do(req)
				if err != nil {
					b.Errorf("do: %v", err)
					return
				}
				_, _ = io.Copy(io.Discard, resp.Body)
				_ = resp.Body.Close()
			}
		}(srv)
	}
	wg.Wait()
}

// HTTPS — TLS handshake amplifies the win.

func BenchmarkPR_BeforePR_HTTPS(b *testing.B) {
	servers := startPRTLSServers(b, prBenchHosts)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		runBeforePR(b, servers)
	}
}

func BenchmarkPR_AfterPR_HTTPS(b *testing.B) {
	opts := setupPRBenchOptions(b, "bench-after-pr-https")
	servers := startPRTLSServers(b, prBenchHosts)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		runAfterPR(b, opts, servers)
	}
}

func BenchmarkPR_AfterPR_HTTPS_Concurrent(b *testing.B) {
	opts := setupPRBenchOptions(b, "bench-after-pr-https-concurrent")
	servers := startPRTLSServers(b, prBenchHosts)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		runAfterPRConcurrent(b, opts, servers)
	}
}

// HTTP — keep-alive still wins because it skips TCP setup on every request.

func BenchmarkPR_BeforePR_HTTP(b *testing.B) {
	servers := startPRHTTPServers(b, prBenchHosts)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		runBeforePR(b, servers)
	}
}

func BenchmarkPR_AfterPR_HTTP(b *testing.B) {
	opts := setupPRBenchOptions(b, "bench-after-pr-http")
	servers := startPRHTTPServers(b, prBenchHosts)
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		runAfterPR(b, opts, servers)
	}
}

package httpclientpool

import (
	"net/http"
	"net/url"
	"testing"
)

func TestNormalizeHost(t *testing.T) {
	tests := []struct {
		name   string
		scheme string
		host   string
		want   string
	}{
		// No port
		{"http no port", "http", "example.com", "example.com"},
		{"https no port", "https", "example.com", "example.com"},

		// Default ports stripped
		{"http default port 80", "http", "example.com:80", "example.com"},
		{"https default port 443", "https", "example.com:443", "example.com"},

		// Non-default ports preserved
		{"http non-default port", "http", "example.com:8080", "example.com:8080"},
		{"https non-default port", "https", "example.com:8443", "example.com:8443"},

		// Cross-scheme default ports preserved (443 is not default for http)
		{"http with port 443", "http", "example.com:443", "example.com:443"},
		{"https with port 80", "https", "example.com:80", "example.com:80"},

		// IP addresses
		{"ipv4 no port", "http", "127.0.0.1", "127.0.0.1"},
		{"ipv4 default port", "http", "127.0.0.1:80", "127.0.0.1"},
		{"ipv4 non-default port", "http", "127.0.0.1:8080", "127.0.0.1:8080"},
		{"ipv4 https default port", "https", "10.0.0.1:443", "10.0.0.1"},

		// IPv6 addresses
		{"ipv6 no port", "http", "[::1]", "[::1]"},
		{"ipv6 default port http", "http", "[::1]:80", "[::1]"},
		{"ipv6 default port https", "https", "[::1]:443", "[::1]"},
		{"ipv6 non-default port", "https", "[::1]:8443", "[::1]:8443"},
		{"ipv6 full address default port", "http", "[2001:db8::1]:80", "[2001:db8::1]"},
		{"ipv6 full address non-default", "http", "[2001:db8::1]:9090", "[2001:db8::1]:9090"},

		// Empty host
		{"empty host", "http", "", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			u := &url.URL{Scheme: tt.scheme, Host: tt.host}
			got := normalizeHost(u)
			if got != tt.want {
				t.Errorf("normalizeHost(%s://%s) = %q, want %q", tt.scheme, tt.host, got, tt.want)
			}
		})
	}
}

func TestFollowSameHostRedirectWithPort(t *testing.T) {
	tests := []struct {
		name        string
		oldURL      string
		newURL      string
		shouldAllow bool
	}{
		// Basic same host
		{"same host no port", "http://example.com/a", "http://example.com/b", true},
		{"same host same path", "http://example.com/a", "http://example.com/a", true},

		// Default port normalization (the bug from #4685)
		{"old has :80 new does not", "http://example.com:80/a", "http://example.com/b", true},
		{"new has :80 old does not", "http://example.com/a", "http://example.com:80/b", true},
		{"both have :80", "http://example.com:80/a", "http://example.com:80/b", true},
		{"old has :443 new does not https", "https://example.com:443/a", "https://example.com/b", true},
		{"new has :443 old does not https", "https://example.com/a", "https://example.com:443/b", true},
		{"both have :443 https", "https://example.com:443/a", "https://example.com:443/b", true},

		// Relative redirect (host carried from original request)
		{"relative redirect same host", "http://example.com/a", "http://example.com/target", true},

		// IP address with default port
		{"ip old has :80 new does not", "http://127.0.0.1:80/a", "http://127.0.0.1/b", true},
		{"ip new has :80 old does not", "http://127.0.0.1/a", "http://127.0.0.1:80/b", true},
		{"ip both no port", "http://127.0.0.1/a", "http://127.0.0.1/b", true},

		// Different hosts should be blocked
		{"different host", "http://example.com/a", "http://other.com/b", false},
		{"different host with port", "http://example.com:80/a", "http://other.com:80/b", false},
		{"different ip", "http://127.0.0.1/a", "http://127.0.0.2/b", false},

		// Non-default ports
		{"same non-default port", "http://example.com:8080/a", "http://example.com:8080/b", true},
		{"different non-default port", "http://example.com:8080/a", "http://example.com:9090/b", false},
		{"non-default vs no port", "http://example.com:8080/a", "http://example.com/b", false},
		{"no port vs non-default", "http://example.com/a", "http://example.com:8080/b", false},

		// Cross-scheme port (443 on http is non-default, should not strip)
		{"http port 443 vs no port", "http://example.com:443/a", "http://example.com/b", false},
		{"https port 80 vs no port", "https://example.com:80/a", "https://example.com/b", false},

		// IPv6
		{"ipv6 same host", "http://[::1]/a", "http://[::1]/b", true},
		{"ipv6 default port normalization", "http://[::1]:80/a", "http://[::1]/b", true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			checkFn := makeCheckRedirectFunc(FollowSameHostRedirect, 10)
			oldReq, _ := http.NewRequest("GET", tt.oldURL, nil)
			newReq, _ := http.NewRequest("GET", tt.newURL, nil)
			err := checkFn(newReq, []*http.Request{oldReq})
			allowed := err == nil
			if allowed != tt.shouldAllow {
				t.Errorf("redirect from %q to %q: allowed=%v, want %v", tt.oldURL, tt.newURL, allowed, tt.shouldAllow)
			}
		})
	}
}

func TestFollowSameHostRedirectViaHost(t *testing.T) {
	// When via[0].Host is set (e.g. Host header override), it takes precedence over URL.Host
	checkFn := makeCheckRedirectFunc(FollowSameHostRedirect, 10)

	oldReq, _ := http.NewRequest("GET", "http://proxy.internal/a", nil)
	oldReq.Host = "example.com"
	newReq, _ := http.NewRequest("GET", "http://example.com/b", nil)

	err := checkFn(newReq, []*http.Request{oldReq})
	if err != nil {
		t.Errorf("redirect should be allowed when via[0].Host matches new host, got err: %v", err)
	}

	// Mismatch: via[0].Host differs from redirect target
	oldReq2, _ := http.NewRequest("GET", "http://proxy.internal/a", nil)
	oldReq2.Host = "other.com"
	newReq2, _ := http.NewRequest("GET", "http://example.com/b", nil)

	err = checkFn(newReq2, []*http.Request{oldReq2})
	if err == nil {
		t.Errorf("redirect should be blocked when via[0].Host differs from new host")
	}
}

func TestDontFollowRedirect(t *testing.T) {
	checkFn := makeCheckRedirectFunc(DontFollowRedirect, 10)
	oldReq, _ := http.NewRequest("GET", "http://example.com/a", nil)
	newReq, _ := http.NewRequest("GET", "http://example.com/b", nil)

	err := checkFn(newReq, []*http.Request{oldReq})
	if err != http.ErrUseLastResponse {
		t.Errorf("DontFollowRedirect should always return ErrUseLastResponse, got: %v", err)
	}
}

func TestFollowAllRedirect(t *testing.T) {
	checkFn := makeCheckRedirectFunc(FollowAllRedirect, 10)

	// Same host
	oldReq, _ := http.NewRequest("GET", "http://example.com/a", nil)
	newReq, _ := http.NewRequest("GET", "http://example.com/b", nil)
	if err := checkFn(newReq, []*http.Request{oldReq}); err != nil {
		t.Errorf("FollowAllRedirect should allow same host redirect, got: %v", err)
	}

	// Different host
	oldReq2, _ := http.NewRequest("GET", "http://example.com/a", nil)
	newReq2, _ := http.NewRequest("GET", "http://other.com/b", nil)
	if err := checkFn(newReq2, []*http.Request{oldReq2}); err != nil {
		t.Errorf("FollowAllRedirect should allow cross-host redirect, got: %v", err)
	}
}

func TestFollowSameSchemeRedirect(t *testing.T) {
	tests := []struct {
		name        string
		oldURL      string
		newURL      string
		shouldAllow bool
	}{
		// same scheme should be allowed
		{"http to http", "http://example.com/a", "http://example.com/b", true},
		{"https to https", "https://example.com/a", "https://example.com/b", true},
		{"http to http different host", "http://example.com/a", "http://other.com/b", true},
		{"https to https different host", "https://example.com/a", "https://other.com/b", true},

		// cross-scheme should be blocked
		{"http to https", "http://example.com/a", "https://example.com/b", false},
		{"https to http", "https://example.com/a", "http://example.com/b", false},
		{"http to https different host", "http://example.com/a", "https://other.com/b", false},
		{"https to http different host", "https://example.com/a", "http://other.com/b", false},

		// same scheme with ports
		{"http with port to http", "http://example.com:8080/a", "http://example.com:9090/b", true},
		{"https with port to https", "https://example.com:8443/a", "https://example.com:443/b", true},
		{"http with port to https", "http://example.com:80/a", "https://example.com:443/b", false},

		// ipv4
		{"ipv4 http to http", "http://127.0.0.1/a", "http://127.0.0.1/b", true},
		{"ipv4 http to https", "http://127.0.0.1/a", "https://127.0.0.1/b", false},

		// ipv6
		{"ipv6 https to https", "https://[::1]/a", "https://[::1]/b", true},
		{"ipv6 https to http", "https://[::1]/a", "http://[::1]/b", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			checkFn := makeCheckRedirectFunc(FollowSameSchemeRedirect, 10)
			oldReq, _ := http.NewRequest("GET", tt.oldURL, nil)
			newReq, _ := http.NewRequest("GET", tt.newURL, nil)
			err := checkFn(newReq, []*http.Request{oldReq})
			allowed := err == nil
			if allowed != tt.shouldAllow {
				t.Errorf("redirect from %q to %q: allowed=%v, want %v", tt.oldURL, tt.newURL, allowed, tt.shouldAllow)
			}
		})
	}
}

func TestFollowSameSchemeRedirectChain(t *testing.T) {
	checkFn := makeCheckRedirectFunc(FollowSameSchemeRedirect, 10)

	// multi-hop chain within same scheme should work
	req1, _ := http.NewRequest("GET", "http://example.com/a", nil)
	req2, _ := http.NewRequest("GET", "http://example.com/b", nil)
	req3, _ := http.NewRequest("GET", "http://example.com/c", nil)
	err := checkFn(req3, []*http.Request{req1, req2})
	if err != nil {
		t.Errorf("same-scheme redirect chain should be allowed, got: %v", err)
	}

	// chain where last hop changes scheme should be blocked
	req4, _ := http.NewRequest("GET", "https://example.com/d", nil)
	err = checkFn(req4, []*http.Request{req1, req2})
	if err == nil {
		t.Errorf("cross-scheme redirect at end of chain should be blocked")
	}
}

func TestFollowSameSchemeRedirectMaxRedirects(t *testing.T) {
	checkFn := makeCheckRedirectFunc(FollowSameSchemeRedirect, 2)

	req, _ := http.NewRequest("GET", "http://example.com/c", nil)
	via := make([]*http.Request, 3)
	for i := range via {
		via[i], _ = http.NewRequest("GET", "http://example.com/"+string(rune('a'+i)), nil)
	}
	if err := checkFn(req, via); err == nil {
		t.Errorf("should block after exceeding maxRedirects=2 with 3 via requests")
	}
}

func TestMaxRedirects(t *testing.T) {
	// Exceeding explicit max
	checkFn := makeCheckRedirectFunc(FollowAllRedirect, 2)
	req, _ := http.NewRequest("GET", "http://example.com/c", nil)
	via := make([]*http.Request, 3)
	for i := range via {
		via[i], _ = http.NewRequest("GET", "http://example.com/"+string(rune('a'+i)), nil)
	}
	if err := checkFn(req, via); err == nil {
		t.Errorf("should block after exceeding maxRedirects=2 with 3 via requests")
	}

	// Within explicit max
	checkFn2 := makeCheckRedirectFunc(FollowAllRedirect, 5)
	via2 := make([]*http.Request, 3)
	for i := range via2 {
		via2[i], _ = http.NewRequest("GET", "http://example.com/"+string(rune('a'+i)), nil)
	}
	if err := checkFn2(req, via2); err != nil {
		t.Errorf("should allow within maxRedirects=5 with 3 via requests, got: %v", err)
	}

	// maxRedirects=0 uses default (10)
	checkFn3 := makeCheckRedirectFunc(FollowAllRedirect, 0)
	via3 := make([]*http.Request, 11)
	for i := range via3 {
		via3[i], _ = http.NewRequest("GET", "http://example.com/x", nil)
	}
	if err := checkFn3(req, via3); err == nil {
		t.Errorf("should block after exceeding default maxRedirects (10) with 11 via requests")
	}

	via4 := make([]*http.Request, 9)
	for i := range via4 {
		via4[i], _ = http.NewRequest("GET", "http://example.com/x", nil)
	}
	if err := checkFn3(req, via4); err != nil {
		t.Errorf("should allow within default maxRedirects (10) with 9 via requests, got: %v", err)
	}
}

package httpclientpool

import (
	"crypto/tls"
	"net"
	"sync"
	"sync/atomic"
)

// desyncConn watches for bytes that arrive from a server while the connection is
// not serving any request. A server has nothing to answer at that point, so
// whatever it sends belongs to an earlier exchange.
//
// Idleness comes from net/http: GotConn fires when a request takes the
// connection and PutIdleConn fires when it returns to the pool. Bytes in that
// window are unsolicited by the same criterion net/http uses internally. The
// check is one atomic load in Read, identical over plaintext and TLS because
// the wrapper sits above the handshake: only decrypted application data
// reaches it. Below the handshake a session ticket or a close_notify alert on
// an idle connection would read as a leftover and quarantine a healthy host.
//
// net/http already closes a connection when it notices this, but only logs it.
// Observing it here is what lets the pool stop reusing connections to that host.
// A leftover that arrives while a request is outstanding is indistinguishable
// from that request's real reply, so this cannot save the first wrong response.
// Closing and quarantining only stops the host from doing it again.
type desyncConn struct {
	net.Conn
	host     string
	onPoison func(host string)
	// state packs the request generation in the high bits and the idle bit in
	// the low bit. markIdle only sets that bit for the generation it was given,
	// so a PutIdleConn that lands after the next request has taken the
	// connection cannot mark the live exchange idle.
	state     atomic.Uint64
	poisoned  atomic.Bool
	closeOnce sync.Once
}

func newDesyncConn(conn net.Conn, addr string, onPoison func(host string)) net.Conn {
	if conn == nil || negotiatedHTTP2(conn) {
		return conn
	}
	return &desyncConn{
		Conn:     conn,
		host:     desyncedHostKey(addr),
		onPoison: onPoison,
	}
}

func (c *desyncConn) Read(b []byte) (int, error) {
	n, err := c.Conn.Read(b)
	if n > 0 && c.state.Load()&1 == 1 {
		c.poison()
	}
	return n, err
}

// markBusy records that a request now owns the connection and returns that
// generation. The matching markIdle is the only one allowed to mark it idle.
func (c *desyncConn) markBusy() uint64 {
	for {
		old := c.state.Load()
		gen := (old >> 1) + 1
		if c.state.CompareAndSwap(old, gen<<1) {
			return gen
		}
	}
}

func (c *desyncConn) markIdle(gen uint64) {
	idle := (gen << 1) | 1
	for {
		old := c.state.Load()
		if old>>1 != gen {
			return
		}
		if c.state.CompareAndSwap(old, idle) {
			return
		}
	}
}

func (c *desyncConn) Close() error {
	c.state.Store(0)
	return c.Conn.Close()
}

// tlsState reports the handshake state of the wrapped connection when there is
// one. Go 1.26 net/http only reads TLS metadata from a concrete *tls.Conn
// returned by DialTLSContext, so a tracked connection leaves resp.TLS empty
// and connTrackingTransport fills it from here.
func (c *desyncConn) tlsState() (tls.ConnectionState, bool) {
	handshaked, ok := c.Conn.(interface{ ConnectionState() tls.ConnectionState })
	if !ok {
		return tls.ConnectionState{}, false
	}
	state := handshaked.ConnectionState()
	if !state.HandshakeComplete {
		return tls.ConnectionState{}, false
	}
	return state, true
}

func (c *desyncConn) poison() {
	if !c.poisoned.CompareAndSwap(false, true) {
		return
	}
	c.state.Store(0)
	if c.onPoison != nil {
		c.onPoison(c.host)
	}
	c.closeOnce.Do(func() { _ = c.Conn.Close() })
}

func negotiatedHTTP2(conn net.Conn) bool {
	handshaked, ok := conn.(interface{ ConnectionState() tls.ConnectionState })
	if !ok {
		return false
	}
	return handshaked.ConnectionState().NegotiatedProtocol == "h2"
}

package httpclientpool

import (
	"context"
	"crypto/tls"
	"fmt"
