)

type quarantineRecorder struct {
	hosts chan string
}

func newQuarantineRecorder() *quarantineRecorder {
	return &quarantineRecorder{hosts: make(chan string, 8)}
}

func (q *quarantineRecorder) record(host string) {
	select {
	case q.hosts <- host:
	default:
	}
}

func (q *quarantineRecorder) await(t *testing.T) string {
	t.Helper()
	select {
	case host := <-q.hosts:
		return host
	case <-time.After(5 * time.Second):
		t.Fatal("idle leftover never quarantined the host")
		return ""
	}
}

func (q *quarantineRecorder) requireQuiet(t *testing.T) {
	t.Helper()
	select {
	case host := <-q.hosts:
		t.Fatalf("healthy traffic was quarantined: %s", host)
	default:
	}
}

func trackedDialer(record func(string)) func(context.Context, string, string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		var dialer net.Dialer
		conn, err := dialer.DialContext(ctx, network, addr)
		if err != nil {
			return nil, err
		}
		return newDesyncConn(conn, addr, record), nil
	}
}

func trackedTLSDialer(record func(string)) func(context.Context, string, string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		var dialer net.Dialer
		raw, err := dialer.DialContext(ctx, network, addr)
		if err != nil {
			return nil, err
		}
		conn := tls.Client(raw, &tls.Config{InsecureSkipVerify: true})
		if err := conn.HandshakeContext(ctx); err != nil {
			_ = raw.Close()
			return nil, err
		}
		return newDesyncConn(conn, addr, record), nil
	}
}

func countingClient(t *testing.T, transport *http.Transport) *http.Client {
	t.Helper()
	t.Cleanup(transport.CloseIdleConnections)
	return &http.Client{Transport: &connTrackingTransport{base: transport}}
}

// surplusHandler answers the first request, then emits a leftover response timed
// to land while the second request is outstanding. net/http attributes that
// leftover to the second request. The genuine reply then arrives with nothing
// outstanding, which is the idle-byte signal.
func surplusHandler() http.HandlerFunc {
	const (
		straySentAfter   = 50 * time.Millisecond
		realReplyDelayed = 400 * time.Millisecond
		stale            = "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nX-Tag: stale\r\n\r\nstale"
	)
	answer := func(exchange int) string {
		return fmt.Sprintf("HTTP/1.1 200 OK\r\nContent-Length: 5\r\nX-Tag: ok-%d\r\n\r\nbody%d", exchange, exchange)
	}

	return func(w http.ResponseWriter, _ *http.Request) {
		hijacker, ok := w.(http.Hijacker)
		if !ok {
			return
		}
		conn, buffered, err := hijacker.Hijack()
		if err != nil {
			return
		}
		defer func() { _ = conn.Close() }()

		if _, err := io.WriteString(conn, answer(1)); err != nil {
			return
		}
		go func() {
			time.Sleep(straySentAfter)
			_, _ = io.WriteString(conn, stale)
		}()

		for exchange := 2; ; exchange++ {
			req, err := http.ReadRequest(buffered.Reader)
			if err != nil {
				return
			}
			_, _ = io.Copy(io.Discard, req.Body)
			time.Sleep(realReplyDelayed)
			if _, err := io.WriteString(conn, answer(exchange)); err != nil {
				return
			}
		}
	}
}

func requireSurplusDetected(t *testing.T, server *httptest.Server, transport *http.Transport) {
	t.Helper()
	client := countingClient(t, transport)
	for range 2 {
		resp, err := client.Get(server.URL)
		if err != nil {
			break
		}
		_, _ = io.Copy(io.Discard, resp.Body)
		_ = resp.Body.Close()
	}
}

func TestDesyncConnDetectsSurplusResponseOverHTTP(t *testing.T) {
	server := httptest.NewServer(surplusHandler())
	t.Cleanup(server.Close)

	recorder := newQuarantineRecorder()
	transport := &http.Transport{MaxIdleConnsPerHost: 1, DialContext: trackedDialer(recorder.record)}
	requireSurplusDetected(t, server, transport)

	require.Equal(t, strings.TrimPrefix(server.URL, "http://"), recorder.await(t))
}

func TestDesyncConnDetectsSurplusResponseOverHTTPS(t *testing.T) {
	server := httptest.NewTLSServer(surplusHandler())
	t.Cleanup(server.Close)

	recorder := newQuarantineRecorder()
	transport := &http.Transport{MaxIdleConnsPerHost: 1, DialTLSContext: trackedTLSDialer(recorder.record)}
	requireSurplusDetected(t, server, transport)

	require.Equal(t, strings.TrimPrefix(server.URL, "https://"), recorder.await(t))
}

func TestDesyncConnPreservesTLSConnectionState(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	t.Cleanup(server.Close)

	transport := &connTrackingTransport{
		base: &http.Transport{DialTLSContext: trackedTLSDialer(func(string) {})},
	}
	t.Cleanup(transport.CloseIdleConnections)
	resp := roundTrip(t, transport, server.URL)
	require.NotNil(t, resp.TLS, "tracked HTTPS connections must still report their handshake")
	require.NotZero(t, resp.TLS.Version)
	require.True(t, resp.TLS.HandshakeComplete)
	require.NotEmpty(t, resp.TLS.PeerCertificates, "certificate metadata feeds the tls_* DSL fields")
}

// Go 1.26 reads handshake metadata only from a *tls.Conn, so an untracked
// dialer keeps the state net/http filled in and the wrapper must not touch it.
func TestConnTrackingTransportKeepsNativeTLSState(t *testing.T) {
	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	t.Cleanup(server.Close)

	transport := &connTrackingTransport{base: &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
	}}
	t.Cleanup(transport.CloseIdleConnections)
	resp := roundTrip(t, transport, server.URL)
	require.NotNil(t, resp.TLS)
	require.NotZero(t, resp.TLS.Version)
}

func TestConnTrackingTransportLeavesPlaintextWithoutTLSState(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	t.Cleanup(server.Close)

	transport := &connTrackingTransport{
		base: &http.Transport{DialContext: trackedDialer(func(string) {})},
	}
	t.Cleanup(transport.CloseIdleConnections)
	resp := roundTrip(t, transport, server.URL)
	require.Nil(t, resp.TLS, "a plaintext exchange must not report a handshake")
}

func TestDesyncConnTLSStateOnlyAfterHandshake(t *testing.T) {
	plain, _ := net.Pipe()
	t.Cleanup(func() { _ = plain.Close() })

	tracked := newDesyncConn(plain, "plain.test:80", nil).(*desyncConn)
	_, ok := tracked.tlsState()
	require.False(t, ok, "a plaintext connection has no handshake to report")

	handshaked := newDesyncConn(stubTLSConn{
		Conn:     plain,
		protocol: "http/1.1",
		state:    tls.ConnectionState{Version: tls.VersionTLS13, HandshakeComplete: true},
	}, "tls.test:443", nil).(*desyncConn)
	state, ok := handshaked.tlsState()
	require.True(t, ok)
	require.Equal(t, uint16(tls.VersionTLS13), state.Version)
}

func roundTrip(t *testing.T, transport http.RoundTripper, target string) *http.Response {
	t.Helper()
	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, target, nil)
	require.NoError(t, err)
	resp, err := transport.RoundTrip(req)
	require.NoError(t, err)
	t.Cleanup(func() { _ = resp.Body.Close() })
	_, err = io.Copy(io.Discard, resp.Body)
	require.NoError(t, err)
	return resp
}

func TestDesyncConnAllowsHealthyKeepAliveTraffic(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	t.Cleanup(server.Close)

	recorder := newQuarantineRecorder()
	client := countingClient(t, &http.Transport{
		MaxIdleConnsPerHost: 1, DialContext: trackedDialer(recorder.record),
	})

	for range 25 {
		resp, err := client.Get(server.URL)
		require.NoError(t, err)
		body, err := io.ReadAll(resp.Body)
		require.NoError(t, err)
		require.Equal(t, "ok", string(body))
		require.NoError(t, resp.Body.Close())
	}
	recorder.requireQuiet(t)
}

func TestDesyncConnIgnoresBytesWhileBusy(t *testing.T) {
	client, server := net.Pipe()
	t.Cleanup(func() { _ = server.Close() })

	recorder := newQuarantineRecorder()
	tracked := newDesyncConn(client, "busy.test:80", recorder.record).(*desyncConn)
	t.Cleanup(func() { _ = tracked.Close() })
	tracked.markBusy()

	go func() { _, _ = io.WriteString(server, "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok") }()

	buffer := make([]byte, 128)
	_, err := tracked.Read(buffer)
	require.NoError(t, err)
	require.False(t, tracked.poisoned.Load())
	recorder.requireQuiet(t)
}

func TestDesyncConnStartsBusy(t *testing.T) {
	client, server := net.Pipe()
	t.Cleanup(func() { _ = server.Close() })

	recorder := newQuarantineRecorder()
	tracked := newDesyncConn(client, "fresh.test:80", recorder.record).(*desyncConn)
	t.Cleanup(func() { _ = tracked.Close() })

	go func() { _, _ = io.WriteString(server, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n") }()

	buffer := make([]byte, 128)
	_, err := tracked.Read(buffer)
	require.NoError(t, err)
	require.False(t, tracked.poisoned.Load())
	recorder.requireQuiet(t)
}

func TestDesyncConnIgnoresStaleIdleAfterReuse(t *testing.T) {
	client, server := net.Pipe()
	t.Cleanup(func() { _ = server.Close() })

	recorder := newQuarantineRecorder()
	tracked := newDesyncConn(client, "stale.test:80", recorder.record).(*desyncConn)
	t.Cleanup(func() { _ = tracked.Close() })

	first := tracked.markBusy()
	second := tracked.markBusy()
	tracked.markIdle(first)

	go func() { _, _ = io.WriteString(server, "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok") }()

	buffer := make([]byte, 128)
	_, err := tracked.Read(buffer)
	require.NoError(t, err)
	require.False(t, tracked.poisoned.Load(), "a late idle mark must not poison the request that already took the connection")
	recorder.requireQuiet(t)

	tracked.markIdle(second)
	go func() { _, _ = io.WriteString(server, "left") }()
	_, err = tracked.Read(buffer)
	require.NoError(t, err)
	require.Equal(t, "stale.test", recorder.await(t))
}

func TestDesyncConnPoisonsOnBytesWhileIdleAndClosesConnection(t *testing.T) {
	client, server := net.Pipe()
	t.Cleanup(func() { _ = server.Close() })

	recorder := newQuarantineRecorder()
	tracked := newDesyncConn(client, "idle.test:80", recorder.record).(*desyncConn)
	tracked.markIdle(tracked.markBusy())

	go func() { _, _ = io.WriteString(server, "HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nstale") }()

	buffer := make([]byte, 128)
	_, err := tracked.Read(buffer)
	require.NoError(t, err)
	require.Equal(t, "idle.test", recorder.await(t))
	require.True(t, tracked.poisoned.Load())

	_, err = tracked.Read(buffer)
	require.Error(t, err, "a poisoned connection must not stay usable")
}

func TestDesyncConnSkipsNegotiatedHTTP2(t *testing.T) {
	plain, _ := net.Pipe()
	t.Cleanup(func() { _ = plain.Close() })

	overHTTP2 := stubTLSConn{Conn: plain, protocol: "h2"}
	require.Equal(t, overHTTP2, newDesyncConn(overHTTP2, "h2.test:443", nil))

	overHTTP1 := stubTLSConn{Conn: plain, protocol: "http/1.1"}
	require.IsType(t, &desyncConn{}, newDesyncConn(overHTTP1, "h1.test:443", nil))
}

type stubTLSConn struct {
	net.Conn
	protocol string
	state    tls.ConnectionState
}

func (s stubTLSConn) ConnectionState() tls.ConnectionState {
	state := s.state
	state.NegotiatedProtocol = s.protocol
	return state
}

func TestMarkHostDesyncedStopsReuse(t *testing.T) {
	opts := newTestOptions(t, "test-desynced-host-no-reuse")
	cfg := &Configuration{}

	var conns atomic.Int64
	server := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	server.Config.ConnState = func(_ net.Conn, state http.ConnState) {
		if state == http.StateNew {
			conns.Add(1)
		}
	}
	server.Start()
	t.Cleanup(server.Close)

	host := hostOf(t, server.URL)

	pooled, err := Get(opts, cfg, host)
	require.NoError(t, err)
	requestTwice(t, pooled, server.URL)
	require.Equal(t, int64(1), conns.Load(), "an unmarked host must reuse its connection")

	MarkHostDesynced(opts, server.URL)
	require.True(t, IsHostDesynced(opts, host))

	guarded, err := Get(opts, cfg, host)
	require.NoError(t, err)
	require.NotSame(t, pooled, guarded)

	conns.Store(0)
	requestTwice(t, guarded, server.URL)
	require.Equal(t, int64(2), conns.Load(), "a marked host must not reuse connections")
}

// The pooled client dials TLS through fastdialer and tracks the handshaked
// connection, so this is the path that has to keep feeding resp.TLS.
func TestPooledClientReportsTLSStateOverHTTPS(t *testing.T) {
	opts := newTestOptions(t, "test-desync-tls-metadata")

	server := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		_, _ = io.WriteString(w, "ok")
	}))
	t.Cleanup(server.Close)

	client, err := Get(opts, &Configuration{}, hostOf(t, server.URL))
	require.NoError(t, err)

	resp, err := client.Get(server.URL)
	require.NoError(t, err)
	t.Cleanup(func() { _ = resp.Body.Close() })
	_, err = io.Copy(io.Discard, resp.Body)
	require.NoError(t, err)

	require.NotNil(t, resp.TLS, "HTTPS responses must carry handshake metadata")
	require.NotZero(t, resp.TLS.Version)
	require.NotEmpty(t, resp.TLS.PeerCertificates)
}

func TestIsHostDesyncedEmptyHost(t *testing.T) {
	opts := newTestOptions(t, "test-desync-empty-host")
	MarkHostDesynced(opts, "")
	require.False(t, IsHostDesynced(opts, ""))
}

func requestTwice(t *testing.T, client *retryablehttp.Client, target string) {
	t.Helper()
	for range 2 {
		resp, err := client.Get(target)
		require.NoError(t, err)
		_, err = io.Copy(io.Discard, resp.Body)
		require.NoError(t, err)
		require.NoError(t, resp.Body.Close())
	}
}

func hostOf(t *testing.T, raw string) string {
	t.Helper()
	parsed, err := url.Parse(raw)
	require.NoError(t, err)
	return parsed.Host
}

func TestDesyncedHostKey(t *testing.T) {
	for _, tc := range []struct{ in, want string }{
		{"https://example.com:8443/admin?a=1", "example.com:8443"},
		{"http://example.com/", "example.com"},
		{"https://EXAMPLE.COM:443/", "example.com"},
		{"http://example.com:80/", "example.com"},
		{"example.com:443", "example.com"},
		{"example.com:80", "example.com"},
		{"https://[2001:db8::1]:8443/", "[2001:db8::1]:8443"},
		{"https://[2001:db8::1]:443/", "[2001:db8::1]"},
		{"example.com:8443", "example.com:8443"},
		{"  example.com  ", "example.com"},
		{"", ""},
	} {
		require.Equal(t, tc.want, desyncedHostKey(tc.in), tc.in)
	}
	require.NotEqual(t, desyncedHostKey("example.com:443"), desyncedHostKey("example.com:8443"))
}

func TestDesyncTrackersAreExecutionScoped(t *testing.T) {
	first := newTestOptions(t, "test-desync-scope-first")
	second := newTestOptions(t, "test-desync-scope-second")

	MarkHostDesynced(first, "example.com:443")
	require.True(t, IsHostDesynced(first, "example.com:443"))
	require.False(t, IsHostDesynced(second, "example.com:443"))
	require.Equal(t, []string{"example.com"}, DesyncedHosts(first))
	require.Empty(t, DesyncedHosts(second))
}

package httpclientpool

import (
	"net"
	"net/url"
	"strings"
	"sync/atomic"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// Some servers answer a request and then send another, unsolicited response on
// the same keep-alive connection. net/http already discards that connection when
// the leftover lands while the connection is idle, but it only logs the event.
// Under back-to-back load a leftover can still be attributed to the next request,
// corrupting a small number of responses before the stream resynchronizes.
//
// Once a leftover is observed on an idle connection, reuse for that host is
// disabled for a while so the same listener cannot keep costing wrong results.
const desyncedHostTTL = 15 * time.Minute

var desyncedResponses atomic.Int64

// DesyncedResponses reports how many idle connections were closed after receiving
// unsolicited bytes since the process started.
func DesyncedResponses() int64 {
	return desyncedResponses.Load()
}

func countDesyncedResponse() {
	desyncedResponses.Add(1)
}

func desyncHostsFor(options *types.Options) *protocolstate.ExpiringSet {
	if options == nil {
		return nil
	}
	dialers := protocolstate.GetDialersWithId(options.ExecutionId)
	if dialers == nil {
		return nil
	}
	return dialers.HTTPDesyncHosts
}

// MarkHostDesynced disables connection reuse for a target until the mark expires.
func MarkHostDesynced(options *types.Options, target string) {
	hosts := desyncHostsFor(options)
	if hosts == nil {
		return
	}
	key := desyncedHostKey(target)
	if key == "" {
		return
	}
	hosts.Store(key, desyncedHostTTL)
}

// IsHostDesynced reports whether connection reuse for a target is disabled.
func IsHostDesynced(options *types.Options, target string) bool {
	hosts := desyncHostsFor(options)
	key := desyncedHostKey(target)
	return hosts != nil && key != "" && hosts.Contains(key)
}

// DesyncedHosts returns the hosts connection reuse is currently disabled for.
func DesyncedHosts(options *types.Options) []string {
	hosts := desyncHostsFor(options)
	if hosts == nil {
		return nil
	}
	return hosts.Keys()
}

func desyncedHostKey(target string) string {
	target = strings.TrimSpace(target)
	if target == "" {
		return ""
	}

	if parsed, err := url.Parse(target); err == nil && parsed.Host != "" {
		return normalizeDesyncedHost(parsed.Host)
	}

	return normalizeDesyncedHost(strings.TrimSuffix(target, "/"))
}

func normalizeDesyncedHost(host string) string {
	host = strings.ToLower(host)
	name, port, err := net.SplitHostPort(host)
	if err != nil || (port != "80" && port != "443") {
		return host
	}
	if strings.Contains(name, ":") {
		return "[" + name + "]"
	}
	return name
}

package httpclientpool

import "errors"

var (
	ErrRebuildURL = errors.New("could not rebuild request URL")
)

package httpclientpool

import (
	"sync"
	"sync/atomic"

	lru "github.com/hashicorp/golang-lru/v2"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/hostratelimit"
)

// defaultHTTPToHTTPSTrackerSize bounds how many host:port entries the tracker
// keeps in memory. It is an LRU rather than a grow-only map so a long-running
// embedder (e.g. a scan service running for days) does not accumulate one entry
// per unique host:port forever. Evicting the least-recently-used entry only
// costs a single re-detection (one extra 400) if that host:port is scanned
// again later, and the result is re-learned immediately.
const defaultHTTPToHTTPSTrackerSize = 50000

// HTTPToHTTPSPortTracker tracks host:port combinations that require HTTPS
// This is used to automatically detect and correct cases where HTTP requests
// are sent to HTTPS ports (detected via 400 error with specific message).
//
// NOTE: detection and correction apply to the standard net/http (retryablehttp)
// request path only. Unsafe/raw (rawhttp) requests bypass this scheme rewrite.
type HTTPToHTTPSPortTracker struct {
	// once guards lazy initialization of ports so a zero-value tracker
	// (e.g. var t HTTPToHTTPSPortTracker) is safe to use directly.
	once sync.Once
	// ports is a bounded LRU of host:port that require HTTPS
	ports *lru.Cache[string, struct{}]

	// Statistics
	totalDetections  atomic.Uint64
	totalCorrections atomic.Uint64
}

// NewHTTPToHTTPSPortTracker creates a new HTTP-to-HTTPS port tracker
func NewHTTPToHTTPSPortTracker() *HTTPToHTTPSPortTracker {
	return newHTTPToHTTPSPortTrackerWithSize(defaultHTTPToHTTPSTrackerSize)
}

func newHTTPToHTTPSPortTrackerWithSize(size int) *HTTPToHTTPSPortTracker {
	if size <= 0 {
		size = defaultHTTPToHTTPSTrackerSize
	}
	// lru.New only errors on a non-positive size, which is guarded above
	cache, _ := lru.New[string, struct{}](size)
	return &HTTPToHTTPSPortTracker{ports: cache}
}

// cache returns the bounded LRU, lazily initializing it with the default size
// when the tracker was constructed as a zero value rather than via
// NewHTTPToHTTPSPortTracker. Since ports is a pointer, a nil cache would
// otherwise panic on first use (unlike the previous zero-value-safe sync.Map).
func (t *HTTPToHTTPSPortTracker) cache() *lru.Cache[string, struct{}] {
	t.once.Do(func() {
		if t.ports == nil {
			t.ports, _ = lru.New[string, struct{}](defaultHTTPToHTTPSTrackerSize)
		}
	})
	return t.ports
}

// RecordHTTPToHTTPSPort records that a host:port requires HTTPS
func (t *HTTPToHTTPSPortTracker) RecordHTTPToHTTPSPort(hostPort string) {
	if hostPort == "" {
		return
	}

	normalizedHostPort := hostratelimit.NormalizeHostPort(hostPort)
	if normalizedHostPort == "" {
		return
	}

	// PeekOrAdd atomically inserts the entry only when absent, so a unique
	// host:port is counted exactly once even under concurrent detections
	// (ContainsOrAdd would do this too). On a hit we additionally issue a Get
	// to refresh the LRU recency: neither Peek/PeekOrAdd nor ContainsOrAdd
	// updates recent-ness, and an actively re-detected host:port must not be
	// evicted while it is still in use.
	if _, existed, _ := t.cache().PeekOrAdd(normalizedHostPort, struct{}{}); existed {
		t.cache().Get(normalizedHostPort)
		return // Already recorded, no need to log again
	}
	t.totalDetections.Add(1)

	gologger.Debug().Msgf("[http-to-https-tracker] Detected HTTP-to-HTTPS port mismatch for %s", normalizedHostPort)
}

// RequiresHTTPS checks if a host:port requires HTTPS
func (t *HTTPToHTTPSPortTracker) RequiresHTTPS(hostPort string) bool {
	if hostPort == "" {
		return false
	}

	normalizedHostPort := hostratelimit.NormalizeHostPort(hostPort)
	if normalizedHostPort == "" {
		return false
	}

	// Get (rather than Contains) so active host:ports refresh their LRU
	// recency and are not evicted while still in use.
	_, ok := t.cache().Get(normalizedHostPort)
	return ok
}

// RecordCorrection records that an HTTP->HTTPS correction was actually applied
func (t *HTTPToHTTPSPortTracker) RecordCorrection() {
	t.totalCorrections.Add(1)
}

// Evict removes a host:port from the tracker. It is used to self-heal a false
// positive: when an http->https correction is applied but the https request
// then fails, the original http scheme is retried and, if the entry was wrong,
// evicted so subsequent requests (including those from unrelated templates)
// against the same host:port are not silently broken.
func (t *HTTPToHTTPSPortTracker) Evict(hostPort string) {
	if hostPort == "" {
		return
	}

	normalizedHostPort := hostratelimit.NormalizeHostPort(hostPort)
	if normalizedHostPort == "" {
		return
	}

	if present := t.cache().Remove(normalizedHostPort); present {
		gologger.Debug().Msgf("[http-to-https-tracker] Reverted HTTP-to-HTTPS for %s (https attempt failed, falling back to http)", normalizedHostPort)
	}
}

// Stats returns statistics about the tracker
func (t *HTTPToHTTPSPortTracker) Stats() HTTPToHTTPSPortStats {
	return HTTPToHTTPSPortStats{
		TotalDetections:  t.totalDetections.Load(),
		TotalCorrections: t.totalCorrections.Load(),
		// TrackedPorts is the number of entries currently held in the bounded
		// LRU (may be lower than TotalDetections once eviction kicks in).
		TrackedPorts: t.cache().Len(),
	}
}

// HTTPToHTTPSPortStats contains statistics about the HTTP-to-HTTPS port tracker
type HTTPToHTTPSPortStats struct {
	TotalDetections  uint64
	TotalCorrections uint64
	TrackedPorts     int
}

// PrintStats prints statistics about the tracker
func (t *HTTPToHTTPSPortTracker) PrintStats() {
	stats := t.Stats()
	if stats.TotalDetections == 0 {
		return
	}

	gologger.Info().Msgf("[http-to-https-tracker] HTTP-to-HTTPS port corrections: Detections=%d Corrections=%d TrackedPorts=%d",
		stats.TotalDetections, stats.TotalCorrections, stats.TrackedPorts)
}

package httpclientpool

import (
	"fmt"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestHTTPToHTTPSPortTracker_RecordAndRequire(t *testing.T) {
	tr := NewHTTPToHTTPSPortTracker()

	require.False(t, tr.RequiresHTTPS("http://example.com:8443/path"), "unknown host should not require https")

	tr.RecordHTTPToHTTPSPort("http://example.com:8443/path")
	require.True(t, tr.RequiresHTTPS("http://example.com:8443/other"), "recorded host:port should require https regardless of path")
	require.True(t, tr.RequiresHTTPS("https://example.com:8443/"), "lookup must be scheme-independent (keyed by host:port)")

	require.EqualValues(t, 1, tr.Stats().TotalDetections)
}

// TestHTTPToHTTPSPortTracker_Evict guards the fallback mechanism: a wrongly detected
// host:port must be removable so a failed https correction can revert to http
// and stop breaking subsequent (cross-template) requests to the same target.
func TestHTTPToHTTPSPortTracker_Evict(t *testing.T) {
	tr := NewHTTPToHTTPSPortTracker()

	tr.RecordHTTPToHTTPSPort("http://example.com:8080/")
	require.True(t, tr.RequiresHTTPS("http://example.com:8080/"))

	tr.Evict("http://example.com:8080/")
	require.False(t, tr.RequiresHTTPS("http://example.com:8080/"), "evicted host:port must no longer require https")

	// Evicting unknown / empty values must be safe no-ops.
	tr.Evict("")
	tr.Evict("http://not-recorded.example:1234/")
}

// TestHTTPToHTTPSPortTracker_BoundedLRU guards against unbounded memory growth
// in long-running embedders: the tracker must cap the number of host:port
// entries it retains and evict the least-recently-used ones instead of growing
// forever.
func TestHTTPToHTTPSPortTracker_BoundedLRU(t *testing.T) {
	const size = 100
	tr := newHTTPToHTTPSPortTrackerWithSize(size)

	for i := 0; i < size*3; i++ {
		tr.RecordHTTPToHTTPSPort(fmt.Sprintf("http://host%d.example.com:8443/", i))
	}

	// cumulative detections counts every unique host:port ever recorded
	require.EqualValues(t, size*3, tr.Stats().TotalDetections)
	// but the in-memory set is bounded by the LRU capacity
	require.Equal(t, size, tr.Stats().TrackedPorts, "tracker must not grow beyond its LRU capacity")

	// the oldest entry must have been evicted, the newest must remain
	require.False(t, tr.RequiresHTTPS("http://host0.example.com:8443/"), "oldest entry should be evicted")
	require.True(t, tr.RequiresHTTPS(fmt.Sprintf("http://host%d.example.com:8443/", size*3-1)), "newest entry should be retained")
}

// TestHTTPToHTTPSPortTracker_RequiresHTTPSRefreshesLRU guards the recency-refresh
// contract: a lookup must mark the entry as recently used so that an actively
// queried host:port survives eviction over an untouched one.
func TestHTTPToHTTPSPortTracker_RequiresHTTPSRefreshesLRU(t *testing.T) {
	tr := newHTTPToHTTPSPortTrackerWithSize(2)

	tr.RecordHTTPToHTTPSPort("http://a.example.com:8443/")
	tr.RecordHTTPToHTTPSPort("http://b.example.com:8443/")

	require.True(t, tr.RequiresHTTPS("http://a.example.com:8443/"), "lookup should refresh recency")

	tr.RecordHTTPToHTTPSPort("http://c.example.com:8443/")

	require.True(t, tr.RequiresHTTPS("http://a.example.com:8443/"), "refreshed entry should be retained")
	require.False(t, tr.RequiresHTTPS("http://b.example.com:8443/"), "untouched least-recently-used entry should be evicted")
	require.True(t, tr.RequiresHTTPS("http://c.example.com:8443/"))
}

// TestHTTPToHTTPSPortTracker_RecordRefreshesLRU guards the recency-refresh
// contract on the write path: re-recording an existing host:port must mark it
// recently-used so an actively re-detected entry survives eviction over an
// untouched one (a plain ContainsOrAdd would not refresh recency here).
func TestHTTPToHTTPSPortTracker_RecordRefreshesLRU(t *testing.T) {
	tr := newHTTPToHTTPSPortTrackerWithSize(2)

	tr.RecordHTTPToHTTPSPort("http://a.example.com:8443/")
	tr.RecordHTTPToHTTPSPort("http://b.example.com:8443/")

	// re-recording "a" must refresh its recency, making "b" the LRU victim
	tr.RecordHTTPToHTTPSPort("http://a.example.com:8443/")

	tr.RecordHTTPToHTTPSPort("http://c.example.com:8443/")

	require.True(t, tr.RequiresHTTPS("http://a.example.com:8443/"), "re-recorded entry should be retained")
	require.False(t, tr.RequiresHTTPS("http://b.example.com:8443/"), "untouched least-recently-used entry should be evicted")
	require.True(t, tr.RequiresHTTPS("http://c.example.com:8443/"))

	// re-recording an existing host must not inflate the unique-detection count
	require.EqualValues(t, 3, tr.Stats().TotalDetections, "re-recording an existing host:port must not double-count")
}

// TestHTTPToHTTPSPortTracker_ConcurrentRecordCountsOnce ensures that recording
// the same host:port from many goroutines counts it as a single detection.
// PeekOrAdd makes the insert+count atomic; a check-then-add (Get then Add)
// implementation would over-count under the race detector.
func TestHTTPToHTTPSPortTracker_ConcurrentRecordCountsOnce(t *testing.T) {
	tr := NewHTTPToHTTPSPortTracker()

	const goroutines = 64
	var wg sync.WaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			defer wg.Done()
			tr.RecordHTTPToHTTPSPort("http://race.example.com:8443/")
		}()
	}
	wg.Wait()

	require.EqualValues(t, 1, tr.Stats().TotalDetections, "a unique host:port must be counted exactly once")
	require.Equal(t, 1, tr.Stats().TrackedPorts, "a unique host:port must occupy a single LRU entry")
}

// TestHTTPToHTTPSPortTracker_ZeroValueSafe ensures a zero-value tracker
// (constructed directly rather than via NewHTTPToHTTPSPortTracker) lazily
// initializes its bounded LRU instead of panicking on a nil cache.
func TestHTTPToHTTPSPortTracker_ZeroValueSafe(t *testing.T) {
	var tr HTTPToHTTPSPortTracker

	require.NotPanics(t, func() {
		require.False(t, tr.RequiresHTTPS("http://example.com:8443/"))
		tr.RecordHTTPToHTTPSPort("http://example.com:8443/")
		require.True(t, tr.RequiresHTTPS("http://example.com:8443/"))
		tr.Evict("http://example.com:8443/")
		_ = tr.Stats()
	})
}

package httpclientpool

import (
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/projectdiscovery/rawhttp"
	stringsutil "github.com/projectdiscovery/utils/strings"
	urlutil "github.com/projectdiscovery/utils/url"
)

// WithCustomTimeout is a configuration for custom timeout
type WithCustomTimeout struct {
	Timeout time.Duration
}

// RawHttpRequestOpts is a configuration for raw http request
type RawHttpRequestOpts struct {
	// Method is the http method to use
	Method string
	// URL is the url to request
	URL string
	// Path is request path to use
	Path string
	// Headers is the headers to use
	Headers map[string][]string
	// Body is the body to use
	Body io.Reader
	// Options is more client related options
	Options *rawhttp.Options
}

// SendRawRequest sends a raw http request with the provided options and returns http response
func SendRawRequest(client *rawhttp.Client, opts *RawHttpRequestOpts) (*http.Response, error) {
	resp, err := client.DoRawWithOptions(opts.Method, opts.URL, opts.Path, opts.Headers, opts.Body, opts.Options)
	if err != nil {
		cause := err.Error()
		if stringsutil.ContainsAll(cause, "ReadStatusLine: ", "read: connection reset by peer") {
			// this error is caused when rawhttp client sends a corrupted or malformed request packet to server
			// some servers may attempt gracefully shutdown but most will just abruptly close the connection which results
			// in a connection reset by peer error and this can be safely assumed as 400 Bad Request in terms of normal http flow
			req, reqErr := http.NewRequest(opts.Method, opts.URL, opts.Body)
			if reqErr != nil {
				// failed to build new request mostly because of invalid url or body
				// try again or else return urlErr
				parsed, urlErr := urlutil.ParseAbsoluteURL(opts.URL, true)
				if urlErr != nil {
					return nil, err
				}
				req, reqErr = http.NewRequest(opts.Method, parsed.Host, opts.Body)
				if reqErr != nil {
					return nil, err
				}
				req.URL = parsed.URL
				req.Header = opts.Headers
			}

			// if req is still nil, return error
			if req == nil {
				return nil, err
			}

			req.Header = opts.Headers
			resp = &http.Response{
				Request:    req,
				StatusCode: http.StatusBadRequest,
				Status:     http.StatusText(http.StatusBadRequest),
				Body:       io.NopCloser(strings.NewReader("")),
			}
			return resp, nil
		}
	}
	return resp, err
}

package httpclientpool

import (
	"bytes"
	"container/list"
	"context"
	"io"
	"maps"
	"net/http"
	"slices"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/useragent"
)

// Templates send many requests another template already sent to the same
// target, byte for byte: clustering merges only single-request templates. A
// request marked with WithSharedResponse is sent once per scan and every
// other template sending the same bytes gets a copy of the response. The key
// is the request as it goes on the wire, cookies included, and the client
// still processes each copy, so redirects and cookies behave as if it was
// sent again.
const (
	// sharedResponseMaxBody keeps large downloads out of the store; they are
	// sent each time
	sharedResponseMaxBody   = 1 << 20
	sharedResponsesMaxBytes = 64 << 20
)

type sharedResponseKey struct{}

// WithSharedResponse marks the request of templateID as one whose response
// other templates may reuse. A template sending the same request again gets
// it sent again: a repeat within one template is intended.
func WithSharedResponse(ctx context.Context, templateID string) context.Context {
	return context.WithValue(ctx, sharedResponseKey{}, templateID)
}

type sharedResponses struct {
	mu      sync.Mutex
	entries map[string]*sharedEntry
	// order holds stored entries oldest first, for eviction
	order    *list.List
	bytes    int
	maxBytes int
}

type sharedEntry struct {
	key        string
	templateID string
	ready      chan struct{}
	response   *storedResponse
}

type storedResponse struct {
	response *http.Response
	body     []byte
}

func getSharedResponses(options *types.Options) *sharedResponses {
	dialers := protocolstate.GetDialersWithId(options.ExecutionId)
	if dialers == nil {
		return nil
	}
	dialers.Lock()
	defer dialers.Unlock()
	if dialers.SharedResponses == nil {
		dialers.SharedResponses = &sharedResponses{entries: make(map[string]*sharedEntry), order: list.New(), maxBytes: sharedResponsesMaxBytes}
	}
	shared, _ := dialers.SharedResponses.(*sharedResponses)
	return shared
}

// ResetSharedResponses forgets the responses of earlier scans, so a scan
// that reuses the execution, as an SDK engine does, sends its requests again.
func ResetSharedResponses(options *types.Options) {
	shared := getSharedResponses(options)
	if shared == nil {
		return
	}
	shared.mu.Lock()
	defer shared.mu.Unlock()
	clear(shared.entries)
	shared.order.Init()
	shared.bytes = 0
}

type sharingTransport struct {
	base   http.RoundTripper
	shared *sharedResponses
}

func (t *sharingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	templateID, marked := req.Context().Value(sharedResponseKey{}).(string)
	if !marked || (req.Method != http.MethodGet && req.Method != http.MethodHead) || hasBody(req) {
		return t.base.RoundTrip(req)
	}
	key := sharedRequestKey(req)

	t.shared.mu.Lock()
	entry, found := t.shared.entries[key]
	if !found {
		entry = &sharedEntry{key: key, templateID: templateID, ready: make(chan struct{})}
		t.shared.entries[key] = entry
		t.shared.mu.Unlock()
		return t.send(req, entry)
	}
	t.shared.mu.Unlock()
	if entry.templateID == templateID {
		return t.base.RoundTrip(req)
	}
	select {
	case <-entry.ready:
	case <-req.Context().Done():
		return nil, req.Context().Err()
	}
	if entry.response == nil {
		// the first send failed or was too large to keep
		return t.base.RoundTrip(req)
	}
	return entry.response.copyFor(req), nil
}

// Unwrap returns the underlying transport, so reporting clients that need TLS
// verification reach the scan transport and never share responses.
func (t *sharingTransport) Unwrap() http.RoundTripper {
	return t.base
}

func (t *sharingTransport) CloseIdleConnections() {
	type closeIdler interface{ CloseIdleConnections() }
	if ci, ok := t.base.(closeIdler); ok {
		ci.CloseIdleConnections()
	}
}

// send sends the first request of key and stores its response for the rest.
func (t *sharingTransport) send(req *http.Request, entry *sharedEntry) (*http.Response, error) {
	defer close(entry.ready)
	resp, err := t.base.RoundTrip(req)
	if err != nil {
		t.forget(entry)
		return resp, err
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, sharedResponseMaxBody+1))
	if err != nil || len(body) > sharedResponseMaxBody || !shareableStatus(resp.StatusCode) {
		t.forget(entry)
		// The bytes already taken off the body have to go back in front of it.
		// A short read is still this caller's response: a Content-Length that
		// is longer than the body is what some matchers look for. It is not
		// stored, and neither is a body too large to keep or a refusal.
		resp.Body = struct {
			io.Reader
			io.Closer
		}{io.MultiReader(bytes.NewReader(body), resp.Body), resp.Body}
		return resp, nil
	}
	_ = resp.Body.Close()
	// The closed Body still reaches the connection that served it, through its
	// bufio.Reader, and the Request reaches it through the trace hooks of
	// connTrackingTransport. copyFor sets both, so the entry keeps neither and
	// a closed connection can be freed.
	kept := *resp
	kept.Body = nil
	kept.Request = nil
	entry.response = &storedResponse{response: &kept, body: body}
	t.store(entry)
	return entry.response.copyFor(req), nil
}

// shareableStatus reports whether code is an answer a later template can
// reuse. 404 and 500 are answers templates match on. 429 and the gateway
// errors mean the server did not answer, so the next template must send.
func shareableStatus(code int) bool {
	switch code {
	case http.StatusTooManyRequests, http.StatusBadGateway, http.StatusServiceUnavailable, http.StatusGatewayTimeout:
		return false
	default:
		return true
	}
}

// hasBody reports whether req sends a body. retryablehttp gives every
// request one, empty for a GET, so its content is what counts.
func hasBody(req *http.Request) bool {
	if req.Body == nil || req.Body == http.NoBody {
		return false
	}
	if req.ContentLength > 0 || req.GetBody == nil {
		return true
	}
	body, err := req.GetBody()
	if err != nil {
		return true
	}
	defer func() { _ = body.Close() }()
	var first [1]byte
	n, _ := body.Read(first[:])
	return n > 0
}

func (t *sharingTransport) forget(entry *sharedEntry) {
	t.shared.mu.Lock()
	defer t.shared.mu.Unlock()
	if t.shared.entries[entry.key] == entry {
		delete(t.shared.entries, entry.key)
	}
}

func (t *sharingTransport) store(entry *sharedEntry) {
	t.shared.mu.Lock()
	defer t.shared.mu.Unlock()
	// a reset while it was in flight dropped it
	if t.shared.entries[entry.key] != entry {
		return
	}
	t.shared.order.PushBack(entry)
	t.shared.bytes += entry.size()
	for t.shared.bytes > t.shared.maxBytes && t.shared.order.Len() > 1 {
		oldest := t.shared.order.Remove(t.shared.order.Front()).(*sharedEntry)
		t.shared.bytes -= oldest.size()
		if t.shared.entries[oldest.key] == oldest {
			delete(t.shared.entries, oldest.key)
		}
	}
}

// sharedEntryOverhead stands for the response struct and bookkeeping, so
// bodyless responses, as every HEAD gets, still count toward the cap.
const sharedEntryOverhead = 512

func (e *sharedEntry) size() int {
	size := sharedEntryOverhead + len(e.key) + len(e.response.body)
	for name, values := range e.response.response.Header {
		size += len(name)
		for _, value := range values {
			size += len(value)
		}
	}
	return size
}

func (s *storedResponse) copyFor(req *http.Request) *http.Response {
	resp := *s.response
	resp.Header = s.response.Header.Clone()
	resp.Trailer = s.response.Trailer.Clone()
	resp.Body = io.NopCloser(bytes.NewReader(s.body))
	// A HEAD response has an empty body and a Content-Length for the body it
	// did not send. Matchers read that length, so a reused HEAD keeps it.
	if req.Method != http.MethodHead {
		resp.ContentLength = int64(len(s.body))
	}
	resp.Request = req
	return &resp
}

// randomUserAgents are the values nuclei picks a User-Agent from for every
// request a template does not set one for. Two templates sending the same
// request almost never pick the same one, and either could have picked the
// other's, so a picked User-Agent is left out of the key.
var randomUserAgents = sync.OnceValue(func() map[string]struct{} {
	values := make(map[string]struct{}, len(useragent.UserAgents))
	for _, userAgent := range useragent.UserAgents {
		values[userAgent.Raw] = struct{}{}
	}
	return values
})

// sharedRequestKey is the request as the server receives it, apart from the
// order of headers and a picked User-Agent.
func sharedRequestKey(req *http.Request) string {
	var key strings.Builder
	key.WriteString(req.Method)
	key.WriteByte(' ')
	key.WriteString(req.URL.String())
	key.WriteByte('\n')
	key.WriteString(req.Host)
	for _, name := range slices.Sorted(maps.Keys(req.Header)) {
		values := req.Header[name]
		if _, picked := randomUserAgents()[req.Header.Get("User-Agent")]; name == "User-Agent" && len(values) == 1 && picked {
			continue
		}
		for _, value := range values {
			key.WriteByte('\n')
			key.WriteString(name)
			key.WriteString(": ")
			key.WriteString(value)
		}
	}
	return key.String()
}

package httpclientpool

import (
	"container/list"
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/tlsverify"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/useragent"
	"github.com/stretchr/testify/require"
)

func newSharingTransport(base http.RoundTripper) *sharingTransport {
	return &sharingTransport{base: base, shared: &sharedResponses{entries: make(map[string]*sharedEntry), order: list.New(), maxBytes: sharedResponsesMaxBytes}}
}

func sharedGet(t *testing.T, transport http.RoundTripper, method, url, templateID string, header http.Header) string {
	t.Helper()
	ctx := context.Background()
	if templateID != "" {
		ctx = WithSharedResponse(ctx, templateID)
	}
	req, err := http.NewRequestWithContext(ctx, method, url, nil)
	require.NoError(t, err)
	for name, values := range header {
		req.Header[name] = values
	}
	resp, err := transport.RoundTrip(req)
	require.NoError(t, err)
	defer func() { _ = resp.Body.Close() }()
	body, err := io.ReadAll(resp.Body)
	require.NoError(t, err)
	return string(body)
}

func TestSharedResponsesSendEachRequestOncePerScan(t *testing.T) {
	var hits atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		n := hits.Add(1)
		_, _ = io.WriteString(w, r.URL.Path+strings.Repeat("!", int(n)))
	}))
	defer server.Close()
	transport := newSharingTransport(http.DefaultTransport)

	first := sharedGet(t, transport, http.MethodGet, server.URL+"/a", "one", nil)
	require.Equal(t, first, sharedGet(t, transport, http.MethodGet, server.URL+"/a", "two", nil), "another template gets the stored response")
	require.EqualValues(t, 1, hits.Load())

	// nuclei builds a GET with an empty body
	empty, err := retryablehttp.NewRequestWithContext(WithSharedResponse(context.Background(), "four"), http.MethodGet, server.URL+"/a", strings.NewReader(""))
	require.NoError(t, err)
	resp, err := transport.RoundTrip(empty.Request)
	require.NoError(t, err)
	_ = resp.Body.Close()
	require.EqualValues(t, 1, hits.Load(), "an empty body is no body")

	sharedGet(t, transport, http.MethodGet, server.URL+"/a", "one", nil)
	require.EqualValues(t, 2, hits.Load(), "a template repeating its own request sends it")

	sharedGet(t, transport, http.MethodGet, server.URL+"/a", "", nil)
	require.EqualValues(t, 3, hits.Load(), "an unmarked request is always sent")

	sharedGet(t, transport, http.MethodGet, server.URL+"/a", "three", http.Header{"Cookie": {"session=1"}})
	require.EqualValues(t, 4, hits.Load(), "other cookies make another request")

	picked := func(i int) http.Header { return http.Header{"User-Agent": {useragent.UserAgents[i].Raw}} }
	sharedGet(t, transport, http.MethodGet, server.URL+"/b", "one", picked(0))
	sharedGet(t, transport, http.MethodGet, server.URL+"/b", "two", picked(1))
	require.EqualValues(t, 5, hits.Load(), "a User-Agent nuclei picked at random is not part of the request")
	sharedGet(t, transport, http.MethodGet, server.URL+"/b", "three", http.Header{"User-Agent": {"custom-scanner"}})
	require.EqualValues(t, 6, hits.Load(), "one a template sets is")

	for range 2 {
		// A new request each time. Clone shares the body, so a second clone
		// of one request can send ContentLength with an already-read body.
		req, err := http.NewRequestWithContext(WithSharedResponse(context.Background(), "one"), http.MethodPost, server.URL+"/a", strings.NewReader("x"))
		require.NoError(t, err)
		resp, err := transport.RoundTrip(req)
		require.NoError(t, err)
		_ = resp.Body.Close()
	}
	require.EqualValues(t, 8, hits.Load(), "a request with a body is always sent")
}

func TestSharedResponsesReleaseTheConnection(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Connection", "close")
		_, _ = io.WriteString(w, r.URL.Path)
	}))
	defer server.Close()

	var released atomic.Bool
	var dialer net.Dialer
	base := &http.Transport{DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
		conn, err := dialer.DialContext(ctx, network, addr)
		if tcp, ok := conn.(*net.TCPConn); ok {
			runtime.AddCleanup(tcp, func(struct{}) { released.Store(true) }, struct{}{})
		}
		return conn, err
	}}
	transport := newSharingTransport(base)

	require.Equal(t, "/a", sharedGet(t, transport, http.MethodGet, server.URL+"/a", "one", nil))
	require.Len(t, transport.shared.entries, 1)
	require.Eventually(t, func() bool {
		runtime.GC()
		return released.Load()
	}, 5*time.Second, 10*time.Millisecond, "the stored response keeps the closed connection it came from")
	require.Equal(t, "/a", sharedGet(t, transport, http.MethodGet, server.URL+"/a", "two", nil), "the entry is still served")
}

func TestSharedResponsesWaitForTheRequestInFlight(t *testing.T) {
	var hits atomic.Int32
	release := make(chan struct{})
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		<-release
		_, _ = io.WriteString(w, "slow")
	}))
	defer server.Close()
	transport := newSharingTransport(http.DefaultTransport)

	var wg sync.WaitGroup
	bodies := make([]string, 5)
	for i := range bodies {
		wg.Add(1)
		go func() {
			defer wg.Done()
			bodies[i] = sharedGet(t, transport, http.MethodGet, server.URL, "template-"+string(rune('a'+i)), nil)
		}()
	}
	require.Eventually(t, func() bool { return hits.Load() > 0 }, 5*time.Second, time.Millisecond)
	close(release)
	wg.Wait()
	require.EqualValues(t, 1, hits.Load())
	require.Equal(t, []string{"slow", "slow", "slow", "slow", "slow"}, bodies)
}

