	base   http.RoundTripper
}

func (f *failOnce) RoundTrip(req *http.Request) (*http.Response, error) {
	if f.failed.CompareAndSwap(false, true) {
		return nil, errors.New("connection reset")
	}
	return f.base.RoundTrip(req)
}

