// A plain request under -project must decode a legacy charset once, both when
// the response comes from the server and when it is replayed from the cache.
func TestProjectCacheReplayDecodesCharsetOnce(t *testing.T) {
	cases := []struct {
		name    string
		charset string
		enc     encoding.Encoding
		text    string
	}{
		{name: "windows-1251", charset: "windows-1251", enc: charmap.Windows1251, text: "Привет, мир"},
		{name: "gbk", charset: "gbk", enc: simplifiedchinese.GBK, text: "你好，世界"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			encoded, err := tc.enc.NewEncoder().String(tc.text)
			require.NoError(t, err)
			ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "text/plain; charset="+tc.charset)
				_, _ = w.Write([]byte(encoded))
			}))
			defer ts.Close()

			project, err := projectfile.New(&projectfile.Options{Path: t.TempDir(), Cleanup: true})
			require.NoError(t, err)
			defer project.Close()

			execute := func(t *testing.T) string {
				options := testutils.DefaultOptions
				testutils.Init(options)
				request := &Request{
					ID:   "project-charset",
					Path: []string{"{{BaseURL}}"},
					Operators: operators.Operators{Extractors: []*extractors.Extractor{{
						Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
						DSL:  []string{"body"},
					}}},
				}
				executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
					ID:   "project-charset",
					Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Info}, Name: "test"},
				})
				executerOpts.ProjectFile = project
				require.NoError(t, request.Compile(executerOpts))

				var event output.InternalEvent
				err := request.ExecuteWithResults(contextargs.NewWithInput(context.Background(), ts.URL), output.InternalEvent{}, output.InternalEvent{}, func(e *output.InternalWrappedEvent) {
					event = e.InternalEvent
				})
				require.NoError(t, err)
				body, _ := event["body"].(string)
				return body
			}

			require.Equal(t, tc.text, execute(t), "first run decodes the response")
			require.Equal(t, tc.text, execute(t), "replayed run must not decode the body again")
		})
	}
}

package race

import (
	"fmt"
	"io"
	"sync/atomic"
	"time"
)

// SyncedReadCloser is compatible with io.ReadSeeker and performs
// gate-based synced writes to enable race condition testing.
type SyncedReadCloser struct {
	data     []byte
	p        int64
	length   int64
	openGate chan struct{}
	// enableBlocking is read by the transport's read goroutine and written
	// by callers (SetOpenGate) and by Read itself, hence atomic.
	enableBlocking atomic.Bool
}

// NewSyncedReadCloser creates a new SyncedReadCloser instance.
func NewSyncedReadCloser(r io.ReadCloser) *SyncedReadCloser {
	var (
		s   SyncedReadCloser
		err error
	)
	s.data, err = io.ReadAll(r)
	if err != nil {
		return nil
	}
	defer func() {
		_ = r.Close()
	}()
	s.length = int64(len(s.data))
	s.openGate = make(chan struct{}, 1)
	s.enableBlocking.Store(true)
	return &s
}

// NewOpenGateWithTimeout creates a new open gate with a timeout
func NewOpenGateWithTimeout(r io.ReadCloser, d time.Duration) *SyncedReadCloser {
	s := NewSyncedReadCloser(r)
	s.OpenGateAfter(d)
	return s
}

// SetOpenGate sets the status of the blocking gate
func (s *SyncedReadCloser) SetOpenGate(status bool) {
	s.enableBlocking.Store(status)
}

// OpenGate opens the gate allowing all requests to be completed
func (s *SyncedReadCloser) OpenGate() {
	select {
	case s.openGate <- struct{}{}:
	default:
	}
}

// OpenGateAfter schedules gate to be opened after a duration
func (s *SyncedReadCloser) OpenGateAfter(d time.Duration) {
	time.AfterFunc(d, func() {
		select {
		case s.openGate <- struct{}{}:
		default:
		}
	})
}

// Seek implements seek method for io.ReadSeeker
func (s *SyncedReadCloser) Seek(offset int64, whence int) (int64, error) {
	var err error
	switch whence {
	case io.SeekStart:
		s.p = 0
	case io.SeekCurrent:
		if s.p+offset < s.length {
			s.p += offset
			break
		}
		err = fmt.Errorf("offset is too big")
	case io.SeekEnd:
		if s.length-offset >= 0 {
			s.p = s.length - offset
			break
		}
		err = fmt.Errorf("offset is too big")
	}
	return s.p, err
}

// Read implements read method for io.ReadSeeker
func (s *SyncedReadCloser) Read(p []byte) (n int, err error) {
	// If the data fits in the buffer blocks awaiting the sync instruction
	if s.p+int64(len(p)) >= s.length && s.enableBlocking.Load() {
		<-s.openGate
		// Once the gate opens, disable blocking so that subsequent reads
		// (e.g. after the retryablehttp client seeks back and re-reads)
		// pass through without deadlocking.
		s.enableBlocking.Store(false)
	}
	n = copy(p, s.data[s.p:])
	s.p += int64(n)
	if s.p == s.length {
		err = io.EOF
	}
	return n, err
}

// Close closes an io.ReadSeeker
func (s *SyncedReadCloser) Close() error {
	return nil
}

// Len returns the length of data in reader
func (s *SyncedReadCloser) Len() int {
	return int(s.length)
}

//go:build gofuzz
// +build gofuzz

package raw

// Fuzz exercises raw HTTP request parsing in safe, unsafe, self-contained, and
// path-automerge modes.
func Fuzz(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	if len(data) > fuzzMaxInputSize {
		return -1
	}
	if !fuzzRawHTTPParsing(data) {
		return 0
	}
	return 1
}

package raw

import (
	"fmt"
	"strings"

	urlutil "github.com/projectdiscovery/utils/url"
)

const (
	fuzzMaxInputSize  = 16 << 10
	fuzzMaxHeaders    = 8
	fuzzMaxValueBytes = 256
)

var (
	fuzzRawMethods = []string{"GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS", "HEAD"}
	fuzzRawPaths   = []string{"/", "", "/admin/login", "/api/v1/users?id=1", "1337?with=param", "http://127.0.0.1/foo?id=1"}
	fuzzRawHosts   = []string{"example.com", "{{Hostname}}", "127.0.0.1", "example.com:8080"}
	fuzzInputURLs  = []string{"https://example.com", "https://example.com/base", "http://target.local:8080/root?x=1", "http://httpbin.org/bar"}
)

type fuzzRawHeader struct {
	key   string
	value string
}

type fuzzRawHTTPCandidate struct {
	method               string
	path                 string
	host                 string
	inputURL             string
	unsafe               bool
	disablePathAutomerge bool
	headers              []fuzzRawHeader
	body                 string
}

func fuzzRawHTTPParsing(data []byte) bool {
	rawRequest, inputURL, unsafe, disablePathAutomerge, ok := rawHTTPRequestFromFuzzData(data)
	if !ok {
		return false
	}

	parsedURL, err := urlutil.Parse(inputURL)
	if err != nil {
		return false
	}

	parsed := false
	for _, unsafeMode := range fuzzBoolCases(unsafe) {
		for _, disableAutomerge := range fuzzBoolCases(disablePathAutomerge) {
			request, parseErr := Parse(rawRequest, parsedURL.Clone(), unsafeMode, disableAutomerge)
			if parseErr == nil {
				exerciseFuzzRawRequest(request)
				parsed = true
			}
		}

		request, parseErr := ParseRawRequest(rawRequest, unsafeMode)
		if parseErr == nil {
			exerciseFuzzRawRequest(request)
			parsed = true
		}
	}

	if looksLikeRawHTTPRequest(data) {
		rawInput := string(data)
		for _, unsafeMode := range []bool{false, true} {
			request, parseErr := Parse(rawInput, parsedURL.Clone(), unsafeMode, disablePathAutomerge)
			if parseErr == nil {
				exerciseFuzzRawRequest(request)
				parsed = true
			}

			request, parseErr = ParseRawRequest(rawInput, unsafeMode)
			if parseErr == nil {
				exerciseFuzzRawRequest(request)
				parsed = true
			}
		}
	}

	return parsed
}

func rawHTTPRequestFromFuzzData(data []byte) (string, string, bool, bool, bool) {
	if len(data) == 0 || len(data) > fuzzMaxInputSize {
		return "", "", false, false, false
	}

	candidate := newFuzzRawHTTPCandidate(data)
	candidate.applyLines(splitFuzzLines(data))
	return candidate.build(), candidate.inputURL, candidate.unsafe, candidate.disablePathAutomerge, true
}

func newFuzzRawHTTPCandidate(data []byte) *fuzzRawHTTPCandidate {
	flags := fuzzByteAt(data, 1)
	return &fuzzRawHTTPCandidate{
		method:               fuzzRawMethods[int(fuzzByteAt(data, 0))%len(fuzzRawMethods)],
		path:                 fuzzRawPaths[int(fuzzByteAt(data, 2))%len(fuzzRawPaths)],
		host:                 fuzzRawHosts[int(fuzzByteAt(data, 3))%len(fuzzRawHosts)],
		inputURL:             fuzzInputURLs[int(fuzzByteAt(data, 4))%len(fuzzInputURLs)],
		unsafe:               flags&0x01 != 0,
		disablePathAutomerge: flags&0x02 != 0,
		headers: []fuzzRawHeader{
			{key: "User-Agent", value: "nuclei-fuzz"},
		},
		body: fuzzRawBody(string(data)),
	}
}

func (candidate *fuzzRawHTTPCandidate) applyLines(lines []string) {
	for _, line := range lines {
		key, value, ok := cutFuzzKV(line)
		if !ok {
			candidate.body = fuzzRawBody(line)
			continue
		}

		switch key {
		case "method":
			candidate.method = fuzzRawMethod(value, candidate.method)
		case "path":
			if value == "" {
				candidate.path = ""
			} else {
				candidate.path = fuzzRawPath(value, candidate.path)
			}
		case "host":
			candidate.host = fuzzRawHost(value, candidate.host)
		case "input-url", "url":
			candidate.inputURL = fuzzRawInputURL(value, candidate.inputURL)
		case "unsafe":
			candidate.unsafe = fuzzRawBool(value, candidate.unsafe)
		case "disable-automerge", "disable-path-automerge":
			candidate.disablePathAutomerge = fuzzRawBool(value, candidate.disablePathAutomerge)
		case "header":
			candidate.addHeader(value)
		case "body":
			candidate.body = fuzzRawBody(value)
		}
	}
}

func (candidate *fuzzRawHTTPCandidate) addHeader(value string) {
	key, headerValue, ok := strings.Cut(value, ":")
	if !ok {
		key, headerValue, ok = strings.Cut(value, "=")
	}
	if !ok {
		return
	}

	key = fuzzRawHeaderKey(key)
	if key == "" || strings.EqualFold(key, "Host") || len(candidate.headers) >= fuzzMaxHeaders {
		return
	}
	candidate.headers = append(candidate.headers, fuzzRawHeader{key: key, value: fuzzRawHeaderValue(headerValue)})
}

func (candidate *fuzzRawHTTPCandidate) build() string {
	var builder strings.Builder
	if candidate.path == "" {
		fmt.Fprintf(&builder, "%s HTTP/1.1\r\n", candidate.method)
	} else {
		fmt.Fprintf(&builder, "%s %s HTTP/1.1\r\n", candidate.method, candidate.path)
	}
	fmt.Fprintf(&builder, "Host: %s\r\n", candidate.host)
	for _, header := range candidate.headers {
		fmt.Fprintf(&builder, "%s: %s\r\n", header.key, header.value)
	}
	builder.WriteString("\r\n")
	builder.WriteString(candidate.body)
	return builder.String()
}

func exerciseFuzzRawRequest(request *Request) {
	if request == nil {
		panic("nil raw request")
	}
	_ = request.FullURL
	_ = request.Method
	_ = request.Path
	_ = request.Data
	if len(request.UnsafeRawBytes) > 0 {
		_ = request.TryFillCustomHeaders([]string{"X-Fuzz: 1"})
	}
}

func looksLikeRawHTTPRequest(data []byte) bool {
	line := string(data)
	if index := strings.IndexAny(line, "\r\n"); index >= 0 {
		line = line[:index]
	}
	parts := strings.Fields(line)
	return len(parts) >= 3 && strings.HasPrefix(parts[2], "HTTP/")
}

func fuzzBoolCases(value bool) []bool {
	if value {
		return []bool{true, false}
	}
	return []bool{false, true}
}

func splitFuzzLines(data []byte) []string {
	fields := strings.FieldsFunc(string(data), func(r rune) bool {
		return r == '\n' || r == '\r' || r == ';'
	})
	if len(fields) > fuzzMaxHeaders*4 {
		fields = fields[:fuzzMaxHeaders*4]
	}

	lines := make([]string, 0, len(fields))
	for _, field := range fields {
		field = fuzzTrim(field)
		if field != "" {
			lines = append(lines, field)
		}
	}
	return lines
}

func cutFuzzKV(line string) (string, string, bool) {
	key, value, ok := strings.Cut(line, "=")
	if !ok {
		key, value, ok = strings.Cut(line, ":")
	}
	if !ok {
		return "", "", false
	}
	return strings.ToLower(fuzzTrim(key)), fuzzTrim(value), true
}

func fuzzByteAt(data []byte, index int) byte {
	if len(data) == 0 {
		return 0
	}
	return data[index%len(data)]
}

func fuzzRawMethod(value, fallback string) string {
	value = strings.ToUpper(fuzzRawToken(value, 16))
	if value == "" {
		return fallback
	}
	return value
}

func fuzzRawPath(value, fallback string) string {
	value = fuzzTrim(value)
	if value == "" {
		return fallback
	}
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

func fuzzRawInputURL(value, fallback string) string {
	value = fuzzTrim(value)
	if strings.HasPrefix(value, "http://") || strings.HasPrefix(value, "https://") {
		return value
	}
	host := fuzzRawHost(value, "")
	if host == "" {
		return fallback
	}
	return "https://" + host + "/"
}

func fuzzRawHost(value, fallback string) string {
	value = strings.TrimSpace(strings.NewReplacer("\x00", "", "\r", "", "\n", "", "/", "", "\\", "").Replace(value))
	if value == "{{Hostname}}" || value == "{{BaseURL}}" {
		return value
	}

	value = strings.ToLower(value)
	var builder strings.Builder
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r)
		case r >= '0' && r <= '9':
			builder.WriteRune(r)
		case r == '.' || r == '-' || r == ':':
			builder.WriteRune(r)
		}
		if builder.Len() >= 128 {
			break
		}
	}
	if builder.Len() == 0 {
		return fallback
	}
	return builder.String()
}

func fuzzRawHeaderKey(value string) string {
	return fuzzRawToken(value, 64)
}

func fuzzRawHeaderValue(value string) string {
	return fuzzTrim(value)
}

func fuzzRawBody(value string) string {
	value = strings.ReplaceAll(value, "\x00", "")
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

func fuzzRawBool(value string, fallback bool) bool {
	switch strings.ToLower(fuzzTrim(value)) {
	case "1", "t", "true", "yes", "y", "on":
		return true
	case "0", "f", "false", "no", "n", "off":
		return false
	default:
		return fallback
	}
}

func fuzzRawToken(value string, limit int) string {
	value = fuzzTrim(value)
	var builder strings.Builder
	for _, r := range value {
		switch {
		case r >= 'a' && r <= 'z':
			builder.WriteRune(r - 'a' + 'A')
		case r >= 'A' && r <= 'Z':
			builder.WriteRune(r)
		case r >= '0' && r <= '9':
			builder.WriteRune(r)
		case r == '-':
			builder.WriteRune(r)
		}
		if builder.Len() >= limit {
			break
		}
	}
	return builder.String()
}

func fuzzTrim(value string) string {
	value = strings.TrimSpace(strings.NewReplacer("\x00", "", "\r", " ", "\n", " ").Replace(value))
	if len(value) > fuzzMaxValueBytes {
		value = value[:fuzzMaxValueBytes]
	}
	return value
}

package raw

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"strings"
	"sync"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/authprovider/authx"
	"github.com/projectdiscovery/rawhttp/client"
	"github.com/projectdiscovery/utils/errkit"
	urlutil "github.com/projectdiscovery/utils/url"
)

var bufferPool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

// Request defines a basic HTTP raw request
type Request struct {
	FullURL        string
	Method         string
	Path           string
	Data           string
	Headers        map[string]string
	UnsafeHeaders  client.Headers
	UnsafeRawBytes []byte
}

// Parse parses the raw request as supplied by the user
func Parse(request string, inputURL *urlutil.URL, unsafe, disablePathAutomerge bool) (*Request, error) {
	rawrequest, err := readRawRequest(request, unsafe)
	if err != nil {
		return nil, err
	}

	// handle full URLs first (before checking unsafe flag) to extract relative path
	lowerPath := strings.ToLower(rawrequest.Path)
	hasAbsoluteRequestTarget := strings.HasPrefix(lowerPath, "http://") || strings.HasPrefix(lowerPath, "https://")
	if hasAbsoluteRequestTarget {
		var requestTarget string
		if strings.HasPrefix(lowerPath, "http://") {
			requestTarget = "http://" + rawrequest.Path[len("http://"):]
		} else {
			requestTarget = "https://" + rawrequest.Path[len("https://"):]
		}

		urlx, err := urlutil.ParseAbsoluteURL(requestTarget, true)
		if err != nil {
			return nil, errkit.Wrapf(err, "failed to parse url %v from template", rawrequest.Path)
		}
		relPath := urlx.GetRelativePath()

		// rotate full URL with rel path
		rawrequest.Path = relPath
		if unsafe {
			cloned := inputURL.Clone()
			cloned.Path = ""
			cloned.Fragment = ""
			cloned.Params = urlutil.NewOrderedParams()
			cloned.Params.IncludeEquals = true

			if err := cloned.MergePath(relPath, true); err != nil {
				return nil, errkit.Wrapf(err, "failed to build request url for absolute target %v", requestTarget)
			}

			rawrequest.FullURL = cloned.String()

			return rawrequest, nil
		}
	}

	switch {
	// If path is empty do not tamper input url (see doc)
	// can be omitted but makes things clear
	case rawrequest.Path == "":
		if !disablePathAutomerge {
			inputURL.Params.IncludeEquals = true
			rawrequest.Path = inputURL.GetRelativePath()
		}

	// If unsafe changes must be made in raw request string itself
	case unsafe:
		prevPath := rawrequest.Path
		cloned := inputURL.Clone()
		cloned.Params.IncludeEquals = true
		unsafeRelativePath := ""
		if (cloned.Path == "" || cloned.Path == "/") && !strings.HasPrefix(prevPath, "/") {
			// Edgecase if raw unsafe request is
			// GET 1337?with=param HTTP/1.1
			if tmpurl, err := urlutil.ParseRelativePath(prevPath, true); err == nil && !tmpurl.Params.IsEmpty() {
				// if raw request contains parameters
				cloned.Params.Merge(tmpurl.Params.Encode())
				unsafeRelativePath = strings.TrimPrefix(tmpurl.Path, "/") + "?" + cloned.Params.Encode()
			} else {
				// if raw request does not contain param
				if !cloned.Params.IsEmpty() {
					unsafeRelativePath = prevPath + "?" + cloned.Params.Encode()
				} else {
					unsafeRelativePath = prevPath
				}
			}
		} else {
			// Edgecase if raw request is
			// GET / HTTP/1.1
			//use case: https://github.com/projectdiscovery/nuclei/issues/4921
			if rawrequest.Path == "/" && cloned.Path != "" {
				rawrequest.Path = ""
			}

			if disablePathAutomerge {
				cloned.Path = ""
			}
			err = cloned.MergePath(rawrequest.Path, true)
			if err != nil {
				return nil, errkit.Wrapf(err, "failed to automerge %v from unsafe template", rawrequest.Path)
			}
			unsafeRelativePath = cloned.GetRelativePath()
		}
		rawrequest.Path = cloned.GetRelativePath()
		rawrequest.UnsafeRawBytes = bytes.Replace(rawrequest.UnsafeRawBytes, []byte(prevPath), []byte(unsafeRelativePath), 1)

	default:
		cloned := inputURL.Clone()
		cloned.Params.IncludeEquals = true
		// Edgecase if raw request is
		// GET / HTTP/1.1
		//use case: https://github.com/projectdiscovery/nuclei/issues/4921
		if rawrequest.Path == "/" {
			rawrequest.Path = ""
		}

		if disablePathAutomerge {
			cloned.Path = ""
		}
		parseErr := cloned.MergePath(rawrequest.Path, true)
		if parseErr != nil {
			return nil, errkit.Wrapf(parseErr, "could not automergepath for template path %v", rawrequest.Path)
		}
		rawrequest.Path = cloned.GetRelativePath()
	}

	if !unsafe {
		if _, ok := rawrequest.Headers["Host"]; !ok {
			rawrequest.Headers["Host"] = inputURL.Host
		}
		cloned := inputURL.Clone()
		cloned.Params.IncludeEquals = true
		cloned.Path = ""
		_ = cloned.MergePath(rawrequest.Path, true)
		rawrequest.FullURL = cloned.String()
	}

	return rawrequest, nil
}

// ParseRawRequest parses the raw request as supplied by the user
// this function should only be used for self-contained requests
func ParseRawRequest(request string, unsafe bool) (*Request, error) {
	req, err := readRawRequest(request, unsafe)
	if err != nil {
		return nil, err
	}
	if strings.HasPrefix(req.Path, "http") {
		urlx, err := urlutil.Parse(req.Path)
		if err != nil {
			return nil, errkit.Wrapf(err, "failed to parse url %v", req.Path)
		}
		req.Path = urlx.GetRelativePath()
		req.FullURL = urlx.String()
	} else {

		if req.Path == "" {
			return nil, errkit.New("path cannot be empty in self contained request")
		}
		// given url is relative construct one using Host Header
		if _, ok := req.Headers["Host"]; !ok {
			return nil, errkit.New("host header is required for relative path")
		}
		// Review: Current default scheme in self contained templates if relative path is provided is http
		req.FullURL = fmt.Sprintf("%s://%s%s", urlutil.HTTP, strings.TrimSpace(req.Headers["Host"]), req.Path)
	}
	return req, nil
}

// reads raw request line by line following convention
func readRawRequest(request string, unsafe bool) (*Request, error) {
	rawRequest := &Request{
		Headers: make(map[string]string),
	}

	_, request = SplitAnnotations(request)

	// store body if it is unsafe request
	if unsafe {
		rawRequest.UnsafeRawBytes = []byte(request)
	}

	// parse raw request
	source := strings.NewReader(request)
	reader := bufio.NewReader(source)
	s, err := reader.ReadString('\n')
	if err != nil {
		return nil, fmt.Errorf("could not read request: %w", err)
	}

	parts := strings.Fields(s)
	if len(parts) > 0 {
		rawRequest.Method = parts[0]
		// Only a version token may stand in for the missing path. A substring
		// test also matched any path containing "HTTP", e.g. "GET /HTTPProxy",
		// and dropped the path.
		if len(parts) == 2 && strings.HasPrefix(parts[1], "HTTP/") {
			// When relative path is missing/ not specified it is considered that
			// request is meant to be untampered at path
			// Ex: GET HTTP/1.1
			parts = []string{parts[0], "", parts[1]}
		}
		if len(parts) < 3 && !unsafe {
			// missing a field
			return nil, fmt.Errorf("malformed request specified: %v", s)
		}

		// relative path
		if len(parts) > 1 {
			rawRequest.Path = parts[1]
		}
		// Note: raw request does not URL Encode if needed `+` should be used
		// this can be also be implemented
	}

	var multiPartRequest bool
	// Accepts all malformed headers
	for {
		line, readErr := reader.ReadString('\n')
		line = strings.TrimSpace(line)

		// An empty line ends the header block, whether it arrived with a read
		// error or not. Falling through on io.EOF stored a header named "",
		// which rawhttp serializes as a bare CRLF and so truncates the header
		// block it is supposed to be part of.
		if line == "" {
			break
		}
		if readErr != nil && readErr != io.EOF {
			break
		}

		// Declared per line on purpose. While these were reused across
		// iterations, a line carrying no colon left value holding whatever the
		// line before it had, so the previous header's value was stored under
		// this line's name and sent on the wire.
		p := strings.SplitN(line, ":", 2)
		key := p[0]
		var value string
		if len(p) > 1 {
			value = p[1]
		}
		if strings.Contains(key, "Content-Type") && strings.Contains(value, "multipart/") {
			multiPartRequest = true
		}

		// in case of unsafe requests multiple headers should be accepted
		// therefore use the full line as key
		_, found := rawRequest.Headers[key]
		if unsafe {
			rawRequest.UnsafeHeaders = append(rawRequest.UnsafeHeaders, client.Header{Key: line})
		}

		if unsafe && found {
			rawRequest.Headers[line] = ""
		} else {
			rawRequest.Headers[key] = strings.TrimSpace(value)
		}
		if readErr == io.EOF {
			break
		}
	}

	// Set the request body. It is sliced from the request rather than read
	// from the reader, which would copy a large body twice.
	rawRequest.Data = request[len(request)-source.Len()-reader.Buffered():]
	if !multiPartRequest {
		rawRequest.Data = strings.TrimSuffix(rawRequest.Data, "\r\n")
	}
	return rawRequest, nil

}

// SplitAnnotations splits a raw request into its annotations and the request
// that follows them. Annotations are the lines starting with "@" before the
// request line. A line starting with "@" after the request line is part of the
// request, so text rendered into the headers or the body never becomes an
// annotation.
func SplitAnnotations(request string) (annotations, rest string) {
	rest = request
	for strings.HasPrefix(rest, "@") {
		_, rest, _ = strings.Cut(rest, "\n")
	}

	return request[:len(request)-len(rest)], rest
}

// TryFillCustomHeaders after the Host header
func (r *Request) TryFillCustomHeaders(headers []string) error {
	unsafeBytes := bytes.ToLower(r.UnsafeRawBytes)
	// locate first host header
	hostHeaderIndex := bytes.Index(unsafeBytes, []byte("host:"))
	if hostHeaderIndex > 0 {
		// attempt to locate next newline
		newLineIndex := bytes.Index(unsafeBytes[hostHeaderIndex:], []byte("\r\n"))
		if newLineIndex > 0 {
			newLineIndex += hostHeaderIndex + 2
			// insert custom headers
			buf := bufferPool.Get().(*bytes.Buffer)
			buf.Reset()
			buf.Write(r.UnsafeRawBytes[:newLineIndex])
			for _, header := range headers {
				buf.WriteString(header)
				buf.WriteString("\r\n")
			}
			buf.Write(r.UnsafeRawBytes[newLineIndex:])
			r.UnsafeRawBytes = append([]byte(nil), buf.Bytes()...)
			buf.Reset()
			bufferPool.Put(buf)
			return nil
		}
		return errors.New("no new line found at the end of host header")
	}

	return errors.New("no host header found")
}

// ApplyAuthStrategy applies the auth strategy to the request
func (r *Request) ApplyAuthStrategy(strategy authx.AuthStrategy) {
	if strategy == nil {
		return
	}
	switch s := strategy.(type) {
	case *authx.QueryAuthStrategy:
		parsed, err := urlutil.Parse(r.FullURL)
		if err != nil {
			gologger.Error().Msgf("auth strategy failed to parse url: %s got %v", r.FullURL, err)
			return
		}
		for _, p := range s.Data.Params {
			parsed.Params.Add(p.Key, p.Value)
		}
		r.FullURL = parsed.String()
	case *authx.CookiesAuthStrategy:
		buff := bufferPool.Get().(*bytes.Buffer)
		buff.Reset()
		for _, cookie := range s.Data.Cookies {
			fmt.Fprintf(buff, "%s=%s; ", cookie.Key, cookie.Value)
		}
		if buff.Len() > 0 {
			if val, ok := r.Headers["Cookie"]; ok {
				r.Headers["Cookie"] = strings.TrimSuffix(strings.TrimSpace(val), ";") + "; " + buff.String()
			} else {
				r.Headers["Cookie"] = buff.String()
			}
		}
		bufferPool.Put(buff)
	case *authx.HeadersAuthStrategy:
		for _, header := range s.Data.Headers {
			r.Headers[header.Key] = header.Value
		}
	case *authx.BearerTokenAuthStrategy:
		r.Headers["Authorization"] = "Bearer " + s.Data.Token
	case *authx.BasicAuthStrategy:
		r.Headers["Authorization"] = "Basic " + base64.StdEncoding.EncodeToString([]byte(s.Data.Username+":"+s.Data.Password))
	default:
		gologger.Warning().Msgf("[raw-request] unknown auth strategy: %T", s)
	}
}

package raw

import (
	"encoding/base64"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/authprovider/authx"
