func TestRawBodyKeepsTheBytesAsReceived(t *testing.T) {
	var compressed bytes.Buffer
	writer := gzip.NewWriter(&compressed)
	writer.ModTime = time.Unix(1700000000, 0)
	_, _ = writer.Write([]byte(`{"hello":"world"}`))
	require.NoError(t, writer.Close())
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Encoding", "gzip")
		_, _ = w.Write(compressed.Bytes())
	}))
	defer ts.Close()

	execute := func(t *testing.T, project *projectfile.ProjectFile, extractor *extractors.Extractor) output.InternalEvent {
		options := testutils.DefaultOptions
		testutils.Init(options)
		request := &Request{
			ID:        "raw-body",
			Path:      []string{"{{BaseURL}}"},
			Operators: operators.Operators{Extractors: []*extractors.Extractor{extractor}},
		}
		executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
			ID:   "raw-body",
			Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Info}, Name: "test"},
		})
		executerOpts.ProjectFile = project
		require.NoError(t, request.Compile(executerOpts))

		var event output.InternalEvent
		err := request.ExecuteWithResults(contextargs.NewWithInput(context.Background(), ts.URL), output.InternalEvent{}, output.InternalEvent{}, func(e *output.InternalWrappedEvent) {
			event = e.InternalEvent
		})
		require.NoError(t, err)
		return event
	}

	t.Run("reading raw_body", func(t *testing.T) {
		event := execute(t, nil, &extractors.Extractor{
			Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
			DSL:  []string{"to_string(gzip_mtime(raw_body))"},
		})
		require.Equal(t, compressed.String(), event["raw_body"])
		require.Contains(t, event["raw_response"], compressed.String())
		require.Equal(t, `{"hello":"world"}`, event["body"], "body stays decoded")
	})
	t.Run("not reading it", func(t *testing.T) {
		event := execute(t, nil, &extractors.Extractor{
			Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
			DSL:  []string{"body"},
		})
		require.NotContains(t, event, "raw_body")
		require.Equal(t, `{"hello":"world"}`, event["body"])
	})
	t.Run("not reading it under -project", func(t *testing.T) {
		project, err := projectfile.New(&projectfile.Options{Path: t.TempDir(), Cleanup: true})
		require.NoError(t, err)
		defer project.Close()
		event := execute(t, project, &extractors.Extractor{
			Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
			DSL:  []string{"body"},
		})
		require.NotContains(t, event, "content_encoding", "the transport decodes the response as without -project")
		require.EqualValues(t, len(`{"hello":"world"}`), event["content_length"])
	})
	t.Run("project cache keeps raw and decoded apart", func(t *testing.T) {
		project, err := projectfile.New(&projectfile.Options{Path: t.TempDir(), Cleanup: true})
		require.NoError(t, err)
		defer project.Close()
		plain := &extractors.Extractor{
			Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
			DSL:  []string{"body"},
		}
		raw := &extractors.Extractor{
			Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
			DSL:  []string{"to_string(gzip_mtime(raw_body))"},
		}

		first := execute(t, project, plain)
		require.Equal(t, `{"hello":"world"}`, first["body"])
		second := execute(t, project, raw)
		require.Equal(t, compressed.String(), second["raw_body"], "a raw reader must not reuse the decoded cache entry")
		require.Equal(t, `{"hello":"world"}`, second["body"])

		other, err := projectfile.New(&projectfile.Options{Path: t.TempDir(), Cleanup: true})
		require.NoError(t, err)
		defer other.Close()
		_ = execute(t, other, raw)
		third := execute(t, other, plain)
		require.Equal(t, `{"hello":"world"}`, third["body"], "a plain reader must not reuse the raw cache entry")
		require.EqualValues(t, len(`{"hello":"world"}`), third["content_length"])
	})
}

func TestReadsRawResponse(t *testing.T) {
	readsRaw := func(request *Request, flow string) bool { return reads(request, flow, rawParts...) }
	require.False(t, readsRaw(&Request{Operators: operators.Operators{Matchers: []*matchers.Matcher{{Words: []string{"admin"}}}}}, ""))
	require.True(t, readsRaw(&Request{Operators: operators.Operators{Matchers: []*matchers.Matcher{{Part: "raw_body"}}}}, ""))
	require.True(t, readsRaw(&Request{Operators: operators.Operators{Extractors: []*extractors.Extractor{{DSL: []string{"gzip_mtime(raw_body)"}}}}}, ""))
	require.True(t, readsRaw(&Request{Operators: operators.Operators{Matchers: []*matchers.Matcher{{Part: "raw_response"}}}}, ""))
	require.True(t, readsRaw(&Request{}, "http(1) && template.raw_body != ''"))

	require.False(t, (&Request{readsRawResponse: true}).IsClusterable(), "a cluster runs on one member's response")
}

func TestKeepRawResponsesCoversEveryRequestOfTheTemplate(t *testing.T) {
	newRequests := func() []*Request {
		return []*Request{
			{ID: "first"},
			{Operators: operators.Operators{Extractors: []*extractors.Extractor{{DSL: []string{"gzip_mtime(first_raw_body)"}}}}},
		}
	}

	requests := newRequests()
	KeepRawResponses(requests, "")
	require.True(t, requests[0].readsRawResponse, "a later request reads the raw body of the first")
	require.True(t, requests[1].readsRawResponse)

	requests = []*Request{{ID: "first"}, {ID: "second"}}
	KeepRawResponses(requests, "http(1) && http(2)")
	require.False(t, requests[0].readsRawResponse)
	require.False(t, requests[1].readsRawResponse)
}

func TestKeepRawResponsesSeesRequestConstruction(t *testing.T) {
	marked := []*Request{
		{ID: "first"},
		{Body: "{{first_raw_body}}"},
	}
	KeepRawResponses(marked, "")
	require.True(t, marked[0].readsRawResponse, "the next request's body reads the raw body")
	require.True(t, marked[1].readsRawResponse)

	for _, request := range []*Request{
		{Path: []string{"{{BaseURL}}/{{http_1_raw_response}}"}},
		{Raw: []string{"GET / HTTP/1.1\r\nHost: {{Hostname}}\r\n\r\n{{http_1_raw_body}}"}},
		{Headers: map[string]string{"X-Raw": "{{http_1_raw_body}}"}},
	} {
		requests := []*Request{{ID: "first"}, request}
		KeepRawResponses(requests, "")
		require.True(t, requests[0].readsRawResponse)
		require.True(t, requests[1].readsRawResponse)
	}

	unmarked := []*Request{
		{ID: "first", Body: "hello", Path: []string{"{{BaseURL}}/"}},
		{Headers: map[string]string{"Accept": "text/plain"}},
	}
	KeepRawResponses(unmarked, "")
	require.False(t, unmarked[0].readsRawResponse)
	require.False(t, unmarked[1].readsRawResponse)
}

package http

import (
	"bufio"
	"bytes"
	"io"
	"net/http"
	"net/url"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/http/httpclientpool"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/utils/errkit"
)

// newReplayClient builds the client that re-sends findings through proxy. It
// uses the scan's TLS configuration so a replay reaches the target the same way.
func newReplayClient(options *types.Options) (*http.Client, error) {
	proxyURL, err := url.Parse(options.ReplayProxy)
	if err != nil {
		return nil, errkit.Wrapf(err, "invalid replay proxy %q", options.ReplayProxy)
	}
	tlsConfig, err := httpclientpool.NewTLSConfig(options)
	if err != nil {
		return nil, err
	}
	return &http.Client{
		Timeout: options.GetTimeouts().HttpTimeout,
		Transport: &http.Transport{
			Proxy:           http.ProxyURL(proxyURL),
			TLSClientConfig: tlsConfig,
			// keep the request as sent, without an added Accept-Encoding
			DisableCompression: true,
		},
		// the proxy must record the request that matched, not where it redirects
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}, nil
}

// replayRequest re-sends a request that produced a finding through the replay
// proxy, so it lands in a tool such as Burp without routing the whole scan
// through it. The response is discarded and failures are only logged: a replay
// must never affect the scan. body replaces the body in the dump when the
// dump holds only part of it.
func (request *Request) replayRequest(dumpedRequest, body []byte, formedURL string) {
	if request.replayClient == nil {
		return
	}
	dump := bufio.NewReader(bytes.NewReader(dumpedRequest))
	replay, err := http.ReadRequest(dump)
	if err != nil {
		gologger.Debug().Msgf("[%s] could not parse request to replay: %s", request.options.TemplateID, err)
		return
	}
	if body != nil {
		replay.Body = io.NopCloser(bytes.NewReader(body))
		if len(replay.TransferEncoding) == 0 {
			replay.ContentLength = int64(len(body))
		}
	} else if replay.ContentLength <= 0 && len(replay.TransferEncoding) == 0 {
		// unsafe raw requests are dumped as written and may carry a body without
		// declaring its length; ReadRequest would then treat them as bodyless
		if rest, _ := io.ReadAll(dump); len(rest) > 0 {
			replay.Body = io.NopCloser(bytes.NewReader(rest))
			replay.ContentLength = int64(len(rest))
		}
	}
	target, err := url.Parse(formedURL)
	if err != nil {
		gologger.Debug().Msgf("[%s] could not parse URL to replay %q: %s", request.options.TemplateID, formedURL, err)
		return
	}
	replay.RequestURI = ""
	replay.URL = target

	resp, err := request.replayClient.Do(replay)
	if err != nil {
		gologger.Debug().Msgf("[%s] could not replay %s through %s: %s", request.options.TemplateID, formedURL, request.options.Options.ReplayProxy, err)
		return
	}
	_, _ = io.Copy(io.Discard, resp.Body)
	_ = resp.Body.Close()
}

