				payloads := []string{"'", `"`, ";probe=value"}
				request := &Request{Fuzzing: []*fuzz.Rule{
					{Part: "cookie", Type: "postfix", Mode: "single", Keys: []string{"session"}, Fuzz: fuzz.SliceOrMapSlice{Value: payloads}},
				}}
