package signer

import (
	"context"
	"errors"
	"net/http"

	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// An Argument that can be passed to Signer
type SignerArg string

type Signer interface {
	SignHTTP(ctx context.Context, request *http.Request) error
}

type SignerArgs interface {
	Validate() error
}

func NewSigner(args SignerArgs) (signer Signer, err error) {
	switch signerArgs := args.(type) {
	case *AWSOptions:
		awsSigner, err := NewAwsSigner(signerArgs)
		if err != nil {
			awsSigner, err = NewAwsSignerFromConfig(signerArgs)
			if err != nil {
				return nil, err
			}
		}
		return awsSigner, err
	default:
		return nil, errors.New("unknown signature arguments type")
	}
}

// GetCtxWithArgs creates and returns context with signature args
func GetCtxWithArgs(maps ...map[string]interface{}) context.Context {
	var region, service string
	for _, v := range maps {
		for key, val := range v {
			if key == "region" && region == "" {
				region = types.ToString(val)
			}
			if key == "service" && service == "" {
				service = types.ToString(val)
			}
		}
	}
	// type ctxkey string
	ctx := context.WithValue(context.Background(), SignerArg("service"), service)
	return context.WithValue(ctx, SignerArg("region"), region)
}

package signerpool

import (
	"fmt"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/http/signer"

	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

var (
	poolMutex  sync.RWMutex
	clientPool map[string]signer.Signer
)

// Init initializes the clientpool implementation
func Init(options *types.Options) error {
	poolMutex.Lock()
	defer poolMutex.Unlock()
	if clientPool != nil {
		return nil // already initialized
	}
	clientPool = make(map[string]signer.Signer)
	return nil
}

// Configuration contains the custom configuration options for a client
type Configuration struct {
	SignerArgs signer.SignerArgs
}

// Hash returns the hash of the configuration to allow client pooling
func (c *Configuration) Hash() string {
	builder := &strings.Builder{}
	_, _ = fmt.Fprintf(builder, "%v", c.SignerArgs)
	hash := builder.String()
	return hash
}

// Get creates or gets a client for the protocol based on custom configuration
func Get(options *types.Options, configuration *Configuration) (signer.Signer, error) {
	hash := configuration.Hash()
	poolMutex.RLock()
	if client, ok := clientPool[hash]; ok {
		poolMutex.RUnlock()
		return client, nil
	}
	poolMutex.RUnlock()

	client, err := signer.NewSigner(configuration.SignerArgs)
	if err != nil {
		return nil, err
	}

	poolMutex.Lock()
	clientPool[hash] = client
	poolMutex.Unlock()
	return client, nil
}

package http

import (
	"crypto/tls"
	"net/http"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/tlsx/pkg/tlsx/clients"
)

// tlsVersionToString mirrors tlsx naming so HTTP and SSL protocol fields align.
var tlsVersionToString = map[uint16]string{
	tls.VersionTLS10: "tls10",
	tls.VersionTLS11: "tls11",
	tls.VersionTLS12: "tls12",
	tls.VersionTLS13: "tls13",
}

// enrichEventWithTLSMetadata copies TLS handshake / leaf-certificate fields from
// the HTTP response into the DSL event using the same names as the ssl protocol.
// Revocation / trust-store checks are intentionally skipped to avoid network
// side effects on every HTTPS request.
func enrichEventWithTLSMetadata(data output.InternalEvent, resp *http.Response) {
	if data == nil || resp == nil || resp.TLS == nil {
		return
	}
	state := resp.TLS

	if ver, ok := tlsVersionToString[state.Version]; ok {
		data["tls_version"] = ver
	}
	if cipher := tls.CipherSuiteName(state.CipherSuite); cipher != "" {
		data["cipher"] = cipher
	}
	if state.ServerName != "" {
		data["sni"] = state.ServerName
	}
	if state.CurveID != 0 {
		data["key_exchange"] = state.CurveID.String()
	}
	if len(state.PeerCertificates) == 0 {
		return
	}

	cert := state.PeerCertificates[0]
	domainNames := append([]string{cert.Subject.CommonName}, cert.DNSNames...)

	data["not_before"] = cert.NotBefore
	data["not_after"] = cert.NotAfter
	data["expired"] = clients.IsExpired(cert.NotAfter)
	data["self_signed"] = clients.IsSelfSigned(cert.AuthorityKeyId, cert.SubjectKeyId, cert.DNSNames)
	if state.ServerName != "" {
		data["mismatched"] = clients.IsMisMatchedCert(state.ServerName, domainNames)
	}
	data["subject_dn"] = cert.Subject.String()
	data["subject_cn"] = cert.Subject.CommonName
	if len(cert.Subject.Organization) > 0 {
		data["subject_org"] = cert.Subject.Organization
	}
	if len(cert.DNSNames) > 0 {
		data["subject_an"] = cert.DNSNames
	}
	if len(cert.EmailAddresses) > 0 {
		data["emails"] = cert.EmailAddresses
	}
	data["issuer_dn"] = cert.Issuer.String()
	data["issuer_cn"] = cert.Issuer.CommonName
	if len(cert.Issuer.Organization) > 0 {
		data["issuer_org"] = cert.Issuer.Organization
	}
	if serial := clients.FormatToSerialNumber(cert.SerialNumber); serial != "" {
		data["serial"] = serial
	}
	data["fingerprint_hash"] = map[string]string{
		"md5":    clients.MD5Fingerprint(cert.Raw),
		"sha1":   clients.SHA1Fingerprint(cert.Raw),
		"sha256": clients.SHA256Fingerprint(cert.Raw),
	}
	data["wildcard_certificate"] = clients.IsWildCardCert(domainNames)

	domains := make([]string, 0, len(domainNames))
	seen := make(map[string]struct{}, len(domainNames))
	for _, d := range domainNames {
		d = strings.TrimPrefix(d, "*.")
		if d == "" {
			continue
		}
		if _, ok := seen[d]; ok {
			continue
		}
		seen[d] = struct{}{}
		domains = append(domains, d)
	}
	if len(domains) > 0 {
		data["domains"] = domains
	}
}

package http

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"slices"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/httpbody"
	"github.com/projectdiscovery/rawhttp"
	"github.com/projectdiscovery/rawhttp/clientpipeline" //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
	"github.com/projectdiscovery/retryablehttp-go"
	convUtil "github.com/projectdiscovery/utils/conversion"
	"github.com/projectdiscovery/utils/errkit"
	urlutil "github.com/projectdiscovery/utils/url" //nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
)

// maxCurlBodySize is the largest request body included in a curl command.
// Larger bodies are left out so the command stays readable.
const maxCurlBodySize = 4 * 1024

// requestDump is a dumped request whose body may be cut short.
type requestDump struct {
	// data holds the request line, the headers and at most maxBody bytes
	// of the body, followed by a truncation marker when cut short.
	data []byte
	// truncated is the number of body bytes left out of data.
	truncated int
}

// dump creates a dump of the http request in form of a byte slice. Only the
// first maxBody bytes of the body are kept; maxBody <= 0 keeps all of it.
func dump(req *generatedRequest, reqURL string, maxBody int) (requestDump, error) {
	if req.request != nil {
		dumper := dumpRequest
		if req.original != nil && req.original.Pipeline {
			dumper = dumpPipelinedRequest
		}

		dumped, err := dumper(req.request, maxBody)
		if err != nil {
			return requestDump{}, errkit.Wrapf(err, "could not dump request: %v", req.request.String())
		}
		return dumped, nil
	}
	data := req.rawRequest.Data
	truncated := 0
	if maxBody > 0 && len(data) > maxBody {
		truncated = len(data) - maxBody
		data = data[:maxBody]
	}
	rawHttpOptions := &rawhttp.Options{CustomHeaders: req.rawRequest.UnsafeHeaders, CustomRawBytes: req.rawRequest.UnsafeRawBytes}
	bin, err := rawhttp.DumpRequestRaw(req.rawRequest.Method, reqURL, req.rawRequest.Path, generators.ExpandMapValues(req.rawRequest.Headers), io.NopCloser(strings.NewReader(data)), rawHttpOptions)
	if err != nil {
		return requestDump{}, errkit.Wrapf(err, "could not dump request: %v", reqURL)
	}
	// CustomRawBytes are dumped as given, without the body
	if len(req.rawRequest.UnsafeRawBytes) > 0 {
		truncated = 0
	}
	return requestDump{data: appendTruncationMarker(bin, truncated), truncated: truncated}, nil
}

// dumpRequest writes req the way http.Transport sends it, as
// httputil.DumpRequestOut does, but streams the body into a capped buffer
// instead of copying all of it.
func dumpRequest(req *retryablehttp.Request, maxBody int) (requestDump, error) {
	body, err := httpbody.View(req)
	if err != nil {
		return requestDump{}, err
	}
	// Use a clone to avoid a race condition with the http transport.
	clone := req.Request.Clone(req.Context())
	if len(body) == 0 {
		clone.Body = nil
		clone.ContentLength = 0
		delete(clone.Header, "Content-length")
	} else {
		clone.Body = httpbody.New(body)
		clone.ContentLength = int64(len(body))
	}
	// http.Transport writes https requests as http over its connection.
	if clone.URL != nil && clone.URL.Scheme == "https" {
		clone.URL.Scheme = "http"
	}

	capture := &cappedWriter{headerEnd: -1, maxBody: maxBody}
	if maxBody <= 0 {
		capture.buf = make([]byte, 0, len(body)+dumpHeaderRoom)
	}
	if err := clone.Write(capture); err != nil {
		return requestDump{}, err
	}
	data := capture.buf
	// http.Transport asks for gzip unless the caller set an encoding.
	if clone.Header.Get("Accept-Encoding") == "" && clone.Header.Get("Range") == "" && clone.Method != http.MethodHead && capture.headerEnd >= 2 {
		end := capture.headerEnd - 2
		data = slices.Insert(data, end, acceptEncodingGzip...)
	}
	return requestDump{data: appendTruncationMarker(data, capture.dropped), truncated: capture.dropped}, nil
}

// dumpPipelinedRequest writes req the way the rawhttp pipeline client does.
// That client does not go through http.Transport: it writes only the method,
// the path and query, the headers, a Host line and the body, so req.Close,
// req.ContentLength and the Accept-Encoding that http.Transport adds do not
// reach the wire.
func dumpPipelinedRequest(req *retryablehttp.Request, maxBody int) (requestDump, error) {
	body, err := httpbody.View(req)
	if err != nil {
		return requestDump{}, errkit.Wrapf(err, "could not read the request body")
	}

	piped, err := newPipelinedRequest(req, body)
	if err != nil {
		return requestDump{}, err
	}

	capture := &cappedWriter{buf: nil, headerEnd: -1, maxBody: maxBody, dropped: 0}
	if maxBody <= 0 {
		capture.buf = make([]byte, 0, len(body)+dumpHeaderRoom)
	}

	writer := bufio.NewWriter(capture)

	err = piped.Write(writer)
	if err != nil {
		return requestDump{}, errkit.Wrapf(err, "could not write the pipelined request")
	}

	err = writer.Flush()
	if err != nil {
		return requestDump{}, errkit.Wrapf(err, "could not write the pipelined request")
	}

	return requestDump{data: appendTruncationMarker(capture.buf, capture.dropped), truncated: capture.dropped}, nil
}

// newPipelinedRequest builds what PipelineClient.Dor passes to the pipeline
// writer for req. The request target and the Host line come from rawhttp's
// unexported do, so a change there needs the same change here.
// TestPipelinedRequestDumpMatchesWire fails when they drift.
func newPipelinedRequest(req *retryablehttp.Request, body []byte) (*clientpipeline.Request, error) {
	// req.URL is the URL that Dor parses; req.String() is its String method.
	target, err := urlutil.ParseURL(req.String(), true)
	if err != nil {
		return nil, errkit.Wrapf(err, "could not parse the request URL")
	}

	path := target.Path
	if path == "" {
		path = "/"
	}

	if !target.Params.IsEmpty() {
		path += "?" + target.Params.Encode()
	}

	var reader io.Reader
	if len(body) > 0 {
		reader = bytes.NewReader(body)
	}

	piped := clientpipeline.ToRequest(req.Method, path, nil, req.Header, reader)
	// The client writes headers in map order. A fixed order keeps the dump
	// the same between runs.
	slices.SortStableFunc(piped.Headers, func(a, b clientpipeline.Header) int { return strings.Compare(a.Key, b.Key) })

	if rawhttp.DefaultPipelineOptions.AutomaticHostHeader && target.Host != "" && !hasHeaderFold(req.Header, hostHeader) {
		piped.Headers = slices.Insert(piped.Headers, 0, clientpipeline.Header{Key: hostHeader, Value: target.Host})
	}

	return piped, nil
}

// hasHeaderFold reports whether headers has key in any letter case, as the
// pipeline client checks for a Host the caller set.
func hasHeaderFold(headers http.Header, key string) bool {
	for k := range headers {
		if strings.EqualFold(k, key) {
			return true
		}
	}

	return false
}

func appendTruncationMarker(data []byte, truncated int) []byte {
	if truncated <= 0 {
		return data
	}
	return fmt.Appendf(data, "\n...[truncated %d bytes]", truncated)
}

// capDumpBody keeps at most maxBody bytes of the body in an already built
// request dump. maxBody <= 0 keeps the dump unchanged. Saved output and debug
// use it. Matchers keep the full dump.
func capDumpBody(dump []byte, maxBody int) []byte {
	if maxBody <= 0 {
		return dump
	}
	idx := bytes.Index(dump, headerTerminator)
	if idx < 0 {
		return dump
	}
	headerEnd := idx + len(headerTerminator)
	bodyLen := len(dump) - headerEnd
	if bodyLen <= maxBody {
		return dump
	}
	capped := append([]byte(nil), dump[:headerEnd+maxBody]...)
	return appendTruncationMarker(capped, bodyLen-maxBody)
}

var headerTerminator = []byte("\r\n\r\n")

const hostHeader = "Host"

var acceptEncodingGzip = []byte("Accept-Encoding: gzip\r\n")

const dumpHeaderRoom = 8 * 1024

// cappedWriter keeps the request line and headers in full and at most
// maxBody bytes of the body that follows, counting the rest.
type cappedWriter struct {
	buf       []byte
	headerEnd int
	maxBody   int
	dropped   int
}

func (w *cappedWriter) Write(p []byte) (int, error) {
	n := len(p)
	if w.headerEnd < 0 {
		from := max(len(w.buf)-len(headerTerminator)+1, 0)
		w.buf = append(w.buf, p...)
		i := bytes.Index(w.buf[from:], headerTerminator)
		if i < 0 {
			return n, nil
		}
		w.headerEnd = from + i + len(headerTerminator)
		// re-apply the cap to body bytes that came with the headers
		p = bytes.Clone(w.buf[w.headerEnd:])
		w.buf = w.buf[:w.headerEnd]
	}
	keep := len(p)
	if w.maxBody > 0 {
		keep = min(keep, max(w.maxBody-(len(w.buf)-w.headerEnd), 0))
	}
	w.buf = append(w.buf, p[:keep]...)
	w.dropped += len(p) - keep
	return n, nil
}

// getHTTPProjectCacheScope builds the project file key for a request. A
// truncated dump does not identify the body, so its hash is added.
func getHTTPProjectCacheScope(requestDump requestDump, body []byte, scheme, host string) []byte {
	scheme = strings.ToLower(strings.TrimSpace(scheme))
	host = strings.ToLower(strings.TrimSpace(host))

	var scoped bytes.Buffer
	if scheme != "" && host != "" {
		_, _ = scoped.WriteString(scheme)
		_, _ = scoped.WriteString("://")
		_, _ = scoped.WriteString(host)
		_, _ = scoped.WriteString("\n")
	}
	_, _ = scoped.Write(requestDump.data)
	if requestDump.truncated > 0 {
		sum := sha256.Sum256(body)
		_, _ = scoped.WriteString("\nbody-sha256:")
		_, _ = scoped.WriteString(hex.EncodeToString(sum[:]))
	}
	return scoped.Bytes()
}

func (g *generatedRequest) bodyLen() int64 {
	if g.rawRequest != nil {
		return int64(len(g.rawRequest.Data))
	}
	if g.request == nil || g.request.Body == nil {
		return 0
	}
	if body, ok := g.request.Body.(*httpbody.Body); ok {
		return int64(body.Len())
	}
	return g.request.ContentLength
}

// body returns the request body without copying it.
func (g *generatedRequest) body() []byte {
	if g.request != nil {
		body, _ := httpbody.View(g.request)
		return body
	}
	if g.rawRequest != nil {
		return convUtil.Bytes(g.rawRequest.Data)
	}
	return nil
}

package http

import "github.com/pkg/errors"

func (request *Request) validate() error {
	if request.Race && request.NeedsRequestCondition() {
		return errors.New("'race' and 'req-condition' can't be used together")
	}

	if len(request.Fuzzing) > 0 && request.NeedsRequestCondition() {
		return errors.New("'fuzzing' and 'request-condition' can't be used together")
	}

	if request.Redirects && request.HostRedirects {
		return errors.New("'redirects' and 'host-redirects' can't be used together")
	}

	if request.ProtocolRedirects && !request.Redirects && !request.HostRedirects {
		return errors.New("'protocol-redirects' requires 'redirects' or 'host-redirects' to be enabled")
	}

	return nil
}

package http

import (
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/fuzz"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/extractors"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
)

func TestValidateRedirectsCombinations(t *testing.T) {
	t.Run("redirects and host-redirects conflict", func(t *testing.T) {
		req := &Request{Redirects: true, HostRedirects: true}
		err := req.validate()
		require.Error(t, err)
		require.Contains(t, err.Error(), "'redirects' and 'host-redirects' can't be used together")
	})

	t.Run("redirects alone is valid", func(t *testing.T) {
		req := &Request{Redirects: true}
		err := req.validate()
		require.NoError(t, err)
	})

	t.Run("host-redirects alone is valid", func(t *testing.T) {
		req := &Request{HostRedirects: true}
		err := req.validate()
		require.NoError(t, err)
	})

	t.Run("protocol-redirects without redirects or host-redirects is invalid", func(t *testing.T) {
		req := &Request{ProtocolRedirects: true}
		err := req.validate()
		require.Error(t, err)
		require.Contains(t, err.Error(), "'protocol-redirects' requires 'redirects' or 'host-redirects'")
	})

	t.Run("protocol-redirects with redirects is valid", func(t *testing.T) {
		req := &Request{Redirects: true, ProtocolRedirects: true}
		err := req.validate()
		require.NoError(t, err)
	})

	t.Run("protocol-redirects with host-redirects is valid", func(t *testing.T) {
		req := &Request{HostRedirects: true, ProtocolRedirects: true}
		err := req.validate()
		require.NoError(t, err)
	})

	t.Run("no redirect options is valid", func(t *testing.T) {
		req := &Request{}
		err := req.validate()
		require.NoError(t, err)
	})
}

func TestValidateFuzzingWithRequestCondition(t *testing.T) {
	t.Run("matcher dsl", func(t *testing.T) {
		req := &Request{
			Fuzzing: []*fuzz.Rule{{}},
			Operators: operators.Operators{
				Matchers: []*matchers.Matcher{
					{DSL: []string{"duration_1 > 18"}},
				},
			},
		}
		err := req.validate()
		require.Error(t, err)
		require.Contains(t, err.Error(), "'fuzzing' and 'request-condition' can't be used together")
	})

	t.Run("extractor part", func(t *testing.T) {
		req := &Request{
			Fuzzing: []*fuzz.Rule{{}},
			Operators: operators.Operators{
				Extractors: []*extractors.Extractor{
					{Part: "body_1"},
				},
			},
		}
		err := req.validate()
		require.Error(t, err)
		require.Contains(t, err.Error(), "'fuzzing' and 'request-condition' can't be used together")
	})
}

package protocols

import (
	"maps"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/render"
)

// renderInfo fills the {{placeholders}} in the free text of each result's info
// with the values of the event that produced it, so a finding can say what was
// found and where. Name, severity, tags and classification stay as written:
// they identify the template for filtering, grouping and issue trackers.
//
// Each result holds its own copy of the info, so the template is never changed.
// When filling changes the text, the result keeps the info as written in
// TemplateInfo.
func renderInfo(results []*output.ResultEvent, data map[string]interface{}) []*output.ResultEvent {
	// A global matcher matches on another template's event, with that template's
	// payloads, variables and extracted values, so only the result fields fill
	// its info.
	if isGlobal, _ := data["global-matchers"].(bool); isGlobal {
		data = nil
	}
	for _, result := range results {
		if !result.Info.HasPlaceholders() {
			continue
		}
		written := result.Info
		values := infoValues(result, data)
		for _, field := range result.Info.PlaceholderFields() {
			if field.HasPlaceholders() {
				*field.Value = renderInfoText(result.TemplateID, *field.Value, values)
			}
		}
		if len(result.Info.FilledFields(&written)) > 0 {
			result.TemplateInfo = &written
		}
	}
	return results
}

// infoValues returns the event data with the result's own fields on top, under
// their names in the JSON output. Those win over the event's keys: in an http
// event host is the raw input URL, while the output reports the hostname.
func infoValues(result *output.ResultEvent, data map[string]interface{}) map[string]interface{} {
	values := make(map[string]interface{}, len(data)+9)
	maps.Copy(values, data)
	for key, value := range map[string]string{
		"host":           result.Host,
		"port":           result.Port,
		"ip":             result.IP,
		"url":            result.URL,
		"scheme":         result.Scheme,
		"path":           result.Path,
		"matched-at":     result.Matched,
		"matcher-name":   result.MatcherName,
		"extractor-name": result.ExtractorName,
	} {
		if value != "" {
			values[key] = value
		}
	}
	return values
}

// renderInfoText renders the text through the shared renderer, as requests and
// matchers are, so nested placeholders and helpers behave the same way. Scan
// options are left out, so network helpers stay denied while results are built.
// If an expression fails, the text stays as written, as a word matcher's does:
// a typo in the template must not cost the finding.
func renderInfoText(templateID, text string, values map[string]interface{}) string {
	rendered, err := render.Render(render.Input{Text: text, Values: values})
	if err != nil {
		gologger.Verbose().Msgf("[%s] Could not render template info: %s\n", templateID, err)
		return text
	}
	return rendered.Text
}

