package offlinehttp

import (
	"bufio"
	"errors"
	"io"
	"net/http"
	"regexp"
	"strings"
)

// noMinor matches a leading status-line protocol with no minor version, such
// as "HTTP/2 ". The go parser only accepts HTTP/X.Y.
var noMinor = regexp.MustCompile(`^HTTP/[0-9] `)

// errNotRequest marks data that does not start with an HTTP request, so the
// caller parses it as a bare response instead.
var errNotRequest = errors.New("not an http request")

// readResponseFromString reads one raw HTTP response. Data may be the response
// itself or a request followed by that response. A status line is recognized
// only where a response starts, never by searching the body for "HTTP/".
func readResponseFromString(data string) (*http.Response, error) {
	resp, err := readRequestResponse(data)
	if err == nil || !errors.Is(err, errNotRequest) {
		return resp, err
	}
	return readResponse(data, nil)
}

// readRequestResponse reads a raw HTTP request from the start of data and the
// response that follows it.
func readRequestResponse(data string) (*http.Response, error) {
	sr := strings.NewReader(data)
	br := bufio.NewReader(sr)
	// unread bytes are either still in sr or buffered in br
	unread := func() string { return data[len(data)-sr.Len()-br.Buffered():] }

	req, err := http.ReadRequest(br)
	if err != nil {
		return nil, errNotRequest
	}
	afterHeaders := unread()
	// the response follows the request body, so it has to be read first.
	// a dump that keeps Content-Length but drops the body is tried at the headers.
	if _, err := io.Copy(io.Discard, req.Body); err == nil {
		if resp, err := readResponse(unread(), req); err == nil {
			return resp, nil
		}
	}
	return readResponse(afterHeaders, req)
}

// maxInterimResponses bounds how many interim responses are skipped before the
// final one. Each skip copies the remainder of data.
const maxInterimResponses = 5

// readResponse reads a raw HTTP response whose status line starts data, after
// any leading blank lines. Interim responses such as 100 Continue are skipped,
// as the HTTP client does. The last interim response is returned when no final
// response follows it.
func readResponse(data string, req *http.Request) (*http.Response, error) {
	var lastInterim *http.Response
	for range maxInterimResponses + 1 {
		data = strings.TrimLeft(data, "\r\n")
		data = addMinorVersionToHTTP(data)
		sr := strings.NewReader(data)
		br := bufio.NewReader(sr)
		resp, err := http.ReadResponse(br, req)
		if err != nil {
			if lastInterim != nil {
				return lastInterim, nil
			}
			return nil, err
		}
		if !isInterimResponse(resp) {
			return resp, nil
		}
		if lastInterim != nil && lastInterim.Body != nil {
			_ = lastInterim.Body.Close()
		}
		lastInterim = resp
		data = data[len(data)-sr.Len()-br.Buffered():]
	}
	return lastInterim, nil
}

// isInterimResponse reports whether resp is an interim response, such as
// 100 Continue, that comes before the final response. 101 Switching Protocols
// is the response.
func isInterimResponse(resp *http.Response) bool {
	return resp != nil && resp.StatusCode >= 100 && resp.StatusCode <= 199 && resp.StatusCode != http.StatusSwitchingProtocols
}

// addMinorVersionToHTTP inserts ".0" into a leading protocol such as HTTP/2.
// Only those bytes change, so the reason phrase, headers, and body stay intact.
func addMinorVersionToHTTP(data string) string {
	if !noMinor.MatchString(data) {
		return data
	}
	const protoLen = len("HTTP/X")
	return data[:protoLen] + ".0" + data[protoLen:]
}

package offlinehttp

import (
	"fmt"
	"io"
	"testing"
)

func TestReadResponsePreservesHTTPVersionText(t *testing.T) {
	body := "Supports HTTP/2 and HTTP/3."
	tests := []struct {
		name   string
		raw    string
		proto  string
		status string
		header string
	}{
		{
			name:   "body without content length",
			raw:    "HTTP/1.1 200 OK\r\n\r\n" + body,
			proto:  "HTTP/1.1",
			status: "200 OK",
		},
		{
			name:   "body with content length",
			raw:    fmt.Sprintf("HTTP/1.1 200 OK\r\nContent-Length: %d\r\n\r\n%s", len(body), body),
			proto:  "HTTP/1.1",
			status: "200 OK",
		},
		{
			name:   "chunked body",
			raw:    fmt.Sprintf("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n%x\r\n%s\r\n0\r\n\r\n", len(body), body),
			proto:  "HTTP/1.1",
			status: "200 OK",
		},
		{
			name:   "header value",
			raw:    "HTTP/1.1 200 OK\r\nServer: HTTP/2 gateway\r\n\r\n" + body,
			proto:  "HTTP/1.1",
			status: "200 OK",
			header: "HTTP/2 gateway",
		},
		{
			name:   "reason phrase",
			raw:    "HTTP/1.1 200 HTTP/2 supported\r\n\r\n" + body,
			proto:  "HTTP/1.1",
			status: "200 HTTP/2 supported",
		},
		{
			name:   "HTTP 2 missing minor version",
			raw:    "HTTP/2 200 OK\r\n\r\n" + body,
			proto:  "HTTP/2.0",
			status: "200 OK",
		},
		{
			name:   "HTTP 3 missing minor version",
			raw:    "HTTP/3 200 OK\r\n\r\n" + body,
			proto:  "HTTP/3.0",
			status: "200 OK",
		},
		{
			name:   "request followed by response",
			raw:    "GET / HTTP/1.1\r\nHost: example.com\r\n\r\nHTTP/1.1 200 OK\r\n\r\n" + body,
			proto:  "HTTP/1.1",
			status: "200 OK",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			resp, err := readResponseFromString(tt.raw)
			if err != nil {
				t.Fatal(err)
			}
			defer func() { _ = resp.Body.Close() }()
			got, err := io.ReadAll(resp.Body)
			if err != nil {
				t.Fatalf("read response body: %v", err)
			}
			if string(got) != body {
				t.Errorf("body = %q, want %q", got, body)
			}
			if resp.Proto != tt.proto {
				t.Errorf("protocol = %q, want %q", resp.Proto, tt.proto)
			}
			if resp.Status != tt.status {
				t.Errorf("status = %q, want %q", resp.Status, tt.status)
			}
			if got := resp.Header.Get("Server"); got != tt.header {
				t.Errorf("Server header = %q, want %q", got, tt.header)
			}
		})
	}
}

package offlinehttp

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httputil"
	"os"
	"strings"

	"github.com/pkg/errors"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/eventcreator"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/utils"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	"github.com/projectdiscovery/utils/conversion"
	syncutil "github.com/projectdiscovery/utils/sync"
	unitutils "github.com/projectdiscovery/utils/unit"
)

var _ protocols.Request = &Request{}

const maxSize = 5 * unitutils.Mega

// Type returns the type of the protocol request
func (request *Request) Type() templateTypes.ProtocolType {
	return templateTypes.OfflineHTTPProtocol
}

// RawInputMode is a flag to indicate if the input is raw input
// rather than a file path
var RawInputMode = false

// ExecuteWithResults executes the protocol requests and returns results instead of writing them.
func (request *Request) ExecuteWithResults(input *contextargs.Context, metadata, previous output.InternalEvent, callback protocols.OutputEventCallback) error {
	// Prefer response bodies carried on multi-format inputs (burp/jsonl/yaml).
	if rr := input.MetaInput.ReqResp; rr != nil && rr.Response != nil && strings.TrimSpace(rr.Response.Raw) != "" {
		err := request.executeRawInput(rr.Response.Raw, rr.URL.String(), input, callback)
		if err == nil {
			request.options.Progress.IncrementRequests()
		}
		return err
	}

	if RawInputMode {
		err := request.executeRawInput(input.MetaInput.Input, "", input, callback)
		if err == nil {
			request.options.Progress.IncrementRequests()
		}
		return err
	}

	// Export inputs attach ReqResp with a URL-shaped MetaInput.Input. Without a
	// response body there is nothing to match offline; do not treat the URL as a filepath.
	if input.MetaInput.ReqResp != nil {
		return nil
	}

	// syncutil.New rejects a size below 1, so a -bs below 1 reads one file at a time.
	bulkSize := max(request.options.Options.BulkSize, 1)

	wg, err := syncutil.New(syncutil.WithSize(bulkSize)) //nolint:varnamelen // wg names the group throughout
	if err != nil {
		return err
	}

	err = request.getInputPaths(input.Context(), input.MetaInput.Input, func(data string) error {
		if err := wg.AddWithContext(input.Context()); err != nil {
			return err
		}

		go func(data string) {
			defer wg.Done()

			file, err := os.Open(data)
			if err != nil {
				gologger.Error().Msgf("Could not open file path %s: %s\n", data, err)
				return
			}
			defer func() {
				_ = file.Close()
			}()

			stat, err := file.Stat()
			if err != nil {
				gologger.Error().Msgf("Could not stat file path %s: %s\n", data, err)
				return
			}
			if stat.Size() >= int64(maxSize) {
				gologger.Verbose().Msgf("Could not process path %s: exceeded max size\n", data)
				return
			}

			buffer, err := io.ReadAll(file)
			if err != nil {
				gologger.Error().Msgf("Could not read file path %s: %s\n", data, err)
				return
			}
			dataStr := conversion.String(buffer)

			if err := request.executeRawInput(dataStr, data, input, callback); err != nil {
				gologger.Error().Msgf("Could not execute raw input %s: %s\n", data, err)
				return
			}
		}(data)
		return nil
	})
	wg.Wait()
	if err := input.Context().Err(); err != nil {
		return err
	}
	if err != nil {
		request.options.Output.Request(request.options.TemplatePath, input.MetaInput.Input, "file", err)
		request.options.Progress.IncrementFailedRequestsBy(1)
		return errors.Wrap(err, "could not send file request")
	}
	request.options.Progress.IncrementRequests()
	return nil
}

func (request *Request) executeRawInput(data, inputString string, input *contextargs.Context, callback protocols.OutputEventCallback) error {
	resp, err := readResponseFromString(data)
	if err != nil {
		return errors.Wrap(err, "could not read raw response")
	}

	if request.options.Options.Debug || request.options.Options.DebugRequests {
		gologger.Info().Msgf("[%s] Dumped offline-http request for %s", request.options.TemplateID, data)
		gologger.Print().Msgf("%s", data)
	}
	gologger.Verbose().Msgf("[%s] Sent OFFLINE-HTTP request to %s", request.options.TemplateID, data)

	dumpedResponse, err := httputil.DumpResponse(resp, true)
	if err != nil {
		return errors.Wrap(err, "could not dump raw http response")
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return errors.Wrap(err, "could not read raw http response body")
	}
	reqURL := inputString
	if inputString == "" {
		reqURL = getURLFromRequest(resp.Request)
	}

	outputEvent := request.responseToDSLMap(resp, data, reqURL, data, conversion.String(dumpedResponse), conversion.String(body), utils.HeadersToString(resp.Header), 0, nil)
	// add response fields to template context and merge templatectx variables to output event
	request.options.AddTemplateVars(input.MetaInput, request.Type(), request.GetID(), outputEvent)
	if request.options.HasTemplateCtx(input.MetaInput) {
		outputEvent = generators.MergeMaps(outputEvent, request.options.GetTemplateCtx(input.MetaInput).GetAll())
	}
	outputEvent["ip"] = ""

	event := eventcreator.CreateEvent(request, outputEvent, request.options.Options.Debug || request.options.Options.DebugResponse)
	callback(event)
	return nil
}

func getURLFromRequest(req *http.Request) string {
	if req.URL.Scheme == "" {
		req.URL.Scheme = "https"
	}
	return fmt.Sprintf("%s://%s%s", req.URL.Scheme, req.Host, req.URL.Path)
}

// UpdateOptions replaces this request's options with a new copy
func (r *Request) UpdateOptions(opts *protocols.ExecutorOptions) {
	if opts != nil {
		r.options = opts.Copy()
	}
}

