	require.Error(t, err)
	require.Zero(t, deniedHandshakes.Load(), "openssl connected to an address the execution policy denies")
}

func TestSSLOpenSSLCustomIPObeysNetworkPolicy(t *testing.T) {
	if !openssl.IsAvailable() {
