package httputil

import (
	"context"
	"net/http"
	"net/url"
	"strings"
)

type cookieFieldsContextKey struct{}

// CookieURL matches the cookie scope used by net/http, including Host overrides.
func CookieURL(req *http.Request) *url.URL {
	if req.URL == nil || req.Host == "" {
		return req.URL
	}
	cloned := *req.URL
	cloned.Host = req.Host
	return &cloned
}

// SetCookieFields records the raw fields produced by cookie fuzzing. Field
// boundaries cannot be recovered from payloads containing unmatched quotes.
func SetCookieFields(req *http.Request, fields []string) {
	fields = append([]string(nil), fields...)
	*req = *req.WithContext(context.WithValue(req.Context(), cookieFieldsContextKey{}, fields))
}

// CookieFields returns a copy of the structured fields recorded by cookie fuzzing.
func CookieFields(req *http.Request) []string {
	fields, _ := req.Context().Value(cookieFieldsContextKey{}).([]string)
	return append([]string(nil), fields...)
}

// SplitCookieHeader separates cookie pairs without changing their raw bytes.
// Quoted semicolons can be intentional fuzzing payloads. An unmatched quote
// keeps the rest of the header in the same value rather than inventing pairs.
func SplitCookieHeader(header string) []string {
	parts := make([]string, 0, strings.Count(header, ";")+1)
	start := 0
	quoted := false
	for i := 0; i < len(header); i++ {
		if quoted && header[i] == '\\' {
			i++ // Preserve an escaped quote without ending the quoted value.
			continue
		}
		switch header[i] {
		case '"':
			quoted = !quoted
		case ';':
			if !quoted {
				parts = append(parts, header[start:i])
				start = i + 1
			}
		}
	}
	return append(parts, header[start:])
}

package httputil

import (
	"regexp"
	"strings"

	"github.com/projectdiscovery/retryablehttp-go"
	urlutil "github.com/projectdiscovery/utils/url"
)

var (
	// TODO: adapt regex for cases where port is updated
	urlWithPortRegex = regexp.MustCompile(`^{{(BaseURL|RootURL)}}:(\d+)`)
	// regex to detect trailing slash in path (not applicable to raw requests)
	trailingSlashregex = regexp.MustCompile(`^\Q{{\E[a-zA-Z]+\Q}}/\E`)
	// ErrNoMoreRequests is internal error to
)

// HasTrailingSlash returns true if path(that has default variables) has trailing slash
func HasTrailingSlash(data string) bool {
	return trailingSlashregex.MatchString(data)
}

// UpdateURLPortFromPayload overrides input port if specified in payload(ex: {{BaseURL}}:8080)
func UpdateURLPortFromPayload(parsed *urlutil.URL, data string) (*urlutil.URL, string) {
	matches := urlWithPortRegex.FindAllStringSubmatch(data, -1)
	if len(matches) > 0 {
		port := matches[0][2]
		parsed.UpdatePort(port)
		// remove it from dsl
		data = strings.Replace(data, ":"+port, "", 1)
	}
	return parsed, data
}

// SetHeader sets some headers only if the header wasn't supplied by the user
func SetHeader(req *retryablehttp.Request, name, value string) {
	if _, ok := req.Header[name]; !ok {
		req.Header.Set(name, value)
	}
	if name == "Host" {
		req.Host = value
	}
}

