func newDelayedUpgradeWebsocketServer(delay time.Duration) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(delay)

		conn, _, _, err := ws.UpgradeHTTP(r, w)
		if err != nil {
			return
		}

		go func() {
			defer func() {
				_ = conn.Close()
			}()
			time.Sleep(delay)
		}()
	}))
}

func TestWebSocketCompileHonorsPayloadRandomOrder(t *testing.T) {
	options := testutils.DefaultOptions.Copy()
	options.ExecutionId = t.Name()
	options.PayloadRandomOrder = true
	testutils.Init(options)
	t.Cleanup(func() { protocolstate.Close(options.ExecutionId) })

	request := &Request{
		Address: "ws://127.0.0.1:1",
		Payloads: map[string]interface{}{
			"username": []string{"a", "b"},
		},
	}
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "testing-websocket-payload-order",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Low}, Name: "test"},
	})
	require.NoError(t, request.Compile(executerOpts))

	sawShuffle := false
	for range 24 {
		iterator := request.generator.NewIterator()
		var got []string
		for {
			value, ok := iterator.Value()
			if !ok {
				break
			}
			got = append(got, value["username"].(string))
		}
		if len(got) == 2 && (got[0] != "a" || got[1] != "b") {
			sawShuffle = true
			break
		}
	}
	require.True(t, sawShuffle, "websocket payloads must honor payload random order")
}

func requireWebsocketDurationField(t *testing.T, event output.InternalEvent, key string) {
	t.Helper()

	value, ok := event[key].(float64)
	require.Truef(t, ok, "expected %s to be a float64 duration", key)
	// Local mocks can finish within one timer tick (esp. on Windows), so 0s is valid.
	require.GreaterOrEqual(t, value, float64(0))
	require.Less(t, value, float64(60))
}

// TestWebSocketSubprotocolNegotiation ensures a Sec-WebSocket-Protocol header is
// negotiated through the dialer. The server only completes the handshake when the
// client offers the "vite-hmr" subprotocol and echoes it back (as Vite's HMR
// endpoint does); without routing the header into Dialer.Protocols, gobwas/ws
// rejects the server-echoed protocol and the handshake fails.
func TestWebSocketSubprotocolNegotiation(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Require the client to offer the vite-hmr subprotocol: reject the upgrade
		// otherwise, so the test fails if the subprotocol is not negotiated.
		offered := false
		for _, proto := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
			if strings.TrimSpace(proto) == "vite-hmr" {
				offered = true
				break
			}
		}
		if !offered {
			http.Error(w, "vite-hmr subprotocol required", http.StatusBadRequest)
			return
		}
		upgrader := ws.HTTPUpgrader{
			Protocol: func(p string) bool { return p == "vite-hmr" },
		}
		conn, _, _, err := upgrader.Upgrade(r, w)
		if err != nil {
			return
		}
		go func() {
			defer func() { _ = conn.Close() }()
			for {
				_, op, err := wsutil.ReadClientData(conn)
				if err != nil {
					return
				}
				_ = wsutil.WriteServerMessage(conn, op, []byte("negotiated-ok"))
			}
		}()
	}))
	defer server.Close()

	options := testutils.DefaultOptions
	testutils.Init(options)

	target := strings.ReplaceAll(server.URL, "http", "ws")
	request := &Request{
		ID:      "subproto-ws",
		Address: target,
		Headers: map[string]string{"Sec-WebSocket-Protocol": "vite-hmr"},
		Inputs:  []*Input{{Data: "ping", Name: "first"}},
	}
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "testing-websocket-subprotocol",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Low}, Name: "test"},
	})
	executerOpts.IsMultiProtocol = true
	require.NoError(t, request.Compile(executerOpts))

	var gotEvent output.InternalEvent
	ctxArgs := contextargs.NewWithInput(context.Background(), target)
	err := request.ExecuteWithResults(ctxArgs, nil, nil, func(event *output.InternalWrappedEvent) {
		gotEvent = event.InternalEvent
	})
	require.NoError(t, err)
	require.NotEmpty(t, gotEvent)
	require.Contains(t, fmt.Sprintf("%v", gotEvent["response"]), "negotiated-ok")
}

package rdapclientpool

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"sync"

	"github.com/openrdap/rdap"
	"github.com/openrdap/rdap/bootstrap"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// clients holds one client per execution, because each one dials with the
// network policy of its execution.
var clients = map[string]*Client{}
var m sync.Mutex

type Client struct {
	mu     sync.Mutex
	client *rdap.Client
}

func (c *Client) Do(request *rdap.Request) (*rdap.Response, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.client.Do(request)
}

// Init initializes the client pool implementation
func Init(options *types.Options) error {
	_, err := Get(options, nil)
	return err
}

// newClient returns an rdap client whose requests, bootstrap lookups and
// redirects all dial through the fastdialer of the execution, so every
// address it connects to is checked against the network policy.
func newClient(options *types.Options) *Client {
	executionID := options.ExecutionId
	httpClient := &http.Client{
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, address string) (net.Conn, error) {
				dialers := protocolstate.GetDialersWithId(executionID)
				if dialers == nil || dialers.Fastdialer == nil {
					return nil, fmt.Errorf("dialers not initialized for %s", executionID)
				}
				return dialers.Fastdialer.Dial(ctx, network, address)
			},
		},
		Timeout: options.GetTimeouts().HttpTimeout,
	}
	client := &rdap.Client{
		HTTP:      httpClient,
		Bootstrap: &bootstrap.Client{HTTP: httpClient},
	}
	if options.Verbose || options.Debug || options.DebugRequests || options.DebugResponse {
		client.Verbose = func(text string) {
			gologger.Debug().Msgf("rdap: %s", text)
		}
	}
	return &Client{client: client}
}

// Configuration contains the custom configuration options for a client - placeholder
type Configuration struct{}

// Hash returns the hash of the configuration to allow client pooling - placeholder
func (c *Configuration) Hash() string {
	return ""
}

// Get creates or gets the client of the execution
func Get(options *types.Options, configuration *Configuration) (*Client, error) {
	m.Lock()
	defer m.Unlock()
	if client, ok := clients[options.ExecutionId]; ok {
		return client, nil
	}
	client := newClient(options)
	clients[options.ExecutionId] = client
	return client, nil
}

// Close drops the client of an execution.
func Close(executionID string) {
	m.Lock()
	client := clients[executionID]
	delete(clients, executionID)
	m.Unlock()
	if client != nil {
		client.mu.Lock()
		client.client.HTTP.CloseIdleConnections()
		client.mu.Unlock()
	}
}

package whois

import (
	"net/url"
	"strings"
	"time"

	"github.com/openrdap/rdap"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/extractors"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/generators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/eventcreator"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/responsehighlighter"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/replacer"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/utils/vardump"
	protocolutils "github.com/projectdiscovery/nuclei/v3/pkg/protocols/utils"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/whois/rdapclientpool"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// Request is a request for the WHOIS protocol
type Request struct {
	// Operators for the current request go here.
	operators.Operators `yaml:",inline,omitempty" json:",inline,omitempty"`
	CompiledOperators   *operators.Operators `yaml:"-" json:"-"`

	// ID is the optional id of the request
	ID string `yaml:"id,omitempty" json:"id,omitempty" jsonschema:"title=id of the request,description=ID of the network request"`

	// description: |
	//   Query contains query for the request
	Query string `yaml:"query,omitempty" json:"query,omitempty" jsonschema:"title=query for the WHOIS request,description=Query contains query for the request"`

	// description: |
	// 	 Optional WHOIS server URL.
	//
	// 	 If present, specifies the WHOIS server to execute the Request on.
	//   Otherwise, nil enables bootstrapping
	Server string `yaml:"server,omitempty" json:"server,omitempty" jsonschema:"title=server url to execute the WHOIS request on,description=Server contains the server url to execute the WHOIS request on"`
	// cache any variables that may be needed for operation.
	client          *rdapclientpool.Client
	options         *protocols.ExecutorOptions
	parsedServerURL *url.URL
}

// Compile compiles the request generators preparing any requests possible.
func (request *Request) Compile(options *protocols.ExecutorOptions) error {
	var err error
	if request.Server != "" {
		request.parsedServerURL, err = url.Parse(request.Server)
		if err != nil {
			return errors.Wrap(err, "failed to parse server URL")
		}
	}

	request.options = options
	request.client, _ = rdapclientpool.Get(options.Options, nil)

	if len(request.Matchers) > 0 || len(request.Extractors) > 0 {
		compiled := &request.Operators
		compiled.ExcludeMatchers = options.ExcludeMatchers
		compiled.TemplateID = options.TemplateID
		if err := compiled.Compile(); err != nil {
			return errors.Wrap(err, "could not compile operators")
		}
		// llm operators only evaluate once they hold the scan's client; without
		// it every llm path returns a negative result instead of an error.
		protocols.BindLLMOperators(compiled, options)
		request.CompiledOperators = compiled
	}
	return nil
}

// Requests returns the total number of requests the rule will perform
func (request *Request) Requests() int {
	return 1
}

// GetID returns the ID for the request if any.
func (request *Request) GetID() string {
	return request.ID
}

// ExecuteWithResults executes the protocol requests and returns results instead of writing them.
func (request *Request) ExecuteWithResults(input *contextargs.Context, dynamicValues, previous output.InternalEvent, callback protocols.OutputEventCallback) error {
	// generate variables
	defaultVars := protocolutils.GenerateVariables(input.MetaInput.Input, false, nil)
	optionVars := generators.BuildPayloadFromOptions(request.options.Options)
	// add templatectx variables to varMap
	scope := request.options.NewVariablesScope(defaultVars, optionVars, dynamicValues, previous)

	request.options.AddTemplateCtxToVariablesScope(input.MetaInput, scope)
	scope.AddData(request.options.Constants)

	vars := request.options.Variables.EvaluateScope(scope).Values
	variables := generators.MergeMaps(vars, defaultVars, optionVars, dynamicValues, previous)
	if request.options.HasTemplateCtx(input.MetaInput) {
		variables = generators.MergeMaps(variables, request.options.GetTemplateCtx(input.MetaInput).GetAll())
	}
	variables = generators.MergeMaps(variables, request.options.Constants)

	if vardump.EnableVarDump {
		gologger.Debug().Msgf("Whois Protocol request variables: %s\n", vardump.DumpVariables(variables))
	}

	// and replace placeholders
	query := replacer.Replace(request.Query, variables)
	// validate a template-specified server against the network policy.
	if request.parsedServerURL != nil {
		if host := request.parsedServerURL.Hostname(); host != "" {
			if !protocolstate.IsHostAllowed(request.options.Options.ExecutionId, host) {
				return errors.Errorf("whois server %s is blocked by network policy", host)
			}
		}
	}
	// build an rdap request
	rdapReq := rdap.NewAutoRequest(query)
	rdapReq.Server = request.parsedServerURL
	if err := request.options.RateLimitTakeContext(input.Context(), query); err != nil {
		return errors.Wrap(err, "could not take rate limit")
	}
	timeStart := time.Now()
	res, err := request.client.Do(rdapReq)
	duration := time.Since(timeStart)
	if err != nil {
		return errors.Wrap(err, "could not make whois request")
	}
	gologger.Verbose().Msgf("Sent WHOIS request to %s", query)
	if request.options.Options.Debug || request.options.Options.DebugRequests {
		gologger.Debug().Msgf("[%s] Dumped WHOIS request for %s", request.options.TemplateID, query)
	}

	data := make(map[string]interface{})
	var response interface{}
	switch rdapReq.Type {
	case rdap.DomainRequest:
		// convert the rdap response to a whois style response (for domain request type only)
		whoisResp := res.ToWhoisStyleResponse()
		if servers, ok := whoisResp.Data["WHOIS Server"]; ok {
			delete(whoisResp.Data, "WHOIS Server")
			whoisResp.Data["Registrar WHOIS Server"] = servers
			for i, key := range whoisResp.KeyDisplayOrder {
				if key == "WHOIS Server" {
					whoisResp.KeyDisplayOrder[i] = "Registrar WHOIS Server"
				}
			}
		}
		for k, v := range whoisResp.Data {
			data[strings.ToLower(k)] = strings.Join(v, ",")
		}
		response = whoisResp
	default:
		response = res.Object
	}
	jsonData, _ := json.Marshal(response)
	jsonDataString := string(jsonData)

	data["type"] = request.Type().String()
	data["host"] = query
	data["response"] = jsonDataString
	data["duration"] = duration.Seconds()

	// add response fields to template context and merge templatectx variables to output event
	request.options.AddTemplateVars(input.MetaInput, request.Type(), request.ID, data)
	data = generators.MergeMaps(data, request.options.GetTemplateCtx(input.MetaInput).GetAll())

	event := eventcreator.CreateEvent(request, data, request.options.Options.Debug || request.options.Options.DebugResponse)
	if request.options.Options.Debug || request.options.Options.DebugResponse {
		gologger.Debug().Msgf("[%s] Dumped WHOIS response for %s", request.options.TemplateID, query)
		gologger.Print().Msgf("%s", responsehighlighter.Highlight(event.OperatorsResult, jsonDataString, request.options.Options.NoColor, false))
	}

	callback(event)
	return nil
}

// Match performs matching operation for a matcher on model and returns:
// true and a list of matched snippets if the matcher type is supports it
// otherwise false and an empty string slice
func (request *Request) Match(data map[string]interface{}, matcher *matchers.Matcher) (bool, []string) {
	return protocols.MakeDefaultMatchFuncWithExecutorOptions(data, matcher, request.options)
}

// Extract performs extracting operation for an extractor on model and returns true or false.
func (request *Request) Extract(data map[string]interface{}, matcher *extractors.Extractor) map[string]struct{} {
	return protocols.MakeDefaultExtractFuncWithExecutorOptions(data, matcher, request.options)
}

// MakeResultEvent creates a result event from internal wrapped event
func (request *Request) MakeResultEvent(wrapped *output.InternalWrappedEvent) []*output.ResultEvent {
	return protocols.MakeDefaultResultEvent(request, wrapped)
}

// GetCompiledOperators returns a list of the compiled operators
func (request *Request) GetCompiledOperators() []*operators.Operators {
	return []*operators.Operators{request.CompiledOperators}
}

func (request *Request) MakeResultEventItem(wrapped *output.InternalWrappedEvent) *output.ResultEvent {
	data := &output.ResultEvent{
		TemplateID:       types.ToString(request.options.TemplateID),
		TemplatePath:     types.ToString(request.options.TemplatePath),
		Info:             request.options.TemplateInfo,
		TemplateVerifier: request.options.TemplateVerifier,
		Type:             types.ToString(wrapped.InternalEvent["type"]),
		Host:             types.ToString(wrapped.InternalEvent["host"]),
		Metadata:         wrapped.OperatorsResult.PayloadValues,
		ExtractedResults: wrapped.OperatorsResult.OutputExtracts,
		Timestamp:        time.Now(),
		MatcherStatus:    true,
		Request:          types.ToString(wrapped.InternalEvent["request"]),
		Response:         types.ToString(wrapped.InternalEvent["response"]),
		TemplateEncoded:  request.options.EncodeTemplate(),
		Error:            types.ToString(wrapped.InternalEvent["error"]),
	}
	return data
}

// RequestPartDefinitions contains a mapping of request part definitions and their
// description. Multiple definitions are separated by commas.
// Definitions not having a name (generated on runtime) are prefixed & suffixed by <>.
var RequestPartDefinitions = map[string]string{
	"type":     "Type is the type of request made",
	"host":     "Host is the input to the template",
	"response": "WHOIS response data",
	"duration": "Protocol operation duration in seconds",
}

// Type returns the type of the protocol request
func (request *Request) Type() templateTypes.ProtocolType {
	return templateTypes.WHOISProtocol
}

// UpdateOptions replaces this request's options with a new copy
func (r *Request) UpdateOptions(opts *protocols.ExecutorOptions) {
	r.Operators = protocols.CloneOperators(r.Operators)
	r.CompiledOperators = nil
	if r.options == nil {
		if opts != nil {
			r.options = opts.Copy()
		}
		return
	}
	r.options = r.options.Copy()
	r.options.ApplyNewEngineOptions(opts)
}

