	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
)

func TestWhoisPreservesRegistrarWhoisServer(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		require.Equal(t, "/domain/example.com", r.URL.Path)
		w.Header().Set("Content-Type", "application/rdap+json")
		_, _ = fmt.Fprint(w, `{"objectClassName":"domain","ldhName":"example.com","port43":"whois.example.com"}`)
	}))
	t.Cleanup(server.Close)

	_, event, _ := runWhoisDurationRequest(t, "example.com", server.URL)
	require.Equal(t, "whois.example.com", event["registrar whois server"])
	var response struct {
		Data            map[string][]string
		KeyDisplayOrder []string
	}
	require.NoError(t, json.Unmarshal([]byte(event["response"].(string)), &response))
	require.Equal(t, []string{"whois.example.com"}, response.Data["Registrar WHOIS Server"])
	require.Contains(t, response.KeyDisplayOrder, "Registrar WHOIS Server")
	require.NotContains(t, response.KeyDisplayOrder, "WHOIS Server")
}

func TestWhoisDuration(t *testing.T) {
	tests := []struct {
		name         string
		query        string
		expectedPath string
		response     string
	}{
		{
			name:         "domain",
			query:        "example.com",
			expectedPath: "/domain/example.com",
			response: `{
				"objectClassName": "domain",
				"ldhName": "example.com",
				"handle": "D123",
				"status": ["active"],
				"events": [{"eventAction": "registration", "eventDate": "2020-01-01T00:00:00Z"}]
			}`,
		},
		{
			name:         "ip",
			query:        "192.0.2.1",
			expectedPath: "/ip/192.0.2.1",
			response: `{
				"objectClassName": "ip network",
				"handle": "NET-EXAMPLE",
				"startAddress": "192.0.2.0",
				"endAddress": "192.0.2.255"
			}`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				require.Equal(t, tt.expectedPath, r.URL.Path)
				w.Header().Set("Content-Type", "application/rdap+json")
				_, _ = fmt.Fprint(w, tt.response)
			}))
			defer server.Close()

			request, event, values := runWhoisDurationRequest(t, tt.query, server.URL)
			require.Equal(t, templateTypes.WHOISProtocol.String(), event["type"])
			require.Equal(t, tt.query, event["host"])
			require.NotEmpty(t, event["response"])
			requireWhoisDurationField(t, event, "duration")
			require.NotContains(t, event, "duration_1")
			require.Equal(t, event["duration"], values["duration-whois_duration"])
			extractor := &extractors.Extractor{
				Type: extractors.ExtractorTypeHolder{ExtractorType: extractors.DSLExtractor},
				DSL:  []string{"duration"},
			}
			require.NoError(t, extractor.CompileExtractors())
			require.NotEmpty(t, request.Extract(event, extractor))
		})
	}
}

func TestWhoisDurationPartDefinitions(t *testing.T) {
	require.Contains(t, RequestPartDefinitions, "type")
	require.Contains(t, RequestPartDefinitions, "host")
	require.Contains(t, RequestPartDefinitions, "response")
	require.Contains(t, RequestPartDefinitions, "duration")
	require.NotContains(t, RequestPartDefinitions, "duration_ms")
	require.NotContains(t, RequestPartDefinitions, "duration_total")
	require.Equal(t, "whois-id", (&Request{ID: "whois-id"}).GetID())
}

func runWhoisDurationRequest(t *testing.T, query, server string) (*Request, output.InternalEvent, map[string]interface{}) {
	t.Helper()

	options := testutils.DefaultOptions
	testutils.Init(options)

	request := &Request{
		ID:     "duration-whois",
		Query:  query,
		Server: server,
	}
	executerOpts := testutils.NewMockExecuterOptions(options, &testutils.TemplateInfo{
		ID:   "testing-whois-duration",
		Info: model.Info{SeverityHolder: severity.Holder{Severity: severity.Low}, Name: "test"},
	})
	executerOpts.IsMultiProtocol = true
	require.NoError(t, request.Compile(executerOpts))

	var gotEvent output.InternalEvent
	ctxArgs := contextargs.NewWithInput(context.Background(), query)
	err := request.ExecuteWithResults(ctxArgs, nil, nil, func(event *output.InternalWrappedEvent) {
		gotEvent = event.InternalEvent
	})
	require.NoError(t, err)
	require.NotEmpty(t, gotEvent)
	return request, gotEvent, executerOpts.GetTemplateCtx(ctxArgs.MetaInput).GetAll()
}

func requireWhoisDurationField(t *testing.T, event output.InternalEvent, key string) {
	t.Helper()

	value, ok := event[key].(float64)
	require.Truef(t, ok, "expected %s to be a float64 duration", key)
	// Local mocks can finish within one timer tick (esp. on Windows), so 0s is valid.
	require.GreaterOrEqual(t, value, float64(0))
	require.Less(t, value, float64(60))
}

package replay

import (
	"encoding/base64"
	"unicode/utf8"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// Matchers type-assert some values, such as an int status code or a []string
// of dns answers, and binary responses are not valid UTF-8, so plain JSON
// would change what they see. Those values are wrapped in a one-key object
// naming their Go type; everything else is stored as JSON.
const (
	tagBytes   = "$bytes"
	tagBinary  = "$binary"
	tagInt     = "$int"
	tagStrings = "$strings"
)

func encodeEvent(event output.InternalEvent) map[string]any {
	encoded := make(map[string]any, len(event))
	for key, value := range event {
		switch v := value.(type) {
		case string:
			if utf8.ValidString(v) {
				encoded[key] = v
			} else {
				encoded[key] = map[string]string{tagBinary: base64.StdEncoding.EncodeToString([]byte(v))}
			}
		case []byte:
			encoded[key] = map[string]string{tagBytes: base64.StdEncoding.EncodeToString(v)}
		case int:
			encoded[key] = map[string]int{tagInt: v}
		case []string:
			encoded[key] = map[string][]string{tagStrings: v}
		default:
			// values JSON cannot hold, such as funcs, are not something a
			// matcher reads
			if _, err := json.Marshal(v); err == nil {
				encoded[key] = v
			}
		}
	}
	return encoded
}

func decodeEvent(raw map[string]json.Message) (output.InternalEvent, error) {
	event := make(output.InternalEvent, len(raw))
	for key, message := range raw {
		value, err := decodeValue(message)
		if err != nil {
			return nil, err
		}
		event[key] = value
	}
	return event, nil
}

func decodeValue(message json.Message) (any, error) {
	var tagged map[string]json.Message
	if json.Unmarshal(message, &tagged) == nil && len(tagged) == 1 {
		for tag, inner := range tagged {
			switch tag {
			case tagBytes, tagBinary:
				var text string
				if err := json.Unmarshal(inner, &text); err != nil {
					return nil, err
				}
				data, err := base64.StdEncoding.DecodeString(text)
				if err != nil {
					return nil, err
				}
				if tag == tagBinary {
					return string(data), nil
				}
				return data, nil
			case tagInt:
				var number int
				err := json.Unmarshal(inner, &number)
				return number, err
			case tagStrings:
				var list []string
				err := json.Unmarshal(inner, &list)
				return list, err
			}
		}
	}
	var value any
	err := json.Unmarshal(message, &value)
	return value, err
}

// Package replay stores the event every request hands its matchers and
// extractors, for any protocol, and runs templates over a stored corpus again
// without sending anything. Comparing the findings of two template sets or
// two builds on the same corpus shows what a change moved.
package replay

import (
	"os"
	"strconv"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

// record is one line of a corpus.
type record[E any] struct {
	TemplateID string `json:"template-id,omitempty"`
	// Request is the position of the request in its template.
	Request int `json:"request"`
	// ClusterKey identifies the request of a single-request template; every
	// template sending the same request replays the event, as the scan
	// clusters them onto one.
	ClusterKey string `json:"cluster-key,omitempty"`
	Event      E      `json:"event"`
}

type requestRef struct {
	templateID string
	index      int
	single     bool
}

// Recorder appends the events of a scan to a corpus file.
type Recorder struct {
	mu       sync.Mutex
	file     *os.File
	requests map[protocols.Request]requestRef
	err      error
}

// clusterKeyed is a request the scan can cluster. The key leaves out what
// makes a request unclusterable, such as a raw request or a body, so only a
// clusterable request may share events by it.
type clusterKeyed interface {
	TmplClusterKey() uint64
	IsClusterable() bool
}

func clusterKey(request protocols.Request) (string, bool) {
	keyed, ok := request.(clusterKeyed)
	if !ok || !keyed.IsClusterable() {
		return "", false
	}
	return strconv.FormatUint(keyed.TmplClusterKey(), 10), true
}

// NewRecorder creates the corpus at path for a scan of templatesList. The
// corpus holds raw traffic, credentials included, so only its owner can read
// it.
func NewRecorder(path string, templatesList []*templates.Template) (*Recorder, error) {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
	if err != nil {
		return nil, err
	}
	recorder := &Recorder{file: file, requests: make(map[protocols.Request]requestRef)}
	for _, source := range sources(templatesList) {
		single := len(source.requests) == 1 && source.clustered
		for i, request := range source.requests {
			recorder.requests[request] = requestRef{templateID: source.id, index: i, single: single}
		}
	}
	return recorder, nil
}

// Record stores event, which request produced. It runs before the operators,
// which add their own values to the event.
func (r *Recorder) Record(request protocols.Request, event output.InternalEvent) {
	ref, known := r.requests[request]
	if !known {
		// a cluster runs one request for all its members and was compiled
		// apart from them; its members replay it by the cluster key
		key, ok := clusterKey(request)
		if !ok {
			return
		}
		templateID, _ := event["template-id"].(string)
		r.write(record[map[string]any]{TemplateID: templateID, ClusterKey: key, Event: encodeEvent(event)})
		return
	}
	line := record[map[string]any]{TemplateID: ref.templateID, Request: ref.index, Event: encodeEvent(event)}
	if key, ok := clusterKey(request); ok && ref.single {
		line.ClusterKey = key
	}
	r.write(line)
}

func (r *Recorder) write(line record[map[string]any]) {
	data, err := json.Marshal(line)
	if err != nil {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	// written straight to the file: ctrl+c exits without running defers
	if _, err := r.file.Write(append(data, '\n')); err != nil && r.err == nil {
		r.err = err
	}
}

// Close closes the corpus and reports the first write error.
func (r *Recorder) Close() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.file.Close(); err != nil && r.err == nil {
		r.err = err
	}
	return r.err
}

package replay

import (
	"bufio"
	"bytes"
	"cmp"
	"fmt"
	"io"
	"maps"
	"os"
	"slices"
	"strconv"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/helpers/eventcreator"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

type target struct {
	source  source
	request protocols.Request
}

// Replay runs the matchers and extractors of templatesList over every event
// in the corpus at path and returns the findings sorted, so two replays diff
// line by line. An event replays on the template and request that produced
// it, and a single-request event also on every template sending the same
// request.
func Replay(path string, templatesList []*templates.Template) ([]*output.ResultEvent, error) {
	byRequest := make(map[string][]target)
	byCluster := make(map[string][]target)
	for _, source := range sources(templatesList) {
		for i, request := range source.requests {
			byRequest[source.id+"\x00"+strconv.Itoa(i)] = []target{{source: source, request: request}}
		}
		if len(source.requests) == 1 && source.clustered {
			if key, ok := clusterKey(source.requests[0]); ok {
				byCluster[key] = append(byCluster[key], target{source: source, request: source.requests[0]})
			}
		}
	}

	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = file.Close() }()
	var results []*output.ResultEvent
	reader := bufio.NewReader(file)
	for number := 1; ; number++ {
		line, readErr := reader.ReadBytes('\n')
		if line = bytes.TrimSpace(line); len(line) > 0 {
			var stored record[map[string]json.Message]
			if err := json.Unmarshal(line, &stored); err != nil {
				return nil, fmt.Errorf("%s:%d: %w", path, number, err)
			}
			event, err := decodeEvent(stored.Event)
			if err != nil {
				return nil, fmt.Errorf("%s:%d: %w", path, number, err)
			}
			targets := byRequest[stored.TemplateID+"\x00"+strconv.Itoa(stored.Request)]
			if stored.ClusterKey != "" {
				targets = byCluster[stored.ClusterKey]
			}
			for _, target := range targets {
				results = append(results, replayEvent(target, event)...)
			}
		}
		if readErr == io.EOF {
			break
		}
		if readErr != nil {
			return nil, readErr
		}
	}
	// extractors keep values in a map, so their order changes between runs
	for _, result := range results {
		slices.Sort(result.ExtractedResults)
	}
	slices.SortStableFunc(results, compareResults)
	return results, nil
}

func replayEvent(target target, event output.InternalEvent) []*output.ResultEvent {
	// operators add their values to the event, and a cluster event carries
	// the first member's identity
	event = maps.Clone(event)
	event["template-id"] = target.source.id
	event["template-path"] = target.source.path
	event["template-info"] = target.source.info
	return eventcreator.CreateEvent(target.request, event, false).Results
}

func compareResults(a, b *output.ResultEvent) int {
	return cmp.Or(
		strings.Compare(a.TemplateID, b.TemplateID),
		strings.Compare(a.Host, b.Host),
		strings.Compare(a.Matched, b.Matched),
		strings.Compare(a.MatcherName, b.MatcherName),
		strings.Compare(a.ExtractorName, b.ExtractorName),
		strings.Compare(strings.Join(a.ExtractedResults, "\x00"), strings.Join(b.ExtractedResults, "\x00")),
	)
}

package replay

import (
	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/templates"
	"github.com/projectdiscovery/nuclei/v3/pkg/workflows"
)

// source is a template whose requests produce events: a loaded template, or
// a step of a loaded workflow, which may not be loaded on its own.
type source struct {
	id       string
	path     string
	info     model.Info
	requests []protocols.Request
	// clustered mirrors templates.Cluster: only a template the scan can
	// cluster shares events with others by its request
	clustered bool
}

type requestLister interface {
	ProtocolRequests() []protocols.Request
}

type templateExecuter interface {
	requestLister
	TemplateOptions() *protocols.ExecutorOptions
}

func sources(templatesList []*templates.Template) []source {
	var list []source
	seen := make(map[string]bool)
	add := func(s source) {
		if !seen[s.id] && len(s.requests) > 0 {
			seen[s.id] = true
			list = append(list, s)
		}
	}
	addTemplate := func(template *templates.Template) {
		if lister, ok := template.Executer.(requestLister); ok {
			clustered := template.Flow == "" && (template.Options == nil || !template.Options.IsMultiProtocol) && !template.Info.HasPlaceholders()
			add(source{id: template.ID, path: template.Path, info: template.Info, requests: lister.ProtocolRequests(), clustered: clustered})
		}
	}
	var walk func(steps []*workflows.WorkflowTemplate)
	walk = func(steps []*workflows.WorkflowTemplate) {
		for _, step := range steps {
			for _, pair := range step.Executers {
				switch executer := pair.Executer.(type) {
				case templateExecuter:
					options := executer.TemplateOptions()
					add(source{id: options.TemplateID, path: options.TemplatePath, info: options.TemplateInfo, requests: executer.ProtocolRequests()})
				case *templates.ClusterExecuter:
					// a cluster holds only the first member's request; each
					// member is parsed again for its own, which the event is
					// matched to by its cluster key
					for _, path := range executer.TemplatePaths() {
						if member, err := templates.Parse(path, nil, pair.Options); err == nil && member != nil {
							addTemplate(member)
						}
					}
				}
			}
			walk(step.Subtemplates)
			for _, matcher := range step.Matchers {
				walk(matcher.Subtemplates)
			}
		}
	}
	for _, template := range templatesList {
		addTemplate(template)
		if template.CompiledWorkflow != nil {
			walk(template.CompiledWorkflow.Workflows)
		}
	}
	return list
}

package reporting

import (
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
)

// Client is a client for nuclei issue tracking module
type Client interface {
	RegisterTracker(tracker Tracker)
	RegisterExporter(exporter Exporter)
	Close()
	Clear()
	CreateIssue(event *output.ResultEvent) error
	CloseIssue(event *output.ResultEvent) error
	GetReportingOptions() *Options
