// Package dedupe implements deduplication layer for nuclei-generated
// issues.
//
// The layer can be persisted to leveldb based storage for further use.
package dedupe

import (
	"crypto/sha1"
	"encoding/binary"
	"os"
	"slices"
	"sync"

	"github.com/syndtr/goleveldb/leveldb"
	"github.com/syndtr/goleveldb/leveldb/errors"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/utils/conversion"
)

// Storage is a duplicate detecting storage for nuclei scan events.
type Storage struct {
	temporary string
	storage   *leveldb.DB
	mu        sync.Mutex
}

// New creates a new duplicate detecting storage for nuclei scan events.
func New(dbPath string) (*Storage, error) {
	storage := &Storage{}

	var err error
	if dbPath == "" {
		dbPath, err = os.MkdirTemp("", "nuclei-report-*")
		storage.temporary = dbPath
	}
	if err != nil {
		return nil, err
	}

	storage.storage, err = leveldb.OpenFile(dbPath, nil)
	if err != nil {
		if !errors.IsCorrupted(err) {
			return nil, err
		}

		// If the metadata is corrupted, try to recover
		storage.storage, err = leveldb.RecoverFile(dbPath, nil)
		if err != nil {
			return nil, err
		}
	}
	return storage, nil
}

func (s *Storage) Clear() {
	var keys [][]byte
	iter := s.storage.NewIterator(nil, nil)
	for iter.Next() {
		keys = append(keys, iter.Key())
	}
	iter.Release()
	for _, key := range keys {
		_ = s.storage.Delete(key, nil)
	}
}

// Close closes the storage for further operations
func (s *Storage) Close() {
	_ = s.storage.Close()
	if s.temporary != "" {
		_ = os.RemoveAll(s.temporary)
	}
}

// Index indexes an item in storage and returns true if the item
// was unique. Concurrent checks and inserts are serialized.
func (s *Storage) Index(result *output.ResultEvent) (bool, error) {
	hasher := sha1.New()

	// Lengths preserve field and collection boundaries, including empty values.
	writeLength := func(length int) {
		var buf [8]byte
		binary.LittleEndian.PutUint64(buf[:], uint64(length))
		_, _ = hasher.Write(buf[:])
	}

	writeString := func(value string) {
		writeLength(len(value))
		_, _ = hasher.Write(conversion.Bytes(value))
	}

	for _, value := range []string{
		result.TemplateID, result.MatcherName, result.ExtractorName, result.Type,
		result.Host, result.Port, result.Scheme, result.URL, result.Matched,
	} {
		writeString(value)
	}

	writeLength(len(result.ExtractedResults))

	for _, v := range result.ExtractedResults {
		writeString(v)
	}

	writeLength(len(result.Metadata))

	keys := make([]string, 0, len(result.Metadata))
	for k := range result.Metadata {
		keys = append(keys, k)
	}

	slices.Sort(keys)
	for _, k := range keys {
		writeString(k)
		writeString(types.ToString(result.Metadata[k]))
	}

	// Version 2 keys cannot reuse legacy hashes that omitted the input origin.
	key := make([]byte, 1, 1+sha1.Size)
	key[0] = 2
	hash := hasher.Sum(key)

	// LevelDB synchronizes individual operations, not this check and insert.
	s.mu.Lock()
	defer s.mu.Unlock()

	exists, err := s.storage.Has(hash, nil)
	if err != nil {
		// if we have an error, return with it but mark it as true
		// since we don't want to lose an issue considering it a dupe.
		return true, err
	}

	if !exists {
		return true, s.storage.Put(hash, nil, nil)
	}

	return false, err
}

package dedupe

import (
	"crypto/sha1"
	"os"
	"strconv"
	"sync"
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
)

func TestDedupeDistinctInputs(t *testing.T) {
	base := output.ResultEvent{
		TemplateID: "gitlab-detect",
		Type:       "http",
		Host:       "example.com",
		Port:       "80",
		Scheme:     "http",
		URL:        "http://example.com:80",
		Matched:    "https://example.com:443/users/sign_in",
	}
	tests := []struct {
		name   string
		change func(*output.ResultEvent)
	}{
		{"redirected origins", func(event *output.ResultEvent) {
			event.Port = "443"
			event.Scheme = "https"
			event.URL = "https://example.com:443"
		}},
		{"port", func(event *output.ResultEvent) { event.Port = "8080" }},
		{"scheme", func(event *output.ResultEvent) { event.Scheme = "https" }},
		{"url", func(event *output.ResultEvent) { event.URL += "/other" }},
		{"template", func(event *output.ResultEvent) { event.TemplateID = "other" }},
		{"matcher", func(event *output.ResultEvent) { event.MatcherName = "other" }},
		{"extractor", func(event *output.ResultEvent) { event.ExtractorName = "other" }},
		{"protocol", func(event *output.ResultEvent) { event.Type = "headless" }},
		{"host", func(event *output.ResultEvent) { event.Host = "other.example.com" }},
		{"matched", func(event *output.ResultEvent) { event.Matched += "/other" }},
		{"extracted results", func(event *output.ResultEvent) { event.ExtractedResults = []string{"other"} }},
		{"metadata", func(event *output.ResultEvent) { event.Metadata = map[string]interface{}{"payload": "other"} }},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			storage, err := New(t.TempDir())
			require.NoError(t, err)
			t.Cleanup(storage.Close)
			other := base
			tt.change(&other)
			for _, event := range []*output.ResultEvent{&base, &other} {
				unique, err := storage.Index(event)
				require.NoError(t, err)
				require.True(t, unique, "distinct input must be retained")
			}
			for _, event := range []*output.ResultEvent{&base, &other} {
				unique, err := storage.Index(event)
				require.NoError(t, err)
				require.False(t, unique, "repeat finding must be suppressed")
			}
		})
	}
}

func TestDedupeConcurrentDuplicates(t *testing.T) {
	storage, err := New(t.TempDir())
	require.NoError(t, err)
	t.Cleanup(storage.Close)
	const workers = 32
	for trial := range 20 {
		event := output.ResultEvent{TemplateID: strconv.Itoa(trial), Host: "example.com"}
		start := make(chan struct{})
		var wg sync.WaitGroup
		var accepted atomic.Int32
		for range workers {
			wg.Add(1)
			go func() {
				defer wg.Done()
				<-start
				unique, err := storage.Index(&event)
				if err != nil {
					t.Errorf("index concurrent finding: %v", err)
					return
				}
				if unique {
					accepted.Add(1)
				}
			}()
		}
		close(start)
		wg.Wait()
		require.EqualValues(t, 1, accepted.Load(), "trial %d must accept exactly one copy", trial)
	}
}

func TestDedupeMetadataOrder(t *testing.T) {
	storage, err := New(t.TempDir())
	require.NoError(t, err)
	t.Cleanup(storage.Close)
	event := output.ResultEvent{
		TemplateID: "test", Host: "example.com",
		Metadata: map[string]interface{}{"username": "admin", "password": "test", "path": "/login"},
	}
	for i := range 100 {
		unique, err := storage.Index(&event)
		require.NoError(t, err)
		require.Equal(t, i == 0, unique, "metadata order must not change finding identity")
	}
}

func TestDedupeFieldBoundaries(t *testing.T) {
	tests := []struct {
		name  string
		first output.ResultEvent
		next  output.ResultEvent
	}{
		{"matcher", output.ResultEvent{TemplateID: "ab", MatcherName: "c"}, output.ResultEvent{TemplateID: "a", MatcherName: "bc"}},
		{"extracts", output.ResultEvent{ExtractedResults: []string{"ab", "c"}}, output.ResultEvent{ExtractedResults: []string{"a", "bc"}}},
		{"metadata", output.ResultEvent{Metadata: map[string]interface{}{"ab": "c"}}, output.ResultEvent{Metadata: map[string]interface{}{"a": "bc"}}},
		{"collections", output.ResultEvent{ExtractedResults: []string{"a", "b"}}, output.ResultEvent{Metadata: map[string]interface{}{"a": "b"}}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			storage, err := New(t.TempDir())
			require.NoError(t, err)
			t.Cleanup(storage.Close)
			for _, event := range []*output.ResultEvent{&tt.first, &tt.next} {
				event.Host = "example.com"
				unique, err := storage.Index(event)
				require.NoError(t, err)
				require.True(t, unique, "field boundaries must distinguish findings")
			}
		})
	}
}

func TestDedupePersistence(t *testing.T) {
	dir := t.TempDir()
	storage, err := New(dir)
	require.NoError(t, err)
	t.Cleanup(storage.Close)
	// Legacy keys cannot distinguish these two input origins.
	legacy := sha1.Sum([]byte("testhttpexample.comhttps://example.com/login"))
	require.NoError(t, storage.storage.Put(legacy[:], nil, nil))
	events := []output.ResultEvent{
		{TemplateID: "test", Type: "http", Host: "example.com", Port: "80", Scheme: "http", URL: "http://example.com", Matched: "https://example.com/login"},
		{TemplateID: "test", Type: "http", Host: "example.com", Port: "443", Scheme: "https", URL: "https://example.com", Matched: "https://example.com/login"},
	}
	for _, event := range events {
		unique, err := storage.Index(&event)
		require.NoError(t, err)
		require.True(t, unique, "legacy key must not suppress an input origin")
	}
	storage.Close()
	storage, err = New(dir)
	require.NoError(t, err)
	t.Cleanup(storage.Close)
	for _, event := range events {
		unique, err := storage.Index(&event)
		require.NoError(t, err)
		require.False(t, unique, "new keys must persist across reopen")
	}
}

func TestDedupeStorageErrorPreservesFinding(t *testing.T) {
	storage, err := New(t.TempDir())
	require.NoError(t, err)
	storage.Close()
	unique, err := storage.Index(&output.ResultEvent{TemplateID: "test", Host: "example.com"})
	require.Error(t, err)
	require.True(t, unique, "storage errors must not discard findings")
}

func BenchmarkDedupeIndex(b *testing.B) {
	for _, unique := range []bool{false, true} {
		name := "duplicates"
		if unique {
			name = "unique"
		}
		b.Run(name, func(b *testing.B) {
			storage, err := New(b.TempDir())
			require.NoError(b, err)
			b.Cleanup(storage.Close)
			base := output.ResultEvent{
				TemplateID: "gitlab-detect", Type: "http", Host: "example.com",
				Port: "443", Scheme: "https", URL: "https://example.com:443",
				Matched: "https://example.com:443/users/sign_in",
			}
			_, err = storage.Index(&base)
			require.NoError(b, err)
			var next atomic.Uint64
			b.ReportAllocs()
			b.ResetTimer()
			b.RunParallel(func(pb *testing.PB) {
				event := base
				for pb.Next() {
					if unique {
						event.Matched = strconv.FormatUint(next.Add(1), 10)
					}
					if _, err := storage.Index(&event); err != nil {
						b.Error(err)
					}
				}
			})
		})
	}
}

func TestDedupeDuplicates(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "nuclei")
	require.Nil(t, err, "could not create temporary storage")
	defer func() {
		_ = os.RemoveAll(tempDir)
	}()

	storage, err := New(tempDir)
	require.Nil(t, err, "could not create duplicate storage")
	defer storage.Close()

	tests := []*output.ResultEvent{
		{TemplateID: "test", Host: "https://example.com"},
		{TemplateID: "test", Host: "https://example.com"},
	}
	first, err := storage.Index(tests[0])
	require.Nil(t, err, "could not index item")
	require.True(t, first, "could not index valid item")

	second, err := storage.Index(tests[1])
	require.Nil(t, err, "could not index item")
	require.False(t, second, "could index duplicate item")
}

package csv

import (
	"encoding/csv"
	"os"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
)

const (
	// defaultFile is used when no file is configured, mirroring the PDF
	// exporter. The generated default reporting config lists every exporter with
	// an empty block, and an empty block must not stop the client from starting.
	defaultFile = "nuclei-results.csv"

	// filePerm keeps the export private to the current user. Rows carry
	// extracted response data and a replayable curl command, which can include
	// credentials, so the file is not world readable by default.
	filePerm = 0o600

	// multiValueSeparator separates the elements of a multi-value cell.
	multiValueSeparator = "\n"
)

// Options contains the configuration options for the CSV exporter client
type Options struct {
	// File is the file to export found CSV result to
	File string `yaml:"file"`
	// OmitRaw whether to leave the curl command, which is a rendering of the raw
	// request, out of the export
	OmitRaw bool `yaml:"omit-raw"`
}

// header is the ordered list of columns written to the CSV file.
//
// The schema is a flattened full row of the result event: everything a triage
// or GRC workflow normally needs is present as its own column, so the file can
// be opened in a spreadsheet or handed to a ticketing/SIEM intake without any
// further transformation.
//
// Column names mirror the JSON/JSONL keys of output.ResultEvent one-for-one so
// a column can always be traced back to the field it came from, and match the
// names httpx uses in its own CSV mode where they overlap (host, port,
// timestamp). The two exceptions are template-name and template-type, which map
// to info.name and type: bare "name"/"type" are ambiguous as spreadsheet
// headers.
var header = []string{
	"template-id",
	"template-name",
	"template-type",
	"severity",
	"host",
	"ip",
	"port",
	"matched-at",
	"matcher-name",
	"extractor-name",
	"extracted-results",
	"cve-id",
	"cwe-id",
	"cvss-metrics",
	"cvss-score",
	"description",
	"reference",
	"curl-command",
	"timestamp",
}

// Exporter is an exporter for nuclei results in CSV format
type Exporter struct {
	options    *Options
	mutex      *sync.Mutex
	writer     *csv.Writer
	outputFile *os.File
	closed     bool
}

// New creates a new CSV exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	opts := &Options{}
	if options != nil {
		*opts = *options
	}
	if opts.File == "" {
		opts.File = defaultFile
	}

	outputFile, err := os.OpenFile(opts.File, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, filePerm)
	if err != nil {
		return nil, errors.Wrap(err, "failed to create CSV file")
	}

	writer := csv.NewWriter(outputFile)
	if err := writer.Write(header); err != nil {
		_ = outputFile.Close()
		return nil, errors.Wrap(err, "failed to write CSV header")
	}
	writer.Flush()
	if err := writer.Error(); err != nil {
		_ = outputFile.Close()
		return nil, errors.Wrap(err, "failed to write CSV header")
	}

	return &Exporter{
		mutex:      &sync.Mutex{},
		options:    opts,
		writer:     writer,
		outputFile: outputFile,
	}, nil
}

// Export appends the passed result event as a flattened row to the CSV file.
// Rows are flushed as they are written so the file is complete and readable
// while a long scan is still running. The event is only read, never modified,
// because the same event is handed to every exporter and tracker.
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	if event == nil {
		return nil
	}

	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	if exporter.closed {
		return errors.New("CSV exporter is closed")
	}

	if err := exporter.writer.Write(formatRow(event, exporter.options.OmitRaw)); err != nil {
		return errors.Wrap(err, "failed to write CSV row")
	}
	exporter.writer.Flush()
	if err := exporter.writer.Error(); err != nil {
		return errors.Wrap(err, "failed to write CSV row")
	}

	return nil
}

// formulaTriggers are the leading characters that Excel, LibreOffice Calc and
// Google Sheets treat as the start of a formula. A cell beginning with one of
// them is evaluated when the file is opened, so a response-derived value such
// as `=cmd|'/C calc'!A0` captured by an extractor would execute on the machine
// of whoever opens the export (CWE-1236).
const formulaTriggers = "=+-@\t\r"

// plainNumber matches a value that is only a decimal number. It is used to keep
// numeric cells such as a negative extracted value sortable. It is deliberately
// stricter than strconv.ParseFloat, which also accepts forms like "+Inf",
// "-NaN" and hex floats that a spreadsheet does not read as numbers.
var plainNumber = regexp.MustCompile(`^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?$`)

// startsWithFormulaTrigger reports whether a spreadsheet would read the value
// as a formula. Leading spaces and control characters are skipped first,
// because some spreadsheets ignore them before the trigger.
func startsWithFormulaTrigger(value string) bool {
	for i := 0; i < len(value); i++ {
		c := value[i]
		if strings.IndexByte(formulaTriggers, c) >= 0 {
			return true
		}
		if c > ' ' {
			return false
		}
	}
	return false
}

// neutralizeFormula prefixes a single apostrophe to any value a spreadsheet
// would evaluate as a formula, which forces the cell to be read as text.
//
// The original value is recovered by removing one leading apostrophe, except
// for a value that already started with an apostrophe, which is left alone and
// is therefore indistinguishable from a neutralized one. Values that are only a
// plain number are left untouched so numeric columns (cvss-score, port) stay
// sortable and a negative number is not needlessly quoted.
func neutralizeFormula(value string) string {
	if !startsWithFormulaTrigger(value) || plainNumber.MatchString(value) {
		return value
	}
	return "'" + value
}

// neutralizeLines neutralizes every line of a value that is stored as a list
// of lines. Consumers split these cells back into lines, so each line has to be
// safe on its own and not just the start of the cell. Line endings are
// normalized to a single newline, which is the separator of the list.
func neutralizeLines(value string) string {
	if value == "" {
		return ""
	}
	value = strings.ReplaceAll(value, "\r\n", "\n")
	value = strings.ReplaceAll(value, "\r", "\n")
	lines := strings.Split(value, "\n")
	for i, line := range lines {
		lines[i] = neutralizeFormula(line)
	}
	return strings.Join(lines, "\n")
}

// neutralizeList joins the elements of a multi-value column with the given
// separator after neutralizing each element, and each line of each element.
func neutralizeList(values []string, separator string) string {
	if len(values) == 0 {
		return ""
	}
	neutralized := make([]string, 0, len(values))
	for _, value := range values {
		neutralized = append(neutralized, neutralizeLines(value))
	}
	return strings.Join(neutralized, separator)
}

// formatRow flattens a ResultEvent into the ordered set of CSV columns defined
// by header. Empty values are emitted for fields that are not present on the
// event (for example, templates without CVE/CVSS classification metadata).
//
// Two separate escaping concerns are handled here. Structural injection is
// handled by encoding/csv, which RFC 4180-quotes any value carrying a comma,
// double quote or newline so it cannot forge extra columns or rows. Spreadsheet
// formula evaluation is handled by neutralizeFormula, because the target of
// this exporter is explicitly a file someone opens in a spreadsheet. Every
// column goes through it, including the ones that normally hold a controlled
// value, because template metadata is written by the template author and is not
// trusted either.
func formatRow(event *output.ResultEvent, omitRaw bool) []string {
	var cve, cwe, cvssMetrics, cvssScore string
	if event.Info.Classification != nil {
		classification := event.Info.Classification
		// CVE/CWE identifiers cannot contain a comma, so they keep the ", "
		// form used everywhere else in nuclei.
		cve = neutralizeList(classification.CVEID.ToSlice(), ", ")
		cwe = neutralizeList(classification.CWEID.ToSlice(), ", ")
		cvssMetrics = classification.CVSSMetrics
		if classification.CVSSScore > 0 {
			cvssScore = strconv.FormatFloat(classification.CVSSScore, 'f', -1, 64)
		}
	}

	// References are URLs and can themselves contain a comma, so they are
	// newline separated inside the (quoted) cell rather than comma separated.
	var reference string
	if event.Info.Reference != nil {
		reference = neutralizeList(event.Info.Reference.ToSlice(), multiValueSeparator)
	}

	var curlCommand string
	if !omitRaw {
		curlCommand = event.CURLCommand
	}

	var timestamp string
	if !event.Timestamp.IsZero() {
		timestamp = event.Timestamp.UTC().Format(time.RFC3339)
	}

	return []string{
		neutralizeFormula(event.TemplateID),
		neutralizeFormula(event.Info.Name),
		neutralizeFormula(event.Type),
		neutralizeFormula(event.Info.SeverityHolder.Severity.String()),
		neutralizeFormula(event.Host),
		neutralizeFormula(event.IP),
		neutralizeFormula(event.Port),
		neutralizeFormula(event.Matched),
		neutralizeFormula(event.MatcherName),
		neutralizeFormula(event.ExtractorName),
		// Extracted results are arbitrary response-derived data and can contain
		// commas and newlines, so they are newline separated inside the
		// (quoted) cell, with every line neutralized on its own.
		neutralizeList(event.ExtractedResults, multiValueSeparator),
		cve,
		cwe,
		neutralizeFormula(cvssMetrics),
		neutralizeFormula(cvssScore),
		neutralizeFormula(event.Info.Description),
		reference,
		neutralizeFormula(curlCommand),
		neutralizeFormula(timestamp),
	}
}

// Close flushes any buffered rows and closes the CSV file. It is safe to call
// more than once.
func (exporter *Exporter) Close() error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	if exporter.closed {
		return nil
	}
	exporter.closed = true

	exporter.writer.Flush()
	if err := exporter.writer.Error(); err != nil {
		_ = exporter.outputFile.Close()
		return errors.Wrap(err, "failed to flush CSV file")
	}

	if err := exporter.outputFile.Close(); err != nil {
		return errors.Wrap(err, "failed to close CSV file")
	}

	return nil
}

