package jsonexporter

import (
	"os"
	"sync"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

type Exporter struct {
	options *Options
	mutex   *sync.Mutex
	rows    []output.ResultEvent
}

// Options contains the configuration options for JSON exporter client
type Options struct {
	// File is the file to export found JSON result to
	File    string `yaml:"file"`
	OmitRaw bool   `yaml:"omit-raw"`
}

// New creates a new JSON exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	exporter := &Exporter{
		mutex:   &sync.Mutex{},
		options: options,
		rows:    []output.ResultEvent{},
	}
	return exporter, nil
}

// Export appends the passed result event to the list of objects to be exported to
// the resulting JSON file
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Work on a copy: every exporter is handed the same event.
	row := *event
	if exporter.options.OmitRaw {
		row.Request = ""
		row.Response = ""
	}

	// Add the event to the rows
	exporter.rows = append(exporter.rows, row)

	return nil
}

// Close writes the in-memory data to the JSON file specified by options.JSONExport
// and closes the exporter after operation
func (exporter *Exporter) Close() error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Convert the rows to JSON byte array
	obj, err := json.Marshal(exporter.rows)
	if err != nil {
		return errors.Wrap(err, "failed to generate JSON report")
	}

	// Attempt to write the JSON to file specified in options.JSONExport
	if err := os.WriteFile(exporter.options.File, obj, 0644); err != nil {
		return errors.Wrap(err, "failed to create JSON file")
	}

	return nil
}

package jsonl

import (
	"os"
	"sync"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
)

type Exporter struct {
	options    *Options
	mutex      *sync.Mutex
	rows       []output.ResultEvent
	outputFile *os.File
}

// Options contains the configuration options for JSONL exporter client
type Options struct {
	// File is the file to export found JSONL result to
	File string `yaml:"file"`
	// OmitRaw whether to exclude the raw request and response from the output
	OmitRaw bool `yaml:"omit-raw"`
	// BatchSize the number of records to keep in memory before writing them out to the JSONL file or 0 to disable
	// batching (default)
	BatchSize int `yaml:"batch-size"`
}

// New creates a new JSONL exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	exporter := &Exporter{
		mutex:   &sync.Mutex{},
		options: options,
		rows:    []output.ResultEvent{},
	}
	return exporter, nil
}

// Export appends the passed result event to the list of objects to be exported to the resulting JSONL file
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Work on a copy: every exporter is handed the same event.
	row := *event
	if exporter.options.OmitRaw {
		row.Request = ""
		row.Response = ""
	}

	// Add the event to the rows
	exporter.rows = append(exporter.rows, row)

	// If the batch size is greater than 0 and the number of rows has reached the batch, flush it to the database
	if exporter.options.BatchSize > 0 && len(exporter.rows) >= exporter.options.BatchSize {
		err := exporter.WriteRows()
		if err != nil {
			// The error is already logged, return it to bubble up to the caller
			return err
		}
	}

	return nil
}

// WriteRows writes all rows from the rows list to JSONL file and removes them from the list
func (exporter *Exporter) WriteRows() error {
	// Open the file for writing if it's not already.
	// This will recreate the file if it exists, but keep the file handle so that batched writes within the same
	// execution are appended to the same file.
	var err error
	if exporter.outputFile == nil {
		// Open the JSONL file for writing and create it if it doesn't exist
		exporter.outputFile, err = os.OpenFile(exporter.options.File, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
		if err != nil {
			return errors.Wrap(err, "failed to create JSONL file")
		}
	}

	// Loop through the rows and write them, removing them as they're entered
	for len(exporter.rows) > 0 {
		row := exporter.rows[0]

		// Convert the row to JSON byte array and append a trailing newline. This is treated as a single line in JSONL
		obj, err := json.Marshal(row)
		if err != nil {
			return errors.Wrap(err, "failed to generate row for JSONL report")
		}

		obj = append(obj, '\n')

		// Attempt to append the JSON line to file specified in options.JSONLExport
		if _, err = exporter.outputFile.Write(obj); err != nil {
			return errors.Wrap(err, "failed to append JSONL line")
		}

		// Remove the item from the list
		exporter.rows = exporter.rows[1:]
	}

	return nil
}

// Close writes the in-memory data to the JSONL file specified by options.JSONLExport and closes the exporter after
// operation
func (exporter *Exporter) Close() error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Write any remaining rows to the file
	// Write all pending rows
	err := exporter.WriteRows()
	if err != nil {
		if exporter.outputFile != nil {
			_ = exporter.outputFile.Close()
		}
		// The error is already logged, return it to bubble up to the caller
		return err
	}

	// Close the file
	if err := exporter.outputFile.Close(); err != nil {
		return errors.Wrap(err, "failed to close JSONL file")
	}

	return nil
}

package markdown

import (
	"bytes"
	"os"
	"path/filepath"
	"unicode/utf8"

	"github.com/google/uuid"
	"github.com/projectdiscovery/gologger"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/exporters/markdown/util"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/format"
	fileutil "github.com/projectdiscovery/utils/file"
	stringsutil "github.com/projectdiscovery/utils/strings"
)

const indexFileName = "index.md"
const extension = ".md"
const maxFilenameLength = 255

type Exporter struct {
	directory string
	options   *Options
}

// Options contains the configuration options for GitHub issue tracker client
type Options struct {
	// Directory is the directory to export found results to
	Directory string `yaml:"directory"`
	OmitRaw   bool   `yaml:"omit-raw"`
	SortMode  string `yaml:"sort-mode"`
}

// New creates a new markdown exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	directory := options.Directory
	if options.Directory == "" {
		dir, err := os.Getwd()
		if err != nil {
			return nil, err
		}
		directory = dir
	}
	_ = os.MkdirAll(directory, 0755)

	// index generation header
	dataHeader := util.CreateTableHeader("Hostname/IP", "Finding", "Severity")

	err := os.WriteFile(filepath.Join(directory, indexFileName), []byte(dataHeader), 0644)
	if err != nil {
		return nil, err
	}

	return &Exporter{options: options, directory: directory}, nil
}

// Export exports a passed result event to markdown
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	// index file generation
	file, err := os.OpenFile(filepath.Join(exporter.directory, indexFileName), os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	defer func() {
		_ = file.Close()
	}()

	filename := createFileName(event)

	// If the sort mode is set to severity, host, or template, then we need to get a safe version of the name for a
	// subdirectory to store the file in.
	// This will allow us to sort the files into subdirectories based on the sort mode. The subdirectory will need to
	// be created if it does not exist.
	fileUrl := filename
	subdirectory := ""
	switch exporter.options.SortMode {
	case "severity":
		subdirectory = event.Info.SeverityHolder.Severity.String()
	case "host":
		subdirectory = event.Host
	case "template":
		subdirectory = event.TemplateID
	}
	if subdirectory != "" {
		// Sanitize the subdirectory name to remove any characters that are not allowed in a directory name
		subdirectory = sanitizeFilename(subdirectory)

		// Prepend the subdirectory name to the filename for the fileUrl
		fileUrl = filepath.Join(subdirectory, filename)

		// Create the subdirectory if it does not exist
		if err = fileutil.CreateFolders(filepath.Join(exporter.directory, subdirectory)); err != nil {
			gologger.Warning().Msgf("Could not create subdirectory for markdown report: %s", err)
		}
	}

	host := util.CreateLink(event.Host, fileUrl)
	finding := event.TemplateID + " " + event.MatcherName
	severity := event.Info.SeverityHolder.Severity.String()

	dataBuilder := &bytes.Buffer{}
	dataBuilder.WriteString(util.CreateHeading3(format.Summary(event)))
	dataBuilder.WriteString("\n")
	dataBuilder.WriteString(util.CreateHorizontalLine())
	dataBuilder.WriteString(format.CreateReportDescription(event, util.MarkdownFormatter{}, exporter.options.OmitRaw))
	data := dataBuilder.Bytes()

	if err := os.WriteFile(filepath.Join(exporter.directory, subdirectory, filename), data, 0644); err != nil {
		return err
	}

	_, err = file.WriteString(util.CreateTableRow(host, finding, severity))
	return err
}

func createFileName(event *output.ResultEvent) string {
	operatorName := ""
	if event.MatcherName != "" {
		operatorName = event.MatcherName
	} else if event.ExtractorName != "" {
		operatorName = event.ExtractorName
	}

	// Keep the UUID and extension outside the truncated prefix. Cutting the
	// assembled name drops them when the template id or host is long, so
	// different findings overwrite one report.
	uniqueSuffix := "-" + uuid.NewString()
	if operatorName != "" {
		operatorBudget := maxFilenameLength - len(uniqueSuffix) - len(extension) - 1
		uniqueSuffix += "-" + truncateFilename(sanitizeFilenamePart(operatorName), operatorBudget)
	}
	uniqueSuffix += extension

	prefix := sanitizeFilenamePart(event.TemplateID + "-" + event.Host)
	prefix = truncateFilename(prefix, maxFilenameLength-len(uniqueSuffix))
	return prefix + uniqueSuffix
}

// Close closes the exporter after operation
func (exporter *Exporter) Close() error {
	return nil
}

func sanitizeFilename(filename string) string {
	return truncateFilename(sanitizeFilenamePart(filename), maxFilenameLength)
}

func sanitizeFilenamePart(filename string) string {
	// Note: "\\" must be replaced together with "/" so an attacker-controlled
	// host or template id with Windows-style path separators cannot traverse
	// out of the configured directory when this value is later used as a
	// subdirectory or filename. ".." is replaced for the same reason — even
	// without a separator, a name of "..foo" is harmless but a name of ".."
	// alone (or any sequence containing "..") is treated by filepath.Clean as
	// a parent reference once joined with the report directory.
	return stringsutil.ReplaceAll(filename, "_", "?", "/", "\\", "..", ">", "|", ":", ";", "*", "<", "\"", "'", " ")
}

func truncateFilename(filename string, maxBytes int) string {
	if maxBytes <= 0 {
		return ""
	}
	if len(filename) <= maxBytes {
		return filename
	}
	filename = filename[:maxBytes]
	for len(filename) > 0 && !utf8.ValidString(filename) {
		filename = filename[:len(filename)-1]
	}
	return filename
}

package markdown

import (
	"path/filepath"
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/google/uuid"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/stretchr/testify/require"
)

func TestCreateFileNameIncludesOperatorName(t *testing.T) {
	tests := []struct {
		name          string
		matcherName   string
		extractorName string
		wantSuffix    string
	}{
		{
			name:        "matcher",
			matcherName: "body-matcher",
			wantSuffix:  "body-matcher.md",
		},
		{
			name:          "extractor",
			extractorName: "token-extractor",
			wantSuffix:    "token-extractor.md",
		},
		{
			name:          "matcher takes precedence",
			matcherName:   "body-matcher",
			extractorName: "token-extractor",
			wantSuffix:    "body-matcher.md",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			filename := createFileName(&output.ResultEvent{
				TemplateID:    "template-id",
				Host:          "example.com",
				MatcherName:   test.matcherName,
				ExtractorName: test.extractorName,
			})

			require.True(t, strings.HasSuffix(filename, test.wantSuffix), filename)
		})
	}
}

func TestCreateFileNamePreservesUniqueSuffixWhenLong(t *testing.T) {
	filename := createFileName(&output.ResultEvent{
		TemplateID:    strings.Repeat("template", 100),
		Host:          strings.Repeat("host", 100),
		ExtractorName: "token-extractor",
	})

	require.LessOrEqual(t, len(filename), maxFilenameLength)
	const operatorSuffix = "-token-extractor.md"
	require.True(t, strings.HasSuffix(filename, operatorSuffix), filename)
	withoutOperator := strings.TrimSuffix(filename, operatorSuffix)
	require.GreaterOrEqual(t, len(withoutOperator), 37)
	_, err := uuid.Parse(withoutOperator[len(withoutOperator)-36:])
	require.NoError(t, err)
}

func TestSanitizeFilenameTruncatesAtUTF8Boundary(t *testing.T) {
	filename := sanitizeFilename(strings.Repeat("界", maxFilenameLength))

	require.LessOrEqual(t, len(filename), maxFilenameLength)
	require.True(t, utf8.ValidString(filename))
}

// TestSanitizeFilenameStripsPathSeparatorsAndDotDot ensures user-supplied
// values (event.Host, event.TemplateID) used to build subdirectory and file
// names cannot escape the reporting directory.
//
// The previous sanitizer only replaced "/" but not "\\" and not "..", which
// allowed Windows-style traversal like "..\\..\\foo" to flow through to
// filepath.Join + filepath.Clean and end up outside the configured directory.
func TestSanitizeFilenameStripsPathSeparatorsAndDotDot(t *testing.T) {
	cases := []struct {
		name     string
		input    string
		mustNot  []string
		mustHave []string
	}{
		{
			name:    "forward slash traversal",
			input:   "../../etc/passwd",
			mustNot: []string{"/", ".."},
		},
		{
			name:    "backslash traversal",
			input:   "..\\..\\etc\\passwd",
			mustNot: []string{"\\", ".."},
		},
		{
			name:    "mixed separators",
			input:   "..\\../etc",
			mustNot: []string{"/", "\\", ".."},
		},
		{
			name:    "bare dotdot",
			input:   "..",
			mustNot: []string{".."},
		},
		{
			name:     "embedded dotdot stays substringless",
			input:    "evil..foo",
			mustNot:  []string{".."},
			mustHave: []string{"evil"},
		},
		{
			name:     "legitimate hostname is preserved enough",
			input:    "example.com",
			mustHave: []string{"example", "com"},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out := sanitizeFilename(tc.input)
			for _, s := range tc.mustNot {
				require.False(t, strings.Contains(out, s),
					"sanitized %q (in=%q) must not contain %q", out, tc.input, s)
			}
			for _, s := range tc.mustHave {
				require.True(t, strings.Contains(out, s),
					"sanitized %q (in=%q) should still contain %q", out, tc.input, s)
			}
		})
	}
}

// TestSanitizedSubdirectoryStaysWithinReportDirectory is a stronger assertion
// that the sanitizer's output, when joined into the report directory and
// cleaned by filepath.Clean (the same code path the markdown exporter walks),
// never escapes that directory. This guards against future regressions in the
// sanitizer that might let a separator slip through.
func TestSanitizedSubdirectoryStaysWithinReportDirectory(t *testing.T) {
	reportDir := t.TempDir()
	hostileInputs := []string{
		"../../etc/passwd",
		"..\\..\\etc\\passwd",
		"..",
		"..\\..\\..\\Windows\\System32",
		"some/host/../../escape",
		// Many-dot variants that earlier ReplaceAll iterations might leave a
		// stray ".." behind (strings.ReplaceAll guarantees no remaining match
		// of the pattern, so even adversarial dot runs collapse safely).
		"...",
		"....",
		".....",
		"......",
		"./.../...",
		"/../../foo",
		"\\..\\..\\foo",
		// Mixed separators on Linux/Windows.
		"a/b\\..\\..\\..\\c",
		"a\\b/../../../c",
		// Embedded NUL — written here as escape; the sanitizer doesn't
		// special-case it, but filepath.Clean handles it as a literal byte.
		"foo\x00..\\bar",
		// Long traversal sequences that cross MAX_PATH-ish boundaries.
		strings.Repeat("../", 200) + "etc/passwd",
		strings.Repeat("..\\", 200) + "Windows",
	}

	for _, in := range hostileInputs {
		t.Run(in, func(t *testing.T) {
			subdir := sanitizeFilename(in)
			// After sanitize the result must not contain a path separator or
			// a parent-reference token at all; otherwise filepath.Clean +
			// filepath.Join could collapse it into a traversal.
			require.False(t, strings.ContainsAny(subdir, "/\\"),
				"sanitizer leaked a path separator: in=%q out=%q", in, subdir)
			require.False(t, strings.Contains(subdir, ".."),
				"sanitizer leaked '..' substring: in=%q out=%q", in, subdir)

			joined := filepath.Clean(filepath.Join(reportDir, subdir))

			// Cleaned path must remain a child of reportDir (or equal to it
			// when the sanitizer reduced everything to underscores).
			rel, err := filepath.Rel(reportDir, joined)
			require.NoError(t, err)
			require.NotEqual(t, "..", rel)
			require.False(t, strings.HasPrefix(rel, ".."+string(filepath.Separator)),
				"input %q produced rel %q which escapes reportDir", in, rel)
		})
	}
}

// FuzzSanitizeFilenameStaysContained is a property test: for any input the
// sanitizer can be fed (event.Host, event.TemplateID, etc.), the output joined
// to a fixed report directory must always resolve back inside that directory.
// This is the reporter's invariant, and the fuzz test makes future regressions
// in the sanitizer impossible to land silently.
func FuzzSanitizeFilenameStaysContained(f *testing.F) {
	seeds := []string{
		"",
		"foo",
		"..",
		"../..",
		"/../etc/passwd",
		"\\..\\..\\Windows",
		"..\\../mixed",
		"foo..bar..baz",
		strings.Repeat("..", 100),
		strings.Repeat("..\\", 100),
		strings.Repeat("../", 100),
		strings.Repeat(".", 1000),
		strings.Repeat("\\", 1000),
		strings.Repeat("/", 1000),
		"\x00\x00\x00..",
		"foo\x00..\\bar",
		"\u202e..\u202d", // RTL/LTR marks around dotdot
	}
	for _, s := range seeds {
		f.Add(s)
	}

	reportDir := f.TempDir()

	f.Fuzz(func(t *testing.T, in string) {
		out := sanitizeFilename(in)
		// Sanitize must never emit a separator or "..". This is the invariant
		// the markdown exporter relies on at filepath.Join time.
		if strings.ContainsAny(out, "/\\") {
			t.Fatalf("sanitizer leaked a separator: in=%q out=%q", in, out)
		}
		if strings.Contains(out, "..") {
			t.Fatalf("sanitizer leaked '..': in=%q out=%q", in, out)
		}

		// The joined+cleaned path must stay inside the report dir.
		joined := filepath.Clean(filepath.Join(reportDir, out))
		rel, err := filepath.Rel(reportDir, joined)
		if err != nil {
			t.Fatalf("Rel error for in=%q out=%q: %v", in, out, err)
		}
		if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			t.Fatalf("escape from reportDir: in=%q out=%q rel=%q", in, out, rel)
		}
	})
}

package util

import (
	"fmt"
	"strings"
)

type MarkdownFormatter struct{}

func (markdownFormatter MarkdownFormatter) MakeBold(text string) string {
	return MakeBold(text)
}

func (markdownFormatter MarkdownFormatter) CreateCodeBlock(title string, content string, language string) string {
	escapedContent := escapeCodeBlockMarkdown(content)
	return fmt.Sprintf("\n%s\n```%s\n%s\n```\n", markdownFormatter.MakeBold(title), language, escapedContent)
}

func (markdownFormatter MarkdownFormatter) CreateTable(headers []string, rows [][]string) (string, error) {
	return CreateTable(headers, rows)
}

func (markdownFormatter MarkdownFormatter) CreateLink(title string, url string) string {
	return CreateLink(title, url)
}

func (markdownFormatter MarkdownFormatter) CreateHorizontalLine() string {
	return CreateHorizontalLine()
}

// escapeCodeBlockMarkdown only escapes the bare minimum characters needed
// for code blocks and other sections where readability is important
//
// For content inside code blocks, we only need to escape backticks
// and backslashes to prevent breaking out
func escapeCodeBlockMarkdown(text string) string {
	minimalChars := []string{
		"\\", "`",
	}

	result := text
	for _, char := range minimalChars {
		result = strings.ReplaceAll(result, char, "\\"+char)
	}
	return result
}

package util

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/projectdiscovery/utils/errkit"
)

func CreateLink(title string, url string) string {
	return fmt.Sprintf("[%s](%s)", title, url)
}

func MakeBold(text string) string {
	return "**" + text + "**"
}

func CreateTable(headers []string, rows [][]string) (string, error) {
	builder := &bytes.Buffer{}
	headerSize := len(headers)
	if headers == nil || headerSize == 0 {
		return "", errkit.New("No headers provided")
	}

	builder.WriteString(CreateTableHeader(headers...))

	for _, row := range rows {
		rowSize := len(row)
		if rowSize == headerSize {
			builder.WriteString(CreateTableRow(row...))
		} else if rowSize < headerSize {
			extendedRows := make([]string, headerSize)
			copy(extendedRows, row)
			builder.WriteString(CreateTableRow(extendedRows...))
		} else {
			return "", errkit.New("Too many columns for the given headers")
		}
	}

	return builder.String(), nil
}

func CreateTableHeader(headers ...string) string {
	headerSize := len(headers)
	if headers == nil || headerSize == 0 {
		return ""
	}

	return CreateTableRow(headers...) +
		"|" + strings.Repeat(" --- |", headerSize) + "\n"
}

func CreateTableRow(elements ...string) string {
	return fmt.Sprintf("| %s |\n", strings.Join(elements, " | "))
}

func CreateHeading3(text string) string {
	return "### " + text + "\n"
}

func CreateHorizontalLine() string {
	// for regular markdown 3 dashes are enough, but for Jira the minimum is 4
	return "----\n"
}

