func TestEscapeCodeBlockMarkdown(t *testing.T) {
	testCases := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "no special characters",
			input:    "normal text without special chars",
			expected: "normal text without special chars",
		},
		{
			name:     "with backticks",
			input:    "text with `backticks` inside",
			expected: "text with \\`backticks\\` inside",
		},
		{
			name:     "with backslashes",
			input:    "text with \\ backslash",
			expected: "text with \\\\ backslash",
		},
		{
			name:     "with both backticks and backslashes",
			input:    "text with `backticks` and \\ backslash",
			expected: "text with \\`backticks\\` and \\\\ backslash",
		},
		{
			name:     "with code block",
			input:    "```code block```",
			expected: "\\`\\`\\`code block\\`\\`\\`",
		},
		{
			name:     "with escaped backtick",
			input:    "escaped \\` backtick",
			expected: "escaped \\\\\\` backtick",
		},
		{
			name:     "with multiple consecutive backticks",
			input:    "``double backticks``",
			expected: "\\`\\`double backticks\\`\\`",
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := escapeCodeBlockMarkdown(tc.input)
			require.Equal(t, tc.expected, result, "Failed to properly escape markdown for code blocks")
		})
	}
}

package mongo

import (
	"context"
	"net/url"
	"os"
	"strings"
	"sync"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"go.mongodb.org/mongo-driver/mongo"

	mongooptions "go.mongodb.org/mongo-driver/mongo/options"
)

type Exporter struct {
	options    *Options
	mutex      *sync.Mutex
	rows       []output.ResultEvent
	collection *mongo.Collection
	connection *mongo.Client
}

// Options contains the configuration options for MongoDB exporter client
type Options struct {
	// ConnectionString is the connection string to the MongoDB database
	ConnectionString string `yaml:"connection-string"`
	// CollectionName is the name of the MongoDB collection in which to store the results
	CollectionName string `yaml:"collection-name"`
	// OmitRaw excludes the Request and Response from the results (helps with filesize)
	OmitRaw bool `yaml:"omit-raw"`
	// BatchSize determines the number of results to be kept in memory before writing it to the database or 0 to
	//	persist all in memory and write all results at the end (default)
	BatchSize int `yaml:"batch-size"`
}

// New creates a new MongoDB exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	exporter := &Exporter{
		mutex:   &sync.Mutex{},
		options: options,
		rows:    []output.ResultEvent{},
	}

	// If the environment variable for the connection string is set, then use that instead. This allows for easier
	// management of sensitive items such as credentials
	envConnectionString := os.Getenv("MONGO_CONNECTION_STRING")
	if envConnectionString != "" {
		options.ConnectionString = envConnectionString
		gologger.Info().Msgf("Using connection string from environment variable MONGO_CONNECTION_STRING")
	}

	// Create the connection to the database
	clientOptions := mongooptions.Client().ApplyURI(options.ConnectionString)

	// Create a new client and connect to the MongoDB server
	client, err := mongo.Connect(context.TODO(), clientOptions)
	if err != nil {
		gologger.Error().Msgf("Error creating MongoDB client: %s", err)
		return nil, err
	}

	// Ensure the connection is valid
	err = client.Ping(context.Background(), nil)
	if err != nil {
		gologger.Error().Msgf("Error connecting to MongoDB: %s", err)
		return nil, err
	}

	// Get the database from the connection string to set the database and collection
	parsed, err := url.Parse(options.ConnectionString)
	if err != nil {
		gologger.Error().Msgf("Error parsing connection string: %s", options.ConnectionString)
		return nil, err
	}

	databaseName := strings.TrimPrefix(parsed.Path, "/")

	if databaseName == "" {
		return nil, errors.New("error getting database name from connection string")
	}

	exporter.connection = client
	exporter.collection = client.Database(databaseName).Collection(options.CollectionName)

	return exporter, nil
}

// Export writes a result document to the configured MongoDB collection
// in the database configured by the connection string
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Work on a copy: every exporter is handed the same event.
	row := *event
	if exporter.options.OmitRaw {
		row.Request = ""
		row.Response = ""
	}

	// Add the row to the queue to be processed
	exporter.rows = append(exporter.rows, row)

	// If the batch size is greater than 0 and the number of rows has reached the batch, flush it to the database
	if exporter.options.BatchSize > 0 && len(exporter.rows) >= exporter.options.BatchSize {
		err := exporter.WriteRows()
		if err != nil {
			// The error is already logged, return it to bubble up to the caller
			return err
		}
	}

	return nil
}

// WriteRows writes all rows from the rows list to the MongoDB collection and removes them from the list
func (exporter *Exporter) WriteRows() error {
	// Loop through the rows and write them, removing them as they're entered
	for len(exporter.rows) > 0 {
		data := exporter.rows[0]

		// Write the data to the database
		_, err := exporter.collection.InsertOne(context.TODO(), data)
		if err != nil {
			gologger.Fatal().Msgf("Error inserting record into MongoDB collection: %s", err)
			return err
		}

		// Remove the item from the list
		exporter.rows = exporter.rows[1:]
	}

	return nil
}

func (exporter *Exporter) Close() error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	// Write all pending rows
	err := exporter.WriteRows()
	if err != nil {
		// The error is already logged, return it to bubble up to the caller
		return err
	}

	// Close the database connection
	err = exporter.connection.Disconnect(context.TODO())
	if err != nil {
		gologger.Error().Msgf("Error disconnecting from MongoDB: %s", err)
		return err
	}

	return nil
}

package pdf

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	fpdf "github.com/go-pdf/fpdf"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
)

const (
	defaultFile = "nuclei-report.pdf"
	maxRawLen   = 4096
)

// Options contains the configuration options for PDF exporter client.
type Options struct {
	// File is the file to export found results to in PDF format.
	File string `yaml:"file"`
	// OmitRaw omits request/response from the report.
	OmitRaw bool `yaml:"omit-raw"`
}

// Exporter is an exporter for nuclei PDF output format.
type Exporter struct {
	options *Options
	mu      sync.Mutex
	results []output.ResultEvent
}

// New creates a new PDF exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	opts := &Options{}
	if options != nil {
		*opts = *options
	}
	if opts.File == "" {
		opts.File = defaultFile
	}
	return &Exporter{
		options: opts,
		results: make([]output.ResultEvent, 0),
	}, nil
}

// Export appends a result event to the report buffer.
func (e *Exporter) Export(event *output.ResultEvent) error {
	if event == nil {
		return nil
	}
	e.mu.Lock()
	defer e.mu.Unlock()
	row := *event
	if e.options.OmitRaw {
		row.Request = ""
		row.Response = ""
	} else {
		if len(row.Request) > maxRawLen {
			row.Request = row.Request[:maxRawLen] + "\n[truncated]"
		}
		if len(row.Response) > maxRawLen {
			row.Response = row.Response[:maxRawLen] + "\n[truncated]"
		}
	}
	e.results = append(e.results, row)
	return nil
}

// Close generates the PDF report and writes it to disk.
// Returns nil without creating a file when there are no results.
func (e *Exporter) Close() error {
	e.mu.Lock()
	snapshot := make([]output.ResultEvent, len(e.results))
	copy(snapshot, e.results)
	opts := *e.options
	e.mu.Unlock()

	if len(snapshot) == 0 {
		return nil
	}
	if dir := filepath.Dir(opts.File); dir != "." && dir != "" {
		if err := os.MkdirAll(dir, 0755); err != nil {
			return errors.Wrap(err, "could not create directory for PDF report")
		}
	}
	return generate(&opts, snapshot)
}

func generate(opts *Options, results []output.ResultEvent) error {
	doc := fpdf.New("P", "mm", "A4", "")
	doc.SetMargins(12, 15, 12)
	doc.SetAutoPageBreak(true, 18)
	renderHeader(doc)
	renderSummary(doc, results)
	renderFindings(doc, results)
	if err := doc.OutputFileAndClose(opts.File); err != nil {
		return errors.Wrap(err, "could not write PDF report")
	}
	return nil
}

func renderHeader(doc *fpdf.Fpdf) {
	doc.AddPage()
	doc.SetFont("Helvetica", "B", 18)
	doc.SetTextColor(30, 30, 30)
	doc.CellFormat(0, 10, "Nuclei Vulnerability Scan Report", "", 1, "C", false, 0, "")
	doc.SetFont("Helvetica", "", 9)
	doc.SetTextColor(100, 100, 100)
	doc.CellFormat(0, 5, "Generated: "+time.Now().UTC().Format("2006-01-02 15:04:05 UTC"), "", 1, "C", false, 0, "")
	doc.CellFormat(0, 5, "Engine: Nuclei "+config.Version, "", 1, "C", false, 0, "")
	doc.Ln(6)
}

type rgb struct{ r, g, b int }

var sevColors = map[string]rgb{
	"critical": {128, 0, 128},
	"high":     {200, 0, 0},
	"medium":   {200, 100, 0},
	"low":      {170, 140, 0},
	"info":     {0, 100, 180},
	"unknown":  {100, 100, 100},
}

var sevOrder = []string{"critical", "high", "medium", "low", "info", "unknown"}

func colorFor(sev string) (int, int, int) {
	if c, ok := sevColors[strings.ToLower(sev)]; ok {
		return c.r, c.g, c.b
	}
	return 100, 100, 100
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + strings.ToLower(s[1:])
}

func renderSummary(doc *fpdf.Fpdf, results []output.ResultEvent) {
	counts := make(map[string]int, len(sevOrder))
	for _, r := range results {
		sev := strings.ToLower(r.Info.SeverityHolder.Severity.String())
		if _, ok := sevColors[sev]; ok {
			counts[sev]++
		} else {
			counts["unknown"]++
		}
	}
	doc.SetFont("Helvetica", "B", 11)
	doc.SetTextColor(30, 30, 30)
	doc.CellFormat(0, 7, fmt.Sprintf("Summary - %d finding(s)", len(results)), "", 1, "", false, 0, "")
	doc.Ln(1)
	colW := 28.0
	doc.SetFont("Helvetica", "B", 9)
	for _, sev := range sevOrder {
		r, g, b := colorFor(sev)
		doc.SetFillColor(r, g, b)
		doc.SetTextColor(255, 255, 255)
		doc.CellFormat(colW, 6, capitalize(sev), "1", 0, "C", true, 0, "")
	}
	doc.Ln(-1)
	doc.SetFont("Helvetica", "", 9)
	doc.SetFillColor(245, 245, 245)
	doc.SetTextColor(30, 30, 30)
	for _, sev := range sevOrder {
		doc.CellFormat(colW, 6, fmt.Sprintf("%d", counts[sev]), "1", 0, "C", true, 0, "")
	}
	doc.Ln(10)
}

func renderFindings(doc *fpdf.Fpdf, results []output.ResultEvent) {
	doc.SetFont("Helvetica", "B", 11)
	doc.SetTextColor(30, 30, 30)
	doc.CellFormat(0, 7, "Findings", "", 1, "", false, 0, "")
	doc.Ln(1)
	for i, r := range results {
		sev := strings.ToLower(r.Info.SeverityHolder.Severity.String())
		cr, cg, cb := colorFor(sev)
		doc.SetFont("Helvetica", "B", 10)
		doc.SetFillColor(cr, cg, cb)
		doc.SetTextColor(255, 255, 255)
		doc.CellFormat(0, 7, safeStr(fmt.Sprintf("[%s] %s", strings.ToUpper(sev), r.Info.Name)), "0", 1, "", true, 0, "")
		doc.SetFont("Helvetica", "", 9)
		doc.SetTextColor(30, 30, 30)
		doc.CellFormat(30, 5, "Host:", "0", 0, "", false, 0, "")
		doc.CellFormat(0, 5, safeStr(r.Host), "0", 1, "", false, 0, "")
		doc.CellFormat(30, 5, "Template:", "0", 0, "", false, 0, "")
		doc.CellFormat(0, 5, safeStr(r.TemplateID), "0", 1, "", false, 0, "")
		if r.Info.Description != "" {
			doc.SetFont("Helvetica", "I", 8)
			doc.SetTextColor(60, 60, 60)
			doc.MultiCell(0, 4, safeStr(r.Info.Description), "", "", false)
		}
		if r.Request != "" {
			renderCodeBlock(doc, "Request", r.Request)
		}
		if r.Response != "" {
			renderCodeBlock(doc, "Response", r.Response)
		}
		if i < len(results)-1 {
			doc.Ln(3)
			doc.SetDrawColor(200, 200, 200)
			doc.Line(12, doc.GetY(), 198, doc.GetY())
			doc.Ln(3)
		}
	}
}

func renderCodeBlock(doc *fpdf.Fpdf, label, content string) {
	doc.SetFont("Helvetica", "B", 8)
	doc.SetTextColor(60, 60, 60)
	doc.CellFormat(0, 5, label+":", "0", 1, "", false, 0, "")
	doc.SetFont("Courier", "", 7)
	doc.SetFillColor(240, 240, 240)
	doc.SetTextColor(40, 40, 40)
	doc.MultiCell(0, 4, safeStr(content), "1", "", true)
}

// safeStr replaces characters outside ISO-8859-1 with '?' for fpdf compatibility.
func safeStr(s string) string {
	out := make([]byte, 0, len(s))
	for _, r := range s {
		if r > 255 {
			out = append(out, '?')
		} else {
			out = append(out, byte(r))
		}
	}
	return string(out)
}

package sarif

import (
	"fmt"
	"os"
	"path"
	"strings"
	"sync"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/sarif"
)

const (
	maxDetailValueLength   = 400
	maxExtractedValues     = 5
	maxRuleReferences      = 8
	fallbackTemplateRuleID = "nuclei-template"
)

// maxInfoValueLength keeps filled info whole for every template in
// nuclei-templates (the longest field is under 3000 characters) while a
// placeholder such as {{body}} cannot pour a whole response into the report.
const maxInfoValueLength = 4096

// Exporter is an exporter for nuclei sarif output format.
type Exporter struct {
	sarif   *sarif.Report
	mutex   *sync.Mutex
	rulemap map[string]int // contains rule-id && ruleIndex
	rules   []sarif.ReportingDescriptor
	options *Options
}

// Options contains the configuration options for sarif exporter client
type Options struct {
	// File is the file to export found sarif result to
	File string `yaml:"file"`
}

// New creates a new sarif exporter integration client based on options.
func New(options *Options) (*Exporter, error) {
	report := sarif.NewReport()
	exporter := &Exporter{
		sarif:   report,
		mutex:   &sync.Mutex{},
		rules:   []sarif.ReportingDescriptor{},
		rulemap: map[string]int{},
		options: options,
	}
	return exporter, nil
}

// addToolDetails adds details of static analysis tool (i.e nuclei)
func (exporter *Exporter) addToolDetails() {
	driver := sarif.ToolComponent{
		Name:         "Nuclei",
		Organization: "ProjectDiscovery",
		Product:      "Nuclei",
		ShortDescription: &sarif.MultiformatMessageString{
			Text: "Fast and Customizable Vulnerability Scanner",
		},
		FullDescription: &sarif.MultiformatMessageString{
			Text: "Fast and customizable vulnerability scanner based on simple YAML based DSL",
		},
		FullName:        "Nuclei " + config.Version,
		SemanticVersion: config.Version,
		DownloadUri:     "https://github.com/projectdiscovery/nuclei/releases",
		InformationUri:  "https://github.com/projectdiscovery/nuclei/releases",
		Rules:           exporter.rules,
	}
	exporter.sarif.RegisterTool(driver)

	reportLocation := sarif.ArtifactLocation{
		Uri: "file:///" + exporter.options.File,
		Description: &sarif.Message{
			Text: "Nuclei Sarif Report",
		},
	}

	invocation := sarif.Invocation{
		CommandLine:         os.Args[0],
		Arguments:           os.Args[1:],
		ResponseFiles:       []sarif.ArtifactLocation{reportLocation},
		ExecutionSuccessful: true,
	}
	exporter.sarif.RegisterToolInvocation(invocation)
}

// getSeverity in terms of sarif
func (exporter *Exporter) getSeverity(severity string) (sarif.Level, string) {
	switch severity {
	case "critical":
		return sarif.Error, "9.4"
	case "high":
		return sarif.Error, "8"
	case "medium":
		return sarif.Note, "5"
	case "low":
		return sarif.Note, "2"
	case "info":
		return sarif.None, "1"
	}

	return sarif.None, "9.5"
}

// Export exports a passed result event to sarif structure
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	severity := event.Info.SeverityHolder.Severity.String()
	ruleID := normalizeValue(event.TemplateID)
	if ruleID == "" {
		ruleID = fallbackTemplateRuleID
	}
	ruleName := normalizeValue(event.Info.Name)
	if ruleName == "" {
		ruleName = ruleID
	}
	resultTarget := getResultTarget(event)
	resultHeader := fmt.Sprintf("%s (%s) found on %s", ruleName, ruleID, event.URL)
	resultLevel, vulnRating := exporter.getSeverity(severity)
	if classification := event.Info.Classification; classification != nil && classification.CVSSScore > 0 {
		vulnRating = fmt.Sprintf("%.1f", classification.CVSSScore)
	}

	// Extra metadata if generated sarif is uploaded to GitHub security page
	ghMeta := map[string]interface{}{
		"tags":              buildRuleTags(event),
		"security-severity": vulnRating,
	}

	// rule contain details of template
	templateEvent := asWritten(event)
	rule := sarif.ReportingDescriptor{
		Id:      ruleID,
		Name:    ruleName,
		HelpUri: normalizeValue(event.TemplateURL),
		ShortDescription: &sarif.MultiformatMessageString{
			Text: ruleName,
		},
		FullDescription: &sarif.MultiformatMessageString{
			Text: buildRuleDescription(templateEvent, ruleName),
		},
		Help: &sarif.MultiformatMessageString{
			Text:     buildRuleHelpText(templateEvent),
			Markdown: buildRuleHelpMarkdown(templateEvent, ruleName),
		},
		Properties: ghMeta,
	}

	// Add rule once and keep stable rule indices.
	ruleIndex, found := exporter.rulemap[ruleID]
	if !found {
		ruleIndex = len(exporter.rules)
		exporter.rulemap[ruleID] = ruleIndex
		exporter.rules = append(exporter.rules, rule)
	}

	location := buildLocation(event, resultTarget)

	// vulnerability report/result
	result := &sarif.Result{
		RuleId:    ruleID,
		RuleIndex: ruleIndex,
		Level:     resultLevel,
		Kind:      sarif.Open,
		Message:   buildResultMessage(event, resultHeader, ruleID),
		Locations: []sarif.Location{location},
		Rule: sarif.ReportingDescriptorReference{
			Id: ruleID,
		},
		Properties: buildResultProperties(event, resultTarget),
	}

	exporter.sarif.RegisterResult(*result)

	return nil

}

// Close Writes data and closes the exporter after operation
func (exporter *Exporter) Close() error {
	exporter.mutex.Lock()
	defer exporter.mutex.Unlock()

	if len(exporter.rules) == 0 {
		// no output if there are no results
		return nil
	}
	// links results and rules/templates
	exporter.addToolDetails()

	bin, err := exporter.sarif.ExportWithOptions(
		sarif.WithNormalization(true),
		sarif.WithEmptyObjectPruning(true),
	)
	if err != nil {
		return errors.Wrap(err, "failed to generate sarif report")
	}
	if err := os.WriteFile(exporter.options.File, bin, 0644); err != nil {
		return errors.Wrap(err, "failed to create sarif file")
	}

	return nil
}

// asWritten returns the event with its info as the template wrote it. Every
// finding of a template shares one rule, so the rule describes the template;
// text filled for one finding goes on that finding's result message instead.
func asWritten(event *output.ResultEvent) *output.ResultEvent {
	if event.TemplateInfo == nil {
		return event
	}
	written := *event
	written.Info = *event.TemplateInfo
	return &written
}

func buildRuleDescription(event *output.ResultEvent, ruleName string) string {
	description := normalizeValue(event.Info.Description)
	if description == "" {
		description = ruleName
	}
	if templateURL := normalizeValue(event.TemplateURL); templateURL != "" {
		description += "\nMore details at\n" + templateURL
	}
	return description
}

func buildRuleHelpText(event *output.ResultEvent) string {
	sections := []string{}

	if description := normalizeValue(event.Info.Description); description != "" {
		sections = append(sections, description)
	}
	if impact := normalizeValue(event.Info.Impact); impact != "" {
		sections = append(sections, "Impact: "+impact)
	}
	if remediation := normalizeValue(event.Info.Remediation); remediation != "" {
		sections = append(sections, "Remediation: "+remediation)
	}
	if templatePath := normalizeValue(firstNonEmpty(event.Template, event.TemplatePath)); templatePath != "" {
		sections = append(sections, "Nuclei Template: "+templatePath)
	}
	if refs := getReferences(event); len(refs) > 0 {
		sections = append(sections, "References: "+strings.Join(refs, ", "))
	}
	if templateURL := normalizeValue(event.TemplateURL); templateURL != "" {
		sections = append(sections, "More details: "+templateURL)
	}

	if len(sections) == 0 {
		return "No additional template metadata was provided by the scanner."
	}

	return strings.Join(sections, "\n")
}

func buildRuleHelpMarkdown(event *output.ResultEvent, ruleName string) string {
	lines := []string{fmt.Sprintf("### %s", ruleName), ""}

	if description := normalizeValue(event.Info.Description); description != "" {
		lines = append(lines, description, "")
	}
	if impact := normalizeValue(event.Info.Impact); impact != "" {
		lines = append(lines, fmt.Sprintf("- **Impact:** %s", impact))
	}
	if remediation := normalizeValue(event.Info.Remediation); remediation != "" {
		lines = append(lines, fmt.Sprintf("- **Remediation:** %s", remediation))
	}
	if templatePath := normalizeValue(firstNonEmpty(event.Template, event.TemplatePath)); templatePath != "" {
		lines = append(lines, fmt.Sprintf("- **Nuclei Template:** %s", templatePath))
	}

	if refs := getReferences(event); len(refs) > 0 {
		lines = append(lines, "", "**References**")
		for _, ref := range refs {
			lines = append(lines, "- "+ref)
		}
	}

	if templateURL := normalizeValue(event.TemplateURL); templateURL != "" {
		lines = append(lines, "", "More details: "+templateURL)
	}

	return strings.TrimSpace(strings.Join(lines, "\n"))
}

func buildResultMessage(event *output.ResultEvent, resultHeader, ruleID string) *sarif.Message {
	detailLines := []string{}
	// Filled info is all the report has of this finding's text, so it gets a
	// longer limit than the other details.
	for _, field := range event.Info.FilledFields(event.TemplateInfo) {
		if value := normalizeAndTruncate(*field.Value, maxInfoValueLength); value != "" {
			detailLines = append(detailLines, field.Label+": "+value)
		}
	}
	target := getResultTarget(event)
	addDetail(&detailLines, "Target", target)
	if matched := normalizeAndTruncate(event.Matched, maxDetailValueLength); matched != "" && matched != target {
		addDetail(&detailLines, "Matched At", matched)
	}
	if baseURL := normalizeAndTruncate(event.URL, maxDetailValueLength); baseURL != "" {
		addDetail(&detailLines, "Base URL", baseURL)
	}
	if host := normalizeAndTruncate(event.Host, maxDetailValueLength); host != "" && host != target {
		addDetail(&detailLines, "Host", host)
	}
	addDetail(&detailLines, "IP", event.IP)
	addDetail(&detailLines, "Protocol", event.Type)
	addDetail(&detailLines, "Matcher", event.MatcherName)
	addDetail(&detailLines, "Extractor", event.ExtractorName)
	addDetail(&detailLines, "Nuclei Template", ruleID)
	if templatePath := normalizeAndTruncate(firstNonEmpty(event.Template, event.TemplatePath), maxDetailValueLength); templatePath != "" {
		addDetail(&detailLines, "Nuclei Template Path", templatePath)
	}
	if extracted := formatExtractedResults(event.ExtractedResults); extracted != "" {
		addDetail(&detailLines, "Extracted Results", extracted)
	}

	reproduction := normalizeAndTruncate(event.CURLCommand, maxDetailValueLength*2)

	text := resultHeader
	if len(detailLines) > 0 {
		text += "\n" + strings.Join(detailLines, "\n")
	}
	if reproduction != "" {
		text += "\nReproduce:\n"
		text += "```bash\n" + reproduction + "\n```"
	}

	markdownLines := []string{resultHeader}
	if len(detailLines) > 0 {
		markdownLines = append(markdownLines, "", "\n**Triage Details**:")
		for _, detail := range detailLines {
			parts := strings.SplitN(detail, ": ", 2)
			if len(parts) == 2 {
				markdownLines = append(markdownLines, fmt.Sprintf("- **%s:** %s", parts[0], parts[1]))
				continue
			}
			markdownLines = append(markdownLines, "- "+detail)
		}
	}
	if reproduction != "" {
		markdownLines = append(markdownLines, "", "\n**Reproduce**:", "```bash", reproduction, "```")
	}

	return &sarif.Message{
		Text:     text,
		Markdown: strings.Join(markdownLines, "\n"),
	}
}

func buildResultProperties(event *output.ResultEvent, target string) map[string]interface{} {
	properties := map[string]interface{}{}

	if normalizedTarget := normalizeAndTruncate(target, maxDetailValueLength); normalizedTarget != "" {
		properties["target"] = normalizedTarget
	}
	if matched := normalizeAndTruncate(event.Matched, maxDetailValueLength); matched != "" {
		properties["matched-at"] = matched
	}
	if matcher := normalizeAndTruncate(event.MatcherName, maxDetailValueLength); matcher != "" {
		properties["matcher"] = matcher
	}
	if extractor := normalizeAndTruncate(event.ExtractorName, maxDetailValueLength); extractor != "" {
		properties["extractor"] = extractor
	}
	if len(event.ExtractedResults) > 0 {
		trimmed := make([]string, 0, maxExtractedValues)
		for i, value := range event.ExtractedResults {
			if i >= maxExtractedValues {
				break
			}
			if normalized := normalizeAndTruncate(value, maxDetailValueLength); normalized != "" {
				trimmed = append(trimmed, normalized)
			}
		}
		if len(trimmed) > 0 {
			properties["extracted-results"] = trimmed
		}
	}
	if templatePath := normalizeAndTruncate(firstNonEmpty(event.Template, event.TemplatePath), maxDetailValueLength); templatePath != "" {
		properties["template-path"] = templatePath
	}

	if len(properties) == 0 {
		return nil
	}

	return properties
}

func buildLocation(event *output.ResultEvent, resultTarget string) sarif.Location {
	location := sarif.Location{
		Message: &sarif.Message{
			Text: resultTarget,
		},
		PhysicalLocation: sarif.PhysicalLocation{
			ArtifactLocation: sarif.ArtifactLocation{
				Uri: buildArtifactURI(event),
				Description: &sarif.Message{
					Text: resultTarget,
				},
			},
		},
	}

	if line := firstPositiveLine(event.Lines); line > 0 {
		location.PhysicalLocation.Region = &sarif.Region{StartLine: line}
	}

	return location
}

func buildArtifactURI(event *output.ResultEvent) string {
	if template := normalizePath(firstNonEmpty(event.Template, event.TemplatePath)); template != "" {
		if idx := strings.Index(template, "/nuclei-templates/"); idx >= 0 {
			return strings.TrimLeft(template[idx+len("/nuclei-templates/"):], "/")
		}
		return strings.TrimLeft(template, "/")
	}

	if targetPath := normalizePath(event.Path); targetPath != "" && targetPath != "/" && targetPath != "." {
		return strings.TrimLeft(targetPath, "/")
	}

	if templateID := normalizeValue(event.TemplateID); templateID != "" {
		return path.Join("nuclei-results", templateID+".txt")
	}

	return "nuclei-results/result.txt"
}

func buildRuleTags(event *output.ResultEvent) []string {
	tags := []string{"security"}
	for _, tag := range event.Info.Tags.ToSlice() {
		normalizedTag := normalizeValue(tag)
		if normalizedTag == "" {
			continue
		}
		tags = appendIfMissing(tags, normalizedTag)
	}

	if classification := event.Info.Classification; classification != nil {
		for _, cwe := range classification.CWEID.ToSlice() {
			if cweTag := buildCWETag(cwe); cweTag != "" {
				tags = appendIfMissing(tags, cweTag)
			}
		}
	}

	return tags
}

func getReferences(event *output.ResultEvent) []string {
	if event.Info.Reference == nil {
		return nil
	}
	references := event.Info.Reference.ToSlice()
	if len(references) == 0 {
		return nil
	}

	output := make([]string, 0, min(len(references), maxRuleReferences))
	for i, reference := range references {
		if i >= maxRuleReferences {
			break
		}
		if normalizedRef := normalizeAndTruncate(reference, maxDetailValueLength); normalizedRef != "" {
			output = append(output, normalizedRef)
		}
	}

	return output
}

func getResultTarget(event *output.ResultEvent) string {
	for _, value := range []string{event.Matched, event.URL, event.Host, event.Path} {
		if normalized := normalizeAndTruncate(value, maxDetailValueLength); normalized != "" {
			return normalized
		}
	}
	return "unknown target"
}

func formatExtractedResults(values []string) string {
	if len(values) == 0 {
		return ""
	}

	trimmed := make([]string, 0, maxExtractedValues)
	for i, value := range values {
		if i >= maxExtractedValues {
			break
		}
		if normalized := normalizeAndTruncate(value, maxDetailValueLength); normalized != "" {
			trimmed = append(trimmed, normalized)
		}
	}

	if len(trimmed) == 0 {
		return ""
	}

	if len(values) > len(trimmed) {
		trimmed = append(trimmed, fmt.Sprintf("... and %d more", len(values)-len(trimmed)))
	}

	return strings.Join(trimmed, ", ")
}

func firstPositiveLine(lines []int) int {
	for _, line := range lines {
		if line > 0 {
			return line
		}
	}
	return 0
}

func addDetail(lines *[]string, label, value string) {
	normalizedValue := normalizeAndTruncate(value, maxDetailValueLength)
	if normalizedValue == "" {
		return
	}
	*lines = append(*lines, fmt.Sprintf("%s: %s", label, normalizedValue))
}

func normalizeAndTruncate(value string, limit int) string {
	normalized := normalizeValue(value)
	if normalized == "" {
		return ""
	}
	if limit > 0 && len(normalized) > limit {
		return normalized[:limit-3] + "..."
	}
	return normalized
}

func normalizeValue(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	return strings.Join(strings.Fields(trimmed), " ")
}

func normalizePath(value string) string {
	normalized := strings.TrimSpace(strings.ReplaceAll(value, "\\", "/"))
	if normalized == "" {
		return ""
	}
	return path.Clean(normalized)
}

func appendIfMissing(values []string, candidate string) []string {
	for _, existing := range values {
		if existing == candidate {
			return values
		}
	}
	return append(values, candidate)
}

func buildCWETag(value string) string {
	normalized := strings.ToLower(strings.TrimSpace(value))
	if normalized == "" {
		return ""
	}
	normalized = strings.TrimPrefix(normalized, "cwe-")
	digitsOnly := strings.Builder{}
	for _, char := range normalized {
		if char >= '0' && char <= '9' {
			digitsOnly.WriteRune(char)
		}
	}
	if digitsOnly.Len() == 0 {
		return ""
	}
	return "external/cwe/cwe-" + digitsOnly.String()
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

package splunk

import (
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/stretchr/testify/require"
)

type bodyCloseTransport func(*http.Request) (*http.Response, error)

func (f bodyCloseTransport) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

type trackedBody struct {
	io.Reader
	closed bool
}

func (b *trackedBody) Close() error { b.closed = true; return nil }

type errorReader struct{}

func (errorReader) Read([]byte) (int, error) { return 0, errors.New("read interrupted") }

func TestExportClosesResponseBody(t *testing.T) {
	for _, tc := range []struct {
		name      string
		status    int
		reader    io.Reader
		wantError bool
	}{
		{"success", http.StatusOK, strings.NewReader("{}"), false},
		{"server error", http.StatusInternalServerError, strings.NewReader("unavailable"), true},
		{"read error", http.StatusOK, errorReader{}, true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			body := &trackedBody{Reader: tc.reader}
			e := &Exporter{url: "http://report.invalid/services/collector/event", splunk: &http.Client{Transport: bodyCloseTransport(func(*http.Request) (*http.Response, error) {
				return &http.Response{StatusCode: tc.status, Body: body, Header: make(http.Header)}, nil
			})}}
			err := e.Export(&output.ResultEvent{})
			if tc.wantError {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
			require.True(t, body.closed, "exporter must close the response body")
		})
	}
}

package splunk

import (
	"bytes"
	"crypto/tls"
	"fmt"
	"io"
	"net"
	"net/http"
	"time"

	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/useragent"
)

// Options contains necessary options required for splunk communication
type Options struct {
	// Host is the hostname and port of the splunk instance
	Host string `yaml:"host" validate:"required"`
	Port int    `yaml:"port" validate:"gte=0,lte=65535"`
	// SSL (optional) enables ssl for splunk connection
	SSL bool `yaml:"ssl"`
	// SSLVerification (optional) disables SSL verification for splunk
	SSLVerification bool `yaml:"ssl-verification"`
	// Token for HEC instance
	Token     string `yaml:"token"  validate:"required"`
	IndexName string `yaml:"index-name"  validate:"required"`

	HttpClient  *retryablehttp.Client `yaml:"-"`
	ExecutionId string                `yaml:"-"`
}

type data struct {
	Event *output.ResultEvent `json:"event"`
}

// Exporter type for splunk
type Exporter struct {
	url            string
	authentication string
	splunk         *http.Client
}

// New creates and returns a new exporter for splunk
func New(option *Options) (*Exporter, error) {
	var ei *Exporter

	dialers := protocolstate.GetDialersWithId(option.ExecutionId)
	if dialers == nil {
		return nil, fmt.Errorf("dialers not initialized for %s", option.ExecutionId)
	}

	var client *http.Client
	if option.HttpClient != nil {
		client = option.HttpClient.HTTPClient
	} else {
		client = &http.Client{
			Timeout: 5 * time.Second,
			Transport: &http.Transport{
				MaxIdleConns:        10,
				MaxIdleConnsPerHost: 10,
				// No DialTLSContext: fastdialer DialTLS ignores TLSClientConfig and
				// skips verification; net/http does the handshake with TLSClientConfig.
				DialContext:     dialers.Fastdialer.Dial,
				TLSClientConfig: &tls.Config{InsecureSkipVerify: option.SSLVerification},
			},
		}
	}

	// preparing url for splunk
	scheme := "http://"
	if option.SSL {
		scheme = "https://"
	}

	// Authentication header for HEC
	authentication := "Splunk " + option.Token

	// add HEC endpoint, index, source, sourcetype
	addr := option.Host
	if option.Port > 0 {
		addr = net.JoinHostPort(addr, fmt.Sprint(option.Port))
	}
	base_url := fmt.Sprintf("%s%s", scheme, addr)
	sourcetype := "nuclei:splunk-hec:exporter:json"
	url := fmt.Sprintf("%s/services/collector/event?index=%s&sourcetype=%s&source=%s", base_url, option.IndexName, sourcetype, base_url)

	ei = &Exporter{
		url:            url,
		authentication: authentication,
		splunk:         client,
	}
	return ei, nil
}

// Export exports a passed result event to Splunk
func (exporter *Exporter) Export(event *output.ResultEvent) error {
	// creating a request
	req, err := http.NewRequest(http.MethodPost, exporter.url, nil)
	if err != nil {
		return errors.Wrap(err, "could not make request")
	}
	if len(exporter.authentication) > 0 {
		req.Header.Add("Authorization", exporter.authentication)
	}
	userAgent := useragent.PickRandom()
	req.Header.Set("User-Agent", userAgent.Raw)
	req.Header.Add("Content-Type", "application/json")

	d := data{Event: event}
	b, err := json.Marshal(&d)
	if err != nil {
		return err
	}
	req.Body = io.NopCloser(bytes.NewReader(b))

	res, err := exporter.splunk.Do(req)
	if err != nil {
		return err
	}
	defer func() {
		_ = res.Body.Close()
	}()

	b, err = io.ReadAll(res.Body)
	if err != nil {
		return errors.New(err.Error() + "error thrown by splunk " + string(b))
	}
	if res.StatusCode >= http.StatusMultipleChoices {
		return errors.New("splunk responded with an error: " + string(b))
	}
	return nil
}

// Close closes the exporter after operation
func (exporter *Exporter) Close() error {
	return nil
}

package format

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/exporters/markdown/util"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
	unitutils "github.com/projectdiscovery/utils/unit"
)

// Summary returns a formatted built one line summary of the event
func Summary(event *output.ResultEvent) string {
	return fmt.Sprintf("%s (%s) found on %s", types.ToString(event.Info.Name), GetMatchedTemplateName(event), event.Host)
}

// GetMatchedTemplateName returns the matched template name from a result event
// together with the found matcher and extractor name, if present
func GetMatchedTemplateName(event *output.ResultEvent) string {
	matchedTemplateName := event.TemplateID
	if event.MatcherName != "" {
		matchedTemplateName += ":" + event.MatcherName
	}

	if event.ExtractorName != "" {
		matchedTemplateName += ":" + event.ExtractorName
	}

	return matchedTemplateName
}

type reportMetadataEditorHook func(event *output.ResultEvent, formatter ResultFormatter) string

var (
	// ReportGenerationMetadataHooks are the hooks for adding metadata to the report
	ReportGenerationMetadataHooks []reportMetadataEditorHook
)

func CreateReportDescription(event *output.ResultEvent, formatter ResultFormatter, omitRaw bool) string {
	template := GetMatchedTemplateName(event)
	builder := &bytes.Buffer{}
	fmt.Fprintf(builder, "%s: %s matched at %s\n\n", formatter.MakeBold("Details"), formatter.MakeBold(template), event.Host)

	attributes := utils.NewEmptyInsertionOrderedStringMap(3)
	attributes.Set("Protocol", strings.ToUpper(event.Type))
	attributes.Set("Full URL", event.Matched)
	attributes.Set("Timestamp", event.Timestamp.Format("Mon Jan 2 15:04:05 -0700 MST 2006"))
	attributes.ForEach(func(key string, data interface{}) {
		fmt.Fprintf(builder, "%s: %s\n\n", formatter.MakeBold(key), types.ToString(data))
	})

	if len(ReportGenerationMetadataHooks) > 0 {
		for _, hook := range ReportGenerationMetadataHooks {
			builder.WriteString(hook(event, formatter))
		}
	}

	builder.WriteString(formatter.MakeBold("Template Information"))
	builder.WriteString("\n\n")
	builder.WriteString(CreateTemplateInfoTable(&event.Info, formatter))

	if !omitRaw {
		if event.Request != "" {
			builder.WriteString(formatter.CreateCodeBlock("Request", types.ToHexOrString(event.Request), "http"))
		}
		if event.Response != "" {
			var responseString string
			// If the response is larger than 5 kb, truncate it before writing.
			maxKbSize := 5 * unitutils.Kilo
			if len(event.Response) > maxKbSize {
				responseString = event.Response[:maxKbSize]
				responseString += ".... Truncated ...."
			} else {
				responseString = event.Response
			}
			builder.WriteString(formatter.CreateCodeBlock("Response", responseString, "http"))
		}
	}

	if len(event.ExtractedResults) > 0 || len(event.Metadata) > 0 || event.AnalyzerDetails != "" {
		builder.WriteString("\n")
		builder.WriteString(formatter.MakeBold("Extra Information"))
		builder.WriteString("\n\n")

		if len(event.ExtractedResults) > 0 {
			builder.WriteString(formatter.MakeBold("Extracted results:"))
			builder.WriteString("\n\n")

			for _, v := range event.ExtractedResults {
				builder.WriteString("- ")
				builder.WriteString(v)
				builder.WriteString("\n")
			}
			builder.WriteString("\n")
		}
		if event.AnalyzerDetails != "" {
			builder.WriteString(formatter.MakeBold("Analyzer Details:"))
			builder.WriteString("\n\n")

			builder.WriteString(event.AnalyzerDetails)
			builder.WriteString("\n")
		}
		if len(event.Metadata) > 0 {
			builder.WriteString(formatter.MakeBold("Metadata:"))
			builder.WriteString("\n\n")
			for k, v := range event.Metadata {
				builder.WriteString("- ")
				builder.WriteString(k)
				builder.WriteString(": ")
				builder.WriteString(types.ToString(v))
				builder.WriteString("\n")
			}
			builder.WriteString("\n")
		}
	}
	if event.Interaction != nil {
		fmt.Fprintf(builder, "%s\n%s", formatter.MakeBold("Interaction Data"), formatter.CreateHorizontalLine())
		builder.WriteString(event.Interaction.Protocol)
		if event.Interaction.QType != "" {
			_, _ = fmt.Fprintf(builder, " (%s)", event.Interaction.QType)
		}
		fmt.Fprintf(builder, " Interaction from %s at %s", event.Interaction.RemoteAddress, event.Interaction.UniqueID)

		if event.Interaction.RawRequest != "" {
			builder.WriteString(formatter.CreateCodeBlock("Interaction Request", event.Interaction.RawRequest, ""))
		}
		if event.Interaction.RawResponse != "" {
			builder.WriteString(formatter.CreateCodeBlock("Interaction Response", event.Interaction.RawResponse, ""))
		}
	}

	reference := event.Info.Reference
	if reference != nil && !reference.IsEmpty() {
		builder.WriteString("\nReferences: \n")

		referenceSlice := reference.ToSlice()
		for i, item := range referenceSlice {
			builder.WriteString("- ")
			builder.WriteString(item)
			if len(referenceSlice)-1 != i {
				builder.WriteString("\n")
			}
		}
	}
	builder.WriteString("\n")

	if event.CURLCommand != "" {
		builder.WriteString(
			formatter.CreateCodeBlock("CURL command", types.ToHexOrString(event.CURLCommand), "sh"),
		)
	}

	builder.WriteString("\n" + formatter.CreateHorizontalLine() + "\n")
	_, _ = fmt.Fprintf(builder, "Generated by %s", formatter.CreateLink("Nuclei "+config.Version, "https://github.com/projectdiscovery/nuclei"))
	data := builder.String()
	return data
}

func CreateTemplateInfoTable(templateInfo *model.Info, formatter ResultFormatter) string {
	rows := [][]string{
		{"Name", templateInfo.Name},
		{"Authors", templateInfo.Authors.String()},
		{"Tags", templateInfo.Tags.String()},
		{"Severity", templateInfo.SeverityHolder.Severity.String()},
	}

	if !utils.IsBlank(templateInfo.Description) {
		rows = append(rows, []string{"Description", lineBreakToHTML(templateInfo.Description)})
	}

	if !utils.IsBlank(templateInfo.Remediation) {
		rows = append(rows, []string{"Remediation", lineBreakToHTML(templateInfo.Remediation)})
	}

	classification := templateInfo.Classification
	if classification != nil {
		if classification.CVSSMetrics != "" {
			rows = append(rows, []string{"CVSS-Metrics", generateCVSSMetricsFromClassification(classification)})
		}

		rows = append(rows, generateCVECWEIDLinksFromClassification(classification)...)
		rows = append(rows, []string{"CVSS-Score", strconv.FormatFloat(classification.CVSSScore, 'f', 2, 64)})
	}

	for key, value := range templateInfo.Metadata {
		switch value := value.(type) {
		case string:
			if !utils.IsBlank(value) {
				rows = append(rows, []string{key, value})
			}
		}
	}

	table, _ := formatter.CreateTable([]string{"Key", "Value"}, rows)

	return table
}

func generateCVSSMetricsFromClassification(classification *model.Classification) string {
	var cvssLinkPrefix string
	if strings.Contains(classification.CVSSMetrics, "CVSS:3.0") {
		cvssLinkPrefix = "https://www.first.org/cvss/calculator/3.0#"
	} else if strings.Contains(classification.CVSSMetrics, "CVSS:3.1") {
		cvssLinkPrefix = "https://www.first.org/cvss/calculator/3.1#"
	}

	if cvssLinkPrefix == "" {
		return classification.CVSSMetrics
	} else {
		return util.CreateLink(classification.CVSSMetrics, cvssLinkPrefix+classification.CVSSMetrics)
	}
}

func generateCVECWEIDLinksFromClassification(classification *model.Classification) [][]string {
	cwes := classification.CWEID.ToSlice()

	cweIDs := make([]string, 0, len(cwes))
	for _, value := range cwes {
		parts := strings.Split(value, "-")
		if len(parts) != 2 {
			continue
		}
		cweIDs = append(cweIDs, util.CreateLink(strings.ToUpper(value), fmt.Sprintf("https://cwe.mitre.org/data/definitions/%s.html", parts[1])))
	}

	var rows [][]string

	if len(cweIDs) > 0 {
		rows = append(rows, []string{"CWE-ID", strings.Join(cweIDs, ",")})
	}

	cves := classification.CVEID.ToSlice()
	cveIDs := make([]string, 0, len(cves))
	for _, value := range cves {
		cveIDs = append(cveIDs, util.CreateLink(strings.ToUpper(value), fmt.Sprintf("https://cve.mitre.org/cgi-bin/cvename.cgi?name=%s", value)))
	}
	if len(cveIDs) > 0 {
		rows = append(rows, []string{"CVE-ID", strings.Join(cveIDs, ",")})
	}

	return rows
}

func lineBreakToHTML(text string) string {
	return strings.ReplaceAll(text, "\n", "<br>")
}

