	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/stretchr/testify/require"
)

const testIssueTitle = "Test finding (template-id) found on example.com"

type issueRequest struct {
	Page    string
	Limit   string
	State   string
	Keyword string
}

type fakeGitea struct {
	server       *httptest.Server
	requests     []issueRequest
	comments     []int64
	created      int
	issueHandler func(http.ResponseWriter, *http.Request, issueRequest)
}

// newFakeGitea starts a local Gitea API stub and returns its tracker integration.
func newFakeGitea(t *testing.T, issueHandler func(http.ResponseWriter, *http.Request, issueRequest)) (*Integration, *fakeGitea) {
	t.Helper()

	fake := &fakeGitea{issueHandler: issueHandler}
	fake.server = httptest.NewServer(http.HandlerFunc(fake.serveHTTP))
	t.Cleanup(fake.server.Close)

	integration, err := New(&Options{
		BaseURL:             fake.server.URL,
		Token:               "test-token",
		ProjectOwner:        "owner",
		ProjectName:         "repo",
		DuplicateIssueCheck: true,
	})
	require.NoError(t, err)
	return integration, fake
}

// serveHTTP records tracker requests and serves the configured fake API responses.
func (f *fakeGitea) serveHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	switch {
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/version"):
		_, _ = w.Write([]byte(`{"version":"1.21.0"}`))
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/labels"):
		_, _ = w.Write([]byte("[]"))
	case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/issues"):
		query := r.URL.Query()
		request := issueRequest{
			Page:    query.Get("page"),
			Limit:   query.Get("limit"),
			State:   query.Get("state"),
			Keyword: query.Get("q"),
		}
		f.requests = append(f.requests, request)
		f.issueHandler(w, r, request)
	case r.Method == http.MethodPost && strings.Contains(r.URL.Path, "/comments"):
		parts := strings.Split(strings.Trim(r.URL.Path, "/"), "/")
		issueNumber, _ := strconv.ParseInt(parts[len(parts)-2], 10, 64)
		f.comments = append(f.comments, issueNumber)
		_, _ = w.Write([]byte(`{"id":1}`))
	case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/issues"):
		f.created++
		_, _ = w.Write([]byte(`{"number":99,"title":"created","url":"https://gitea.test/issues/99"}`))
	default:
		http.NotFound(w, r)
	}
}

// writeIssuePage writes issue objects as a JSON API response.
func writeIssuePage(w http.ResponseWriter, issues ...map[string]any) {
	_ = json.NewEncoder(w).Encode(issues)
}

// TestCreateIssueFollowsLinkAfterCappedPageAndComments verifies duplicate detection continues after a capped page.
func TestCreateIssueFollowsLinkAfterCappedPageAndComments(t *testing.T) {
	var server *httptest.Server
	integration, fake := newFakeGitea(t, func(w http.ResponseWriter, r *http.Request, request issueRequest) {
		if request.Page == "1" {
			// Gitea may return only 50 items despite a requested limit of 100.
			w.Header().Set("Link", fmt.Sprintf("<%s%s?limit=100&page=2&state=all>; rel=\"next\"", server.URL, r.URL.Path))
			issues := make([]map[string]any, 50)
			for index := range issues {
				issues[index] = map[string]any{"number": index + 1, "title": "unrelated issue"}
			}
			writeIssuePage(w, issues...)
			return
		}
		writeIssuePage(w, map[string]any{"number": 42, "title": testIssueTitle, "url": "https://gitea.test/issues/42"})
	})
	server = fake.server

	response, err := integration.CreateIssue(testGiteaEvent())
	require.NoError(t, err)
	require.Equal(t, "42", response.IssueID)
	require.Equal(t, "https://gitea.test/issues/42", response.IssueURL)
	require.Equal(t, []int64{42}, fake.comments)
	require.Zero(t, fake.created)
	require.Equal(t, []string{"1", "2"}, []string{fake.requests[0].Page, fake.requests[1].Page})
	for _, request := range fake.requests {
		require.Equal(t, "100", request.Limit)
		require.Equal(t, "all", request.State)
		require.Empty(t, request.Keyword)
	}
}

// TestFindIssueByTitleRespectsMaxPages verifies the configured page limit stops further requests.
func TestFindIssueByTitleRespectsMaxPages(t *testing.T) {
	var server *httptest.Server
	integration, fake := newFakeGitea(t, func(w http.ResponseWriter, r *http.Request, request issueRequest) {
		w.Header().Set("Link", fmt.Sprintf("<%s%s?page=2>; rel=\"next\"", server.URL, r.URL.Path))
		writeIssuePage(w, map[string]any{"number": 1, "title": "unrelated"})
	})
	server = fake.server
	integration.options.DuplicateIssueMaxPages = 1

	issue, err := integration.findIssueByTitle(testIssueTitle)
	require.NoError(t, err)
	require.Nil(t, issue)
	require.Len(t, fake.requests, 1)
	require.Equal(t, "1", fake.requests[0].Page)
}

// TestFindIssueByTitleStopsWhenLinkHeaderHasNoNextPage verifies pagination ends without a next link.
func TestFindIssueByTitleStopsWhenLinkHeaderHasNoNextPage(t *testing.T) {
	integration, fake := newFakeGitea(t, func(w http.ResponseWriter, _ *http.Request, _ issueRequest) {
		writeIssuePage(w, map[string]any{"number": 1, "title": "unrelated"})
	})

	issue, err := integration.findIssueByTitle(testIssueTitle)
	require.NoError(t, err)
	require.Nil(t, issue)
	require.Len(t, fake.requests, 1)
}

// TestFindIssueByTitleRejectsNonAdvancingPage verifies malformed links return an error instead of looping.
func TestFindIssueByTitleRejectsNonAdvancingPage(t *testing.T) {
	var server *httptest.Server
	integration, fake := newFakeGitea(t, func(w http.ResponseWriter, r *http.Request, _ issueRequest) {
		w.Header().Set("Link", fmt.Sprintf("<%s%s?page=1>; rel=\"next\"", server.URL, r.URL.Path))
		writeIssuePage(w, map[string]any{"number": 1, "title": "unrelated"})
	})
	server = fake.server

	issue, err := integration.findIssueByTitle(testIssueTitle)
	require.ErrorContains(t, err, "non-advancing issue page")
	require.Nil(t, issue)
	require.Len(t, fake.requests, 1)
}

// testGiteaEvent builds a small result event for tracker tests.
func testGiteaEvent() *output.ResultEvent {
	return &output.ResultEvent{
		TemplateID: "template-id",
		Host:       "example.com",
		Info:       model.Info{Name: "Test finding"},
	}
}

package github

import (
	"context"
	"fmt"
	"io"
	"strconv"

	"github.com/google/go-github/v92/github"
	"github.com/pkg/errors"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/exporters/markdown/util"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/format"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/tlsverify"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/trackers/filters"
	"github.com/projectdiscovery/retryablehttp-go"
	"golang.org/x/oauth2"
)

// Integration is a client for an issue tracker integration
type Integration struct {
	client  *github.Client
	options *Options
}

// Options contains the configuration options for GitHub issue tracker client
type Options struct {
	// BaseURL (optional) is the self-hosted GitHub application url
	BaseURL string `yaml:"base-url" validate:"omitempty,url"`
	// Username is the username of the GitHub user
	Username string `yaml:"username" validate:"required"`
	// Owner is the owner name of the repository for issues.
	Owner string `yaml:"owner" validate:"required"`
	// Token is the token for GitHub account.
	Token string `yaml:"token" validate:"required"`
	// ProjectName is the name of the repository.
	ProjectName string `yaml:"project-name" validate:"required"`
	// IssueLabel (optional) is the label of the created issue type
	IssueLabel string `yaml:"issue-label"`
	// SeverityAsLabel (optional) sends the severity as the label of the created
	// issue.
	SeverityAsLabel bool `yaml:"severity-as-label"`
	// AllowList contains a list of allowed events for this tracker
	AllowList *filters.Filter `yaml:"allow-list"`
	// DenyList contains a list of denied events for this tracker
	DenyList *filters.Filter `yaml:"deny-list"`
	// DuplicateIssueCheck (optional) comments under existing finding issue
	// instead of creating duplicates for subsequent runs.
	DuplicateIssueCheck bool `yaml:"duplicate-issue-check"`

	HttpClient *retryablehttp.Client `yaml:"-"`
	OmitRaw    bool                  `yaml:"-"`
}

// New creates a new issue tracker integration client based on options.
func New(options *Options) (*Integration, error) {
	ctx := context.Background()
	// Build the oauth2 client on top of the caller's client, so its transport
	// (proxy, address policy) and redirect rules apply to every request.
	if options.HttpClient != nil && options.HttpClient.HTTPClient != nil {
		ctx = context.WithValue(ctx, oauth2.HTTPClient, tlsverify.Client(options.HttpClient.HTTPClient))
	}
	ts := oauth2.StaticTokenSource(
		&oauth2.Token{AccessToken: options.Token},
	)
	tc := oauth2.NewClient(ctx, ts)

	clientOptions := []github.ClientOptionsFunc{github.WithHTTPClient(tc)}
	if options.BaseURL != "" {
		clientOptions = append(clientOptions, github.WithURLs(&options.BaseURL, nil))
	}
	client, err := github.NewClient(clientOptions...)
	if err != nil {
		return nil, errors.Wrap(err, "could not create github client")
	}
	return &Integration{client: client, options: options}, nil
}

// CreateIssue creates an issue in the tracker
func (i *Integration) CreateIssue(event *output.ResultEvent) (*filters.CreateIssueResponse, error) {
	summary := format.Summary(event)
	description := format.CreateReportDescription(event, util.MarkdownFormatter{}, i.options.OmitRaw)
	labels := []string{}
	severityLabel := fmt.Sprintf("Severity: %s", event.Info.SeverityHolder.Severity.String())
	if i.options.SeverityAsLabel && severityLabel != "" {
		labels = append(labels, severityLabel)
	}
	if label := i.options.IssueLabel; label != "" {
		labels = append(labels, label)
	}

	ctx := context.Background()

	var err error
	var existingIssue *github.Issue
	if i.options.DuplicateIssueCheck {
		existingIssue, err = i.findIssueByTitle(ctx, summary)
		if err != nil && !errors.Is(err, io.EOF) {
			return nil, err
		}
	}

	if existingIssue == nil {
		req := github.CreateIssueRequest{
			Title:     summary,
			Body:      &description,
			Labels:    labels,
			Assignees: []string{i.options.Username},
		}
		createdIssue, _, err := i.client.Issues.Create(ctx, i.options.Owner, i.options.ProjectName, req)
		if err != nil {
			return nil, err
		}
		return &filters.CreateIssueResponse{
			IssueID:  strconv.FormatInt(createdIssue.GetID(), 10),
			IssueURL: createdIssue.GetHTMLURL(),
		}, nil
	} else {
		if existingIssue.GetState() == "closed" {
			stateOpen := "open"
			if _, _, err := i.client.Issues.Update(ctx, i.options.Owner, i.options.ProjectName, *existingIssue.Number, github.UpdateIssueRequest{
				State: &stateOpen,
			}); err != nil {
				return nil, fmt.Errorf("error reopening issue %d: %s", *existingIssue.Number, err)
			}
		}

		req := github.IssueCommentRequest{
			Body: description,
		}
		_, _, err = i.client.Issues.CreateComment(ctx, i.options.Owner, i.options.ProjectName, *existingIssue.Number, req)
		if err != nil {
			return nil, err
		}
		return &filters.CreateIssueResponse{
			IssueID:  strconv.FormatInt(existingIssue.GetID(), 10),
			IssueURL: existingIssue.GetHTMLURL(),
		}, nil
	}
}

func (i *Integration) CloseIssue(event *output.ResultEvent) error {
	ctx := context.Background()
	summary := format.Summary(event)

	existingIssue, err := i.findIssueByTitle(ctx, summary)
	if err != nil && !errors.Is(err, io.EOF) {
		return err
	}
	if existingIssue == nil {
		return nil
	}

	stateClosed := "closed"
	if _, _, err := i.client.Issues.Update(ctx, i.options.Owner, i.options.ProjectName, *existingIssue.Number, github.UpdateIssueRequest{
		State: &stateClosed,
	}); err != nil {
		return fmt.Errorf("error closing issue %d: %s", *existingIssue.Number, err)
	}
	return nil
}

func (i *Integration) Name() string {
	return "github"
}

// ShouldFilter determines if an issue should be logged to this tracker
func (i *Integration) ShouldFilter(event *output.ResultEvent) bool {
	if i.options.AllowList != nil && !i.options.AllowList.GetMatch(event) {
		return false
	}

	if i.options.DenyList != nil && i.options.DenyList.GetMatch(event) {
		return false
	}

	return true
}

func (i *Integration) findIssueByTitle(ctx context.Context, title string) (*github.Issue, error) {
	req := &github.SearchOptions{
		Sort:      "updated",
		Order:     "desc",
		TextMatch: false,
		ListOptions: github.ListOptions{
			Page:    1,
			PerPage: 100,
		},
	}

	query := fmt.Sprintf(`is:issue repo:%s/%s "%s"`, i.options.Owner, i.options.ProjectName, title)

	for {
		issues, resp, err := i.client.Search.Issues(ctx, query, req)
		if err != nil {
			return nil, fmt.Errorf("error listing issues for %s, %s: %w", i.options.Owner, i.options.ProjectName, err)
		}

		for _, issue := range issues.Issues {
			if issue != nil && issue.Title != nil && *issue.Title == title {
				return issue, nil
			}
		}

		if resp.NextPage <= req.Page || len(issues.Issues) == 0 {
			return nil, io.EOF
		}

		req.ListOptions = github.ListOptions{
			Page:    resp.NextPage,
			PerPage: 100,
		}
	}
}

package github

import (
	"context"
	"crypto/tls"
	"errors"
	"net"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/model"
	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/severity"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/stretchr/testify/require"
)

type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

func testEvent() *output.ResultEvent {
	return &output.ResultEvent{
		TemplateID: "test-template",
		Host:       "https://target.example",
		Info:       model.Info{Name: "test", SeverityHolder: severity.Holder{Severity: severity.High}},
	}
}

func clientWithTransport(rt http.RoundTripper) *retryablehttp.Client {
	c := retryablehttp.NewClient(retryablehttp.DefaultOptionsSingle)
	c.HTTPClient = &http.Client{Transport: rt}
	return c
}

// The tracker must send every request through the caller's client, so a
// caller's address policy also covers the GitHub API base URL.
func TestNewUsesCallerHTTPClient(t *testing.T) {
	var serverHits atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		serverHits.Add(1)
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"number":1,"html_url":"https://github.example/o/r/issues/1"}`))
	}))
	defer srv.Close()

	t.Run("requests go through the caller's transport", func(t *testing.T) {
		var seen atomic.Int32
		rt := roundTripFunc(func(r *http.Request) (*http.Response, error) {
			seen.Add(1)
			require.Equal(t, "Bearer test-token", r.Header.Get("Authorization"))
			return http.DefaultTransport.RoundTrip(r)
		})
		tracker, err := New(&Options{BaseURL: srv.URL + "/", Username: "u", Owner: "o", ProjectName: "r", Token: "test-token", HttpClient: clientWithTransport(rt)})
		require.NoError(t, err)
		_, err = tracker.CreateIssue(testEvent())
		require.NoError(t, err)
		require.Positive(t, seen.Load())
	})

	t.Run("a refusing transport stops the request", func(t *testing.T) {
		before := serverHits.Load()
		denied := errors.New("denied by address policy")
		rt := roundTripFunc(func(*http.Request) (*http.Response, error) { return nil, denied })
		tracker, err := New(&Options{BaseURL: srv.URL + "/", Username: "u", Owner: "o", ProjectName: "r", Token: "test-token", HttpClient: clientWithTransport(rt)})
		require.NoError(t, err)
		_, err = tracker.CreateIssue(testEvent())
		require.ErrorContains(t, err, "denied by address policy")
		require.Equal(t, before, serverHits.Load(), "the request reached the server")
	})
}

func TestNewRefusesUntrustedCertificateFromInsecureCallerClient(t *testing.T) {
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"number":1}`))
	}))
	defer srv.Close()

	insecure := &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}}
	tracker, err := New(&Options{BaseURL: srv.URL + "/", Username: "u", Owner: "o", ProjectName: "r", Token: "test-token", HttpClient: clientWithTransport(insecure)})
	require.NoError(t, err)
	_, err = tracker.CreateIssue(testEvent())
	require.ErrorContains(t, err, "certificate")
}

type wrappingTransport struct{ base http.RoundTripper }

func (w *wrappingTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	return w.base.RoundTrip(r)
}
func (w *wrappingTransport) Unwrap() http.RoundTripper { return w.base }

// The scan client wraps its transport and, with a SOCKS proxy, does TLS in its
// own dialer with the scan TLS config, which skips verification.
func TestNewRefusesUntrustedCertificateFromInsecureTLSDialer(t *testing.T) {
	srv := httptest.NewTLSServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusCreated)
		_, _ = w.Write([]byte(`{"number":1}`))
	}))
	defer srv.Close()

	var dialed atomic.Int32
	var dialer net.Dialer
	base := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			dialed.Add(1)
			return dialer.DialContext(ctx, network, addr)
		},
		DialTLSContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			conn, err := dialer.DialContext(ctx, network, addr)
			if err != nil {
				return nil, err
			}
			return tls.Client(conn, &tls.Config{InsecureSkipVerify: true}), nil
		},
	}
	tracker, err := New(&Options{BaseURL: srv.URL + "/", Username: "u", Owner: "o", ProjectName: "r", Token: "test-token", HttpClient: clientWithTransport(&wrappingTransport{base: base})})
	require.NoError(t, err)
	_, err = tracker.CreateIssue(testEvent())
	require.ErrorContains(t, err, "certificate")
	require.Positive(t, dialed.Load(), "the caller's dialer was not used")
}

package gitlab

import (
	"fmt"
	"strconv"

	gitlab "gitlab.com/gitlab-org/api/client-go"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/exporters/markdown/util"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/format"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/trackers/filters"
	"github.com/projectdiscovery/retryablehttp-go"
)

// Integration is a client for an issue tracker integration
type Integration struct {
	client  *gitlab.Client
	userID  int64
	options *Options
}

// Options contains the configuration options for gitlab issue tracker client
type Options struct {
	// BaseURL (optional) is the self-hosted gitlab application url
	BaseURL string `yaml:"base-url" validate:"omitempty,url"`
	// Username is the username of the gitlab user
	Username string `yaml:"username" validate:"required"`
	// Token is the token for gitlab account.
	Token string `yaml:"token" validate:"required"`
	// ProjectName is the name of the repository.
	ProjectName string `yaml:"project-name" validate:"required"`
	// IssueLabel is the label of the created issue type
	IssueLabel string `yaml:"issue-label"`
	// SeverityAsLabel (optional) sends the severity as the label of the created
	// issue.
	SeverityAsLabel bool `yaml:"severity-as-label"`
	// AllowList contains a list of allowed events for this tracker
	AllowList *filters.Filter `yaml:"allow-list"`
	// DenyList contains a list of denied events for this tracker
	DenyList *filters.Filter `yaml:"deny-list"`
	// DuplicateIssueCheck is a bool to enable duplicate tracking issue check and update the newest
	DuplicateIssueCheck bool `yaml:"duplicate-issue-check" default:"false"`
	// DuplicateIssuePageSize is the number of issues to request per page when searching for duplicates.
	// GitLab returns at most 100 issues per page.
	// If unset or <=0, a default of 100 is used.
	DuplicateIssuePageSize int `yaml:"duplicate-issue-page-size" default:"100"`
	// DuplicateIssueMaxPages limits how many pages are fetched when searching for duplicates.
	// If unset or <=0, all pages are fetched until exhaustion.
	DuplicateIssueMaxPages int `yaml:"duplicate-issue-max-pages" default:"0"`

	HttpClient *retryablehttp.Client `yaml:"-"`
	OmitRaw    bool                  `yaml:"-"`
}

// New creates a new issue tracker integration client based on options.
func New(options *Options) (*Integration, error) {
	gitlabOpts := []gitlab.ClientOptionFunc{}
	if options.BaseURL != "" {
		gitlabOpts = append(gitlabOpts, gitlab.WithBaseURL(options.BaseURL))
	}
	if options.HttpClient != nil {
		gitlabOpts = append(gitlabOpts, gitlab.WithHTTPClient(options.HttpClient.HTTPClient))
	}
	git, err := gitlab.NewClient(options.Token, gitlabOpts...)
	if err != nil {
		return nil, err
	}
	user, _, err := git.Users.CurrentUser()
	if err != nil {
		return nil, err
	}
	return &Integration{client: git, userID: user.ID, options: options}, nil
}

// CreateIssue creates an issue in the tracker
func (i *Integration) CreateIssue(event *output.ResultEvent) (*filters.CreateIssueResponse, error) {
	summary := format.Summary(event)
	description := format.CreateReportDescription(event, util.MarkdownFormatter{}, i.options.OmitRaw)
	labels := []string{}
	severityLabel := fmt.Sprintf("Severity: %s", event.Info.SeverityHolder.Severity.String())
	if i.options.SeverityAsLabel && severityLabel != "" {
		labels = append(labels, severityLabel)
	}
	if label := i.options.IssueLabel; label != "" {
		labels = append(labels, label)
	}
	customLabels := gitlab.LabelOptions(labels)
	assigneeIDs := []int64{i.userID}

	var issue *gitlab.Issue
	if i.options.DuplicateIssueCheck {
		var err error
		issue, err = i.findIssueByTitle(summary)
		if err != nil {
			return nil, err
		}
	}

	if issue != nil {
		_, _, err := i.client.Notes.CreateIssueNote(i.options.ProjectName, issue.IID, &gitlab.CreateIssueNoteOptions{
			Body: &description,
		})
		if err != nil {
			return nil, err
		}
		if issue.State == "closed" {
			reopen := "reopen"
			_, _, err := i.client.Issues.UpdateIssue(i.options.ProjectName, issue.IID, &gitlab.UpdateIssueOptions{
				StateEvent: &reopen,
			})
			if err != nil {
				return nil, err
			}
		}
		return &filters.CreateIssueResponse{
			IssueID:  strconv.FormatInt(issue.ID, 10),
			IssueURL: issue.WebURL,
		}, nil
	}
	createdIssue, _, err := i.client.Issues.CreateIssue(i.options.ProjectName, &gitlab.CreateIssueOptions{
		Title:       &summary,
		Description: &description,
		Labels:      &customLabels,
		AssigneeIDs: &assigneeIDs,
	})
	if err != nil {
		return nil, err
	}
	return &filters.CreateIssueResponse{
		IssueID:  strconv.FormatInt(createdIssue.ID, 10),
		IssueURL: createdIssue.WebURL,
	}, nil
}

func (i *Integration) Name() string {
	return "gitlab"
}

func (i *Integration) CloseIssue(event *output.ResultEvent) error {
	summary := format.Summary(event)
	issue, err := i.findIssueByTitle(summary)
	if err != nil {
		return err
	}
	if issue == nil {
		return nil
	}

	state := "close"
	_, _, err = i.client.Issues.UpdateIssue(i.options.ProjectName, issue.IID, &gitlab.UpdateIssueOptions{
		StateEvent: &state,
	})
	if err != nil {
		return err
	}
	return nil
}

func (i *Integration) findIssueByTitle(title string) (*gitlab.Issue, error) {
	pageSize := i.options.DuplicateIssuePageSize
	if pageSize <= 0 {
		pageSize = 100
	}
	maxPages := int64(i.options.DuplicateIssueMaxPages)

	searchIn := "title"
	searchState := "all"
	page := int64(1)

	for {
		if maxPages > 0 && page > maxPages {
			return nil, nil
		}

		issues, resp, err := i.client.Issues.ListProjectIssues(i.options.ProjectName, &gitlab.ListProjectIssuesOptions{
			In:     &searchIn,
			State:  &searchState,
			Search: &title,
			ListOptions: gitlab.ListOptions{
				Page:    page,
				PerPage: int64(pageSize),
			},
		})
		if err != nil {
			return nil, err
		}

		for _, issue := range issues {
			if issue.Title == title {
				return issue, nil
			}
		}

		// GitLab caps per_page at 100, so a short page is not necessarily
		// the last one. Follow X-Next-Page instead, and stop when it is
		// empty or does not move forward.
		if resp.NextPage <= page {
			return nil, nil
		}

		page = resp.NextPage
	}
}

// ShouldFilter determines if an issue should be logged to this tracker
func (i *Integration) ShouldFilter(event *output.ResultEvent) bool {
	if i.options.AllowList != nil && !i.options.AllowList.GetMatch(event) {
		return false
	}

	if i.options.DenyList != nil && i.options.DenyList.GetMatch(event) {
		return false
	}

	return true
}

package gitlab

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"sync"
	"testing"

	"github.com/stretchr/testify/require"
)

type fakeIssue struct {
	ID    int64  `json:"id"`
	IID   int64  `json:"iid"`
	Title string `json:"title"`
}

// fakeGitLab serves the GitLab API endpoints that findIssueByTitle uses. Like
// GitLab, it caps per_page at maxPerPage and names the next page in the
// X-Next-Page header, which is empty on the last page. Every issue counts as
// a search hit, which leaves the exact title match to the tracker.
type fakeGitLab struct {
	issues     []fakeIssue
	maxPerPage int

	mu    sync.Mutex
	pages []int
}

func newFakeGitLab(issueCount, maxPerPage int) *fakeGitLab {
	f := &fakeGitLab{maxPerPage: maxPerPage}
	for n := 1; n <= issueCount; n++ {
		f.issues = append(f.issues, fakeIssue{ID: int64(n), IID: int64(n), Title: fmt.Sprintf("issue %d", n)})
	}
	return f
}

func (f *fakeGitLab) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	switch r.URL.Path {
	case "/api/v4/user":
		_, _ = w.Write([]byte(`{"id":1}`))
	case "/api/v4/projects/1234/issues":
		f.listIssues(w, r)
	default:
		http.NotFound(w, r)
	}
}

func (f *fakeGitLab) listIssues(w http.ResponseWriter, r *http.Request) {
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	perPage, _ := strconv.Atoi(r.URL.Query().Get("per_page"))
	if perPage <= 0 || perPage > f.maxPerPage {
		perPage = f.maxPerPage
	}

	f.mu.Lock()
	f.pages = append(f.pages, page)
	f.mu.Unlock()

	nextPage := ""
	if page*perPage < len(f.issues) {
		nextPage = strconv.Itoa(page + 1)
	}
	w.Header().Set("X-Next-Page", nextPage)

	start := min((page-1)*perPage, len(f.issues))
	end := min(start+perPage, len(f.issues))
	_ = json.NewEncoder(w).Encode(f.issues[start:end])
}

func (f *fakeGitLab) requestedPages() []int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return slices.Clone(f.pages)
}

func TestFindIssueByTitle(t *testing.T) {
	tests := []struct {
		name      string
		title     string
		maxPages  int
		wantIID   int64
		wantPages []int
	}{
		{
			name:      "match after a server-capped first page",
			title:     "issue 110",
			wantIID:   110,
			wantPages: []int{1, 2},
		},
		{
			name:      "no match checks every page once",
			title:     "missing",
			wantPages: []int{1, 2},
		},
		{
			name:      "max pages stops the search",
			title:     "issue 110",
			maxPages:  1,
			wantPages: []int{1},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// GitLab caps per_page at 100, so a configured page size of
			// 150 still splits 120 issues into two pages.
			fake := newFakeGitLab(120, 100)
			server := httptest.NewServer(fake)
			t.Cleanup(server.Close)

			integration, err := New(&Options{
				BaseURL:                server.URL,
				Token:                  "token",
				ProjectName:            "1234",
				DuplicateIssuePageSize: 150,
				DuplicateIssueMaxPages: tt.maxPages,
			})
			require.NoError(t, err)

			issue, err := integration.findIssueByTitle(tt.title)
			require.NoError(t, err)
			if tt.wantIID == 0 {
				require.Nil(t, issue)
			} else {
				require.NotNil(t, issue)
				require.Equal(t, tt.wantIID, issue.IID)
			}
			require.Equal(t, tt.wantPages, fake.requestedPages())
		})
	}
}

package jira

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"text/template"

	"github.com/andygrunwald/go-jira"
	"github.com/pkg/errors"
	"github.com/trivago/tgo/tcontainer"
	"golang.org/x/text/cases"
	"golang.org/x/text/language"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/exporters/markdown/util"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/format"
	"github.com/projectdiscovery/nuclei/v3/pkg/reporting/trackers/filters"
	"github.com/projectdiscovery/retryablehttp-go"
	"github.com/projectdiscovery/utils/ptr"
)

type Formatter struct {
	util.MarkdownFormatter
}

// TemplateContext holds the data available for template evaluation
type TemplateContext struct {
	Severity    string
	Name        string
	Host        string
	CVSSScore   string
	CVEID       string
	CWEID       string
	CVSSMetrics string
	Tags        []string
}

// buildTemplateContext creates a template context from a ResultEvent
func buildTemplateContext(event *output.ResultEvent) *TemplateContext {
	ctx := &TemplateContext{
		Host: event.Host,
		Name: event.Info.Name,
		Tags: event.Info.Tags.ToSlice(),
	}

	// Set severity string
	ctx.Severity = event.Info.SeverityHolder.Severity.String()

	if event.Info.Classification != nil {
		ctx.CVSSScore = fmt.Sprintf("%.2f", ptr.Safe(event.Info.Classification).CVSSScore)
		ctx.CVEID = strings.Join(ptr.Safe(event.Info.Classification).CVEID.ToSlice(), ", ")
		ctx.CWEID = strings.Join(ptr.Safe(event.Info.Classification).CWEID.ToSlice(), ", ")
		ctx.CVSSMetrics = ptr.Safe(event.Info.Classification).CVSSMetrics
	}

	return ctx
}

// evaluateTemplate executes a template string with the given context
func evaluateTemplate(templateStr string, ctx *TemplateContext) (string, error) {
	// If no template markers found, return as-is for backward compatibility
	if !strings.Contains(templateStr, "{{") {
		return templateStr, nil
	}

	// Create template with useful functions for JIRA custom fields
	funcMap := template.FuncMap{
		"upper":     strings.ToUpper,
		"lower":     strings.ToLower,
		"title":     cases.Title(language.English).String,
		"contains":  strings.Contains,
		"hasPrefix": strings.HasPrefix,
		"hasSuffix": strings.HasSuffix,
		"trim":      strings.Trim,
		"trimSpace": strings.TrimSpace,
		"replace":   strings.ReplaceAll,
		"split":     strings.Split,
		"join":      strings.Join,
	}

	tmpl, err := template.New("field").Funcs(funcMap).Parse(templateStr)
	if err != nil {
		return templateStr, fmt.Errorf("failed to parse template: %w", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, ctx); err != nil {
		return templateStr, fmt.Errorf("failed to execute template: %w", err)
	}

	return buf.String(), nil
}

// evaluateCustomFieldValue evaluates a custom field value, supporting both new template syntax and legacy $variable syntax
func (i *Integration) evaluateCustomFieldValue(value string, templateCtx *TemplateContext, event *output.ResultEvent) (interface{}, error) {
	// Try template evaluation first (supports {{...}} syntax)
	if strings.Contains(value, "{{") {
		return evaluateTemplate(value, templateCtx)
	}

	// Handle legacy $variable syntax for backward compatibility
	if strings.HasPrefix(value, "$") {
		variableName := strings.TrimPrefix(value, "$")
		switch variableName {
		case "CVSSMetrics":
			if event.Info.Classification != nil {
				return ptr.Safe(event.Info.Classification).CVSSMetrics, nil
			}
			return "", nil
		case "CVEID":
			if event.Info.Classification != nil {
				return strings.Join(ptr.Safe(event.Info.Classification).CVEID.ToSlice(), ", "), nil
			}
			return "", nil
		case "CWEID":
			if event.Info.Classification != nil {
				return strings.Join(ptr.Safe(event.Info.Classification).CWEID.ToSlice(), ", "), nil
			}
			return "", nil
		case "CVSSScore":
			if event.Info.Classification != nil {
				return fmt.Sprintf("%.2f", ptr.Safe(event.Info.Classification).CVSSScore), nil
			}
			return "", nil
		case "Host":
			return event.Host, nil
		case "Severity":
			return event.Info.SeverityHolder.Severity.String(), nil
		case "Name":
			return event.Info.Name, nil
		default:
			return value, nil // return as-is if variable not found
		}
	}

	// Return as-is if no template or variable syntax found
	return value, nil
}

func (jiraFormatter *Formatter) MakeBold(text string) string {
	return "*" + text + "*"
}

func (jiraFormatter *Formatter) CreateCodeBlock(title string, content string, _ string) string {
	escapedContent := strings.ReplaceAll(content, "{code}", "")
	return fmt.Sprintf("\n%s\n{code}\n%s\n{code}\n", jiraFormatter.MakeBold(title), escapedContent)
}

func (jiraFormatter *Formatter) CreateTable(headers []string, rows [][]string) (string, error) {
	table, err := jiraFormatter.MarkdownFormatter.CreateTable(headers, rows)
	if err != nil {
		return "", err
	}
	tableRows := strings.Split(table, "\n")
	tableRowsWithoutHeaderSeparator := append(tableRows[:1], tableRows[2:]...)
	return strings.Join(tableRowsWithoutHeaderSeparator, "\n"), nil
}

func (jiraFormatter *Formatter) CreateLink(title string, url string) string {
	return fmt.Sprintf("[%s|%s]", title, url)
}

// Integration is a client for an issue tracker integration
type Integration struct {
	Formatter
	jira    *jira.Client
	options *Options
}

// Options contains the configuration options for jira client
type Options struct {
	// Cloud value (optional) is set to true when Jira cloud is used
	Cloud bool `yaml:"cloud" json:"cloud"`
	// UpdateExisting value (optional) if true, the existing opened issue is updated
	UpdateExisting bool `yaml:"update-existing" json:"update_existing"`
	// URL is the URL of the jira server
	URL string `yaml:"url" json:"url" validate:"required"`
	// SiteURL is the browsable URL for the Jira instance (optional)
	// If not provided, issue.Self will be used. Useful for OAuth where issue.Self contains api.atlassian.com
	SiteURL string `yaml:"site-url" json:"site_url"`
	// AccountID is the accountID of the jira user.
	AccountID string `yaml:"account-id" json:"account_id" validate:"required"`
	// Email is the email of the user for jira instance
	Email string `yaml:"email" json:"email"`
	// PersonalAccessToken is the personal access token for jira instance.
	// If this is set, Bearer Auth is used instead of Basic Auth.
	PersonalAccessToken string `yaml:"personal-access-token" json:"personal_access_token"`
	// Token is the token for jira instance.
	Token string `yaml:"token" json:"token"`
	// ProjectName is the name of the project.
	ProjectName string `yaml:"project-name" json:"project_name"`
	// ProjectID is the ID of the project (optional)
	ProjectID string `yaml:"project-id" json:"project_id"`
	// IssueType (optional) is the name of the created issue type
	IssueType string `yaml:"issue-type" json:"issue_type"`
	// IssueTypeID (optional) is the ID of the created issue type
	IssueTypeID string `yaml:"issue-type-id" json:"issue_type_id"`
	// SeverityAsLabel (optional) sends the severity as the label of the created
	// issue.
	SeverityAsLabel bool `yaml:"severity-as-label" json:"severity_as_label"`
	// AllowList contains a list of allowed events for this tracker
	AllowList *filters.Filter `yaml:"allow-list"`
	// DenyList contains a list of denied events for this tracker
	DenyList *filters.Filter `yaml:"deny-list"`
	// Severity (optional) is the severity of the issue.
	Severity   []string              `yaml:"severity" json:"severity"`
	HttpClient *retryablehttp.Client `yaml:"-" json:"-"`
	// for each customfield specified in the configuration options
	// we will create a map of customfield name to the value
	// that will be used to create the issue
	CustomFields map[string]interface{} `yaml:"custom-fields" json:"custom_fields"`
	StatusNot    string                 `yaml:"status-not" json:"status_not"`
	OmitRaw      bool                   `yaml:"-"`
}

// New creates a new issue tracker integration client based on options.
func New(options *Options) (*Integration, error) {
	username := options.Email
	if !options.Cloud {
		username = options.AccountID
	}

	var httpclient *http.Client
	if options.PersonalAccessToken != "" {
		bearerTp := jira.BearerAuthTransport{
			Token: options.PersonalAccessToken,
		}
		if options.HttpClient != nil {
			bearerTp.Transport = options.HttpClient.HTTPClient.Transport
		}
		httpclient = bearerTp.Client()
	} else {
		basicTp := jira.BasicAuthTransport{
			Username: username,
			Password: options.Token,
		}
		if options.HttpClient != nil {
			basicTp.Transport = options.HttpClient.HTTPClient.Transport
		}
		httpclient = basicTp.Client()
	}

	jiraClient, err := jira.NewClient(httpclient, options.URL)
	if err != nil {
		return nil, err
	}
	integration := &Integration{
		jira:    jiraClient,
		options: options,
	}
	return integration, nil
}

func (i *Integration) Name() string {
	return "jira"
}

// CreateNewIssue creates a new issue in the tracker
func (i *Integration) CreateNewIssue(event *output.ResultEvent) (*filters.CreateIssueResponse, error) {
	summary := format.Summary(event)
	labels := []string{}
	severityLabel := fmt.Sprintf("Severity:%s", event.Info.SeverityHolder.Severity.String())
	if i.options.SeverityAsLabel && severityLabel != "" {
		labels = append(labels, severityLabel)
	}
	if label := i.options.IssueType; label != "" {
		labels = append(labels, label)
	}
	// Build template context for evaluating custom field templates
	templateCtx := buildTemplateContext(event)

	// Process custom fields with template evaluation support
	customFields := tcontainer.NewMarshalMap()
	for name, value := range i.options.CustomFields {
		if valueMap, ok := value.(map[interface{}]interface{}); ok {
			// Iterate over nested map
			for nestedName, nestedValue := range valueMap {
				fmtNestedValue, ok := nestedValue.(string)
				if !ok {
					return nil, fmt.Errorf(`couldn't iterate on nested item "%s": %s`, nestedName, nestedValue)
				}

				// Evaluate template or handle legacy $variable syntax
				evaluatedValue, err := i.evaluateCustomFieldValue(fmtNestedValue, templateCtx, event)
				if err != nil {
					gologger.Warning().Msgf("Failed to evaluate template for field %s.%s: %v", name, nestedName, err)
					evaluatedValue = fmtNestedValue // fallback to original value
				}

				switch nestedName {
				case "id":
					customFields[name] = map[string]interface{}{"id": evaluatedValue}
				case "name":
					customFields[name] = map[string]interface{}{"value": evaluatedValue}
				case "freeform":
					customFields[name] = evaluatedValue
				}
			}
		}
	}
	fields := &jira.IssueFields{
		Assignee:    &jira.User{Name: i.options.AccountID},
		Description: format.CreateReportDescription(event, i, i.options.OmitRaw),
		Unknowns:    customFields,
		Labels:      labels,
		Type:        jira.IssueType{Name: i.options.IssueType},
		Project:     jira.Project{Key: i.options.ProjectName},
		Summary:     summary,
	}

	// On-prem version of Jira server does not use AccountID
	if !i.options.Cloud {
		fields = &jira.IssueFields{
			Assignee:    &jira.User{Name: i.options.AccountID},
			Description: format.CreateReportDescription(event, i, i.options.OmitRaw),
			Type:        jira.IssueType{Name: i.options.IssueType},
			Project:     jira.Project{Key: i.options.ProjectName},
			Summary:     summary,
			Labels:      labels,
			Unknowns:    customFields,
		}
	}
	if i.options.IssueTypeID != "" {
		fields.Type = jira.IssueType{ID: i.options.IssueTypeID}
	}
	if i.options.ProjectID != "" {
		fields.Project = jira.Project{ID: i.options.ProjectID}
	}

	issueData := &jira.Issue{
		Fields: fields,
	}
	createdIssue, resp, err := i.jira.Issue.Create(issueData)
	if err != nil {
		return nil, fmt.Errorf("%w => %s", err, readAndCloseBody(resp))
	}
	return i.getIssueResponseFromJira(createdIssue)
}

func (i *Integration) getIssueResponseFromJira(issue *jira.Issue) (*filters.CreateIssueResponse, error) {
	var issueURL string

	// Use SiteURL if provided, otherwise fall back to original issue.Self logic
	if i.options.SiteURL != "" {
		// Use the configured site URL for browsable links (useful for OAuth)
		baseURL := strings.TrimRight(i.options.SiteURL, "/")
		issueURL = fmt.Sprintf("%s/browse/%s", baseURL, issue.Key)
	} else {
		// Fall back to original logic using issue.Self
		parsed, err := url.Parse(issue.Self)
		if err != nil {
			return nil, err
		}
		parsed.Path = fmt.Sprintf("/browse/%s", issue.Key)
		issueURL = parsed.String()
	}

	return &filters.CreateIssueResponse{
		IssueID:  issue.ID,
		IssueURL: issueURL,
	}, nil
}

// CreateIssue creates an issue in the tracker or updates the existing one
func (i *Integration) CreateIssue(event *output.ResultEvent) (*filters.CreateIssueResponse, error) {
	if i.options.UpdateExisting {
		issue, err := i.FindExistingIssue(event, true)
		if err != nil {
			return nil, errors.Wrap(err, "could not find existing issue")
		} else if issue.ID != "" {
			_, _, err = i.jira.Issue.AddComment(issue.ID, &jira.Comment{
				Body: format.CreateReportDescription(event, i, i.options.OmitRaw),
			})
			if err != nil {
				return nil, errors.Wrap(err, "could not add comment to existing issue")
			}
			return i.getIssueResponseFromJira(&issue)
		}
	}
	resp, err := i.CreateNewIssue(event)
	if err != nil {
		return nil, errors.Wrap(err, "could not create new issue")
	}
	return resp, nil
}

func (i *Integration) CloseIssue(event *output.ResultEvent) error {
	if i.options.StatusNot == "" {
		return nil
	}

	issue, err := i.FindExistingIssue(event, true)
	if err != nil {
		return err
	}
	if issue.ID == "" {
		return nil
	}
	return i.CloseIssueByID(issue.ID)
}

// CloseIssueByID transitions a known Jira issue to the configured target status.
func (i *Integration) CloseIssueByID(issueID string) error {
	if i.options.StatusNot == "" {
		return nil
	}
	if issueID == "" {
		return fmt.Errorf("jira issue ID is required")
	}

	transitions, _, err := i.jira.Issue.GetTransitions(issueID)
	if err != nil {
		return fmt.Errorf("get Jira issue %s transitions: %w", issueID, err)
	}
	for _, transition := range transitions {
		if transition.To.Name != i.options.StatusNot {
			continue
		}
		resp, err := i.jira.Issue.DoTransitionWithPayload(issueID, jira.CreateTransitionPayload{
			Transition: jira.TransitionPayload{ID: transition.ID},
		})
		// go-jira does not decode the transition response, so it leaves the
		// body open on success. Close it so the connection can be reused.
		closeBody(resp)
		if err != nil {
			return fmt.Errorf("transition Jira issue %s: %w", issueID, err)
		}
		return nil
	}

	currentIssue, _, err := i.jira.Issue.Get(issueID, nil)
	if err != nil {
		return fmt.Errorf("get Jira issue %s status: %w", issueID, err)
	}
	if currentIssue.Fields != nil && currentIssue.Fields.Status != nil && currentIssue.Fields.Status.Name == i.options.StatusNot {
		return nil
	}
	return fmt.Errorf("jira issue %s has no transition to %q", issueID, i.options.StatusNot)
}

// FindExistingIssue checks if the issue already exists and returns its ID
func (i *Integration) FindExistingIssue(event *output.ResultEvent, useStatus bool) (jira.Issue, error) {
	template := format.GetMatchedTemplateName(event)
	project := i.options.ProjectName
	if i.options.ProjectID != "" {
		project = i.options.ProjectID
	}
	jql := fmt.Sprintf("summary ~ \"%s\" AND summary ~ \"%s\" AND project = \"%s\"", template, event.Host, project)
	if useStatus {
		jql = fmt.Sprintf("%s AND status != \"%s\"", jql, i.options.StatusNot)
	}

	// Hotfix for Jira Cloud: use Enhanced Search API (v3) to avoid deprecated v2 path
	if i.options.Cloud {
		params := url.Values{}
		params.Set("jql", jql)
		params.Set("maxResults", "1")
		params.Set("fields", "id,key")

		req, err := i.jira.NewRequest("GET", "/rest/api/3/search/jql"+"?"+params.Encode(), nil)
		if err != nil {
			return jira.Issue{}, err
		}

		var searchResult struct {
			Issues []struct {
				ID  string `json:"id"`
				Key string `json:"key"`
			} `json:"issues"`
			IsLast        bool   `json:"isLast"`
			NextPageToken string `json:"nextPageToken"`
		}

		resp, err := i.jira.Do(req, &searchResult)
		if err != nil {
			return jira.Issue{}, fmt.Errorf("%w => %s", err, readAndCloseBody(resp))
		}

		if len(searchResult.Issues) == 0 {
			return jira.Issue{}, nil
		}
		first := searchResult.Issues[0]
		base := strings.TrimRight(i.options.URL, "/")
		return jira.Issue{
			ID:   first.ID,
			Key:  first.Key,
			Self: fmt.Sprintf("%s/rest/api/3/issue/%s", base, first.ID),
		}, nil
	}

	searchOptions := &jira.SearchOptions{
		MaxResults: 1, // if any issue exists, then we won't create a new one
		Fields:     []string{"summary", "description", "issuetype", "status", "priority", "project"},
	}

	issues, resp, err := i.jira.Issue.Search(jql, searchOptions)
	if err != nil {
		var data string
		if resp != nil && resp.Body != nil {
			d, _ := io.ReadAll(resp.Body)
			data = string(d)
		}
		return jira.Issue{}, fmt.Errorf("%w => %s", err, data)
	}

	switch len(issues) {
	case 0:
		return jira.Issue{}, nil
	case 1:
		return issues[0], nil
	default:
		gologger.Warning().Msgf("Discovered multiple opened issues %s for the host %s: The issue [%s] will be updated.", template, event.Host, issues[0].ID)
		return issues[0], nil
	}
}

// ShouldFilter determines if an issue should be logged to this tracker
func (i *Integration) ShouldFilter(event *output.ResultEvent) bool {
	if i.options.AllowList != nil && !i.options.AllowList.GetMatch(event) {
		return false
	}

	if i.options.DenyList != nil && i.options.DenyList.GetMatch(event) {
		return false
	}

	return true
}

// readAndCloseBody returns the body of a failed go-jira response and closes it.
// go-jira hands the response back unread on some error paths, so the caller
// has to close it.
func readAndCloseBody(resp *jira.Response) string {
	if resp == nil || resp.Response == nil || resp.Body == nil {
		return ""
	}
	defer closeBody(resp)
	data, _ := io.ReadAll(resp.Body)
	return string(data)
}

// closeBody closes a go-jira response body. It does not drain it: a server
// that stalls mid-body would otherwise block the caller, and an empty
// response, which is what go-jira leaves open, returns to the pool on close.
func closeBody(resp *jira.Response) {
	if resp == nil || resp.Response == nil || resp.Body == nil {
		return
	}
	_ = resp.Body.Close()
}

