package scan

import (
	"context"
	"fmt"
	"strings"
	"sync"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/contextargs"
	"github.com/projectdiscovery/utils/errkit"
)

type ScanContextOption func(*ScanContext)

func WithEvents() ScanContextOption {
	return func(sc *ScanContext) {
		sc.withEvents = true
	}
}

type ScanContext struct {
	ctx context.Context

	// exported / configurable fields
	Input *contextargs.Context

	// callbacks or hooks
	OnError   func(error)
	OnResult  func(e *output.InternalWrappedEvent)
	OnWarning func(string)

	// unexported state fields
	error    error
	warnings []string
	events   []*output.InternalWrappedEvent
	results  []*output.ResultEvent

	// what to log
	withEvents bool

	// might not be required but better to sync
	m sync.Mutex
}

// NewScanContext creates a new scan context using input
func NewScanContext(ctx context.Context, input *contextargs.Context) *ScanContext {
	return &ScanContext{ctx: ctx, Input: input}
}

// Context returns the context of the scan
func (s *ScanContext) Context() context.Context {
	return s.ctx
}

func (s *ScanContext) GenerateErrorMessage() error {
	return s.error
}

// GenerateResult returns final results slice from all events
func (s *ScanContext) GenerateResult() []*output.ResultEvent {
	s.m.Lock()
	defer s.m.Unlock()

	return s.results
}

// LogEvent logs events to all events and triggers any callbacks
func (s *ScanContext) LogEvent(e *output.InternalWrappedEvent) {
	s.m.Lock()
	defer s.m.Unlock()
	if e == nil {
		// do not log nil events
		return
	}

	if s.OnResult != nil {
		s.OnResult(e)
	}

	if s.withEvents {
		s.events = append(s.events, e)
	}

	e.RLock()
	defer e.RUnlock()

	s.results = append(s.results, e.Results...)
}

// LogError logs error to all events and triggers any callbacks
func (s *ScanContext) LogError(err error) {
	s.m.Lock()
	defer s.m.Unlock()
	if err == nil {
		return
	}
	if s.OnError != nil {
		s.OnError(err)
	}
	if s.error == nil {
		s.error = err
	} else {
		s.error = errkit.Append(s.error, err)
	}

	errorMessage := s.GenerateErrorMessage().Error()

	for _, result := range s.results {
		result.Error = errorMessage
	}

	for _, e := range s.events {
		e.InternalEvent["error"] = errorMessage
	}
}

// LogWarning logs warning to all events
func (s *ScanContext) LogWarning(format string, args ...any) {
	s.m.Lock()
	defer s.m.Unlock()
	val := fmt.Sprintf(format, args...)

	if s.OnWarning != nil {
		s.OnWarning(val)
	}

	s.warnings = append(s.warnings, val)

	for _, e := range s.events {
		if e.InternalEvent != nil {
			e.InternalEvent["warning"] = strings.Join(s.warnings, "; ")
		}
	}
}

package templates

import (
	"os"
	"time"

	"github.com/projectdiscovery/utils/conversion"
	mapsutil "github.com/projectdiscovery/utils/maps"
	"golang.org/x/sync/singleflight"
)

// Templates is a cache for caching and storing templates for reuse.
type Cache struct {
	items *mapsutil.SyncLockMap[string, parsedTemplate]
	loads singleflight.Group
}

// New returns a new templates cache
func NewCache() *Cache {
	return &Cache{
		items: mapsutil.NewSyncLockMap[string, parsedTemplate](),
	}
}

type parsedTemplate struct {
	template *Template
	raw      string
	err      error
	filePath string
	modTime  time.Time
}

// setModTime sets the modification time of the file if it exists.
func (p *parsedTemplate) setModTime(id string) {
	if stat, err := os.Stat(id); err == nil {
		p.modTime = stat.ModTime()
	}
}

// isValid checks if the cached template is still valid based on the file's
// modification time.
func (p *parsedTemplate) isValid(templatePath string) bool {
	if p.modTime.IsZero() {
		return true
	}

	stat, err := os.Stat(templatePath)
	if err != nil {
		return false
	}

	return stat.ModTime().Equal(p.modTime)
}

// Has returns true if the cache has a template. The template
// is returned along with any errors if found.
func (t *Cache) Has(template string) (*Template, []byte, error) {
	value, ok := t.items.Get(template)
	if !ok {
		return nil, nil, nil
	}

	if !value.isValid(template) {
		t.items.Delete(template)

		return nil, nil, nil
	}

	return value.template, conversion.Bytes(value.raw), value.err
}

// Store stores a template with data and error
func (t *Cache) Store(id string, tpl *Template, raw []byte, err error) {
	entry := parsedTemplate{
		template: tpl,
		err:      err,
		raw:      conversion.String(raw),
		filePath: id,
	}

	entry.setModTime(id)
	_ = t.items.Set(id, entry)
}

// StoreWithoutRaw stores a template without raw data for memory efficiency
func (t *Cache) StoreWithoutRaw(id string, tpl *Template, err error) {
	entry := parsedTemplate{
		template: tpl,
		err:      err,
		raw:      "",
		filePath: id,
	}

	entry.setModTime(id)
	_ = t.items.Set(id, entry)
}

// Get returns only the template without raw bytes
func (t *Cache) Get(id string) (*Template, error) {
	value, ok := t.items.Get(id)
	if !ok {
		return nil, nil
	}
	return value.template, value.err
}

// Purge the cache
func (t *Cache) Purge() {
	t.items.Clear()
}

package templates

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
)

func TestCache(t *testing.T) {
	templates := NewCache()
	testErr := errors.New("test error")

	data, _, err := templates.Has("test")
	require.Nil(t, err, "invalid value for err")
	require.Nil(t, data, "invalid value for data")

	item := &Template{}

	templates.Store("test", item, nil, testErr)
	data, _, err = templates.Has("test")
	require.Equal(t, testErr, err, "invalid value for err")
	require.Equal(t, item, data, "invalid value for data")
}

func TestCacheFileBased(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "cache_test")
	require.NoError(t, err)
	defer func() {
		_ = os.RemoveAll(tempDir)
	}()

	cache := NewCache()
	template := &Template{}

	// Create a test file
	testFile := filepath.Join(tempDir, "test.yaml")
	err = os.WriteFile(testFile, []byte("test content"), 0644)
	require.NoError(t, err)

	// Store template with file
	cache.Store(testFile, template, []byte("raw content"), nil)

	// Should be able to retrieve it
	retrieved, raw, err := cache.Has(testFile)
	require.NoError(t, err)
	require.Equal(t, template, retrieved)
	require.Equal(t, []byte("raw content"), raw)

	// Modify file content (should invalidate cache)
	time.Sleep(10 * time.Millisecond) // Ensure mod time difference
	err = os.WriteFile(testFile, []byte("modified content"), 0644)
	require.NoError(t, err)

	// Cache should be invalidated
	retrieved, raw, err = cache.Has(testFile)
	require.NoError(t, err)
	require.Nil(t, retrieved)
	require.Nil(t, raw)
}

func TestCacheFileDeletion(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "cache_test")
	require.NoError(t, err)
	defer func() {
		_ = os.RemoveAll(tempDir)
	}()

	cache := NewCache()
	template := &Template{}

	// Create a test file
	testFile := filepath.Join(tempDir, "test.yaml")
	err = os.WriteFile(testFile, []byte("test content"), 0644)
	require.NoError(t, err)

	// Store template with file
	cache.Store(testFile, template, []byte("raw content"), nil)

	// Should be able to retrieve it
	retrieved, raw, err := cache.Has(testFile)
	require.NoError(t, err)
	require.Equal(t, template, retrieved)
	require.Equal(t, []byte("raw content"), raw)

	// Delete the file
	err = os.Remove(testFile)
	require.NoError(t, err)

	// Cache should be invalidated
	retrieved, raw, err = cache.Has(testFile)
	require.NoError(t, err)
	require.Nil(t, retrieved)
	require.Nil(t, raw)
}

func TestCacheStoreWithoutRaw(t *testing.T) {
	cache := NewCache()
	template := &Template{}
	testErr := errors.New("test error")

	// Store without raw data
	cache.StoreWithoutRaw("test", template, testErr)

	// Should be able to retrieve template but not raw data
	retrieved, raw, err := cache.Has("test")
	require.Equal(t, testErr, err)
	require.Equal(t, template, retrieved)
	require.Empty(t, raw)
}

func TestCacheGet(t *testing.T) {
	cache := NewCache()
	template := &Template{}
	testErr := errors.New("test error")

	// Test cache miss
	retrieved, err := cache.Get("nonexistent")
	require.NoError(t, err)
	require.Nil(t, retrieved)

	// Store template
	cache.Store("test", template, []byte("raw"), testErr)

	// Should be able to get template
	retrieved, err = cache.Get("test")
	require.Equal(t, testErr, err)
	require.Equal(t, template, retrieved)
}

func TestCachePurge(t *testing.T) {
	cache := NewCache()
	template := &Template{}

	// Store multiple templates
	cache.Store("test1", template, []byte("raw1"), nil)
	cache.Store("test2", template, []byte("raw2"), nil)

	// Verify they exist
	retrieved1, _, _ := cache.Has("test1")
	require.Equal(t, template, retrieved1)
	retrieved2, _, _ := cache.Has("test2")
	require.Equal(t, template, retrieved2)

	// Purge cache
	cache.Purge()

	// Should be empty now
	retrieved1, _, _ = cache.Has("test1")
	require.Nil(t, retrieved1)
	retrieved2, _, _ = cache.Has("test2")
	require.Nil(t, retrieved2)
}

func TestCacheNonFileTemplates(t *testing.T) {
	cache := NewCache()
	template := &Template{}
	testErr := errors.New("test error")

	// Store non-file template (like the original test)
	cache.Store("nonfile", template, []byte("raw"), testErr)

	// Should work normally
	retrieved, raw, err := cache.Has("nonfile")
	require.Equal(t, testErr, err)
	require.Equal(t, template, retrieved)
	require.Equal(t, []byte("raw"), raw)
}

func TestCacheFileBasedStoreWithoutRaw(t *testing.T) {
	// Create a temporary directory for test files
	tempDir, err := os.MkdirTemp("", "cache_test")
	require.NoError(t, err)
	defer func() {
		_ = os.RemoveAll(tempDir)
	}()

	cache := NewCache()
	template := &Template{}

	// Create a test file
	testFile := filepath.Join(tempDir, "test.yaml")
	err = os.WriteFile(testFile, []byte("test content"), 0644)
	require.NoError(t, err)

	// Store template without raw data
	cache.StoreWithoutRaw(testFile, template, nil)

	// Should be able to retrieve template but not raw data
	retrieved, raw, err := cache.Has(testFile)
	require.NoError(t, err)
	require.Equal(t, template, retrieved)
	require.Empty(t, raw)
}

package templates

import (
	"fmt"

	"github.com/projectdiscovery/nuclei/v3/pkg/operators/extractors"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators/matchers"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
)

// Capability identifies an opt-in capability a template may require.
type Capability string

const (
	// CapabilityHeadless requires the -headless flag.
	CapabilityHeadless Capability = "headless"
	// CapabilityCode requires the -code flag.
	CapabilityCode Capability = "code"
	// CapabilityDAST requires the -dast flag.
	CapabilityDAST Capability = "dast"
	// CapabilitySelfContained requires the -enable-self-contained flag.
	CapabilitySelfContained Capability = "self-contained"
	// CapabilityGlobalMatchers requires the -enable-global-matchers flag.
	CapabilityGlobalMatchers Capability = "global-matchers"
	// CapabilityFile requires the -file flag.
	CapabilityFile Capability = "file"
	// CapabilityLLM requires the -llm flag.
	CapabilityLLM Capability = "llm"
)

type capabilityDefinition struct {
	capability   Capability
	stat         string
	flag         string
	templateKind string
	loadBlocking bool
	enabled      func(*types.Options) bool
	required     func(*Template) bool
}

var capabilityDefinitions = []capabilityDefinition{
	{
		capability:   CapabilityHeadless,
		stat:         ExcludedHeadlessTemplateStats,
		flag:         "-headless",
		templateKind: "headless",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.Headless
		},
		required: func(template *Template) bool {
			return template.HasHeadlessRequest()
		},
	},
	{
		capability:   CapabilityCode,
		stat:         ExcludedCodeTemplateStats,
		flag:         "-code",
		templateKind: "code protocol",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.EnableCodeTemplates
		},
		required: func(template *Template) bool {
			return template.HasCodeRequest()
		},
	},
	{
		capability:   CapabilityDAST,
		stat:         ExcludedDASTTemplateStats,
		flag:         "-dast",
		templateKind: "DAST",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.DAST
		},
		required: func(template *Template) bool {
			return template.IsFuzzableRequest()
		},
	},
	{
		capability:   CapabilitySelfContained,
		stat:         ExcludedSelfContainedTemplateStats,
		flag:         "-enable-self-contained",
		templateKind: "self-contained",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.EnableSelfContainedTemplates
		},
		required: func(template *Template) bool {
			return template.requiresSelfContained()
		},
	},
	{
		capability:   CapabilityGlobalMatchers,
		stat:         ExcludedGlobalMatchersTemplateStats,
		flag:         "-enable-global-matchers",
		templateKind: "global matchers",
		loadBlocking: false,
		enabled: func(options *types.Options) bool {
			return options.EnableGlobalMatchersTemplates
		},
		required: func(template *Template) bool {
			return template.requiresGlobalMatchers()
		},
	},
	{
		capability:   CapabilityLLM,
		stat:         ExcludedLLMTemplateStats,
		flag:         "-llm",
		templateKind: "llm",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.EnableLLM
		},
		required: func(template *Template) bool {
			return template.requiresLLM()
		},
	},
	{
		capability:   CapabilityFile,
		stat:         ExcludedFileTemplateStats,
		flag:         "-file",
		templateKind: "file",
		loadBlocking: true,
		enabled: func(options *types.Options) bool {
			return options.EnableFileTemplates
		},
		required: func(template *Template) bool {
			return template.HasFileRequest()
		},
	},
}

// AllCapabilities returns all template execution capabilities in evaluation order.
func AllCapabilities() []Capability {
	capabilities := make([]Capability, 0, len(capabilityDefinitions))
	for _, definition := range capabilityDefinitions {
		capabilities = append(capabilities, definition.capability)
	}

	return capabilities
}

// Stat returns the stats key for a missing capability.
func (capability Capability) Stat() string {
	definition, _ := capability.definition()

	return definition.stat
}

// Flag returns the CLI flag enabling the capability.
func (capability Capability) Flag() string {
	definition, _ := capability.definition()

	return definition.flag
}

// TemplateKind returns the template kind label used in missing-flag messages.
func (capability Capability) TemplateKind() string {
	definition, found := capability.definition()
	if !found {
		return string(capability)
	}

	return definition.templateKind
}

func (capability Capability) definition() (capabilityDefinition, bool) {
	for _, definition := range capabilityDefinitions {
		if definition.capability == capability {
			return definition, true
		}
	}

	return capabilityDefinition{}, false
}

// MissingFlagMessage returns a per-template message for a missing capability.
func (capability Capability) MissingFlagMessage(templatePath string) string {
	return fmt.Sprintf("%s flag is required for %s template %q.", capability.Flag(), capability.TemplateKind(), templatePath)
}

// CapabilitySet represents enabled template execution capabilities.
type CapabilitySet map[Capability]bool

// CapabilitiesFromOptions returns the template capabilities enabled by options.
func CapabilitiesFromOptions(options *types.Options) CapabilitySet {
	capabilities := make(CapabilitySet, len(capabilityDefinitions))
	for _, definition := range capabilityDefinitions {
		capabilities[definition.capability] = definition.enabled(options)
	}

	return capabilities
}

// Has returns true when a capability is enabled.
func (caps CapabilitySet) Has(capability Capability) bool {
	return caps[capability]
}

// RequiredCapabilities returns the opt-in capabilities required by the template.
func (template *Template) RequiredCapabilities() []Capability {
	var required []Capability

	for _, definition := range capabilityDefinitions {
		if definition.required(template) {
			required = append(required, definition.capability)
		}
	}

	return required
}

func (template *Template) requiresSelfContained() bool {
	if template.SelfContained {
		return true
	}

	for _, request := range template.RequestsHTTP {
		if request != nil && request.SelfContained {
			return true
		}
	}
	for _, request := range template.RequestsNetwork {
		if request != nil && request.SelfContained {
			return true
		}
	}
	for _, request := range template.RequestsHeadless {
		if request != nil && request.SelfContained {
			return true
		}
	}

	return false
}

func (template *Template) requiresGlobalMatchers() bool {
	for _, request := range template.RequestsHTTP {
		if request != nil && request.GlobalMatchers {
			return true
		}
	}

	return false
}

// requiresLLM reports whether any http matcher in the template is an llm
// matcher, so the capability check can exclude it when -llm is off rather than
// letting it silently fail closed to no match at scan time.
func (template *Template) requiresLLM() bool {
	for _, request := range template.RequestsHTTP {
		if request == nil {
			continue
		}
		for _, matcher := range request.Matchers {
			if matcher != nil && matcher.GetType() == matchers.LLMMatcher {
				return true
			}
		}
		for _, extractor := range request.Extractors {
			if extractor != nil && extractor.GetType() == extractors.LLMExtractor {
				return true
			}
		}
	}

	return false
}

// MissingCapabilities returns all disabled capabilities required by the template.
func (template *Template) MissingCapabilities(caps CapabilitySet) []Capability {
	return template.missingCapabilities(caps, false)
}

// MissingLoadCapabilities returns disabled capabilities that prevent a template
// from being loaded into the execution store.
func (template *Template) MissingLoadCapabilities(caps CapabilitySet) []Capability {
	return template.missingCapabilities(caps, true)
}

func (template *Template) missingCapabilities(caps CapabilitySet, loadOnly bool) []Capability {
	var missing []Capability

	for _, definition := range capabilityDefinitions {
		if loadOnly && !definition.loadBlocking {
			continue
		}
		if definition.required(template) && !caps.Has(definition.capability) {
			missing = append(missing, definition.capability)
		}
	}

	return missing
}

package templates

import (
	"reflect"

	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/variables"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
)

var executorOptionsType = reflect.TypeOf((*protocols.ExecutorOptions)(nil))

type cloneVisit struct {
	typeOf   reflect.Type
	pointer  uintptr
	length   int
	capacity int
}

// cloneTemplate copies a clean parsed template before protocol compilation
// adds engine-local state. Unexported fields hold immutable parse state at this
// point and are copied by value; exported maps, slices, pointers, and
// interfaces are copied recursively.
func cloneTemplate(template *Template) *Template {
	visited := newCloneVisited()
	cloned := cloneTemplateValue(reflect.ValueOf(template), visited)
	clonedTemplate := cloned.Interface().(*Template)
	clonedTemplate.Variables = cloneTemplateVariables(template.Variables, visited)
	return clonedTemplate
}

// newCloneVisited tracks values already cloned during one clone operation.
// Callers cloning several fields of the same owner must share it so values
// aliased across those fields stay aliased in the copy.
func newCloneVisited() map[cloneVisit]reflect.Value {
	return make(map[cloneVisit]reflect.Value)
}

// cloneTemplateVariables deep-copies variables, whose backing map is held in
// unexported fields that cloneTemplateValue copies by reference.
func cloneTemplateVariables(src variables.Variable, visited map[cloneVisit]reflect.Value) variables.Variable {
	dst := variables.Variable{LazyEval: src.LazyEval}
	dst.InsertionOrderedStringMap = *utils.NewEmptyInsertionOrderedStringMap(src.Len())
	src.ForEach(func(key string, value interface{}) {
		clonedValue := cloneTemplateValue(reflect.ValueOf(value), visited)
		if clonedValue.IsValid() {
			dst.Set(key, clonedValue.Interface())
		} else {
			dst.Set(key, nil)
		}
	})
	return dst
}

func cloneTemplateConstants(src map[string]interface{}, visited map[cloneVisit]reflect.Value) map[string]interface{} {
	if src == nil {
		return nil
	}
	cloned := cloneTemplateValue(reflect.ValueOf(src), visited)
	return cloned.Interface().(map[string]interface{})
}

func cloneTemplateValue(value reflect.Value, visited map[cloneVisit]reflect.Value) reflect.Value {
	if !value.IsValid() {
		return value
	}

	// ExecutorOptions reach engine-scoped state such as the shared parser and its
	// caches, which other goroutines mutate while this template is cloned. Callers
	// swap in a cache-safe copy, so carry the pointer instead of walking it.
	if value.Type() == executorOptionsType {
		return value
	}

	switch value.Kind() {
	case reflect.Interface:
		if value.IsNil() {
			return reflect.Zero(value.Type())
		}
		cloned := cloneTemplateValue(value.Elem(), visited)
		result := reflect.New(value.Type()).Elem()
		result.Set(cloned)
		return result
	case reflect.Pointer:
		if value.IsNil() {
			return reflect.Zero(value.Type())
		}
		visit := cloneVisit{typeOf: value.Type(), pointer: value.Pointer()}
		if cloned, ok := visited[visit]; ok {
			return cloned
		}
		cloned := reflect.New(value.Type().Elem())
		visited[visit] = cloned
		cloned.Elem().Set(cloneTemplateValue(value.Elem(), visited))
		return cloned
	case reflect.Struct:
		cloned := reflect.New(value.Type()).Elem()
		cloned.Set(value)
		for i := 0; i < value.NumField(); i++ {
			if value.Type().Field(i).IsExported() {
				cloned.Field(i).Set(cloneTemplateValue(value.Field(i), visited))
			}
		}
		return cloned
	case reflect.Slice:
		if value.IsNil() {
			return reflect.Zero(value.Type())
		}
		visit := cloneVisit{
			typeOf:   value.Type(),
			pointer:  value.Pointer(),
			length:   value.Len(),
			capacity: value.Cap(),
		}
		if cloned, ok := visited[visit]; ok {
			return cloned
		}
		cloned := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
		visited[visit] = cloned
		for i := 0; i < value.Len(); i++ {
			cloned.Index(i).Set(cloneTemplateValue(value.Index(i), visited))
		}
		return cloned
	case reflect.Map:
		if value.IsNil() {
			return reflect.Zero(value.Type())
		}
		visit := cloneVisit{typeOf: value.Type(), pointer: value.Pointer()}
		if cloned, ok := visited[visit]; ok {
			return cloned
		}
		cloned := reflect.MakeMapWithSize(value.Type(), value.Len())
		visited[visit] = cloned
		iterator := value.MapRange()
		for iterator.Next() {
			key := cloneTemplateValue(iterator.Key(), visited)
			item := cloneTemplateValue(iterator.Value(), visited)
			cloned.SetMapIndex(key, item)
		}
		return cloned
	case reflect.Array:
		cloned := reflect.New(value.Type()).Elem()
		for i := 0; i < value.Len(); i++ {
			cloned.Index(i).Set(cloneTemplateValue(value.Index(i), visited))
		}
		return cloned
	default:
		return value
	}
}

