func TestParserLifecycle(t *testing.T) {
	t.Run("purge clears parsed and compiled caches", func(t *testing.T) {
		parser := NewParser()
		parser.Cache().Store("tpl-a", &Template{}, []byte("raw"), nil)
		parser.CompiledCache().Store("tpl-a", &Template{}, []byte("raw"), nil)

		require.Equal(t, 1, parser.ParsedCount())
		require.Equal(t, 1, parser.CompiledCount())
		parser.Purge()
		require.Zero(t, parser.ParsedCount())
		require.Zero(t, parser.CompiledCount())
	})

	t.Run("execution parser shares only parsed cache", func(t *testing.T) {
		parent := NewParser()
		parent.ShouldValidate = true
		parent.NoStrictSyntax = true
		parent.Cache().Store("parsed", &Template{}, []byte("raw"), nil)
		parent.CompiledCache().StoreWithoutRaw("parent-compiled", &Template{}, nil)

		execution := NewExecutionParser(parent)
		sibling := NewExecutionParser(parent)

		require.Same(t, parent.Cache(), execution.Cache())
		require.Same(t, parent.Cache(), sibling.Cache())
		require.NotSame(t, parent.CompiledCache(), execution.CompiledCache())
		require.NotSame(t, execution.CompiledCache(), sibling.CompiledCache())
		require.True(t, execution.ShouldValidate)
		require.True(t, execution.NoStrictSyntax)
		require.Equal(t, 1, execution.ParsedCount())
		require.Zero(t, execution.CompiledCount())

		execution.CompiledCache().StoreWithoutRaw("execution-compiled", &Template{}, nil)
		require.Equal(t, 1, execution.CompiledCount())
		require.Zero(t, sibling.CompiledCount())
		require.Equal(t, 1, parent.CompiledCount())
	})

	t.Run("purge compiled preserves shared parsed cache", func(t *testing.T) {
		parent := NewParser()
		parent.Cache().Store("parsed", &Template{}, []byte("raw"), nil)
		execution := NewExecutionParser(parent)
		execution.CompiledCache().StoreWithoutRaw("compiled", &Template{}, nil)

		execution.PurgeCompiled()

		require.Zero(t, execution.CompiledCount())
		require.Equal(t, 1, execution.ParsedCount())
		require.Equal(t, 1, parent.ParsedCount())
	})
}

func TestParseTemplateCoalescesConcurrentCacheMisses(t *testing.T) {
	const callers = 20
	cache := NewCache()
	catalog := &countingCatalog{}
	start := make(chan struct{})
	errs := make(chan error, callers)
	var wg sync.WaitGroup

	for range callers {
		parser := NewParserWithParsedCache(cache)
		wg.Add(1)
		go func(parser *Parser) {
			defer wg.Done()
			<-start
			_, err := parser.ParseTemplate("concurrent.yaml", catalog)
			errs <- err
		}(parser)
	}

	close(start)
	wg.Wait()
	close(errs)

	for err := range errs {
		require.NoError(t, err)
	}
	require.EqualValues(t, 1, catalog.reads.Load(), "one shared cache miss should read and parse the template once")
}

func TestLoadTemplate(t *testing.T) {
	catalog := disk.NewCatalog("")
	p := NewParser()

	tt := []struct {
		name        string
		template    *Template
		templateErr error
		filter      TagFilterConfig

		expectedErr error
		isValid     bool
	}{
		{
			name: "valid",
			template: &Template{
				ID: "CVE-2021-27330",
				Info: model.Info{
					Name:           "Valid template",
					Authors:        stringslice.StringSlice{Value: "Author"},
					SeverityHolder: severity.Holder{Severity: severity.Medium},
				},
			},
			isValid: true,
		},
		{
			name:        "emptyTemplate",
			template:    &Template{},
			isValid:     false,
			expectedErr: errors.New("cause=\"Could not load template emptyTemplate: cause=\\\"mandatory 'name' field is missing\\\"\\ncause=\\\"mandatory 'author' field is missing\\\"\\ncause=\\\"mandatory 'id' field is missing\\\"\""),
		},
		{
			name: "emptyNameWithInvalidID",
			template: &Template{
				ID: "invalid id",
				Info: model.Info{
					Authors:        stringslice.StringSlice{Value: "Author"},
					SeverityHolder: severity.Holder{Severity: severity.Medium},
				},
			},
			expectedErr: errors.New("cause=\"Could not load template emptyNameWithInvalidID: cause=\\\"mandatory 'name' field is missing\\\"\\ncause=\\\"invalid field format for 'id' (allowed format is ^([a-zA-Z0-9]+[-_])*[a-zA-Z0-9]+$)\\\"\""),
		},
		{
			name: "emptySeverity",
			template: &Template{
				ID: "CVE-2021-27330",
				Info: model.Info{
					Name:    "Valid template",
					Authors: stringslice.StringSlice{Value: "Author"},
				},
			},
			isValid:     true,
			expectedErr: errors.New("field 'severity' is missing"),
		},
		{
			name: "template-without-severity-with-correct-filter-id",
			template: &Template{
				ID: "CVE-2021-27330",
				Info: model.Info{
					Name:    "Valid template",
					Authors: stringslice.StringSlice{Value: "Author"},
				},
			},
			// should be error because the template is loaded
			expectedErr: errors.New("field 'severity' is missing"),
			isValid:     true,
			filter:      TagFilterConfig{IncludeIds: []string{"CVE-2021-27330"}},
		},
		{
			name: "template-without-severity-with-diff-filter-id",
			template: &Template{
				ID: "CVE-2021-27330",
				Info: model.Info{
					Name:    "Valid template",
					Authors: stringslice.StringSlice{Value: "Author"},
				},
			},
			isValid: false,
			filter:  TagFilterConfig{IncludeIds: []string{"another-id"}},
			// no error because the template is not loaded
			expectedErr: nil,
		},
	}

	for _, tc := range tt {
		t.Run(tc.name, func(t *testing.T) {
			p.parsedTemplatesCache.Store(tc.name, tc.template, nil, tc.templateErr)

			tagFilter, err := NewTagFilter(&tc.filter)
			require.Nil(t, err)
			success, err := p.LoadTemplate(tc.name, tagFilter, nil, catalog)
			if tc.expectedErr == nil {
				require.NoError(t, err)
			} else {
				require.ErrorContains(t, err, tc.expectedErr.Error())
			}
			require.Equal(t, tc.isValid, success)
		})
	}

	// Regression test for projectdiscovery/nuclei#7448.
	//
	// Templates loaded from JSON used to silently accept unknown fields because
	// [Template.UnmarshalJSON] delegated to a non-strict json.Unmarshal call.
	// That meant `-validate` would pass templates that contained typoed fields
	// or HTTP-only fields on a network.Request block, which then failed at
	// runtime with the unknown-field error. Strict mode is the default and
	// must be opt-out via the parser's [Parser.NoStrictSyntax] field (set
	// from the runner's `-no-strict-syntax` flag).
	t.Run("strictJSONRejectsUnknownFields", func(t *testing.T) {
		const tmpl = `{
  "id": "JSON-UNKNOWN-FIELD",
  "info": {
    "name": "strict json regression",
    "author": "anonymous",
    "severity": "info",
    "tags": "test"
  },
  "tcp": [{
    "host": ["{{Hostname}}"],
    "port": "80",
    "name": "first_read",
    "req-condition": true,
    "bogus_field_42": "anything",
    "inputs": [{"data": "X"}],
    "matchers": [{"type": "word", "words": ["HTTP"]}]
  }]
}`
		dir := t.TempDir()
		strictPath := filepath.Join(dir, "tmpl-strict.json")
		require.NoError(t, os.WriteFile(strictPath, []byte(tmpl), 0o600))

		// Strict mode (default): unknown fields must be rejected.
		strictParser := NewParser()
		_, err := strictParser.ParseTemplate(strictPath, disk.NewCatalog(""))
		require.Error(t, err, "expected strict JSON decode to reject unknown fields")
		require.Contains(t, err.Error(), "unknown field", "expected unknown-field error, got: %v", err)

		// Lax mode: when the parser opts out via NoStrictSyntax (set from the
		// `-no-strict-syntax` flag) the same template must still parse.
		laxParser := NewParser()
		laxParser.NoStrictSyntax = true
		laxPath := filepath.Join(dir, "tmpl-lax.json")
		require.NoError(t, os.WriteFile(laxPath, []byte(tmpl), 0o600))
		_, err = laxParser.ParseTemplate(laxPath, disk.NewCatalog(""))
		require.NoError(t, err, "NoStrictSyntax should allow unknown fields")
	})

	// json.Decoder by design only consumes one top-level value. Without an
	// explicit EOF check, concatenated JSON documents would silently load
	// only the first — e.g. `{"id":"safe"...}{"id":"hijack"...}` would scan
	// under the safe id while the second document is ignored.
	t.Run("strictJSONRejectsTrailingData", func(t *testing.T) {
		const tmpl = `{
  "id": "JSON-TRAILING-DATA",
  "info": {
    "name": "trailing data regression",
    "author": "anonymous",
    "severity": "info"
  },
  "http": [{
    "method": "GET",
    "path": ["{{BaseURL}}"],
    "matchers": [{"type": "word", "words": ["HTTP"]}]
  }]
}
{"id":"HIJACK","info":{"name":"x","author":"y","severity":"high"}}
`
		dir := t.TempDir()
		path := filepath.Join(dir, "tmpl.json")
		require.NoError(t, os.WriteFile(path, []byte(tmpl), 0o600))

		_, err := NewParser().ParseTemplate(path, disk.NewCatalog(""))
		require.Error(t, err, "expected strict JSON to reject trailing data")
		require.Contains(t, err.Error(), "trailing data", "expected trailing-data error, got: %v", err)
	})

	// Strictness is a per-parser setting (not a process global) so two
	// parsers in the same process with different `-no-strict-syntax` values
	// must not interfere with each other. Cf. concurrent-engines support
	// introduced in #6322.
	t.Run("strictJSONIsPerParser", func(t *testing.T) {
		const tmpl = `{
  "id": "JSON-PER-PARSER",
  "info": {
    "name": "per-parser strictness",
    "author": "anonymous",
    "severity": "info"
  },
  "http": [{
    "method": "GET",
    "path": ["{{BaseURL}}"],
    "matchers": [{"type": "word", "words": ["HTTP"]}],
    "bogus_field": "ignore me"
  }]
}`
		dir := t.TempDir()
		strictPath := filepath.Join(dir, "per-parser-strict.json")
		laxPath := filepath.Join(dir, "per-parser-lax.json")
		require.NoError(t, os.WriteFile(strictPath, []byte(tmpl), 0o600))
		require.NoError(t, os.WriteFile(laxPath, []byte(tmpl), 0o600))

		strictParser := NewParser()
		laxParser := NewParser()
		laxParser.NoStrictSyntax = true

		_, strictErr := strictParser.ParseTemplate(strictPath, disk.NewCatalog(""))
		_, laxErr := laxParser.ParseTemplate(laxPath, disk.NewCatalog(""))

		require.Error(t, strictErr, "strict parser must reject unknown field")
		require.Contains(t, strictErr.Error(), "unknown field")
		require.NoError(t, laxErr, "lax parser must accept the same template")
	})

	t.Run("strictYAMLRejectsUnknownFields", func(t *testing.T) {
		const tmpl = `id: yaml-unknown-field
info:
  name: strict yaml regression
  author: anonymous
  severity: info
http:
  - method: GET
    path:
      - "{{BaseURL}}"
    bogus_field: ignore me
    matchers:
      - type: word
        words:
          - HTTP
`
		dir := t.TempDir()
		strictPath := filepath.Join(dir, "tmpl-strict.yaml")
		laxPath := filepath.Join(dir, "tmpl-lax.yaml")
		require.NoError(t, os.WriteFile(strictPath, []byte(tmpl), 0o600))
		require.NoError(t, os.WriteFile(laxPath, []byte(tmpl), 0o600))

		_, strictErr := NewParser().ParseTemplate(strictPath, disk.NewCatalog(""))

		laxParser := NewParser()
		laxParser.NoStrictSyntax = true
		_, laxErr := laxParser.ParseTemplate(laxPath, disk.NewCatalog(""))

		require.Error(t, strictErr, "strict YAML decode must reject unknown fields")
		require.Contains(t, strictErr.Error(), "bogus_field")
		require.NoError(t, laxErr, "NoStrictSyntax should allow unknown YAML fields")
	})

	t.Run("strictYAMLRejectsDuplicateFields", func(t *testing.T) {
		const tmpl = `id: yaml-duplicate-field
id: yaml-duplicate-field-overwrite
info:
  name: duplicate yaml regression
  author: anonymous
  severity: info
http:
  - method: GET
    path:
      - "{{BaseURL}}"
    matchers:
      - type: word
        words:
          - HTTP
`
		dir := t.TempDir()
		path := filepath.Join(dir, "tmpl.yaml")
		require.NoError(t, os.WriteFile(path, []byte(tmpl), 0o600))

		_, err := NewParser().ParseTemplate(path, disk.NewCatalog(""))
		require.Error(t, err, "strict YAML decode must reject duplicate fields")
		require.Contains(t, err.Error(), "already")
	})

	t.Run("laxYAMLAllowsDuplicateFields", func(t *testing.T) {
		const tmpl = `id: yaml-duplicate-field
id: yaml-duplicate-field-overwrite
info:
  name: duplicate yaml regression
  author: anonymous
  severity: info
http:
  - method: GET
    path:
      - "{{BaseURL}}"
    matchers:
      - type: word
        words:
          - HTTP
`
		dir := t.TempDir()
		path := filepath.Join(dir, "tmpl.yaml")
		require.NoError(t, os.WriteFile(path, []byte(tmpl), 0o600))

		laxParser := NewParser()
		laxParser.NoStrictSyntax = true
		parsed, err := laxParser.ParseTemplate(path, disk.NewCatalog(""))
		require.NoError(t, err, "NoStrictSyntax should preserve yaml.v2 duplicate-field behavior")

		template, ok := parsed.(*Template)
		require.True(t, ok)
		require.Equal(t, "yaml-duplicate-field-overwrite", template.ID)
	})

	t.Run("YAMLPreservesMultiProtocolOrder", func(t *testing.T) {
		const tmpl = `id: yaml-protocol-order
info:
  name: protocol order regression
  author: anonymous
  severity: info
dns:
  - name: "{{FQDN}}"
    type: cname
http:
  - method: GET
    path:
      - "{{BaseURL}}"
    matchers:
      - type: word
        words:
          - HTTP
`
		dir := t.TempDir()
		path := filepath.Join(dir, "tmpl.yaml")
		require.NoError(t, os.WriteFile(path, []byte(tmpl), 0o600))

		parsed, err := NewParser().ParseTemplate(path, disk.NewCatalog(""))
		require.NoError(t, err)

		template, ok := parsed.(*Template)
		require.True(t, ok)
		require.Len(t, template.RequestsQueue, 2)
		require.Equal(t, "dns", template.RequestsQueue[0].Type().String())
		require.Equal(t, "http", template.RequestsQueue[1].Type().String())
	})

	t.Run("invalidTemplateID", func(t *testing.T) {
		tt := []struct {
			id      string
			success bool
		}{
			{id: "A-B-C", success: true},
			{id: "A-B-C-1", success: true},
			{id: "CVE_2021_27330", success: true},
			{id: "ABC DEF", success: false},
			{id: "_-__AAA_", success: false},
			{id: " CVE-2021-27330", success: false},
			{id: "CVE-2021-27330 ", success: false},
			{id: "CVE-2021-27330-", success: false},
			{id: "-CVE-2021-27330-", success: false},
			{id: "CVE-2021--27330", success: false},
			{id: "CVE-2021+27330", success: false},
		}
		for i, tc := range tt {
			name := fmt.Sprintf("regexp%d", i)
			t.Run(name, func(t *testing.T) {
				template := &Template{
					ID: tc.id,
					Info: model.Info{
						Name:           "Valid template",
						Authors:        stringslice.StringSlice{Value: "Author"},
						SeverityHolder: severity.Holder{Severity: severity.Medium},
					},
				}
				p.parsedTemplatesCache.Store(name, template, nil, nil)

				tagFilter, err := NewTagFilter(&TagFilterConfig{})
				require.Nil(t, err)
				success, err := p.LoadTemplate(name, tagFilter, nil, catalog)
				if tc.success {
					require.NoError(t, err)
					require.True(t, success)
				} else {
					require.ErrorContains(t, err, "invalid field format for 'id' (allowed format is ^([a-zA-Z0-9]+[-_])*[a-zA-Z0-9]+$)")
					require.False(t, success)
				}
			})
		}
	})
}

package templates

import (
	"errors"

	"github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils"
	"github.com/projectdiscovery/utils/errkit"
)

// validateTemplateMandatoryFields validates the mandatory fields of a template
// return error from this function will cause hard fail and not proceed further
func validateTemplateMandatoryFields(template *Template) error {
	info := template.Info

	var validateErrors []error

	if utils.IsBlank(info.Name) {
		validateErrors = append(validateErrors, errkit.Newf("mandatory '%s' field is missing", "name"))
	}

	if info.Authors.IsEmpty() {
		validateErrors = append(validateErrors, errkit.Newf("mandatory '%s' field is missing", "author"))
	}

	if template.ID == "" {
		validateErrors = append(validateErrors, errkit.Newf("mandatory '%s' field is missing", "id"))
	} else if !ReTemplateID.MatchString(template.ID) {
		validateErrors = append(validateErrors, errkit.Newf("invalid field format for '%s' (allowed format is %s)", "id", ReTemplateID.String()))
	}

	if len(validateErrors) > 0 {
		return errors.Join(validateErrors...)
	}

	return nil
}

func isTemplateInfoMetadataMatch(tagFilter *TagFilter, template *Template, extraTags []string) (bool, error) {
	match, err := tagFilter.Match(template, extraTags)

	if err == ErrExcluded {
		return false, ErrExcluded
	}

	return match, err
}

// validateTemplateOptionalFields validates the optional fields of a template
// return error from this function will throw a warning and proceed further
func validateTemplateOptionalFields(template *Template) error {
	info := template.Info

	var warnings []error

	if template.Type() != types.WorkflowProtocol && utils.IsBlank(info.SeverityHolder.Severity.String()) {
		warnings = append(warnings, errkit.Newf("field '%s' is missing", "severity"))
	}

	if len(warnings) > 0 {
		return errors.Join(warnings...)
	}

	return nil
}

package templates

import (
	"bytes"
	"regexp"
	"strings"

	stringsutil "github.com/projectdiscovery/utils/strings"
	"github.com/segmentio/ksuid"
)

type Preprocessor interface {
	// Process processes the data and returns the processed data.
	ProcessNReturnData(data []byte) ([]byte, map[string]interface{})
	// Exists check if the preprocessor exists in the data.
	Exists(data []byte) bool
}

var (
	preprocessorRegex    = regexp.MustCompile(`{{([a-z0-9_]+)}}`)
	defaultPreprocessors = []Preprocessor{
		&randStrPreprocessor{},
	}
)

func getPreprocessors(preprocessor Preprocessor) []Preprocessor {
	if preprocessor != nil {
		// append() function adds the elements to existing slice if space is available
		// else it creates a new slice and copies the elements to new slice
		// this may cause race-conditions hence we do it explicitly
		tmp := make([]Preprocessor, 0, len(defaultPreprocessors)+1)
		tmp = append(tmp, preprocessor)
		tmp = append(tmp, defaultPreprocessors...)
		return tmp
	}
	return defaultPreprocessors
}

var _ Preprocessor = &randStrPreprocessor{}

type randStrPreprocessor struct{}

// ProcessNReturnData processes the data and returns the key-value pairs of generated/replaced data.
func (r *randStrPreprocessor) ProcessNReturnData(data []byte) ([]byte, map[string]interface{}) {
	foundMap := make(map[string]struct{})
	dataMap := make(map[string]interface{})
	for _, expression := range preprocessorRegex.FindAllStringSubmatch(string(data), -1) {
		if len(expression) != 2 {
			continue
		}
		value := expression[1]
		if stringsutil.ContainsAny(value, "(", ")") {
			continue
		}

		if _, ok := foundMap[value]; ok {
			continue
		}
		foundMap[value] = struct{}{}
		if strings.EqualFold(value, "randstr") || strings.HasPrefix(value, "randstr_") {
			randStr := ksuid.New().String()
			data = bytes.ReplaceAll(data, []byte(expression[0]), []byte(randStr))
			dataMap[expression[0]] = randStr
		}
	}
	return data, dataMap
}

// Exists check if the preprocessor exists in the data.
func (r *randStrPreprocessor) Exists(data []byte) bool {
	return bytes.Contains(data, []byte("randstr"))
}

package signer

import (
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/keys"
	"github.com/projectdiscovery/utils/errkit"
)

// DefaultTemplateVerifiers contains the default template verifiers
var DefaultTemplateVerifiers []*TemplateSigner

func init() {
	h := &KeyHandler{
		UserCert: keys.NucleiCert,
	}
	if err := h.ParseUserCert(); err != nil {
		gologger.Error().Msgf("Could not parse pd nuclei certificate: %s\n", err)
		return
	}
	DefaultTemplateVerifiers = append(DefaultTemplateVerifiers, &TemplateSigner{handler: h})

	// try to load default user cert
	usr := &KeyHandler{}
	if err := usr.ReadCert(CertEnvVarName, config.DefaultConfig.GetKeysDir()); err == nil {
		if err := usr.ParseUserCert(); err != nil {
			gologger.Error().Msgf("malformed user cert found: %s\n", err)
			return
		}
		DefaultTemplateVerifiers = append(DefaultTemplateVerifiers, &TemplateSigner{handler: usr})
	}
}

// AddSignerToDefault adds a signer to the default list of signers
func AddSignerToDefault(s *TemplateSigner) error {
	if s == nil {
		return errkit.New("signer is nil")
	}
	DefaultTemplateVerifiers = append(DefaultTemplateVerifiers, s)
	return nil
}

package signer

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"fmt"
	"math/big"
	"os"
	"path/filepath"
	"time"

	"github.com/projectdiscovery/gologger"
	fileutil "github.com/projectdiscovery/utils/file"
	"github.com/rs/xid"
	"golang.org/x/term"
)

const (
	CertType           = "PD NUCLEI USER CERTIFICATE"
	PrivateKeyType     = "PD NUCLEI USER PRIVATE KEY"
	CertFilename       = "nuclei-user.crt"
	PrivateKeyFilename = "nuclei-user-private-key.pem"
	CertEnvVarName     = "NUCLEI_USER_CERTIFICATE"
	PrivateKeyEnvName  = "NUCLEI_USER_PRIVATE_KEY"
)

var (
	ErrNoCertificate   = fmt.Errorf("nuclei user certificate not found")
	ErrNoPrivateKey    = fmt.Errorf("nuclei user private key not found")
	SkipGeneratingKeys = false
	noUserPassphrase   = false
)

// KeyHandler handles the key generation and management
// of signer public and private keys
type KeyHandler struct {
	UserCert    []byte
	PrivateKey  []byte
	cert        *x509.Certificate
	ecdsaPubKey *ecdsa.PublicKey
	ecdsaKey    *ecdsa.PrivateKey
}

// ReadCert reads the user certificate from environment variable or given directory
func (k *KeyHandler) ReadCert(envName, dir string) error {
	// read from env
	if cert := k.getEnvContent(envName); cert != nil {
		k.UserCert = cert
		return nil
	}
	// read from disk
	if cert, err := os.ReadFile(filepath.Join(dir, CertFilename)); err == nil {
		k.UserCert = cert
		return nil
	}
	return ErrNoCertificate
}

// ReadPrivateKey reads the private key from environment variable or given directory
func (k *KeyHandler) ReadPrivateKey(envName, dir string) error {
	// read from env
	if privateKey := k.getEnvContent(envName); privateKey != nil {
		k.PrivateKey = privateKey
		return nil
	}
	// read from disk
	if privateKey, err := os.ReadFile(filepath.Join(dir, PrivateKeyFilename)); err == nil {
		k.PrivateKey = privateKey
		return nil
	}
	return ErrNoPrivateKey
}

// ParseUserCert parses the user certificate and returns the public key
func (k *KeyHandler) ParseUserCert() error {
	block, _ := pem.Decode(k.UserCert)
	if block == nil {
		return fmt.Errorf("failed to parse PEM block containing the certificate")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return err
	}
	if cert.Subject.CommonName == "" {
		return fmt.Errorf("invalid certificate: expected common name to be set")
	}
	k.cert = cert
	var ok bool
	k.ecdsaPubKey, ok = cert.PublicKey.(*ecdsa.PublicKey)
	if !ok {
		return fmt.Errorf("failed to parse ecdsa public key from cert")
	}
	return nil
}

// ParsePrivateKey parses the private key and returns the private key
func (k *KeyHandler) ParsePrivateKey() error {
	block, _ := pem.Decode(k.PrivateKey)
	if block == nil {
		return fmt.Errorf("failed to parse PEM block containing the private key")
	}
	// if pem block is encrypted , decrypt it
	if x509.IsEncryptedPEMBlock(block) { // nolint: all
		gologger.Info().Msgf("Private Key is encrypted with passphrase")
		fmt.Printf("[*] Enter passphrase (exit to abort): ")
		bin, err := term.ReadPassword(int(os.Stdin.Fd()))
		if err != nil {
			return err
		}
		fmt.Println()
		if string(bin) == "exit" {
			return fmt.Errorf("private key requires passphrase, but none was provided")
		}
		block.Bytes, err = x509.DecryptPEMBlock(block, bin) // nolint: all
		if err != nil {
			return err
		}
	}
	var err error
	k.ecdsaKey, err = x509.ParseECPrivateKey(block.Bytes)
	if err != nil {
		return err
	}
	return nil
}

// GenerateKeyPair generates a new key-pair for signing code templates
func (k *KeyHandler) GenerateKeyPair() {

	gologger.Info().Msgf("Generating new key-pair for signing templates")
	fmt.Printf("[*] Enter User/Organization Name (exit to abort) : ")

	// get user/organization name
	identifier := ""
	_, err := fmt.Scanln(&identifier)
	if err != nil {
		gologger.Fatal().Msgf("failed to read user/organization name: %s", err)
	}
	if identifier == "exit" {
		gologger.Fatal().Msgf("exiting key-pair generation")
	}
	if identifier == "" {
		gologger.Fatal().Msgf("user/organization name cannot be empty")
	}

	// generate new key-pair
	privateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		gologger.Fatal().Msgf("failed to generate ecdsa key-pair: %s", err)
	}

	// create x509 certificate with user/organization name and public key
	// self-signed certificate with generated private key
	k.UserCert, err = k.generateCertWithKey(identifier, privateKey)
	if err != nil {
		gologger.Fatal().Msgf("failed to create certificate: %s", err)
	}

	// marshal private key
	k.PrivateKey, err = k.marshalPrivateKey(privateKey)
	if err != nil {
		gologger.Fatal().Msgf("failed to marshal ecdsa private key: %s", err)
	}
	gologger.Info().Msgf("Successfully generated new key-pair for signing templates")
}

// SaveToDisk saves the generated key-pair to the given directory
func (k *KeyHandler) SaveToDisk(dir string) error {
	_ = fileutil.FixMissingDirs(filepath.Join(dir, CertFilename)) // not required but just in case will take care of missing dirs in path
	if err := os.WriteFile(filepath.Join(dir, CertFilename), k.UserCert, 0600); err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, PrivateKeyFilename), k.PrivateKey, 0600); err != nil {
		return err
	}
	return nil
}

// getEnvContent returns the content of the environment variable
// if it is a file then it loads its content
func (k *KeyHandler) getEnvContent(name string) []byte {
	val := os.Getenv(name)
	if val == "" {
		return nil
	}
	if fileutil.FileExists(val) {
		data, err := os.ReadFile(val)
		if err != nil {
			gologger.Fatal().Msgf("failed to read file: %s", err)
		}
		return data
	}
	return []byte(val)
}

// generateCertWithKey creates a self-signed certificate with the given identifier and private key
func (k *KeyHandler) generateCertWithKey(identifier string, privateKey *ecdsa.PrivateKey) ([]byte, error) {
	// Setting up the certificate
	notBefore := time.Now()
	notAfter := notBefore.Add(4 * 365 * 24 * time.Hour)

	serialNumber := big.NewInt(xid.New().Time().Unix())
	// create certificate template
	template := x509.Certificate{
		SerialNumber: serialNumber,
		Subject: pkix.Name{
			CommonName: identifier,
		},
		SignatureAlgorithm: x509.ECDSAWithSHA256,
		NotBefore:          notBefore,
		NotAfter:           notAfter,
		PublicKey:          &privateKey.PublicKey,
		KeyUsage:           x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{
			x509.ExtKeyUsageServerAuth,
		},
		IsCA:                  false,
		BasicConstraintsValid: true,
	}
	// Create the certificate
	derBytes, err := x509.CreateCertificate(rand.Reader, &template, &template, &privateKey.PublicKey, privateKey)
	if err != nil {
		return nil, err
	}

	var certOut bytes.Buffer
	if err := pem.Encode(&certOut, &pem.Block{Type: CertType, Bytes: derBytes}); err != nil {
		return nil, err
	}
	return certOut.Bytes(), nil
}

// marshalPrivateKey marshals the private key and encrypts it with the given passphrase
func (k *KeyHandler) marshalPrivateKey(privateKey *ecdsa.PrivateKey) ([]byte, error) {

	var passphrase []byte
	// get passphrase to encrypt private key before saving to disk
	if !noUserPassphrase {
		fmt.Printf("[*] Enter passphrase (exit to abort): ")
		passphrase = getPassphrase()
	}

	// marshal private key
	privateKeyData, err := x509.MarshalECPrivateKey(privateKey)
	if err != nil {
		gologger.Fatal().Msgf("failed to marshal ecdsa private key: %s", err)
	}
	//  pem encode keys
	pemBlock := &pem.Block{
		Type: PrivateKeyType, Bytes: privateKeyData,
	}
	// encrypt private key if passphrase is provided
	if len(passphrase) > 0 {
		// encode it with passphrase
		// this function is deprecated since go 1.16 but go stdlib does not want to provide any alternative
		// see: https://github.com/golang/go/issues/8860
		encBlock, err := x509.EncryptPEMBlock(rand.Reader, pemBlock.Type, pemBlock.Bytes, passphrase, x509.PEMCipherAES256) // nolint: all
		if err != nil {
			gologger.Fatal().Msgf("failed to encrypt private key: %s", err)
		}
		pemBlock = encBlock
	}
	return pem.EncodeToMemory(pemBlock), nil
}

func getPassphrase() []byte {
	bin, err := term.ReadPassword(int(os.Stdin.Fd()))
	if err != nil {
		gologger.Fatal().Msgf("could not read passphrase: %s", err)
	}
	fmt.Println()
	if string(bin) == "exit" {
		gologger.Fatal().Msgf("exiting")
	}
	fmt.Printf("[*] Enter same passphrase again: ")
	bin2, err := term.ReadPassword(int(os.Stdin.Fd()))
	if err != nil {
		gologger.Fatal().Msgf("could not read passphrase: %s", err)
	}
	fmt.Println()
	// review: should we allow empty passphrase?
	// we currently allow empty passphrase
	if string(bin) != string(bin2) {
		gologger.Fatal().Msgf("passphrase did not match try again")
	}
	return bin
}

package signer

import (
	"bytes"
	"os"
	"os/exec"
	"strings"
	"testing"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/gologger/levels"
)

// This Unit Test generates a new key pair and parses it
// to ensure that the key handler works as expected.
func TestKeyHandler(t *testing.T) {
	if val := os.Getenv("KEY_HANDLER_CI"); val != "1" {
		cmd := exec.Command(os.Args[0], "-test.run=^TestKeyHandler$", "-test.v")
		cmd.Env = append(cmd.Env, "KEY_HANDLER_CI=1")
		var buff bytes.Buffer
		cmd.Stdin = &buff
		buff.WriteString("CIUSER\n")
		buff.WriteString("\n")
		out, err := cmd.CombinedOutput()
		if !strings.Contains(string(out), "PASS\n") || err != nil {
			t.Fatalf("%s\n(exit status %v)", string(out), err)
		}
		return
	}
	gologger.DefaultLogger.SetMaxLevel(levels.LevelSilent)
	h := &KeyHandler{}
	noUserPassphrase = true
	h.GenerateKeyPair()
	if h.UserCert == nil {
		t.Fatal("no user cert found")
	}
	if h.PrivateKey == nil {
		t.Fatal("no private key found")
	}

	// now parse the cert and private key
	if err := h.ParseUserCert(); err != nil {
		t.Fatal(err)
	}
	if err := h.ParsePrivateKey(); err != nil {
		t.Fatal(err)
	}
	if h.ecdsaKey == nil {
		t.Fatal("no ecdsa key found")
	}
	if h.ecdsaPubKey == nil {
		t.Fatal("no ecdsa public key found")
	}
	if h.cert == nil {
		t.Fatal("no certificate found")
	}
	if h.cert.Subject.CommonName != "CIUSER" {
		t.Fatal("invalid user name found")
	}
}

package signer

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/md5"
	"crypto/rand"
	"crypto/sha256"
	"encoding/gob"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strings"
	"sync"

	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/utils/errkit"
)

var (
	ErrUnknownAlgorithm = errors.New("unknown algorithm")
	SignaturePattern    = "# digest: "
	SignatureFmt        = SignaturePattern + "%x" + ":%v" // `#digest: <signature>:<fragment>`
)

// ExtractSignatureAndContent extracts the signature (if present) and returns the content without the signature
func ExtractSignatureAndContent(data []byte) (signature, content []byte) {
	dataStr := string(data)
	if idx := strings.LastIndex(dataStr, SignaturePattern); idx != -1 {
		signature = []byte(strings.TrimSpace(dataStr[idx:]))
		content = bytes.TrimSpace(data[:idx])
	} else {
		content = data
	}
	content = bytes.TrimSpace(content)
	return signature, content
}

// SignableTemplate is a template that can be signed
type SignableTemplate interface {
	// GetFileImports returns a list of files that are imported by the template
	GetFileImports() []string
	// HasCodeProtocol returns true if the template has a code protocol section
	HasCodeProtocol() bool
}

type fileImportContentProvider interface {
	GetFileImportContents() ([][]byte, bool)
}

type javascriptSignableTemplate interface {
	HasJavascriptRequest(...int) bool
}

type TemplateSigner struct {
	sync.Once
	handler     *KeyHandler
	fragment    string
	fragmentErr error
}

// Identifier returns the identifier for the template signer
func (t *TemplateSigner) Identifier() string {
	return t.handler.cert.Subject.CommonName
}

// fragment is optional part of signature that is used to identify the user
// who signed the template via md5 hash of the public key x-coordinate
func (t *TemplateSigner) GetUserFragment() string {
	fragment, _ := t.userFragment()
	return fragment
}

func (t *TemplateSigner) userFragment() (string, error) {
	// wrap with sync.Once to reduce unnecessary md5 hashing
	t.Do(func() {
		t.fragment, t.fragmentErr = publicKeyFragment(t.handler.ecdsaPubKey)
	})
	return t.fragment, t.fragmentErr
}

func publicKeyFragment(publicKey *ecdsa.PublicKey) (string, error) {
	if publicKey == nil {
		return "", nil
	}
	publicKeyBytes, err := publicKey.Bytes()
	if err != nil {
		return "", fmt.Errorf("encode ecdsa public key: %w", err)
	}
	if len(publicKeyBytes) < 3 || publicKeyBytes[0] != 4 || (len(publicKeyBytes)-1)%2 != 0 {
		return "", fmt.Errorf("invalid uncompressed ecdsa public key")
	}
	xCoordinateLength := (len(publicKeyBytes) - 1) / 2
	// Keep the old fragment stable: big.Int.Bytes omitted leading zero bytes.
	xCoordinateBytes := bytes.TrimLeft(publicKeyBytes[1:1+xCoordinateLength], "\x00")
	hashed := md5.Sum(xCoordinateBytes)
	return fmt.Sprintf("%x", hashed), nil
}

// Sign signs the given template with the template signer and returns the signature
func (t *TemplateSigner) Sign(data []byte, tmpl SignableTemplate) (string, error) {
	existingSignature, content := ExtractSignatureAndContent(data)
	content = normalizeTemplateContentForSignature(content)

	// Executable templates can only be re-signed by the current signer.
	hasJavascript := false
	if javascriptTemplate, ok := tmpl.(javascriptSignableTemplate); ok {
		hasJavascript = javascriptTemplate.HasJavascriptRequest()
	}

	if tmpl.HasCodeProtocol() || hasJavascript {
		if len(existingSignature) > 0 {
			arr := strings.SplitN(string(existingSignature), ":", 3)
			if len(arr) == 2 {
				// signature has no fragment
				return "", errkit.New("re-signing executable templates are not allowed for security reasons.")
			}

			if len(arr) == 3 {
				// signature has fragment verify if it is equal to current fragment
				fragment, err := t.userFragment()
				if err != nil {
					return "", err
				}

				if fragment != arr[2] {
					return "", errkit.New("re-signing executable templates are not allowed for security reasons.")
				}
			}
		}
	}

	buff, err := templateContentWithImports(content, tmpl)
	if err != nil {
		return "", err
	}

	signatureData, err := t.sign(buff.Bytes())
	if err != nil {
		return "", err
	}

	return signatureData, nil
}

// Signs given data with the template signer
// Note: this should not be used for signing templates as file references
// in templates are not processed use template.SignTemplate() instead
func (t *TemplateSigner) sign(data []byte) (string, error) {
	dataHash := sha256.Sum256(data)

	ecdsaSignature, err := ecdsa.SignASN1(rand.Reader, t.handler.ecdsaKey, dataHash[:])
	if err != nil {
		return "", err
	}

	var signatureData bytes.Buffer
	if err := gob.NewEncoder(&signatureData).Encode(ecdsaSignature); err != nil {
		return "", err
	}

	fragment, err := t.userFragment()
	if err != nil {
		return "", err
	}

	return fmt.Sprintf(SignatureFmt, signatureData.Bytes(), fragment), nil
}

// Verify verifies the given template with the template signer
func (t *TemplateSigner) Verify(data []byte, tmpl SignableTemplate) (bool, error) {
	signature, content := ExtractSignatureAndContent(data)
	if len(signature) == 0 {
		return false, errors.New("no signature found")
	}

	if !bytes.HasPrefix(signature, []byte(SignaturePattern)) {
		return false, errors.New("signature must be at the end of the template")
	}

	digestData := bytes.TrimSpace(bytes.TrimPrefix(signature, []byte(SignaturePattern)))

	fragment, err := t.userFragment()
	if err != nil {
		return false, err
	}

	// remove fragment from digest as it is used for re-signing purposes only
	digestString := strings.TrimSuffix(string(digestData), ":"+fragment)

	digest, err := hex.DecodeString(digestString)
	if err != nil {
		return false, err
	}

	content = normalizeTemplateContentForSignature(content)

	buff, err := templateContentWithImports(content, tmpl)
	if err != nil {
		return false, err
	}

	return t.verify(buff.Bytes(), digest)
}

func templateContentWithImports(content []byte, tmpl SignableTemplate) (*bytes.Buffer, error) {
	buff := bytes.NewBuffer(content)
	imports := tmpl.GetFileImports()

	if provider, ok := tmpl.(fileImportContentProvider); ok {
		if importedContents, captured := provider.GetFileImportContents(); captured {
			if len(importedContents) != len(imports) {
				return nil, fmt.Errorf("imported-file content count does not match imported-file path count")
			}

			for _, importedContent := range importedContents {
				buff.WriteRune('\n')
				buff.Write(importedContent)
			}

			return buff, nil
		}
	}

	for _, file := range imports {
		bin, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}

		buff.WriteRune('\n')
		buff.Write(bin)
	}

	return buff, nil
}

// Fingerprint returns the SHA-256 fingerprint of the signer's public key.
func (t *TemplateSigner) Fingerprint() [sha256.Size]byte {
	if t == nil || t.handler == nil || t.handler.cert == nil {
		return [sha256.Size]byte{}
	}

	return sha256.Sum256(t.handler.cert.RawSubjectPublicKeyInfo)
}

func normalizeTemplateContentForSignature(content []byte) []byte {
	return bytes.ReplaceAll(content, []byte("\r\n"), []byte("\n"))
}

// Verify verifies the given data with the template signer
// Note: this should not be used for verifying templates as file references
// in templates are not processed
func (t *TemplateSigner) verify(data, signatureData []byte) (bool, error) {
	dataHash := sha256.Sum256(data)

	var signature []byte
	if err := gob.NewDecoder(bytes.NewReader(signatureData)).Decode(&signature); err != nil {
		return false, err
	}

	return ecdsa.VerifyASN1(t.handler.ecdsaPubKey, dataHash[:], signature), nil
}

// NewTemplateSigner creates a new signer for signing templates
func NewTemplateSigner(cert, privateKey []byte) (*TemplateSigner, error) {
	handler := &KeyHandler{}

	var err error

	if cert != nil || privateKey != nil {
		handler.UserCert = cert
		handler.PrivateKey = privateKey
	} else {
		err = handler.ReadCert(CertEnvVarName, config.DefaultConfig.GetKeysDir())
		if err == nil {
			err = handler.ReadPrivateKey(PrivateKeyEnvName, config.DefaultConfig.GetKeysDir())
		}
	}

	if err != nil && !SkipGeneratingKeys {
		if err != ErrNoCertificate && err != ErrNoPrivateKey {
			gologger.Info().Msgf("Invalid user cert found : %s\n", err)
		}

		// generating new keys
		handler.GenerateKeyPair()
		if err := handler.SaveToDisk(config.DefaultConfig.GetKeysDir()); err != nil {
			gologger.Fatal().Msgf("could not save generated keys to disk: %s\n", err)
		}

		// do not continue further let user re-run the command
		os.Exit(0)
	} else if err != nil && SkipGeneratingKeys {
		return nil, err
	}

	if err := handler.ParseUserCert(); err != nil {
		return nil, err
	}

	if err := handler.ParsePrivateKey(); err != nil {
		return nil, err
	}

	return &TemplateSigner{
		handler: handler,
	}, nil
}

// NewTemplateSignerFromFiles creates a new signer for signing templates
func NewTemplateSignerFromFiles(cert, privKey string) (*TemplateSigner, error) {
	certData, err := os.ReadFile(cert)
	if err != nil {
		return nil, err
	}

	privKeyData, err := os.ReadFile(privKey)
	if err != nil {
		return nil, err
	}

	return NewTemplateSigner(certData, privKeyData)
}

// NewTemplateSigVerifier creates a new signer for verifying templates
func NewTemplateSigVerifier(cert []byte) (*TemplateSigner, error) {
	handler := &KeyHandler{}
	if cert != nil {
		handler.UserCert = cert
	} else {
		if err := handler.ReadCert(CertEnvVarName, config.DefaultConfig.GetKeysDir()); err != nil {
			return nil, err
		}
	}

	if err := handler.ParseUserCert(); err != nil {
		return nil, err
	}

	return &TemplateSigner{
		handler: handler,
	}, nil
}

