		},
		{
			capability:   CapabilityCode,
			expectedStat: ExcludedCodeTemplateStats,
			expectedFlag: "-code",
			expectedKind: "code protocol",
		},
		{
			capability:   CapabilityDAST,
			expectedStat: ExcludedDASTTemplateStats,
			expectedFlag: "-dast",
			expectedKind: "DAST",
		},
		{
