	router.GET("/step3", func(w http.ResponseWriter, r *http.Request, _ httprouter.Params) {
		w.WriteHeader(http.StatusOK)
		_, _ = fmt.Fprint(w, "step3-ok")
	})
	return httptest.NewServer(router)
}

