	"github.com/projectdiscovery/nuclei/v3/pkg/tmplexec/utils"
	"github.com/projectdiscovery/utils/errkit"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

// contains all internal/unexported methods of flow

// requestExecutor executes a protocol/request and returns true if any matcher was found
func (f *FlowExecutor) requestExecutor(runtime *goja.Runtime, reqMap mapsutil.Map[string, protocols.Request], opts *ProtoOptions) bool {
	defer func() {
		// evaluate all variables after execution of each protocol
		scope := f.options.NewVariablesScope()
		f.options.AddTemplateCtxToVariablesScope(f.ctx.Input.MetaInput, scope)
		evaluation := f.options.Variables.EvaluateScope(scope)
		f.options.GetTemplateCtx(f.ctx.Input.MetaInput).Merge(evaluation.Values) // merge all variables into template context
		f.options.GetTemplateCtx(f.ctx.Input.MetaInput).MergeTemplateVariables(evaluation.TemplateValues)

		// to avoid polling update template variables everytime we execute a protocol
		m := f.options.GetTemplateCtx(f.ctx.Input.MetaInput).GetAll()
		_ = runtime.Set("template", m)
	}()
	matcherStatus := &atomic.Bool{} // due to interactsh matcher polling logic this needs to be atomic bool
	// if no id is passed execute all requests in sequence
	if len(opts.reqIDS) == 0 {
		// execution logic for http()/dns() etc
		for index := range f.allProtocols[opts.protoName] {
			req := f.allProtocols[opts.protoName][index]
			// transform input if required
			inputItem := f.ctx.Input.Clone()
			if f.options.InputHelper != nil && f.ctx.Input.MetaInput.Input != "" && !utils.HasOfflineHTTPResponse(f.ctx.Input.MetaInput, req.Type()) {
				if inputItem.MetaInput.Input = f.options.InputHelper.TransformPinned(inputItem.MetaInput.Input, inputItem.MetaInput.CustomIP, req.Type()); inputItem.MetaInput.Input == "" {
					f.ctx.LogError(fmt.Errorf("failed to transform input for protocol %s", req.Type()))
					return false
				}
			}
			err := req.ExecuteWithResults(inputItem, output.InternalEvent(f.options.GetTemplateCtx(f.ctx.Input.MetaInput).GetAll()), output.InternalEvent{}, f.protocolResultCallback(req, matcherStatus, opts))
			f.executions[req].Add(1)

			if f.logUnresponsiveSkip(err) {
				continue
			}
			if err != nil {
				// save all errors in a map with id as key
				// its less likely that there will be race condition but just in case
				id := req.GetID()
				if id == "" {
					id, _ = reqMap.GetKeyWithValue(req)
				}
				err = f.allErrs.Set(opts.protoName+":"+id, err)
				if err != nil {
					f.ctx.LogError(fmt.Errorf("failed to store flow runtime errors got %v", err))
				}
				return matcherStatus.Load()
			}
		}
		return matcherStatus.Load()
	}

	// execution logic for http("0") or http("get-aws-vpcs")
	for _, id := range opts.reqIDS {
		req, ok := reqMap[id]
		if !ok {
			f.ctx.LogError(fmt.Errorf("[%v] invalid request id '%s' provided", f.options.TemplateID, id))
			// compile error
			if err := f.allErrs.Set(opts.protoName+":"+id, errkit.Newf("[%s] invalid request id '%s' provided", f.options.TemplateID, id)); err != nil {
				f.ctx.LogError(fmt.Errorf("failed to store flow runtime errors got %v", err))
			}
			return matcherStatus.Load()
		}
		// transform input if required
		inputItem := f.ctx.Input.Clone()
		if f.options.InputHelper != nil && f.ctx.Input.MetaInput.Input != "" && !utils.HasOfflineHTTPResponse(f.ctx.Input.MetaInput, req.Type()) {
			if inputItem.MetaInput.Input = f.options.InputHelper.TransformPinned(inputItem.MetaInput.Input, inputItem.MetaInput.CustomIP, req.Type()); inputItem.MetaInput.Input == "" {
				f.ctx.LogError(fmt.Errorf("failed to transform input for protocol %s", req.Type()))
				return false
			}
		}
		err := req.ExecuteWithResults(inputItem, output.InternalEvent(f.options.GetTemplateCtx(f.ctx.Input.MetaInput).GetAll()), output.InternalEvent{}, f.protocolResultCallback(req, matcherStatus, opts))
		f.executions[req].Add(1)

		if f.logUnresponsiveSkip(err) {
			continue
		}
		if err != nil {
			index := id
			err = f.allErrs.Set(opts.protoName+":"+index, err)
			if err != nil {
				f.ctx.LogError(fmt.Errorf("failed to store flow runtime errors got %v", err))
			}
		}
	}
	return matcherStatus.Load()
}

// logUnresponsiveSkip logs err on the scan and returns true when it says a
// request was not sent because its address is unresponsive. That is no failure
// of the flow: the event reports it, and the engine has no error to warn about,
// as for a target it skips itself.
func (f *FlowExecutor) logUnresponsiveSkip(err error) bool {
	if !errors.Is(err, hosterrorscache.ErrUnresponsiveHost) {
		return false
	}

	f.ctx.LogError(err)

	return true
}

// protocolResultCallback returns a callback that is executed
// after execution of each protocol request
func (f *FlowExecutor) protocolResultCallback(req protocols.Request, matcherStatus *atomic.Bool, _ *ProtoOptions) func(result *output.InternalWrappedEvent) {
	return func(result *output.InternalWrappedEvent) {
		if result != nil {
			// Note: flow specific implicit behaviours should be handled here
			// before logging the event
			f.ctx.LogEvent(result)
			// export dynamic values from operators (i.e internal:true)
			// add add it to template context
			// this is a conflicting behaviour with iterate-all
			if result.HasOperatorResult() {
				f.results.CompareAndSwap(false, true)
				// this is to handle case where there is any operator result (matcher or extractor)
				matcherStatus.CompareAndSwap(false, result.OperatorsResult.Matched)
				if !result.OperatorsResult.Matched && !hasMatchers(req.GetCompiledOperators()) {
					// if matcher status is false . check if template/request contains any matcher at all
					// if it does then we need to set matcher status to true
					matcherStatus.CompareAndSwap(false, true)
				}
				if len(result.OperatorsResult.DynamicValues) > 0 {
					for k, v := range result.OperatorsResult.DynamicValues {
						// if length of v is 1 then remove slice and convert it to single value
						if len(v) == 1 {
							// add it to flatten keys list so it will be flattened to a string later
							f.flattenKeys = append(f.flattenKeys, k)
							// flatten and convert it to string
							f.options.GetTemplateCtx(f.ctx.Input.MetaInput).Set(k, v[0])
						} else {
							// keep it as slice
							f.options.GetTemplateCtx(f.ctx.Input.MetaInput).Set(k, v)
						}
					}
				}
			} else if !result.HasOperatorResult() && !hasOperators(req.GetCompiledOperators()) {
				// this is to handle case where there are no operator result and there was no matcher in operators
				// if matcher status is false . check if template/request contains any matcher at all
				// if it does then we need to set matcher status to true
				matcherStatus.CompareAndSwap(false, true)
			}
		}
	}
}

package flow

import "github.com/projectdiscovery/nuclei/v3/pkg/operators"

// Checks if template has matchers
func hasMatchers(all []*operators.Operators) bool {
	for _, operator := range all {
		if operator != nil && len(operator.Matchers) > 0 {
			return true
		}
	}
	return false
}

// hasOperators checks if template has operators (i.e matchers/extractors)
func hasOperators(all []*operators.Operators) bool {
	for _, operator := range all {
		if operator != nil {
			return true
		}
	}
	return false
}

func flatten(v interface{}) interface{} {
	switch v := v.(type) {
	case []interface{}:
		if len(v) == 1 {
			return v[0]
		}
		return v
	case []string:
		if len(v) == 1 {
			return v[0]
		}
		return v
	default:
		return v
	}
}

package flow

import (
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/stretchr/testify/require"
)

func TestHasMatchersPanicRegression(t *testing.T) {
	// This test ensures that hasMatchers does not panic when passed a slice containing nil.
	// This was the source of a reported panic when a request had no local operators.

	require.NotPanics(t, func() {
		all := []*operators.Operators{nil}
		result := hasMatchers(all)
		require.False(t, result)
	}, "hasMatchers should not panic with nil element in slice")

	require.NotPanics(t, func() {
		all := []*operators.Operators{nil, {}}
		result := hasMatchers(all)
		require.False(t, result)
	}, "hasMatchers should not panic with mix of nil and empty operators")
}

func TestHasOperatorsPanicRegression(t *testing.T) {
	// Also ensure hasOperators is safe
	require.NotPanics(t, func() {
		all := []*operators.Operators{nil}
		result := hasOperators(all)
		require.False(t, result)
	}, "hasOperators should not panic with nil element in slice")
}

package flow

import (
	"context"
	"reflect"
	"sync"

	"github.com/logrusorgru/aurora/v4"
	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/gologger"
	"github.com/projectdiscovery/nuclei/v3/pkg/js/gojs"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/protocolstate"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols/common/utils/vardump"
	"github.com/projectdiscovery/nuclei/v3/pkg/tmplexec/flow/builtin"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/projectdiscovery/utils/sync/sizedpool"
)

var jsOnce sync.Once

// createNewRuntime creates a fresh clean JS runtime with registered builtins
func createNewRuntime() *goja.Runtime {
	runtime := protocolstate.NewJSRuntime()
	registerBuiltins(runtime)
	return runtime
}

// js runtime pool using sync.Pool
var gojapool = &sync.Pool{
	New: func() interface{} {
		return createNewRuntime()
	},
}

var sizedgojapool *sizedpool.SizedPool[*goja.Runtime]

// GetJSRuntime returns a JS runtime from the process-global pool.
//
// Deprecated: GetJSRuntime ignores cancellation and can block until another
// scan releases a runtime. Use GetJSRuntimeContext.
func GetJSRuntime(opts *types.Options) *goja.Runtime {
	runtime, _ := GetJSRuntimeContext(context.TODO(), opts)
	return runtime
}

// GetJSRuntimeContext returns a JS runtime from the process-global pool.
//
// A runtime stays checked out for as long as the flow runs, including any wait
// on the rate limiter, so this can block once the pool is saturated. The
// context lets a cancelled scan stop waiting for a runtime it will not use.
func GetJSRuntimeContext(ctx context.Context, opts *types.Options) (*goja.Runtime, error) {
	jsOnce.Do(func() {
		if opts.JsConcurrency < 100 {
			opts.JsConcurrency = 100
		}
		sizedgojapool, _ = sizedpool.New(
			sizedpool.WithPool[*goja.Runtime](gojapool),
			sizedpool.WithSize[*goja.Runtime](int64(opts.JsConcurrency)),
		)
	})
	return sizedgojapool.Get(ctx)
}

// PutJSRuntime returns a JS runtime to pool.
// When reuse is false, a brand new clean runtime is replenished to avoid leaking globals.
func PutJSRuntime(runtime *goja.Runtime, reuse bool) {
	if reuse {
		sizedgojapool.Put(runtime)
	} else {
		sizedgojapool.Put(createNewRuntime())
	}
}

func registerBuiltins(runtime *goja.Runtime) {
	_ = gojs.RegisterFuncWithSignature(runtime, gojs.FuncOpts{
		Name:        "log",
		Description: "Logs a given object/message to stdout (only for debugging purposes)",
		Signatures: []string{
			"log(obj any) any",
		},
		FuncDecl: func(call goja.FunctionCall) goja.Value {
			arg := call.Argument(0).Export()
			switch value := arg.(type) {
			case string:
				gologger.DefaultLogger.Print().Msgf("[%v] %v", aurora.BrightCyan("JS"), value)
			case map[string]interface{}:
				gologger.DefaultLogger.Print().Msgf("[%v] %v", aurora.BrightCyan("JS"), vardump.DumpVariables(value))
			default:
				gologger.DefaultLogger.Print().Msgf("[%v] %v", aurora.BrightCyan("JS"), value)
			}
			return call.Argument(0) // return the same value
		},
	})

	_ = gojs.RegisterFuncWithSignature(runtime, gojs.FuncOpts{
		Name:        "iterate",
		Description: "Normalizes and Iterates over all arguments (can be a string,array,null etc) and returns an array of objects\nNote: If the object type is unknown(i.e could be a string or array) iterate should be used and it will always return an array of strings",
		Signatures: []string{
			"iterate(...any) []any",
		},
		FuncDecl: func(call goja.FunctionCall) goja.Value {
			allVars := []any{}
			for _, v := range call.Arguments {
				if v.Export() == nil {
					continue
				}
				if v.ExportType().Kind() == reflect.Slice {
					// convert []datatype to []interface{}
					// since it cannot be type asserted to []interface{} directly
					rfValue := reflect.ValueOf(v.Export())
					for i := 0; i < rfValue.Len(); i++ {
						allVars = append(allVars, rfValue.Index(i).Interface())
					}
				} else {
					allVars = append(allVars, v.Export())
				}
			}
			return runtime.ToValue(allVars)
		},
	})

	_ = gojs.RegisterFuncWithSignature(runtime, gojs.FuncOpts{
		Name:        "Dedupe",
		Description: "De-duplicates given values and returns a new array of unique values",
		Signatures: []string{
			"new Dedupe()",
		},
		FuncDecl: func(call goja.ConstructorCall) *goja.Object {
			d := builtin.NewDedupe(runtime)
			obj := call.This
			// register these methods
			_ = obj.Set("Add", d.Add)
			_ = obj.Set("Values", d.Values)
			return nil
		},
	})

}

package flow_test

import (
	"context"
	"testing"
	"time"

	"github.com/projectdiscovery/goja"
	"github.com/projectdiscovery/nuclei/v3/pkg/tmplexec/flow"
	"github.com/projectdiscovery/nuclei/v3/pkg/types"
	"github.com/stretchr/testify/require"
)

// TestGetJSRuntimeHonoursContext covers what made a saturated pool fatal rather than slow.
//
// The pool is shared by every scan in the process, and a runtime stays checked out for the
// whole flow, including any wait on the rate limiter. Once it is saturated, an acquire that
// ignored the context left a scan that had already been cancelled queueing for a runtime it
// only needed in order to unwind, unable to leave until an unrelated scan finished.
func TestGetJSRuntimeHonoursContext(t *testing.T) {
	opts := &types.Options{JsConcurrency: 100}

	runtime, err := flow.GetJSRuntimeContext(context.Background(), opts)
	require.NoError(t, err, "a live scan still gets a runtime")
	flow.PutJSRuntime(runtime, true)

	// Acquire reports a cancelled context before it looks at whether a slot is free, so this
	// holds whether the pool is saturated or idle.
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, err = flow.GetJSRuntimeContext(ctx, opts)
	require.Error(t, err, "a cancelled scan must not queue for a runtime it will never use")
}

func TestGetJSRuntimeDeprecatedSignatureStillWorks(t *testing.T) {
	opts := &types.Options{JsConcurrency: 100}
	runtime := flow.GetJSRuntime(opts)
	require.NotNil(t, runtime)
	flow.PutJSRuntime(runtime, true)
}

func TestGetJSRuntimeUnblocksCancelledAcquireWhenPoolIsFull(t *testing.T) {
	opts := &types.Options{JsConcurrency: 100}
	held := make([]*goja.Runtime, 0, 100)
	t.Cleanup(func() {
		for _, runtime := range held {
			flow.PutJSRuntime(runtime, true)
		}
	})
	for i := 0; i < 100; i++ {
		runtime, err := flow.GetJSRuntimeContext(context.Background(), opts)
		require.NoError(t, err)
		held = append(held, runtime)
	}

	start := time.Now()
	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() {
		_, err := flow.GetJSRuntimeContext(ctx, opts)
		done <- err
	}()

	select {
	case err := <-done:
		t.Fatalf("acquire returned before cancel: %v", err)
	case <-time.After(50 * time.Millisecond):
	}
	cancel()

	select {
	case err := <-done:
		require.Error(t, err)
		require.Less(t, time.Since(start), 200*time.Millisecond)
	case <-time.After(200 * time.Millisecond):
		t.Fatal("blocked acquire did not return after cancel")
	}
}
func TestPutJSRuntimeReplenishesCleanRuntime(t *testing.T) {
	opts := &types.Options{JsConcurrency: 100}

	var held []*goja.Runtime
	for len(held) < 100 {
		ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
		runtime, err := flow.GetJSRuntimeContext(ctx, opts)
		cancel()
		if err != nil {
			break
		}
		_, err = runtime.RunString("globalThis.leakedGlobal = 'tainted';")
		require.NoError(t, err)
		held = append(held, runtime)
	}
	require.NotEmpty(t, held)

	tainted := make(map[*goja.Runtime]struct{}, len(held))
	for _, runtime := range held {
		tainted[runtime] = struct{}{}
		flow.PutJSRuntime(runtime, false)
	}

	for i := 0; i < len(held); i++ {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		runtime, err := flow.GetJSRuntimeContext(ctx, opts)
		cancel()
		require.NoError(t, err)
		_, reused := tainted[runtime]
		require.False(t, reused, "tainted runtime was returned to the pool")
		require.Nil(t, runtime.Get("leakedGlobal"))
		flow.PutJSRuntime(runtime, false)
	}
}

package generic

//nolint:depguard // No depguard rules are configured, so its default list allows only the standard library.
import (
	"sync/atomic"

	"github.com/projectdiscovery/nuclei/v3/pkg/output"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	"github.com/projectdiscovery/nuclei/v3/pkg/scan"
	"github.com/projectdiscovery/nuclei/v3/pkg/tmplexec/utils"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

// generic engine as name suggests is a generic template
// execution engine and executes all requests one after another
// without any logic in between
type Generic struct {
	requests []protocols.Request
	options  *protocols.ExecutorOptions
	results  *atomic.Bool
}

// NewGenericEngine creates a new generic engine from a list of requests
func NewGenericEngine(requests []protocols.Request, options *protocols.ExecutorOptions, results *atomic.Bool) *Generic {
	if results == nil {
		results = &atomic.Bool{}
	}
	return &Generic{requests: requests, options: options, results: results}
}

// Compile engine specific compilation
func (g *Generic) Compile() error {
	// protocol/ request is already handled by template executer
	return nil
}

// ExecuteWithResults executes the template and returns results
func (g *Generic) ExecuteWithResults(ctx *scan.ScanContext) error {
	dynamicValues := make(map[string]interface{})
	if ctx.Input.HasArgs() {
		ctx.Input.ForEach(func(key string, value interface{}) {
			dynamicValues[key] = value
		})
	}
	previous := mapsutil.NewSyncLockMap[string, any]()

	for _, req := range g.requests {
		select {
		case <-ctx.Context().Done():
			return ctx.Context().Err()
		default:
		}

		inputItem := ctx.Input.Clone()
		if g.options.InputHelper != nil && ctx.Input.MetaInput.Input != "" && !utils.HasOfflineHTTPResponse(ctx.Input.MetaInput, req.Type()) {
			if inputItem.MetaInput.Input = g.options.InputHelper.TransformPinned(inputItem.MetaInput.Input, inputItem.MetaInput.CustomIP, req.Type()); inputItem.MetaInput.Input == "" {
				return nil
			}
		}

		err := req.ExecuteWithResults(inputItem, dynamicValues, output.InternalEvent(previous.GetAll()), func(event *output.InternalWrappedEvent) {
			// this callback is not concurrent safe so mutex should be used to synchronize
			if event == nil {
				// ideally this should never happen since protocol exits on error and callback is not called
				return
			}

			utils.FillPreviousEvent(req.GetID(), event, previous)

			if event.HasOperatorResult() {
				g.results.CompareAndSwap(false, true)
			}
			// for ExecuteWithResults : this callback will execute user defined callback and some error handling
			// for Execute : this callback will print the result to output
			ctx.LogEvent(event)
		})
		if err != nil {
			utils.LogRequestError(ctx, g.options.TemplateID, err)
		}
		// If a match was found and stop at first match is set, break out of the loop and return
		if g.results.Load() && (g.options.StopAtFirstMatch || g.options.Options.StopAtFirstMatch) {
			break
		}
	}
	return nil
}

// Type returns the type of engine
func (g *Generic) Name() string {
	return "generic"
}

