// DefaultResumeFileName is the default filename for the resume file.
const (
	DefaultResumeFileName      = "resume-%s.cfg"
	defaultCrashResumeFileName = "crash-resume-file-%s.dump"
)

func DefaultResumeFilePath() string {
	stateDir := config.DefaultConfig.GetStateDir()
	resumeFile := filepath.Join(stateDir, fmt.Sprintf(DefaultResumeFileName, xid.New().String()))

	return resumeFile
}

// DefaultCrashResumeFilePath returns the generated crash checkpoint path.
func DefaultCrashResumeFilePath(id string) string {
	return filepath.Join(config.DefaultConfig.GetStateDir(), fmt.Sprintf(defaultCrashResumeFileName, id))
}

// ResumeCfg contains the scan progression
type ResumeCfg struct {
	sync.RWMutex
	ResumeFrom map[string]*ResumeInfo `json:"resumeFrom"`
	Current    map[string]*ResumeInfo `json:"-"`
}

type ResumeInfo struct {
	sync.RWMutex
	Completed bool                `json:"completed"`
	InFlight  map[uint32]struct{} `json:"inFlight"`
	SkipUnder uint32              `json:"-"`
	Repeat    map[uint32]struct{} `json:"-"`
	DoAbove   uint32              `json:"-"`
}

func (resumeInfo *ResumeInfo) IsCompleted() bool {
	resumeInfo.RLock()
	defer resumeInfo.RUnlock()
	return resumeInfo.Completed
}

func (resumeInfo *ResumeInfo) GetSkipUnder() uint32 {
	resumeInfo.RLock()
	defer resumeInfo.RUnlock()
	return resumeInfo.SkipUnder
}

func (resumeInfo *ResumeInfo) GetDoAbove() uint32 {
	resumeInfo.RLock()
	defer resumeInfo.RUnlock()
	return resumeInfo.DoAbove
}

func (resumeInfo *ResumeInfo) InitInFlight() {
	resumeInfo.Lock()
	defer resumeInfo.Unlock()
	if resumeInfo.InFlight == nil {
		resumeInfo.InFlight = make(map[uint32]struct{})
	}
}

func (resumeInfo *ResumeInfo) IsInFlight(index uint32) bool {
	resumeInfo.RLock()
	defer resumeInfo.RUnlock()
	_, ok := resumeInfo.InFlight[index]
	return ok
}

// Clone the ResumeInfo structure
func (resumeInfo *ResumeInfo) Clone() *ResumeInfo {
	resumeInfo.Lock()
	defer resumeInfo.Unlock()

	inFlight := make(map[uint32]struct{})
	for u := range resumeInfo.InFlight {
		inFlight[u] = struct{}{}
	}
	repeat := make(map[uint32]struct{})
	for u := range resumeInfo.Repeat {
		repeat[u] = struct{}{}
	}

	return &ResumeInfo{
		Completed: resumeInfo.Completed,
		InFlight:  inFlight,
		SkipUnder: resumeInfo.SkipUnder,
		Repeat:    repeat,
		DoAbove:   resumeInfo.DoAbove,
	}
}

// NewResumeCfg creates a new scan progression structure
func NewResumeCfg() *ResumeCfg {
	return &ResumeCfg{
		ResumeFrom: make(map[string]*ResumeInfo),
		Current:    make(map[string]*ResumeInfo),
	}
}

// Clone the resume structure
func (resumeCfg *ResumeCfg) Clone() *ResumeCfg {
	resumeCfg.Lock()
	defer resumeCfg.Unlock()

	resumeFrom := make(map[string]*ResumeInfo)
	for id, resumeInfo := range resumeCfg.ResumeFrom {
		resumeFrom[id] = resumeInfo.Clone()
	}
	current := make(map[string]*ResumeInfo)
	for id, resumeInfo := range resumeCfg.Current {
		current[id] = resumeInfo.Clone()
	}

	return &ResumeCfg{
		ResumeFrom: resumeFrom,
		Current:    current,
	}
}

// Snapshot returns a copy of the progress for a resume file, which saves only
// ResumeFrom.
//
// A template keeps the entry that the scan loaded when the scan did nothing
// that supersedes it: it never started the template, or it started it but has
// no target in flight and hasn't completed it, as when an interrupt arrives
// while the scan still skips the targets that the loaded entry marks as done.
// A Current entry with nothing in flight says only "run from the first target",
// which is less than the loaded entry knows. Any other Current entry wins.
func (resumeCfg *ResumeCfg) Snapshot() *ResumeCfg {
	snapshot := resumeCfg.Clone()

	for id, current := range snapshot.Current {
		if _, loaded := snapshot.ResumeFrom[id]; loaded && !current.Completed && len(current.InFlight) == 0 {
			continue
		}

		snapshot.ResumeFrom[id] = current
	}

	return snapshot
}

// Clone the resume structure
func (resumeCfg *ResumeCfg) Compile() {
	resumeCfg.Lock()
	defer resumeCfg.Unlock()

	for _, resumeInfo := range resumeCfg.ResumeFrom {
		if resumeInfo.Completed && len(resumeInfo.InFlight) > 0 {
			resumeInfo.InFlight = make(map[uint32]struct{})
		}
		min := uint32(math.MaxUint32)
		max := uint32(0)
		for index := range resumeInfo.InFlight {
			if index < min {
				min = index
			}
			if index > max {
				max = index
			}
		}
		// maybe redundant but ensures we track the indexes to be repeated
		resumeInfo.Repeat = map[uint32]struct{}{}
		for index := range resumeInfo.InFlight {
			resumeInfo.Repeat[index] = struct{}{}
		}
		resumeInfo.SkipUnder = min
		// An interrupt can find a started template with no target in flight, such
		// as between two targets. Then the file doesn't say how far the scan got,
		// and skipping every target would lose the ones it never reached.
		if len(resumeInfo.InFlight) == 0 {
			resumeInfo.SkipUnder = 0
		}
		resumeInfo.DoAbove = max
	}
}

package types

import (
