func TestDetermineSchemeOrder(t *testing.T) {
	type testCase struct {
		input    string
		expected []string
	}

	tests := []testCase{
		// No port or uncommon ports should return https first
		{"example.com", []string{"https", "http"}},
		{"example.com:443", []string{"https", "http"}},
		{"127.0.0.1", []string{"https", "http"}},
		{"[fe80::1]:443", []string{"https", "http"}},
		// Common HTTP ports should return http first
		{"example.com:80", []string{"http", "https"}},
		{"example.com:8080", []string{"http", "https"}},
		{"127.0.0.1:80", []string{"http", "https"}},
		{"127.0.0.1:8080", []string{"http", "https"}},
		{"fe80::1", []string{"https", "http"}},
		{"[fe80::1]:80", []string{"http", "https"}},
		{"[fe80::1]:8080", []string{"http", "https"}},
	}

	for _, tc := range tests {
		t.Run(tc.input, func(t *testing.T) {
			actual := DetermineSchemeOrder(tc.input)
			require.Equal(t, tc.expected, actual)
		})
	}
}

func TestDetermineSchemeOrderWithHighPorts(t *testing.T) {
	type testCase struct {
		input    string
		expected []string
	}

	tests := []testCase{
		// Ports > 1024 should return http first
		{"example.com:2048", []string{"http", "https"}},
		{"example.com:8081", []string{"http", "https"}},
		{"[fe80::1]:2048", []string{"http", "https"}},
		{"[fe80::1]:12345", []string{"http", "https"}},
	}

	for _, tc := range tests {
		t.Run(tc.input, func(t *testing.T) {
			actual := DetermineSchemeOrder(tc.input)
			require.Equal(t, tc.expected, actual)
		})
	}
}

func TestDetermineSchemeOrderAmbiguousIPv6Literal(t *testing.T) {
	tests := []struct {
		input    string
		expected []string
	}{
		{"::1:8065", []string{"https", "http"}},
		{"[::1]:8065", []string{"http", "https"}},
	}

	for _, tc := range tests {
		t.Run(tc.input, func(t *testing.T) {
			actual := DetermineSchemeOrder(normalizeProbeInput(tc.input))
			require.Equal(t, tc.expected, actual)
		})
	}
}

func TestNormalizeProbeInput(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{"::1:8065", "[::1:8065]"},
		{"fe80::1", "[fe80::1]"},
		{"[::1]:8065", "[::1]:8065"},
		{"127.0.0.1:8080", "127.0.0.1:8080"},
		{"example.com:443", "example.com:443"},
	}

	for _, tc := range tests {
		t.Run(tc.input, func(t *testing.T) {
			actual := normalizeProbeInput(tc.input)
			require.Equal(t, tc.expected, actual)
		})
	}
}

// Package httpbody provides a zero-copy, rewinding request body.
//
// retryablehttp's ReusableReadCloser tees every read into a second growing
// buffer and clones the body on every GetBody call, which multiplies the
// memory of large request bodies several times over. Body reads directly
// from one immutable slice instead, and GetBody hands out independent
// cursors over that same slice.
package httpbody

import (
	"io"
	"sync"

	"github.com/projectdiscovery/retryablehttp-go"
	convUtil "github.com/projectdiscovery/utils/conversion"
)

// Body is a request body over an immutable byte slice. Like
// ReusableReadCloser, it rewinds to the start once it returns io.EOF, since
// the retryablehttp retry loop resends the same req.Body without rewinding.
type Body struct {
	mu   sync.Mutex
	data []byte
	off  int
}

// New returns a Body reading data. data must not be modified afterwards.
func New(data []byte) *Body {
	return &Body{data: data}
}

// Read reads from the current offset and rewinds after returning io.EOF.
func (b *Body) Read(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	if b.off >= len(b.data) {
		b.off = 0
		return 0, io.EOF
	}
	n := copy(p, b.data[b.off:])
	b.off += n
	return n, nil
}

// Close is a no-op so the body can be sent again.
func (b *Body) Close() error {
	return nil
}

// Len returns the full length of the body.
func (b *Body) Len() int {
	return len(b.data)
}

// Bytes returns the body without copying. It must not be modified.
func (b *Body) Bytes() []byte {
	return b.data
}

// Set installs data as the request body. GetBody returns a new cursor over
// the same slice, so the transport and dumps never copy it. data must not be
// modified afterwards.
func Set(req *retryablehttp.Request, data []byte) {
	req.Body = New(data)
	req.GetBody = func() (io.ReadCloser, error) {
		return New(data), nil
	}
	req.ContentLength = int64(len(data))
}

// SetString installs s as the request body without copying it.
func SetString(req *retryablehttp.Request, s string) {
	Set(req, convUtil.Bytes(s))
}

// View returns the request body, without copying it when it was installed
// by Set. Other bodies are read from a fresh GetBody copy; a body without
// GetBody is read once and replaced by a Body over the result.
func View(req *retryablehttp.Request) ([]byte, error) {
	if req == nil || req.Body == nil {
		return nil, nil
	}
	if body, ok := req.Body.(*Body); ok {
		return body.Bytes(), nil
	}

	if req.GetBody != nil {
		fresh, err := req.GetBody()
		if err != nil {
			return nil, err
		}
		if body, ok := fresh.(*Body); ok {
			return body.Bytes(), nil
		}
		return io.ReadAll(fresh)
	}

	data, err := io.ReadAll(req.Body)
	if err != nil {
		return nil, err
	}
	contentLength := req.ContentLength
	Set(req, data)
	req.ContentLength = contentLength
	return data, nil
}

package httpbody

import (
	"context"

	"golang.org/x/sync/semaphore"
)

// MinBudgetedBody is the smallest body that waits on a Budget, so small
// requests never queue behind a heavy one.
const MinBudgetedBody = 1 << 20

// Budget bounds the request-body bytes held by requests in flight.
type Budget struct {
	size int64
	sem  *semaphore.Weighted
}

// NewBudget returns nil when size <= 0; a nil budget never blocks.
func NewBudget(size int64) *Budget {
	if size <= 0 {
		return nil
	}
	return &Budget{size: size, sem: semaphore.NewWeighted(size)}
}

// Acquire blocks until n bytes fit or ctx is done. n larger than the budget
// is clamped, so that request runs alone.
func (b *Budget) Acquire(ctx context.Context, n int64) (release func(), err error) {
	if b == nil || n < MinBudgetedBody {
		return func() {}, nil
	}
	n = min(n, b.size)
	if err := b.sem.Acquire(ctx, n); err != nil {
		return nil, err
	}
	return func() { b.sem.Release(n) }, nil
}

package utils

// TransformIndex transforms user given index (start from 1) to array index (start from 0)
// in safe way without panic i.e negative index or index out of range
func TransformIndex[T any](arr []T, index int) int {
	if index <= 1 {
		// negative index
		return 0
	}
	if index >= len(arr) {
		// index out of range
		return len(arr) - 1
	}
	// valid index
	return index - 1
}

package utils

import (
	"fmt"
	"strconv"

	"github.com/projectdiscovery/nuclei/v3/pkg/utils/json"
	"github.com/projectdiscovery/nuclei/v3/pkg/utils/yaml"
)

type InsertionOrderedStringMap struct {
	keys   []string `yaml:"-"`
	values map[string]interface{}
}

func NewEmptyInsertionOrderedStringMap(size int) *InsertionOrderedStringMap {
	return &InsertionOrderedStringMap{
		keys:   make([]string, 0, size),
		values: make(map[string]interface{}, size),
	}
}

func NewInsertionOrderedStringMap(stringMap map[string]interface{}) *InsertionOrderedStringMap {
	result := NewEmptyInsertionOrderedStringMap(len(stringMap))

	for k, v := range stringMap {
		result.Set(k, v)
	}
	return result
}

func (insertionOrderedStringMap *InsertionOrderedStringMap) Len() int {
	return len(insertionOrderedStringMap.values)
}

func (insertionOrderedStringMap *InsertionOrderedStringMap) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var data yaml.MapSlice
	if err := unmarshal(&data); err != nil {
		return err
	}
	insertionOrderedStringMap.values = make(map[string]interface{})
	for _, v := range data {
		if v.Key == nil {
			continue
		}
		// Only string keys are valid here. A bare `1:` or `true:` key decodes to a
		// non-string value, which previously panicked; reject it with an error
		// instead of converting, so `1` and "1" are never merged into one entry.
		key, ok := v.Key.(string)
		if !ok {
			return fmt.Errorf("invalid map key %v (%T): keys must be strings, quote the key to use it as a string", v.Key, v.Key)
		}
		insertionOrderedStringMap.Set(key, toString(v.Value))
	}
	return nil
}

func (insertionOrderedStringMap *InsertionOrderedStringMap) UnmarshalJSON(data []byte) error {
	var dataMap map[string]interface{}
	if err := json.Unmarshal(data, &dataMap); err != nil {
		return err
	}
	insertionOrderedStringMap.values = make(map[string]interface{})
	for k, v := range dataMap {
		insertionOrderedStringMap.Set(k, toString(v))
	}
	return nil
}

// toString converts an interface to string in a quick way
func toString(data interface{}) interface{} {
	switch s := data.(type) {
	case nil:
		return ""
	case string:
		return s
	case bool:
		return strconv.FormatBool(s)
	case float64:
		return strconv.FormatFloat(s, 'f', -1, 64)
	case float32:
		return strconv.FormatFloat(float64(s), 'f', -1, 32)
	case int:
		return strconv.Itoa(s)
	case int64:
		return strconv.FormatInt(s, 10)
	case int32:
		return strconv.Itoa(int(s))
	case int16:
		return strconv.FormatInt(int64(s), 10)
	case int8:
		return strconv.FormatInt(int64(s), 10)
	case uint:
		return strconv.FormatUint(uint64(s), 10)
	case uint64:
		return strconv.FormatUint(s, 10)
	case uint32:
		return strconv.FormatUint(uint64(s), 10)
	case uint16:
		return strconv.FormatUint(uint64(s), 10)
	case uint8:
		return strconv.FormatUint(uint64(s), 10)
	case []byte:
		return string(s)
	case []interface{}:
		return data
	default:
		return fmt.Sprintf("%v", data)
	}
}

func (insertionOrderedStringMap *InsertionOrderedStringMap) ForEach(fn func(key string, data interface{})) {
	for _, key := range insertionOrderedStringMap.keys {
		fn(key, insertionOrderedStringMap.values[key])
	}
}

func (insertionOrderedStringMap *InsertionOrderedStringMap) Set(key string, value interface{}) {
	_, present := insertionOrderedStringMap.values[key]
	insertionOrderedStringMap.values[key] = value
	if !present {
		insertionOrderedStringMap.keys = append(insertionOrderedStringMap.keys, key)
	}
}

