func TestAgentRunExitsWhenCancelled(t *testing.T) {
	// Given
	monitor := NewStackMonitor()
	ctx, cancel := context.WithCancel(context.Background())
	ticker := time.NewTicker(time.Hour)
	t.Cleanup(cancel)
