// SMB constants for packet crafting
const (
	// SMB Commands
	SMB_COM_NEGOTIATE_PROTOCOL = 0x72
	SMB_COM_SESSION_SETUP_ANDX = 0x73
	SMB_COM_TREE_CONNECT_ANDX  = 0x75
	SMB_COM_NT_CREATE_ANDX     = 0xA2
	SMB_COM_READ_ANDX          = 0x2E
	SMB_COM_WRITE_ANDX         = 0x2F
	SMB_COM_CLOSE              = 0x04
	SMB_COM_TREE_DISCONNECT    = 0x71
	SMB_COM_LOGOFF_ANDX        = 0x74

	// SMB Flags
	SMB_FLAGS_CANONICAL_PATHNAMES              = 0x10
	SMB_FLAGS_CASELESS_PATHNAMES               = 0x08
	SMB_FLAGS2_UNICODE_STRINGS                 = 0x8000
	SMB_FLAGS2_ERRSTATUS                       = 0x4000
	SMB_FLAGS2_READ_IF_EXECUTE                 = 0x2000
	SMB_FLAGS2_32_BIT_ERRORS                   = 0x1000
	SMB_FLAGS2_DFS                             = 0x0800
	SMB_FLAGS2_EXTENDED_SECURITY               = 0x0400
	SMB_FLAGS2_REPARSE_PATH                    = 0x0200
	SMB_FLAGS2_SMB_SECURITY_SIGNATURE          = 0x0100
	SMB_FLAGS2_SMB_SECURITY_SIGNATURE_REQUIRED = 0x0080

	// SMB Security modes
	SMB_SECURITY_SHARE  = 0x00
	SMB_SECURITY_USER   = 0x01
	SMB_SECURITY_DOMAIN = 0x02

	// SMB Capabilities
	SMB_CAP_EXTENDED_SECURITY  = 0x80000000
	SMB_CAP_COMPRESSED_DATA    = 0x40000000
	SMB_CAP_BULK_TRANSFER      = 0x20000000
	SMB_CAP_UNIX               = 0x00800000
	SMB_CAP_LARGE_READX        = 0x00400000
	SMB_CAP_LARGE_WRITEX       = 0x00200000
	SMB_CAP_INFOLEVEL_PASSTHRU = 0x00100000
	SMB_CAP_DFS                = 0x00080000
	SMB_CAP_NT_FIND            = 0x00040000
	SMB_CAP_LOCK_AND_READ      = 0x00020000
	SMB_CAP_LEVEL_II_OPLOCKS   = 0x00010000
	SMB_CAP_STATUS32           = 0x00008000
	SMB_CAP_RPC_REMOTE_APIS    = 0x00004000
	SMB_CAP_NT_SMBS            = 0x00002000

	// NTLM constants
	NTLMSSP_NEGOTIATE_56                        = 0x80000000
	NTLMSSP_NEGOTIATE_KEY_EXCH                  = 0x40000000
	NTLMSSP_NEGOTIATE_128                       = 0x20000000
	NTLMSSP_NEGOTIATE_VERSION                   = 0x02000000
	NTLMSSP_NEGOTIATE_TARGET_INFO               = 0x00800000
	NTLMSSP_REQUEST_NON_NT_SESSION_KEY          = 0x00400000
	NTLMSSP_NEGOTIATE_IDENTIFY                  = 0x00100000
	NTLMSSP_NEGOTIATE_EXTENDED_SESSION_SECURITY = 0x00080000
	NTLMSSP_TARGET_TYPE_SERVER                  = 0x00020000
	NTLMSSP_NEGOTIATE_ALWAYS_SIGN               = 0x00008000
	NTLMSSP_NEGOTIATE_NTLM                      = 0x00000200
	NTLMSSP_NEGOTIATE_LM_KEY                    = 0x00000080
	NTLMSSP_NEGOTIATE_DATAGRAM                  = 0x00000040
	NTLMSSP_NEGOTIATE_SEAL                      = 0x00000020
	NTLMSSP_NEGOTIATE_SIGN                      = 0x00000010
	NTLMSSP_REQUEST_TARGET                      = 0x00000004
	NTLMSSP_NEGOTIATE_UNICODE                   = 0x00000001
)

// SMBPacket represents a complete SMB packet
type SMBPacket struct {
	NetBIOSHeader []byte
	SMBHeader     []byte
	SMBData       []byte
}

// SMBHeader represents the SMB header structure
type SMBHeader struct {
	ProtocolID  [4]byte // 0xFF, 'S', 'M', 'B'
	Command     byte
	Status      uint32
	Flags       byte
	Flags2      uint16
	PIDHigh     uint16
	Signature   [8]byte
	Reserved    uint16
	TreeID      uint16
	ProcessID   uint16
	UserID      uint16
	MultiplexID uint16
}

// CreateSMBPacket creates a complete SMB packet with NetBIOS header
func CreateSMBPacket(smbData []byte) *SMBPacket {
	// Create NetBIOS header
	netbiosHeader := make([]byte, 4)
	netbiosHeader[0] = 0x00 // Message type (Session message)
	netbiosHeader[1] = 0x00 // Padding
	netbiosHeader[2] = 0x00 // Padding

	// Calculate NetBIOS length (big-endian)
	length := len(smbData)
	netbiosHeader[3] = byte(length & 0xFF)

	return &SMBPacket{
		NetBIOSHeader: netbiosHeader,
		SMBHeader:     createSMBHeader(),
		SMBData:       smbData,
	}
}

// createSMBHeader creates a standard SMB header
func createSMBHeader() []byte {
	header := make([]byte, 32)

	// Protocol ID: 0xFF, 'S', 'M', 'B'
	header[0] = 0xFF
	header[1] = 'S'
	header[2] = 'M'
	header[3] = 'B'

	// Command (will be set by caller)
	header[4] = 0x00

	// Status (0 for requests)
	binary.LittleEndian.PutUint32(header[5:9], 0)

	// Flags
	header[9] = SMB_FLAGS_CANONICAL_PATHNAMES

	// Flags2
	binary.LittleEndian.PutUint16(header[10:12], SMB_FLAGS2_UNICODE_STRINGS|SMB_FLAGS2_EXTENDED_SECURITY)

	// PIDHigh, Signature, Reserved, TreeID, ProcessID, UserID, MultiplexID
	// All set to 0 for new connections
	binary.LittleEndian.PutUint16(header[12:14], 0) // PIDHigh
	// Signature is 8 bytes of zeros
	binary.LittleEndian.PutUint16(header[20:22], 0) // Reserved
	binary.LittleEndian.PutUint16(header[22:24], 0) // TreeID
	binary.LittleEndian.PutUint16(header[24:26], 0) // ProcessID
	binary.LittleEndian.PutUint16(header[26:28], 0) // UserID
	binary.LittleEndian.PutUint16(header[28:30], 0) // MultiplexID

	return header
}

// CreateNegotiateProtocolPacket creates an SMB negotiate protocol packet
func CreateNegotiateProtocolPacket() []byte {
	// Create SMB header
	header := createSMBHeader()
	header[4] = SMB_COM_NEGOTIATE_PROTOCOL

	// Create negotiate protocol data
	data := createNegotiateProtocolData()

	// Combine header and data
	packet := append(header, data...)

	// Create complete packet with NetBIOS header
	smbPacket := CreateSMBPacket(packet)

	return smbPacket.Bytes()
}

// createNegotiateProtocolData creates the data portion of negotiate protocol packet
func createNegotiateProtocolData() []byte {
	var buf bytes.Buffer

	// Word count
	_ = buf.WriteByte(0x00)

	// Byte count
	_ = buf.WriteByte(0x00)

	// Dialect strings
	dialects := []string{
		"NT LM 0.12",
		"SMB 2.002",
		"SMB 2.???",
	}

	for _, dialect := range dialects {
		_ = buf.WriteByte(byte(len(dialect)))
		_, _ = buf.WriteString(dialect)
		_ = buf.WriteByte(0x00)
	}

	// Update byte count
	data := buf.Bytes()
	data[1] = byte(len(data) - 2)

	return data
}

// CreateSessionSetupPacket creates an SMB session setup packet
func CreateSessionSetupPacket(username, password, domain string, sessionKey uint64) []byte {
	// Create SMB header
	header := createSMBHeader()
	header[4] = SMB_COM_SESSION_SETUP_ANDX

	// Create session setup data
	data := createSessionSetupData(username, password, domain, sessionKey)

	// Combine header and data
	packet := append(header, data...)

	// Create complete packet with NetBIOS header
	smbPacket := CreateSMBPacket(packet)

	return smbPacket.Bytes()
}

// createSessionSetupData creates the data portion of session setup packet
func createSessionSetupData(username, password, domain string, sessionKey uint64) []byte {
	var buf bytes.Buffer

	// Word count
	_ = buf.WriteByte(0x0D)

	// AndXCommand (no chained command)
	_ = buf.WriteByte(0xFF)

	// AndXReserved
	_ = buf.WriteByte(0x00)

	// AndXOffset
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))

	// MaxBufferSize
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0xFFFF))

	// MaxMpxCount
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x01))

	// VcNumber
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x00))

	// SessionKey
	_ = binary.Write(&buf, binary.LittleEndian, uint32(sessionKey))

	// CaseInsensitivePasswordLength
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(password)))

	// CaseSensitivePasswordLength
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(password)))

	// Reserved
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00))

	// Capabilities
	_ = binary.Write(&buf, binary.LittleEndian, uint32(SMB_CAP_EXTENDED_SECURITY|SMB_CAP_NT_SMBS))

	// Byte count
	_ = buf.WriteByte(0x00)

	// CaseInsensitivePassword
	_, _ = buf.WriteString(password)

	// CaseSensitivePassword
	_, _ = buf.WriteString(password)

	// Account name
	_, _ = buf.WriteString(username)
	_ = buf.WriteByte(0x00)

	// Primary domain
	_, _ = buf.WriteString(domain)
	_ = buf.WriteByte(0x00)

	// Native OS
	_, _ = buf.WriteString("Windows 2000 2195")
	_ = buf.WriteByte(0x00)

	// Native LAN Manager
	_, _ = buf.WriteString("Windows 2000 5.0")
	_ = buf.WriteByte(0x00)

	// Update byte count
	data := buf.Bytes()
	data[len(data)-1] = byte(len(data) - 0x21) // 0x21 is the offset to the start of variable data

	return data
}

// CreateTreeConnectPacket creates an SMB tree connect packet
func CreateTreeConnectPacket(shareName string, password string) []byte {
	// Create SMB header
	header := createSMBHeader()
	header[4] = SMB_COM_TREE_CONNECT_ANDX

	// Create tree connect data
	data := createTreeConnectData(shareName, password)

	// Combine header and data
	packet := append(header, data...)

	// Create complete packet with NetBIOS header
	smbPacket := CreateSMBPacket(packet)

	return smbPacket.Bytes()
}

// createTreeConnectData creates the data portion of tree connect packet
func createTreeConnectData(shareName, password string) []byte {
	var buf bytes.Buffer

	// Word count
	_ = buf.WriteByte(0x04)

	// AndXCommand (no chained command)
	_ = buf.WriteByte(0xFF)

	// AndXReserved
	_ = buf.WriteByte(0x00)

	// AndXOffset
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))

	// Flags
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x00))

	// Password length
	_ = buf.WriteByte(byte(len(password)))

	// Byte count
	_ = buf.WriteByte(0x00)

	// Password
	_, _ = buf.WriteString(password)
	_ = buf.WriteByte(0x00)

	// Tree
	_, _ = buf.WriteString(shareName)
	_ = buf.WriteByte(0x00)

	// Service
	_, _ = buf.WriteString("?????")
	_ = buf.WriteByte(0x00)

	// Update byte count
	data := buf.Bytes()
	data[7] = byte(len(data) - 0x0B) // 0x0B is the offset to the start of variable data

	return data
}

// CreateNTCreatePacket creates an SMB NT create packet
func CreateNTCreatePacket(fileName string) []byte {
	// Create SMB header
	header := createSMBHeader()
	header[4] = SMB_COM_NT_CREATE_ANDX

	// Create NT create data
	data := createNTCreateData(fileName)

	// Combine header and data
	packet := append(header, data...)

	// Create complete packet with NetBIOS header
	smbPacket := CreateSMBPacket(packet)

	return smbPacket.Bytes()
}

// createNTCreateData creates the data portion of NT create packet
func createNTCreateData(fileName string) []byte {
	var buf bytes.Buffer

	// Word count
	_ = buf.WriteByte(0x18)

	// AndXCommand (no chained command)
	_ = buf.WriteByte(0xFF)

	// AndXReserved
	_ = buf.WriteByte(0x00)

	// AndXOffset
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))

	// Reserved
	_ = buf.WriteByte(0x00)

	// NameLength
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(fileName)))

	// Flags
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// RootDirectoryFID
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// DesiredAccess
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// AllocationSize
	_ = binary.Write(&buf, binary.LittleEndian, uint64(0x0000000000000000))

	// FileAttributes
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// ShareAccess
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// CreateDisposition
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000001)) // FILE_OPEN

	// CreateOptions
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// ImpersonationLevel
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000002)) // SecurityImpersonation

	// SecurityFlags
	_ = buf.WriteByte(0x00)

	// Byte count
	_ = buf.WriteByte(0x00)

	// SecurityDescriptor
	_ = buf.WriteByte(0x00)

	// FileName
	_, _ = buf.WriteString(fileName)
	_ = buf.WriteByte(0x00)

	// Update byte count
	data := buf.Bytes()
	data[0x3B] = byte(len(data) - 0x3C) // 0x3C is the offset to the start of variable data

	return data
}

// Bytes returns the complete SMB packet as bytes
func (p *SMBPacket) Bytes() []byte {
	var result bytes.Buffer
	result.Write(p.NetBIOSHeader)
	result.Write(p.SMBHeader)
	result.Write(p.SMBData)
	return result.Bytes()
}

// CreateNTLMNegotiatePacket creates an NTLM negotiate packet for SMB authentication
func CreateNTLMNegotiatePacket() []byte {
	var buf bytes.Buffer

	// NTLMSSP signature
	_, _ = buf.WriteString("NTLMSSP")
	_ = buf.WriteByte(0x00)

	// Message type (1 = Negotiate)
	_ = binary.Write(&buf, binary.LittleEndian, uint32(1))

	// Negotiate flags
	flags := uint32(NTLMSSP_NEGOTIATE_56 |
		NTLMSSP_NEGOTIATE_128 |
		NTLMSSP_NEGOTIATE_VERSION |
		NTLMSSP_NEGOTIATE_TARGET_INFO |
		NTLMSSP_NEGOTIATE_EXTENDED_SESSION_SECURITY |
		NTLMSSP_TARGET_TYPE_SERVER |
		NTLMSSP_NEGOTIATE_ALWAYS_SIGN |
		NTLMSSP_NEGOTIATE_NTLM |
		NTLMSSP_NEGOTIATE_UNICODE)
	_ = binary.Write(&buf, binary.LittleEndian, flags)

	// Domain name fields (empty for negotiate)
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0)) // DomainNameLen
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0)) // DomainNameMaxLen
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0)) // DomainNameBufferOffset

	// Workstation name fields (empty for negotiate)
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0)) // WorkstationNameLen
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0)) // WorkstationNameMaxLen
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0)) // WorkstationNameBufferOffset

	// Version
	_ = buf.WriteByte(0x05)                                     // Major version
	_ = buf.WriteByte(0x02)                                     // Minor version
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0A28)) // Build number
	_, _ = buf.Write(make([]byte, 3))                           // Reserved
	_ = buf.WriteByte(0x0F)                                     // NTLM revision

	return buf.Bytes()
}

// CreateNTLMChallengePacket creates an NTLM challenge packet (for testing)
func CreateNTLMChallengePacket(challenge []byte, targetInfo []byte) []byte {
	var buf bytes.Buffer

	// NTLMSSP signature
	_, _ = buf.WriteString("NTLMSSP")
	_ = buf.WriteByte(0x00)

	// Message type (2 = Challenge)
	_ = binary.Write(&buf, binary.LittleEndian, uint32(2))

	// Target name fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(56)) // TargetNameBufferOffset

	// Negotiate flags
	flags := uint32(NTLMSSP_NEGOTIATE_56 |
		NTLMSSP_NEGOTIATE_128 |
		NTLMSSP_NEGOTIATE_VERSION |
		NTLMSSP_NEGOTIATE_TARGET_INFO |
		NTLMSSP_NEGOTIATE_EXTENDED_SESSION_SECURITY |
		NTLMSSP_TARGET_TYPE_SERVER |
		NTLMSSP_NEGOTIATE_ALWAYS_SIGN |
		NTLMSSP_NEGOTIATE_NTLM |
		NTLMSSP_NEGOTIATE_UNICODE)
	_ = binary.Write(&buf, binary.LittleEndian, flags)

	// Challenge
	_, _ = buf.Write(challenge)

	// Reserved
	_, _ = buf.Write(make([]byte, 8))

	// Target info fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(targetInfo)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(targetInfo)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(56)) // TargetInfoBufferOffset

	// Version
	_ = buf.WriteByte(0x05)                                     // Major version
	_ = buf.WriteByte(0x02)                                     // Minor version
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0A28)) // Build number
	_, _ = buf.Write(make([]byte, 3))                           // Reserved
	_ = buf.WriteByte(0x0F)                                     // NTLM revision

	// Target info
	_, _ = buf.Write(targetInfo)

	return buf.Bytes()
}

// CreateNTLMAuthPacket creates an NTLM authenticate packet
func CreateNTLMAuthPacket(username, password, domain, workstation string, challenge []byte, lmResponse, ntResponse []byte) []byte {
	var buf bytes.Buffer

	// NTLMSSP signature
	_, _ = buf.WriteString("NTLMSSP")
	_ = buf.WriteByte(0x00)

	// Message type (3 = Authenticate)
	_ = binary.Write(&buf, binary.LittleEndian, uint32(3))

	// Calculate offsets
	baseOffset := uint32(72) // Header size (assuming Version is present)

	lmOffset := baseOffset
	ntOffset := lmOffset + uint32(len(lmResponse))
	domainOffset := ntOffset + uint32(len(ntResponse))
	userOffset := domainOffset + uint32(len(domain))
	workOffset := userOffset + uint32(len(username))
	sessionKeyOffset := workOffset + uint32(len(workstation))

	// LM response fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(lmResponse)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(lmResponse)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(lmOffset))

	// NT response fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(ntResponse)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(ntResponse)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(ntOffset))

	// Domain name fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(domain)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(domain)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(domainOffset))

	// Username fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(username)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(username)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(userOffset))

	// Workstation name fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(workstation)))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(len(workstation)))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(workOffset))

	// Encrypted random session key fields
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0))
	_ = binary.Write(&buf, binary.LittleEndian, uint32(sessionKeyOffset))

	// Negotiate flags
	flags := uint32(NTLMSSP_NEGOTIATE_56 |
		NTLMSSP_NEGOTIATE_128 |
		NTLMSSP_NEGOTIATE_VERSION |
		NTLMSSP_NEGOTIATE_TARGET_INFO |
		NTLMSSP_NEGOTIATE_EXTENDED_SESSION_SECURITY |
		NTLMSSP_TARGET_TYPE_SERVER |
		NTLMSSP_NEGOTIATE_ALWAYS_SIGN |
		NTLMSSP_NEGOTIATE_NTLM |
		NTLMSSP_NEGOTIATE_UNICODE)
	_ = binary.Write(&buf, binary.LittleEndian, flags)

	// Version
	_ = buf.WriteByte(0x05)                                     // Major version
	_ = buf.WriteByte(0x02)                                     // Minor version
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0A28)) // Build number
	_, _ = buf.Write(make([]byte, 3))                           // Reserved
	_ = buf.WriteByte(0x0F)                                     // NTLM revision

	// LM response
	_, _ = buf.Write(lmResponse)

	// NT response
	_, _ = buf.Write(ntResponse)

	// Domain name
	_, _ = buf.WriteString(domain)

	// Username
	_, _ = buf.WriteString(username)

	// Workstation name
	_, _ = buf.WriteString(workstation)

	return buf.Bytes()
}

// Helper function to create LM hash response
func CreateLMResponse(challenge []byte, password string) []byte {
	// Create a minimal Type 2 challenge packet to satisfy ntlmssp
	type2 := CreateNTLMChallengePacket(challenge, []byte{})

	// Generate Type 3 authenticate packet
	// We use empty username/domain as we only need the hash response
	authMsg, err := ntlmssp.NewAuthenticateMessage(type2, "", password, nil)
	if err != nil {
		return nil
	}

	// Parse the response to extract LM response
	// LM Response Len is at offset 12 (2 bytes)
	// LM Response Offset is at offset 16 (4 bytes)
	if len(authMsg) < 20 {
		return nil
	}

	lmLen := binary.LittleEndian.Uint16(authMsg[12:14])
	lmOffset := binary.LittleEndian.Uint32(authMsg[16:20])

	if int(lmOffset)+int(lmLen) > len(authMsg) {
		return nil
	}

	return authMsg[lmOffset : lmOffset+uint32(lmLen)]
}

// Helper function to create NT hash response
func CreateNTResponse(challenge []byte, password string) []byte {
	// Create a minimal Type 2 challenge packet to satisfy ntlmssp
	type2 := CreateNTLMChallengePacket(challenge, []byte{})

	// Generate Type 3 authenticate packet
	authMsg, err := ntlmssp.NewAuthenticateMessage(type2, "", password, nil)
	if err != nil {
		return nil
	}

	// Parse the response to extract NT response
	// NT Response Len is at offset 20 (2 bytes)
	// NT Response Offset is at offset 24 (4 bytes)
	if len(authMsg) < 28 {
		return nil
	}

	ntLen := binary.LittleEndian.Uint16(authMsg[20:22])
	ntOffset := binary.LittleEndian.Uint32(authMsg[24:28])

	if int(ntOffset)+int(ntLen) > len(authMsg) {
		return nil
	}

	return authMsg[ntOffset : ntOffset+uint32(ntLen)]
}

// CreateSMBv2NegotiatePacket creates an SMBv2 negotiate protocol packet
func CreateSMBv2NegotiatePacket() []byte {
	var buf bytes.Buffer

	// SMB2 header
	_ = buf.WriteByte(0xFE) // Protocol ID
	_, _ = buf.WriteString("SMB")
	_ = buf.WriteByte(0x00) // Protocol ID

	// Command (Negotiate Protocol)
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0000))

	// Status
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// Flags
	_ = buf.WriteByte(0x00)

	// Next command
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0000))

	// Message ID
	_ = binary.Write(&buf, binary.LittleEndian, uint64(0x0000000000000001))

	// Reserved
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// Tree ID
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000000))

	// Session ID
	_ = binary.Write(&buf, binary.LittleEndian, uint64(0x0000000000000000))

	// Signature
	_, _ = buf.Write(make([]byte, 16))

	// Structure size
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x24))

	// Dialect count
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0001))

	// Security mode
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0001))

	// Reserved
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0000))

	// Capabilities
	_ = binary.Write(&buf, binary.LittleEndian, uint32(0x00000001))

	// Client GUID
	_, _ = buf.Write(make([]byte, 16))

	// Client start time
	_ = binary.Write(&buf, binary.LittleEndian, uint64(0x0000000000000000))

	// Dialects
	_ = binary.Write(&buf, binary.LittleEndian, uint16(0x0311)) // SMB 3.1.1

	return buf.Bytes()
}

// ParseSMBResponse parses an SMB response packet
func ParseSMBResponse(data []byte) (*SMBHeader, error) {
	if len(data) < 32 {
		return nil, fmt.Errorf("SMB response too short: %d bytes", len(data))
	}

	header := &SMBHeader{}

	// Check protocol ID
	if data[0] != 0xFF || data[1] != 'S' || data[2] != 'M' || data[3] != 'B' {
		return nil, fmt.Errorf("invalid SMB protocol ID")
	}

	// Parse header fields
	header.Command = data[4]
	header.Status = binary.LittleEndian.Uint32(data[5:9])
	header.Flags = data[9]
	header.Flags2 = binary.LittleEndian.Uint16(data[10:12])
	header.PIDHigh = binary.LittleEndian.Uint16(data[12:14])
	copy(header.Signature[:], data[14:22])
	header.Reserved = binary.LittleEndian.Uint16(data[22:24])
	header.TreeID = binary.LittleEndian.Uint16(data[24:26])
	header.ProcessID = binary.LittleEndian.Uint16(data[26:28])
	header.UserID = binary.LittleEndian.Uint16(data[28:30])
	header.MultiplexID = binary.LittleEndian.Uint16(data[30:32])

	return header, nil
}

// telnetmini.go
// Minimal Telnet helper for authentication + simple I/O over an existing or new connection.

package telnetmini

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"strings"
	"time"
)

// Telnet protocol constants
const (
	IAC     = 255 // Interpret As Command
	WILL    = 251 // Will
	WONT    = 252 // Won't
	DO      = 253 // Do
	DONT    = 254 // Don't
	SB      = 250 // Subnegotiation Begin
	SE      = 240 // Subnegotiation End
	ENCRYPT = 38  // Encryption option (0x26)
)

// EncryptionInfo contains information about telnet encryption support
type EncryptionInfo struct {
	SupportsEncryption bool
	Banner             string
	Options            map[int][]int
}

// Client wraps a Telnet connection with tiny helpers.
type Client struct {
	Conn            net.Conn
	rd              *bufio.Reader
	wr              *bufio.Writer
	LoginPrompts    []string // matched case-insensitively
	UserPrompts     []string // alternative to LoginPrompts; if empty, LoginPrompts used for username step
	PasswordPrompts []string
	FailBanners     []string // e.g., "login incorrect", "authentication failed"
	ShellPrompts    []string // e.g., "$ ", "# ", "> "
	ReadCapBytes    int      // safety cap while scanning (default 64 KiB)
}

// Defaults sets reasonable prompt patterns if none provided.
func (c *Client) Defaults() {
	if c.ReadCapBytes == 0 {
		c.ReadCapBytes = 64 * 1024
	}
	if len(c.LoginPrompts) == 0 {
		c.LoginPrompts = []string{"login:", "username:"}
	}
	if len(c.PasswordPrompts) == 0 {
		c.PasswordPrompts = []string{"password:"}
	}
	if len(c.FailBanners) == 0 {
		c.FailBanners = []string{"login incorrect", "authentication failed", "login failed"}
	}
	if len(c.ShellPrompts) == 0 {
		c.ShellPrompts = []string{"$ ", "# ", "> "}
	}
	if len(c.UserPrompts) == 0 {
		c.UserPrompts = c.LoginPrompts
	}
}

// New wraps an existing net.Conn.
func New(conn net.Conn) *Client {
	c := &Client{
		Conn: conn,
		rd:   bufio.NewReader(conn),
		wr:   bufio.NewWriter(conn),
	}
	c.Defaults()
	return c
}

// Close closes the underlying connection.
func (c *Client) Close() error {
	return c.Conn.Close()
}

// DetectEncryption detects if a telnet server supports encryption.
// Based on Nmap's telnet-encryption.nse script functionality.
// WARNING: The connection becomes unusable after calling this function
// due to the encryption negotiation packets sent.
func DetectEncryption(conn net.Conn, timeout time.Duration) (*EncryptionInfo, error) {
	if timeout == 0 {
		timeout = 7 * time.Second
	}

	// Set connection timeout
	_ = conn.SetDeadline(time.Now().Add(timeout))

	// Send encryption negotiation packet (based on Nmap script)
	// FF FD 26 FF FB 26 = IAC DO ENCRYPT IAC WILL ENCRYPT
	encryptionPacket := []byte{IAC, DO, ENCRYPT, IAC, WILL, ENCRYPT}
	_, err := conn.Write(encryptionPacket)
	if err != nil {
		return nil, fmt.Errorf("failed to send encryption packet: %w", err)
	}

	// Process server responses
	options := make(map[int][]int)
	supportsEncryption := false
	banner := ""

	// Read responses until we get encryption info or timeout
	for {
		_ = conn.SetReadDeadline(time.Now().Add(1 * time.Second))
		buffer := make([]byte, 1024)
		n, err := conn.Read(buffer)
		if err != nil {
			// Timeout or connection closed, break
			break
		}

		if n > 0 {
			data := buffer[:n]
			// Check if this contains banner text (non-IAC bytes)
			for _, b := range data {
				if b != IAC {
					banner += string(b)
				}
			}

			// Process telnet options
			encrypted, opts := processTelnetOptions(data)
			if encrypted {
				supportsEncryption = true
			}

			// Merge options
			for opt, cmds := range opts {
				if options[opt] == nil {
					options[opt] = make([]int, 0)
				}
				options[opt] = append(options[opt], cmds...)
			}

			// Check if we have encryption info
			if cmds, exists := options[ENCRYPT]; exists {
				for _, cmd := range cmds {
					if cmd == WILL || cmd == DO {
						supportsEncryption = true
						break
					}
				}
			}
		}
	}

	return &EncryptionInfo{
		SupportsEncryption: supportsEncryption,
		Banner:             banner,
		Options:            options,
	}, nil
}

// processTelnetOptions processes telnet protocol options and returns encryption support status
func processTelnetOptions(data []byte) (bool, map[int][]int) {
	options := make(map[int][]int)
	supportsEncryption := false

	for i := 0; i < len(data); i++ {
		if data[i] == IAC && i+2 < len(data) {
			cmd := data[i+1]
			option := data[i+2]

			// Initialize option slice if not exists
			optInt := int(option)
			if options[optInt] == nil {
				options[optInt] = make([]int, 0)
			}
			options[optInt] = append(options[optInt], int(cmd))

			// Check for encryption support
			if option == ENCRYPT && (cmd == WILL || cmd == DO) {
				supportsEncryption = true
			}

			// Handle subnegotiation
			if cmd == SB {
				// Skip until SE
				for j := i + 3; j < len(data); j++ {
					if data[j] == IAC && j+1 < len(data) && data[j+1] == SE {
						i = j + 1
						break
					}
				}
			} else {
				i += 2 // Skip command and option
			}
		}
	}

	return supportsEncryption, options
}

// Auth performs a minimal Telnet username/password interaction.
// It waits for a username/login prompt, sends username, waits for a password prompt,
// sends password, and then looks for fail banners or shell prompts.
// A timeout should be enforced via ctx.
func (c *Client) Auth(ctx context.Context, username, password string) error {
	// Wait for username/login prompt
	if _, _, err := c.readUntil(ctx, c.UserPrompts...); err != nil {
		return fmt.Errorf("waiting for login/username prompt: %w", err)
	}
	if err := c.writeLine(ctx, username); err != nil {
		return fmt.Errorf("sending username: %w", err)
	}

	// Wait for password prompt
	if _, _, err := c.readUntil(ctx, c.PasswordPrompts...); err != nil {
		return fmt.Errorf("waiting for password prompt: %w", err)
	}
	if err := c.writeLine(ctx, password); err != nil {
		return fmt.Errorf("sending password: %w", err)
	}

	// Post-auth: look quickly for explicit failure, else accept shell prompt / silence.
	match, got, err := c.readUntil(ctx,
		append(append([]string{}, c.FailBanners...), c.ShellPrompts...)...,
	)
	if err != nil && !errors.Is(err, context.DeadlineExceeded) {
		return fmt.Errorf("post-auth read: %s (got: %s)", preview(got, 200), err)
	}
	low := strings.ToLower(match)
	for _, fb := range c.FailBanners {
		if low == strings.ToLower(fb) {
			return errors.New("authentication failed")
		}
	}
	// success (matched a shell prompt or timed out without explicit failure)
	return nil
}

// Exec sends a command followed by CRLF and returns text captured until one of
// the provided prompts appears (typically your shell prompt). Provide a deadline via ctx.
func (c *Client) Exec(ctx context.Context, command string, until ...string) (string, error) {
	if err := c.writeLine(ctx, command); err != nil {
		return "", err
	}
	_, out, err := c.readUntil(ctx, until...)
	return out, err
}

// --- internals ---

// writeLine writes s + CRLF and flushes.
func (c *Client) writeLine(ctx context.Context, s string) error {
	c.setDeadlineFromCtx(ctx, true)
	if _, err := io.WriteString(c.wr, s+"\r\n"); err != nil {
		return err
	}
	return c.wr.Flush()
}

// readUntil scans bytes, handles minimal Telnet IAC negotiation, and returns when any needle appears.
func (c *Client) readUntil(ctx context.Context, needles ...string) (matched string, bufStr string, err error) {
	if len(needles) == 0 {
		return "", "", errors.New("readUntil: no needles provided")
	}
	c.setDeadlineFromCtx(ctx, false)

	lowNeedles := make([]string, len(needles))
	for i, n := range needles {
		lowNeedles[i] = strings.ToLower(n)
	}

	var b strings.Builder
	tmp := make([]byte, 1)

	// Maximum iteration counter to prevent infinite loops
	maxIterations := 20
	iterationCount := 0

	for {
		iterationCount++
		// if we have iterated more than maxIterations, return
		if iterationCount > maxIterations {
			return "", b.String(), nil
		}
		// honor context deadline on every read
		c.setDeadlineFromCtx(ctx, false)
		_, err := c.rd.Read(tmp)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				return "", b.String(), context.DeadlineExceeded
			}
			return "", b.String(), err
		}

		// Telnet IAC (Interpret As Command)
		if tmp[0] == 255 { // IAC
			cmd, err := c.rd.ReadByte()
			if err != nil {
				return "", b.String(), err
			}
			switch cmd {
			case 251, 252, 253, 254: // WILL, WONT, DO, DONT
				opt, err := c.rd.ReadByte()
				if err != nil {
					return "", b.String(), err
				}
				// Politely refuse everything: DONT to WILL; WONT to DO.
				var reply []byte
				if cmd == 251 { // WILL
					reply = []byte{255, 254, opt} // DONT
				}
				if cmd == 253 { // DO
					reply = []byte{255, 252, opt} // WONT
				}
				if len(reply) > 0 {
					c.setDeadlineFromCtx(ctx, true)
					_, _ = c.wr.Write(reply)
					_ = c.wr.Flush()
				}
			case 250: // SB (subnegotiation): skip until SE
				for {
					bb, err := c.rd.ReadByte()
					if err != nil {
						return "", b.String(), err
					}
					if bb == 255 {
						if se, err := c.rd.ReadByte(); err == nil && se == 240 { // SE
							break
						}
					}
				}
			default:
				// NOP for other commands (IAC NOP, GA, etc.)
			}
			continue
		}

		// regular data byte
		b.WriteByte(tmp[0])
		lower := strings.ToLower(b.String())
		for i, n := range lowNeedles {
			if strings.Contains(lower, n) {
				return needles[i], b.String(), nil
			}
		}
		if b.Len() > c.ReadCapBytes {
			return "", b.String(), errors.New("prompt not found (read cap reached)")
		}
	}
}

func (c *Client) setDeadlineFromCtx(ctx context.Context, write bool) {
	if ctx == nil {
		return
	}
	if dl, ok := ctx.Deadline(); ok {
		_ = c.Conn.SetReadDeadline(dl)
		if write {
			_ = c.Conn.SetWriteDeadline(dl)
		}
	}
}

func preview(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}

package utils

import (
	"path/filepath"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
	"github.com/projectdiscovery/nuclei/v3/pkg/keys"
	filepathutil "github.com/projectdiscovery/nuclei/v3/pkg/utils/filepath"
)

const (
	// TemplatesRepoURL is the URL for files in nuclei-templates repository
	TemplatesRepoURL = "https://cloud.projectdiscovery.io/public/"
)

// TemplatePathURL returns the Path and URL for the provided template
func TemplatePathURL(fullPath, templateId, templateVerifier string) (path string, url string) {
	configData := config.DefaultConfig
	if configData.TemplatesDirectory != "" && filepathutil.IsPathWithinDirectory(fullPath, configData.GetTemplateDir()) {
		relPath, err := filepath.Rel(configData.GetTemplateDir(), fullPath)
		if err == nil && relPath != "." {
			path = relPath
		}
	}
	if templateVerifier == keys.PDVerifier {
		url = TemplatesRepoURL + templateId
	}
	return
}

package utils

import (
	"path/filepath"
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/catalog/config"
)

func TestTemplatePathURLUsesTemplateDirBoundaries(t *testing.T) {
	templatesDir := filepath.Join(t.TempDir(), "nuclei-templates")

	oldTemplatesDir := config.DefaultConfig.TemplatesDirectory
	config.DefaultConfig.SetTemplatesDir(templatesDir)
	t.Cleanup(func() {
		config.DefaultConfig.SetTemplatesDir(oldTemplatesDir)
	})

	path, _ := TemplatePathURL(filepath.Join(templatesDir, "http", "test.yaml"), "test", "")
	if path != filepath.Join("http", "test.yaml") {
		t.Fatalf("expected relative template path, got %q", path)
	}

	path, _ = TemplatePathURL(filepath.Join(templatesDir+"-evil", "test.yaml"), "test", "")
	if path != "" {
		t.Fatalf("expected sibling prefix path not to be relativized, got %q", path)
	}
}

package utils

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"strings"
	"time"

	"github.com/cespare/xxhash"
	"github.com/projectdiscovery/nuclei/v3/pkg/catalog"
	"github.com/projectdiscovery/ratelimit"
	"github.com/projectdiscovery/retryablehttp-go"
	mapsutil "github.com/projectdiscovery/utils/maps"
)

func IsBlank(value string) bool {
	return strings.TrimSpace(value) == ""
}

func UnwrapError(err error) error {
	for { // get the last wrapped error
		unwrapped := errors.Unwrap(err)
		if unwrapped == nil {
			break
		}
		err = unwrapped
	}
	return err
}

// IsURL tests a string to determine if it is a well-structured url or not.
func IsURL(input string) bool {
	u, err := url.Parse(input)
	return err == nil && u.Scheme != "" && u.Host != ""
}

// ReaderFromPathOrURL reads and returns the contents of a file or url.
func ReaderFromPathOrURL(templatePath string, catalog catalog.Catalog) (io.ReadCloser, error) {
	if IsURL(templatePath) {
		resp, err := retryablehttp.DefaultClient().Get(templatePath)
		if err != nil {
			return nil, err
		}
		return resp.Body, nil
	} else {
		f, err := catalog.OpenFile(templatePath)
		if err != nil {
			return nil, err
		}
		return f, nil
	}
}

// StringSliceContains checks if a string slice contains a string.
func StringSliceContains(slice []string, item string) bool {
	for _, i := range slice {
		if strings.EqualFold(i, item) {
			return true
		}
	}
	return false
}

// MapHash generates a hash for any give map
func MapHash[K cmp.Ordered, V any](m map[K]V) uint64 {
	keys := mapsutil.GetSortedKeys(m)
	var sb strings.Builder
	for _, k := range keys {
		fmt.Fprintf(&sb, "%v:%v\n", k, m[k])
	}
	return xxhash.Sum64([]byte(sb.String()))
}

// GetRateLimiter returns a rate limiter with the given max tokens and duration
// if maxTokens is 0 or duration is 0, it returns an unlimited rate limiter
func GetRateLimiter(ctx context.Context, maxTokens int, duration time.Duration) *ratelimit.Limiter {
	if maxTokens == 0 || duration == 0 {
		return ratelimit.NewUnlimited(ctx)
	}
	return ratelimit.New(ctx, uint(maxTokens), duration)
}

package yaml

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"

	"github.com/projectdiscovery/nuclei/v3/pkg/templates/extensions"
	filepathutil "github.com/projectdiscovery/nuclei/v3/pkg/utils/filepath"
	"github.com/projectdiscovery/utils/errkit"
	fileutil "github.com/projectdiscovery/utils/file"
	stringsutil "github.com/projectdiscovery/utils/strings"
)

var reImportsPattern = regexp.MustCompile(`(?m)# !include:(.+.yaml)`)

const maxIncludeDepth = 32

// StrictSyntax determines if pre-processing directives should be observed
var StrictSyntax bool

// AllowLocalFileAccess mirrors the -allow-local-file-access (-lfa) option for
// the preprocessing stage. When false (the default), include directives are
// confined to the nuclei-templates directory and the including template's own
// directory.
var AllowLocalFileAccess bool

// TemplateBaseDirProvider, when set, returns an additional directory under which
// include directives are permitted (in addition to the including template's own
// directory). It is wired up by the catalog/config package to avoid an import
// cycle between this low-level utility package and catalog/config.
var TemplateBaseDirProvider func() string

// PreProcess all include directives. templatePath is the path of the template
// currently being processed and is used to resolve relative include paths and
// to validate them.
func PreProcess(data []byte, templatePath string) ([]byte, error) {
	return preProcess(data, templatePath, make(map[string]struct{}), 0)
}

func preProcess(data []byte, templatePath string, includeStack map[string]struct{}, depth int) ([]byte, error) {
	// find all matches like !include:path\n
	// FindAllSubmatchIndex is used (instead of FindAllSubmatch) so each match
	// carries its own offset; relying on bytes.Index would always resolve to the
	// first occurrence and incorrectly pad repeated include directives.
	importMatches := reImportsPattern.FindAllSubmatchIndex(data, -1)
	hasImportDirectives := len(importMatches) > 0

	if hasImportDirectives && StrictSyntax {
		return data, errors.New("include directive preprocessing is disabled")
	}

	if !hasImportDirectives {
		return data, nil
	}

	// Expand each directive in place using its own offset. A strings.Replacer
	// cannot be used here because it collapses identical directive lines onto a
	// single replacement, which would reuse the first occurrence's indentation
	// for every later occurrence.
	var out bytes.Buffer
	lastEnd := 0

	for _, match := range importMatches {
		matchStart, matchEnd := match[0], match[1]

		var includeFileName string
		if len(match) > 3 && match[2] >= 0 {
			includeFileName = string(data[match[2]:match[3]])
		}

		// resolve relative include paths against the including template's
		// directory rather than the process working directory.
		resolvedInclude := includeFileName
		if !filepath.IsAbs(resolvedInclude) && templatePath != "" {
			resolvedInclude = filepath.Join(filepath.Dir(templatePath), resolvedInclude)
		}

		// validate the include path unless local file access is enabled.
		if !AllowLocalFileAccess {
			if err := validateIncludePath(resolvedInclude, templatePath); err != nil {
				return nil, err
			}
		}

		// check if the file exists; otherwise leave the directive untouched
		if !fileutil.FileExists(resolvedInclude) {
			continue
		}

		includeFileContent, err := readIncludedFile(resolvedInclude, includeStack, depth)
		if err != nil {
			return nil, err
		}

		// Preserve the newline and indentation that should prefix included content lines.
		lastNewLineIndex := bytes.LastIndex(data[:matchStart], []byte("\n"))
		var padBytes []byte
		if lastNewLineIndex < 0 {
			padBytes = append([]byte("\n"), data[:matchStart]...)
		} else {
			padBytes = data[lastNewLineIndex:matchStart]
		}

		// pad each line of file content with padBytes
		includeFileContent = bytes.ReplaceAll(includeFileContent, []byte("\n"), padBytes)

		// copy everything up to the directive (including its indentation), then
		// the expanded content, and resume after the directive.
		out.Write(data[lastEnd:matchStart])
		out.Write(includeFileContent)
		lastEnd = matchEnd
	}
	out.Write(data[lastEnd:])

	return out.Bytes(), nil
}

func readIncludedFile(includeFileName string, includeStack map[string]struct{}, depth int) ([]byte, error) {
	includePath := includePathKey(includeFileName)
	if _, ok := includeStack[includePath]; ok {
		return nil, fmt.Errorf("circular include directive detected: %s", includeFileName)
	}

	includeStack[includePath] = struct{}{}
	defer delete(includeStack, includePath)

	includeFileContent, err := os.ReadFile(includeFileName)
	if err != nil {
		return nil, err
	}

	// if it's yaml, tries to preprocess that too recursively
	if stringsutil.HasSuffixAny(includeFileName, extensions.YAML) {
		if depth >= maxIncludeDepth {
			return nil, fmt.Errorf("include directive exceeded maximum include depth of %d", maxIncludeDepth)
		}
		includeFileContent, err = preProcess(includeFileContent, includeFileName, includeStack, depth+1)
		if err != nil {
			return nil, err
		}
	}

	return includeFileContent, nil
}

func includePathKey(includeFileName string) string {
	includePath, err := filepath.Abs(includeFileName)
	if err != nil {
		return filepath.Clean(includeFileName)
	}
	if evaluatedPath, err := filepath.EvalSymlinks(includePath); err == nil {
		return evaluatedPath
	}
	return includePath
}

// validateIncludePath checks that an include path resolves within the
// nuclei-templates directory or the including template's directory, and is not
// a hard-linked regular file.
func validateIncludePath(includePath, templatePath string) error {
	var allowedDirs []string
	if TemplateBaseDirProvider != nil {
		if baseDir := TemplateBaseDirProvider(); baseDir != "" {
			allowedDirs = append(allowedDirs, baseDir)
		}
	}
	if templatePath != "" {
		allowedDirs = append(allowedDirs, filepath.Dir(templatePath))
	}
	if !filepathutil.IsPathWithinAnyDirectory(includePath, allowedDirs...) {
		return errkit.Newf("include path %v is outside the templates directory and -lfa is not enabled", includePath)
	}
	if filepathutil.IsHardLinkedRegularFile(includePath) {
		return errkit.Newf("include path %v denied (hard link)", includePath)
	}
	return nil
}

package yaml

import (
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestPreProcessIncludesFileAtStartOfData(t *testing.T) {
	restoreStrictSyntax(t)

	dir := t.TempDir()
	includedPath := filepath.Join(dir, "included.yaml")
	require.NoError(t, os.WriteFile(includedPath, []byte("alpha: one\nbeta: two"), 0o600))

	var (
		output []byte
		err    error
	)
	require.NotPanics(t, func() {
		output, err = PreProcess([]byte(fmt.Sprintf("# !include:%s\nroot: true\n", includedPath)), filepath.Join(dir, "root.yaml"))
	})
	require.NoError(t, err)
	require.NotContains(t, string(output), "# !include:")
	require.Contains(t, string(output), "alpha: one\nbeta: two")
	require.Contains(t, string(output), "root: true")
}

func TestPreProcessExpandsRepeatedIncludeWithPerOccurrenceIndentation(t *testing.T) {
	restoreStrictSyntax(t)

	dir := t.TempDir()
	childPath := filepath.Join(dir, "child.yaml")
	require.NoError(t, os.WriteFile(childPath, []byte("key: value\nnested: true"), 0o600))

	// The same include directive appears twice at different indentation levels.
	// Each occurrence must be expanded using its own offset/indentation.
	data := []byte(fmt.Sprintf("root:\n  # !include:%s\nother:\n      # !include:%s\n", childPath, childPath))

	var (
		output []byte
		err    error
	)
	require.NotPanics(t, func() {
		output, err = PreProcess(data, filepath.Join(dir, "root.yaml"))
	})
	require.NoError(t, err)

	got := string(output)
	require.NotContains(t, got, "# !include:")
	require.Contains(t, got, "root:\n  key: value\n  nested: true")
	require.Contains(t, got, "other:\n      key: value\n      nested: true")
}

func TestPreProcessRejectsCircularInclude(t *testing.T) {
	restoreStrictSyntax(t)

	dir := t.TempDir()
	templatePath := filepath.Join(dir, "self.yaml")
	template := []byte(fmt.Sprintf("# !include:%s\nid: self\n", templatePath))
	require.NoError(t, os.WriteFile(templatePath, template, 0o600))

	var err error
	require.NotPanics(t, func() {
		_, err = PreProcess(template, templatePath)
	})
	require.Error(t, err)
	require.Contains(t, err.Error(), "circular include")
}

func TestPreProcessRejectsExcessiveIncludeDepth(t *testing.T) {
	restoreStrictSyntax(t)

	dir := t.TempDir()
	paths := make([]string, 40)
	for i := range paths {
		paths[i] = filepath.Join(dir, fmt.Sprintf("include-%02d.yaml", i))
	}
	for i, path := range paths {
		content := fmt.Sprintf("id: include-%02d\n", i)
		if i < len(paths)-1 {
			content = fmt.Sprintf("# !include:%s\n%s", paths[i+1], content)
		}
		require.NoError(t, os.WriteFile(path, []byte(content), 0o600))
	}

	_, err := PreProcess([]byte(fmt.Sprintf("# !include:%s\nid: root\n", paths[0])), filepath.Join(dir, "root.yaml"))
	require.Error(t, err)
	require.Contains(t, err.Error(), "maximum include depth")
}

// TestPreProcessRejectsIncludeOutsideAllowedDirs guards the include-path
// confinement: with -lfa disabled, an include resolving outside the including
// template's directory (and any template base dir) must be denied.
func TestPreProcessRejectsIncludeOutsideAllowedDirs(t *testing.T) {
	restoreSandboxState(t)

	templateDir := t.TempDir()
	outsideDir := t.TempDir()
	outsidePath := filepath.Join(outsideDir, "outside.yaml")
	require.NoError(t, os.WriteFile(outsidePath, []byte("secret: leaked"), 0o600))

	var err error
	require.NotPanics(t, func() {
		_, err = PreProcess([]byte(fmt.Sprintf("# !include:%s\nid: root\n", outsidePath)), filepath.Join(templateDir, "root.yaml"))
	})
	require.Error(t, err)
	require.Contains(t, err.Error(), "outside the templates directory")
}

// TestPreProcessRejectsHardLinkedInclude guards against hard-link smuggling: an
// include file that lives inside an allowed directory but is a hard link to
// content elsewhere must still be denied when -lfa is disabled.
func TestPreProcessRejectsHardLinkedInclude(t *testing.T) {
	restoreSandboxState(t)

	dir := t.TempDir()
	realPath := filepath.Join(dir, "real.yaml")
	require.NoError(t, os.WriteFile(realPath, []byte("secret: leaked"), 0o600))

	linkedPath := filepath.Join(dir, "linked.yaml")
	if err := os.Link(realPath, linkedPath); err != nil {
		t.Skipf("hard links not supported on this platform/filesystem: %v", err)
	}

	var err error
	require.NotPanics(t, func() {
		_, err = PreProcess([]byte(fmt.Sprintf("# !include:%s\nid: root\n", linkedPath)), filepath.Join(dir, "root.yaml"))
	})
	require.Error(t, err)
	require.Contains(t, err.Error(), "hard link")
}

func restoreStrictSyntax(t *testing.T) {
	t.Helper()

	previous := StrictSyntax
	StrictSyntax = false
	t.Cleanup(func() {
		StrictSyntax = previous
	})
}

// restoreSandboxState resets the package-level preprocessing knobs to their
// sandboxed defaults (strict syntax off, local file access denied, no template
// base dir) and restores the originals on cleanup so include-confinement tests
// are isolated from each other and from global state.
func restoreSandboxState(t *testing.T) {
	t.Helper()

	previousStrict := StrictSyntax
	previousLFA := AllowLocalFileAccess
	previousProvider := TemplateBaseDirProvider

	StrictSyntax = false
	AllowLocalFileAccess = false
	TemplateBaseDirProvider = nil

	t.Cleanup(func() {
		StrictSyntax = previousStrict
		AllowLocalFileAccess = previousLFA
		TemplateBaseDirProvider = previousProvider
	})
}

package yaml

import (
	"bytes"
	"io"
	"reflect"
	"strings"

	"github.com/go-playground/validator/v10"
	"github.com/pkg/errors"
	"gopkg.in/yaml.v3"
)

var validate *validator.Validate

// Marshaler is the YAML marshaling interface used by the project.
type Marshaler interface {
	MarshalYAML() (interface{}, error)
}

// Unmarshaler is the legacy callback-style YAML unmarshaling interface used
// throughout nuclei. yaml.v3 still supports this shape, but does not export it.
type Unmarshaler interface {
	UnmarshalYAML(unmarshal func(interface{}) error) error
}

// TypeError is returned for YAML type conversion errors.
type TypeError = yaml.TypeError

// Node is the yaml.v3 syntax tree node type.
type Node = yaml.Node

// MapItem is a single YAML mapping item.
type MapItem struct {
	Key   interface{}
	Value interface{}
}

// MapSlice preserves mapping key order for compatibility with yaml.v2.
type MapSlice []MapItem

// Encoder writes YAML documents.
type Encoder = yaml.Encoder

// Marshal serializes a value to YAML.
func Marshal(v interface{}) ([]byte, error) {
	var out bytes.Buffer
	encoder := yaml.NewEncoder(&out)
	encoder.SetIndent(2)
	if err := encoder.Encode(v); err != nil {
		return nil, err
	}
	if err := encoder.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// Unmarshal deserializes YAML using yaml.v2-compatible lax duplicate-key
// behavior. In lax mode yaml.v2 allowed duplicate mapping keys and kept the
// last value; yaml.v3 rejects duplicates by default, so normalize first.
func Unmarshal(data []byte, v interface{}) error {
	return NewDecoder(bytes.NewReader(data)).Decode(v)
}

// UnmarshalStrict deserializes YAML and rejects unknown struct fields and
// duplicate mapping keys.
func UnmarshalStrict(data []byte, v interface{}) error {
	decoder := NewDecoder(bytes.NewReader(data))
	decoder.SetStrict(true)
	return decoder.Decode(v)
}

// NewEncoder returns a YAML encoder.
func NewEncoder(w io.Writer) *Encoder {
	return yaml.NewEncoder(w)
}

// Decoder reads YAML documents.
type Decoder struct {
	decoder *yaml.Decoder
	strict  bool
}

// NewDecoder returns a YAML decoder.
func NewDecoder(r io.Reader) *Decoder {
	return &Decoder{decoder: yaml.NewDecoder(r)}
}

// SetStrict matches yaml.v2's decoder API.
func (d *Decoder) SetStrict(strict bool) {
	d.strict = strict
	d.decoder.KnownFields(strict)
}

// KnownFields matches yaml.v3's decoder API.
func (d *Decoder) KnownFields(enable bool) {
	d.SetStrict(enable)
}

// Decode reads the next YAML document into v.
func (d *Decoder) Decode(v interface{}) error {
	if d.strict {
		if err := d.decoder.Decode(v); err != nil {
			return err
		}
		restoreYAMLv2InterfaceMapShape(v)
		return nil
	}

	var node yaml.Node
	if err := d.decoder.Decode(&node); err != nil {
		return err
	}
	normalizeDupMappingKeys(&node)
	if err := node.Decode(v); err != nil {
		return err
	}
	restoreYAMLv2InterfaceMapShape(v)
	return nil
}

// UnmarshalYAML decodes an ordered map from a yaml.v3 node.
func (m *MapSlice) UnmarshalYAML(node *Node) error {
	node = unwrapDoc(node)
	if node == nil || node.Kind == 0 {
		*m = nil
		return nil
	}
	if node.Kind != yaml.MappingNode {
		var value interface{}
		if err := node.Decode(&value); err != nil {
			return err
		}
		return errors.Errorf("cannot unmarshal %T into yaml.MapSlice", value)
	}

	items := make([]MapItem, 0, len(node.Content)/2)
	for i := 0; i < len(node.Content); i += 2 {
		var item MapItem
		if err := node.Content[i].Decode(&item.Key); err != nil {
			return err
		}
		if err := node.Content[i+1].Decode(&item.Value); err != nil {
			return err
		}
		item.Value = toYAMLv2InterfaceValue(item.Value)
		items = append(items, item)
	}
	*m = items
	return nil
}

// DecodeAndValidate is a wrapper for yaml Decode adding struct validation
func DecodeAndValidate(r io.Reader, v interface{}) error {
	if err := NewDecoder(r).Decode(v); err != nil {
		return err
	}
	if validate == nil {
		validate = validator.New()
	}

	if err := validate.Struct(v); err != nil {
		if _, ok := err.(*validator.InvalidValidationError); ok {
			return err
		}
		errs := []string{}
		for _, err := range err.(validator.ValidationErrors) {
			errs = append(errs, err.Namespace()+": "+err.Tag())
		}
		return errors.Wrap(errors.New(strings.Join(errs, ", ")), "validation failed for these fields")
	}
	return nil
}

func normalizeDupMappingKeys(node *yaml.Node) {
	node = unwrapDoc(node)
	if node == nil {
		return
	}

	switch node.Kind {
	case yaml.DocumentNode:
		for _, child := range node.Content {
			normalizeDupMappingKeys(child)
		}
	case yaml.SequenceNode:
		for _, child := range node.Content {
			normalizeDupMappingKeys(child)
		}
	case yaml.MappingNode:
		type pair struct {
			key   *yaml.Node
			value *yaml.Node
		}
		pairs := make([]pair, 0, len(node.Content)/2)
		indexes := make(map[string]int, len(node.Content)/2)
		for i := 0; i < len(node.Content); i += 2 {
			key := node.Content[i]
			value := node.Content[i+1]
			normalizeDupMappingKeys(value)

			identity := mappingKeyIdentity(key)
			if existing, ok := indexes[identity]; ok {
				pairs[existing].value = value
				continue
			}
			indexes[identity] = len(pairs)
			pairs = append(pairs, pair{key: key, value: value})
		}

		node.Content = node.Content[:0]
		for _, item := range pairs {
			node.Content = append(node.Content, item.key, item.value)
		}
	}
}

func mappingKeyIdentity(node *yaml.Node) string {
	if node == nil {
		return ""
	}
	return string(rune(node.Kind)) + "\x00" + node.Value
}

func unwrapDoc(node *yaml.Node) *yaml.Node {
	if node != nil && node.Kind == yaml.DocumentNode && len(node.Content) == 1 {
		return node.Content[0]
	}
	return node
}

func restoreYAMLv2InterfaceMapShape(v interface{}) {
	value := reflect.ValueOf(v)
	if !value.IsValid() {
		return
	}
	if value.Kind() != reflect.Pointer || value.IsNil() {
		return
	}
	restoreYAMLv2InterfaceMapShapeValue(value.Elem())
}

func restoreYAMLv2InterfaceMapShapeValue(value reflect.Value) {
	if !value.IsValid() {
		return
	}

	switch value.Kind() {
	case reflect.Interface:
		if value.IsNil() || !value.CanSet() {
			return
		}
		setInterfaceValue(value, toYAMLv2InterfaceValue(value.Interface()))
	case reflect.Pointer:
		if !value.IsNil() {
			restoreYAMLv2InterfaceMapShapeValue(value.Elem())
		}
	case reflect.Struct:
		for i := 0; i < value.NumField(); i++ {
			field := value.Field(i)
			if field.CanSet() {
				restoreYAMLv2InterfaceMapShapeValue(field)
			}
		}
	case reflect.Map:
		if value.Type().Elem().Kind() != reflect.Interface {
			return
		}
		for _, key := range value.MapKeys() {
			normalized := toYAMLv2InterfaceValue(value.MapIndex(key).Interface())
			value.SetMapIndex(key, interfaceValueForMap(value.Type().Elem(), normalized))
		}
	case reflect.Slice, reflect.Array:
		for i := 0; i < value.Len(); i++ {
			restoreYAMLv2InterfaceMapShapeValue(value.Index(i))
		}
	}
}

func toYAMLv2InterfaceValue(value interface{}) interface{} {
	switch typed := value.(type) {
	case map[string]interface{}:
		converted := make(map[interface{}]interface{}, len(typed))
		for key, item := range typed {
			converted[key] = toYAMLv2InterfaceValue(item)
		}
		return converted
	case []interface{}:
		for i, item := range typed {
			typed[i] = toYAMLv2InterfaceValue(item)
		}
		return typed
	default:
		return value
	}
}

func setInterfaceValue(dst reflect.Value, value interface{}) {
	if value == nil {
		dst.Set(reflect.Zero(dst.Type()))
		return
	}
	dst.Set(reflect.ValueOf(value))
}

func interfaceValueForMap(elem reflect.Type, value interface{}) reflect.Value {
	if value == nil {
		return reflect.Zero(elem)
	}
	return reflect.ValueOf(value)
}

package yaml

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestUnmarshalStrictRejectsUnknownFields(t *testing.T) {
	var value struct {
		Name string `yaml:"name"`
	}

	err := UnmarshalStrict([]byte("name: test\nunknown: value\n"), &value)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")
}

func TestUnmarshalStrictRejectsDuplicateFields(t *testing.T) {
	var value struct {
		Name string `yaml:"name"`
	}

	err := UnmarshalStrict([]byte("name: first\nname: second\n"), &value)
	require.Error(t, err)
	require.Contains(t, err.Error(), "already")
}

func TestUnmarshalLaxAllowsDuplicateFields(t *testing.T) {
	var value struct {
		Name string `yaml:"name"`
	}

	err := Unmarshal([]byte("name: first\nname: second\n"), &value)
	require.NoError(t, err)
	require.Equal(t, "second", value.Name)
}

func TestDecoderLaxAllowsDuplicateFields(t *testing.T) {
	var value struct {
		Name string `yaml:"name"`
	}

	err := NewDecoder(strings.NewReader("name: first\nname: second\n")).Decode(&value)
	require.NoError(t, err)
	require.Equal(t, "second", value.Name)
}

func TestUnmarshalPreservesYAMLv2NestedInterfaceMapShape(t *testing.T) {
	var value map[string]interface{}

	err := Unmarshal([]byte("payload:\n  low:\n    - one\n"), &value)
	require.NoError(t, err)

	nested, ok := value["payload"].(map[interface{}]interface{})
	require.True(t, ok, "nested interface map should keep yaml.v2 map[interface{}]interface{} shape")
	require.Equal(t, []interface{}{"one"}, nested["low"])
}

func TestMapSlicePreservesOrder(t *testing.T) {
	var value MapSlice

	err := Unmarshal([]byte("first: one\nsecond: two\nthird: three\n"), &value)
	require.NoError(t, err)
	require.Len(t, value, 3)
	require.Equal(t, "first", value[0].Key)
	require.Equal(t, "second", value[1].Key)
	require.Equal(t, "third", value[2].Key)
	require.Equal(t, "one", value[0].Value)
	require.Equal(t, "two", value[1].Value)
	require.Equal(t, "three", value[2].Value)
}

package workflows

import (
	"fmt"

	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/stringslice"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/projectdiscovery/nuclei/v3/pkg/protocols"
	templateTypes "github.com/projectdiscovery/nuclei/v3/pkg/templates/types"
)

// Workflow is a workflow to execute with chained requests, etc.
type Workflow struct {
	// description: |
	//   Workflows is a list of workflows to execute for a template.
	Workflows []*WorkflowTemplate `yaml:"workflows,omitempty" json:"workflows,omitempty" jsonschema:"title=list of workflows to execute,description=List of workflows to execute for template"`

	Options *protocols.ExecutorOptions `yaml:"-" json:"-"`
}

// WorkflowTemplate is a template to be run as part of a workflow
type WorkflowTemplate struct {
	// description: |
	//   Template is a single template or directory to execute as part of workflow.
	// examples:
	//   - name: A single template
	//     value: "\"dns/worksites-detection.yaml\""
	//   - name: A template directory
	//     value: "\"misconfigurations/aem\""
	Template string `yaml:"template,omitempty" json:"template,omitempty" jsonschema:"title=template/directory to execute,description=Template or directory to execute as part of workflow"`
	// description: |
	//    Tags to run templates based on.
	Tags stringslice.StringSlice `yaml:"tags,omitempty" json:"tags,omitempty" jsonschema:"title=tags to execute,description=Tags to run template based on"`
	// description: |
	//    Matchers perform name based matching to run subtemplates for a workflow.
	Matchers []*Matcher `yaml:"matchers,omitempty" json:"matchers,omitempty" jsonschema:"title=name based template result matchers,description=Matchers perform name based matching to run subtemplates for a workflow"`
	// description: |
	//    Subtemplates are run if the `template` field Template matches.
	Subtemplates []*WorkflowTemplate `yaml:"subtemplates,omitempty" json:"subtemplates,omitempty" jsonschema:"title=subtemplate based result matchers,description=Subtemplates are ran if the template field Template matches"`
	// Executers perform the actual execution for the workflow template
	Executers []*ProtocolExecuterPair `yaml:"-" json:"-"`
}

// ProtocolExecuterPair is a pair of protocol executer and its options
type ProtocolExecuterPair struct {
	Executer     protocols.Executer
	Options      *protocols.ExecutorOptions
	TemplateType templateTypes.ProtocolType
}

// Matcher performs conditional matching on the workflow template results.
type Matcher struct {
	// description: |
	//    Name is the name of the items to match.
	Name stringslice.StringSlice `yaml:"name,omitempty" json:"name,omitempty" jsonschema:"title=name of items to match,description=Name of items to match"`
	// description: |
	//   Condition is the optional condition between names. By default,
	//   the condition is assumed to be OR.
	// values:
	//   - "and"
	//   - "or"
	Condition string `yaml:"condition,omitempty" json:"condition,omitempty" jsonschema:"title=condition between names,description=Condition between the names,enum=and,enum=or"`
	// description: |
	//    Subtemplates are run if the name of matcher matches.
	Subtemplates []*WorkflowTemplate `yaml:"subtemplates,omitempty" json:"subtemplates,omitempty" jsonschema:"title=templates to run after match,description=Templates to run after match"`

	condition ConditionType
}

// ConditionType is the type of condition for matcher
type ConditionType int

const (
	// ANDCondition matches responses with AND condition in arguments.
	ANDCondition ConditionType = iota + 1
	// ORCondition matches responses with AND condition in arguments.
	ORCondition
)

// ConditionTypes is a table for conversion of condition type from string.
var ConditionTypes = map[string]ConditionType{
	"and": ANDCondition,
	"or":  ORCondition,
}

// Compile compiles the matcher for workflow
func (matcher *Matcher) Compile() error {
	var ok bool
	if matcher.Condition != "" {
		matcher.condition, ok = ConditionTypes[matcher.Condition]
		if !ok {
			return fmt.Errorf("unknown condition specified: %s", matcher.Condition)
		}
	} else {
		matcher.condition = ORCondition
	}
	return nil
}

// Match matches a name for matcher names or name
func (matcher *Matcher) Match(result *operators.Result) bool {
	names := matcher.Name.ToSlice()
	if len(names) == 0 {
		return false
	}

	for i, name := range names {
		matchOK := result.HasMatch(name)
		extractOK := result.HasExtract(name)

		if !matchOK && !extractOK {
			if matcher.condition == ANDCondition {
				return false
			}
			continue
		}
		if matcher.condition == ORCondition {
			return true
		} else if len(names)-1 == i {
			return true
		}
	}
	return false
}

package workflows

import (
	"testing"

	"github.com/projectdiscovery/nuclei/v3/pkg/model/types/stringslice"
	"github.com/projectdiscovery/nuclei/v3/pkg/operators"
	"github.com/stretchr/testify/require"
)

func TestWorkflowMatchAndCompile(t *testing.T) {
	t.Run("name", func(t *testing.T) {
		matcher := &Matcher{Name: stringslice.StringSlice{Value: "sphinx"}}
		matched := matcher.Match(&operators.Result{Matches: map[string][]string{"sphinx": {}}, Extracts: map[string][]string{}})
		require.True(t, matched, "could not match value")
	})
	t.Run("name-negative", func(t *testing.T) {
		matcher := &Matcher{Name: stringslice.StringSlice{Value: "tomcat"}}
		matched := matcher.Match(&operators.Result{Matches: map[string][]string{"apache": {}}, Extracts: map[string][]string{}})
		require.False(t, matched, "could not match value")
	})
	t.Run("names-or", func(t *testing.T) {
		matcher := &Matcher{Name: stringslice.StringSlice{Value: []string{"sphinx", "elastic"}}, Condition: "or"}
		_ = matcher.Compile()
		matched := matcher.Match(&operators.Result{Matches: map[string][]string{"elastic": {}}, Extracts: map[string][]string{}})
		require.True(t, matched, "could not match value")
		matched = matcher.Match(&operators.Result{Matches: map[string][]string{"sphinx": {}}, Extracts: map[string][]string{}})
		require.True(t, matched, "could not match value")
		matched = matcher.Match(&operators.Result{Matches: map[string][]string{"random": {}}, Extracts: map[string][]string{}})
		require.False(t, matched, "could not match value")
	})
	t.Run("names-and", func(t *testing.T) {
		matcher := &Matcher{Name: stringslice.StringSlice{Value: []string{"sphinx", "elastic"}}, Condition: "and"}
		_ = matcher.Compile()
		matched := matcher.Match(&operators.Result{Matches: map[string][]string{"elastic": {}, "sphinx": {}}, Extracts: map[string][]string{}})
		require.True(t, matched, "could not match value")

		matched = matcher.Match(&operators.Result{Matches: map[string][]string{"sphinx": {}}, Extracts: map[string][]string{}})
		require.False(t, matched, "could not match value")
		matched = matcher.Match(&operators.Result{Matches: map[string][]string{"random": {}}, Extracts: map[string][]string{}})
		require.False(t, matched, "could not match value")
	})
}
